    layers: [
      { baseY: 0.5, amp: 66, factor: 0.1, seed: 2.2, color: 'amber', fillAlpha: 0.12, lineAlpha: 0.5 },
      { baseY: 0.66, amp: 44, factor: 0.22, seed: 5.9, color: 'magenta', fillAlpha: 0.09, lineAlpha: 0.4 },
    ],
  },
  // Micro Mountain: soft moss lumps, giant grass blades, big dew drops that catch the light.
  'dew-drops': {
    shape: 'moss',
    layers: [
      { baseY: 0.6, amp: 40, factor: 0.07, seed: 1.1, color: 'lime', fillAlpha: 0.1, lineAlpha: 0.42 },
      { baseY: 0.72, amp: 30, factor: 0.18, seed: 7.7, color: 'cyan', fillAlpha: 0.08, lineAlpha: 0.36 },
    ],
  },
  // Vertigo Vents: flat-topped volcanic cones, each vent glowing amber with a smoke plume rising from it.
  vents: {
    shape: 'cone',
    layers: [
      { baseY: 0.6, amp: 70, factor: 0.08, seed: 3.7, color: 'magenta', fillAlpha: 0.12, lineAlpha: 0.48 },
      { baseY: 0.74, amp: 40, factor: 0.2, seed: 8.4, color: 'amber', fillAlpha: 0.09, lineAlpha: 0.4 },
    ],
  },
};

/** Integer hash of (n, seed) to [0, 1). Pure, platform-stable (Math.imul), used for per-cell variety. */
function hash01(n, seed) {
  let h = Math.imul((n | 0) ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul((seed | 0) + 0x632be5ab, 0xc2b2ae35);
  h ^= h >>> 13;
  h = Math.imul(h, 0x27d4eb2f);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

/** Vent cone cell width (px of layer space); the plume decor finds cone tops from the same constant. */
const CONE_W = 230;

/**
 * One sample of a layer's height at a layer-space x, per shape. Pure. Every profile returns roughly
 * -1..1 (the W6 shapes 0..1) before amplitude, so section heights stay comparable between motifs.
 * @param {string} shape @param {number} wx @param {number} seed @returns {number}
 */
export function motifProfile(shape, wx, seed) {
  if (shape === 'step') {
    // Pyramid Peak: quantise a sine into benches, so the silhouette is blocky rather than smooth.
    const raw = Math.sin(wx * 0.009 + seed) * 0.6 + Math.sin(wx * 0.021 + seed * 2.1) * 0.4;
    return Math.round(raw * 3) / 3;
  }
  if (shape === 'facet') {
    // Crystal Cavern: alternating angular facets, sharpest profile of the five.
    const tri = Math.abs(((wx * 0.014 + seed) % 2) - 1) * 2 - 1;
    return tri * 0.7 + Math.sin(wx * 0.05 + seed * 3.3) * 0.3;
  }
  if (shape === 'swell') {
    // Garbage Dump Glacier: long shallow drifts, no high-frequency detail at all.
    return Math.sin(wx * 0.004 + seed) * 0.8 + Math.sin(wx * 0.011 + seed * 1.7) * 0.2;
  }
  if (shape === 'sine') {
    // Underwater Mountain: water-like, slightly phase-shifted ripples.
    return Math.sin(wx * 0.008 + seed) * 0.55 + Math.sin(wx * 0.019 + seed * 2.6) * 0.3 + Math.sin(wx * 0.043 + seed * 5.1) * 0.15;
  }
  if (shape === 'crater') {
    // Space Mountain: a flat plain cut by bowls with raised rims, one crater per 150 px cell at most.
    const f = (wx + seed * 97) / 150;
    const c = Math.floor(f);
    const u = f - c;
    let h = 0.45 + 0.03 * Math.sin(wx * 0.02 + seed);
    if (hash01(c, seed * 1000) < 0.8) {
      const r = 0.22 + 0.16 * hash01(c + 7919, seed * 1000);
      const t = (u - 0.5) / r;
      if (Math.abs(t) < 1) h -= 0.4 * (1 - t * t);
      h += 0.3 * Math.exp(-(((Math.abs(t) - 1) / 0.24) ** 2));
    }
    return clamp01(h);
  }
  if (shape === 'gumdrop') {
    // Candy Cane Canyon: broad round domes with pinched valleys (a root of |sin| flattens the tops).
    return Math.abs(Math.sin(wx * 0.0105 + seed)) ** 0.45 * 0.85 + Math.abs(Math.sin(wx * 0.031 + seed * 2)) * 0.1;
  }
  if (shape === 'cloud') {
    // Sky Jellyfish Mountain: scalloped billows, two |sin| octaves so every crest is a puff.
    return 0.25 + Math.abs(Math.sin(wx * 0.017 + seed)) * 0.45 + Math.abs(Math.sin(wx * 0.041 + seed * 1.9)) * 0.3;
  }
  if (shape === 'works') {
    // Steampunk Slopes: flat-roofed blocks at quantised heights, some with a chimney stack.
    const f = (wx + seed * 53) / 44;
    const c = Math.floor(f);
    const u = f - c;
    let h = 0.25 + 0.5 * (Math.round(hash01(c, seed * 1000) * 4) / 4);
    if (hash01(c + 104729, seed * 1000) > 0.62 && u > 0.3 && u < 0.56) h += 0.3;
    return clamp01(h);
  }
  if (shape === 'moss') {
    // Micro Mountain: soft lumpy moss, never sharp.
    return 0.42 + Math.sin(wx * 0.0065 + seed) * 0.22 + Math.abs(Math.sin(wx * 0.029 + seed * 1.3)) * 0.22;
  }
  if (shape === 'cone') {
    // Vertigo Vents: volcanic cones with a flat top and a small vent notch in the middle.
    const f = (wx + seed * 71) / CONE_W;
    const c = Math.floor(f);
    const d = Math.abs(2 * (f - c) - 1);
    const hv = 0.7 + 0.3 * hash01(c, seed * 1000);
    let h = 0.08 + Math.max(0, Math.min(1 - d * 1.5, 0.8)) * hv;
    if (d < 0.07) h -= 0.05;
    return clamp01(h);
  }
  // 'peak' — the original ridge profile, unchanged from pre-W3 so base terrain looks identical.
  return Math.sin(wx * 0.011 + seed) * 0.55 + Math.sin(wx * 0.027 + seed * 2.3) * 0.3 + Math.sin(wx * 0.061 + seed * 4.1) * 0.15;
}

/** Identical visual-only ridge offset for the silhouette and rooted decor.
 * No terrain/physics subsystem ever calls this helper.
 */
function horizonDanceOffset(scrollX, screenX, layer, dance = 0) {
  if (!(dance > 0)) return 0;
  const wx = screenX + scrollX * layer.factor;
  return 1.7 * dance * Math.sin(wx * 0.02 + layer.seed);
}

/** Screen y of the background silhouette; decor roots track its tiny sway. */
function layerYAt(shape, layer, scrollX, sx, dance = 0) {
  const h = motifProfile(shape, sx + scrollX * layer.factor, layer.seed);
  const crest = CRESTLESS.has(shape) ? 0 : (h > 0 ? h * layer.amp * 0.2 : 0);
  return GAME_HEIGHT * layer.baseY - Math.abs(h) * layer.amp - crest +
    horizonDanceOffset(scrollX, sx, layer, dance);
}

/**
 * The layer geometry a motif draws. Pure function of (motif, scrollX), so a repaint at any scroll
 * position is stable and an unknown motif can fall back without a special case at the call site.
 *
 * `baseY`/`amp`/`factor` are returned in the same units the original backdrop used (fractions of
 * GAME_HEIGHT and px); only the shape tag tells the renderer which profile function to sample.
 * @param {string|null} motif
 * @param {number} scrollX
 * @returns {{shape:string, motif:string, layers:Array<Object>}}
 */
export function motifGeometry(motif, scrollX) {
  const id = typeof motif === 'string' && MOTIFS.includes(motif) ? motif : 'ridges';
  const def = MOTIF_DEFS[id];
  const x = Number.isFinite(scrollX) ? scrollX : 0;
  return {
    motif: id,
    shape: def.shape,
    layers: def.layers.map((l) => ({
      baseY: l.baseY, amp: l.amp, factor: l.factor, seed: l.seed,
      color: l.color, fillAlpha: l.fillAlpha, lineAlpha: l.lineAlpha,
      // A per-layer phase offset derived from scroll, so the check that geometry actually varies with
      // scroll is meaningful rather than trivially true.
      phase: (x * l.factor * 0.011) % (Math.PI * 2),
    })),
  };
}

/** mulberry32 - visual-only randomness, deterministic so the sky is stable between runs. */
function mulberry32(a) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Horizontal tile the decor items repeat over; wider than the screen so nothing pops at the seams. */
const DECOR_TILE = 960;
/** Items are emitted only while their anchor is within this many px of the screen. */
const DECOR_MARGIN = 40;
/** Per-motif base seed for the decor layout (any fixed odd number; changing one re-lays that motif). */
const DECOR_SEEDS = {
  stars: 0x5ca7, 'candy-stripes': 0xc4d1, jellyfish: 0x1e11, 'brass-pipes': 0xb4a5, 'dew-drops': 0xde3d, vents: 0x7e57,
};
const EMPTY_DECOR = Object.freeze([]);

/** Screen x of an item anchored at tile x `x0` scrolling at `factor`, or null if it is off screen. */
function tileX(x0, scrollX, factor) {
  let x = (x0 - scrollX * factor) % DECOR_TILE;
  if (x < 0) x += DECOR_TILE;
  x -= DECOR_MARGIN;
  return x > GAME_WIDTH + DECOR_MARGIN ? null : x;
}

/**
 * Fixed per-(motif, seed) item layout from mulberry32 (never Math.random). Rebuilt on every call (about
 * 50 PRNG draws): no module-level cache, so the output cannot depend on what was drawn before.
 */
function decorLayout(motif, seed) {
  let lay;
  const rnd = mulberry32((DECOR_SEEDS[motif] ^ Math.imul(seed | 0, 0x9e3779b1)) >>> 0);
  const items = (n, make) => Array.from({ length: n }, (_, i) => make(i));
  const span = (lo, hi) => lo + rnd() * (hi - lo);
  if (motif === 'stars') {
    lay = {
      stars: items(36, () => ({ x0: rnd() * DECOR_TILE, y: span(4, GAME_HEIGHT * 0.5), f: span(0.01, 0.05), tw: rnd() * 6.28, bright: rnd() < 0.2 })),
      planet: { x0: span(200, 700), y: span(GAME_HEIGHT * 0.16, GAME_HEIGHT * 0.26), r: span(11, 15), tilt: span(-0.45, -0.15) },
    };
  } else if (motif === 'candy-stripes') {
    lay = {
      canes: items(6, (i) => ({ x0: (i + rnd() * 0.7) * (DECOR_TILE / 6), h: span(30, 44), flip: rnd() < 0.5 })),
      pops: items(5, (i) => ({ x0: (i + rnd() * 0.7) * (DECOR_TILE / 5), r: span(8, 12), stick: span(18, 26), color: ['magenta', 'amber', 'lime'][i % 3], ph: rnd() * 6.28 })),
    };
  } else if (motif === 'jellyfish') {
    lay = {
      jellies: items(7, (i) => {
        const size = span(7, 14);
        return { x0: (i + rnd() * 0.6) * (DECOR_TILE / 7), y: span(GAME_HEIGHT * 0.15, GAME_HEIGHT * 0.4), s: size, f: 0.03 + ((size - 7) / 7) * 0.06, color: ['magenta', 'cyan', 'lime'][i % 3], ph: rnd() * 6.28 };
      }),
    };
  } else if (motif === 'brass-pipes') {
    lay = {
      gears: items(4, (i) => ({ x0: (i + rnd() * 0.6) * (DECOR_TILE / 4), y: span(GAME_HEIGHT * 0.2, GAME_HEIGHT * 0.28), r: span(15, 24), ph: rnd() * 6.28, dir: i % 2 ? -1 : 1 })),
      pipeY: GAME_HEIGHT * 0.555,
      drops: items(15, () => rnd() < 0.3),
    };
  } else if (motif === 'dew-drops') {
    const blade = (layer, lo, hi) => (i, n) => ({ layer, x0: (i + rnd() * 0.8) * (DECOR_TILE / n), h: span(lo, hi), w: span(5, 8) * (hi / 70), lean: span(-18, 18), drop: rnd() < 0.75, dt: span(0.45, 0.8), ph: rnd() * 6.28 });
    const far = blade(0, 34, 60);
    const near = blade(1, 62, 100);
    lay = { blades: [...items(6, (i) => far(i, 6)), ...items(5, (i) => near(i, 5))] };
  } else if (motif === 'vents') {
    lay = { ph: rnd() * 6.28, wind: span(0.6, 1.2) };
  } else {
    lay = null;
  }
  return lay;
}

/** Points of an ellipse (closed polygon) centred at (cx, cy), rotated by `rot`. */
function ellipsePts(cx, cy, rx, ry, rot, n) {
  const pts = [];
  const cr = Math.cos(rot);
  const sr = Math.sin(rot);
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const ex = Math.cos(a) * rx;
    const ey = Math.sin(a) * ry;
    pts.push({ x: cx + ex * cr - ey * sr, y: cy + ex * sr + ey * cr });
  }
  return pts;
}

/**
 * Audit T1: the decor a W6 motif draws on top of its silhouette — the things that make the backdrop read
 * as its biome (stars and a ringed planet, candy canes, jellyfish, gears and pipes, dew drops, vent smoke).
 * The five batch-1 motifs and the base backdrop have none, so their draw calls are unchanged.
 *
 * Pure function of (motif, scrollX, timeMs, seed): the item layout comes from a seeded mulberry32 and all
 * animation from `timeMs` (scene time), never Math.random or Date.now, so a repaint is repeatable.
 * Like motifGeometry it never names a colour, only a palette KEY, and never `danger`: hazards must stay the
 * only thing on screen drawn in the hazard colour.
 *
 * Each primitive has `depth`: -1 = in the sky (before every layer), k = right after silhouette layer k.
 * Kinds: `poly` {pts, fillAlpha, lineAlpha}, `line` {pts (open polyline), alpha, width},
 * `circle` {x, y, r, fillAlpha, lineAlpha}, `rect` {x, y, w, h, alpha}; all carry `color` (a palette key).
 * @param {string|null} motif
 * @param {number} scrollX camera scroll X (world px)
 * @param {number} [timeMs=0] scene time
 * @param {number} [seed=0] layout seed (Background uses 0; any integer gives a different but stable layout)
 * @param {{bees?:boolean}} [o] Micro glow-up: `bees: false` leaves out the dew-drops bees (systems/MicroBees.js;
 *   the perf comparison switch). Default on. Bee primitives carry `bee: id`.
 * @returns {ReadonlyArray<Object>} primitives in draw order
 */
export function motifDecor(motif, scrollX, timeMs = 0, seed = 0, o = {}) {
  if (typeof motif !== 'string' || !DECOR_SEEDS[motif] || !MOTIFS.includes(motif)) return EMPTY_DECOR;
  const sx = Number.isFinite(scrollX) ? scrollX : 0;
  const t = Number.isFinite(timeMs) ? timeMs : 0;
  const lay = decorLayout(motif, Number.isFinite(seed) ? Math.trunc(seed) : 0);
  const def = MOTIF_DEFS[motif];
  const dance = Number.isFinite(o.dance) ? Math.min(1, Math.max(0, o.dance)) : 0;
  const horizonDance = Number.isFinite(o.horizonDance)
    ? Math.min(1, Math.max(0, o.horizonDance)) : 0;
  const out = [];
  const W = GAME_WIDTH;
  const H = GAME_HEIGHT;

  if (motif === 'stars') {
    for (const st of lay.stars) {
      const x = tileX(st.x0, sx, st.f);
      if (x === null || x < -2 || x > W + 2) continue;
      const alpha = 0.3 + 0.4 * (0.5 + 0.5 * Math.sin(t / 450 + st.tw));
      if (st.bright) {
        out.push({ kind: 'line', depth: -1, color: 'cyan', alpha, width: 1, pts: [{ x: x - 3, y: st.y }, { x: x + 3, y: st.y }] });
        out.push({ kind: 'line', depth: -1, color: 'cyan', alpha, width: 1, pts: [{ x, y: st.y - 3 }, { x, y: st.y + 3 }] });
      } else {
        out.push({ kind: 'rect', depth: -1, color: 'text', alpha, x: Math.floor(x), y: Math.floor(st.y), w: 1, h: 1 });
      }
    }
    const pl = lay.planet;
    const px = tileX(pl.x0, sx, 0.012);
    if (px !== null) {
      const r = pl.r * (1 + 0.04 * dance);
      out.push({ kind: 'circle', depth: -1, color: 'lime', fillAlpha: 0.2, lineAlpha: 0.6, x: px, y: pl.y, r });
      out.push({ kind: 'poly', depth: -1, color: 'amber', fillAlpha: 0, lineAlpha: 0.65, pts: ellipsePts(px, pl.y, r * 1.9, r * 0.42, pl.tilt, 20) });
    }
  } else if (motif === 'candy-stripes') {
    // Candy-cane sky: slanted alternating bands across the upper sky, scrolling slowly.
    const P = 28;
    const yb = H * 0.5;
    const K = yb * 0.4;
    const off = sx * 0.04;
    // First band whose top edge reaches the screen; the last one must cover the bottom-right corner,
    // which the slant pushes K px to the left of its top edge.
    for (let k = Math.floor(off / P); ; k++) {
      const x = k * P - off;
      if (x > W + K) break;
      out.push({
        kind: 'poly', depth: -1, color: k % 2 === 0 ? 'magenta' : 'text', fillAlpha: 0.05, lineAlpha: 0,
        pts: [{ x, y: 0 }, { x: x + P, y: 0 }, { x: x + P - K, y: yb }, { x: x - K, y: yb }],
      });
    }
    // Candy canes standing on the far ridge: a striped stick and hook, drawn as alternating segments.
    const L0 = def.layers[0];
    for (const c of lay.canes) {
      const x = tileX(c.x0, sx, L0.factor);
      if (x === null) continue;
      const yB = layerYAt(def.shape, L0, sx, x, horizonDance) + 2;
      const top = yB - c.h;
      const dir = c.flip ? -1 : 1;
      const path = [];
      const flex = dance * 3 * dir;
      for (let y = yB; y > top; y -= 5)
        path.push({ x: x + flex * ((yB - y) / c.h), y });
      for (let i = 0; i <= 6; i++) {
        const a = Math.PI - (i / 6) * Math.PI;
        path.push({ x: x + flex + dir * (6 + Math.cos(a) * 6), y: top - Math.sin(a) * 6 });
      }
      path.push({ x: x + flex + dir * 12, y: top + 5 });
      // One white stroke for the whole cane, then a red stripe on every other segment.
      out.push({ kind: 'line', depth: 0, color: 'text', alpha: 0.7, width: 3, pts: path });
      for (let i = 0; i < path.length - 1; i += 2) {
        out.push({ kind: 'line', depth: 0, color: 'magenta', alpha: 0.8, width: 3, pts: [path[i], path[i + 1]] });
      }
    }
    // Lollipops on the near ridge: stick, disc, and a slowly turning spiral.
    const L1 = def.layers[1];
    for (const lp of lay.pops) {
      const x = tileX(lp.x0, sx, L1.factor);
      if (x === null) continue;
      const yB = layerYAt(def.shape, L1, sx, x, horizonDance) + 2;
      const cy = yB - lp.stick - lp.r - dance * 2.5;
      out.push({ kind: 'line', depth: 1, color: 'text', alpha: 0.55, width: 2, pts: [{ x, y: yB }, { x, y: cy + lp.r }] });
      out.push({ kind: 'circle', depth: 1, color: lp.color, fillAlpha: 0.32, lineAlpha: 0.75, x, y: cy, r: lp.r });
      const spiral = [];
      const spin = t * 0.001 + lp.ph;
      for (let i = 0; i <= 16; i++) {
        const a = spin + (i / 16) * Math.PI * 3.5;
        const rr = (i / 16) * lp.r * 0.85;
        spiral.push({ x: x + Math.cos(a) * rr, y: cy + Math.sin(a) * rr });
      }
      out.push({ kind: 'line', depth: 1, color: 'text', alpha: 0.6, width: 1, pts: spiral });
    }
  } else if (motif === 'jellyfish') {
    for (const j of lay.jellies) {
      const x = tileX(j.x0, sx, j.f);
      if (x === null) continue;
      const pulse = 1 + 0.08 * Math.sin(t / 520 + j.ph) + 0.09 * dance;
      const y = j.y + Math.sin(t / 1400 + j.ph) * 5;
      const rx = j.s * pulse;
      const ry = (j.s * 0.8) / pulse;
      const bell = [];
      for (let i = 0; i <= 10; i++) {
        const a = Math.PI + (i / 10) * Math.PI;
        bell.push({ x: x + Math.cos(a) * rx, y: y + Math.sin(a) * ry });
      }
      // Scalloped skirt along the bottom of the bell.
      for (let i = 1; i < 5; i++) bell.push({ x: x + rx - (i / 5) * 2 * rx, y: y + (i % 2 ? 2 : 0) });
      out.push({ kind: 'poly', depth: -1, color: j.color, fillAlpha: 0.22, lineAlpha: 0.6, pts: bell });
      for (let k = 0; k < 4; k++) {
        const bx = x - rx * 0.6 + (k / 3) * rx * 1.2;
        const len = j.s * 2.2;
        const tend = [];
        for (let i = 0; i <= 5; i++) {
          const u = i / 5;
          tend.push({ x: bx + Math.sin(t / 650 + j.ph + k * 0.7 + u * 3) * u * 3, y: y + 2 + u * len });
        }
        out.push({ kind: 'line', depth: -1, color: j.color, alpha: 0.45, width: 1, pts: tend });
      }
    }
  } else if (motif === 'brass-pipes') {
    // Gears turning behind the factory roofline (scene time drives the rotation).
    for (const gr of lay.gears) {
      const x = tileX(gr.x0, sx, 0.06);
      if (x === null) continue;
      const teeth = Math.max(6, Math.round(gr.r / 2.4));
      const rot = gr.ph + gr.dir * t * (0.012 / gr.r) + dance * 0.055 * gr.dir;
      const pts = [];
      for (let i = 0; i < teeth; i++) {
        const a = rot + (i / teeth) * Math.PI * 2;
        const st = (Math.PI * 2) / teeth;
        pts.push({ x: x + Math.cos(a) * gr.r, y: gr.y + Math.sin(a) * gr.r });
        pts.push({ x: x + Math.cos(a + st * 0.15) * (gr.r + 4), y: gr.y + Math.sin(a + st * 0.15) * (gr.r + 4) });
        pts.push({ x: x + Math.cos(a + st * 0.45) * (gr.r + 4), y: gr.y + Math.sin(a + st * 0.45) * (gr.r + 4) });
        pts.push({ x: x + Math.cos(a + st * 0.6) * gr.r, y: gr.y + Math.sin(a + st * 0.6) * gr.r });
      }
      out.push({ kind: 'poly', depth: -1, color: 'amber', fillAlpha: 0.16, lineAlpha: 0.55, pts });
      out.push({ kind: 'circle', depth: -1, color: 'amber', fillAlpha: 0, lineAlpha: 0.55, x, y: gr.y, r: gr.r * 0.38 });
    }
    // A brass pipe run in front of the far roofline: pipe, highlight, flanges, and some drop pipes.
    const L0 = def.layers[0];
    const py = lay.pipeY;
    out.push({ kind: 'line', depth: 0, color: 'amber', alpha: 0.5, width: 4, pts: [{ x: -4, y: py }, { x: W + 4, y: py }] });
    out.push({ kind: 'line', depth: 0, color: 'text', alpha: 0.22, width: 1, pts: [{ x: -4, y: py - 1 }, { x: W + 4, y: py - 1 }] });
    const FL = 64;
    const off = sx * L0.factor;
    const k0 = Math.floor(off / FL);
    for (let k = k0; ; k++) {
      const x = k * FL - off;
      if (x > W + 4) break;
      out.push({ kind: 'rect', depth: 0, color: 'amber', alpha: 0.6, x: x - 2, y: py - 4, w: 4, h: 8 });
      if (lay.drops[((k % 15) + 15) % 15]) {
        const yb = H * 0.68;
        out.push({ kind: 'line', depth: 0, color: 'amber', alpha: 0.45, width: 3, pts: [{ x: x + 10, y: py }, { x: x + 10, y: yb }] });
        out.push({ kind: 'circle', depth: 0, color: 'amber', fillAlpha: 0.4, lineAlpha: 0.6, x: x + 10, y: py, r: 3 });
      }
    }
  } else if (motif === 'dew-drops') {
    for (const b of lay.blades) {
      const L = def.layers[b.layer];
      const x = tileX(b.x0, sx, L.factor);
      if (x === null) continue;
      const yB = layerYAt(def.shape, L, sx, x, horizonDance) + 3;
      const beatSway = dance * (3 + b.h * 0.045) * Math.sin(b.ph);
      const centre = (u) => ({
        x: x + (b.lean + beatSway) * u * u,
        y: yB - b.h * u,
      });
      const left = [];
      const right = [];
      for (let i = 0; i <= 5; i++) {
        const u = i / 5;
        const c = centre(u);
        const hw = b.w * (1 - u);
        left.push({ x: c.x - hw, y: c.y });
        right.push({ x: c.x + hw, y: c.y });
      }
      out.push({ kind: 'poly', depth: b.layer, color: 'lime', fillAlpha: 0.18, lineAlpha: 0.5, pts: [...left, ...right.reverse()] });
      if (b.drop) {
        const c = centre(b.dt);
        const r = 3.5 + b.h / 16;
        const dx = c.x + (b.lean >= 0 ? -1 : 1) * b.w * (1 - b.dt) * 0.4;
        const dy = c.y - r * 0.6;
        out.push({ kind: 'circle', depth: b.layer, color: 'cyan', fillAlpha: 0.3, lineAlpha: 0.75, x: dx, y: dy, r });
        out.push({ kind: 'circle', depth: b.layer, color: 'text', fillAlpha: 0.5 + 0.4 * Math.sin(t / 900 + b.ph), lineAlpha: 0, x: dx - r * 0.35, y: dy - r * 0.35, r: Math.max(1, r * 0.3) });
      }
    }
    // Micro glow-up: HUGE bees (they are ordinary bees; the rider is the micro one). After the near layer and its
    // blades, so a bee flies over the moss but under the terrain, the hazards and everything else in the run.
    if (!(o && o.bees === false)) {
      const seedI = Number.isFinite(seed) ? Math.trunc(seed) : 0;
      for (const d of beePrimitives(beesAt(sx, t, seedI), def.layers.length - 1)) out.push(d);
    }
  } else if (motif === 'vents') {
    // A plume over every active cone, on the same layer as its cone, so the near ridge hides far smoke.
    def.layers.forEach((L, li) => {
      const s71 = L.seed * 71;
      const off = sx * L.factor;
      const c0 = Math.floor((off - DECOR_MARGIN + s71) / CONE_W);
      const c1 = Math.floor((off + W + DECOR_MARGIN + s71) / CONE_W);
      const plumeH = li === 0 ? 58 : 44;
      for (let c = c0; c <= c1; c++) {
        if (hash01(c, L.seed * 1000 + 17) < 0.25) continue;
        const cx = (c + 0.5) * CONE_W - s71 - off;
        if (cx < -60 || cx > W + 60) continue;
        const top = layerYAt(def.shape, L, sx, cx, horizonDance) + 1;
        out.push({ kind: 'circle', depth: li, color: 'amber', fillAlpha: 0.35, lineAlpha: 0, x: cx, y: top, r: 4 + dance * 0.7 });
        const cell = hash01(c, 4242);
        for (let k = 0; k < 6; k++) {
          const age = (((t / 3800 + k / 6 + cell) % 1) + 1) % 1;
          out.push({
            kind: 'circle', depth: li, color: 'text', fillAlpha: 0.3 * (1 - age), lineAlpha: 0,
            x: cx + age * 14 * lay.wind + Math.sin(age * 5 + lay.ph + c) * 3,
            y: top - 4 - age * plumeH,
            r: (2.5 + age * 8) * (li === 0 ? 1 : 0.8),
          });
        }
      }
    });
  }
  return out;
}

export class Background {
  /**
   * @param {Phaser.Scene} scene
   * @param {Object<string,number>} palette
   */
  constructor(scene, palette) {
    this.scene = scene;
    this.palette = palette;
    this.motif = null; // null = base backdrop ('ridges'), so pre-W3 runs are unchanged
    this.skin = null; // #65: 'pixel' = BiomeFx draws the sky and ridgelines (Debutmont's SVG art); null = drawn here
    this.decorSeed = 0; // layout seed for motifDecor; fixed so a biome's backdrop looks the same every run
    this.bees = true; // Micro glow-up: draw the dew-drops bees (false = the perf comparison baseline)
    this.beeCount = 0; // bees drawn in the last frame (the built-game gate reads it)
    this.gfx = scene.add.graphics().setScrollFactor(0).setDepth(-100);
    const rnd = mulberry32(0xb175);
    this.stars = [];
    for (let i = 0; i < STAR_COUNT; i++) {
      this.stars.push({ x: rnd() * TILE, y: rnd() * GAME_HEIGHT * 0.8, z: 0.02 + rnd() * 0.1, tw: rnd() * 6.28, s: rnd() < 0.15 ? 2 : 1 });
    }
  }

  /** @param {Object<string,number>} palette @returns {void} */
  setPalette(palette) {
    this.palette = palette;
  }

  /**
   * #65: hand the sky bands and the ridgelines to the pixel-art layers (BiomeFx) or take them back. Stars, sun and the
   * data grid stay here either way.
   * @param {string|null} skin 'pixel' | null
   * @returns {void}
   */
  setSkin(skin) {
    this.skin = skin === 'pixel' ? 'pixel' : null;
  }

  /**
   * W3: switch the background motif. Passing null/undefined returns to the base backdrop, which is what
   * the biome-exit path does — a motif must not outlive the sector that owns it.
   * @param {string|null} motif
   * @returns {void}
   */
  setMotif(motif) {
    this.motif = typeof motif === 'string' && MOTIFS.includes(motif) ? motif : null;
  }

  /**
   * One sample of a layer's height at a world x, per shape. Every profile returns -1..1 before amplitude
   * so section heights stay comparable between motifs.
   * @param {string} shape @param {number} wx @param {number} seed @returns {number}
   */
  _profile(shape, wx, seed) {
    return motifProfile(shape, wx, seed);
  }

  /**
   * Draw one motif layer. The pre-W3 `_ridge` is this function with shape 'peak', which is why base
   * terrain still looks identical: same profile, same sampling step, same fill/stroke alphas.
   * @param {Phaser.GameObjects.Graphics} g
   * @param {number} scrollX
   * @param {Object} layer a layer from motifGeometry()
   * @param {Object<string,number>} palette
   * @param {string} shape
   * @returns {void}
   */
  _layer(g, scrollX, layer, palette, shape, dance = 0) {
    const step = 8;
    const off = scrollX * layer.factor;
    const baseY = GAME_HEIGHT * layer.baseY;
    const color = palette[layer.color] != null ? palette[layer.color] : palette.cyan;
    const pts = [{ x: 0, y: GAME_HEIGHT }];
    for (let sx = 0; sx <= GAME_WIDTH + step; sx += step) {
      const wx = sx + off;
      const h = this._profile(shape, wx, layer.seed);
      // Sharpen crests slightly (wireframe-mountain feel). Step/facet shapes already carry their own
      // character from _profile, so the extra crest term only applies to the smooth profiles.
      const crest = CRESTLESS.has(shape) ? 0 : (h > 0 ? h * layer.amp * 0.2 : 0);
      // Only the decorative horizon dances; the terrain mesh and collision
      // geometry are owned by separate systems and never use this offset.
      const sway = horizonDanceOffset(scrollX, sx, layer, dance);
      pts.push({ x: sx, y: baseY - Math.abs(h) * layer.amp - crest + sway });
    }
    pts.push({ x: GAME_WIDTH + step, y: GAME_HEIGHT });
    g.fillStyle(palette.bg, 1);
    g.fillPoints(pts, true);
    g.fillStyle(color, layer.fillAlpha);
    g.fillPoints(pts, true);
    g.lineStyle(1, color, layer.lineAlpha);
    g.strokePoints(pts.slice(1, -1), false, false);
  }

  /**
   * Draw the decor primitives at one depth (see motifDecor). Colour keys resolve through the palette the
   * same way _layer's do, so colour-blind mode and biome tints apply to decor too.
   * @param {Phaser.GameObjects.Graphics} g
   * @param {ReadonlyArray<Object>} decor
   * @param {number} depth
   * @param {Object<string,number>} palette
   * @returns {void}
   */
  _decor(g, decor, depth, palette) {
    for (const d of decor) {
      if (d.depth !== depth) continue;
      const color = palette[d.color] != null ? palette[d.color] : palette.cyan;
      if (d.kind === 'rect') {
        g.fillStyle(color, d.alpha);
        g.fillRect(d.x, d.y, d.w, d.h);
      } else if (d.kind === 'line') {
        g.lineStyle(d.width, color, d.alpha);
        if (d.pts.length === 2) g.lineBetween(d.pts[0].x, d.pts[0].y, d.pts[1].x, d.pts[1].y);
        else g.strokePoints(d.pts, false, false);
      } else if (d.kind === 'circle') {
        if (d.fillAlpha > 0) {
          g.fillStyle(color, d.fillAlpha);
          g.fillCircle(d.x, d.y, d.r);
        }
        if (d.lineAlpha > 0) {
          g.lineStyle(1, color, d.lineAlpha);
          g.strokeCircle(d.x, d.y, d.r);
        }
      } else if (d.kind === 'poly') {
        if (d.fillAlpha > 0) {
          g.fillStyle(color, d.fillAlpha);
          g.fillPoints(d.pts, true);
        }
        if (d.lineAlpha > 0) {
          g.lineStyle(1, color, d.lineAlpha);
          g.strokePoints(d.pts, true, true);
        }
      }
    }
  }

  _ridge(g, scrollX, factor, baseY, amp, seed, color, fillAlpha, lineAlpha) {
    const step = 8;
    const off = scrollX * factor;
    const pts = [{ x: 0, y: GAME_HEIGHT }];
    for (let sx = 0; sx <= GAME_WIDTH + step; sx += step) {
      const wx = sx + off;
      const h = Math.sin(wx * 0.011 + seed) * 0.55 + Math.sin(wx * 0.027 + seed * 2.3) * 0.3 + Math.sin(wx * 0.061 + seed * 4.1) * 0.15;
      // sharpen peaks a little (wireframe-mountain feel)
      const y = baseY - Math.abs(h) * amp - (h > 0 ? h * amp * 0.2 : 0);
      pts.push({ x: sx, y });
    }
    pts.push({ x: GAME_WIDTH + step, y: GAME_HEIGHT });
    g.fillStyle(this.palette.bg, 1);
    g.fillPoints(pts, true);
    g.fillStyle(color, fillAlpha);
    g.fillPoints(pts, true);
    g.lineStyle(1, color, lineAlpha);
    g.strokePoints(pts.slice(1, -1), false, false);
  }

  /**
   * @param {number} scrollX camera scroll X (world px).
   * @param {number} timeMs
   * @param {number} speedPxS rider speed (streaks the grid at high speed).
   * @returns {void}
   */
  update(scrollX, timeMs, speedPxS = 0, danceStrength = 0) {
    const g = this.gfx;
    const p = this.palette;
    const dance = biomeDanceStyle(this.motif,danceStrength);
    g.clear();
    // sky gradient (banded)
    const pixel = this.skin === 'pixel';
    const bands = pixel ? 0 : 8;
    for (let i = 0; i < bands; i++) {
      const t = i / bands;
      g.fillStyle(p.magenta, 0.015 + 0.075 * t * t);
      g.fillRect(0, GAME_HEIGHT * (0.1 + 0.6 * t), GAME_WIDTH, (GAME_HEIGHT * 0.6) / bands + 1);
    }
    // stars
    for (const s of this.stars) {
      let x = (s.x - scrollX * s.z) % TILE;
      if (x < 0) x += TILE;
      if (x > GAME_WIDTH) continue;
      const a = 0.35 + 0.35 * Math.sin(timeMs / 600 + s.tw);
      g.fillStyle(s.s > 1 ? p.cyan : p.text, a);
      g.fillRect(Math.floor(x), Math.floor(s.y), s.s, s.s);
    }
    // striped sun
    const sunX = GAME_WIDTH * 0.72 - ((scrollX * 0.02) % 40);
    const sunY = GAME_HEIGHT * 0.27;
    const R = 40;
    // Real-sound-transient response, NOT a verified beat grid. Alternate
    // width/height a few px around the same centre: gentle Popeye-like
    // squish, with no camera motion or strobe. Zero reproduces old drawing.
    const {widthRadius:rx,heightRadius:ry}=sunDanceGeometry(dance.sun,R);
    for (let i = 0; i < 9; i++) {
      const y0 = sunY - ry + (i * 2 * ry) / 9;
      const y1 = y0 + (2 * ry) / 9 - (i * 0.45 + 0.4);
      const mid = (y0 + y1) / 2;
      const dy = mid - sunY;
      if (Math.abs(dy) >= ry) continue;
      const hw = rx * Math.sqrt(1 - (dy * dy) / (ry * ry));
      g.fillStyle(i < 4 ? p.amber : p.magenta, 0.2 + i * 0.012);
      // pixel skin: stripes on whole pixels with stepped edges, and no smooth outline
      if (pixel) {
        const sw = Math.round(hw / 4) * 4;
        g.fillRect(Math.round(sunX) - sw, Math.round(y0), sw * 2, Math.max(1, Math.round(y1 - y0)));
      } else g.fillRect(sunX - hw, y0, hw * 2, Math.max(1, y1 - y0));
    }
    g.lineStyle(1, p.amber, 0.35);
    if (pixel) { /* stepped stripes only */ }
    else if(dance.sun > 0.001) g.strokeEllipse(sunX, sunY, rx * 2, ry * 2);
    else g.strokeCircle(sunX, sunY, R);
    // ridges / biome motif
    const geom = motifGeometry(this.motif, scrollX);
    // Audit T1: W6 motifs add decor between/over their layers. The base backdrop and the batch-1 motifs
    // have none, so their draw calls are exactly what they were.
    const decor = this.motif ? motifDecor(this.motif, scrollX, timeMs, this.decorSeed,
      { bees: this.bees, dance: dance.decor,
        horizonDance: dance.horizon }) : EMPTY_DECOR;
    let beeMask = 0;
    for (const d of decor) if (d.bee !== undefined) beeMask |= 1 << d.bee;
    let bees = 0;
    for (; beeMask; beeMask &= beeMask - 1) bees += 1;
    this.beeCount = bees;
    if (decor.length) this._decor(g, decor, -1, p);
    for (let i = 0; i < (pixel ? 0 : geom.layers.length); i++) {
      this._layer(g, scrollX, geom.layers[i], p, geom.shape, dance.horizon);
      if (decor.length) this._decor(g, decor, i, p);
    }
    // data grid (faint), vertical lines scroll with parallax, speed streaks stretch them
    const gs = 48;
    const gx = -((scrollX * 0.35) % gs);
    g.lineStyle(1, p.cyan, 0.05);
    for (let x = gx; x < GAME_WIDTH; x += gs) g.lineBetween(x, 0, x, GAME_HEIGHT);
    for (let y = 0; y < GAME_HEIGHT; y += gs) g.lineBetween(0, y, GAME_WIDTH, y);
    if (speedPxS > 500) {
      const k = Math.min(1, (speedPxS - 500) / 500);
      g.lineStyle(1, p.text, 0.08 * k);
      for (let i = 0; i < 10; i++) {
        const y = ((i * 97 + (timeMs * 0.3)) % GAME_HEIGHT);
        const x = ((i * 173 - scrollX * 0.6) % GAME_WIDTH + GAME_WIDTH) % GAME_WIDTH;
        g.lineBetween(x, y, x - 30 * k - 10, y);
      }
    }
  }

  /** @returns {void} */
  destroy() {
    if (this.gfx) this.gfx.destroy();
    this.gfx = null;
  }
}/**
 * OWNER: gameplay (game-feel pass). A vertical neon "BEST" gate standing on the terrain at the device's best distance.
 * Drawn lazily once the terrain around it is within reach; pulses a little; destroyed with the run.
 */
import Phaser from 'phaser';

export class BestMarker {
  /**
   * @param {Phaser.Scene} scene
   * @param {Object<string,number>} palette
   * @param {number} x world px of the gate.
   * @param {number} distanceM label value.
   */
  constructor(scene, palette, x, distanceM) {
    this.scene = scene;
    this.palette = palette;
    this.x = x;
    this.distanceM = distanceM;
    this.y = null;
    this.gfx = scene.add.graphics().setDepth(7);
    this.label = scene.add.text(x, 0, `BEST ${distanceM}m`, {
      fontFamily: 'monospace', fontSize: '12px', color: '#ffffff',
    }).setOrigin(0.5, 1).setDepth(7).setVisible(false);
    this.passed = false;
  }


  /**
   * Where the label hangs (MarkerLayout.layoutMarkerLabels): world x/y of its bottom edge and the text origin x.
   * @param {{x:number, y:number, originX:number}|null} p @returns {void}
   */
  setPlacement(p) {
    if (!this.label || !p) return;
    this.label.setOrigin(p.originX, 1).setPosition(p.x, p.y);
  }

  /**
   * @param {number} timeMs
   * @param {number} sledX
   * @param {(x:number)=>number} heightAt terrain height (only used once the sled is near).
   * @returns {void}
   */
  update(timeMs, sledX, heightAt) {
    if (!this.gfx) return;
    if (this.y == null) {
      if (this.x - sledX > 2600) return;
      const y = heightAt(this.x);
      if (!Number.isFinite(y)) return;
      this.y = y;
      this.label.setPosition(this.x, y - 96).setVisible(true);
    }
    const col = this.passed ? this.palette.lime : this.palette.amber;
    const pulse = 0.65 + 0.35 * Math.sin(timeMs / 180);
    const g = this.gfx;
    g.clear();
    const x = this.x;
    const y = this.y;
    g.lineStyle(7, col, 0.12 * pulse);
    g.lineBetween(x, y, x, y - 90);
    g.lineStyle(2, col, 0.95);
    g.lineBetween(x, y, x, y - 90);
    g.lineStyle(1.5, col, 0.6 * pulse);
    for (let i = 0; i < 6; i++) g.lineBetween(x, y - 10 - i * 14, x + 14, y - 14 - i * 14);
    g.fillStyle(col, 0.35 * pulse);
    g.fillRect(x - 1, y - 92, 3 + 20 * (this.passed ? 0 : 1), 4);
    this.label.setColor(this.passed ? '#7dff9a' : '#ffffff');
  }

  /** @returns {void} */
  markPassed() {
    this.passed = true;
  }

  /** @returns {void} */
  destroy() {
    if (this.gfx) this.gfx.destroy();
    if (this.label) this.label.destroy();
    this.gfx = null;
    this.label = null;
  }
}/** Issue #54: which artwork a song billboard shows, driven only by catalog metadata.
 *
 * 1. A confirmed YouTube ID: explicit `track.youtubeId`, or (backward
 *    compatible) a catalog `track.id` that is itself an 11-character YouTube
 *    video ID. `youtubeId: null` explicitly opts a track out.
 * 2. Otherwise, or while/if that thumbnail is unavailable, the bundled generic
 *    NOW PLAYING card. No track is special-cased.
 *
 * Thumbnails load at most once per ID per session, never per frame: the bundled
 * `music/thumbnails/<id>.jpg` first, then YouTube's public thumbnail URL. A
 * failure is remembered and the generic card stays.
 */
export const YOUTUBE_ID_RE=/^[A-Za-z0-9_-]{11}$/;
export const GENERIC_ART_KEY='bb-art-generic';
export const GENERIC_ART_URL='music/billboard/generic-now-playing.png';
export const CATALOG_CACHE_KEY='bb-music-catalog';
export const CATALOG_URL='music/catalog.json';

export const isYoutubeId=(v)=>typeof v==='string'&&YOUTUBE_ID_RE.test(v);

/** Confirmed YouTube video ID for a catalog track, or null. */
export function trackYoutubeId(track){
  if(!track||typeof track!=='object')return null;
  if(Object.prototype.hasOwnProperty.call(track,'youtubeId'))return isYoutubeId(track.youtubeId)?track.youtubeId:null;
  return isYoutubeId(track.id)?track.id:null;
}
export const youtubeArtKey=(id)=>`bb-youtube-${id}`;
/** Load order for one YouTube ID: bundled copy, then YouTube's own thumbnail (sends CORS `*`). */
export function youtubeArtSources(id){
  return isYoutubeId(id)?[`music/thumbnails/${id}.jpg`,`https://i.ytimg.com/vi/${id}/mqdefault.jpg`]:[];
}
/** Catalog entry for a playing track: the event payload overlaid on the catalog row with the same id. */
export function catalogTrack(catalog,payload){
  if(!payload?.id)return null;
  const row=Array.isArray(catalog?.tracks)?catalog.tracks.find(t=>t&&t.id===payload.id):null;
  return {...(row||{}),...payload};
}

/** Per-game, scene-independent thumbnail loader (Phaser's TextureManager is global). */
export class BillboardArtLoader {
  /** @param {{exists:(k:string)=>boolean, addImage:(k:string,img:any)=>any}} textures */
  constructor(textures,makeImage=()=>(typeof Image==='function'?new Image():null)){
    this.textures=textures;
    this.makeImage=makeImage;
    this.state=new Map();   // id -> 'loading' | 'ready' | 'failed'
    this.waiters=new Map(); // id -> [callbacks]
  }
  status(id){
    if(!isYoutubeId(id))return 'failed';
    if(this.textures.exists(youtubeArtKey(id)))return 'ready';
    return this.state.get(id)||'idle';
  }
  /** Start loading (once) and call `done(ready:boolean)` when settled. Returns the current status. */
  ensure(id,done){
    const s=this.status(id);
    if(s==='ready'||s==='failed'){done?.(s==='ready');return s;}
    if(done){const w=this.waiters.get(id)||[];w.push(done);this.waiters.set(id,w);}
    if(s==='idle'){this.state.set(id,'loading');this._try(id,youtubeArtSources(id),0);}
    return 'loading';
  }
  _settle(id,ok){
    this.state.set(id,ok?'ready':'failed');
    const w=this.waiters.get(id)||[];this.waiters.delete(id);
    for(const fn of w){try{fn(ok);}catch{/* a stale scene must not break other waiters */}}
  }
  _try(id,sources,i){
    const img=i<sources.length?this.makeImage():null;
    if(!img){this._settle(id,false);return;}
    img.crossOrigin='anonymous'; // a tainted image cannot become a WebGL texture
    img.onload=()=>{
      if(!(img.naturalWidth>0)){this._try(id,sources,i+1);return;}
      try{
        if(!this.textures.exists(youtubeArtKey(id)))this.textures.addImage(youtubeArtKey(id),img);
        this._settle(id,true);
      }catch{this._try(id,sources,i+1);}
    };
    img.onerror=()=>this._try(id,sources,i+1);
    img.src=sources[i];
  }
}
const loaders=new WeakMap();
/** The one loader for this Phaser game. */
export function billboardArtLoader(game){
  let l=loaders.get(game);
  if(!l){l=new BillboardArtLoader(game.textures);loaders.set(game,l);}
  return l;
}
/** PreloadScene: the generic card and the catalog (for youtubeId metadata). */
export function queueBillboardArt(loader){
  loader.image(GENERIC_ART_KEY,GENERIC_ART_URL);
  loader.json(CATALOG_CACHE_KEY,CATALOG_URL);
}
/** Warm every catalog track's thumbnail once at boot, so a song's first billboard rarely waits. */
export function prewarmBillboardArt(game){
  const catalog=game.cache?.json?.get?.(CATALOG_CACHE_KEY);
  if(!Array.isArray(catalog?.tracks))return 0;
  const loader=billboardArtLoader(game);
  let n=0;
  for(const t of catalog.tracks){const id=trackYoutubeId(t);if(id){loader.ensure(id);n++;}}
  return n;
}/**
 * OWNER: gameplay engineer.
 * #65 presentation: the biome-aware glitch layers and the arcade bridge look. Cosmetic only: it reads the camera scroll,
 * the run clock and a look decision (systems/BiomeTransition.js), draws behind the play layer, and touches no
 * terrain, physics, hazard or score state. Its randomness is a named cosmetic stream (CosmeticRandom), never a gameplay one.
 *
 * One screen-space Container at depth -99 (above Background at -100, below the terrain at 5), counter-scaled for camera
 * zoom like Background. Layers, bottom to top:
 *   Debutmont  an ordered-dither sky, two pixel-stepped SVG ridgelines (parallax), blocky pixel snow, an occasional
 *              scanline shimmer. Background stops drawing its own sky bands and ridges while this skin is on.
 *   Glacier    corrupt-trash debris: blocky trash pixels and colour-channel-offset glitch fragments.
 *   Arcade     the veil: Bayer-dithered pixel blocks that cover the backdrop (coverage = BiomeTransition veil), then a
 *              dithered sky, a stepped sun, a blocky skyline, a neon perspective grid and CRT scanlines.
 * Every other biome shows nothing from here.
 *
 * Hot path: no allocations (typed-array pools, whole-pixel positions, no per-frame closures). Reduced motion keeps the
 * art but stops the time-driven parts (snow fall, shimmer, debris) and the dissolve (the veil is simply on or off).
 */
import { GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
import { VEIL_CELL_PX, veilCovers, hash01 } from '../systems/BiomeTransition.js';
import { cosmeticRandom } from '../systems/CosmeticRandom.js';
import { mixColor } from '../ui/MenuArt.js';
import { BACKDROP_ART, hasBackdropArt } from '../ui/BackdropArt.js';

const ADD = 1; // Phaser.BlendModes.ADD
const DEPTH = -99;

const SNOW_COUNT = 64;
const DEBRIS_TRASH = 26;
const DEBRIS_FRAG = 14;
/** Debris lives in the upper part of the screen (the sky); the ground covers the rest. */
const DEBRIS_BAND_H = GAME_HEIGHT * 0.8;

/** Where the arcade horizon sits on screen (y). */
const HORIZON_Y = 118;
const GRID_COLS = 9; // perspective lane lines each side of centre
const GRID_ROWS = 9;
const LANE_PX = 84; // lane spacing at the bottom of the screen

const CRT_KEY = 'bd-crt-lines';
/** How long one shimmer pass sweeps (ms). */
const SHIMMER_MS = 1100;

const wrap = (v, n) => ((v % n) + n) % n;
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

export class BiomeFx {
  /**
   * @param {Phaser.Scene} scene
   * @param {Object} palette the live (look) palette
   * @param {Object} arcadePalette the base palette the arcade bridge wears
   * @param {{setSkin:function(string|null):void}|null} [background] the Background to hand its sky/ridges over to
   */
  constructor(scene, palette, arcadePalette, background = null) {
    this.scene = scene;
    this.bg = background;
    this.palette = palette;
    this.arc = arcadePalette;
    this.lookId = null;
    this.veil = 0;
    this._veilDrawn = -1; // veil level the block layer was last drawn at (-1 = stale)
    this._gridKey = -1;
    this.debut = false;
    this.gdg = false;
    this.hasDebutArt = hasBackdropArt(scene, 'debutmontSky') && hasBackdropArt(scene, 'debutmontRidgeFar') && hasBackdropArt(scene, 'debutmontRidgeNear');
    this.shimNext = 0; // run-clock ms of the next shimmer pass (0 = not scheduled yet)
    this.shimStart = -1;
    this._rng = cosmeticRandom('biomefx');
    this._seed = (this._rng.next() * 0x7fffffff) | 0;

    const add = scene.add;
    this.root = add.container(0, 0).setScrollFactor(0).setDepth(DEPTH);
    const img = (name, x, y) => (hasBackdropArt(scene, name)
      ? add.image(x, y, BACKDROP_ART[name].key).setOrigin(0, 0).setScrollFactor(0) : null);
    const tile = (name, x, y, w, h) => (hasBackdropArt(scene, name)
      ? add.tileSprite(x, y, w, h, BACKDROP_ART[name].key).setOrigin(0, 0).setScrollFactor(0) : null);

    // Debutmont
    this.debutSky = img('debutmontSky', 0, 8);
    this.ridgeFar = tile('debutmontRidgeFar', 0, 54, GAME_WIDTH, BACKDROP_ART.debutmontRidgeFar.h);
    this.ridgeNear = tile('debutmontRidgeNear', 0, 100, GAME_WIDTH, BACKDROP_ART.debutmontRidgeNear.h);
    this.snowG = add.graphics().setScrollFactor(0);
    // Glacier
    this.debrisG = add.graphics().setScrollFactor(0);
    this.debrisAdd = add.graphics().setScrollFactor(0).setBlendMode(ADD);
    // Arcade
    this.veilG = add.graphics().setScrollFactor(0);
    this.arcSky = img('arcadeSky', 0, HORIZON_Y - BACKDROP_ART.arcadeSky.h);
    this.arcSun = img('arcadeSun', 300, HORIZON_Y - BACKDROP_ART.arcadeSun.h);
    this.arcSkyline = tile('arcadeSkyline', 0, HORIZON_Y - BACKDROP_ART.arcadeSkyline.h, GAME_WIDTH, BACKDROP_ART.arcadeSkyline.h);
    this.gridG = add.graphics().setScrollFactor(0);
    this.crt = this._crtImage();
    const kids = [this.debutSky, this.ridgeFar, this.ridgeNear, this.snowG, this.debrisG, this.debrisAdd, this.veilG,
      this.arcSky, this.arcSun, this.arcSkyline, this.gridG, this.crt];
    this.root.add(kids.filter(Boolean));
    this.root.setVisible(false);

    this._buildPools();
    this.setPalettes(palette, arcadePalette);
    this._applyVisibility(0);
  }

  // ------------------------------------------------------------------ setup

  /** One 480x270 canvas of 1 px dark rows every third row: the CRT scanlines. Shared across runs. */
  _crtImage() {
    const tm = this.scene.textures;
    if (!tm) return null;
    if (!tm.exists(CRT_KEY)) {
      const tex = tm.createCanvas(CRT_KEY, GAME_WIDTH, GAME_HEIGHT);
      const ctx = tex && tex.context;
      if (!ctx) return null;
      ctx.fillStyle = 'rgba(0,0,0,0.42)';
      for (let y = 1; y < GAME_HEIGHT; y += 3) ctx.fillRect(0, y, GAME_WIDTH, 1);
      tex.refresh();
    }
    return this.scene.add.image(0, 0, CRT_KEY).setOrigin(0, 0).setScrollFactor(0);
  }

  /** Fixed-size typed pools, laid out once from the cosmetic stream; nothing is allocated per frame. */
  _buildPools() {
    const r = this._rng;
    const n = SNOW_COUNT;
    this.snowX = new Float32Array(n);
    this.snowY = new Float32Array(n);
    this.snowS = new Uint8Array(n);
    this.snowV = new Float32Array(n);
    this.snowZ = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      const roll = r.next();
      const s = roll < 0.5 ? 2 : roll < 0.8 ? 3 : 4;
      this.snowX[i] = r.next() * GAME_WIDTH;
      this.snowY[i] = r.next() * GAME_HEIGHT;
      this.snowS[i] = s;
      this.snowV[i] = 12 + s * 9 + r.next() * 8; // px/s: bigger flakes are nearer, so faster
      this.snowZ[i] = 0.03 + s * 0.035; // parallax: nearer = more camera-driven drift
    }
    const m = DEBRIS_TRASH + DEBRIS_FRAG;
    this.dX = new Float32Array(m);
    this.dY = new Float32Array(m);
    this.dW = new Uint8Array(m);
    this.dH = new Uint8Array(m);
    this.dVx = new Float32Array(m);
    this.dVy = new Float32Array(m);
    this.dZ = new Float32Array(m);
    this.dK = new Uint8Array(m); // 0..2 trash colour, 3 fragment
    this.dPh = new Float32Array(m);
    for (let i = 0; i < m; i++) {
      const frag = i >= DEBRIS_TRASH;
      this.dX[i] = r.next() * GAME_WIDTH;
      this.dY[i] = r.next() * DEBRIS_BAND_H;
      this.dW[i] = frag ? 8 + ((r.next() * 5) | 0) * 2 : 2 + ((r.next() * 3) | 0) * 2;
      this.dH[i] = frag ? 2 + ((r.next() * 2) | 0) * 2 : this.dW[i] > 4 ? 2 : this.dW[i];
      this.dVx[i] = -(4 + r.next() * 10);
      this.dVy[i] = 5 + r.next() * 9;
      this.dZ[i] = 0.05 + r.next() * 0.2;
      this.dK[i] = frag ? 3 : (r.next() * 3) | 0;
      this.dPh[i] = r.next() * 50;
    }
  }

  /**
   * Re-tint everything from the live palettes (a palette setting change, or the look changing biome).
   * @param {Object<string,number>} palette the look palette (the biome the world currently wears)
   * @param {Object<string,number>} arcadePalette the base palette (arcade bridges)
   * @returns {void}
   */
  setPalettes(palette, arcadePalette) {
    this.palette = palette;
    this.arc = arcadePalette;
    const p = palette;
    const a = arcadePalette;
    if (this.debutSky) this.debutSky.setTint(p.magenta).setAlpha(0.38);
    if (this.ridgeFar) this.ridgeFar.setTint(p.magenta).setAlpha(0.8);
    if (this.ridgeNear) this.ridgeNear.setTint(p.cyan).setAlpha(0.9);
    if (this.arcSky) this.arcSky.setTint(a.magenta).setAlpha(0);
    if (this.arcSun) this.arcSun.setTint(a.magenta).setAlpha(0);
    if (this.arcSkyline) this.arcSkyline.setTint(a.cyan).setAlpha(0);
    // deep blue / near black checker for the veil blocks, derived from the palette so colour-blind mode applies
    this.veilA = a.bg;
    this.veilB = mixColor(a.bgAlt, a.cyan, 0.1);
    this._veilDrawn = -1; // the blocks and the grid are palette-coloured: redraw
    this._gridKey = -1;
  }

  /**
   * Which biome's look the world wears now. Switches the biome sets on or off and hands Background's sky/ridges to the
   * SVG layers for Debutmont.
   * @param {string|null} lookId
   * @returns {void}
   */
  setLook(lookId) {
    this.lookId = lookId;
    const debut = lookId === 'debutmont' && this.hasDebutArt;
    const gdg = lookId === 'garbage-dump-glacier';
    // leaving a set drops what it last drew, so nothing stale shows if the set comes back later
    if (this.debut && !debut) { this.snowG.clear(); this.shimStart = -1; this.shimNext = 0; }
    if (this.gdg && !gdg) { this.debrisG.clear(); this.debrisAdd.clear(); }
    this.debut = debut;
    this.gdg = gdg;
    if (this.bg && typeof this.bg.setSkin === 'function') this.bg.setSkin(this.debut ? 'pixel' : null);
  }

  /** Counter-scale for camera zoom (screen-space layer), the same transform Background gets. */
  applyZoomCompensation(k, px, py) {
    if (this.root) this.root.setScale(k).setPosition(px, py);
  }

  _applyVisibility(veil) {
    const arc = veil > 0;
    if (!arc) { this._veilDrawn = -1; this._gridKey = -1; } // hidden: the next showing redraws
    const sky = this.debut && veil < 1;
    if (this.debutSky) this.debutSky.setVisible(sky);
    if (this.ridgeFar) this.ridgeFar.setVisible(sky);
    if (this.ridgeNear) this.ridgeNear.setVisible(sky);
    this.snowG.setVisible(sky);
    this.debrisG.setVisible(this.gdg && veil < 1);
    this.debrisAdd.setVisible(this.gdg && veil < 1);
    this.veilG.setVisible(arc);
    this.gridG.setVisible(arc && veil >= 0.5);
    if (this.arcSky) this.arcSky.setVisible(arc);
    if (this.arcSun) this.arcSun.setVisible(arc);
    if (this.arcSkyline) this.arcSkyline.setVisible(arc);
    if (this.crt) this.crt.setVisible(arc);
    this.root.setVisible(this.debut || this.gdg || arc);
  }

  // ------------------------------------------------------------------ frame

  /**
   * @param {number} scrollX camera scroll x (world px)
   * @param {number} timeMs the run clock
   * @param {number} veil 0..1 bridge veil coverage (BiomeTransition.bridgeLook)
   * @param {boolean} reduced reduced motion: art stays, time-driven motion stops
   * @returns {void}
   */
  update(scrollX, timeMs, veil, reduced) {
    this.veil = veil;
    this._applyVisibility(veil);
    if (!this.root.visible) return;
    const t = reduced ? 0 : timeMs;
    if (this.debut && veil < 1) this._drawDebutmont(scrollX, t, timeMs, reduced);
    if (this.gdg && veil < 1 && !reduced) this._drawDebris(scrollX, t);
    else if (this.gdg) { this.debrisG.clear(); this.debrisAdd.clear(); }
    if (veil > 0) this._drawArcade(scrollX, veil);
  }

  // ------------------------------------------------------------------ Debutmont

  _drawDebutmont(scrollX, t, runMs, reduced) {
    const p = this.palette;
    if (this.ridgeFar) this.ridgeFar.tilePositionX = Math.round(scrollX * 0.1);
    if (this.ridgeNear) this.ridgeNear.tilePositionX = Math.round(scrollX * 0.22);
    // ---- blocky pixel snow: whole-pixel squares, a slight stepped horizontal jitter, no round flakes
    const g = this.snowG;
    g.clear();
    const jstep = Math.floor(t / 220);
    for (let i = 0; i < SNOW_COUNT; i++) {
      const s = this.snowS[i];
      const jit = reduced ? 0 : Math.floor(hash01(jstep + i * 131, this._seed) * 3) - 1;
      const x = ((wrap(this.snowX[i] - scrollX * this.snowZ[i] - t * 0.0045 * s + jit, GAME_WIDTH)) >> 1) << 1;
      const y = ((wrap(this.snowY[i] + (t * this.snowV[i]) / 1000, GAME_HEIGHT)) >> 1) << 1;
      g.fillStyle(i % 6 === 0 ? p.cyan : p.text, s === 4 ? 0.85 : s === 3 ? 0.7 : 0.55);
      g.fillRect(x, y, s, s);
    }
    // ---- an occasional scanline shimmer: a short band of 1 px rows sweeping down the sky, faint, never the whole screen
    if (reduced) return;
    if (runMs < this.shimStart) { this.shimNext = 0; this.shimStart = -1; } // the run clock restarted
    if (this.shimNext === 0) this.shimNext = runMs + this._rng.range(5000, 11000);
    if (this.shimStart < 0 && runMs >= this.shimNext) this.shimStart = runMs;
    if (this.shimStart >= 0) {
      const k = (runMs - this.shimStart) / SHIMMER_MS;
      if (k >= 1) {
        this.shimStart = -1;
        this.shimNext = runMs + this._rng.range(7000, 15000);
      } else {
        const y0 = (Math.floor(k * 120) >> 1) << 1;
        g.fillStyle(p.text, 0.09);
        for (let y = y0; y < y0 + 14; y += 2) g.fillRect(0, y, GAME_WIDTH, 1);
        g.fillStyle(p.cyan, 0.06);
        for (let y = y0 + 15; y < y0 + 21; y += 2) g.fillRect(0, y, GAME_WIDTH, 1);
      }
    }
  }

  // ------------------------------------------------------------------ Garbage Dump Glacier

  _drawDebris(scrollX, t) {
    const p = this.palette;
    const g = this.debrisG;
    const ga = this.debrisAdd;
    g.clear();
    ga.clear();
    const jstep = Math.floor(t / 650);
    for (let i = 0; i < DEBRIS_TRASH + DEBRIS_FRAG; i++) {
      const k = this.dK[i];
      let x = wrap(this.dX[i] + (t * this.dVx[i]) / 1000 - scrollX * this.dZ[i], GAME_WIDTH);
      const y = ((wrap(this.dY[i] + (t * this.dVy[i]) / 1000, DEBRIS_BAND_H)) >> 1) << 1;
      if (k < 3) {
        // blocky trash: 2-6 px rectangles in the glacier's greens, low alpha, behind the play layer
        g.fillStyle(k === 0 ? p.lime : k === 1 ? p.amber : p.text, 0.62);
        g.fillRect((x >> 1) << 1, y, this.dW[i], this.dH[i]);
      } else {
        // a glitched fragment: the same block three times with the colour channels pulled apart; it hops sideways
        // and drops out on a slow stepped schedule, like a corrupt sprite
        const step = Math.floor(jstep + this.dPh[i]);
        const h = hash01(step + i * 17, this._seed);
        if (h < 0.28) continue; // dropped frame
        x += h > 0.8 ? 6 : h > 0.65 ? -4 : 0;
        const xi = (x >> 1) << 1;
        const w = this.dW[i];
        const hh = this.dH[i];
        ga.fillStyle(this.arc.magenta, 0.4);
        ga.fillRect(xi - 3, y, w, hh);
        ga.fillStyle(this.arc.cyan, 0.4);
        ga.fillRect(xi + 3, y, w, hh);
        ga.fillStyle(p.text, 0.3);
        ga.fillRect(xi, y, w, hh);
      }
    }
  }

  // ------------------------------------------------------------------ arcade bridge

  /** Redraw the veil blocks and their neon block grid at this coverage. */
  _drawVeilBlocks(veil) {
    const g = this.veilG;
    const a = this.arc;
    g.clear();
    // ---- the pixel-block veil: Bayer-dithered coverage of 16 px blocks in two deep-blue shades, so the biome look
    // dissolves into chunky pixels, and the same blocks hold the backdrop once the dissolve is complete
    const cols = GAME_WIDTH / VEIL_CELL_PX;
    const rows = Math.ceil(GAME_HEIGHT / VEIL_CELL_PX);
    if (veil >= 1) {
      g.fillStyle(this.veilA, 1);
      g.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      g.fillStyle(this.veilB, 1);
      for (let iy = 0; iy < rows; iy++) for (let ix = (iy & 1); ix < cols; ix += 2) g.fillRect(ix * VEIL_CELL_PX, iy * VEIL_CELL_PX, VEIL_CELL_PX, VEIL_CELL_PX);
    } else {
      for (let pass = 0; pass < 2; pass++) {
        g.fillStyle(pass ? this.veilB : this.veilA, 1);
        for (let iy = 0; iy < rows; iy++) {
          for (let ix = 0; ix < cols; ix++) {
            if (((ix + iy) & 1) !== pass || !veilCovers(ix, iy, veil)) continue;
            g.fillRect(ix * VEIL_CELL_PX, iy * VEIL_CELL_PX, VEIL_CELL_PX, VEIL_CELL_PX);
          }
        }
      }
    }
    // wireframe: the block grid as neon hairlines, brighter as coverage rises
    g.lineStyle(1, a.cyan, 0.1 + 0.2 * veil);
    for (let x = 0; x <= GAME_WIDTH; x += VEIL_CELL_PX) g.lineBetween(x, 0, x, GAME_HEIGHT);
    for (let y = 0; y <= GAME_HEIGHT; y += VEIL_CELL_PX) g.lineBetween(0, y, GAME_WIDTH, y);
  }

  _drawArcade(scrollX, veil) {
    const a = this.arc;
    // The block layer depends only on the veil level (and the palette), so it is drawn when the level changes and
    // left alone otherwise: the whole pure-arcade stretch of a bridge costs no redraw.
    if (veil !== this._veilDrawn) {
      this._veilDrawn = veil;
      this._drawVeilBlocks(veil);
    }

    // ---- the arcade scene fades in over the last stretch of the dissolve (under near-full coverage, so no pop)
    const a1 = clamp01((veil - 0.6) / 0.4);
    if (this.arcSky) this.arcSky.setAlpha(0.45 * a1);
    if (this.arcSun) this.arcSun.setAlpha(0.95 * a1);
    if (this.arcSkyline) {
      this.arcSkyline.setAlpha(0.55 * a1);
      this.arcSkyline.tilePositionX = Math.round(scrollX * 0.05);
    }
    if (this.crt) this.crt.setAlpha(veil);
    const gg = this.gridG;
    if (veil < 0.5) { if (this._gridKey !== 0) { gg.clear(); this._gridKey = 0; } return; }
    // the grid is a function of the camera and the fade only: unchanged inputs keep last frame's drawing
    const key = Math.round(scrollX) * 1000 + Math.round(a1 * 100) + 1;
    if (key === this._gridKey) return;
    this._gridKey = key;
    gg.clear();
    // perspective grid under the horizon: lanes converge on the vanishing point and slide with the camera; rows
    // advance toward the viewer. Both are pure functions of scrollX.
    const vx = GAME_WIDTH / 2;
    const slide = (scrollX * 0.6) % LANE_PX;
    gg.lineStyle(1, a.magenta, 0.55 * a1);
    for (let i = -GRID_COLS; i <= GRID_COLS; i++) {
      const bx = vx + i * LANE_PX - slide;
      gg.lineBetween(vx + (bx - vx) * 0.04, HORIZON_Y, bx, GAME_HEIGHT);
    }
    const adv = wrap(scrollX * 0.004, 1);
    gg.lineStyle(1, a.cyan, 0.6 * a1);
    for (let j = 0; j < GRID_ROWS; j++) {
      const u = (j + adv) / GRID_ROWS;
      const y = Math.round(HORIZON_Y + (GAME_HEIGHT - HORIZON_Y) * u * u);
      gg.lineBetween(0, y, GAME_WIDTH, y);
    }
    // the horizon itself: a bright 2 px line with a magenta glow row beneath it
    gg.fillStyle(a.cyan, a1);
    gg.fillRect(0, HORIZON_Y, GAME_WIDTH, 2);
    gg.fillStyle(a.magenta, 0.5 * a1);
    gg.fillRect(0, HORIZON_Y + 2, GAME_WIDTH, 2);
  }

  /** @returns {void} */
  destroy() {
    if (this.root) this.root.destroy(true);
    this.root = null;
    if (this.bg && typeof this.bg.setSkin === 'function') this.bg.setSkin(null);
    this.bg = null;
  }
}/** Shard Magnet visual: a small black hole on the rider. A near-black core, a spinning
 * accretion ring, and a faint event-horizon circle at the pull radius. It grows with the
 * MAGNET PULL upgrade (strength), never with time. Cosmetic only: no body, no events.
 */
import Phaser from 'phaser';

export class BlackHole {
  /** @param {Phaser.Scene} scene @param {Object<string,number>} palette */
  constructor(scene, palette) {
    this.palette = palette;
    // Above the rider (20): the hole hovers over the sled and must never hide behind it.
    this.core = scene.add.graphics().setDepth(21);
    this.glow = scene.add.graphics().setDepth(21).setBlendMode(Phaser.BlendModes.ADD);
  }

  /**
   * @param {number} timeMs run clock
   * @param {{x:number,y:number}|null} at centre, or null to hide
   * @param {{radius:number, mul:number}} strength from ShardMagnet.magnetStrength
   * @param {number} msLeft effect time left (fades over the last 600 ms)
   * @param {boolean} [reducedMotion]
   */
  update(timeMs, at, strength, msLeft, reducedMotion = false) {
    const g = this.core, a = this.glow;
    g.clear();
    a.clear();
    if (!at || !(msLeft > 0)) return;
    const fade = Math.min(1, msLeft / 600);
    const k = Math.min(1, (strength.mul - 1) / 1.5); // 0 at rank 0, 1 at the soft cap
    const coreR = 6 + 5 * k;
    const spin = reducedMotion ? 0 : timeMs / 160;
    const mag = this.palette.magenta ?? 0xff3cac, cyan = this.palette.cyan ?? 0x2ccde5;
    // Event horizon: the pull radius, barely there
    a.lineStyle(1, mag, 0.14 * fade).strokeCircle(at.x, at.y, strength.radius);
    // Accretion ring: two tilted arcs counter-rotating around the core
    // Soft glow disc behind the ring, so the hole reads at a glance
    a.fillStyle(mag, 0.16 * fade).fillCircle(at.x, at.y, coreR + 9 + 3 * k);
    for (let i = 0; i < 3; i++) {
      const r = coreR + 3 + i * (2.5 + k);
      const s = spin * (i % 2 ? -1 : 1) + i;
      a.lineStyle(2, i % 2 ? cyan : mag, (0.9 - i * 0.2) * fade);
      a.beginPath();
      a.arc(at.x, at.y, r, s, s + Math.PI * 1.2);
      a.strokePath();
    }
    // Core: darker than the sky, with a thin bright rim (the photon ring)
    g.fillStyle(0x020006, 0.92 * fade).fillCircle(at.x, at.y, coreR);
    a.lineStyle(1, 0xffffff, 0.5 * fade).strokeCircle(at.x, at.y, coreR + 0.5);
  }

  destroy() {
    this.core?.destroy();
    this.glow?.destroy();
    this.core = null;
    this.glow = null;
  }
}/**
 * OWNER: gameplay engineer.
 * Pooled one-shot effects drawn into a single Graphics: neon shards (crash explosion), sparks (landings, pickups) and
 * expanding rings. A fixed-size pool means no allocation per effect and nothing to leak on restart.
 */
import Phaser from 'phaser';
import { cosmeticRandom } from '../systems/CosmeticRandom.js';

const POOL = 160;

export class Fx {
  /**
   * @param {Phaser.Scene} scene
   * @param {Object<string,number>} palette
   */
  constructor(scene, palette) {
    // Crash shards and sparks: the run's visual/fx stream (repeatable per seed), never a gameplay stream.
    this.random = scene.runRandom?.visualFx || cosmeticRandom('visual/fx');
    this.scene = scene;
    this.palette = palette;
    this.gfx = scene.add.graphics().setDepth(30).setBlendMode(Phaser.BlendModes.ADD);
    this.items = [];
    for (let i = 0; i < POOL; i++) {
      this.items.push({ on: false, kind: 0, x: 0, y: 0, vx: 0, vy: 0, rot: 0, vr: 0, life: 0, max: 1, size: 1, color: 0xffffff, grav: 0 });
    }
    this.active = 0;
  }

  _take() {
    for (let i = 0; i < POOL; i++) {
      const it = this.items[i];
      if (!it.on) {
        it.on = true;
        this.active++;
        return it;
      }
    }
    return null;
  }

  /**
   * Explosion of neon triangles.
   * @param {number} x
   * @param {number} y
   * @param {number} vx inherited velocity px/s.
   * @param {number} vy
   * @param {number[]} colors
   * @param {number} [count=44]
   * @returns {void}
   */
  shards(x, y, vx, vy, colors, count = 44) {
    for (let i = 0; i < count; i++) {
      const it = this._take();
      if (!it) return;
      const a = this.random.next() * Math.PI * 2;
      const sp = 60 + this.random.next() * 260;
      it.kind = 1;
      it.x = x + (this.random.next() - 0.5) * 14;
      it.y = y + (this.random.next() - 0.5) * 14;
      it.vx = vx * 0.5 + Math.cos(a) * sp;
      it.vy = vy * 0.5 + Math.sin(a) * sp - 80;
      it.rot = this.random.next() * 6.28;
      it.vr = (this.random.next() - 0.5) * 18;
      it.life = it.max = 900 + this.random.next() * 700;
      it.size = 2.5 + this.random.next() * 5;
      it.color = colors[i % colors.length];
      it.grav = 650;
    }
  }

  /**
   * Radial sparks.
   * @param {number} x
   * @param {number} y
   * @param {number} color
   * @param {number} count
   * @param {number} speed px/s
   * @param {number} [upBias=0] extra upward velocity px/s
   * @returns {void}
   */
  sparks(x, y, color, count, speed, upBias = 0) {
    for (let i = 0; i < count; i++) {
      const it = this._take();
      if (!it) return;
      const a = this.random.next() * Math.PI * 2;
      const sp = speed * (0.3 + this.random.next() * 0.7);
      it.kind = 0;
      it.x = x;
      it.y = y;
      it.vx = Math.cos(a) * sp;
      it.vy = Math.sin(a) * sp - upBias;
      it.life = it.max = 250 + this.random.next() * 350;
      it.size = 1.5 + this.random.next() * 1.5;
      it.color = color;
      it.grav = 300;
    }
  }

  /**
   * Expanding ring.
   * @param {number} x
   * @param {number} y
   * @param {number} color
   * @param {number} r1 final radius
   * @param {number} [lifeMs=380]
   * @returns {void}
   */
  ring(x, y, color, r1, lifeMs = 380) {
    const it = this._take();
    if (!it) return;
    it.kind = 2;
    it.x = x;
    it.y = y;
    it.vx = it.vy = 0;
    it.life = it.max = lifeMs;
    it.size = r1;
    it.color = color;
    it.grav = 0;
  }

  /**
   * @param {number} dtMs
   * @param {(x:number)=>number} [groundY] surface height for shard bounce.
   * @returns {void}
   */
  update(dtMs, groundY) {
    const g = this.gfx;
    g.clear();
    if (this.active === 0) return;
    const dt = dtMs / 1000;
    for (let i = 0; i < POOL; i++) {
      const it = this.items[i];
      if (!it.on) continue;
      it.life -= dtMs;
      if (it.life <= 0) {
        it.on = false;
        this.active--;
        continue;
      }
      const t = it.life / it.max; // 1 -> 0
      if (it.kind === 2) {
        const r = it.size * (1 - t);
        g.lineStyle(2, it.color, 0.9 * t);
        g.strokeCircle(it.x, it.y, r);
        continue;
      }
      it.vy += it.grav * dt;
      it.x += it.vx * dt;
      it.y += it.vy * dt;
      if (groundY && it.kind === 1) {
        const gy = groundY(it.x);
        if (gy != null && it.y > gy - 1 && it.vy > 0) {
          it.y = gy - 1;
          it.vy *= -0.35;
          it.vx *= 0.75;
          it.vr *= 0.6;
        }
      }
      if (it.kind === 1) {
        it.rot += it.vr * dt;
        const s = it.size * (0.4 + 0.6 * t);
        const c = Math.cos(it.rot);
        const sn = Math.sin(it.rot);
        const pts = [
          { x: it.x + c * s, y: it.y + sn * s },
          { x: it.x + Math.cos(it.rot + 2.4) * s * 0.8, y: it.y + Math.sin(it.rot + 2.4) * s * 0.8 },
          { x: it.x + Math.cos(it.rot - 2.2) * s * 0.9, y: it.y + Math.sin(it.rot - 2.2) * s * 0.9 },
        ];
        g.fillStyle(it.color, 0.35 * Math.min(1, t * 2));
        g.fillPoints(pts, true);
        g.lineStyle(1, it.color, Math.min(1, t * 2));
        g.strokePoints(pts, true, true);
      } else {
        g.fillStyle(it.color, Math.min(1, t * 1.5));
        g.fillRect(it.x - it.size / 2, it.y - it.size / 2, it.size, it.size);
      }
    }
  }

  /** @returns {void} */
  destroy() {
    if (this.gfx) this.gfx.destroy();
    this.gfx = null;
    this.items.length = 0;
  }
}/** Visual-only replay ghost (issue #56): a translucent rider drawn from a tape's recorded
 * trace at the current simulation tick. No Matter body, no events, no score: it cannot touch
 * gameplay. Up to five per course (Latest, Best, Favorites), one per distinct run.
 */
import { FONT_KEY } from '../ui/PixelFont.js';
import { decodeTrace, tracePose } from '../systems/ghost/GhostTape.js';

export const GHOST_ALPHA = 0.42;
export const GHOST_DEPTH = 19; // just behind the live sled (20)
const ROLE_LABEL = { best: 'BEST', latest: 'LAST', fav0: 'FAV A', fav1: 'FAV B', fav2: 'FAV C' };
const ROLE_ORDER = ['best', 'latest', 'fav0', 'fav1', 'fav2'];

/** Tag text and colour key for a run holding `roles` (best wins, then latest, then favorites). */
export function ghostTag(roles) {
  const sorted = ROLE_ORDER.filter((r) => roles.includes(r));
  const lead = sorted[0] || 'latest';
  return { text: sorted.map((r) => ROLE_LABEL[r]).join('+'), color: lead === 'best' ? 'amber' : lead === 'latest' ? 'cyan' : 'magenta' };
}

export class GhostRider {
  /**
   * @param {Phaser.Scene} scene RunScene
   * @param {{tape:object, roles:string[]}} ghost
   * @param {Object<string,number>} palette
   */
  constructor(scene, ghost, palette) {
    this.scene = scene;
    this.runId = ghost.tape.runId;
    this.roles = ghost.roles;
    this.trace = decodeTrace(ghost.tape);
    const tag = ghostTag(ghost.roles);
    this.color = palette[tag.color] ?? 0xffffff;
    this.gfx = scene.add.graphics().setDepth(GHOST_DEPTH).setAlpha(GHOST_ALPHA);
    this.label = scene.add.bitmapText(0, 0, FONT_KEY, tag.text, 8).setOrigin(0.5, 1)
      .setTint(this.color).setDepth(GHOST_DEPTH).setAlpha(0.7);
    this.visible = false;
  }

  /** Draw the ghost at simulation tick `tick`; hidden past the end of its run. */
  update(tick) {
    const pose = tracePose(this.trace, tick);
    this.visible = Boolean(pose);
    this.gfx.clear().setVisible(this.visible);
    this.label.setVisible(this.visible);
    if (!pose) return;
    const c = Math.cos(pose.angle), s = Math.sin(pose.angle);
    // Same local frame as Sled._draw: the trace holds the physics body's centre, the drawing
    // origin sits at the body minus the rotated spawn offset.
    const off = this.scene.sled?.off || { x: 0, y: 0 };
    const ox = pose.x - (c * off.x - s * off.y), oy = pose.y - (s * off.x + c * off.y);
    const P = (lx, ly) => ({ x: ox + lx * c - ly * s, y: oy + lx * s + ly * c });
    const g = this.gfx;
    // Runner with its curved prow, and the deck
    const run = [P(-24, 11), P(18, 11), P(25, 9), P(29, 4)];
    g.lineStyle(2, this.color, 1).strokePoints(run, false, false);
    g.fillStyle(this.color, 0.55).fillPoints([P(-23, 1.5), P(21, 1.5), P(28, -1), P(22, 5.5), P(-23, 5.5)], true);
    // Rider: torso wedge and helmet
    g.fillStyle(this.color, 0.9).fillPoints([P(-8, 1), P(0, 1), P(1, -14), P(-5, -14)], true);
    const h = P(0, -20.5);
    g.fillCircle(h.x, h.y, 4.6);
    // Tag over the helmet. The run camera zooms out with speed: keep it at 1x pixel scale so it stays legible.
    const z = this.scene.cameras?.main?.zoom > 0 ? this.scene.cameras.main.zoom : 1;
    this.label.setScale(1 / z).setPosition(h.x, h.y - 6 - 4 / z);
  }

  destroy() {
    this.gfx?.destroy();
    this.label?.destroy();
    this.gfx = null;
    this.label = null;
  }
}/**
 * OWNER: gameplay (readable-chaos pass). World-space drawing of the ground-hazard telegraph planned by
 * systems/HazardTelegraph.js (pattern: entities/AirTelegraph.js). One instance per run. For each mark:
 *  - hazard cue would be clipped: a badge at the right screen edge, standing on the terrain line, with the hazard's glyph,
 *    marching chevrons pointing at what is coming, a response cue above it (hop = up-chevrons, brace = bars) and a
 *    proximity bar that fills as the hazard closes in. Several off-screen hazards stack upward (nearest lowest).
 *  - hazard cue fits: a faint vertical light column standing on the box with the same response cue on top.
 * Colour is the response (mark.color): danger = hop, amber = brace, lime = hop NOW. Shape repeats it (colour-blind safe):
 * the hop cue is open up-chevrons, the hop-now cue a filled up-arrow, the brace cue two flat bars.
 * Dim (and silent, see TelegraphTracker): a hazard the sled is flying over (state 'clear') and a Gear Gate that will be
 * open when the sled gets there (state 'open'; its glyph is drawn without the bar across it).
 * All sizes are game px (GAME_WIDTH x GAME_HEIGHT = 480 x 270, shown 2x) divided by the camera zoom, so the marker is the
 * same size on screen at every zoom.
 * Pure drawing: no physics, no score, no state that outlives a frame. Does not import Phaser (uses scene.add.graphics()).
 */
import { hazardDrawKind } from '../systems/BiomeEffects.js';

/** Badge centre this many game px in from the right screen edge. */
export const EDGE_INSET_PX = 26;
/** At most this many badges are stacked at the edge. */
export const EDGE_MAX_STACK = 3;
const BADGE_HALF_PX = 13;
const STACK_STEP_PX = 31;
const COLUMN_PX = 130;
/** The response cue is drawn at this scale of its design size. */
const CUE_SCALE = 0.75;
const GO_CUE_HALF_PX = 14;
const CUE_STROKE_PX = 3;

/** Read the drawn polyline only. A camera-driven heightAt call could stream terrain ahead of the next sim tick. */
function edgeTerrainY(chunks, x) {
  for (const chunk of chunks || []) {
    if (!(x >= chunk.startX && x <= chunk.endX)) continue;
    const points = chunk.points;
    if (!points || points.length < 2 || x < points[0].x || x > points[points.length - 1].x) return NaN;
    let lo = 0, hi = points.length - 1;
    while (hi - lo > 1) {
      const mid = (hi + lo) >> 1;
      if (points[mid].x <= x) lo = mid; else hi = mid;
    }
    const a = points[lo], b = points[hi];
    return b.x > a.x ? a.y + (b.y - a.y) * (x - a.x) / (b.x - a.x) : NaN;
  }
  return NaN;
}

export class GroundTelegraph {
  /**
   * @param {{add:{graphics:Function}}} scene
   * @param {Object<string,number>} palette
   */
  constructor(scene, palette) {
    this.scene = scene;
    this.palette = palette;
    this.gfx = scene.add.graphics().setDepth(9);
  }

  /**
   * @param {number} timeMs run time (drives the pulse).
   * @param {import('../systems/HazardTelegraph.js').TelegraphMark[]} marks nearest first.
   * @param {{left:number,right:number,top:number,bottom:number}} view visible world rect.
   * @param {number} zoom camera zoom.
   * @param {import('../data/schemas.js').TerrainChunk[]} activeChunks already-streamed terrain, read only.
   * @returns {void}
   */
  update(timeMs, marks, view, zoom, activeChunks) {
    const g = this.gfx;
    if (!g) return;
    g.clear();
    if (!marks || !marks.length || !view) return;
    const k = 1 / (zoom || 1);
    const cueK = k * CUE_SCALE;
    // Allow the full largest pulse plus outline so the cue doesn't switch layouts every time it pulses.
    const half = (GO_CUE_HALF_PX + CUE_STROKE_PX / 2) * cueK;
    const height = (1.5 * GO_CUE_HALF_PX + CUE_STROKE_PX / 2) * cueK;
    const badges = [];
    for (const m of marks) {
      const h = m.ref;
      const base = h.cy - h.h / 2 - 3 * k;
      const top = Math.min(base - 30 * k, Math.max(base - COLUMN_PX * k, view.top + 30 * k));
      const cue = top - 4 * k;
      if (h.cx - half >= view.left && h.cx + half <= view.right &&
          cue - height >= view.top && cue + CUE_STROKE_PX / 2 * cueK <= view.bottom) {
        this._column(g, timeMs, m, k, base, top);
      } else badges.push(m);
    }
    // Only the first badge has a response glyph. Don't let an earlier warning hide the nearest clipped hop-now cue.
    const go = badges.findIndex((m) => m.state === 'go');
    if (go > 0) badges.unshift(...badges.splice(go, 1));
    for (let slot = 0; slot < Math.min(badges.length, EDGE_MAX_STACK); slot++) {
      this._edge(g, timeMs, badges[slot], k, view, activeChunks, slot);
    }
  }

  /** Light column on an on-screen hazard. */
  _column(g, t, m, k, y0, y1) {
    const col = this.palette[m.color];
    const go = m.state === 'go';
    const dim = m.clear || m.state === 'open' ? 0.3 : 1;
    const x = m.ref.cx;
    const pulse = 0.5 + 0.5 * Math.sin(t / (go ? 45 : 150 - 70 * m.urgency));
    // fades once the box is close enough to read on its own, unless it is time to hop
    const near = go ? 1 : 1 - 0.55 * Math.max(0, (m.urgency - 0.6) / 0.4);
    g.lineStyle((go ? 16 : 11) * k, col, (go ? 0.24 : 0.13 + 0.08 * pulse) * near * dim);
    g.lineBetween(x, y0, x, y1);
    g.lineStyle(2 * k, col, (go ? 0.95 : 0.5 + 0.25 * pulse) * near * dim);
    g.lineBetween(x, y0, x, y1);
    this._cue(g, t, m, x, y1 - 4 * k, k * CUE_SCALE, col, dim * (go ? 1 : 0.55 + 0.45 * near));
  }

  /** Badge at the right screen edge for an off-screen hazard. */
  _edge(g, t, m, k, view, activeChunks, slot) {
    const col = this.palette[m.color];
    const dim = m.clear || m.state === 'open' ? 0.3 : 1;
    const x = view.right - EDGE_INSET_PX * k;
    let ground = edgeTerrainY(activeChunks, x);
    if (!Number.isFinite(ground)) ground = (view.top + view.bottom) / 2;
    // not under the HUD's bottom row (seed / daily rule, bottom right) when the terrain line is below the view
    ground = Math.min(Math.max(ground, view.top + 100 * k), view.bottom - 30 * k);
    const b = BADGE_HALF_PX * k;
    const y = ground - (24 + slot * STACK_STEP_PX) * k;
    const pulse = 0.5 + 0.5 * Math.sin(t / (150 - 80 * m.urgency));
    // stem to the terrain line (first badge only) and the badge
    if (slot === 0) {
      g.lineStyle(1.5 * k, col, 0.7 * dim);
      g.lineBetween(x, ground, x, y + b);
    }
    g.fillStyle(this.palette.bg, 0.82 * dim);
    g.fillRect(x - b, y - b, 2 * b, 2 * b);
    g.lineStyle((1.5 + 0.8 * pulse) * k, col, (0.75 + 0.25 * pulse) * dim);
    g.strokeRect(x - b, y - b, 2 * b, 2 * b);
    this._glyph(g, m.ref, x, y, 7.5 * k, k, col, dim, m);
    // proximity bar under the glyph: fills as the hazard closes in
    g.fillStyle(col, 0.9 * dim);
    g.fillRect(x - b + 1.5 * k, y + b - 3 * k, (2 * b - 3 * k) * m.urgency, 1.5 * k);
    // marching chevrons toward the screen edge: "it comes from there"
    const step = m.clear || m.state === 'open' ? 0 : Math.floor(t / 110) % 3;
    for (let i = 0; i < 2; i++) {
      const cx = x + b + (3 + i * 4.5) * k;
      const lit = step === i + 1;
      g.lineStyle((lit ? 2 : 1.5) * k, col, (lit ? 1 : 0.55) * dim);
      g.lineBetween(cx, y - 4 * k, cx + 3 * k, y);
      g.lineBetween(cx, y + 4 * k, cx + 3 * k, y);
    }
    if (slot === 0) this._cue(g, t, m, x, y - b - 4 * k, k * CUE_SCALE, col, dim);
  }

  /** Response cue with its tip at (x, y): hop = two open up-chevrons, hop now = filled up-arrow, brace = two bars. */
  _cue(g, t, m, x, y, k, col, a) {
    if (m.kind === 'brace') {
      g.lineStyle(3 * k, col, 0.9 * a);
      g.lineBetween(x - 8 * k, y - 4 * k, x + 8 * k, y - 4 * k);
      g.lineBetween(x - 8 * k, y - 11 * k, x + 8 * k, y - 11 * k);
      return;
    }
    if (m.state === 'go') {
      const s = (GO_CUE_HALF_PX - 3 + 3 * (Math.floor(t / 60) % 2)) * k;
      g.fillStyle(col, a);
      g.fillTriangle(x - s, y, x + s, y, x, y - 1.5 * s);
      g.lineStyle(CUE_STROKE_PX * k, this.palette.text, 0.9 * a);
      g.lineBetween(x - s, y, x, y - 1.5 * s);
      g.lineBetween(x + s, y, x, y - 1.5 * s);
      return;
    }
    const bob = m.clear ? 0 : (Math.floor(t / 130) % 2) * 2 * k;
    for (let i = 0; i < 2; i++) {
      const cy = y - i * 8 * k - bob;
      g.lineStyle(3 * k, col, (i === 0 ? 1 : 0.7) * a);
      g.lineBetween(x - 9 * k, cy, x, cy - 8 * k);
      g.lineBetween(x + 9 * k, cy, x, cy - 8 * k);
    }
  }

  /** The hazard's silhouette, simplified, centred at (x, y) with half-size s. m (optional): the mark (gate open/closed). */
  _glyph(g, h, x, y, s, k, col, a, m) {
    const kind = hazardDrawKind(h.def);
    g.lineStyle(1.5 * k, col, a);
    if (kind === 'spike') {
      for (let i = -1; i <= 1; i++) {
        const x0 = x + i * s * 0.66;
        const top = y - (i === 0 ? s : s * 0.6);
        g.lineBetween(x0 - s * 0.33, y + s * 0.7, x0, top);
        g.lineBetween(x0 + s * 0.33, y + s * 0.7, x0, top);
      }
      g.lineBetween(x - s, y + s * 0.7, x + s, y + s * 0.7);
    } else if (kind === 'chasm') {
      // ground line torn open by a jagged rift
      g.lineBetween(x - s, y - s * 0.5, x - s * 0.55, y - s * 0.5);
      g.lineBetween(x + s * 0.55, y - s * 0.5, x + s, y - s * 0.5);
      g.lineBetween(x - s * 0.55, y - s * 0.5, x - s * 0.2, y);
      g.lineBetween(x - s * 0.2, y, x - s * 0.45, y + s * 0.3);
      g.lineBetween(x - s * 0.45, y + s * 0.3, x, y + s * 0.8);
      g.lineBetween(x, y + s * 0.8, x + s * 0.45, y + s * 0.3);
      g.lineBetween(x + s * 0.45, y + s * 0.3, x + s * 0.2, y);
      g.lineBetween(x + s * 0.2, y, x + s * 0.55, y - s * 0.5);
    } else if (kind === 'firewall') {
      g.lineBetween(x - s * 0.4, y + s * 0.7, x - s * 0.4, y - s * 0.5);
      g.lineBetween(x + s * 0.4, y + s * 0.7, x + s * 0.4, y - s * 0.5);
      g.lineBetween(x - s * 0.4, y - s * 0.5, x, y - s);
      g.lineBetween(x + s * 0.4, y - s * 0.5, x, y - s);
      g.lineBetween(x - s * 0.4, y + s * 0.1, x + s * 0.4, y + s * 0.1);
    } else if (kind === 'vent') {
      g.lineBetween(x - s, y + s * 0.7, x + s, y + s * 0.7);
      g.lineBetween(x - s, y + s * 0.7, x - s * 0.7, y + s * 0.2);
      g.lineBetween(x + s, y + s * 0.7, x + s * 0.7, y + s * 0.2);
      g.lineBetween(x - s * 0.7, y + s * 0.2, x + s * 0.7, y + s * 0.2);
      g.fillStyle(col, a);
      g.fillRect(x - s * 0.5, y - s * 0.35, 1.5 * k, 1.5 * k);
      g.fillRect(x + s * 0.2, y - s * 0.7, 1.5 * k, 1.5 * k);
      g.fillRect(x - s * 0.05, y - s * 1.0, 1.5 * k, 1.5 * k);
    } else if (kind === 'seaweed') {
      for (let i = -1; i <= 1; i++) {
        g.lineBetween(x + i * s * 0.6, y + s * 0.7, x + i * s * 0.6 + s * 0.25, y);
        g.lineBetween(x + i * s * 0.6 + s * 0.25, y, x + i * s * 0.6, y - s * (i === 0 ? 1 : 0.7));
      }
    } else if (kind === 'chocoRiver') {
      g.lineBetween(x - s, y + s * 0.5, x + s, y + s * 0.5);
      g.lineBetween(x - s, y, x - s * 0.3, y - s * 0.3);
      g.lineBetween(x - s * 0.3, y - s * 0.3, x + s * 0.3, y);
      g.lineBetween(x + s * 0.3, y, x + s, y - s * 0.3);
    } else if (kind === 'groomer') {
      g.lineBetween(x - s, y + s * 0.7, x + s, y + s * 0.7);
      g.lineBetween(x - s * 0.7, y + s * 0.7, x - s * 0.7, y - s * 0.1);
      g.lineBetween(x - s * 0.7, y - s * 0.1, x + s * 0.8, y - s * 0.1);
      g.lineBetween(x + s * 0.8, y - s * 0.1, x + s * 0.8, y + s * 0.7);
      g.lineBetween(x, y - s * 0.1, x, y - s * 0.8);
      g.lineBetween(x, y - s * 0.8, x + s * 0.8, y - s * 0.8);
      g.lineBetween(x + s * 0.8, y - s * 0.8, x + s * 0.8, y - s * 0.1);
    } else if (kind === 'boulder' || kind === 'dewDrop') {
      // a ball on the ground line, with a motion streak (no direction implied: both sides)
      const r = kind === 'boulder' ? s * 0.7 : s * 0.55;
      g.strokeCircle(x, y + s * 0.7 - r, r);
      g.lineBetween(x - s, y + s * 0.7, x + s, y + s * 0.7);
    } else if (kind === 'gearGate') {
      // two posts; a bar across them while the gate will be closed
      g.lineBetween(x - s * 0.6, y + s * 0.7, x - s * 0.6, y - s * 0.8);
      g.lineBetween(x + s * 0.6, y + s * 0.7, x + s * 0.6, y - s * 0.8);
      g.strokeCircle(x, y - s * 0.8, s * 0.3);
      if (!m || m.state !== 'open') g.lineBetween(x - s * 0.6, y, x + s * 0.6, y);
    } else if (kind === 'shatterWall') {
      // a crystal pane with a crack
      g.strokeRect(x - s * 0.5, y - s, s, s * 1.7);
      g.lineBetween(x - s * 0.2, y - s, x + s * 0.1, y - s * 0.2);
      g.lineBetween(x + s * 0.1, y - s * 0.2, x - s * 0.15, y + s * 0.7);
    } else {
      g.fillStyle(col, 0.5 * a);
      g.fillRect(x - s * 0.7, y - s * 0.7, s * 1.4, s * 1.4);
    }
  }

  /** @param {Object<string,number>} palette @returns {void} */
  setPalette(palette) {
    this.palette = palette;
  }

  /** @returns {void} */
  destroy() {
    if (this.gfx) this.gfx.destroy();
    this.gfx = null;
  }
}/**
 * OWNER: gameplay engineer.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * One hazard instance built from a HazardDef + HazardSpawn. Sensor body; draws shape from def.shapeKey
 * ('chasm' | 'firewall' | 'spike' | 'vent' | 'drone'; B1: 'groomer' | 'seagull' | 'seaweed' | 'chocoRiver'; B2: 'shatterWall' | 'ashCloud'; B3: 'boulder' | 'dewDrop' | 'gearGate'; B4: 'meteor' | 'gustFront'; any other key draws the generic box, BiomeEffects.hazardDrawKind). Silhouettes fill their hit-box so the danger is always legible
 * (design doc pillar 2); faint corner brackets mark the exact hit-box.
 */
import Phaser from 'phaser';
import { CAT } from './Sled.js';
import { hazardColor, hazardDrawKind, gustImpulse } from '../systems/BiomeEffects.js';
import { emptyRollState, rollStep, rollParams, rollPredictX, gateOpenAt, gateNextChangeMs } from '../systems/HazardMotion.js';
import pmath from '../systems/pmath.js';

const Matter = Phaser.Physics.Matter.Matter;
const { Bodies, Body } = Matter;
const DEG = Math.PI / 180;

/** Tiny deterministic hash -> [0,1). */
function hash01(n) {
  const s = pmath.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

export class Hazard {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('../data/schemas.js').HazardDef} def
   * @param {import('../data/schemas.js').HazardSpawn} spawn
   * @param {Object<string,number>} palette
   */
  constructor(scene, def, spawn, palette) {
    this.scene = scene;
    this.world = scene.matter.world;
    this.def = def;
    this.spawn = spawn;
    this.palette = palette;
    this.hit = false;
    this.destroyed = false;
    // BiomeEffects.hazardColorKey: a biome crash hazard is always `danger` (spec §4); base defs keep their colorKey
    this.color = hazardColor(def, palette);
    /** Drawing routine: the def's shapeKey when known, else 'generic' (a biome def with a new shapeKey still draws). */
    this.drawKind = hazardDrawKind(def);
    const w = (def.size && def.size.w) || 24;
    const h = (def.size && def.size.h) || 24;
    this.w = w;
    this.h = h;
    const rot = (spawn.rotationDeg || 0) * DEG;
    const air = def.placement === 'air';
    // crash hit-boxes are a little smaller than the drawn brackets (forgiving: a normal hop clears a spike)
    const crashy = !def.onHit || def.onHit.effect === 'crash';
    const bw = crashy ? w * 0.72 : w;
    const bh = crashy ? h * 0.8 : h;
    this._crashy = crashy;
    const { cx, cy, bcx, bcy } = this._boxAt(spawn.x, spawn.y, rot);
    this.cx = cx;
    this.cy = cy;
    this.body = Bodies.rectangle(bcx, bcy, bw, bh, {
      isStatic: true,
      isSensor: true,
      angle: rot,
      label: 'hazard',
      collisionFilter: { group: 0, category: CAT.SENSOR, mask: CAT.SLED },
    });
    this.body.bbHazard = this;
    this.world.add(this.body);
    this.gfx = scene.add.graphics({ x: air ? spawn.x : spawn.x, y: air ? spawn.y + h / 2 : spawn.y }).setDepth(8);
    this.gfx.setRotation(rot);
    this.seed = spawn.x * 0.013 + spawn.y * 0.007;
    /**
     * B3 motion (HazardDef.motion, systems/HazardMotion.js). `roll`: this.roll is the RollState, the entity (cx, cy, body,
     * gfx) follows the ground at x0 + offset, `spin` turns the drawing, `rolling` is true while it moves. `gate`: `open`
     * follows gateOpenAt(motion, spawn.phase, run time). Stepped in update(), on or off camera.
     */
    this.motion = def.motion && (def.motion.kind === 'roll' || def.motion.kind === 'gate') ? def.motion : null;
    this.x0 = spawn.x;
    this.phase = Number.isFinite(spawn.phase) ? spawn.phase : 0;
    this.roll = emptyRollState();
    this.rolling = false;
    this.rollDir = this.motion && this.motion.kind === 'roll' ? rollParams(this.motion).dir : 0;
    this.spin = 0;
    this.open = this.motion && this.motion.kind === 'gate' ? gateOpenAt(this.motion, this.phase, 0) : false;
    /** Set by RunScene when an air hazard is about to enter view: faster pulse + a wider warning glow. */
    this.alert = false;
    this._lastDraw = -1e9;
    this.draw(0);
  }

  /**
   * Animate (cheap: only redraw ~15 Hz and only when near the camera).
   * @param {number} timeMs
   * @param {number} camLeft
   * @param {number} camRight
   * @returns {void}
   */
  update(timeMs, camLeft, camRight) {
    if (this.destroyed) return;
    // RunScene advances motion in its fixed simulation tick (simStepped); stand-alone callers still step here.
    if (this.motion && !this.simStepped) this.stepMotion(timeMs);
    const vis = this.cx > camLeft - 80 && this.cx < camRight + 80;
    this.gfx.setVisible(vis);
    if (!vis) return;
    if (timeMs - this._lastDraw < 66) return;
    this.draw(timeMs);
  }

  /**
   * Centre of the drawn box and of the (smaller, ground-anchored) crash hit-box for a ground point (x, y) and rotation.
   * Ground hazards sit on the surface (up vector rotated with the ground); 'air' floats at y. Pure geometry.
   * @param {number} x @param {number} y @param {number} rot radians
   * @returns {{cx:number, cy:number, bcx:number, bcy:number}}
   */
  _boxAt(x, y, rot) {
    const air = this.def.placement === 'air';
    const h = this.h;
    const cx = air ? x : x + pmath.sin(rot) * (h / 2);
    const cy = air ? y : y - pmath.cos(rot) * (h / 2);
    const bh = this._crashy ? h * 0.8 : h;
    const bcy = this._crashy && !air ? cy + (h - bh) / 2 * pmath.cos(rot) : cy;
    const bcx = this._crashy && !air ? cx - (h - bh) / 2 * pmath.sin(rot) : cx;
    return { cx, cy, bcx, bcy };
  }

  /**
   * B3: advance this hazard's motion to run time `timeMs` (HazardMotion). A roll starts when the sled comes within
   * ROLL_ACTIVATE_PX and then moves the sensor body, the drawing and cx / cy along the ground (scene.heightFn and
   * terrain.slopeDegAt: the same surface the sled rides). A gate updates `open` (redrawn at once when it flips).
   * @param {number} timeMs run time
   * @param {number} [sledX] defaults to scene.sled.x
   * @returns {void}
   */
  stepMotion(timeMs, sledX) {
    const m = this.motion;
    if (!m || this.destroyed) return;
    if (m.kind === 'gate') {
      const o = gateOpenAt(m, this.phase, timeMs);
      if (o !== this.open) { this.open = o; this._lastDraw = -1e9; }
      return;
    }
    const sx = Number.isFinite(sledX) ? sledX : (this.scene.sled && Number.isFinite(this.scene.sled.x) ? this.scene.sled.x : -Infinity);
    const before = this.roll.offsetPx;
    this.roll = rollStep(this.roll, m, this.x0, sx, timeMs, this._slopeFn());
    const off = this.roll.offsetPx;
    this.rolling = this.roll.activeAtMs !== null && Math.abs(off) < rollParams(m).rangePx;
    if (off === before) return;
    const x = this.x0 + off;
    const hf = this.scene.heightFn || (this.scene.terrain && this.scene.terrain.heightAt ? (q) => this.scene.terrain.heightAt(q) : null);
    const y = hf ? hf(x) : this.spawn.y;
    const slope = this.scene.terrain && this.scene.terrain.slopeDegAt ? this.scene.terrain.slopeDegAt(x) : this.spawn.rotationDeg || 0;
    const rot = (Number.isFinite(slope) ? slope : 0) * DEG;
    const b = this._boxAt(x, y, rot);
    this.cx = b.cx;
    this.cy = b.cy;
    Body.setPosition(this.body, { x: b.bcx, y: b.bcy });
    Body.setAngle(this.body, rot);
    if (this.gfx) { this.gfx.setPosition(x, y); this.gfx.setRotation(rot); }
    this.spin = off / Math.max(4, Math.min(this.w, this.h) / 2); // rolling downhill (+x) turns it clockwise
  }

  /** B3 tuning: the ground slope (deg) a roll reads, x -> terrain.slopeDegAt (the surface it rides); null = flat. */
  _slopeFn() {
    const t = this.scene && this.scene.terrain;
    return t && typeof t.slopeDegAt === 'function' ? (x) => t.slopeDegAt(x) : null;
  }

  /**
   * B3: can the sled pass through this hazard at run time tMs without a hit? True only for an open Gear Gate.
   * @param {number} tMs @returns {boolean}
   */
  isPassable(tMs) {
    return !!(this.motion && this.motion.kind === 'gate' && gateOpenAt(this.motion, this.phase, tMs));
  }

  /**
   * B3, for a telegraph: the hazard's x at a later run time (a roll that has not started waits at its spawn x, then rolls
   * downhill on the ground it rides; anything else stays put), and ms until a gate next opens or closes (null for
   * anything but a gate). A roll's current signed x speed is `this.roll.vPxS` (closing speed = sled speed - vPxS, which
   * is negative while a roll catches a slower sled up).
   * @param {number} tMs @returns {number}
   */
  predictX(tMs) {
    return this.motion && this.motion.kind === 'roll' ? rollPredictX(this.roll, this.motion, this.x0, tMs, this._slopeFn()) : this.x0;
  }

  /** @param {number} tMs @returns {number|null} */
  gateNextChangeMs(tMs) {
    return this.motion && this.motion.kind === 'gate' ? gateNextChangeMs(this.motion, this.phase, tMs) : null;
  }

  /** @param {number} t time ms. @returns {void} */
  draw(t) {
    this._lastDraw = t;
    const g = this.gfx;
    g.clear();
    const col = this.color;
    const pal = this.palette;
    const w = this.w;
    const h = this.h;
    const frame = Math.floor(t / 66);

    if (this.drawKind === 'drone') {
      this._drone(g, t, frame, col, pal);
      return;
    }
    if (this.drawKind === 'seagull') {
      this._seagull(g, t, frame, col, pal);
      return;
    }
    if (this.drawKind === 'meteor') {
      this._meteor(g, t, frame, col, pal);
      return;
    }

    // hit-box corner brackets (the drawn box; crash hit-boxes are ~25% smaller)
    g.lineStyle(1, col, 0.5);
    const hw = w / 2;
    const b = 4;
    for (const sxn of [-1, 1]) {
      for (const [y0, syn] of [[0, 1], [-h, -1]]) {
        const x = sxn * hw;
        g.lineBetween(x, y0, x - sxn * b, y0);
        g.lineBetween(x, y0, x, y0 + (y0 === 0 ? -b : b));
        void syn;
      }
    }

    switch (this.drawKind) {
      case 'chasm': this._chasm(g, t, frame, col, pal); break;
      case 'firewall': this._firewall(g, t, frame, col, pal); break;
      case 'spike': this._spike(g, t, frame, col, pal); break;
      case 'vent': this._vent(g, t, frame, col, pal); break;
      case 'groomer': this._groomer(g, t, frame, col, pal); break;
      case 'seaweed': this._seaweed(g, t, frame, col, pal); break;
      case 'chocoRiver': this._chocoRiver(g, t, frame, col, pal); break;
      case 'shatterWall': this._shatterWall(g, t, frame, col, pal); break;
      case 'ashCloud': this._ashCloud(g, t, frame, col, pal); break;
      case 'boulder': this._boulder(g, t, frame, col, pal); break;
      case 'dewDrop': this._dewDrop(g, t, frame, col, pal); break;
      case 'gearGate': this._gearGate(g, t, frame, col, pal); break;
      case 'gustFront': this._gustFront(g, t, frame, col, pal); break;
      default: this._generic(g, col); break;
    }
  }

  _generic(g, col) {
    g.fillStyle(col, 0.3);
    g.fillRect(-this.w / 2, -this.h, this.w, this.h);
    g.lineStyle(1.5, col, 1);
    g.strokeRect(-this.w / 2, -this.h, this.w, this.h);
  }

  // Glitch Chasm: a torn, dark data-rift with displaced scan slices
  _chasm(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    g.fillStyle(pal.bg, 1);
    g.fillRect(-w / 2, -h, w, h);
    const slices = 8;
    const sh = h / slices;
    for (let i = 0; i < slices; i++) {
      const r = hash01(this.seed + i * 3.1 + Math.floor(frame / 2) * 0.37);
      const off = (r - 0.5) * 10;
      const sw = w * (0.55 + 0.45 * hash01(i + this.seed));
      g.fillStyle(col, 0.22 + 0.25 * r);
      g.fillRect(-sw / 2 + off, -h + i * sh + 1, sw, sh - 2);
      g.lineStyle(1.5, col, 1);
      g.lineBetween(-sw / 2 + off, -h + i * sh + 1, sw / 2 + off, -h + i * sh + 1);
    }
    // jagged tear outline
    g.lineStyle(2, col, 1);
    g.strokePoints([
      { x: -w / 2, y: 0 }, { x: -w / 2 + 6, y: -h * 0.3 }, { x: -w / 2 - 2, y: -h * 0.55 },
      { x: -w / 2 + 8, y: -h * 0.8 }, { x: -w * 0.25, y: -h }, { x: w * 0.25, y: -h },
      { x: w / 2 - 8, y: -h * 0.8 }, { x: w / 2 + 2, y: -h * 0.55 }, { x: w / 2 - 6, y: -h * 0.3 }, { x: w / 2, y: 0 },
    ], false, false);
    // chromatic ghost
    g.lineStyle(1, pal.cyan, 0.6);
    g.strokeRect(-w / 2 + 3 * pmath.sin(t / 90), -h, w, h);
  }

  // Overflow Firewall: wall of amber flame bars
  _firewall(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    g.fillStyle(pal.bg, 0.9);
    g.fillRect(-w / 2, -h, w, h);
    const n = 6;
    for (let i = 0; i < n; i++) {
      const y = -h + (i * h) / n;
      const flick = hash01(this.seed + i + frame * 0.91);
      const inset = 1 + flick * 3;
      g.fillStyle(col, 0.25 + 0.5 * (1 - i / n) * flick + 0.15);
      g.fillRect(-w / 2 + inset, y + 1, w - inset * 2, h / n - 2);
    }
    // flame tongue top
    const tipH = 6 + 6 * hash01(frame * 0.7 + this.seed);
    g.fillStyle(col, 0.9);
    g.fillTriangle(-w / 2, -h, 0, -h - tipH, w / 2, -h);
    g.lineStyle(2, col, 1);
    g.strokeRect(-w / 2, -h, w, h);
    g.lineStyle(1, pal.text, 0.7);
    g.lineBetween(0, -h + 2, 0, -2);
  }

  // Packet Spike: three red spikes
  _spike(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const n = 3;
    const sw = w / n;
    for (let i = 0; i < n; i++) {
      const x0 = -w / 2 + i * sw;
      const th = h * (i === 1 ? 1 : 0.78);
      g.fillStyle(col, 0.4);
      g.fillTriangle(x0, 0, x0 + sw / 2, -th, x0 + sw, 0);
      g.lineStyle(2, col, 1);
      g.strokeTriangle(x0, 0, x0 + sw / 2, -th, x0 + sw, 0);
      g.fillStyle(pal.text, 0.9);
      g.fillCircle(x0 + sw / 2, -th + 1.5, 1.4);
    }
    // base plate
    g.lineStyle(2, col, 1);
    g.lineBetween(-w / 2 - 3, 0, w / 2 + 3, 0);
  }

  // Rogue Packet: a hovering hostile data drone. Hull is a bright-cored diamond with pulsing rings and two flickering
  // rotor bars so it reads against the sky at speed; the drawing bobs (visual only, the hit-box stays put).
  _drone(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const bob = pmath.sin(t / 260 + this.seed) * 2.5;
    const pulse = 0.5 + 0.5 * pmath.sin(t / (this.alert ? 90 : 190) + this.seed);
    const cy = -h / 2 + bob;
    // soft halo (additive-looking stacked discs) plus an alert ring that tightens
    g.fillStyle(col, 0.1 + 0.1 * pulse);
    g.fillEllipse(0, cy, w + 22 + 8 * pulse, h + 18 + 6 * pulse);
    g.fillStyle(col, 0.12 + 0.1 * pulse);
    g.fillEllipse(0, cy, w + 8, h + 6);
    if (this.alert) {
      g.lineStyle(1, pal.text, 0.35 + 0.4 * pulse);
      g.strokeEllipse(0, cy, w + 30 - 10 * pulse, h + 24 - 8 * pulse);
    }
    // rotor bars (flicker between two lengths)
    const rl = frame % 2 === 0 ? w * 0.62 : w * 0.46;
    g.lineStyle(2, col, 0.95);
    g.lineBetween(-rl, cy - h * 0.38, rl, cy - h * 0.38);
    g.lineBetween(-rl * 0.8, cy + h * 0.38, rl * 0.8, cy + h * 0.38);
    // hull: diamond with notched sides
    const hull = [
      { x: -w / 2, y: cy }, { x: -w * 0.22, y: cy - h * 0.42 }, { x: w * 0.22, y: cy - h * 0.42 },
      { x: w / 2, y: cy }, { x: w * 0.22, y: cy + h * 0.42 }, { x: -w * 0.22, y: cy + h * 0.42 },
    ];
    g.fillStyle(pal.bg, 0.95);
    g.fillPoints(hull, true);
    g.fillStyle(col, 0.3);
    g.fillPoints(hull, true);
    g.lineStyle(2, col, 1);
    g.strokePoints(hull, true, true);
    // packet "header" stripes
    g.lineStyle(1, col, 0.8);
    g.lineBetween(-w * 0.3, cy - 3, w * 0.3, cy - 3);
    g.lineBetween(-w * 0.3, cy + 4, w * 0.3, cy + 4);
    // hostile eye: white-hot core
    g.fillStyle(pal.text, 0.95);
    g.fillCircle(0, cy, 3.5 + 1.5 * pulse);
    g.fillStyle(col, 1);
    g.fillCircle(0, cy, 1.8);
    // side spikes pointing outward
    g.fillStyle(col, 1);
    g.fillTriangle(-w / 2 - 6, cy, -w / 2 + 1, cy - 4, -w / 2 + 1, cy + 4);
    g.fillTriangle(w / 2 + 6, cy, w / 2 - 1, cy - 4, w / 2 - 1, cy + 4);
  }

  // Garbage-Data Vent: grate + rising junk glyphs
  _vent(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const baseH = 8;
    g.fillStyle(col, 0.35);
    g.fillPoints([{ x: -w / 2, y: 0 }, { x: -w / 2 + 3, y: -baseH }, { x: w / 2 - 3, y: -baseH }, { x: w / 2, y: 0 }], true);
    g.lineStyle(2, col, 1);
    g.strokePoints([{ x: -w / 2, y: 0 }, { x: -w / 2 + 3, y: -baseH }, { x: w / 2 - 3, y: -baseH }, { x: w / 2, y: 0 }], true, true);
    g.lineStyle(1, pal.bg, 1);
    for (let i = -2; i <= 2; i++) g.lineBetween(i * 5, -1, i * 5, -baseH + 1);
    // junk glyphs rising (deterministic from time)
    for (let i = 0; i < 9; i++) {
      const ph = ((t / 900 + i * 0.137 + hash01(this.seed + i)) % 1);
      const gx = (hash01(i * 7.7 + this.seed) - 0.5) * (w - 4) + pmath.sin(ph * 9 + i) * 3;
      const gy = -baseH - ph * (h - baseH);
      const s = 1.5 + 2.5 * (1 - ph);
      g.fillStyle(i % 3 === 0 ? pal.cyan : col, 1 - ph * 0.8);
      g.fillRect(gx - s / 2, gy - s / 2, s, s);
    }
  }

  // B1 Debutmont: Groomer Cat, a little tracked snow groomer facing the sled, its blade out front (left) and a puffing stack
  _groomer(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const trackH = Math.max(5, h * 0.3);
    // track: dark belt with three road wheels that turn with time
    g.fillStyle(pal.bg, 0.95);
    g.fillRect(-w / 2 + 3, -trackH, w - 4, trackH);
    g.lineStyle(1.5, col, 1);
    g.strokeRect(-w / 2 + 3, -trackH, w - 4, trackH);
    for (let i = 0; i < 3; i++) {
      const wx = -w / 2 + 6 + i * ((w - 10) / 2);
      g.fillStyle(col, 0.8);
      g.fillCircle(wx, -trackH / 2, trackH * 0.32);
      g.fillStyle(pal.bg, 1);
      g.fillCircle(wx + pmath.cos(t / 120 + i) * 1.2, -trackH / 2 + pmath.sin(t / 120 + i) * 1.2, 0.8);
    }
    // body and cab
    const bodyTop = -h * 0.62;
    g.fillStyle(col, 0.35);
    g.fillRect(-w / 2 + 5, bodyTop, w - 8, -trackH - bodyTop);
    g.lineStyle(1.5, col, 1);
    g.strokeRect(-w / 2 + 5, bodyTop, w - 8, -trackH - bodyTop);
    g.fillStyle(col, 0.55);
    g.fillRect(-2, -h, w / 2 - 2, h + bodyTop);
    g.fillStyle(pal.text, 0.8);
    g.fillRect(0, -h + 2, w / 2 - 6, (h + bodyTop) * 0.5); // cab window
    // front blade (a wedge on the uphill side)
    g.fillStyle(col, 0.9);
    g.fillTriangle(-w / 2, 0, -w / 2 + 4, -h * 0.55, -w / 2 + 4, 0);
    // exhaust puff rising from the stack
    const ph = (t / 700) % 1;
    g.fillStyle(pal.text, 0.5 * (1 - ph));
    g.fillCircle(w / 2 - 4 + ph * 3, -h - 2 - ph * 6, 1.5 + ph * 2);
  }

  // B1 Underwater Mountain: Seaweed Tangle, three fronds swaying from a rooted clump
  _seaweed(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    g.fillStyle(col, 0.4);
    g.fillEllipse(0, -1.5, w, 4);
    for (let f = 0; f < 3; f++) {
      const x0 = (f - 1) * (w / 3.2);
      const tall = h * (f === 1 ? 1 : 0.8);
      const pts = [];
      for (let k = 0; k <= 6; k++) {
        const u = k / 6;
        pts.push({ x: x0 + pmath.sin(u * 3.2 + t / 380 + f * 1.7 + this.seed) * 3.2 * u, y: -u * tall });
      }
      g.lineStyle(2.5, col, 1);
      g.strokePoints(pts, false, false);
      // leaf blobs along the frond
      for (let k = 2; k <= 6; k += 2) {
        g.fillStyle(col, 0.6);
        g.fillEllipse(pts[k].x + (k % 4 === 0 ? 2.5 : -2.5), pts[k].y, 4, 2.5);
      }
    }
    g.fillStyle(pal.text, 0.7);
    g.fillCircle(pmath.sin(t / 500 + this.seed) * 3, -h * 0.55 - ((t / 40) % 10), 1); // a rising bubble
  }

  // B1 Candy Cane Canyon: Chocolate River, a wide glossy strip flush with the ground, ripples flowing downhill (right)
  _chocoRiver(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const band = [
      { x: -w / 2 - 2, y: 0 }, { x: -w / 2 + 3, y: -h * 0.7 }, { x: -w / 4, y: -h }, { x: w / 4, y: -h * 0.85 },
      { x: w / 2 - 3, y: -h * 0.65 }, { x: w / 2 + 2, y: 0 },
    ];
    g.fillStyle(pal.bg, 1);
    g.fillPoints(band, true);
    g.fillStyle(col, 0.45);
    g.fillPoints(band, true);
    g.lineStyle(1.5, col, 1);
    g.strokePoints(band, true, true);
    // flowing ripples: short dashes sliding right, wrapping inside the strip
    for (let i = 0; i < 4; i++) {
      const ph = ((t / 900 + i / 4) % 1);
      const rx = -w / 2 + 4 + ph * (w - 12);
      const ry = -h * (0.3 + 0.35 * (i % 2));
      g.lineStyle(1, pal.text, 0.75);
      g.lineBetween(rx, ry, rx + 5, ry);
    }
    // a sugar bubble that swells and pops
    const b = (t / 1100 + this.seed) % 1;
    g.lineStyle(1, col, 1 - b);
    g.strokeCircle(-w * 0.15, -h * 0.55, 0.8 + b * 2);
  }

  // B1 Garbage Dump Glacier: Seagull Dive, a gull in a steep dive (crash, `danger`): beating wings, beak first, with the
  // same soft halo as the drone so it reads against the sky at speed. Drawn around the box centre; the hit-box stays put.
  /** B2 Crystal Cavern: a cracked wall of crystal facets that glints (its hit flashes and dims the screen). */
  _shatterWall(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const glint = 0.5 + 0.5 * pmath.sin(t / 210 + this.seed);
    g.fillStyle(col, 0.12 + 0.12 * glint);
    g.fillRect(-w / 2 - 3, -h - 3, w + 6, h + 3);
    // three tall facets leaning together
    g.fillStyle(col, 0.55);
    g.fillPoints([{ x: -w / 2, y: 0 }, { x: -w / 2 + 2, y: -h * 0.7 }, { x: -w * 0.12, y: -h * 0.92 }, { x: -w * 0.05, y: 0 }], true);
    g.fillStyle(col, 0.8);
    g.fillPoints([{ x: -w * 0.08, y: 0 }, { x: -w * 0.1, y: -h * 0.95 }, { x: w * 0.08, y: -h }, { x: w * 0.14, y: 0 }], true);
    g.fillStyle(col, 0.55);
    g.fillPoints([{ x: w * 0.1, y: 0 }, { x: w * 0.16, y: -h * 0.85 }, { x: w / 2 - 1, y: -h * 0.6 }, { x: w / 2, y: 0 }], true);
    // cracks and a moving glint line
    g.lineStyle(1, pal.text, 0.7);
    g.lineBetween(-w * 0.02, -h * 0.9, w * 0.05, -h * 0.55);
    g.lineBetween(w * 0.05, -h * 0.55, -w * 0.04, -h * 0.3);
    g.lineBetween(w * 0.05, -h * 0.55, w * 0.12, -h * 0.4);
    const gy = -h * ((t / 900 + this.seed) % 1);
    g.lineStyle(1.5, pal.text, 0.35 + 0.5 * glint);
    g.lineBetween(-w / 2 + 2, gy, w / 2 - 2, gy - 4);
  }

  /** B2 Vertigo Vents: a drifting ash cloud with glowing embers (an air hazard; its hit dims the screen, no crash). */
  _ashCloud(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const drift = pmath.sin(t / 400 + this.seed) * 2;
    g.fillStyle(pal.bgAlt, 0.85);
    g.fillEllipse(-w * 0.22 + drift, -h * 0.45, w * 0.55, h * 0.7);
    g.fillEllipse(w * 0.2 - drift, -h * 0.5, w * 0.6, h * 0.8);
    g.fillEllipse(drift * 0.5, -h * 0.62, w * 0.5, h * 0.7);
    g.lineStyle(1.5, col, 0.8);
    g.strokeEllipse(-w * 0.22 + drift, -h * 0.45, w * 0.55, h * 0.7);
    g.strokeEllipse(w * 0.2 - drift, -h * 0.5, w * 0.6, h * 0.8);
    g.strokeEllipse(drift * 0.5, -h * 0.62, w * 0.5, h * 0.7);
    for (let k = 0; k < 5; k++) {
      const u = hash01(this.seed * 10 + k);
      const ph = ((t / 700) + u) % 1;
      g.fillStyle(col, 1 - ph);
      g.fillCircle(-w * 0.4 + u * w * 0.8, -h * 0.25 - ph * h * 0.6, 1.3);
    }
  }

  /** B3 Pyramid Peak: a sandstone boulder (crash, `danger`) whose cracks turn as it rolls (this.spin, radians). */
  _boulder(g, t, frame, col, pal) {
    const r = Math.min(this.w, this.h) / 2;
    const cy = -this.h / 2;
    const a = this.spin || 0;
    g.fillStyle(pal.bgAlt, 1);
    g.fillCircle(0, cy, r);
    g.fillStyle(col, 0.3);
    g.fillCircle(0, cy, r);
    g.lineStyle(2, col, 1);
    g.strokeCircle(0, cy, r);
    // three cracks fixed to the stone, so they turn with the roll
    g.lineStyle(1.5, pal.text, 0.75);
    for (let k = 0; k < 3; k++) {
      const u = a + k * 2.1;
      g.lineBetween(pmath.cos(u) * r * 0.15, cy + pmath.sin(u) * r * 0.15, pmath.cos(u + 0.3) * r * 0.8, cy + pmath.sin(u + 0.3) * r * 0.8);
    }
    // dust kicked up behind it while it rolls
    if (this.rolling) {
      for (let k = 0; k < 3; k++) {
        const ph = ((t / 300) + k / 3) % 1;
        g.fillStyle(col, 0.5 * (1 - ph));
        g.fillCircle(r * (0.8 + ph * 1.2) * (this.rollDir > 0 ? -1 : 1), -2 - ph * 5, 1.5 + ph * 1.5);
      }
    }
  }

  /** B3 Micro Mountain: a dew drop (crash, `danger`) that wobbles as it rolls, with a highlight that turns with it. */
  _dewDrop(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const a = this.spin || 0;
    const wob = this.rolling ? pmath.sin(t / 70 + this.seed) * 1.2 : 0;
    g.fillStyle(pal.bgAlt, 0.9);
    g.fillEllipse(0, -h / 2, w + wob, h - wob);
    g.fillStyle(col, 0.35);
    g.fillEllipse(0, -h / 2, w + wob, h - wob);
    g.lineStyle(2, col, 1);
    g.strokeEllipse(0, -h / 2, w + wob, h - wob);
    g.fillStyle(pal.text, 0.85);
    g.fillCircle(pmath.cos(a - 2.2) * w * 0.25, -h / 2 + pmath.sin(a - 2.2) * h * 0.25, 2);
  }

  /**
   * B3 Steampunk Slopes: a gear gate (crash, `danger`, only while closed). Two brass posts with a turning gear on top;
   * closed, a row of bars fills the box; open, the bars sit retracted below the posts' tops and the box goes faint.
   */
  _gearGate(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const open = !!this.open;
    // posts
    g.fillStyle(pal.bgAlt, 1);
    g.fillRect(-w / 2, -h, 4, h);
    g.fillRect(w / 2 - 4, -h, 4, h);
    g.lineStyle(1.5, col, 1);
    g.strokeRect(-w / 2, -h, 4, h);
    g.strokeRect(w / 2 - 4, -h, 4, h);
    // bars: full height while closed, a short stub while open
    const barH = open ? h * 0.18 : h - 3;
    g.fillStyle(col, open ? 0.35 : 0.9);
    for (let k = 0; k < 3; k++) g.fillRect(-w / 2 + 5 + k * ((w - 12) / 2) - 1, -barH, 2.5, barH);
    // gear on top, turning faster while it moves the bars
    const gr = Math.max(4, w * 0.28);
    const gy = -h - gr * 0.4;
    const ang = (t / (open ? 700 : 250)) % (Math.PI * 2);
    g.fillStyle(col, 1);
    for (let k = 0; k < 6; k++) {
      const u = ang + (k * Math.PI) / 3;
      g.fillCircle(pmath.cos(u) * gr, gy + pmath.sin(u) * gr, 1.6);
    }
    g.lineStyle(1.5, col, 1);
    g.strokeCircle(0, gy, gr * 0.75);
    g.fillStyle(pal.text, 0.9);
    g.fillCircle(0, gy, 1.5);
  }

  _seagull(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const pulse = 0.5 + 0.5 * pmath.sin(t / (this.alert ? 90 : 190) + this.seed);
    const cy = -h / 2 + pmath.sin(t / 240 + this.seed) * 2;
    g.fillStyle(col, 0.1 + 0.1 * pulse);
    g.fillEllipse(0, cy, w + 18 + 6 * pulse, h + 14 + 4 * pulse);
    if (this.alert) {
      g.lineStyle(1, pal.text, 0.35 + 0.4 * pulse);
      g.strokeEllipse(0, cy, w + 26 - 8 * pulse, h + 20 - 6 * pulse);
    }
    // wings: two poses (up / down) so the beat reads at 15 Hz redraw
    const up = frame % 4 < 2;
    const tipY = up ? cy - h * 0.5 : cy + h * 0.15;
    const elbowY = up ? cy - h * 0.15 : cy - h * 0.05;
    g.lineStyle(3, col, 1);
    g.strokePoints([{ x: -w / 2, y: tipY }, { x: -w * 0.22, y: elbowY }, { x: 0, y: cy }], false, false);
    g.strokePoints([{ x: w / 2, y: tipY }, { x: w * 0.22, y: elbowY }, { x: 0, y: cy }], false, false);
    // body: a pale teardrop pointing down-left (the dive), outlined in danger
    g.fillStyle(pal.text, 0.95);
    g.fillEllipse(0, cy + 1, 9, 13);
    g.lineStyle(1.5, col, 1);
    g.strokeEllipse(0, cy + 1, 9, 13);
    // beak and eye
    g.fillStyle(col, 1);
    g.fillTriangle(-2, cy + 6, 2, cy + 6, -3, cy + 11);
    g.fillCircle(-1.5, cy - 1, 1.3);
  }

  /**
   * B4 Space Mountain: Meteor, a burning rock falling through the jump arc (crash, `danger`). A flickering tail streams up
   * and back from it and the same soft halo as the seagull makes it read against the star field; drawn around the box
   * centre, the hit-box stays put.
   */
  _meteor(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const pulse = 0.5 + 0.5 * pmath.sin(t / (this.alert ? 90 : 190) + this.seed);
    const cy = -h / 2;
    g.fillStyle(col, 0.1 + 0.1 * pulse);
    g.fillEllipse(0, cy, w + 18 + 6 * pulse, h + 16 + 4 * pulse);
    if (this.alert) {
      g.lineStyle(1, pal.text, 0.35 + 0.4 * pulse);
      g.strokeEllipse(0, cy, w + 26 - 8 * pulse, h + 22 - 6 * pulse);
    }
    // tail: three flickering streaks up and to the right (it falls down-left, toward the oncoming sled)
    for (let k = 0; k < 3; k++) {
      const len = w * (0.7 + 0.35 * hash01(this.seed + k + frame * 0.73));
      const off = (k - 1) * h * 0.18;
      g.lineStyle(3 - k * 0.7, k === 1 ? pal.amber : col, 0.75 - k * 0.15);
      g.lineBetween(w * 0.12, cy - h * 0.12 + off, w * 0.12 + len * 0.8, cy - h * 0.12 + off - len * 0.55);
    }
    // the rock: a lumpy disc in danger with a pale molten rim and two craters
    const r = Math.min(w, h) * 0.36;
    const pts = [];
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      const rr = r * (0.85 + 0.25 * hash01(this.seed * 3 + i));
      pts.push({ x: -w * 0.08 + pmath.cos(a) * rr, y: cy + h * 0.06 + pmath.sin(a) * rr });
    }
    g.fillStyle(col, 1);
    g.fillPoints(pts, true);
    g.lineStyle(1.5, pal.text, 0.6 + 0.3 * pulse);
    g.strokePoints(pts, true, true);
    g.fillStyle(pal.bg, 0.55);
    g.fillCircle(-w * 0.14, cy + h * 0.02, r * 0.28);
    g.fillCircle(w * 0.02, cy + h * 0.18, r * 0.2);
  }

  /**
   * B4 Sky Jellyfish Mountain: Gust Front, a band of moving air (no crash). A pale zone with wind streaks flowing the way
   * the gust pushes, so the push direction reads before the sled flies in. The streak direction comes from the def's
   * impulse (BiomeEffects.gustImpulse).
   */
  _gustFront(g, t, frame, col, pal) {
    const w = this.w;
    const h = this.h;
    const imp = gustImpulse(this.def.onHit && this.def.onHit.impulsePxS);
    const m = pmath.hypot(imp.dvx, imp.dvy) || 1;
    const ux = imp.dvx / m;
    const uy = imp.dvy / m;
    const breathe = 0.5 + 0.5 * pmath.sin(t / 300 + this.seed);
    g.fillStyle(col, 0.1 + 0.06 * breathe);
    g.fillEllipse(0, -h / 2, w + 6, h + 4);
    g.lineStyle(1, col, 0.45);
    g.strokeEllipse(0, -h / 2, w + 6, h + 4);
    // streaks drifting along the push direction, wrapping inside the box
    for (let k = 0; k < 6; k++) {
      const u = hash01(this.seed * 7 + k);
      const ph = ((t / 520) + u) % 1;
      const bx = (hash01(this.seed + k * 2.3) - 0.5) * w * 0.7;
      const by = -h / 2 + (u - 0.5) * h * 0.7;
      const d = (ph - 0.5) * Math.min(w, h) * 0.8;
      const x0 = bx + ux * d;
      const y0 = by + uy * d;
      const len = 9 + 5 * u;
      g.lineStyle(1.5, k % 2 ? pal.text : col, 0.8 * pmath.sin(ph * Math.PI));
      g.lineBetween(x0, y0, x0 + ux * len, y0 + uy * len);
    }
    // one arrowhead at the centre: the push direction
    const ax = ux * 8;
    const ay = -h / 2 + uy * 8;
    g.fillStyle(pal.text, 0.6 + 0.3 * breathe);
    g.fillTriangle(ax + ux * 5, ay + uy * 5, ax - uy * 4, ay + ux * 4, ax + uy * 4, ay - ux * 4);
  }

  /** @returns {void} */
  destroy() {
    if (this.destroyed) return;
    this.destroyed = true;
    try {
      this.world.remove(this.body);
    } catch (e) { /* world already gone */ }
    if (this.gfx) this.gfx.destroy();
    this.gfx = null;
    this.body.bbHazard = null;
  }
}/** Hostile Kodiak drawing (issue #47). Visual only: the bear's state lives in RunScene.kodiak and
 * is advanced by systems/Kodiaks.js in the fixed tick. Each bear reads by SHAPE as well as colour:
 * the grizzly's shoulder hump, the polar bear's long neck and low body, the black bear's round
 * build, tall ears and tan muzzle. A telegraph ring precedes every attack (red = real, amber =
 * Kernel-Panic feint), and an off-screen bear shows as a chevron at the screen edge.
 */
import { FONT_KEY } from '../ui/PixelFont.js';

export const KODIAK_DEPTH = 19;

export class KodiakRider {
  /** @param {Phaser.Scene} scene @param {Object<string,number>} palette */
  constructor(scene, palette) {
    this.scene = scene;
    this.palette = palette;
    this.gfx = scene.add.graphics().setDepth(KODIAK_DEPTH);
    this.labels = [];
  }

  /** The i-th name tag (a small pool: one per pack member). */
  _label(i) {
    while (this.labels.length <= i) {
      this.labels.push(this.scene.add.bitmapText(0, 0, FONT_KEY, '', 8).setOrigin(0.5, 1).setDepth(KODIAK_DEPTH).setVisible(false));
    }
    return this.labels[i];
  }

  /**
   * @param {object[]} bears RunScene.kodiaks (the live pack)
   * @param {{left:number,right:number,top:number,bottom:number}|null} view camera world view
   * @param {number} zoom camera zoom
   * @param {number} timeMs run time
   * @param {boolean} reducedMotion
   */
  update(bears, view, zoom, timeMs, reducedMotion) {
    this.gfx.clear();
    for (const l of this.labels) l.setVisible(false);
    if (!view) return;
    // Off-screen chevrons stack per side so a pack shows as a pack.
    const edge = { left: 0, right: 0 };
    (bears || []).forEach((k, i) => { if (!k.done && Number.isFinite(k.groundY)) this._drawBear(k, this._label(i), view, zoom, timeMs, reducedMotion, edge); });
  }

  _drawBear(k, label, view, zoom, timeMs, reducedMotion, edge) {
    const g = this.gfx;
    const def = k.def, red = this.palette.danger ?? 0xff4060, amber = this.palette.amber ?? 0xffb347;
    const inv = 1 / (zoom > 0 ? zoom : 1);
    const onScreen = k.x > view.left - 30 && k.x < view.right + 30;
    if (!onScreen) {
      // Edge chevron in the bear's colours, with its short name: which bear, and from which side.
      const left = k.x < view.left;
      const ex = left ? view.left + 10 * inv : view.right - 10 * inv;
      const stack = edge[left ? 'left' : 'right']++ * 18 * inv;
      // Kept below the score block and above the bottom HUD row.
      const ey = Math.max(view.top + 80 * inv, Math.min(view.bottom - 40 * inv, k.groundY - 20 - stack));
      const d = (left ? 1 : -1) * 7 * inv;
      g.fillStyle(def.accent, 0.95).fillTriangle(ex - d, ey - 7 * inv, ex - d, ey + 7 * inv, ex + d * 0.6, ey);
      g.lineStyle(1.5 * inv, def.color === 0x15151b ? def.accent : def.color, 1).strokeTriangle(ex - d, ey - 7 * inv, ex - d, ey + 7 * inv, ex + d * 0.6, ey);
      label.setText(def.short).setTint(def.accent).setScale(inv).setOrigin(left ? 0 : 1, 0.5)
        .setPosition(ex + (left ? 12 : -12) * inv, ey).setVisible(true);
      return;
    }
    const x = k.x, y = k.groundY;
    let gx = 0;
    if (k.kind === 'kernelPanic' && k.phase === 'tele' && !reducedMotion) gx = (Math.floor(timeMs / 60) % 2 ? 2 : -2); // glitch jitter
    const run = reducedMotion ? 0 : Math.sin(timeMs / 70 + x * 0.02) * 3; // gallop
    const X = (lx) => x + lx + gx;
    // telegraph ring (before the drawing so the bear stays readable)
    if (k.phase === 'tele') {
      const real = k.kind !== 'kernelPanic' || k.real;
      const pulse = reducedMotion ? 1 : 0.6 + 0.4 * Math.sin(timeMs / 60);
      g.lineStyle(2, real ? red : amber, 0.9 * pulse).strokeCircle(X(0), y - 16, 30);
      g.fillStyle(real ? red : amber, 1).fillRect(X(-1), y - 58, 3, 10).fillRect(X(-1), y - 45, 3, 3); // "!"
      if (k.kind === 'blackIce' && Number.isFinite(k.targetX)) {
        // the landing spot it is sliding toward: a black-ice glint on the ground
        const ty = this.scene.terrain?.heightAt?.(k.targetX);
        if (Number.isFinite(ty)) g.lineStyle(2, def.accent, 0.9).lineBetween(k.targetX - 18, ty - 1, k.targetX + 18, ty - 1);
      }
    }
    if (k.phase === 'lunge' && !reducedMotion) {
      g.lineStyle(1.5, red, 0.6);
      for (let i = 0; i < 3; i++) g.lineBetween(X(-40 - i * 8), y - 10 - i * 6, X(-22 - i * 8), y - 10 - i * 6);
    }
    // Outline in a lighter tone of the bear's own colour (never the accent), so brown reads brown.
    const body = def.color, rim = def.rim ?? def.accent;
    g.fillStyle(body, 1);
    g.lineStyle(1.5, rim, 0.9);
    if (k.kind === 'bruteForce') {
      // GRIZZLY: big, heavy, a pronounced shoulder hump
      g.fillEllipse(X(0), y - 15, 46, 24).strokeEllipse(X(0), y - 15, 46, 24);
      g.fillCircle(X(-4), y - 27, 10).strokeCircle(X(-4), y - 27, 10);
      g.fillCircle(X(22), y - 20, 8).strokeCircle(X(22), y - 20, 8);
      g.fillCircle(X(18), y - 28, 2.5).fillCircle(X(25), y - 28, 2.5);
      g.fillStyle(0x3a2412, 1).fillCircle(X(29), y - 19, 2.5);
    } else if (k.kind === 'kernelPanic') {
      // POLAR: long, low body and a long neck reaching forward
      g.fillEllipse(X(-2), y - 13, 48, 18).strokeEllipse(X(-2), y - 13, 48, 18);
      g.fillEllipse(X(20), y - 18, 18, 9).strokeEllipse(X(20), y - 18, 18, 9);
      g.fillCircle(X(29), y - 20, 6).strokeCircle(X(29), y - 20, 6);
      g.fillCircle(X(26), y - 25, 1.8);
      g.fillStyle(0x10141c, 1).fillCircle(X(34), y - 19, 1.8);
    } else {
      // VERMONT BLACK BEAR: round, compact, tall rounded ears, tan muzzle
      g.fillEllipse(X(0), y - 15, 38, 24).strokeEllipse(X(0), y - 15, 38, 24);
      g.fillCircle(X(19), y - 21, 8).strokeCircle(X(19), y - 21, 8);
      g.fillCircle(X(14), y - 30, 3.6).strokeCircle(X(14), y - 30, 3.6);
      g.fillCircle(X(23), y - 30, 3.6).strokeCircle(X(23), y - 30, 3.6);
      g.fillStyle(0xc8a070, 1).fillEllipse(X(26), y - 19, 8, 6);
    }
    // legs (gallop)
    g.fillStyle(body, 1);
    for (const [lx, ph] of [[-14, 1], [-6, -1], [8, 1], [15, -1]]) g.fillRect(X(lx) - 2.5, y - 6 + ph * run * 0.3, 5, 6 - ph * run * 0.3);
    // name tag while it is a threat
    if (k.phase === 'tele' || k.phase === 'lunge') {
      label.setText(def.short).setTint(def.accent).setScale(inv).setOrigin(0.5, 1).setPosition(X(0), y - 62).setVisible(true);
    }
  }

  destroy() {
    this.gfx?.destroy();
    for (const l of this.labels) l.destroy();
    this.gfx = null;
    this.labels = [];
  }
}/**
 * OWNER: gameplay (readable-chaos pass, phase 3). A "DIED HERE" gate at the last crash x, shown only on a retry of the
 * same seed and mask (CrashReport.deathMarkerX decides). A BestMarker clone in `danger`: drawn lazily once the terrain
 * around it is in reach, pulses, and turns lime once the sled gets past it (you beat your own death). It stands taller
 * than the BEST gate (label at -126 vs -96): your best is often exactly where you died, and the labels must not overprint.
 * Drawing only; destroyed with the run.
 */
/** Gate height (px); the BEST gate is 90 with its label at -96. */
const GATE_H = 118;

export class LastDeathMarker {
  /**
   * @param {Phaser.Scene} scene
   * @param {Object<string,number>} palette
   * @param {number} x world px of the death.
   * @param {number} distanceM label value.
   */
  constructor(scene, palette, x, distanceM) {
    this.scene = scene;
    this.palette = palette;
    this.x = x;
    this.distanceM = distanceM;
    this.y = null;
    this.passed = false;
    this.gfx = scene.add.graphics().setDepth(7);
    this.label = scene.add.text(x, 0, `DIED HERE ${distanceM}m`, {
      fontFamily: 'monospace', fontSize: '12px', color: '#ff5a6e',
    }).setOrigin(0.5, 1).setDepth(7).setVisible(false);
  }


  /**
   * Where the label hangs (MarkerLayout.layoutMarkerLabels): world x/y of its bottom edge and the text origin x.
   * @param {{x:number, y:number, originX:number}|null} p @returns {void}
   */
  setPlacement(p) {
    if (!this.label || !p) return;
    this.label.setOrigin(p.originX, 1).setPosition(p.x, p.y);
  }

  /**
   * @param {number} timeMs @param {number} sledX
   * @param {(x:number)=>number} heightAt terrain height (only used once the sled is near).
   * @returns {void}
   */
  update(timeMs, sledX, heightAt) {
    if (!this.gfx) return;
    if (this.y == null) {
      if (this.x - sledX > 2600) return;
      const y = heightAt(this.x);
      if (!Number.isFinite(y)) return;
      this.y = y;
      this.label.setPosition(this.x, y - GATE_H - 8).setVisible(true);
    }
    if (!this.passed && sledX > this.x + 10) {
      this.passed = true;
      this.label.setText(`BEAT IT ${this.distanceM}m`).setColor('#7dff9a');
    }
    const col = this.passed ? this.palette.lime : this.palette.danger;
    const pulse = 0.6 + 0.4 * Math.sin(timeMs / 140);
    const g = this.gfx;
    g.clear();
    const x = this.x;
    const y = this.y;
    g.lineStyle(9, col, 0.14 * pulse);
    g.lineBetween(x, y, x, y - GATE_H);
    g.lineStyle(2, col, 0.95);
    g.lineBetween(x, y, x, y - GATE_H);
    // an X at the top: where it ended
    g.lineStyle(2, col, 0.6 + 0.4 * pulse);
    g.lineBetween(x - 7, y - GATE_H + 7, x + 7, y - GATE_H - 7);
    g.lineBetween(x + 7, y - GATE_H + 7, x - 7, y - GATE_H - 7);
    g.lineStyle(1.5, col, 0.5 * pulse);
    for (let i = 0; i < 5; i++) g.lineBetween(x - 12, y - 8 - i * 14, x, y - 12 - i * 14);
  }

  /** @param {Object<string,number>} palette @returns {void} */
  setPalette(palette) {
    this.palette = palette;
  }

  /** @returns {void} */
  destroy() {
    if (this.gfx) this.gfx.destroy();
    if (this.label) this.label.destroy();
    this.gfx = null;
    this.label = null;
  }
}/**
 * OWNER: gameplay engineer.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Floating pickup (sensor body). shapeKey: 'clock' (Clock Pulse), 'burst' (Packet Burst), 'shield' (Hashed Backup);
 * B1 biome pickups: 'maple' (Maple Wax), 'waxSpray' (Slick Wax Spray), 'bubble' (Aqua-Lung Bubble), 'candyCoat' (Sweet-Tooth);
 * B2: 'goggles' (Crystal Clear Goggles), 'heatShield' (Heat Shield); B3: 'skis' (Sandrunner Skis), 'jellyWax' (Royal Jelly
 * Wax), 'treads' (Clockwork Treads); B4: 'gravStabilizer' (Gravity Stabilizer), 'stabRails' (Stabilizer Rails).
 * Visual: a rotating dashed ring + bobbing glyph, glow pulse. The sensor stays put while the glyph bobs.
 */
import Phaser from 'phaser';
import { CAT } from './Sled.js';
import { powerupDrawKind } from '../systems/BiomeEffects.js';

const Matter = Phaser.Physics.Matter.Matter;
const { Bodies } = Matter;

export class PowerUp {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('../data/schemas.js').PowerUpDef} def
   * @param {import('../data/schemas.js').PowerUpSpawn} spawn
   * @param {Object<string,number>} palette
   */
  constructor(scene, def, spawn, palette) {
    this.scene = scene;
    this.world = scene.matter.world;
    this.def = def;
    this.spawn = spawn;
    this.palette = palette;
    this.collected = false;
    this.destroyed = false;
    this.color = palette[def.colorKey] != null ? palette[def.colorKey] : palette.cyan;
    const r = def.radius || 10;
    this.radius = r;
    /** Glyph: the def's shapeKey when known, else 'generic' (a biome pickup with a new shapeKey still shows a glyph). */
    this.drawKind = powerupDrawKind(def);
    this.body = Bodies.circle(spawn.x, spawn.y, r + 3, {
      isStatic: true,
      isSensor: true,
      label: 'powerup',
      collisionFilter: { group: 0, category: CAT.SENSOR, mask: CAT.SLED },
    });
    this.body.bbPowerUp = this;
    this.world.add(this.body);
    this.gfx = scene.add.graphics({ x: spawn.x, y: spawn.y }).setDepth(9);
    this._lastDraw = -1e9;
    this.draw(0);
  }

  /**
   * @param {number} timeMs
   * @param {number} camLeft
   * @param {number} camRight
   * @returns {void}
   */
  update(timeMs, camLeft, camRight) {
    if (this.destroyed) return;
    const vis = this.spawn.x > camLeft - 40 && this.spawn.x < camRight + 40;
    this.gfx.setVisible(vis);
    if (vis) this.draw(timeMs);
  }

  /** @param {number} t time ms. @returns {void} */
  draw(t) {
    const g = this.gfx;
    const col = this.color;
    const pal = this.palette;
    const r = this.radius;
    g.clear();
    const bob = Math.sin(t / 260 + this.spawn.x * 0.01) * 2.5; // pmath-exempt: draw-only
    g.y = this.spawn.y + bob;
    // glow
    const pulse = 0.5 + 0.5 * Math.sin(t / 200); // pmath-exempt: draw-only
    g.fillStyle(col, 0.1 + 0.08 * pulse);
    g.fillCircle(0, 0, r + 6);
    g.fillStyle(pal.bg, 0.85);
    g.fillCircle(0, 0, r);
    // dashed rotating ring
    const rot = t / 700;
    g.lineStyle(1.5, col, 1);
    for (let i = 0; i < 8; i++) {
      const a0 = rot + (i * Math.PI) / 4;
      g.beginPath();
      g.arc(0, 0, r + 1, a0, a0 + 0.5);
      g.strokePath();
    }
    g.lineStyle(1.5, col, 1);
    g.strokeCircle(0, 0, r - 3);

    switch (this.drawKind) {
      case 'blackHole': {
        // Shard Magnet: a dark core with a spinning accretion arc and an orbiting shard
        g.fillStyle(0x020006, 0.95);
        g.fillCircle(0, 0, 3.6);
        g.lineStyle(1.5, pal.text, 1);
        g.beginPath();
        g.arc(0, 0, 5, t / 200, t / 200 + Math.PI * 1.3);
        g.strokePath();
        const o = t / 350;
        g.fillStyle(pal.lime != null ? pal.lime : col, 1);
        g.fillCircle(Math.cos(o) * 5.5, Math.sin(o) * 5.5, 1.3); // pmath-exempt: draw-only
        break;
      }
      case 'clock': {
        g.lineStyle(1.5, pal.text, 1);
        g.lineBetween(0, 0, 0, -r * 0.55);
        const a = t / 300;
        g.lineBetween(0, 0, Math.sin(a) * r * 0.45, -Math.cos(a) * r * 0.45); // pmath-exempt: draw-only
        g.fillStyle(col, 1);
        g.fillCircle(0, 0, 1.4);
        break;
      }
      case 'burst': {
        g.fillStyle(col, 1);
        g.fillPoints([{ x: 1.5, y: -6 }, { x: -3.5, y: 0.5 }, { x: -0.3, y: 0.5 }, { x: -1.5, y: 6 }, { x: 3.5, y: -1 }, { x: 0.3, y: -1 }], true);
        break;
      }
      case 'shield': {
        g.lineStyle(1.5, pal.text, 1);
        g.strokePoints([{ x: -4.5, y: -4.5 }, { x: 0, y: -6.5 }, { x: 4.5, y: -4.5 }, { x: 4, y: 2 }, { x: 0, y: 6 }, { x: -4, y: 2 }], true, true);
        g.fillStyle(col, 0.7);
        g.fillCircle(0, -0.5, 1.8);
        break;
      }
      case 'maple': {
        // B1 Maple Wax: a maple leaf (three lobes and a stem)
        g.fillStyle(col, 1);
        g.fillTriangle(0, -6.5, -2.5, -1, 2.5, -1);
        g.fillTriangle(-6, -2.5, -0.5, 1, -1.5, -3.5);
        g.fillTriangle(6, -2.5, 0.5, 1, 1.5, -3.5);
        g.fillRect(-2, -2, 4, 3.5);
        g.lineStyle(1.5, pal.text, 1);
        g.lineBetween(0, 1, 0.5, 6);
        break;
      }
      case 'waxSpray': {
        // B1 Slick Wax Spray: a spray can with a puff of mist
        g.fillStyle(col, 0.85);
        g.fillRect(-5, -2, 4.5, 8);
        g.fillStyle(pal.text, 1);
        g.fillRect(-4, -4.5, 2.5, 2.5);
        const ph = (t / 300) % 1;
        g.fillStyle(pal.text, 1 - ph * 0.7);
        g.fillCircle(1.5 + ph * 2, -4, 1);
        g.fillCircle(3.5 + ph * 2, -6, 0.9);
        g.fillCircle(3.5 + ph * 2, -2, 0.9);
        break;
      }
      case 'bubble': {
        // B1 Aqua-Lung Bubble: a breathing bubble with a glint and a small one rising
        const breathe = 1 + 0.12 * Math.sin(t / 250); // pmath-exempt: draw-only
        g.lineStyle(1.5, pal.text, 1);
        g.strokeCircle(-0.5, 1, 4.5 * breathe);
        g.fillStyle(pal.text, 0.9);
        g.fillCircle(-2.2, -0.8, 1.1);
        g.lineStyle(1, col, 1);
        g.strokeCircle(4, -4.5 - ((t / 120) % 2), 1.4);
        break;
      }
      case 'candyCoat': {
        // B1 Sweet-Tooth Coating: a tooth with a candy-stripe coat
        g.fillStyle(pal.text, 1);
        g.fillRect(-4.5, -5.5, 9, 5);
        g.fillTriangle(-4.5, -0.5, -0.8, -0.5, -3.5, 5.5);
        g.fillTriangle(0.8, -0.5, 4.5, -0.5, 3.5, 5.5);
        g.lineStyle(1.5, col, 1);
        g.lineBetween(-4.5, -2, 4.5, -4.5);
        g.lineBetween(-4.5, -4.8, 0, -5.5);
        break;
      }
      case 'goggles': {
        // B2 Crystal Clear Goggles: two lenses on a strap, a glint sweeping across
        g.lineStyle(1.5, pal.text, 1);
        g.strokeCircle(-3, 0.5, 2.6);
        g.strokeCircle(3, 0.5, 2.6);
        g.lineStyle(1.5, col, 1);
        g.lineBetween(-6.5, -1, 6.5, -1);
        g.fillStyle(pal.text, 0.9);
        g.fillCircle(-3.8 + ((t / 500) % 1) * 7.6, -0.3, 0.9);
        break;
      }
      case 'heatShield': {
        // B2 Heat Shield: a round shield with a flickering flame
        g.lineStyle(1.5, pal.text, 1);
        g.strokeCircle(0, 0, 5);
        const fl = 1 + 0.15 * Math.sin(t / 90); // pmath-exempt: draw-only
        g.fillStyle(col, 1);
        g.fillTriangle(0, -4 * fl, -2.6, 3, 2.6, 3);
        g.fillStyle(pal.text, 0.9);
        g.fillTriangle(0, -1.5 * fl, -1.2, 2.5, 1.2, 2.5);
        break;
      }
      case 'skis': {
        // B3 Sandrunner Skis: two skis with upturned tips and a sand streak sliding under them
        g.lineStyle(1.8, pal.text, 1);
        g.lineBetween(-5.5, -1.5, 4, -1.5);
        g.lineBetween(-5.5, 2, 4, 2);
        g.lineBetween(4, -1.5, 6, -3.5);
        g.lineBetween(4, 2, 6, 0);
        const sx = -6 + ((t / 400) % 1) * 10;
        g.lineStyle(1, col, 1);
        g.lineBetween(sx, 4.5, sx + 3, 4.5);
        break;
      }
      case 'jellyWax': {
        // B3 Royal Jelly Wax: a honeycomb cell with a glossy drop of jelly
        g.lineStyle(1.5, pal.text, 1);
        const hx = [];
        for (let k = 0; k < 6; k++) hx.push({ x: Math.cos((k * Math.PI) / 3) * 5.5, y: Math.sin((k * Math.PI) / 3) * 5.5 }); // pmath-exempt: draw-only
        g.strokePoints(hx, true, true);
        g.fillStyle(col, 1);
        g.fillCircle(0, 0.8 + Math.sin(t / 300) * 0.6, 2.6); // pmath-exempt: draw-only
        g.fillStyle(pal.text, 0.9);
        g.fillCircle(-0.8, 0, 0.8);
        break;
      }
      case 'treads': {
        // B3 Clockwork Treads: a tread loop whose links run round a cog
        g.lineStyle(1.5, pal.text, 1);
        g.strokeRect(-6, -3.5, 12, 7);
        const ph = (t / 120) % 3;
        g.fillStyle(col, 1);
        for (let k = 0; k < 4; k++) g.fillRect(-5 + ((k * 3 + ph) % 10), -4.5, 1.4, 1.4);
        g.lineStyle(1.2, col, 1);
        g.strokeCircle(0, 0, 2);
        break;
      }
      case 'gravStabilizer': {
        // B4 Gravity Stabilizer: a gyroscope, a level bar held flat inside a ring that tilts back and forth
        const tilt = Math.sin(t / 260) * 0.5; // pmath-exempt: draw-only
        g.lineStyle(1.5, pal.text, 1);
        g.strokeEllipse(0, 0, 12, 12 * (0.55 + 0.35 * Math.abs(Math.cos(tilt)))); // pmath-exempt: draw-only
        g.lineStyle(2, col, 1);
        g.lineBetween(-5.5, 0, 5.5, 0);
        g.fillStyle(col, 1);
        g.fillCircle(0, 0, 1.6);
        break;
      }
      case 'stabRails': {
        // B4 Stabilizer Rails: two parallel rails with ties, and a spring above them squashed flat (the bounce damped)
        g.lineStyle(1.5, pal.text, 1);
        g.lineBetween(-6, 1.5, 6, 1.5);
        g.lineBetween(-6, 4.5, 6, 4.5);
        g.lineStyle(1, col, 1);
        for (let k = -4; k <= 4; k += 4) g.lineBetween(k, 0.5, k, 5.5);
        const sq = 1 + 0.4 * Math.abs(Math.sin(t / 220)); // pmath-exempt: draw-only
        g.lineStyle(1.3, col, 1);
        g.strokePoints([{ x: -4, y: -1 }, { x: -2, y: -1 - 2 * sq }, { x: 0, y: -1 }, { x: 2, y: -1 - 2 * sq }, { x: 4, y: -1 }], false, false);
        break;
      }
      default: {
        // generic glyph: a filled diamond in the pickup colour with a light core, readable at any size
        const d = r * 0.5;
        g.fillStyle(col, 1);
        g.fillPoints([{ x: 0, y: -d }, { x: d, y: 0 }, { x: 0, y: d }, { x: -d, y: 0 }], true);
        g.fillStyle(pal.text, 1);
        g.fillCircle(0, 0, 1.4);
      }
    }
  }

  /** @returns {void} */
  destroy() {
    if (this.destroyed) return;
    this.destroyed = true;
    try {
      this.world.remove(this.body);
    } catch (e) { /* world already gone */ }
    if (this.gfx) this.gfx.destroy();
    this.gfx = null;
    this.body.bbPowerUp = null;
  }
}/**
 * OWNER: gameplay (game-feel pass). Collectible neon data shards. No physics bodies: ONE Graphics redrawn each frame for
 * the shards near the camera, collected by a simple radius overlap test. Chunk-scoped (add/remove with the terrain chunk
 * lifecycle); collected ids are remembered so a re-streamed chunk does not respawn them.
 */
import Phaser from 'phaser';

export class ShardField {
  /** @param {Phaser.Scene} scene @param {Object<string,number>} palette */
  constructor(scene, palette) {
    this.scene = scene;
    this.palette = palette;
    this.byChunk = new Map();
    this.collected = new Set();
    this.gfx = scene.add.graphics().setDepth(9).setBlendMode(Phaser.BlendModes.ADD);
  }

  /** @param {{index:number, shards?:{id:string,x:number,y:number}[]}} chunk @returns {void} */
  addChunk(chunk) {
    if (!chunk || !Array.isArray(chunk.shards) || !chunk.shards.length) return;
    const list = [];
    for (const s of chunk.shards) {
      if (!s || !Number.isFinite(s.x) || !Number.isFinite(s.y) || this.collected.has(s.id)) continue;
      list.push({ id: s.id, x: s.x, y: s.y });
    }
    if (list.length) this.byChunk.set(chunk.index, list);
  }

  /** @param {number} idx @returns {void} */
  removeChunk(idx) {
    this.byChunk.delete(idx);
  }

  /**
   * Collect every shard within r px of (x, y).
   * @returns {{id:string,x:number,y:number}[]} the collected shards (already removed).
   */
  collect(x, y, r) {
    let out = null;
    const r2 = r * r;
    for (const list of this.byChunk.values()) {
      for (let i = list.length - 1; i >= 0; i--) {
        const s = list[i];
        const dx = s.x - x;
        if (dx > r || dx < -r) continue;
        const dy = s.y - y;
        if (dx * dx + dy * dy <= r2) {
          list.splice(i, 1);
          this.collected.add(s.id);
          (out || (out = [])).push(s);
        }
      }
    }
    return out || [];
  }

  /**
   * Shard Magnet: move every shard within r px of (x, y) one pull step toward it. `step` is
   * ShardMagnet.pullStep. Positions only; collection still happens in collect().
   * @returns {number} how many shards moved
   */
  pull(x, y, r, step) {
    let moved = 0;
    for (const list of this.byChunk.values()) {
      for (const s of list) {
        if (s.x - x > r || x - s.x > r) continue;
        const p = step(s.x, s.y, x, y);
        if (!p) continue;
        s.x = p.x;
        s.y = p.y;
        s.pulled = true;
        moved++;
      }
    }
    return moved;
  }

  /** @param {number} timeMs @param {number} left @param {number} right @returns {void} */
  update(timeMs, left, right) {
    const g = this.gfx;
    g.clear();
    const pulse = 0.75 + 0.25 * Math.sin(timeMs / 140); // pmath-exempt: draw-only
    const col = this.palette.lime != null ? this.palette.lime : 0xffffff;
    const hi = this.palette.text != null ? this.palette.text : 0xffffff;
    for (const list of this.byChunk.values()) {
      for (const s of list) {
        if (s.x < left - 20 || s.x > right + 20) continue;
        // A pulled shard stops bobbing (its x changes every tick) and is drawn where the pull put it.
        const bob = s.pulled ? 0 : Math.sin(timeMs / 260 + s.x * 0.05) * 2; // pmath-exempt: draw-only
        const y = s.y + bob;
        const pts = [{ x: s.x, y: y - 7 }, { x: s.x + 5, y }, { x: s.x, y: y + 7 }, { x: s.x - 5, y }];
        g.fillStyle(col, 0.18 * pulse);
        g.fillCircle(s.x, y, 11);
        g.fillStyle(col, 0.45);
        g.fillPoints(pts, true);
        g.lineStyle(1.5, hi, 0.95 * pulse);
        g.strokePoints(pts, true, true);
      }
    }
  }

  /** @param {Object<string,number>} palette @returns {void} */
  setPalette(palette) {
    this.palette = palette;
  }

  /** @returns {void} */
  destroy() {
    if (this.gfx) this.gfx.destroy();
    this.gfx = null;
    this.byChunk.clear();
  }
}/**
 * OWNER: gameplay engineer.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Sled + rider as ONE compound Matter body (SAT on convex hulls, doc 4.2), drawn with Phaser Graphics shapes.
 * Collision parts (all convex, labelled so RunScene can tell a harmless runner touch from a rider crash):
 *   'skid' x2 (circles at the runner ends - they glide over polyline seams), 'deck' (plate), 'torso', 'head'.
 * Rider pose reacts to input: tuck (crouch), lean (A/D), air brake (arms/legs thrown out + flap), parachute (canopy),
 * helicopter (sled spins about its vertical axis - drawn by foreshortening the shapes, no physics involved).
 */
import Phaser from 'phaser';
import { PHYSICS } from '../constants.js';
import { TUNING, BASE_STEP_MS, stallNudgeStep, airIdleSpin, conveyorStep, geyserStep } from '../systems/PhysicsTuner.js';
import { springReboundVelocity } from '../systems/BiomeEffects.js';
import { aerodynamicStep, canopyFuelStep, vacuumDivebombStep, airBrakeKickStep } from '../systems/BsodAerodynamics.js';
import { runRandomStreams } from '../systems/RunRandom.js';
import pmath from '../systems/pmath.js';

const Matter = Phaser.Physics.Matter.Matter;
const { Bodies, Body } = Matter;

const DEG = Math.PI / 180;

/** Matter collision categories shared with TerrainMesh / Hazard / PowerUp. */
export const CAT = Object.freeze({ TERRAIN: 0x0001, SLED: 0x0002, SENSOR: 0x0004 });

/** Seconds per 1 px/s step conversion helpers (Matter 0.20 velocities are normalised to the 1000/60 ms base step). */
const toPxS = (v) => (v * 1000) / BASE_STEP_MS;
const fromPxS = (v) => (v * BASE_STEP_MS) / 1000;

const fromRadS = (w) => (w * BASE_STEP_MS) / 1000;
const lerp = (a, b, t) => a + (b - a) * t;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

export class Sled {
  /**
   * @param {Phaser.Scene} scene
   * @param {number} x world px spawn.
   * @param {number} y world px spawn.
   * @param {Object<string,number>} palette colour ints from ui/Palette.getPalette().
   */
  constructor(scene, x, y, palette, look) {
    this.scene = scene;
    this.world = scene.matter.world;
    this.palette = palette;
    // W4 cosmetics. `look` is pre-resolved by Cosmetics.resolveCosmetics, so this entity never reads the
    // profile or the catalogue. Absent `look` (every pre-W4 caller and every test) falls straight through
    // to the palette keys below, so the default sled renders exactly as it did before W4.
    this.look = look || null;
    // Seeded streams (issue #59): scramble torque draws from physics/scramble, the scrambled
    // silhouette shake from visual/sled, so drawing one never moves the other. RunScene supplies
    // the run's streams; a bare Sled (tests, tools) gets fixed ones.
    this.random = scene.runRandom || runRandomStreams('sled');
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.destroyed = false;
    this.inWorld = false;

    // Contact / state bookkeeping
    this.msSinceContact = 999;
    this._contactFlag = false;
    this.groundAngleDeg = 0;
    this.airtimeMs = 0;
    this.hopBufferMs = 0;
    this._playerHopActive = false;
    this._playerHopElapsedMs = 0;
    this.pushCooldownMs = 0;
    this.parachuteMs = 0;
    this.parachuteFuelMs = (this.canopyFuelFullMs || PHYSICS.parachuteDurationMs);
    this.chuteUsed = false;
    this.tucked = false;
    this.airBrakeActive = false;
    this.airBrakePressPending = false; // one press retained across physics hit-stop
    this.airBrakeKickUsed = false; // #247 one-shot per actual airborne interval; rearm on genuine touchdown
    this.airBrakeLiftProtected = false; // persists until real touchdown; later coyote Hop cannot erase purchased lift
    this._protectedHopExtraVyPxS = 0; // separate later Hop lift that variable release MAY truncate
    this.airBrakeKickPulse = 0; // actual spent-speed event; RunScene consumes & clears this fixed tick
    this.heliInput = 0;
    this.corkscrewActive = false;
    this.heliPhase = 0; // degrees, visual only
    this.heliVel = 0;
    this.shield = false;
    this.scrambled = false;
    this.invulnerableMs = 0;
    this.hidden = false;
    this._lastPad = null;
    this._time = 0;
    this._lastTilt = 0;
    this.pose = { phi: 10, chute: 0, brake: 0, tuck: 0 };
    this.boostMs = 0; // reduced drag after a landing boost
    this.squash = 0; // 0..1 landing squash (visual)
    this.airEtaMs = Infinity; // ballistic ms to touchdown while airborne (set by RunScene.airForecast); Infinity = unknown
    this.airSlopeDeg = null; // ground slope at that touchdown point (deg), null = unknown
    this.dropAheadDeg = 90; // how much steeper the ground gets just ahead (set by RunScene); large = kicker/drop
    this._groundRunMs = 0;
    this._sinceLaunchMs = 999;
    this._landSettleMs = 0;

    this._buildBody(x, y);
    this.gfx = scene.add.graphics().setDepth(20);
    this.render(16);
  }

  _buildBody(x, y) {
    const mk = (shape, label, opts = {}) => {
      const o = { label, ...opts };
      return shape(o);
    };
    const parts = [
      mk((o) => Bodies.polygon(x - 15, y + 7, 24, 4, o), 'skid'),
      mk((o) => Bodies.polygon(x + 15, y + 7, 24, 4, o), 'skid'),
      mk((o) => Bodies.rectangle(x, y + 3, 40, 6, { ...o, chamfer: { radius: 2 } }), 'deck'),
      mk((o) => Bodies.rectangle(x - 5, y - 8, 9, 15, { ...o, chamfer: { radius: 3 } }), 'torso', { density: 0.0012 }),
      mk((o) => Bodies.circle(x - 2, y - 21, 5, o), 'head', { density: 0.0008 }),
    ];
    const body = Body.create({
      parts,
      label: 'sled',
      friction: TUNING.groundFriction,
      frictionStatic: TUNING.groundFrictionStatic,
      frictionAir: PHYSICS.dragUntucked,
      restitution: 0.02,
      slop: 0.02,
      collisionFilter: { group: 0, category: CAT.SLED, mask: CAT.TERRAIN | CAT.SENSOR },
    });
    for (const p of body.parts) p.collisionFilter = { group: 0, category: CAT.SLED, mask: CAT.TERRAIN | CAT.SENSOR };
    this.body = body;
    // Offset between centre of mass and the drawing origin (spawn point), in the body's local (unrotated) frame.
    this.off = { x: body.position.x - x, y: body.position.y - y };
    this.world.add(body);
    this.inWorld = true;
    this._sync();
  }

  _sync() {
    const b = this.body;
    this.x = b.position.x;
    this.y = b.position.y;
    const v = Body.getVelocity(b);
    this.vx = toPxS(v.x);
    this.vy = toPxS(v.y);
  }

  /** @returns {boolean} true while the runners (or deck) are touching terrain, with a short hysteresis. */
  get grounded() {
    return this.msSinceContact < TUNING.groundedGraceMs;
  }

  /** Speed magnitude in px/s. @returns {number} */
  get speed() {
    return pmath.hypot(this.vx, this.vy);
  }

  /** @returns {number} body angle in degrees, continuous (never wrapped). */
  get angleDeg() {
    return this.body.angle / DEG;
  }

  /** Called by RunScene when a skid/deck pair is touching terrain this sub-step. @returns {void} */
  noteGroundContact() {
    this._contactFlag = true;
  }

  /**
   * Call once after every physics sub-step (collision events have fired by then).
   * @param {number} stepMs
   * @returns {boolean} true only on a new actual terrain touchdown
   */
  endStep(stepMs) {
    const actualNewTouchdown=!!this._contactFlag &&
      this.msSinceContact >= TUNING.groundedGraceMs;
    if (this._contactFlag) {
      this.airBrakePressPending = false;
      this.airBrakeKickUsed = false; // actual Matter contact rearms, never a button release
      this.airBrakeLiftProtected = false; // only physical terrain contact can end protection
      this._protectedHopExtraVyPxS = 0;
      if (this.msSinceContact >= TUNING.groundedGraceMs) {
        this.chuteUsed = false; // freshly landed
        this.parachuteFuelMs = (this.canopyFuelFullMs || PHYSICS.parachuteDurationMs);
        this._landSettleMs = TUNING.landSettleMs;
        this.touchdownVx = this._preVx;
        this.touchdownVy = this._preVy;
      }
      this.msSinceContact = 0;
    } else {
      this.msSinceContact += stepMs;
    }
    this._contactFlag = false;
    // Matter applies linear air friction DURING each physics substep, after
    // our input-level quadratic drag. The removable player-Hop velocity must
    // receive the SAME damping or release will subtract more ascent than is
    // physically still present and consume paid AirBrake lift.
    if (this._protectedHopExtraVyPxS > 0) {
      const frictionAir=Number.isFinite(this.body?.frictionAir)
        ? this.body.frictionAir : 0;
      this._protectedHopExtraVyPxS *= Math.max(0,
        1 - frictionAir * stepMs / BASE_STEP_MS);
    }
    this._groundRunMs = this.msSinceContact < 1 ? this._groundRunMs + stepMs : (this.msSinceContact > TUNING.snapWindowMs ? 0 : this._groundRunMs);
    this.airtimeMs = this.grounded ? 0 : this.airtimeMs + stepMs;
    if (this._landSettleMs > 0 && TUNING.landSpinMaxDegS > 0) {
      this._landSettleMs = Math.max(0, this._landSettleMs - stepMs);
      const wMax = fromRadS(TUNING.landSpinMaxDegS * DEG);
      const w = Body.getAngularVelocity(this.body);
      if (Math.abs(w) > wMax) Body.setAngularVelocity(this.body, Math.sign(w) * wMax);
    }
    this._sync();
    return actualNewTouchdown;
  }

  /**
   * Apply input + effective physics for one sub-step.
   * @param {import('../systems/VirtualPad.js').VirtualPadState} pad
   * @param {import('../systems/PhysicsTuner.js').EffectivePhysics} phys
   * @param {number} stepMs
   * @returns {void}
   */
  applyControls(pad, phys, stepMs, atmosphere = null) {
    if (this.destroyed || !this.inWorld) return;
    const dt = stepMs / 1000;
    const b = this.body;
    const firstOfFrame = pad !== this._lastPad;
    this._lastPad = pad;
    this._time += stepMs;
    const pressed = (pad && pad.pressed) || {};
    const grounded = this.grounded;

    // ---- one-shot edges (only on the first sub-step of a frame) ----
    if (firstOfFrame) {
      if (pressed.hop) this.hopBufferMs = TUNING.hopBufferMs;
      // Parachute uses continuous hold input, not a one-shot pulse. Fuel is shared
      // between every deployment in this flight and restored on actual touchdown.
      this.heliInput = (pad && (pad.heli || (pad.corkscrew && !grounded ? 1 : 0))) || 0;
    }
    this.hopBufferMs = Math.max(0, this.hopBufferMs - stepMs);
    this.pushCooldownMs = Math.max(0, this.pushCooldownMs - stepMs);
    this.geyserCooldownMs = Math.max(0, (this.geyserCooldownMs || 0) - stepMs);
    this.invulnerableMs = Math.max(0, this.invulnerableMs - stepMs);
    const fuel = canopyFuelStep(this.parachuteFuelMs, !!(pad && pad.parachute), !grounded, stepMs, (this.canopyFuelFullMs || PHYSICS.parachuteDurationMs));
    this.parachuteFuelMs = fuel.fuelMs;
    const chute = fuel.deployed;
    this.parachuteMs = chute ? Math.max(0.001, this.parachuteFuelMs) : 0;
    if (chute) this.chuteUsed = true;
    // Fixed-tick input preserves a short press edge even if the key was
    // released before the tick sampled the held state. A paid one-shot
    // needs that first-substep edge; later substeps cannot replay it.
    const bufferedAirBrake = firstOfFrame && !!this.airBrakePressPending;
    if (firstOfFrame) this.airBrakePressPending = false;
    this.airBrakeActive = !grounded &&
      (!!(pad && pad.airBrake) || (firstOfFrame && !!pressed.airBrake) || bufferedAirBrake);
    this.corkscrewActive = !!(pad && pad.corkscrew) && !grounded;
    this.tucked = !!(pad && pad.tuck);

    // ---- world / body tunables ----
    this.world.engine.gravity.y = phys.gravityPxS2 / 1000;
    this._sinceLaunchMs += stepMs;
    const boostK = this.boostMs > 0 ? TUNING.boostDragMul : 1;
    if (this.boostMs > 0) this.boostMs = Math.max(0, this.boostMs - stepMs);
    b.frictionAir = phys.frictionAir * boostK;
    b.friction = phys.groundFriction;
    b.restitution = phys.restitution == null ? 0.02 : phys.restitution;

    // ---- velocity-space forces (px/s) ----
    let vx = toPxS(Body.getVelocity(b).x);
    let vy = toPxS(Body.getVelocity(b).y);
    let speed = pmath.hypot(vx, vy);
    const slopeRad = this.groundAngleDeg * DEG;
    const tx = pmath.cos(slopeRad);
    const ty = pmath.sin(slopeRad);
    const nx = pmath.sin(slopeRad);
    const ny = -pmath.cos(slopeRad);

    // soft terminal velocity
    if (phys.quadDrag && speed > 1) {
      const f = Math.max(0, 1 - phys.quadDrag * boostK * speed * dt);
      vx *= f;
      vy *= f;
      this._protectedHopExtraVyPxS = (this._protectedHopExtraVyPxS || 0) * f;
    }
    // runner resistance on the ground (lower inside High Bandwidth zones, much higher while braking)
    if (grounded && phys.groundResist) {
      const f = pmath.exp(-phys.groundResist * boostK * dt);
      vx *= f;
      vy *= f;
    }
    // Only the player's own Space-hop ascent may be shortened by release.
    // A fresh paid AirBrake impulse is independent and must survive the cutoff.
    // Neither holding nor re-tapping AirBrake buys extra lift until touchdown.
    let airBrakeKickedThisStep = false;
    if (this.airBrakeActive && !this.airBrakeKickUsed) {
      const kicked = airBrakeKickStep({ vx, vy,
        atmosphereDensity: atmosphere ? atmosphere.atmosphereDensity : 1,
        decelFraction: PHYSICS.airBrakeDecel,
        liftBudgetFraction: TUNING.airBrakeLiftBudgetFraction,
        upwardRatio: TUNING.airBrakeKickUpRatio,
        maxUpPxS: TUNING.airBrakeKickUpCapPxS,
        liftMul: phys.airbrakeLiftMul || 1,
      });
      // Variable-hop release only truncates the original Space launch.
      // A paid AirBrake impulse is a NEW airborne kick, like a spring rebound;
      // it must not be zeroed by the hop-release cutoff later this tick or in
      // a subsequent tick. When no lift was actually purchased (vacuum, very
      // slow rider, or already faster upward), retain normal hop semantics.
      if (kicked.spentSpeedPxS > 0) {
        // Vacuum and other no-payment attempts cannot consume the flight's
        // ONLY AirBrake. Spend the latch, event and any purchased lift as ONE
        // transaction. A later physical paid press in atmosphere may retry.
        this.airBrakeKickUsed = true;
        if (kicked.vy < vy) {
          this.airBrakeLiftProtected = true;
          // A real purchased ascent is a launch, not incidental crest drift.
          this._sinceLaunchMs = 0;
          this._protectedHopExtraVyPxS = this._playerHopActive
            ? Math.max(0, -vy) : 0;
        }
        this.airBrakeKickPulse = 1;
        airBrakeKickedThisStep = true;
        vx = kicked.vx;
        vy = kicked.vy;
      }
    }
    // parachute stall: float
    if (chute && vy > 0 && (!atmosphere || atmosphere.atmosphereDensity > 0)) vy *= pmath.exp(-1.6 * dt * (atmosphere ? atmosphere.atmosphereDensity : 1));
    // Normal divebomb drops without killing horizontal momentum. In zero-atmo
    // Space Mountain the small board thruster instead trades flight height/time
    // for modest forward purchase; no false atmospheric wind is generated.
    if (!grounded && pad && pad.divebomb && !chute && !airBrakeKickedThisStep) {
      const density = atmosphere ? atmosphere.atmosphereDensity : 1;
      if (density === 0) {
        const impulse = vacuumDivebombStep({
          airborne: true, divebomb: true, atmosphereDensity: 0,
          power: phys.divebombMul || 1, stepMs,
        });
        vx += impulse.dvx;
        vy += impulse.dvy;
      } else {
        vy += TUNING.divebombDownPxS2 * (phys.divebombMul || 1) * dt * density;
      }
    }
    // Deterministic physical BSOD airflow; wind/audio renderers never affect physics.
    if (!grounded && atmosphere) {
      const wind = aerodynamicStep({ vx, vy, relativeAirX: atmosphere.relativeAirX,
        atmosphereDensity: atmosphere.atmosphereDensity, proximity01: atmosphere.proximity01, parachute: chute,
        stepMs });
      vx += wind.dvx;
      vy += wind.dvy;
    }

    // push (W): only when nearly stopped on flat / uphill ground
    speed = pmath.hypot(vx, vy);
    if (pad && pad.push && grounded && speed < PHYSICS.pushMaxSpeedPxS && this.groundAngleDeg >= PHYSICS.pushMinSlopeDeg
      && this.pushCooldownMs <= 0) {
      const kick = TUNING.pushKickPxS * (phys.pushForceMul || 1);
      vx = tx * kick;
      vy = ty * kick;
      this.pushCooldownMs = TUNING.pushCooldownMs;
      this.pushPulse = 1;
    }

    // Classic retains legacy stall assistance; Trick Deck deliberately makes a stall a
    // recoverable risk via hop + BSOD tailwind + held parachute, without an auto-shove.
    if (!pad || !pad.noAutoNudge) {
      const nudge = stallNudgeStep({ crawlMs: this._crawlMs || 0, nudging: !!this._nudging }, {
        grounded, braking: !!(pad && (pad.brake || pad.airBrake)), slopeDeg: this.groundAngleDeg, vx, vy, stepMs, gravityPxS2: phys.gravityPxS2,
      });
      this._crawlMs = nudge.crawlMs;
      this._nudging = nudge.nudging;
      vx += nudge.dvx;
      vy += nudge.dvy;
    } else { this._crawlMs = 0; this._nudging = false; }

    // hop / bump jump (Space) with coyote time and input buffer
    if (this.hopBufferMs > 0 && this.msSinceContact < TUNING.hopCoyoteMs) {
      const beforeHopVy = vy;
      const vn = vx * nx + vy * ny;
      const want = TUNING.hopPxS * (phys.hopMul || 1);
      if (vn < want) {
        vx += nx * (want - vn);
        vy += ny * (want - vn);
      }
      this.hopBufferMs = 0;
      this.msSinceContact = TUNING.groundedGraceMs + 1; // leave the ground immediately
      this.hopPulse = 1;
      this._sinceLaunchMs = 0;
      // Hop and AirBrake are INDEPENDENT vertical impulses. Even if the brake
      // happened on a prior coyote substep, Space release can truncate just
      // the upward velocity this NEW Hop added, never the paid AirBrake part.
      this._protectedHopExtraVyPxS = this.airBrakeLiftProtected
        ? Math.max(0, beforeHopVy - vy) : 0;
      this._playerHopActive = !!pad.variableHop;
      this._playerHopElapsedMs = 0;
    }
    if (this._playerHopActive) {
      this._playerHopElapsedMs += stepMs;
      if (!pad.hop && this._playerHopElapsedMs >= TUNING.hopMinimumHoldMs) {
        // Cut only the extra launch velocity introduced by the player Hop.
        // A previously paid AirBrake kick has its OWN protected ascent; never
        // zero that separately bought vertical impulse. The stored extra is
        // attenuated by the same quad drag as vy on subsequent physics steps.
        if (this.airBrakeLiftProtected) {
          // Gravity may have already spent part of the original Hop ascent.
          // Shortening a jump must never create an instant downward shove:
          // remove no more than the upward velocity still present NOW.
          if (vy < 0) vy = Math.min(0, vy + (this._protectedHopExtraVyPxS || 0));
          // When gravity has ALREADY crossed the apex, Hop release does not
          // change positive downward velocity or artificially pause the fall.
        } else if (vy < 0) vy = 0;
        this._protectedHopExtraVyPxS = 0;
        this._playerHopActive = false;
      } else if (vy >= 0) {
        this._protectedHopExtraVyPxS = 0;
        this._playerHopActive = false;
      }
    }

    // ground snap / crest smoothing: kill the small upward drift off convex crests (see TUNING.snap*)
    if (this._sinceLaunchMs > TUNING.snapQuietMs && this._groundRunMs >= TUNING.snapMinGroundMs
      && this.msSinceContact < TUNING.snapWindowMs && this.dropAheadDeg < TUNING.snapMaxDropDeg
      && pmath.hypot(vx, vy) > TUNING.snapMinSpeedPxS && !chute && !airBrakeKickedThisStep) {
      const vn2 = vx * nx + vy * ny;
      if (vn2 > TUNING.snapKeepVnPxS && vn2 < TUNING.snapMaxVnPxS) {
        const cut = vn2 - TUNING.snapKeepVnPxS;
        vx -= nx * cut;
        vy -= ny * cut;
        this.snapSteps = (this.snapSteps || 0) + 1;
      }
    }

    // conveyor belt (W6): a belt carries the sled while it is touching the ground, with no input from the
    // player. It is a direct velocity change, not a multiplier on the W-key kick, because a belt that only
    // works while you hold push is not a belt.
    if (grounded && phys.beltDrivePxS2 > 0) {
      const belt = conveyorStep({
        grounded, drivePxS2: phys.beltDrivePxS2, direction: phys.beltDirection,
        slopeDeg: this.groundAngleDeg, stepMs,
      });
      vx += belt.dvx;
      vy += belt.dvy;
    }

    // geyser vent (W6, Vertigo Vents): a grounded sled over a vent is thrown upward, on a cooldown so the
    // vent cannot re-fire every step and pin the sled in the air. The data carried this since the biome
    // shipped but nothing read it, so the mechanic did not exist; this is its consumer.
    if (phys.geyserLaunch) {
      const vent = geyserStep({ grounded, launch: phys.geyserLaunch, cooldownLeftMs: this.geyserCooldownMs || 0 });
      if (vent.fire) {
        vy = Math.min(vy, 0) + vent.dvy;
        this.geyserCooldownMs = vent.cooldownMs;
        this._sinceLaunchMs = 0;
      }
    }

    Body.setVelocity(b, { x: fromPxS(vx), y: fromPxS(vy) });
    // velocity going INTO this step's collision solve: Matter has already removed the normal component when
    // endStep() runs, so this is the only honest source for the touchdown impact speed
    this._preVx = vx;
    this._preVy = vy;

    // ---- rotation (rad/s) ----
    let w = (Body.getAngularVelocity(b) * 1000) / BASE_STEP_MS;
    const tilt = clamp(((pad && pad.tilt) || (this.corkscrewActive ? 0.72 : 0)), -1, 1) * (phys.tiltSign == null ? 1 : phys.tiltSign)
      * (phys.steerMul == null ? 1 : phys.steerMul);
    this._lastTilt = tilt;
    const g = this.grounded;
    const torqueDeg = phys.tiltTorqueDegS2 * (g ? TUNING.groundTiltMul : phys.airControl) * tilt;
    if (!g && tilt !== 0) {
      // Continuous flip input approaches a stable angular velocity. Once the
      // target is reached, holding the button no longer accelerates the flip.
      const desired = tilt * TUNING.flipTargetDegS * (phys.flipMul || 1) * DEG;
      const step = TUNING.flipAccelDegS2 * (phys.flipMul || 1) * DEG * dt;
      w += clamp(desired - w, -step, step);
    } else {
      w += torqueDeg * DEG * dt;
    }
    if (phys.scrambleJitterDegS2) w += (this.random.physicsScramble.next() * 2 - 1) * phys.scrambleJitterDegS2 * DEG * dt;
    if (!g && tilt === 0) {
      // hands off: spin bleeds off and the nose eases toward the travel direction, so a pitch-over at a lip does not tumble the sled
      w = airIdleSpin(w, b.angle, vx, vy, dt, TUNING, { etaMs: this.airEtaMs, slopeDeg: this.airSlopeDeg });
    }
    if (pad && pad.brake && !g) w *= pmath.exp(-TUNING.airBrakeAngularDamp * dt);
    if (chute) w *= pmath.exp(-2.5 * dt);
    const wMax = TUNING.maxAngularVelDegS * (phys.flipMul || 1) * DEG;
    w = clamp(w, -wMax, wMax);
    Body.setAngularVelocity(b, (w * BASE_STEP_MS) / 1000);
  }

  /**
   * Multiply linear velocity (Packet Burst kick, Overflow Firewall cut).
   * @param {number} k
   * @returns {void}
   */
  scaleVelocity(k) {
    if (!this.inWorld) return;
    const v = Body.getVelocity(this.body);
    Body.setVelocity(this.body, { x: v.x * k, y: v.y * k });
    // The variable-Hop release budget represents an actual share of upward
    // velocity. Hazards and sloppy-land wobble scale the WHOLE velocity;
    // preserving its unscaled old amount would erase purchased AirBrake lift
    // on later Space release. Match the authoritative velocity change.
    this._protectedHopExtraVyPxS = (this._protectedHopExtraVyPxS || 0) * k;
    this._sync();
  }

  /**
   * Set vertical speed upward (bounce pad).
   * @param {number} upPxS positive = up.
   * @returns {void}
   */
  launchUp(upPxS) {
    if (!this.inWorld) return;
    const v = Body.getVelocity(this.body);
    Body.setVelocity(this.body, { x: v.x, y: Math.min(v.y, -fromPxS(upPxS)) });
    this.msSinceContact = TUNING.groundedGraceMs + 1;
    this._sinceLaunchMs = 0;
    this._playerHopActive = false;
    this._protectedHopExtraVyPxS = 0; // other launch supersedes pending optional Hop hold
    this.chuteUsed = false;
    this.parachuteFuelMs = (this.canopyFuelFullMs || PHYSICS.parachuteDurationMs);
    this._sync();
  }

  /**
   * Spring rebound along the ground normal (Sky Jellyfish bouncySpring): keep the along-slope velocity and raise the
   * outward normal component to at least `upPxS` (BiomeEffects.springReboundVelocity). Matter 0.20 normalises
   * Body.setVelocity to the 1000/60 ms base step, so convert px/s with fromPxS. Resets contact/snap state like
   * launchUp, but never converts forward speed into extra bounce on a slope. A zero, negative or non-finite `upPxS`
   * is a no-op before any body or state change.
   * @param {number} upPxS desired outward normal speed, positive = away from the ground.
   * @param {number} groundAngleDeg slope under the sled (deg, clockwise positive = descending right).
   * @returns {void}
   */
  launchNormal(upPxS, groundAngleDeg) {
    // Zero, negative and non-finite requests are no-ops before the body or contact/snap state is touched.
    if (!this.inWorld || !this.body || !Number.isFinite(upPxS) || upPxS <= 0) return;
    const v = Body.getVelocity(this.body);
    const next = springReboundVelocity(toPxS(v.x), toPxS(v.y), groundAngleDeg, upPxS);
    Body.setVelocity(this.body, { x: fromPxS(next.vx), y: fromPxS(next.vy) });
    this.msSinceContact = TUNING.groundedGraceMs + 1;
    this._sinceLaunchMs = 0;
    this._playerHopActive = false;
    this._protectedHopExtraVyPxS = 0; // other launch supersedes pending optional Hop hold
    this.chuteUsed = false;
    this.parachuteFuelMs = (this.canopyFuelFullMs || PHYSICS.parachuteDurationMs);
    this._sync();
  }

  /**
   * Landing boost: add forward speed along the current travel direction (slope tangent when nearly stopped).
   * @param {number} pxS
   * @returns {void}
   */
  addForwardSpeed(pxS) {
    if (!this.inWorld) return;
    const v = Body.getVelocity(this.body);
    let vx = toPxS(v.x);
    let vy = toPxS(v.y);
    const sp = pmath.hypot(vx, vy);
    let dx;
    let dy;
    if (sp > 30) { dx = vx / sp; dy = vy / sp; } else { dx = pmath.cos(this.groundAngleDeg * DEG); dy = pmath.sin(this.groundAngleDeg * DEG); }
    vx += dx * pxS;
    vy += dy * pxS;
    Body.setVelocity(this.body, { x: fromPxS(vx), y: fromPxS(vy) });
    this._sync();
  }

  /** Sloppy landing: shave speed and damp the spin so the wobble recovers. @param {number} keep @returns {void} */
  wobble(keep) {
    if (!this.inWorld) return;
    this.scaleVelocity(keep);
    Body.setAngularVelocity(this.body, Body.getAngularVelocity(this.body) * 0.3);
  }

  /**
   * Teleport (respawn).
   * @param {number} x
   * @param {number} y
   * @param {number} angleDeg
   * @param {number} vxPxS
   * @param {number} vyPxS
   * @returns {void}
   */
  setPose(x, y, angleDeg, vxPxS, vyPxS) {
    const b = this.body;
    if (!this.inWorld) {
      this.world.add(b);
      this.inWorld = true;
    }
    Body.setAngle(b, angleDeg * DEG);
    Body.setAngularVelocity(b, 0);
    // place the origin at (x, y): COM = origin + R * off
    const c = pmath.cos(b.angle);
    const s = pmath.sin(b.angle);
    Body.setPosition(b, { x: x + c * this.off.x - s * this.off.y, y: y + s * this.off.x + c * this.off.y });
    Body.setVelocity(b, { x: fromPxS(vxPxS), y: fromPxS(vyPxS) });
    this.msSinceContact = 999;
    this._contactFlag = false;
    this.touchdownVx = undefined;
    this.touchdownVy = undefined;
    this._landSettleMs = 0;
    this.boostMs = 0;
    this._groundRunMs = 0;
    this._sinceLaunchMs = 0;
    this.parachuteMs = 0;
    this.parachuteFuelMs = (this.canopyFuelFullMs || PHYSICS.parachuteDurationMs);
    this.chuteUsed = false;
    this.airtimeMs = 0;
    this.airBrakeActive = false;
    this.airBrakePressPending = false;
    this.airBrakeKickUsed = false; // respawn is a new flight/life
    this.airBrakeLiftProtected = false;
    this._protectedHopExtraVyPxS = 0;
    this.airBrakeKickPulse = 0;
    this._playerHopActive = false;
    this._playerHopElapsedMs = 0;
    this.hopBufferMs = 0;
    this._sync();
  }

  /** Remove the body from physics and hide the drawing (crash). @returns {void} */
  vanish() {
    if (this.inWorld) {
      this.world.remove(this.body);
      this.inWorld = false;
    }
    this.hidden = true;
    this.windPomAnchor = null; // Hide the tether as soon as the rider vanishes.
    if (this.gfx) this.gfx.clear();
  }

  /**
   * Build the per-frame state consumed by TrickTracker.
   * @param {number} timeMs
   * @param {number} dtMs
   * @returns {import('../systems/TrickTracker.js').SledFrameState}
   */
  getFrameState(timeMs, dtMs) {
    this._sync();
    return {
      timeMs,
      dtMs,
      x: this.x,
      y: this.y,
      vx: this.vx,
      vy: this.vy,
      impactVx: this.touchdownVx,
      impactVy: this.touchdownVy,
      angleDeg: this.angleDeg,
      heliDeg: this.heliPhase,
      // the helicopter DRAWING's spin angle: TrickTracker drops the landing grade when it is not near a whole turn
      midSpin: this.heliPhase,
      angularVelDegS: ((Body.getAngularVelocity(this.body) * 1000) / BASE_STEP_MS) / DEG,
      grounded: this.grounded,
      groundAngleDeg: this.groundAngleDeg,
      input: {
        heli: this.grounded ? 0 : this.heliInput,
        corkscrew: this.corkscrewActive,
        airBrake: this.airBrakeActive,
        parachute: this.parachuteMs > 0,
      },
      crashed: false,
    };
  }

  /**
   * Sync graphics to body.
   * @param {number} [dtMs=16.7] frame time, drives pose smoothing (the helicopter spin is stepHeli, per tick).
   * @returns {void}
   */
  render(dtMs = 16.7) {
    if (this.destroyed || this.hidden || !this.gfx) return;
    const k = 1 - pmath.exp(-dtMs / 70);
    this.squash = Math.max(0, (this.squash || 0) - dtMs / 160);
    const pose = this.pose;
    const tiltN = this._lastTilt || 0;
    const airbrake = this.airBrakeActive ? 1 : 0;
    const tuck = this.tucked ? 1 : 0;
    const targetPhi = airbrake ? -28 : lerp(8 + tiltN * 24, 64, tuck);
    pose.phi = lerp(pose.phi, targetPhi, k);
    pose.tuck = lerp(pose.tuck, tuck, k);
    pose.brake = lerp(pose.brake, airbrake, k);
    pose.chute = lerp(pose.chute, this.parachuteMs > 0 ? 1 : 0, 1 - pmath.exp(-dtMs / 90));
    this._draw();
  }

  /**
   * Helicopter spin, advanced once per fixed simulation tick (issue #59): TrickTracker scores heliPhase, so it
   * must not follow the display frame rate. Spins up while an arrow is held in the air and eases back to the
   * nearest full turn on the ground.
   * @param {number} dtMs the tick (ms)
   * @returns {void}
   */
  stepHeli(dtMs) {
    if (!this.grounded && this.heliInput) {
      this.heliVel = lerp(this.heliVel, this.heliInput * TUNING.heliSpinDegS, 1 - pmath.exp(-dtMs / 60));
    } else {
      this.heliVel = lerp(this.heliVel, 0, 1 - pmath.exp(-dtMs / 60));
    }
    this.heliPhase += (this.heliVel * dtMs) / 1000;
    if (this.grounded && Math.abs(this.heliVel) < 120) {
      const target = Math.round(this.heliPhase / 360) * 360;
      this.heliPhase = lerp(this.heliPhase, target, 1 - pmath.exp(-dtMs / 50));
    }
    if (Math.abs(this.heliPhase) > 36000) this.heliPhase %= 360; // TrickTracker ignores the resulting jump (> 720 deg)
  }

  /**
   * A cosmetic colour as an int, or the palette fallback. Cosmetics resolve to hex strings; Phaser's
   * Graphics wants an int, and converting here keeps it out of the draw loop's hot path.
   * @param {'rider'|'glow'} key @param {number} fallback @returns {number}
   */
  _cosmetic(key, fallback) {
    const v = this.look && this.look[key];
    if (typeof v !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(v)) return fallback;
    return parseInt(v.slice(1), 16);
  }

  _draw() {
    const g = this.gfx;
    const pal = this.palette;
    const b = this.body;
    g.clear();
    this._sync();

    const ang = b.angle;
    const c = pmath.cos(ang);
    const s = pmath.sin(ang);
    const ox = b.position.x - (c * this.off.x - s * this.off.y);
    const oy = b.position.y - (s * this.off.x + c * this.off.y);
    let sx = pmath.cos(this.heliPhase * DEG);
    // keep a hair of width so the edge-on silhouette stays visible
    if (Math.abs(sx) < 0.12) sx = sx < 0 ? -0.12 : 0.12;
    const edgeOn = 1 - Math.abs(sx);
    const flip = sx < 0;
    const jx = this.scrambled ? (this.random.visualSled.next() - 0.5) * 3 : 0;
    const jy = this.scrambled ? (this.random.visualSled.next() - 0.5) * 3 : 0;
    const sq = this.squash || 0;
    const wx = 1 + 0.12 * sq;
    const P = (lx0, ly0) => {
      const ly = 11 + (ly0 - 11) * (1 - 0.22 * sq);
      const lx = lx0 * wx;
      return { x: ox + c * lx * sx - s * ly + jx, y: oy + s * lx * sx + c * ly + jy };
    };
    const poly = (pts, fill, fa, stroke, w) => {
      const m = pts.map((p) => P(p[0], p[1]));
      if (fill != null) {
        g.fillStyle(fill, fa);
        g.fillPoints(m, true);
      }
      if (stroke != null) {
        g.lineStyle(w, stroke, 1);
        g.strokePoints(m, true, true);
      }
    };
    const line = (pts, color, w, alpha = 1) => {
      g.lineStyle(w, color, alpha);
      g.strokePoints(pts.map((p) => P(p[0], p[1])), false, false);
    };
    const limb = (a, bb, color, w = 2.6) => {
      line([a, bb], pal.bg, w + 2);
      line([a, bb], color, w);
    };

    const flicker = this.invulnerableMs > 0 && Math.floor(this._time / 70) % 2 === 0;
    const aMul = flicker ? 0.35 : 1;
    // A scramble deliberately overrides cosmetics: the effect's whole point is that the player loses
    // control of their look for a moment, so it must not be cancelled by a paid hue.
    const sledCol = this.scrambled ? pal.magenta : this._cosmetic('glow', pal.cyan);
    const riderCol = this.scrambled ? pal.lime : this._cosmetic('rider', pal.magenta);

    // parachute canopy (world-up, drawn first so the rider overlaps the shrouds)
    if (this.pose.chute > 0.02) this._drawChute(g, ox, oy, this.pose.chute, c, s);

    // ----- sled -----
    const pose = this.pose;
    // runner (curved prow), struts, deck
    line([[-24, 11], [18, 11], [25, 9], [29, 4]], pal.bg, 4.5);
    line([[-24, 11], [18, 11], [25, 9], [29, 4]], pal.lime, 2.2, aMul);
    line([[-14, 11], [-14, 5]], sledCol, 1.5, aMul);
    line([[14, 11], [14, 5]], sledCol, 1.5, aMul);
    poly([[-23, 1.5], [21, 1.5], [28, -1], [22, 5.5], [-23, 5.5]], sledCol, 0.4 * aMul, sledCol, 1.5);
    // deck grid ticks (data motif)
    for (let i = -18; i <= 16; i += 7) line([[i, 2.2], [i, 5]], pal.bg, 1, 0.7);

    // Micro glow-up: the Neon Sled Drone replaces the neon rider (draw only; the collision parts in _buildBody
    // are unchanged, so the drone is exactly as hittable as the rider it replaces). `lastRiderShape` records
    // what this frame drew, for the built-game gate.
    const shape = this.look && this.look.riderShape === 'drone' ? 'drone' : 'default';
    this.lastRiderShape = shape;
    if (shape === 'drone') {
      this._drawDrone(g, P, poly, line, limb, riderCol, aMul);
    } else {
      this.drone = null;
      this._drawRider(g, P, poly, limb, riderCol, aMul, sx, flip);
    }

    // air-brake flap
    if (pose.brake > 0.05) {
      const h = 18 * pose.brake;
      poly([[24, 2], [32, 2 - h], [34, 2 - h], [28, 2]], pal.amber, 0.6, pal.amber, 1.2);
    }

    // helicopter blur ring (edge-on cue)
    if (edgeOn > 0.5 && Math.abs(this.heliVel) > 200) {
      const p0 = P(0, -2);
      g.lineStyle(1, pal.cyan, 0.5);
      g.strokeEllipse(p0.x, p0.y, 56, 14);
    }

    // shield (Hashed Backup)
    if (this.shield) {
      const p0 = P(0, -6);
      const pulse = 0.55 + 0.25 * pmath.sin(this._time / 90);
      g.lineStyle(1.5, pal.amber, pulse);
      g.strokeCircle(p0.x, p0.y, 30);
      g.fillStyle(pal.amber, 0.08);
      g.fillCircle(p0.x, p0.y, 30);
    }
  }

  /** The neon rider (the default rider shape): legs, torso, arm, helmet and visor. */
  _drawRider(g, P, poly, limb, riderCol, aMul, sx, flip) {
    const pal = this.palette;
    const pose = this.pose;
    const phi = pose.phi * DEG;
    const hip = [-6, 0];
    const sh = [hip[0] + pmath.sin(phi) * 13, hip[1] - pmath.cos(phi) * 13];
    const head = [sh[0] + pmath.sin(phi) * 6.5, sh[1] - pmath.cos(phi) * 6.5];
    const nxp = pmath.cos(phi);
    const nyp = pmath.sin(phi);
    const torso = [
      [hip[0] - nxp * 4.2, hip[1] - nyp * 4.2],
      [sh[0] - nxp * 3.6, sh[1] - nyp * 3.6],
      [sh[0] + nxp * 3.6, sh[1] + nyp * 3.6],
      [hip[0] + nxp * 4.2, hip[1] + nyp * 4.2],
    ];
    // legs
    const knee = pose.brake > 0.5 ? [8, -6] : [lerp(6, 5, pose.tuck), lerp(-3.5, -7, pose.tuck)];
    const foot = pose.brake > 0.5 ? [19, -7] : [lerp(14, 12, pose.tuck), lerp(0.5, -0.5, pose.tuck)];
    limb(hip, knee, riderCol, 3);
    limb(knee, foot, riderCol, 3);
    poly(torso, riderCol, 0.8 * aMul, pal.bg, 1);
    g.lineStyle(1.2, riderCol, 1);
    g.strokePoints(torso.map((p) => P(p[0], p[1])), true, true);
    // arms
    const hand = pose.brake > 0.5 ? [sh[0] + 9, sh[1] - 9] : (this.heliInput && !this.grounded ? [sh[0] + 11, sh[1] - 3] : [12, -1]);
    limb(sh, hand, pal.amber, 2.4);
    // helmet + visor (visor faces travel direction, flips with the spin)
    const hp = P(head[0], head[1]);
    // Wind pom-pom must share the EXACT helmet pose transform: COM coordinates
    // and a fixed world-space Y offset drift away during flips and helicopter spins.
    this.windPomAnchor = P(head[0] + pmath.sin(phi) * 5.5, head[1] - pmath.cos(phi) * 5.5);
    g.fillStyle(pal.bg, 1);
    g.fillCircle(hp.x, hp.y, 5.8);
    g.fillStyle(pal.amber, 0.9 * aMul);
    g.fillCircle(hp.x, hp.y, 4.6);
    g.lineStyle(1, pal.bg, 1);
    g.strokeCircle(hp.x, hp.y, 4.6);
    const vs = P(head[0] + 2.6 * (flip ? -1 : 1) / Math.max(0.2, Math.abs(sx)) * Math.abs(sx), head[1] - 0.6);
    g.fillStyle(pal.cyan, 1);
    g.fillRect(vs.x - 1.5, vs.y - 1.6, 3, 3);
  }

  /**
   * The Neon Sled Drone (Micro glow-up): an RC micro drone riding the deck. A pod in the rider colour with a
   * cyan camera eye, a mast, two rotor arms, a spinning rotor disc at each tip and a light on each arm that
   * blinks from sled time, the two arms out of phase. All in local sled space through P, so it tilts, squashes
   * and spins (helicopter) with the sled exactly like the rider. Colours: the rider colour and palette keys
   * only (never danger), so under colourblind mode, where the rider colour is palette magenta, it is all palette.
   * Records `this.drone` ({rotors, lights}) for tests and the gate.
   */
  _drawDrone(g, P, poly, line, limb, riderCol, aMul) {
    const pal = this.palette;
    const pose = this.pose;
    const t = this._time || 0;
    // Tuck lowers the mast, lean pitches the pod a little (the same inputs that pose the rider).
    const drop = 3 * (pose.tuck || 0);
    const lean = Math.max(-0.5, Math.min(0.5, ((pose.phi || 0) - 8) * DEG * 0.35));
    const L = (x, y) => [x + (y - 0) * lean * -0.4, y + drop * (y < -6 ? 1 : 0.4)];
    // pod: dark backing first so it reads on any backdrop, then the frame
    const pod = [L(-16, 1), L(-13, -7), L(4, -9), L(11, -6), L(13, 1)];
    poly(pod, pal.bg, 0.9, null, 0);
    poly(pod, riderCol, 0.45 * aMul, riderCol, 1.4);
    // skid struts down to the deck
    line([L(-9, 1), L(-9, 1.8)], riderCol, 1.2, aMul);
    line([L(7, 1), L(7, 1.8)], riderCol, 1.2, aMul);
    // camera eye at the nose
    const eye = P(...L(9, -4));
    g.fillStyle(pal.bg, 1);
    g.fillCircle(eye.x, eye.y, 2.8);
    g.fillStyle(pal.cyan, 1);
    g.fillCircle(eye.x, eye.y, 1.7);
    // mast and rotor arms
    const hub = L(-2, -14);
    // Drone skin has no helmet. Fasten the tether to the same transformed mast hub.
    this.windPomAnchor = P(hub[0], hub[1] - 2);
    limb(L(-2, -8), hub, riderCol, 2);
    const tips = [L(-16, -18), L(12, -18)];
    for (const tip of tips) limb(hub, tip, riderCol, 1.8);
    const rotors = [];
    const lights = [];
    tips.forEach((tip, i) => {
      // rotor disc: a flat ring of points in sled space (so it tilts with the sled), a translucent blur fill
      // and a cyan rim, then one blade turning fast from sled time
      const ring = [];
      for (let k = 0; k < 10; k++) {
        const a = (k / 10) * Math.PI * 2;
        ring.push(P(tip[0] + pmath.cos(a) * 8, tip[1] - 1.2 + pmath.sin(a) * 1.6));
      }
      g.fillStyle(pal.text, 0.14 * aMul);
      g.fillPoints(ring, true);
      g.lineStyle(1, pal.cyan, 0.65 * aMul);
      g.strokePoints(ring, true, true);
      const spin = t / 22 + i * 1.7;
      const bx = pmath.cos(spin) * 8;
      const blade = [P(tip[0] - bx, tip[1] - 1.2), P(tip[0] + bx, tip[1] - 1.2)];
      g.lineStyle(1.2, pal.text, 0.8 * aMul);
      g.lineBetween(blade[0].x, blade[0].y, blade[1].x, blade[1].y);
      rotors.push({ ring, blade: [blade[0].x, blade[0].y, blade[1].x, blade[1].y] });
      // the arm light: the two arms blink out of phase, 250 ms each
      const on = (Math.floor(t / 250) + i) % 2 === 0;
      const lp = P(tip[0] + (i ? -3 : 3), tip[1] + 1.2);
      const col = i ? pal.lime : pal.magenta;
      g.fillStyle(col, on ? 1 : 0.25);
      g.fillCircle(lp.x, lp.y, on ? 1.8 : 1.2);
      if (on) {
        g.fillStyle(col, 0.25 * aMul);
        g.fillCircle(lp.x, lp.y, 3.6);
      }
      lights.push({ on, color: col, x: lp.x, y: lp.y });
    });
    this.drone = { rotors, lights };
  }

  _drawChute(g, ox, oy, t, c, s) {
    const pal = this.palette;
    const w = 30 * t;
    const h = 20 * t;
    const cx = ox;
    const cy = oy - 40 - 12 * t + pmath.sin(this._time / 120) * 1.5;
    const n = 8;
    const pts = [];
    for (let i = 0; i <= n; i++) {
      const a = Math.PI + (Math.PI * i) / n;
      pts.push({ x: cx + pmath.cos(a) * w, y: cy + pmath.sin(a) * h });
    }
    // alternating stripes
    for (let i = 0; i < n; i++) {
      g.fillStyle(i % 2 ? pal.magenta : pal.cyan, 0.5);
      g.fillPoints([{ x: cx, y: cy }, pts[i], pts[i + 1]], true);
    }
    g.lineStyle(1.5, pal.cyan, 1);
    g.strokePoints(pts, true, true);
    // shrouds down to the rider
    const hitch = { x: ox - c * 2 * 1 + s * 12, y: oy - s * 2 - c * 12 };
    g.lineStyle(1, pal.text, 0.8);
    for (const i of [0, 3, 5, 8]) {
      g.strokePoints([pts[i], hitch], false, false);
    }
  }

  /** @returns {void} */
  destroy() {
    if (this.destroyed) return;
    this.destroyed = true;
    if (this.inWorld) {
      try {
        this.world.remove(this.body);
      } catch (e) { /* world may already be torn down on scene shutdown */ }
      this.inWorld = false;
    }
    if (this.gfx) {
      this.gfx.destroy();
      this.gfx = null;
    }
    this.body = this.body || null;
  }
}/** Cosmetic song billboard: one roadside pass per ACTUAL track identity change.
 * Artwork comes from catalog metadata via BillboardArt: the song's YouTube
 * thumbnail when it has a confirmed ID, otherwise the generic NOW PLAYING card.
 */
import {GAME_WIDTH,GAME_HEIGHT} from '../constants.js';
import {FONT_KEY,ellipsize,measureText} from '../ui/PixelFont.js';
import {GENERIC_ART_KEY,CATALOG_CACHE_KEY,billboardArtLoader,catalogTrack,trackYoutubeId,youtubeArtKey}
  from './BillboardArt.js';

// Sized to fit a sky lane above the rider: the rider sits near screen y = H/3,
// so an 82 px sign had no lane there and crossed the rider's silhouette.
export const BILLBOARD_WIDTH=80;
export const BILLBOARD_HEIGHT=56;
export const BILLBOARD_ART={w:72,h:40,y:-5};
/** Screen px from the sled's centre up to the top of the rider's head, padded. */
export const RIDER_HEAD_PX=18;
/** Clear gap (screen px) kept between the sign's bottom edge and the rider's head. */
export const RIDER_CLEAR_PX=RIDER_HEAD_PX+2;
/** Lowest the sign's centre sits when the rider is low on screen. */
export const BILLBOARD_LANE_Y=80;
/**
 * Depth layers. Background: behind the terrain mesh (depth 5), so the posts
 * vanish behind the slope the rider is on. Foreground: in front of the rider
 * (depth 20), with posts running off the bottom of the screen.
 */
export const BILLBOARD_DEPTH={background:-11,foreground:24};
/** Alpha while the sign still has to cross the rider (no clear lane at the top of the screen). */
export const BILLBOARD_BEHIND_RIDER_ALPHA=0.22;
export const BILLBOARD_LIFETIME_MS=14000;
export const BILLBOARD_FADE_MS=600;
/** Longest the sign waits off-screen for a thumbnail still loading before it goes out with the generic card. */
export const BILLBOARD_ART_WAIT_MS=1500;
// Phaser.Textures.FilterMode.LINEAR: the game runs pixelArt (NEAREST), which
// makes a 320x180 photo downscaled to 72x40 crunchy.
const LINEAR_FILTER=0;
// Per-AudioSynth announced track: survives scene restarts and retries without
// storing scene state on the audio object itself.
const announced=new WeakMap();
// Per-AudioSynth pass count, so passes alternate background / foreground across runs.
const passes=new WeakMap();

/** Layer for the n-th pass (0-based): background first, then alternating. */
export function billboardLayer(passIndex){
  return (Number(passIndex)||0)%2===1?'foreground':'background';
}
/** Target screen y of the sign's centre: the sky lane above the rider, kept above ACTUAL nearby terrain. */
export function billboardScreenY(riderScreenY,groundScreenY=Infinity){
  const half=BILLBOARD_HEIGHT*.5;
  let y=BILLBOARD_LANE_Y;
  if(Number.isFinite(riderScreenY))y=Math.min(y,riderScreenY-RIDER_CLEAR_PX-half);
  if(Number.isFinite(groundScreenY))y=Math.min(y,groundScreenY-half-8);
  return Math.max(half+8,y);
}
/**
 * Post length below the sign (screen px). Both layers run to past the bottom of
 * the screen: in the background the terrain mesh hides everything below the
 * slope; in the foreground the posts leave the frame.
 */
export function billboardPostLength(signScreenY){
  return Math.max(6,GAME_HEIGHT+8-(signScreenY+BILLBOARD_HEIGHT*.5));
}
/**
 * Visible slice of a title wider than the sign at scroll offset `offsetPx`:
 * whole characters only, like an LED ticker. No crop scissor (Phaser's DBT
 * crop clipped the top of the glyphs under the run camera).
 */
export function tickerWindow(text,offsetPx,maxPx=BILLBOARD_TITLE_PX){
  const s=String(text);
  // First start index whose tail fits: the ticker never scrolls past the end.
  let tail=0;
  while(tail<s.length-1&&measureText(s.slice(tail))>maxPx)tail++;
  // Start at the first character beginning at or after the offset (x of char i = width of s[0..i) + 1 gap).
  let i=0;
  while(i<tail&&(i?measureText(s.slice(0,i))+1:0)<offsetPx)i++;
  let j=i;
  while(j<s.length&&measureText(s.slice(i,j+1))<=maxPx)j++;
  return s.slice(i,Math.max(i+1,j));
}
export function billboardScreenX(startX,cameraTravelPx,elapsedMs,allowAutoPass=true){
  if(!Number.isFinite(startX))return GAME_WIDTH+80;
  const travel=Math.max(0,Number(cameraTravelPx)||0);
  const automatic=allowAutoPass&&Number.isFinite(elapsedMs)?Math.max(0,elapsedMs)*0.077:0;
  return startX-Math.max(travel,automatic);
}
export function billboardPulseScale(dance){
  const p=Number.isFinite(dance)?Math.max(0,Math.min(1,dance)):0;
  return {x:1+0.045*p,y:1-0.035*p};
}
/** Sign title at 1x pixel-font scale: drop "(subtitle)" / " - part" tails first, then ellipsize to the sign. */
export function billboardTitle(title){
  const full=String(title||'').toUpperCase().trim();
  const short=full.replace(/\s*\(.*$/,'').replace(/\s+-\s+.*$/,'').trim()||full;
  return ellipsize(short,BILLBOARD_TITLE_PX);
}
/** Room for the title on the sign, in unscaled font px. */
export const BILLBOARD_TITLE_PX=BILLBOARD_WIDTH-6;
/**
 * Marquee scroll (px) for a title `travelPx` wider than the sign: hold, scroll
 * at 20 px/s, hold at the end, jump back. Zero when it fits.
 */
export function marqueeOffset(elapsedMs,travelPx){
  if(!(travelPx>0)||!Number.isFinite(elapsedMs))return 0;
  const hold=900,scroll=travelPx/0.02,t=Math.max(0,elapsedMs)%(hold*2+scroll);
  return Math.round(Math.max(0,Math.min(travelPx,(t-hold)*0.02)));
