const DEG = Math.PI / 180;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
/** Minimum delay between a crash and GameOver so the explosion reads (must stay <= TIMING.crashToGameOverMs). */
const CRASH_TO_GAMEOVER_MS = Math.min(950, TIMING.crashToGameOverMs);
const SAFE_SAMPLE_EVERY_MS = 120;
const SAFE_HISTORY_MS = 3000;
const SLOWMO_CAP_MS = 3000;
/** Spawn this far past terrain x=0 so the rear runner has ground under it. */
const SPAWN_RUNIN_PX = 44;
const TUTORIAL_KEY = 'bb.tutorialDone';
const TUCK_SHOWS_KEY = 'bb.tuckShows';
/**
 * First-run hint triggers (the scheduling rules live in systems/HintScheduler.js). Kept here, not in PhysicsTuner.
 * hop: show when the next ground hazard is within HOP_HINT_LEAD_S of travel (but at least HOP_HINT_MIN_PX); other hints are
 * held back while it is within HOP_DANGER_S so they cannot eat the warning window. flip: show on the approach to a launch lip.
 */
const HOP_HINT_LEAD_S = 1.2;
const HOP_HINT_MIN_PX = 350;
const HOP_HINT_MAX_PX = 1300;
const HOP_DANGER_S = 3.4;
const FLIP_APPROACH_S = 1.3;
const FLIP_APPROACH_MIN_PX = 160;
const FLIP_AIR_MS = 250;
const BOOST_HINT_MS = 2200;
/** The tuck hint (an advanced technique) waits for this much run time and for the first landing. */
const TUCK_HINT_MIN_RUN_MS = 12000;
/** The speed -> zoom curve (three stages, floor 0.45) lives in systems/CameraZoom.js since the readable-chaos pass. */
/** Extra look-ahead (px, on top of TUNING.lookAheadMaxPx) that ramps in between 600 and 1000 px/s; the follow lag eats the base look-ahead at speed. */
const LOOK_FAR_EXTRA_PX = 90;
/** Readable chaos: a further look-ahead between 850 and 1300 px/s. The 5.5 /s follow lags speed / 5.5 px behind (218 px at 1200), which left the rider ~130 px in. */
const LOOK_ULTRA_EXTRA_PX = 110;
/** The rider is never allowed closer than this many screen px to the left edge. */
const RIDER_MIN_SCREEN_X = 36;
const smooth01 = (t) => { const c = clamp(t, 0, 1); return c * c * (3 - 2 * c); };
/** Production uses actual Matter bounds; fallback supports legacy scene test doubles. */
const sledLeftCollisionEdge = (sled) => Number.isFinite(sled?.body?.bounds?.min?.x) ? sled.body.bounds.min.x : sled.x - 20;

/** Tutorial hints already completed on this device. SaveStore.sanitizeSettings drops unknown keys, so use our own key. */
function loadTutorialDone() {
  try {
    const raw = globalThis.localStorage && globalThis.localStorage.getItem(TUTORIAL_KEY);
    const arr = raw ? JSON.parse(raw) : [];
    return new Set(Array.isArray(arr) ? arr : []);
  } catch (e) { return new Set(); }
}
function saveTutorialDone(set) {
  try { if (globalThis.localStorage) globalThis.localStorage.setItem(TUTORIAL_KEY, JSON.stringify([...set])); } catch (e) { /* ignore */ }
}

/** How many times the tuck hint has been shown on this device (it is retired after TUNING.tuckHintMaxShows). */
function loadTuckShows() {
  try {
    const n = Number(globalThis.localStorage && globalThis.localStorage.getItem(TUCK_SHOWS_KEY));
    return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
  } catch (e) { return 0; }
}
function saveTuckShows(n) {
  try { if (globalThis.localStorage) globalThis.localStorage.setItem(TUCK_SHOWS_KEY, String(n)); } catch (e) { /* ignore */ }
}

export class RunScene extends Phaser.Scene {
  constructor() {
    super(SCENES.RUN);
  }

  // ------------------------------------------------------------------ lifecycle

  create() {
    const reg = this.registry;
    this.content = reg.get(REG.CONTENT) || { chunks: [], hazards: {}, powerups: {}, terrainMods: {}, palettes: {} };
    this.inputRouter = reg.get(REG.INPUT) || null;
    this.saveStore = reg.get(REG.SAVE_STORE) || null;
    this.settings = reg.get(REG.SETTINGS) || {};
    // One-shot edges (Esc that closed a menu view, Space that retried, ...) pile up while no scene polls the router; a
    // stale `pressed.pause` paused the run on its first frame. Drop them before the run starts.
    try { if (this.inputRouter) this.inputRouter.poll(); } catch (e) { /* ignore */ }
    this.palette = getPalette(this.game);
    // RunScene is one instance across runs and the palette above is the base one: forget the previous run's biome, or a
    // retry that ends where it began (Debutmont) would skip its opening repaint, motif and BIOME_ENTER (#65).
    this._biomeId = undefined;
    this._lookId = undefined; // #65 presentation: the look follows the same reset
    // W4 cosmetics: resolved ONCE per run, from the profile, for the same reason the biome mask is: the
    // sled, the trail and the drawn colours must not disagree with each other mid-run.
    this.look = this._resolveLook();
    // A ghost replay (issue #56) is driven entirely by its tape header: the recorded course, loadout and
    // upgrades, never the current profile (which may have levelled up and enabled new biomes since).
    this._replayTape = reg.get(REG.GHOST_REPLAY) || null;
    if (this._replayTape) reg.remove(REG.GHOST_REPLAY);
    const replay = this._replayTape;
    // Replay Contract R-1..R-4: a replay resolves daily rule, Sync Level and Kodiak/magnet flags from the recorded
    // tape/manifest, never from the clock, the live profile or the live registry flags.
    const rp = replay ? resolveReplaySetup(replay, { rules: DailyPatch.RULES }) : null;
    this.seed = replay ? String(replay.seed) : String(reg.get(REG.SEED) != null ? reg.get(REG.SEED) : 'default');
    // Named seeded streams for this run (issue #59). Rebuilt from the seed on every create.
    this.runRandom = runRandomStreams(this.seed);
    this.simClock = new SimClock();
    // W3: resolved ONCE per run, from the registry (a daily run sets the date-derived mask). Never
    // re-read mid-run, so the terrain, the stats scope and the saved record cannot disagree.
    const maskReg = reg.get(REG.BIOME_MASK);
    this.biomeMask = replay ? (Number(replay.biomeMask) || 0) >>> 0 : Number.isFinite(maskReg) ? maskReg >>> 0 : 0;
    this.startedAt = Date.now();
    this.runId = `${this.startedAt}-${this.seed}`;
    // A manual pause is a distinct session, never a death or title transition.
    // Audio can pair and cancel turntable effects without guessing scene state.
    this._manualPauseSeq = 0;
    this._manualPausePending = false;

    // Decision 2: is this the OFFICIAL Daily? Only when the DAILY RUN item asked for it (REG.DAILY_OFFICIAL)
    // AND the seed is today's daily seed. Any other run on a `daily-YYYY-MM-DD` seed is a practice run.
    // The today check means a retry or a pause-restart after 00:00 UTC cannot back-fill yesterday.
    const seedDay = DailyPatch.dateKeyFromSeed(this.seed);
    const todayKey = DailyPatch.getDailyInfo().dateKey;
    this.dailyOfficial = !replay && reg.get(REG.DAILY_OFFICIAL) === true && seedDay !== null && seedDay === todayKey;
    // Separate ranked Daily lane. A typed seed, Gym or stale-date retry
    // can NEVER turn itself into an official competitive Draft.
    this.dailyMode=this.dailyOfficial&&reg.get(REG.DAILY_MODE)==='draft'?'draft':'classic';
    // daily rule (read ONCE per run). A run on a daily seed plays THAT date's rule (decision 2: a practice
    // run of a past date replays that date, FAIRNESS-2); every other run plays today's rule as before.
    const seedDayInfo = seedDay ? DailyPatch.infoForDateKey(seedDay) : null;
    const daily = rp ? { rule: rp.dailyRule } : seedDayInfo ? { rule: seedDayInfo.rule } : DailyPatch.getDailyInfo();
    this.dailyRuleId = (daily && daily.rule && daily.rule.id) || 'none';
    // W4 loadout: the boosts the player switched on, read from the profile. Absent profile or absent
    // boosts means a clean run, which is the default-off rule.
    // The owned set (`unlocked.boosts`, granted at Sync Level 8 / 15) gates them: a toggle switched on
    // before the boost is unlocked does nothing and does not mark the run modded (Boosts.boostEffects).
    const prof = this.registry.get(REG.PROFILE) || {};
    this.bsodGym = !replay && reg.get(REG.BSOD_GYM) === true && prof.bsodGym?.owned === true;
    this.loadout = { boosts: (prof && prof.boosts && typeof prof.boosts === 'object') ? { ...prof.boosts } : {} };
    const owned = prof && prof.unlocked && typeof prof.unlocked === 'object' ? prof.unlocked.boosts : null;
    this.unlockedBoosts = owned && typeof owned === 'object' ? { ...owned } : {};
    // Permanent upgrades are opt-in, frozen for the run, and never applied to official Dailies.
    this.upgradeRun = upgradeLoadoutForRun(prof, { daily: this.dailyOfficial });
    if(this.dailyMode==='draft'){
      // Draft completely disregards owned/upgraded ranks. The saved one-run
      // snapshot comes ONLY from the free fixed-budget editor, never BANK.
      const proposed=reg.get(REG.DAILY_DRAFT_RANKS);
      const ranks=draftActiveRanks(validDraftRanks(proposed)?proposed:{});
      this.upgradeRun={enabled:Object.keys(ranks).length>0,ranks,effects:upgradeEffects(ranks)};
    }
    if (replay) {
      // The recorded upgrade ranks and boosts, exactly; nothing from the live profile.
      const ranks = replay.upgradeRanks && typeof replay.upgradeRanks === 'object' ? { ...replay.upgradeRanks } : {};
      this.upgradeRun = { enabled: Object.keys(ranks).length > 0, ranks, effects: upgradeEffects(ranks) };
      const boosts = Array.isArray(replay.boosts) ? replay.boosts : [];
      this.loadout = { boosts: Object.fromEntries(boosts.map((id) => [id, true])) };
      this.unlockedBoosts = Object.fromEntries(boosts.map((id) => [id, true]));
    }
    this.upgradeFx = this.upgradeRun.effects;
    // Shard Magnets drop from Sync Level 5, and on every Daily (equal pickups on an official board).
    // A ghost replay restores the recorded choice so the course matches.
    this.magnetsDrop = rp ? rp.magnetsDrop
      : magnetsDropFor({ level: prof.level, daily: this.dailyOfficial === true || this.dailyMode === 'draft' });
    // Issue #47: hostile Kodiaks from the proposed Sync Level, never on Dailies or in the Gym (no event rule yet).
    this.kodiaksOn = rp ? rp.kodiaksOn
      : kodiaksEnabledFor({ level: prof.level, daily: this.dailyOfficial === true || this.dailyMode === 'draft', gym: this.bsodGym === true });
    // Packs are one type ('same') or mixed; a Settings switch while Marvin playtests which is better.
    this.kodiakPackMode = rp ? rp.kodiakPackMode
      : this.settings?.kodiakPacks === 'mixed' ? 'mixed' : 'same';
    this.kodiaks = [];
    this.kodiakNext = 0;
    this.kodiakShoveCdMs = 0; // immunity window after a bear shove (sim ms)
    // Player abilities and BSOD behavior are unchanged in the Gym. Only the
    // starting pose, pursuit gap/speed and post-catch retry are different.
    this.gymSetup = this.bsodGym ? gymSetupForProfile(prof) : null;
    // Every Gym attempt—including first entry—starts with the same short,
    // deterministic READY hold. Music may decorate it, never delay physics.
    this.gymReadyMs = this.bsodGym ? GYM_READY_MS : 0;
    this.gymBeatWaitMs = 0;
    this.gymBeatSnapshot = null;
    this.dailyMods = (daily && daily.rule && daily.rule.modifiers) || {};

    // pure systems — the exact same deterministic world factory is also used
    // when a Gym attempt restarts at its ORIGINAL launch position.
    this.terrain = this.createTerrainGenerator();
    this.heightFn = (x) => this.terrain.heightAt(x); // allocated once; reads this.terrain at call time
    this.score = new ScoreManager({ pxPerMeter: PIXELS_PER_METER });
    this.score.reset();
    this.tricks = new TrickTracker();
    this.glitch = new GlitchDirector({ seed: this.seed });
    this.tuner = new PhysicsTuner();

    // run state
    this.runTimeMs = 0;
    this.gymAttemptStartTimeMs = 0;
    this._leaving = false;
    this._hudMs = 0;
    this._despawn = [];
    this.currentPhys = null;
    this.crashed = false;
    this.crashTimerMs = 0;
    this.pendingCrash = null;
    this.trickCounts = {};
    this.bestCombo = 1;
    this.maxAirtimeMs = 0;
    this.lastTotal = 0;
    this.slowMs = 0;
    this.slowFactor = PHYSICS.slowFactor;
    this.scrambleMs = 0;
    this.boostMs = 0;
    this.boostFactor = 1;
    this.slowmoMs = 0;
    this.slowmoScale = 0.5;
    this.shieldCharges = 0;
    this.shieldSources = []; // B2: which pickup each shield charge came from (BiomeEffects.spendShieldSource)
    this._resetBiomeEffects();
    this.openingGraces = 0;
    this.activeZones = new Map();
    this.hazards = new Map();
    this.powerups = new Map();
    this.collectedPowerups = new Set();
    this.safeSamples = [];
    this._safeTimer = 0;
    this.resetCooldownMs = 0;
    this.shakeAmp = 0;
    this._contactQueue = [];
    this._landingShake = 0;
    this._frameDt = 16.7;
    this.hitStopMs = 0;
    this.blinkMs = 0;
    this._zoom = 1;
    this._zoomKick = 0;
    this._airTricks = 0;
    this.shardChain = 0;
    this.shardChainAt = -1e9;
    this.shardTotal = 0;
    this.shardCount = 0;
    this.nearMissCount = 0;
    this._steepMs = 0;
    this._landings = 0; // landings survived this run (the tuck hint waits for the first one)
    this.tuckShows = loadTuckShows();
    this.newBestDone = false;
    this.tutDone = loadTutorialDone();
    this.tutShown = new Set();
    this.tutTimers = { stall: 0 };
    this.hints = new HintScheduler({ done: this.tutDone });

    // physics world: manual stepping only
    const world = this.matter.world;
    world.autoUpdate = false;
    world.engine.positionIterations = 8;
    world.engine.velocityIterations = 6;
    world.engine.gravity.y = PHYSICS.gravityPxS2 / 1000;
    installTerrainContactFix(Phaser.Physics.Matter.Matter);
    installPortableMatter(Phaser.Physics.Matter.Matter); // #121: Matter's trig/pow/acos through pmath, before any body is built

    // visuals / entities
    this.cameras.main.setBackgroundColor(this.palette.bg);
    this.bg = new Background(this, this.palette);
    // #65 presentation: the biome glitch sets and the arcade bridge look. Render-only (BiomeFx reads the camera and the
    // run clock; nothing it does reaches terrain, physics, hazards or score).
    this._veil = 0;
    this._bridgeSpan = null;
    this._lookScratch = { veil: 0, lookId: null, t: -1 }; // bridgeLook's result, reused every frame
    this.biomeFx = new BiomeFx(this, this.palette, getPalette(this.game, null), this.bg);
    this.worldDance = new WorldDanceEnvelope();
    this.songBillboard = new SongBillboard(this);
    // Retain a live MediaQueryList so an OS reduced-motion change is seen
    // without creating a new query object every render frame.
    try { this._worldDanceMotionQuery=typeof matchMedia==='function'
      ?matchMedia('(prefers-reduced-motion: reduce)'):null; }
    catch { this._worldDanceMotionQuery=null; }
    this.mesh = new TerrainMesh(this, this.palette, this.content.terrainMods);
    // #253: BEST/DIED HERE are presentation. Their lookahead height reads must
    // never pre-generate terrain beyond the chunks already joined in Matter.
    this.markerHeightFn = (x) => joinedMarkerHeight(x, this.mesh.chunks);
    this.fx = new Fx(this, this.palette);
    this.trail = new TrailParticles(this, this.palette, this.look && this.look.trail);
    this.shardField = new ShardField(this, this.palette);
    this.airTelegraph = new AirTelegraph(this, this.palette);
    this.groundTelegraph = new GroundTelegraph(this, this.palette);
    this.teleTracker = new TelegraphTracker();
    this._teleMarks = [];
    this.streaks = this.add.graphics().setDepth(12).setBlendMode(Phaser.BlendModes.ADD);
    this.flashRect = this.add.rectangle(0, 0, GAME_WIDTH, GAME_HEIGHT, 0xffffff, 0)
      .setOrigin(0).setScrollFactor(0).setDepth(100);
    // B0 `blind`: a dimming layer under the flash (the HUD is a separate scene above it, so it stays readable).
    // Fill alpha 1 and object alpha 0: a Rectangle draws fillAlpha x alpha, so updateBlindOverlay's alpha is the opacity.
    this.blindRect = this.add.rectangle(0, 0, GAME_WIDTH, GAME_HEIGHT, this.palette.bg, 1)
      .setOrigin(0).setScrollFactor(0).setDepth(99).setAlpha(0);

    // initial terrain buffer, then the sled on the surface
    this._chunkQueue = new Map(); // a retry re-enters create() on this instance: no stale queued chunks
    // The scene instance outlives the run (scene.start re-enters create()). The biome announcement compares the sled's
    // biome with the last one it saw (`_biomeId`, reset above, before the look reads it). Before #140 the palette
    // repaint also rebuilt terrain colliders, so this affected physics by session position; since #140 it is a
    // presentation/cue reset. Keep every run like run #1.
    // Presentation state of the previous run (a stale boost hint at run start, a stale POWERUP_EXPIRED id):
    this.lastBoost = null;
    this.boostId = null;
    // Defensive: update() rewrites these every frame, so today they carry nothing over.
    this._hopped = false;
    this._pushed = false;
    this.streamTerrain(0);
    const start = this.safeStartPosition();
    // spawn a few body-lengths in so the rear runner is over solid ground (terrain begins exactly at start.x)
    const spawnX = start.x + SPAWN_RUNIN_PX;
    const spawnY = this.terrain.heightAt(spawnX);
    const spawnAng = this.slopeAt(spawnX);
    this.startX = spawnX;
    // Gym score/distance is per practice attempt; normal runs keep startX.
    this.gymAttemptStartX = spawnX;
    this.gymStartX = spawnX;
    this.sled = new Sled(this, spawnX, spawnY - 14, this.palette, this.look);
    this.sled.setPose(spawnX, spawnY - 15, spawnAng, 50 * pmath.cos(spawnAng * DEG), 50 * pmath.sin(spawnAng * DEG));
    // W4 boosts. Applied at spawn from the loadout chosen before the run: the shield reuses the Hashed
    // Backup charge counter the pickup already feeds, and Head Start scales the launch velocity through
    // the same method the speed-boost pickup uses. No physics constant is touched.
    // Decision 2: only the OFFICIAL Daily refuses boosts. A typed daily seed is a practice run, so its
    // boosts apply and make it MODDED like any other boosted run.
    const isDaily = this.dailyOfficial;
    const boostOpts = { daily: isDaily, unlocked: this.unlockedBoosts };
    this.boostFx = boostEffects(this.loadout, boostOpts);
    this.modded = this.dailyMode==='draft'||this.boostFx.modded || this.upgradeRun.enabled;
    // The ids that actually applied, written onto the record (and so into the v2 ledger hash).
    const applied = loadoutForRun(this.loadout, boostOpts).boosts;
    this.appliedBoosts = Object.keys(applied).filter((id) => applied[id]).sort();
    // Decision 4: Head Start's opening surge (a speedBoost multiplier that fades to 1; see physicsContext).
    this.opening = headStartOpening(this.loadout, boostOpts);
    if (this.boostFx.shieldCharges > 0) {
      this.shieldCharges = (this.shieldCharges || 0) + this.boostFx.shieldCharges;
      this.sled.shield = true;
    }
    if (this.boostFx.speedFactor !== 1) this.sled.scaleVelocity(this.boostFx.speedFactor);
    // An actual Gym attempt starts at a prepared launch pose. After that,
    // NORMAL sled physics, boosts, aero, progression and pursuer acceleration
    // are authoritative. Never override an upgrade or rank-12 refill rule.
    if (this.bsodGym) {
      const setup = this.gymSetup;
      this.sled.setPose(spawnX, spawnY - setup.launchHeightPx, 0,
        setup.launchSpeedPxS, setup.launchRisePxS);
    }
    // Authoritative physical chase: gap is measured from the wall's leading
    // edge to the compound sled body left bound, not center x.
    this.sled.canopyFuelFullMs = PHYSICS.parachuteDurationMs * this.upgradeFx.canopyFuelMul;
    this.sled.parachuteFuelMs = this.sled.canopyFuelFullMs;
    this.bsod = new BsodPursuit({
      sledLeftEdgeX: sledLeftCollisionEdge(this.sled),
      level: rp ? rp.syncLevel : prof.level,
      config: { ...BSOD_DEFAULTS,
        accelerationPxS2: BSOD_DEFAULTS.accelerationPxS2 * this.upgradeFx.bsodAccelerationMul },
    });
    if (this.bsodGym) placeGymWall(this.bsod, sledLeftCollisionEdge(this.sled), this.gymSetup);
    this.bsodState = this.bsod.state(sledLeftCollisionEdge(this.sled), this.sled.vx, 1);
    this.bsodCaught = false;
    this.bsodBluffs = new BsodBluffTracker();
    this.bsodEdge = this.add.graphics().setDepth(16);
    this.windPom = this.add.graphics().setDepth(22);
    this.startGate = this.add.graphics().setDepth(6);
    this.drawStartGate(this.startGate, start.x + 14, this.terrain.heightAt(start.x + 14));
    this.snapCamera();
    // best-distance gate (device best from the save store's in-memory run list; skipped when there is none).
    // Only runs on the board THIS run lands on count (Ranking.sameBoardAs): a clean run must not chase, or
    // be told it fell short of, a Head Start run's distance. boostFx carries this run's `modded`.
    this.bestM = 0;
    try {
      const runs = !this.bsodGym && this.saveStore && this.saveStore.runs;
      const boardIdentity = {...this.boostFx,dailyMode:this.dailyMode,seed:this.seed};
      boardIdentity.modded = this.modded; // input snapshot, NOT a ranking decision
      const onBoard = sameBoardAs(boardIdentity);
      if (Array.isArray(runs)) for (const r of runs) if (r && onBoard(r) && r.distanceM > this.bestM) this.bestM = Math.floor(r.distanceM);
    } catch (e) { this.bestM = 0; }
    this.bestMarker = this.bestM >= 20
      ? new BestMarker(this, this.palette, this.startX + this.bestM * PIXELS_PER_METER, this.bestM) : null;
    // Readable Chaos phase 3: DIED HERE at the last crash x, only on a same-seed, same-mask retry
    const lastCrash = this.registry.get(REG.LAST_CRASH);
    const deathX = deathMarkerX(lastCrash, this.seed, this.biomeMask);
    this.deathMarker = deathX != null ? new LastDeathMarker(this, this.palette, deathX, lastCrash.distM) : null;
    this._lastHopMs = null;

    // events
    this._onCollide = (event) => {
      const pairs = event && event.pairs;
      if (!pairs) return;
      for (let i = 0; i < pairs.length; i++) this.handlePair(pairs[i]);
    };
    this.matter.world.on('collisionstart', this._onCollide);
    this.matter.world.on('collisionactive', this._onCollide);
    this._onSettings = (payload) => this.onSettingsChanged(payload);
    this._onResume = () => {
      this._manualPausePending = false;
      if (this.inputRouter && this.inputRouter.setEnabled) this.inputRouter.setEnabled(true);
      // consume the stale one-shot edge (the Esc that resumed) so it cannot re-pause immediately
      try { if (this.inputRouter) this.inputRouter.poll(); } catch (e) { /* ignore */ }
      // A beat prediction predating a user-controlled pause is no longer a
      // reliable launch deadline. Release once on resume, without querying
      // music again or extending the hold. The original 1000ms READY, if
      // incomplete, remains paused and resumes normally.
      if (this.bsodGym && this.gymBeatSnapshot) {
        // A paused suggestion cannot count as a synchronized beat even if
        // the music happens to be near its original due time on resume.
        this.gymBeatSnapshot = null;
        this.finishGymReady();
      }
    };
    // Audio is presentation: a failing engine must never break run start or the emitter (issue #140).
    this._onMusicTrackChange = (payload) => {
      try { this.songBillboard?.showTrack(payload, this.registry.get(REG.AUDIO)); } catch { /* no billboard */ }
    };
    this.game.events.on(EVT.MUSIC_TRACK_CHANGED,this._onMusicTrackChange);
    this.game.events.on(EVT.SETTINGS_CHANGED, this._onSettings);
    this.game.events.on(EVT.GAME_RESUME, this._onResume);
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.teardown, this);

    // post-FX + HUD + go
    GlitchPipeline.install(this);
    this.scene.stop(SCENES.UI);
    this.scene.launch(SCENES.UI);
    // A track may already be playing from the Title jukebox. Introduce it
    // once when entering the first run, never once per scene retry.
    try {
      const playing=this.registry.get(REG.AUDIO)?.jukeboxSnapshot?.();
      if(playing?.state==='playing'&&playing.current)
        this.songBillboard?.showTrack(playing.current,this.registry.get(REG.AUDIO));
    } catch { /* a throwing audio engine must not stop the run from starting (issue #140) */ }
    this._initGhosts();
    this.game.events.emit(EVT.RUN_START, {
      runId: this.runId, seed: this.seed, dailyRuleId: this.dailyRuleId, startedAt: this.startedAt,
      dailyOfficial: this.dailyOfficial, // additive (decision 2): lets the HUD tell the Daily from practice
      dailyMode:this.dailyMode,
      gym: this.bsodGym === true, // non-ranked practice must never trigger live mission-completion toasts
    });
  }

  /**
   * Ghosts (issue #56). Normal and Daily runs record a tape from the first tick; Gym practice
   * never does. Ghosts for this exact course load asynchronously and join at the current tick.
   */
  _initGhosts() {
    this.ghostRiders = [];
    const token = this._ghostToken = (this._ghostToken || 0) + 1;
    const replay = this._replayTape;
    this.tapePlayer = replay ? new TapePlayer(replay) : null;
    // Ghosts are cosmetic: a recorder that cannot start must never stop the run from starting.
    try { this.ghostRecorder = this.bsodGym || replay ? null : new GhostRecorder(this._ghostHeader()); }
    catch (e) { this.ghostRecorder = null; }
    const lib = this.registry.get(REG.GHOSTS);
    if (!lib || this.bsodGym || replay) return;
    const st = this.settings || {};
    const show = { best: st.ghostBest !== false, latest: st.ghostLatest !== false, fav0: true, fav1: true, fav2: true };
    // A missing/older simRevision is never a current-terrain display ghost.
    // The source revision is available synchronously even if the validated
    // runtime ruleset's asynchronous loader has not completed at run start.
    const loadedRevision = this.registry.get(RULESET_KEY)?.doc?.simRevision;
    const simRevision = loadedRevision === SIM_REVISION ? loadedRevision : SIM_REVISION;
    lib.ghostsFor(this.seed, this.biomeMask, show, { simRevision }).then((list) => {
      if (token !== this._ghostToken || !this.sys?.isActive?.()) return;
      this.ghostRiders = list.map((g) => new GhostRider(this, g, this.palette));
    }).catch(() => { /* ghosts are cosmetic */ });
  }

  /** Everything a replay needs that the seed alone does not reconstruct. */
  _ghostHeader() {
    const b = this.sled.body;
    return {
      seed: this.seed, biomeMask: this.biomeMask || 0,
      // Use the registered, verified ruleset when present. A run can begin
      // before the nonblocking ruleset-loader finishes; the same build's
      // compile-time SIM_REVISION is the safe fallback, not legacy physicsVersion.
      simRevision: this.registry.get(RULESET_KEY)?.doc?.simRevision === SIM_REVISION
        ? this.registry.get(RULESET_KEY).doc.simRevision : SIM_REVISION,
      mode: this.bsodGym ? 'gym' : this.dailyMode === 'draft' ? 'daily-draft' : this.dailyOfficial ? 'daily' : 'normal',
      dailyRuleId: this.dailyRuleId || null,
      dailyRuleSource: DailyPatch.dateKeyFromSeed(this.seed) ? 'seed-date' : 'clock-at-start',
      syncLevel: Number.isFinite(this.registry.get(REG.PROFILE)?.level) ? Math.max(1, this.registry.get(REG.PROFILE).level) : 1,
      bsod: { leftEdgeX: sledLeftCollisionEdge(this.sled),
        initial: { wallX: this.bsod.wallX, wallSpeedPxS: this.bsod.wallSpeedPxS, accelerationPxS2: this.bsod.accelerationPxS2 } },
      controlLayout: this.settings?.controlLayout || 'tricksRight',
      boosts: [...(this.appliedBoosts || [])],
      upgradeRanks: this.upgradeRun?.enabled ? { ...this.upgradeRun.ranks } : null,
      magnetsDrop: this.magnetsDrop === true,
      kodiaksOn: this.kodiaksOn === true,
      kodiakPackMode: this.kodiakPackMode,
      kodiakVersion: KODIAK_VERSION,
      startPose: [b.position.x, b.position.y, b.angle, b.velocity.x, b.velocity.y, b.angularVelocity],
      random: runRandomState(this.runRandom),
      startedAt: this.startedAt,
    };
  }

  _saveGhostTape(record) {
    const rec = this.ghostRecorder;
    this.ghostRecorder = null;
    if (!rec) return;
    try {
      const tape = rec.finish({ runId: record.id, distanceM: record.distanceM, score: record.score, endedAt: record.endedAt });
      this.registry.set(REG.LAST_GHOST_TAPE, tape);
      const pr = this.registry.get(REG.GHOSTS)?.saveRun(tape);
      if (pr && pr.catch) pr.catch(() => {});
      // Replay evidence (#116): runs in a later task (never on this frame), never throws; failures are logged and left on the registry.
      scheduleRunEvidence(tape, rec, { registry: this.registry, ruleset: this.registry.get(RULESET_KEY) });
    } catch (e) { /* a ghost must never break the end of a run */ }
  }

  /**
   * Issue #47: one Kodiak PACK at a time, on the seeded schedule (Kodiaks.kodiakEncounter). Runs inside the
   * fixed tick; collision is a tick-exact box test per bear (no Matter body). Contact is never a crash: the bear
   * shoves the sled back and up (Kodiaks.kodiakKnockback), once per bear, with a shared immunity window so a pack
   * cannot chain shoves. A shoved bear earns no pass bonus; a clean pass scores.
   */
  updateKodiaks(dt) {
    if (!this.kodiaksOn || this.crashed || !this.sled) return;
    const sled = this.sled;
    if (this.kodiakShoveCdMs > 0) this.kodiakShoveCdMs = Math.max(0, this.kodiakShoveCdMs - dt);
    if (!this.kodiaks.length) {
      const enc = kodiakEncounter(this.seed, this.kodiakNext, this.kodiakPackMode);
      if ((sled.x - this.startX) / PIXELS_PER_METER < enc.atM) return;
      this.kodiakNext++;
      this.kodiaks = spawnKodiakPack(this.seed, enc, { x: sled.x, vx: sled.vx });
      const sides = [...new Set(enc.members.map((m) => KODIAK_DEFS[m].from))];
      this.emitIf(EVT.KODIAK, { type: 'incoming', mode: enc.mode, members: enc.members.map((m) => KODIAK_DEFS[m].short),
        from: sides.length > 1 ? 'both' : sides[0] });
    }
    const landX = !sled.grounded && Number.isFinite(sled.airEtaMs) ? sled.x + sled.vx * sled.airEtaMs / 1000 : null;
    const steps = stepKodiakPack(this.kodiaks, { x: sled.x, vx: sled.vx, grounded: sled.grounded, landX, etaMs: sled.airEtaMs }, dt);
    const sledBox = { x: sled.x - 18, y: sled.y - 20, w: 36, h: 30 };
    for (const { k, ev } of steps) {
      const gy = this.terrain.heightAt(k.x);
      if (Number.isFinite(gy)) k.groundY = gy; else if (!Number.isFinite(k.groundY)) k.groundY = sled.y;
      if (ev.telegraph) {
        this.playSfx('groundWarn', { brace: ev.telegraph === 'real' });
        this.emitIf(EVT.KODIAK, { type: 'telegraph', id: k.def.id, short: k.def.short, real: ev.telegraph === 'real' });
      }
      if (!k.hit && this.kodiakShoveCdMs <= 0 && !(sled.invulnerableMs > 0) && kodiakHits(kodiakBox(k.x, k.groundY), sledBox)) {
        k.hit = true;
        const shove = kodiakKnockback(k, sled);
        this._addSledVelocity(shove.dvx, shove.dvy);
        this.kodiakShoveCdMs = KODIAK_KNOCK.immunityMs;
        this.fx.sparks(k.x, k.groundY - 14, k.def.accent, 16, 220);
        this.shake(3);
        this.playSfx('push');
        this.emitIf(EVT.KODIAK, { type: 'shove', id: k.def.id, short: k.def.short, n: k.n, member: k.member, dvx: shove.dvx, dvy: shove.dvy });
      }
      // Passing a bear (it was ahead and now is behind) scores; clearing it in the air scores more.
      const ahead = sled.x > k.x;
      if (ahead && !k.sledAhead && !k.hit) {
        const air = !sled.grounded, points = air ? 250 : 150;
        this.bonus(points, 'kodiak');
        this.emitIf(EVT.KODIAK, { type: 'passed', id: k.def.id, short: k.def.short, air, points });
      }
      k.sledAhead = ahead;
    }
    if (this.kodiaks.every((k) => k.done)) {
      this.emitIf(EVT.KODIAK, { type: 'gone' });
      this.kodiaks = [];
    }
  }

  /** Remove every listener / pooled object / body (runs on scene shutdown). @returns {void} */
  teardown() {
    this.gymBeatSnapshot = null;
    this.gymBeatWaitMs = 0;
    try {
      this.game.events.off(EVT.MUSIC_TRACK_CHANGED,this._onMusicTrackChange);
      this.game.events.off(EVT.SETTINGS_CHANGED, this._onSettings);
      this.game.events.off(EVT.GAME_RESUME, this._onResume);
    } catch (e) { /* ignore */ }
    try {
      if (this.matter && this.matter.world) {
        this.matter.world.off('collisionstart', this._onCollide);
        this.matter.world.off('collisionactive', this._onCollide);
      }
    } catch (e) { /* ignore */ }
    const safe = (o) => { try { if (o) o.destroy(); } catch (e) { /* world already torn down */ } };
    for (const list of this.hazards ? this.hazards.values() : []) list.forEach(safe);
    for (const list of this.powerups ? this.powerups.values() : []) list.forEach(safe);
    this.hazards = new Map();
    this.powerups = new Map();
    safe(this.sled);
    safe(this.mesh);
    safe(this.trail);
    safe(this.fx);
    safe(this.bg);
    safe(this.biomeFx);
    this.biomeFx = null;
    safe(this.songBillboard);
    this.songBillboard=null;
    safe(this.blackHole);
    this.blackHole = null;
    safe(this.kodiakRider);
    this.kodiakRider = null;
    this.kodiaks = [];
    (this.ghostRiders || []).forEach(safe);
    this.ghostRiders = [];
    this._ghostToken = (this._ghostToken || 0) + 1;
    this.worldDance?.reset();
    this.worldDance = null;
    this._worldDanceMotionQuery=null;
    safe(this.shardField);
    safe(this.bestMarker);
    safe(this.deathMarker);
    this.deathMarker = null;
    safe(this.airTelegraph);
    safe(this.groundTelegraph);
    this.groundTelegraph = null;
    safe(this.streaks);
    safe(this.bsodEdge);
    safe(this.windPom);
    this.deactivateBsod();
    this.bsod = null;
    this.bsodEdge = this.windPom = null;
    this.shardField = this.bestMarker = this.streaks = this.airTelegraph = null;
    this.sled = this.mesh = this.trail = this.fx = this.bg = null;
    this.terrain = null;
    this.tricks = null;
    this.glitch = null;
    this.score = null;
    this.safeSamples = [];
    this._contactQueue = [];
    try { this.scene.stop(SCENES.UI); } catch (e) { /* ignore */ }
  }

  /** Active Space Mountain has no atmosphere, even though the BSOD still chases. */
  bsodAtmosphere() {
    if (!this.terrain || !this.sled || !this.biomeMask) return 1;
    const biome = this._biomeDefAt(this.sled.x);
    return biome && biome.id === 'space-mountain' ? 0 : 1;
  }

  /** Authoritative BSOD event must not let a faulty *observer* abort collision
   * resolution. The actual audio subscriber additionally handles its own errors,
   * so a failing mixer cannot suppress unrelated listeners. */
  publishBsodState(state) {
    try { this.game?.events?.emit?.(EVT.BSOD_STATE_CHANGED, state); }
    catch (e) {
      if (!this._bsodObserverErrorLogged) {
        this._bsodObserverErrorLogged = true;
        console.warn('BSOD observer failed; gameplay continues', e);
      }
    }
  }

  /** Reset wind/music subscriptions on end, abort or teardown; never mutate the music mixer. */
  deactivateBsod() {
    if (this.bsodBluffs) this.bsodBluffs.reset();
    if (!this.bsod || !this.bsod.active) return;
    this.bsodState = this.bsod.stop();
    this.publishBsodState(emptyBsodState());
  }

  /** World-coordinate visual cues. They do not affect physics, danger, input or accessibility settings. */
  drawBsodCues() {
    const s = this.sled, view = this._view, state = this.bsodState;
    const wall = this.bsodEdge, pom = this.windPom;
    if (!s || !view) return;
    if (wall && wall.clear) {
      wall.clear();
      if (this.bsod && (this.bsod.active || this.bsodCaught) && this.bsod.wallX > view.left) {
        const edge = Math.min(view.right, this.bsod.wallX);
        const width = Math.max(0, edge - (view.left - 12));
        const y = view.top - 15, height = view.bottom - view.top + 30;
        wall.fillStyle(this.palette.magenta, 0.23);
        wall.fillRect(view.left - 12, y, width, height);
        wall.lineStyle(3, this.palette.magenta, 0.95);
        wall.lineBetween(this.bsod.wallX, y, this.bsod.wallX, y + height);
      }
    }
    if (pom && pom.clear) {
      pom.clear();
      // Sled._draw supplies an exact helmet/drone anchor in rendered world coords.
      // Never leave a free-floating pom after the rider vanishes on BSOD impact.
      if (s.hidden || s.inWorld === false || !s.windPomAnchor) return;
      const wind = state && state.active ? state.relativeAirX : 0;
      const strength = bsodWindVisualStrength(state);
      const dir = wind > 0 ? 1 : wind < 0 ? -1 : 0;
      const { x: anchorX, y: anchorY } = s.windPomAnchor;
      // The visual THREAT cue has a gentle, continuous buildup instead of
      // saturating from raw relative airspeed while the BSOD is still far.
      // At zero wind the pom dangles; at close range it stretches and rises.
      // Signed wind direction remains authoritative; all physics is unchanged.
      const endX = anchorX + dir * (5 + 23 * strength);
      const endY = anchorY + 5 - 12 * strength;
      pom.lineStyle(1.6, this.palette.text, 0.50 + 0.44 * strength);
      pom.lineBetween(anchorX, anchorY, endX, endY);
      pom.fillStyle(this.palette.amber, 0.62 + 0.35 * strength);
      pom.fillCircle(endX, endY, 2.6 + 0.4 * strength);
    }
  }

  /** A real close approach followed by a parachute escape; zero score for proximity alone. */
  updateBsodBluff(airBrakeKicked = false, physicalTouchdowns = [], kickSample = null) {
    if (!this.bsodBluffs || !this.sled || !this.bsodState) return;
    // The scorer otherwise sees only the LAST substep of an 8ms frame.
    // A real Matter touchdown followed by a buffered Hop in that frame
    // separates TWO flights: the earlier one loses its canopy/AirBrake
    // credit before the new one can arm. Grounded update does not award.
    for (const contact of physicalTouchdowns) {
      const d=contact.bsodState || this.bsodState;
      this.bsodBluffs.update({
        active: !!d.active, gapPx:d.gapPx,
        playerX:contact.fs.x,nowMs:contact.fs.timeMs,
        grounded:true,crashed:!!this.bsodCaught,
      });
    }
    const s = this.sled, danger = this.bsodState;
    // Resolve the approach at the actual pre-controls kick position. An
    // encounter that arms only at the end of this tick cannot claim this kick.
    // Observe any already-completed escape BEFORE recording the new kick.
    if (kickSample && airBrakeKicked && !this.bsodCaught && !this.crashed) {
      const early = this.bsodBluffs.update({ ...kickSample, airbrakeKicked: false });
      if (early) this.awardBsodBluff(early);
      this.bsodBluffs.recordPaidAirBrake();
    }
    const event = this.bsodBluffs.update({
      active: danger.active, gapPx: danger.gapPx, playerX: s.x, nowMs: this.runTimeMs,
      grounded: !!s.grounded, crashed: !!this.crashed || !!this.bsodCaught,
      canopyDeployed: (s.parachuteMs || 0) > 0,
      airbrakeKicked: !!airBrakeKicked && !kickSample, // sampled callers only; real controls supply kickSample
      relativeAirX: danger.relativeAirX,
      atmosphereDensity: danger.atmosphereDensity,
    });
    if (event) this.awardBsodBluff(event);
  }

  awardBsodBluff(event) {
    const s = this.sled;
    // Existing near-miss accounting feeds scoring, missions, achievements and run records.
    this.nearMissCount = (this.nearMissCount || 0) + 1;
    this.bonus(event.points, 'nearMiss');
    // Milestone perk: ONLY an actual, verified midair Bluff refills part of
    // an upgraded canopy. This is off in clean and official Daily runs.
    const rank = this.upgradeRun?.enabled ? this.upgradeRun.ranks?.canopy : 0;
    const full = s.canopyFuelFullMs || PHYSICS.parachuteDurationMs;
    const spent = Number.isFinite(s.parachuteFuelMs) ? s.parachuteFuelMs : full;
    const recovery = canopyBluffRecoveryMs(rank, event.chain, full);
    const newFuel = Math.min(full, spent + recovery);
    const canopyRecoveredMs = Math.max(0, newFuel - spent);
    if (canopyRecoveredMs > 0) s.parachuteFuelMs = newFuel;
    // Only the FIRST actually survived escape reveals a secret shop item.
    // No hints, previews, or tutorial actions exist before that event.
    const store = this.registry?.get?.(REG.PROGRESSION)?.store;
    // Stamp the actual live achievement BEFORE the store marks the Gym as
    // discovered. Otherwise legacy-migration logic would infer a historical
    // unlock at timestamp zero and swallow the real first-time reveal toast.
    const achieved = !this.bsodGym ? store?.recordBsodBluff?.(event.chain,Date.now()) : null;
    const discovered = !this.bsodGym && store?.discoverBsodGym?.();
    if (discovered?.discovered || achieved?.added?.length)
      this.registry?.set?.(REG.PROFILE, store.profile);
    // The nested Easter egg is earned ONLY by five genuine scored escapes
    // WITHOUT LANDING in the GYM. Normal-world chains never advance it.
    if (this.bsodGym && event.chain >= GYM_MASTERY_CHAIN) {
      const mastery = store?.unlockGymSetup?.();
      if (mastery?.unlocked) {
        this.registry?.set?.(REG.PROFILE, mastery.profile);
        this.game.events.emit(EVT.GYM_SETUP_UNLOCKED, {});
      }
    }
    const payload = {
      hazardType: 'bsod', points: event.points, x: s.x, y: s.y,
      ...(discovered?.discovered ? { gymDiscovered: true } : {}),
      ...(achieved?.added?.length ? { achievementsEarned: achieved.added.map(x=>x.id) } : {}),
      chain: event.chain, surfing: event.surfing, closestGapPx: event.closestGapPx,
      ...(canopyRecoveredMs > 0 ? { canopyRecoveredMs } : {}),
    };
    this.game.events.emit(EVT.NEAR_MISS, payload);
    this.game.events.emit(EVT.BSOD_BLUFF, payload);
  }

  /** Stable world factory: practice retries regenerate the same launch track,
   * rather than teleporting the rider into terrain streamed far down-course. */
  createTerrainGenerator() {
    return new TerrainGenerator({
      seed: this.seed,
      chunkDefs: this.content.chunks,
      hazardDefs: this.content.hazards,
      powerupDefs: this.content.powerups,
      modDefs: this.content.terrainMods,
      biomeDefs: Object.values(this.content.biomes || {}),
      biomeMask: this.biomeMask,
    });
  }

  /** Restore the entire Gym course between attempts: physical terrain bodies,
   * hit hazards, picked-up items, and collected shards. We only call this
   * AFTER Matter stepping has completed, never from collision callbacks.
   * The same seed/mask and generation rules are reused; physics unchanged. */
  resetGymWorld() {
    if (!this.mesh?.chunks || !this.terrain?.getActiveChunks || !this.content) return;
    for (const index of [...this.mesh.chunks.keys()]) this.dropChunk(index);
    this.terrain = this.createTerrainGenerator();
    this.collectedPowerups?.clear?.();
    this.shardField?.collected?.clear?.();
    this.shardField?.byChunk?.clear?.();
    this.activeZones?.clear?.();
    this._despawn?.splice?.(0);
    this.glitch = new GlitchDirector({seed:this.seed});
    this._chunkQueue = new Map();
    this.streamTerrain(0);
  }

  // ------------------------------------------------------------------ terrain streaming

  /** Ask the generator to stream around x and mirror its adds/removals into mesh, hazards and power-ups. */
  /**
   * The biome definition at world x, or null for an arcade bridge / no content. Asks the generator, so the
   * palette, the BIOME_ENTER announcement and the terrain itself (arcade bridges included) cannot disagree.
   * Pure w.r.t. game state.
   * @param {number} x world px
   * @returns {Object|null}
   */
  _biomeDefAt(x) {
    return this._biomeDefById(this.terrain.biomeAtX(x));
  }

  _biomeDefById(id) {
    return id ? (this.content.biomes || {})[id] || null : null;
  }

  /**
   * #65 presentation: the biome whose look (palette, motif, glitch set) the world wears. Equals the generator's biome
   * except across an arcade bridge, where the outgoing look holds through the dissolve and the incoming look is on
   * before the bridge ends (BiomeTransition.bridgeLook). Reduced motion is the hard cut: the generator's answer.
   * @returns {string|null|undefined}
   */
  _lookBiomeId() {
    return this._lookId !== undefined ? this._lookId : this._biomeId;
  }

  /**
   * Recompute the look and the dissolve veil from the sled's x and repaint when the look changes. Presentation only:
   * the generator's own biome (BIOME_ENTER, discovery, music) is untouched. A bridge's span is cached while the sled
   * is inside it, so the generator is asked once per bridge, not once per frame.
   * @param {string|null} biomeNow terrain.biomeAtX(sled.x)
   * @param {boolean} paletteOwed the generator's biome changed and a repaint was owed (entering a biome, or leaving one)
   */
  _updateLook(biomeNow, paletteOwed) {
    const x = this.sled.x;
    let span = null;
    if (biomeNow === null && this.terrain.bridgeSpanAt && this.terrain.biomeDefs && this.terrain.biomeDefs.length) {
      span = this._bridgeSpan;
      if (!span || x < span.startX || x >= span.endX) span = this._bridgeSpan = this.terrain.bridgeSpanAt(x);
    } else this._bridgeSpan = null;
    const look = bridgeLook(span, x, biomeNow, !isReducedMotion(this), this._lookScratch || (this._lookScratch = { veil: 0, lookId: null, t: -1 }));
    this._veil = look.veil;
    const lookChanged = look.lookId !== this._lookId;
    const firstLook = this._lookId === undefined;
    this._lookId = look.lookId;
    if (paletteOwed || (lookChanged && (this._biomeDefById(look.lookId) || !firstLook))) this.refreshPalette();
  }

  streamTerrain(x) {
    const res = this.terrain.update(x) || {};
    if (!this._chunkQueue) this._chunkQueue = new Map();
    for (const idx of res.removed || []) { this._chunkQueue.delete(idx); this.dropChunk(idx); }
    for (const chunk of res.added || []) this._chunkQueue.set(chunk.index, chunk);
    // Defensive reconcile (first call, or a generator that only reports through getActiveChunks()).
    if (this.mesh.chunks.size === 0 && this.terrain.getActiveChunks) {
      for (const chunk of this.terrain.getActiveChunks()) if (!this.mesh.chunks.has(chunk.index)) this._chunkQueue.set(chunk.index, chunk);
    }
    // Issue #59: a chunk's colliders, hazards, pickups and shards join the world on the first tick the sled is
    // within the generator's own fill-ahead bound of it, never earlier. Cosmetic terrain reads (minimap, billboard,
    // camera) can make the generator build chunks ahead of time on any display frame; gating here keeps the tick a
    // chunk becomes physical a function of the sled's position alone, so replays and 30/60/120 Hz runs stay exact.
    const bound = x + TERRAIN.bufferAheadScreens * (this.terrain.screenW || GAME_WIDTH);
    for (const idx of [...this._chunkQueue.keys()].sort((a, b) => a - b)) {
      const chunk = this._chunkQueue.get(idx);
      if (chunk.startX >= bound) break;
      this._chunkQueue.delete(idx);
      this.takeChunk(chunk);
    }
  }

  takeChunk(chunk) {
    if (!chunk || this.mesh.chunks.has(chunk.index)) return;
    this.mesh.addChunk(chunk);
    const hz = [];
    const spawns = chunk.hazards || [];
    for (let hazardOrdinal = 0; hazardOrdinal < spawns.length; hazardOrdinal++) {
      const spawn = spawns[hazardOrdinal];
      const def = this.content.hazards[spawn.defId];
      if (!def) continue;
      const h = new Hazard(this, def, spawn, this.palette);
      h.hid = `${chunk.index}:${hazardOrdinal}`; // stable id (chunk + spawn ordinal): keys TelegraphTracker, serializable
      h.simStepped = true; // its motion (rolls, gates) moves the sensor body: advanced in simTick, not per frame
      if (def.placement === 'air') {
        // the launch lip this air hazard belongs to (nearest lip before it): the STAY LOW telegraph stands there
        let lip = null;
        for (const l of chunk.launches || []) if (l.x < spawn.x && (!lip || l.x > lip.x)) lip = l;
        h.lip = lip ? { x: lip.x, y: lip.y } : null;
      }
      hz.push(h);
    }
    if (hz.length) this.hazards.set(chunk.index, hz);
    const pu = [];
    (chunk.powerups || []).forEach((spawn, i) => {
      const def = this.content.powerups[spawn.defId];
      if (!def || this.collectedPowerups.has(`${chunk.index}:${i}`)) return;
      const p = new PowerUp(this, def, spawn, this.palette);
      p.key = `${chunk.index}:${i}`;
      pu.push(p);
    });
    // Shard Magnet: one optional extra pickup per chunk, from its own seeded stream (never in the chunk data).
    // Drops from Sync Level 5 (always on Dailies); MYRIAD MAGNETS raises the chance.
    const magnetDef = this.content.powerups.shardMagnet;
    if (magnetDef && this.magnetsDrop && !this.collectedPowerups.has(`${chunk.index}:magnet`)) {
      let spawn = null;
      try { spawn = magnetSpawn(this.seed, chunk, magnetDef, (x) => this.terrain.heightAt(x), PIXELS_PER_METER, this.upgradeFx?.magnetSpawnMul); } catch (e) { /* a pickup never breaks streaming */ }
      if (spawn) {
        const p = new PowerUp(this, magnetDef, spawn, this.palette);
        p.key = `${chunk.index}:magnet`;
        pu.push(p);
      }
    }
    if (pu.length) this.powerups.set(chunk.index, pu);
    if (this.shardField) this.shardField.addChunk(chunk);
  }

  dropChunk(idx) {
    this.mesh.removeChunk(idx);
    if (this.shardField) this.shardField.removeChunk(idx);
    const hz = this.hazards.get(idx);
    if (hz) hz.forEach((h) => h.destroy());
    this.hazards.delete(idx);
    if (this.teleTracker) this.teleTracker.forgetChunk(idx);
    const pu = this.powerups.get(idx);
    if (pu) pu.forEach((p) => p.destroy());
    this.powerups.delete(idx);
  }

  /** Neon start pylon with a blinking beacon, drawn once. */
  drawStartGate(g, x, y) {
    const p = this.palette;
    g.lineStyle(5, p.cyan, 0.15);
    g.lineBetween(x, y, x, y - 70);
    g.lineStyle(2, p.cyan, 1);
    g.lineBetween(x, y, x, y - 70);
    g.lineStyle(1.5, p.text, 0.9);
    g.strokePoints([{ x: x - 7, y: y - 70 }, { x: x + 7, y: y - 70 }, { x: x + 7, y: y - 58 }, { x: x - 7, y: y - 58 }], true, true);
    g.fillStyle(p.lime, 0.8);
    g.fillRect(x - 5, y - 68, 10, 8);
    g.lineStyle(1, p.cyan, 0.5);
    for (let i = 1; i <= 4; i++) g.lineBetween(x, y - i * 12, x + 12, y - i * 12 + 4);
  }

  safeStartPosition() {
    let sp = null;
    try { sp = this.terrain.getStartPosition(); } catch (e) { /* fall through */ }
    const x = sp && Number.isFinite(sp.x) ? sp.x : 0;
    const y = sp && Number.isFinite(sp.y) ? sp.y : this.terrain.heightAt(x);
    return { x, y };
  }

  slopeAt(x) {
    const s = this.terrain.slopeDegAt(x);
    return Number.isFinite(s) ? s : 0;
  }

  /** Emit an event only if its constant exists (UI engineer adds the fun-pass names to events.js). */
  emitIf(name, payload) {
    if (name) this.game.events.emit(name, payload);
  }

  /** One-shot SFX through the registry audio (never throws). */
  playSfx(name, opts) {
    try {
      const audio = this.registry.get(REG.AUDIO);
      if (audio) audio.playSfx(name, opts);
    } catch (e) { /* audio must never break the loop */ }
  }

  /** Award a bonus through ScoreManager.addBonus when present, then publish the score. @returns {boolean} */
  bonus(points, kind) {
    if (!this.score || typeof this.score.addBonus !== 'function') return false;
    this.score.addBonus(points, kind);
    this.emitScore();
    return true;
  }

  // ------------------------------------------------------------------ collisions

  /** A head/torso brush on a concave transition is forgiven while the sled is grounded and roughly aligned with the slope. */
  headForgiven() {
    const sled = this.sled;
    if (sled.msSinceContact > 150) return false;
    const rel = Math.abs(((sled.angleDeg - sled.groundAngleDeg + 540) % 360 + 360) % 360 - 180);
    return rel <= 70;
  }

  handlePair(pair) {
    if (this.crashed || !this.sled || !this.sled.body) return;
    const a = pair.bodyA;
    const b = pair.bodyB;
    const sb = this.sled.body;
    let part;
    let other;
    if (a && a.parent === sb) { part = a; other = b; } else if (b && b.parent === sb) { part = b; other = a; } else return;
    if (!other) return;
    switch (other.label) {
      case 'terrain':
        if (part.label === 'skid' || part.label === 'deck') this.sled.noteGroundContact();
        else if (this.headForgiven()) this.sled.noteGroundContact();
        else if (!this.pendingCrash) this.pendingCrash = { cause: 'terrain' };
        break;
      case 'hazard':
        if (other.bbHazard && !other.bbHazard.hit) this._contactQueue.push(other.bbHazard);
        break;
      case 'powerup':
        if (other.bbPowerUp && !other.bbPowerUp.collected) this._contactQueue.push(other.bbPowerUp);
        break;
      case 'pad':
        if (other.bbPad) this._contactQueue.push(other);
        break;
      default:
        break;
    }
  }

  /** Resolve sensor overlaps gathered during a sub-step. */
  processContacts() {
    const q = this._contactQueue;
    if (!q.length) return;
    for (let i = 0; i < q.length; i++) {
      const o = q[i];
      if (o instanceof Hazard) this.onHazard(o);
      else if (o instanceof PowerUp) this.onPowerUp(o);
      else if (o && o.bbPad) this.onPad(o.bbPad);
    }
    q.length = 0;
  }

  onPad(pad) {
    const now = this.runTimeMs;
    if (pad._last != null && now - pad._last < 250) return;
    pad._last = now;
    const mul = this.sled ? 1 : 1;
    const zoneMul = this.currentPhys ? this.currentPhys.bounceMul : 1;
    const up = pad.boost * mul * Math.max(1, zoneMul);
    this.sled.launchUp(up);
    this.fx.ring(pad.x, pad.y - 6, this.palette.lime, 26, 320);
    this.fx.sparks(pad.x, pad.y - 6, this.palette.lime, 10, 140, 120);
  }

  onHazard(h) {
    if (h.hit || this.crashed) return;
    if (this.sled.invulnerableMs > 0) return;
    if (h.isPassable && h.isPassable(this.runTimeMs)) return; // B3: an open Gear Gate is passed (stays armed)
    h.hit = true;
    const def = h.def;
    const eff = def.onHit || { effect: 'crash' };
    const kind = eff.effect;
    // B0 ward: a warded hazard (by id) or effect does nothing at all and reports no hit (Wards.js)
    if (isWarded(this.wards, { hazardId: def.id }) || isWarded(this.wards, { effect: kind })) {
      this.fx.ring(h.cx, h.cy, this.palette.cyan, 22, 260);
      if (h.gfx) h.gfx.setAlpha(0.4);
      return;
    }
    const dur = hazardEffectDurationMs(eff);
    this.game.events.emit(EVT.HAZARD_HIT, { hazardId: def.id, effect: kind, durationMs: dur, x: h.cx, y: h.cy });
    if (kind === 'crash') {
      if (!this.pendingCrash) {
        this.pendingCrash = { cause: 'hazard', hazardId: def.id };
        this._crashHazard = h; // crash report: the entity, for its telegraph arrival (pendingCrash keeps its shape)
      }
    } else if (kind === 'slow') {
      this.slowMs = dur;
      this.slowFactor = eff.speedFactor != null ? eff.speedFactor : PHYSICS.slowFactor;
      this.sled.scaleVelocity(this.slowFactor);
      this.fx.sparks(h.cx, h.cy, h.color, 14, 200);
      this.shake(2);
    } else if (kind === 'scramble') {
      this.scrambleMs = dur;
      this.fx.sparks(h.cx, h.cy, h.color, 16, 160, 80);
      this.shake(1.5);
    } else if (kind === 'blind') {
      // B0: a flash, then a dimming overlay (BiomeEffects.blindOverlayAlpha; never below 35 % visibility, no crash)
      this.blindMs = dur;
      this.blindTotalMs = dur;
      this.blindVis = blindVisibility(eff.visibility);
      this.flashRect.setFillStyle(0xffffff, 1).setAlpha(0.45);
      this.fx.sparks(h.cx, h.cy, h.color, 12, 160, 60);
    } else if (kind === 'gust') {
      // B0: one bounded velocity kick (BiomeEffects.gustImpulse, <= 180 px/s)
      const g = gustImpulse(eff.impulsePxS);
      this._addSledVelocity(g.dvx, g.dvy);
      this.fx.sparks(h.cx, h.cy, h.color, 10, 220, 40);
      this.shake(1);
    }
    if (h.gfx) h.gfx.setAlpha(0.4);
  }

  /** Add a velocity (px/s) to the sled body (B0 gust). Sled caches px/s from the body; keep the cache in step. */
  _addSledVelocity(dvx, dvy) {
    const s = this.sled;
    if (!s || !s.inWorld || !s.body || (!dvx && !dvy)) return;
    const Body = Phaser.Physics.Matter.Matter.Body;
    const v = Body.getVelocity(s.body);
    Body.setVelocity(s.body, { x: v.x + pxPerSecToStep(dvx, BASE_STEP_MS), y: v.y + pxPerSecToStep(dvy, BASE_STEP_MS) });
    s.vx += dvx;
    s.vy += dvy;
  }

  onPowerUp(p) {
    if (p.collected || this.crashed) return;
    p.collected = true;
    if (p.key) this.collectedPowerups.add(p.key);
    const def = p.def;
    const eff = def.effect || {};
    let durationMs = 0;
    let charges = 0;
    if (eff.kind === 'slowmo') {
      durationMs = eff.durationMs || 1000;
      this.slowmoMs = Math.min(SLOWMO_CAP_MS, this.slowmoMs + durationMs);
      this.slowmoScale = eff.timeScale || 0.5;
    } else if (eff.kind === 'speedBoost') {
      durationMs = eff.durationMs || 3000;
      this.boostMs = durationMs;
      this.boostFactor = eff.speedFactor || 1.3;
      this.boostId = def.id; // B1: Maple Wax expires under its own id, not packetBurst's
      this.sled.scaleVelocity(this.boostFactor);
    } else if (eff.kind === 'shield') {
      this.shieldCharges += eff.charges || 1;
      // B2: a biome shield (Heat Shield) shares the pool but keeps its own HUD chip and charge count
      this.shieldSources = addShieldSource(this.shieldSources, def.id, eff.charges || 1);
      charges = shieldChargesFor(this.shieldSources, def.id, this.shieldCharges);
      this.sled.shield = true;
    } else if (eff.kind === 'ward') {
      // B0: switches off its listed mods / hazards / effects for 4-6 s (Wards.js; PhysicsTuner and onHazard consult it)
      this.wards = addWard(this.wards, def.id, eff);
      durationMs = wardMsLeft(this.wards, def.id);
      // B1: a ward's optional speed boost (Slick Wax Spray 1.1): an instant kick now, and wardSpeedMul in the tuner context
      // while the ward lasts. Kept apart from boostMs so a Packet Burst / Maple Wax never overwrites it (or vice versa).
      const wf = this.wards.wards.find((w) => w.id === def.id).speedFactor;
      if (wf > 1) this.sled.scaleVelocity(wf);
    } else if (eff.kind === 'glide') {
      // B0: lower ground friction (PhysicsTuner glideFrictionMul)
      durationMs = timedPowerupMs(eff);
      if (this.glideMs > 0 && this.glideId !== def.id) this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.glideId, reason: 'replaced' });
      this.glideMs = durationMs;
      this.glideMul = glideFrictionMul(eff.frictionMul);
      this.glideId = def.id;
    } else if (eff.kind === 'magnet') {
      // Shard Magnet: pulls shards in for durationMs. Strength = def x MAGNET PULL upgrade (never time).
      // MAGNET MEASURE stretches the duration.
      durationMs = Math.round(timedPowerupMs(eff) * (this.upgradeFx?.magnetDurationMul || 1));
      this.magnetMs = durationMs;
      this.magnetEff = eff;
      this.magnetId = def.id;
    } else if (eff.kind === 'stabilize') {
      // B0: wider landing tolerance (BiomeEffects.resolveLanding) and optional bounce damping
      durationMs = timedPowerupMs(eff);
      if (this.stabilizeMs > 0 && this.stabilizeId !== def.id) this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.stabilizeId, reason: 'replaced' });
      this.stabilizeMs = durationMs;
      this.stabilizeDeg = stabilizeToleranceDeg(eff.landingToleranceDeg);
      this.stabilizeBounce = stabilizeBounceMul(eff.bounceMul);
      this.stabilizeId = def.id;
    }
    this.fx.ring(p.spawn.x, p.spawn.y, p.color, 34, 420);
    this.fx.sparks(p.spawn.x, p.spawn.y, p.color, 12, 180);
    this.game.events.emit(EVT.POWERUP_COLLECTED, { id: def.id, durationMs, charges });
    // remove the pickup immediately (cannot be destroyed inside a Matter event callback chain, so defer to frame end)
    this._despawn = this._despawn || [];
    this._despawn.push(p);
  }

  // ------------------------------------------------------------------ input

  normalizePad(raw) {
    const p = raw || {};
    const pr = p.pressed || {};
    return {
      push: !!p.push,
      tilt: quantizeTilt(p.tilt), // 1/127 steps: an analog tilt replays exactly from a ghost tape
      variableHop: (this.settings?.controlLayout || 'tricksRight') !== 'classic',
      noAutoNudge: (this.settings?.controlLayout || 'tricksRight') !== 'classic',
      divebomb: !!p.divebomb,
      corkscrew: !!p.corkscrew,
      tuck: !!p.tuck,
      brake: !!p.brake || (!!p.airBrake && !!this.sled && this.sled.grounded),
      brakeHeld: !!p.brake, // simTick re-derives `brake` from this and the sled's grounded state each tick
      hop: !!p.hop,
      reset: !!p.reset,
      heli: p.heli > 0 ? 1 : p.heli < 0 ? -1 : 0,
      airBrake: !!p.airBrake,
      parachute: !!p.parachute,
      pause: !!p.pause,
      pressed: {
        hop: !!pr.hop, reset: !!pr.reset, pause: !!pr.pause, airBrake: !!pr.airBrake, parachute: !!pr.parachute, confirm: !!pr.confirm,
      },
      lastSource: p.lastSource || 'keyboard',
    };
  }

  // ------------------------------------------------------------------ main loop

  /** Release gameplay unconditionally. A stale beat affects only whether
   * the optional music alignment was successful, NEVER whether the sled GOes.
   * Clear the one-shot snapshot before emitting, so event listeners cannot
   * accidentally turn a completed release into another audio wait.
   */
  finishGymReady() {
    const timing = this.gymBeatSnapshot;
    this.gymBeatSnapshot = null;
    this.gymBeatWaitMs = 0;
    let onBeat = false;
    if (timing) {
      try { onBeat = this.registry?.get?.(REG.AUDIO)?.isBeatTimingCurrent?.(timing) === true; }
      catch { /* failed audio cannot prevent GO */ }
    }
    this.game.events.emit(EVT.GYM_READY_GO, { onBeat });
  }

  update(time, delta) {
    if (!this.sled) return;
    const dt = clamp(Number.isFinite(delta) ? delta : 16.7, 0, 50);
    this._frameDt = dt;

    if (this.crashed) {
      this.updateCrashed(dt);
      return;
    }

    // Every attempt first freezes real-time gameplay for ~1000ms. Only at
    // that boundary can MUSIC SUGGEST a verified regular pulse <=300ms away.
    // The optional delay is Gym-owned, never a music-engine timer or physics
    // step. Both holds freeze the rider, pursuer, score and run clock.
    if (this.bsodGym && (this.gymReadyMs > 0 || this.gymBeatWaitMs > 0)) {
      const readyPad = this.normalizePad(this.inputRouter ? this.inputRouter.poll() : null);
      if (readyPad.pressed.pause) { this.pauseRun(); return; }
      if (this.gymReadyMs > 0) {
        // The physics delta is capped at 50ms, not the real-time READY.
        this.gymReadyMs = advanceGymReadyMs(this.gymReadyMs, delta);
        if (this.gymReadyMs === 0) {
          const timing = gymBeatSuggestion(this.registry?.get?.(REG.AUDIO));
          if (timing) {
            this.gymBeatSnapshot = timing;
            this.gymBeatWaitMs = timing.waitMs;
          } else this.finishGymReady();
        }
      } else {
        // No requery and never wait for a second pulse. A late/suspended tab
        // must not prolong the hold beyond the supplied original suggestion.
        this.gymBeatWaitMs = advanceGymReadyMs(this.gymBeatWaitMs, delta);
        let audioNow = NaN;
        try { audioNow = this.registry?.get?.(REG.AUDIO)?.ctx?.currentTime; }
        catch { /* audio cannot block a release */ }
        if (this.gymBeatWaitMs === 0 ||
            (Number.isFinite(audioNow) && audioNow >= this.gymBeatSnapshot?.dueAudioTime))
          this.finishGymReady();
      }
      this.renderFrame(0);
      return;
    }

    const rawPad = this.inputRouter ? this.inputRouter.poll() : null;
    const polled = this.normalizePad(rawPad);
    if (polled.pressed.pause) {
      this.pauseRun();
      return;
    }
    // Fixed simulation tick (issue #59): real frame time feeds an accumulator and the game
    // advances only in whole SIM_TICK_MS ticks, so one input tape gives one run at any
    // display rate. Rendering stays once per display frame.
    if (!this.simClock) this.simClock = new SimClock();
    const ticks = this.simClock.advance(dt);
    // A ghost tape under replay (REG.GHOST_REPLAY) replaces live input tick by tick.
    const pads = this.tapePlayer
      ? Array.from({ length: ticks }, (_, i) => this.tapePlayer.padAt(this.simClock.tick + 1 + i))
      // Issue #115: timestamped key changes go to the tick whose window contains them (`time` is the
      // rAF time, the same clock as KeyboardEvent.timeStamp); see SimClock.padsFor.
      : this.simClock.padsFor(polled, ticks, {
        frameTime: time, timeline: rawPad && rawPad.timeline, normalize: (raw) => this.normalizePad(raw),
      });
    let pad = polled;
    for (const tickPad of pads) {
      pad = tickPad;
      const tick = ++this.simClock.tick;
      // Air brake on the ground brakes: decided per tick, not per display frame.
      tickPad.brake = !!tickPad.brakeHeld || (!!tickPad.airBrake && !!this.sled?.grounded);
      this.ghostRecorder?.input(tick, tickPad);
      const r = this.simTick(this.simClock.tickMs, tickPad);
      if (!this.crashed) {
        this.ghostRecorder?.afterTick(tick, this);
        this.tapePlayer?.check(tick, this);
      }
      if (r === 'hold') { this.renderFrame(0); return; }
      if (this.crashed) break;
    }
    for (const g of this.ghostRiders || []) g.update(this.simClock.tick);
    this.renderFrame(dt, pad);
  }

  /**
   * One fixed simulation tick: every causal gameplay system (timers, physics, contacts,
   * BSOD, tricks, score, pickups, hazards, streaming, glitch schedule). `dt` is always
   * SimClock.tickMs; slow-mo, blink and hit-stop scale the physics delta inside it.
   * @returns {'hold'|undefined} 'hold' when a Gym retry froze the new attempt.
   */
  simTick(dt, pad) {
    this.runTimeMs += dt;
    this._hudMs = (this._hudMs || 0) + dt;
    if (this._hudMs >= 100) {
      this._hudMs = 0;
      // flow fields resync the HUD meter (timeout drains in run-clock time, which slow-mo stretches)
      this.game.events.emit(HUD_SPEED_EVENT, {
        speedPxS: this.sled.speed, flow: this.score.getFlow(), flowFrac: this.score.getFlowTimeoutFraction(),
      });
    }

    // timers (real time)
    this.tickEffects(dt);
    this.resetCooldownMs = Math.max(0, this.resetCooldownMs - dt);
    if (pad.pressed.reset && this.resetCooldownMs <= 0) this.manualReset();

    // B3 hazard motion (rolling boulders, gates) moves sensor bodies: once per tick, before physics (issue #59).
    for (const list of this.hazards.values()) for (const h of list) if (h.motion) h.stepMotion(this.runTimeMs);

    // physics context
    const zoneDefs = this.getZoneDefs(this.sled.x);
    const sled = this.sled;
    sled.groundAngleDeg = this.slopeAt(sled.x);
    sled.scrambled = this.scrambleMs > 0 && !isWarded(this.wards, { effect: 'scramble' });
    const phys = this.tuner.getEffective(this.physicsContext(pad, zoneDefs));
    this.currentPhys = phys;

    // sub-stepped physics; slow-mo scales the delta, never the 8 ms limit
    sled.dropAheadDeg = this.dropAhead(sled);
    this.airForecast(sled);
    let simDt = dt * (this.slowmoMs > 0 ? this.slowmoScale : 1);
    if (this.blinkMs > 0) { this.blinkMs -= dt; simDt *= 0.35; }
    if (this.hitStopMs > 0) { this.hitStopMs -= dt; simDt = 0; }
    // A fixed input tick can run while physics is frozen. Preserve only
    // a valid unspent airborne press until the next actual controls step.
    // The tape retains the original edge; this causal latch is fingerprinted.
    if (simDt === 0 && pad.pressed.airBrake && !sled.grounded && !sled.airBrakeKickUsed)
      sled.airBrakePressPending = true;
    // A real contact can occur in one Matter substep and a buffered coyote
    // Hop relaunch in the NEXT substep of this same fixed tick. The final
    // sled frame would be airborne and otherwise lose the paid AirBrake
    // touchdown (or attach its points to a later unrelated landing).
    // Buffer actual contact snapshots before any later substep modifies pose.
    const substepTouchdowns=[];
    const landingLedger = { entries: [], combo: null, airTricks: 0 };
    let stepElapsedMs=0, kickSinceTouchdown=false, bluffKickSample=null;
    stepWorld(
      this.matter.world,
      simDt,
      (stepMs) => {
        const air = this.bsod ? this.bsod.state(sledLeftCollisionEdge(sled), sled.vx, this.bsodAtmosphere()) : null;
        // The kick is applied before Matter or the wall advances.
        const kickSample = air && {
          active: air.active, gapPx: air.gapPx, playerX: sled.x,
          nowMs: this.runTimeMs - dt + (simDt > 0 ? stepElapsedMs / simDt * dt : 0),
          grounded: !!sled.grounded, crashed: !!this.bsodCaught || (!!this.pendingCrash &&
            !(this.pendingCrash.cause === 'hazard' && (this.shieldCharges > 0 || sled.invulnerableMs > 0))),
          canopyDeployed: (sled.parachuteMs || 0) > 0,
          relativeAirX: air.relativeAirX, atmosphereDensity: air.atmosphereDensity,
        };
        sled.applyControls(pad, phys, stepMs, air);
        if (sled.airBrakeKickPulse) bluffKickSample = kickSample;
        // Integrate visual helicopter yaw over the upcoming physical
        // interval, BEFORE Matter can register a touchdown at its end.
        sled.stepHeli(stepMs);
      },
      (stepMs) => {
        const actualTouchdown=!!sled.endStep(stepMs);
        stepElapsedMs+=stepMs;
        // Preserve Flow expiry before the matching landing in the ledger;
        // yaw was already advanced before Matter resolved the contact.
        landingLedger.entries.push({ stepMs });
        const paidKick=!!sled.airBrakeKickPulse;
        if (paidKick) kickSinceTouchdown=true;
        sled.airBrakeKickPulse=0; // retain actual event in local ordered tick evidence
        if (actualTouchdown) {
          // Map the physical substep to the corresponding fixed run-clock
          // timestamp; slow-mo changes the physics delta, not the run clock.
          const atMs=this.runTimeMs-dt+
            (simDt>0 ? Math.min(1,stepElapsedMs/simDt)*dt : 0);
          const contactFs=sled.getFrameState(atMs,stepMs);
          // Grade against the real CONTACT slope, not the ground angle
          // sampled at the beginning of this potentially long fixed tick.
          // Terrain progression is unchanged; this read uses the same
          // existing slopeAt mechanism as the final-frame landing.
          contactFs.groundAngleDeg=this.slopeAt(contactFs.x);
          contactFs.grounded=true;
          contactFs.input.airBrakeKicked=kickSinceTouchdown;
          substepTouchdowns.push({fs:contactFs,kicked:kickSinceTouchdown});
          kickSinceTouchdown=false;
          bluffKickSample=null;
        }
        this.processContacts();
        // The BSOD advances with the SAME capped physics substeps as the sled. A fast wall cannot
        // jump over the rider between render frames. Do not depend on audio or animation timers.
        if (this.bsod && !this.bsodCaught) {
          this.bsod.advance(stepMs, sledLeftCollisionEdge(sled));
          const s = this.bsod.state(sledLeftCollisionEdge(sled), sled.vx, this.bsodAtmosphere());
          if (actualTouchdown) substepTouchdowns[substepTouchdowns.length-1].bsodState=s;
          if (s.gapPx <= 0) {
            this.bsodCaught = true;
            this.pendingCrash = { cause: 'bsod' };
          }
        }
        if (actualTouchdown) {
          // The contact has been resolved by Matter and sensor handlers,
          // and we know whether a terminal hazard/BSOD took priority.
          // Settle a REAL landing now, BEFORE the next physics substep:
          // wobble/boost/spring rebound must act on THIS flight's body,
          // not on a buffered new Hop that launches in the next substep.
          const absorbed=!!this.pendingCrash &&
            this.pendingCrash.cause==='hazard' &&
            (this.shieldCharges>0 || sled.invulnerableMs>0);
          if ((!this.pendingCrash || absorbed) && !landingLedger.badLanding)
            this.settlePhysicalTouchdown(substepTouchdowns[substepTouchdowns.length-1].fs, landingLedger);
        }
      },
    );
    this.flushDespawn();
    // One authoritative post-physics snapshot per frame. Music will subscribe later; physics never
    // reads from that subscriber. An inactive/reset snapshot is emitted at run termination.
    if (this.bsod && !this.crashed) {
      this.bsodState = this.bsod.state(sledLeftCollisionEdge(sled), sled.vx, this.bsodAtmosphere());
      this.publishBsodState(this.bsodState);
    }
    // The ledger retains the exact substep Flow/landing chronology;
    // only surviving ticks may commit the landing awards.

    // SFX with no event: push / hop (+ wind speed every frame)
    const audio = this.registry.get(REG.AUDIO);
    if (audio) {
      try {
        if (sled.hopPulse) audio.playSfx('hop');
        if (sled.pushPulse) audio.playSfx('push');
        if (audio.setSpeed) audio.setSpeed(sled.speed);
        if (audio.setAirborne) audio.setAirborne(!sled.grounded);
      } catch (e) { /* audio must never break the loop */ }
    }
    if (sled.hopPulse) this._lastHopMs = this.runTimeMs; // crash report: the hop verdict
    this._hopped = !!sled.hopPulse;
    this._pushed = !!sled.pushPulse;
    const airBrakeKickedThisTick = kickSinceTouchdown; // only the current flight
    sled.airBrakeKickPulse = 0; // consumed per substep; always zero at replay checkpoint
    sled.hopPulse = 0;
    sled.pushPulse = 0;

    // ground slope for landing alignment (post-step position)
    sled.groundAngleDeg = this.slopeAt(sled.x);

    // void check (fell into a wireless gap / off the world)
    if (!this.pendingCrash) {
      const gy = this.terrain.heightAt(sled.x);
      if (!Number.isFinite(sled.y) || (Number.isFinite(gy) && sled.y > gy + TUNING.voidDepthPx)) {
        this.pendingCrash = { cause: 'chasm' };
      }
    }

    // Trick yaw was advanced through each physical substep, including
    // any touchdown, rather than applying an extra full-tick rotation here.
    const fs = sled.getFrameState(this.runTimeMs, dt);
    if (substepTouchdowns.length) {
      // This is a NEW flight after a genuine physical contact. Count only
      // the interval since the most recent touchdown, never pre-contact time.
      const lastContactMs=substepTouchdowns[substepTouchdowns.length-1].fs.timeMs;
      fs.dtMs=Math.max(0,this.runTimeMs-lastContactMs);
    }
    fs.input.airBrakeKicked = airBrakeKickedThisTick; // earlier kicks were settled at real contacts
    // a hazard hit that a shield charge (or post-respawn grace) will absorb leaves the sled flying: keep its air phase
    const absorbed = !!this.pendingCrash && this.pendingCrash.cause === 'hazard' && (this.shieldCharges > 0 || sled.invulnerableMs > 0);
    fs.crashed = !!this.pendingCrash && !absorbed;
    // All genuine touches already applied their physical consequences.
    // Score/event publication remains staged until crash priority is known.
    const upd = this.tricks.update(fs) || {};
    this.maxAirtimeMs = Math.max(this.maxAirtimeMs, upd.airtimeMs || 0, sled.airtimeMs);

    // A fallback final-frame landing must be graded before committing any
    // earlier touchdown rewards. It cannot outrank a terminal wall/hazard.
    const finalLanding = (!this.pendingCrash || absorbed) ? this.gradeLanding(upd.landing) : null;
    if (finalLanding?.quality === 'crash') {
      landingLedger.badLanding = true;
      landingLedger.entries.push({ crashLanding: finalLanding, fs });
    }
    // Sensor/void causes have priority over provisional contact grading.
    // A shield-absorbed hazard plus a bad landing still requires a backup
    // respawn, as in the prior final-frame landing path.
    if (landingLedger.badLanding && (!this.pendingCrash || absorbed))
      this.pendingCrash = { cause: 'badLanding' };

    // zones, safe-ground samples
    this.updateZones(sled.x);
    this.sampleSafeGround(dt, fs);

    // Issue #47: the Kodiak rival (if one is out) runs, telegraphs and may shove the sled this tick.
    this.updateKodiaks(dt);

    // Collision with the deletion wall always wins if any other contact/landing happened during this frame.
    if (this.bsodCaught) this.pendingCrash = { cause: "bsod" };
    const survivedLanding = !this.pendingCrash || (this.pendingCrash.cause === 'hazard' &&
      (this.shieldCharges > 0 || sled.invulnerableMs > 0));
    this.commitTouchdownLedger(landingLedger, survivedLanding);
    if (survivedLanding) this.handleTricksAndLanding(upd, fs, { gradedLanding: finalLanding });
    // crash resolution (may be negated by Hashed Backup, except the BSOD)
    if (this.pendingCrash) this.resolveCrash(fs);
    // The replacement attempt remains frozen even for this crash frame.
    if (this.bsodGym && this.gymReadyMs > 0) return 'hold';

    if (!this.crashed) {
      // A physical landing split the flight. Only a paid kick AFTER the
      // last contact belongs to this relaunched encounter; never carry a
      // tick-wide pre-touchdown brake bonus into the new flight.
      this.updateBsodBluff(
        substepTouchdowns.length ? kickSinceTouchdown : airBrakeKickedThisTick,
        substepTouchdowns, bluffKickSample);
      // Gym may continue through the same terrain, but score/distance belongs
      // only to the current attempt. Never recredit earlier travel on a retry.
      const origin = this.bsodGym ? this.gymAttemptStartX : this.startX;
      const metres = Math.max(0, (sled.x - origin) / PIXELS_PER_METER);
      this.updateFun(dt, pad, metres);
      // distance
      if (this.score.setDistance(metres)) {
        this.game.events.emit(EVT.DISTANCE_CHANGED, { meters: Math.floor(this.score.distanceM) });
        this.emitScore();
      }

      // terrain streaming
      this.streamTerrain(sled.x);

      // glitch schedule
      const gr = this.glitch.update(this.runTimeMs, this.score.distanceM) || {};
      for (const e of gr.ended || []) this.game.events.emit(EVT.GLITCH_END, { id: e.id });
      for (const e of gr.started || []) {
        this.game.events.emit(EVT.GLITCH_START, { id: e.id, kind: e.kind, durationMs: e.durationMs, intensity: e.intensity });
      }
    }

  }

  /** Visuals shared by live and crashed frames that need the sled. */
  renderFrame(dt) {
    const sled = this.sled;
    if (!sled || !this.cameras.main) return;
    sled.shield = this.shieldCharges > 0;
    if (!this.crashed) {
      sled.render(dt);
      // trail anchored at the rear runner
      const a = sled.body.angle;
      const c = pmath.cos(a);
      const s = pmath.sin(a);
      this.trail.update(sled.x + c * -16 - s * 6, sled.y + s * -16 + c * 6, sled.speed);
    }
    // the crash beat (CrashReport.crashBeat): hit-stop, then 400 ms of FX at 0.25x; visual only, the run clock is stopped
    const fxDt = this.hitStopMs > 0 ? dt * 0.08 : this.crashed ? dt * crashBeat(this.crashTimerMs, TUNING.hitStopCrashMs).fxScale : dt;
    this.updateCamera(dt);
    const cam = this.cameras.main;
    const halfW = GAME_WIDTH / (2 * cam.zoom);
    const left = cam.scrollX + GAME_WIDTH / 2 - halfW;
    const right = cam.scrollX + GAME_WIDTH / 2 + halfW;
    this._view = { left, right, top: cam.scrollY + GAME_HEIGHT / 2 - GAME_HEIGHT / (2 * cam.zoom), bottom: cam.scrollY + GAME_HEIGHT / 2 + GAME_HEIGHT / (2 * cam.zoom) };
    this.mesh.cull(left - 40, right + 40);
    const t = this.runTimeMs;
    for (const list of this.hazards.values()) for (const h of list) h.update(t, left, right);
    for (const list of this.powerups.values()) for (const p of list) p.update(t, left, right);
    this.fx.update(fxDt, this.heightFn);
    if (this.shardField) this.shardField.update(t, left, right);
    if (this.kodiaks?.length || this.kodiakRider) {
      if (!this.kodiakRider) this.kodiakRider = new KodiakRider(this, this.palette);
      this.kodiakRider.update(this.crashed ? [] : this.kodiaks, this._view, cam.zoom, t, isReducedMotion(this));
    }
    if (this.magnetMs > 0 && !this.crashed) {
      if (!this.blackHole) this.blackHole = new BlackHole(this, this.palette);
      this.blackHole.update(t, magnetHolePos(sled.x, sled.y), magnetStrength(this.magnetEff, this.upgradeFx?.magnetMul), this.magnetMs, isReducedMotion(this));
    } else this.blackHole?.update(t, null, null, 0);
    if (this.bestMarker) this.bestMarker.update(t, sled.x, this.markerHeightFn);
    if (this.deathMarker) this.deathMarker.update(t, sled.x, this.markerHeightFn);
    if (this.bestMarker && this.deathMarker) {
      // BEST and DIED HERE are often at the same x: lay their labels out together so they never overprint
      const known = (m) => (m.y != null ? { x: m.x, y: m.y } : null);
      const L = layoutMarkerLabels(known(this.bestMarker), known(this.deathMarker));
      this.bestMarker.setPlacement(L.best);
      this.deathMarker.setPlacement(L.death);
    }
    this.drawStreaks(t);
    if (this.groundTelegraph) this.groundTelegraph.update(t, this.crashed ? null : this._teleMarks, this._view, cam.zoom, this.terrain?.activeList);
    // Visual-only world dance: no music player/beat-grid mutation, and no
    // hidden synthetic tempo. With a muted/paused song or reduced motion the
    // backdrop returns immediately to its original neutral geometry.
    const danceAllowed=worldDanceMotionAllowed(this.settings,
      this._worldDanceMotionQuery?.matches===true);
    const audio=this.registry?.get?.(REG.AUDIO);
    // Never throws: a failing audio engine must not stop the frame (and with it Phaser's loop), issue #140.
    const {sample,meter}=readWorldDanceAudio(audio,danceAllowed);
    const dance=this.worldDance?.update(sample,dt,meter)||0;
    this.bg.update(cam.scrollX, t, sled.speed,dance);
    if (this.biomeFx) this.biomeFx.update(cam.scrollX, t, this._veil || 0, isReducedMotion(this));
    this.songBillboard?.update(dt,dance,!danceAllowed);
    this.drawBsodCues();
    if (this.flashRect.alpha > 0) this.flashRect.setAlpha(Math.max(0, this.flashRect.alpha - dt / 350));
    this.updateBlindOverlay();
  }

  /**
   * The PhysicsTuner context for this frame: zones, daily rule, timed hazard effects and power-ups (B0: wards, glide,
   * stabilize). A warded slow / scramble stops acting while the ward lasts.
   * @param {Object} pad normalized pad.
   * @param {Object[]} [zoneDefs] mod defs under the sled (default: looked up at the sled x).
   */
  physicsContext(pad, zoneDefs) {
    const sled = this.sled;
    return {
      tucked: !!pad.tuck,
      zones: zoneDefs || this.getZoneDefs(sled.x),
      daily: this.dailyMods,
      scrambled: this.scrambleMs > 0 && !isWarded(this.wards, { effect: 'scramble' }),
      slowed: this.slowMs > 0 && !isWarded(this.wards, { effect: 'slow' }),
      slowFactor: this.slowFactor,
      // Decision 4: Head Start's opening surge multiplies in for its window only (exactly 1 afterwards).
      speedBoost: (this.boostMs > 0 ? this.boostFactor : 1) * wardSpeedMul(this.wards)
        * openingSpeedMul(this.opening, this.bsodGym
          ? this.runTimeMs - this.gymAttemptStartTimeMs : this.runTimeMs),
      upgradeEffects: this.upgradeFx,
      timeMs: this.runTimeMs,
      parachute: !!pad.parachute && !sled.grounded && (sled.parachuteFuelMs ?? PHYSICS.parachuteDurationMs) > 0,
      airBrake: !!pad.airBrake && !sled.grounded,
      atmosphereDensity: this.bsodAtmosphere(),
      airborne: !sled.grounded,
      braking: !!pad.brake,
      wards: this.wards,
      glideFrictionMul: this.glideMs > 0 ? this.glideMul : 1,
      stabilizeBounceMul: this.stabilizeMs > 0 ? this.stabilizeBounce : 1,
    };
  }

  /** B0 biome effect state (wards, glide, stabilize, blind), cleared at run start. */
  _resetBiomeEffects() {
    this.wards = emptyWards();
    this.glideMs = 0;
    this.glideMul = 1;
    this.glideId = null;
    this.stabilizeMs = 0;
    this.stabilizeDeg = 0;
    this.stabilizeBounce = 1;
    this.stabilizeId = null;
    this.blindMs = 0;
    this.blindTotalMs = 0;
    this.blindVis = 1;
    this.magnetMs = 0;
    this.magnetEff = null;
    this.magnetId = null;
  }

  /** B0: end every biome effect now (manual reset), reporting each the way its HUD chip expects. */
  _endBiomeEffects(reason) {
    for (const w of this.wards.wards) this.game.events.emit(EVT.POWERUP_EXPIRED, { id: w.id, reason });
    if (this.glideMs > 0) this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.glideId, reason });
    if (this.stabilizeMs > 0) this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.stabilizeId, reason });
    if (this.blindMs > 0) this.game.events.emit(EVT.EFFECT_END, { effect: 'blind' });
    if (this.magnetMs > 0) this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.magnetId, reason });
    this._resetBiomeEffects();
    this.updateBlindOverlay();
  }

  /** B0 timers (real time, like the other effects). */
  tickBiomeEffects(dt) {
    const r = tickWards(this.wards, dt);
    for (const id of r.expired) this.game.events.emit(EVT.POWERUP_EXPIRED, { id, reason: 'timeout' });
    if (this.glideMs > 0) {
      this.glideMs -= dt;
      if (this.glideMs <= 0) { this.glideMs = 0; this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.glideId, reason: 'timeout' }); }
    }
    if (this.stabilizeMs > 0) {
      this.stabilizeMs -= dt;
      if (this.stabilizeMs <= 0) { this.stabilizeMs = 0; this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.stabilizeId, reason: 'timeout' }); }
    }
    if (this.magnetMs > 0) {
      this.magnetMs -= dt;
      if (this.magnetMs <= 0) { this.magnetMs = 0; this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.magnetId, reason: 'timeout' }); }
    }
    if (this.blindMs > 0) {
      this.blindMs -= dt;
      if (this.blindMs <= 0) { this.blindMs = 0; this.game.events.emit(EVT.EFFECT_END, { effect: 'blind' }); }
    }
  }

  /** B0: alpha of the blind overlay for this frame (0 when not blinded or when blind is warded). */
  updateBlindOverlay() {
    if (!this.blindRect) return;
    const a = this.blindMs > 0 && !isWarded(this.wards, { effect: 'blind' }) ? blindOverlayAlpha(this.blindMs, this.blindTotalMs, this.blindVis) : 0;
    if (this.blindRect.alpha !== a) this.blindRect.setAlpha(a);
  }

  /** Airborne only: ballistic ms to touchdown and the ground slope there (sled.airEtaMs / airSlopeDeg), for Sled's hands-off levelling. */
  airForecast(sled) {
    if (sled.grounded) { sled.airEtaMs = Infinity; sled.airSlopeDeg = null; return; }
    const g = (this.currentPhys && this.currentPhys.gravityPxS2) || 900;
    for (let ms = 20; ms <= 2500; ms += 20) {
      const ts = ms / 1000;
      const x = sled.x + sled.vx * ts;
      if (sled.y + sled.vy * ts + 0.5 * g * ts * ts + 14 >= this.terrain.heightAt(x)) { sled.airEtaMs = ms; sled.airSlopeDeg = this.slopeAt(x); return; }
    }
    sled.airEtaMs = Infinity;
    sled.airSlopeDeg = null;
  }

  /** How many degrees steeper (downhill) the ground gets a short way ahead; large for kickers / drops. */
  dropAhead(sled) {
    const ahead = clamp(Math.abs(sled.vx) * 0.1, 24, 90);
    const here = this.slopeAt(sled.x);
    return this.slopeAt(sled.x + ahead) - here;
  }

  /** Subtle speed streaks (world space, additive), only at high speed. */
  drawStreaks(t) {
    const g = this.streaks;
    if (!g) return;
    g.clear();
    const sled = this.sled;
    const k = smooth01((sled.speed - TUNING.streakSpeedLo) / (TUNING.streakSpeedHi - TUNING.streakSpeedLo));
    if (k <= 0.02 || !this._view || this.crashed) return;
    const v = this._view;
    const w = v.right - v.left;
    const h = v.bottom - v.top;
    const sp = sled.speed || 1;
    const dx = sled.vx / sp;
    const dy = sled.vy / sp;
    const len = 26 + 60 * k;
    g.lineStyle(1, this.palette.text, 0.22 * k);
    for (let i = 0; i < 16; i++) {
      const fx = (((i * 0.6180339 + 0.13) % 1) * w * 1.0 - sled.x * (0.35 + (i % 4) * 0.12) + w * 8) % w;
      const fy = ((i * 0.3819660 + 0.07) % 1) * h * 0.85 + ((t * 0.02 * (1 + i % 3)) % 6);
      const x = v.left + (fx + w) % w;
      const y = v.top + fy;
      g.lineBetween(x, y, x - dx * len, y - dy * len);
    }
  }

  tickEffects(dt) {
    this.tickBiomeEffects(dt);
    if (this.slowMs > 0) {
      this.slowMs -= dt;
      if (this.slowMs <= 0) {
        this.slowMs = 0;
        this.game.events.emit(EVT.EFFECT_END, { effect: 'slow' });
      }
    }
    if (this.scrambleMs > 0) {
      this.scrambleMs -= dt;
      if (this.scrambleMs <= 0) {
        this.scrambleMs = 0;
        this.sled.scrambled = false;
        this.game.events.emit(EVT.EFFECT_END, { effect: 'scramble' });
      }
    }
    if (this.boostMs > 0) {
      this.boostMs -= dt;
      if (this.boostMs <= 0) {
        this.boostMs = 0;
        this.game.events.emit(EVT.POWERUP_EXPIRED, { id: this.boostId || 'packetBurst', reason: 'timeout' });
      }
    }
    if (this.slowmoMs > 0) {
      this.slowmoMs -= dt;
      if (this.slowmoMs <= 0) {
        this.slowmoMs = 0;
        this.game.events.emit(EVT.POWERUP_EXPIRED, { id: 'clockPulse', reason: 'timeout' });
      }
    }
  }

  flushDespawn() {
    if (!this._despawn || !this._despawn.length) return;
    for (const p of this._despawn) {
      for (const [idx, list] of this.powerups) {
        const i = list.indexOf(p);
        if (i >= 0) {
          list.splice(i, 1);
          if (!list.length) this.powerups.delete(idx);
          break;
        }
      }
      p.destroy();
    }
    this._despawn.length = 0;
  }

  // ------------------------------------------------------------------ tricks / landings / score

  /** Grade once at the actual contact, before a later pickup can change tolerance. */
  gradeLanding(landing) {
    if (!landing) return null;
    let l = resolveLanding(landing, this.stabilizeMs > 0 ? this.stabilizeDeg : 0, TUNING);
    if (l.shortAirBrakeTouchdown && l.quality === 'perfect') l = { ...l, quality: 'good' };
    return l;
  }

  /** Apply causal body changes at contact, but stage score/event publication.
   * The preview only needs combo types and trick count (not points or Flow).
   * Clock steps and real score operations are committed in their original order.
   */
  settlePhysicalTouchdown(fs, ledger = null) {
    const upd = this.tricks.update(fs) || {};
    this.maxAirtimeMs = Math.max(this.maxAirtimeMs || 0, upd.airtimeMs || 0);
    if (!ledger) { this.handleTricksAndLanding(upd, fs); return upd; }
    const l = this.gradeLanding(upd.landing);
    if (l?.quality === 'crash') {
      // Do not occupy pendingCrash: subsequent sensor hits must be able
      // to report their true cause (especially a fatal hazard).
      ledger.badLanding = true;
      ledger.entries.push({ crashLanding: l, fs });
      return upd;
    }
    if (!ledger.combo) {
      ledger.combo = new Set(this.score.getSnapshot().comboTricks);
      ledger.airTricks = this._airTricks;
    }
    for (const t of upd.tricks || []) {
      ledger.combo.add(t.type);
      ledger.airTricks += Math.max(1, t.count || 1);
    }
    let boostEvent;
    if (l) {
      const types = [...ledger.combo];
      boostEvent = this.applyLandingPhysics(l, this.score.getMultiplier(types),
        Math.max(ledger.airTricks, types.length), fs, false);
      ledger.combo.clear();
      ledger.airTricks = 0;
    }
    ledger.entries.push({ upd, fs, options: {
      gradedLanding: l, physicalApplied: true, boostEvent,
      zoneScoreMul: l ? this._zoneScoreMulAt(fs.x) : undefined,
    } });
    return upd;
  }

  /** A terminal collision anywhere in the tick forfeits its staged rewards.
   * Flow still advances, and older banked points and unrelated bonuses survive.
   */
  commitTouchdownLedger(ledger, survived) {
    for (const entry of ledger.entries) {
      if (entry.stepMs !== undefined) this.emitFlow(this.score.tick(entry.stepMs));
      else if (survived && entry.upd) this.handleTricksAndLanding(entry.upd, entry.fs, entry.options);
      else if (entry.crashLanding && this.pendingCrash?.cause === 'badLanding') {
        this.emitCrashLanding(entry.crashLanding, entry.fs);
      }
    }
  }

  emitCrashLanding(l, fs) {
    this.game.events.emit(EVT.LANDING, {
      quality: 'crash', angleDeg: l.angleDeg || 0, impactSpeedPxS: l.impactSpeedPxS || 0,
      airtimeMs: l.airtimeMs || 0, bonusPoints: 0, bankedPoints: 0, hard: true, x: fs.x, y: fs.y,
    });
  }

  emitScore() {
    const total = this.score.getTotal();
    const delta = total - this.lastTotal;
    this.lastTotal = total;
    this.game.events.emit(EVT.SCORE_CHANGED, {
      total, distancePoints: this.score.getDistancePoints(), trickPoints: this.score.trickPoints, delta,
    });
  }

  emitCombo(reason) {
    const snap = this.score.getSnapshot();
    this.bestCombo = Math.max(this.bestCombo, snap.multiplier);
    this.game.events.emit(EVT.COMBO_CHANGED, {
      multiplier: snap.multiplier, tricks: snap.comboTricks, pendingPoints: snap.pendingPoints, reason,
    });
  }

  /** Publish a ScoreManager FlowChange: FLOW_LOST when cleared, else FLOW_CHANGED when the value moved. */
  emitFlow(fc) {
    if (!fc) return;
    if (fc.lost) {
      this.game.events.emit(EVT.FLOW_LOST, { previous: fc.previous, reason: fc.reason });
    } else if (fc.changed) {
      this.game.events.emit(EVT.FLOW_CHANGED, {
        flow: fc.flow, previous: fc.previous, reason: fc.reason, timeoutFrac: fc.timeoutFrac, best: fc.best,
      });
    }
  }

  handleTricksAndLanding(upd, fs, options = {}) {
    for (const t of upd.tricks || []) {
      const r = this.score.addTrick(t);
      const n = Math.max(1, t.count || 1);
      this.trickCounts[t.type] = (this.trickCounts[t.type] || 0) + n;
      this.game.events.emit(EVT.TRICK, {
        type: t.type, count: n, value: r.value, isNew: r.isNew, airtimeMs: t.airtimeMs != null ? t.airtimeMs : upd.airtimeMs || 0,
      });
      this._airTricks += n;
      if (/flip$/i.test(t.type)) this.tutDoneId('flip');
      this.emitCombo('trick');
      this.fx.sparks(fs.x, fs.y - 14, r.isNew ? this.palette.amber : this.palette.cyan, 8, 150, 60);
    }
    const l = options.gradedLanding === undefined ? this.gradeLanding(upd.landing) : options.gradedLanding;
    if (!l) return;
    this.maxAirtimeMs = Math.max(this.maxAirtimeMs, l.airtimeMs || 0);
    const airTricks = this._airTricks;
    this._airTricks = 0;
    if (l.quality === 'crash') {
      this.emitCrashLanding(l, fs);
      this.pendingCrash = { cause: 'badLanding' };
      return;
    }
    const pre = this.score.getSnapshot();
    const mult = pre.multiplier || 1;
    const nTricks = Math.max(airTricks, (pre.comboTricks || []).length);
    const r = this.score.onLanding(l, { zoneScoreMul: options.zoneScoreMul ?? this._zoneScoreMulAt(fs.x) });
    this.game.events.emit(EVT.LANDING, {
      quality: l.quality, angleDeg: l.angleDeg || 0, impactSpeedPxS: l.impactSpeedPxS || 0, airtimeMs: l.airtimeMs || 0,
      bonusPoints: r.bonus, bankedPoints: r.banked, hard: !!l.hard, x: fs.x, y: fs.y,
      // additive (HUD): named combo, the multipliers applied, and whether an unfinished helicopter spin cost a grade
      comboName: r.comboName || '', comboMult: r.multiplierUsed, flowUsed: r.flowUsed, midSpin: !!l.midSpin,
    });
    this.emitFlow(r.flowChange);
    this.emitCombo('landing');
    this.emitScore();
    const col = l.quality === 'perfect' ? this.palette.lime : l.quality === 'sloppy' ? this.palette.amber : this.palette.cyan;
    const imp = l.impactSpeedPxS || 0;
    this.fx.sparks(fs.x, fs.y + 8, col, Math.round(clamp(6 + imp / 45, 6, 28)), clamp(110 + imp * 0.25, 110, 280), 90);
    if (l.quality === 'perfect') this.fx.ring(fs.x, fs.y + 10, this.palette.lime, 30, 360);
    if (l.hard) this.shake(TUNING.shakeHardLanding);
    if (l.quality === 'perfect' || l.hard) {
      this.hitStopMs = Math.max(this.hitStopMs, TUNING.hitStopLandingMs);
      this.sled.squash = l.hard ? 1 : 0.6;
    } else if (imp > 250) this.sled.squash = 0.35;
    this._landings += 1;
    if (options.physicalApplied) {
      if (options.boostEvent) this.emitIf(EVT.LANDING_BOOST, options.boostEvent);
    } else this.applyLandingPhysics(l, mult, nTricks, fs);
  }

  applyLandingPhysics(l, mult, nTricks, fs, publish = true) {
    if (l.shortAirBrakeTouchdown) {
      // Micro-touches cannot manufacture boost/rebound, but still pay wobble.
      if (l.quality === 'sloppy') this.sled.wobble(TUNING.sloppySpeedKeep);
      return;
    }
    const event = this.applyLandingBoost(l, mult, nTricks, fs, publish);
    this.applySpringRebound(l, fs);
    return event;
  }

  /**
   * Sky Jellyfish felt bounce: a scored (non-crash) landing inside a zone with `physics.landingRebound` throws the sled
   * back away from the landing slope by BiomeEffects.springRebound of its impact speed (bounded, decaying; the Rails
   * damp the share in PhysicsTuner). Sled.launchNormal preserves the along-slope velocity, so a descent never turns
   * forward speed into extra bounce. Runs after the landing boost, so a sloppy wobble's velocity cut does not eat the
   * rebound.
   */
  applySpringRebound(l, fs) {
    const share = this.currentPhys ? this.currentPhys.landingRebound : 0;
    const up = springRebound(l.impactSpeedPxS || 0, share);
    if (!(up > 0)) return;
    const angle = fs && Number.isFinite(fs.groundAngleDeg) ? fs.groundAngleDeg : this.sled.groundAngleDeg;
    this.sled.launchNormal(up, Number.isFinite(angle) ? angle : 0);
    if (fs) this.fx.ring(fs.x, fs.y + 8, this.palette.lime, 20, 260);
  }

  /** Trick -> speed loop (TUNING.boost*): a clean landing after tricks gives a forward burst and a stretch of low drag. */
  applyLandingBoost(l, mult, nTricks, fs, publish = true) {
    const sled = this.sled;
    if (l.quality === 'sloppy') {
      sled.wobble(TUNING.sloppySpeedKeep);
      return;
    }
    let amt = 0;
    if (nTricks > 0) {
      amt = TUNING.boostBasePxS * mult * (1 + TUNING.boostTrickCountBonus * (nTricks - 1));
      if (l.quality === 'perfect') amt *= TUNING.boostPerfectMul;
      amt = Math.min(TUNING.boostCapPxS, amt);
    } else if (l.quality === 'perfect') {
      amt = TUNING.boostPerfectNoTrickPxS;
    }
    if (amt <= 0) return;
    sled.addForwardSpeed(amt);
    sled.boostMs = TUNING.boostDragMs;
    this.lastBoost = { amountPxS: Math.round(amt), t: this.runTimeMs };
    const event = { amountPxS: Math.round(amt), quality: l.quality, comboMult: mult, tricks: nTricks };
    if (publish) this.emitIf(EVT.LANDING_BOOST, event);
    const k = amt / TUNING.boostCapPxS;
    const sp = sled.speed || 1;
    const bx = fs.x - (sled.vx / sp) * 18;
    const by = fs.y - (sled.vy / sp) * 18 + 6;
    this.fx.ring(fs.x, fs.y + 6, this.palette.amber, 38 + 30 * k, 420);
    this.fx.sparks(bx, by, this.palette.lime, 10 + Math.round(14 * k), 260 + 160 * k, 20);
    this.fx.sparks(bx, by, this.palette.amber, 6, 200, 10);
    this._zoomKick = Math.max(this._zoomKick, 0.025 + 0.04 * k);
    this.shake(1 + 1.5 * k);
    return event;
  }

  // ------------------------------------------------------------------ fun-pass systems

  /** Emit scheduler transitions (UIScene draws one hint at a time) and persist what they imply. */
  applyHintEvents(events) {
    for (const e of events) {
      if (e.show) this.tutShown.add(e.id); else this.tutShown.delete(e.id);
      this.emitIf(EVT.TUTORIAL_HINT, e);
      if (e.id === 'tuck' && e.show) {
        this.tuckShows += 1;
        if (!this.bsodGym) saveTuckShows(this.tuckShows);
      } else if (!e.show && ((e.id === 'boost') || (e.id === 'tuck' && this.tuckShows >= TUNING.tuckHintMaxShows))) {
        this.tutDoneId(e.id); // explained once / shown often enough
      }
    }
  }

  /** The player did what the hint asks: hide it and never show it again (persisted). */
  tutDoneId(id) {
    if (this.tutDone.has(id)) return;
    const ev = this.hints.complete(id, this.runTimeMs);
    // Practice hints may be completed for this session, but never consume a
    // first-run hint in the player's permanent normal-game tutorial history.
    if (!this.bsodGym) saveTutorialDone(this.tutDone);
    this.applyHintEvents(ev);
  }

  /** Per-frame: shards, near misses, milestones / best marker, first-run hints. */
  updateFun(dt, pad, metres) {
    const sled = this.sled;
    const now = this.runTimeMs;

    // shards
    if (this.shardField) {
      let got = this.shardField.collect(sled.x, sled.y - 6, TUNING.shardRadiusPx);
      if (this.magnetMs > 0) {
        // Shards fall into the hole (hovering over the rider) and are collected there.
        const m = magnetStrength(this.magnetEff, this.upgradeFx?.magnetMul), h = magnetHolePos(sled.x, sled.y);
        this.shardField.pull(h.x, h.y, m.radius, (sx, sy, x, y) => pullStep(sx, sy, x, y, m.radius, m.speed, dt));
        got = got.concat(this.shardField.collect(h.x, h.y, TUNING.shardRadiusPx));
      }
      for (const sh of got) {
        if (now - this.shardChainAt > TUNING.shardChainMs) this.shardChain = 0;
        this.shardChain += 1;
        this.shardChainAt = now;
        const points = Math.min(TUNING.shardPointsCap, TUNING.shardPointsPerChain * this.shardChain);
        this.bonus(points, 'shard');
        this.shardTotal += points;
        this.shardCount = (this.shardCount || 0) + 1;
        this.emitIf(EVT.SHARD_COLLECTED, { chain: this.shardChain, points, total: this.shardTotal, count: this.shardCount, x: sh.x, y: sh.y });
        this.fx.ring(sh.x, sh.y, this.palette.lime, 16 + Math.min(14, this.shardChain * 2), 260);
        this.fx.sparks(sh.x, sh.y, this.palette.lime, 6 + Math.min(8, this.shardChain), 150);
      }
    }

    // near misses + first-hazard hint
    let hazardDx = Infinity;
    const marks = [];
    for (const list of this.hazards.values()) {
      for (const h of list) {
        if (h.hit || (h.def.onHit && h.def.onHit.effect !== 'crash')) continue;
        // air hazards (roguePacket) float: hy is the box CENTRE, not a ground contact, and hopping is the wrong answer
        const air = h.def.placement === 'air';
        const dxh = h.cx - sled.x;
        if (!air && dxh > 0 && dxh < hazardDx) hazardDx = dxh;
        if (air && !h.warned && !h.hit && dxh > 0 && dxh < TUNING.airWarnAheadPx) {
          h.warned = true;
          h.alert = true;
          this.playSfx('airWarn');
        }
        if (air && h.alert && h.lip && dxh > 0) marks.push({ lip: h.lip, box: { x: h.cx, y: h.cy } });
        const side = sled.x >= h.cx ? 1 : -1;
        if (h._side === -1 && side === 1 && !h.nearMissed) {
          const dy = sled.y - h.cy;
          const below = air ? TUNING.airNearMissBelowPx : TUNING.nearMissBelowPx;
          // air hazards: flying UNDER it (airborne at the box x) is the normal line and pays; the window covers the whole no-hop family
          if (air && (sled.invulnerableMs > 0 || dy <= h.h / 2)) {
            // no payout while passing through the box under grace, and only a sled BELOW the box bottom counts
          } else if ((!air || !sled.grounded) && dy > -(h.h / 2 + TUNING.nearMissAbovePx) && dy < h.h / 2 + below) {
            h.nearMissed = true;
            this.nearMissCount = (this.nearMissCount || 0) + 1;
            this.bonus(TUNING.nearMissPoints, 'nearMiss');
            this.emitIf(EVT.NEAR_MISS, { hazardType: h.def.id, points: TUNING.nearMissPoints, x: h.cx, y: h.cy });
            this.blinkMs = TUNING.nearMissSlowMs;
            const fy = air ? h.cy : h.cy - h.h / 2;
            this.fx.sparks(h.cx, fy, this.palette.amber, 12, 220, 60);
            this.fx.ring(h.cx, fy, this.palette.amber, 26, 300);
          }
        }
        h._side = side;
      }
    }

    if (this.airTelegraph) this.airTelegraph.update(now, sled.x, marks);
    this.updateGroundTelegraph(now);

    // milestones + best marker
    // ScoreManager pays each completed sector exactly once (addBonus 'milestone'); the scene only announces it
    for (const m of this.score.checkMilestones(metres)) {
      this.emitScore();
      this.emitIf(EVT.MILESTONE, { sector: m.sector, distanceM: m.distanceM, points: m.points });
      this.flashRect.setFillStyle(this.palette.cyan, 1).setAlpha(0.2);
      this.fx.ring(sled.x, sled.y, this.palette.cyan, 70, 600);
      this.fx.sparks(sled.x, sled.y - 6, this.palette.cyan, 14, 240, 40);
    }
    // W3: announce the biome we are in, when it changes. Driven by the sled's current position rather
    // than by chunk callbacks so it cannot fire out of order or twice for one crossing. #65: the biome is the
    // generator's own answer at the sled's x, so an arcade bridge (null) is its own stretch: entering it and
    // entering the next biome each fire once, and a run opens in the home biome.
    const biomeNow = this.terrain.biomeAtX(this.sled.x);
    const biomeChanged = this._biomeId !== biomeNow;
    let def = null;
    let first = false;
    if (biomeChanged) {
      first = this._biomeId === undefined;
      this._biomeId = biomeNow;
      def = this._biomeDefById(biomeNow);
      const sectorNow = this.terrain._sectorOf(this.sled.x);
      if (def) this.emitIf(EVT.BIOME_ENTER, { id: def.id, name: def.name, sector: sectorNow, entering: true });
      else if (!first) this.emitIf(EVT.BIOME_ENTER, { id: null, name: 'Bitstream', sector: sectorNow, entering: false });
    }
    // The biome's palette only takes effect if something applies it. Repaint on entry AND on exit
    // back to arcade terrain, or the tint would persist past the biome that owns it. refreshPalette repaints graphics
    // only (#140: colliders are never touched), so it runs when the generator's biome changed and a repaint was actually
    // owed: a run with no biome content never repaints beyond a palette setting change. #65 presentation: the look
    // (what the world is painted as) can change at other x than that (inside an arcade bridge) and repaints the same way.
    this._updateLook(biomeNow, biomeChanged && (def !== null || !first));
    if (this.bestM > 0 && !this.newBestDone && metres > this.bestM) {
      this.newBestDone = true;
      this.emitIf(EVT.NEW_BEST, { distanceM: Math.floor(metres), previousBestM: this.bestM });
      if (this.bestMarker) this.bestMarker.markPassed();
      this.flashRect.setFillStyle(this.palette.amber, 1).setAlpha(0.28);
      this.fx.ring(sled.x, sled.y, this.palette.amber, 80, 700);
      this.fx.sparks(sled.x, sled.y - 6, this.palette.amber, 20, 280, 60);
    }

    // first-run hints: triggers only; HintScheduler decides what is on screen (one at a time, readable, prioritised)
    if (this._pushed) this.tutDoneId('push');
    if (this._hopped && this.tutShown.has('hop')) this.tutDoneId('hop');
    if (pad.tuck && sled.grounded) this.tutDoneId('tuck');
    this.tutTimers.stall = sled.grounded && sled.speed < 20 && now > 800 ? this.tutTimers.stall + dt : 0;
    const wants = {};
    wants.push = this.tutTimers.stall > 700;
    // hop: HOP_HINT_LEAD_S of travel before the hazard (it enters the screen about a second before the sled gets there)
    const hopLead = clamp(sled.speed * HOP_HINT_LEAD_S, HOP_HINT_MIN_PX, HOP_HINT_MAX_PX);
    wants.hop = hazardDx < hopLead;
    const danger = !this.tutDone.has('hop') && hazardDx < sled.speed * HOP_DANGER_S + HOP_HINT_MIN_PX;
    // flip: on the approach to a launch lip (learn it before the jump), and in the air until a trick starts
    const lipAhead = !this.tutDone.has('flip') && sled.grounded && this.launchAheadPx(sled.x) < Math.max(FLIP_APPROACH_MIN_PX, sled.speed * FLIP_APPROACH_S);
    wants.flip = lipAhead || (!sled.grounded && sled.airtimeMs > FLIP_AIR_MS && this._airTricks === 0);
    wants.boost = this.lastBoost != null && now - this.lastBoost.t < BOOST_HINT_MS;
    // tuck: a steep grounded descent, only once the first jump and landing are behind the player
    const steep = sled.grounded && !pad.tuck && sled.groundAngleDeg >= TUNING.tuckHintSlopeDeg && sled.speed > 150;
    this._steepMs = steep ? this._steepMs + dt : 0;
    wants.tuck = this._landings > 0 && now > TUCK_HINT_MIN_RUN_MS && this.tuckShows < TUNING.tuckHintMaxShows && (this._steepMs > TUNING.tuckHintMs || this.tutShown.has('tuck') && steep);
    this.applyHintEvents(this.hints.update(now, wants, danger));
  }

  /**
   * Ground-hazard telegraph (systems/HazardTelegraph.js): plan this frame's marks (drawn by entities/GroundTelegraph.js in
   * renderFrame) and play each hazard's warn / hop cue once. The speed-based horizon never reads the camera.
   * @param {number} now run time (ms).
   */
  updateGroundTelegraph(now) {
    const sled = this.sled;
    const live = [];
    for (const list of this.hazards.values()) for (const h of list) live.push(h);
    const landX = !sled.grounded && Number.isFinite(sled.airEtaMs) ? sled.x + sled.vx * sled.airEtaMs / 1000 : null;
    const isMuted = (h) => isWarded(this.wards, { hazardId: h.def.id }) || isWarded(this.wards, { effect: h.def.onHit ? h.def.onHit.effect : 'crash' });
    const marks = planTelegraph(live, { x: sled.x, vx: sled.vx, speed: sled.speed, grounded: sled.grounded, landX }, { isMuted, nowMs: now });
    for (const e of this.teleTracker.update(now, marks)) {
      if (e.type === 'warn') {
        e.ref.teleAtMs = now; // read by the measurement harness and the gate; nothing in the game depends on it
        if (e.sound) this.playSfx('groundWarn', { brace: e.kind === 'brace' });
      } else this.playSfx('hopCue');
    }
    this._teleMarks = marks;
  }

  /** Savestate hook (#119): the telegraph tracker's plain-data state. */
  snapshotTelegraph() { return this.teleTracker.snapshot(); }

  /**
   * Savestate hook (#119): restore the tracker, then re-stamp `teleAtMs` on the (freshly built) live hazards from it, so
   * nothing re-warns and the crash-report/harness timestamp matches the uninterrupted run.
   * @param {ReturnType<TelegraphTracker['snapshot']>} snap
   */
  restoreTelegraph(snap) {
    this.teleTracker.restore(snap);
    for (const list of this.hazards.values()) for (const h of list) {
      const w = this.teleTracker.firstWarnMs(h);
      if (w !== null) h.teleAtMs = w;
    }
  }

  /** Distance (px) from x to the next generated launch lip ahead, or Infinity. */
  launchAheadPx(x) {
    let best = Infinity;
    for (const ch of this.terrain.activeList) {
      if (ch.endX < x) continue;
      for (const l of ch.launches || []) if (l.x > x && l.x - x < best) best = l.x - x;
      if (best < Infinity) break;
    }
    return best;
  }

  // ------------------------------------------------------------------ zones

  getZoneDefs(x) {
    let zones = [];
    try { zones = this.terrain.getZonesAt(x) || []; } catch (e) { zones = []; }
    const out = [];
    for (const z of zones) {
      const def = this.content.terrainMods[z.modId];
      if (def) out.push(def);
    }
    return out;
  }

  /**
   * Product of the scoring multipliers of the mod zones at x (W3). Only mods that define `scoreMul`
   * contribute, so physics-only zones leave scoring untouched. Bounded by the data, and multiplied
   * rather than summed so two overlapping echo zones cannot compound into a runaway payout.
   * @param {number} x world px
   * @returns {number} >= 1
   */
  _zoneScoreMulAt(x) {
    let mul = 1;
    for (const def of this.getZoneDefs(x)) {
      if (def && Number.isFinite(def.scoreMul) && def.scoreMul > 1) mul *= def.scoreMul;
    }
    return mul;
  }

  updateZones(x) {
    let zones = [];
    try { zones = this.terrain.getZonesAt(x) || []; } catch (e) { zones = []; }
    const now = new Map();
    for (const z of zones) now.set(`${z.modId}:${Math.round(z.x0)}`, z);
    for (const [k, z] of now) {
      if (!this.activeZones.has(k)) {
        this.game.events.emit(EVT.ZONE_ENTER, { modId: z.modId, x0: z.x0, x1: z.x1 });
      }
    }
    for (const [k, z] of this.activeZones) {
      if (!now.has(k)) this.game.events.emit(EVT.ZONE_EXIT, { modId: z.modId, x0: z.x0, x1: z.x1 });
    }
    this.activeZones = now;
  }

  // ------------------------------------------------------------------ safe ground / respawn

  sampleSafeGround(dt, fs) {
    this._safeTimer += dt;
    const t = this.runTimeMs;
    while (this.safeSamples.length && t - this.safeSamples[0].t > SAFE_HISTORY_MS) this.safeSamples.shift();
    if (this._safeTimer < SAFE_SAMPLE_EVERY_MS) return;
    this._safeTimer = 0;
    if (!this.sled.grounded || this.pendingCrash) return;
    const rel = Math.abs(((fs.angleDeg - fs.groundAngleDeg + 540) % 360) - 180);
    if (rel > 28) return;
    // origin y of the sled so that the runners sit on the ground at this x
    const gy = this.terrain.heightAt(fs.x);
    if (!Number.isFinite(gy)) return;
    this.safeSamples.push({ t, x: fs.x, y: gy - 14, vx: fs.vx, vy: fs.vy, ang: this.slopeAt(fs.x) });
  }

  pickSafe(minAgeMs) {
    const t = this.runTimeMs;
    for (let i = this.safeSamples.length - 1; i >= 0; i--) {
      if (t - this.safeSamples[i].t >= minAgeMs) return this.safeSamples[i];
    }
    return this.safeSamples[0] || null;
  }

  respawnAt(sample, reason, speedKeep, minAlong = 60) {
    const s = this.sled;
    let x;
    let y;
    let ang;
    let vx;
    let vy;
    if (sample) {
      x = sample.x; y = sample.y; ang = sample.ang; vx = sample.vx; vy = sample.vy;
    } else {
      x = s.x; y = this.terrain.heightAt(s.x) - 16; ang = this.slopeAt(s.x);
      vx = s.vx; vy = 0;
    }
    const sp = pmath.hypot(vx, vy);
    const keep = sp > 1 ? Math.min(1, 380 / sp) * speedKeep : 0;
    const dirx = pmath.cos(ang * DEG);
    const diry = pmath.sin(ang * DEG);
    const along = Math.max(minAlong, sp * keep);
    s.setPose(x, y - 4, ang, dirx * along, diry * along);
    s.invulnerableMs = TUNING.invulnerableMs;
    this._airTricks = 0;
    this.tricks.reset();
    this.trail.reset();
    this.safeSamples.length = 0;
    this.fx.ring(x, y, this.palette.cyan, 40, 400);
    this.snapCamera();
    return { x, y };
  }

  /** End temporary pickups/hazards consistently on manual and Gym recovery.
   * Permanent upgrade/loadout settings are intentionally not modified. */
  clearTemporaryEffects(reason) {
    if (this.boostMs > 0) this.game.events.emit(EVT.POWERUP_EXPIRED,
      { id: this.boostId || 'packetBurst', reason });
    if (this.slowmoMs > 0) this.game.events.emit(EVT.POWERUP_EXPIRED,
      { id: 'clockPulse', reason });
    if (this.slowMs > 0) this.game.events.emit(EVT.EFFECT_END, { effect: 'slow' });
    if (this.scrambleMs > 0) this.game.events.emit(EVT.EFFECT_END, { effect: 'scramble' });
    this.boostMs = 0;
    this.boostFactor = 1;
    this.boostId = null;
    this.slowmoMs = 0;
    this.slowMs = 0;
    this.scrambleMs = 0;
    if (this.sled) this.sled.scrambled = false;
    this._endBiomeEffects(reason);
  }

  manualReset() {
    const sample = this.pickSafe(250);
    const r = this.score.penalizeReset() || { comboPenalty: 0, pointsLost: 0 };
    this.emitFlow(r.flowChange);
    const pos = this.respawnAt(sample, 'manual', 0.6);
    this.resetCooldownMs = 600;
    // Shared cleanup prevents different recovery paths from retaining hazard timers.
    this.clearTemporaryEffects('respawn');
    this.game.events.emit(EVT.RESPAWN, { reason: 'manual', x: pos.x, y: pos.y, comboPenalty: r.comboPenalty || 0 });
    this.emitCombo('reset');
    this.emitScore();
  }

  // ------------------------------------------------------------------ crash

  resolveCrash(fs) {
    const c = this.pendingCrash;
    this.pendingCrash = null;
    const speed = pmath.hypot(fs.vx, fs.vy);
    // The advancing deletion wall overrides even shield, respawn grace and opening grace.
    if (c.cause === 'bsod') { this.doCrash(c, fs, speed); return; }
    if (this.sled.invulnerableMs > 0 && c.cause !== 'chasm') {
      // Grace prevents death, not the failure of a completed bad landing.
      // Its provisional combo belongs to the ended flight, never a later one.
      if (c.cause === 'badLanding') {
        this._airTricks = 0;
        this.tricks.reset();
        this.emitFlow(this.score.onCrash());
        this.emitCombo('crash');
        this.emitScore();
      }
      return;
    }
    const distM = (fs.x - this.startX) / PIXELS_PER_METER;
    if (c.cause !== 'hazard' && c.cause !== 'chasm' && distM < TUNING.openingGraceM && this.openingGraces < TUNING.openingGraceMax) {
      // opening grace: recover instead of ending the run (no Hashed Backup charge used)
      this.openingGraces += 1;
      this.sled.invulnerableMs = Math.max(this.sled.invulnerableMs, 1200);
      this.fx.ring(fs.x, fs.y, this.palette.amber, 46, 450);
      this.fx.sparks(fs.x, fs.y, this.palette.amber, 12, 220);
      this.shake(1.5);
      this.flashRect.setFillStyle(this.palette.amber, 1).setAlpha(0.2);
      const dropped = this.score.getSnapshot().comboTricks.length;
      this.emitFlow(this.score.onCrash());
      const pos = this.respawnAt(this.pickSafe(800), 'backup', 0.9, 250);
      this.game.events.emit(EVT.RESPAWN, { reason: 'backup', x: pos.x, y: pos.y, comboPenalty: dropped });
      this.emitCombo('crash');
      return;
    }
    if (this.shieldCharges > 0) {
      this.shieldCharges -= 1;
      const spent = spendShieldSource(this.shieldSources); // B2: expire the chip of the pickup whose charge this was
      this.shieldSources = spent.sources;
      this.game.events.emit(EVT.CRASH, {
        cause: c.cause, x: fs.x, y: fs.y, speedPxS: speed, hazardId: c.hazardId,
        negated: true, fatal: false, runId: this.runId,
      });
      this.game.events.emit(EVT.POWERUP_EXPIRED, { id: spent.id, reason: 'consumed' });
      this.sled.invulnerableMs = Math.max(this.sled.invulnerableMs, 1200);
      this.fx.ring(fs.x, fs.y, this.palette.amber, 46, 450);
      this.fx.sparks(fs.x, fs.y, this.palette.amber, 20, 260);
      this.shake(2.5);
      this.flashRect.setFillStyle(this.palette.amber, 1).setAlpha(0.25);
      if (c.cause !== 'hazard') {
        // body/landing/void crash: the sled is wrecked, put it back on safe ground (pending combo dropped, tracker reset)
        const dropped = this.score.getSnapshot().comboTricks.length;
        this.emitFlow(this.score.onShieldHit(true));
        const pos = this.respawnAt(this.pickSafe(800), 'backup', 0.8);
        this.game.events.emit(EVT.RESPAWN, { reason: 'backup', x: pos.x, y: pos.y, comboPenalty: dropped });
        this.emitCombo('crash');
      } else {
        // a hazard hit absorbed by the shield (e.g. mid-air): the jump goes on, so the pending combo stays untouched and
        // only the flow bonus is halved (dropping it would re-pay later flips at their full cumulative value)
        this.emitFlow(this.score.onShieldHit(false));
      }
      return;
    }
    this.doCrash(c, fs, speed);
  }

  /** Non-ranked practice retry: never advance a normal life/ledger.
   * Rebuild the same course, repeat the player-selected initial conditions,
   * then hold physics for one second. Once released the normal live-world
   * wall and canopy rules resume unchanged. */
  resetBsodGym() {
    if (!this.bsodGym || !this.sled || !this.bsod) return;
    const sled = this.sled;
    // Rebuild fixed-seed terrain, hazards, pickups and shards as well as the
    // player so repeated attempts truly rehearse the same initial situation.
    this.resetGymWorld();
    // Reset to a repeatable practice launch, not farther along a random
    // course. These are allowed initial conditions, never special movement.
    const setup = this.gymSetup || gymSetupForProfile(this.registry?.get?.(REG.PROFILE));
    const x = this.gymStartX ?? this.startX;
    const y = this.terrain.heightAt(x) - setup.launchHeightPx;
    sled.setPose(x, y, 0, setup.launchSpeedPxS, setup.launchRisePxS);
    sled.parachuteFuelMs = sled.canopyFuelFullMs;
    sled.invulnerableMs = 0;
    // Each attempt starts with the same actually-enabled bonus loadout, with
    // normal timed boosts and their duration restarting for the new attempt.
    this.shieldCharges = this.boostFx?.shieldCharges || 0;
    this.shieldSources = [];
    sled.shield = this.shieldCharges > 0;
    this.openingGraces = 0;
    this.gymAttemptStartTimeMs = this.runTimeMs;
    this.gymAttemptStartX = x;
    this.pendingCrash = null;
    this.bsodCaught = false;
    this.crashed = false;
    this.hitStopMs = 0;
    this.blinkMs = 0;
    this.clearTemporaryEffects('gym-retry');
    // Starting the NEXT attempt may reposition the wall. Once released,
    // the existing BsodPursuit.advance() strictly moves it forward; we
    // NEVER reverse the wall or change its live-run acceleration.
    placeGymWall(this.bsod, sledLeftCollisionEdge(sled), setup);
    this.bsodBluffs?.reset?.();
    this._airTricks = 0;
    this._landings = 0;
    this._steepMs = 0;
    this._lastHopMs = null;
    this._hopped = false;
    this._pushed = false;
    this.shardChainAt = -1e9;
    this.safeSamples?.splice?.(0);
    this._safeTimer = 0;
    this._contactQueue?.splice?.(0);
    this.trail?.reset?.();
    this.resetCooldownMs = 0;
    // Each retry is a NEW training attempt. Do not retain the previous
    // attempt's score/combos/shard tally in the HUD or its internal trackers.
    this.score?.reset?.();
    this.tricks?.reset?.();
    this.nearMissCount = 0;
    this.shardCount = 0;
    this.shardTotal = 0;
    this.shardChain = 0;
    this.trickCounts = {};
    this.bestCombo = 1;
    this.maxAirtimeMs = 0;
    this.lastTotal = 0;
    this.gymRetries = (this.gymRetries || 0) + 1;
    this.gymReadyMs = GYM_READY_MS;
    this.gymBeatWaitMs = 0;
    this.gymBeatSnapshot = null;
    // Reset HUD and show the beat; no frame may advance the wall until it ends.
    this.game?.events?.emit?.(EVT.GYM_ATTEMPT_RESET,
      { attempt: this.gymRetries, readyMs: GYM_READY_MS });
    if (this.score) this.emitScore();
    this.bsodState = this.bsod.state(sledLeftCollisionEdge(sled), sled.vx, this.bsodAtmosphere());
    this.publishBsodState(this.bsodState);
  }

  doCrash(c, fs, speed) {
    if (this.bsodGym) {
      // Gym is a sandbox. Every impact restores a playable attempt in-place:
      // no run record, progression, leaderboard, shards or earned achievements.
      this.resetBsodGym();
      return;
    }
    this.crashed = true;
    this.deactivateBsod();
    this.crashTimerMs = 0;
    this.emitFlow(this.score.onCrash());
    this.emitCombo('crash');
    // A third-party/music observer may fail while constructing optional
    // scratch/count-in audio. Fatal score, record, and GameOver must still
    // finish; audio is never authoritative over a life ending.
    try {
      this.game.events.emit(EVT.CRASH, {
        cause: c.cause, x: fs.x, y: fs.y, speedPxS: speed, hazardId: c.hazardId,
        negated: false, fatal: true, runId: this.runId,
      });
    } catch (e) { console.warn('Fatal crash observer failed; finalizing run anyway',e); }
    const p = this.palette;
    this.fx.shards(fs.x, fs.y, fs.vx, fs.vy, [p.cyan, p.magenta, p.lime, p.amber, p.text], 46);
    this.fx.ring(fs.x, fs.y, p.danger, 64, 500);
    this.fx.sparks(fs.x, fs.y, p.text, 24, 320);
    this.sled.vanish();
    this.shake(TUNING.shakeCrash);
    this.flashRect.setFillStyle(0xffffff, 1).setAlpha(0.55);
    this.reportCrash(c, fs);

    // A replay is a re-simulation of an existing run: it never saves a record, awards progress or records a tape.
    if (this.tapePlayer) return;
    // persist + hand off
    const snap = this.score.getSnapshot();
    const record = {
      version: STORAGE.saveVersion,
      id: this.runId,
      seed: this.seed,
      dailyRuleId: this.dailyRuleId,
      // W3: only recorded when non-zero; absent reads as mask 0 everywhere (the v2 hash canonicalises it
      // to 0), so old and new mask-0 runs stay comparable.
      ...(this.biomeMask ? { biomeMask: this.biomeMask } : {}),
      startedAt: this.startedAt,
      endedAt: Date.now(),
      durationMs: Math.round(this.runTimeMs),
      score: Math.max(0, Math.round(snap.total)),
      distanceM: Math.floor(snap.distanceM),
      trickPoints: Math.round(snap.trickPoints),
      tricks: { ...this.trickCounts },
      bestCombo: Math.max(this.bestCombo, snap.bestCombo || 1),
      bestFlow: Math.max(1, snap.bestFlow || 1), // stored and v2-hashed since decision 6
      maxAirtimeMs: Math.round(this.maxAirtimeMs),
      cause: 'crash',
      // W4: set only when a boost was actually active. Ranking keeps it off clean boards; since decision 6
      // the v2 ledger hash covers it, with the ids of the boosts that applied.
      ...(this.modded ? { modded: true, boosts: [...(this.appliedBoosts || [])] } : {}),
      ...(this.upgradeRun?.enabled || this.dailyMode==='draft'
        ? { upgradeRanks: { ...this.upgradeRun.ranks } } : {}),
      ...(this.dailyMode==='draft'?{
        dailyMode:'draft',draftRulesVersion:DRAFT_RULES_VERSION,draftBudget:DRAFT_BUDGET,
      }:{}),
      // Decision 2: true only for the official Daily (DAILY RUN item, today's seed). Written on every
      // record so a v2 record is never mistaken for a legacy one (Ranking.isOfficialDaily).
      dailyOfficial: this.dailyOfficial === true,
      shards: this.shardCount || 0,
      nearMisses: this.nearMissCount || 0,
      bonusPoints: Math.round(snap.bonusPoints || 0),
      // Decision 6: new records are ledger-hash v2 (every gameplay and result field).
      hashV: this.dailyMode==='draft'?DRAFT_LEDGER_HASH_V:
        this.upgradeRun?.enabled ? UPGRADE_LEDGER_HASH_V : LEDGER_HASH_V,
      ledgerHash: '',
    };
    record.ledgerHash = SaveStore.computeLedgerHash(record);
    this.registry.set(REG.LAST_RECORD, record);
    this._saveGhostTape(record);
    try {
      if (this.saveStore) {
        const pr = this.saveStore.saveRun(record);
        if (pr && pr.catch) pr.catch(() => {});
      }
    } catch (e) { /* saving must never break the loop */ }
    // Decision 3: which biomes this run entered / rode through (pure, BiomeDiscovery). Beside the record, never
    // in it, so the RunRecord and its ledger hash are unchanged. Furthest x = the ScoreManager's furthest metres.
    const biomeVisits = detectBiomeVisits({
      biomeAt: (x) => this.terrain.biomeAtX(x),
      furthestX: Math.max(fs.x, this.startX + (snap.distanceM || 0) * PIXELS_PER_METER), crashX: fs.x, pxPerMeter: PIXELS_PER_METER,
    });
    this.game.events.emit(EVT.RUN_END, { record, biomeVisits });
  }

  /**
   * Readable Chaos phase 3: name the killer and time the hop (systems/CrashReport.js) into REG.LAST_CRASH. Only a crash
   * that ends the run gets here (an absorbed one returns in resolveCrash). Registry only; reads state, changes none.
   * @param {{cause:string, hazardId?:string}} c @param {{x:number}} fs
   */
  reportCrash(c, fs) {
    const hz = this.content && this.content.hazards;
    const h = this._crashHazard;
    const ent = c.cause === 'hazard' && h && h.def && h.def.id === c.hazardId ? h : null;
    const def = ent ? ent.def : c.hazardId ? (hz && hz[c.hazardId]) || null : null;
    const arrivalMs = ent && this.teleTracker ? this.teleTracker.lastArrivalMs(ent) : null;
    this.registry.set(REG.LAST_CRASH, crashReport({
      runId: this.runId, seed: this.seed, biomeMask: this.biomeMask, cause: c.cause, def, x: fs.x, startX: this.startX,
      pxPerMeter: PIXELS_PER_METER, lastHopMs: this._lastHopMs, arrivalMs, crashMs: this.runTimeMs,
    }));
  }

  updateCrashed(dt) {
    this.crashTimerMs += dt;
    this.renderFrame(dt);
    if (this.crashTimerMs >= CRASH_TO_GAMEOVER_MS && !this._leaving) {
      this._leaving = true;
      this.scene.stop(SCENES.UI);
      this.scene.start(SCENES.GAME_OVER);
    }
  }

  // ------------------------------------------------------------------ pause

  pauseRun() {
    // A held Escape/input edge must not dispatch two scratch starts or launch
    // two PauseScenes. This is only the intentional player pause path; death
    // and automatic scene transitions never route through this method.
    if (this._manualPausePending || this.scene?.isPaused?.(SCENES.RUN)) return;
    this._manualPausePending = true;
    const pauseToken = `${this.runId}:${++this._manualPauseSeq}`;
    const manual = { runTimeMs: this.runTimeMs, runId: this.runId,
      reason: 'manual', pauseToken, gym: this.bsodGym === true };
    // The transition must complete even if an audio/third-party observer
    // throws while constructing its scratch. Nothing may hold gameplay hostage.
    try { this.game.events.emit(EVT.GAME_PAUSE, manual); }
    catch (e) { console.warn('Manual pause observer failed; pausing anyway', e); }
    this.scene.pause();
    this.scene.launch(SCENES.PAUSE, manual);
  }

  // ------------------------------------------------------------------ settings

  onSettingsChanged(payload) {
    if (payload && payload.settings) this.settings = payload.settings;
    // A palette toggle (Pause > Settings) is presentation: repaint only, never rebuild colliders (issue #140).
    if (payload && payload.key === 'palette' && this.sled) this.refreshPalette();
  }

  /**
   * Resolve the equipped cosmetics into colours. Reads the profile, then hands off to the pure resolver so
   * the colourblind safety rule lives in one tested place rather than in the draw loop.
   * @returns {{rider:string, glow:string, trail:string[], theme:string}|null}
   */
  _resolveLook() {
    const reg = this.registry;
    const profile = reg.get(REG.PROFILE) || null;
    const settings = reg.get(REG.SETTINGS) || {};
    const hex = getPaletteCss(this.game, this._biomeDefById(this._lookBiomeId()));
    return resolveCosmetics(profile, this.palette, hex, {
      colorblind: settings.palette === 'colorblind',
    });
  }

  /**
   * Repaint the world in the current palette (+ the active sector's biome tint). Graphics only: terrain chunks are
   * repainted with TerrainMesh.redrawChunk and their colliders are never touched (issue #140). Used by the palette
   * setting AND on entering / leaving a biome sector. A biome's gameplay (zone mods, hazards, pickups) is chunk data
   * read by the sim (getZoneDefs, takeChunk); collider material is fixed (TerrainMesh._takeBody), so rebuilding the
   * colliders here only reshuffled body ids/order and dropped contact warm-start state. Owner-approved physics change
   * (SIM_REVISION 2).
   */
  refreshPalette() {
    // W3: the active sector's biome tints the world. Passing the def (not just an id) keeps this a
    // pure function of current state, so a palette toggle mid-biome repaints to the right place.
    const biomeDef = this._biomeDefById(this._lookBiomeId());
    this.palette = getPalette(this.game, biomeDef);
    // W3: the biome's `background` motif, and back to the base backdrop when the sector has no biome.
    // setMotif(null) is the exit case: a motif must not outlive the sector that owns it.
    if (this.bg) this.bg.setMotif(biomeDef && biomeDef.background ? biomeDef.background : null);
    this.cameras.main.setBackgroundColor(this.palette.bg);
    if (this.blindRect) this.blindRect.setFillStyle(this.palette.bg, 1); // B0 blind overlay follows the palette
    this.sled.palette = this.palette;
    // A palette toggle can turn colourblind ON, which refuses every cosmetic: the sled and trail have to
    // be re-resolved, not just repainted, or a paid hue would survive the accessibility switch.
    this.look = this._resolveLook();
    if (this.sled) this.sled.look = this.look;
    if (this.trail) { this.trail.setPalette(this.palette); this.trail.setStops(this.look && this.look.trail); }
    this.bg.setPalette(this.palette);
    if (this.biomeFx) {
      this.biomeFx.setPalettes(this.palette, getPalette(this.game, null));
      this.biomeFx.setLook(biomeDef ? biomeDef.id : null);
    }
    this.fx.palette = this.palette;
    if (this.airTelegraph) this.airTelegraph.setPalette(this.palette);
    if (this.groundTelegraph) this.groundTelegraph.setPalette(this.palette);
    this.mesh.setPalette(this.palette);
    for (const chunk of this.terrain.getActiveChunks()) {
      if (!this.mesh.chunks.has(chunk.index)) continue;
      this.mesh.redrawChunk(chunk); // graphics only; colliders stay
      const hz = this.hazards.get(chunk.index);
      if (hz) hz.forEach((h) => { h.palette = this.palette; h.color = hazardColor(h.def, this.palette); });
      const pu = this.powerups.get(chunk.index);
      if (pu) pu.forEach((p) => { p.palette = this.palette; p.color = this.palette[p.def.colorKey] != null ? this.palette[p.def.colorKey] : this.palette.cyan; });
    }
  }

  // ------------------------------------------------------------------ camera

  shake(amp) {
    if (this.settings && this.settings.screenShake === false) return;
    this.shakeAmp = Math.max(this.shakeAmp, amp);
  }

  snapCamera() {
    const cam = this.cameras.main;
    const s = this.sled;
    this._camX = s.x - GAME_WIDTH * 0.38;
    this._camY = s.y - GAME_HEIGHT / 3;
    this._zoom = 1;
    cam.setZoom(1);
    this.applyZoomCompensation(1);
    cam.scrollX = Math.round(this._camX);
    cam.scrollY = Math.round(this._camY);
  }

  /** Screen-space layers (background, flash) live at scroll factor 0; counter-scale them so camera zoom does not shrink them. */
  applyZoomCompensation(z) {
    const k = 1 / z;
    const px = (GAME_WIDTH * (z - 1)) / (2 * z);
    const py = (GAME_HEIGHT * (z - 1)) / (2 * z);
    if (this.bg && this.bg.gfx) this.bg.gfx.setScale(k).setPosition(px, py);
    if (this.biomeFx) this.biomeFx.applyZoomCompensation(k, px, py);
    if (this.flashRect) this.flashRect.setScale(k).setPosition(px, py);
    if (this.blindRect) this.blindRect.setScale(k).setPosition(px, py);
  }

  updateCamera(dt) {
    const cam = this.cameras.main;
    const s = this.sled;
    // Look ahead in the direction of travel; Y keeps ~1/3 of the screen above the rider and peeks lower when falling.
    const look = clamp(s.vx * TUNING.lookAheadSec, -TUNING.lookAheadMaxPx * 0.5, TUNING.lookAheadMaxPx)
      + LOOK_FAR_EXTRA_PX * smooth01((s.vx - 600) / 400) + LOOK_ULTRA_EXTRA_PX * smooth01((s.vx - 850) / 450)
      - 225 * smooth01((this.bsodState && this.bsodState.proximity01) || 0);
    const tx = s.x + look - GAME_WIDTH * 0.38;
    const ty = s.y - GAME_HEIGHT / 3 - clamp(s.vy * 0.05, -26, 34);
    const kx = 1 - pmath.exp((-TUNING.cameraLerpX * dt) / 1000);
    // follow faster the quicker the sled moves vertically (bounce pads / big drops must never push it off screen)
    const ky = 1 - pmath.exp((-(TUNING.cameraLerpY + clamp(Math.abs(s.vy) / 90, 0, 7)) * dt) / 1000);
    this._camX += (tx - this._camX) * kx;
    this._camY += (ty - this._camY) * ky;
    // hard guarantee: keep the rider inside the visible band
    const margin = 34;
    if (s.y - this._camY < margin) this._camY = s.y - margin;
    else if (s.y - this._camY > GAME_HEIGHT - margin) this._camY = s.y - (GAME_HEIGHT - margin);
    let ox = 0;
    let oy = 0;
    if (this.shakeAmp > 0.15) {
      // per-pixel RNG jitter, decaying
      ox = Math.round(((this.runRandom?.visualCamera || cosmeticRandom('visual/camera')).next() * 2 - 1) * this.shakeAmp);
      oy = Math.round(((this.runRandom?.visualCamera || cosmeticRandom('visual/camera')).next() * 2 - 1) * this.shakeAmp);
      this.shakeAmp *= pmath.exp(-dt / 140);
    } else {
      this.shakeAmp = 0;
    }
    // ... and horizontally: the extra look-ahead must not push the rider off the left edge (the zoom below keeps the rider at
    // screen x = s.x - _camX whatever the zoom, so this is a plain screen-px bound)
    if (s.x - this._camX < RIDER_MIN_SCREEN_X) this._camX = s.x - RIDER_MIN_SCREEN_X;
    // The BSOD camera pullback must NEVER drive the rider off the right edge or hide all terrain ahead.
    const riderMaxScreenX = GAME_WIDTH - 72;
    if (s.x - this._camX > riderMaxScreenX) this._camX = s.x - riderMaxScreenX;
    // never show far past the start edge of the world
    if (this._camX < -30) this._camX = -30;

    // speed zoom: 1.0 at rest -> zoomMin at zoomSpeedHi, smoothed, with a brief extra pull-out on boosts. Stepped to 0.005
    // so the vector terrain does not shimmer from continuous sub-pixel scale changes.
    const zt = speedZoom(s.speed);
    this._zoom += (zt - this._zoom) * (1 - pmath.exp((-TUNING.zoomLerp * dt) / 1000));
    this._zoomKick = Math.max(0, this._zoomKick - dt / 260 * 0.05);
    const crashZoom = this.crashed ? crashBeat(this.crashTimerMs, TUNING.hitStopCrashMs).zoomMul : 1; // crash beat zoom-in
    const z = Math.round(clamp((this._zoom - this._zoomKick) * crashZoom, ZOOM_FLOOR, 1.2) * 200) / 200;
    if (z !== cam.zoom) {
      cam.setZoom(z);
      this.applyZoomCompensation(z);
    }
    // keep the rider at the same screen position whatever the zoom (zoom pivots on the screen centre)
    const px0 = s.x - this._camX;
    const py0 = s.y - this._camY;
    let sx = s.x - GAME_WIDTH / 2 - (px0 - GAME_WIDTH / 2) / z;
    const sy = s.y - GAME_HEIGHT / 2 - (py0 - GAME_HEIGHT / 2) / z;
    const visLeft = sx + GAME_WIDTH / 2 - GAME_WIDTH / (2 * z);
    if (visLeft < -30) sx += -30 - visLeft;
    cam.scrollX = Math.round(sx) + ox;
    cam.scrollY = Math.round(sy) + oy;
  }
}/**
 * OWNER: UI engineer.
 * Title / main menu, laid out as a synthwave arcade cabinet:
 *
 *   - the chrome SVG wordmark top-centre, over the retro sun (chromatic-split outline layers, a gentle wave,
 *     a passing glint and periodic glitch slices; all motion off under reduce motion);
 *   - the six-item menu on a glass panel on the grid floor, left (START RUN, DAILY RUN with today's rule as
 *     its sub label, ENTER SEED, PROFILE, LEADERBOARD, SETTINGS);
 *   - a "cabinet card" on the right: level badge and title, BEST, the Daily Patch (rule, countdown, streak /
 *     today's best) and the three active missions;
 *   - the compact jukebox top-right, the HOW TO PLAY chip and the control hint at the foot;
 *   - the sun, ranges, rider and grid left open in the centre column.
 *
 * Every rectangle comes from MissionsLayout (TITLE_BANDS, TITLE_CARD, titleMenuLayout) and ProfileLayout
 * (titleBadgeLayout), which are overlap-tested in Jest.
 *
 * Operable by keyboard, gamepad and touch/mouse. HOW TO PLAY: H, pad X/Y or SELECT, or the chip. After
 * ATTRACT_MS without input the cabinet goes into attract mode (panels dim, PRESS START blinks, the rider
 * throws tricks); any input restores it and is swallowed, so waking the cabinet never also fires a menu item.
 *
 * A start (START RUN, DAILY, seed) writes the seed and mask to the registry exactly as before, then warps the
 * backdrop and leaves through Motion.sceneTransition (a quick fade under reduce motion) into SCENES.RUN.
 */
import Phaser from 'phaser';
import packageInfo from '../../package.json';
import { SCENES, REG, GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
import { EVT } from '../events.js';
import { DailyPatch } from '../systems/DailyPatch.js';
import { parseSeedMask } from '../systems/SaveStore.js';
import { rankableOnly } from '../systems/Ranking.js';
import { enabledBiomeMask } from '../systems/ProfileStore.js';
import { Theme } from '../ui/Theme.js';
import { NeonText } from '../ui/Neon.js';
import { measureText, ellipsize, wrapText } from '../ui/PixelFont.js';
import { Panel } from '../ui/Panel.js';
import { Button } from '../ui/Button.js';
import { MenuList } from '../ui/MenuList.js';
import { MenuInput } from '../ui/MenuInput.js';
import { Backdrop } from '../ui/Backdrop.js';
import { buildTitleMissionList } from '../ui/MissionsUi.js';
import { TITLE_BEST_X, TITLE_BEST_Y, TITLE_BANDS, TITLE_CARD, TITLE_CARD_INNER_W, TITLE_HORIZON, titleMenuLayout, titleBestText, titleChaseText } from '../ui/MissionsLayout.js';
import { addScanlines, playCrtPowerOn } from '../ui/Scanlines.js';
import { openDim, closeDim, sceneTransition, isReducedMotion, tweenProgress, Ease } from '../ui/Motion.js';
import { artImage, hasArt, mixColor } from '../ui/MenuArt.js';
// HowToPlayView before Views: it extends Views' View lazily, so either order works, but keep the natural one.
import { HowToPlayView } from '../ui/HowToPlayView.js';
import { LeaderboardView, SettingsView, SeedView, ProfileView, ShopView, DailyModesView, DailyDraftEditorView, DailyDraftLeaderboardView } from '../ui/Views.js';
import { titleBadgeLayout } from '../ui/ProfileLayout.js';
import { randomSeed, idToLabel, fmtInt } from '../ui/Format.js';
import { uiSfx } from '../ui/Sound.js';
import { JukeboxHUD } from '../ui/JukeboxHUD.js';
import { cosmeticRandom } from '../systems/CosmeticRandom.js';

/** Idle time before attract mode. */
export const ATTRACT_MS = 20000;
/** Input arriving this soon after attract mode ends is the same press that woke it: swallowed. */
const WAKE_SWALLOW_MS = 220;
/** Phaser.BlendModes.ADD. */
const BLEND_ADD = 1;
/** Logo depth: above the backdrop and the panels' glow, below views and the dim. */
const LOGO_DEPTH = 5;

// The startup version belongs to the game instance, not every return to Title.
const versionShown = new WeakSet();
const VERSION_LABEL_ALPHA = 0.65;

const HINT_TEXT = '↑↓ SELECT   ENTER / A CONFIRM   H / X HOW TO PLAY';

export class TitleScene extends Phaser.Scene {
  constructor() {
    super(SCENES.TITLE);
  }

  create() {
    this.starting = false;
    this.view = null;
    this.dim = null;
    this.attract = false;
    this.attractExitAt = -Infinity;
    this.lastInputAt = this.time.now;
    this.glitchUntil = 0;
    this.nextGlitch = 2600;
    this.nextGlint = 1800;
    this.padSelectPrev = false;
    const theme = (this.theme = new Theme(this));
    theme.bind((pal) => this.cameras.main.setBackgroundColor(pal.bg));
    // Horizon at 150: the sun sits behind the logo and the ranges fill the band between the logo and the
    // menu. The rider carves through the open centre column, between the menu and the card.
    this.backdrop = new Backdrop(this, theme, { horizon: TITLE_HORIZON, alpha: 1, riderX: 266, riderRange: 30 });
    this.daily = DailyPatch.getDailyInfo();

    this._buildLogo();
    this._buildMenu();
    this._buildCard();
    this._buildFooter();
    // the rolling band is a menu-only flourish; the power-on plays once per page load (Scanlines.js)
    addScanlines(this, 1, { roll: true });
    playCrtPowerOn(this);

    this.input_ = new MenuInput(this, (a) => this._onAction(a));
    this._bindIdleInputs();
    // Compact song/transport keys top-right, beside the logo; the queue opens under it, over the card.
    const jb = TITLE_BANDS.jukebox;
    this.jukebox = new JukeboxHUD(this, theme, { x: jb.x, y: jb.y, variant: 'compact', queueAt: { x: GAME_WIDTH - 236, y: jb.y + jb.h + 4 } });
    // One soundtrack across Title, Run and Game Over. Browser policy may
    // defer sound until the first gesture, but it is requested immediately.
    this.game.registry.get(REG.AUDIO)?.startMenuMusic?.();
    this.events.once('shutdown', () => {
      this.jukebox?.destroy();
      this.jukebox = null;
      this._unbindIdleInputs();
      this._closeView();
    });
    this.cameras.main.fadeIn(180, 5, 6, 15);
  }

  // ------------------------------------------------------------------ logo

  _buildLogo() {
    const theme = this.theme;
    const words = [
      { fill: 'logoBitstreamFill', line: 'logoBitstreamLine', y: TITLE_BANDS.logo.y + 2, w: 249, h: 42, phase: 0 },
      { fill: 'logoBluffsFill', line: 'logoBluffsLine', y: TITLE_BANDS.logo.y + 39, w: 205, h: 51, phase: 1.4 },
    ];
    this.logoWords = null;
    this.logo = null;
    if (words.every((w) => hasArt(this, w.fill) && hasArt(this, w.line))) {
      this.logoWords = words.map((w) => this._buildLogoWord(w));
    } else {
      this._buildLogoFallback();
    }
    this.sub = new NeonText(this, theme, GAME_WIDTH / 2, TITLE_BANDS.tagline.y, 'A DOWNHILL NEON TRICK RACE', {
      color: 'cyan', anchor: 'center', outline: 'dark',
    }).setDepth(LOGO_DEPTH);
  }

  /**
   * One chrome word: a deep extrusion shadow, magenta and cyan outline copies offset either side (the
   * chromatic split), the greyscale chrome fill tinted cool-top / warm-bottom, an additive glint that sweeps
   * across now and then, and three hidden slices the glitch borrows.
   */
  _buildLogoWord(w) {
    const x = GAME_WIDTH / 2;
    const o = { theme: this.theme, originX: 0.5, originY: 0, depth: LOGO_DEPTH };
    const shadow = artImage(this, w.line, x, w.y + 3, { ...o, tint: (pal) => mixColor(pal.bg, pal.magenta, 0.45) });
    const lineM = artImage(this, w.line, x - 1, w.y, { ...o, tint: 'magenta', alpha: 0.95 });
    const lineC = artImage(this, w.line, x + 1, w.y, { ...o, tint: 'cyan', alpha: 0.95 });
    const fill = artImage(this, w.fill, x, w.y, {
      ...o,
      tint: (pal) => {
        const top = mixColor(pal.text, pal.cyan, 0.42);
        const bottom = mixColor(pal.text, pal.magenta, 0.62);
        return [top, top, bottom, bottom];
      },
    });
    const glint = artImage(this, w.fill, x, w.y, { ...o, tint: 0xffffff, alpha: 0.7, blend: BLEND_ADD });
    glint.setVisible(false);
    const slices = [0, 1, 2].map((i) => {
      const s = artImage(this, w.fill, x, w.y, { ...o, depth: LOGO_DEPTH + 0.1, tint: i % 2 ? 'magenta' : 'cyan', alpha: 0.95 });
      s.setVisible(false);
      return s;
    });
    return { ...w, x, shadow, lineM, lineC, fill, glint, slices, layers: [shadow, lineM, lineC, fill, glint] };
  }

  /** No SVGs (a failed load): the v1 per-letter neon wordmark, so the Title is never blank. */
  _buildLogoFallback() {
    const theme = this.theme;
    this.logo = [];
    const lines = [
      { text: 'BITSTREAM', y: 10, scale: 4, color: 'cyan' },
      { text: 'BLUFFS', y: 46, scale: 4, color: 'magenta' },
    ];
    for (const ln of lines) {
      const total = measureText(ln.text) * ln.scale;
      let x = Math.round(GAME_WIDTH / 2 - total / 2);
      [...ln.text].forEach((ch, i) => {
        const t = new NeonText(this, theme, x, ln.y, ch, { color: ln.color, scale: ln.scale, outline: 'dark' }).setDepth(LOGO_DEPTH);
        this.logo.push({ t, baseY: ln.y, baseX: x, i, base: ln.color, line: ln.text });
        x += (measureText(ch) + 1) * ln.scale;
      });
    }
  }

  _updateLogo(t, reduced) {
    if (this.logo) {
      // fallback: the v1 per-letter wave and colour sweep
      for (const L of this.logo) {
        const wave = reduced ? 0 : Math.round(Math.sin(t * 0.004 + L.i * 0.55 + (L.line === 'BLUFFS' ? 1.5 : 0)) * 2);
        L.t.setPosition(L.baseX, L.baseY + wave);
      }
      return;
    }
    if (!this.logoWords) return;
    // glitch: every 2.6-6 s a 140 ms burst of displaced, tinted slices and a wider RGB split
    let glitching = false;
    if (!reduced) {
      if (t >= this.nextGlitch && t >= this.glitchUntil) {
        this.glitchUntil = t + 140;
        this.nextGlitch = t + 2600 + cosmeticRandom('title/fx').next() * 3400;
        for (const w of this.logoWords) {
          for (const s of w.slices) {
            const sy = Math.floor(cosmeticRandom('title/fx').next() * (w.h - 6));
            s.glitch = { y: sy, h: 2 + Math.floor(cosmeticRandom('title/fx').next() * 5), dx: (cosmeticRandom('title/fx').next() < 0.5 ? -1 : 1) * (3 + Math.floor(cosmeticRandom('title/fx').next() * 5)) };
          }
        }
      }
      glitching = t < this.glitchUntil;
      if (t >= this.nextGlint) this.nextGlint = t + 4200 + cosmeticRandom('title/fx').next() * 2000;
    }
    // the glint sweeps for 700 ms after each schedule point (nextGlint - its period)
    for (const w of this.logoWords) {
      const dy = reduced ? 0 : Math.round(Math.sin(t * 0.0022 + w.phase) * 1.5);
      const split = glitching ? 3 : 1;
      const jit = glitching ? (cosmeticRandom('title/fx').next() < 0.5 ? -1 : 1) : 0;
      w.shadow.setPosition(w.x, w.y + 3 + dy);
      w.lineM.setPosition(w.x - split, w.y + dy + (glitching ? jit : 0));
      w.lineC.setPosition(w.x + split, w.y + dy - (glitching ? jit : 0));
      w.fill.setPosition(w.x, w.y + dy);
      for (const s of w.slices) {
        if (!glitching || !s.glitch) { s.setVisible(false); continue; }
        s.setVisible(true);
        s.setCrop(0, s.glitch.y, w.w, s.glitch.h);
        s.setPosition(w.x + s.glitch.dx, w.y + dy);
      }
      // glint: a 10 px vertical band crossing the word, a little later on the second word
      const since = reduced ? -1 : t - (this.nextGlint - 4200) - w.phase * 90;
      if (since >= 0 && since < 700) {
        const gx = Math.round(-14 + (since / 700) * (w.w + 28));
        w.glint.setVisible(true);
        w.glint.setCrop(Math.max(0, gx), 0, 10, w.h);
        w.glint.setPosition(w.x, w.y + dy);
      } else w.glint.setVisible(false);
    }
  }

  // ------------------------------------------------------------------ menu

  _buildMenu() {
    const theme = this.theme;
    // Panel height is DERIVED from the row count (MissionsLayout.titleMenuLayout), not hard-coded, so a future
    // row cannot be silently clipped. Six rows fill the band on the grid floor exactly; a seventh would run
    // through the control hint. ACHIEVEMENTS and the SHARD SHOP therefore live in PROFILE, and the controls
    // reference is HOW TO PLAY (hotkey / chip / Settings), not a row.
    const items = [
      { kind: 'action', label: 'START RUN', color: 'lime', onSelect: () => this.startRun(randomSeed()) },
      { kind: 'action', label: 'DAILY RUN', color: 'magenta', sub: ellipsize(this.daily.rule ? this.daily.rule.name.toUpperCase() : '', 76), onSelect: () => this._openDailyModes() },
      { kind: 'action', label: 'ENTER SEED', color: 'cyan', onSelect: () => this._openSeed() },
      {
        kind: 'action',
        label: 'PROFILE',
        color: 'lime',
        onSelect: () => {
          // The shop is opened FROM the profile and returns TO it. Closing the shop straight to Title
          // would make Escape a two-screen jump — the player pressed back once and lost their place,
          // and a keys-only player had no way to tell what had happened.
          const openProfile = () => this._openView(new ProfileView(this, theme, {
            // SHOP-2: a title equipped inside Profile -> TITLES changes the badge, so redraw it on the way out.
            onClose: () => { this._closeView(); this._refreshLevelBadge(); },
            onShop: () => this._openView(new ShopView(this, theme, { onClose: () => { openProfile(); } })),
          }));
          openProfile();
        },
      },
      { kind: 'action', label: 'LEADERBOARD', color: 'amber', onSelect: () => this._openView(new LeaderboardView(this, theme, { onClose: () => this._closeView() })) },
      { kind: 'action', label: 'SETTINGS', color: 'cyan', onSelect: () => this._openView(new SettingsView(this, theme, { onClose: () => this._closeView() })) },
    ];
    // Declared AFTER `items`: reading it first was a temporal-dead-zone ReferenceError that blanked the
    // whole Title screen at boot.
    const geo = titleMenuLayout(items.length);
    if (!geo.fits) {
      // Fail visibly in development rather than shipping a row under the hint: the menu is full.
      console.warn(`Title menu does not fit: ${items.length} rows reach y${geo.lastRowBottom}, band ends at ${TITLE_BANDS.menu.y + TITLE_BANDS.menu.h}`);
    }
    // Translucent glass: the grid floor shows through, so the panel reads as a cabinet bezel, not a wall.
    this.menuPanel = new Panel(this, theme, {
      x: geo.x, y: geo.y, w: geo.w, h: geo.h, color: 'cyan', fillAlpha: 0.62,
    });
    this.menu = new MenuList(this, theme, { x: 4, y: geo.inset, w: geo.w - 8, rowH: geo.rowH, items, scale: geo.scale, parent: this.menuPanel });
  }

  // ------------------------------------------------------------------ cabinet card

  /** The right-hand card: player section, Daily Patch, missions. */
  _buildCard() {
    const theme = this.theme;
    const C = TITLE_CARD;
    const S = C.sections;
    this.cardPanel = new Panel(this, theme, { x: C.x, y: C.y, w: C.w, h: C.h, color: 'magenta', fillAlpha: 0.66 });
    const card = this.cardPanel;
    // decoration under the text: player-section wash, section rules, the MISSIONS rule
    this.cardG = new Phaser.GameObjects.Graphics(this);
    card.add(this.cardG);
    this.cardDecoUnbind = theme.bind((pal) => this._paintCard(pal));
    card.once('destroy', () => this.cardDecoUnbind && this.cardDecoUnbind());
    const txt = (x, y, text, opts) => {
      const t = new NeonText(this, theme, x, y, text, { outline: 'none', ...opts });
      card.add(t);
      return t;
    };
    // the cabinet label: "1UP", right of the badge
    txt(C.w - C.pad, S.level, '1UP', { color: 'amber', anchor: 'right', outline: 'glow' });
    this._buildLevelBadge();
    this.bestText = txt(TITLE_BEST_X - C.x, TITLE_BEST_Y - C.y, 'BEST --', { color: 'lime' });
    this._loadBest();
    this._buildDailyCard(txt);
    this._buildMissions();
  }

  _paintCard(pal) {
    const g = this.cardG;
    if (!g || !g.scene) return;
    const C = TITLE_CARD;
    const S = C.sections;
    g.clear();
    // player section: a lime wash fading down, like a lit marquee
    for (let i = 0; i < 6; i++) {
      g.fillStyle(pal.lime, 0.07 * (1 - i / 6));
      g.fillRect(3, 3 + i * 5, C.w - 6, 5);
    }
    const rule = (y, color) => {
      const steps = 10;
      const x0 = C.pad;
      const w = C.w - C.pad * 2;
      for (let i = 0; i < steps; i++) {
        g.fillStyle(color, 0.75 * (1 - Math.abs(i - steps / 2) / (steps / 2 + 1)));
        g.fillRect(x0 + Math.round((i * w) / steps), y, Math.ceil(w / steps), 1);
      }
    };
    rule(S.rule1, pal.magenta);
    // MISSIONS header rule, right of the label
    const mx = C.pad + measureText('MISSIONS') + 5;
    g.fillStyle(pal.cyan, 0.45);
    g.fillRect(mx, S.missionsHead + 4, C.w - C.pad - mx, 1);
    g.fillStyle(pal.cyan, 1);
    g.fillRect(mx, S.missionsHead + 3, 2, 3);
    // the Daily Patch date chip frame
    if (this.dailyDateText && this.dailyDateText.scene) {
      const w = this.dailyDateText.textWidth + 6;
      const x = C.w - C.pad - w + 3;
      g.fillStyle(pal.amber, 0.14);
      g.fillRect(x, S.dailyHead - 1, w, 10);
      g.fillStyle(pal.amber, 0.6);
      g.fillRect(x, S.dailyHead + 9, w, 1);
    }
  }

  /**
   * The level badge, at the top of the card. Geometry comes from ProfileLayout.titleBadgeLayout (screen
   * coordinates, overlap-tested); inside the card it is drawn card-local. Works without the card too (tests
   * build only the menu).
   */
  _buildLevelBadge() {
    const theme = this.theme;
    const layout = titleBadgeLayout({
      profile: this.registry.get(REG.PROFILE),
      levels: (this.registry.get(REG.CONTENT) || {}).progression,
    });
    if (!layout) return;
    this.levelBadge = [];
    const card = this.cardPanel && this.cardPanel.scene ? this.cardPanel : null;
    layout.items.forEach((it, i) => {
      const x = card ? it.x - card.x : it.x;
      const y = card ? it.y - card.y : it.y;
      // the first line shares its row with the card's 1UP label
      const room = TITLE_CARD_INNER_W - (i === 0 ? 22 : 0);
      const t = new NeonText(this, theme, x, y, ellipsize(it.text, room), { color: it.color, outline: it.outline, alpha: it.alpha });
      if (card) card.add(t);
      this.levelBadge.push(t);
    });
  }

  /** Redraw the level badge from the current profile (SHOP-2: the equipped title replaces the level title). */
  _refreshLevelBadge() {
    for (const t of this.levelBadge || []) {
      try { t.destroy(); } catch (e) { /* already gone */ }
    }
    this.levelBadge = [];
    this._buildLevelBadge();
  }

  _loadBest() {
    try {
      const store = this.registry.get(REG.SAVE_STORE);
      Promise.resolve(store.getRecentRuns(1000)).then((all) => {
        // Clean runs only (Ranking.rankableOnly): a Head Start run is a different game and must not set
        // the device BEST shown on the Title, any more than it can set a clean leaderboard entry.
        const runs = rankableOnly(all);
        if (!runs.length || !this.bestText.scene) return;
        const m = Math.max(...runs.map((r) => r.distanceM || 0));
        const sc = Math.max(...runs.map((r) => r.score || 0));
        if (m > 0) this.bestText.setText(titleBestText(fmtInt(m), fmtInt(sc)));
      }).catch(() => {});
    } catch (e) { /* cosmetic */ }
  }

  /** The three active missions, in the card's last section. Geometry is unit-tested in MissionsLayout. */
  _buildMissions() {
    try {
      const view = this.registry.get(REG.MISSIONS);
      const rows = (view && view.active) || [];
      const card = this.cardPanel;
      if (card) {
        const S = TITLE_CARD.sections;
        const done = rows.filter((r) => r && r.done).length;
        card.add(new NeonText(this, this.theme, TITLE_CARD.pad, S.missionsHead, 'MISSIONS', { color: 'cyan', outline: 'none' }));
        if (rows.length) {
          card.add(new NeonText(this, this.theme, TITLE_CARD.w - TITLE_CARD.pad, S.missionsHead, `${done}/${Math.min(3, rows.length)}`, {
            color: done ? 'lime' : 'text', anchor: 'right', outline: 'none', alpha: 0.8,
          }));
        }
      }
      if (!rows.length) {
        if (card) {
          card.add(new NeonText(this, this.theme, TITLE_CARD.pad, TITLE_CARD.sections.missions, 'NO ACTIVE MISSIONS', { color: 'text', outline: 'none', alpha: 0.5 }));
        }
        return;
      }
      this.missionsPanel = buildTitleMissionList(this, this.theme, rows);
      if (this.missionsPanel && card) {
        this.missionsPanel.setPosition(this.missionsPanel.x - card.x, this.missionsPanel.y - card.y);
        card.add(this.missionsPanel);
      }
    } catch (e) { /* cosmetic: a missing mission service must never block the Title screen */ }
  }

  _buildDailyCard(txt) {
    const C = TITLE_CARD;
    const S = C.sections;
    this.dailyHeadText = txt(C.pad, S.dailyHead, 'DAILY PATCH', { color: 'amber', outline: 'glow' });
    this.dailyDateText = txt(C.w - C.pad, S.dailyHead, '', { color: 'amber', anchor: 'right' });
    this.dailyRuleText = txt(C.pad, S.ruleName, '', { color: 'magenta', outline: 'glow', scale: 2 });
    this.dailyDescText = txt(C.pad, S.desc1, '', { color: 'text', alpha: 0.82 });
    this.nextPatchText = txt(C.pad, S.next, '', { color: 'cyan' });
    this.chaseText = txt(C.pad, S.chase, '', { color: 'lime' });
    this._applyDaily();
    this._refreshDaily();
    // slow refresh (countdown minutes, midnight rollover); the scene clock stops with the scene
    this.time.addEvent({ delay: 15000, loop: true, callback: () => this._refreshDaily() });
  }

  /** Rebuild everything that shows this.daily: card header, rule, description and the DAILY RUN sub label. */
  _applyDaily() {
    const rule = this.daily.rule || { name: '-', description: '', id: '' };
    const name = rule.name.toUpperCase();
    if (this.dailyDateText) {
      // MM-DD: the year is noise on a daily card, and the full key is on the DAILY RUN screen
      this.dailyDateText.setText(`${String(this.daily.dateKey).slice(5)} UTC`);
    }
    if (this.dailyRuleText) {
      // 2x when it fits the card, else 1x centred in the same 16 px band
      const big = measureText(name) * 2 <= TITLE_CARD_INNER_W;
      this.dailyRuleText.setText(big ? name : ellipsize(name, TITLE_CARD_INNER_W));
      this.dailyRuleText.setScale(big ? 2 : 1);
      this.dailyRuleText.y = TITLE_CARD.sections.ruleName + (big ? 0 : 4);
    }
    this.dailyDesc = rule.description || idToLabel(rule.id);
    if (this.dailyDescText) this.dailyDescText.setText(wrapText(this.dailyDesc.toUpperCase(), TITLE_CARD_INNER_W, 2));
    const row = this.menu && this.menu.rows[1];
    if (row && row.sub) row.sub.setText(ellipsize(name, 76));
    if (this.cardG) this._paintCard(this.theme.pal);
  }

  /** Streak, today's best (or NOT PLAYED TODAY) and the NEXT PATCH IN countdown. All synchronous reads, never throws. */
  _refreshDaily() {
    if (!this.nextPatchText || !this.nextPatchText.scene) return;
    const now = new Date();
    // midnight UTC rollover: re-read the daily info so the rule, the DAILY RUN seed and the stats below all agree
    const fresh = DailyPatch.getDailyInfo(now);
    if (fresh.dateKey !== this.daily.dateKey) {
      this.daily = fresh;
      this._applyDaily();
    }
    this.nextPatchText.setText(`NEXT PATCH IN ${DailyPatch.formatCountdown(DailyPatch.msUntilNextRule(now))}`);
    let chase = 'NOT PLAYED TODAY';
    let key = 'amber';
    try {
      const store = this.registry.get(REG.SAVE_STORE);
      const st = store.getDailyStreak(now.getTime());
      const today = store.getDailyStats(now.getTime());
      const played = !!(today && today.attempts > 0);
      chase = titleChaseText(st && st.streak > 0 ? st.streak : 0, played ? fmtInt(today.bestScore) : null);
      if (played) key = 'lime';
    } catch (e) { /* cosmetic: leave the default */ }
    this.chaseText.setText(ellipsize(chase, TITLE_CARD_INNER_W)).setColorKey(key);
  }

  // ------------------------------------------------------------------ footer, help

  _buildFooter() {
    const theme = this.theme;
    this.hint = new NeonText(this, theme, GAME_WIDTH / 2, TITLE_BANDS.hint.y + 4, HINT_TEXT, {
      color: 'text', anchor: 'center', vAnchor: 0.5, outline: 'dark',
    });
    this.hint.setAlpha(0.72);
    // Show the actual bundled version once per game load; never revive it
    // on attract-mode wake or a later return to the title screen.
    this.versionLabel = null;
    if (!versionShown.has(this.game)) {
      versionShown.add(this.game);
      const v = TITLE_BANDS.version;
      const label = this.versionLabel = new NeonText(this, theme, v.x, v.y, `v${packageInfo.version}`, {
        color: 'text', outline: 'dark', scale: 1,
      }).setDepth(LOGO_DEPTH).setAlpha(VERSION_LABEL_ALPHA);
      this.time.delayedCall(3000, () => {
        if (!label.scene) return;
        tweenProgress(this, {
          duration: isReducedMotion(this) ? 120 : 400,
          ease: Ease.outQuad,
          onUpdate: (p) => { if (label.scene) label.setAlpha(VERSION_LABEL_ALPHA * (1 - p)); },
          onComplete: () => { if (label.scene) label.setVisible(false); },
        });
      });
    }
    const h = TITLE_BANDS.help;
    // The touch / mouse route to HOW TO PLAY (keyboard: H; pad: X / Y or SELECT).
    this.helpButton = new Button(this, theme, { x: h.x, y: h.y, w: h.w, h: h.h, label: '? HOW TO PLAY', color: 'amber', onClick: () => this._openHelp(true) });
  }

  /** @param {boolean} [fromButton] the chip already played its own click */
  _openHelp(fromButton) {
    if (this.starting || this.view) return;
    if (!fromButton) uiSfx(this, 'uiSelect');
    if (fromButton && this.attract) { this._exitAttract(); return; }
    this._openView(new HowToPlayView(this, this.theme, { onClose: () => this._closeView() }));
  }

  _openSeed() {
    this._openView(new SeedView(this, this.theme, {
      onClose: () => this._closeView(),
      onSubmit: (seed) => this.startRun(seed || randomSeed()),
    }));
  }

  _openView(view) {
    // The dim survives a view-to-view hop (Profile -> Shop) so it does not flash; Motion fades it otherwise.
    const keepDim = this.dim;
    this.dim = null;
    this._closeView();
    this.dim = openDim(this, keepDim, 0.8);
    this.view = view;
  }

  _closeView() {
    if (this.view) this.view.destroy();
    this.view = null;
    closeDim(this, this.dim);
    this.dim = null;
    this.lastInputAt = this.time ? this.time.now : 0;
  }

  // ------------------------------------------------------------------ input, idle / attract

  /** True (and the input is consumed) when this input should only wake the cabinet. */
  _wakeGate() {
    const now = this.time ? this.time.now : 0;
    this.lastInputAt = now;
    if (this.attract) {
      this._exitAttract();
      return true;
    }
    return now - this.attractExitAt < WAKE_SWALLOW_MS;
  }

  _onAction(action) {
    if (this.starting) return;
    if (this._wakeGate()) return;
    if (this.view) {
      this.view.handleAction(action);
      return;
    }
    // pad X / Y and the N key: HOW TO PLAY (the menu has no use for 'alt')
    if (action === 'alt') {
      this._openHelp();
      return;
    }
    this.menu.handleAction(action);
  }

  /**
   * Inputs MenuInput does not deliver but that must still count as "someone is here": any key (H opens HOW TO
   * PLAY), pointer moves and taps, and every router action (pad buttons, touch). Each wakes attract mode.
   */
  _bindIdleInputs() {
    this._onAnyKey = (ev) => {
      const e = ev && (ev.originalEvent || ev);
      if (this._wakeGate()) return;
      if (e && (e.key === 'h' || e.key === 'H') && !e.repeat && !this.view && !this.starting) this._openHelp();
    };
    this._onPointer = () => { this._wakeGate(); };
    this._onRouter = (p) => { if (p && p.pressed) this._wakeGate(); };
    if (this.input.keyboard) this.input.keyboard.on('keydown', this._onAnyKey);
    this.input.on('pointerdown', this._onPointer);
    this.input.on('pointermove', this._onPointer);
    this.game.events.on(EVT.INPUT_ACTION, this._onRouter);
  }

  _unbindIdleInputs() {
    if (this.input && this.input.keyboard && this._onAnyKey) this.input.keyboard.off('keydown', this._onAnyKey);
    if (this.input && this._onPointer) {
      this.input.off('pointerdown', this._onPointer);
      this.input.off('pointermove', this._onPointer);
    }
    if (this.game && this._onRouter) this.game.events.off(EVT.INPUT_ACTION, this._onRouter);
  }

  /** Pad SELECT (button 8) opens HOW TO PLAY; MenuInput does not map it. */
  _pollPadSelect() {
    let down = false;
    try {
      const pads = (navigator.getGamepads && navigator.getGamepads()) || [];
      for (const p of pads) if (p && p.connected && p.buttons[8] && p.buttons[8].pressed) down = true;
    } catch (e) { /* no gamepad API */ }
    if (down && !this.padSelectPrev && !this._wakeGate() && !this.view && !this.starting) this._openHelp();
    this.padSelectPrev = down;
  }

  /** The things attract mode dims. */
  _attractTargets() {
    return [this.menuPanel, this.cardPanel, this.jukebox && this.jukebox.panel, this.hint, this.helpButton, this.sub].filter((o) => o && o.scene);
  }

  _enterAttract() {
    if (this.attract || this.view || this.starting) return;
    this.attract = true;
    const reduced = isReducedMotion(this);
    const targets = this._attractTargets();
    this.attractBase = targets.map((o) => o.alpha);
    this._fadeTargets(targets, this.attractBase.map((a) => a * 0.22), reduced ? 0 : 600);
    // A full-screen catcher above the menu and the jukebox: a tap only wakes the cabinet, it never also
    // lands on a menu row or a transport key.
    this.attractCatcher = this.add.zone(0, 0, GAME_WIDTH, GAME_HEIGHT).setOrigin(0, 0).setDepth(450).setInteractive();
    this.attractCatcher.on('pointerdown', () => this._wakeGate());
    const A = TITLE_BANDS.attract;
    this.attractPrompt = new NeonText(this, this.theme, GAME_WIDTH / 2, A.y, 'PRESS START', {
      color: 'text', anchor: 'center', scale: 2, outline: 'dark',
    }).setDepth(30);
    this.attractSub = new NeonText(this, this.theme, GAME_WIDTH / 2, A.y + 21, 'INSERT COIN', {
      color: 'amber', anchor: 'center', outline: 'dark',
    }).setDepth(30);
    this.nextTrickAt = 0;
  }

  _exitAttract() {
    if (!this.attract) return;
    this.attract = false;
    this.attractExitAt = this.time.now;
    this.lastInputAt = this.time.now;
    const targets = this._attractTargets();
    const base = targets.map((o, i) => (this.attractBase && this.attractBase[i] !== undefined ? this.attractBase[i] : 1));
    this._fadeTargets(targets, base, isReducedMotion(this) ? 0 : 180);
    for (const k of ['attractCatcher', 'attractPrompt', 'attractSub']) {
      if (this[k] && this[k].scene) this[k].destroy();
      this[k] = null;
    }
  }

  _fadeTargets(targets, to, ms) {
    const from = targets.map((o) => o.alpha);
    tweenProgress(this, {
      duration: ms,
      ease: Ease.outQuad,
      onUpdate: (p) => targets.forEach((o, i) => { if (o.scene) o.setAlpha(from[i] + (to[i] - from[i]) * p); }),
    });
  }

  _updateAttract(t, reduced) {
    if (!this.attract) {
      if (this.view || this.starting) this.lastInputAt = t;
      else if (t - this.lastInputAt > ATTRACT_MS) this._enterAttract();
      return;
    }
    // PRESS START blinks (steady when reduced); the sub line alternates INSERT COIN / FREE PLAY
    if (this.attractPrompt) {
      const on = reduced || Math.floor(t / 530) % 2 === 0;
      this.attractPrompt.setVisible(on);
      // reduced: nothing flashes or swaps, the prompt just sits there
      this.attractPrompt.setColorKey(!reduced && Math.floor(t / 1060) % 2 ? 'magenta' : 'text');
      this.attractSub.setText(!reduced && Math.floor(t / 2120) % 2 ? 'FREE PLAY' : 'INSERT COIN');
    }
    if (!reduced && t >= this.nextTrickAt) {
      this.backdrop.trick({ height: 30, flips: 2 });
      this.nextTrickAt = t + 4200;
    }
  }

  // ------------------------------------------------------------------ starting a run

  /**
   * DAILY RUN. The seed and the mask are both derived at press time from ONE clock read. `this.daily` is
   * refreshed only every 15 s, so reading the seed from it and the mask from "now" could pair yesterday's
   * seed with today's mask for a press just after 00:00 UTC. RunScene reads the daily rule at create(), so
   * deriving all three from the current day keeps seed, mask and rule on the same date.
   * @returns {void}
   */
  _openDailyModes(){
    const openChoices=()=>this._openView(new DailyModesView(this,this.theme,{
      onClose:()=>this._closeView(),
      onClassic:()=>this._startDaily('classic'),
      onDraft:()=>this._startDaily('draft'),
      onEdit:()=>this._openView(new DailyDraftEditorView(this,this.theme,{
        onClose:openChoices,onPlay:()=>this._startDaily('draft'),
      })),
      onBoard:()=>this._openView(new DailyDraftLeaderboardView(this,this.theme,{
        onClose:openChoices,
      })),
    }));
    openChoices();
  }

  _startDaily(mode='classic') {
    const now = new Date();
    // Decision 2: this menu item is the ONLY way to start an official Daily.
    this.startRun(DailyPatch.getDailyInfo(now).seed, DailyPatch.biomeMaskForDate(now), { official: true,mode });
  }

  /**
   * @param {string} seed seed text, optionally with a `seed@mask` suffix (W3).
   * @param {number} [maskOverride] explicit mask (daily run); wins over any suffix.
   * @param {{official?:boolean}} [o] `official: true` only from the DAILY RUN item (decision 2).
   * @returns {void}
   */
  startRun(seed, maskOverride, o) {
    if (this.starting) return;
    this.starting = true;
    const biomeDefs = Object.values((this.registry.get(REG.CONTENT) || {}).biomes || {});
    const parsed = parseSeedMask(seed, biomeDefs);
    this.registry.set(REG.SEED, parsed.seed || seed);
    // Decision 2: set on EVERY Title start, so a typed `daily-*` seed (ENTER SEED) is never official.
    this.registry.set(REG.DAILY_OFFICIAL, !!(o && o.official === true));
    const draft=o?.official===true&&o?.mode==='draft';
    this.registry.set(REG.DAILY_MODE,draft?'draft':'classic');
    this.registry.set(REG.DAILY_DRAFT_RANKS,draft?
      {...(this.registry.get(REG.PROGRESSION)?.store?.profile?.dailyDraft?.ranks||{})}:{});
    // A normal/daily start MUST clear the one-shot training flag.
    const owned = this.registry.get(REG.PROFILE)?.bsodGym?.owned === true;
    this.registry.set(REG.BSOD_GYM, !!(o && o.gym === true && owned));
    // A typed `daily-YYYY-MM-DD` with no suffix is a PRACTICE run of that date: it replays that date's
    // mask (and RunScene plays that date's rule), not the profile's own biomes.
    const typedDay = parsed.hadSuffix ? null : DailyPatch.dateKeyFromSeed(parsed.seed);
    const typedDayInfo = typedDay ? DailyPatch.infoForDateKey(typedDay) : null;
    // W3 mask precedence, highest first:
    //   1. an explicit maskOverride (the Daily: date-derived, identical for every player)
    //   2. a `seed@mask` suffix (a shared seed must reproduce the sender's world)
    //   3. a typed `daily-YYYY-MM-DD`: that date's Daily mask (decision 2, practice run)
    //   4. the profile's own enabled-and-unlocked signatures (an ordinary run)
    // Falling back to 0 at step 4 is what CC Friday caught: START RUN ignored the profile entirely.
    const mask = Number.isFinite(maskOverride)
      ? maskOverride >>> 0
      : parsed.hadSuffix
        ? parsed.biomeMask
        : typedDayInfo
          ? typedDayInfo.biomeMask
          : enabledBiomeMask(this.registry.get(REG.PROFILE), biomeDefs);
    this.registry.set(REG.BIOME_MASK, mask);
    uiSfx(this, 'uiSelect', { pitch: 1.3 });
    this._closeView();
    // a module function, not this._launch(): startRun is also driven on plain contexts (title-biome-start)
    launchRun(this);
  }

  /** Leave for the run (see launchRun). Kept as a method so a scene can be driven through it directly. */
  _launch() {
    launchRun(this);
  }

  update(time) {
    this.backdrop.update(time);
    const reduced = isReducedMotion(this);
    this._updateLogo(time, reduced);
    if (!reduced && !this.attract && !this.starting) this.sub.setAlpha(0.78 + 0.2 * Math.sin(time * 0.004));
    this._pollPadSelect();
    this._updateAttract(time, reduced);
  }
}

/**
 * Leave the Title for the run: the grid and ranges warp, the panels slide off, then the scanline wipe into
 * RunScene. Reduced motion: no warp (Backdrop.warp returns 0), a short fade. Without a backdrop or a tween
 * manager (tests) the scene starts at once, exactly as before.
 * @param {TitleScene} scene
 * @returns {void}
 */
function launchRun(scene) {
  const go = () => scene.scene.start(SCENES.RUN);
  const bd = scene.backdrop;
  const warpMs = bd && typeof bd.warp === 'function' ? bd.warp({ duration: 700 }) : 0;
  const accent = bd && scene.theme && scene.theme.pal ? scene.theme.pal.cyan : undefined;
  if (warpMs > 0 && scene.time && typeof scene.time.delayedCall === 'function') {
    launchFx(scene, warpMs);
    scene.time.delayedCall(Math.round(warpMs * 0.6), () => sceneTransition(scene, go, { duration: 320, accent }));
    return;
  }
  sceneTransition(scene, go, { accent });
}

/** The launch flourish: menu out left, card out right, footer, tagline and jukebox fade. */
function launchFx(scene, ms) {
  const slide = (o, dx) => {
    if (!o || !o.scene) return;
    const x0 = o.x;
    const a0 = o.alpha;
    tweenProgress(scene, {
      duration: ms,
      ease: Ease.inCubic,
      onUpdate: (p) => { if (o.scene) o.setPosition(x0 + dx * p, o.y).setAlpha(a0 * (1 - p)); },
    });
  };
  slide(scene.menuPanel, -240);
  slide(scene.cardPanel, 180);
  for (const o of [scene.hint, scene.helpButton, scene.jukebox && scene.jukebox.panel, scene.sub]) slide(o, 0);
}/**
 * OWNER: UI engineer.
 * HUD overlay launched in parallel by RunScene (`scene.launch(SCENES.UI)`) and stopped by RunScene on shutdown.
 * Read-only: it only LISTENS to game.events (SCORE_CHANGED, COMBO_CHANGED, DISTANCE_CHANGED, TRICK, LANDING,
 * POWERUP_*, HAZARD_HIT / EFFECT_END, ZONE_*, GLITCH_*, CRASH, RESPAWN, GAME_PAUSE / RESUME, RUN_START) and never reaches
 * into RunScene. It may miss RUN_START (it is launched in the same frame RunScene emits it), so everything is
 * initialised from the registry / DailyPatch as well.
 *
 * Speed has no contract event: it is derived from DISTANCE_CHANGED over time. RunScene MAY additionally emit the
 * optional event HUD_SPEED_EVENT with {speedPxS} (about 10 Hz) for an exact reading (see ARCHITECTURE.md UI addenda).
 *
 * Layout (480x270): score top-left, combo top-right, zone chip + warnings top-centre, trick popups below them, power-up
 * timers bottom-left, seed / daily rule bottom-right. The middle band where the rider lives stays clear.
 * Centre banners (warnings, BOOST, PERFECT LANDING, sector strip, bank line, crash banner, popups) never share a slot:
 * `_layout()` stacks the visible ones top to bottom (ui/HudLayout.js `stackY`) from their classic y, pushing them under the fixed
 * HUD rows, the zone chip and the touch buttons they would touch. The sector / mission strip is a full-width band and takes its
 * slot in that same stack (a `full` item), so it cannot overlap the banners above or below it. The bottom row (power-ups, tutorial chip) does the same with `placeX`.
 */
import Phaser from 'phaser';
import { SCENES, REG, GAME_WIDTH, GAME_HEIGHT, PIXELS_PER_METER, SCORING } from '../constants.js';
import { EVT } from '../events.js';
import { missionToastText, stripToastText } from '../ui/MissionsUi.js';
import { DailyPatch } from '../systems/DailyPatch.js';
import { Theme } from '../ui/Theme.js';
import { NeonText, strokeRectPx } from '../ui/Neon.js';
import { measureText } from '../ui/PixelFont.js';
import { addScanlines } from '../ui/Scanlines.js';
import { fmtInt, fmtMult, fmtSec, idToLabel } from '../ui/Format.js';
import { uiSfx } from '../ui/Sound.js';
import { stackY, placeX, STRIP_BAND } from '../ui/HudLayout.js';
import { killerName } from '../systems/CrashReport.js';
import { RunMinimap } from '../ui/RunMinimap.js';
import { cosmeticRandom } from '../systems/CosmeticRandom.js';

/** Optional extra event (additive): payload {speedPxS:number}. */
export const HUD_SPEED_EVENT = 'bb:hudSpeed';

const TRICK_NAMES = {
  backflip: 'BACKFLIP', frontflip: 'FRONTFLIP', helicopterCCW: 'HELI CCW', helicopterCW: 'HELI CW',
  airBrake: 'AIR BRAKE', parachute: 'PARACHUTE', corkscrew: 'CORKSCREW',
};
const ZONE_INFO = {
  highBandwidth: { name: 'HIGH BANDWIDTH', sub: 'LOW FRICTION', color: 'cyan' },
  compression: { name: 'COMPRESSION', sub: 'HIGH GRAVITY', color: 'magenta' },
  wirelessBridge: { name: 'WIRELESS BRIDGE', sub: 'BOUNCE PADS', color: 'lime' },
};
const POWERUP_INFO = {
  clockPulse: { name: 'CLOCK PULSE', color: 'cyan' },
  packetBurst: { name: 'PACKET BURST', color: 'lime' },
  hashedBackup: { name: 'HASHED BACKUP', color: 'amber' },
  // B1 biome pickups (spec §4): each has its own name and icon (_drawIcon)
  mapleWax: { name: 'MAPLE WAX', color: 'amber' },
  slickWaxSpray: { name: 'SLICK WAX', color: 'cyan' },
  aquaLungBubble: { name: 'AQUA-LUNG', color: 'cyan' },
  sweetToothCoating: { name: 'SWEET-TOOTH', color: 'magenta' },
  // B2 biome pickups
  crystalClearGoggles: { name: 'GOGGLES', color: 'cyan' },
  heatShield: { name: 'HEAT SHIELD', color: 'magenta' },
  // B3 biome pickups
  sandrunnerSkis: { name: 'SANDRUNNER SKIS', color: 'amber' },
  royalJellyWax: { name: 'JELLY WAX', color: 'amber' },
  clockworkTreads: { name: 'CLOCKWORK TREADS', color: 'cyan' },
  // B4 biome pickups (both the shared stabilize kind)
  gravityStabilizer: { name: 'GRAV STABILIZER', color: 'amber' },
  stabilizerRails: { name: 'STABILIZER RAILS', color: 'lime' },
  // Shard Magnet: the black hole that vacuums up shards
  shardMagnet: { name: 'SHARD MAGNET', color: 'magenta' },
};
/** B1: a biome hazard names itself on the effect warning line instead of the generic effect label. */
const HAZARD_LABEL = {
  groomerCat: 'GROOMER CAT',
  seaweedTangle: 'SEAWEED TANGLE',
  chocolateRiver: 'CHOCOLATE RIVER',
  // B2: the two blind hazards
  shatterWall: 'SHATTER WALL',
  ashCloud: 'ASH CLOUD',
  // B4: the gust (a crash hazard such as the Meteor never shows an effect line)
  gustFront: 'GUST FRONT',
};
/**
 * Power-up KINDS (B0, biome full treatment). Biome pickups are keyed by id like the base ones once their content lands;
 * until a pickup id has its own POWERUP_INFO row, its chip, popup colour and icon come from its effect kind here.
 */
const POWERUP_KIND_INFO = {
  ward: { color: 'cyan' },
  glide: { color: 'lime' },
  stabilize: { color: 'amber' },
};
/** Hazard effects on screen. `showMs`: minimum time the warning stays up (a gust is instant, so it reports 0 ms). */
const EFFECT_INFO = {
  scramble: { label: 'PHYSICS SCRAMBLE', color: 'danger' },
  slow: { label: 'SPEED CUT', color: 'amber' },
  blind: { label: 'BLINDED', color: 'amber' },
  gust: { label: 'GUST', color: 'cyan', showMs: 700 },
};

const HINT_TEXT = {
  keyboard: { push: 'W  PUSH', hop: 'SPACE  HOP', flip: 'IN AIR  HOLD A / D  FLIP', tuck: 'A+D  TUCK', boost: 'CLEAN LANDING = SPEED BOOST' },
  touch: { push: 'TAP PUSH', hop: 'TAP HOP', flip: 'IN AIR  HOLD TILT  FLIP', tuck: 'HOLD TUCK', boost: 'CLEAN LANDING = SPEED BOOST' },
  gamepad: { push: 'RT  PUSH', hop: 'A  HOP', flip: 'IN AIR  HOLD STICK L / R  FLIP', tuck: 'LT  TUCK', boost: 'CLEAN LANDING = SPEED BOOST' },
};
const CHAIN_LIFE_MS = 2500;
/** Backstop only: RunScene's HintScheduler (systems/HintScheduler.js) owns hint timing and always sends the hide. */
const HINT_MAX_MS = 8000;

/** Flow meter: compact readout under the pending-points line (top-right), bar width in px. */
const FLOW_Y = 62;
const FLOW_BAR_W = 64;
/** Widest a popup line may be (screen is 480 px). */
const POPUP_MAX_W = 440;
const flowColor = (f) => (f >= 2.5 ? 'magenta' : f >= 2 ? 'amber' : f >= 1.5 ? 'lime' : 'cyan');
/** 1.5 -> '1.5', 1.25 -> '1.25', 2 -> '2'. */
const fmtShort = (n) => String(Math.round(n * 100) / 100);

/** The named-combo bank line (the payoff) is its own big line; the small popups stack under it. */
const BANK_Y = 80;
const POPUP_Y = 100;
const POPUP_STEP = 11;
const MAX_POPUPS = 3;
/** Row of the shard counter (the speed row above it is 10 px high; its pop stays under that). */
const SHARD_Y = 53;
/** Classic top y of each centre slot (used when nothing above it is showing). */
const SLOT = { warn: 22, boost: 24, flash: 46, strip: 59, bank: BANK_Y, banner: 86, popup: POPUP_Y };
/**
 * Strip slide timings. `runEnd` must finish well inside RunScene's 950 ms crash-to-Game-Over stop (RUN_END is
 * emitted at the crash, and the stop is checked once per frame), so it ends at 800 ms.
 */
const STRIP_TIMING = {
  normal: { inMs: 220, holdMs: 500, outMs: 220 },
  runEnd: { inMs: 200, holdMs: 400, outMs: 200 },
};
const POWER_Y = GAME_HEIGHT - 28;
const POWER_PITCH = 62;
const HINT_ROWS = [GAME_HEIGHT - 23, GAME_HEIGHT - 44];

export class UIScene extends Phaser.Scene {
  constructor() {
    super(SCENES.UI);
  }

  create() {
    this.frozen = false;
    this.listeners = [];
    const theme = (this.theme = new Theme(this));
    const content = this.registry.get(REG.CONTENT) || {};
    this.content = content;
    this.hud = this.add.container(0, 0);

    // state
    this.score = 0;
    this.meters = 0;
    this.multiplier = 1;
    this.speedMs = 0;
    this.lastDist = { m: 0, t: 0 };
    this.exactSpeedUntil = 0;
    this.powerups = new Map();
    this.effects = new Map();
    this.zones = [];
    this.popups = [];
    this.glitchUntil = 0;
    this.nowMs = 0;
    this.runId = '';
    this.dailyRuleId = '';
    this.shards = 0;
    this.chain = 0;
    this.chainUntil = 0;
    this.pending = 0;
    this.pendingRaw = 0;
    this.hintId = null;
    this.hintUntil = 0;
    this.stripQueue = [];
    this.stripBusy = false;
    this.missionToastsThisRun = new Set();
    this.bestShown = false;
    this.flow = 1;
    this.flowFrac = 0;
    this.flowStep = 0;
    this.zoneY = 3;
    this.powerX = 8;
    this.hintX = 0;
    this.hintY = HINT_ROWS[0];
    this.touchRects = [];
    this.touchAt = -1e9;
    this.bannerScale = 3;
    this.boostScale = 2;

    this._buildStats();
    this._buildCenter();
    this._buildFooter();
    this._buildSeedInfo(this.registry.get(REG.SEED));
    this.minimap = new RunMinimap(this);
    this.scan = addScanlines(this, 0.55);

    const on = (evt, fn) => {
      this.game.events.on(evt, fn, this);
      this.listeners.push([evt, fn]);
    };
    on(EVT.RUN_START, this.onRunStart);
    on(EVT.GYM_ATTEMPT_RESET, this.onGymAttemptReset);
    on(EVT.GYM_READY_GO, this.onGymReadyGo);
    on(EVT.GYM_SETUP_UNLOCKED, this.onGymSetupUnlocked);
    on(EVT.SCORE_CHANGED, this.onScore);
    on(EVT.COMBO_CHANGED, this.onCombo);
    on(EVT.DISTANCE_CHANGED, this.onDistance);
    on(HUD_SPEED_EVENT, this.onSpeed);
    on(EVT.TRICK, this.onTrick);
    on(EVT.LANDING, this.onLanding);
    on(EVT.POWERUP_COLLECTED, this.onPowerCollected);
    on(EVT.POWERUP_EXPIRED, this.onPowerExpired);
    on(EVT.HAZARD_HIT, this.onHazard);
    on(EVT.KODIAK, this.onKodiak);
    on(EVT.EFFECT_END, this.onEffectEnd);
    on(EVT.ZONE_ENTER, this.onZoneEnter);
    on(EVT.ZONE_EXIT, this.onZoneExit);
    on(EVT.GLITCH_START, this.onGlitchStart);
    on(EVT.GLITCH_END, this.onGlitchEnd);
    on(EVT.CRASH, this.onCrash);
    on(EVT.RESPAWN, this.onRespawn);
    on(EVT.GAME_PAUSE, this.onPause);
    on(EVT.GAME_RESUME, this.onResume);
    on(EVT.RUN_END, this.onRunEnd);
    on(EVT.LANDING_BOOST, this.onBoost);
    on(EVT.NEAR_MISS, this.onNearMiss);
    on(EVT.SHARD_COLLECTED, this.onShard);
    on(EVT.MILESTONE, this.onMilestone);
    on(EVT.NEW_BEST, this.onNewBest);
    // W3: biome banner. Uses the same serialised strip queue as milestones and missions, so two strips
    // never show at once. Overlap with the FLOW indicator, the trick popups and the other centre banners
    // is prevented by _layout, which stacks the strip band with them as one full-width slot.
    on(EVT.BIOME_ENTER, this.onBiomeEnter);
    on(EVT.TUTORIAL_HINT, this.onHint);
    on(EVT.FLOW_CHANGED, this.onFlowChanged);
    on(EVT.FLOW_LOST, this.onFlowLost);
    // W2: toast the moment a mission is met, not just at run end.
    on(EVT.MISSION_COMPLETED, this.onMissionCompleted);
    on(EVT.MUSIC_TRACK_CHANGED, this.onMusicTrackChanged);

    const cleanup = () => {
      for (const [evt, fn] of this.listeners) this.game.events.off(evt, fn, this);
      this.listeners.length = 0;
    };
    this.events.once('shutdown', cleanup);
    this.events.once('destroy', cleanup);
  }

  // ---------------------------------------------------------------- build

  _t(x, y, text, opts) {
    const t = new NeonText(this, this.theme, x, y, text, opts);
    this.hud.add(t);
    return t;
  }

  _buildStats() {
    this.scoreLabel = this._t(8, 4, 'SCORE', { color: 'cyan' });
    this.scoreLabel.setAlpha(0.8);
    this.scoreText = this._t(8, 13, '0', { color: 'text', scale: 2 });
    this.distText = this._t(8, 31, '0 M', { color: 'lime' });
    this.speedText = this._t(8, 41, '0 KM/H', { color: 'cyan' });
    this.comboLabel = this._t(GAME_WIDTH - 8, 4, 'COMBO', { color: 'magenta', anchor: 'right' });
    this.comboLabel.setAlpha(0.8);
    this.comboText = this._t(GAME_WIDTH - 8, 13, 'x1.00', { color: 'lime', scale: 2, anchor: 'right' });
    this.comboInfo = this._t(GAME_WIDTH - 8, 31, '', { color: 'amber', anchor: 'right' });
    // pending (at stake) trick points, pulses while the multiplier is above x1
    this.pendingText = this._t(GAME_WIDTH - 8, 43, '', { color: 'amber', scale: 2, anchor: 'right', outline: 'glow' });
    this.shardText = this._t(8, SHARD_Y, '', { color: 'cyan' });
    this.chainText = this._t(8, SHARD_Y, '', { color: 'amber' });
    this.shardLabel = '';
    this.shardText.setVisible(false);
    this.chainText.setVisible(false);
    // flow streak: label + draining timeout bar, only visible while flow > 1
    this.flowText = this._t(GAME_WIDTH - 8, FLOW_Y, 'FLOW x1.1', { color: 'cyan', anchor: 'right', outline: 'glow' });
    this.flowG = new Phaser.GameObjects.Graphics(this);
    this.hud.add(this.flowG);
    this.flowLostText = this._t(GAME_WIDTH - 8, FLOW_Y, 'FLOW LOST', { color: 'danger', anchor: 'right', outline: 'glow' });
    this.flowText.setVisible(false);
    this.flowG.setVisible(false);
    this.flowLostText.setAlpha(0);
  }

  _buildCenter() {
    const cx = GAME_WIDTH / 2;
    // zone chip (graphics repainted on palette change)
    this.zoneG = new Phaser.GameObjects.Graphics(this);
    this.hud.add(this.zoneG);
    this.zoneText = this._t(cx, 6, '', { color: 'cyan', anchor: 'center', outline: 'none' });
    this.zoneChip = { w: 0, key: 'cyan' };
    this.theme.bind(() => this._paintZone());
    this.zoneG.setVisible(false);
    this.zoneText.setVisible(false);
    this.warnY = 22;
    this.flash = this._t(cx, 46, '', { color: 'amber', scale: 2, anchor: 'center', vAnchor: 0.5, outline: 'glow' });
    this.flash.setAlpha(0);
    this.banner = this._t(cx, 100, '', { color: 'danger', scale: 3, anchor: 'center', vAnchor: 0.5 });
    this.banner.setAlpha(0);
    // Only shown during the one-second frozen respawn beat. No trick hints.
    this.gymReadyText = this._t(cx, 126, 'READY', {
      color: 'lime', scale: 3, anchor: 'center', vAnchor: 0.5, outline: 'glow',
    });
    // UIScene can miss RUN_START while being launched, so also read the
    // authoritative Gym flag directly for the very first READY hold.
    this.gymReadyText.setVisible(this.registry.get(REG.BSOD_GYM) === true);
    this.boostText = this._t(cx, 24, '', { color: 'lime', scale: 2, anchor: 'center', vAnchor: 0.5, outline: 'glow' });
    this.boostText.setAlpha(0);
    // payoff line of a landing: "DOUBLE BACKFLIP + HELI x1.5 +450" (big, glowing, fades after ~1.1 s)
    this.bankLine = this._t(cx, BANK_Y, '', { color: 'amber', scale: 2, anchor: 'center', vAnchor: 0.5, outline: 'glow' });
    this.bankLine.setAlpha(0);
    // slide-in strip (milestones / new best) just above the rider band
    this.stripC = this.add.container(0, 0);
    this.hud.add(this.stripC);
    this.stripG = new Phaser.GameObjects.Graphics(this);
    this.stripT = new NeonText(this, this.theme, cx, 61, '', { color: 'cyan', scale: STRIP_BAND.textScale, anchor: 'center', outline: 'glow' });
    this.stripC.add([this.stripG, this.stripT]);
    this.stripC.setVisible(false);
    this.hud.sendToBack(this.stripC); // the band sits behind the HUD rows it crosses (score / shards / flow stay readable)
    this.theme.bind(() => this._paintStrip());
    // tutorial chip
    this.hintG = new Phaser.GameObjects.Graphics(this);
    this.hintT = new NeonText(this, this.theme, cx, GAME_HEIGHT - 19, '', { color: 'text', anchor: 'center', outline: 'none' });
    this.hud.add([this.hintG, this.hintT]);
    this.hintChip = { w: 0, key: 'cyan' };
    this.theme.bind(() => this._paintHint());
    this.hintG.setVisible(false);
    this.hintT.setVisible(false);
  }

  _buildFooter() {
    this.powerG = new Phaser.GameObjects.Graphics(this);
    this.hud.add(this.powerG);
    this.theme.bind(() => this._paintPowerups());
  }

  _buildSeedInfo(seed, official) {
    if (this.seedText) {
      this.seedText.destroy();
      this.ruleText.destroy();
    }
    const info = DailyPatch.getDailyInfo();
    // before RUN_START arrives, use the rule this seed plays (a typed daily-<date> replays that date's rule)
    this.dailyRuleId = this.dailyRuleId || DailyPatch.ruleIdForSeed(seed);
    // decision 2: before RUN_START arrives, mirror RunScene's rule (registry flag AND today's daily seed)
    const isOfficial = typeof official === 'boolean'
      ? official
      : this.registry.get(REG.DAILY_OFFICIAL) === true && String(seed || '') === info.seed;
    this.seedText = this._t(GAME_WIDTH - 8, GAME_HEIGHT - 20, `SEED ${String(seed || '-').toUpperCase()}`, {
      color: 'text', anchor: 'right', outline: 'dark',
    });
    this.seedText.setAlpha(0.7);
    const rule = DailyPatch.getRuleById(this.dailyRuleId);
    const name = rule ? rule.name.toUpperCase() : idToLabel(this.dailyRuleId);
    this.ruleText = this._t(GAME_WIDTH - 8, GAME_HEIGHT - 10, this.dailyRuleId ? `${DailyPatch.hudRuleLabel(seed, isOfficial)}  ${name}` : '', {
      color: 'amber', anchor: 'right', outline: 'dark',
    });
    this.ruleText.setAlpha(0.85);
  }

  // ---------------------------------------------------------------- painters

  _paintZone() {
    const g = this.zoneG;
    g.clear();
    if (!this.zoneChip.w) return;
    const pal = this.theme.pal;
    const c = pal[this.zoneChip.key];
    const w = this.zoneChip.w;
    const x = Math.round(GAME_WIDTH / 2 - w / 2);
    g.fillStyle(pal.bg, 0.72);
    const y = this.zoneY;
    g.fillRect(x, y, w, 13);
    strokeRectPx(g, x, y, w, 13, c, 0.9);
    g.fillStyle(c, 1);
    g.fillRect(x - 3, y, 2, 13);
    g.fillRect(x + w + 1, y, 2, 13);
  }

  _paintStrip() {
    const g = this.stripG;
    g.clear();
    const pal = this.theme.pal;
    g.fillStyle(pal.bg, 0.6);
    g.fillRect(0, 59, GAME_WIDTH, 17);
    g.fillStyle(pal[this.stripKey || 'cyan'], 0.9);
    g.fillRect(0, 59, GAME_WIDTH, 1);
    g.fillRect(0, 75, GAME_WIDTH, 1);
  }

  _paintHint() {
    const g = this.hintG;
    g.clear();
    if (!this.hintChip.w) return;
    const pal = this.theme.pal;
    const w = this.hintChip.w;
    const x = this.hintX || Math.round(GAME_WIDTH / 2 - w / 2);
    const y = this.hintY;
    g.fillStyle(pal.bg, 0.78);
    g.fillRect(x, y, w, 13);
    strokeRectPx(g, x, y, w, 13, pal[this.hintChip.key], 0.9);
  }

  _paintPowerups() {
    const g = this.powerG;
    const pal = this.theme.pal;
    g.clear();
    let i = 0;
    for (const [id, p] of this.powerups) {
      const key = this._powerColor(id);
      const c = pal[key];
      const x = this.powerX + i * POWER_PITCH;
      const y = POWER_Y;
      const blink = p.total > 0 && p.remaining < 1000 && Math.floor(this.nowMs / 120) % 2 === 0;
      g.fillStyle(pal.bg, 0.75);
      g.fillRect(x, y, 20, 20);
      strokeRectPx(g, x, y, 20, 20, c, blink ? 0.3 : 1);
      this._drawIcon(g, id, x + 10, y + 10, c);
      if (p.total > 0) {
        g.fillStyle(pal.bgAlt, 1);
        g.fillRect(x, y + 22, 20, 3);
        g.fillStyle(c, blink ? 0.4 : 1);
        g.fillRect(x, y + 22, Math.round(20 * Math.max(0, Math.min(1, p.remaining / p.total))), 3);
      }
      p.slot = i;
      p.sx = x;
      i++;
    }
  }

  /** Effect kind of a power-up id from content ('' when unknown). */
  _powerKind(id) {
    const d = this.content && this.content.powerups && this.content.powerups[id];
    return (d && d.effect && d.effect.kind) || '';
  }

  /** HUD info for a power-up id: its own POWERUP_INFO row, else its kind's (B0), else a cyan chip named after the id. */
  _powerInfo(id) {
    if (POWERUP_INFO[id]) return POWERUP_INFO[id];
    const k = POWERUP_KIND_INFO[this._powerKind(id)];
    return { name: idToLabel(id), color: k ? k.color : 'cyan' };
  }

  _drawIcon(g, id, cx, cy, c) {
    g.lineStyle(1, c, 1);
    g.fillStyle(c, 1);
    const kind = POWERUP_INFO[id] ? '' : this._powerKind(id);
    if (kind === 'ward') {
      // ward: a ring with a bar through it ("this mechanic is off")
      g.strokeCircle(cx, cy, 6);
      g.lineBetween(cx - 4, cy + 4, cx + 4, cy - 4);
    } else if (kind === 'glide') {
      // glide: two runner lines with a speed tick
      g.lineBetween(cx - 6, cy + 2, cx + 5, cy + 2);
      g.lineBetween(cx - 4, cy + 5, cx + 6, cy + 5);
      g.fillTriangle(cx - 2, cy - 6, cx - 2, cy - 1, cx + 4, cy - 3.5);
    } else if (kind === 'stabilize') {
      // stabilize: a level bar on a pivot
      g.lineBetween(cx - 6, cy - 1, cx + 6, cy - 1);
      g.fillTriangle(cx, cy, cx - 4, cy + 6, cx + 4, cy + 6);
    } else if (id === 'mapleWax') {
      // maple leaf: a three-lobed leaf on a stem
      g.fillTriangle(cx, cy - 7, cx - 3, cy - 1, cx + 3, cy - 1);
      g.fillTriangle(cx - 7, cy - 3, cx - 1, cy + 1, cx - 2, cy - 4);
      g.fillTriangle(cx + 7, cy - 3, cx + 1, cy + 1, cx + 2, cy - 4);
      g.fillRect(cx - 2, cy - 2, 4, 4);
      g.lineBetween(cx, cy + 2, cx, cy + 7);
    } else if (id === 'slickWaxSpray') {
      // spray can with a mist of dots
      g.strokeRect(cx - 6, cy - 2, 5, 9);
      g.fillRect(cx - 5, cy - 5, 3, 3);
      g.fillCircle(cx + 2, cy - 4, 1);
      g.fillCircle(cx + 5, cy - 6, 1);
      g.fillCircle(cx + 5, cy - 2, 1);
      g.fillCircle(cx + 2, cy, 1);
    } else if (id === 'aquaLungBubble') {
      // one big bubble with a glint, two small ones rising
      g.strokeCircle(cx - 1, cy + 2, 5);
      g.fillCircle(cx - 3, cy, 1);
      g.strokeCircle(cx + 5, cy - 4, 2);
      g.strokeCircle(cx + 2, cy - 7, 1);
    } else if (id === 'sweetToothCoating') {
      // a tooth (crown + two roots) with a coating line across it
      g.fillRect(cx - 5, cy - 6, 10, 6);
      g.fillTriangle(cx - 5, cy, cx - 1, cy, cx - 4, cy + 6);
      g.fillTriangle(cx + 1, cy, cx + 5, cy, cx + 4, cy + 6);
      g.lineBetween(cx - 7, cy - 3, cx + 7, cy - 3);
    } else if (id === 'crystalClearGoggles') {
      // B2: goggles (two lenses on a strap) with a glint
      g.strokeCircle(cx - 3.5, cy + 1, 3);
      g.strokeCircle(cx + 3.5, cy + 1, 3);
      g.lineBetween(cx - 7, cy - 1, cx + 7, cy - 1);
      g.fillCircle(cx - 4.5, cy, 1);
    } else if (id === 'sandrunnerSkis') {
      // B3: two skis with upturned tips
      g.lineBetween(cx - 7, cy - 2, cx + 4, cy - 2);
      g.lineBetween(cx - 7, cy + 3, cx + 4, cy + 3);
      g.lineBetween(cx + 4, cy - 2, cx + 7, cy - 5);
      g.lineBetween(cx + 4, cy + 3, cx + 7, cy);
    } else if (id === 'royalJellyWax') {
      // B3: a honeycomb cell with a drop of jelly
      const hx = [];
      for (let k = 0; k < 6; k++) hx.push({ x: cx + Math.cos((k * Math.PI) / 3) * 6, y: cy + Math.sin((k * Math.PI) / 3) * 6 });
      g.strokePoints(hx, true, true);
      g.fillCircle(cx, cy + 1, 2.5);
    } else if (id === 'gravityStabilizer') {
      // B4: a gyroscope ring with a level bar
      g.strokeEllipse(cx, cy, 13, 9);
      g.lineBetween(cx - 6, cy, cx + 6, cy);
      g.fillCircle(cx, cy, 1.5);
    } else if (id === 'stabilizerRails') {
      // B4: two rails with ties under a squashed spring
      g.lineBetween(cx - 7, cy + 2, cx + 7, cy + 2);
      g.lineBetween(cx - 7, cy + 5, cx + 7, cy + 5);
      for (let k = -5; k <= 5; k += 5) g.lineBetween(cx + k, cy + 1, cx + k, cy + 6);
      g.lineBetween(cx - 5, cy - 1, cx - 2.5, cy - 4);
      g.lineBetween(cx - 2.5, cy - 4, cx, cy - 1);
      g.lineBetween(cx, cy - 1, cx + 2.5, cy - 4);
      g.lineBetween(cx + 2.5, cy - 4, cx + 5, cy - 1);
    } else if (id === 'clockworkTreads') {
      // B3: a tread loop round a cog
      g.strokeRect(cx - 7, cy - 4, 14, 8);
      g.strokeCircle(cx, cy, 2.5);
      for (let k = 0; k < 4; k++) g.fillRect(cx - 6 + k * 3.5, cy - 5, 1.5, 1.5);
    } else if (id === 'heatShield') {
      // B2: a round shield with a flame inside
      g.strokeCircle(cx, cy, 6);
      g.fillTriangle(cx, cy - 4, cx - 3, cy + 3, cx + 3, cy + 3);
      g.fillTriangle(cx - 2, cy - 1, cx - 4, cy + 3, cx, cy + 3);
    } else if (id === 'shardMagnet') {
      // a black hole: dark core in a ring, with an orbiting shard
      g.strokeCircle(cx, cy, 6);
      g.fillCircle(cx, cy, 2.5);
      g.fillTriangle(cx + 5, cy - 6, cx + 7, cy - 4, cx + 5, cy - 2);
    } else if (id === 'clockPulse') {
      g.strokeCircle(cx, cy, 6);
      g.lineBetween(cx, cy, cx, cy - 4);
      g.lineBetween(cx, cy, cx + 3, cy + 1);
    } else if (id === 'packetBurst') {
      g.fillTriangle(cx - 5, cy - 6, cx - 5, cy + 6, cx, cy);
      g.fillTriangle(cx, cy - 6, cx, cy + 6, cx + 5, cy);
    } else if (id === 'hashedBackup') {
      g.beginPath();
      g.moveTo(cx - 5, cy - 6);
      g.lineTo(cx + 5, cy - 6);
      g.lineTo(cx + 5, cy + 1);
      g.lineTo(cx, cy + 6);
      g.lineTo(cx - 5, cy + 1);
      g.closePath();
      g.strokePath();
      g.fillRect(cx - 1, cy - 3, 2, 5);
    } else {
      g.strokeRect(cx - 5, cy - 5, 10, 10);
    }
  }

  // ---------------------------------------------------------------- events

  onRunStart(p) {
    // First Gym launch gets the same frozen READY cue as later catches.
    this.gymReadyText?.setVisible?.(p?.gym === true);
    this.missionToastsThisRun.clear();
    this.runId = (p && p.runId) || '';
    this.score = 0;
    this.meters = 0;
    this.speedMs = 0;
    this.lastDist = { m: 0, t: this.nowMs };
    this.multiplier = 1;
    this.scoreText.setText('0');
    this.distText.setText('0 M');
    this.speedText.setText('0 KM/H');
    this.comboText.setText(fmtMult(1)).setColorKey('lime');
    this.comboInfo.setText('');
    this._setPending(0);
    this.shards = 0;
    this.chain = 0;
    this.shardText.setVisible(false);
    this.chainText.setVisible(false);
    this._setFlow(1, 0);
    this.tweens.killTweensOf(this.flowLostText);
    this.flowLostText.setAlpha(0);
    this.tweens.killTweensOf(this.bankLine);
    this.bankLine.setAlpha(0);
    this.bestShown = false;
    this._hideHint();
    for (const id of [...this.powerups.keys()]) this._removePowerup(id);
    for (const k of [...this.effects.keys()]) this._removeEffect(k);
    this.zones = [];
    this._refreshZone();
    this.frozen = false;
    this.tweens.resumeAll();
    if (p) {
      this.dailyRuleId = p.dailyRuleId || this.dailyRuleId;
      this._buildSeedInfo(p.seed, p.dailyOfficial === true);
    }
  }

  /** Gym retries keep the gameplay scene alive. Clear ALL attempt-local HUD
   * projections without resetting music, controls, or scene-level ownership. */
  onGymAttemptReset(p) {
    this.score = 0;
    this.meters = 0;
    this.multiplier = 1;
    this.lastDist = { m: 0, t: this.nowMs };
    this.scoreText.setText('0');
    this.distText.setText('0 M');
    this.comboText.setText(fmtMult(1)).setColorKey('lime');
    this.comboInfo.setText('');
    this._setFlow(1, 0);
    this._setPending(0, true);
    this.shards = 0;
    this.chain = 0;
    this.chainUntil = 0;
    this.shardLabel = '';
    this.shardText.setText('').setVisible(false);
    this.chainText.setText('').setVisible(false);
    for (const p of [...this.popups]) this._dropPopup(p);
    this.stripQueue = [];
    this.stripBusy = false;
    this.tweens.killTweensOf(this.stripC);
    this.stripC.setVisible(false);
    this._hideHint();
    for (const id of [...this.powerups.keys()]) this._removePowerup(id);
    for (const id of [...this.effects.keys()]) this._removeEffect(id);
    this.tweens.killTweensOf(this.flowLostText);
    this.flowLostText.setAlpha(0);
    this.tweens.killTweensOf(this.bankLine);
    this.bankLine.setAlpha(0);
    this.gymReadyText?.setVisible?.(!!p?.readyMs);
  }

  onGymReadyGo() {
    this.gymReadyText?.setVisible?.(false);
    this._flash('GO');
  }

  onGymSetupUnlocked() {
    this._banner('GYM SETUP UNLOCKED', 'cyan', 1);
  }

  onRunEnd() {
    this.comboInfo.setText('');
    this._setPending(0);
    this._toastMissions();
  }

  /**
   * W2: a mission was completed mid-run. Shares the milestone strip queue so HUD stacking is
   * unchanged and the toast cannot collide with a MILESTONE or NEW BEST slide.
   * @param {{id:string,title?:string,xp?:number,shards?:number}} p
   */
  onMissionCompleted(p) {
    if (!p) return;
    if (p.id) this.missionToastsThisRun.add(p.id);
    this._strip(missionToastText(p, p.title), 'lime', { mission: p });
  }

  /**
   * Run-end mission toast. RunScene stops this HUD CRASH_TO_GAMEOVER_MS (950 ms) after RUN_END, and one strip
   * already takes 940 ms, so a second queued toast was always cut off (audit UI-3). Every completion not
   * already toasted mid-run is folded into ONE strip ("2 MISSIONS DONE  +100 XP"; a single one keeps its
   * title), together with any mid-run mission toast still waiting in the queue, run on the shorter RUN_END
   * timing and put ahead of any stale strip still waiting in the queue.
   * Game Over lists the missions by name right after. ProgressionService has already published the awards
   * by the time RUN_END reaches this scene (it is registered first in createServices); if it somehow has
   * not, nothing is toasted rather than throwing at run end.
   */
  _toastMissions() {
    try {
      const awards = this.registry.get(REG.LAST_AWARDS);
      const done = awards && awards.missions && Array.isArray(awards.missions.completed)
        ? awards.missions.completed : [];
      // Mid-run toasts that have not started sliding yet would be cut off too: fold them in.
      const fresh = this.stripQueue.filter((j) => j.mission).map((j) => j.mission);
      this.stripQueue = this.stripQueue.filter((j) => !j.mission);
      for (const c of done) {
        if (!c) continue;
        if (c.id && this.missionToastsThisRun.has(c.id)) continue;
        if (c.id) this.missionToastsThisRun.add(c.id);
        fresh.push(c);
      }
      if (!fresh.length) return;
      const text = fresh.length === 1
        ? missionToastText(fresh[0], fresh[0].title)
        : stripToastText(`${fresh.length} MISSIONS`, fresh.reduce((n, c) => n + (Number(c.xp) || 0), 0));
      this._strip(text, 'lime', { front: true, timing: STRIP_TIMING.runEnd });
    } catch (e) { /* cosmetic */ }
  }

  onScore(p) {
    const prev = this.score;
    this.score = p.total || 0;
    this.scoreText.setText(fmtInt(this.score));
    if (this.score - prev >= 40) this._pop(this.scoreText, 2, 2.4);
  }

  onCombo(p) {
    const m = p.multiplier || 1;
    const grew = m > this.multiplier + 1e-6;
    this.multiplier = m;
    this.comboText.setText(fmtMult(m));
    this.comboText.setColorKey(m >= 2.5 ? 'magenta' : m >= 1.5 ? 'amber' : 'lime');
    const n = (p.tricks && p.tricks.length) || 0;
    this.comboInfo.setText(n > 0 ? `${n} TRICK${n > 1 ? 'S' : ''} PENDING` : '');
    if (grew) this._pop(this.comboText, 2, 2.5);
    this._setPending(n > 0 ? p.pendingPoints || 0 : 0);
  }

  _setPending(raw, quiet) {
    const prev = this.pending;
    this.pendingRaw = raw;
    // what a clean landing would bank: pending x combo x the flow carried in
    this.pending = Math.round(raw * (this.multiplier || 1) * (this.flow || 1));
    if (this.pending <= 0) {
      this.pendingText.setText('');
      return;
    }
    this.pendingText.setText(`+${fmtInt(this.pending)}`);
    if (this.pending > prev && !quiet) this._pop(this.pendingText, 2, 2.3);
  }

  onBoost(p) {
    if (!p) return;
    const perfect = p.quality === 'perfect';
    const t = this.boostText;
    this.tweens.killTweensOf(t);
    t.setText(`BOOST +${fmtInt(Math.round(p.amountPxS || 0))}`).setColorKey(perfect ? 'amber' : 'lime');
    const base = perfect ? 3 : 2;
    this.boostScale = base;
    t.__snap = true;
    // pops about its centre by 25 %: stays inside the gap to the next slot
    t.setAlpha(1).setScale(base * 1.25);
    this.tweens.add({ targets: t, scaleX: base, scaleY: base, duration: 150, ease: 'Back.easeOut' });
    this.tweens.add({ targets: t, alpha: 0, delay: perfect ? 900 : 600, duration: 300 });
    // speed readout flash
    this.speedText.setColorKey('amber');
    this._pop(this.speedText, 1, perfect ? 1.4 : 1.3); // the shard row is 12 px below: a bigger pop would run into it
    this.time.delayedCall(450, () => { if (this.speedText.scene) this.speedText.setColorKey('cyan'); });
    uiSfx(this, 'boost', { intensity: perfect ? 1 : 0.35 });
  }

  onNearMiss(p) {
    const bsod = p && p.hazardType === 'bsod';
    // One discovery is allowed; after that, no Surfing the Void tutorial,
    // chain callout or refill popup. Players notice the behavior themselves.
    const first = bsod && p.gymDiscovered === true;
    if (bsod && !first) return; // Secret mechanic: no repeat popups after discovery.
    const label = first ? 'BITSTREAM BLUFF' : 'NEAR MISS';
    this._popup(`${label} +${fmtInt((p && p.points) || 25)}`, bsod ? 'amber' : 'magenta');
    if (first) this._strip('BSOD GYM DISCOVERED', 'cyan');
    const earned = Array.isArray(p?.achievementsEarned) ? p.achievementsEarned : [];
    if (earned.includes('bluff-the-bsod')) this._strip('BLUFFING THE BSOD UNLOCKED', 'amber');
    if (earned.includes('surfing-the-void')) this._strip('SURFING THE VOID UNLOCKED', 'amber');
    uiSfx(this, 'nearMiss');
  }

  onShard(p) {
    if (!p) return;
    this.shards = p.count != null ? p.count : this.shards + 1;
    this.chain = p.chain || 0;
    this.chainUntil = this.nowMs + CHAIN_LIFE_MS;
    this.shardLabel = `SHARDS ${fmtInt(this.shards)}`;
    this.shardText.setText(this.shardLabel).setVisible(true);
    this._pop(this.shardText, 1, 1.4);
    const show = this.chain > 1;
    this.chainText.setVisible(show);
    if (show) {
      this.chainText.setText(`x${this.chain}`);
      this._pop(this.chainText, 1, 1.5);
    }
    uiSfx(this, 'shard', { step: Math.max(0, this.chain - 1) });
  }

  onMilestone(p) {
    const pts = p && p.points > 0 ? `  +${fmtInt(p.points)}` : '';
    this._strip(`SECTOR ${(p && p.sector) || ''}${pts}`, 'cyan');
    uiSfx(this, 'milestone');
  }

  onBiomeEnter(p) {
    if (!p || !p.name) return;
    if (p.entering) this._strip(p.name.toUpperCase(), 'magenta');
    else this._strip('BITSTREAM', 'cyan');
  }

  onMusicTrackChanged(payload) {
    // Song changes are announced by the actual in-world billboard owned by
    // RunScene. Never display a second, competing central HUD toast.
  }

  onNewBest() {
    if (this.bestShown) return;
    this.bestShown = true;
    this._strip('NEW BEST DISTANCE', 'amber');
    uiSfx(this, 'newBest');
  }

  onHint(p) {
    if (!p) return;
    if (!p.show) {
      if (this.hintId === p.id) this._hideHint();
      return;
    }
    const router = this.registry.get(REG.INPUT);
    const ov = router && router.pad && router.pad.overlay;
    const src = router && router.pad && router.pad.state && router.pad.state.lastSource;
    const mode = (ov && ov.isVisible && ov.isVisible()) || src === 'touch' ? 'touch' : src === 'gamepad' ? 'gamepad' : 'keyboard';
    // A valley-recovery hint is allowed, but it must NEVER teach the secret
    // BSOD close-escape trick. The default Trick Deck uses the canopy where
    // Classic used a manual push; swapped controls use UP for the sail.
    const layout = this.registry.get(REG.SETTINGS)?.controlLayout || 'tricksRight';
    const valley = p.id === 'push' && layout !== 'classic';
    const label = valley
      ? (mode === 'keyboard'
        ? layout === 'tricksLeft' ? 'STALLED? HOP + UP SAIL' : 'STALLED? HOP + W SAIL'
        : 'STALLED? HOP + SAIL')
      : HINT_TEXT[mode][p.id] || '';
    if (!label) return;
    this.hintId = p.id;
    this.hintX = 0; // _layout picks the free spot on the next frame
    this.hintY = HINT_ROWS[0];
    this.hintT.setText(label).setVisible(true);
    this.hintChip = { w: measureText(label) + 14, key: 'cyan' };
    this.hintG.setVisible(true);
    this._paintHint();
    this.hintUntil = this.nowMs + HINT_MAX_MS;
  }

  _hideHint() {
    this.hintId = null;
    this.hintUntil = 0;
    this.hintChip.w = 0;
    this.hintG.setVisible(false);
    this.hintT.setVisible(false);
    this._paintHint();
  }

  /**
   * @param {string} text
   * @param {string} key palette key
   * @param {{front?:boolean, timing?:{inMs:number,holdMs:number,outMs:number}, mission?:Object}} [o]
   *   front = jump the queue; mission = the completion this toast announces (so RUN_END can fold it)
   */
  _strip(text, key, o = {}) {
    const job = { text, key, timing: o.timing || STRIP_TIMING.normal };
    if (o.mission) job.mission = o.mission;
    if (o.front) this.stripQueue.unshift(job);
    else this.stripQueue.push(job);
    if (!this.stripBusy) this._nextStrip();
  }

  _nextStrip() {
    const job = this.stripQueue.shift();
    if (!job) {
      this.stripBusy = false;
      return;
    }
    this.stripBusy = true;
    this.stripKey = job.key;
    this._paintStrip();
    this.stripT.setText(job.text).setColorKey(job.key);
    const c = this.stripC;
    this.tweens.killTweensOf(c);
    c.__snap = true;
    c.setVisible(true).setX(-GAME_WIDTH);
    // normal: slide in 220 ms, hold 500 ms, slide out 220 ms (< 1 s total); RUN_END: shorter, see STRIP_TIMING
    const tm = job.timing || STRIP_TIMING.normal;
    this.tweens.add({ targets: c, x: 0, duration: tm.inMs, ease: 'Cubic.easeOut' });
    this.tweens.add({
      targets: c, x: GAME_WIDTH, delay: tm.inMs + tm.holdMs, duration: tm.outMs, ease: 'Cubic.easeIn',
      onComplete: () => { c.setVisible(false); this._nextStrip(); },
    });
  }

  onDistance(p) {
    const m = p.meters || 0;
    this.meters = m;
    this.distText.setText(`${fmtInt(m)} M`);
    if (this.nowMs < this.exactSpeedUntil) return;
    const dt = (this.nowMs - this.lastDist.t) / 1000;
    if (dt > 0.05 && dt < 2) {
      const v = (m - this.lastDist.m) / dt;
      this.speedMs = this.speedMs ? this.speedMs * 0.6 + v * 0.4 : v;
      this.speedText.setText(`${fmtInt(Math.max(0, this.speedMs) * 3.6)} KM/H`);
    }
    this.lastDist = { m, t: this.nowMs };
  }

  onSpeed(p) {
    if (!p) return;
    this.exactSpeedUntil = this.nowMs + 600;
    this.speedMs = (p.speedPxS || 0) / PIXELS_PER_METER;
    this.speedText.setText(`${fmtInt(this.speedMs * 3.6)} KM/H`);
    // flow resync (also covers a missed FLOW_* event and a timeout refresh at the x3.0 cap)
    if (p.flow != null) {
      if (p.flow > 1.001 && (Math.abs(p.flow - this.flow) > 1e-6 || Math.abs((p.flowFrac || 0) - this.flowFrac) > 0.02)) {
        this._setFlow(p.flow, p.flowFrac || 0);
      } else if (p.flow <= 1.001 && this.flow > 1.001) {
        this._setFlow(1, 0);
      }
    }
  }

  onTrick(p) {
    const name = TRICK_NAMES[p.type] || idToLabel(p.type);
    const count = p.count > 1 ? ` X${p.count}` : '';
    this._popup(`${p.isNew ? 'NEW ' : ''}${name}${count} +${fmtInt(p.value)}`, p.isNew ? 'lime' : 'cyan');
  }

  onLanding(p) {
    const banked = p.bankedPoints || 0;
    if (p.midSpin) this._popup('SPIN CUT  GRADE DOWN', 'magenta');
    if (p.quality === 'perfect') {
      const bonus = p.bonusPoints || 20;
      this._flash(`PERFECT LANDING +${bonus}`);
      if (banked > 0) this._bank(this._bankText(p, banked, ''), 'amber');
    } else if (p.quality === 'good') {
      if (banked > 0) this._bank(this._bankText(p, banked, ''), 'text');
    } else if (p.quality === 'sloppy') {
      this._bank(banked > 0 ? this._bankText(p, banked, 'SLOPPY ') : 'SLOPPY LANDING', 'amber');
    }
  }

  /** Show the landing payoff line (scale 2, glow), replacing the previous one. */
  _bank(text, color) {
    const t = this.bankLine;
    this.tweens.killTweensOf(t);
    t.__snap = true;
    t.setText(text).setColorKey(color).setAlpha(1).setScale(2.5);
    this.tweens.add({ targets: t, scaleX: 2, scaleY: 2, duration: 160, ease: 'Back.easeOut' });
    this.tweens.add({ targets: t, alpha: 0, delay: 1100, duration: 350 });
  }

  /**
   * "DOUBLE BACKFLIP + HELI x1.5 +450": named combo, combo multiplier when above x1, banked points. Always fits 480 px
   * at the bank line's scale 2 (shortened step by step: drop prefix, mult, name).
   */
  _bankText(p, banked, prefix) {
    const name = p.comboName || '';
    const mult = p.comboMult > 1.001 ? ` x${fmtShort(p.comboMult)}` : '';
    const pts = ` +${fmtInt(banked)}`;
    const tries = [
      `${prefix}${name || 'BANKED'}${mult}${pts}`,
      `${name || 'BANKED'}${mult}${pts}`,
      `${name || 'BANKED'}${pts}`,
      `BANKED${pts}`,
    ];
    return tries.find((t) => measureText(t) * 2 <= POPUP_MAX_W) || tries[tries.length - 1];
  }

  // ---------------------------------------------------------------- flow

  /** Apply flow state to the meter: visibility, text, colour. frac = remaining timeout 0..1. */
  _setFlow(flow, frac) {
    this.flow = flow;
    this.flowFrac = Math.max(0, Math.min(1, frac));
    const on = flow > 1.001;
    this.flowText.setVisible(on);
    this.flowG.setVisible(on);
    if (on) {
      this.flowText.setText(`FLOW x${flow.toFixed(2)}`).setColorKey(flowColor(flow));
      this._paintFlow();
    }
    this._setPending(this.pendingRaw, true);
  }

  _paintFlow() {
    const g = this.flowG;
    g.clear();
    if (this.flow <= 1.001) return;
    const pal = this.theme.pal;
    const x = GAME_WIDTH - 8 - FLOW_BAR_W;
    const y = FLOW_Y + 10;
    const low = this.flowFrac < 0.25 && Math.floor(this.nowMs / 110) % 2 === 0;
    const c = pal[low ? 'danger' : flowColor(this.flow)];
    g.fillStyle(pal.bg, 0.75);
    g.fillRect(x - 1, y - 1, FLOW_BAR_W + 2, 5);
    g.fillStyle(pal.bgAlt, 1);
    g.fillRect(x, y, FLOW_BAR_W, 3);
    g.fillStyle(c, 1);
    g.fillRect(x, y, Math.round(FLOW_BAR_W * this.flowFrac), 3);
  }

  onFlowChanged(p) {
    if (!p) return;
    const flow = p.flow || 1;
    const rose = flow > this.flow + 1e-6;
    const step = Math.floor(flow * 2); // colour steps at 1.5 / 2 / 2.5
    this._setFlow(flow, p.timeoutFrac != null ? p.timeoutFrac : 1);
    if (flow > 1.001) {
      this.tweens.killTweensOf(this.flowText);
      this.flowText.setAlpha(1);
      if (rose) {
        this._pop(this.flowText, 1, step > this.flowStep ? 2.6 : 1.8);
        uiSfx(this, 'flowUp', { flow });
      } else {
        // sloppy landing, shield hit or timeout halving: partly lost (the bar was refilled by the event's timeoutFrac)
        this._pop(this.flowText, 1, 1.4);
        uiSfx(this, 'uiBack', { pitch: 0.8, volume: 0.6 });
        if (p.reason === 'timeout') {
          this.flowText.setColorKey('danger');
          this.time.delayedCall(350, () => {
            if (this.flowText.scene && this.flow > 1.001) this.flowText.setColorKey(flowColor(this.flow));
          });
        }
      }
    }
    this.flowStep = step;
  }

  onFlowLost() {
    this._setFlow(1, 0);
    this.flowStep = 0;
    const t = this.flowLostText;
    this.tweens.killTweensOf(t);
    t.setY(FLOW_Y).setAlpha(1).setScale(1.6);
    this.tweens.add({ targets: t, scaleX: 1, scaleY: 1, duration: 150, ease: 'Back.easeOut' });
    this.tweens.add({ targets: t, alpha: 0, y: FLOW_Y + 6, delay: 800, duration: 300 });
    uiSfx(this, 'flowLost');
  }

  onPowerCollected(p) {
    const id = p.id;
    const total = p.durationMs || 0;
    const old = this.powerups.get(id);
    if (old) old.text.destroy();
    const info = this._powerInfo(id);
    const t = this._t(0, GAME_HEIGHT - 26, '', { color: 'text', outline: 'dark' });
    this.powerups.set(id, { total, remaining: total, charges: p.charges || 0, text: t });
    this._paintPowerups();
    this._layoutPowerups();
    this._popup(info.name, this._powerColor(id));
  }

  _powerColor(id) {
    const info = this._powerInfo(id);
    return (this.content.powerups && this.content.powerups[id] && this.content.powerups[id].colorKey) || info.color;
  }

  onPowerExpired(p) {
    if (this.powerups.has(p.id)) this._removePowerup(p.id);
  }

  _removePowerup(id) {
    const e = this.powerups.get(id);
    if (e) e.text.destroy();
    this.powerups.delete(id);
    this._paintPowerups();
    this._layoutPowerups();
  }

  _layoutPowerups() {
    let i = 0;
    for (const [, p] of this.powerups) {
      p.text.setPosition(this.powerX + i * POWER_PITCH + 24, GAME_HEIGHT - 24);
      i++;
    }
  }

  /**
   * Issue #47: one warning per pack and the pass bonuses, through the centre popup line. Attack telegraphs are
   * drawn on the bear itself (ring, "!" and name tag), so they never stack popups on top of banners.
   */
  onKodiak(p) {
    if (!p) return;
    if (p.type === 'incoming') {
      const side = p.from === 'both' ? 'BOTH SIDES' : p.from === 'behind' ? 'BEHIND' : 'AHEAD';
      const who = p.mode === 'mixed' ? 'MIXED KODIAK PACK' : `${p.members?.[0] || ''} PACK`;
      this._popup(`!! ${who} ${side} !!`, 'danger');
    } else if (p.type === 'passed') this._popup(`${p.air ? 'BEAR HOP' : 'KODIAK PASSED'} +${p.points}`, 'lime');
    else if (p.type === 'shove') this._popup(`BUMPED BY ${p.short}`, 'amber');
  }

  onHazard(p) {
    if (p.effect === 'crash') return;
    const info = EFFECT_INFO[p.effect];
    if (!info) return;
    const dur = Math.max(p.durationMs || 0, info.showMs || 0);
    let e = this.effects.get(p.effect);
    if (!e) {
      const t = this._t(GAME_WIDTH / 2, this.warnY + this.effects.size * 11, '', { color: info.color, anchor: 'center', outline: 'dark' });
      t.__snap = true;
      e = { text: t, remaining: 0, total: 0 };
      this.effects.set(p.effect, e);
    }
    e.remaining = e.total = dur;
    e.label = (p.hazardId && HAZARD_LABEL[p.hazardId]) || null;
    this._updateEffect(p.effect, e);
  }

  _updateEffect(key, e) {
    const info = EFFECT_INFO[key];
    e.text.setText(`!! ${e.label || info.label} ${fmtSec(e.remaining)} !!`);
    e.text.setColorKey(Math.floor(this.nowMs / 150) % 2 === 0 ? info.color : 'text');
  }

  onEffectEnd(p) {
    if (p && this.effects.has(p.effect)) this._removeEffect(p.effect);
  }

  _removeEffect(key) {
    const e = this.effects.get(key);
    if (e) e.text.destroy();
    this.effects.delete(key); // the rest glide up in _layout
  }

  onZoneEnter(p) {
    this.zones = this.zones.filter((z) => z.modId !== p.modId);
    this.zones.push({ modId: p.modId });
    this._refreshZone();
    const info = ZONE_INFO[p.modId];
    if (info) this._pop(this.zoneText, 1, 1.5);
  }

  onZoneExit(p) {
    this.zones = this.zones.filter((z) => z.modId !== p.modId);
    this._refreshZone();
  }

  _refreshZone() {
    const z = this.zones[this.zones.length - 1];
    if (!z) {
      this.zoneChip.w = 0;
      this.zoneG.setVisible(false);
      this.zoneText.setVisible(false);
      this._paintZone();
      return;
    }
    const info = ZONE_INFO[z.modId] || { name: idToLabel(z.modId), sub: '', color: 'cyan' };
    const mod = this.content.terrainMods && this.content.terrainMods[z.modId];
    const key = (mod && mod.colorKey) || info.color;
    const label = info.sub ? `${info.name} // ${info.sub}` : info.name;
    this.zoneText.setText(label).setColorKey(key);
    this.zoneChip = { w: measureText(label) + 14, key };
    this.zoneG.setVisible(true);
    this.zoneText.setVisible(true);
    this._paintZone();
  }

  onGlitchStart(p) {
    this.glitchUntil = this.nowMs + Math.min(250, (p && p.durationMs) || 100);
    this.glitchPower = Math.max(1, Math.round(((p && p.intensity) || 0.5) * 4));
  }

  onGlitchEnd() {
    this.glitchUntil = 0;
    this.hud.setPosition(0, 0).setAlpha(1);
  }

  onCrash(p) {
    if (p && p.negated) {
      this._banner('HASHED BACKUP USED', 'amber', 1);
    } else {
      // Readable Chaos phase 3: the banner names the killer (CrashReport.killerName; a hazard that cannot kill never is)
      const hz = (this.registry.get(REG.CONTENT) || {}).hazards || {};
      const name = killerName(p && p.cause, p && p.hazardId ? hz[p.hazardId] : null);
      this._banner(name, 'danger', name.length * 18 > 460 ? 2 : 3); // 6 px a glyph at scale 3 in a 480 px HUD
      this.comboInfo.setText('');
    }
  }

  onRespawn(p) {
    if (p && p.reason === 'manual') this._popup(p.comboPenalty > 0 ? `RESET  -${p.comboPenalty} COMBO` : 'RESET', 'amber');
  }

  onPause() {
    this.frozen = true;
    this.tweens.pauseAll();
  }

  onResume() {
    this.frozen = false;
    this.tweens.resumeAll();
  }

  // ---------------------------------------------------------------- effects

  _pop(textObj, base, peak) {
    this.tweens.killTweensOf(textObj);
    textObj.setScale(peak);
    this.tweens.add({ targets: textObj, scaleX: base, scaleY: base, duration: 220, ease: 'Back.easeOut' });
  }

  _flash(text) {
    const f = this.flash;
    this.tweens.killTweensOf(f);
    f.__snap = true;
    f.setText(text).setAlpha(1).setScale(2.5);
    this.tweens.add({ targets: f, scaleX: 2, scaleY: 2, duration: 160, ease: 'Back.easeOut' });
    this.tweens.add({ targets: f, alpha: 0, delay: 750, duration: 300 });
  }

  _banner(text, color, scale) {
    const b = this.banner;
    this.tweens.killTweensOf(b);
    this.bannerScale = scale;
    b.__snap = true;
    b.setText(text).setColorKey(color).setScale(scale * 1.25).setAlpha(1);
    this.tweens.add({ targets: b, scaleX: scale, scaleY: scale, duration: 140, ease: 'Back.easeOut' });
    this.tweens.add({ targets: b, alpha: 0, delay: 900, duration: 250 });
  }

  _popup(text, color) {
    // older popups drop one slot (positions come from _layout, which glides them down)
    for (const p of this.popups) this.tweens.killTweensOf(p);
    const t = this._t(GAME_WIDTH / 2, POPUP_Y, text, { color, anchor: 'center', outline: 'dark' });
    t.__snap = true;
    t.setScale(1.25);
    this.popups.unshift(t);
    this.tweens.add({ targets: t, scaleX: 1, scaleY: 1, duration: 140, ease: 'Back.easeOut' });
    this.tweens.add({
      targets: t, alpha: 0, delay: 650, duration: 350,
      onComplete: () => this._dropPopup(t),
    });
    while (this.popups.length > MAX_POPUPS) this._dropPopup(this.popups[this.popups.length - 1]);
    // earlier popups keep fading from where they are
    for (const p of this.popups) {
      if (p !== t) {
        this.tweens.add({ targets: p, alpha: 0, delay: 400, duration: 300, onComplete: () => this._dropPopup(p) });
      }
    }
  }

  _dropPopup(t) {
    const i = this.popups.indexOf(t);
    if (i >= 0) this.popups.splice(i, 1);
    this.tweens.killTweensOf(t);
    if (t.scene) t.destroy();
  }

  // ---------------------------------------------------------------- layout

  /** Screen box of a NeonText (game px), from its current scale and anchor. */
  _trect(nt) {
    const s = nt.scaleX;
    const w = measureText(nt.main.text) * s;
    const h = 8 * s;
    return { x: nt.x - w * nt.main.originX, y: nt.y - h * nt.main.originY, w, h };
  }

  _shown(nt) {
    return nt.visible && nt.alpha > 0.03 && !!nt.main.text;
  }

  /** Boxes of the fixed HUD rows that are showing (what the centre banners must not touch). */
  _fixedRects() {
    const out = [];
    for (const nt of [this.scoreLabel, this.scoreText, this.distText, this.speedText, this.shardText, this.chainText,
      this.comboLabel, this.comboText, this.comboInfo, this.pendingText, this.flowText, this.flowLostText]) {
      if (this._shown(nt)) out.push(this._trect(nt));
    }
    if (this.flowG.visible) out.push({ x: GAME_WIDTH - 8 - FLOW_BAR_W - 1, y: FLOW_Y + 9, w: FLOW_BAR_W + 2, h: 5 });
    return out;
  }

  /** Boxes (game px) of the on-screen touch buttons, read from the DOM overlay and mapped through the canvas rectangle. */
  _refreshTouchRects() {
    this.touchAt = this.nowMs;
    const router = this.registry.get(REG.INPUT);
    const ov = router && router.pad && router.pad.overlay;
    const root = ov && ov.isVisible && ov.isVisible() && ov.root;
    const canvas = this.game.canvas;
    const out = [];
    if (root && root.querySelectorAll && canvas && canvas.getBoundingClientRect) {
      const cr = canvas.getBoundingClientRect();
      if (cr.width > 0 && cr.height > 0) {
        const sx = GAME_WIDTH / cr.width;
        const sy = GAME_HEIGHT / cr.height;
        for (const el of root.querySelectorAll('.bb-cl')) {
          const r = el.getBoundingClientRect();
          if (r.width > 0 && r.height > 0) out.push({ x: (r.left - cr.left) * sx, y: (r.top - cr.top) * sy, w: r.width * sx, h: r.height * sy });
        }
      }
    }
    this.touchRects = out;
  }

  _glide(obj, ty, dt) {
    if (obj.__snap || obj.__laid === undefined) {
      obj.__snap = false;
      obj.__laid = true;
      obj.y = ty;
      return;
    }
    const d = ty - obj.y;
    obj.y = Math.abs(d) < 1 ? ty : Math.round(obj.y + d * Math.min(1, dt / 70));
  }

  /** Stack the centre slots and place the bottom row. Called every frame; cheap (a dozen rectangles). */
  _layout(dt) {
    if (this.nowMs - this.touchAt > 500) this._refreshTouchRects();
    const cx = GAME_WIDTH / 2;
    const touch = this.touchRects;
    const keep = this._fixedRects().concat(touch);

    // zone chip: top centre, below the touch pause / reset buttons when those are up
    let chipBox = null;
    if (this.zoneChip.w) {
      const w = this.zoneChip.w + 8;
      const y = stackY([{ w, h: 13, pref: 3 }], { cx, gap: 3, keepOuts: touch })[0];
      if (y !== this.zoneY) {
        this.zoneY = y;
        this._paintZone();
      }
      this.zoneText.setY(y + 3);
      chipBox = { x: cx - w / 2, y, w, h: 13 };
    } else this.zoneY = 3;
    if (chipBox) keep.push(chipBox);

    // centre stack, in priority order; each entry is {obj, w, h, pref, kind}
    const slots = [];
    const add = (obj, w, h, pref, kind) => slots.push({ obj, w, h, pref, kind });
    for (const e of this.effects.values()) add(e.text, measureText(e.text.main.text), 8, SLOT.warn, 'top');
    if (this._shown(this.boostText)) add(this.boostText, measureText(this.boostText.main.text) * this.boostScale, 8 * this.boostScale, SLOT.boost, 'mid');
    if (this._shown(this.flash)) add(this.flash, measureText(this.flash.main.text) * 2, 16, SLOT.flash, 'mid');
    // The strip is a FULL-WIDTH band, not a text box: its background fill crosses the whole row, so measuring
    // only its text (the W2 defect) let it paint over "FLOW x1.25" and the trick popups. It takes its slot in
    // this same stack (between the flash and the bank line, in SLOT order) as a `full` item, tested across
    // the whole row. It used to be placed separately with placeBand, which ignored the stack, so it sat on
    // the PERFECT flash, the bank line and the CRASH banner (audit U5a/b/c).
    const stripUp = this.stripC.visible && Boolean(this.stripT.main.text);
    if (stripUp) slots.push({ obj: this.stripC, w: GAME_WIDTH, h: STRIP_BAND.h, pref: SLOT.strip, kind: 'band', full: true });
    if (this._shown(this.bankLine)) add(this.bankLine, measureText(this.bankLine.main.text) * 2, 16, SLOT.bank, 'mid');
    if (this._shown(this.banner)) add(this.banner, measureText(this.banner.main.text) * this.bannerScale, 8 * this.bannerScale, SLOT.banner, 'mid');
    for (const p of this.popups) add(p, measureText(p.main.text), 8, SLOT.popup, 'top');
    const ys = stackY(slots, { cx, startY: 0, gap: 3, width: GAME_WIDTH, keepOuts: keep });
    // The minimap dims under these instead of pushing the full-width strip down into the playfield.
    this._minimapOccluders = slots.map((sl, i) => (sl.full
      ? { x: 0, y: ys[i], w: GAME_WIDTH, h: sl.h }
      : { x: cx - sl.w / 2, y: ys[i], w: sl.w, h: sl.h }));
    slots.forEach((sl, i) => {
      if (sl.kind === 'band') {
        // The container's band is drawn at local y 59..76 and its text at local y 61: shift so the BAND
        // top lands on its stacked y. Never lower than the screen allows.
        const bandTop = Math.min(ys[i], Math.max(SLOT.strip, GAME_HEIGHT - sl.h));
        const ty = bandTop - SLOT.strip;
        if (this.stripC.__snap) { this.stripC.__snap = false; this.stripC.y = ty; } else this.stripC.y += (ty - this.stripC.y) * Math.min(1, dt / 70);
        return;
      }
      this._glide(sl.obj, sl.kind === 'mid' ? ys[i] + sl.h / 2 : ys[i], dt);
    });

    // bottom row: power-up timers (clear of the touch buttons), then the tutorial chip (clear of both and of the seed lines)
    const n = this.powerups.size;
    const rowW = n ? (n - 1) * POWER_PITCH + 56 : 0;
    let px = 8;
    if (n) {
      const free = placeX(rowW, POWER_Y, 26, 8, touch, { min: 8, max: GAME_WIDTH - 8 });
      px = free === null ? 8 : free;
    }
    if (px !== this.powerX) {
      this.powerX = px;
      this._paintPowerups();
      this._layoutPowerups();
    }
    const bottom = touch.slice();
    if (n) bottom.push({ x: px, y: POWER_Y, w: rowW, h: 26 });
    if (this.seedText && this.seedText.visible) bottom.push(this._trect(this.seedText), this._trect(this.ruleText));
    // The minimap keeps clear of everything in `bottom` so far (touch buttons, power-ups, seed lines);
    // the tutorial chip then yields to the minimap, never the other way round (no ping-pong).
    this._minimapKeepOuts = keep.concat(bottom);
    if (this.minimap && this.minimap.rect) bottom.push(this.minimap.rect);
    if (this.hintChip.w) {
      const w = this.hintChip.w;
      let hx = null;
      let hy = HINT_ROWS[0];
      for (const row of HINT_ROWS) {
        hy = row;
        hx = placeX(w, row, 13, Math.round(cx - w / 2), bottom, { min: 4, max: GAME_WIDTH - 4 });
        if (hx !== null) break;
      }
      if (hx === null) hx = Math.round(cx - w / 2);
      if (hx !== this.hintX || hy !== this.hintY) {
        this.hintX = hx;
        this.hintY = hy;
        this._paintHint();
      }
      this.hintT.setPosition(hx + w / 2, hy + 4);
    }
    // the shard chain chip follows the (popping) shard counter
    if (this.chainText.visible) this.chainText.setX(8 + measureText(this.shardLabel) * this.shardText.scaleX + 6);
  }

  // ---------------------------------------------------------------- frame

  update(time, delta) {
    if (this.frozen) return;
    this.nowMs += delta;
    // power-up timers
    let dirty = false;
    for (const [id, p] of [...this.powerups]) {
      if (p.total > 0) {
        p.remaining -= delta;
        if (p.remaining <= 0) {
          this._removePowerup(id);
          continue;
        }
        p.text.setText(`${fmtSec(p.remaining)}S`);
        dirty = true;
      } else {
        p.text.setText(`x${p.charges || 1}`);
      }
    }
    if (dirty) this._paintPowerups();
    // effect timers
    for (const [key, e] of [...this.effects]) {
      e.remaining -= delta;
      if (e.remaining <= 0) this._removeEffect(key);
      else this._updateEffect(key, e);
    }
    // speed decays when no distance ticks arrive
    if (this.nowMs >= this.exactSpeedUntil && this.nowMs - this.lastDist.t > 1500 && this.speedMs > 0) {
      this.speedMs = 0;
      this.speedText.setText('0 KM/H');
    }
    // the on-screen touch controls own the bottom-right corner: hide the seed / daily rule lines while they are shown
    const router = this.registry.get(REG.INPUT);
    const ov = router && router.pad && router.pad.overlay;
    const covered = !!(ov && ov.isVisible && ov.isVisible());
    if (this.seedText && this.seedText.visible === covered) {
      this.seedText.setVisible(!covered);
      this.ruleText.setVisible(!covered);
    }
    // glitch jitter of the HUD (subtle)
    if (this.nowMs < this.glitchUntil) {
      this.hud.setPosition(Phaser.Math.Between(-this.glitchPower, this.glitchPower), 0);
      this.hud.setAlpha(cosmeticRandom('ui/glitch').next() < 0.3 ? 0.6 : 1);
    } else if (this.hud.x !== 0 || this.hud.alpha !== 1) {
      this.hud.setPosition(0, 0).setAlpha(1);
    }
    // flow timeout drains in run time (resynced ~10 Hz by HUD_SPEED_EVENT)
    if (this.flow > 1.001) {
      this.flowFrac = Math.max(0, this.flowFrac - delta / SCORING.flowTimeoutMs);
      this._paintFlow();
    }
    this._layout(delta);
    // A passing song billboard is a keep-out too: the minimap must not paint over the sign.
    let sign = null;
    try { sign = this.scene.get(SCENES.RUN)?.songBillboard?.screenRect?.() ?? null; } catch { /* run scene gone */ }
    const keepOuts = sign ? (this._minimapKeepOuts || []).concat(sign) : this._minimapKeepOuts;
    this.minimap?.update(delta, { keepOuts, occluders: this._minimapOccluders });
    // zone chip pulse
    if (this.zoneText.visible) this.zoneG.setAlpha(0.75 + 0.25 * Math.sin(this.nowMs * 0.008));
    // tutorial chip fallback timeout, shard chain expiry
    if (this.hintId && this.nowMs > this.hintUntil) this._hideHint();
    if (this.chain > 0 && this.nowMs > this.chainUntil) {
      this.chain = 0;
      this.chainText.setVisible(false);
    }
    // combo urgency: pending points pulse while the multiplier is above x1
    if (this.pending > 0) {
      if (this.multiplier > 1.01) {
        const k = Math.sin(this.nowMs * (0.012 + (this.multiplier - 1) * 0.004));
        this.pendingText.setAlpha(0.7 + 0.3 * k);
        this.pendingText.setColorKey(k > 0.3 ? 'text' : this.multiplier >= 2.5 ? 'magenta' : 'amber');
      } else {
        this.pendingText.setAlpha(1).setColorKey('amber');
      }
    }
  }
}#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

// Global glitch + always-on CRT layer (Phaser PostFX fragment shader).
// Readable Chaos: displacement is limited to a few thin bands / small blocks, the colour inversion only hits a band
// (or one 1/24 s tick of the whole frame at the highest intensities), static covers only some rows, and nothing ever
// blanks the screen. uSafe = 1 (reduced effects) scales everything down and removes the inversion / strobing.

uniform sampler2D uMainSampler;
uniform float uIntensity; // 0 = off, 1 = full glitch (already envelope-shaped by GlitchPipeline)
uniform float uTime;      // seconds
uniform float uKind;      // 0 none, 1 rgbSplit, 2 scanlineWobble, 3 stutter, 4 dropout, 5 static
uniform float uSeed;      // 0..1, derived from the event id (seed-bound pattern)
uniform float uSafe;      // 1 = reduced effects (no inversion, weaker)
uniform float uCrt;       // always-on scanline/CRT strength, 0..1
uniform vec3 uBg;        // clear colour showing through transparent camera pixels
uniform vec2 uResolution; // render size in px (set by Phaser PostFXPipeline)

varying vec2 outTexCoord;

float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// Camera texture is premultiplied and transparent where nothing is drawn: composite over the clear colour so the
// effects act on what the player actually sees.
vec3 tex(vec2 p) {
  vec4 t = texture2D(uMainSampler, clamp(p, 0.0, 1.0));
  return t.rgb + uBg * (1.0 - t.a);
}

float kindIs(float n) {
  return step(abs(uKind - n), 0.5);
}

void main() {
  vec2 uv = outTexCoord;
  float I = uIntensity * mix(1.0, 0.4, uSafe);
  vec3 col;

  if (I > 0.003) {
    float wRgb = kindIs(1.0);
    float wWob = kindIs(2.0);
    float wStut = kindIs(3.0);
    float wDrop = kindIs(4.0);
    float wStat = kindIs(5.0);

    float tick = floor(uTime * 24.0);   // glitch animates at 24 steps per second
    float seed = uSeed * 97.0;

    // --- horizontal tearing: a handful of thin bands slide sideways
    float bandN = 10.0 + floor(hash11(seed + 1.0) * 14.0);
    float band = floor(uv.y * bandN);
    float bh = hash21(vec2(band, tick + seed));
    float tearProb = I * (0.16 + 0.24 * wStut + 0.14 * wWob + 0.08 * wStat);
    float tear = step(1.0 - tearProb, bh) * (hash21(vec2(band + 7.0, tick + seed)) * 2.0 - 1.0);
    uv.x += tear * 0.055 * I * (1.0 + wStut);

    // --- scanline wobble
    uv.x += sin(uv.y * uResolution.y * 0.3 + uTime * 46.0) * 0.0035 * I * (0.5 + 1.8 * wWob);

    // --- block displacement
    vec2 grid = vec2(7.0 + floor(hash11(seed + 3.0) * 8.0), 5.0 + floor(hash11(seed + 5.0) * 6.0));
    vec2 bid = floor(uv * grid);
    float blk = step(1.0 - I * (0.05 + 0.22 * (wStut + wStat + wDrop) + 0.06 * wRgb), hash21(bid + tick * 0.37 + seed));
    uv += vec2(hash21(bid + 3.1) - 0.5, (hash21(bid + 9.7) - 0.5) * 0.35) * 0.11 * blk * I;

    // --- stutter: briefly re-sample an earlier horizontal slice
    float hold = wStut * step(0.6, hash11(tick * 1.3 + seed)) * step(0.35, I);
    uv.y = mix(uv.y, fract(uv.y + 0.07 * (hash11(tick + seed) - 0.5) * 4.0), hold * 0.6);

    uv = clamp(uv, vec2(0.0), vec2(1.0));

    // --- RGB channel split
    float ang = hash11(seed + 11.0) * 6.2831853;
    float split = (0.003 + 0.011 * (0.4 + wRgb)) * I;
    vec2 dir = vec2(cos(ang), sin(ang) * 0.3);
    col = vec3(
      tex(uv + dir * split).r,
      tex(uv).g,
      tex(uv - dir * split).b
    );

    // --- dropout: signal-loss bands darken (never the whole frame)
    float dropBand = step(0.55, hash21(vec2(floor(uv.y * 18.0), tick + seed)));
    col *= 1.0 - 0.55 * wDrop * dropBand * I;

    // --- static: noise over some rows only
    float rowMask = step(0.6, hash21(vec2(floor(uv.y * uResolution.y * 0.5), tick + seed * 2.0)));
    float n = hash21(floor(uv * uResolution) + tick);
    col = mix(col, vec3(n), 0.45 * wStat * rowMask * I);

    // --- colour inversion flicker: a band, plus one whole-frame tick at high intensity
    float flick = step(0.55, hash11(tick * 1.7 + seed));
    float y0 = hash11(seed + tick);
    float inBand = step(y0, outTexCoord.y) * step(outTexCoord.y, y0 + 0.08 + 0.2 * I);
    float whole = step(0.9, hash11(tick * 2.3 + seed * 3.0)) * step(0.8, I);
    float inv = (1.0 - uSafe) * step(0.3, I) * max(flick * inBand * (0.4 + wStat + wDrop), whole * 0.8);
    col = mix(col, vec3(1.0) - col, clamp(inv, 0.0, 1.0));
  } else {
    col = tex(uv);
  }

  // --- always-on subtle CRT: faint scanlines + vignette
  float row = floor(outTexCoord.y * uResolution.y);
  col *= 1.0 - uCrt * 0.045 * mod(row, 2.0);
  vec2 q = outTexCoord - 0.5;
  col *= 1.0 - uCrt * 0.16 * smoothstep(0.35, 0.85, dot(q, q) * 2.0);

  gl_FragColor = vec4(col, 1.0);
}/**
 * OWNER: input/audio/glitch engineer.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Phaser 3.90 PostFX pipeline: RGB split, scanline wobble / horizontal tearing, block displacement, colour
 * inversion flicker and an always-on faint scanline/CRT layer (see glitch.frag). Registered once in main.js postBoot
 * under the name GLITCH_PIPELINE_KEY. RunScene attaches it with `GlitchPipeline.install(this)` in create().
 * Driven by EVT.GLITCH_START / GLITCH_END on game.events (payload kind/intensity/durationMs; the seed-bound block
 * pattern comes from the hex tag in the event id, e.g. 'g12-3fa9'). The glitch also expires on its own after
 * durationMs (+ a small grace), so a pause mid-glitch can never leave the screen glitched.
 * Reduced effects: when settings.screenShake === false the shader runs in "safe" mode (weaker, no inversion).
 * WebGL only.
 */
import Phaser from 'phaser';
import fragShader from './glitch.frag?raw';
import { EVT } from '../events.js';
import { REG } from '../constants.js';

export const GLITCH_PIPELINE_KEY = 'GlitchPipeline';

/** Shader kind ids (must match glitch.frag). */
const KIND_ID = { rgbSplit: 1, scanlineWobble: 2, stutter: 3, dropout: 4, static: 5 };

/** @param {string} id @returns {number} 0..1 seed-bound pattern value from the event id. */
export function patternFromId(id) {
  const s = String(id || '');
  const m = /-([0-9a-f]{1,8})$/i.exec(s);
  if (m) return (parseInt(m[1], 16) % 65536) / 65536;
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619) >>> 0;
  return (h % 65536) / 65536;
}

export class GlitchPipeline extends Phaser.Renderer.WebGL.Pipelines.PostFXPipeline {
  /** @param {Phaser.Game} game */
  constructor(game) {
    super({ game, name: GLITCH_PIPELINE_KEY, fragShader });
    /** 0..1 current glitch strength (read by the shader; normally driven by the active event). */
    this.intensity = 0;
    /** Always-on CRT layer strength 0..1. */
    this.crt = 1;
    /** @type {{id:string, kind:number, seed:number, start:number, duration:number, intensity:number}|null} */
    this.active = null;
    /** Force reduced-effects mode regardless of settings (tests / debug). */
    this.forceSafe = false;
  }

  /** Begin a glitch from an event payload. @param {import('../events.js').GlitchStartPayload} p @returns {void} */
  startEvent(p) {
    if (!p) return;
    this.active = {
      id: p.id,
      kind: KIND_ID[p.kind] || 1,
      seed: patternFromId(p.id),
      start: this.game.loop.time,
      duration: Math.max(30, Number(p.durationMs) || 100),
      intensity: Math.max(0, Math.min(1, p.intensity == null ? 0.7 : p.intensity)),
    };
  }

  /** @param {string} [id] @returns {void} */
  endEvent(id) {
    if (!this.active || (id && this.active.id !== id)) return;
    this.active = null;
    this.intensity = 0;
  }

  /** @returns {void} sets shader uniforms each frame. */
  onPreRender() {
    const a = this.active;
    let kind = 0;
    let seed = 0;
    if (a) {
      const el = this.game.loop.time - a.start;
      if (el > a.duration + 60) {
        this.active = null;
        this.intensity = 0;
      } else {
        const attack = Math.min(1, el / 16);
        const release = el > a.duration ? Math.max(0, 1 - (el - a.duration) / 60) : 1;
        // slight deterministic flicker inside the event so it is not a flat wash
        const flick = 0.82 + 0.18 * Math.sin(el * 0.11 + a.seed * 40);
        this.intensity = a.intensity * attack * release * flick;
        kind = a.kind;
        seed = a.seed;
      }
    }
    let safe = this.forceSafe ? 1 : 0;
    try {
      const s = this.game.registry.get(REG.SETTINGS);
      if (s && s.screenShake === false) safe = 1;
    } catch (e) { /* no registry yet */ }
    this.set1f('uIntensity', this.active || this.intensity > 0 ? this.intensity : 0);
    this.set1f('uTime', this.game.loop.time / 1000);
    this.set1f('uKind', kind);
    this.set1f('uSeed', seed);
    this.set1f('uSafe', safe);
    this.set1f('uCrt', this.crt);
    if (!this._bg) {
      const c = this.game.config.backgroundColor;
      this._bg = c && c.red !== undefined ? [c.redGL, c.greenGL, c.blueGL] : [0.02, 0.024, 0.06];
    }
    this.set3f('uBg', this._bg[0], this._bg[1], this._bg[2]);
  }

  /**
   * Attach the pipeline to the scene's main camera and subscribe to EVT.GLITCH_START / GLITCH_END on game.events
   * (sets intensity for the event's duration). Unsubscribes automatically on scene shutdown.
   * @param {Phaser.Scene} scene
   * @returns {() => void} uninstall function.
   */
  static install(scene) {
    const cam = scene.cameras.main;
    const game = scene.game;
    cam.setPostPipeline(GLITCH_PIPELINE_KEY);
    const find = () => {
      const r = cam.getPostPipeline(GLITCH_PIPELINE_KEY);
      return Array.isArray(r) ? r[0] : r;
    };
    const onStart = (p) => { const pl = find(); if (pl && pl.startEvent) pl.startEvent(p); };
    const onEnd = (p) => { const pl = find(); if (pl && pl.endEvent) pl.endEvent(p && p.id); };
    game.events.on(EVT.GLITCH_START, onStart);
    game.events.on(EVT.GLITCH_END, onEnd);
    let done = false;
    const uninstall = () => {
      if (done) return;
      done = true;
      game.events.off(EVT.GLITCH_START, onStart);
      game.events.off(EVT.GLITCH_END, onEnd);
      scene.events.off('shutdown', uninstall);
      scene.events.off('destroy', uninstall);
      try { cam.resetPostPipeline(); } catch (e) { /* camera already destroyed */ }
    };
    scene.events.once('shutdown', uninstall);
    scene.events.once('destroy', uninstall);
    return uninstall;
  }
}/**
 * OWNER: core-logic engineer. NO Phaser imports. Never throws; falls back to memory when
 * IndexedDB is unavailable (Jest, private windows), like SaveStore.
 *
 * Local ghost library (issue #56). Per course (exact seed + biome mask) it keeps at most
 * five ghost roles: Latest, Best and Favorites A/B/C. A run that holds several roles is one
 * tape and one ghost. Tapes are deleted only when no role on any course references them.
 *
 * Course-archive capacity (the repeatable upgrade) is NOT enforced yet: its starting size,
 * price and eviction rules are open owner decisions. Nothing here uploads anything; Brain
 * Bazaar publishing (#58) will be a separate, explicit action.
 */
import { GHOST_TAPE_FORMAT, GHOST_TAPE_VERSION, GHOST_PHYSICS_VERSION, courseKey } from './GhostTape.js';
import { KODIAK_VERSION } from '../Kodiaks.js';
import { SIM_TICK_HZ } from '../SimClock.js';

export const GHOST_DB = 'bitstream-ghosts';
export const GHOST_DB_VERSION = 1;
export const FAVORITE_SLOTS = 3;
export const MAX_GHOSTS_PER_COURSE = 2 + FAVORITE_SLOTS;
const IDB_TIMEOUT_MS = 2500;

const req2p = (req) => new Promise((resolve, reject) => {
  req.onsuccess = () => resolve(req.result);
  req.onerror = () => reject(req.error || new Error('idb request failed'));
});

/** A tape this build can draw: right format, version, tick rate and physics. A Kodiak run from another bear ruleset (contact crashed before v3) would not replay. */
export function tapeCompatible(tape) {
  return Boolean(tape && tape.format === GHOST_TAPE_FORMAT && tape.version === GHOST_TAPE_VERSION &&
    tape.simTickHz === SIM_TICK_HZ && tape.physicsVersion === GHOST_PHYSICS_VERSION && typeof tape.trace === 'string' &&
    (tape.kodiaksOn !== true || tape.kodiakVersion === KODIAK_VERSION));
}

function emptyCourse(key, tape) {
  return { key, seed: tape.seed, biomeMask: tape.biomeMask || 0, latest: null, best: null, bestDistanceM: -1,
    favorites: Array(FAVORITE_SLOTS).fill(null), lastPlayedAt: 0 };
}

/** Role -> runId pairs of a course, merged per run: [{runId, roles:['best','latest']}], at most five. */
export function courseGhostRuns(course) {
  if (!course) return [];
  const byRun = new Map();
  const add = (role, runId) => { if (runId) byRun.set(runId, [...(byRun.get(runId) || []), role]); };
  add('best', course.best);
  add('latest', course.latest);
  course.favorites.forEach((runId, i) => add(`fav${i}`, runId));
  return [...byRun].map(([runId, roles]) => ({ runId, roles })).slice(0, MAX_GHOSTS_PER_COURSE);
}

export class GhostLibrary {
  constructor() {
    /** @type {Map<string, object>} course entries (small; always in memory) */
    this.courses = new Map();
    /** @type {Map<string, object>} tapes: memory backend, or a read cache over IndexedDB */
    this.tapes = new Map();
    this.backend = 'memory';
    this._db = null;
  }

  /** Open IndexedDB and load course entries. Never rejects. */
  async init() {
    try {
      const idb = globalThis.indexedDB;
      if (!idb) return;
      const db = await new Promise((resolve, reject) => {
        const timer = setTimeout(() => reject(new Error('idb open timeout')), IDB_TIMEOUT_MS);
        const req = idb.open(GHOST_DB, GHOST_DB_VERSION);
        req.onupgradeneeded = () => {
          const d = req.result;
          if (!d.objectStoreNames.contains('courses')) d.createObjectStore('courses', { keyPath: 'key' });
          if (!d.objectStoreNames.contains('tapes')) d.createObjectStore('tapes', { keyPath: 'runId' });
        };
        req.onsuccess = () => { clearTimeout(timer); resolve(req.result); };
        req.onerror = () => { clearTimeout(timer); reject(req.error); };
        req.onblocked = () => { clearTimeout(timer); reject(new Error('idb blocked')); };
      });
      const all = await req2p(db.transaction('courses', 'readonly').objectStore('courses').getAll());
      for (const c of all || []) if (c && typeof c.key === 'string') this.courses.set(c.key, c);
      this._db = db;
      this.backend = 'idb';
    } catch {
      this._db = null;
      this.backend = 'memory';
    }
  }

  course(seed, biomeMask = 0) { return this.courses.get(courseKey(seed, biomeMask)) || null; }

  /**
   * Store a finished run's tape and update its course's Latest and Best.
   * Best is the furthest distance; a tie keeps the earlier run.
   * @returns {Promise<object>} the updated course entry
   */
  async saveRun(tape) {
    if (!tape?.runId || tape.mode === 'gym') return null;
    const key = courseKey(tape.seed, tape.biomeMask);
    const course = { ...(this.courses.get(key) || emptyCourse(key, tape)) };
    course.favorites = [...course.favorites];
    const before = new Set(courseGhostRuns(course).map((g) => g.runId));
    course.latest = tape.runId;
    // Terrain/ruleset revisions are distinct courses for competitive Best
    // purposes even when their seed and mask are identical. An old-terrain
    // distance must not permanently outrank every fresh-terrain tape.
    const oldBest = course.best ? await this.getTape(course.best) : null;
    const staleBest = Number.isSafeInteger(tape.simRevision) && tape.simRevision > 0 &&
      course.best && oldBest?.simRevision !== tape.simRevision;
    if (staleBest || tape.distanceM > course.bestDistanceM) {
      course.best = tape.runId;
      course.bestDistanceM = tape.distanceM;
    }
    course.lastPlayedAt = tape.endedAt || Date.now();
    await this._putTape(tape);
    await this._putCourse(course);
    const after = new Set(courseGhostRuns(course).map((g) => g.runId));
    for (const runId of before) {
      if (after.has(runId)) continue;
      // Preserve displaced legacy/other-revision tapes for explicit replay
      // tools and later historical analysis, even though current gameplay
      // no longer draws them. Normal same-revision role GC is unchanged.
      const previous = await this.getTape(runId);
      if (Number.isSafeInteger(tape.simRevision) && tape.simRevision > 0 &&
          previous && previous.simRevision !== tape.simRevision) continue;
      await this._collect(runId);
    }
    return course;
  }

  /** Pin (or with runId null, clear) Favorite slot 0..2 of a course. */
  async setFavorite(seed, biomeMask, slot, runId) {
    const key = courseKey(seed, biomeMask);
    const old = this.courses.get(key);
    if (!old || slot < 0 || slot >= FAVORITE_SLOTS) return null;
    if (runId && !(await this.getTape(runId))) return null;
    const course = { ...old, favorites: [...old.favorites] };
    const dropped = course.favorites[slot];
    course.favorites[slot] = runId || null;
    await this._putCourse(course);
    if (dropped && !courseGhostRuns(course).some((g) => g.runId === dropped)) await this._collect(dropped);
    return course;
  }

  /** Per-course on/off switch for one ghost role (used for Favorites A/B/C). */
  async setShow(seed, biomeMask, role, on) {
    const old = this.courses.get(courseKey(seed, biomeMask));
    if (!old) return null;
    const course = { ...old, show: { ...(old.show || {}), [role]: on !== false } };
    await this._putCourse(course);
    return course;
  }

  /**
   * Ghosts to draw on a course: deduped runs with their roles, filtered by `show`
   * (role -> boolean) and the course's own `show` switches; a run shows if any of its roles is shown.
   * Compatible tapes only. `simRevision` is a display-only current-terrain
   * gate; leave `tapeCompatible` and direct getTape/manifest replay unchanged.
   * When present, an invalid revision refuses all display candidates.
   * Omitting the fourth argument preserves the legacy tool/library API.
   */
  async ghostsFor(seed, biomeMask = 0, show = {}, { simRevision } = {}) {
    const out = [];
    if (simRevision !== undefined && (!Number.isSafeInteger(simRevision) || simRevision < 1)) return out;
    const course = this.course(seed, biomeMask);
    // A role shows when both the player's global switch (`show`) and the course's own switch allow it.
    const visible = (r) => show[r] !== false && course?.show?.[r] !== false;
    for (const g of courseGhostRuns(course)) {
      if (!g.roles.some(visible)) continue;
      const tape = await this.getTape(g.runId);
      // No silent legacy->current simulation identity inference. Old or
      // unstamped trace poses can float/clip on the revised terrain.
      if (tapeCompatible(tape) && (simRevision === undefined || tape.simRevision === simRevision)) {
        out.push({ ...g, tape });
      }
    }
    return out;
  }

  async getTape(runId) {
    if (this.tapes.has(runId)) return this.tapes.get(runId);
    if (!this._db) return null;
    try {
      const tape = await req2p(this._db.transaction('tapes', 'readonly').objectStore('tapes').get(runId));
      if (tape) this.tapes.set(runId, tape);
      return tape || null;
    } catch { return null; }
  }

  /** Delete a tape no course still references. */
  async _collect(runId) {
    for (const c of this.courses.values()) if (courseGhostRuns(c).some((g) => g.runId === runId)) return;
    this.tapes.delete(runId);
    if (this._db) {
      try { await req2p(this._db.transaction('tapes', 'readwrite').objectStore('tapes').delete(runId)); } catch { /* best effort */ }
    }
  }

  async _putTape(tape) {
    this.tapes.set(tape.runId, tape);
    if (this._db) {
      try { await req2p(this._db.transaction('tapes', 'readwrite').objectStore('tapes').put(tape)); } catch { /* quota: memory keeps the session */ }
    }
  }

  async _putCourse(course) {
    this.courses.set(course.key, course);
    if (this._db) {
      try { await req2p(this._db.transaction('courses', 'readwrite').objectStore('courses').put(course)); } catch { /* quota */ }
    }
  }
}/**
 * OWNER: core-logic engineer. NO Phaser imports.
 *
 * Ghost tapes (issue #56). A tape is the canonical record of one run:
 *  - header: course (seed + biome mask), mode, loadout, initial pose, RNG stream state and
 *    engine versions; anything a replay needs that is not reconstructible from the seed;
 *  - inputs: the normalized pad fed to each fixed simulation tick (#59), stored only on the
 *    ticks where it changes;
 *  - checkpoints: exact sled state about once a second, to detect a replay that desyncs;
 *  - trace: the pose every TRACE_EVERY ticks, which is what a visual ghost draws. Drawing
 *    from the trace means five ghosts never run five live physics simulations.
 * Tapes live beside the RunRecord, never inside it: run-ledger hashes are untouched.
 */
import { SIM_TICK_HZ } from '../SimClock.js';
import { RUN_RANDOM_VERSION } from '../RunRandom.js';
import { captureCausalState } from '../replay/fingerprintCapture.js';
import { fingerprintState } from '../replay/fingerprint.js';

export const GHOST_TAPE_FORMAT = 'bb-ghost-tape';
/** Bump when the header, input bits or trace layout change. */
export const GHOST_TAPE_VERSION = 1;
/** Bump when a physics/tuning change would make old input tapes replay differently. */
export const GHOST_PHYSICS_VERSION = 1;
export const CHECKPOINT_EVERY = 120; // ticks: 1 s at 120 Hz
export const TRACE_EVERY = 4; // ticks: 30 Hz, a whole number of 30/60/120 Hz frames

// Pad fields carried in the input bits, in bit order. Never reorder: append and bump the version.
const BOOL_FIELDS = ['push', 'variableHop', 'noAutoNudge', 'divebomb', 'corkscrew', 'tuck', 'brakeHeld',
  'hop', 'reset', 'airBrake', 'parachute', 'pause'];
const EDGE_FIELDS = ['hop', 'reset', 'pause', 'airBrake', 'parachute', 'confirm'];
const HELI_SHIFT = BOOL_FIELDS.length + EDGE_FIELDS.length; // 2 bits: 0 none, 1 = +1, 2 = -1
/** Mask of the one-shot edge bits (12-17) in a row's bits. */
const EDGE_BITS_MASK = ((1 << EDGE_FIELDS.length) - 1) << BOOL_FIELDS.length;
/**
 * Recorder behavior for edge rows (Replay Contract C11/R-5): 'every-tick' = a row is written on every tick whose bits
 * carry an edge bit. Tapes without this header field were recorded by the older deduping recorder ('legacy').
 */
const GHOST_EDGE_ROWS = 'every-tick';

/** Identity of a course: the exact seed plus the selected biome mask. */
export function courseKey(seed, biomeMask = 0) {
  return `${String(seed)}|${((Number(biomeMask) || 0) >>> 0).toString(16).padStart(8, '0')}`;
}

/** Analog tilt rounded to 1/127 so it survives storage exactly (keyboard -1/0/1 is unchanged). */
export function quantizeTilt(tilt) {
  const t = Number.isFinite(tilt) ? Math.max(-1, Math.min(1, tilt)) : 0;
  const q = Math.round(t * 127) / 127;
  return q === 0 ? 0 : q; // Replay Contract C4: never store -0 (JSON writes it as 0, structured clone keeps it)
}

/** Pack a normalized tick pad into [bits, tilt127]. */
export function encodePad(pad) {
  let bits = 0;
  BOOL_FIELDS.forEach((k, i) => { if (pad[k]) bits |= 1 << i; });
  EDGE_FIELDS.forEach((k, i) => { if (pad.pressed?.[k]) bits |= 1 << (BOOL_FIELDS.length + i); });
  if (pad.heli > 0) bits |= 1 << HELI_SHIFT; else if (pad.heli < 0) bits |= 2 << HELI_SHIFT;
  const tilt127 = Math.round(quantizeTilt(pad.tilt) * 127);
  return [bits >>> 0, tilt127 === 0 ? 0 : tilt127];
}

/** Inverse of encodePad. `brake` is re-derived per tick by RunScene from brakeHeld/airBrake. */
export function decodePad(bits, tilt127) {
  const pad = { tilt: tilt127 / 127, pressed: {}, lastSource: 'tape' };
  BOOL_FIELDS.forEach((k, i) => { pad[k] = (bits & (1 << i)) !== 0; });
  EDGE_FIELDS.forEach((k, i) => { pad.pressed[k] = (bits & (1 << (BOOL_FIELDS.length + i))) !== 0; });
  const h = (bits >>> HELI_SHIFT) & 3;
  pad.heli = h === 1 ? 1 : h === 2 ? -1 : 0;
  pad.brake = pad.brakeHeld;
  return pad;
}

/** Exact sled state for a checkpoint. Doubles round-trip JSON exactly, so equality is exact. */
export function sledState(scene) {
  const b = scene.sled.body;
  return [b.position.x, b.position.y, b.angle, b.velocity.x, b.velocity.y, b.angularVelocity,
    Math.round(scene.score?.getTotal?.() ?? 0)];
}

function toBase64(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(s);
}
function fromBase64(str) {
  const s = atob(str);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

/** Records one run. RunScene calls input() before and afterTick() after each simulation tick. */
export class GhostRecorder {
  /** @param {object} header everything but versions; see RunScene._ghostHeader() */
  constructor(header) {
    this.header = { format: GHOST_TAPE_FORMAT, version: GHOST_TAPE_VERSION, physicsVersion: GHOST_PHYSICS_VERSION,
      simTickHz: SIM_TICK_HZ, runRandomVersion: RUN_RANDOM_VERSION, edgeRows: GHOST_EDGE_ROWS, ...header };
    this.inputs = []; // [tickDelta, bits, tilt127] on change
    this.checkpoints = []; // [tick, ...sledState]
    this.trace = []; // x, y, angle every TRACE_EVERY ticks from tick TRACE_EVERY
    // Replay Contract v1 (#118): one fingerprint per checkpoint tick, `{tick, combined, subsystems}`. Kept beside the tape,
    // never inside it, so the tape format and the exact sled checkpoints above are unchanged. A capture failure is
    // recorded here, never thrown: a fingerprint is a diagnostic and must not break a run.
    this.fingerprints = [];
    /** Uncapped count of failed captures. The evidence path (#164) MUST treat a recorder with a non-zero count as having
     *  incomplete fingerprints (a gap in `fingerprints`), never as a clean run. */
    this.fingerprintErrorCount = 0;
    /** The first few failures (tick, message), for diagnosis. */
    this.fingerprintErrors = [];
    this._last = null;
    this._lastTick = 0;
    this.lastTick = 0;
  }

  input(tick, pad) {
    const [bits, tilt] = encodePad(pad);
    // An edge applies only on its exact tick on replay, so a repeated edge row must still be written (C11).
    if (this._last && this._last[0] === bits && this._last[1] === tilt && !(bits & EDGE_BITS_MASK)) return;
    this.inputs.push([tick - this._lastTick, bits, tilt]);
    this._lastTick = tick;
    this._last = [bits, tilt];
  }

  afterTick(tick, scene) {
    this.lastTick = tick;
    if (tick % TRACE_EVERY === 0) {
      const b = scene.sled.body;
      this.trace.push(b.position.x, b.position.y, b.angle);
    }
    if (tick % CHECKPOINT_EVERY === 0) {
      this.checkpoints.push([tick, ...sledState(scene)]);
      this._fingerprint(tick, scene);
    }
  }

  /** Subsystem frame fingerprint at a checkpoint tick (read-only capture; runs once per CHECKPOINT_EVERY ticks). */
  _fingerprint(tick, scene) {
    try {
      const f = fingerprintState(captureCausalState(scene));
      this.fingerprints.push({ tick, combined: f.combined, subsystems: f.subsystems });
    } catch (e) {
      const message = String(e && e.message);
      if (this.fingerprintErrorCount++ === 0 && typeof console !== 'undefined') {
        console.warn(`GhostRecorder: frame fingerprint capture failed at tick ${tick} (${message}); further failures are only counted`);
      }
      if (this.fingerprintErrors.length < 8) this.fingerprintErrors.push({ tick, message });
    }
  }

  /** @param {{runId:string, distanceM:number, score:number, cause?:string, endedAt?:number}} result */
  finish(result) {
    return {
      ...this.header,
      runId: result.runId, distanceM: result.distanceM, score: result.score, cause: result.cause || 'crash',
      endedAt: result.endedAt ?? Date.now(), endTick: this.lastTick,
      inputs: this.inputs, checkpoints: this.checkpoints,
      trace: toBase64(new Uint8Array(new Float32Array(this.trace).buffer)),
    };
  }
}

/** Float32 [x, y, angle, ...] of a finished tape. */
export function decodeTrace(tape) {
  try {
    const bytes = fromBase64(tape.trace || '');
    return new Float32Array(bytes.buffer, bytes.byteOffset, Math.floor(bytes.length / 4));
  } catch { return new Float32Array(0); }
}

/** Pose at simulation tick `tick` (interpolated between trace samples), or null past the run's end. */
export function tracePose(trace, tick) {
  const n = Math.floor(trace.length / 3);
  if (!n || !(tick >= 0)) return null;
  const f = tick / TRACE_EVERY - 1; // sample i holds tick (i + 1) * TRACE_EVERY
  if (f > n - 1) return null;
  const i = Math.max(0, Math.floor(f)), j = Math.min(n - 1, i + 1), u = Math.max(0, Math.min(1, f - i));
  let da = trace[j * 3 + 2] - trace[i * 3 + 2];
  if (da > Math.PI) da -= 2 * Math.PI; else if (da < -Math.PI) da += 2 * Math.PI;
  return { x: trace[i * 3] + (trace[j * 3] - trace[i * 3]) * u, y: trace[i * 3 + 1] + (trace[j * 3 + 1] - trace[i * 3 + 1]) * u,
    angle: trace[i * 3 + 2] + da * u };
}

/**
 * Feeds a tape's inputs back, tick by tick, and checks its checkpoints. Replaces live input
 * in RunScene for replay verification (and, later, a replay viewer).
 */
export class TapePlayer {
  constructor(tape) {
    this.tape = tape;
    this._i = 0;
    this._nextAt = tape.inputs.length ? tape.inputs[0][0] : Infinity;
    this._pad = decodePad(0, 0);
    this._changeTick = -1;
    this._cp = 0;
    /** First failing checkpoint, or null while the replay matches. */
    this.desync = null;
    this.checked = 0;
  }

  /** Pad for simulation tick `tick` (ticks must be requested in increasing order). */
  padAt(tick) {
    const rows = this.tape.inputs;
    while (this._i < rows.length && tick >= this._nextAt) {
      this._pad = decodePad(rows[this._i][1], rows[this._i][2]);
      this._changeTick = this._nextAt;
      this._i++;
      this._nextAt = this._i < rows.length ? this._nextAt + rows[this._i][0] : Infinity;
    }
    // A one-shot edge belongs to exactly the tick it was recorded on.
    return this._changeTick === tick ? this._pad : { ...this._pad, pressed: {} };
  }

  /** Compare the live sled against a checkpoint recorded at this tick. */
  check(tick, scene) {
    const cps = this.tape.checkpoints;
    while (this._cp < cps.length && cps[this._cp][0] < tick) this._cp++;
    if (this._cp >= cps.length || cps[this._cp][0] !== tick) return;
    const want = cps[this._cp].slice(1), got = sledState(scene);
    this.checked++;
    if (!this.desync && want.some((v, k) => v !== got[k])) this.desync = { tick, want, got };
  }
}/**
 * Optional adaptive-backing playback for four-family / twelve-biome packs.
 *
 * All SIX original stems remain scheduled by StemMusicDirector. Three shared
 * buses receive replacements for bass, airborne drums and ONE featured source.
 * The melody continues to use the existing sampled voice:<biome> assets.
 * Variant files can be authored with ANY instrument renderer, not just GM.
 *
 * Sessions are bounded to two per family (current and transitioning).
 * A failed or slow variant fetch never mutes its original source.
 */
import { HOME_BIOME } from './BiomeVoices.js';
import { canonicalBiomeId } from '../../data/biomeAliases.js';

export const ADAPTIVE_FAMILIES = Object.freeze(['bass', 'drums', 'featured', 'guitar', 'piano', 'other']);
const FADE_SECONDS = 0.20;

const clamped = (v, low, high) => Math.max(low, Math.min(high, v));

export class AdaptiveBiomeRouter {
	constructor(ctx, mixer, loadBuffer) {
		this.ctx = ctx;
		this.mixer = mixer;
		this.loadBuffer = loadBuffer;
		this.pack = null;
		this.clockStart = null;
		this.biome = HOME_BIOME;
		this.airborne = false;
		// Standalone router callers retain the legacy enabled default.
		// StemMusicDirector sets the actual user toggle on every track.
		this.enabled = true;
		this.speed = null;
		this.channels = new Map();
		this.retired = new Set();
		this.generation = 0;
		this.timers = new Set();
		this.attached = false;
	}

	_attach() {
		if (this.attached) return;
		for (const role of ADAPTIVE_FAMILIES) {
			this.mixer.addSource('adaptive:' + role, { gain: 1 });
		}
		this.attached = true;
	}

	configure(pack, clockStart, { biome = this.biome, airborne = this.airborne } = {}) {
		this.reset();
		this.pack = pack?.adaptive ? pack : null;
		this.clockStart = Number.isFinite(clockStart) ? clockStart : null;
		this.biome = canonicalBiomeId(biome);
		this.airborne = !!airborne;
		if (!this.pack) return;
		this._attach();
		for (const role of ADAPTIVE_FAMILIES) {
			this.channels.set(role, { current: null, pending: null });
		}
		this._applySpeed();
		this._reconcile();
	}

	setEnabled(on) {
		this.enabled = on === true;
		this._reconcile();
	}

	setBiome(id) {
		this.biome = canonicalBiomeId(id) || HOME_BIOME;
		this._reconcile();
	}

	setAirborne(value) {
		this.airborne = !!value;
		this._reconcile();
	}

	setSpeed(value) {
		this.speed = Math.max(0, Number(value) || 0);
		this._applySpeed();
	}

	_applySpeed() {
		if (!this.pack || this.speed === null) return;
		const speedGain = clamped(0.28 + this.speed / 820, 0.28, 1.35);
		this.mixer.setGain('adaptive:bass', speedGain, { motion: true, time: .16 });
	}

	_original(role) {
		return role === 'featured' ? this.pack.adaptive.featuredStem : role;
	}

	_variant(role) {
		const variants = this.pack?.adaptive?.variants?.[role];
		if (!this.enabled || !variants || this.biome === HOME_BIOME) return null;
		// The featured part already has its own adaptive bus. Don't
		// simultaneously route that same source into a second named bus.
		if (['guitar','piano','other'].includes(role) &&
			this.pack.adaptive.featuredStem===role) return null;
		if (role === 'drums' && !this.airborne) return null;
		return variants[this.biome] ? this.biome : null;
	}

	_setOriginal(role, value) {
		const name = this._original(role);
		if (name) this.mixer.setMixGain(name, value, { time: FADE_SECONDS });
		// In adaptive mode the original drum bed is full-strength on the ground.
		// Unlike the legacy no-adaptive behavior, airborne means a real alternate.
	}

	_makeSession(role, biome) {
		const input = this.mixer.addSource('adaptive:' + role, { gain: 1 });
		if (!input) throw new Error('Adaptive bus missing: ' + role);
		const gain = this.ctx.createGain();
		gain.gain.value = 0;
		gain.connect(input);
		return { role, biome, gain, scheduled: new Set(), inflight: new Set(),
			failures: new Map(), nodes: new Set(), generation: ++this.generation,
			live: false, dead: false };
	}

	_ramp(session, value, at = this.ctx.currentTime) {
		const p = session.gain.gain;
		p.cancelScheduledValues(at);
		p.setValueAtTime(p.value, at);
		p.linearRampToValueAtTime(value, at + FADE_SECONDS);
	}

	_retire(session, { immediate = false } = {}) {
		if (!session || (session.dead && !immediate)) return;
		session.dead = true;
		this.retired.delete(session);
		if (immediate) {
			for (const node of session.nodes) {
				try { node.stop(); } catch {}
				try { node.disconnect(); } catch {}
			}
			session.nodes.clear();
			try { session.gain.disconnect(); } catch {}
			return;
		}
		// Only one retiring session per family. Rapid switches reclaim the
		// oldest voice rather than leaking a mixer/audio-source fleet.
		for (const old of [...this.retired]) {
			if (old.role === session.role) this._retire(old, { immediate: true });
		}
		this._ramp(session, 0);
		const until = this.ctx.currentTime + FADE_SECONDS + .02;
		for (const node of session.nodes) {
			try { node.stop(until); } catch {}
		}
		this.retired.add(session);
		const timer = setTimeout(() => {
			this.timers.delete(timer);
			this._retire(session, { immediate: true });
		}, Math.ceil((FADE_SECONDS + .08) * 1000));
		this.timers.add(timer);
	}

	_reconcile() {
		if (!this.pack) return;
		for (const role of ADAPTIVE_FAMILIES) {
			const channel = this.channels.get(role);
			const wanted = this._variant(role);
			if (!wanted) {
				// Do NOT restart the source fade on every 75ms audio pump.
				// A repeated setMixGain(1) would cancel the in-progress
				// WebAudio automation and keep the original half-muted.
				if (channel.current || channel.pending) this._setOriginal(role, 1);
				this._retire(channel.current);
				this._retire(channel.pending, { immediate: true });
				channel.current = null;
				channel.pending = null;
				continue;
			}
			if (channel.current?.biome === wanted) {
				if (channel.pending) this._retire(channel.pending, { immediate: true });
				channel.pending = null;
				continue;
			}
			if (channel.pending?.biome === wanted) continue;
			// At most current and pending for each family (plus short fades).
			if (channel.pending) this._retire(channel.pending, { immediate: true });
			for (const old of [...this.retired]) {
				if (old.role === role) this._retire(old, { immediate: true });
			}
			channel.pending = this._makeSession(role, wanted);
		}
	}

	_promote(role, session) {
		const channel = this.channels.get(role);
		if (!channel || channel.pending !== session || session.dead) return;
		const previous = channel.current;
		channel.current = session;
		channel.pending = null;
		session.live = true;
		this._ramp(session, 1);
		this._setOriginal(role, 0);
		if (previous) this._retire(previous);
	}

	_schedule(session, index, buffer) {
		if (session.dead || !this.pack || this.clockStart === null ||
			session.scheduled.has(index)) return;
		const seg = this.pack.segments[index];
		const desired = this.clockStart + seg.startFrame / this.pack.sampleRate;
		const duration = seg.frames / this.pack.sampleRate;
		const now = this.ctx.currentTime;
		const start = Math.max(desired, now + .025);
		const offset = start - desired;
		// Lossy codec padding of a few milliseconds is normal, but an
		// incorrectly segmented replacement must never be mistaken for
		// a complete synced chunk.
		if (!buffer || !Number.isFinite(buffer.duration) ||
			buffer.duration + .04 < duration) {
			throw new Error('Adaptive asset shorter than source music segment');
		}
		const playLength = Math.min(duration - offset, buffer.duration - offset);
		if (!Number.isFinite(playLength) || playLength < .01) {
			throw new Error('Adaptive asset shorter than the required song-clock segment');
		}
		const node = this.ctx.createBufferSource();
		node.buffer = buffer;
		node.connect(session.gain);
		node.onended = () => {
			session.nodes.delete(node);
			try { node.disconnect(); } catch {}
		};
		try {
			node.start(start, offset, playLength);
			session.nodes.add(node);
			session.scheduled.add(index);
			// Never fade away the original before audio is actually schedulable.
			// Do not fade out the original a quarter-second before a
			// future song segment or first track chunk has even begun.
			if (!session.live && start <= now + .05) this._promote(session.role, session);
		} catch (error) {
			try { node.disconnect(); } catch {}
			throw error;
		}
	}

	pump() {
		if (!this.pack || this.clockStart === null || this.ctx.state !== 'running') return;
		this._reconcile();
		const now = this.ctx.currentTime;
		for (const role of ADAPTIVE_FAMILIES) {
			const pending = this.channels.get(role)?.pending;
			if (pending && !pending.dead && pending.scheduled.size) {
				for (const index of pending.scheduled) {
					const seg = this.pack.segments[index];
					const begin = this.clockStart + seg.startFrame / this.pack.sampleRate;
					const end = begin + seg.frames / this.pack.sampleRate;
					if (begin <= now + .05 && end > now + .025) {
						this._promote(role, pending);
						break;
					}
				}
			}
		}
		for (const role of ADAPTIVE_FAMILIES) {
			const channel = this.channels.get(role);
			if (channel.current && !channel.current.dead) {
				const covered = [...channel.current.scheduled].some(index => {
					const seg = this.pack.segments[index];
					const begin = this.clockStart + seg.startFrame / this.pack.sampleRate;
					const end = begin + seg.frames / this.pack.sampleRate;
					return begin <= now + .05 && end > now + .025;
				});
				if (!covered) {
					this._setOriginal(role, 1);
					this._ramp(channel.current, 0);
					channel.current.live = false;
					if (!channel.pending) channel.pending = channel.current;
					else this._retire(channel.current);
					channel.current = null;
				}
			}
			for (const session of [channel.current, channel.pending]) {
				if (!session || session.dead) continue;
				const paths = this.pack.adaptive.variants[role]?.[session.biome];
				if (!paths) continue;
				for (let index = 0; index < this.pack.segments.length; index++) {
					const seg = this.pack.segments[index];
					const start = this.clockStart + seg.startFrame / this.pack.sampleRate;
					const end = start + seg.frames / this.pack.sampleRate;
					if (end < now + .025 || start > now + 8) continue;
					if (session.scheduled.has(index) || session.inflight.has(index)) continue;
					if ((session.failures.get(index)?.retryAt ?? 0) > now) continue;
					session.inflight.add(index);
					Promise.resolve().then(() => {
						if (session.dead || !this.pack) return null;
						return this.loadBuffer(index, paths[index]);
					})
						.then(buffer => {
							if (buffer && !session.dead && this.pack) {
								session.failures.delete(index);
								this._schedule(session, index, buffer);
							}
						})
						.catch(error => {
							this.lastError = String(error);
							const attempts = (session.failures.get(index)?.attempts ?? 0) + 1;
							// Bound missing-asset request rates; a 404 must never be
							// retried on every 75-ms audio pump.
							session.failures.set(index, {
								attempts, retryAt: this.ctx.currentTime +
									Math.min(16, Math.pow(2, attempts)),
							});
							const channel = this.channels.get(role);
							// Prefetch failure for a LATER chunk must not
							// interrupt the current healthy music chunk.
							// The coverage guard restores the original at
							// the boundary if that file remains unavailable.
							const failingSegment = this.pack?.segments[index];
							const nearFailure = !failingSegment ||
								this.clockStart + failingSegment.startFrame /
								this.pack.sampleRate <= this.ctx.currentTime + .12;
							if (!nearFailure) return;
							// A failed destination must not leave the PREVIOUS
							// mountain instrument playing indefinitely.
							if (!session.dead && channel?.current === session) {
								this._setOriginal(role, 1);
								this._ramp(session, 0);
								session.live = false;
								channel.current = null;
								if (channel.pending) this._retire(channel.pending, { immediate: true });
								channel.pending = session;
							} else if (!session.dead && channel?.pending === session &&
								channel.current) {
								this._setOriginal(role, 1);
								this._retire(channel.current);
								channel.current = null;
							}
						})
						.finally(() => session.inflight.delete(index));
				}
			}
		}
	}

	reset() {
		for (const channel of this.channels.values()) {
			this._retire(channel.current, { immediate: true });
			this._retire(channel.pending, { immediate: true });
		}
		for (const old of this.retired) this._retire(old, { immediate: true });
		for (const timer of this.timers) clearTimeout(timer);
		this.timers.clear();
		this.retired.clear();
		if (this.pack) {
			for (const role of ADAPTIVE_FAMILIES) this._setOriginal(role, 1);
		}
		this.channels.clear();
		if (this.pack && this.speed !== null) {
			this.mixer.setGain('bass', 1, { motion: true, time: .16 });
		}
		this.pack = null;
		this.clockStart = null;
	}

	destroy() {
		this.reset();
	}
}/** Public-release beat metadata, deliberately FAIL CLOSED.
 * No song is marked verified until actual pulse phase and regular quarter-note
 * division pass TWO independent checks including an accountable listening/spot
 * check. Detected attack timestamps are not musical beat proof.
 * Later verified entries must carry SHA-256 of the ORIGINAL source performance.
 */
import {BEAT_GRID_FORMAT} from './BeatGridTiming.js';
const ids=[
	'local-one-more-run-bitstream-bluffs',
	'WRBGQUqD54U',
	'FYImnz5-hXs',
	'FEsxYVStla4',
];
export const RELEASE_BEAT_GRIDS=Object.freeze(Object.fromEntries(ids.map(id=>[id,
	Object.freeze({format:BEAT_GRID_FORMAT,trackId:id,status:'unverified',
		review:Object.freeze({humanSpotCheck:'pending',independentCheck:'pending'}),
		confidence:0,sections:Object.freeze([]),
		note:'Beat phase is not established. BPM/score onsets are not beat evidence.'})])));/** Verified source-performance quarter-note pulse lookup. No physics, no clock ownership.
 * Beat grid frame positions are authored/validated against unaltered OGG performance.
 * BPM-only and guessed percussion subdivisions NEVER authorize a Gym release.
 */
export const BEAT_GRID_FORMAT='bitstream-beat-grid-v1';
export const MIN_GRID_CONFIDENCE=.9;
const isInt=n=>Number.isSafeInteger(n)&&n>=0;
const fail=reason=>Object.freeze({trusted:false,reason});

/** Returns trusted, normalized beat-grid metadata or a typed rejection.
 * - section pulseFrames are strictly ordered quarter-note grid positions;
 * - invalid sections and section boundaries are never guessed across;
 * - source sample rate + length MUST match the actual music pack.
 * Proof metadata is supplied by an independent verification step, never by detection itself.
 */
export function validateBeatGrid(raw,pack){
	if(!raw||raw.format!==BEAT_GRID_FORMAT||raw.trackId!==pack?.id)
		return fail('missing-or-mismatched-grid');
	if(raw.status!=='verified'||raw.review?.humanSpotCheck!=='passed'||
		raw.review?.independentCheck!=='passed'||
		!Number.isFinite(raw.confidence)||raw.confidence<MIN_GRID_CONFIDENCE)
		return fail('unverified-beat-grid');
	if(raw.sourceSampleRate!==pack.sampleRate||raw.sourceFrameCount!==pack.frameCount)
		return fail('different-recording');
	if(typeof raw.sourceSha256!=='string'||!/^[0-9a-f]{64}$/.test(raw.sourceSha256)||
		typeof raw.version!=='string'||!raw.version.trim())
		return fail('missing-source-provenance');
	if(!Array.isArray(raw.sections)||!raw.sections.length)return fail('missing-sections');
	let cursor=0,approvedCount=0;
	const sections=[];
	for(const section of raw.sections){
		if(!isInt(section.startFrame)||!isInt(section.endFrame)||
			section.startFrame!==cursor||section.endFrame<=section.startFrame||
			section.endFrame>pack.frameCount)return fail('invalid-section-range');
		const safe=section.status==='verified'&&
			Number.isFinite(section.confidence)&&section.confidence>=MIN_GRID_CONFIDENCE;
		if(!['verified','uncertain'].includes(section.status))return fail('invalid-section-status');
		const beats=section.pulseFrames;
		if(!Array.isArray(beats)||!beats.every(isInt))return fail('invalid-pulses');
		let prev=-1;
		for(const frame of beats){
			if(frame<=prev||frame<section.startFrame||frame>=section.endFrame)
				return fail('invalid-pulse-order');
			prev=frame;
		}
		if(!safe&&beats.length)return fail('uncertain-section-must-not-have-pulses');
		if(safe){
			if(beats.length<2)return fail('underspecified-beats');
			for(let i=1;i<beats.length;i++){
				const interval=(beats[i]-beats[i-1])/pack.sampleRate;
				if(interval<.24||interval>2.01)return fail('implausible-quarter-note-interval');
			}
			approvedCount+=beats.length;
		}
		sections.push(Object.freeze({startFrame:section.startFrame,
			endFrame:section.endFrame,confidence:section.confidence,
			status:section.status,pulseFrames:Object.freeze(beats.slice())}));
		cursor=section.endFrame;
	}
	if(cursor!==pack.frameCount||approvedCount<2)return fail('incomplete-or-empty-grid');
	return Object.freeze({trusted:true,trackId:raw.trackId,version:raw.version,
		confidence:raw.confidence,sourceSha256:raw.sourceSha256,
		sourceSampleRate:raw.sourceSampleRate,sourceFrameCount:raw.sourceFrameCount,
		sections:Object.freeze(sections)});
}

/** Conservative next quarter-note pulse by frame, with no extrapolation. */
export function nextVerifiedPulse(validated,positionSeconds,maxWaitMs=300){
	if(!validated?.trusted)return fail(validated?.reason||'missing-grid');
	if(!Number.isFinite(positionSeconds)||positionSeconds<0)return fail('invalid-position');
	const frames=validated.sourceFrameCount;
	const currentFrame=Math.ceil(positionSeconds*validated.sourceSampleRate-1e-7);
	if(currentFrame>=frames)return fail('end-of-recording');
	const section=validated.sections.find(s=>currentFrame>=s.startFrame&&currentFrame<s.endFrame);
	if(!section||section.status!=='verified')return fail('uncertain-section');
	const pulses=section.pulseFrames;
	let lo=0,hi=pulses.length;
	while(lo<hi){const mid=(lo+hi)>>1;
		if(pulses[mid]<currentFrame)lo=mid+1;else hi=mid;
	}
	if(lo===pulses.length)return fail('no-verified-pulse-in-section');
	const beatFrame=pulses[lo],beatSeconds=beatFrame/validated.sourceSampleRate;
	const waitMs=Math.max(0,(beatSeconds-positionSeconds)*1000);
	if(waitMs>Math.min(300,Math.max(0,Number(maxWaitMs)||0))+1e-6)
		return fail('no-imminent-pulse');
	return Object.freeze({trusted:true,beatFrame,beatSeconds,waitMs,
		trackId:validated.trackId,gridVersion:validated.version,
		confidence:Math.min(validated.confidence,section.confidence)});
}/**
 * Cheap, shared, send-only convolution room. Two spaces crossfade at a time.
 * Each source chooses how much enters this bus; the clean mix remains separate.
 */
import { ImpulseBank, ROOM_PRESETS } from './ImpulseBank.js';
import { HOME_BIOME } from './BiomeVoices.js';

export class BiomeSpaceBus {
	constructor(ctx, destination, { quality = 'standard', wet = 0.22 } = {}) {
		this.ctx = ctx;
		this.destination = destination;
		this.quality = quality;
		this.wet = wet;
		this.bank = new ImpulseBank(ctx, 3);
		this.input = ctx.createGain();
		this.active = null;
		this.paths = new Set();
		this.timers = new Set();
		this.selectBiome(HOME_BIOME, 0.01);
	}

	selectBiome(id, fade = 0.55) {
		const next = Object.prototype.hasOwnProperty.call(ROOM_PRESETS, id) ? id : HOME_BIOME;
		if (this.active?.id === next) return false;
		const c = this.ctx;
		const convolver = c.createConvolver();
		convolver.normalize = true;
		convolver.buffer = this.bank.get(next, this.quality);
		const gain = c.createGain();
		gain.gain.value = 0;
		this.input.connect(convolver);
		convolver.connect(gain);
		gain.connect(this.destination);
		const route = { id: next, convolver, gain };
		this.paths.add(route);
		const start = c.currentTime, seconds = Math.min(2, Math.max(0.01, fade));
		gain.gain.setValueAtTime(0, start);
		gain.gain.linearRampToValueAtTime(this.wet, start + seconds);
		if (this.active) {
			const old = this.active;
			old.gain.gain.cancelScheduledValues(start);
			old.gain.gain.setValueAtTime(old.gain.gain.value, start);
			old.gain.gain.linearRampToValueAtTime(0, start + seconds);
			const timer = setTimeout(() => {
				this.timers.delete(timer);
				this.paths.delete(old);
				try { this.input.disconnect(old.convolver); } catch {}
				try { old.convolver.disconnect(); old.gain.disconnect(); } catch {}
			}, (seconds + Math.min(4, ROOM_PRESETS[old.id].seconds)) * 1000);
			this.timers.add(timer);
		}
		this.active = route;
		// Fast biome changes must not accumulate unbounded live convolvers.
		if (this.paths.size > 3) {
			for (const obsolete of [...this.paths].slice(0, this.paths.size - 3)) {
				this.paths.delete(obsolete);
				try { this.input.disconnect(obsolete.convolver); } catch {}
				try { obsolete.convolver.disconnect(); obsolete.gain.disconnect(); } catch {}
			}
		}
		return true;
	}

	destroy() {
		for (const t of this.timers) clearTimeout(t);
		this.timers.clear();
		for (const route of this.paths) {
			try { this.input.disconnect(route.convolver); route.convolver.disconnect(); route.gain.disconnect(); } catch {}
		}
		this.paths.clear();
		this.input.disconnect();
		this.bank.clear();
	}
}/**
 * The 12 mountain voice *identities*.
 * The sounds themselves are offline-rendered and supplied as optional pack sources.
 * Each voice is a first-class route: "voice:<id>".
 *
 * These art-direction presets are proposals, not hard-coded sound synthesis.
 */
import { canonicalBiomeId } from '../../data/biomeAliases.js';

export const HOME_BIOME = 'bitstream-bluffs';
export const BIOME_VOICES = Object.freeze({
	'bitstream-bluffs': { instrument: 'glitch-chip vocoder', environment: 'virtual-arcade', family: 'speech-synth' },
	'debutmont': { instrument: 'warm SNES woodwind', environment: 'winter-cabin', family: 'sampled-wavetable' },
	'garbage-dump-glacier': { instrument: 'corrupt speech chip', environment: 'drain-tunnel', family: 'glitch-vocoder' },
	'pyramid-peak': { instrument: 'FM brass', environment: 'stone-chamber', family: 'fm' },
	'underwater-mountain': { instrument: 'liquid glass harmonica', environment: 'submerged', family: 'formant' },
	'crystal-cavern': { instrument: 'crystal bell choir', environment: 'crystal-cavern', family: 'fm' },
	'space-mountain': { instrument: 'expressive theremin', environment: 'cosmic-void', family: 'continuous' },
	'candy-cane-canyon': { instrument: 'candy hyperpop', environment: 'plastic-reflections', family: 'chip-hyperpop' },
	'sky-jellyfish-mountain': { instrument: 'vowel choir', environment: 'floating-cathedral', family: 'vocal-formant' },
	'steampunk-slopes': { instrument: 'mechanical calliope', environment: 'iron-factory', family: 'organ' },
	'micro-mountain': { instrument: 'toybox music-box', environment: 'tiny-wooden-room', family: 'plucked' },
	'vertigo-vents': { instrument: 'distorted pipe organ', environment: 'volcanic-chamber', family: 'organ' },
});

export const BIOME_IDS = Object.freeze(Object.keys(BIOME_VOICES));
export function voiceSourceForBiome(rawId) {
	const id = canonicalBiomeId(rawId); // a stale legacy-id request (issue #65) resolves to its canonical id
	const selected = Object.prototype.hasOwnProperty.call(BIOME_VOICES, id) ? id : HOME_BIOME;
	return 'voice:' + selected;
}/** Music-only BSOD threat processor.
 * Live guitar/piano/Other original stems pass through here. Far = dry,
 * approach = dark/unstable/pitch-preserving filtered distortion+tremolo.
 * There is no timer, pursuit model, source replay or music note guessing.
 */
export const BSOD_THREAT_STEMS = Object.freeze(['guitar','piano','other']);
const clamp01 = n => Number.isFinite(n) ? Math.max(0,Math.min(1,n)) : 0;

export function bsodThreatParameters(proximity01) {
	const proximity=clamp01(proximity01);
	// A small safe zone prevents distant hiss, then a slow onset and strong
	// final warning. Unapproved musical intensity: audit/listen before release.
	const u=clamp01((proximity-.08)/.92);
	const ramp=u*u*(3-2*u);
	return { proximity, blend: .84*ramp, cutoffHz: 16000-13800*ramp,
		tremoloHz: 3+10*ramp, tremoloDepth: .47*ramp,
		// Mid-stage parallel paths partially cancel in some real stems.
		// A gentle bell-shaped gain restores a stable approach, not an end boost.
		midMakeup: 1+.20*Math.sin(Math.PI*ramp) };
}

function distortionCurve() {
	const curve=new Float32Array(2048);
	// Calibrated makeup normalization: original unnormalized waveshaping
	// amplified the real 12-stem source set by 5.6-11.4 dB; full unity
	// small-signal normalization reduced some stems by 7 dB. This makeup
	// balances both without returning to the original loudness spike.
	const drive=4.7,denom=3.0;
	for(let i=0;i<curve.length;i++){
		const x=i*2/(curve.length-1)-1;
		curve[i]=Math.tanh(drive*x)/denom;
	}
	return curve;
}

const smooth=(param,value,now,seconds=.14)=>{
	param.cancelScheduledValues(now);
	param.setTargetAtTime(value,now,seconds);
};
/** A static chain with dynamic AudioParams: no DSP graph churn per frame.
 * Routed AFTER ordinary biome FX, so current song clock and replacements are
 * untouched. Only original accompaniment buses have this optional chain.
 */
export function createBsodThreatProcessor(ctx,output) {
	const input=ctx.createGain();
	const dry=ctx.createGain(),wet=ctx.createGain();
	const shaper=ctx.createWaveShaper();
	const mixGain=ctx.createGain();
	const filter=ctx.createBiquadFilter();
	const trem=ctx.createGain(),osc=ctx.createOscillator();
	const mod=ctx.createGain();
	dry.gain.value=1;
	wet.gain.value=0;
	mixGain.gain.value=1;
	trem.gain.value=1;
	filter.type='lowpass';
	filter.frequency.value=16000;
	filter.Q.value=.7;
	shaper.curve=distortionCurve();
	shaper.oversample='2x';
	osc.type='sine';
	osc.frequency.value=3;
	mod.gain.value=0;
	input.connect(dry);dry.connect(mixGain);
	input.connect(shaper);shaper.connect(filter);
	filter.connect(trem);trem.connect(wet);wet.connect(mixGain);
	mixGain.connect(output);
	osc.connect(mod);mod.connect(trem.gain);
	osc.start();
	let last=0,destroyed=false;
	return {
		input,dry,wet,filter,shaper,trem,osc,mod,mixGain,
		get danger(){return last;},
		setDanger(value) {
			if(destroyed)return false;
			const p=bsodThreatParameters(value);
			if(Math.abs(p.proximity-last)<.025 &&
				!(p.proximity===0 && last!==0))return false;
			last=p.proximity;
			const t=ctx.currentTime;
			smooth(dry.gain,1-p.blend,t);
			smooth(wet.gain,p.blend,t);
			smooth(mixGain.gain,p.midMakeup,t,.2);
			smooth(filter.frequency,p.cutoffHz,t,.2);
			smooth(osc.frequency,p.tremoloHz,t,.2);
			smooth(trem.gain,1-p.tremoloDepth/2,t);
			smooth(mod.gain,p.tremoloDepth/2,t);
			return true;
		},
		destroy(){
			if(destroyed)return;
			destroyed=true;
			try{osc.stop();}catch{}
			for(const node of [input,dry,wet,shaper,filter,trem,osc,mod,mixGain]){
				try{node.disconnect();}catch{}
			}
		},
	};
}/** Word timing belongs to the recorded performance, never the prompt text. */
export function normalizeCaptions(raw, durationSeconds) {
	if (!raw || raw.format !== 'bitstream-lyrics-v1' || !Array.isArray(raw.words) ||
		raw.words.length > 50000) throw new Error('Invalid lyric timeline');
	let previousStart = -1;
	const words = raw.words.map((word) => {
		if (!word || !Number.isFinite(word.start) || !Number.isFinite(word.end) ||
			word.start < 0 || word.end <= word.start || word.end > durationSeconds + 0.5 ||
			word.start < previousStart || typeof word.text !== 'string' ||
			word.text.length < 1 || word.text.length > 100) throw new Error('Invalid lyric word timing');
		previousStart = word.start;
		return { start: word.start, end: word.end, text: word.text };
	});
	return { words };
}

export function captionAt(words, positionSeconds) {
	if (!Array.isArray(words) || !Number.isFinite(positionSeconds)) return null;
	// Find the last word that starts before the current musical position.
	let lo = 0, hi = words.length;
	while (lo < hi) {
		const mid = (lo + hi) >>> 1;
		if (words[mid].start <= positionSeconds) lo = mid + 1;
		else hi = mid;
	}
	const word = words[lo - 1];
	return word && positionSeconds < word.end ? word : null;
}

export function nextBeatTime(transportStart, positionSeconds, bpm, beatOffset = 0) {
	if (!Number.isFinite(bpm) || bpm <= 0 || bpm > 350) return transportStart + Math.max(0, positionSeconds);
	const interval = 60 / bpm;
	const beats = Math.ceil((positionSeconds - beatOffset) / interval);
	return transportStart + Math.max(positionSeconds, beatOffset + Math.max(0, beats) * interval);
}/** Independent non-destructive processing presets for source-stem playback.
 * They are active regardless of Dynamic Orchestra ON/OFF.
 * OFF disables re-performed replacement stems, NOT filtering, ambience,
 * distortion, tremolo, EQ, speed controls or other processing of originals.
 * The separately synthesized biome-specific lead stays active in both modes.
 */
import { BIOME_IDS, HOME_BIOME } from './BiomeVoices.js';

const filter = (id, mode, frequency, Q = 0.7) => ({ type:'filter', id, mode, frequency, Q });
const distortion = amount => ({ type:'distortion', id:'color', amount });
const tremolo = (rate, depth) => ({ type:'tremolo', id:'motion', rate, depth });
const delay = (time, wet) => ({ type:'delay', id:'echo', time, wet, feedback:0.15 });

export function melodyPreset(biome) {
	switch (biome) {
		case 'debutmont': return [filter('warm','lowpass',3200),tremolo(3.6,.12)];
		case 'garbage-dump-glacier': return [distortion(.31),filter('edge','highpass',420),tremolo(11,.24)];
		case 'pyramid-peak': return [distortion(.12),filter('brass','lowpass',4100,1.1)];
		case 'underwater-mountain': return [filter('submerged','lowpass',1400),delay(.22,.23)];
		case 'crystal-cavern': return [filter('crystal','highpass',650),delay(.29,.32)];
		case 'space-mountain': return [tremolo(5.8,.16),delay(.37,.27)];
		case 'candy-cane-canyon': return [distortion(.19),tremolo(9,.24)];
		case 'sky-jellyfish-mountain': return [filter('sky','lowpass',2600),tremolo(1.2,.21)];
		case 'steampunk-slopes': return [distortion(.17),tremolo(8.5,.23)];
		case 'micro-mountain': return [filter('tiny','highpass',1000),tremolo(10.5,.18)];
		case 'vertigo-vents': return [distortion(.44),filter('volcanic','lowpass',2900)];
		case HOME_BIOME: return [filter('arcade','lowpass',7000)];
		default: return [filter('arcade','lowpass',7000)];
	}
}

export function orchestraPreset(biome, stem) {
	if (!['bass','drums','guitar','piano','other'].includes(stem))
		throw new Error('Cannot apply orchestra effects to an unknown stem');
	if (!BIOME_IDS.includes(biome)) return [];
	const edge = {
		'debutmont': 4200,'garbage-dump-glacier':6200,
		'pyramid-peak': 5100,'underwater-mountain':1800,
		'crystal-cavern':6800,'space-mountain':5700,
		'candy-cane-canyon':6900,'sky-jellyfish-mountain':3200,
		'steampunk-slopes':3800,'micro-mountain':7100,
		'vertigo-vents':3700,
	}[biome] || 5000;
	if (stem==='bass') {
		return [filter('shaped-bass','lowpass',Math.min(3000,edge*.55)),
			...(biome==='garbage-dump-glacier'||biome==='vertigo-vents'?[distortion(.18)]:[])];
	}
	if (stem==='drums') {
		return [filter('drum-color','lowpass',edge),
			...(biome==='steampunk-slopes'||biome==='micro-mountain'?[tremolo(6,.17)]:[])];
	}
	// Never replace, retrigger, rescore or move source note attacks here.
	// These are purely effects on the *original* waveform and apply
	// even when the separate re-performance playback is switched OFF.
	return [filter('accompaniment-color','lowpass',edge),
		...(biome==='crystal-cavern'||biome==='space-mountain'?[delay(.19,.17)]:[]),
		...(biome==='garbage-dump-glacier'||biome==='vertigo-vents'?[distortion(.2)]:[])];
}/** Single-transport fatal-death musical recovery. Research/review build.
 * CRITICAL: the 0.5s pulse is a SYNTHETIC UNVERIFIED TEST GRID, NOT a
 * verified beat for any shipped soundtrack. This module NEVER writes to
 * RELEASE_BEAT_GRIDS or publishes its pulses to the Gym's trusted API.
 *
 * Only four short one-shot excerpts from the ORIGINAL decoded drum stem
 * are scheduled; no second song transport, alternate decoder, or seek.
 * All normal stems continue to advance silently behind their own separate
 * recovery gains. Original stem and adaptive orchestra routing are intact.
 */
import {VINYL_SCRATCH_SECONDS} from './TurntableScratch.js';
import {SYNTHETIC_BEAT_SECONDS,SYNTHETIC_BEATS_PER_MEASURE} from './SyntheticMeterTiming.js';

export const FATAL_SYNTHETIC_BEAT_SECONDS=SYNTHETIC_BEAT_SECONDS;
export const FATAL_SILENT_BEATS=2;
export const FATAL_DRUM_BEATS=4;
export const FATAL_ACCENT_SECONDS=.14;

export function planFatalCountIn(startAudioTime,{
  beatSeconds=FATAL_SYNTHETIC_BEAT_SECONDS,
  silentBeats=FATAL_SILENT_BEATS,
  scratchSeconds=VINYL_SCRATCH_SECONDS,
  timingKind='synthetic-unverified',
}={}){
  if(!Number.isFinite(startAudioTime)||startAudioTime<0||
    !Number.isFinite(beatSeconds)||beatSeconds<.25||beatSeconds>1.1||
    !Number.isInteger(silentBeats)||silentBeats<1||silentBeats>3||
    !Number.isFinite(scratchSeconds)||scratchSeconds<0||scratchSeconds>.5)
    return null;
  const silenceStart=startAudioTime+scratchSeconds;
  const drumsStart=silenceStart+silentBeats*beatSeconds;
  const beatOnsets=Object.freeze(Array.from({length:FATAL_DRUM_BEATS},
    (_,i)=>drumsStart+i*beatSeconds));
  // Never relabel an experimental proposal as a verified source grid.
  if(timingKind!=='synthetic-unverified')return null;
  const bandAt=drumsStart+FATAL_DRUM_BEATS*beatSeconds;
  // Label the four artificial count-in beats 1..4: the count-in's first
  // drum accent is its synthetic downbeat. This is NOT a downbeat found in
  // the original OGG or necessarily aligned with the song-wide fake meter.
  const beatInMeasure=Object.freeze(Array.from({length:FATAL_DRUM_BEATS},
    (_,i)=>i%SYNTHETIC_BEATS_PER_MEASURE+1));
  const measureStartOnsets=Object.freeze(beatOnsets.filter((_,i)=>
    beatInMeasure[i]===1));
  return Object.freeze({startAudioTime,silenceStart,drumsStart,
    bandAt,beatOnsets,beatSeconds,silentBeats,
    beatInMeasure,measureStartOnsets,
    beatsPerMeasure:SYNTHETIC_BEATS_PER_MEASURE,
    measureSeconds:SYNTHETIC_BEATS_PER_MEASURE*beatSeconds,
    syntheticMeterOrigin:'count-in-first-drum',
    timingKind,verified:false});
}

/** Pick one short rising transient from ORIGINAL decoded OGG drum audio.
 * This is deliberately NOT a note detector nor a quarter-note verifier.
 * Each selected 140ms excerpt is repeated 4x, one isolated accent/slot.
 * We refuse very quiet/missing stems rather than inventing a drum recording.
 */
export function findOriginalDrumAccent(d){
  const pack=d?.pack,cache=d?.cache;
  if(!pack?.segments?.length||!cache?.get||!Number.isFinite(pack.sampleRate))return null;
  const pos=Math.max(0,d.ctx?.currentTime-d.clockStart||0);
  const candidates=[];
  for(let i=0;i<pack.segments.length;i++){
    const buffer=cache.get(`${i}/drums`);
    if(!buffer?.getChannelData||buffer.length<.3*buffer.sampleRate||
      !Number.isFinite(buffer.sampleRate)||buffer.sampleRate<8000)continue;
    const seg=pack.segments[i],delta=Math.abs((seg.startFrame+seg.frames/2)/pack.sampleRate-pos);
    candidates.push({i,buffer,delta});
  }
  candidates.sort((a,b)=>a.delta-b.delta);
  for(const {i,buffer} of candidates.slice(0,4)){
    const length=buffer.length,rate=buffer.sampleRate;
    const channels=[];
    for(let c=0;c<Math.min(2,buffer.numberOfChannels);c++)
      channels.push(buffer.getChannelData(c));
    if(!channels.length)continue;
    const hop=Math.max(1,Math.round(rate*.021));
    const window=Math.max(1,Math.round(rate*.014));
    const end=length-Math.round(FATAL_ACCENT_SECONDS*rate)-1;
    let best=-Infinity,bestAt=0;
    for(let at=hop*2;at<end;at+=hop){
      let current=0,prior=0;
      const step=Math.max(1,Math.round(window/20));
      for(let j=0;j<window;j+=step){
        for(const data of channels){
          current+=Math.abs(data[at+j]||0);
          prior+=Math.abs(data[at-window+j]||0);
        }
      }
      // Prefer a clearly audible rising attack, not a steady cymbal bed.
      const score=current+.6*Math.max(0,current-prior);
      if(score>best){best=score;bestAt=at;}
    }
    const volume=best/(Math.ceil(window/Math.max(1,Math.round(window/20)))*channels.length);
    if(!(volume>.015))continue;
    const offsetSeconds=Math.max(0,(bestAt-Math.round(rate*.006))/rate);
    return Object.freeze({buffer,segmentIndex:i,offsetSeconds,
      excerptSeconds:Math.min(FATAL_ACCENT_SECONDS,buffer.duration-offsetSeconds-.001),
      source:'original-decoded-ogg-drums',onsetScore:volume});
  }
  return null;
}

export class FatalCrashCountIn {
  /** Warm one or two *original* drum-only segments when a source has an
   * almost silent introduction. This uses the director's existing
   * verified music-pack URL, same fetch/cache/decode method and token,
   * never a second audio player. No new file is imported or modified.
   */
  async prepare(d){
    const token=d?._token;
    if(!d?.pack||!d.pack.segments?.length||
      findOriginalDrumAccent(d)||typeof d._fetchSource!=='function')return false;
    const info={track:d.track,pack:d.pack,base:d.packBase};
    for(let i=1;i<Math.min(4,d.pack.segments.length);i++){
      if(token!==d._token||d.disposed||this.ctx!==d.ctx)return false;
      try{await d._fetchSource(info,i,'drums',token)}catch{return false;}
      if(findOriginalDrumAccent(d))return true;
    }
    return false;
  }

  constructor(ctx,mixer,scratch){
    this.ctx=ctx;this.mixer=mixer;this.scratch=scratch;
    this.active=null;this.sources=[];this.nodes=[];this.generation=0;
  }

  cancel(){
    ++this.generation;
    // Also covers an exception halfway through a four-source schedule:
    // never leave source gates stuck silent because active was not set yet.
    if(this.mixer?.recoveryPlan)this.mixer.cancelRecoveryPlan();
    if(this.active)this.scratch?.cancel();
    for(const src of this.sources){try{src.stop(this.ctx.currentTime)}catch{}}
    for(const node of this.nodes){try{node.disconnect()}catch{}}
    this.sources=[];this.nodes=[];
    this.active=null;
  }

  /** Start on a real fatal CRASH, not on RUN_END. Returns a readonly
   * report with its timing-evidence disclaimer and exact source identity.
   * If drum source is silent/missing, leave ordinary continuous music alone.
   */
  start(d,{beatSeconds=FATAL_SYNTHETIC_BEAT_SECONDS,
    timingKind='synthetic-unverified',silentBeats=FATAL_SILENT_BEATS,
    runId=null}={}){
    const c=this.ctx;
    if(!c||c.state!=='running'||!d?.started||d.transportPaused||
      d.ctx!==c||!d.pack||!d.track||d._loading||
      !d.activeNodes?.size||d.clockStart===null||
      this.mixer!==d.mixer)return null;
    const drum=findOriginalDrumAccent(d);
    if(!drum||drum.excerptSeconds<.06)return null;
    const plan=planFatalCountIn(c.currentTime,{beatSeconds,silentBeats,timingKind});
    if(!plan)return null;
    this.cancel();
    try{
      // The recovery gate itself may throw after partially changing its
      // AudioParams. A failure must unwind the original band immediately,
      // not leave it inadvertently muted during Game Over.
      if(!this.mixer.setRecoveryPlan(plan)){
        this.cancel();
        return null;
      }
      // One short scratch on existing music bus, then exact silence.
      this.scratch?.play('pause');
      const token=this.generation;
      for(let i=0;i<plan.beatOnsets.length;i++){
        const due=plan.beatOnsets[i];
        const source=c.createBufferSource();
        source.buffer=drum.buffer;
        const envelope=c.createGain();
        envelope.gain.setValueAtTime(0,due);
        envelope.gain.linearRampToValueAtTime(.95,due+.009);
        envelope.gain.setValueAtTime(.8,due+Math.min(.07,drum.excerptSeconds*.6));
        envelope.gain.linearRampToValueAtTime(0,due+drum.excerptSeconds);
        source.connect(envelope);
        envelope.connect(this.mixer.countInInput);
        this.sources.push(source);
        this.nodes.push(source,envelope);
        source.start(due,drum.offsetSeconds,drum.excerptSeconds);
        source.stop(due+drum.excerptSeconds+.004);
      }
      this.active=Object.freeze({...plan,runId,
        trackId:d.track.id,transportToken:d._token,clockStart:d.clockStart,
        sourceSegment:drum.segmentIndex,sourceOffset:drum.offsetSeconds,
        drumSource:drum.source,scheduledDrumAccents:FATAL_DRUM_BEATS,
        generation:token});
      return this.snapshot();
    }catch{
      this.cancel();return null;
    }
  }

  snapshot(){
    const a=this.active;
    if(!a)return Object.freeze({active:false,stage:'idle'});
    const t=this.ctx?.currentTime??Infinity;
    const stage=t>=a.bandAt?'full-band':
      t>=a.drumsStart?'four-drum-count-in':
      t>=a.silenceStart?'silent-beats':'vinyl-scratch';
    return Object.freeze({...a,active:t<a.bandAt+.055,stage,
      clockBasis:'AudioContext.currentTime'});
  }

  destroy(){this.cancel();this.ctx=null;this.mixer=null;this.scratch=null;}
}/**
 * Twelve deterministic *designed* impulse responses, one per musical mountain.
 * These are placeholders for recorded/licensed room captures and special IRs.
 * The vacuum of Space Mountain deliberately sounds unreal; it is not physical acoustics.
 */
import { HOME_BIOME } from './BiomeVoices.js';

export const ROOM_PRESETS = Object.freeze({
	'bitstream-bluffs':       { seconds: 0.72, decay: 0.27, damping: 0.26, echoMs: 48, glitch: true },
	'debutmont':              { seconds: 0.48, decay: 0.18, damping: 0.15, echoMs: 32 },
	'garbage-dump-glacier':   { seconds: 1.45, decay: 0.55, damping: 0.65, echoMs: 113 },
	'pyramid-peak':          { seconds: 2.2, decay: 0.85, damping: 0.29, echoMs: 170 },
	'underwater-mountain':   { seconds: 1.4, decay: 0.52, damping: 0.93, echoMs: 95 },
	'crystal-cavern':        { seconds: 2.8, decay: 1.1, damping: 0.1, echoMs: 153 },
	'space-mountain':        { seconds: 3.0, decay: 1.15, damping: 0.43, echoMs: 240 },
	'candy-cane-canyon':     { seconds: 0.65, decay: 0.26, damping: 0.17, echoMs: 35 },
	'sky-jellyfish-mountain':{ seconds: 3.5, decay: 1.45, damping: 0.42, echoMs: 133 },
	'steampunk-slopes':      { seconds: 1.55, decay: 0.57, damping: 0.33, echoMs: 80 },
	'micro-mountain':        { seconds: 0.24, decay: 0.085, damping: 0.24, echoMs: 14 },
	'vertigo-vents':         { seconds: 2.65, decay: 1.04, damping: 0.72, echoMs: 195 },
});

function seedFor(text) {
	let h = 2166136261;
	for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 16777619);
	return h >>> 0;
}

/** Build an offline-in-memory impulse. O(seconds * sampleRate), no model inference. */
export function createBiomeImpulse(ctx, id = HOME_BIOME, quality = 'standard') {
	const name = Object.prototype.hasOwnProperty.call(ROOM_PRESETS, id) ? id : HOME_BIOME;
	const preset = ROOM_PRESETS[name];
	const sr = ctx.sampleRate;
	const seconds = quality === 'mobile' ? Math.min(1.15, preset.seconds) : preset.seconds;
	const length = Math.max(128, Math.ceil(sr * seconds));
	const audio = ctx.createBuffer(2, length, sr);
	for (let ch = 0; ch < 2; ch++) {
		const samples = audio.getChannelData(ch);
		let rng = seedFor(name + ':' + ch), smooth = 0;
		for (let i = 0; i < length; i++) {
			rng = (Math.imul(rng, 1664525) + 1013904223) >>> 0;
			const random = rng / 0xffffffff * 2 - 1;
			// Simple spectrum envelope and exponentially-decaying room tail.
			smooth = smooth * preset.damping + random * (1 - preset.damping);
			const decay = Math.exp(-i / (sr * preset.decay));
			const quantized = preset.glitch ? Math.floor(i / 32) * 32 : i;
			samples[i] = 0.06 * decay * (preset.glitch ? Math.sin(quantized * 0.022) * smooth : smooth);
		}
		// Distinct reflections, different left/right times for a stereo image.
		const echoFrames = sr * preset.echoMs / 1000;
		for (let k = 0; k < 5; k++) {
			const where = Math.round((k + 1) * echoFrames * (ch ? 1.043 : 1));
			if (where < length) samples[where] += Math.pow(0.55, k + 1) * (ch ? -0.4 : 0.4);
		}
		samples[0] += 0.65;
	}
	return audio;
}

export class ImpulseBank {
	constructor(ctx, capacity = 3) {
		this.ctx = ctx;
		this.capacity = Math.max(1, Math.min(6, capacity));
		this.cache = new Map();
	}
	get(id, quality = 'standard') {
		const key = String(id) + '/' + quality;
		if (this.cache.has(key)) {
			const buffer = this.cache.get(key);
			this.cache.delete(key);
			this.cache.set(key, buffer);
			return buffer;
		}
		const buffer = createBiomeImpulse(this.ctx, id, quality);
		this.cache.set(key, buffer);
		if (this.cache.size > this.capacity) this.cache.delete(this.cache.keys().next().value);
		return buffer;
	}
	clear() { this.cache.clear(); }
}/** Music Lab's IN-MEMORY ONLY source-stem audition levels.
 * Never persisted and never applied to the shared main-game director.
 * "melody" refers to the selected biome voice (not original vocals).
 */
export const LAB_STEMS=Object.freeze(['drums','bass','guitar','piano','other','melody']);
export const LAB_MIX_PRESETS=Object.freeze([
  Object.freeze({id:'mute',label:'MUTE',gain:0}),
  Object.freeze({id:'duck',label:'DUCK',gain:.35}),
  Object.freeze({id:'normal',label:'NORMAL',gain:1}),
  Object.freeze({id:'boost',label:'BOOST',gain:1.35}),
]);
export const LAB_MAX_GAIN=1.35;

export function freshLabLevels(){
  return Object.fromEntries(LAB_STEMS.map(role=>[role,1]));
}

export function labGainFor(role,levels,solo='ALL'){
  if(!LAB_STEMS.includes(role))return 0;
  if(solo!=='ALL'&&solo!==role.toUpperCase())return 0;
  const value=levels?.[role];
  return Number.isFinite(value)?Math.max(0,Math.min(LAB_MAX_GAIN,value)):1;
}

/** Mutates ONLY the caller's isolated director; never shared AudioSynth. */
export function applyLabStemLevels(lab,levels,solo='ALL'){
  if(!lab?.mixer||!lab.pack)return false;
  for(const role of LAB_STEMS){
    const level=labGainFor(role,levels,solo);
    if(role==='melody'){
      const active=lab._activeVoiceFor(lab.pack);
      for(const key of lab.gains.keys()){
        if(key.startsWith('voice:'))
          lab.mixer.setGain(key,key===active?level:0,{time:.07});
      }
    }else{
      // This uses user input gain; source's separate motion gain stays intact.
      // StemMusicDirector keeps replacement source user gain in sync.
      lab.setStemGain(role,level);
    }
  }
  return true;
}

export function gainLabel(value){
  const preset=LAB_MIX_PRESETS.find(p=>p.gain===value);
  return preset?`${preset.label} (${value.toFixed(2)}x)`:`${value.toFixed(2)}x`;
}import { BiomeSpaceBus } from './BiomeSpaceBus.js';
import { BSOD_THREAT_STEMS, createBsodThreatProcessor } from './BsodThreatProcessor.js';
/**
 * Low-cost WebAudio processors. Types are trusted code, specifications are validated data.
 * Each returned chain owns its oscillators/connections and can be disposed independently.
 */
const clamp = (n, lo, hi, fallback = lo) =>
	Number.isFinite(Number(n)) ? Math.min(hi, Math.max(lo, Number(n))) : fallback;

export const MUSIC_PROCESSORS = Object.freeze([
	'gain', 'filter', 'pan', 'distortion', 'delay', 'tremolo', 'ring', 'convolution', 'analyser',
]);

function saturatorCurve(amount) {
	const curve = new Float32Array(2048);
	const drive = 1 + amount * 18;
	const denom = Math.tanh(drive);
	for (let i = 0; i < curve.length; i++) {
		const x = 2 * i / (curve.length - 1) - 1;
		curve[i] = Math.tanh(x * drive) / denom;
	}
	return curve;
}

function numericParam(param, value, at, smoothing = 0.025) {
	param.cancelScheduledValues(at);
	param.setTargetAtTime(value, at, smoothing);
}

function allocateEffect(ctx, raw) {
	if (!raw || typeof raw !== 'object' || !MUSIC_PROCESSORS.includes(raw.type)) {
		throw new Error('Unsupported music processor');
	}
	const owned = [];
	const lfos = [];
	const refs = {};
	const node = (n) => { owned.push(n); return n; };
	const input = node(ctx.createGain());
	const output = node(ctx.createGain());
	const param = (key, target, lo, hi, defaultValue) => {
		refs[key] = { target, lo, hi };
		target.value = clamp(raw[key], lo, hi, defaultValue);
	};
	switch (raw.type) {
		case 'gain': {
			param('gain', output.gain, 0, 2, 1);
			input.connect(output);
			break;
		}
		case 'filter': {
			const filter = node(ctx.createBiquadFilter());
			filter.type = ['lowpass','highpass','bandpass','notch','peaking','lowshelf','highshelf'].includes(raw.mode)
				? raw.mode : 'lowpass';
			param('frequency', filter.frequency, 20, Math.min(20000,ctx.sampleRate/2 - 10), 1000);
			param('Q', filter.Q, 0.05, 30, 0.7);
			param('gainDb', filter.gain, -24, 24, 0);
			input.connect(filter);
			filter.connect(output);
			break;
		}
		case 'pan': {
			if (!ctx.createStereoPanner) {
				input.connect(output);
				break;
			}
			const p = node(ctx.createStereoPanner());
			param('pan', p.pan, -1, 1, 0);
			input.connect(p);
			p.connect(output);
			break;
		}
		case 'distortion': {
			const shaper = node(ctx.createWaveShaper());
			shaper.curve = saturatorCurve(clamp(raw.amount, 0, 1, 0.3));
			shaper.oversample = '2x';
			input.connect(shaper);
			shaper.connect(output);
			break;
		}
		case 'delay': {
			const dry = node(ctx.createGain());
			const wet = node(ctx.createGain());
			const delayed = node(ctx.createDelay(2));
			const feedback = node(ctx.createGain());
			param('time', delayed.delayTime, 0.01, 1.5, 0.22);
			param('feedback', feedback.gain, 0, 0.85, 0.25);
			param('wet', wet.gain, 0, 1, 0.22);
			dry.gain.value = 1;
			input.connect(dry); dry.connect(output);
			input.connect(delayed); delayed.connect(wet); wet.connect(output);
			delayed.connect(feedback); feedback.connect(delayed);
			break;
		}
		case 'tremolo': {
			const depth = clamp(raw.depth, 0, 1, 0.55);
			const trem = node(ctx.createGain());
			trem.gain.value = 1 - depth / 2;
			const osc = node(ctx.createOscillator());
			osc.type = 'sine';
			param('rate', osc.frequency, 0.1, 30, 4);
			const modGain = node(ctx.createGain());
			modGain.gain.value = depth / 2;
			osc.connect(modGain); modGain.connect(trem.gain);
			input.connect(trem); trem.connect(output);
			osc.start(); lfos.push(osc);
			break;
		}
		case 'ring': {
			const carrier = node(ctx.createGain());
			carrier.gain.value = 0;
			const osc = node(ctx.createOscillator());
			osc.type = ['sine','square','triangle'].includes(raw.wave) ? raw.wave : 'sine';
			param('rate', osc.frequency, 1, 2500, 110);
			osc.connect(carrier.gain);
			input.connect(carrier); carrier.connect(output);
			osc.start(); lfos.push(osc);
			break;
		}
		case 'convolution': {
			const dry = node(ctx.createGain());
			const wet = node(ctx.createGain());
			const conv = node(ctx.createConvolver());
			conv.normalize = raw.normalize !== false;
			param('wet', wet.gain, 0, 1, 0.2);
			dry.gain.value = 1;
			input.connect(dry); dry.connect(output);
			input.connect(conv); conv.connect(wet); wet.connect(output);
			// IR buffer arrives asynchronously. Missing IR = dry-only sound.
			refs.impulse = { set: (buffer) => { conv.buffer = buffer || null; } };
			break;
		}
		case 'analyser': {
			const analyser = node(ctx.createAnalyser());
			analyser.fftSize = 2 ** Math.round(Math.log2(clamp(raw.fftSize, 256, 2048, 512)));
			input.connect(analyser); analyser.connect(output);
			refs.analyser = { node: analyser };
			break;
		}
		default:
			throw new Error('Unsupported processor');
	}
	return {
		type: raw.type,
		id: String(raw.id || raw.type),
		input, output, refs,
		set(key, value, at) {
			const ref = refs[key];
			if (!ref || !ref.target) return false;
			numericParam(ref.target, clamp(value, ref.lo, ref.hi), at);
			return true;
		},
		setImpulse(buffer) { return refs.impulse?.set(buffer); },
		dispose() {
			for (const osc of lfos) { try { osc.stop(); } catch {} }
			for (const n of owned) { try { n.disconnect(); } catch {} }
		},
	};
}

export function buildMusicChain(ctx, effects, output) {
	if (!Array.isArray(effects) || effects.length > 16) throw new Error('Invalid music FX chain');
	const input = ctx.createGain();
	const stages = [];
	let current = input;
	try {
		const seen = new Set();
		for (const spec of effects) {
			const effect = allocateEffect(ctx, spec);
			if (seen.has(effect.id)) { effect.dispose(); throw new Error('Duplicate music processor id'); }
			seen.add(effect.id);
			current.connect(effect.input);
			current = effect.output;
			stages.push(effect);
		}
		current.connect(output);
	} catch (e) {
		for (const stage of stages) stage.dispose();
		try { input.disconnect(); } catch {}
		throw e;
	}
	return {
		input, stages,
		find(id) { return stages.find(s => s.id === id); },
		dispose() {
			try { input.disconnect(); } catch {}
			for (const stage of stages) stage.dispose();
			try { current.disconnect(); } catch {}
		},
	};
}

/**
 * Extensible stem bus. Source keys are data, not hardcoded to Demucs labels.
 * Separate base gain and motion gain prevent gameplay ducking from destroying
 * user mix levels. Effect chains can be replaced with smooth audio crossfades.
 */
export class StemFXMixer {
	constructor(ctx, destination, { roomQuality = 'standard' } = {}) {
		this.ctx = ctx;
		this.destination = destination;
		this.sources = new Map();
		this.maxSources = 48;
		this.timers = new Set();
		this.analyser = ctx.createAnalyser();
		this.analyser.fftSize = 1024;
		this.analyser.smoothingTimeConstant = 0.65;
		this.analyser.connect(destination);
		this._spectrum = new Uint8Array(this.analyser.frequencyBinCount);
		this.mixInput = ctx.createGain();
		this.mixInput.connect(this.analyser);
		// A tiny four-hit count-in may borrow short percussion excerpts from
		// already decoded original drum audio. It shares THIS same bus and
		// music transport but bypasses original-source recovery mute gates.
		this.countInInput=ctx.createGain();
		this.countInInput.connect(this.mixInput);
		this.recoveryPlan=null;
		this.space = new BiomeSpaceBus(ctx, this.mixInput, { quality: roomQuality });
	}

	addSource(id, { gain = 1, effects = [] } = {}) {
		if (this.sources.has(id)) return this.sources.get(id).input;
		if (typeof id !== 'string' || !/^[\w:-]{1,100}$/.test(id) ||
			this.sources.size >= this.maxSources) throw new Error('Music source budget exceeded');
		const input = this.ctx.createGain();
		input.gain.value = clamp(gain, 0, 2, 1);
		const motion = this.ctx.createGain();
		input.connect(motion);
		// Separate the user's mix level and gameplay motion from adaptive
		// original↔replacement fades. Default gain=1 preserves legacy packs.
		const mix = this.ctx.createGain();
		mix.gain.value = 1;
		const recovery=this.ctx.createGain();
		recovery.gain.value=1;
		motion.connect(recovery);
		recovery.connect(mix);
		const output = this.ctx.createGain();
		// Only the three ORIGINAL accompaniment stems get BSOD corruption.
		// This permanent processor survives every biome FX replacement.
		const threat = BSOD_THREAT_STEMS.includes(id)
			? createBsodThreatProcessor(this.ctx, this.mixInput) : null;
		output.connect(threat?.input || this.mixInput);
		const chain = buildMusicChain(this.ctx, effects, output);
		mix.connect(chain.input);
		const send = this.ctx.createGain();
		const defaultRoomSend = id.startsWith('voice:') ? 0.38 :
			id === 'vocals' ? 0.12 : id === 'piano' ? 0.09 :
			id === 'guitar' || id === 'other' ? 0.04 : 0;
		send.gain.value = defaultRoomSend;
		mix.connect(send);
		send.connect(this.space.input);
		const source = { input, motion, recovery, mix, output, chain, send, threat, defaultRoomSend };
		this.sources.set(id, source);
		if(this.recoveryPlan)this._scheduleRecoveryGate(source,this.recoveryPlan);
		return input;
	}

	selectBiome(id) { return this.space.selectBiome(id); }

	setRoomSend(id, value) {
		const source = this.sources.get(id);
		if (!source) return false;
		numericParam(source.send.gain, value == null ? source.defaultRoomSend : clamp(value, 0, 1), this.ctx.currentTime, 0.15);
		return true;
	}

	/** Music-only crash gate, independent of user level, motion gain,
	 * original-vs-adaptive mix crossfade, and room send. ALL source
	 * channels are gated; exactly four short drum accents may use
	 * countInInput before the existing master/music compressor.
	 */
	_scheduleRecoveryGate(source,plan){
		const param=source.recovery.gain;
		const now=this.ctx.currentTime;
		param.cancelScheduledValues(now);
		param.setValueAtTime(param.value,now);
		if(now<plan.bandAt){
			param.linearRampToValueAtTime(0,Math.min(plan.bandAt,now+.014));
			param.setValueAtTime(0,plan.bandAt);
		}
		param.linearRampToValueAtTime(1,Math.max(now+.01,plan.bandAt+.055));
	}

	setRecoveryPlan(plan){
		if(!plan||!Number.isFinite(plan.bandAt)||
			plan.bandAt<=this.ctx.currentTime)return false;
		this.recoveryPlan=plan;
		for(const source of this.sources.values())this._scheduleRecoveryGate(source,plan);
		return true;
	}

	cancelRecoveryPlan(){
		this.recoveryPlan=null;
		const now=this.ctx.currentTime;
		for(const source of this.sources.values()){
			const param=source.recovery.gain;
			param.cancelScheduledValues(now);
			param.setValueAtTime(param.value,now);
			param.linearRampToValueAtTime(1,now+.04);
		}
	}

	setGain(id, value, { motion = false, time = 0.04 } = {}) {
		const src = this.sources.get(id);
		if (!src) return false;
		const param = motion ? src.motion.gain : src.input.gain;
		numericParam(param, clamp(value, 0, 2), this.ctx.currentTime, clamp(time, 0.005, 1, 0.04));
		return true;
	}

	/** Authoritative BSOD proximity on ORIGINAL guitar, piano, Other only. */
	setThreatLevel(id, proximity01) {
		return this.sources.get(id)?.threat?.setDanger(proximity01) || false;
	}

	setMixGain(id, value, { time = 0.20 } = {}) {
		const src = this.sources.get(id);
		if (!src) return false;
		const now = this.ctx.currentTime;
		const param = src.mix.gain;
		param.cancelScheduledValues(now);
		param.setValueAtTime(param.value, now);
		// An explicit 200ms crossfade duration, not a 200ms exponential
		// time constant (which takes ~1 second to actually finish).
		param.linearRampToValueAtTime(clamp(value, 0, 1),
			now + clamp(time, 0.005, 1, 0.20));
		return true;
	}

	setEffectParam(id, effectId, key, value) {
		const effect = this.sources.get(id)?.chain?.find(effectId);
		return effect ? effect.set(key, value, this.ctx.currentTime) : false;
	}

	setImpulse(id, effectId, buffer) {
		const effect = this.sources.get(id)?.chain?.find(effectId);
		if (!effect || effect.type !== 'convolution') return false;
		effect.setImpulse(buffer);
		return true;
	}

	replaceEffects(id, effects = [], fadeSeconds = 0.15) {
		const src = this.sources.get(id);
		if (!src) return false;
		const output = this.ctx.createGain();
		output.gain.value = 0;
		const chain = buildMusicChain(this.ctx, effects, output);
		output.connect(src.threat?.input || this.mixInput);
		src.mix.connect(chain.input);
		const previous = { chain: src.chain, output: src.output };
		src.chain = chain;
		src.output = output;
		const t = this.ctx.currentTime;
		const fade = clamp(fadeSeconds, 0.02, 2, 0.15);
		previous.output.gain.cancelScheduledValues(t);
		previous.output.gain.setValueAtTime(previous.output.gain.value, t);
		previous.output.gain.linearRampToValueAtTime(0, t + fade);
		output.gain.setValueAtTime(0, t);
		output.gain.linearRampToValueAtTime(1, t + fade);
		const timer = setTimeout(() => {
			this.timers.delete(timer);
			try { src.mix.disconnect(previous.chain.input); } catch {}
			previous.chain.dispose();
			try { previous.output.disconnect(); } catch {}
		}, (fade + 0.15) * 1000);
		this.timers.add(timer);
		return true;
	}

	energy() {
		this.analyser.getByteFrequencyData(this._spectrum);
		const bands = [0, 0, 0], counts = [0, 0, 0];
		const hzPerBin = this.ctx.sampleRate / this.analyser.fftSize;
		for (let i = 1; i < this._spectrum.length; i++) {
			const hz = i * hzPerBin;
			const band = hz < 250 ? 0 : hz < 2500 ? 1 : 2;
			bands[band] += this._spectrum[i] / 255;
			counts[band]++;
		}
		return { bass: bands[0]/(counts[0]||1), mid: bands[1]/(counts[1]||1),
			treble: bands[2]/(counts[2]||1) };
	}

	destroy() {
		for (const timer of this.timers) clearTimeout(timer);
		this.timers.clear();
		for (const src of this.sources.values()) {
			try { src.input.disconnect(); src.motion.disconnect(); src.recovery.disconnect(); src.mix.disconnect(); src.output.disconnect(); src.send.disconnect(); } catch {}
			src.chain.dispose();
			src.threat?.destroy();
		}
		this.sources.clear();
		this.space.destroy();
		this.countInInput.disconnect();
		this.mixInput.disconnect();
		this.analyser.disconnect();
	}
}/** Validated, versioned music-pack data. No Phaser, DOM or I/O. */
import { BIOME_IDS, HOME_BIOME } from './BiomeVoices.js';
import { canonicalBiomeId, canonicalLegacyId } from '../../data/biomeAliases.js';
export const CORE_STEMS = Object.freeze(['vocals', 'drums', 'bass', 'guitar', 'piano', 'other']);
const validId = (s) => typeof s === 'string' && /^[a-zA-Z0-9:_-]{1,100}$/.test(s);
const safePath = (s) => typeof s === 'string' && s.length < 300 &&
  !s.startsWith('/') && !s.includes('..') && !s.includes('\\') &&
  /^[a-zA-Z0-9_.\/-]+$/.test(s);
const whole = (v) => Number.isSafeInteger(v) && v >= 0;
const effectTypes = new Set(['gain', 'filter', 'pan', 'distortion', 'delay', 'tremolo', 'ring', 'convolution', 'analyser']);

/**
 * An object's entries with legacy biome ids (issue #65) read as canonical. A map carrying BOTH spellings of one key
 * is ambiguous (which value wins?), so it is rejected rather than silently overwritten.
 */
function canonicalEntries(obj, canon = canonicalLegacyId) {
	const seen = new Set();
	return Object.entries(obj).map(([k, v]) => {
		const key = canon(k);
		if (seen.has(key)) throw new Error('Invalid music pack: duplicate biome key (legacy alias): ' + key);
		seen.add(key);
		return [key, v];
	});
}

const ADAPTIVE_FAMILIES = Object.freeze(['bass', 'drums', 'featured', 'guitar', 'piano', 'other']);
const FEATURE_STEMS = Object.freeze(['guitar', 'piano', 'other']);

/**
 * Biome-specific files are indexed separately from the 48 permanent pack
 * source IDs. Each role uses one reusable mix bus; its individual instrument
 * recordings may come from any synthesis, sampling or sound-design method.
 * Variant arrays are complete segment-aligned safe relative paths.
 */
function normalizeAdaptive(raw, count) {
	if (raw === undefined) return null;
	if (!raw || typeof raw !== 'object' || Array.isArray(raw) ||
		!FEATURE_STEMS.includes(raw.featuredStem) ||
		!raw.variants || typeof raw.variants !== 'object' ||
		Array.isArray(raw.variants)) {
		throw new Error('Invalid adaptive music map');
	}
	const variants = Object.create(null);
	for (const role of Object.keys(raw.variants)) {
		if (!ADAPTIVE_FAMILIES.includes(role)) throw new Error('Unknown adaptive role');
	}
	for (const role of ADAPTIVE_FAMILIES) {
		const biomeFiles = raw.variants[role] ?? {};
		if (!biomeFiles || typeof biomeFiles !== 'object' ||
			Array.isArray(biomeFiles)) throw new Error('Invalid adaptive variants');
		const mapping = Object.create(null);
		for (const [biome, legacyFiles] of canonicalEntries(biomeFiles, canonicalBiomeId)) {
			// A pack still written with the legacy id (issue #65) loads under the canonical one, paths included.
			const files = Array.isArray(legacyFiles) ? legacyFiles.map(canonicalLegacyId) : legacyFiles;
			if (biome === HOME_BIOME || !BIOME_IDS.includes(biome) ||
				!Array.isArray(files) || files.length !== count ||
				!files.every(safePath)) {
				throw new Error('Invalid biome audio segment mapping');
			}
			mapping[biome] = files.slice();
		}
		variants[role] = mapping;
	}
	return { featuredStem: raw.featuredStem, variants };
}

export function normalizeCatalog(raw) {
	if (!raw || raw.format !== 'bitstream-music-catalog-v1' || !Array.isArray(raw.tracks) || raw.tracks.length > 500) {
		throw new Error('Invalid music catalog');
	}
	const seen = new Set();
	const tracks = raw.tracks.map((track) => {
		if (!validId(track.id) || !safePath(track.manifest) || seen.has(track.id)) {
			throw new Error('Invalid catalog track');
		}
		seen.add(track.id);
		return { id: track.id, title: String(track.title || track.id).slice(0, 200), manifest: track.manifest };
	});
	return { tracks };
}

export function normalizePack(raw) {
	if (!raw || raw.format !== 'bitstream-music-pack-v1' || !validId(raw.id) ||
		!whole(raw.frameCount) || raw.frameCount < 1 || !whole(raw.sampleRate) ||
		raw.sampleRate < 8000 || raw.sampleRate > 192000 ||
		!Array.isArray(raw.segments) || raw.segments.length < 1 || raw.segments.length > 5000) {
		throw new Error('Invalid music pack');
	}
	let cursor = 0;
	// Source keys and paths may carry a legacy biome id (issue #65, e.g. a legacy voice key); read them as canonical.
	const baselineNames = canonicalEntries(raw.segments[0]?.sources || {}).map(([k]) => k).sort();
	if (baselineNames.length < CORE_STEMS.length ||
		baselineNames.length > (raw.adaptive === undefined ? 48 : 42)) {
		// Adaptive packs reserve SIX reusable mixer buses (featured, bass, drums, plus individual source guitar/piano/other).
		throw new Error('Too many music sources');
	}
	const segments = raw.segments.map((seg) => {
		if (!whole(seg.startFrame) || !whole(seg.frames) || seg.frames < 1 || seg.startFrame !== cursor ||
			!seg.sources || typeof seg.sources !== 'object') {
			throw new Error('Noncontiguous music segment');
		}
		const segSources = Object.fromEntries(canonicalEntries(seg.sources).map(([k, v]) => [k, canonicalLegacyId(v)]));
		if (Object.keys(segSources).sort().join('|') !== baselineNames.join('|')) throw new Error('Stem names change between segments');
		for (const name of CORE_STEMS) {
			if (!safePath(segSources[name])) throw new Error('Missing or unsafe stem: ' + name);
		}
		const sources = {};
		for (const [name, path] of Object.entries(segSources)) {
			if (!validId(name) || !safePath(path)) throw new Error('Unsafe music source');
			sources[name] = path;
		}
		cursor += seg.frames;
		return { startFrame: seg.startFrame, frames: seg.frames, sources };
	});
	if (cursor !== raw.frameCount) throw new Error('Music pack frame count mismatch');
	const effects = Object.create(null);
	if (raw.effects !== undefined) {
		if (!raw.effects || typeof raw.effects !== 'object' || Array.isArray(raw.effects)) throw new Error('Invalid effects map');
		for (const [name, stages] of canonicalEntries(raw.effects)) {
			if (!baselineNames.includes(name) || !Array.isArray(stages) || stages.length > 16) {
				throw new Error('Invalid source FX preset');
			}
			const ids = new Set();
			effects[name] = stages.map(stage => {
				if (!stage || !effectTypes.has(stage.type) || !validId(stage.id || stage.type) ||
					ids.has(stage.id || stage.type)) throw new Error('Invalid music processor');
				ids.add(stage.id || stage.type);
				return { ...stage };
			});
		}
	}
	const roomSends = Object.create(null);
	if (raw.roomSends !== undefined) {
		if (!raw.roomSends || typeof raw.roomSends !== 'object' ||
			Array.isArray(raw.roomSends)) throw new Error('Invalid room sends');
		for (const [name, value] of canonicalEntries(raw.roomSends)) {
			if (!baselineNames.includes(name) || !Number.isFinite(value) ||
				value < 0 || value > 1) throw new Error('Invalid room send level');
			roomSends[name] = value;
		}
	}
	// Optional always-on extra texture buses. Derived assets need no special engine code.
	const layers = Object.create(null);
	if (raw.layers !== undefined) {
		if (!raw.layers || typeof raw.layers !== 'object' || Array.isArray(raw.layers)) {
			throw new Error('Invalid derived layer map');
		}
		for (const [name, level] of canonicalEntries(raw.layers)) {
			if (!baselineNames.includes(name) || CORE_STEMS.includes(name) ||
				name.startsWith('voice:') || !Number.isFinite(level) || level < 0 || level > 1.5) {
				throw new Error('Invalid derived layer');
			}
			layers[name] = level;
		}
	}
	const captions = raw.captions === undefined ? null : raw.captions;
	if (captions !== null && !safePath(captions)) throw new Error('Invalid caption asset');
	// This is diagnostic metadata. It never changes normal playback routing.
	// An explicit expected content hash ties the score to this song revision.
	const score=raw.performance;
	if(score!==undefined && (!score||typeof score!=='object'||
		Array.isArray(score)||!safePath(score.path)||
		!/^[0-9a-f]{64}$/.test(score.scoreHash)))
		throw new Error('Invalid performance score asset');
	const performance=score===undefined?null:{
		path:score.path,scoreHash:score.scoreHash,
	};
	// The V2 file is an OPTIONAL, unverified comparison timeline. It is
	// intentionally NOT a music stem, rendering asset, or selection input.
	const experiment=raw.experimentalPerformance;
	if(experiment!==undefined && (
		!experiment||typeof experiment!=='object'||
		Array.isArray(experiment)||!safePath(experiment.path)||
		!/^[0-9a-f]{64}$/.test(experiment.scoreHash)||
		!/^[0-9a-f]{64}$/.test(experiment.parentScoreHash)||
		experiment.parentScoreHash!==performance?.scoreHash)){
		throw new Error('Invalid experimental performance comparison');
	}
	const experimentalPerformance=experiment===undefined?null:{
		path:experiment.path,scoreHash:experiment.scoreHash,
		parentScoreHash:experiment.parentScoreHash,
	};
	// Machine disagreement is a future human review queue, not gold and
	// not an audio or music playback asset.
	const review=raw.diagnosticReviewQueue;
	if(review!==undefined&&(!review||typeof review!=='object'||
		Array.isArray(review)||!safePath(review.path)||
		!/^[0-9a-f]{64}$/.test(review.baselineScoreHash)||
		!/^[0-9a-f]{64}$/.test(review.experimentalScoreHash)||
		review.baselineScoreHash!==performance?.scoreHash||
		review.experimentalScoreHash!==experimentalPerformance?.scoreHash)){
		throw new Error('Invalid non-gold review queue descriptor');
	}
	const diagnosticReviewQueue=review===undefined?null:{
		path:review.path,baselineScoreHash:review.baselineScoreHash,
		experimentalScoreHash:review.experimentalScoreHash,
	};
	const tempo = Number(raw.tempo);
	const beat = Number.isFinite(tempo) && tempo >= 30 && tempo <= 350 ? tempo : null;
	return {
		id: raw.id,
		title: String(raw.title || raw.id).slice(0, 200),
		sampleRate: raw.sampleRate,
		frameCount: raw.frameCount,
		duration: raw.frameCount / raw.sampleRate,
		segments,
		sourceNames: baselineNames,
		effects,
		roomSends,
		layers,
		adaptive: normalizeAdaptive(raw.adaptive, segments.length),
		performance,
		experimentalPerformance,
		diagnosticReviewQueue,
		captions,
		bpm: beat,
	};
}

export function resolveMusicAsset(baseUrl, safeRelativePath) {
	if (!safePath(safeRelativePath)) throw new Error('Unsafe music asset path');
	return new URL(safeRelativePath, baseUrl).href;
}import { cosmeticRandom } from '../CosmeticRandom.js';
/** Four-song owner-selected rotation: One More Run first per fresh load, then sequential/shuffled. All disabled = SILENCE. */
export const GAME_SONGS = Object.freeze([
	{ id: 'FEsxYVStla4', label: 'POPE LEO' },
	{ id: 'local-one-more-run-bitstream-bluffs', label: 'ONE MORE RUN' },
	{ id: 'WRBGQUqD54U', label: 'RUNS OUT OF CODE' },
	{ id: 'FYImnz5-hXs', label: 'VARMONT IS SAVED' },
]);
export const FIRST_SONG_ID = 'local-one-more-run-bitstream-bluffs';
export const defaultSongSelection = () => Object.fromEntries(GAME_SONGS.map(song => [song.id, true]));
export function sanitizeSongSelection(input) {
	const defaults = defaultSongSelection();
	if (!input || typeof input !== 'object' || Array.isArray(input)) return defaults;
	for (const song of GAME_SONGS) {
		if (typeof input[song.id] === 'boolean') defaults[song.id] = input[song.id];
	}
	return defaults;
}
export function enabledSongIndices(catalog, selection) {
	const enabled = sanitizeSongSelection(selection);
	if (!Array.isArray(catalog)) return [];
	return catalog.flatMap((track, i) => enabled[track.id] === true ? [i] : []);
}
export function nextEnabledSongIndex(catalog, selection, previousIndex = -1) {
	const indices = enabledSongIndices(catalog, selection);
	if (!indices.length) return -1;
	return indices.find(i => i > previousIndex) ?? indices[0];
}
/** Build a shuffled round of enabled tracks; never repeat the current one when alternatives exist. */
export function shuffledSongRound(catalog, selection, currentIndex, random=()=>cosmeticRandom('audio/shuffle').next()) {
	const enabled=enabledSongIndices(catalog,selection);
	if(enabled.length<2)return enabled;
	const choices=enabled.filter(index=>index!==currentIndex);
	for(let i=choices.length-1;i>0;i--){
		const raw=Number(random());
		const pick=Number.isFinite(raw)?Math.max(0,Math.min(0.999999999,raw)):0;
		const j=Math.floor(pick*(i+1));
		[choices[i],choices[j]]=[choices[j],choices[i]];
	}
	return choices;
}

export function hasEnabledSongs(selection) {
	return GAME_SONGS.some(song => sanitizeSongSelection(selection)[song.id]);
}/**
 * Pure validator for model-DISAGREEMENT review shorts, not human gold.
 * Never used by playback or in a source note correction automatically.
 */
const FORMAT='bitstream-music-review-queue-v1';
const STATUS='machine-ranked-disagreement-not-human-verified';
const ROLES=new Set(['bass','drums','guitar','piano','other']);
const integer=n=>Number.isSafeInteger(n);
const hex64=s=>typeof s==='string'&&/^[0-9a-f]{64}$/.test(s);

export function validateMusicReviewQueue(raw,pack,base,candidate){
	if(!raw||raw.format!==FORMAT||raw.status!==STATUS||
		raw.songId!==pack?.id||!base||!candidate||
		raw.baselineScoreHash!==base.scoreHash||
		raw.experimentalScoreHash!==candidate.scoreHash||
		!hex64(raw.baselineScoreHash)||!hex64(raw.experimentalScoreHash)||
		pack.diagnosticReviewQueue?.baselineScoreHash!==base.scoreHash||
		pack.diagnosticReviewQueue?.experimentalScoreHash!==candidate.scoreHash||
		typeof raw.selectionMethod!=='string'||
		!raw.selectionMethod.includes('NOT correctness')||
		!Array.isArray(raw.excerpts)||raw.excerpts.length<1||
		raw.excerpts.length>20){
		throw new Error('Review shortlist provenance or non-gold status mismatch');
	}
	const seen=new Set();
	let priorRank=0;
	for(const item of raw.excerpts){
		if(!item||!ROLES.has(item.role)||
			!integer(item.startFrame)||!integer(item.endFrame)||
			item.startFrame<0||item.endFrame<=item.startFrame||
			item.endFrame>pack.frameCount||
			item.endFrame-item.startFrame>8*48000||
			item.id!==item.role+'-'+item.startFrame||
			seen.has(item.id)||
			!integer(item.priorityOrder)||item.priorityOrder<=priorRank||
			item.priorityOrder>20||
			!integer(item.releaseCount)||item.releaseCount<0||
			!integer(item.candidateCount)||item.candidateCount<0||
			!integer(item.samePitchWithin50ms)||item.samePitchWithin50ms<0||
			item.samePitchWithin50ms>Math.min(
				item.releaseCount,item.candidateCount)||
			!Number.isFinite(item.disagreementProxy)||
			item.disagreementProxy<0){
			throw new Error('Invalid or unreviewed musical review excerpt');
		}
		seen.add(item.id);
		priorRank=item.priorityOrder;
	}
	return raw;
}/**
 * The same immutable performance-v1 schema that offline release rendering
 * consumes, interpreted on the REAL game's 48kHz music clock.
 *
 * This module never runs a detector, guesses a beat, invents confidence or
 * changes live playback. Source audio and replacement routing remain owned
 * by StemMusicDirector; optional score sidecars are diagnostic evidence only.
 */
export const PERFORMANCE_FORMAT='bitstream-performance-v1';
export const PERFORMANCE_ROLES=Object.freeze([
	'melody','bass','drums','guitar','piano','other'
]);
export const PERFORMANCE_SAMPLE_RATE=48000;
const hex64=s=>typeof s==='string'&&/^[0-9a-f]{64}$/.test(s);
const int=n=>Number.isSafeInteger(n)&&n>=0;
const safeId=s=>typeof s==='string'&&/^[a-zA-Z0-9_-]{3,48}$/.test(s);

function validateScoreShape(raw,pack,asset,quality){
	if(!raw||raw.format!==PERFORMANCE_FORMAT||
		raw.songId!==pack.id||raw.frameCount!==pack.frameCount||
		raw.sampleRate!==PERFORMANCE_SAMPLE_RATE||
		raw.sampleRate!==pack.sampleRate||
		raw.featuredStem!==pack.adaptive?.featuredStem||
		raw.quality!==quality||
		raw.calibratedConfidence!==false||
		!hex64(raw.scoreHash)||
		raw.scoreHash!==asset?.scoreHash){
		throw new Error('Performance score identity/revision mismatch');
	}
	const stems=raw.provenance?.sourceStemSha256;
	if(!stems||Object.keys(stems).sort().join(',')!==
		['bass','drums','guitar','other','piano','vocals'].join(',')||
		!Object.values(stems).every(hex64)){
		throw new Error('Performance score source fingerprint invalid');
	}
	if(!raw.events||Object.keys(raw.events).sort().join(',')!==
		PERFORMANCE_ROLES.slice().sort().join(',')){
		throw new Error('Performance score lacks instrument roles');
	}
	const ids=new Set();
	for(const role of PERFORMANCE_ROLES){
		const events=raw.events[role];
		if(!Array.isArray(events)||events.length>150000)
			throw new Error('Performance score role event count invalid');
		let last=-1;
		for(const event of events){
			if(!event||!int(event.startFrame)||
				event.startFrame>=raw.frameCount||
				event.startFrame<last||!safeId(event.id)||ids.has(event.id)||
				event.confidence!==null){
				throw new Error('Performance score event corrupt');
			}
			ids.add(event.id);
			last=event.startFrame;
			if(role==='drums'){
				if(event.endFrame!==undefined ||
					!['kick','snare','hat','tom','cymbal'].includes(event.class))
					throw new Error('Performance drum hit corrupt');
			}else if(!int(event.endFrame)||
				event.endFrame<=event.startFrame||
				event.endFrame>raw.frameCount||
				!int(event.pitch)||event.pitch>127||event.class!=='note'){
				throw new Error('Performance note event corrupt');
			}
		}
	}
	return raw;
}

export function validatePerformanceScore(raw,pack){
	return validateScoreShape(raw,pack,pack.performance,'provisional-unreviewed');
}

/** This is READ-ONLY source-disagreement evidence; it can never be
 * substituted for the actual game's authoritative base performance score.
 * The parent hash and six original stem fingerprints must match exactly.
 */
export function validateExperimentalPerformanceScore(raw,pack,original){
	if(!original||!pack.experimentalPerformance||
		pack.experimentalPerformance.parentScoreHash!==original.scoreHash){
		throw new Error('Experimental score has no validated released parent');
	}
	validateScoreShape(raw,pack,pack.experimentalPerformance,
		'experimental-candidate-unreviewed');
	if(raw.provenance?.evidence?.parentScoreHash!==original.scoreHash){
		throw new Error('Experimental score is not descended from released score');
	}
	for(const role of ['vocals','bass','drums','guitar','piano','other']){
		if(raw.provenance.sourceStemSha256[role]!==
			original.provenance.sourceStemSha256[role]){
			throw new Error('Experimental candidate used different source audio');
		}
	}
	// The current experiment intentionally leaves released melody alone.
	// If future experiments modify it, they must explicitly version this
	// invariant rather than quietly claiming a like-for-like comparison.
	const before=original.events.melody;
	const after=raw.events.melody;
	if(before.length!==after.length||before.some((event,index)=>
		event.id!==after[index].id||
		event.startFrame!==after[index].startFrame||
		event.endFrame!==after[index].endFrame||
		event.pitch!==after[index].pitch)){
		throw new Error('Candidate unexpectedly changed baseline melody');
	}
	return raw;
}

/** Return source-start events near the clock, preserving simultaneous hits
 * and same-pitch re-attacks. This is O(log N + number of local events).
 */
export function nearbyPerformanceEvents(score,roles,frame,spanFrames=2400){
	if(!score||!int(frame)||!int(spanFrames))return [];
	const result=[];
	const left=Math.max(0,frame-spanFrames);
	const right=frame+spanFrames;
	for(const role of roles){
		const events=score.events[role]||[];
		let lo=0,hi=events.length;
		while(lo<hi){
			const mid=(lo+hi)>>1;
			if(events[mid].startFrame<left)lo=mid+1;
			else hi=mid;
		}
		while(lo<events.length&&events[lo].startFrame<=right){
			result.push({role,event:events[lo]});
			lo++;
		}
	}
	result.sort((a,b)=>a.event.startFrame-b.event.startFrame||
		a.role.localeCompare(b.role)||a.event.id.localeCompare(b.event.id));
	return result;
}

/** A human suspicion marker is NOT a gold label. Never directly edit the
 * score because it would invalidate the content hash and the shipped audio.
 */
export function makeIssueMarker(score,{songId,role,frame,biome,airborne,speed,
	replacements}){
	if(!int(frame))throw new Error('Cannot annotate a non-frame time');
	const roles=role==='ALL'?PERFORMANCE_ROLES:
		PERFORMANCE_ROLES.includes(role)?[role]:[];
	if(!roles.length)throw new Error('Unknown marker role');
	const near=nearbyPerformanceEvents(score,roles,frame,Math.round(.075*
		PERFORMANCE_SAMPLE_RATE));
	return {
		kind:'subjective-suspected-issue-not-gold-truth',
		songId,
		scoreHash:score?.scoreHash??null,
		frame,
		roles,
		nearbySourceEventIds:near.map(({event})=>event.id),
		biome,
		airborne:airborne===true,
		speedPxS:Number(speed)||0,
		replacements:replacements===true,
	};
}/**
 * Non-destructive candidate correction queue for the game's source-event
 * inspector. Not live audio, not an accepted gold transcription.
 *
 * All changes are rendered as ONE atomic operation per stable note ID.
 * Offline performance_v1.apply_patch_layer is the sole materializer.
 * A new score hash never inherits corrections without explicit reconciliation.
 */
import { PERFORMANCE_ROLES } from './PerformanceScore.js';

const integer=n=>Number.isSafeInteger(n);
const inRange=(x,lo,hi)=>integer(x)&&x>=lo&&x<=hi;

export class ScoreCorrectionDraft {
	constructor(score){
		if(!score?.scoreHash||!score?.songId)throw new Error('Missing immutable source score');
		this.songId=score.songId;
		this.scoreHash=score.scoreHash;
		this.frameCount=score.frameCount;
		this.original=new Map();
		this.roleEvents=new Map();
		for(const role of PERFORMANCE_ROLES){
			this.roleEvents.set(role,score.events[role]||[]);
			for(const event of score.events[role]||[]){
				if(this.original.has(event.id))throw new Error('Duplicate score event ID');
				this.original.set(event.id,{role,event});
			}
		}
		this.edits=new Map();
	}

	get count(){return this.edits.size;}

	/** Return preview only; never mutate the underlying score. */
	preview(id){
		const original=this.original.get(id);
		if(!original)return null;
		const op=this.edits.get(id);
		const e=original.event;
		return {
			id,role:original.role,
			startFrame:op?.action==='correct'?op.startFrame:e.startFrame,
			endFrame:original.role==='drums'?undefined:
				op?.action==='correct'?op.endFrame:e.endFrame,
			pitch:original.role==='drums'?null:
				op?.action==='correct'?op.pitch:e.pitch,
			class:e.class,
			status:op?.action||'source-candidate',
		};
	}

	/** One edit per ID even if user nudges and changes octave repeatedly. */
	modify(id,action,amount=0){
		const original=this.original.get(id);
		if(!original)return false;
		if(action==='undo'){
			this.edits.delete(id);
			return true;
		}
		if(action==='reject'||action==='accept'){
			this.edits.set(id,{action,id});
			return true;
		}
		if(action!=='nudge'||!integer(amount)) {
			if(action!=='octave'||!integer(amount))return false;
		}
		if(!['nudge','octave'].includes(action))return false;
		const e=original.event, role=original.role;
		if(action==='octave'&&(role==='drums'||Math.abs(amount)!==12))
			return false;
		if(action==='nudge'&&(!amount||Math.abs(amount)>4800))return false;
		const prior=this.preview(id);
		const startFrame=prior.startFrame+(action==='nudge'?amount:0);
		const endFrame=role==='drums'?undefined:
			prior.endFrame+(action==='nudge'?amount:0);
		const pitch=role==='drums'?undefined:
			prior.pitch+(action==='octave'?amount:0);
		if(!inRange(startFrame,0,this.frameCount-1)||(
			role!=='drums'&&(!inRange(endFrame,startFrame+1,this.frameCount)||
				!inRange(pitch,0,127))))return false;
		// Canonical performance events remain monotonically time-ordered.
		// Never export a patch the offline materializer would reject.
		// Simultaneous chords may need a future coordinated group operation.
		const siblings=this.roleEvents.get(role)||[];
		const index=siblings.findIndex(item=>item.id===id);
		for(let i=index-1;i>=0;i--){
			const adjacent=this.preview(siblings[i].id);
			if(adjacent.status==='reject')continue;
			if(adjacent.startFrame>startFrame)return false;
			break;
		}
		for(let i=index+1;i<siblings.length;i++){
			const adjacent=this.preview(siblings[i].id);
			if(adjacent.status==='reject')continue;
			if(adjacent.startFrame<startFrame)return false;
			break;
		}
		// A nudge followed by octave MUST retain both changes.
		if(startFrame===e.startFrame && (
			role==='drums'||(endFrame===e.endFrame&&pitch===e.pitch))){
			this.edits.delete(id);
			return true;
		}
		this.edits.set(id,{id,action:'correct',startFrame,...(
			role==='drums'?{}:{endFrame,pitch})});
		return true;
	}

	/** This JSON is human feedback, not an approved musical release. */
	export(){
		if(!this.edits.size)return null;
		return {
			format:'bitstream-performance-patches-v1',
			status:'draft-unreviewed-not-applied-to-audio',
			songId:this.songId,
			baseScoreHash:this.scoreHash,
			sampleRate:48000,
			operations:[...this.edits.values()],
		};
	}
}/** Renders source AUDIO waveform from the SAME decoded OGG AudioBuffer
 * cache already used by the sandbox transport. No network, copied audio,
 * invented waveform, or pitch detector. Output is display-only normalized
 * sampled absolute PCM peaks per bin (up to 64 sample positions per bin),
 * NOT exact true-peaks, loudness, or post-DSP sound pressure.
 */
export const LAB_WAVEFORM_BINS=200;

export function originalStemWaveform(pack,cache,role,startFrame,endFrame,bins=LAB_WAVEFORM_BINS){
  if(!pack||!cache?.get||!Number.isInteger(startFrame)||
    !Number.isInteger(endFrame)||endFrame<=startFrame||
    !Number.isInteger(bins)||bins<8||bins>1024||
    !Number.isInteger(pack.sampleRate)||pack.sampleRate<=0||
    !Array.isArray(pack.segments))return null;
  const result=new Float32Array(bins);
  let populated=0;
  const range=endFrame-startFrame;
  const source=String(role||'');
  for(let i=0;i<bins;i++){
    const a=startFrame+Math.floor(i*range/bins);
    const b=startFrame+Math.floor((i+1)*range/bins);
    const segIndex=pack.segments.findIndex(seg=>
      a>=seg.startFrame&&a<seg.startFrame+seg.frames);
    if(segIndex<0)continue;
    const seg=pack.segments[segIndex];
    const buffer=cache.get(`${segIndex}/${source}`);
    if(!buffer?.getChannelData||!Number.isFinite(buffer.sampleRate)||
      buffer.sampleRate<=0||buffer.length<=0)continue;
    const start=Math.max(0,Math.floor((a-seg.startFrame)*buffer.sampleRate/pack.sampleRate));
    const until=Math.min(buffer.length,
      Math.ceil((Math.min(b,seg.startFrame+seg.frames)-seg.startFrame)*
        buffer.sampleRate/pack.sampleRate));
    if(until<=start)continue;
    const samples=[];
    for(let c=0;c<Math.min(buffer.numberOfChannels,2);c++)
      samples.push(buffer.getChannelData(c));
    if(!samples.length)continue;
    let peak=0;
    // Inspect a stable maximum ~64 positions per bin per channel;
    // avoid 192k samples per draw on low-end Chromebooks.
    const stride=Math.max(1,Math.floor((until-start)/64));
    for(let j=start;j<until;j+=stride){
      for(const samplesOfChannel of samples){
        const v=Math.abs(samplesOfChannel[j]??0);
        if(Number.isFinite(v))peak=Math.max(peak,v);
      }
    }
    result[i]=Math.min(1,peak);
    populated++;
  }
  return Object.freeze({role:source,bins:result,available:populated,
    total:bins,coverage:populated/bins});
}/**
 * Six-stem Web Audio jukebox; decoded chunks share one clock.
 * The master FLAC bank is never loaded by the browser.
 * Derived source keys (for example "voice:bitstream-bluffs") are allowed in packs.
 * Optional 'voice:<biome>' sources are mixed in dynamically when a pack provides them.
 */
import { CORE_STEMS, normalizeCatalog, normalizePack, resolveMusicAsset } from './MusicPack.js';
import { StemFXMixer } from './MusicFXGraph.js';
import { AdaptiveBiomeRouter } from './AdaptiveBiomeRouter.js';
import { voiceSourceForBiome, HOME_BIOME } from './BiomeVoices.js';
import { canonicalBiomeId } from '../../data/biomeAliases.js';
import { captionAt, nextBeatTime, normalizeCaptions } from './CaptionSequencer.js';
import { FIRST_SONG_ID, defaultSongSelection, sanitizeSongSelection, nextEnabledSongIndex, enabledSongIndices, shuffledSongRound } from './MusicPlaylist.js';
import { melodyPreset, orchestraPreset } from './DynamicOrchestraPresets.js';

const clamp = (v, min, max) => Math.min(max, Math.max(min, v));
const sleepSafe = (promise) => Promise.resolve(promise).catch(() => null);

export class StemMusicDirector {
	constructor(audio, catalogUrl = 'music/catalog.json') {
		this.audio = audio;
		this.catalogUrl = catalogUrl;
		this.catalog = [];
		this.songEnabled = defaultSongSelection();
		this.shuffleEnabled = false;
		this._shuffleRemaining = [];
		this.menuMode = false;
		this.bsodDanger = 0;
		this.dynamicOrchestra = false;
		this.speedPxS = 0;
		this._timbreSignatures = new Map();
		this.ready = false;
		this.started = false;
		this.disposed = false;
		this.trackIndex = 0;
		this.track = null;
		this.pack = null;
		this.packBase = '';
		this.clockStart = null;
		this.ctx = null;
		this.gains = new Map();
		this._stemUserLevels = new Map(CORE_STEMS.map(name => [name, 1]));
		this._effectSignatures = new Map();
		this.activeNodes = new Set();
		this.cache = new Map();
		this.scheduled = new Set();
		this.inflight = new Map();
		this.biome = HOME_BIOME;
		this.vocals = false;
		this.musicCaptions = false;
		this.captionWords = [];
		this.airborne = false;
		this._timer = null;
		this._token = 0;
		this._nextPromise = null;
		this._nextIndex = null;
		this._loading = null;
		this.transportPaused = false;
		this._resumeOffset = 0;
		this._resumeGateAt = null; // precise first audible frame after manual pause
		this._transportHistory = [];
		this._lastPlayed = null;
		this._skipHistoryOnce = false;
		this.initPromise = this._loadCatalog();
	}

	async _loadCatalog() {
		try {
			const response = await fetch(this.catalogUrl);
			if (!response.ok) return false; // No music installed: existing synth stays in service.
			const parsed = normalizeCatalog(await response.json());
			this.catalog = parsed.tracks;
			// A fresh game begins with One More Run, including with shuffle enabled.
			const opening = this.catalog.findIndex(song => song.id === FIRST_SONG_ID);
			if (opening >= 0) this.trackIndex = opening;
			this.ready = this.catalog.length > 0;
			if (this.ready && this.onReady && !this.disposed) this.onReady();
			return this.ready;
		} catch {
			return false;
		}
	}

	attach(ctx, target) {
		if (this.ctx) return;
		this.ctx = ctx;
		this.bus = ctx.createGain();
		this.bus.connect(target);
		const lowMemory = typeof navigator !== 'undefined' &&
			Number.isFinite(navigator.deviceMemory) && navigator.deviceMemory <= 4;
		this.mixer = new StemFXMixer(ctx, this.bus, { roomQuality: lowMemory ? 'mobile' : 'standard' });
		this.mixer.selectBiome(this.biome);
		for (const name of CORE_STEMS) {
			const g = this.mixer.addSource(name, { gain: name === 'vocals' && !this.vocals ? 0 : 1 });
			this.gains.set(name, g);
		}
		// Optional 4x12 sources use only three additional reusable mixer buses.
		// Legacy packs do not create or play any alternate source.
		this.adaptive = new AdaptiveBiomeRouter(ctx, this.mixer,
			(index, path) => this._fetchAdaptiveSegment(index, path));
	}

	applySettings(settings) {
		if (!settings) return;
		this.musicCaptions = settings.musicCaptions === true;
		this.vocalGain = clamp(Number(settings.vocalGain ?? 1),0,1);
		this.melodyWithVocalsGain = clamp(Number(settings.melodyWithVocalsGain ?? 0.18),0,1);
		this.setVocals(settings.musicVocals === true);
		this.setSongSelection(settings.musicEnabledSongs);
		this.setShuffle(settings.musicShuffle === true);
		this.setDynamicOrchestra(settings.dynamicOrchestra === true);
	}

	setSongSelection(selection) {
		const selected = sanitizeSongSelection(selection);
		const changed = JSON.stringify(selected) !== JSON.stringify(this.songEnabled);
		this.songEnabled = selected;
		if (!changed) return;
		this._shuffleRemaining = [];
		this._nextIndex = null;
		this._nextPromise = null;
		if (this.transportPaused) {
			const next = nextEnabledSongIndex(this.catalog, this.songEnabled, -1);
			if(next<0){this.stop();return;}
			if(this.songEnabled[this.catalog[this.trackIndex]?.id]===false){
				this.trackIndex=next;
				this._resumeOffset=0;
			}
			return;
		}
		if (!this.started) return;
		const next = nextEnabledSongIndex(this.catalog, this.songEnabled, -1);
		if (next < 0) {
			// Crucially NO procedural fallback: the owner's all-off setting
			// means absolutely no music, while the SFX graph remains active.
			this.stop();
			return;
		}
		if (!this.track || this.songEnabled[this.track.id] === false) {
			this.stop();
			this.start();
		}
	}

	setDynamicOrchestra(on) {
		const next = on === true;
		if (next === this.dynamicOrchestra) return;
		this.dynamicOrchestra = next;
		// The user toggle governs *replacement recordings only*. All
		// processing of original stem audio (FX, room, speed and dynamics)
		// remains active in either mode and must not be rebuilt here.
		this.adaptive?.setEnabled(next && !this.menuMode);
	}

	setShuffle(on) {
		const next = on === true;
		if (this.shuffleEnabled === next) return;
		this.shuffleEnabled = next;
		this._shuffleRemaining = [];
		this._nextIndex = null;
		this._nextPromise = null;
	}

	/** Preserve the song clock while menus use unprocessed originals and Debutmont lead. */
	setMenuMode(on) {
		const next = on === true;
		if (this.menuMode === next) return;
		this.menuMode = next;
		if (next) {
			// Menus restore all three original accompaniments to clean DSP.
			this.setBsodDanger(0);
			this.setAirborne(false);
			this.setCombo(1);
			this.setSpeed(0);
		}
		this._refreshVoices();
		this.mixer?.selectBiome(next ? HOME_BIOME : this.biome);
		this.adaptive?.setBiome(next ? HOME_BIOME : this.biome);
		this.adaptive?.setEnabled(this.dynamicOrchestra && !next);
		this._applyMusicTimbres(true);
	}

	/** The real physical BSOD proximity drives only accompaniment corruption.
	 * The wind signal is independent and only AudioSynth reads airflow.
	 */
	setBsodDanger(proximity01) {
		this.bsodDanger = this.menuMode || !Number.isFinite(proximity01) ? 0 :
			Math.max(0, Math.min(1, proximity01));
		for (const stem of ['guitar','piano','other'])
			this.mixer?.setThreatLevel?.(stem, this.bsodDanger);
	}

	/** Original stem processing runs INDEPENDENTLY of the Dynamic
	 * Orchestra toggle: source-stem filtering, coloration, room sends,
	 * speed-dependent ducking and FX are all legitimate in OFF mode.
	 * The only mode-gated action is the AdaptiveBiomeRouter replacing
	 * an original instrumental source with its re-performed alternative.
	 * The separately synthesized biome melody stays active in BOTH modes.
	 */
	_applyMusicTimbres(force=false) {
		if (!this.mixer || !this.gains) return;
		const lead = this._activeVoiceFor(this.pack);
		const sourceNames = ['bass','drums','guitar','piano','other'];
		if (lead) sourceNames.push(lead);
		for (const name of sourceNames) {
			if (!this.gains.has(name)) continue;
			const effects = name===lead ? melodyPreset(this.menuMode ? 'debutmont' : this.biome) :
				this.menuMode ? [] : orchestraPreset(this.biome,name);
			const key = JSON.stringify(effects);
			if (force || this._timbreSignatures.get(name)!==key) {
				this.mixer.replaceEffects(name,effects,.18);
				this._timbreSignatures.set(name,key);
			}
			// Restore each source's normal biome room send in either
			// mode. Muting reverb when the toggle is OFF would wrongly
			// disable legitimate processing of the ORIGINAL recordings.
			this.mixer.setRoomSend(name,this.menuMode ? 0 : null);
		}
	}

	_nextEnabledIndex(previous = -1) {
		if (!this.shuffleEnabled || previous < 0)
			return nextEnabledSongIndex(this.catalog, this.songEnabled, previous);
		if (!this._shuffleRemaining?.length)
			this._shuffleRemaining = shuffledSongRound(this.catalog, this.songEnabled, previous);
		return this._shuffleRemaining[0] ?? -1;
	}

	_consumeShuffledIndex(index) {
		if (this.shuffleEnabled)
			this._shuffleRemaining = (this._shuffleRemaining || []).filter(i => i !== index);
	}

	setStemGain(name, gain) {
		if (!CORE_STEMS.includes(name) || name === 'vocals') return false;
		const level = clamp(Number(gain) || 0, 0, 1.5);
		this._stemUserLevels?.set(name, level);
		const changed = this.mixer?.setGain(name, level) || false;
		// Keep user-mix level consistent as an original stem is replaced.
		const featured = this.pack?.adaptive?.featuredStem;
		const alternate = name === 'bass' || name === 'drums' ? name :
			name === featured ? 'featured' :
			['guitar','piano','other'].includes(name) ? name : null;
		if (alternate) this.mixer?.setGain('adaptive:' + alternate, level);
		return changed;
	}

	setVocals(on) {
		this.vocals = !!on;
		this.mixer?.setGain('vocals', this.vocals ? (this.vocalGain ?? 1) : 0, { time: 0.03 });
		this._refreshVoices();
	}

	setBiome(id) {
		this.biome = typeof id === 'string' && id ? canonicalBiomeId(id) : HOME_BIOME;
		this._refreshVoices();
		this.mixer?.selectBiome(this.menuMode ? HOME_BIOME : this.biome);
		this.adaptive?.setBiome(this.menuMode ? HOME_BIOME : this.biome);
		this._applyMusicTimbres();
		if (this.started) this._pump();
	}

	_activeVoiceFor(pack) {
		const desired = voiceSourceForBiome(this.menuMode ? 'debutmont' : this.biome);
		if (pack?.sourceNames?.includes(desired)) return desired;
		// Until all mountain instruments are rendered, keep the home melody audible.
		const home = voiceSourceForBiome(HOME_BIOME);
		return pack?.sourceNames?.includes(home) ? home : null;
	}

	_refreshVoices() {
		if (!this.mixer) return;
		const active = this._activeVoiceFor(this.pack);
		for (const name of this.gains.keys()) {
			if (!name.startsWith('voice:')) continue;
			// Maxi's real voice replaces most of the synthetic melodic lead when enabled.
			this.mixer.setGain(name,name === active ?
				(this.vocals ? (this.melodyWithVocalsGain ?? .18) : 1) : 0,
				{ time: 0.22 });
		}
	}

	setAirborne(airborne) {
		const next = !this.menuMode && !!airborne;
		if (next === this.airborne) return;
		this.airborne = next;
		// New adaptive packs crossfade full original drums with an actual
		// airborne kit. The legacy 0.58 airborne duck remains unchanged.
		// Airborne ducking applies to the ORIGINAL stem regardless
		// of orchestra mode or availability of alternate kit assets.
		this.mixer?.setGain('drums', this.airborne ? .22 : 1,
			{ motion: true, time: .15 });
		// Actual alternate air drums also soften rather than becoming
		// a permanent full-volume replacement under a low source bed.
		this.mixer?.setGain('adaptive:drums', this.airborne ? .38 : 1,
			{ motion: true, time: .15 });
		this.adaptive?.setAirborne(this.airborne);
		if (this.started) this._pump();
	}

	setSpeed(speedPxS) {
		if (this.menuMode) speedPxS = 0;
		// Effects marked speed-filter react without altering source playback rate.
		const normalized = clamp((Number(speedPxS) || 0) / 1000, 0, 1);
		this.mixer?.setEffectParam('other', 'speed-filter', 'frequency', 400 + normalized * 15000);
		this.speedPxS = Math.max(0, Number(speedPxS)||0);
		const speedGain = this.menuMode ? 1 : clamp(.2+this.speedPxS/850,.2,1.18);
		this.mixer?.setGain('bass',speedGain,{motion:true,time:.16});
		this.mixer?.setGain('adaptive:bass',speedGain,{motion:true,time:.16});
		this.adaptive?.setSpeed(speedPxS);
	}

	setCombo(multiplier = 1) {
		if (this.menuMode) multiplier = 1;
		const level = clamp(1 + (Number(multiplier) - 1) * 0.05, 0.8, 1.25);
		this.mixer?.setGain('other', level, { motion: true, time: 0.09 });
		if (this.pack?.adaptive) {
			const role=this.pack.adaptive.featuredStem === 'other' ? 'featured' : 'other';
			this.mixer?.setGain('adaptive:'+role, level, { motion: true, time: 0.09 });
		}
	}

	getEnergy() { return this.mixer?.energy() || { bass: 0, mid: 0, treble: 0 }; }

	currentCaption() {
		if (!this.musicCaptions || !this.pack || this.clockStart === null || !this.ctx) return null;
		return captionAt(this.captionWords, this.ctx.currentTime - this.clockStart);
	}

	nextBeat() {
		if (!this.pack || !this.ctx || this.clockStart === null) return 0;
		return nextBeatTime(this.clockStart, Math.max(0, this.ctx.currentTime - this.clockStart), this.pack.bpm);
	}

	_wantedNames(pack) {
		const names = [...CORE_STEMS];
		const voice = this._activeVoiceFor(pack);
		if (voice) names.push(voice);
		for (const name of Object.keys(pack?.layers || {})) {
			if (!names.includes(name)) names.push(name);
		}
		return names;
	}

	start() {
		if (this.disposed || !this.ready) return false;
		const first = this._nextEnabledIndex(-1);
		if (first < 0) { this.stop(); return false; }
		if (!this.catalog[this.trackIndex] ||
			this.songEnabled[this.catalog[this.trackIndex].id] === false)
			this.trackIndex = first;
		this.transportPaused = false;
		this.started = true;
		if (this.bus && this.ctx) this.bus.gain.setTargetAtTime(1, this.ctx.currentTime, 0.025);
		this._ensureRunning();
		return true;
	}

	onResume() {
		if (this.started) this._ensureRunning();
	}

	_ensureRunning() {
		if (!this.started || !this.ctx || this.ctx.state !== 'running') return;
		const next = this._nextEnabledIndex(-1);
		if (next < 0) { this.stop(); return; }
		if (!this.pack && !this._loading) {
			const index = this.songEnabled[this.catalog[this.trackIndex]?.id] !== false
				? this.trackIndex : next;
			const offset=this._resumeOffset;
			this._resumeOffset=0;
			const pending=this._beginTrack(index,null,offset);
			this._loading=pending;
			pending.finally(()=>{if(this._loading===pending)this._loading=null;});
		}
		if (!this._timer) this._timer = setInterval(() => { this._pump(); }, 75);
	}

	async _getTrack(index) {
		const track = this.catalog[index % this.catalog.length];
		const catalogBase = new URL(this.catalogUrl, window.location.href);
		const manifestUrl = resolveMusicAsset(catalogBase, track.manifest);
		const response = await fetch(manifestUrl);
		if (!response.ok) throw new Error('Cannot load music pack: ' + track.id);
		const pack = normalizePack(await response.json());
		if (pack.id !== track.id) throw new Error('Music pack ID mismatch');
		return { track, pack, base: manifestUrl };
	}

	async _preloadTrack(index) {
		const info = await this._getTrack(index);
		const buffers = new Map();
		await Promise.all(this._wantedNames(info.pack).map(async (name) => {
			const relative = info.pack.segments[0].sources[name];
			const response = await fetch(resolveMusicAsset(info.base, relative));
			if (!response.ok) throw new Error('Missing first segment: ' + name);
			const buffer = await this.ctx.decodeAudioData(await response.arrayBuffer());
			buffers.set('0/' + name, buffer);
		}));
		return { ...info, buffers };
	}

	async _fetchSource(info, segmentIndex, sourceName, token) {
		const seg = info.pack.segments[segmentIndex];
		const relative = seg && seg.sources[sourceName];
		if (!relative || token !== this._token) return null;
		const key = String(segmentIndex) + '/' + sourceName;
		if (this.cache.has(key)) return this.cache.get(key);
		if (this.inflight.has(key)) return this.inflight.get(key);
		const promise = (async () => {
			const response = await fetch(resolveMusicAsset(info.base, relative));
			if (!response.ok) throw new Error('Missing stem ' + sourceName + ' in ' + info.track.id);
			const compressed = await response.arrayBuffer();
			const buffer = await this.ctx.decodeAudioData(compressed);
			if (token === this._token && !this.disposed) this.cache.set(key, buffer);
			return buffer;
		})();
		this.inflight.set(key, promise);
		try { return await promise; }
		finally { if (this.inflight.get(key) === promise) this.inflight.delete(key); }
	}

	// Biome assets are in the optional adaptive manifest map, not the 48
	// permanent segment sources. Cache by segment AND relative asset path;
	// source identity remains stable through biome switches.
	_syncAdaptiveUserLevels() {
		if (!this.pack?.adaptive || !this.mixer) return;
		const level = name => this._stemUserLevels?.get(name) ?? 1;
		this.mixer.setGain('adaptive:bass', level('bass'));
		this.mixer.setGain('adaptive:drums', level('drums'));
		this.mixer.setGain('adaptive:featured', level(this.pack.adaptive.featuredStem));
		for (const stem of ['guitar','piano','other']) {
			if (stem!==this.pack.adaptive.featuredStem)
				this.mixer.setGain('adaptive:'+stem,level(stem));
		}
	}

	async _fetchAdaptiveSegment(index, path) {
		const token = this._token;
		if (!this.pack || this.clockStart === null || !this.pack.adaptive) return null;
		const key = String(index) + '/adaptive:' + path;
		if (this.cache.has(key)) return this.cache.get(key);
		if (this.inflight.has(key)) return this.inflight.get(key);
		const promise = (async () => {
			const response = await fetch(resolveMusicAsset(this.packBase, path));
			if (!response.ok) throw new Error('Missing optional adaptive source');
			const buffer = await this.ctx.decodeAudioData(await response.arrayBuffer());
			if (token === this._token && !this.disposed) this.cache.set(key, buffer);
			return buffer;
		})();
		this.inflight.set(key, promise);
		try { return await promise; }
		finally { if (this.inflight.get(key) === promise) this.inflight.delete(key); }
	}

	async _beginTrack(index, desiredAt, offsetSeconds=0) {
		if (index < 0 || !this.catalog[index] ||
			this.songEnabled[this.catalog[index].id] === false) {
			if (this._nextEnabledIndex(-1) < 0) this.stop();
			return;
		}
		const token = ++this._token;
		this.cache.clear();
		this.inflight.clear();
		this.scheduled.clear();
		try {
			const info = this._nextIndex === index && this._nextPromise
				? await this._nextPromise : await this._getTrack(index);
			if (token !== this._token || this.disposed) return;
			if (!info) throw new Error('Next track could not be prepared');
			if (this.songEnabled[info.track.id] === false) {
				const next = this._nextEnabledIndex(-1);
				if (next < 0) this.stop();
				else if (next !== index) this._beginTrack(next, null);
				return;
			}
			// Record history when a track actually begins, not when a stale
			// async request *intended* to begin one.
			if(this.track?.id && this.track.id!==info.track.id){
				this._lastPlayed={id:this.track.id,title:this.track.title};
				if(!this._skipHistoryOnce){
					this._transportHistory.push({id:this.track.id,title:this.track.title});
					if(this._transportHistory.length>12)this._transportHistory.shift();
				}
			}
			this._skipHistoryOnce=false;
			this.pack = info.pack;
			this.track = info.track;
			this.packBase = info.base;
			this.trackIndex = index;
			this._consumeShuffledIndex(index);
			this.captionWords = [];
			for (const name of info.pack.sourceNames) {
				if (!this.gains.has(name)) {
					const initialGain = name.startsWith('voice:') ? 0 : CORE_STEMS.includes(name) ? 1 : 0;
					this.gains.set(name, this.mixer.addSource(name, { gain: initialGain }));
				}
				const effects = info.pack.effects[name] || [];
				const signature = JSON.stringify(effects);
				const previous = this._effectSignatures.get(name);
				if (previous !== signature) {
					this._effectSignatures.set(name, signature);
					// Default-empty chains already exist when a source is added.
					if (effects.length || (previous && previous !== '[]')) {
						this.mixer.replaceEffects(name, effects);
					}
				}
			}
			for (const name of info.pack.sourceNames) {
				this.mixer.setRoomSend(name, info.pack.roomSends[name]);
			}
			for (const [name, level] of Object.entries(info.pack.layers)) {
				this.mixer.setGain(name, level, { time: 0.1 });
			}
			this._refreshVoices();
			this._timbreSignatures.clear();
			this._applyMusicTimbres(true);
			if (info.pack.captions) this._loadCaptions(info, token);
			this._nextPromise = null;
			this._nextIndex = null;
			if (info.buffers) {
				for (const [key, buffer] of info.buffers) this.cache.set(key, buffer);
			} else {
				await Promise.all(this._wantedNames(info.pack).map((s) => this._fetchSource(info, 0, s, token)));
			}
			if (token !== this._token || this.disposed) return;
			const actualResumeOffset=clamp(Number(offsetSeconds)||0,0,
				Math.max(0,this.pack.duration-.1));
			const firstSourceTime=Math.max(this.ctx.currentTime+.12,desiredAt||0);
			this.clockStart=firstSourceTime-actualResumeOffset;
			// For normal track-start this is a no-op. For a manual pause resume,
			// offsets MUST begin on this first sound frame, never 100ms before it
			// just because buffers were fetched early in the WebAudio scheduler.
			this._resumeGateAt=actualResumeOffset>0 ? firstSourceTime : null;
			this.adaptive?.configure(this.pack, this.clockStart,
				{ biome: this.menuMode ? HOME_BIOME : this.biome, airborne: this.airborne });
			this.adaptive?.setEnabled(this.dynamicOrchestra && !this.menuMode);
			this._syncAdaptiveUserLevels();
			this.mixer?.setGain('drums',this.airborne ? .22 : 1,
				{ motion:true,time:.15 });
			this.mixer?.setGain('adaptive:drums',this.airborne ? .38 : 1,
				{ motion:true,time:.15 });
			this.setSpeed(this.speedPxS);
			this._pump();
			if (this.onTrackStarted) this.onTrackStarted({
				id: this.track.id, title: this.track.title, index: this.trackIndex,
			});
		} catch (e) {
			if (token === this._token) {
				this.pack = null;
				this.lastError = String(e);
				this.started = false;
				if (this._timer) clearInterval(this._timer);
				this._timer = null;
				if (this.audio && this.audio.musicProviderFailed) this.audio.musicProviderFailed();
			}
		}
	}

	async _loadCaptions(info, token) {
		try {
			const response = await fetch(resolveMusicAsset(info.base, info.pack.captions));
			if (!response.ok) return;
			const parsed = normalizeCaptions(await response.json(), info.pack.duration);
			if (token === this._token && !this.disposed) this.captionWords = parsed.words;
		} catch { /* Missing/bad captions never silence the music. */ }
	}

	_scheduleSource(i, name, buffer) {
		const key = String(i) + '/' + name;
		if (!this.pack || !this.ctx || this.scheduled.has(key) || !buffer) return;
		const seg = this.pack.segments[i];
		const desired = this.clockStart + seg.startFrame / this.pack.sampleRate;
		const duration = seg.frames / this.pack.sampleRate;
		const now = this.ctx.currentTime;
		const firstAllowed=Math.max(desired,now+.02,this._resumeGateAt??0);
		const late = Math.max(0,firstAllowed-desired);
		if (late >= duration) { this.scheduled.add(key); return; }
		const dest = this.gains.get(name);
		if (!dest) return;
		const src = this.ctx.createBufferSource();
		src.buffer = buffer;
		src.connect(dest);
		this.activeNodes.add(src);
		src.onended = () => {
			this.activeNodes.delete(src);
			try { src.disconnect(); } catch {}
		};
		try {
			src.start(firstAllowed, late,
				Math.max(0.001, Math.min(duration-late,buffer.duration-late)));
			this.scheduled.add(key);
		} catch (e) {
			this.activeNodes.delete(src);
			try { src.disconnect(); } catch {}
			this.lastError = 'Schedule failed: ' + String(e);
		}
	}

	_pump() {
		if (!this.started || !this.pack || !this.ctx || this.ctx.state !== 'running' ||
			this.clockStart === null) return;
		const now = this.ctx.currentTime;
		const elapsed = now - this.clockStart;
		const duration = this.pack.duration;
		if (elapsed > duration - 15 && !this._nextPromise) {
			this._nextIndex = this._nextEnabledIndex(this.trackIndex);
			if (this._nextIndex >= 0)
				this._nextPromise = this._preloadTrack(this._nextIndex).catch(() => null);
		}
		if (elapsed >= duration - 0.5) {
			if (!this._loading) {
				const nextIndex = this._nextEnabledIndex(this.trackIndex);
				if (nextIndex < 0) { this.stop(); return; }
				const pending=this._beginTrack(nextIndex,this.clockStart+duration);
				this._loading=pending;
				pending.finally(()=>{if(this._loading===pending)this._loading=null;});
			}
			return;
		}
		const info = { track: this.track, pack: this.pack, base: this.packBase };
		const token = this._token;
		this.adaptive?.pump();
		for (let i = 0; i < this.pack.segments.length; i++) {
			const seg = this.pack.segments[i];
			const begin = this.clockStart + seg.startFrame / this.pack.sampleRate;
			const end = begin + seg.frames / this.pack.sampleRate;
			if (end < now - 0.2) {
				const prefix = String(i) + '/';
				for (const key of this.cache.keys()) {
					if (key.startsWith(prefix)) this.cache.delete(key);
				}
				continue;
			}
			if (begin > now + 8) break;
			for (const name of this._wantedNames(this.pack)) {
				if (this.scheduled.has(String(i) + '/' + name)) continue;
				const cached = this.cache.get(String(i) + '/' + name);
				if (cached) this._scheduleSource(i, name, cached);
				else sleepSafe(this._fetchSource(info, i, name, token));
			}
		}
	}

	/** One canonical transport for Title, Pause, and Game-Over. These
	 * screens never instantiate a second audio player or own a playback
	 * clock. Browser AudioContext suspension is distinct from user pause.
	 */
	transportSnapshot() {
		const enabled=enabledSongIndices(this.catalog,this.songEnabled);
		const current=this.catalog[this.trackIndex]||null;
		const index=enabled.includes(this.trackIndex) ? this.trackIndex : enabled[0];
		const upcoming=[];
		if(enabled.length && index!==undefined){
			if (this.shuffleEnabled) {
				this._nextEnabledIndex(index);
				for (const next of (this._shuffleRemaining || []).slice(0,2))
					upcoming.push(this.catalog[next]);
			} else {
				let cursor=enabled.indexOf(index);
				for(let i=0;i<Math.min(2,enabled.length);i++){
					cursor=(cursor+1)%enabled.length;
					upcoming.push(this.catalog[enabled[cursor]]);
				}
			}
		}
		return {
			state:!enabled.length?'stopped':
				this.transportPaused?'paused':
				this.started?(this.pack?'playing':'loading'):'stopped',
			current: enabled.length ? (current||this.track) : null,
			previous:this._lastPlayed||this._transportHistory.at(-1)||null,
			upcoming,
			position:this.transportPaused?this._resumeOffset:
				this.started&&this.ctx&&this.clockStart!==null?
					// A manually resumed source is scheduled slightly in the future.
					// Don't show its saved position moving BACKWARD during that silent
					// pre-start window; audio itself already has the exact-frame gate.
					Math.max(0,Math.max(this.ctx.currentTime,
						this._resumeGateAt??this.ctx.currentTime)-this.clockStart):0,
			audioSuspended:this.ctx?.state==='suspended',
		};
	}

	transportPause() {
		if(!this.started)return false;
		const position=this.pack&&this.ctx&&this.clockStart!==null?
			clamp(this.ctx.currentTime-this.clockStart,0,
				Math.max(0,this.pack.duration-.1)):0;
		this.stop();
		this._resumeOffset=position;
		this.transportPaused=true;
		return true;
	}

	transportPlay() {
		if(this.disposed||!this.ready||this._nextEnabledIndex(-1)<0)
			return false;
		if(this.started)return true;
		return this.start();
	}

	/** Previous takes the actual last-played song where possible; if
	 * there is no history, wrap to the preceding enabled playlist slot.
	 * Paused intent is retained across skips; only Play resumes sound.
	 */
	transportStep(direction) {
		if(this.disposed||!this.ready)return false;
		const enabled=enabledSongIndices(this.catalog,this.songEnabled);
		if(!enabled.length){this.stop();return false;}
		const wasPaused=this.transportPaused;
		const current=enabled.includes(this.trackIndex)?
			enabled.indexOf(this.trackIndex):0;
		let target;
		if(direction<0){
			while(this._transportHistory.length){
				const previous=this._transportHistory.pop();
				const found=this.catalog.findIndex(t=>t.id===previous.id);
				if(enabled.includes(found)){target=found;break;}
			}
			if(target===undefined)target=enabled[(current+enabled.length-1)%enabled.length];
			this._skipHistoryOnce=true;
		}else{
			target=this.shuffleEnabled ? this._nextEnabledIndex(this.trackIndex) :
				enabled[(current+1)%enabled.length];
			this._skipHistoryOnce=false;
		}
		this.stop();
		this.trackIndex=target;
		this._resumeOffset=0;
		if(wasPaused){this.transportPaused=true;return true;}
		return this.start();
	}

	/** Real-engine passage seek used by the in-game lab.
	 * This changes the actual WebAudio clock anchor, invalidates pending
	 * network/decoder requests, and reconfigures adaptive replacement
	 * instruments at the same sample position. Never creates a second
	 * score or playback engine. It does not affect persistent settings.
	 */
	seekTo(seconds) {
		if (!this.started || !this.pack || !this.ctx ||
			this.ctx.state !== 'running') return false;
		if (!Number.isFinite(seconds)) return false;
		const position = clamp(seconds, 0, Math.max(0, this.pack.duration-0.1));
		const t = this.ctx.currentTime;
		this.bus.gain.cancelScheduledValues(t);
		this.bus.gain.setTargetAtTime(0,t,.007);
		++this._token; // all older fetches are now stale
		for(const src of this.activeNodes){
			try {src.stop(t+.014);} catch {}
		}
		this.activeNodes.clear();
		this.scheduled.clear();
		this.inflight.clear();
		this._nextPromise=null;
		this._nextIndex=null;
		this.clockStart=t+.085-position;
		this._resumeGateAt=null; // an explicit seek owns a separate transport generation
		this.adaptive?.reset();
		this.adaptive?.configure(this.pack,this.clockStart,{
			biome:this.menuMode ? HOME_BIOME : this.biome,airborne:this.airborne,
		});
		this.adaptive?.setEnabled(this.dynamicOrchestra && !this.menuMode);
		this._syncAdaptiveUserLevels();
		this.bus.gain.setTargetAtTime(1,t+.045,.018);
		this._pump();
		return true;
	}

	stop() {
		this.started = false;
		this.transportPaused=false;
		this._resumeOffset=0;
		this._resumeGateAt=null;
		this._token++;
		if (this._timer) clearInterval(this._timer);
		this._timer = null;
		this._loading = null;
		this.adaptive?.reset();
		this.pack = null;
		this.clockStart = null;
		this.cache.clear();
		this.scheduled.clear();
		this._nextPromise = null;
		this._nextIndex = null;
		this.captionWords = [];
		// Stop queued sources, not just the timer: otherwise a rapid restart resurrects old audio.
		const now = this.ctx?.currentTime || 0;
		if (this.bus && this.ctx) this.bus.gain.setTargetAtTime(0, now, 0.01);
		for (const src of this.activeNodes) { try { src.stop(now + 0.04); } catch {} }
		this.activeNodes.clear();
	}

	destroy() {
		this.disposed = true;
		this.stop();
		this.adaptive?.destroy();
		this.mixer?.destroy();
		if (this.bus) this.bus.disconnect();
	}
}/** Explicitly fake, SOURCE-UNVERIFIED 4/4 meter for optional COSMETIC uses.
 * 0.5s is inherited from the previously shipped fatal crash count-in.
 * The beat and measure origin are the original recording's t=0, NOT an
 * established musical first beat or true bar line. No gameplay timing.
 */
export const SYNTHETIC_BEAT_SECONDS=.5;
export const SYNTHETIC_BEATS_PER_MEASURE=4;
export const SYNTHETIC_METER_KIND='synthetic-unverified';

/** Pure source-transport calculation. It NEVER verifies musical structure. */
export function syntheticMeterAt(positionSeconds,{
  beatSeconds=SYNTHETIC_BEAT_SECONDS,
  beatsPerMeasure=SYNTHETIC_BEATS_PER_MEASURE,
  durationSeconds=Infinity,
}={}){
  if(!Number.isFinite(positionSeconds)||positionSeconds<0||
    !Number.isFinite(beatSeconds)||beatSeconds<.25||beatSeconds>2||
    !Number.isSafeInteger(beatsPerMeasure)||beatsPerMeasure<2||beatsPerMeasure>12||
    !(durationSeconds===Infinity||Number.isFinite(durationSeconds)&&durationSeconds>0)||
    positionSeconds>=durationSeconds)return null;
  // Epsilon avoids classifying a boundary as the previous beat from float
  // rounding; note that all values still belong to an UNVERIFIED meter.
  const beatIndex=Math.floor(positionSeconds/beatSeconds+1e-8);
  const measureIndex=Math.floor(beatIndex/beatsPerMeasure);
  const beatInMeasure=beatIndex%beatsPerMeasure+1;
  const measureSeconds=beatSeconds*beatsPerMeasure;
  const beatStartSeconds=beatIndex*beatSeconds;
  const measureStartSeconds=measureIndex*measureSeconds;
  const nextBeatSeconds=(beatIndex+1)*beatSeconds;
  const nextMeasureStartSeconds=(measureIndex+1)*measureSeconds;
  return Object.freeze({
    trusted:false,timingKind:SYNTHETIC_METER_KIND,
    use:'cosmetic-only',canAuthorizeGameplay:false,
    assumedMeter:'4/4-synthetic',
    sourceTimeSeconds:positionSeconds,
    beatSeconds,beatsPerMeasure,measureSeconds,
    beatIndex,beatInMeasure,measureIndex,
    beatStartSeconds,measureStartSeconds,
    nextBeatSeconds,nextMeasureStartSeconds,
    isMeasureStartBeat:beatInMeasure===1,
    // Convenience for consumers polling <=25Hz; use measureIndex transitions
    // for exactly-once triggering instead of trusting this flag as an event.
    atMeasureStart:beatInMeasure===1&&
      positionSeconds-measureStartSeconds<=.05,
  });
}/** One short, reversible, music-volume-governed turntable gesture.
 * Distinct from the actual stem transport: one-shot synthesized vinyl noise,
 * never a second music player or a recording of copyrighted audio.
 * Connect ONLY to AudioSynth's music bus (not the SFX bus) so soundtrack
 * mute, music slider and master volume apply. No external assets required.
 */
export const VINYL_SCRATCH_SECONDS = 0.205;
const clip = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

export class TurntableScratch {
  constructor(ctx, noiseBuffer, musicBus) {
    this.ctx = ctx;
    this.noiseBuffer = noiseBuffer;
    this.musicBus = musicBus;
    this._active = null;
    this._generation = 0;
    this.disposed = false;
  }

  /** Abort all still-scheduled one-shot nodes when a transition changes. */
  cancel() {
    ++this._generation;
    const active = this._active;
    this._active = null;
    if (!active) return;
    const now = this.ctx?.currentTime ?? 0;
    for (const source of active.sources) {
      try { source.stop(now); } catch { /* already stopped */ }
    }
    for (const node of active.nodes) {
      try { node.disconnect(); } catch { /* detached */ }
    }
  }

  /** Returns the one-shot's duration, or zero when audio is unavailable. */
  play(direction, volume = 1) {
    this.cancel();
    if (this.disposed || !this.ctx ||
        (this.ctx.state !== 'running' && typeof this.ctx.startRendering !== 'function') ||
        !this.noiseBuffer || !this.musicBus ||
        !['pause','resume'].includes(direction) || !(volume > 0)) return 0;
    try {
      const c = this.ctx;
      const t = c.currentTime;
      const duration = VINYL_SCRATCH_SECONDS;
      const v = clip(Number(volume) || 0, 0, 1);
      // One reusable design with opposite pitch/speed envelopes.
      const descending = direction === 'pause';
      const source = c.createBufferSource();
      source.buffer = this.noiseBuffer;
      source.loop = false;
      const filter = c.createBiquadFilter();
      filter.type = 'bandpass';
      filter.Q.value = 0.85;
      const scratch = c.createGain();
      scratch.gain.setValueAtTime(0, t);
      scratch.gain.linearRampToValueAtTime(0.15 * v, t + .012);
      scratch.gain.linearRampToValueAtTime(0.105 * v, t + .102);
      scratch.gain.linearRampToValueAtTime(0, t + duration);
      const rateStart = descending ? 1.9 : 0.46;
      const rateEnd = descending ? 0.46 : 1.9;
      source.playbackRate.setValueAtTime(rateStart, t);
      source.playbackRate.exponentialRampToValueAtTime(rateEnd, t + duration);
      filter.frequency.setValueAtTime(descending ? 3900 : 590, t);
      filter.frequency.exponentialRampToValueAtTime(descending ? 590 : 3900,
        t + duration);
      source.connect(filter);
      filter.connect(scratch);
      scratch.connect(this.musicBus);
      // A quiet, low-pitched platter drag adds body without a shrill screech.
      const tone = c.createOscillator();
      tone.type = 'triangle';
      tone.frequency.setValueAtTime(descending ? 310 : 85, t);
      tone.frequency.exponentialRampToValueAtTime(descending ? 85 : 310,
        t + duration);
      const tonalGain = c.createGain();
      tonalGain.gain.setValueAtTime(0, t);
      tonalGain.gain.linearRampToValueAtTime(0.026 * v, t + .014);
      tonalGain.gain.linearRampToValueAtTime(0.014 * v, t + .095);
      tonalGain.gain.linearRampToValueAtTime(0, t + duration);
      tone.connect(tonalGain);
      tonalGain.connect(this.musicBus);
      const token = this._generation;
      const active = { token, direction,
        sources: [source, tone], nodes: [source, filter, scratch, tone, tonalGain] };
      this._active = active;
      tone.onended = () => {
        if (this._active === active) this._active = null;
        for (const node of active.nodes) {
          try { node.disconnect(); } catch { /* ignore */ }
        }
      };
      // Nonlooping noise source is explicitly stopped; no orphaned oscillators.
      source.start(t, .3);
      source.stop(t + duration + .003);
      tone.start(t);
      tone.stop(t + duration + .003);
      return duration;
    } catch {
      this.cancel();
      return 0;
    }
  }

  destroy() {
    this.cancel();
    this.disposed = true;
    this.musicBus = null;
    this.noiseBuffer = null;
    this.ctx = null;
  }
}/**
 * Tier B frame-fingerprint primitives for Replay Contract v1 (docs/replay/replay-contract-v1.md, sections 3.2, 6.5).
 *
 *  - xxh32Bytes / xxh32x2: XXH32 over raw bytes (a bytes twin of Rng.js's string xxHash32, which stays untouched
 *    because ledger hashes depend on it) and the 64-bit `xxh32x2` pair (seeds 0 and 0x9E3779B9).
 *  - FpWriter: the BB-FP v1 little-endian binary encoder (the bytes that get hashed), with range checks.
 *  - combineFingerprints: the per-frame combined digest over per-subsystem digests.
 *
 * Fingerprints are drift detectors, never proofs: XXH32 is not collision resistant against an adversary.
 * Pure module: no Phaser, no clock, no randomness.
 */
import { asUint8Array, utf8Encode } from './canonicalJson.js';

const P1 = 2654435761;
const P2 = 2246822519;
const P3 = 3266489917;
const P4 = 668265263;
const P5 = 374761393;
const rotl = (x, r) => ((x << r) | (x >>> (32 - r))) >>> 0;

export const FP_VERSION = 1;
export const FP_SEED_A = 0x00000000;
export const FP_SEED_B = 0x9e3779b9;
export const FP_PREFIX = 'xxh32x2:';
const FP_DIGEST_RE = /^xxh32x2:[0-9a-f]{16}$/;

const hex8 = (n) => (n >>> 0).toString(16).padStart(8, '0');

/**
 * XXH32 of raw bytes.
 * @param {Uint8Array|ArrayBuffer} input
 * @param {number} [seed=0] 32-bit seed
 * @returns {number} unsigned 32-bit
 * @throws {TypeError} for anything that is not a Uint8Array/ArrayBuffer
 */
export function xxh32Bytes(input, seed = 0) {
  const b = asUint8Array(input, 'xxh32Bytes'); // Uint8Array/Buffer/ArrayBuffer only; other views would hash wrongly
  const len = b.length;
  seed >>>= 0;
  const lane = (i) => (b[i] | (b[i + 1] << 8) | (b[i + 2] << 16) | (b[i + 3] << 24)) >>> 0;
  let p = 0;
  let h;
  if (len >= 16) {
    let v1 = (seed + P1 + P2) >>> 0;
    let v2 = (seed + P2) >>> 0;
    let v3 = seed;
    let v4 = (seed - P1) >>> 0;
    const limit = len - 16;
    while (p <= limit) {
      v1 = Math.imul(rotl((v1 + Math.imul(lane(p), P2)) >>> 0, 13), P1) >>> 0;
      v2 = Math.imul(rotl((v2 + Math.imul(lane(p + 4), P2)) >>> 0, 13), P1) >>> 0;
      v3 = Math.imul(rotl((v3 + Math.imul(lane(p + 8), P2)) >>> 0, 13), P1) >>> 0;
      v4 = Math.imul(rotl((v4 + Math.imul(lane(p + 12), P2)) >>> 0, 13), P1) >>> 0;
      p += 16;
    }
    h = (rotl(v1, 1) + rotl(v2, 7) + rotl(v3, 12) + rotl(v4, 18)) >>> 0;
  } else {
    h = (seed + P5) >>> 0;
  }
  h = (h + len) >>> 0;
  while (p + 4 <= len) {
    h = (h + Math.imul(lane(p), P3)) >>> 0;
    h = Math.imul(rotl(h, 17), P4) >>> 0;
    p += 4;
  }
  while (p < len) {
    h = (h + Math.imul(b[p], P5)) >>> 0;
    h = Math.imul(rotl(h, 11), P1) >>> 0;
    p++;
  }
  h ^= h >>> 15;
  h = Math.imul(h, P2) >>> 0;
  h ^= h >>> 13;
  h = Math.imul(h, P3) >>> 0;
  h ^= h >>> 16;
  return h >>> 0;
}

/**
 * 64-bit fingerprint body: `hex8(XXH32(bytes, 0)) + hex8(XXH32(bytes, 0x9E3779B9))` (16 lowercase hex, no prefix).
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function xxh32x2(bytes) {
  return hex8(xxh32Bytes(bytes, FP_SEED_A)) + hex8(xxh32Bytes(bytes, FP_SEED_B));
}

/**
 * Tier B fingerprint string: `xxh32x2:` + 16 lowercase hex.
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function fingerprintOf(bytes) {
  return FP_PREFIX + xxh32x2(bytes);
}

/**
 * BB-FP v1 binary encoder (section 6.5). Little-endian, schema-driven (field names are not encoded), no padding, no
 * tags. Callers write `u32 schemaVersion` first, then fields in schema order. Growable; reusable via reset().
 * Atomic per call: every method validates before writing, and opt()/list() roll back everything they wrote if the
 * element callback throws, so a throw never leaves a partial field behind (a caller that has already written earlier
 * fields of a record should still reset() and discard that record).
 */
export class FpWriter {
  /** @param {number} [capacity=256] initial buffer size in bytes */
  constructor(capacity = 256) {
    this.buf = new Uint8Array(Math.max(16, capacity | 0));
    this.view = new DataView(this.buf.buffer);
    this.len = 0;
  }

  /** Bytes written so far. */
  get length() {
    return this.len;
  }

  /** Discard written bytes and keep the buffer. @returns {this} */
  reset() {
    this.len = 0;
    return this;
  }

  _need(n) {
    const want = this.len + n;
    if (want <= this.buf.length) return;
    let cap = this.buf.length;
    while (cap < want) cap *= 2;
    const next = new Uint8Array(cap);
    next.set(this.buf.subarray(0, this.len));
    this.buf = next;
    this.view = new DataView(next.buffer);
  }

  /** @param {number} v integer 0..2^32-1 @returns {this} */
  u32(v) {
    if (typeof v !== 'number' || !Number.isInteger(v) || v < 0 || v > 0xffffffff) {
      throw new RangeError(`FpWriter.u32: ${String(v)} is not an integer in [0, 4294967295]`);
    }
    this._need(4);
    this.view.setUint32(this.len, v, true);
    this.len += 4;
    return this;
  }

  /** @param {number} v integer -2^31..2^31-1 @returns {this} */
  i32(v) {
    if (typeof v !== 'number' || !Number.isInteger(v) || v < -2147483648 || v > 2147483647) {
      throw new RangeError(`FpWriter.i32: ${String(v)} is not an integer in [-2147483648, 2147483647]`);
    }
    this._need(4);
    this.view.setInt32(this.len, v, true);
    this.len += 4;
    return this;
  }

  /**
   * IEEE-754 bits as is (keeps -0 and +-Infinity); every NaN becomes 0x7ff8000000000000.
   * @param {number} v
   * @returns {this}
   */
  f64(v) {
    if (typeof v !== 'number') throw new TypeError(`FpWriter.f64: expected number, got ${typeof v}`);
    this._need(8);
    if (Number.isNaN(v)) {
      this.view.setUint32(this.len, 0, true);
      this.view.setUint32(this.len + 4, 0x7ff80000, true);
    } else this.view.setFloat64(this.len, v, true);
    this.len += 8;
    return this;
  }

  /** @param {boolean} v strictly true/false @returns {this} */
  bool(v) {
    if (typeof v !== 'boolean') throw new TypeError(`FpWriter.bool: expected boolean, got ${typeof v}`);
    this._need(1);
    this.buf[this.len++] = v ? 1 : 0;
    return this;
  }

  /** `u32` UTF-8 byte length + bytes. Lone surrogates throw. @param {string} s @returns {this} */
  str(s) {
    if (typeof s !== 'string') throw new TypeError(`FpWriter.str: expected string, got ${typeof s}`);
    let b;
    try {
      b = utf8Encode(s);
    } catch {
      throw new RangeError('FpWriter.str: string contains a lone surrogate'); // same error family as the other writers
    }
    this.u32(b.length);
    this._need(b.length);
    this.buf.set(b, this.len);
    this.len += b.length;
    return this;
  }

  /**
   * `opt<T>`: presence byte, then the value if present. Absent means exactly `null` (undefined is a bug and throws).
   * @param {*} v
   * @param {(w: FpWriter, v: *) => void} writeFn writes one T
   * @returns {this}
   */
  opt(v, writeFn) {
    if (v === undefined) throw new TypeError('FpWriter.opt: undefined is not a valid optional (use null)');
    this._need(1);
    const start = this.len;
    if (v === null) {
      this.buf[this.len++] = 0;
    } else {
      this.buf[this.len++] = 1;
      try {
        writeFn(this, v);
      } catch (e) {
        this.len = start; // no partial record after a throw
        throw e;
      }
    }
    return this;
  }

  /**
   * `list<T>`: `u32` count, then the elements.
   * @param {ArrayLike<*>} arr
   * @param {(w: FpWriter, v: *, i: number) => void} writeFn writes one T
   * @returns {this}
   */
  list(arr, writeFn) {
    const start = this.len;
    try {
      this.u32(arr.length);
      for (let i = 0; i < arr.length; i++) writeFn(this, arr[i], i);
    } catch (e) {
      this.len = start; // no partial record after a throw
      throw e;
    }
    return this;
  }

  /** Copy of the bytes written so far. @returns {Uint8Array} */
  bytes() {
    return this.buf.slice(0, this.len);
  }
}

function digestBytes(d, name) {
  if (typeof d !== 'string' || !FP_DIGEST_RE.test(d)) {
    throw new TypeError(`combineFingerprints: digest for "${name}" is not "xxh32x2:" + 16 lowercase hex`);
  }
  const out = new Uint8Array(8);
  for (let i = 0; i < 8; i++) out[i] = parseInt(d.slice(FP_PREFIX.length + 2 * i, FP_PREFIX.length + 2 * i + 2), 16);
  return out;
}

/**
 * The bytes hashed for the combined frame fingerprint (section 6.5):
 * `u32 fpVersion(=1) | u32 tick | u32 count | count x 8 raw digest bytes`, in `order`.
 * Every name in `order` must have a digest and vice versa; a missing or extra subsystem is a bug, never a silent zero.
 * @param {number} tick u32
 * @param {Record<string, string>} digests subsystem name -> `xxh32x2:<16 hex>`
 * @param {string[]} order canonical subsystem order (FP_SUBSYSTEMS)
 * @returns {Uint8Array}
 */
export function combineFingerprintBytes(tick, digests, order) {
  if (!Array.isArray(order)) throw new TypeError('combineFingerprints: order must be an array of subsystem names');
  const seen = new Set();
  const w = new FpWriter(12 + 8 * order.length);
  w.u32(FP_VERSION).u32(tick).u32(order.length);
  for (const name of order) {
    if (seen.has(name)) throw new Error(`combineFingerprints: duplicate subsystem "${name}" in order`);
    seen.add(name);
    if (!Object.prototype.hasOwnProperty.call(digests, name)) {
      throw new Error(`combineFingerprints: missing digest for subsystem "${name}"`);
    }
    const raw = digestBytes(digests[name], name);
    w._need(8);
    w.buf.set(raw, w.len);
    w.len += 8;
  }
  for (const name of Object.keys(digests)) {
    if (!seen.has(name)) throw new Error(`combineFingerprints: digest for "${name}" is not in the subsystem order`);
  }
  return w.bytes();
}

/**
 * Combined frame fingerprint: `xxh32x2:` of combineFingerprintBytes.
 * @param {number} tick
 * @param {Record<string, string>} digests
 * @param {string[]} order
 * @returns {string}
 */
export function combineFingerprints(tick, digests, order) {
  return fingerprintOf(combineFingerprintBytes(tick, digests, order));
}/**
 * BB-CJSON v1: canonical JSON for Replay Contract v1 (docs/replay/replay-contract-v1.md, section 2, with the binding
 * amendments from the independent review).
 *
 * A strict profile of RFC 8785 (JCS): the same bytes in every implementation, so a SHA-256 over them is a stable
 * identity. Anything not representable is an error with a stable `code` and an RFC 6901 JSON Pointer `pointer`
 * (root is the empty string, e.g. "/causal/bsod/syncLevel", "/pose/2"), never silently altered. Pure module: no
 * Phaser, no clock, no randomness, no TextEncoder/TextDecoder (UTF-8 is done by hand so it behaves identically under
 * Node, browsers and Jest's jsdom).
 *
 * Error codes: nan, infinity, negative-zero, unsafe-integer, float-out-of-range, undefined, lone-surrogate,
 * key-not-allowed, proto-key, non-plain-object, unsupported-type:<typeof>, sparse-array, too-deep, duplicate-key,
 * not-canonical, invalid-utf8, bom, syntax-error, too-large (canonical bytes > 16 MiB), string-too-long (string >
 * 1 MiB of UTF-8), f64-noncanonical. Additional codes (not named by the contract): non-plain-array, array-extra-props,
 * symbol-key, accessor, hidden-property.
 *
 * parseCanonical error precedence (deterministic): UTF-8 decode -> BOM -> too-large -> syntax-error / duplicate-key
 * (first offender in document order) -> value-level rejections (first offender in document order: depth, number,
 * string, key rules) -> re-serialize byte equality (`not-canonical`). Token-level forms such as `1.0`, `1e2` are caught
 * by the byte-equality step; a parsed -0 value is `negative-zero`.
 *
 * Notes: (1) canonicalize() validates all keys of an object (and symbols / hidden properties) before descending into
 * values, so for `{a: undefined, '\u00e9': 1}` it reports `key-not-allowed`; the document-order rule above applies to
 * parseCanonical only. (2) parseCanonical(string) cannot see UTF-8, so a lone surrogate in a string input is reported
 * as the value-level `lone-surrogate`, not `invalid-utf8`. (3) Proxy objects cannot be detected from JS and are
 * serialized as whatever their traps present; do not pass untrusted Proxies.
 */

export const MAX_DEPTH = 32;
export const MAX_OUTPUT_BYTES = 16777216; // 16 MiB
export const MAX_STRING_BYTES = 1048576; // 1 MiB

const KEY_RE = /^[A-Za-z0-9_.:$-]{1,64}$/;
const NEEDS_ESCAPE_RE = /[\u0000-\u001f"\\]/;
const F64_RE = /^f64:[0-9a-f]{16}$/;

/** Error for every canonical-JSON failure. `code` is contract-stable; `pointer` is an RFC 6901 JSON Pointer. */
export class CJSONError extends Error {
  /**
   * @param {string} code
   * @param {string} pointer RFC 6901 JSON Pointer ("" is the root)
   * @param {string} [detail]
   */
  constructor(code, pointer, detail) {
    // The pointer property is always complete; only the message is truncated (a 16M-level pointer is 32 MB).
    const shown = pointer.length > 200 ? `${pointer.slice(0, 200)}...` : pointer;
    super(`${code} at pointer ${JSON.stringify(shown)}${detail ? ` (${detail})` : ''}`);
    this.name = 'CJSONError';
    this.code = code;
    this.pointer = pointer;
  }
}

/** RFC 6901 reference-token escaping. */
const esc = (token) => {
  const s = String(token);
  return s.indexOf('~') < 0 && s.indexOf('/') < 0 ? s : s.replace(/~/g, '~0').replace(/\//g, '~1');
};

// ---------------------------------------------------------------------------------------------------------------------
// UTF-8 (hand-rolled so the module has no environment dependencies)
// ---------------------------------------------------------------------------------------------------------------------

/** True when `s` has no unpaired UTF-16 surrogate. */
function isWellFormed(s) {
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) i++;
      else return false;
    } else if (c >= 0xdc00 && c <= 0xdfff) return false;
  }
  return true;
}

/**
 * UTF-8 byte length of a well-formed string.
 * @param {string} s
 * @returns {number}
 */
export function utf8Length(s) {
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 0x80) n += 1;
    else if (c < 0x800) n += 2;
    else if (c >= 0xd800 && c <= 0xdbff) {
      n += 4;
      i++;
    } else n += 3;
  }
  return n;
}

/**
 * Encode a well-formed string as UTF-8. Throws CJSONError('lone-surrogate') on an unpaired surrogate.
 * @param {string} s
 * @returns {Uint8Array}
 */
export function utf8Encode(s) {
  if (!isWellFormed(s)) throw new CJSONError('lone-surrogate', '');
  const out = new Uint8Array(utf8Length(s));
  let p = 0;
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c < 0x80) out[p++] = c;
    else if (c < 0x800) {
      out[p++] = 0xc0 | (c >> 6);
      out[p++] = 0x80 | (c & 63);
    } else if (c >= 0xd800 && c <= 0xdbff) {
      c = 0x10000 + ((c - 0xd800) << 10) + (s.charCodeAt(++i) - 0xdc00);
      out[p++] = 0xf0 | (c >> 18);
      out[p++] = 0x80 | ((c >> 12) & 63);
      out[p++] = 0x80 | ((c >> 6) & 63);
      out[p++] = 0x80 | (c & 63);
    } else {
      out[p++] = 0xe0 | (c >> 12);
      out[p++] = 0x80 | ((c >> 6) & 63);
      out[p++] = 0x80 | (c & 63);
    }
  }
  return out;
}

/**
 * Strict UTF-8 decode: rejects overlong forms, surrogate code points, values above U+10FFFF, truncated and stray bytes.
 * A leading BOM is NOT stripped (it decodes to U+FEFF).
 * @param {Uint8Array} bytes
 * @returns {string}
 * @throws {CJSONError} code `invalid-utf8`
 */
export function utf8DecodeStrict(bytes) {
  const bad = (i) => new CJSONError('invalid-utf8', '', `byte offset ${i}`);
  let out = '';
  let chunk = [];
  const n = bytes.length;
  for (let i = 0; i < n; ) {
    const b0 = bytes[i];
    let cp;
    if (b0 < 0x80) {
      cp = b0;
      i += 1;
    } else if (b0 >= 0xc2 && b0 <= 0xdf) {
      if (i + 1 >= n || (bytes[i + 1] & 0xc0) !== 0x80) throw bad(i);
      cp = ((b0 & 0x1f) << 6) | (bytes[i + 1] & 63);
      i += 2;
    } else if (b0 >= 0xe0 && b0 <= 0xef) {
      if (i + 2 >= n || (bytes[i + 1] & 0xc0) !== 0x80 || (bytes[i + 2] & 0xc0) !== 0x80) throw bad(i);
      cp = ((b0 & 0x0f) << 12) | ((bytes[i + 1] & 63) << 6) | (bytes[i + 2] & 63);
      if (cp < 0x800 || (cp >= 0xd800 && cp <= 0xdfff)) throw bad(i);
      i += 3;
    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
      if (
        i + 3 >= n ||
        (bytes[i + 1] & 0xc0) !== 0x80 ||
        (bytes[i + 2] & 0xc0) !== 0x80 ||
        (bytes[i + 3] & 0xc0) !== 0x80
      )
        throw bad(i);
      cp = ((b0 & 0x07) << 18) | ((bytes[i + 1] & 63) << 12) | ((bytes[i + 2] & 63) << 6) | (bytes[i + 3] & 63);
      if (cp < 0x10000 || cp > 0x10ffff) throw bad(i);
      i += 4;
    } else throw bad(i);
    if (cp >= 0x10000) {
      cp -= 0x10000;
      chunk.push(0xd800 + (cp >> 10), 0xdc00 + (cp & 0x3ff));
    } else chunk.push(cp);
    if (chunk.length >= 4096) {
      out += String.fromCharCode.apply(null, chunk);
      chunk = [];
    }
  }
  if (chunk.length) out += String.fromCharCode.apply(null, chunk);
  return out;
}

/**
 * Normalize a byte input to a Uint8Array view (no copy): accepts Uint8Array (including node Buffer and Uint8Arrays from
 * another realm, which fail `instanceof` under Jest's jsdom) and ArrayBuffer. Everything else, including Int8Array,
 * Uint8ClampedArray, other typed arrays, DataView, strings and arrays, throws TypeError: hashing the wrong view type
 * would silently produce a wrong digest.
 * @param {*} x
 * @param {string} [who] caller name for the error message
 * @returns {Uint8Array}
 */
export function asUint8Array(x, who = 'bytes') {
  if (x instanceof Uint8Array) return x;
  const tag = Object.prototype.toString.call(x);
  if (tag === '[object Uint8Array]' && ArrayBuffer.isView(x)) return x;
  if (x instanceof ArrayBuffer || tag === '[object ArrayBuffer]') {
    try {
      return new Uint8Array(x);
    } catch {
      /* not a real ArrayBuffer (spoofed tag) */
    }
  }
  throw new TypeError(`${who} expects a Uint8Array or ArrayBuffer`);
}

// ---------------------------------------------------------------------------------------------------------------------
// Serializer
// ---------------------------------------------------------------------------------------------------------------------

/** Exact string rules: well-formed UTF-16 and at most MAX_STRING_BYTES of UTF-8. Returns an error code or null. */
function stringViolation(s) {
  if (!isWellFormed(s)) return 'lone-surrogate';
  // UTF-16 length <= UTF-8 length <= 3 x UTF-16 length: only compute the exact size when the cheap bounds disagree.
  if (s.length > MAX_STRING_BYTES || (s.length * 3 > MAX_STRING_BYTES && utf8Length(s) > MAX_STRING_BYTES)) {
    return 'string-too-long';
  }
  return null;
}

/** Key rules. Returns an error code or null. */
function keyViolation(k) {
  if (!KEY_RE.test(k)) return 'key-not-allowed';
  if (k === '__proto__') return 'proto-key';
  return null;
}

function serString(s, pointer) {
  const bad = stringViolation(s);
  if (bad) throw new CJSONError(bad, pointer);
  if (!NEEDS_ESCAPE_RE.test(s)) return `"${s}"`;
  let out = '"';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 0x22) out += '\\"';
    else if (c === 0x5c) out += '\\\\';
    else if (c === 0x08) out += '\\b';
    else if (c === 0x09) out += '\\t';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0c) out += '\\f';
    else if (c === 0x0d) out += '\\r';
    else if (c < 0x20) out += `\\u${c.toString(16).padStart(4, '0')}`;
    else out += s[i];
  }
  return `${out}"`;
}

function serNumber(v, pointer) {
  if (Number.isNaN(v)) throw new CJSONError('nan', pointer);
  if (!Number.isFinite(v)) throw new CJSONError('infinity', pointer);
  if (Object.is(v, -0)) throw new CJSONError('negative-zero', pointer);
  if (Number.isInteger(v)) {
    if (!Number.isSafeInteger(v)) throw new CJSONError('unsafe-integer', pointer);
    return String(v);
  }
  const s = String(v);
  if (s.includes('e')) throw new CJSONError('float-out-of-range', pointer);
  return s;
}

const toStringTag = (v) => Object.prototype.toString.call(v);

/** Brand checks (throw on a wrong receiver, in any realm). Only used for the rare null-prototype path. */
function hasBrand(v) {
  const probes = [
    () => Map.prototype.has.call(v, 0),
    () => Set.prototype.has.call(v, 0),
    () => WeakMap.prototype.has.call(v, {}),
    () => WeakSet.prototype.has.call(v, {}),
    () => Object.getOwnPropertyDescriptor(ArrayBuffer.prototype, 'byteLength').get.call(v),
  ];
  for (const probe of probes) {
    try {
      probe();
      return true;
    } catch {
      /* not that brand */
    }
  }
  return false;
}

/**
 * Cross-realm plain-object test: the toString tag is "[object Object]" and the prototype is null, or the prototype's
 * own prototype is null (so Object.prototype of any realm qualifies; Date, Map, typed arrays, class instances and
 * objects with an inherited prototype chain do not). A null-prototype object is additionally refused if it is really
 * a typed array / DataView or a Map/Set/WeakMap/WeakSet whose prototype was stripped (their toString tag is lost with
 * the prototype). Proxy objects are NOT reliably detectable from JS and are accepted as whatever they present
 * through their traps; never pass untrusted Proxies to canonicalize.
 */
function isPlainObject(v) {
  if (toStringTag(v) !== '[object Object]') return false;
  const proto = Object.getPrototypeOf(v);
  if (proto === null) return !ArrayBuffer.isView(v) && !hasBrand(v);
  return Object.getPrototypeOf(proto) === null;
}

/** Plain array: Array.isArray and a prototype that is some realm's Array.prototype (chain length exactly 2). */
function isPlainArray(v) {
  const proto = Object.getPrototypeOf(v);
  return proto !== null && Object.getPrototypeOf(Object.getPrototypeOf(proto)) === null && toStringTag(v) === '[object Array]';
}

/**
 * @param {*} v
 * @param {string} pointer JSON Pointer of `v`
 * @param {number} level number of containers enclosing `v` (0 at the root)
 * @returns {string}
 */
function ser(v, pointer, level) {
  if (v === null) return 'null';
  switch (typeof v) {
    case 'boolean':
      return v ? 'true' : 'false';
    case 'string':
      return serString(v, pointer);
    case 'number':
      return serNumber(v, pointer);
    case 'undefined':
      throw new CJSONError('undefined', pointer);
    case 'object':
      break;
    default:
      throw new CJSONError(`unsupported-type:${typeof v}`, pointer);
  }
  // `v` is a container: it sits at nesting level `level + 1`, which must not exceed MAX_DEPTH.
  if (level + 1 > MAX_DEPTH) throw new CJSONError('too-deep', pointer);
  if (Array.isArray(v)) {
    if (!isPlainArray(v)) throw new CJSONError('non-plain-array', pointer);
    const parts = new Array(v.length);
    for (let i = 0; i < v.length; i++) {
      // Descriptors, never v[i] on an unchecked slot: an accessor element must not have its getter invoked.
      const d = Object.getOwnPropertyDescriptor(v, i);
      if (d === undefined) throw new CJSONError('sparse-array', `${pointer}/${i}`);
      if (!('value' in d)) throw new CJSONError('accessor', `${pointer}/${i}`);
      if (!d.enumerable) throw new CJSONError('hidden-property', `${pointer}/${i}`);
      parts[i] = ser(d.value, `${pointer}/${i}`, level + 1);
    }
    if (Object.getOwnPropertyNames(v).length !== v.length + 1 || Object.getOwnPropertySymbols(v).length) {
      throw new CJSONError('array-extra-props', pointer);
    }
    return `[${parts.join(',')}]`;
  }
  if (!isPlainObject(v)) throw new CJSONError('non-plain-object', pointer);
  if (Object.getOwnPropertySymbols(v).length) throw new CJSONError('symbol-key', pointer);
  const keys = Object.keys(v);
  if (Object.getOwnPropertyNames(v).length !== keys.length) throw new CJSONError('hidden-property', pointer);
  for (const k of keys) {
    const bad = keyViolation(k);
    if (bad) throw new CJSONError(bad, `${pointer}/${esc(k)}`);
    if (!('value' in Object.getOwnPropertyDescriptor(v, k))) throw new CJSONError('accessor', `${pointer}/${esc(k)}`);
  }
  keys.sort(); // UTF-16 code unit order; keys are ASCII so it equals code point and UTF-8 byte order
  let out = '{';
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    out += `${i ? ',' : ''}"${k}":${ser(v[k], `${pointer}/${esc(k)}`, level + 1)}`;
  }
  return `${out}}`;
}

/**
 * Canonical text of `value` (BB-CJSON v1).
 * @param {*} value
 * @returns {string}
 * @throws {CJSONError}
 */
export function canonicalize(value) {
  const text = ser(value, '', 0);
  // UTF-16 length is a lower bound of the byte length: only measure when it could matter.
  if (text.length > MAX_OUTPUT_BYTES || (text.length * 3 > MAX_OUTPUT_BYTES && utf8Length(text) > MAX_OUTPUT_BYTES)) {
    throw new CJSONError('too-large', '');
  }
  return text;
}

/**
 * Canonical UTF-8 bytes of `value`.
 * @param {*} value
 * @returns {Uint8Array}
 * @throws {CJSONError}
 */
export function canonicalBytes(value) {
  return utf8Encode(canonicalize(value));
}

// ---------------------------------------------------------------------------------------------------------------------
// Strict parser
// ---------------------------------------------------------------------------------------------------------------------

const NUMBER_RE = /-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?/y;

/**
 * Iterative (no recursion, so absurd nesting cannot overflow the stack) JSON parser that accepts the whole JSON
 * grammar, rejects duplicate keys, builds Object.create(null) objects, and records the FIRST value-level violation in
 * document order without stopping, so that a later syntax error still takes precedence (see the module comment).
 *
 * Memory is bounded for hostile nesting: values are only built for the first MAX_DEPTH levels. Deeper levels (which
 * are already a `too-deep` violation) keep one byte of type per level in a growable Uint8Array, plus map entries only
 * for levels that actually carry an array count or an object key, so `'[' x 16 MiB` costs ~16-32 MiB, not gigabytes.
 * Syntax and duplicate-key checking continue through the deep region, preserving the precedence rules.
 */
class Parser {
  constructor(text) {
    this.t = text;
    this.i = 0;
    this.depth = 0; // number of open containers
    this.types = new Uint8Array(64); // per level: 1 = array, 2 = object
    this.frames = new Array(MAX_DEPTH); // built containers, levels < MAX_DEPTH only
    this.tok = new Array(MAX_DEPTH); // current pointer token per shallow level (array: index, object: key)
    this.deepTok = new Map(); // same, for levels >= MAX_DEPTH, only when not the default (0 / no key yet)
    this.deepSeen = new Map(); // level -> Set of keys, created lazily once a deep object has 2 keys
    this.violation = null;
  }

  getTok(L) {
    if (L < MAX_DEPTH) return this.tok[L];
    const v = this.deepTok.get(L);
    return v === undefined ? (this.types[L] === 1 ? 0 : '') : v;
  }

  /** JSON Pointer of the current location (the value being read, or the member whose key was just read). */
  pointer() {
    let p = '';
    for (let L = 0; L < this.depth; L++) {
      if (L >= MAX_DEPTH && this.types[L] === 1 && !this.deepTok.has(L)) {
        // run of untouched deep arrays (token 0): emit in one go instead of one concatenation per level
        let end = L + 1;
        while (end < this.depth && this.types[end] === 1 && !this.deepTok.has(end)) end++;
        p += '/0'.repeat(end - L);
        L = end - 1;
      } else p += `/${esc(this.getTok(L))}`;
    }
    return p;
  }

  /** Record the first value-level violation (pointer built lazily: only the first one is ever needed). */
  note(code) {
    if (this.violation === null) this.violation = new CJSONError(code, this.pointer());
  }

  syntax(why) {
    return new CJSONError('syntax-error', this.pointer(), `${why} at offset ${this.i}`);
  }

  ws() {
    const t = this.t;
    for (;;) {
      const c = t.charCodeAt(this.i);
      if (c === 0x20 || c === 0x09 || c === 0x0a || c === 0x0d) this.i++;
      else return;
    }
  }

  push(arr) {
    const L = this.depth;
    if (L >= this.types.length) {
      const next = new Uint8Array(this.types.length * 2);
      next.set(this.types);
      this.types = next;
    }
    this.types[L] = arr ? 1 : 2;
    if (L < MAX_DEPTH) {
      this.frames[L] = arr ? [] : Object.create(null);
      this.tok[L] = arr ? 0 : '';
    }
    this.depth = L + 1;
  }

  /** Close the top level and return its built value (undefined for deep levels, which are discarded). */
  pop() {
    const L = --this.depth;
    if (L < MAX_DEPTH) return this.frames[L];
    this.deepTok.delete(L);
    this.deepSeen.delete(L);
    return undefined;
  }

  /** A key was read for the top (object) level: update the token, reject duplicates. */
  key(k) {
    const L = this.depth - 1;
    if (L < MAX_DEPTH) {
      const dup = k in this.frames[L];
      this.tok[L] = k;
      if (dup) throw new CJSONError('duplicate-key', this.pointer(), `key ${JSON.stringify(k)}`);
      return;
    }
    const prev = this.deepTok.get(L); // last key read for this object, if any
    this.deepTok.set(L, k);
    let seen = this.deepSeen.get(L);
    let dup = false;
    if (seen) {
      dup = seen.has(k);
      seen.add(k);
    } else if (prev !== undefined) {
      dup = prev === k;
      seen = new Set([prev, k]);
      this.deepSeen.set(L, seen);
    }
    if (dup) throw new CJSONError('duplicate-key', this.pointer(), `key ${JSON.stringify(k)}`);
  }

  /** Hand a finished value to the enclosing container. */
  deliver(v) {
    const L = this.depth - 1;
    const arr = this.types[L] === 1;
    if (L < MAX_DEPTH) {
      if (arr) {
        this.frames[L].push(v);
        this.tok[L] = this.frames[L].length;
      } else this.frames[L][this.tok[L]] = v;
    } else if (arr) this.deepTok.set(L, (this.deepTok.get(L) || 0) + 1);
  }

  /** Read a string token (cursor on the opening quote) and return its decoded value. */
  string() {
    const t = this.t;
    this.i++;
    let out = '';
    let start = this.i;
    for (;;) {
      if (this.i >= t.length) throw this.syntax('unterminated string');
      const c = t.charCodeAt(this.i);
      if (c === 0x22) {
        out += t.slice(start, this.i);
        this.i++;
        return out;
      }
      if (c < 0x20) throw this.syntax('raw control character in string');
      if (c !== 0x5c) {
        this.i++;
        continue;
      }
      out += t.slice(start, this.i);
      const e = t[this.i + 1];
      this.i += 2;
      switch (e) {
        case '"':
          out += '"';
          break;
        case '\\':
          out += '\\';
          break;
        case '/':
          out += '/';
          break;
        case 'b':
          out += '\b';
          break;
        case 'f':
          out += '\f';
          break;
        case 'n':
          out += '\n';
          break;
        case 'r':
          out += '\r';
          break;
        case 't':
          out += '\t';
          break;
        case 'u': {
          const hex = t.slice(this.i, this.i + 4);
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw this.syntax('bad \\u escape');
          out += String.fromCharCode(parseInt(hex, 16));
          this.i += 4;
          break;
        }
        default:
          throw this.syntax('bad escape');
      }
      start = this.i;
    }
  }

  parseDocument() {
    const t = this.t;
    let phase = 'value';
    let v;
    for (;;) {
      if (phase === 'value') {
        this.ws();
        const c = t[this.i];
        if (c === '{' || c === '[') {
          if (this.depth + 1 > MAX_DEPTH) this.note('too-deep');
          const arr = c === '[';
          this.push(arr);
          this.i++;
          this.ws();
          if (t[this.i] === (arr ? ']' : '}')) {
            this.i++;
            v = this.pop();
            phase = 'deliver';
          } else phase = arr ? 'value' : 'key';
        } else if (c === '"') {
          const s = this.string();
          const bad = stringViolation(s);
          if (bad) this.note(bad);
          v = s;
          phase = 'deliver';
        } else if (c === '-' || (c >= '0' && c <= '9')) {
          NUMBER_RE.lastIndex = this.i;
          const m = NUMBER_RE.exec(t);
          if (!m) throw this.syntax('bad number');
          this.i += m[0].length;
          v = Number(m[0]);
          try {
            serNumber(v, '');
          } catch (e) {
            this.note(e.code);
          }
          phase = 'deliver';
        } else if (t.startsWith('true', this.i)) {
          this.i += 4;
          v = true;
          phase = 'deliver';
        } else if (t.startsWith('false', this.i)) {
          this.i += 5;
          v = false;
          phase = 'deliver';
        } else if (t.startsWith('null', this.i)) {
          this.i += 4;
          v = null;
          phase = 'deliver';
        } else throw this.syntax('unexpected token');
      } else if (phase === 'key') {
        this.ws();
        if (t[this.i] !== '"') throw this.syntax('expected string key');
        const key = this.string();
        this.key(key);
        const bad = keyViolation(key);
        if (bad) this.note(bad);
        this.ws();
        if (t[this.i] !== ':') throw this.syntax('expected :');
        this.i++;
        phase = 'value';
      } else {
        // deliver `v` to the enclosing container, then expect `,` or the closer
        if (this.depth === 0) {
          this.ws();
          if (this.i !== t.length) throw this.syntax('trailing characters');
          return v;
        }
        this.deliver(v);
        const arr = this.types[this.depth - 1] === 1;
        this.ws();
        const c = t[this.i];
        if (c === ',') {
          this.i++;
          phase = arr ? 'value' : 'key';
        } else if (c === (arr ? ']' : '}')) {
          this.i++;
          v = this.pop();
        } else throw this.syntax(arr ? 'expected , or ]' : 'expected , or }');
      }
    }
  }
}

/**
 * Parse canonical bytes (or text). Precedence: strict UTF-8 -> BOM -> too-large -> syntax / duplicate-key ->
 * value-level rejections -> re-serialize byte equality. Returned objects have a null prototype.
 * @param {Uint8Array|string} input
 * @returns {*}
 * @throws {CJSONError}
 */
export function parseCanonical(input) {
  let text;
  let size;
  if (typeof input === 'string') {
    text = input;
    size = -1;
  } else if (input !== null && typeof input === 'object') {
    let bytes;
    try {
      bytes = asUint8Array(input, 'parseCanonical');
    } catch {
      throw new CJSONError('unsupported-type:object', '', 'parseCanonical takes a Uint8Array, an ArrayBuffer or a string');
    }
    text = utf8DecodeStrict(bytes);
    size = bytes.length;
  } else throw new CJSONError(`unsupported-type:${typeof input}`, '', 'parseCanonical takes bytes or a string');
  if (text.charCodeAt(0) === 0xfeff) throw new CJSONError('bom', '');
  if (size > MAX_OUTPUT_BYTES || (size < 0 && utf8Length(text) > MAX_OUTPUT_BYTES)) throw new CJSONError('too-large', '');
  const parser = new Parser(text);
  const value = parser.parseDocument();
  if (parser.violation) throw parser.violation;
  if (canonicalize(value) !== text) throw new CJSONError('not-canonical', '');
  return value;
}

// ---------------------------------------------------------------------------------------------------------------------
// F64 strings (section 2.2)
// ---------------------------------------------------------------------------------------------------------------------

const HEX = '0123456789abcdef';
const f64View = new DataView(new ArrayBuffer(8));

/**
 * Encode a JS number as `"f64:" + 16 lowercase hex digits` of its IEEE-754 binary64 bits, big-endian.
 * Preserves -0 and +-Infinity; every NaN becomes `f64:7ff8000000000000`.
 * @param {number} v
 * @returns {string}
 * @throws {TypeError} when `v` is not a number
 */
export function f64Encode(v) {
  if (typeof v !== 'number') throw new TypeError(`f64Encode expects a number, got ${typeof v}`);
  if (Number.isNaN(v)) return 'f64:7ff8000000000000';
  f64View.setFloat64(0, v, false);
  let s = 'f64:';
  for (let i = 0; i < 8; i++) {
    const b = f64View.getUint8(i);
    s += HEX[b >> 4] + HEX[b & 15];
  }
  return s;
}

/**
 * Inverse of f64Encode. Decodes, re-encodes and compares: any non-canonical form (uppercase hex, wrong length, missing
 * prefix, a NaN payload other than 7ff8000000000000, non-strings) throws `f64-noncanonical`.
 * @param {string} s
 * @returns {number}
 * @throws {CJSONError} code `f64-noncanonical`
 */
export function f64Decode(s) {
  if (typeof s !== 'string' || !F64_RE.test(s)) {
    throw new CJSONError('f64-noncanonical', '', 'expected "f64:" + 16 lowercase hex digits');
  }
  for (let i = 0; i < 8; i++) f64View.setUint8(i, parseInt(s.slice(4 + 2 * i, 6 + 2 * i), 16));
  const v = f64View.getFloat64(0, false);
  if (f64Encode(v) !== s) throw new CJSONError('f64-noncanonical', '', 'does not re-encode to the same string');
  return v;
}

// ---------------------------------------------------------------------------------------------------------------------
// Boot self-test (section 2.2: every implementation MUST run the vector self-test at verifier start)
// ---------------------------------------------------------------------------------------------------------------------

/**
 * Check this engine's `Number::toString`, integer rules and F64 helpers against the section 2 vectors. Verifiers call
 * it once at start; an engine whose number formatting differs fails loudly instead of producing different identities.
 * @returns {true}
 * @throws {Error} on the first mismatch
 */
export function canonicalSelfTest() {
  const expect = (what, got, want) => {
    if (got !== want) throw new Error(`BB-CJSON self-test failed: ${what}: got ${got}, want ${want}`);
  };
  const reject = (what, fn, code) => {
    let got = 'no error';
    try {
      fn();
    } catch (e) {
      got = e && e.code;
    }
    expect(`${what} rejection`, got, code);
  };
  expect(
    'cj-007 floats',
    canonicalize([0.1, 0.30000000000000004, 1.15, 0.15, 0.000001, 123456.789, 0.5, -2.5, 1.7, 4.35, 0.0003, 0.1 + 0.7]),
    '[0.1,0.30000000000000004,1.15,0.15,0.000001,123456.789,0.5,-2.5,1.7,4.35,0.0003,0.7999999999999999]',
  );
  expect('cj-008 integer-valued floats', canonicalize([3.0, 1e3, 2 ** 40]), '[3,1000,1099511627776]');
  expect('cj-006 integers', canonicalize([0, -1, 1, 9007199254740991, -9007199254740991, 120, 127, -127]), '[0,-1,1,9007199254740991,-9007199254740991,120,127,-127]');
  expect('exponent-free band', canonicalize([0.000001, 123456789012345.6, 0.0005]), '[0.000001,123456789012345.6,0.0005]');
  expect('cj-003 key order', canonicalize({ b: 1, a: 2, B: 3, _: 4, 10: 5, 9: 6, aa: 7, 'a.b': 8, 'a-b': 9 }), '{"10":5,"9":6,"B":3,"_":4,"a":2,"a-b":9,"a.b":8,"aa":7,"b":1}');
  reject('1e-7', () => canonicalize(1e-7), 'float-out-of-range');
  reject('9.99e-7', () => canonicalize(9.99e-7), 'float-out-of-range');
  reject('1e21', () => canonicalize(1e21), 'unsafe-integer');
  reject('2^53', () => canonicalize(9007199254740992), 'unsafe-integer');
  reject('-0', () => canonicalize(-0), 'negative-zero');
  reject('NaN', () => canonicalize(NaN), 'nan');
  const f = [[0, 'f64:0000000000000000'], [-0, 'f64:8000000000000000'], [0.1, 'f64:3fb999999999999a'], [4.35, 'f64:4011666666666666'], [5e-324, 'f64:0000000000000001'], [-Infinity, 'f64:fff0000000000000'], [NaN, 'f64:7ff8000000000000']];
  for (const [x, want] of f) {
    expect(`f64Encode(${x})`, f64Encode(x), want);
    expect(`f64Decode(${want})`, Object.is(f64Decode(want), Number.isNaN(x) ? NaN : x), true);
  }
  return true;
}/**
 * Tier A identity digests for Replay Contract v1 (docs/replay/replay-contract-v1.md, section 3.1).
 *
 * Synchronous, dependency-free SHA-256 so it works everywhere the replay code does: crypto.subtle needs a secure
 * context and is absent from Jest's jsdom environment, and sync code needs no async plumbing. Inputs are tens of KB
 * and hashed outside the sim loop, so speed is irrelevant. A boot self-test against NIST vectors runs when the module
 * loads and throws if the implementation is wrong. Pure module: no Phaser, no clock, no randomness.
 */
import { asUint8Array, canonicalBytes } from './canonicalJson.js';

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01,
  0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
  0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
  0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08,
  0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

const HEX = '0123456789abcdef';

/** Compress one 64-byte block starting at `off` of `buf` into state `h` (Uint32Array(8)); `w` is scratch (64). */
function block(h, buf, off, w) {
  for (let i = 0; i < 16; i++) {
    const p = off + i * 4;
    w[i] = ((buf[p] << 24) | (buf[p + 1] << 16) | (buf[p + 2] << 8) | buf[p + 3]) >>> 0;
  }
  for (let i = 16; i < 64; i++) {
    const a = w[i - 15];
    const b = w[i - 2];
    const s0 = ((a >>> 7) | (a << 25)) ^ ((a >>> 18) | (a << 14)) ^ (a >>> 3);
    const s1 = ((b >>> 17) | (b << 15)) ^ ((b >>> 19) | (b << 13)) ^ (b >>> 10);
    w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
  }
  let a = h[0];
  let b = h[1];
  let c = h[2];
  let d = h[3];
  let e = h[4];
  let f = h[5];
  let g = h[6];
  let hh = h[7];
  for (let i = 0; i < 64; i++) {
    const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
    const ch = (e & f) ^ (~e & g);
    const t1 = (hh + S1 + ch + K[i] + w[i]) >>> 0;
    const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
    const maj = (a & b) ^ (a & c) ^ (b & c);
    const t2 = (S0 + maj) >>> 0;
    hh = g;
    g = f;
    f = e;
    e = (d + t1) >>> 0;
    d = c;
    c = b;
    b = a;
    a = (t1 + t2) >>> 0;
  }
  h[0] = (h[0] + a) >>> 0;
  h[1] = (h[1] + b) >>> 0;
  h[2] = (h[2] + c) >>> 0;
  h[3] = (h[3] + d) >>> 0;
  h[4] = (h[4] + e) >>> 0;
  h[5] = (h[5] + f) >>> 0;
  h[6] = (h[6] + g) >>> 0;
  h[7] = (h[7] + hh) >>> 0;
}

/**
 * SHA-256 of `bytes` as 64 lowercase hex digits.
 * @param {Uint8Array|ArrayBuffer} input
 * @returns {string}
 * @throws {TypeError} for anything that is not a Uint8Array/ArrayBuffer
 */
export function sha256Hex(input) {
  const bytes = asUint8Array(input, 'sha256Hex'); // Uint8Array/Buffer/ArrayBuffer only; other views would hash wrongly
  const h = new Uint32Array([
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ]);
  const w = new Uint32Array(64);
  const n = bytes.length;
  const full = n - (n % 64);
  for (let off = 0; off < full; off += 64) block(h, bytes, off, w);
  // Tail: remaining bytes, 0x80, zero padding, 64-bit big-endian bit length. One or two final blocks.
  const rem = n - full;
  const tail = new Uint8Array(rem < 56 ? 64 : 128);
  tail.set(bytes.subarray(full), 0);
  tail[rem] = 0x80;
  const bitsHi = Math.floor(n / 0x20000000); // (n * 8) >>> 32 without overflowing 2^53
  const bitsLo = (n << 3) >>> 0;
  const end = tail.length;
  tail[end - 8] = bitsHi >>> 24;
  tail[end - 7] = (bitsHi >>> 16) & 255;
  tail[end - 6] = (bitsHi >>> 8) & 255;
  tail[end - 5] = bitsHi & 255;
  tail[end - 4] = bitsLo >>> 24;
  tail[end - 3] = (bitsLo >>> 16) & 255;
  tail[end - 2] = (bitsLo >>> 8) & 255;
  tail[end - 1] = bitsLo & 255;
  for (let off = 0; off < end; off += 64) block(h, tail, off, w);
  let out = '';
  for (let i = 0; i < 8; i++) {
    for (let s = 28; s >= 0; s -= 4) out += HEX[(h[i] >>> s) & 15];
  }
  return out;
}

/**
 * Tier A identity digest of a value: `sha256:` + hex of its BB-CJSON v1 canonical bytes (section 3.1).
 * @param {*} value
 * @returns {string}
 * @throws {CJSONError} when the value is not canonicalizable
 */
export function digestOf(value) {
  return `sha256:${sha256Hex(canonicalBytes(value))}`;
}

/** Digest of already-canonical bytes: `sha256:` + hex. */
export function digestOfBytes(bytes) {
  return `sha256:${sha256Hex(bytes)}`;
}

const ascii = (s) => Uint8Array.from(s, (c) => c.charCodeAt(0));

/** NIST FIPS 180-4 / CAVS reference vectors, [message bytes, expected hex]. The million-'a' one is opt-in (slow-ish). */
const VECTORS = [
  [ascii(''), 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'],
  [ascii('abc'), 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad'],
  [
    ascii('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'),
    '248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1',
  ],
  [
    ascii('abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmnhijklmnoijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu'),
    'cf5b16a778af8380036ce59e7b0492370b249b11e8f07a51afac45037afee9d1',
  ],
];

/**
 * Check the implementation against NIST vectors. Throws on the first mismatch.
 * @param {{full?: boolean}} [opts] full: also hash one million 'a' bytes (NIST long message).
 * @returns {true}
 */
export function sha256SelfTest(opts = {}) {
  for (const [msg, want] of VECTORS) {
    const got = sha256Hex(msg);
    if (got !== want) throw new Error(`sha256 self-test failed for ${msg.length}-byte vector: ${got} != ${want}`);
  }
  if (opts.full) {
    const got = sha256Hex(new Uint8Array(1000000).fill(0x61));
    const want = 'cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0';
    if (got !== want) throw new Error(`sha256 self-test failed for one million 'a': ${got} != ${want}`);
  }
  return true;
}

// Boot self-test (Replay Contract v1, 3.1): an engine or port that gets SHA-256 wrong must fail loudly at load.
sha256SelfTest();/**
 * Live evidence path (Replay Contract v1.0, sections 4.5, 6.7, 7.1; issue #116). NO Phaser imports. Called once, after a
 * run ends, from RunScene._saveGhostTape via scheduleRunEvidence (a deferred task: building, validating and hashing a
 * bundle costs tens to hundreds of ms and must not land on the crash frame). It reads only the finished tape and the
 * recorder's already-captured fingerprints, never simulation state. It never throws and never blocks ghost saving: every
 * failure is logged (console.warn) and left in `registry['lastEvidenceStatus']` for any UI that wants it.
 *
 *   tape + recorder.fingerprints (#165, detail `combined`) + the committed ruleset of this build (#166, loaded by
 *   src/systems/replay/runtimeRuleset.js) -> manifest -> `bb-replay-evidence` bundle -> evidence store.
 */
import { buildManifest, evidenceBundle, bundleBytes, validateEvidenceBundle } from './manifest.js';
import { EvidenceStore } from './evidenceStore.js';
import { FP_SCHEMAS, FP_SUBSYSTEMS } from './fingerprintSchemas.js';
import { FP_PREFIX } from './canonicalBinary.js';

/** Registry key holding the status of the last evidence write: `{ok, digest?, durable?, code?, message?}`. */
export const EVIDENCE_STATUS_KEY = 'lastEvidenceStatus';
/** Optional registry key holding an EvidenceStore (tests, or a UI that created one); otherwise a shared lazy store is used. */
export const EVIDENCE_STORE_KEY = 'evidenceStore';
/** Registry key holding `{doc, rulesetId}`: the ruleset of this build (set by services.js). */
export const RULESET_KEY = 'currentRuleset';

let shared = null;
/** Shared lazily-opened store (IndexedDB `bitstream-replay-evidence`, memory fallback). */
export function sharedEvidenceStore() {
  if (!shared) shared = new EvidenceStore().init();
  return shared;
}

const bare = (fp) => (typeof fp === 'string' && fp.startsWith(FP_PREFIX) ? fp.slice(FP_PREFIX.length) : fp);

/** Number of failed fingerprint captures the recorder saw (`fingerprintErrorCount`, else the length of its error list). */
export function captureErrorCount(recorder) {
  if (!recorder) return 0;
  if (Number.isInteger(recorder.fingerprintErrorCount)) return recorder.fingerprintErrorCount;
  return Array.isArray(recorder.fingerprintErrors) ? recorder.fingerprintErrors.length : 0;
}

/**
 * Build (not store) the evidence bundle of a finished run.
 * Checkpoint detail is `combined` only when every checkpoint of the tape has a fingerprint and no capture failed;
 * otherwise `none`. The capture error count is always recorded in `manifest.info.capture.errorCount`, and a non-zero
 * count makes validation report `inconclusive` (`fingerprint-capture-errors`), never a silent pass.
 * Per-subsystem schema versions come from FP_SCHEMAS (#165), not constants.
 * @param {{tape:object, recorder:object, ruleset:{doc:object, rulesetId:string}, gameVersion?:string}} p
 */
export function buildRunEvidence({ tape, recorder, ruleset, gameVersion }) {
  if (!ruleset || !ruleset.doc || !ruleset.rulesetId) throw Object.assign(new Error('no ruleset for this build'), { code: 'no-ruleset' });
  const { doc, rulesetId } = ruleset;
  const fps = (recorder && recorder.fingerprints) || [];
  const errorCount = captureErrorCount(recorder);
  const expected = (tape.checkpoints || []).length;
  const complete = errorCount === 0 && fps.length === expected && fps.every((f, i) => f.tick === tape.checkpoints[i][0]);
  const detail = complete && fps.length ? 'combined' : 'none';
  const checkpoints = detail === 'combined'
    ? { algo: 'xxh32x2', detail, schemas: Object.fromEntries(FP_SUBSYSTEMS.map((n) => [n, FP_SCHEMAS[n].version])) }
    : { algo: null, detail: 'none', schemas: null };
  const manifest = buildManifest({
    tape, ruleset: { rulesetId, simRevision: doc.simRevision, engine: { phaser: doc.engine.phaser, matter: doc.engine.matter } },
    checkpoints, gameVersion, capture: { errorCount },
  });
  const bundle = evidenceBundle({ manifest, tape, checkpoints: detail === 'combined' ? fps.map((f) => [f.tick, bare(f.combined)]) : [] });
  return { bundle, rulesetId, ruleset: doc, detail, errorCount };
}

/**
 * Build, validate (once) and store the evidence of a finished run. Resolves `{ok:true, digest, durable, detail, outcome}`
 * or `{ok:false, code, message}`; never rejects. The result is also placed on `registry` under EVIDENCE_STATUS_KEY.
 * @param {object} tape finished tape (GhostRecorder.finish)
 * @param {object} recorder the GhostRecorder that produced it (for `fingerprints`)
 * @param {{registry?:object, ruleset:{doc:object, rulesetId:string}, gameVersion?:string, store?:object}} opts
 */
export async function saveRunEvidence(tape, recorder, opts) {
  const reg = opts && opts.registry;
  const report = (status) => {
    if (!status.ok) console.warn(`[replay-evidence] not saved: ${status.code}: ${status.message}`); // eslint-disable-line no-console
    else if (!status.durable) console.warn('[replay-evidence] saved to memory only (no durable storage)'); // eslint-disable-line no-console
    try { if (reg && typeof reg.set === 'function') reg.set(EVIDENCE_STATUS_KEY, status); } catch { /* signal is optional */ }
    return status;
  };
  try {
    const { bundle, rulesetId, ruleset, detail } = buildRunEvidence({ tape, recorder, ruleset: opts.ruleset, gameVersion: opts.gameVersion });
    const bytes = bundleBytes(bundle);
    const v = validateEvidenceBundle(bytes, (id) => (id === rulesetId ? ruleset : null)); // the only validation pass
    if (!v.ok) return report({ ok: false, code: v.code, message: `${v.pointer}${v.detail ? ` (${v.detail})` : ''}` });
    const store = opts.store || (reg && reg.get && reg.get(EVIDENCE_STORE_KEY)) || await sharedEvidenceStore();
    store.rulesetResolver = (id) => (id === rulesetId ? ruleset : null);
    const digest = await store.put(bytes, { runId: tape.runId }, v);
    return report({ ok: true, digest, durable: store.durable, detail, outcome: v.outcome, reasons: v.reasons.map((r) => r.reason) });
  } catch (e) {
    return report({ ok: false, code: (e && e.code) || 'error', message: String((e && e.message) || e) });
  }
}

/**
 * Fire-and-forget: run saveRunEvidence in a later task (setTimeout 0), after the run-end frame. Touches no simulation
 * state: `tape` and `recorder` are finished objects the scene has already let go of.
 * @returns {void}
 */
export function scheduleRunEvidence(tape, recorder, opts) {
  const run = () => { saveRunEvidence(tape, recorder, opts); };
  if (typeof setTimeout === 'function') setTimeout(run, 0); else Promise.resolve().then(run);
}/**
 * Durable local replay evidence (Replay Contract v1.0, section 1.2; issue #116). NO Phaser imports. No network.
 *
 * A SEPARATE IndexedDB database (`bitstream-replay-evidence`), never an object store inside `bitstream-ghosts`, so
 * GhostLibrary._collect cannot touch it by construction. Two object stores: `bundles` (`{digest, bytes}`: the canonical
 * `bb-replay-evidence` bytes keyed by their `bundleDigest`) and `index` (`{digest, size, runId, seq}`). Only the index is
 * loaded into memory; bytes are read on demand. `seq` is a local insertion sequence (no wall-clock values are stored, so
 * nothing in the database or in an export reveals when a run was played). No auto-eviction; deletion only through
 * `remove()` (an explicit user action).
 *
 * Unlike GhostLibrary, write failures are NOT swallowed: put() rejects with an EvidenceStoreError and reports to
 * `onError`. A bundle whose durable write failed stays in memory for the session (and is retried on the next successful
 * write); `durable` is true only while the backend is IndexedDB and nothing is memory-only. When IndexedDB is unavailable
 * the store works from memory and says so (`durable === false`). Export/import move the canonical bytes (`.bbreplay`)
 * with their digest; import REQUIRES the expected digest (the digest in the file name or manifest of the export), because
 * a structurally valid bundle with a flipped byte is a different, equally valid bundle. `navigator.storage.persist()` is
 * requested only on an explicit export (`requestPersistence`), never unasked. Evidence never leaves the device by itself.
 */
import { validateEvidenceBundle, bundleDigest, bundleBytes, bundleFilename } from './manifest.js';
import { digestOfBytes } from './canonicalSha256.js';

export const EVIDENCE_DB = 'bitstream-replay-evidence';
export const EVIDENCE_DB_VERSION = 1;
export const EVIDENCE_STORE = 'bundles';
export const EVIDENCE_INDEX = 'index';
export const EVIDENCE_EXTENSION = '.bbreplay';
const IDB_TIMEOUT_MS = 2500;

/** `code`: invalid-bundle (+ `cause` = validator result), digest-required, digest-mismatch, write-failed, quota-exceeded, read-failed, corrupt-record, not-found. */
export class EvidenceStoreError extends Error {
  constructor(code, detail, cause) {
    super(`${code}${detail ? `: ${detail}` : ''}`);
    this.name = 'EvidenceStoreError';
    this.code = code;
    this.cause = cause;
  }
}

const req2p = (req) => new Promise((resolve, reject) => {
  req.onsuccess = () => resolve(req.result);
  req.onerror = () => reject(req.error || new Error('idb request failed'));
});
const txDone = (tx) => new Promise((resolve, reject) => {
  tx.oncomplete = () => resolve();
  tx.onabort = () => reject(tx.error || new Error('idb transaction aborted'));
  tx.onerror = () => reject(tx.error || new Error('idb transaction failed'));
});
const isQuota = (e) => Boolean(e && (e.name === 'QuotaExceededError' || e.code === 22 || e.name === 'NS_ERROR_DOM_QUOTA_REACHED'));
const copy = (bytes) => Uint8Array.from(bytes);

export class EvidenceStore {
  /**
   * @param {{rulesetResolver?: Function|null, idb?: IDBFactory|null, storage?: {persist?:Function}|null, onError?: Function}} [opts]
   *   rulesetResolver: forwarded to bundle validation (null = ruleset-dependent checks are skipped: preservation is not execution).
   */
  constructor(opts = {}) {
    this.rulesetResolver = opts.rulesetResolver || null;
    this._idb = opts.idb !== undefined ? opts.idb : globalThis.indexedDB;
    this._storage = opts.storage !== undefined ? opts.storage : globalThis.navigator?.storage;
    this.onError = typeof opts.onError === 'function' ? opts.onError : null;
    /** @type {Map<string, {digest:string, size:number, runId:string|null, seq:number}>} index only, no bytes */
    this.index = new Map();
    /** @type {Map<string, Uint8Array>} bytes that exist only in memory (no IndexedDB, or a write failed) */
    this.pending = new Map();
    this.backend = 'memory';
    this.persisted = null;
    this.lastError = null;
    this._seq = 0;
    this._db = null;
  }

  /** True only while IndexedDB is the backend and no bundle is memory-only. */
  get durable() { return this._db !== null && this.pending.size === 0; }

  /** Open the database and load the index (not the bundles). Never rejects; check `backend`/`durable` afterwards. */
  async init() {
    try {
      if (this._idb) {
        const db = await new Promise((resolve, reject) => {
          const timer = setTimeout(() => reject(new Error('idb open timeout')), IDB_TIMEOUT_MS);
          const req = this._idb.open(EVIDENCE_DB, EVIDENCE_DB_VERSION);
          req.onupgradeneeded = () => {
            const d = req.result;
            if (!d.objectStoreNames.contains(EVIDENCE_STORE)) d.createObjectStore(EVIDENCE_STORE, { keyPath: 'digest' });
            if (!d.objectStoreNames.contains(EVIDENCE_INDEX)) d.createObjectStore(EVIDENCE_INDEX, { keyPath: 'digest' });
          };
          req.onsuccess = () => { clearTimeout(timer); resolve(req.result); };
          req.onerror = () => { clearTimeout(timer); reject(req.error); };
          req.onblocked = () => { clearTimeout(timer); reject(new Error('idb blocked')); };
        });
        const all = await req2p(db.transaction(EVIDENCE_INDEX, 'readonly').objectStore(EVIDENCE_INDEX).getAll());
        for (const r of all || []) {
          if (r && typeof r.digest === 'string') { this.index.set(r.digest, r); this._seq = Math.max(this._seq, r.seq || 0); }
        }
        this._db = db;
        this.backend = 'idb';
      }
    } catch (e) {
      this._db = null;
      this.backend = 'memory';
      this._report(new EvidenceStoreError('read-failed', 'IndexedDB unavailable; evidence is memory-only', e));
    }
    return this;
  }

  /** Best-effort `navigator.storage.persist()`; call from an explicit user action (export/keep), never unasked. */
  async requestPersistence() {
    try {
      if (this._storage && typeof this._storage.persist === 'function') this.persisted = Boolean(await this._storage.persist());
    } catch { this.persisted = null; }
    return this.persisted;
  }

  _report(err) {
    this.lastError = err;
    if (this.onError) { try { this.onError(err); } catch { /* a UI callback must not break the store */ } }
  }

  async _writeDurable(record, bytes) {
    const tx = this._db.transaction([EVIDENCE_STORE, EVIDENCE_INDEX], 'readwrite');
    const done = txDone(tx);
    tx.objectStore(EVIDENCE_STORE).put({ digest: record.digest, bytes });
    tx.objectStore(EVIDENCE_INDEX).put(record);
    await done;
  }

  /**
   * Store a bundle (object or canonical bytes). Returns its digest. Rejects when the bundle is invalid or when a durable
   * write fails (the bundle then stays in memory for this session and `durable` is false until a later write succeeds).
   * @param {object|Uint8Array} bundle
   * @param {{runId?: string}} [meta] local index only; never exported
   * @param {{ok:true, bundleDigest:string}|null} [validated] result of validateEvidenceBundle for exactly these bytes:
   *   skips the second validation and hash
   */
  async put(bundle, meta = {}, validated = null) {
    const bytes = ArrayBuffer.isView(bundle) ? copy(bundle) : bundleBytes(bundle);
    let digest;
    if (validated && validated.ok === true && typeof validated.bundleDigest === 'string') digest = validated.bundleDigest;
    else {
      const res = validateEvidenceBundle(bytes, this.rulesetResolver);
      if (!res.ok) throw new EvidenceStoreError('invalid-bundle', `${res.code} at ${res.pointer}`, res);
      digest = res.bundleDigest;
    }
    const prior = this.index.get(digest);
    const record = { digest, size: bytes.length, runId: meta.runId || (prior && prior.runId) || null, seq: prior ? prior.seq : ++this._seq };
    this.index.set(digest, record);
    // Memory-only backend (no IndexedDB): the caller sees `durable === false` (init() also reported it once).
    if (!this._db) { this.pending.set(digest, bytes); return digest; }
    try {
      await this._writeDurable(record, bytes);
      this.pending.delete(digest);
    } catch (e) {
      this.pending.set(digest, bytes);
      const err = new EvidenceStoreError(isQuota(e) ? 'quota-exceeded' : 'write-failed', e && e.message, e);
      this._report(err);
      throw err;
    }
    await this._flushPending();
    return digest;
  }

  /** Retry bundles that are still memory-only. Failures stay pending and are not reported again. */
  async _flushPending() {
    for (const [digest, bytes] of [...this.pending]) {
      try { await this._writeDurable(this.index.get(digest), bytes); this.pending.delete(digest); } catch { return; }
    }
  }

  has(digest) { return this.index.has(digest); }

  /** Local index (no bytes), in insertion order. */
  list() { return [...this.index.values()].sort((a, b) => a.seq - b.seq).map((r) => ({ digest: r.digest, runId: r.runId, size: r.size })); }

  /** Canonical bytes of a stored bundle, read on demand and re-hashed against their key; null when absent. */
  async get(digest) {
    if (!this.index.has(digest)) return null;
    let bytes = this.pending.get(digest);
    if (!bytes && this._db) {
      try {
        const row = await req2p(this._db.transaction(EVIDENCE_STORE, 'readonly').objectStore(EVIDENCE_STORE).get(digest));
        bytes = row && row.bytes;
      } catch (e) { throw new EvidenceStoreError('read-failed', digest, e); }
    }
    if (!bytes) throw new EvidenceStoreError('corrupt-record', `${digest}: indexed but no bytes`);
    if (digestOfBytes(bytes) !== digest) throw new EvidenceStoreError('corrupt-record', digest);
    return copy(bytes);
  }

  /** `.bbreplay` export: the canonical bytes plus their digest and a suggested file name. An explicit user action: asks the browser to persist storage. */
  async exportBundle(digest) {
    const bytes = await this.get(digest);
    if (!bytes) throw new EvidenceStoreError('not-found', digest);
    await this.requestPersistence();
    return { digest, bytes, filename: bundleFilename(digest) };
  }

  /**
   * Import `.bbreplay` bytes. `expectedDigest` is REQUIRED (the digest the export reported / the file name carries):
   * without it a single flipped byte inside a checkpoint or an input would import as a different valid bundle.
   * Verifies the digest and then the whole bundle before storing. Non-canonical or corrupt bytes are refused, never repaired.
   */
  async importBundle(bytes, { expectedDigest, runId } = {}) {
    if (typeof expectedDigest !== 'string' || !expectedDigest) throw new EvidenceStoreError('digest-required', 'importBundle needs the expected bundle digest');
    const actual = bundleDigest(bytes);
    if (expectedDigest !== actual) throw new EvidenceStoreError('digest-mismatch', `expected ${expectedDigest}, got ${actual}`);
    return this.put(bytes, { runId });
  }

  /** Explicit user deletion. Nothing else ever removes evidence. */
  async remove(digest) {
    this.index.delete(digest);
    this.pending.delete(digest);
    if (this._db) {
      try {
        const tx = this._db.transaction([EVIDENCE_STORE, EVIDENCE_INDEX], 'readwrite');
        const done = txDone(tx);
        tx.objectStore(EVIDENCE_STORE).delete(digest);
        tx.objectStore(EVIDENCE_INDEX).delete(digest);
        await done;
      } catch (e) {
        const err = new EvidenceStoreError('write-failed', e && e.message, e);
        this._report(err);
        throw err;
      }
    }
  }
}/**
 * Frame fingerprints for Replay Contract v1 (docs/replay/replay-contract-v1.md, section 6; issue #118): schema-driven BB-FP
 * encoding, per-subsystem and combined `xxh32x2` digests, a flat field dump, and `compareRuns` (first-divergence
 * localization). Fingerprints are drift detectors, never proofs of anything (section 3.2).
 *
 * Pure module: no Phaser, no clock, no randomness. Capture (reading a live scene) is fingerprintCapture.js.
 */
import { FpWriter, combineFingerprints, fingerprintOf } from './canonicalBinary.js';
import { f64Encode } from './canonicalJson.js';
import { FP_SCHEMAS, FP_SUBSYSTEMS, FP_VERSION } from './fingerprintSchemas.js';

export { FP_SCHEMAS, FP_SUBSYSTEMS, FP_VERSION };

const hasOwn = (o, k) => Object.prototype.hasOwnProperty.call(o, k);

const FP_ERR = (path, msg) => new TypeError(`fingerprint ${path}: ${msg}`);

/**
 * Write `value` by `schema` (BB-FP v1, section 6.5). Strict: a missing field, an extra field, a wrong type or an
 * out-of-range integer throws with a path, because a silent default would hide drift.
 * @param {FpWriter} w
 * @param {*} schema DSL node
 * @param {*} v
 * @param {string} [path]
 * @returns {FpWriter}
 */
export function encodeBySchema(w, schema, v, path = '$') {
  if (typeof schema === 'string') {
    try {
      switch (schema) {
        case 'u32': return w.u32(v);
        case 'i32': return w.i32(v);
        case 'f64': return w.f64(v);
        case 'bool': return w.bool(v);
        case 'str': return w.str(v);
        default: throw new Error(`unknown schema type "${schema}"`);
      }
    } catch (e) {
      throw FP_ERR(path, e.message);
    }
  }
  if (hasOwn(schema, 'opt')) {
    if (v === undefined) throw FP_ERR(path, 'undefined is not a valid optional (use null)');
    return w.opt(v, (ww, x) => encodeBySchema(ww, schema.opt, x, path));
  }
  if (hasOwn(schema, 'list')) {
    if (!Array.isArray(v)) throw FP_ERR(path, `expected an array, got ${typeof v}`);
    return w.list(v, (ww, x, i) => encodeBySchema(ww, schema.list, x, `${path}[${i}]`));
  }
  if (hasOwn(schema, 'rec')) {
    if (v === null || typeof v !== 'object') throw FP_ERR(path, `expected a record, got ${v === null ? 'null' : typeof v}`);
    const names = new Set();
    for (const [name, type] of schema.rec) {
      if (!hasOwn(v, name)) throw FP_ERR(`${path}.${name}`, 'missing field');
      names.add(name);
      encodeBySchema(w, type, v[name], `${path}.${name}`);
    }
    for (const k of Object.keys(v)) if (!names.has(k)) throw FP_ERR(`${path}.${k}`, 'field is not in the schema');
    return w;
  }
  throw FP_ERR(path, 'malformed schema node');
}

/**
 * The BB-FP bytes of one subsystem: `u32 schemaVersion` then the fields in schema order.
 * @param {string} name subsystem
 * @param {*} value that subsystem's plain-object state
 * @returns {Uint8Array}
 */
export function encodeSubsystem(name, value) {
  const def = FP_SCHEMAS[name];
  if (!def) throw new Error(`unknown fingerprint subsystem "${name}"`);
  const w = new FpWriter(256);
  w.u32(def.version);
  encodeBySchema(w, def.schema, value, name);
  return w.bytes();
}

/** `xxh32x2:<16 hex>` of one subsystem's state. */
export function fingerprintSubsystem(name, value) {
  return fingerprintOf(encodeSubsystem(name, value));
}

/**
 * @typedef {{fp:number, tick:number, combined:string, subsystems:Object<string,string>}} FingerprintResult
 * Per-subsystem digests plus the combined digest (`u32 fpVersion | u32 tick | u32 count | count x 8 digest bytes`).
 * @param {{fp:number, tick:number}} state a CausalState from captureCausalState (or any state of the same shape)
 * @returns {FingerprintResult}
 */
export function fingerprintState(state) {
  if (!state || state.fp !== FP_VERSION) throw new TypeError(`fingerprintState: expected a CausalState with fp=${FP_VERSION}`);
  const subsystems = {};
  for (const name of FP_SUBSYSTEMS) {
    if (!hasOwn(state, name)) throw new Error(`fingerprintState: missing subsystem "${name}"`);
    subsystems[name] = fingerprintSubsystem(name, state[name]);
  }
  return { fp: FP_VERSION, tick: state.tick, combined: combineFingerprints(state.tick, subsystems, FP_SUBSYSTEMS), subsystems };
}

// ---------------------------------------------------------------------------------------------------------------------
// dumpState
// ---------------------------------------------------------------------------------------------------------------------

function dumpNode(out, schema, v, path) {
  if (typeof schema === 'string') {
    out[path] = schema === 'f64' ? f64Encode(v) : v;
  } else if (hasOwn(schema, 'opt')) {
    if (v === null) out[path] = null;
    else dumpNode(out, schema.opt, v, path);
  } else if (hasOwn(schema, 'list')) {
    out[`${path}.length`] = v.length;
    for (let i = 0; i < v.length; i++) dumpNode(out, schema.list, v[i], `${path}[${i}]`);
  } else {
    for (const [name, type] of schema.rec) dumpNode(out, type, v[name], `${path}.${name}`);
  }
}

/**
 * Flat field dump of a CausalState: `{ "bsod.wallX": "f64:c0bd2fecccccccce", "kodiak.bears[0].phase": "approach", ... }`.
 * Floats are F64 hex strings (so -0, Infinity and NaN are visible and exact), integers and booleans are literal, an absent
 * optional is `null`, a list adds `<path>.length`. Key order is the canonical schema order (FP_SUBSYSTEMS order, then the
 * schema's field order, then ascending index), which is what "first differing field" means.
 * @param {{fp:number, tick:number}} state
 * @param {{subsystems?: string[]}} [opts] restrict to some subsystems
 * @returns {Object<string, string|number|boolean|null>}
 */
export function dumpState(state, opts = {}) {
  const names = opts.subsystems || FP_SUBSYSTEMS;
  const out = { tick: state.tick };
  for (const name of FP_SUBSYSTEMS) {
    if (!names.includes(name)) continue;
    dumpNode(out, FP_SCHEMAS[name].schema, state[name], name);
  }
  return out;
}

// ---------------------------------------------------------------------------------------------------------------------
// compareRuns
// ---------------------------------------------------------------------------------------------------------------------

/**
 * @typedef {Object} RunTrace
 * @property {string} [causalDigest] `sha256:` of the manifest `causal` object; two runs are only comparable when equal
 * @property {string} [manifestDigest] informational
 * @property {number} [endTick] last simulated tick of the run (`causal.input.endTick`); compared when both sides have it
 * @property {Array<{tick:number, combined:string, subsystems?:Object<string,string>}>} checkpoints ascending by tick
 * @property {(w:{fromTick:number, toTick:number}) => Promise<FingerprintResult[]>|FingerprintResult[]} [resimulate]
 *   re-simulate this side from tick 0 and return the per-tick fingerprint (with `subsystems`) of every tick in
 *   (fromTick, toTick]; the caller owns the simulator, this module never imports one
 * @property {(tick:number) => Promise<object>|object} [dumpAt] CausalState at a tick (a re-simulation capture)
 */

/**
 * @typedef {Object} CompareResult
 * @property {'match'|'diverged'|'inconclusive'} status
 * @property {number|null} firstDivergentTick first tick whose combined digest differs (needs both resimulate callbacks)
 * @property {number|null} firstDivergentCheckpoint first checkpoint tick whose combined digest differs
 * @property {string|null} subsystem owner of `fieldPath`
 * @property {string|null} fieldPath first differing field in canonical order (`bsod.wallX`)
 * @property {*} expected `a`'s value at `fieldPath`
 * @property {*} actual `b`'s value at `fieldPath`
 * @property {string[]} differingSubsystems subsystems whose digest differs at firstDivergentTick (FP_SUBSYSTEMS order)
 * @property {string[]} matchingSubsystems the rest
 * @property {number} resims simulations started (resimulate calls)
 * @property {string[]} differingPaths additive: every differing field of `subsystem` at firstDivergentTick, canonical order
 * @property {string} [note]
 */

const result = (over) => ({
  status: 'match', firstDivergentTick: null, firstDivergentCheckpoint: null, subsystem: null, fieldPath: null,
  expected: null, actual: null, differingSubsystems: [], matchingSubsystems: [...FP_SUBSYSTEMS], resims: 0,
  differingPaths: [], ...over,
});

const splitSubsystems = (a, b) => {
  const differing = FP_SUBSYSTEMS.filter((n) => a[n] !== b[n]);
  return { differing, matching: FP_SUBSYSTEMS.filter((n) => a[n] === b[n]) };
};

const ownerOf = (path) => path.slice(0, path.search(/[.[]/) < 0 ? path.length : path.search(/[.[]/));

/**
 * Compare two runs of the same causal inputs and localize the first divergence (section 6.6, steps 1-5).
 *  1. refuse (inconclusive, note "causal-mismatch") when the causal digests differ, unless `opts.ignoreCausal`;
 *  2. find the first checkpoint whose combined digest differs (or a different checkpoint list);
 *  3. name the differing subsystems there (from stored `full` detail, else from the re-simulation);
 *  4. re-simulate both sides once over (previous matching checkpoint, divergent checkpoint] and find the first tick whose
 *     per-tick combined digest differs;
 *  5. dump both sides at that tick and diff the flat dumps.
 * `a` is the reference ("expected"), `b` the run under test ("actual"). Re-simulation is injected through
 * `RunTrace.resimulate/dumpAt`; without it the result stops at checkpoint resolution and is `inconclusive`.
 * @param {RunTrace} a
 * @param {RunTrace} b
 * @param {{ignoreCausal?: boolean}} [opts]
 * @returns {Promise<CompareResult>}
 */
export async function compareRuns(a, b, opts = {}) {
  let resims = 0;
  if (!opts.ignoreCausal) {
    if (!a.causalDigest || !b.causalDigest) return result({ status: 'inconclusive', note: 'no-causal-digest' });
    if (a.causalDigest !== b.causalDigest) return result({ status: 'inconclusive', note: 'causal-mismatch' });
  }
  const ca = a.checkpoints || [];
  const cb = b.checkpoints || [];
  if (ca.length === 0 && cb.length === 0) return result({ status: 'inconclusive', note: 'no-checkpoints' });
  // A gap (a capture that failed, or a stripped checkpoint) must never be read as agreement or as a divergence.
  const every = opts.everyTicks || 120;
  for (const c of [ca, cb]) {
    if (c.some((x, i) => x.tick !== (i + 1) * every)) return result({ status: 'inconclusive', note: 'checkpoint-gap' });
  }
  const n = Math.min(ca.length, cb.length);
  let idx = -1;
  for (let i = 0; i < n; i++) {
    if (ca[i].tick !== cb[i].tick) {
      return result({ status: 'diverged', firstDivergentCheckpoint: Math.min(ca[i].tick, cb[i].tick), note: 'checkpoint-tick-mismatch' });
    }
    if (ca[i].combined !== cb[i].combined) { idx = i; break; }
  }
  if (idx < 0) {
    if (ca.length !== cb.length) {
      const longer = ca.length > cb.length ? ca : cb;
      return result({ status: 'diverged', firstDivergentCheckpoint: longer[n].tick, note: 'checkpoint-count-mismatch' });
    }
    if (a.endTick !== undefined && b.endTick !== undefined && a.endTick !== b.endTick) {
      return result({ status: 'diverged', note: 'end-tick-mismatch' });
    }
    return result({ status: 'match', ...(a.endTick === undefined || b.endTick === undefined ? { note: 'end-tick-not-compared' } : {}) });
  }
  const t1 = ca[idx].tick;
  const t0 = idx > 0 ? ca[idx - 1].tick : 0;
  const base = { firstDivergentCheckpoint: t1 };

  // Step 3 from stored detail, when both sides have it.
  let storedSplit = null;
  if (ca[idx].subsystems && cb[idx].subsystems) storedSplit = splitSubsystems(ca[idx].subsystems, cb[idx].subsystems);

  if (typeof a.resimulate !== 'function' || typeof b.resimulate !== 'function') {
    return result({
      ...base, status: 'inconclusive', note: 'no-resimulate',
      differingSubsystems: storedSplit ? storedSplit.differing : [], matchingSubsystems: storedSplit ? storedSplit.matching : [...FP_SUBSYSTEMS],
    });
  }

  // Step 4: one re-simulation per side over the window.
  const window = { fromTick: t0, toTick: t1 };
  const ra = await a.resimulate(window); resims++;
  const rb = await b.resimulate(window); resims++;
  const want = t1 - t0;
  if (!Array.isArray(ra) || !Array.isArray(rb) || ra.length !== want || rb.length !== want
    || ra.some((r, i) => r.tick !== t0 + 1 + i) || rb.some((r, i) => r.tick !== t0 + 1 + i)) {
    return result({ ...base, status: 'inconclusive', resims, note: 'bad-resimulation-window' });
  }
  let k = -1;
  for (let i = 0; i < want; i++) if (ra[i].combined !== rb[i].combined) { k = i; break; }
  if (k < 0) {
    return result({ ...base, status: 'inconclusive', resims, note: 'divergence-not-reproduced' });
  }
  // The re-simulation must reproduce what was recorded at the checkpoint, or its first divergence means nothing.
  if (ra[want - 1].combined !== ca[idx].combined || rb[want - 1].combined !== cb[idx].combined) {
    return result({ ...base, status: 'inconclusive', resims, note: 'resim-does-not-reproduce-checkpoint' });
  }
  const tick = ra[k].tick;
  const split = splitSubsystems(ra[k].subsystems || {}, rb[k].subsystems || {});
  const out = { ...base, firstDivergentTick: tick, resims, differingSubsystems: split.differing, matchingSubsystems: split.matching };

  // Step 5: field-level diff.
  if (typeof a.dumpAt !== 'function' || typeof b.dumpAt !== 'function') {
    return result({ ...out, status: 'diverged', subsystem: split.differing[0] ?? null, note: 'no-dumpAt' });
  }
  const da = dumpState(await a.dumpAt(tick));
  const db = dumpState(await b.dumpAt(tick));
  const paths = [];
  const seen = new Set();
  for (const p of Object.keys(da)) { seen.add(p); if (!Object.is(da[p], db[p])) paths.push(p); }
  for (const p of Object.keys(db)) if (!seen.has(p) && !Object.is(da[p], db[p])) paths.push(p);
  const first = paths[0];
  if (first === undefined) {
    return result({ ...out, status: 'diverged', subsystem: split.differing[0] ?? null, note: 'dumps-identical-but-digests-differ' });
  }
  const subsystem = ownerOf(first);
  return result({
    ...out, status: 'diverged', subsystem, fieldPath: first, expected: first in da ? da[first] : null,
    actual: first in db ? db[first] : null, differingPaths: paths.filter((p) => ownerOf(p) === subsystem),
  });
}/**
 * Causal-state capture for Replay Contract v1 (docs/replay/replay-contract-v1.md, section 6.6; issue #118).
 *
 * `captureCausalState(sceneLike)` copies the authoritative causal state of a run into plain objects shaped exactly like the
 * schemas in fingerprintSchemas.js. It is READ-ONLY (never assigns to the scene, never advances a RNG, never calls a
 * method that could) and allocates, so it runs only at checkpoint ticks (GhostRecorder.afterTick, every 120 ticks) or in
 * an explicit diagnostic window, never per tick in production.
 *
 * `sceneLike` is a duck type: what RunScene exposes (and what GhostRecorder.afterTick already receives). Pure module: no
 * Phaser import, no clock, no randomness.
 */
import { FP_VERSION, fingerprintOf, FpWriter } from './canonicalBinary.js';

export { FP_VERSION };

const hasOwn = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
const opt = (v) => (v === undefined || v === null ? null : v);
const sortedStrings = (iter) => Array.from(iter, String).sort(); // default sort = UTF-16 code unit order
const numericAsc = (iter) => Array.from(iter).sort((x, y) => x - y);

/** Throw unless `obj` has exactly the expected keys: a new key means the schema is stale, which must be loud. */
function exactKeys(obj, keys, what) {
  const have = Object.keys(obj);
  if (have.length !== keys.length || !keys.every((k) => hasOwn(obj, k))) {
    throw new Error(`fingerprint capture: ${what} keys [${have.join(',')}] differ from [${keys.join(',')}]; update the schema`);
  }
}

/** Sorted `{k, v}` list of a string -> number map (paid, counts, trickCounts). */
const kvList = (map) => Object.keys(map || {}).sort().map((k) => ({ k, v: map[k] }));

// -----------------------------------------------------------------------------------------------------------------
// bb-pad v1 identity of the last pad (section 4.3): bool fields in bit order, then edge fields, then 2 heli bits.
// Duplicated here on purpose (not imported from GhostTape: no import cycle); a test asserts equality with encodePad.
// -----------------------------------------------------------------------------------------------------------------
const PAD_BOOL = ['push', 'variableHop', 'noAutoNudge', 'divebomb', 'corkscrew', 'tuck', 'brakeHeld', 'hop', 'reset', 'airBrake', 'parachute', 'pause'];
const PAD_EDGE = ['hop', 'reset', 'pause', 'airBrake', 'parachute', 'confirm'];
const PAD_HELI_SHIFT = PAD_BOOL.length + PAD_EDGE.length;

/** @returns {{bits:number, tilt127:number}} the pad as the tape would store it (tilt quantized to 1/127). */
export function padIdentity(pad) {
  let bits = 0;
  PAD_BOOL.forEach((k, i) => { if (pad[k]) bits |= 1 << i; });
  PAD_EDGE.forEach((k, i) => { if (pad.pressed && pad.pressed[k]) bits |= 1 << (PAD_BOOL.length + i); });
  if (pad.heli > 0) bits |= 1 << PAD_HELI_SHIFT; else if (pad.heli < 0) bits |= 2 << PAD_HELI_SHIFT;
  const t = Number.isFinite(pad.tilt) ? Math.max(-1, Math.min(1, pad.tilt)) : 0;
  const tilt127 = Math.round(Math.round(t * 127) / 127 * 127);
  return { bits: bits >>> 0, tilt127: tilt127 === 0 ? 0 : tilt127 };
}

// -----------------------------------------------------------------------------------------------------------------
// terrain: GV1 chunk digest
// -----------------------------------------------------------------------------------------------------------------

/**
 * GV1 (generic value, v1): tag byte then payload. 0 null, 1 false, 2 true, 3 f64 (any NaN canonical), 4 str, 5 list
 * (u32 count, elements), 6 record (u32 count, then key str + value in UTF-16 key order). `undefined` record entries are
 * skipped (absent), `undefined` in a list throws. Typed arrays encode as lists of f64.
 */
function writeGv1(w, v, depth) {
  if (depth > 24) throw new Error('fingerprint capture: GV1 value is too deep or cyclic');
  if (v === null) { w._need(1); w.buf[w.len++] = 0; return; }
  switch (typeof v) {
    case 'boolean': w._need(1); w.buf[w.len++] = v ? 2 : 1; return;
    case 'number': w._need(1); w.buf[w.len++] = 3; w.f64(v); return;
    case 'string': w._need(1); w.buf[w.len++] = 4; w.str(v); return;
    case 'object': break;
    default: throw new TypeError(`fingerprint capture: GV1 cannot encode ${typeof v}`);
  }
  if (Array.isArray(v) || ArrayBuffer.isView(v)) {
    w._need(1); w.buf[w.len++] = 5; w.u32(v.length);
    for (let i = 0; i < v.length; i++) {
      if (v[i] === undefined) throw new TypeError('fingerprint capture: GV1 list contains undefined');
      writeGv1(w, v[i], depth + 1);
    }
    return;
  }
  const keys = Object.keys(v).filter((k) => v[k] !== undefined).sort();
  w._need(1); w.buf[w.len++] = 6; w.u32(keys.length);
  for (const k of keys) { w.str(k); writeGv1(w, v[k], depth + 1); }
}

/** `xxh32x2:` digest of a chunk's immutable generated content (every own enumerable property, GV1-encoded). */
export function chunkDigestOf(chunk) {
  const w = new FpWriter(1024);
  writeGv1(w, chunk, 0);
  return fingerprintOf(w.bytes());
}

const chunkMemo = new WeakMap(); // terrain generator -> Map(index -> digest); capture-side cache, never game state

function chunkDigest(terrain, index, memo) {
  let m = null;
  if (memo) {
    m = chunkMemo.get(terrain);
    if (!m) chunkMemo.set(terrain, (m = new Map()));
    const hit = m.get(index);
    if (hit !== undefined) return hit;
  }
  // `active` holds the live (pooled) chunk object for a joined index; never call terrain.getChunk (it fills caches).
  const chunk = terrain.active && terrain.active.get ? terrain.active.get(index) : undefined;
  if (!chunk) return 'absent'; // joined but already recycled: deterministic, and not memoized
  const d = chunkDigestOf(chunk);
  if (m) m.set(index, d);
  return d;
}

// -----------------------------------------------------------------------------------------------------------------
// Matter
// -----------------------------------------------------------------------------------------------------------------

function bodyRecord(b) {
  return {
    x: b.position.x, y: b.position.y, px: b.positionPrev.x, py: b.positionPrev.y, angle: b.angle, anglePrev: b.anglePrev,
    vx: b.velocity.x, vy: b.velocity.y, angVel: b.angularVelocity,
    fx: b.force.x, fy: b.force.y, torque: b.torque,
    posImpX: b.positionImpulse.x, posImpY: b.positionImpulse.y,
    conImpX: b.constraintImpulse.x, conImpY: b.constraintImpulse.y, conImpAngle: b.constraintImpulse.angle,
    deltaTime: b.deltaTime, totalContacts: b.totalContacts | 0, isSleeping: !!b.isSleeping,
  };
}

const partRecord = (p) => ({ x: p.position.x, y: p.position.y, px: p.positionPrev.x, py: p.positionPrev.y, angle: p.angle, anglePrev: p.anglePrev });

function captureSled(sled) {
  const b = sled.body;
  const lastPad = sled._lastPad ? padIdentity(sled._lastPad) : null;
  return {
    body: bodyRecord(b),
    parts: b.parts.filter((p) => p.id !== b.id).map(partRecord),
    ctl: {
      msSinceContact: sled.msSinceContact, groundAngleDeg: sled.groundAngleDeg, airtimeMs: sled.airtimeMs,
      hopBufferMs: sled.hopBufferMs, playerHopElapsedMs: sled._playerHopElapsedMs, protectedHopExtraVyPxS: sled._protectedHopExtraVyPxS || 0, pushCooldownMs: sled.pushCooldownMs,
      parachuteMs: sled.parachuteMs, parachuteFuelMs: sled.parachuteFuelMs, canopyFuelFullMs: opt(sled.canopyFuelFullMs),
      heliPhase: sled.heliPhase, heliVel: sled.heliVel, invulnerableMs: sled.invulnerableMs, boostMs: sled.boostMs,
      geyserCooldownMs: sled.geyserCooldownMs ?? 0, // the sim reads `(geyserCooldownMs || 0)`
      airEtaMs: sled.airEtaMs, airSlopeDeg: opt(sled.airSlopeDeg), dropAheadDeg: sled.dropAheadDeg,
      groundRunMs: sled._groundRunMs, sinceLaunchMs: sled._sinceLaunchMs, landSettleMs: sled._landSettleMs,
      crawlMs: sled._crawlMs ?? 0, // the sim reads `(_crawlMs || 0)`
      lastTilt: sled._lastTilt, preVx: opt(sled._preVx), preVy: opt(sled._preVy),
      touchdownVx: opt(sled.touchdownVx), touchdownVy: opt(sled.touchdownVy), heliInput: sled.heliInput | 0,
    },
    flags: {
      contactFlag: !!sled._contactFlag, playerHopActive: !!sled._playerHopActive, chuteUsed: !!sled.chuteUsed,
      tucked: !!sled.tucked, airBrakeActive: !!sled.airBrakeActive, airBrakePressPending: !!sled.airBrakePressPending,
      airBrakeKickUsed: !!sled.airBrakeKickUsed, airBrakeLiftProtected: !!sled.airBrakeLiftProtected, airBrakeKickPulse: !!sled.airBrakeKickPulse, corkscrewActive: !!sled.corkscrewActive,
      scrambled: !!sled.scrambled, nudging: !!sled._nudging, inWorld: !!sled.inWorld,
      destroyed: !!sled.destroyed,
    },
    lastPad,
  };
}

function captureMatter(scene) {
  const engine = scene.matter.world.engine;
  const sledBody = scene.sled.body;
  const bodies = [];
  const staticOrder = [];
  for (const b of engine.detector.bodies) {
    if (b.id === sledBody.id) continue; // compare by Matter id (stable within one engine), not by object identity
    if (b.isStatic) staticOrder.push({ label: String(b.label), minX: b.bounds.min.x, minY: b.bounds.min.y, padLast: b.bbPad ? opt(b.bbPad._last) : null });
    else bodies.push({ label: String(b.label), sensor: !!b.isSensor, ...bodyRecord(b), parts: b.parts.filter((q) => q.id !== b.id).map(partRecord) });
  }
  const pairs = [];
  for (const p of engine.pairs.list) {
    pairs.push({
      aLabel: String(p.bodyA.label), bLabel: String(p.bodyB.label), aMinX: p.bodyA.bounds.min.x, bMinX: p.bodyB.bounds.min.x,
      active: !!p.isActive, separation: p.separation, contactCount: p.contactCount | 0,
      contacts: p.contacts.map((c) => ({ normalImpulse: c.normalImpulse, tangentImpulse: c.tangentImpulse })),
    });
  }
  const g = engine.gravity;
  return {
    timestamp: engine.timing.timestamp, lastDelta: engine.timing.lastDelta, // never lastElapsed (wall clock) or metrics
    gravity: { x: g.x, y: g.y, scale: g.scale }, bodies, staticOrder, pairs,
  };
}

// -----------------------------------------------------------------------------------------------------------------
// the rest
// -----------------------------------------------------------------------------------------------------------------

function captureTerrain(scene, memo) {
  const joined = numericAsc(scene.mesh.chunks.keys());
  return {
    seedState: scene.terrain.seedState >>> 0,
    biomeMask: scene.biomeMask >>> 0,
    joined,
    queue: numericAsc(scene._chunkQueue ? scene._chunkQueue.keys() : []),
    chunkDigests: joined.map((i) => chunkDigest(scene.terrain, i, memo)),
  };
}

function captureHazards(scene) {
  const chunks = [];
  for (const chunk of numericAsc(scene.hazards.keys())) {
    const items = scene.hazards.get(chunk).map((h) => ({
      defId: String(h.def.id), hit: !!h.hit, destroyed: !!h.destroyed, open: !!h.open, rolling: !!h.rolling,
      nearMissed: !!h.nearMissed, side: opt(h._side), phase: h.phase,
      roll: {
        activeAtMs: opt(h.roll.activeAtMs), offsetPx: h.roll.offsetPx, vPxS: h.roll.vPxS, simMs: h.roll.simMs,
        simDist: h.roll.simDist, simV: h.roll.simV,
      },
    }));
    chunks.push({ chunk, items });
  }
  return { chunks };
}

function capturePickups(scene) {
  const liveShards = [];
  const by = scene.shardField.byChunk;
  for (const chunk of numericAsc(by.keys())) {
    liveShards.push({ chunk, shards: by.get(chunk).map((s) => ({ id: String(s.id), x: s.x, y: s.y })) });
  }
  return {
    collectedPowerups: sortedStrings(scene.collectedPowerups),
    shardCollected: sortedStrings(scene.shardField.collected),
    activeZones: sortedStrings(scene.activeZones.keys()),
    liveShards,
  };
}

/** ShardMagnet.magnetStrength with a multiplier of 1: the only fields of a magnet effect the sim reads. */
function magnetEffRecord(eff) {
  if (eff === null || eff === undefined) return null;
  return {
    pullRadiusPx: Number.isFinite(eff.pullRadiusPx) ? eff.pullRadiusPx : 96,
    pullPxS: Number.isFinite(eff.pullPxS) ? eff.pullPxS : 360,
  };
}

function captureEffects(s) {
  return {
    slowMs: s.slowMs, slowFactor: s.slowFactor, scrambleMs: s.scrambleMs, boostMs: s.boostMs, boostFactor: s.boostFactor,
    slowmoMs: s.slowmoMs, slowmoScale: s.slowmoScale, hitStopMs: s.hitStopMs, blinkMs: s.blinkMs,
    resetCooldownMs: s.resetCooldownMs, glideMs: s.glideMs, glideMul: s.glideMul, stabilizeMs: s.stabilizeMs,
    stabilizeDeg: s.stabilizeDeg, stabilizeBounce: s.stabilizeBounce, magnetMs: s.magnetMs,
    shieldCharges: s.shieldCharges | 0, openingGraces: s.openingGraces | 0, shieldSources: s.shieldSources.map(String),
    wards: s.wards.wards.map((w) => ({
      id: String(w.id), msLeft: w.msLeft, mods: w.mods.map(String), hazards: w.hazards.map(String),
      effects: w.effects.map(String), speedFactor: w.speedFactor,
    })),
    magnetEff: magnetEffRecord(s.magnetEff),
  };
}

function captureBsod(scene) {
  const p = scene.bsod;
  const t = scene.bsodBluffs;
  return {
    active: !!p.active, wallX: p.wallX, wallSpeedPxS: p.wallSpeedPxS, accelerationPxS2: p.accelerationPxS2,
    caught: !!scene.bsodCaught,
    bluff: {
      armed: !!t.armed, usedCanopy: !!t.usedCanopy, usedAirbrake: !!t.usedAirbrake, closestGapPx: opt(t.closestGapPx),
      previousGapPx: opt(t.previousGapPx), chain: t.chain >>> 0, lastAwardX: t.lastAwardX, lastAwardTimeMs: t.lastAwardTimeMs,
    },
  };
}

function captureKodiak(scene) {
  return {
    next: scene.kodiakNext >>> 0,
    on: !!scene.kodiaksOn,
    shoveCdMs: scene.kodiakShoveCdMs,
    bears: (scene.kodiaks || []).map((k) => ({
      kind: String(k.kind), n: k.n >>> 0, member: k.member >>> 0, x: k.x, speed: k.speed, phase: String(k.phase),
      phaseMs: k.phaseMs, ageMs: k.ageMs, rngState: k.rng.state >>> 0, feints: k.feints >>> 0, targetX: opt(k.targetX),
      groundY: k.groundY, sledAhead: !!k.sledAhead, real: k.real === undefined || k.real === null ? null : !!k.real,
      hit: !!k.hit, done: !!k.done,
    })),
  };
}

function captureScore(scene) {
  const m = scene.score;
  exactKeys(m.bonusCounts, ['shard', 'nearMiss', 'milestone'], 'ScoreManager.bonusCounts');
  exactKeys(m.bonusByKind, ['shard', 'nearMiss', 'milestone'], 'ScoreManager.bonusByKind');
  return {
    mgr: {
      distanceM: m.distanceM, trickPoints: m.trickPoints, penaltyPoints: m.penaltyPoints, bonusPoints: m.bonusPoints,
      bestCombo: m.bestCombo, flow: m.flow, flowRemainingMs: m.flowRemainingMs, bestFlow: m.bestFlow, pending: m.pending,
      lastMilestoneSector: m.lastMilestoneSector | 0,
      bonusCounts: { shard: m.bonusCounts.shard, nearMiss: m.bonusCounts.nearMiss, milestone: m.bonusCounts.milestone },
      bonusByKind: { shard: m.bonusByKind.shard, nearMiss: m.bonusByKind.nearMiss, milestone: m.bonusByKind.milestone },
      comboTricks: m.comboTricks.map(String), paid: kvList(m.paid), counts: kvList(m.counts),
    },
    run: {
      shardChain: scene.shardChain, shardChainAt: scene.shardChainAt, shardTotal: scene.shardTotal,
      shardCount: scene.shardCount, nearMissCount: scene.nearMissCount, maxAirtimeMs: scene.maxAirtimeMs,
      bestCombo: scene.bestCombo, lastTotal: scene.lastTotal, trickCounts: kvList(scene.trickCounts),
    },
  };
}

function captureTricks(scene) {
  const t = scene.tricks;
  return {
    tracker: {
      air: !!t._air, airStart: t._airStart, tiltNet: t._tiltNet, heliNet: t._heliNet, tiltDone: t._tiltDone,
      heliDone: t._heliDone, corkscrewNet: t._corkscrewNet, corkscrewDone: t._corkscrewDone, brakeMs: t._brakeMs,
      chuteMs: t._chuteMs, heliMax: t._heliMax, prevAngle: t._prevAngle, brakeDone: !!t._brakeDone,
      chuteDone: !!t._chuteDone, heliHeld: !!t._heliHeld, havePrev: !!t._havePrev, prevHeli: opt(t._prevHeli),
    },
    airTricks: scene._airTricks, landings: scene._landings, steepMs: scene._steepMs,
  };
}

function captureRecovery(scene) {
  const c = scene.pendingCrash;
  if (c) for (const k of Object.keys(c)) if (k !== 'cause' && k !== 'hazardId') throw new Error(`fingerprint capture: pendingCrash.${k} is not in the schema`);
  return {
    pendingCrash: c ? { cause: String(c.cause), hazardId: c.hazardId === undefined || c.hazardId === null ? null : String(c.hazardId) } : null,
    crashTimerMs: scene.crashTimerMs,
    safeSamples: scene.safeSamples.map((q) => ({ t: q.t, x: q.x, y: q.y, vx: q.vx, vy: q.vy, ang: q.ang })),
    safeTimer: scene._safeTimer,
  };
}

/**
 * Capture the causal state of a run. Read-only; allocates; call only at checkpoints or in a diagnostic window.
 * @param {object} scene a RunScene or a duck type with the same fields
 * @param {{chunkMemo?: boolean}} [opts] `chunkMemo:false` re-hashes every joined chunk (tests); default memoizes per index
 * @returns {{fp:number, tick:number, clock:object, rng:object, sled:object, matter:object, terrain:object, hazards:object,
 *   pickups:object, effects:object, bsod:object, kodiak:object, score:object, tricks:object, recovery:object}}
 */
export function captureCausalState(scene, opts = {}) {
  const memo = opts.chunkMemo !== false;
  const tick = scene.simClock.tick;
  return {
    fp: FP_VERSION,
    tick,
    clock: { tick, runTimeMs: scene.runTimeMs, crashed: !!scene.crashed },
    rng: { version: scene.runRandom.version >>> 0, physicsScramble: scene.runRandom.physicsScramble.state >>> 0 },
    sled: captureSled(scene.sled),
    matter: captureMatter(scene),
    terrain: captureTerrain(scene, memo),
    hazards: captureHazards(scene),
    pickups: capturePickups(scene),
    effects: captureEffects(scene),
    bsod: captureBsod(scene),
    kodiak: captureKodiak(scene),
    score: captureScore(scene),
    tricks: captureTricks(scene),
    recovery: captureRecovery(scene),
  };
}/**
 * Frame-fingerprint schemas for Replay Contract v1 (docs/replay/replay-contract-v1.md, sections 6.3, 6.5, 6.8; issue #118).
 *
 * A subsystem schema is the field list (names and order) that BB-FP encodes; names are never encoded, so the schema IS the
 * layout. Every subsystem carries its own `schemaVersion` (starting at 1): adding, removing, reordering or retyping a field
 * is a breaking change that bumps that subsystem's version and keeps the old fixtures valid under the old version.
 *
 * Schema DSL (the same one tests/fixtures/replay/v1/fingerprint-vectors.json uses):
 *   'u32' | 'i32' | 'f64' | 'bool' | 'str' | {opt: T} | {list: T} | {rec: [[name, T], ...]}
 *
 * Pure module: no Phaser, no clock, no randomness.
 *
 * The second half of the file is the anti-drift ledger (section 6.8): for every owner class, each own enumerable property is
 * either mapped to the schema path that covers it (FIELD_SOURCES) or listed in NON_CAUSAL with a reason. The reflection tests
 * (tests/replay/fingerprintCompleteness.test.js) fail when a property is in neither, and prove each FIELD_SOURCES entry by
 * perturbing the real property and watching the owning subsystem digest change.
 */
import { FP_VERSION } from './canonicalBinary.js';

export { FP_VERSION };

/** Fixed order of the 13 subsystems. Stable for v1 (renumbering is a breaking change, section 9). */
export const FP_SUBSYSTEMS = Object.freeze([
  'clock', 'rng', 'sled', 'matter', 'terrain', 'hazards', 'pickups', 'effects', 'bsod', 'kodiak', 'score', 'tricks', 'recovery',
]);

const rec = (...fields) => ({ rec: fields });
const opt = (t) => ({ opt: t });
const list = (t) => ({ list: t });

/** A Matter body's fingerprinted fields (section 6.2): pose, previous pose, velocity, accumulators and contact count. */
const BODY_FIELDS = [
  ['x', 'f64'], ['y', 'f64'], ['px', 'f64'], ['py', 'f64'], ['angle', 'f64'], ['anglePrev', 'f64'],
  ['vx', 'f64'], ['vy', 'f64'], ['angVel', 'f64'],
  ['fx', 'f64'], ['fy', 'f64'], ['torque', 'f64'],
  ['posImpX', 'f64'], ['posImpY', 'f64'], ['conImpX', 'f64'], ['conImpY', 'f64'], ['conImpAngle', 'f64'],
  ['deltaTime', 'f64'], ['totalContacts', 'i32'], ['isSleeping', 'bool'],
];
const PART_FIELDS = [['x', 'f64'], ['y', 'f64'], ['px', 'f64'], ['py', 'f64'], ['angle', 'f64'], ['anglePrev', 'f64']];
const KV = rec(['k', 'str'], ['v', 'f64']);

export const FP_SCHEMAS = Object.freeze({
  // Fixture-pinned (vector 6.10): clock, rng and bsod are byte-identical to the committed vector schemas.
  clock: { version: 1, schema: rec(['tick', 'u32'], ['runTimeMs', 'f64'], ['crashed', 'bool']) },
  rng: { version: 1, schema: rec(['version', 'u32'], ['physicsScramble', 'u32']) },

  sled: {
    version: 3, // v3: one-shot AirBrake state is causal and must be replay-fingerprinted
    schema: rec(
      ['body', rec(...BODY_FIELDS)],
      ['parts', list(rec(...PART_FIELDS))], // the 5 collision parts (the compound root, parts[0], is `body`)
      ['ctl', rec(
        ['msSinceContact', 'f64'], ['groundAngleDeg', 'f64'], ['airtimeMs', 'f64'], ['hopBufferMs', 'f64'],
        ['playerHopElapsedMs', 'f64'], ['protectedHopExtraVyPxS', 'f64'], ['pushCooldownMs', 'f64'], ['parachuteMs', 'f64'], ['parachuteFuelMs', 'f64'],
        ['canopyFuelFullMs', opt('f64')], ['heliPhase', 'f64'], ['heliVel', 'f64'], ['invulnerableMs', 'f64'],
        ['boostMs', 'f64'], ['geyserCooldownMs', 'f64'], ['airEtaMs', 'f64'], ['airSlopeDeg', opt('f64')],
        ['dropAheadDeg', 'f64'], ['groundRunMs', 'f64'], ['sinceLaunchMs', 'f64'], ['landSettleMs', 'f64'],
        ['crawlMs', 'f64'], ['lastTilt', 'f64'], ['preVx', opt('f64')], ['preVy', opt('f64')],
        ['touchdownVx', opt('f64')], ['touchdownVy', opt('f64')], ['heliInput', 'i32'],
      )],
      ['flags', rec(
        ['contactFlag', 'bool'], ['playerHopActive', 'bool'], ['chuteUsed', 'bool'], ['tucked', 'bool'],
        ['airBrakeActive', 'bool'], ['airBrakePressPending', 'bool'], ['airBrakeKickUsed', 'bool'], ['airBrakeLiftProtected', 'bool'], ['airBrakeKickPulse', 'bool'], ['corkscrewActive', 'bool'], ['scrambled', 'bool'],
        ['nudging', 'bool'], ['inWorld', 'bool'], ['destroyed', 'bool'],
      )],
      // Bit identity of the last pad. The sim only uses `pad !== _lastPad` (object identity; each tick gets a fresh pad), so this
      // is a diagnostic mirror, not state to rely on (review N3).
      ['lastPad', opt(rec(['bits', 'u32'], ['tilt127', 'i32']))],
    ),
  },

  matter: {
    version: 2, // v2: staticOrder entries carry `padLast` (bounce-pad cooldown, RunScene.onPad)
    schema: rec(
      ['timestamp', 'f64'], ['lastDelta', 'f64'],
      ['gravity', rec(['x', 'f64'], ['y', 'f64'], ['scale', 'f64'])],
      // Every non-static, non-sled body in detector order. In this game that is normally empty (the sled is the only
      // dynamic body, and its state is the `sled` subsystem); listed for completeness and future dynamic bodies.
      ['bodies', list(rec(['label', 'str'], ['sensor', 'bool'], ...BODY_FIELDS, ['parts', list(rec(...PART_FIELDS))]))],
      // Every static body (terrain colliders, hazard and pickup sensors, bounce pads) in detector order. Position only,
      // except `padLast`: the bounce-pad cooldown stamp RunScene.onPad keeps on `body.bbPad._last` (run ms of the last
      // launch, null when the body is not a pad or has never fired). Hazard sensors that a roll moves have changing bounds.
      ['staticOrder', list(rec(['label', 'str'], ['minX', 'f64'], ['minY', 'f64'], ['padLast', opt('f64')]))],
      // The pair table in pairs.list order. Both warm-start contact slots are included (stale slots seed a later contact).
      ['pairs', list(rec(
        ['aLabel', 'str'], ['bLabel', 'str'], ['aMinX', 'f64'], ['bMinX', 'f64'], ['active', 'bool'],
        ['separation', 'f64'], ['contactCount', 'i32'],
        ['contacts', list(rec(['normalImpulse', 'f64'], ['tangentImpulse', 'f64']))],
      ))],
    ),
  },

  terrain: {
    version: 1,
    schema: rec(
      ['seedState', 'u32'], ['biomeMask', 'u32'],
      ['joined', list('i32')], // chunk indices that are physically joined (mesh.chunks), ascending
      ['queue', list('i32')], // generated but not yet joined (_chunkQueue), ascending
      // chunkDigests[i] is the GV1 digest (see fingerprintCapture.chunkDigest) of the generated chunk `joined[i]`.
      ['chunkDigests', list('str')],
    ),
  },

  hazards: {
    version: 1,
    schema: rec(
      ['chunks', list(rec(['chunk', 'i32'], ['items', list(rec(
        ['defId', 'str'], ['hit', 'bool'], ['destroyed', 'bool'], ['open', 'bool'], ['rolling', 'bool'],
        ['nearMissed', 'bool'], ['side', opt('i32')], ['phase', 'f64'],
        ['roll', rec(
          ['activeAtMs', opt('f64')], ['offsetPx', 'f64'], ['vPxS', 'f64'], ['simMs', 'f64'], ['simDist', 'f64'], ['simV', 'f64'],
        )],
      ))]))],
    ),
  },

  pickups: {
    version: 1,
    schema: rec(
      ['collectedPowerups', list('str')], // sorted (UTF-16 code units)
      ['shardCollected', list('str')], // sorted
      ['activeZones', list('str')], // sorted keys `${modId}:${round(x0)}`
      // Live shards still on the ground, per chunk ascending, in array order. A Shard Magnet moves them (pull), so their
      // positions are state, not a function of the chunk.
      ['liveShards', list(rec(['chunk', 'i32'], ['shards', list(rec(['id', 'str'], ['x', 'f64'], ['y', 'f64']))]))],
    ),
  },

  effects: {
    version: 1,
    schema: rec(
      ['slowMs', 'f64'], ['slowFactor', 'f64'], ['scrambleMs', 'f64'], ['boostMs', 'f64'], ['boostFactor', 'f64'],
      ['slowmoMs', 'f64'], ['slowmoScale', 'f64'], ['hitStopMs', 'f64'], ['blinkMs', 'f64'], ['resetCooldownMs', 'f64'],
      ['glideMs', 'f64'], ['glideMul', 'f64'], ['stabilizeMs', 'f64'], ['stabilizeDeg', 'f64'], ['stabilizeBounce', 'f64'],
      ['magnetMs', 'f64'],
      ['shieldCharges', 'i32'], ['openingGraces', 'i32'],
      ['shieldSources', list('str')], // spend order matters (most recent first): array order, not sorted
      // Wards in array order (wardSpeedMul multiplies in that order). `mods/hazards/effects` are the ward's own lists.
      ['wards', list(rec(
        ['id', 'str'], ['msLeft', 'f64'], ['mods', list('str')], ['hazards', list('str')], ['effects', list('str')],
        ['speedFactor', 'f64'],
      ))],
      // The only fields of the active magnet effect the sim reads (ShardMagnet.magnetStrength), defaults resolved.
      ['magnetEff', opt(rec(['pullRadiusPx', 'f64'], ['pullPxS', 'f64']))],
    ),
  },

  bsod: {
    version: 1,
    schema: rec(
      ['active', 'bool'], ['wallX', 'f64'], ['wallSpeedPxS', 'f64'], ['accelerationPxS2', 'f64'], ['caught', 'bool'],
      ['bluff', rec(
        ['armed', 'bool'], ['usedCanopy', 'bool'], ['usedAirbrake', 'bool'], ['closestGapPx', opt('f64')],
        ['previousGapPx', opt('f64')], ['chain', 'u32'], ['lastAwardX', 'f64'], ['lastAwardTimeMs', 'f64'],
      )],
    ),
  },

  kodiak: {
    version: 2,
    schema: rec(
      ['next', 'u32'], ['on', 'bool'], ['shoveCdMs', 'f64'],
      ['bears', list(rec(
        ['kind', 'str'], ['n', 'u32'], ['member', 'u32'], ['x', 'f64'], ['speed', 'f64'], ['phase', 'str'],
        ['phaseMs', 'f64'], ['ageMs', 'f64'], ['rngState', 'u32'], ['feints', 'u32'], ['targetX', opt('f64')],
        ['groundY', 'f64'], ['sledAhead', 'bool'], ['real', opt('bool')], ['hit', 'bool'], ['done', 'bool'],
      ))],
    ),
  },

  score: {
    version: 1,
    schema: rec(
      ['mgr', rec(
        ['distanceM', 'f64'], ['trickPoints', 'f64'], ['penaltyPoints', 'f64'], ['bonusPoints', 'f64'],
        ['bestCombo', 'f64'], ['flow', 'f64'], ['flowRemainingMs', 'f64'], ['bestFlow', 'f64'], ['pending', 'f64'],
        ['lastMilestoneSector', 'i32'],
        ['bonusCounts', rec(['shard', 'f64'], ['nearMiss', 'f64'], ['milestone', 'f64'])],
        ['bonusByKind', rec(['shard', 'f64'], ['nearMiss', 'f64'], ['milestone', 'f64'])],
        ['comboTricks', list('str')], // appended in order; order kept
        ['paid', list(KV)], // sorted by key
        ['counts', list(KV)], // sorted by key
      )],
      ['run', rec(
        ['shardChain', 'f64'], ['shardChainAt', 'f64'], ['shardTotal', 'f64'], ['shardCount', 'f64'],
        ['nearMissCount', 'f64'], ['maxAirtimeMs', 'f64'], ['bestCombo', 'f64'], ['lastTotal', 'f64'],
        ['trickCounts', list(KV)], // sorted by key
      )],
    ),
  },

  tricks: {
    version: 1,
    schema: rec(
      ['tracker', rec(
        ['air', 'bool'], ['airStart', 'f64'], ['tiltNet', 'f64'], ['heliNet', 'f64'], ['tiltDone', 'f64'],
        ['heliDone', 'f64'], ['corkscrewNet', 'f64'], ['corkscrewDone', 'f64'], ['brakeMs', 'f64'], ['chuteMs', 'f64'],
        ['heliMax', 'f64'], ['prevAngle', 'f64'], ['brakeDone', 'bool'], ['chuteDone', 'bool'], ['heliHeld', 'bool'],
        ['havePrev', 'bool'], ['prevHeli', opt('f64')],
      )],
      ['airTricks', 'f64'], ['landings', 'f64'], ['steepMs', 'f64'], // RunScene._airTricks (read by the landing boost), _landings, _steepMs (hint inputs, kept per spec 6.3)
    ),
  },

  recovery: {
    version: 1,
    schema: rec(
      ['pendingCrash', opt(rec(['cause', 'str'], ['hazardId', opt('str')]))],
      ['crashTimerMs', 'f64'],
      ['safeSamples', list(rec(['t', 'f64'], ['x', 'f64'], ['y', 'f64'], ['vx', 'f64'], ['vy', 'f64'], ['ang', 'f64']))],
      ['safeTimer', 'f64'],
    ),
  },
});

// -----------------------------------------------------------------------------------------------------------------
// Anti-drift ledger (section 6.8)
// -----------------------------------------------------------------------------------------------------------------

/**
 * Own enumerable property -> the schema path that covers it, per owner class. `Class.prop` is what code defines, the value
 * is `<subsystem>.<path in the schema>`. For classes whose capture reads a nested object (Matter body), the path names the
 * schema record. The completeness test perturbs each property on a real instance and requires that subsystem's digest to
 * change, so an entry here is a verified claim, not a comment.
 */
export const FIELD_SOURCES = Object.freeze({
  Sled: Object.freeze({
    body: 'sled.body', // the compound root and its 5 parts (+ the Matter pair table in `matter`)
    msSinceContact: 'sled.ctl.msSinceContact', groundAngleDeg: 'sled.ctl.groundAngleDeg', airtimeMs: 'sled.ctl.airtimeMs',
