}/**
 * pmath: the single import point for the math functions that ECMAScript does not require to be bit-identical across engines
 * (issue #121). Every authoritative simulation file imports these instead of the native Math.sin/cos/tan/asin/acos/atan/atan2/
 * exp/expm1/log/log1p/log2/log10/pow/hypot/tanh/sinh/cosh/cbrt; presentation-only code (audio, backgrounds, UI, particles) stays on
 * native Math. The boundary is enforced by tests/determinism/sim-math-boundary.test.js.
 *
 * Implementation: the maintained @stdlib/math-base-special-* packages (Apache-2.0, ports of FreeBSD msun / fdlibm / Boost algorithms
 * in pure JS: only IEEE + - * / sqrt floor abs, no native transcendental, no FMA). They are pinned to exact versions in package.json
 * and package-lock.json, and evaluated in docs/determinism/portable-math.md (golden hashes identical in Node, Chromium, Firefox and
 * WebKit; accuracy <= 1 to 2 ulp vs V8; per-engine cost at the real op mix). This module is a thin facade so call sites never import
 * the packages directly and the implementation can be swapped without touching them.
 *
 * Changing ANY result bit of ANY function here (a version bump of any @stdlib package, or swapping the implementation) changes
 * simulation outcomes: bump SIM_REVISION (ruleset.js) and re-record fixtures. tests/determinism/pmath.test.js pins the outputs with
 * fixed-input golden hashes (docs/determinism/results/portable-math-golden.json).
 */
import sin from '@stdlib/math-base-special-sin';
import cos from '@stdlib/math-base-special-cos';
import tan from '@stdlib/math-base-special-tan';
import asin from '@stdlib/math-base-special-asin';
import acos from '@stdlib/math-base-special-acos';
import atan from '@stdlib/math-base-special-atan';
import atan2 from '@stdlib/math-base-special-atan2';
import exp from '@stdlib/math-base-special-exp';
import expm1 from '@stdlib/math-base-special-expm1';
import log from '@stdlib/math-base-special-ln';
import log1p from '@stdlib/math-base-special-log1p';
import log2 from '@stdlib/math-base-special-log2';
import log10 from '@stdlib/math-base-special-log10';
import pow from '@stdlib/math-base-special-pow';
import hypot from '@stdlib/math-base-special-hypot';
import tanh from '@stdlib/math-base-special-tanh';
import sinh from '@stdlib/math-base-special-sinh';
import cosh from '@stdlib/math-base-special-cosh';
import cbrt from '@stdlib/math-base-special-cbrt';

export const pmath = Object.freeze({ sin, cos, tan, asin, acos, atan, atan2, exp, expm1, log, log1p, log2, log10, pow, hypot, tanh, sinh, cosh, cbrt });
export { sin, cos, tan, asin, acos, atan, atan2, exp, expm1, log, log1p, log2, log10, pow, hypot, tanh, sinh, cosh, cbrt };
export default pmath;/**
 * OWNER: progression engineer. Pure logic + INJECTED storage — no Phaser, no direct DOM access.
 *
 * The profile lives under its own localStorage key (`bb.profile`) with its OWN version field, so it
 * is never touched by `sanitizeSettings` (which drops unknown keys) and never needs
 * `STORAGE.saveVersion` to change. Every operation degrades to an in-memory profile when storage is
 * missing or throws (private windows), and nothing here ever throws to the caller.
 *
 * Crediting is idempotent on `record.ledgerHash` (falling back to `record.id`): a run is banked at
 * most once, so a replayed RUN_END or a double-scene start cannot double-award.
 */
import { defaultProfile, loadLevelTable, levelForXp, rewardsForLevel, xpForRun, PROFILE_VERSION, BASE_BIOME_ID } from './Progression.js';
import { ACHIEVEMENTS, metricsFrom, newlyUnlocked, stampNew } from './Achievements.js';
import { isOfficialDaily } from './Ranking.js';
import { COSMETIC_ITEMS } from './Cosmetics.js';
import { sanitizeBiomeProgress, mergeBiomeVisits } from './BiomeDiscovery.js';
import { canonicalBiomeId, canonicalLegacyId } from '../data/biomeAliases.js';
import { sanitizeUpgradeRanks, purchaseUpgrade } from './PermanentUpgrades.js';
import { BSOD_GYM_PRICE, sanitizeGymSetup } from './BsodGym.js';
import {DRAFT_RULES_VERSION,DRAFT_BUDGET,validDraftRanks,sanitizeDraftRanks,draftCost} from './DailyDraft.js';

export { BASE_BIOME_ID };

/** localStorage key for the player profile. Deliberately NOT STORAGE.settingsKey. */
export const PROFILE_KEY = 'bb.profile';

/** Temporary/pre-alpha music-vocals entitlement price.
 * Eventually earned by level, with existing purchases grandfathered.
 */
export const VOCALS_UNLOCK_SHARDS = 200;

/** Pure, idempotent entitlement and bank transaction, no UI/localStorage.
 * Rejects malformed balances, missing funds or repeat purchase.
 */
export function purchaseVocals(profile,price=VOCALS_UNLOCK_SHARDS) {
  if (!profile || typeof profile !== 'object') return {ok:false,reason:'invalid-profile',profile};
  if (profile.unlocked?.musicVocals===true)
    return {ok:true,reason:'already-owned',profile};
  if (!Number.isSafeInteger(price)||price<1)
    return {ok:false,reason:'invalid-price',profile};
  if (!Number.isSafeInteger(profile.bank)||profile.bank<price)
    return {ok:false,reason:'not-enough-shards',profile};
  const next={...profile,bank:profile.bank-price,
    unlocked:{...(profile.unlocked||{}),musicVocals:true}};
  return {ok:true,reason:'purchased',profile:next};
}


/** Bounded ring of credited run hashes: enough for thousands of runs, cannot grow forever. */
export const CREDITED_MAX = 500;

const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const int = (v, d = 0) => (isNum(v) ? Math.round(v) : d);
const nonNeg = (v) => Math.max(0, int(v, 0));
/**
 * Non-negative FLOAT: a counter that legitimately has a fractional part.
 *
 * RunRecord.bestCombo is a combo MULTIPLIER (SaveStore: "highest multiplier"), so x1.25 and x2.5 are
 * real values. Rounding it with nonNeg stored 1 and 3 — a silent corruption that missions and
 * achievements would read back. Counters that are genuinely integral (runs, metres, score, shards)
 * keep using nonNeg; this is only for fields whose unit is fractional.
 */
const nonNegFloat = (v, d = 0) => (isNum(v) ? Math.max(0, v) : d);
const str = (v) => (typeof v === 'string' ? v : '');
const strArr = (v) => (Array.isArray(v) ? Array.from(new Set(v.filter((s) => typeof s === 'string' && s))) : []);

/**
 * Missions retired by a data change, mapped to their replacement (#65: "1500 m in Debutmont" was trivial, every run
 * starts in Debutmont). An active or in-progress old id keeps its slot as the replacement. A retired singleRun mission
 * banks no progress worth keeping, so its progress entry is dropped. Applied after the legacy-biome rename.
 */
export const RETIRED_MISSIONS = Object.freeze({ 't4-biome-debutmont': 't4-pickup-maple-wax' });
const migrateMissionId = (id) => {
  const c = canonicalLegacyId(id);
  return typeof c === 'string' && Object.hasOwn(RETIRED_MISSIONS, c) ? RETIRED_MISSIONS[c] : c;
};

/**
 * Mission progress keyed by mission id, with legacy ids (issue #65) moved to their canonical key. When both
 * the old and the new key exist the larger count wins, so a rename never loses progress or lowers it.
 * @param {*} raw
 * @returns {Object<string,*>}
 */
function canonicalMissionProgress(raw) {
  const out = {};
  if (!raw || typeof raw !== 'object') return out;
  for (const [k, v] of Object.entries(raw)) {
    const id = canonicalLegacyId(k);
    if (Object.hasOwn(RETIRED_MISSIONS, id)) continue;
    // Own-key writes only: a crafted "__proto__" key must not reach the prototype setter.
    if (id === '__proto__' || id === 'constructor' || id === 'prototype') continue;
    const prev = Object.hasOwn(out, id) ? out[id] : undefined;
    out[id] = typeof prev === 'number' && typeof v === 'number' ? Math.max(prev, v) : (id === k || prev === undefined ? v : prev);
  }
  return out;
}

/** @param {*} raw @returns {{runs:number,distanceM:number,playMs:number,score:number,tricks:Object<string,number>,shards:number,nearMisses:number,bestScore:number,bestDistanceM:number,bestCombo:number,maxAirtimeMs:number}} */
function sanitizeLifetime(raw) {
  const o = raw && typeof raw === 'object' ? raw : {};
  const tricks = {};
  if (o.tricks && typeof o.tricks === 'object') {
    for (const [k, v] of Object.entries(o.tricks)) {
      if (typeof k === 'string' && k && isNum(v) && v >= 0) tricks[k] = Math.round(v);
    }
  }
  return {
    runs: nonNeg(o.runs),
    distanceM: nonNeg(o.distanceM),
    playMs: nonNeg(o.playMs),
    score: nonNeg(o.score),
    tricks,
    shards: nonNeg(o.shards),
    nearMisses: nonNeg(o.nearMisses),
    bsodBluffs: nonNeg(o.bsodBluffs),
    bsodSurfs: nonNeg(o.bsodSurfs),
    bestScore: nonNeg(o.bestScore),
    bestDistanceM: nonNeg(o.bestDistanceM),
    bestCombo: nonNegFloat(o.bestCombo),
    maxAirtimeMs: nonNeg(o.maxAirtimeMs),
    dailyRuns: nonNeg(o.dailyRuns),
    bestStreak: nonNeg(o.bestStreak),
  };
}

/**
 * Derived fields, applied on EVERY path out of sanitizeProfile so the profile shape never depends on
 * whether it was persisted yet. A fresh default and a saved-then-reloaded profile must be byte-identical,
 * otherwise UI code and future migrations see two different shapes for the same player state.
 * @param {Object} p @param {{levels:Array<Object>}} table
 * @returns {Object} p
 */
function finishShape(p, table) {
  // Level is always derived from XP: a stale/hand-edited level field can never lie.
  p.level = levelForXp(p.xp, table);
  // W1 lists biome rewards but they are not playable yet; keep them visible as pending.
  p.pendingBiomes = table.levels.filter((l) => l.biome && l.level <= p.level).map((l) => l.biome);
  return p;
}

/** @param {*} raw @param {*} levels @returns {Object} a complete, trustworthy profile. Never throws. */
export function sanitizeProfile(raw, levels) {
  const table = loadLevelTable(levels);
  const p = defaultProfile();
  // Trust NOTHING that is not a strict v1 profile. `v` must be exactly the number 1: a missing version,
  // a stringified "1", a future v2 blob or an array all yield a clean default instead of a half-trusted
  // object, so another version's bank/xp/credited can never leak into v1 state.
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return finishShape(p, table);
  if (raw.v !== PROFILE_VERSION) return finishShape(p, table);
  p.xp = nonNeg(raw.xp);
  p.bank = nonNeg(raw.bank);
  p.upgrades = sanitizeUpgradeRanks(raw.upgrades);
  p.upgradesEnabled = raw.upgradesEnabled === true;
  // Device-local preset for the separate ranked Daily Draft ruleset. NOT
  // permanently owned upgrades and NEVER a drain on the shard bank.
  const dailyDraft=raw.dailyDraft&&typeof raw.dailyDraft==='object'?raw.dailyDraft:{};
  p.dailyDraft={version:DRAFT_RULES_VERSION,ranks:sanitizeDraftRanks(
    dailyDraft.version===DRAFT_RULES_VERSION?dailyDraft.ranks:null)};
  const gym = raw.bsodGym && typeof raw.bsodGym === 'object' ? raw.bsodGym : {};
  p.bsodGym = { discovered: gym.discovered === true || gym.owned === true,
    owned: gym.owned === true };
  // Backward compatible: old owned profiles remain {discovered,owned}.
  // Setup is a nested, permanent Easter egg with no tease before genuine
  // five-in-one-flight Gym mastery; it cannot be earned by a normal run.
  if (p.bsodGym.owned && gym.advanced === true) {
    p.bsodGym.advanced = true;
    p.bsodGym.setup = sanitizeGymSetup(gym.setup);
  }
  p.lifetime = sanitizeLifetime(raw.lifetime);
  const u = raw.unlocked && typeof raw.unlocked === 'object' ? raw.unlocked : {};
  p.unlocked = {
    biomes: strArr(strArr(u.biomes).map(canonicalBiomeId)), // legacy ids (issue #65) follow the rename
    cosmetics: strArr(u.cosmetics),
    // W5: achievement title rewards land here. Without this line the sanitizer would drop them on the
    // very next load, so a player would win OMNISCIENT and lose it at the next boot.
    titles: strArr(u.titles),
    boosts: u.boosts && typeof u.boosts === 'object' ? Object.fromEntries(Object.entries(u.boosts).filter(([k, v]) => typeof k === 'string' && k && isNum(v))) : {},
    musicVocals: u.musicVocals === true,
  };
  const e = raw.equipped && typeof raw.equipped === 'object' ? raw.equipped : {};
  for (const k of ['trail', 'glow', 'rider', 'theme', 'title']) {
    p.equipped[k] = typeof e[k] === 'string' && e[k] ? e[k] : 'default';
  }
  // Issue #65: explicit OFF choices only. `raw.biomeMask` (the old opt-in mask) is deliberately never read,
  // so an old save migrates to all-unlocked-ON with no PROFILE_VERSION bump. Only the biome table knows which
  // bits are real, so stray bits are not stripped here; `enabledBiomeMask` and `toggleBiome` intersect with
  // the unlocked bits, which makes a stale bit inert (and `toggleBiome` refuses locked biomes, so none arise).
  p.biomeOff = nonNeg(raw.biomeOff) >>> 0;
  // W4 loadout. Anything that is not an explicit `true` is off: a hand-edited save, a string "true", or a
  // boost id that no longer ships must never silently start a run modded.
  const b = raw.boosts && typeof raw.boosts === 'object' ? raw.boosts : {};
  p.boosts = {
    errorCorrection: b.errorCorrection === true,
    headStart: b.headStart === true,
  };
  const m = raw.missions && typeof raw.missions === 'object' ? raw.missions : {};
  p.missions = {
    counter: nonNeg(m.counter),
    // Deduped before the cap: a hand-edited ['a','a','a'] would otherwise fill all three slots with one
    // mission and pay it three times on a single run.
    active: strArr(strArr(m.active).map(migrateMissionId)).slice(0, 3),
    progress: canonicalMissionProgress(m.progress),
  };
  // W5: {id: unlockMs}. Only finite timestamps survive: a NaN or a string would sort unpredictably in the
  // Profile grid, and a junk key would render as a nameless row.
  p.achievements = {};
  if (raw.achievements && typeof raw.achievements === 'object' && !Array.isArray(raw.achievements)) {
    for (const [k, v] of Object.entries(raw.achievements)) {
      if (typeof k === 'string' && k && Number.isFinite(v)) p.achievements[k] = v;
    }
  }
  // Legacy one-time backfill: discovering the purchasable Gym required a
  // genuine first Bluff. Preserve that evidence without guessing an unlock
  // timestamp; zero means historical date unknown, not an unearned trophy.
  if (p.bsodGym?.discovered && !Number.isFinite(p.achievements['bluff-the-bsod'])) {
    p.achievements['bluff-the-bsod'] = 0;
    p.lifetime.bsodBluffs = Math.max(1, p.lifetime.bsodBluffs);
  }
  p.credited = strArr(raw.credited).slice(-CREDITED_MAX);
  // Decision 3: only known biome ids survive, completed implies encountered, absent reads as empty sets.
  p.biomeProgress = sanitizeBiomeProgress(raw.biomeProgress);
  return finishShape(p, table);
}

/**
 * Grant every non-biome level reward crossed on the way from `levelBefore` to the profile's current
 * level. Mutates `profile` in place. Shared by creditRun (run XP) and applyMissions (mission XP) so a
 * threshold crossed by either path pays exactly the same rewards — mission XP used to bump the level
 * without ever granting its cosmetic/boost, stranding that reward forever.
 * @param {Object} profile
 * @param {number} levelBefore
 * @param {*} table
 */
function grantLevelRewards(profile, levelBefore, table) {
  const before = isNum(levelBefore) ? levelBefore : 1;
  const level = isNum(profile.level) ? profile.level : before;
  if (level <= before) return;
  // A long run can cross several thresholds; grant every intervening non-biome reward.
  for (let l = before + 1; l <= level; l++) {
    const crossed = rewardsForLevel(l, table);
    if (crossed.cosmetic && !profile.unlocked.cosmetics.includes(crossed.cosmetic)) profile.unlocked.cosmetics.push(crossed.cosmetic);
    if (crossed.boost) profile.unlocked.boosts[crossed.boost] = profile.unlocked.boosts[crossed.boost] || 1;
  }
  // W1: biome rewards are LISTED but not unlockable until W3/W6 ship the biomes themselves.
  profile.pendingBiomes = table.levels.filter((l) => l.biome && l.level <= level).map((l) => l.biome);
}

/**
 * Apply one finished run to a profile. PURE — returns a NEW profile (or null when the run was
 * already credited). Callers persist the result.
 * @param {Object} profile
 * @param {Object} record
 * @param {*} levels
 * @param {{streak?:number, biomeVisits?:{encountered:string[],completed:string[]}}} [extra] caller-owned facts:
 *        `streak` is the current Daily streak (SaveStore.getDailyStreak), kept as lifetime.bestStreak;
 *        `biomeVisits` is what the run saw (decision 3), merged into profile.biomeProgress.
 * @returns {{profile:Object, awards:Object}|null} null when already credited or the record is unusable.
 */
/**
 * Biomes a profile has actually unlocked. `pendingBiomes` is derived from the level table on every
 * sanitize, so it is the one field that is always in step with XP; `unlocked.biomes` is part of the
 * profile shape but nothing populates it yet, so reading it alone would report every biome locked.
 * Pure.
 * @param {Object} profile
 * @returns {string[]}
 */
export function unlockedBiomeIds(profile) {
  if (!profile || typeof profile !== 'object') return [];
  const pending = Array.isArray(profile.pendingBiomes) ? profile.pendingBiomes : [];
  const listed = (profile.unlocked && Array.isArray(profile.unlocked.biomes)) ? profile.unlocked.biomes : [];
  // The base biome is always unlocked, even for a profile built without the level table.
  return [...new Set([BASE_BIOME_ID, ...pending, ...listed])];
}

/**
 * Biomes a profile has EARNED, resolved against the shipped biome table. Pure.
 *
 * `unlockedBiomeIds` answers from the profile alone, which is why mission gating against
 * `profile.unlocked.biomes` was dead code: nothing ever populated it. This resolves the derived
 * `pendingBiomes` list against the real defs, so the answer is bounded by both what the profile
 * reached and what actually ships. A biome id the profile mentions but the table does not have is
 * dropped rather than trusted.
 * @param {Object} profile
 * @param {Array<{id:string,bit:number,unlockLevel:number}>} biomeDefs
 * @returns {string[]}
 */
export function earnedBiomeIds(profile, biomeDefs) {
  const defs = Array.isArray(biomeDefs) ? biomeDefs : [];
  const earned = unlockedBiomeIds(profile);
  return defs
    .filter((d) => d && typeof d.id === 'string' && earned.includes(d.id))
    .sort((a, b) => (a.unlockLevel || 0) - (b.unlockLevel || 0) || a.id.localeCompare(b.id))
    .map((d) => d.id);
}

/**
 * Toggle one unlocked biome signature on or off (W3). Pure: returns a new profile, never mutates the
 * input, so a caller can decide whether to save.
 *
 * Unlocked biomes default ON (issue #65), so the toggle flips the biome's bit in `biomeOff`, the player's
 * explicit OFF choices. An OFF bit is authoritative: it survives later level-ups and saves.
 *
 * Refuses a biome the player has not unlocked: a toggle that honoured a locked bit would let a profile
 * see terrain it never earned. The base biome is refused too, it cannot be turned off. An unknown id is
 * likewise a no-op rather than an error, because this is driven by UI ids and must never throw.
 *
 * @param {Object} profile
 * @param {string} biomeId
 * @param {Array<{id:string,bit:number}>} biomeDefs
 * @returns {Object} the same profile object when nothing changed, else a shallow copy.
 */
export function toggleBiome(profile, biomeId, biomeDefs) {
  if (!profile || typeof profile !== 'object') return profile;
  const defs = Array.isArray(biomeDefs) ? biomeDefs : [];
  const def = defs.find((d) => d && d.id === biomeId);
  if (!def || !Number.isFinite(def.bit)) return profile;
  const unlocked = unlockedBiomeIds(profile);
  if (biomeId === BASE_BIOME_ID || !unlocked.includes(biomeId)) return profile;
  const off = (profile.biomeOff >>> 0) || 0;
  const next = (off & def.bit) ? (off & ~def.bit) >>> 0 : (off | def.bit) >>> 0;
  if (next === off) return profile;
  return { ...profile, biomeOff: next };
}

/**
 * The mask a normal run should start with: every unlocked biome except the player's explicit OFFs
 * (`biomeOff`), minus the base biome. Pure.
 *
 * Unlocked is the whole point of the restriction. A hand-edited `biomeOff` (or the legacy `biomeMask`,
 * which is ignored) can never enable a biome the player has not reached, because only unlocked bits are
 * ever in the result. `toggleBiome` refuses the same thing on the toggle path; this is the same rule at the
 * run-start path, so the two cannot drift. A biome unlocked later is ON unless its OFF bit was set.
 *
 * The base biome's bit is excluded: Debutmont is the terrain of every run, so its bit is a no-op, and
 * leaving it out keeps masks canonical (a fresh profile starts at mask 0, as before).
 *
 * @param {Object} profile
 * @param {Array<{id:string,bit:number}>} biomeDefs
 * @returns {number} a non-negative integer mask
 */
export function enabledBiomeMask(profile, biomeDefs) {
  const defs = Array.isArray(biomeDefs) ? biomeDefs : [];
  if (!profile || typeof profile !== 'object') return 0;
  const off = (profile.biomeOff >>> 0) || 0;
  const unlocked = unlockedBiomeIds(profile);
  let allowed = 0;
  for (const def of defs) {
    if (def && Number.isFinite(def.bit) && def.id !== BASE_BIOME_ID && unlocked.includes(def.id)) allowed |= def.bit;
  }
  return (allowed & ~off) >>> 0;
}

/**
 * The biome toggle rows a Profile view should show: every switchable biome in unlock order, with the
 * player's current state. The base biome has no row, it cannot be turned off. Pure, so the view stays a
 * renderer and this stays testable.
 * @param {Object} profile
 * @param {Array<{id:string,bit:number,name:string,unlockLevel:number}>} biomeDefs
 * @returns {Array<{id:string,name:string,bit:number,unlockLevel:number,unlocked:boolean,enabled:boolean,
 *   encountered:boolean,completed:boolean,state:'locked'|'unlocked'|'encountered'|'completed'}>}
 */
export function biomeToggleRows(profile, biomeDefs) {
  const defs = Array.isArray(biomeDefs) ? biomeDefs : [];
  const unlocked = unlockedBiomeIds(profile);
  const off = (profile && profile.biomeOff) >>> 0 || 0;
  // Decision 3: encountered / completed are separate from unlocked. A Daily plays the date's mask whatever
  // the player has unlocked, so a LOCKED biome can be encountered too; `state` reports the strongest fact.
  const prog = sanitizeBiomeProgress(profile && profile.biomeProgress);
  const stateOf = (id) => {
    if (prog.completed.includes(id)) return 'completed';
    if (prog.encountered.includes(id)) return 'encountered';
    return unlocked.includes(id) ? 'unlocked' : 'locked';
  };
  return defs
    .filter((d) => d && d.id && d.id !== BASE_BIOME_ID && Number.isFinite(d.bit))
    .slice()
    .sort((a, b) => (a.unlockLevel || 0) - (b.unlockLevel || 0) || a.id.localeCompare(b.id))
    .map((d) => ({
      id: d.id,
      name: d.name || d.id,
      bit: d.bit,
      unlockLevel: d.unlockLevel || 1,
      unlocked: unlocked.includes(d.id),
      enabled: unlocked.includes(d.id) && (off & d.bit) === 0,
      encountered: prog.encountered.includes(d.id),
      completed: prog.completed.includes(d.id),
      state: stateOf(d.id),
    }));
}

export function creditRun(profile, record, levels, extra = {}) {
  const table = loadLevelTable(levels);
  const base = sanitizeProfile(profile, table);
  if (!record || typeof record !== 'object') return null;
  const key = str(record.ledgerHash) || str(record.id);
  if (!key) return null;
  if (base.credited.includes(key)) return null;

  const xp = xpForRun(record);
  const levelBefore = levelForXp(base.xp, table);
  const next = {
    ...base,
    xp: base.xp + xp.total,
    credited: [...base.credited, key].slice(-CREDITED_MAX),
    lifetime: { ...base.lifetime },
    unlocked: { ...base.unlocked, biomes: [...base.unlocked.biomes], cosmetics: [...base.unlocked.cosmetics], boosts: { ...base.unlocked.boosts } },
  };
  // W4: the run's Data Shards land in the spendable bank as well as the lifetime total. Two numbers on
  // purpose - `lifetime.shards` is what the player has EARNED and never goes down when they spend, and
  // `bank` is the balance. This is the one place a run pays, so a replay that returns null above pays
  // neither, and missions fold their shards in through applyMissions below.
  next.bank = base.bank + nonNeg(record.shards);
  const L = next.lifetime;
  L.runs += 1;
  L.distanceM += nonNeg(record.distanceM);
  L.playMs += nonNeg(record.durationMs);
  L.score += nonNeg(record.score);
  L.shards += nonNeg(record.shards);
  L.nearMisses += nonNeg(record.nearMisses);
  L.bestScore = Math.max(L.bestScore, nonNeg(record.score));
  L.bestDistanceM = Math.max(L.bestDistanceM, nonNeg(record.distanceM));
  L.bestCombo = Math.max(L.bestCombo, nonNegFloat(record.bestCombo));
  L.maxAirtimeMs = Math.max(L.maxAirtimeMs, nonNeg(record.maxAirtimeMs));
  // ACH-3 + decisions 1/2: only an OFFICIAL Daily run played on this device counts (Ranking.isOfficialDaily,
  // the same rule SaveStore's streak uses). A typed `daily-*` seed is practice and an imported run was not
  // played here, so neither moves dailyRuns or the Daily achievements.
  // The streak itself is the caller's fact: it needs every stored run, which this pure function does not
  // see, so ProgressionService passes SaveStore.getDailyStreak's value in and the best one is kept.
  if (isOfficialDaily(record) && record.imported !== true) L.dailyRuns += 1;
  const ex = extra && typeof extra === 'object' ? extra : {};
  L.bestStreak = Math.max(L.bestStreak, nonNeg(ex.streak));
  // Decision 3: what RunScene saw this run (RUN_END.biomeVisits, BiomeDiscovery.detectBiomeVisits), merged
  // as a union. A new object, so the caller's profile is never written through.
  next.biomeProgress = mergeBiomeVisits(base.biomeProgress, ex.biomeVisits);
  // Micro glow-up: a biome grant (the Neon Sled Drone) is granted by the credit that first completes its biome,
  // through the same grant path achievement rewards use, before achievements are evaluated.
  const grants = grantBiomeCosmetics(base, next);
  if (record.tricks && typeof record.tricks === 'object') {
    for (const [k, v] of Object.entries(record.tricks)) {
      if (typeof k === 'string' && k && isNum(v) && v > 0) L.tricks[k] = (L.tricks[k] || 0) + Math.round(v);
    }
  }
  next.level = levelForXp(next.xp, table);
  const leveledTo = next.level > levelBefore ? next.level : 0;
  const rewards = leveledTo ? rewardsForLevel(leveledTo, table) : null;
  if (leveledTo) grantLevelRewards(next, levelBefore, table);
  const rewardsEarned = leveledTo
    ? table.levels.filter((entry) => entry.level > levelBefore && entry.level <= next.level).map((entry) => rewardsForLevel(entry.level, table))
    : [];
  // W5: evaluate achievements as part of the same credit, so a run that crosses a threshold unlocks it
  // on the Game Over screen rather than on some later unrelated save. `now` comes from the record's
  // end time, not from inside the pure evaluator.
  // Only the daily facts are forwarded. Decision 3: discovered means encountered, and metricsFrom reads it from
  // `next.biomeProgress` (sanitized, known ids only, merged above); a caller's `biomeCount` is still ignored,
  // so nothing but a real encounter can unlock the biome achievements.
  const unlockedNow = unlockAchievementsFor(next, record, {
    at: nonNeg(record.endedAt), dailyRuns: L.dailyRuns, streak: L.bestStreak,
  });
  const awards = {
    xp,
    levelBefore,
    levelAfter: next.level,
    leveledTo,
    rewards,
    rewardsEarned,
    title: rewards ? rewards.title : null,
    // The Game Over toast list (decision 9): this run's achievement defs in the one sort order, then its
    // biome grants (biomes is the last group, and a grant names its biome). A grant entry has a name and a
    // desc like a def but is never stamped into profile.achievements.
    achievements: [...unlockedNow.added, ...grants],
    grants,
  };
  return { profile: unlockedNow.profile, awards };
}

/**
 * Grant every biome cosmetic (`grant: 'biome'`) that `next` owns and `before` did not, i.e. whose biome this
 * credit completed for the first time. Writes the id into `next.unlocked.cosmetics` through
 * grantAchievementReward (so the grant record and the toast cannot disagree), in catalogue order.
 * A profile that completed the biome before this build already owns the item by its completion, so it is
 * never re-announced.
 * @param {Object} before the profile as it was before this run's visits were merged
 * @param {Object} next the profile being credited (mutated: `unlocked` is already a fresh copy)
 * @returns {Array<{id:string,kind:'cosmetic',grant:'biome',biome:string,slot:string,name:string,desc:string}>}
 */
function grantBiomeCosmetics(before, next) {
  const out = [];
  for (const it of SHOP_ITEMS) {
    if (!it || it.grant !== 'biome') continue;
    if (isOwned(before, it.id) || !isOwned(next, it.id)) continue;
    grantAchievementReward(next, { reward: { cosmetic: it.id } });
    out.push({
      id: it.id, kind: 'cosmetic', grant: 'biome', biome: it.biome, slot: it.slot, name: it.name,
      // fits the 138 px toast line uncut (RIDER SKIN: EQUIP IN SHOP is 125 px)
      desc: `${it.slot} skin: equip in shop`.replace(/^./, (c) => c.toUpperCase()),
    });
  }
  return out;
}

/**
 * Evaluate W5 achievements against a profile and stamp the newly unlocked ones.
 *
 * Pure apart from nothing at all: `opts.at` is supplied by the caller (spec W5), so this is deterministic.
 * Returns a NEW profile even when nothing unlocked, which keeps callers from having to check.
 *
 * @param {Object} profile
 * @param {Object|null} [run] the record that just finished, if any
 * @param {{at?:number, biomeCount?:number, streak?:number, dailyRuns?:number}} [opts]
 * @returns {{profile:Object, added:Array<Object>}}
 */
export function unlockAchievementsFor(profile, run, opts = {}) {
  const p = (profile && typeof profile === 'object') ? profile : {};
  const metrics = metricsFrom(p, run, opts);
  const newly = newlyUnlocked(metrics, p.achievements);
  const { store, added } = stampNew(p.achievements, newly, opts && opts.at);
  if (!added.length) return { profile: p, added: [] };
  // `unlocked` must be cloned before any reward touches it: the spread above is SHALLOW, so writing
  // through a shared nested object would mutate the caller's profile even though the top level is a copy.
  const u = p.unlocked && typeof p.unlocked === 'object' ? p.unlocked : {};
  const next = {
    ...p,
    achievements: store,
    unlocked: {
      ...u,
      biomes: Array.isArray(u.biomes) ? [...u.biomes] : [],
      cosmetics: Array.isArray(u.cosmetics) ? [...u.cosmetics] : [],
      titles: Array.isArray(u.titles) ? [...u.titles] : [],
      boosts: u.boosts && typeof u.boosts === 'object' ? { ...u.boosts } : {},
    },
  };
  // W5: a reward is granted exactly when the achievement is stamped, in the same save, so the two can
  // never disagree about whether the player owns it.
  for (const a of added) grantAchievementReward(next, a);
  return { profile: next, added };
}

/**
 * Grant an achievement's cosmetic or title reward. Unknown reward types are ignored rather than thrown:
 * a future reward kind shipping ahead of its grant path must not break a run's credit.
 * @param {Object} profile mutated in place (already a fresh copy)
 * @param {Object} def
 * @returns {void}
 */
export function grantAchievementReward(profile, def) {
  const r = def && def.reward;
  if (!r || typeof r !== 'object') return;
  if (typeof r.cosmetic === 'string' && r.cosmetic) {
    const u = profile.unlocked && typeof profile.unlocked === 'object' ? profile.unlocked : { biomes: [], cosmetics: [], boosts: {} };
    const list = Array.isArray(u.cosmetics) ? u.cosmetics : [];
    if (!list.includes(r.cosmetic)) u.cosmetics = [...list, r.cosmetic];
    profile.unlocked = u;
  }
  if (typeof r.title === 'string' && r.title) {
    const u = profile.unlocked && typeof profile.unlocked === 'object' ? profile.unlocked : { biomes: [], cosmetics: [], boosts: {} };
    const list = Array.isArray(u.titles) ? u.titles : [];
    if (!list.includes(r.title)) u.titles = [...list, r.title];
    profile.unlocked = u;
  }
}

/**
 * One-time backfill for an existing device: bank lifetime totals and XP from runs that were recorded
 * before the profile existed. PURE. Does nothing when the profile already has runs.
 * @param {Object} profile
 * @param {Array<Object>} runs
 * @param {*} levels
 * @returns {Object} a new profile
 */
export function backfillFromRuns(profile, runs, levels) {
  const table = loadLevelTable(levels);
  const base = sanitizeProfile(profile, table);
  if (base.lifetime.runs > 0) return base;
  // Credit in play order, oldest first. SaveStore.getRecentRuns hands runs over newest first; crediting in
  // that order stamped First Descent with the NEWEST run's time and left the credited ring holding the
  // OLDEST hashes once it overflowed. A copy is sorted so the caller's array is never reordered; Array#sort
  // is stable, so runs with equal or missing end times keep their given order.
  const endedAt = (r) => (r && typeof r === 'object' && isNum(r.endedAt) ? r.endedAt : 0);
  const ordered = (Array.isArray(runs) ? runs.slice() : []).sort((a, b) => endedAt(a) - endedAt(b));
  let out = base;
  for (const r of ordered) {
    const res = creditRun(out, r, table);
    if (res) out = res.profile;
  }
  return out;
}

/**
 * Profile persistence wrapper. Owns one in-memory copy; storage is write-through and optional.
 */
export class ProfileStore {
  /**
   * @param {{storage?: Storage, levels?: *}} [o]
   */
  constructor(o = {}) {
    if (o.storage !== undefined) {
      this.storage = o.storage;
    } else {
      try {
        this.storage = typeof globalThis !== 'undefined' ? globalThis.localStorage : undefined;
      } catch (e) {
        // Accessing localStorage itself can throw in opaque origins/private contexts, before any method runs.
        this.storage = undefined;
      }
    }
    this.levels = loadLevelTable(o.levels);
    /** @type {Object} */
    this.profile = defaultProfile();
    this.backend = 'memory';
  }

  /** @returns {Object} the in-memory profile (always usable). */
  load() {
    let raw = null;
    try {
      if (this.storage) {
        const s = this.storage.getItem(PROFILE_KEY);
        if (s) raw = JSON.parse(s);
        this.backend = 'localStorage';
      }
    } catch (e) {
      raw = null; // corrupt JSON or denied storage: fall through to a clean default
      this.backend = 'memory';
    }
    this.profile = sanitizeProfile(raw, this.levels);
    // Existing pilots keep earned progress when new catalogue rungs ship.
    // Stamp any newly qualified achievements once from persisted lifetime
    // metrics, but never guess a Surfing chain from raw near-miss counts.
    if (raw && typeof raw === 'object') {
      const historical = unlockAchievementsFor(this.profile,null,{at:Date.now()});
      if (historical.added.length) this.save(historical.profile);
    }
    // Nothing usable was stored at all: persist the clean default now instead of re-deriving it on
    // every load. (A future-version blob is deliberately LEFT on disk rather than overwritten, in case
    // the player returns to a build that understands it; the in-memory profile is a clean default and
    // the first save() will replace it.)
    if (!raw || typeof raw !== 'object') this.save();
    return this.profile;
  }

  /**
   * Persist the given profile (defaults to the in-memory one). Never throws.
   * @param {Object} [profile]
   * @returns {Object} the profile that is now in memory
   */
  save(profile) {
    if (profile) this.profile = sanitizeProfile(profile, this.levels);
    try {
      if (this.storage) {
        this.storage.setItem(PROFILE_KEY, JSON.stringify(this.profile));
        this.backend = 'localStorage';
      }
    } catch (e) {
      this.backend = 'memory';
    }
    return this.profile;
  }

  /** Reveal an unpurchased Gym after a genuine first BSOD escape. */
  discoverBsodGym() {
    if (this.profile.bsodGym?.discovered) return { discovered: false, profile: this.profile };
    const next = sanitizeProfile({ ...this.profile, bsodGym: { discovered: true, owned: false } }, this.levels);
    if (this.storage) {
      try { this.storage.setItem(PROFILE_KEY, JSON.stringify(next)); }
      catch { return { discovered: false, profile: this.profile }; }
    }
    this.profile = next;
    return { discovered: true, profile: this.profile };
  }

  /** Persist a genuinely scored live Bitstream Bluff (never Gym practice).
   * A second unbroken midair Bluff reveals the Surfing achievement, not a
   * gameplay unlock or purchase. Earning is immediate, before run end.
   */
  recordBsodBluff(chain,at) {
    if (!Number.isSafeInteger(chain)||chain<1||!Number.isFinite(at))
      return {added:[],profile:this.profile};
    const p=this.profile;
    const was=p.achievements||{};
    const wanted=[chain>=1?'bluff-the-bsod':null,
      chain>=2?'surfing-the-void':null].filter(Boolean);
    const defs=ACHIEVEMENTS.filter(a=>wanted.includes(a.id)&&!Number.isFinite(was[a.id]));
    const stamped=stampNew(was,defs,at);
    const next=sanitizeProfile({...p,
      lifetime:{...p.lifetime,
        bsodBluffs:(p.lifetime?.bsodBluffs||0)+1,
        bsodSurfs:(p.lifetime?.bsodSurfs||0)+(chain>=2?1:0)},
      achievements:stamped.store},this.levels);
    this.save(next);
    return {added:stamped.added,profile:this.profile};
  }

  /** Atomic, one-time shop unlock; never charges without persisting ownership. */
  buyBsodGym() {
    if (!this.profile.bsodGym?.discovered || this.profile.bsodGym?.owned
        || !Number.isSafeInteger(this.profile.bank) || this.profile.bank < BSOD_GYM_PRICE
        || !this.storage) return { ok: false, profile: this.profile };
    const next = sanitizeProfile({
      ...this.profile, bank: this.profile.bank - BSOD_GYM_PRICE,
      bsodGym: { discovered: true, owned: true },
    }, this.levels);
    try { this.storage.setItem(PROFILE_KEY, JSON.stringify(next)); }
    catch { return { ok: false, profile: this.profile }; }
    this.profile = next;
    return { ok: true, profile: this.profile };
  }

  /** Unlock nested Gym setup after 5 genuinely scored Bluffs in ONE Gym
   * flight. Called by RunScene ONLY for Gym events; normal run Bluff events
   * never call this. Never gives shards, XP, missions or ranked records.
   * Storage failure leaves both persisted and in-memory state untouched. */
  unlockGymSetup() {
    if (!this.profile.bsodGym?.owned || this.profile.bsodGym.advanced || !this.storage)
      return { unlocked: false, profile: this.profile };
    const next = sanitizeProfile({ ...this.profile, bsodGym: {
      ...this.profile.bsodGym, advanced: true,
      setup: sanitizeGymSetup(),
    } }, this.levels);
    try { this.storage.setItem(PROFILE_KEY, JSON.stringify(next)); }
    catch { return { unlocked: false, profile: this.profile }; }
    this.profile = next;
    return { unlocked: true, profile: this.profile };
  }

  /** Persist one deterministic Daily Draft preset. Can be rebuilt at any
   * time, never spends shards or changes permanent purchase ranks.
   * A failed localStorage write does not silently change the active preset.
   */
  setDailyDraftRanks(input){
    if(!validDraftRanks(input))return {ok:false,reason:'invalid-or-over-budget',profile:this.profile};
    if(!this.storage)return {ok:false,reason:'storage-unavailable',profile:this.profile};
    const ranks=sanitizeDraftRanks(input);
    const next=sanitizeProfile({...this.profile,dailyDraft:{version:DRAFT_RULES_VERSION,ranks}},this.levels);
    try{this.storage.setItem(PROFILE_KEY,JSON.stringify(next));}
    catch{return {ok:false,reason:'storage-failed',profile:this.profile};}
    this.profile=next;
    return {ok:true,profile:this.profile,cost:draftCost(ranks),remaining:DRAFT_BUDGET-draftCost(ranks)};
  }

  /** Save a bounded, forward-only launch configuration after Gym-specific
   * mastery. The same localStorage atomicity as purchase applies; no free
   * user-editable knobs before the Easter egg is earned. */
  setGymSetup(candidate) {
    if (!this.profile.bsodGym?.owned || this.profile.bsodGym.advanced !== true || !this.storage)
      return { ok: false, profile: this.profile };
    const next = sanitizeProfile({ ...this.profile, bsodGym: {
      ...this.profile.bsodGym, setup: sanitizeGymSetup(candidate),
    } }, this.levels);
    try { this.storage.setItem(PROFILE_KEY, JSON.stringify(next)); }
    catch { return { ok: false, profile: this.profile }; }
    this.profile = next;
    return { ok: true, profile: this.profile };
  }

  /** Buy one permanent upgrade with the exact same atomic persistence guarantees
   * as music-vocals. Refused transactions do not modify memory or storage. */
  buyUpgrade(id) {
    const next = purchaseUpgrade(this.profile, id);
    if (next === this.profile) return { ok: false, reason: 'unavailable-or-insufficient-shards', profile: this.profile };
    if (!this.storage) return { ok: false, reason: 'storage-unavailable', profile: this.profile };
    const clean = sanitizeProfile(next, this.levels);
    try {
      this.storage.setItem(PROFILE_KEY, JSON.stringify(clean));
    } catch {
      return { ok: false, reason: 'storage-unavailable', profile: this.profile };
    }
    this.profile = clean;
    this.backend = 'localStorage';
    return { ok: true, reason: 'purchased', profile: this.profile };
  }

  /** Atomic persistent purchase: charge + unlock are a SINGLE storage
   * commit. On storage failure, do not debit the in-memory account.
   * Music unlock is a permanent entitlement even if the final build
   * later changes its unlock source to level progression.
   */
  buyMusicVocals() {
    const tx=purchaseVocals(this.profile);
    if (!tx.ok || tx.reason==='already-owned') return tx;
    const next=sanitizeProfile(tx.profile,this.levels);
    if (!this.storage) return {ok:false,reason:'storage-unavailable',profile:this.profile};
    try {
      this.storage.setItem(PROFILE_KEY,JSON.stringify(next));
    } catch {
      return {ok:false,reason:'storage-failed',profile:this.profile};
    }
    this.profile=next;
    this.backend='localStorage';
    return {ok:true,reason:'purchased',profile:this.profile};
  }

  /**
   * Credit a finished run and persist. Idempotent on ledgerHash.
   * @param {Object} record
   * @param {{streak?:number}} [extra] caller-owned facts, forwarded to creditRun
   * @returns {Object|null} awards, or null when the run was already credited / unusable.
   */
  credit(record, extra = {}) {
    const res = creditRun(this.profile, record, this.levels, extra);
    if (!res) return null;
    this.profile = res.profile;
    this.save();
    return res.awards;
  }

  /**
   * Merge a W2 mission roll into the profile and persist.
   *
   * Missions are applied separately from `credit()` on purpose: credit() is what makes a run
   * idempotent (it returns null on a replayed hash), and missions must follow that decision rather
   * than make their own. Keeping this as a distinct step means a tombstoned run can never advance
   * mission progress while paying no XP, or the reverse.
   *
   * @param {{active:string[],counter:number,progress:Object,completed:Array,xp:number,shards:number,setCleared:boolean}} roll
   * @returns {Object} the new profile (also assigned to this.profile)
   */
  applyMissions(roll) {
    if (!roll || typeof roll !== 'object') return this.profile;
    const p = this.profile;
    const missions = {
      counter: nonNeg(roll.counter),
      active: strArr(roll.active).slice(0, 3),
      progress: roll.progress && typeof roll.progress === 'object' ? { ...roll.progress } : {},
    };
    const next = {
      ...p,
      xp: p.xp + nonNeg(roll.xp),
      bank: p.bank + nonNeg(roll.shards),
      missions,
    };
    // Mission XP can cross a level threshold, and it must pay that level's reward exactly like run XP
    // does. Without this the level number rose while the cosmetic/boost was silently lost.
    const table = loadLevelTable(this.levels);
    const levelBefore = levelForXp(next.xp - nonNeg(roll.xp), table);
    next.level = levelForXp(next.xp, table);
    if (next.level > levelBefore) {
      next.unlocked = {
        ...p.unlocked,
        biomes: [...p.unlocked.biomes],
        cosmetics: [...p.unlocked.cosmetics],
        boosts: { ...p.unlocked.boosts },
      };
      grantLevelRewards(next, levelBefore, table);
    }
    this.profile = sanitizeProfile(next, this.levels);
    this.save();
    return this.profile;
  }

  /**
   * One-time backfill from stored runs (see backfillFromRuns). Saves only if something changed.
   * @param {Array<Object>} runs
   * @returns {boolean} true when the profile changed
   */
  backfill(runs) {
    const before = this.profile;
    const after = backfillFromRuns(before, runs, this.levels);
    if (after === before || JSON.stringify(after) === JSON.stringify(before)) return false;
    this.profile = after;
    this.save();
    return true;
  }
}

// ---- W4 economy: the shop -------------------------------------------------------------------------

/**
 * The cosmetic catalogue. Audit F4b: this is Cosmetics.COSMETIC_ITEMS itself, not a copy, so the shop, the
 * resolver that draws an item and data/cosmetics/cosmetics.json (a pinned mirror) can never disagree.
 *
 * `slot` matches a key in `profile.equipped` (trail/glow/rider/theme/title), so equipping is a direct
 * assignment rather than a second mapping table that could drift from the profile shape.
 */
export const SHOP_ITEMS = COSMETIC_ITEMS;

/** @param {string} id @returns {Object|null} */
export function shopItem(id) {
  return SHOP_ITEMS.find((i) => i && i.id === id) || null;
}

/**
 * Whether the profile owns an item. Level-reward items (price 0) are owned once the player reaches their
 * unlockLevel, which is how W1's level rewards already work; paid items are owned by purchase; an
 * achievement title (`grant: 'achievement'`) is owned once its achievement put it in `unlocked.titles`; a
 * biome grant (`grant: 'biome'`) once its `biome` is in `biomeProgress.completed` (or its id was granted).
 * @param {Object} profile @param {string} id @returns {boolean}
 */
export function isOwned(profile, id) {
  const item = shopItem(id);
  if (!item || !profile || typeof profile !== 'object') return false;
  const owned = profile.unlocked && Array.isArray(profile.unlocked.cosmetics) ? profile.unlocked.cosmetics : [];
  if (owned.includes(id)) return true;
  // Achievement titles (SHOP-2) are owned by the grant record unlockAchievementsFor writes, never by level.
  if (item.grant === 'achievement') {
    const titles = profile.unlocked && Array.isArray(profile.unlocked.titles) ? profile.unlocked.titles : [];
    return titles.includes(item.value);
  }
  // Biome grants (Micro glow-up: the Neon Sled Drone) are owned by completing their biome (decision 3), never by
  // level, so a level-30 profile that has not completed it does not get it for free through the price-0 rule.
  if (item.grant === 'biome') {
    return sanitizeBiomeProgress(profile.biomeProgress).completed.includes(item.biome);
  }
  const lvl = Number(profile.level) || 1;
  return item.price === 0 && Number(item.unlockLevel) <= lvl;
}

/**
 * Buy one item. PURE, and atomic: on ANY refusal it returns the profile object it was given, untouched,
 * so a caller that saves unconditionally still cannot persist a partial purchase.
 *
 * Refusals, in order: unknown id, already owned, not for sale (price 0: a level reward or an achievement
 * grant, owned by reaching it, never bought), level too low, not enough shards. The affordability
 * check is a single comparison against `price` rather than a subtraction followed by a clamp, because a
 * clamp would silently let a player buy with shards they do not have.
 * @param {Object} profile @param {string} id @returns {Object}
 */
export function purchase(profile, id) {
  const item = shopItem(id);
  if (!item || !profile || typeof profile !== 'object') return profile;
  if (isOwned(profile, id)) return profile;
  if (!(Number(item.price) > 0)) return profile;
  if ((Number(profile.level) || 1) < (Number(item.unlockLevel) || 1)) return profile;
  const bank = nonNeg(profile.bank);
  if (bank < item.price) return profile;
  return {
    ...profile,
    bank: bank - item.price,
    unlocked: {
      ...profile.unlocked,
      cosmetics: [...(Array.isArray(profile.unlocked && profile.unlocked.cosmetics) ? profile.unlocked.cosmetics : []), id],
    },
  };
}

/**
 * Equip an owned item into its slot. PURE. Idempotent: equipping what is already equipped returns the
 * same object unchanged, so a save is a no-op rather than a rewrite.
 * @param {Object} profile @param {string} id @returns {Object}
 */
export function equip(profile, id) {
  const item = shopItem(id);
  if (!item || !profile || typeof profile !== 'object') return profile;
  if (!isOwned(profile, id)) return profile;
  const equipped = profile.equipped && typeof profile.equipped === 'object' ? profile.equipped : {};
  if (equipped[item.slot] === item.value) return profile;
  return { ...profile, equipped: { ...equipped, [item.slot]: item.value } };
}

/** Unequip a slot back to 'default'. PURE. @param {Object} profile @param {string} slot @returns {Object} */
export function unequip(profile, slot) {
  if (!profile || typeof profile !== 'object') return profile;
  const equipped = profile.equipped && typeof profile.equipped === 'object' ? profile.equipped : {};
  if (equipped[slot] === 'default' || equipped[slot] === undefined) return profile;
  return { ...profile, equipped: { ...equipped, [slot]: 'default' } };
}/**
 * OWNER: progression engineer. PURE module — no Phaser, no DOM, no storage, no clock.
 *
 * W1: XP awards, Sync Level thresholds and level rewards. Everything tunable lives in
 * `src/data/progression/levels.json`; this file only does arithmetic on top of it.
 *
 * XP model (all parts are integers, summed with no hidden multiplier):
 *   distance    1 XP per 10 m                      (distanceM / 10, floored)
 *   score       1 XP per 50 points                 (score / 50, floored)
 *   tricks      12 XP per trick performed          (sum of the trick counts)
 *   shards      5 XP per Data Shard collected
 *   nearMisses  2 XP per near miss
 *   airtime     1 XP per full 2 s of the run's best single airtime
 * Pacing is anchored on MEASURED play, not on a hypothetical good run: an untrained player who only
 * steers (tools/sim/pacing.mjs --policy handsOff) earns ~33-44 XP per run (Debutmont base terrain, #65), so Sync Level 2
 * is set at 80 XP and lands on the third run — the "level 2 within the first 3 runs" target. The first earned biome
 * (Garbage Dump Glacier, level 4) is 3 750 XP, asserted to land within 14-28 measured minutes. Both are asserted in
 * tests/src/progression.test.js against a committed real-sim fixture (D-C numbers).
 *
 * The default profile shape is created ONCE by `defaultProfile()` with every field the later
 * workstreams (W2 missions, W4 bank/shop, W5 achievements) need, so they never need a migration.
 */

import { emptyUpgradeRanks } from "./PermanentUpgrades.js";
import { DRAFT_RULES_VERSION } from './DailyDraft.js';
import { BASE_BIOME_ID } from '../data/biomeAliases.js';

/** Profile schema version, independent of STORAGE.saveVersion. */
export const PROFILE_VERSION = 1;

/**
 * The base biome (issue #65): Debutmont is the normal run's terrain from the very first run. It is always
 * unlocked and can never be switched off, so it has no toggle row and its mask bit is never part of a
 * profile's enabled mask (the terrain generator treats the home bit as a no-op, and keeping it out keeps
 * masks canonical so leaderboard cohorts do not split on a meaningless bit). Defined once in data/biomeAliases.js
 * (shared with the terrain generator's BASE_BIOME_ID); re-exported here.
 */
export { BASE_BIOME_ID };

/** XP weights. Kept here (not in JSON) because they are arithmetic, not content. */
export const XP = Object.freeze({
  per10m: 1,
  per50Points: 1,
  perTrick: 12,
  perShard: 5,
  perNearMiss: 2,
  per2sAirtime: 1,
});

/** Fallback table, used only if levels.json is missing or unusable. Mirrors the shipped JSON minimally. */
const FALLBACK_TABLE = Object.freeze({
  cap: 3,
  levels: Object.freeze([
    Object.freeze({ level: 1, xpMin: 0, title: 'Signal Virgin', biome: null, cosmetic: null, boost: null }),
    Object.freeze({ level: 2, xpMin: 80, title: 'Bit Runner', biome: null, cosmetic: 'trail-cyan', boost: null }),
    Object.freeze({ level: 3, xpMin: 1200, title: 'Packet Jockey', biome: null, cosmetic: null, boost: null }),
  ]),
  biomeOrder: Object.freeze([]),
});

const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const int = (v, d = 0) => (isNum(v) ? Math.round(v) : d);
const clampInt = (v, min, d = 0) => Math.max(min, int(v, d));

/**
 * Validate/normalise a level table. Accepts the parsed levels.json (or anything else) and always
 * returns a usable table with strictly increasing thresholds and a consistent cap.
 * @param {*} raw
 * @returns {{cap:number, levels:Array<Object>, biomeOrder:string[]}}
 */
export function loadLevelTable(raw) {
  const src = raw && typeof raw === 'object' && Array.isArray(raw.levels) ? raw.levels : null;
  if (!src || !src.length) return { ...FALLBACK_TABLE, levels: FALLBACK_TABLE.levels.map((l) => ({ ...l })) };
  const levels = [];
  let lastXp = -1;
  for (const e of src) {
    if (!e || typeof e !== 'object') continue;
    const level = int(e.level, levels.length + 1);
    if (level !== levels.length + 1) continue; // levels must be dense 1..cap
    const xpMin = Math.max(clampInt(e.xpMin, 0), lastXp + 1);
    lastXp = xpMin;
    levels.push({
      level,
      xpMin,
      title: typeof e.title === 'string' ? e.title : `Level ${level}`,
      biome: typeof e.biome === 'string' && e.biome ? e.biome : null,
      cosmetic: typeof e.cosmetic === 'string' && e.cosmetic ? e.cosmetic : null,
      boost: typeof e.boost === 'string' && e.boost ? e.boost : null,
    });
  }
  if (levels.length < 2) return { ...FALLBACK_TABLE, levels: FALLBACK_TABLE.levels.map((l) => ({ ...l })) };
  levels[0].xpMin = 0;
  const biomeOrder = Array.isArray(raw.biomeOrder) ? raw.biomeOrder.filter((s) => typeof s === 'string') : [];
  return { cap: levels[levels.length - 1].level, levels, biomeOrder };
}

/**
 * XP awarded by one finished run, broken into parts so the UI can explain it.
 * Pure: never mutates the record, never throws, tolerant of junk fields.
 * @param {Partial<import('./SaveStore.js').RunRecord>} record
 * @returns {{total:number, parts:{key:string,label:string,xp:number}[]}}
 */
export function xpForRun(record) {
  const r = record && typeof record === 'object' ? record : {};
  const tricks = r.tricks && typeof r.tricks === 'object' ? r.tricks : {};
  const trickCount = Object.values(tricks).reduce((a, b) => a + clampInt(b, 0), 0);
  const parts = [
    { key: 'distance', label: 'DISTANCE', xp: Math.floor(clampInt(r.distanceM, 0) / 10) * XP.per10m },
    { key: 'score', label: 'SCORE', xp: Math.floor(clampInt(r.score, 0) / 50) * XP.per50Points },
    { key: 'tricks', label: 'TRICKS', xp: trickCount * XP.perTrick },
    { key: 'shards', label: 'SHARDS', xp: clampInt(r.shards, 0) * XP.perShard },
    { key: 'nearMisses', label: 'NEAR MISSES', xp: clampInt(r.nearMisses, 0) * XP.perNearMiss },
    { key: 'airtime', label: 'BEST AIR', xp: Math.floor(clampInt(r.maxAirtimeMs, 0) / 2000) * XP.per2sAirtime },
  ].filter((p) => p.xp > 0);
  const total = parts.reduce((s, p) => s + p.xp, 0);
  return { total, parts };
}

const table = (t) => (t && Array.isArray(t.levels) && t.levels.length ? t : loadLevelTable(t));

/**
 * @param {number} xp cumulative XP
 * @param {{cap:number, levels:Array<Object>}} t level table
 * @returns {number} level 1..cap
 */
export function levelForXp(xp, t) {
  const tb = table(t);
  const v = isNum(xp) ? xp : 0;
  let level = 1;
  for (const e of tb.levels) {
    if (v >= e.xpMin) level = e.level;
    else break;
  }
  return level;
}

/**
 * @param {number} xp cumulative XP
 * @param {{cap:number, levels:Array<Object>}} t level table
 * @returns {number} XP still needed for the next level, 0 at the cap
 */
export function xpToNext(xp, t) {
  const tb = table(t);
  const v = isNum(xp) ? xp : 0;
  const level = levelForXp(v, tb);
  const next = tb.levels.find((e) => e.level === level + 1);
  if (!next || level >= tb.cap) return 0;
  return Math.max(0, next.xpMin - v);
}

/**
 * What reaching `level` grants. Out-of-range levels clamp to 1..cap.
 * @param {number} level
 * @param {{cap:number, levels:Array<Object>}} t level table
 * @returns {{level:number,title:string,biome:string|null,cosmetic:string|null,boost:string|null}}
 */
export function rewardsForLevel(level, t) {
  const tb = table(t);
  const lvl = Math.min(Math.max(int(level, 1), 1), tb.cap);
  const e = tb.levels.find((x) => x.level === lvl) || tb.levels[0];
  return { level: e.level, title: e.title, biome: e.biome, cosmetic: e.cosmetic, boost: e.boost };
}

/**
 * A brand-new profile: the complete v1 shape with empty defaults. Deep-fresh on every call.
 * @returns {Object} Profile
 */
export function defaultProfile() {
  return {
    v: PROFILE_VERSION,
    xp: 0,
    level: 1,
    bank: 0,
    lifetime: {
      runs: 0,
      distanceM: 0,
      playMs: 0,
      score: 0,
      tricks: {},
      shards: 0,
      nearMisses: 0,
      bsodBluffs: 0,
      bsodSurfs: 0,
      bestScore: 0,
      bestDistanceM: 0,
      bestCombo: 0,
      maxAirtimeMs: 0,
      // W5 daily achievements (ACH-3): daily-seed runs credited, and the longest Daily streak seen at a
      // credit. Kept here so the achievements grid reads the same numbers the unlock did.
      dailyRuns: 0,
      bestStreak: 0,
    },
    // W5: `titles` holds achievement title rewards. It is present from the start so a fresh profile and a
    // reloaded one have the identical shape — a missing key would make the two disagree on first save.
    unlocked: { biomes: [], cosmetics: [], titles: [], boosts: {}, musicVocals: false },
    equipped: { trail: 'default', glow: 'default', rider: 'default', theme: 'default', title: 'default' },
    // Issue #65: unlocked biomes default ON, so the profile stores only the player's explicit OFF choices (one
    // bit per biome, the biome table's `bit`). The old opt-in `biomeMask` field is gone: it is no longer
    // written and an old save's value is ignored, which migrates every existing profile to all-ON.
    biomeOff: 0,
    // W4 loadout: which boosts are switched ON for the next run. Separate from `unlocked.boosts`, which
    // records what the player owns. Additive, default-off, and safe on an old save by omission - which is
    // why it needs no saveVersion bump.
    boosts: { errorCorrection: false, headStart: false },
    // Permanent ranks persist forever; OFF by default so clean/daily competition stays unchanged.
    upgrades: emptyUpgradeRanks(),
    upgradesEnabled: false,
    dailyDraft: {version:DRAFT_RULES_VERSION,ranks:emptyUpgradeRanks()},
    bsodGym: { discovered: false, owned: false },
    missions: { counter: 0, active: [], progress: {} },
    achievements: {},
    credited: [],
    // Marvin decision 3: biomes actually ENTERED in a run, and biomes ridden through a whole sector without
    // the run-ending crash inside it. Additive (an old v1 profile loads with empty sets); the unlock itself
    // stays where it was (pendingBiomes / unlocked.biomes). See BiomeDiscovery.js.
    biomeProgress: { encountered: [], completed: [] },
  };
}/**
 * OWNER: progression engineer. Thin service glue: owns one ProfileStore, listens to RUN_END, and
 * exposes the awards of the last run for GameOverScene to read. NO Phaser imports, no rendering.
 *
 * RunScene is not edited (spec §5 W1): the service subscribes to the global RUN_END event, computes
 * awards SYNCHRONOUSLY on the record it is handed, persists, and stores the awards object in the
 * registry under REG.LAST_AWARDS (additive key) for the UI to display.
 */
import { EVT } from '../events.js';
import { REG } from '../constants.js';
import { ProfileStore } from './ProfileStore.js';
import { levelForXp, xpToNext, rewardsForLevel, loadLevelTable } from './Progression.js';
import { newlyAffordable, shopState } from './ShopPrompt.js';

/**
 * Create the progression service, load the profile (and backfill it once from stored runs if this
 * device already has history), and start listening for RUN_END.
 *
 * @param {Phaser.Game} game
 * @param {{levels:*, saveStore?:*, now?:function():number}} o  `levels` is the parsed levels.json.
 * @returns {Promise<ProgressionService>}
 */
export async function createProgressionService(game, o) {
  const service = new ProgressionService(game, o);
  await service.init();
  return service;
}

export class ProgressionService {
  /**
   * @param {Phaser.Game} game
   * @param {{levels:*, saveStore?:*, now?:function():number, store?:ProfileStore, missions?:*}} o
   */
  constructor(game, o) {
    this.game = game;
    this.levels = loadLevelTable(o.levels);
    // W2 missions attach here (set by createServices) so RUN_END has exactly one listener that
    // decides whether a run counts at all.
    this.missions = o.missions || null;
    this.store = o.store || new ProfileStore({ levels: this.levels });
    this.now = o.now || (() => Date.now());
    this.alive = true;
    this._onRunEnd = (payload) => this.onRunEnd(payload);
  }

  /** Load the profile, backfill once if the device already has runs, then subscribe. */
  async init() {
    this.alive = true;
    this.store.load();
    const saveStore = this.game.registry.get(REG.SAVE_STORE);
    if (saveStore && this.store.profile.lifetime.runs === 0) {
      try {
        // Backfill the complete local history; truncating here permanently loses lifetime stats on
        // devices with more runs than the UI's usual recent-history window.
        const runs = await saveStore.getRecentRuns(Number.MAX_SAFE_INTEGER);
        if (Array.isArray(runs) && runs.length) this.store.backfill(runs);
      } catch (e) { /* backfill is a nicety; never block boot on it */ }
    }
    this.game.events.on(EVT.RUN_END, this._onRunEnd);
    this.game.events.once('destroy', () => this.destroy());
    this.publish();
    return this;
  }

  /** @returns {Object} the live profile. */
  get profile() {
    return this.store.profile;
  }

  /**
   * RUN_END handler. Computes awards synchronously and publishes them for Game Over.
   * @param {{record:Object}} payload
   */
  onRunEnd(payload) {
    if (!this.alive) return;
    const record = payload && payload.record ? payload.record : null;
    // W4.1: snapshot the spendable state BEFORE the run is credited, so the shop autoprompt can tell
    // whether THIS run newly made something affordable. Taken from the live profile rather than derived
    // from the credit afterwards, because both `credit()` and `applyMissions()` move the bank.
    const before = shopState(this.store.profile);
    // Decision 3: RunScene's biome visits ride beside the record and are credited with it (so a replayed run,
    // which credit() refuses, records nothing twice).
    const biomeVisits = payload && payload.biomeVisits && typeof payload.biomeVisits === 'object' ? payload.biomeVisits : null;
    const awards = record ? this.store.credit(record, { ...this._dailyFacts(), ...(biomeVisits ? { biomeVisits } : {}) }) : null;
    // Missions ride on the crediting decision, not on RUN_END itself: `credit()` returns null for a
    // run whose hash is already in the ring, so a replayed event pays missions nothing. Missions then
    // fold their own XP/shards into the same profile before the awards view is built, so Game Over
    // shows one consistent total.
    let missionRoll = null;
    if (awards && record && this.missions) {
      try {
        missionRoll = this.missions.onRunCredited(record);
      } catch (e) {
        // Missions must never break the boot or the run's XP: log-free degrade, carry on.
        missionRoll = null;
      }
    }
    const view = this._awardsView(awards, record, missionRoll);
    // W4.1: decide the shop autoprompt here, where both the before- and after-credit state are known, and
    // publish it as a plain boolean. Game Over only renders it; it does not re-derive economy rules.
    // Not published for a replayed run (awards === null): that run paid nothing, so it changed nothing.
    const showShop = Boolean(awards) && this._shopAutoprompt(before);
    view.shopAutoprompt = showShop;
    this.lastAwards = view;
    this.game.registry.set(REG.LAST_AWARDS, view);
    this.publish(view);
  }

  /**
   * ACH-3: the caller-owned daily facts the achievement evaluator needs. The streak comes from SaveStore,
   * which RunScene has already handed this run (saveRun pushes it synchronously before RUN_END), so the
   * run that makes a 3-day streak unlocks "Three in a Row" on its own Game Over. Guarded: a missing or
   * throwing SaveStore means streak 0, never a lost credit.
   * @returns {{streak:number}}
   */
  _dailyFacts() {
    try {
      const saveStore = this.game.registry.get(REG.SAVE_STORE);
      if (!saveStore || typeof saveStore.getDailyStreak !== 'function') return { streak: 0 };
      const st = saveStore.getDailyStreak(this.now());
      return { streak: st && Number.isFinite(st.streak) ? st.streak : 0 };
    } catch (e) {
      return { streak: 0 };
    }
  }

  /**
   * Did this run newly make a shop item affordable?
   *
   * Kept behind a guard because a broken economy must never stop a run from being credited: if anything
   * here throws, the answer is "no popup" and the run stands.
   * @param {{bank:number, level:number, owned:Array<string>}} before
   * @returns {boolean}
   */
  _shopAutoprompt(before) {
    try {
      const after = shopState(this.store.profile);
      return newlyAffordable(before, after);
    } catch (e) {
      return false;
    }
  }

  /** @returns {{xp:{total:number,parts:Array},levelBefore:number,levelAfter:number,leveledTo:number,rewards:Object|null,title:string|null,credited:boolean,progress:{level:number,xp:number,levelXp:number,nextXp:number,xpToNext:number}}} */
  _awardsView(awards, record, missionRoll) {
    const p = this.store.profile;
    const table = this.levels;
    const level = levelForXp(p.xp, table);
    const levelXp = table.levels[level - 1] ? table.levels[level - 1].xpMin : 0;
    const nextXp = level < table.cap ? table.levels[level].xpMin : levelXp;
    const rw = rewardsForLevel(level, table);
    // LVL-1: the level-up is measured from before the run to the profile AFTER missions folded their XP in,
    // not taken from credit() alone. A threshold crossed by mission XP used to raise the level silently: no
    // level-up line, no reward line, even though applyMissions granted the reward. Same shape as creditRun.
    const levelBefore = awards ? awards.levelBefore : level;
    const leveledTo = awards && level > levelBefore ? level : 0;
    const rewards = leveledTo ? rewardsForLevel(leveledTo, table) : null;
    // Every level crossed by THIS run, not just the last one: a big run can jump L1 -> L3 and the L2 reward
    // (e.g. trail-cyan) is still earned. Game Over lists all of them.
    const rewardsEarned = leveledTo
      ? table.levels.filter((e) => e.level > levelBefore && e.level <= leveledTo).map((e) => rewardsForLevel(e.level, table))
      : [];
    return {
      xp: awards ? awards.xp : { total: 0, parts: [] },
      levelBefore,
      levelAfter: level,
      leveledTo,
      rewards,
      rewardsEarned,
      title: rewards ? rewards.title : (awards ? null : rw.title),
      credited: Boolean(awards),
      // Resonance bar: XP progress inside the current level.
      progress: {
        level,
        xp: p.xp,
        levelXp,
        nextXp,
        xpToNext: xpToNext(p.xp, table),
        ratio: nextXp > levelXp ? Math.min(1, Math.max(0, (p.xp - levelXp) / (nextXp - levelXp))) : 1,
      },
      record: record ? { id: record.id, seed: record.seed } : null,
      earnedCosmetics: rewards && rewards.cosmetic ? [rewards.cosmetic] : [],
      pendingBiomes: rewards && rewards.biome ? [rewards.biome] : [],
      // W5: achievements unlocked BY THIS RUN, so Game Over can announce them. Forwarded from the credit
      // result rather than re-read from the profile, which would include unlocks from earlier sessions and
      // re-announce them on every run.
      achievements: awards && Array.isArray(awards.achievements) ? awards.achievements : [],
      // W2: what the mission set paid this run, for the Game Over list and the completion toast.
      missions: missionRoll ? {
        completed: missionRoll.completed || [],
        setCleared: Boolean(missionRoll.setCleared),
        xp: missionRoll.xp || 0,
        shards: missionRoll.shards || 0,
      } : null,
    };
  }

  /** Push the current profile + last awards into the registry so scenes can read them at any time. */
  publish(view) {
    const p = this.store.profile;
    this.game.registry.set(REG.PROFILE, p);
    if (view) this.game.registry.set(REG.LAST_AWARDS, view);
  }

  /** @returns {Object|null} awards object of the most recent run (for GameOverScene). */
  get awardsForDisplay() {
    return this.lastAwards || this.game.registry.get(REG.LAST_AWARDS) || null;
  }

  /** Detach the RUN_END listener (scene/game shutdown). */
  destroy() {
    this.alive = false;
    try { this.game.events.off(EVT.RUN_END, this._onRunEnd); } catch (e) { /* already gone */ }
  }
}/**
 * OWNER: progression engineer. The ONE place that decides whether a modded (boosted) run may rank.
 *
 * Spec W4 requires every ranking decision to route through a single helper that reads
 * `MODDED_RUNS_RANKED`, and that grep shows no other place deciding whether a modded run counts. A run
 * with a boost is a different game — Head Start literally moves the start line — so while the constant is
 * false a boosted run must not enter the clean top-10, seed best, daily best or streak. It still earns
 * Resonance, Data Shards and mission progress: the boosts are not a penalty, they are a separate board.
 *
 * Why a module and not a condition at each call site: this was the one piece of W4 that review could not
 * verify behaviourally. Five inline `!rec.modded` checks pass every test and still mean that turning the
 * constant on requires finding all five, and that a sixth ranking surface added later silently defaults
 * to excluding modded runs. tests/src/modded-ranking.test.js greps the tree to keep it to one place.
 *
 * Deliberately NOT here: `computeLedgerHash`. Hashing is integrity, not ranking. Since decision 6 the v2
 * hash covers `modded` (so a sharecode cannot strip it), but WHETHER a modded run ranks is still decided
 * only here.
 *
 * Decisions 1 and 2 (2026-11-14) add the other ranking rule: which runs are OFFICIAL Daily runs
 * (isOfficialDaily). Daily best and the streak count only those.
 */
import { MODDED_RUNS_RANKED } from '../constants.js';
import { DailyPatch } from './DailyPatch.js';
import {DRAFT_BUDGET,DRAFT_RULES_VERSION,validDraftRanks} from './DailyDraft.js';

/**
 * Whether this record plays on the MODDED board rather than the clean one.
 *
 * This exists so a view can label the board it is showing without testing the field itself. Game Over needs
 * the answer twice — which board to load, and whether to say MODDED - UNRANKED instead of announcing a seed
 * best — and both are ranking decisions, so both belong here rather than in the scene.
 *
 * @param {{modded?:boolean}} record
 * @param {{ranked?:boolean}} [o] test override
 * @returns {boolean}
 */
export function boardsModded(record, o) {
  if (!record || typeof record !== 'object') return false;
  if (record.modded !== true||record.dailyMode==='draft') return false;
  return !ranksModded(o);
}

/**
 * Whether modded runs are allowed to rank right now.
 * @param {{ranked?:boolean}} [o] test override; production callers pass nothing and read the constant.
 * @returns {boolean}
 */
export function ranksModded(o) {
  if (o && typeof o.ranked === 'boolean') return o.ranked;
  return MODDED_RUNS_RANKED === true;
}

/**
 * Whether this record may appear on a CLEAN ranking surface (top-10, seed best, daily best, streak).
 *
 * A missing/unknown `modded` field means a pre-W4 record or an imported one, and those are clean by
 * definition: W4 is additive, and treating an absent field as modded would retroactively disqualify every
 * run a player has already set. `null`/non-object is not rankable at all, which keeps a junk record from
 * poisoning a board.
 * @param {Object} record
 * @param {{ranked?:boolean}} [o]
 * @returns {boolean}
 */
export function isRankable(record, o) {
  if (!record || typeof record !== 'object') return false;
  if (record.dailyMode==='draft'||record.hashV===4) return false;
  if (record.modded !== true) return true;
  return ranksModded(o);
}

/**
 * Whether this record belongs on the MODDED board.
 *
 * The complement of `isRankable`, and deliberately defined here rather than at the view: a modded tab that
 * filtered on `r.modded === true` itself would be the sixth scattered decision this module exists to
 * prevent, and would ignore the constant when it flips.
 * @param {Object} record
 * @param {{ranked?:boolean}} [o]
 * @returns {boolean}
 */
export function isModdedOnly(record, o) {
  if (!record || typeof record !== 'object') return false;
  if (record.modded !== true||record.dailyMode==='draft'||record.hashV===4) return false;
  // When the constant is on, a modded run ranks on the CLEAN board too, so it does not also need a
  // separate listing to be discoverable.
  return !ranksModded(o);
}

/**
 * Filter a list of records down to the ones allowed on a clean surface. Callers use this instead of
 * hand-rolling the predicate, so the rule stays in one place even as surfaces are added.
 * @param {Array<Object>} records
 * @param {{ranked?:boolean}} [o]
 * @returns {Array<Object>}
 */
export function rankableOnly(records, o) {
  return (Array.isArray(records) ? records : []).filter((r) => isRankable(r, o));
}

/**
 * A predicate for "on the same board as this record": the modded board when `record` boards modded,
 * otherwise the clean board. A run's in-world BEST marker and its NEW BEST chase the best on the board the
 * run itself will land on, the same split Game Over makes when it picks which list to compare against.
 *
 * While MODDED_RUNS_RANKED is false a clean run never chases a boosted distance and a boosted run chases
 * the modded runs. When the constant is on, every run is on the one clean board.
 * @param {{modded?:boolean}} record the run being played (any object carrying the loadout's `modded`)
 * @param {{ranked?:boolean}} [o]
 * @returns {(r:Object) => boolean}
 */
export function sameBoardAs(record, o) {
  if(record?.dailyMode==='draft')return (r)=>countsForDraftDailyBest(r)&&r.seed===record.seed;
  return boardsModded(record, o) ? (r) => isModdedOnly(r, o) : (r) => isRankable(r, o);
}

/**
 * Decision 2: whether this record is an OFFICIAL Daily run. Only a run started from the DAILY RUN menu
 * item is official; a typed `daily-YYYY-MM-DD[@mask]` seed is a practice run.
 *
 *  - The seed must be a daily seed, and the record must have been played on THAT date's mask and rule.
 *    Official runs are on them by construction; the explicit check keeps a mis-stamped record out.
 *  - A v2 record (`hashV` 2, written since decision 6) is official only when `dailyOfficial === true`.
 *    This matters most for a typed `daily-<today>` with no suffix: it plays today's mask AND today's rule,
 *    so it is indistinguishable from a legacy official run by mask and rule alone.
 *  - A legacy record (no `hashV`) has no flag. It counts as official when its mask (absent = 0) and its
 *    `dailyRuleId` are the date's. That keeps the history of real Daily runs and drops typed runs that
 *    used a different mask.
 * @param {Object} record
 * @returns {boolean}
 */
export function isOfficialDaily(record) {
  if (!record || typeof record !== 'object') return false;
  const key = DailyPatch.dateKeyFromSeed(record.seed);
  if (!key) return false;
  const info = DailyPatch.infoForDateKey(key);
  if (!info) return false;
  if (((Number(record.biomeMask) >>> 0) || 0) !== info.biomeMask) return false;
  if (record.dailyRuleId !== info.rule.id) return false;
  const versioned = Number.isFinite(record.hashV) && record.hashV >= 2;
  return versioned ? record.dailyOfficial === true : true;
}

/**
 * Decision 1: whether this record may set a Daily best (TODAY'S BEST on Title and Game Over). An
 * official Daily run that is allowed on a clean surface.
 * @param {Object} record @param {{ranked?:boolean}} [o]
 * @returns {boolean}
 */
export function countsForDailyBest(record, o) {
  return record?.dailyMode!=='draft'&&isRankable(record,o)&&isOfficialDaily(record);
}

/** Daily Draft only: strict rules, one original day seed, fixed verified
 * upgrade-credit budget, no bought shop boosts and version-four hashed mode.
 */
export function countsForDraftDailyBest(r){
  return Boolean(r && r.hashV===4 && r.dailyMode==='draft' &&
    r.draftRulesVersion===DRAFT_RULES_VERSION && r.draftBudget===DRAFT_BUDGET &&
    r.modded===true && (!r.boosts||r.boosts.length===0) &&
    validDraftRanks(r.upgradeRanks||{}) && isOfficialDaily(r));
}

/**
 * Decision 1: whether this record holds a day of the Daily streak. Official, clean, and played on THIS
 * device: an imported run (`imported: true`, set by SaveStore.importSharecode) never extends the streak.
 * @param {Object} record @param {{ranked?:boolean}} [o]
 * @returns {boolean}
 */
export function countsForStreak(record, o) {
  return (countsForDailyBest(record,o)||countsForDraftDailyBest(record)) && record.imported !== true;
}/**
 * OWNER: core-logic engineer. NO Phaser imports.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Seeded randomness. Seed string -> xxHash32 (real, spec-compliant) -> mulberry32 PRNG state.
 * Same seed => same sequence on every machine. `fork(label)` derives an independent stream from the
 * ORIGINAL seed state (not the current position), so consuming numbers in one stream never shifts another
 * and the order in which forks are created does not matter.
 */

const P1 = 2654435761;
const P2 = 2246822519;
const P3 = 3266489917;
const P4 = 668265263;
const P5 = 374761393;

const rotl = (x, r) => ((x << r) | (x >>> (32 - r))) >>> 0;

/**
 * Encode a string to UTF-8 bytes without TextEncoder (not present in every Jest environment).
 * @param {string} str
 * @returns {number[]}
 */
function utf8Bytes(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const d = str.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00);
        i++;
      }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

/**
 * xxHash32 of a string (UTF-8 bytes).
 * @param {string} input
 * @param {number} [seed=0] 32-bit hash seed.
 * @returns {number} unsigned 32-bit integer.
 */
export function xxHash32(input, seed = 0) {
  const b = utf8Bytes(String(input));
  const len = b.length;
  seed = seed >>> 0;
  const lane = (i) => (b[i] | (b[i + 1] << 8) | (b[i + 2] << 16) | (b[i + 3] << 24)) >>> 0;
  let p = 0;
  let h;
  if (len >= 16) {
    let v1 = (seed + P1 + P2) >>> 0;
    let v2 = (seed + P2) >>> 0;
    let v3 = seed;
    let v4 = (seed - P1) >>> 0;
    const limit = len - 16;
    while (p <= limit) {
      v1 = Math.imul(rotl((v1 + Math.imul(lane(p), P2)) >>> 0, 13), P1) >>> 0;
      v2 = Math.imul(rotl((v2 + Math.imul(lane(p + 4), P2)) >>> 0, 13), P1) >>> 0;
      v3 = Math.imul(rotl((v3 + Math.imul(lane(p + 8), P2)) >>> 0, 13), P1) >>> 0;
      v4 = Math.imul(rotl((v4 + Math.imul(lane(p + 12), P2)) >>> 0, 13), P1) >>> 0;
      p += 16;
    }
    h = (rotl(v1, 1) + rotl(v2, 7) + rotl(v3, 12) + rotl(v4, 18)) >>> 0;
  } else {
    h = (seed + P5) >>> 0;
  }
  h = (h + len) >>> 0;
  while (p + 4 <= len) {
    h = (h + Math.imul(lane(p), P3)) >>> 0;
    h = Math.imul(rotl(h, 17), P4) >>> 0;
    p += 4;
  }
  while (p < len) {
    h = (h + Math.imul(b[p], P5)) >>> 0;
    h = Math.imul(rotl(h, 11), P1) >>> 0;
    p++;
  }
  h ^= h >>> 15;
  h = Math.imul(h, P2) >>> 0;
  h ^= h >>> 13;
  h = Math.imul(h, P3) >>> 0;
  h ^= h >>> 16;
  return h >>> 0;
}

/**
 * Cheap integer mixer: combine two 32-bit ints into a well-scrambled unsigned 32-bit value. Pure, allocation free.
 * Used for lattice noise and per-index seeding.
 * @param {number} a
 * @param {number} b
 * @returns {number} unsigned 32-bit.
 */
export function hashInts(a, b) {
  let h = Math.imul((a ^ 0x9e3779b9) >>> 0, 0x85ebca6b) ^ Math.imul((b + 0x7f4a7c15) >>> 0, 0xc2b2ae35);
  h ^= h >>> 15;
  h = Math.imul(h, 0x2c1b3c6d);
  h ^= h >>> 12;
  h = Math.imul(h, 0x297a2d39);
  h ^= h >>> 15;
  return h >>> 0;
}

export class Rng {
  /**
   * @param {string|number} seed seed string (hashed with xxHash32) or a number used directly as state.
   */
  constructor(seed) {
    const s = typeof seed === 'number' ? seed >>> 0 : xxHash32(String(seed));
    /** Initial state, immutable: fork() derives from this so it is independent of consumption. */
    this.baseSeed = s;
    this.state = s;
  }

  /** @returns {number} float in [0,1). */
  next() {
    // mulberry32
    let t = (this.state = (this.state + 0x6d2b79f5) >>> 0);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  /**
   * @param {number} min inclusive
   * @param {number} max inclusive
   * @returns {number} integer.
   */
  int(min, max) {
    return min + Math.floor(this.next() * (max - min + 1));
  }

  /**
   * @param {number} min
   * @param {number} max
   * @returns {number} float in [min,max).
   */
  range(min, max) {
    return min + this.next() * (max - min);
  }

  /**
   * @param {number} p probability 0..1
   * @returns {boolean}
   */
  chance(p) {
    return this.next() < p;
  }

  /**
   * @template T
   * @param {T[]} arr non-empty
   * @returns {T}
   */
  pick(arr) {
    return arr[this.int(0, arr.length - 1)];
  }

  /**
   * Weighted pick.
   * @template T
   * @param {T[]} items
   * @param {(item:T)=>number} weightFn returns weight >= 0
   * @returns {T|undefined} undefined if items empty or all weights 0.
   */
  weighted(items, weightFn) {
    let total = 0;
    for (let i = 0; i < items.length; i++) total += Math.max(0, weightFn(items[i]));
    if (!(total > 0)) return undefined;
    let r = this.next() * total;
    let last;
    for (let i = 0; i < items.length; i++) {
      const w = Math.max(0, weightFn(items[i]));
      if (w <= 0) continue;
      last = items[i];
      r -= w;
      if (r < 0) return items[i];
    }
    return last;
  }

  /**
   * Derive an independent, deterministic child stream (e.g. 'terrain', 'hazards', 'glitch') so that
   * consuming numbers in one subsystem never shifts another. Does NOT advance this stream and does not
   * depend on how far it has advanced.
   * @param {string} label
   * @returns {Rng}
   */
  fork(label) {
    return new Rng(xxHash32(label, this.baseSeed));
  }
}/** #87: standalone, deliberately unverified artwork from decoded ghost poses. */
export const RUN_TRACE_ART_VERSION = 1;
export const MAX_ART_POSES = 32_768;
export const MAX_ART_SVG_BYTES = 8_192;

const POSE_WIDTH = 3;
const ART_POINTS = 64;
const GRID = 4;
const ORIENTATION_SLOTS = 16;
const FULL_TURN = 2 * Math.PI;
const ORIENTATION_COLORS = ['#384158', '#6883a6', '#78e5e8', '#ff9ccf'];
const MAX_COMPONENT_MAGNITUDE = 1e9;

function boundsOf(poses) {
  if (!(poses instanceof Float32Array) || poses.length % POSE_WIDTH !== 0) {
    throw new TypeError('Expected complete Float32 ghost poses');
  }
  const count = poses.length / POSE_WIDTH;
  if (count < 2 || count > MAX_ART_POSES) {
    throw new RangeError(`Trace art needs 2 to ${MAX_ART_POSES} poses`);
  }
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  // Check the entire trace, not just rendered samples: invalid values must not
  // be hidden by the resampler or reach an SVG attribute.
  for (let i = 0; i < poses.length; i += POSE_WIDTH) {
    const x = poses[i], y = poses[i + 1], angle = poses[i + 2];
    if (![x, y, angle].every((v) => Number.isFinite(v) && Math.abs(v) <= MAX_COMPONENT_MAGNITUDE)) {
      throw new RangeError('Ghost pose components must be finite and within art limits');
    }
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    minY = Math.min(minY, y);
    maxY = Math.max(maxY, y);
  }
  return { count, minX, maxX, minY, maxY };
}

function project(value, low, high, from, to) {
  const unit = low === high ? 0.5 : Math.max(0, Math.min(1, (value - low) / (high - low)));
  return GRID * Math.round((from + (to - from) * unit) / GRID);
}

function composePath(poses) {
  const { count, minX, maxX, minY, maxY } = boundsOf(poses);
  const points = [];
  // Fixed size and endpoint-anchored interpolation avoid leaking the exact
  // source sample count. Each axis loses both world origin and absolute scale.
  for (let i = 0; i < ART_POINTS; i++) {
    const sample = i * (count - 1) / (ART_POINTS - 1);
    const lower = Math.floor(sample);
    const mix = sample - lower;
    const a = lower * POSE_WIDTH, b = Math.min(lower + 1, count - 1) * POSE_WIDTH;
    const x = poses[a] + (poses[b] - poses[a]) * mix;
    const y = poses[a + 1] + (poses[b + 1] - poses[a + 1]) * mix;
    points.push([project(x, minX, maxX, 120, 840), project(y, minY, maxY, 268, 456)]);
  }
  const path = points.map(([x, y], i) => `${i ? 'L' : 'M'}${x} ${y}`).join(' ');
  return { path, first: points[0], last: points.at(-1) };
}

// Take the strongest *observed* shortest-arc delta in each fixed relative
// band. Missing samples and full turns between samples cannot be inferred.
function composeOrientationAccents(poses) {
  const pairCount = poses.length / POSE_WIDTH - 1;
  const peaks = new Uint8Array(ORIENTATION_SLOTS);
  for (let i = 0; i < pairCount; i++) {
    const slot = Math.floor((i + 0.5) * ORIENTATION_SLOTS / pairCount);
    const a = poses[i * POSE_WIDTH + 2], b = poses[(i + 1) * POSE_WIDTH + 2];
    const arc = Math.abs(b - a) % FULL_TURN;
    const delta = Math.min(arc, FULL_TURN - arc);
    const tier = delta >= 0.35 ? 3 : delta >= 0.12 ? 2 : delta >= 0.035 ? 1 : 0;
    peaks[slot] = Math.max(peaks[slot], tier);
  }
  const marks = Array.from(peaks, (tier, i) =>
    `<circle cx="${135 + 46 * i}" cy="499" r="${2 + tier}" fill="${ORIENTATION_COLORS[tier]}"/>`
  ).join('');
  return `<g aria-label="Coarse sampled sled orientation changes">${marks}</g>`;
}

function composeSvg(poses, orientationStudy) {
  const { path, first, last } = composePath(poses);
  const studyName = orientationStudy ? 'SLED ORIENTATION STUDY / ART V2' : `SLED PATH STUDY / ART V${RUN_TRACE_ART_VERSION}`;
  const stamp = orientationStudy ? 'V2 STUDY' : `V${RUN_TRACE_ART_VERSION}`;
  const description = orientationStudy
    ? 'An abstract neon path with coarse recorded orientation-change accents. It is local artwork, not a verified result.'
    : 'An abstract neon motif from a recorded sled path. It is local artwork, not a verified result.';
  const accents = orientationStudy ? composeOrientationAccents(poses) : '';
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="960" height="620" viewBox="0 0 960 620" role="img" aria-labelledby="art-title art-desc">
<title id="art-title">Bitstream Bluffs Run DNA: Local / Unverified</title>
<desc id="art-desc">${description}</desc>
<defs>
  <linearGradient id="sky" x1="0" y1="0" x2="1" y2="1">
    <stop stop-color="#141a37"/><stop offset="0.55" stop-color="#100d29"/><stop offset="1" stop-color="#290d2b"/>
  </linearGradient>
  <linearGradient id="ion" gradientUnits="userSpaceOnUse" x1="120" x2="840" y1="268" y2="268">
    <stop stop-color="#64faff"/><stop offset="0.5" stop-color="#a2a4ff"/><stop offset="1" stop-color="#ff7bc7"/>
  </linearGradient>
  <radialGradient id="halo">
    <stop stop-color="#763c9f" stop-opacity=".34"/><stop offset="1" stop-color="#763c9f" stop-opacity="0"/>
  </radialGradient>
</defs>
<rect width="960" height="620" fill="#080914"/>
<rect x="18" y="18" width="924" height="584" rx="32" fill="url(#sky)" stroke="#464463" stroke-width="2"/>
<ellipse cx="700" cy="310" rx="308" ry="270" fill="url(#halo)"/>
<path d="M64 188H896 M64 540H896" stroke="#434564" fill="none"/>
<g font-family="system-ui,sans-serif">
  <circle cx="73" cy="64" r="5" fill="#64faff"/>
  <text x="89" y="69" fill="#bdcdf5" font-size="15" font-weight="700" letter-spacing="3">BITSTREAM BLUFFS</text>
  <text x="66" y="143" fill="#f3f2ff" font-size="71" font-weight="800" letter-spacing="-2">RUN DNA</text>
  <text x="72" y="170" fill="#96a5d1" font-size="13" font-weight="600" letter-spacing="3">${studyName}</text>
  <rect x="668" y="49" width="228" height="38" rx="19" fill="#261637" stroke="#f290cd"/>
  <circle cx="688" cy="68" r="4" fill="#ff7bc7"/>
  <text x="703" y="74" fill="#ffd1ee" font-size="15" font-weight="750" letter-spacing="1.3">LOCAL / UNVERIFIED</text>
  <rect x="64" y="209" width="832" height="309" rx="20" fill="#0c1026" fill-opacity=".9" stroke="#464463"/>
  <path d="M104 270H856 M104 316H856 M104 362H856 M104 408H856 M104 454H856 M120 255V470 M240 255V470 M360 255V470 M480 255V470 M600 255V470 M720 255V470 M840 255V470" stroke="#363854" stroke-opacity=".67" fill="none"/>
  <path d="M104 247H113V238 M847 238V247H856 M104 477H113V486 M847 486V477H856" stroke="#626483" fill="none"/>
  <text x="122" y="240" fill="#929cbd" font-size="12" font-weight="600" letter-spacing="2">NORMALIZED TRACE</text>
  <path d="${path}" fill="none" stroke="url(#ion)" stroke-width="24" stroke-opacity=".09" stroke-linecap="round" stroke-linejoin="round"/>
  <path d="${path}" fill="none" stroke="url(#ion)" stroke-width="11" stroke-opacity=".22" stroke-linecap="round" stroke-linejoin="round"/>
  <path d="${path}" fill="none" stroke="url(#ion)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>
  <circle cx="${first[0]}" cy="${first[1]}" r="6" fill="#141932" stroke="#64faff" stroke-width="2"/>
  <circle cx="${last[0]}" cy="${last[1]}" r="5" fill="#ff7bc7" stroke="#ffd1ee" stroke-width="2"/>
  <path d="M104 499H856" stroke="url(#ion)" stroke-opacity=".38"/>${accents}
  <text x="65" y="571" fill="#bdc7e7" font-size="13" font-weight="700" letter-spacing="2">RECORDED PATH / ARTWORK ONLY</text>
  <text x="894" y="571" text-anchor="end" fill="#a4adcc" font-size="13" font-weight="600" letter-spacing="2">${stamp} / NO ATTESTATION</text>
</g>
</svg>
`;
  if (svg.length > MAX_ART_SVG_BYTES) throw new RangeError('Trace artwork exceeded its byte limit');
  return svg;
}

/**
 * @param {Float32Array} poses Decoded GhostTape v1 x/y/angle triples.
 * @returns {string} Standalone ASCII Art V1 SVG; no header or user strings.
 */
export function renderRunTraceArt(poses) {
  return composeSvg(poses, false);
}

/**
 * @param {Float32Array} poses Decoded GhostTape v1 x/y/angle triples.
 * @returns {string} Opt-in local Art V2 study; not a trick or timing analysis.
 */
export function renderRunTraceOrientationStudy(poses) {
  return composeSvg(poses, true);
}/**
 * OWNER: core-logic engineer. NO Phaser imports.
 *
 * Named, domain-separated random streams for one run (issue #59). Every stream is
 * `new Rng(seed).fork(label)`: derived from the ORIGINAL seed state, so drawing from a
 * cosmetic stream can never advance or shift the physics stream, and vice versa.
 * Streams restart from the seed whenever a RunScene is created (new run, retry,
 * replay). Their numeric state is part of a future replay header.
 */
import { Rng } from './Rng.js';

/** Bump when a label, derivation or draw order changes: old replay tapes become incompatible. */
export const RUN_RANDOM_VERSION = 1;

/** Stream labels. Physics streams affect gameplay; visual streams must never. */
export const RUN_STREAMS = Object.freeze({
  physicsScramble: 'physics/scramble',
  visualSled: 'visual/sled',
  visualFx: 'visual/fx',
  visualCamera: 'visual/camera',
});

/**
 * @param {string} seed the run seed exactly as the terrain uses it.
 * @returns {{version:number, physicsScramble:Rng, visualSled:Rng, visualFx:Rng, visualCamera:Rng}}
 */
export function runRandomStreams(seed) {
  const root = new Rng(String(seed));
  const out = { version: RUN_RANDOM_VERSION };
  for (const [key, label] of Object.entries(RUN_STREAMS)) out[key] = root.fork(label);
  return out;
}

/** Snapshot of every stream's position (for replay headers and checkpoints). */
export function runRandomState(streams) {
  const out = { version: streams.version };
  for (const key of Object.keys(RUN_STREAMS)) out[key] = streams[key].state >>> 0;
  return out;
}/**
 * OWNER: core-logic engineer. NO Phaser imports. Must degrade gracefully when localStorage / indexedDB are
 * unavailable (Jest jsdom has no indexedDB; private windows may throw): fall back to in-memory, never throw.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Persistence (design doc section 8): localStorage `settings`, IndexedDB `runs`, versioned JSON, unknown keys ignored.
 *
 * Design notes:
 *  - `this.runs` is the in-memory mirror and is always the source of truth for reads; IndexedDB is write-through
 *    persistence. A failed write retains the session row but never marks it committed; retry is explicit.
 *  - Everything read from storage or a sharecode is sanitised (known keys only, types checked, numbers clamped),
 *    so older/newer versions or hand-edited data can never break the game.
 */
import { STORAGE } from '../constants.js';
import { defaultSongSelection, sanitizeSongSelection } from './music/MusicPlaylist.js';
import { xxHash32 } from './Rng.js';
import { DailyPatch } from './DailyPatch.js';
import { activeUpgradeRanks } from './PermanentUpgrades.js';
import { DEFAULT_CONTROL_LAYOUT, normalizeControlLayout } from './ControlLayouts.js';
import { isRankable, isModdedOnly, countsForDailyBest,countsForDraftDailyBest, countsForStreak } from './Ranking.js';
import {DRAFT_BUDGET,DRAFT_RULES_VERSION,draftCost,validDraftRanks} from './DailyDraft.js';

/**
 * @typedef {Object} Settings
 * @property {number} version            STORAGE.saveVersion.
 * @property {number} masterVolume       0..1
 * @property {number} musicVolume        0..1
 * @property {number} sfxVolume
 * @property {number} windVolume   0..1
 * @property {boolean} windEnabled  false mutes wind audio but not wind forces.
 * @property {'tricksRight'|'tricksLeft'|'classic'} controlLayout
 * @property {Object<string,boolean>} musicEnabledSongs   Per-song switches. All false = silence.
 * @property {boolean} musicShuffle     Shuffle following tracks without repeats; first launch track remains One More Run.
 * @property {boolean} dynamicOrchestra  OFF: original instrumental stems with full FX; ON: separately rendered replacement instruments.
 * @property {boolean} screenShake       false disables shake (accessibility).
 * @property {boolean} ghostBest         show the Best ghost on its course (issue #56).
 * @property {boolean} ghostLatest       show the Latest ghost on its course (issue #56).
 * @property {'same'|'mixed'} kodiakPacks  Kodiak packs of one type or mixed types (issue #47 playtest switch).
 * @property {'auto'|'on'|'off'} reduceMotion  menu motion (accessibility). 'auto' follows the OS
 *           prefers-reduced-motion query; resolved by ui/Motion.js isReducedMotion().
 * @property {'default'|'colorblind'} palette
 * @property {'auto'|'on'|'off'} touchOverlay  on-screen controls.
 * @property {boolean} touchRotate90     90-degree tilt controls for mobile (design doc section 9).
 * @property {string} lastInitials       last initials typed (prefill), '' if none.
 */

/**
 * @typedef {Object} RunRecord
 * @property {number} version        STORAGE.saveVersion.
 * @property {string} id             == RunStartPayload.runId.
 * @property {string} seed
 * @property {string} dailyRuleId    rule in effect (leaderboard flag).
 * @property {number} startedAt      epoch ms.
 * @property {number} endedAt        epoch ms.
 * @property {number} durationMs     run time excluding pauses.
 * @property {number} score          final integer score.
 * @property {number} distanceM      integer metres.
 * @property {number} trickPoints
 * @property {Object<string,number>} tricks  trick type -> count performed.
 * @property {number} bestCombo      highest multiplier.
 * @property {number} maxAirtimeMs
 * @property {'crash'|'quit'} cause
 * @property {string} ledgerHash     computeLedgerHash(record) (8 hex chars), shown on game-over screen.
 * @property {string} [initials]     3+ chars, uppercase, set only once the player enters them (leaderboard entry).
 */

/** Initials length limits (design doc: 3 chars now, longer later). */
export const INITIALS_MIN = 3;
export const INITIALS_MAX = 12;
/** Sharecode prefix; the payload after it is base64(UTF-8 JSON). */
export const SHARECODE_PREFIX = 'BB1:';
const MAX_IMPORT = 500;
const IDB_TIMEOUT_MS = 2500;

/** @returns {Settings} defaults. */
export function defaultSettings() {
  return {
    version: STORAGE.saveVersion, masterVolume: 0.8, musicVolume: 0.6, sfxVolume: 0.9, windVolume: 1, windEnabled: true, screenShake: true,
    ghostBest: true, ghostLatest: true, kodiakPacks: 'same',
    palette: 'default', controlLayout: DEFAULT_CONTROL_LAYOUT, touchOverlay: 'auto', touchRotate90: false, lastInitials: '',
    musicEnabledSongs: defaultSongSelection(),
    musicShuffle: false,
    dynamicOrchestra: false,
    reduceMotion: 'auto',
    worldDance: true,
    musicVocals: false,
    vocalGain: 1,
    melodyWithVocalsGain: 0.18,
  };
}

const num = (v, def, lo = -Infinity, hi = Infinity) => {
  const n = typeof v === 'number' ? v : NaN;
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : def;
};
const str = (v, def = '') => (typeof v === 'string' ? v : def);

/**
 * Merge arbitrary parsed data over defaults, keeping only known keys with valid types.
 * @param {any} raw
 * @returns {Settings}
 */
export function sanitizeSettings(raw) {
  const d = defaultSettings();
  if (!raw || typeof raw !== 'object') return d;
  return {
    version: STORAGE.saveVersion,
    masterVolume: num(raw.masterVolume, d.masterVolume, 0, 1),
    musicVolume: num(raw.musicVolume, d.musicVolume, 0, 1),
    sfxVolume: num(raw.sfxVolume, d.sfxVolume, 0, 1),
    windVolume: num(raw.windVolume, d.windVolume, 0, 1),
    windEnabled: typeof raw.windEnabled === 'boolean' ? raw.windEnabled : d.windEnabled,
    screenShake: typeof raw.screenShake === 'boolean' ? raw.screenShake : d.screenShake,
    ghostBest: typeof raw.ghostBest === 'boolean' ? raw.ghostBest : d.ghostBest,
    ghostLatest: typeof raw.ghostLatest === 'boolean' ? raw.ghostLatest : d.ghostLatest,
    kodiakPacks: raw.kodiakPacks === 'mixed' ? 'mixed' : d.kodiakPacks,
    palette: raw.palette === 'colorblind' || raw.palette === 'default' ? raw.palette : d.palette,
    controlLayout: normalizeControlLayout(raw.controlLayout),
    touchOverlay: ['auto', 'on', 'off'].includes(raw.touchOverlay) ? raw.touchOverlay : d.touchOverlay,
    touchRotate90: typeof raw.touchRotate90 === 'boolean' ? raw.touchRotate90 : d.touchRotate90,
    lastInitials: str(raw.lastInitials).slice(0, INITIALS_MAX),
    musicEnabledSongs: sanitizeSongSelection(raw.musicEnabledSongs),
    musicShuffle: typeof raw.musicShuffle === 'boolean' ? raw.musicShuffle : d.musicShuffle,
    dynamicOrchestra: typeof raw.dynamicOrchestra === 'boolean' ? raw.dynamicOrchestra : false,
    reduceMotion: ['auto', 'on', 'off'].includes(raw.reduceMotion) ? raw.reduceMotion : d.reduceMotion,
    worldDance: typeof raw.worldDance === 'boolean' ? raw.worldDance : d.worldDance,
    musicVocals: raw.musicVocals === true,
    vocalGain: num(raw.vocalGain, d.vocalGain, 0, 1),
    melodyWithVocalsGain: num(raw.melodyWithVocalsGain, d.melodyWithVocalsGain, 0, 1),
  };
}

/**
 * Normalise initials: strip control chars, trim, uppercase, clamp to INITIALS_MAX.
 * @param {any} v
 * @returns {string} '' if not a string.
 */
/**
 * Parse a seed that may carry a biome-mask suffix, `seed@mask` (W3). Pure.
 *
 * The suffix form exists so a player can replay a specific biome layout from the seed field; a bare
 * seed is mask 0 and behaves exactly as before, so every existing seed string keeps its meaning. A
 * malformed suffix is not an error: the whole string is treated as a seed, because a seed is arbitrary
 * user text and rejecting it would lose the run the player asked for.
 *
 * @param {string} raw
 * @param {Array<{bit:number}>} [biomeDefs] content, to bound the mask to biomes that exist.
 * @returns {{seed:string, biomeMask:number, hadSuffix:boolean}}
 */
export function parseSeedMask(raw, biomeDefs) {
  const str0 = typeof raw === 'string' ? raw.trim() : '';
  const m = /^(.*?)@(\d{1,10})$/.exec(str0);
  if (!m || !m[1]) return { seed: str0, biomeMask: 0, hadSuffix: false };
  let mask = Number(m[2]) >>> 0;
  const defs = Array.isArray(biomeDefs) ? biomeDefs : [];
  if (defs.length) {
    // Only keep bits that correspond to a real biome: a mask naming a non-existent biome would produce
    // sectors with no palette and no chunks.
    let known = 0;
    for (const d of defs) if (d && Number.isFinite(d.bit)) known |= d.bit;
    mask &= known;
  }
  return { seed: m[1], biomeMask: mask, hadSuffix: true };
}

export function normalizeInitials(v) {
  if (typeof v !== 'string') return '';
  // eslint-disable-next-line no-control-regex
  return v.replace(/[\u0000-\u001f\u007f]/g, '').trim().toUpperCase().slice(0, INITIALS_MAX);
}

/**
 * Validate/normalise a run record from untrusted storage. Unknown keys are dropped.
 * @param {any} raw
 * @returns {RunRecord|null} null when it has no usable id.
 */
export function sanitizeRun(raw) {
  if (!raw || typeof raw !== 'object' || typeof raw.id !== 'string' || !raw.id) return null;
  const tricks = {};
  if (raw.tricks && typeof raw.tricks === 'object') {
    for (const k of Object.keys(raw.tricks)) {
      const n = raw.tricks[k];
      if (typeof n === 'number' && Number.isFinite(n) && n >= 0) tricks[k] = n;
    }
  }
  /** @type {RunRecord} */
  const r = {
    version: num(raw.version, STORAGE.saveVersion, 0),
    id: raw.id,
    seed: str(raw.seed),
    dailyRuleId: str(raw.dailyRuleId),
    startedAt: num(raw.startedAt, 0, 0),
    endedAt: num(raw.endedAt, 0, 0),
    durationMs: num(raw.durationMs, 0, 0),
    score: num(raw.score, 0, 0),
    distanceM: num(raw.distanceM, 0, 0),
    trickPoints: num(raw.trickPoints, 0),
    tricks,
    bestCombo: num(raw.bestCombo, 1, 0),
    maxAirtimeMs: num(raw.maxAirtimeMs, 0, 0),
    cause: raw.cause === 'quit' ? 'quit' : 'crash',
    ledgerHash: str(raw.ledgerHash),
  };
  for (const k of ['shards', 'nearMisses', 'bonusPoints']) {
    if (typeof raw[k] === 'number' && Number.isFinite(raw[k]) && raw[k] >= 0) r[k] = raw[k];
  }
  // W3 (mask-scoped stats): the biome mask the run was played on. Absent from the v1 ledger hash (so
  // every pre-decision-6 record keeps its identity) and covered by the v2 hash (decision 6). No
  // saveVersion bump; old records without the field count as mask 0.
  if (typeof raw.biomeMask === 'number' && Number.isFinite(raw.biomeMask) && raw.biomeMask >= 0) {
    r.biomeMask = Math.floor(raw.biomeMask) >>> 0;
  }
  // W4 (modded runs): true when the run used a boost. Like `biomeMask`, absent from the v1 hash and
  // covered by the v2 hash (decision 6: a sharecode can no longer strip it). No saveVersion bump; every
  // pre-W4 run stays clean by omission rather than being retroactively disqualified. The decision to
  // exclude it from a board lives in systems/Ranking.js, not here.
  if (raw.modded === true) r.modded = true;
  // Decision 6 (ledger hash v2). Every field the v2 hash reads must survive this whitelist, or a record
  // hashed in RunScene would fail verification after saveRun or an export/import round trip.
  //  - `hashV`: kept only when it is exactly a known version. Never defaulted: a record without it is a
  //    v1 record and keeps verifying under the v1 function, so it is never re-hashed (crediting is keyed
  //    on ledgerHash, so a re-hash would double-credit).
  //  - `bestFlow`: a result shown on Game Over; stored from now on so the hash can cover it.
  //  - `dailyOfficial`: decision 2, true only for a run started from the DAILY RUN menu item. Stored as a
  //    boolean (false too) because the v2 hash covers it and Ranking.isOfficialDaily reads it.
  //  - `boosts`: the ids of the boosts that actually applied (sorted, de-duplicated); `modded` says
  //    whether any did, `boosts` says which, so the v2 hash covers the applied effects.
  //  - `imported`: LOCAL provenance only (set by importSharecode, never by a sharecode itself). Not in
  //    any hash: it is not gameplay. Imported runs never extend the Daily streak (decision 1).
  if ([LEDGER_HASH_V,UPGRADE_LEDGER_HASH_V,DRAFT_LEDGER_HASH_V].includes(raw.hashV)) r.hashV = raw.hashV;
  if (raw.hashV === UPGRADE_LEDGER_HASH_V || raw.hashV===DRAFT_LEDGER_HASH_V) r.upgradeRanks = activeUpgradeRanks(raw.upgradeRanks);
  if (raw.hashV===DRAFT_LEDGER_HASH_V) {
    r.dailyMode=raw.dailyMode==='draft'?'draft':'invalid';
    r.draftRulesVersion=Number.isSafeInteger(raw.draftRulesVersion)?raw.draftRulesVersion:0;
    r.draftBudget=Number.isSafeInteger(raw.draftBudget)?raw.draftBudget:0;
  }
  if (typeof raw.bestFlow === 'number' && Number.isFinite(raw.bestFlow) && raw.bestFlow >= 0) r.bestFlow = raw.bestFlow;
  if (typeof raw.dailyOfficial === 'boolean') r.dailyOfficial = raw.dailyOfficial;
  if (Array.isArray(raw.boosts)) {
    const ids = [...new Set(raw.boosts.filter((b) => typeof b === 'string' && /^[A-Za-z][A-Za-z0-9]{0,31}$/.test(b)))].sort().slice(0, 8);
    r.boosts = ids;
  }
  if (raw.imported === true) r.imported = true;
  const ini = normalizeInitials(raw.initials);
  if (ini.length >= INITIALS_MIN) r.initials = ini;
  return r;
}

// ---- ledger hash (versioned, decision 6) --------------------------------------------------------------------

/** Clean/boost runs remain on hash v2; permanent-upgrade loadouts require v3. */
export const LEDGER_HASH_V = 2;
export const UPGRADE_LEDGER_HASH_V = 3;
export const DRAFT_LEDGER_HASH_V = 4;

const sortedTricksOf = (r) => {
  const tricks = r.tricks && typeof r.tricks === 'object' ? r.tricks : {};
  const out = {};
  for (const k of Object.keys(tricks).sort()) out[k] = tricks[k];
  return out;
};

/**
 * v1 ledger hash, UNCHANGED since before W3: xxHash32 of canonical JSON of the original stable fields
 * (excludes ledgerHash, initials, biomeMask, modded and every later field). Kept byte-identical so every
 * record written before decision 6 keeps verifying and keeps its crediting key.
 * @param {RunRecord} record
 * @returns {string} 8 lowercase hex chars.
 */
export function computeLedgerHashV1(record) {
  const r = record || {};
  const canon = JSON.stringify([
    r.version, r.id, r.seed, r.dailyRuleId, r.startedAt, r.endedAt, r.durationMs, r.score, r.distanceM,
    r.trickPoints, sortedTricksOf(r), r.bestCombo, r.maxAirtimeMs, r.cause,
  ]);
  return xxHash32(canon).toString(16).padStart(8, '0');
}

/**
 * v2 ledger hash (decision 6): every gameplay-affecting setting and every score/result field. Excludes
 * cosmetics and local bookkeeping: initials, ledgerHash, imported. Absent and default values are
 * canonicalised the same way (absent `modded` == false, absent `biomeMask` == 0, absent counters == 0,
 * absent `boosts` == []) so a sanitised copy hashes like the original.
 *
 * `hashV` itself is the first element: stripping it makes the record a v1 record, whose v1 hash then
 * cannot match, so a version downgrade cannot be used to drop the newly covered fields.
 * @param {RunRecord} record
 * @returns {string} 8 lowercase hex chars.
 */
export function computeLedgerHashV2(record) {
  const r = record || {};
  const n = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);
  const boosts = Array.isArray(r.boosts) ? [...new Set(r.boosts.filter((b) => typeof b === 'string'))].sort() : [];
  // Canonicalisation only, not a ranking decision: the flag is hashed as a strict boolean so an absent
  // field and `false` hash alike. Whether a modded run may RANK is still decided only in Ranking.js.
  const { modded, dailyOfficial } = r;
  const canon = JSON.stringify([
    'v2', r.version, r.id, r.seed, r.dailyRuleId, (Number(r.biomeMask) >>> 0) || 0, modded === true, boosts,
    dailyOfficial === true, r.startedAt, r.endedAt, r.durationMs, r.score, r.distanceM, r.trickPoints,
    sortedTricksOf(r), r.bestCombo, n(r.bestFlow), r.maxAirtimeMs, r.cause, n(r.shards), n(r.nearMisses),
    n(r.bonusPoints),
  ]);
  return xxHash32(canon).toString(16).padStart(8, '0');
}

/**
 * Version 3 snapshots permanent purchased ranks at RUN START.
 * The digest of the v2 fields commits the established score and session facts;
 * the ordered rank pairs commit every gameplay-affecting permanent upgrade.
 * No hypothetical old user migration is required: only upgraded runs use v3.
 */
export function computeLedgerHashV3(record) {
  const r = record || {};
  const ranks = activeUpgradeRanks(r.upgradeRanks);
  const applied = Object.keys(ranks).length > 0;
  const pairs = Object.keys(ranks).map(id => [id, ranks[id]]);
  return xxHash32(JSON.stringify(['v3', computeLedgerHashV2(r), applied, pairs])).toString(16).padStart(8, '0');
}

/** v4 binds the separate OFFICIAL DAILY DRAFT competitive rules. The
 * parent v3 digest already commits active rank snapshots, mods and scoring;
 * this outer digest additionally commits Draft identity and fixed rule version.
 * Old clean/upgrade records retain their original bytes and hash semantics.
 */
export function computeLedgerHashV4(record){
  const r=record||{};
  return xxHash32(JSON.stringify(['v4',computeLedgerHashV3(r),
    r.dailyMode=== 'draft'?'draft':'invalid',r.draftRulesVersion,r.draftBudget]))
    .toString(16).padStart(8,'0');
}

/**
 * Whether a record's ledgerHash matches its contents under ITS version (v3 for permanent-upgrade snapshots, v2 otherwise when versioned).
 * An empty or missing hash never verifies (audit F2: it used to skip verification). Never throws.
 * @param {RunRecord} record
 * @returns {boolean}
 */
export function verifyLedgerHash(record) {
  try {
    if (!record || typeof record !== 'object' || Array.isArray(record)) return false;
    const h = typeof record.ledgerHash === 'string' ? record.ledgerHash : '';
    if (!h) return false;
    return h === SaveStore.computeLedgerHash(record);
  } catch (e) {
    return false;
  }
}

// ---- base64 (UTF-8 safe, no reliance on btoa/atob/Buffer) -------------------------------------------------------

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function toUtf8(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00);
        i++;
      }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function fromUtf8(b) {
  let s = '';
  for (let i = 0; i < b.length; ) {
    const c = b[i++];
    let cp;
    if (c < 0x80) cp = c;
    else if (c >= 0xc0 && c < 0xe0) cp = ((c & 31) << 6) | (b[i++] & 63);
    else if (c >= 0xe0 && c < 0xf0) { cp = ((c & 15) << 12) | ((b[i] & 63) << 6) | (b[i + 1] & 63); i += 2; }
    else { cp = ((c & 7) << 18) | ((b[i] & 63) << 12) | ((b[i + 1] & 63) << 6) | (b[i + 2] & 63); i += 3; }
    s += String.fromCodePoint(cp);
  }
  return s;
}

/**
 * @param {string} text
 * @returns {string} base64 of the UTF-8 bytes.
 */
export function base64Encode(text) {
  const b = toUtf8(text);
  let out = '';
  for (let i = 0; i < b.length; i += 3) {
    const n = (b[i] << 16) | ((b[i + 1] || 0) << 8) | (b[i + 2] || 0);
    out += B64[(n >> 18) & 63] + B64[(n >> 12) & 63];
    out += i + 1 < b.length ? B64[(n >> 6) & 63] : '=';
    out += i + 2 < b.length ? B64[n & 63] : '=';
  }
  return out;
}

/**
 * @param {string} b64
 * @returns {string} decoded text.
 * @throws {Error} on invalid characters.
 */
export function base64Decode(b64) {
  const clean = b64.replace(/\s+/g, '').replace(/=+$/, '');
  const bytes = [];
  let acc = 0;
  let bits = 0;
  for (let i = 0; i < clean.length; i++) {
    const v = B64.indexOf(clean[i]);
    if (v < 0) throw new Error('bad base64');
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes.push((acc >> bits) & 255);
    }
  }
  return fromUtf8(bytes);
}

// ---- storage access (all guarded) ------------------------------------------------------------------------------

function getLocalStorage() {
  try {
    const ls = globalThis.localStorage;
    if (!ls) return null;
    const probe = '__bb_probe__';
    ls.setItem(probe, '1');
    ls.removeItem(probe);
    return ls;
  } catch (e) {
    return null;
  }
}

const reqToPromise = (req) =>
  new Promise((resolve, reject) => {
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error || new Error('idb request failed'));
  });

const txDone = (tx) =>
  new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error || new Error('idb tx failed'));
    tx.onabort = () => reject(tx.error || new Error('idb tx aborted'));
  });

/**
 * A leaderboard row: a copy of the record without the LOCAL `imported` marker (provenance on this device,
 * not part of the run), so a board reads the same on the device that set it and on the one that imported it.
 * @param {RunRecord} r @returns {RunRecord}
 */
function boardRow(r) {
  const { imported, ...rest } = r; // eslint-disable-line no-unused-vars
  return { ...rest, tricks: { ...r.tricks } };
}

/** @param {Date|number} v @returns {Date} valid Date (invalid input falls back to now). */
function toDate(v) {
  const d = v instanceof Date ? v : new Date(typeof v === 'number' ? v : NaN);
  return Number.isNaN(d.getTime()) ? new Date() : d;
}

export class SaveStore {
  constructor() {
    /** @type {RunRecord[]} in-memory mirror / fallback, insertion order. */
    this.runs = [];
    /** @type {'idb'|'memory'} */
    this.backend = 'memory';
    this._db = null;
    this._memSettings = null;
    this._runPersistence = new Map();
    this._runWrites = new Map();
    this._initPromise = null;
  }

  /**
   * Open IndexedDB (create `runs` store) and load runs. Must be awaited once at boot (PreloadScene via createServices).
   * Never rejects: on any failure the store keeps working in memory.
   * @returns {Promise<void>}
   */
  async init() {
    if (this._db) return;
    if (!this._initPromise) {
      this._initPromise = this._open().finally(() => { this._initPromise = null; });
    }
    await this._initPromise;
  }

  async _open() {
    try {
      const idb = globalThis.indexedDB;
      if (!idb) return;
      const db = await new Promise((resolve, reject) => {
        let settled = false;
        const timer = setTimeout(() => {
          if (!settled) { settled = true; reject(new Error('idb open timeout')); }
        }, IDB_TIMEOUT_MS);
        const done = (fn, v) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          fn(v);
        };
        let req;
        try {
          req = idb.open(STORAGE.dbName, STORAGE.saveVersion);
        } catch (e) {
          done(reject, e);
          return;
        }
        req.onupgradeneeded = () => {
          const d = req.result;
          if (!d.objectStoreNames.contains(STORAGE.runsStore)) d.createObjectStore(STORAGE.runsStore, { keyPath: 'id' });
        };
        req.onsuccess = () => {
          if (settled) {
            try { req.result.close(); } catch (_) { /* abandoned open */ }
            return;
          }
          done(resolve, req.result);
        };
        req.onerror = () => done(reject, req.error || new Error('idb open failed'));
        req.onblocked = () => done(reject, new Error('idb blocked'));
      });
      const tx = db.transaction(STORAGE.runsStore, 'readonly');
      const all = await reqToPromise(tx.objectStore(STORAGE.runsStore).getAll());
      this._db = db;
      this.backend = 'idb';
      for (const raw of all || []) {
        const rec = sanitizeRun(raw);
        if (!rec) continue;
        const existing = this.runs.find((r) => r.id === rec.id);
        if (!existing) {
          this.runs.push(rec);
          this._runPersistence.set(rec.id, 'committed');
        } else if (!this._runWrites.has(rec.id) && JSON.stringify(existing) === JSON.stringify(rec)) {
          this._runPersistence.set(rec.id, 'committed');
        }
      }
    } catch (e) {
      this._db = null;
      this.backend = 'memory';
    }
  }

  /** @returns {Settings} settings from localStorage merged over defaults (sync). Never throws. */
  loadSettings() {
    try {
      const ls = getLocalStorage();
      const raw = ls ? ls.getItem(STORAGE.settingsKey) : this._memSettings;
      if (!raw) return defaultSettings();
      return sanitizeSettings(JSON.parse(raw));
    } catch (e) {
      return defaultSettings();
    }
  }

  /**
   * @param {Settings} settings
   * @returns {void} never throws.
   */
  saveSettings(settings) {
    const json = JSON.stringify(sanitizeSettings(settings));
    this._memSettings = json;
    try {
      const ls = getLocalStorage();
      if (ls) ls.setItem(STORAGE.settingsKey, json);
    } catch (e) {
      // quota / private mode: memory copy above keeps this session consistent.
    }
  }

  /**
   * Store a finished run. Committed duplicate IDs are idempotent; an uncommitted
   * duplicate retries the original session record, never substitutes new contents.
   * @param {RunRecord} record
   * @returns {Promise<'committed'|'session-only'|'invalid'>}
   */
  async saveRun(record) {
    const rec = sanitizeRun(record);
    if (!rec) return 'invalid';
    const existing = this.runs.find((r) => r.id === rec.id);
    if (existing) {
      if (this._runWrites.has(rec.id)) return this._runWrites.get(rec.id);
      if (this.getRunPersistence(rec.id) === 'committed') return 'committed';
      return this._persist(existing, true);
    }
    // A run saved here was played on this device: the `imported` marker is only ever set by import.
    delete rec.imported;
    this.runs.push(rec);
    return this._persist(rec);
  }

  /**
   * Attach initials to a stored run, making it a leaderboard entry. Initials: trimmed, uppercased, 3+ chars
   * (min 3, max 12). Throws RangeError for < 3 chars. Unknown run ids are ignored.
   * @param {string} runId
   * @param {string} initials
   * @returns {Promise<'committed'|'session-only'|undefined>}
   */
  async setInitials(runId, initials) {
    const ini = normalizeInitials(initials);
    if (ini.length < INITIALS_MIN) throw new RangeError(`initials must be at least ${INITIALS_MIN} characters`);
    const rec = this.runs.find((r) => r.id === runId);
    if (!rec) return;
    rec.initials = ini;
    return this._persist(rec, true);
  }

  /**
   * Leaderboard = runs that have initials, sorted by score desc (ties: older first).
   * @param {number} [limit=10]
   * @returns {Promise<RunRecord[]>}
   */
  async getLeaderboard(limit = 10, opts = {}) {
    return this._board(opts).slice(0, Math.max(0, limit)).map(boardRow);
  }

  /** Separate daily Draft leaderboard. Same date/seed/biome rule for every
   * pilot, same fixed Draft budget and rules version; never mixed with clean
   * or ordinary purchased-upgrade MODDED scores. A local on-device board.
   */
  async getDailyDraftLeaderboard(limit=10,when=new Date()){
    const info=DailyPatch.getDailyInfo(toDate(when));
    const matches=this.runs.map((r,i)=>[r,i]).filter(([r])=>r.initials&&
      r.seed===info.seed&&countsForDraftDailyBest(r));
    matches.sort((a,b)=>b[0].score-a[0].score||a[0].endedAt-b[0].endedAt||a[1]-b[1]);
    return matches.slice(0,Math.max(0,limit)).map(([r])=>boardRow(r));
  }

  async qualifiesForDailyDraftTop10(score,when=new Date()){
    const rows=await this.getDailyDraftLeaderboard(10,when);
    return Number.isFinite(score)&&score>0&&
      (rows.length<10||score>rows[rows.length-1].score);
  }

  /**
   * The MODDED board: boosted runs only. Spec W4 gives them "their own leaderboard tab" rather than
   * simply hiding them, so a boosted run's score is still visible to the player who earned it.
   * @param {number} [limit=10]
   * @returns {Promise<RunRecord[]>}
   */
  async getModdedLeaderboard(limit = 10, opts = {}) {
    const idx = this.runs.map((r, i) => [r, i])
      .filter(([r]) => r.initials && isModdedOnly(r, opts));
    idx.sort((a, b) => b[0].score - a[0].score || a[0].endedAt - b[0].endedAt || a[1] - b[1]);
    return idx.slice(0, Math.max(0, limit)).map(([r]) => boardRow(r));
  }

  /**
   * Whether `score` would place on the MODDED top 10.
   *
   * Separate from qualifiesForTop10 because that method's `opts` doubles as BOTH the candidate's ranking
   * permission and the board filter; a boosted candidate cannot be expressed there without also making the
   * boosted runs already on the board rankable. The modded board is defined by isModdedOnly, so this asks
   * that same helper rather than testing the flag.
   *
   * @param {number} score
   * @returns {Promise<boolean>}
   */
  async qualifiesForModdedTop10(score) {
    const board = this.runs.filter((r) => r.initials && isModdedOnly(r))
      .sort((a, b) => b.score - a.score || a.endedAt - b.endedAt);
    if (board.length < 10) return true;
    return score > board[9].score;
  }

  /**
   * @param {number} score
   * @returns {Promise<boolean>} true if `score` would place in the top 10 (board not full, or beats 10th).
   */
  async qualifiesForTop10(score, opts = {}) {
    // `opts` carries the candidate's `modded` flag, so it IS the record to rank: the helper decides, and
    // this method never looks at the flag itself. Whether a boosted run may rank is the constant's
    // business; duplicating that test here is precisely the scatter the gate forbids.
    if (!isRankable(opts, opts)) return false;
    const board = this._board(opts);
    if (board.length < 10) return true;
    return score > board[9].score;
  }

  /**
   * @param {number} [limit=20]
   * @returns {Promise<RunRecord[]>} most recent runs first.
   */
  async getRecentRuns(limit = 20) {
    const idx = this.runs.map((r, i) => [r, i]);
    idx.sort((a, b) => b[0].endedAt - a[0].endedAt || b[1] - a[1]);
    return idx.slice(0, Math.max(0, limit)).map(([r]) => ({ ...r, tricks: { ...r.tricks } }));
  }

  /**
   * Short non-cryptographic fingerprint: v3 includes the active permanent-upgrade snapshot;
   * v2 hashes existing gameplay/score fields; unversioned records use v1.
   * Excludes local initials and ledgerHash in every version.
   * @param {RunRecord} record
   * @returns {string} 8 lowercase hex chars.
   */
  static computeLedgerHash(record) {
    const r = record || {};
    return r.hashV === DRAFT_LEDGER_HASH_V ? computeLedgerHashV4(r)
      : r.hashV === UPGRADE_LEDGER_HASH_V ? computeLedgerHashV3(r)
      : r.hashV === LEDGER_HASH_V ? computeLedgerHashV2(r) : computeLedgerHashV1(r);
  }

  /**
   * Export leaderboard (+ version) as a copy/paste sharecode: `BB1:` + base64 of UTF-8 JSON
   * `{app, v, runs:[RunRecord...]}`. Contains every run with initials (not only the top 10).
   * @returns {Promise<string>}
   */
  async exportSharecode() {
    // The local `imported` marker does not travel: the receiving store sets its own on import.
    const runs = this._board({ ranked: true }).map(boardRow);
    return SHARECODE_PREFIX + base64Encode(JSON.stringify({ app: 'bitstream-bluffs', v: STORAGE.saveVersion, runs }));
  }

  /**
   * Merge a sharecode into the leaderboard (dedupe by run id, validate/ignore unknown keys). Accepts `BB1:`+base64,
   * bare base64, or raw JSON. Records whose ledgerHash does not match their contents are skipped.
   * @param {string} code
   * @returns {Promise<{imported:number, skipped:number}>} never throws on bad input; returns {0, n}.
   */
  async importSharecode(code) {
    let list;
    try {
      let text = String(code == null ? '' : code).trim();
      if (text.startsWith(SHARECODE_PREFIX)) text = text.slice(SHARECODE_PREFIX.length);
      if (!text.startsWith('{') && !text.startsWith('[')) text = base64Decode(text);
      const parsed = JSON.parse(text);
      list = Array.isArray(parsed) ? parsed : parsed && Array.isArray(parsed.runs) ? parsed.runs : null;
    } catch (e) {
      return { imported: 0, skipped: 0 };
    }
    if (!list) return { imported: 0, skipped: 0 };
    let imported = 0;
    let skipped = 0;
    for (const raw of list.slice(0, MAX_IMPORT)) {
      const rec = sanitizeRun(raw);
      // Verified per version, and an empty hash is rejected (audit F2: it used to skip verification).
      const ok =
        rec &&
        rec.initials &&
        verifyLedgerHash(rec) &&
        !this.runs.some((r) => r.id === rec.id);
      if (!ok) {
        skipped++;
        continue;
      }
      // Local provenance, forced whatever the sharecode said: imported runs never extend the streak.
      rec.imported = true;
      this.runs.push(rec);
      imported++;
      await this._persist(rec);
    }
    skipped += Math.max(0, list.length - MAX_IMPORT);
    return { imported, skipped };
  }

  // ---- read-only chase queries (sync, in-memory mirror; no I/O, safe to call from create()) ------------------------

  /**
   * Best score / best distance / attempt count among stored runs on `seed`. Synchronous O(n) scan of the in-memory
   * mirror (a few thousand runs is well under a millisecond). Counts every stored run, crash or quit.
   * Pass `excludeRunId` (the run that just finished) to compare against the PREVIOUS best:
   * NEW SEED BEST when `!prev || run.score > prev.bestScore`. Best score and best distance are independent maxima.
   * @param {string} seed
   * @param {{excludeRunId?: string}} [opts]
   * @returns {{seed:string, attempts:number, bestScore:number, bestDistanceM:number}|null} null when no runs match.
   */
  getSeedStats(seed, opts = {}) {
    if (typeof seed !== 'string' || !seed) return null;
    const ex = opts && typeof opts.excludeRunId === 'string' ? opts.excludeRunId : null;
    // D6: seed-best compares only within the same biome mask, because two masks are different terrain.
    // `biomeMask` is opt-in: when the caller does not pass it, every run on the seed is compared, which
    // is the pre-W3 behaviour this method had and what the legacy tests and leaderboard still expect.
    const wantMask = opts && Number.isFinite(opts.biomeMask) ? opts.biomeMask >>> 0 : null;
    let attempts = 0;
    let bestScore = 0;
    let bestDistanceM = 0;
    for (const r of this.runs) {
      if (r.seed !== seed || (ex !== null && r.id === ex)) continue;
      if (!isRankable(r, opts)) continue;
      // Old records predate the field and are mask 0 by definition (they were played before biomes).
      if (wantMask !== null && ((r.biomeMask >>> 0) || 0) !== wantMask) continue;
      attempts++;
      if (r.score > bestScore) bestScore = r.score;
      if (r.distanceM > bestDistanceM) bestDistanceM = r.distanceM;
    }
    return attempts ? { seed, attempts, bestScore, bestDistanceM } : null;
  }

  /**
   * Stats for the OFFICIAL Daily of a UTC day (decisions 1/2): only runs started from the DAILY RUN menu
   * item (Ranking.countsForDailyBest), on that date's seed AND that date's mask. A typed `daily-*` seed is
   * a practice run: it compares only as an ordinary seed (getSeedStats within its mask), never here.
   * Same return shape and `excludeRunId` option as getSeedStats.
   * @param {Date|number} [when=new Date()] instant inside the UTC day (Date or epoch ms).
   * @param {{excludeRunId?: string}} [opts]
   * @returns {{seed:string, dateKey:string, attempts:number, bestScore:number, bestDistanceM:number}|null}
   */
  getDailyStats(when = new Date(), opts = {}) {
    const info = DailyPatch.infoForDateKey(DailyPatch.getDailyInfo(toDate(when)).dateKey);
    if (!info) return null;
    const ex = opts && typeof opts.excludeRunId === 'string' ? opts.excludeRunId : null;
    let attempts = 0;
    let bestScore = 0;
    let bestDistanceM = 0;
    for (const r of this.runs) {
      if (r.seed !== info.seed || (ex !== null && r.id === ex)) continue;
      // Official runs are on the date's mask by construction; the explicit mask (and rule) filter is
      // inside Ranking.isOfficialDaily, so it is one tested check rather than two copies (decision 1).
      if (!(opts.mode==='draft'?countsForDraftDailyBest(r, opts):countsForDailyBest(r, opts))) continue;
      attempts++;
      if (r.score > bestScore) bestScore = r.score;
      if (r.distanceM > bestDistanceM) bestDistanceM = r.distanceM;
    }
    return attempts ? { seed: info.seed, dateKey: info.dateKey, attempts, bestScore, bestDistanceM } : null;
  }

  /**
   * Daily streak: consecutive UTC days with at least one OFFICIAL, LOCAL Daily run (Ranking.countsForStreak:
   * started from the DAILY RUN item, clean, not imported; decisions 1/2), ending today or
   * yesterday (ending yesterday = still live, today's run would extend it; an older last day = 0).
   * Day membership comes from the date inside each run's SEED (`daily-YYYY-MM-DD`), not from timestamps: it is
   * immune to clock skew, zero/missing timestamps, and midnight-straddling runs, and it is exactly the day whose
   * rule/seed the player chose. Future-dated seeds are ignored. Counts crash and quit runs.
   * @param {Date|number} [now=new Date()] "now" (Date or epoch ms).
   * @returns {{streak:number, playedToday:boolean, todayKey:string, lastPlayedKey:string|null}}
   *   lastPlayedKey = most recent daily date key played that is not in the future (null if none).
   */
  getDailyStreak(now = new Date(), opts = {}) {
    const nowD = toDate(now);
    const todayKey = nowD.toISOString().slice(0, 10);
    const days = new Set();
    for (const r of this.runs) {
      // W4: a boosted run does not hold a daily streak. Scanned here rather than through _board()
      // because the streak is about DAYS played, not placed runs, so it has its own loop - which is
      // exactly why this surface needed its own route through the one helper.
      // Decisions 1/2: a typed daily seed (practice) or an imported run never holds a day.
      if (!countsForStreak(r, opts)) continue;
      const k = DailyPatch.dateKeyFromSeed(r.seed);
      if (k && k <= todayKey) days.add(k);
    }
    const playedToday = days.has(todayKey);
    const DAY = 86400000;
    const keyAt = (offset) => new Date(Date.parse(`${todayKey}T00:00:00.000Z`) - offset * DAY).toISOString().slice(0, 10);
    let start = playedToday ? 0 : days.has(keyAt(1)) ? 1 : -1;
    let streak = 0;
    if (start >= 0) {
      while (days.has(keyAt(start + streak))) streak++;
    }
    let lastPlayedKey = null;
    for (const k of days) if (lastPlayedKey === null || k > lastPlayedKey) lastPlayedKey = k;
    return { streak, playedToday, todayKey, lastPlayedKey };
  }

  // ---- internals ----------------------------------------------------------------------------------------------

  /** @returns {RunRecord[]} sorted initialed runs (live objects; callers copy). */
  _board(opts) {
    const idx = this.runs.map((r, i) => [r, i])
      .filter(([r]) => r.initials && isRankable(r, opts));
    idx.sort((a, b) => b[0].score - a[0].score || a[0].endedAt - b[0].endedAt || a[1] - b[1]);
    return idx.map(([r]) => r);
  }

  /** Status of the latest in-memory revision; never part of a ledger hash. */
  getRunPersistence(id) {
    return this._runPersistence.get(id) || 'unknown';
  }

  /** Await the latest write, including an initials update queued during an earlier save. */
  async whenRunSettled(id) {
    while (this._runWrites.has(id)) await this._runWrites.get(id);
    return this.getRunPersistence(id);
  }

  _persist(rec, retry = false) {
    const id = rec.id;
    const snapshot = { ...rec, tricks: { ...rec.tricks } };
    const previous = this._runWrites.get(id) || Promise.resolve();
    this._runPersistence.set(id, 'pending');
    const write = previous.then(async () => {
      if (this._initPromise) await this._initPromise;
      else if (retry && !this._db) await this.init();
      const db = this._db;
      if (!db) return 'session-only';
      try {
        const tx = db.transaction(STORAGE.runsStore, 'readwrite');
        const done = txDone(tx);
        // Attach handlers before initiating the request. Abort and drain if
        // put throws synchronously; request success alone is not a commit.
        try {
          tx.objectStore(STORAGE.runsStore).put(snapshot);
        } catch (error) {
          done.catch(() => {});
          try { tx.abort(); } catch (_) { /* transaction already inactive */ }
          throw error;
        }
        await done;
        return 'committed';
      } catch (error) {
        if (this._db === db) {
          this._db = null;
          this.backend = 'memory';
          try { db.close?.(); } catch (_) { /* preserve memory fallback */ }
        }
        return 'session-only';
      }
    }).then(status => {
      if (this._runWrites.get(id) === write) {
        this._runWrites.delete(id);
        this._runPersistence.set(id, status);
      }
      return status;
    });
    this._runWrites.set(id, write);
    return write;
  }
}/**
 * OWNER: core-logic engineer. NO Phaser imports. Never emits events (RunScene does, from return values).
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Scoring rules: design doc section 6.1 + constants SCORING.
 *
 *   distance     +1 pt per whole metre (monotonic furthest distance).
 *   trick value  base(type) x rotationFactor(count) x airtimeFactor(airtimeMs)
 *                rotationFactor(n) = 2^n - 1   (1, 3, 7, 15 ... "harder = exponentially higher", pillar 4)
 *                airtimeFactor(t)  = 1 + min(t, 2500) / 2500   (1.0 .. 2.0)
 *                A TrickEvent reports the CUMULATIVE count of rotations so far (a double flip arrives as count 1
 *                and then count 2), so addTrick() pays only the increase over what that trick type was already
 *                worth in this combo (never double pays).
 *   combo        x1, +0.25 per UNIQUE flip / helicopter type (SCORING.comboStepTypes; air brake and parachute keep
 *                their points but do not step) before landing; applies to all pending trick points when the landing
 *                banks them; resets on landing.
 *   flow         run-level multiplier x1.0..x3.0 that survives landings. A perfect (+0.25) / good (+0.15) landing after
 *                >= 1 combo-step trick (flip / helicopter; air brake or parachute alone do not count) raises it. ANY
 *                perfect / good landing refreshes the timeout (SCORING.flowTimeoutMs, 9 s of run time fed through
 *                tick()). Sloppy after tricks halves the bonus above 1.0; a shield-absorbed hit halves it
 *                (onShieldHit); the timeout halves it and restarts the timer (cleared, i.e. lost, once the bonus is
 *                below SCORING.flowClearBelow); crash / Shift reset clear it. It multiplies banked trick points (on top
 *                of combo) using the value AFTER this landing's gain. Distance and flat bonuses are never multiplied.
 *   landing      perfect = +20 flat (not multiplied); sloppy/good just bank; crash forfeits the whole pending combo.
 *   reset        Shift: pending combo dropped, SCORING.resetPenaltyPoints deducted (total floored at 0).
 */
import { SCORING } from '../constants.js';
import pmath from './pmath.js';

/**
 * @param {number} count completed rotations (>=1)
 * @returns {number}
 */
export function rotationFactor(count) {
  const n = Math.max(1, Math.min(8, Math.floor(count) || 1));
  return pmath.pow(2, n) - 1;
}

/**
 * @param {number} airtimeMs
 * @returns {number} 1..2
 */
export function airtimeFactor(airtimeMs) {
  const t = Math.max(0, Math.min(2500, Number(airtimeMs) || 0));
  return 1 + t / 2500;
}

/**
 * @typedef {Object} ScoreSnapshot
 * @property {number} total          integer, never negative.
 * @property {number} distancePoints
 * @property {number} trickPoints    banked trick + perfect-landing points.
 * @property {number} distanceM      furthest distance, metres (not rounded).
 * @property {number} multiplier     current combo multiplier.
 * @property {string[]} comboTricks  unique trick types in pending combo.
 * @property {number} pendingPoints  unbanked trick points (before multiplier).
 * @property {number} bestCombo      highest multiplier reached this run.
 * @property {number} [penaltyPoints] total deducted by emergency resets (additive field).
 * @property {number} [bonusPoints]   immediate bonus points (shards, near misses, milestones); included in `total`.
 * @property {number} [shards]        shard bonuses collected.
 * @property {number} [nearMisses]    near-miss bonuses awarded.
 * @property {number} [milestones]    milestone bonuses awarded.
 * @property {{shard:number,nearMiss:number,milestone:number}} [bonusByKind] points per bonus kind.
 * @property {Object<string,number>} [comboCounts] additive: highest count per trick type in the pending combo.
 * @property {number} [flow]            additive: current flow multiplier (1..SCORING.flowMax).
 * @property {number} [flowTimeoutFrac] additive: remaining flow timeout 0..1 (0 when flow is 1).
 * @property {number} [bestFlow]        additive: best flow reached this run.
 */

/**
 * What a flow-affecting call did. RunScene emits EVT.FLOW_CHANGED when `changed && !lost`, EVT.FLOW_LOST when `lost`.
 * @typedef {Object} FlowChange
 * @property {boolean} changed  flow value differs from before.
 * @property {boolean} lost     flow was cleared from a value above 1 (a 'timeout' halving that leaves flow above 1 is NOT lost).
 * @property {number} previous  flow before the call.
 * @property {number} flow      flow after the call.
 * @property {'gain'|'halved'|'crash'|'reset'|'timeout'|'none'} reason  'timeout' with lost=false is a timeout halving.
 * @property {number} timeoutFrac remaining timeout 0..1 after the call.
 * @property {number} best      best flow this run.
 */

const round2 = (v) => Math.round(v * 100) / 100;

/**
 * Bonus for finishing a 500 m sector: milestoneBasePoints x min(sector, milestoneMaxSector) (sector 1 = first 500 m),
 * so it is linear and capped at 1000 points from sector 10 on.
 * @param {number} sector 1-based
 * @returns {number} 0 for sector < 1
 */
export function milestoneBonus(sector) {
  const n = Math.floor(Number(sector) || 0);
  return n >= 1 ? SCORING.milestoneBasePoints * Math.min(n, SCORING.milestoneMaxSector) : 0;
}

const NAME_PARTS = {
  backflip: 'BACKFLIP',
  frontflip: 'FRONTFLIP',
  helicopterCCW: 'HELI',
  helicopterCW: 'HELI',
  corkscrew: 'CORKSCREW',
  airBrake: 'AIR BRAKE',
  parachute: 'PARACHUTE',
};
const SHORT_PARTS = { 'AIR BRAKE': 'BRAKE', PARACHUTE: 'CHUTE' };
const NAME_ORDER = ['BACKFLIP', 'FRONTFLIP', 'HELI', 'CORKSCREW', 'AIR BRAKE', 'PARACHUTE'];
const COUNT_WORDS = ['', '', 'DOUBLE ', 'TRIPLE ', 'QUAD '];

/**
 * Display name for the tricks banked in one jump, e.g. "DOUBLE BACKFLIP + HELI". Pure.
 * Degrades: short part names (BRAKE, CHUTE), then "N-TRICK COMBO" (N = total tricks incl. repeats).
 * @param {Array<string|{type:string,count?:number}>} tricks type strings (repeats add up) or {type,count} objects.
 * @param {number} [maxChars] default SCORING.comboNameMaxChars.
 * @returns {string} uppercase; '' when there are no known tricks.
 */
export function comboName(tricks, maxChars = SCORING.comboNameMaxChars) {
  const counts = {};
  let total = 0;
  for (const t of tricks || []) {
    const type = typeof t === 'string' ? t : t && t.type;
    const n = typeof t === 'string' ? 1 : Math.max(1, Math.floor(t.count) || 1);
    const part = NAME_PARTS[type];
    if (!part) continue;
    counts[part] = (counts[part] || 0) + n;
    total += n;
  }
  const build = (short) =>
    NAME_ORDER.filter((p) => counts[p])
      .map((p) => {
        const n = counts[p];
        const label = short && SHORT_PARTS[p] ? SHORT_PARTS[p] : p;
        return n >= 5 ? `${n}X ${label}` : COUNT_WORDS[n] + label;
      })
      .join(' + ');
  if (!total) return '';
  let name = build(false);
  if (name.length > maxChars) name = build(true);
  if (name.length > maxChars) name = `${total}-TRICK COMBO`;
  return name;
}

export class ScoreManager {
  /** @param {{pxPerMeter?:number}} [options] */
  constructor(options = {}) {
    this.options = options;
    /** @type {Object<string,number>} points already paid this combo, per trick type. */
    this.paid = {};
    this.reset();
  }

  /** Reset everything for a new run. @returns {void} */
  reset() {
    this.distanceM = 0;
    this.trickPoints = 0;
    this.penaltyPoints = 0;
    this.bonusPoints = 0;
    this.bonusCounts = { shard: 0, nearMiss: 0, milestone: 0 };
    this.bonusByKind = { shard: 0, nearMiss: 0, milestone: 0 };
    this.pending = 0;
    this.comboTricks = [];
    this.paid = {};
    this.bestCombo = SCORING.comboStart;
    this.counts = {};
    this.flow = SCORING.flowStart;
    this.flowRemainingMs = 0;
    this.bestFlow = SCORING.flowStart;
    this.lastMilestoneSector = 0;
  }

  /**
   * Report current distance. Monotonic: only increases the stored furthest distance.
   * @param {number} meters
   * @returns {boolean} true if the whole-metre value increased (caller emits DISTANCE_CHANGED / SCORE_CHANGED).
   */
  setDistance(meters) {
    if (!(meters > this.distanceM)) return false;
    const before = Math.floor(this.distanceM);
    this.distanceM = meters;
    return Math.floor(meters) > before;
  }

  /**
   * Register a trick performed mid-air (from TrickTracker). Provisional until landing.
   * @param {{type:string,count:number,rotationDeg:number,airtimeMs:number}} trick TrickEvent from TrickTracker.
   * @returns {{value:number, isNew:boolean, multiplier:number}} value = provisional points ADDED by this event,
   *   before the combo multiplier. isNew = this type raised the multiplier (false for air brake / parachute).
   */
  addTrick(trick) {
    const base = SCORING.trickBase[trick.type] || 0;
    const firstOfType = !this.comboTricks.includes(trick.type);
    if (firstOfType) this.comboTricks.push(trick.type);
    const isNew = firstOfType && SCORING.comboStepTypes.includes(trick.type);
    this.counts[trick.type] = Math.max(this.counts[trick.type] || 0, Math.floor(trick.count) || 1);
    const worth = base * rotationFactor(trick.count) * airtimeFactor(trick.airtimeMs);
    const before = this.paid[trick.type] || 0;
    const value = Math.max(0, Math.round(worth - before));
    this.paid[trick.type] = before + value;
    this.pending += value;
    const multiplier = this.getMultiplier();
    if (multiplier > this.bestCombo) this.bestCombo = multiplier;
    return { value, isNew, multiplier };
  }

  /**
   * Landing: bank pending tricks x multiplier x flow, add perfect bonus, reset combo. A crash landing forfeits everything.
   * @param {{quality:'perfect'|'good'|'sloppy'|'crash'}} landing LandingResult from TrickTracker.
   *   Pass the already graded quality (classifyLanding with the mid-spin penalty applied).
   * @param {{zoneScoreMul?:number}} [opts] additive (W3): bonus multiplier from terrain-mod zones the sled
   *   is standing in at the landing (Crystal Cavern's echo zone). Bounded by the caller; clamped to
   *   >= 1 here so a mod can never reduce a payout, only add to it. Multiplies the banked trick points
   *   only - never the perfect-landing flat bonus or distance points, so the echo cannot inflate the
   *   parts of a score that are meant to be identical everywhere.
   * @returns {{banked:number, bonus:number, multiplierUsed:number, flowUsed:number, flowChange:FlowChange,
   *   comboName:string}} banked = pending x combo x flowUsed; flowUsed is the flow AFTER this landing's gain (so the first
   *   clean trick landing already pays), or the flow carried in when nothing was gained; comboName = display name of
   *   the jump's tricks ('' if none), captured before the combo clears.
   */
  onLanding(landing, opts) {
    const multiplierUsed = this.getMultiplier();
    const name = comboName(this.comboTricks.map((type) => ({ type, count: this.counts[type] })));
    if (landing && landing.quality === 'crash') {
      const flowUsed = this.flow;
      this._clearCombo();
      return { banked: 0, bonus: 0, multiplierUsed, flowUsed, flowChange: this._clearFlow('crash'), comboName: name };
    }
    const hadTricks = this.comboTricks.length > 0;
    const hadStep = this.comboTricks.some((t) => SCORING.comboStepTypes.includes(t));
    const q = landing && landing.quality;
    const clean = q === 'perfect' || q === 'good';
    let flowChange;
    if (clean && hadStep) {
      const step = q === 'perfect' ? SCORING.flowPerfectStep : SCORING.flowGoodStep;
      flowChange = this._setFlow(Math.min(SCORING.flowMax, this.flow + step), 'gain');
    } else if (q === 'sloppy' && hadTricks && this.flow > SCORING.flowStart) {
      // the halving applies after this landing banks (the sloppy jump is still paid at the flow it was flown with)
      flowChange = null;
    } else {
      flowChange = this._flowChange(this.flow, 'none');
    }
    const flowUsed = this.flow;
    const zoneMul = Math.max(1, (opts && Number.isFinite(opts.zoneScoreMul) ? opts.zoneScoreMul : 1));
    const banked = Math.round(this.pending * multiplierUsed * flowUsed * zoneMul);
    const bonus = q === 'perfect' ? SCORING.perfectLandingBonus : 0;
    this.trickPoints += banked + bonus;
    this._clearCombo();
    if (!flowChange) {
      flowChange = this._halveFlow('halved');
    }
    if (clean && this.flow > SCORING.flowStart) {
      this.flowRemainingMs = SCORING.flowTimeoutMs;
      flowChange.timeoutFrac = 1;
    }
    return { banked, bonus, multiplierUsed, flowUsed, flowChange, comboName: name, zoneMul };
  }

  /**
   * Advance the flow timeout. Call every frame with the frame delta (run clock, excludes pause); never wall clock.
   * Each expiry halves the bonus above 1.0 and restarts the timer; when the bonus falls below
   * SCORING.flowClearBelow flow is cleared instead.
   * @param {number} dtMs
   * @returns {FlowChange} reason 'timeout': `lost` false = halved (emit FLOW_CHANGED), `lost` true = cleared (FLOW_LOST).
   */
  tick(dtMs) {
    if (this.flow > SCORING.flowStart) {
      this.flowRemainingMs -= Math.max(0, Number(dtMs) || 0);
      if (this.flowRemainingMs <= 0) {
        const change = this._halveFlow('timeout');
        if (!change.lost) {
          this.flowRemainingMs = SCORING.flowTimeoutMs;
          change.timeoutFrac = 1;
        }
        return change;
      }
    }
    return this._flowChange(this.flow, 'none');
  }

  /**
   * A hit absorbed by Hashed Backup: halve the flow bonus (like a sloppy landing) and keep everything else. The pending
   * combo, its paid baseline and the tracker's counts stay consistent, so tricks finished after a mid-air hazard hit are
   * paid exactly once.
   * @param {boolean} [dropCombo] also discard the pending combo (use when the sled is respawned and the tracker reset).
   * @returns {FlowChange} reason 'halved' (changed false when flow was already 1).
   */
  onShieldHit(dropCombo = false) {
    if (dropCombo) this._clearCombo();
    if (this.flow <= SCORING.flowStart) return this._flowChange(this.flow, 'none');
    return this._halveFlow('halved');
  }

  /**
   * Crash (real or negated by a respawn): discard pending tricks and combo and clear flow.
   * @returns {FlowChange}
   */
  onCrash() {
    this._clearCombo();
    return this._clearFlow('crash');
  }

  /**
   * Pay milestone bonuses for every whole sector (SCORING.milestoneEveryM) newly completed up to distanceM; never pays
   * a sector twice. Reaching 500 m pays sector 1 (100), 1000 m pays sector 2 (200), and so on.
   * @param {number} distanceM furthest distance, metres.
   * @returns {Array<{sector:number, points:number, distanceM:number}>} newly paid sectors (usually empty); the scene
   *   emits EVT.MILESTONE for each.
   */
  checkMilestones(distanceM) {
    const out = [];
    const reached = Math.floor((Number(distanceM) || 0) / SCORING.milestoneEveryM);
    while (this.lastMilestoneSector < reached) {
      const sector = ++this.lastMilestoneSector;
      const points = milestoneBonus(sector);
      this.addBonus(points, 'milestone');
      out.push({ sector, points, distanceM: sector * SCORING.milestoneEveryM });
    }
    return out;
  }

  /** @returns {number} current flow multiplier. */
  getFlow() {
    return this.flow;
  }

  /** @returns {number} remaining flow timeout 0..1 (0 when flow is 1). */
  getFlowTimeoutFraction() {
    if (this.flow <= SCORING.flowStart) return 0;
    return Math.max(0, Math.min(1, this.flowRemainingMs / SCORING.flowTimeoutMs));
  }

  /** @returns {string} display name of the pending combo ('' if empty). */
  getComboName() {
    return comboName(this.comboTricks.map((type) => ({ type, count: this.counts[type] })));
  }

  /**
   * Shift emergency reset: drop pending combo, deduct SCORING.resetPenaltyPoints (floor 0 total).
   *   Also clears flow.
   * @returns {{comboPenalty:number, pointsLost:number, flowChange:FlowChange}} comboPenalty = number of unique
   *   tricks dropped.
   */
  penalizeReset() {
    const comboPenalty = this.comboTricks.length;
    this._clearCombo();
    const flowChange = this._clearFlow('reset');
    const pointsLost = Math.min(SCORING.resetPenaltyPoints, this.getSnapshot().total);
    this.penaltyPoints += pointsLost;
    return { comboPenalty, pointsLost, flowChange };
  }

  /**
   * Immediate bonus (not part of the pending combo, not multiplied, survives crashes and resets).
   * @param {number} points non-negative; rounded, NaN / negatives count as 0.
   * @param {'shard'|'nearMiss'|'milestone'} kind unknown kinds add points but are not counted per kind.
   * @returns {ScoreSnapshot}
   */
  addBonus(points, kind) {
    const pts = Math.max(0, Math.round(Number(points) || 0));
    this.bonusPoints += pts;
    if (kind in this.bonusCounts) {
      this.bonusCounts[kind]++;
      this.bonusByKind[kind] += pts;
    }
    return this.getSnapshot();
  }

  /** @returns {number} current multiplier = 1 + 0.25 * unique flip / helicopter types (SCORING.comboStepTypes). */
  getMultiplier(trickTypes = this.comboTricks) {
    const steps = trickTypes.filter((t) => SCORING.comboStepTypes.includes(t)).length;
    return SCORING.comboStart + SCORING.comboStep * steps;
  }

  /** @returns {number} points from whole metres; allocation-free (per-frame callers). */
  getDistancePoints() {
    return Math.floor(this.distanceM) * SCORING.pointsPerMeter;
  }

  /** @returns {number} running total (same value as getSnapshot().total); allocation-free. */
  getTotal() {
    return Math.max(0, Math.round(this.getDistancePoints() + this.trickPoints + this.bonusPoints - this.penaltyPoints));
  }

  /** @returns {ScoreSnapshot} */
  getSnapshot() {
    return {
      total: this.getTotal(),
      distancePoints: this.getDistancePoints(),
      trickPoints: this.trickPoints,
      distanceM: this.distanceM,
      multiplier: this.getMultiplier(),
      comboTricks: [...this.comboTricks],
      pendingPoints: this.pending,
      bestCombo: this.bestCombo,
      penaltyPoints: this.penaltyPoints,
      bonusPoints: this.bonusPoints,
      shards: this.bonusCounts.shard,
      nearMisses: this.bonusCounts.nearMiss,
      milestones: this.bonusCounts.milestone,
      bonusByKind: { ...this.bonusByKind },
      comboCounts: { ...this.counts },
      flow: this.flow,
      flowTimeoutFrac: this.getFlowTimeoutFraction(),
      bestFlow: this.bestFlow,
    };
  }

  _clearCombo() {
    this.pending = 0;
    this.comboTricks = [];
    this.paid = {};
    this.counts = {};
  }

  _flowChange(previous, reason) {
    return {
      changed: this.flow !== previous,
      lost: false,
      previous,
      flow: this.flow,
      reason,
      timeoutFrac: this.getFlowTimeoutFraction(),
      best: this.bestFlow,
    };
  }

  _setFlow(value, reason) {
    const previous = this.flow;
    this.flow = round2(value);
    if (this.flow > this.bestFlow) this.bestFlow = this.flow;
    const change = this._flowChange(previous, reason);
    if (this.flow <= SCORING.flowStart && previous > SCORING.flowStart) {
      // reaching exactly 1.0 by any path is a loss, not a change
      this.flowRemainingMs = 0;
      change.lost = true;
      change.timeoutFrac = 0;
    }
    return change;
  }

  /** Halve the bonus above 1.0; a bonus left below SCORING.flowClearBelow clears flow to 1.0 (lost) instead. */
  _halveFlow(reason) {
    const bonus = (this.flow - SCORING.flowStart) * SCORING.flowSloppyKeep;
    if (bonus < SCORING.flowClearBelow) return this._clearFlow(reason);
    return this._setFlow(SCORING.flowStart + bonus, reason);
  }

  _clearFlow(reason) {
    const previous = this.flow;
    this.flow = SCORING.flowStart;
    this.flowRemainingMs = 0;
    const change = this._flowChange(previous, previous > SCORING.flowStart ? reason : 'none');
    change.lost = previous > SCORING.flowStart;
    return change;
  }
}/**
 * OWNER: gameplay. NO Phaser imports. Pure.
 *
 * Shard Magnet (the black hole). While active, every shard within the pull radius drifts
 * toward the rider, faster the closer it gets, until the normal pickup radius takes it.
 * Strength never grows with time on screen: it comes from the MAGNET PULL permanent
 * upgrade (unlimited ranks, softcapped in PermanentUpgrades), as `magnetMul`.
 *
 * Placement lives here, not in TerrainGenerator: the generator's chunk output (golden-tested,
 * SPEC §9) must stay bit-identical for every existing seed. RunScene asks magnetSpawn() for
 * at most one extra pickup per chunk, from its own seeded stream.
 */
import { Rng } from './Rng.js';
import pmath from './pmath.js';

/** Never below this share of the def's base chance, however far down the mountain (as for base pickups). */
const MAGNET_FLOOR_FRACTION = 0.4;

/**
 * The Shard Magnet pickup for one generated chunk, or null. Deterministic per seed and chunk
 * index; keeps clear of the chunk's hazards, gaps and other pickups.
 * @param {string} seed
 * @param {{index:number,startX:number,endX:number,hazards?:object[],gaps?:object[],powerups?:object[]}} chunk
 * @param {object} def the shardMagnet power-up def
 * @param {function(number):number} heightAt terrain surface y at world x
 * @param {number} ppm pixels per metre
 * @param {number} [spawnMul] MYRIAD MAGNETS multiplier on the chance (the result is capped at 0.95)
 * @returns {{defId:string,x:number,y:number}|null}
 */
export function magnetSpawn(seed, chunk, def, heightAt, ppm, spawnMul = 1) {
  if (!def || !chunk || !Number.isFinite(chunk.startX) || !Number.isFinite(chunk.endX)) return null;
  const rng = new Rng(String(seed)).fork(`shardMagnet/${chunk.index}`);
  const span = chunk.endX - chunk.startX - 400;
  if (!(span > 0)) return null;
  const x = Math.round(chunk.startX + 240 + rng.range(0, span));
  const lift = (def.radius || 10) + rng.range(26, 58);
  const sp = def.spawn || {};
  const base = Number.isFinite(sp.baseChance) ? sp.baseChance : 0.2;
  const decay = Number.isFinite(sp.distanceDecayM) ? sp.distanceDecayM : 2000;
  const mul = Number.isFinite(spawnMul) && spawnMul >= 1 ? spawnMul : 1;
  const chance = Math.min(0.95, mul * Math.max(base * MAGNET_FLOOR_FRACTION, base / (1 + x / ppm / decay)));
  if (!rng.chance(chance) || x <= 480) return null;
  for (const h of chunk.hazards || []) if (Math.abs(h.x - x) < 90) return null;
  for (const g of chunk.gaps || []) if (x > g.x0 - 80 && x < g.x1 + 40) return null;
  for (const p of chunk.powerups || []) if (Math.abs(p.x - x) < 120) return null;
  const y = heightAt(x);
  return Number.isFinite(y) ? { defId: def.id, x, y: y - lift } : null;
}

/** Shard Magnets start dropping at this Sync Level in ordinary runs (owner, 2026-11-20). */
export const MAGNET_MIN_SYNC_LEVEL = 5;

/**
 * Do magnets drop on this run? From Sync Level 5 in ordinary runs. Always in Daily runs (classic and
 * Draft): an official board must give every pilot the same pickups, whatever their level.
 */
export function magnetsDropFor({ level, daily = false } = {}) {
  return daily === true || (Number.isFinite(level) && level >= MAGNET_MIN_SYNC_LEVEL);
}

/** The hole hovers above and behind the rider (world px from the sled centre): visible, not hidden under the sprite. */
export const MAGNET_HOLE_OFFSET = Object.freeze({ x: -14, y: -34 });

/** World position of the hole for a sled at (x, y). */
export function magnetHolePos(x, y) {
  return { x: x + MAGNET_HOLE_OFFSET.x, y: y + MAGNET_HOLE_OFFSET.y };
}

/** Pull radius (px) and base pull speed (px/s) for an effect def and upgrade multiplier. */
export function magnetStrength(eff = {}, magnetMul = 1) {
  const mul = Number.isFinite(magnetMul) && magnetMul >= 1 ? magnetMul : 1;
  const radius = (Number.isFinite(eff.pullRadiusPx) ? eff.pullRadiusPx : 96) * mul;
  const speed = (Number.isFinite(eff.pullPxS) ? eff.pullPxS : 360) * mul;
  return { radius, speed, mul };
}

/**
 * New position of one shard pulled toward (x, y) for `dtMs`. Speed rises from 1x at the rim
 * to 3x at the centre; a shard never overshoots the rider.
 * @returns {{x:number,y:number}|null} null when the shard is outside the radius
 */
export function pullStep(sx, sy, x, y, radius, speedPxS, dtMs) {
  const dx = x - sx, dy = y - sy;
  const d = pmath.hypot(dx, dy);
  if (!(d <= radius) || d === 0) return null;
  const step = Math.min(d, speedPxS * (1 + 2 * (1 - d / radius)) * (dtMs / 1000));
  return { x: sx + (dx / d) * step, y: sy + (dy / d) * step };
}/**
 * W4.1 (CC Friday / Marvin, 2026-11-13): should the Shard Shop open itself after this run?
 *
 * Marvin's request was "auto-open the shop after any round where the player can afford something".
 * CC's amendment narrowed it: fire only when THIS RUN newly made something affordable, not every round
 * while a stockpile sits there — otherwise a player with 400 shards gets the shop in their face after
 * every run forever, which is the opposite of a helpful popup.
 *
 * Stateless by design. "Before" is derived from the credit rather than stored, because a new profile
 * field would be a saveVersion change, which the campaign forbids:
 *
 *     bankBefore  = bankAfter  - this run's credited shards
 *     levelBefore = levelForXp(xpAfter - this run's credited xp)
 *
 * That is exact, not an estimate: `creditRun` adds `record.shards` to the bank, `applyMissions` adds the
 * mission roll's shards, and the level before the run is fully determined by the XP without this run's
 * award (verified in tests against the real progression table).
 *
 * WHY THIS RE-STATES THE SHOP'S RULES INSTEAD OF CALLING isOwned/purchase:
 * `isOwned` and `purchase` look their item up in the module-level SHOP_ITEMS, so they cannot be pointed at
 * another catalogue. Rather than fake a catalogue and have the popup silently disagree with the panel it
 * opens, the rules are restated here over an explicit item, and `shop-prompt.test.js` proves equivalence
 * against the real `purchase()` across a grid of banks, levels and owned-sets on the SHIPPED catalogue.
 * If the shop's refusals ever change order or meaning, that test fails.
 */
import { SHOP_ITEMS } from './ProfileStore.js';

/** @param {*} n @returns {number} */
const num = (n) => (Number.isFinite(Number(n)) ? Number(n) : 0);
/** @param {*} n @returns {number} */
const nonNeg = (n) => Math.max(0, num(n));

/**
 * Is `item` owned by this state? Same two clauses as the shop: explicitly owned, or a level reward
 * (price 0) whose unlockLevel has been reached.
 * @param {{level:number, owned:Array<string>}} state
 * @param {Object} item
 * @returns {boolean}
 */
function ownedHere(state, item) {
  const owned = Array.isArray(state.owned) ? state.owned : [];
  if (owned.includes(item.id)) return true;
  return num(item.price) === 0 && num(item.unlockLevel || 1) <= state.level;
}

/**
 * Is `item` buyable from this state? Mirrors `purchase()`'s refusals in its order — unknown/absent item,
 * already owned, level too low, not enough shards — plus `price > 0`, because a price-0 item is a level
 * reward and is never something to buy, plus "the shop shows it" (titles are hidden until a title UI
 * exists, SHOP-1). The prompt may therefore say "nothing" where purchase() would still buy a title; it
 * never says "something" where the panel has nothing to offer.
 * @param {{bank:number, level:number, owned:Array<string>}} state
 * @param {Object} item
 * @returns {boolean}
 */
function buyableHere(state, item) {
  if (!item || !item.id) return false;
  // Only what the Shard Shop actually shows can be "affordable". Titles have no UI yet, so ShopLayout drops
  // `slot === 'title'` from the panel; counting them here opened the shop (and lit "SHOP: B") over a
  // 220-shard title the player could not see. Same field as ShopLayout's filter, so the two cannot drift.
  // Remove this line when a title UI ships.
  if (item.slot === 'title') return false;
  const price = num(item.price);
  if (price <= 0) return false;
  if (ownedHere(state, item)) return false;
  if (state.level < num(item.unlockLevel || 1)) return false;
  return state.bank >= price;
}

/**
 * Normalise any caller-supplied state into the three fields the rules read.
 * @param {*} state
 * @returns {{bank:number, level:number, owned:Array<string>}}
 */
function norm(state) {
  const s = state && typeof state === 'object' ? state : {};
  return {
    bank: nonNeg(s.bank),
    level: Math.max(1, Math.floor(num(s.level) || 1)),
    owned: Array.isArray(s.owned) ? s.owned : [],
  };
}

/**
 * Can this state buy at least one catalogue item right now?
 * @param {{bank:number, level:number, owned?:Array<string>}} state
 * @param {Array<Object>} [catalog]
 * @returns {boolean}
 */
export function canAffordAnything(state, catalog = SHOP_ITEMS) {
  const s = norm(state);
  const items = Array.isArray(catalog) ? catalog : [];
  for (const it of items) if (buyableHere(s, it)) return true;
  return false;
}

/**
 * Did this run newly make something affordable?
 *
 * True when at least one item is buyable after the credit and was not buyable before it. "Not before"
 * covers both ways a run can open a purchase: more shards (bank crosses the price) or a level-up (crosses
 * unlockLevel).
 *
 * Cases CC named, all answered here:
 *  - stockpile already covers something, run adds shards but crosses nothing new -> false
 *  - the run crosses a price -> true
 *  - a level-up unlocks something the bank already covers -> true
 *  - broke -> false
 *  - two prices crossed in one run -> true once; the caller opens one panel, never two
 *
 * @param {{bank:number, level:number, owned?:Array<string>}} before
 * @param {{bank:number, level:number, owned?:Array<string>}} after
 * @param {Array<Object>} [catalog]
 * @returns {boolean}
 */
export function newlyAffordable(before, after, catalog = SHOP_ITEMS) {
  if (!after || typeof after !== 'object') return false;
  const a = norm(after);
  const b = before && typeof before === 'object' ? norm(before) : { bank: 0, level: 1, owned: a.owned };
  const items = Array.isArray(catalog) ? catalog : [];
  for (const it of items) {
    if (!buyableHere(a, it)) continue; // nothing to buy now
    if (!buyableHere(b, it)) return true; // ...but there was nothing to buy before
  }
  return false;
}

/**
 * The three fields the decision reads, taken from a live profile.
 *
 * A profile carries more than this; the decision deliberately does not, so a caller cannot accidentally
 * feed it a field it does not use. `owned` comes from `unlocked.cosmetics`, which is where `purchase()`
 * records a buy.
 * @param {*} profile
 * @returns {{bank:number, level:number, owned:Array<string>}}
 */
export function shopState(profile) {
  const p = profile && typeof profile === 'object' ? profile : {};
  const unlocked = p.unlocked && typeof p.unlocked === 'object' ? p.unlocked : {};
  return {
    bank: nonNeg(p.bank),
    level: Math.max(1, Math.floor(num(p.level) || 1)),
    owned: Array.isArray(unlocked.cosmetics) ? unlocked.cosmetics.slice() : [],
  };
}

/**
 * Derive the "before this run" state from the live profile and this run's total credit.
 *
 * @param {{bank:number, xp:number}} afterProfile live profile, already credited
 * @param {{shards?:number, xp?:number}} credit this run's total shards and XP (run + missions)
 * @param {(xp:number)=>number} levelForXp the progression table's own resolver
 * @param {Array<string>} owned cosmetic ids owned now
 * @returns {{bank:number, level:number, owned:Array<string>}}
 */
export function stateBeforeRun(afterProfile, credit, levelForXp, owned) {
  const shards = nonNeg(credit && credit.shards);
  const xp = nonNeg(credit && credit.xp);
  const bankAfter = nonNeg(afterProfile && afterProfile.bank);
  const xpAfter = nonNeg(afterProfile && afterProfile.xp);
  const levelBefore = typeof levelForXp === 'function' ? levelForXp(Math.max(0, xpAfter - xp)) : 1;
  return {
    bank: Math.max(0, bankAfter - shards),
    level: Math.max(1, Math.floor(num(levelBefore) || 1)),
    owned: Array.isArray(owned) ? owned : [],
  };
}/**
 * OWNER: core-logic engineer. NO Phaser imports.
 *
 * Fixed simulation tick (issue #59). Display frames feed real elapsed time into an
 * accumulator; the game advances only in whole ticks of SIM_TICK_MS, so the same input
 * tape produces the same run at 30, 60 or 120 Hz.
 *
 * Candidate tick: 120 Hz (8.333 ms). It divides 30/60/120 Hz frames exactly (4/2/1 ticks,
 * no judder without interpolation), and with the 8 ms Matter cap every tick is two 4.17 ms
 * physics steps: exactly the steps a 120 Hz display already runs on the variable-delta
 * loop. Chosen by Marvin (2026-11-20); play-test pending: see docs/issue-59-fixed-tick.md.
 */

import { deriveHeld } from './PadDerive.js';

export const SIM_TICK_HZ = 120;
/**
 * Recorder-side input capture policy (Replay Contract v1 `info.inputCapture.edgeAssignment`, #152):
 * live input is assigned to ticks by event timestamp window (issue #115). Informational; replays ignore it.
 */
export const INPUT_EDGE_ASSIGNMENT = 'timestamp-window';
export const SIM_TICK_MS = 1000 / SIM_TICK_HZ;
/** Same ceiling as the old 50 ms frame clamp: never more than this many ticks per frame. */
export const SIM_MAX_TICKS_PER_FRAME = Math.ceil(50 / SIM_TICK_MS - 1e-9);
// Float slack so 3 x 33.333.. ms frames are exactly 12 ticks, never 11 then 13.
const EPS = 1e-6;
const EDGE_NAMES = ['hop', 'reset', 'pause', 'airBrake', 'parachute', 'confirm'];
const EDGE_SET = new Set(EDGE_NAMES);

export class SimClock {
  /** @param {number} [tickMs] @param {number} [maxTicks] */
  constructor(tickMs = SIM_TICK_MS, maxTicks = SIM_MAX_TICKS_PER_FRAME) {
    this.tickMs = tickMs;
    this.maxTicks = maxTicks;
    /** Real ms owed to the simulation, always < tickMs between frames. */
    this.accMs = 0;
    /** Integer count of ticks simulated this run: the replay time axis. */
    this.tick = 0;
    /** Real ms discarded because a frame needed more than maxTicks (slow device). */
    this.droppedMs = 0;
    this._edges = null;
    /** Timeline carried over 0-tick frames (issue #115). */
    this._timeline = null;
  }

  /**
   * Ticks to run for a display frame of `frameMs` real ms. Backlog beyond the cap is
   * dropped, not replayed later: a stalled tab never fast-forwards the run.
   * @param {number} frameMs
   * @returns {number}
   */
  advance(frameMs) {
    this.accMs += Number.isFinite(frameMs) && frameMs > 0 ? frameMs : 0;
    let n = Math.floor((this.accMs + EPS) / this.tickMs);
    if (n > this.maxTicks) {
      this.droppedMs += (n - this.maxTicks) * this.tickMs;
      n = this.maxTicks;
    }
    this.accMs = Math.max(0, this.accMs - n * this.tickMs);
    if (this.accMs + EPS >= this.tickMs) { this.droppedMs += this.accMs; this.accMs = 0; }
    return n;
  }

  /**
   * Pads for this frame's ticks. Called right after advance(), with this frame's polled pad.
   *
   * Without `opts.timeline` (tape replay tools, probes, legacy callers): held controls come from the
   * latest poll on every tick; one-shot `pressed` edges reach exactly one tick, the first one; if the
   * frame runs no tick they wait for the next frame that does.
   *
   * With `opts.timeline` and `opts.frameTime` (issue #115, live play): every timestamped input change
   * is given to the tick whose real-time window contains it. This frame's ticks cover the windows
   * ending at `frameTime - accMs - (ticks-1-i) * tickMs`. A change is clamped into THIS frame's ticks:
   * older than the first window (stall, dropped backlog, untimed gamepad/touch/blur) -> first tick, as
   * before; newer than the last window (the sub-tick remainder) -> last tick, so nothing is ever shown
   * a frame later than before and no tick that already ran is rewritten. Changes keep arrival order.
   * A button that went down inside a tick's window is held on that tick even if it was released
   * before the window closed (a tap is at least one tick). Edges are rebuilt from the rises.
   * A 0-tick frame carries its timeline forward intact (held taps included).
   *
   * @param {object} pad normalized pad polled this frame (its `pressed` edges already consumed from the router)
   * @param {number} ticks result of advance()
   * @param {{frameTime?:number, timeline?:{base:Object<string,boolean>,events:{t:number|null,name:string,down:boolean}[],analog:number}|null,
   *   normalize?:(raw:object)=>object}} [opts] frameTime = rAF time of this frame on the event.timeStamp clock;
   *   timeline = InputRouter.poll().timeline; normalize = raw VirtualPadState -> tick pad (RunScene.normalizePad)
   * @returns {object[]} one pad per tick
   */
  padsFor(pad, ticks, opts) {
    const timeline = opts && opts.timeline;
    if (timeline && Array.isArray(timeline.events)) return this._timedPads(pad, ticks, opts);
    const pressed = { ...(pad.pressed || {}) };
    if (this._timeline) {
      // rises carried by a timed-path 0-tick frame (router just disabled): keep their edges
      const h = { ...this._timeline.base };
      for (const e of this._timeline.events) { if (e.down && !h[e.name] && EDGE_SET.has(e.name)) pressed[e.name] = true; h[e.name] = !!e.down; }
      this._timeline = null;
    }
    if (this._edges) for (const k of EDGE_NAMES) pressed[k] = !!(pressed[k] || this._edges[k]);
    if (ticks <= 0) { this._edges = pressed; return []; }
    this._edges = null;
    const quiet = {};
    for (const k of Object.keys(pressed)) quiet[k] = false;
    const out = [];
    for (let i = 0; i < ticks; i++) out.push(i === 0 ? { ...pad, pressed } : { ...pad, pressed: quiet });
    return out;
  }

  /** @private issue #115 scheduler; see padsFor. */
  _timedPads(pad, ticks, opts) {
    const tl = opts.timeline;
    const carried = this._timeline;
    let merged = tl;
    if (carried) {
      // A poll consumed between the two (e.g. a pause frame) must not leave stale holds: bridge any
      // difference between the carried end state and this poll's base with untimed changes.
      const end = { ...carried.base };
      for (const e of carried.events) end[e.name] = !!e.down;
      const bridge = [];
      for (const n of Object.keys(tl.base || {})) if (!!end[n] !== !!tl.base[n]) bridge.push({ t: null, name: n, down: !!tl.base[n] });
      merged = { base: carried.base, events: carried.events.concat(bridge, tl.events), analog: tl.analog };
    }
    if (this._edges) {
      // edges carried by a legacy-path 0-tick frame (router just re-enabled): keep them as untimed rises
      const lift = [];
      for (const k of EDGE_NAMES) if (this._edges[k] && !merged.base[k]) lift.push({ t: null, name: k, down: true }, { t: null, name: k, down: false });
      if (lift.length) merged = { ...merged, events: lift.concat(merged.events) };
    }
    this._edges = null;
    if (ticks <= 0) { this._timeline = merged; return []; }
    this._timeline = null;
    const normalize = typeof opts.normalize === 'function' ? opts.normalize : (raw) => raw;
    const T = Number(opts.frameTime);
    const timed = Number.isFinite(T);
    const lastEnd = T - this.accMs;
    const tickOf = (t) => {
      if (!timed || t == null) return 0;
      // smallest i with t <= end_i, end_i = lastEnd - (ticks - 1 - i) * tickMs
      const i = Math.ceil((t - lastEnd) / this.tickMs - EPS) + ticks - 1;
      return i < 0 ? 0 : i >= ticks ? ticks - 1 : i;
    };
    const held = { ...merged.base };
    const analog = Number.isFinite(merged.analog) ? merged.analog : 0;
    // Schedule every change. Order is kept PER BUTTON (the journal records aggregate changes per name):
    // a change never lands before an earlier change of the same button, but an untimed gamepad/touch
    // change is never pushed behind a key event on another button (it keeps the frame's first tick).
    const buckets = Array.from({ length: ticks }, () => []);
    const floor = {};
    for (const ev of merged.events) {
      const at = Math.max(floor[ev.name] || 0, tickOf(ev.t));
      floor[ev.name] = at;
      buckets[at].push(ev);
    }
    const out = [];
    for (let i = 0; i < ticks; i++) {
      const rose = [];
      const pressed = { hop: false, reset: false, pause: false, airBrake: false, parachute: false, confirm: false };
      for (const ev of buckets[i]) {
        if (ev.down && !held[ev.name]) {
          rose.push(ev.name);
          if (EDGE_SET.has(ev.name)) pressed[ev.name] = true;
        }
        held[ev.name] = !!ev.down;
      }
      let view = held;
      if (rose.length) { view = { ...held }; for (const n of rose) view[n] = true; }
      const raw = { ...deriveHeld(view, analog), pressed, lastSource: pad.lastSource };
      out.push(normalize(raw));
    }
    return out;
  }
}/**
 * OWNER: gameplay engineer. Phaser-free (takes the Matter module as an argument), so it is unit-testable with plain objects.
 *
 * Skid-vs-terrain contact normals. The terrain is a chain of 16 px wide convex quads with vertical side walls and the
 * runners are 24-sided polygons. Matter's SAT picks the axis of MINIMUM overlap, so when a runner touches a seam
 * (or just skims a quad corner) the chosen axis is often a wall axis or one of the runner polygon's own 15 degree face
 * axes instead of the ground's top-face normal. That "ghost" normal points up to 15..60 degrees away from the real
 * surface, so a sled sliding at 700+ px/s gets a spurious normal velocity of v*sin(dev) (150-600 px/s) and the solver
 * answers with an off-centre impulse at a runner 15 px from the centre of mass: +/-400..700 deg/s of spin out of nothing
 * (verified frame by frame with tools/sim --sub). Snapping the contact normal of every skid/terrain pair to the quad's own
 * top-face normal removes it and leaves everything else (gaps, walls, head and deck contacts) untouched.
 */
import { TUNING } from './PhysicsTuner.js';
import pmath from './pmath.js';

const SNAP_FLAG = '__bbTerrainNormalSnap';

/**
 * Top-face unit normal (pointing up, out of the ground) of a terrain collider quad, from its vertices.
 * The top edge is the pair of lowest-y (highest on screen) vertices; colliders are extruded straight down so this holds
 * up to ~75 degree slopes.
 * @param {{vertices:{x:number,y:number}[]}} body
 * @returns {{x:number,y:number,top:number}|null} normal and the top-face plane offset along it (max projection of the quad).
 */
export function terrainTopNormal(body) {
  const v = body && body.vertices;
  if (!v || v.length < 3) return null;
  let a = null;
  let b = null;
  for (let i = 0; i < v.length; i++) {
    const p = v[i];
    if (!a || p.y < a.y) { b = a; a = p; } else if (!b || p.y < b.y) b = p;
  }
  if (!a || !b) return null;
  let dx = b.x - a.x;
  let dy = b.y - a.y;
  if (dx < 0) { dx = -dx; dy = -dy; }
  const len = pmath.hypot(dx, dy);
  if (len < 1e-6) return null;
  const nx = dy / len;
  const ny = -dx / len; // (dy,-dx): points up for a left-to-right edge
  let top = -Infinity;
  for (let i = 0; i < v.length; i++) top = Math.max(top, v[i].x * nx + v[i].y * ny);
  return { x: nx, y: ny, top };
}

/**
 * Rewrite a skid/terrain collision (in place) so its normal is the terrain quad's top-face normal.
 * Leaves the collision alone when it is not a runner-on-terrain pair, when the runner is deeper than `maxDepthPx` below the
 * top plane (a real wall: the side of a gap), or when the normal is already within `minDevDeg` of the face normal.
 * @param {object} collision Matter collision record (bodyA, bodyB are the colliding PARTS).
 * @param {{maxDepthPx?:number, minDevDeg?:number}} [opt]
 * @returns {boolean} true when the normal was replaced.
 */
export function snapTerrainNormal(collision, opt = {}) {
  const A = collision.bodyA;
  const B = collision.bodyB;
  let terrain;
  let skid;
  if (A.label === 'terrain' && B.label === 'skid') { terrain = A; skid = B; } else if (B.label === 'terrain' && A.label === 'skid') { terrain = B; skid = A; } else return false;
  const tn = terrainTopNormal(terrain);
  if (!tn) return false;
  const n = collision.normal;
  // Matter orients the collision normal so that it points from bodyB towards bodyA
  const sign = terrain === B ? 1 : -1;
  const dot = (n.x * tn.x + n.y * tn.y) * sign;
  const minDev = pmath.cos(((opt.minDevDeg != null ? opt.minDevDeg : 0.5) * Math.PI) / 180);
  if (dot >= minDev) return false;
  // overlap along the face normal: quad's top plane minus the runner's lowest point along it
  let low = Infinity;
  const sv = skid.vertices;
  for (let i = 0; i < sv.length; i++) low = Math.min(low, sv[i].x * tn.x + sv[i].y * tn.y);
  const depth = tn.top - low;
  const maxDepth = opt.maxDepthPx != null ? opt.maxDepthPx : TUNING.terrainSnapMaxDepthPx;
  if (!(depth > 0) || depth > maxDepth) return false;
  n.x = tn.x * sign;
  n.y = tn.y * sign;
  collision.tangent.x = -n.y;
  collision.tangent.y = n.x;
  collision.penetration.x = n.x * depth;
  collision.penetration.y = n.y * depth;
  collision.depth = depth;
  return true;
}

/**
 * Wrap Matter.Collision.collides once (idempotent) so every runner/terrain contact is normalised by snapTerrainNormal.
 * Matter's Detector looks the function up on the module object at call time, so patching the property is enough.
 * @param {{Collision:{collides:Function}}} Matter the Matter module Phaser bundles (Phaser.Physics.Matter.Matter).
 * @returns {void}
 */
export function installTerrainContactFix(Matter) {
  const C = Matter && Matter.Collision;
  if (!C || C.collides[SNAP_FLAG]) return;
  const orig = C.collides;
  const wrapped = function collides(bodyA, bodyB, pairs) {
    const col = orig(bodyA, bodyB, pairs);
    if (col && TUNING.terrainSnapNormals) snapTerrainNormal(col);
    return col;
  };
  wrapped[SNAP_FLAG] = true;
  wrapped.original = orig;
  C.collides = wrapped;
}/**
 * OWNER: core-logic engineer. NO Phaser imports.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Hybrid generator (design doc section 5): seeded spline-segment packs, then a noise zone, loop forever.
 * Output shapes are TerrainChunk (src/data/schemas.js). Content is injected, never imported
 * (so Jest can run it): tests read the JSON with fs, the game passes registry content.
 *
 * How it works
 *  - Track plan: chunk i has a "bound" record {startX, startY, startAngDeg, packNo, pos, ...}. The bound of chunk
 *    i+1 is produced when chunk i is built (end position and end tangent), so chunk i is a pure function of
 *    (seed, i, bound[i]) and can be regenerated identically in any call order after recycling.
 *  - Packs: `packSize` spline/bridge chunks followed by one noise-zone chunk (when a noise template is eligible),
 *    pack size and chunk length escalate with the pack number.
 *  - Every chunk is sampled at SPACING_PX (16 px) so points are evenly spaced (inside TERRAIN's 8..40 range) and
 *    chunk borders share the exact same point. Shape pipeline: raw profile (bezier / noise) -> start-tangent blend
 *    (slope continuity with the previous chunk) -> guaranteed net descent -> per-segment slope clamp and
 *    slope-change limiter (no impossible walls, readable curvature).
 *  - Spawns (zones, hazards, power-ups, bounce pads) come from independent forked RNG streams per chunk, so tweaking
 *    hazard content never changes the terrain shape.
 *  - Air hazards (placement 'air') are placed last, per jump, from their own fork ('air'); see _placeAirHazard.
 *  - Streaming: update(playerX) keeps TERRAIN.bufferAheadScreens screens generated ahead and drops chunks wholly
 *    TERRAIN.keepBehindScreens screens behind. Dropped chunk objects are pooled and reused one update later (so
 *    consumers that still hold a reference during the frame they receive `removed` are safe).
 *
 * Additive conventions (documented in ARCHITECTURE.md "Core-logic addenda"):
 *  - hazards[].x and bouncePads[].x are the CENTRE of the object.
 *  - Chunk `index` is stable; chunk.startX of chunk i+1 === chunk.endX of chunk i.
 */
import { Rng, xxHash32, hashInts } from './Rng.js';
import { rollSweep } from './HazardMotion.js';
import { TERRAIN } from '../constants.js';
import pmath from './pmath.js';
import { BASE_BIOME_ID } from '../data/biomeAliases.js';

/** Horizontal distance between consecutive polyline points (px). */
export const SPACING_PX = 16;
/** Steepest descent / ascent the generator will emit (degrees). Always below TERRAIN.maxSlopeDeg. */
export const MAX_DOWN_DEG = 42;
export const MAX_UP_DEG = 12;
export const MAX_NOISE_DOWN_DEG = 38;
export const MAX_NOISE_UP_DEG = 26;
/** Max change of slope angle between neighbouring segments (degrees). */
export const MAX_TURN_DEG = 10;
export const MAX_NOISE_TURN_DEG = 17;
/** Every chunk descends at least this much overall (tan of angle). */
const MIN_NET_TAN = pmath.tan((9 * Math.PI) / 180);
/** Hazard fairness: hazards keep this far from chunk ends / each other / the start of the run. */
export const HAZARD_END_MARGIN_PX = 240;
export const HAZARD_MIN_SPACING_PX = 480;
export const HAZARD_MIN_X_PX = 700;
/**
 * Anti-stall ("flow") rule: a hill may never rise above the descending RISE_LINE_DEG line drawn from the previous
 * peak (a sled resting on that peak can always roll over the next one), nor more than RISE_MAX_PX above the valley
 * floor it climbs out of. Keeps ordinary terrain rollable without pushing.
 */
export const RISE_LINE_DEG = 7;
export const RISE_MAX_PX = 30;
const RISE_LINE_TAN = pmath.tan((RISE_LINE_DEG * Math.PI) / 180);
/**
 * Crest rounding (fun pass): the slope angle may INCREASE (convex crest = ground falling away) by at most this per 16 px
 * segment on ordinary terrain, so a sled above ~450 px/s no longer micro-hops. Deliberate launch templates (SHARP_TAGS)
 * keep the full MAX_TURN_DEG. Concave (bowl) transitions are unrestricted up to the turn limit.
 */
export const CREST_TURN_DEG = 3.5;
export const NOISE_CREST_TURN_DEG = 6;
export const SHARP_TAGS = ['kicker', 'jump-lip', 'launch', 'big-air', 'drop', 'steps', 'jump-gen'];
/** Sectors: every SECTOR_M metres difficulty steps up and a calm breather chunk starts the sector. */
export const SECTOR_M = 500;

/**
 * Issue #65: Debutmont is the base biome. This is the id every "base" answer resolves to (sectors before
 * BASE_SECTORS, mask 0, the base-weight draw). One constant, shared with the profile and defined in
 * data/biomeAliases.js; re-exported here. Arcade (`null`) is no longer a base: it is only the bridge between two
 * different biomes (see biomeAtPosition).
 */
export { BASE_BIOME_ID };

/**
 * Sectors whose content is always the home biome, whatever the mask (spec W3: "Sectors 0 and 1 are always
 * base"; the base is now Debutmont, #65). Sector numbers here are 0-based (sector n starts at
 * n * SECTOR_M); TerrainChunk.sector is the same value 1-based for display.
 */
export const BASE_SECTORS = 2;
/** Weight of a home-biome sector against the enabled biomes, once biomes can appear. */
export const BIOME_BASE_WEIGHT = 2.2;
/**
 * Arcade bridges (#65): the first stretch of a sector whose biome differs from the previous sector's is arcade
 * terrain. Length, as a fraction of SECTOR_M, is MIN_FRAC at the run start and rises linearly with the sector's
 * start distance to MAX_FRAC at ARCADE_BRIDGE_RAMP_M, then stays there. Distance only: never progression, input or BSOD.
 */
export const ARCADE_BRIDGE_MIN_FRAC = 1 / 6;
export const ARCADE_BRIDGE_MAX_FRAC = 1 / 4;
export const ARCADE_BRIDGE_RAMP_M = 5000;
/**
 * Hard cap on a bridge, as a multiple of its target length (whole chunks make a bridge overshoot the target, and a
 * long carve starting just inside the window used to stretch it to 300 m). A chunk that would carry the bridge past
 * ARCADE_BRIDGE_CAP_MUL x target, measured from the bridge's own first chunk, takes the sector's biome instead.
 */
export const ARCADE_BRIDGE_CAP_MUL = 1.5;
/** bridgeSpanAt never walks more chunks than this either way (a bridge is a handful; this only bounds a bug). */
const BRIDGE_SCAN_MAX_CHUNKS = 64;
/** Hazard gentleness: no hazards before HAZARD_SOFT_PX (80 m); only non-crash hazards before HAZARD_SAFE_PX (150 m). */
export const HAZARD_SOFT_PX = 1600;
export const HAZARD_SAFE_PX = 3000;
/** The first part of a sector's breather chunk is hazard free. */
export const BREATHER_CALM_PX = 1100;
/** Jump chunks, landing zones and breathers are hazard free, so ordinary chunks carry proportionally more. */
export const HAZARD_DENSITY_MUL = 3.4;
/**
 * Late-game fill: past 500 m the density formula asks for a gap well below HAZARD_MIN_SPACING_PX, so every slot sits exactly
 * one min spacing apart and a slot rejected (flat / slow-hazard / lip-zone rules) wastes a whole 480 px. From
 * HAZARD_RETRY_FROM_M on, a rejected slot is retried HAZARD_RETRY_STEP_PX further instead; a placed hazard still advances
 * by the full gap, so the spacing rules are untouched (only the fill of the eligible ground rises).
 */
export const HAZARD_RETRY_FROM_M = 2000;
export const HAZARD_RETRY_STEP_PX = 120;
/** Generated launch chunk ("gen-jump"): see _jumpAngles. */
export const JUMP_APPROACH_FIRST_PX = 900;
export const JUMP_RUNOUT_PX = 240;
/** Measured (real game): launch speed after a JUMP_APPROACH_DEG x JUMP_APPROACH_PX approach, regardless of the entry speed. */
export const JUMP_LAUNCH_SPEED_PX_S = 480;
/** Up-angle of the lip of later generated jumps (the first, easy one keeps MAX_UP_DEG). */
export const JUMP_LIP_UP_DEG = 15;
export const JUMP_APPROACH_DEG = 24;
export const JUMP_APPROACH_PX = 900;
/** The runout after a landing ramp bends (concave) by at most this per 16 px segment, so a 700 px/s sled keeps its head off the ground. */
export const RUNOUT_TURN_DEG = 0.9;
/** Slow-type hazards need this much clear descent behind them (px) or they are not placed (anti-stall). */
export const SLOW_HAZARD_CLEAR_PX = 600;
export const SLOW_HAZARD_MIN_DEG = 9;
/** Real launch speed of a sharp-lip template is this share of the expected speed (measured 160-300 px/s of 340-440). */
export const TEMPLATE_LIP_SPEED_MUL = 0.8;
/** Anti-stall: the roll model must stay above this speed (px/s) inside every chunk. */
export const STALL_SPEED_PX_S = 80;
export const LIP_MIN_AIR_S = 0.45;
/** Deliberate lips of generated jumps turn this much per segment (still below the 17 deg kink limit). */
export const LIP_TURN_DEG = 16;
/** Shards: spacing, group size and share of chunks that carry a group. */
export const SHARD_SPACING_PX = [28, 40];
export const SHARD_GROUP = [4, 9];
export const SHARD_PLAIN_CHANCE = 0.17;
/**
 * Air hazards (placement 'air', e.g. roguePacket): at most one per generated jump, never on chunk 0, never in breathers,
 * never before AIR_HAZARD_MIN_M (the def's own minDistanceM may only raise this). Chance per eligible jump rises from
 * AIR_CHANCE_START to AIR_CHANCE_END between AIR_HAZARD_MIN_M and AIR_CHANCE_FULL_M. Drawn from the forked rng 'air'.
 */
export const AIR_HAZARD_MIN_M = 1500;
export const AIR_CHANCE_START = 0.25;
export const AIR_CHANCE_END = 0.55;
export const AIR_CHANCE_FULL_M = 10000;
/**
 * Fairness: the hit box of an air hazard sits ABOVE every no-hop arc, with at least AIR_CLEARANCE_PX of vertical clearance,
 * for launch speeds from AIR_SPEED_LO_MUL x to max(AIR_SPEED_HI_MUL x, expected speed) of the nominal launch speed (arcs are
 * monotone in speed, so the fastest one bounds the family; 1.6x covers a sled boosted by landing speed-ups). So a normal
 * flight always passes under it and only a hop at the lip or a wildly over-fast arc reaches it. (A "low" placement near the
 * lip-to-landing chord was rejected: a slow launch drops onto the landing ramp and no box could keep 70 px clear of it.)
 */
export const AIR_CLEARANCE_PX = 70;
export const AIR_SPEED_LO_MUL = 0.75;
export const AIR_SPEED_HI_MUL = 1.6;
/**
 * Position along the flight: the box sits LATE in the arc, at least AIR_MIN_DX_PX past the lip and between AIR_U_MIN and
 * AIR_U_MAX of the lip-to-landing span, so a reflex hop at the lip is already committed when the box is reached and the
 * warning telegraph has time to be read. A jump whose span cannot fit this (0.8 x span < 400 px) gets no air hazard.
 */
export const AIR_MIN_DX_PX = 400;
export const AIR_U_MIN = 0.55;
export const AIR_U_MAX = 0.8;
/**
 * Near-miss window for flying UNDER an air hazard: a sled that crosses the box x while airborne and at most this far below
 * the box bottom paid a near miss. It spans the whole no-hop family: the box bottom is >= AIR_CLEARANCE_PX above the 1.6x
 * arc and the nominal (1.0x) arc passes ~280 px below it at the placement distances above (tested), so one normal flight
 * pays exactly once.
 */
export const AIR_NEAR_MISS_BELOW_PX = 360;
/** Power-up spawn chance never decays below this share of the def's baseChance. */
export const POWERUP_FLOOR_FRACTION = 0.4;
/**
 * B0 biome spawns (spec §4 bounds). One hazard slot and one power-up slot per biome chunk, each spawning with the def's
 * own `spawn.baseChance`, capped here. The power-up chance has no distance decay (spec: "a fixed spawn chance").
 */
export const BIOME_SPAWN_MAX_CHANCE = 0.5;
/** B1 presence amendment (c) (spec author, 2026-11-14): the biome HAZARD slot's chance cap. Power-ups keep 0.5. */
export const BIOME_HAZARD_MAX_CHANCE = 0.75;
/** Chance used when a biome def carries no `spawn.baseChance` (mirrors the base power-up default). */
export const BIOME_SPAWN_DEFAULT_CHANCE = 0.2;
/**
 * Clearance from the chunk edges for biome spawns. Spec §4 asks for >= 96 px; 240 (the base hazard margin) is used because a
 * per-chunk pass cannot see the neighbour chunk, and two 240 px margins are what keep hazards >= HAZARD_MIN_SPACING_PX apart
 * across a chunk border.
 */
export const BIOME_EDGE_MARGIN_PX = HAZARD_END_MARGIN_PX;
/** Random numbers each biome slot draws, whatever its outcome, so one def's tuning never shifts another stream. */
export const BIOME_SLOT_DRAWS = 5;
/**
 * B1 slot rule (spec §4, amended 2026-11-14): when the free scan finds no ground slot, the biome hazard may replace ONE base
 * ground hazard of its chunk, but only when its box fits within the replaced box plus this slack (w and h each), so the
 * shard and power-up clearances computed around the base hazard still hold.
 */
export const BIOME_REPLACE_SLACK_PX = 8;
/**
 * B1 presence amendment (spec author, 2026-11-14) (a): a biome ground hazard keeps this far from any other hazard, instead of
 * the base HAZARD_MIN_SPACING_PX. BIOME_EDGE_MARGIN_PX still keeps it 240 px inside its chunk, so base hazards across a
 * chunk border are untouched.
 */
export const BIOME_HAZARD_CLEARANCE_PX = 240;
/**
 * (b): the descent-ahead rule (anti-stall) binds a biome `slow` hazard only when its speedFactor is below this. A gentler slow
 * may sit on flat or downhill ground, but never before an uphill (no segment climbing within BIOME_EDGE_MARGIN_PX ahead).
 */
export const BIOME_GENTLE_SLOW_FACTOR = 0.6;
/**
 * B2 blind fairness: a biome `blind` ground hazard (Shatter Wall) needs the stretch the sled covers while blinded, plus a
 * reaction margin, clear of every crash hazard, so a hazard hidden by the dimming is never a cheap death. The stretch is
 * (durationMs + BIOME_BLIND_REACT_MS) at BIOME_BLIND_SPEED_MUL x the expected speed. The per-chunk pass cannot see the
 * next chunk, so only this chunk's hazards are checked: requiring the stretch to end inside the chunk cut Shatter Wall
 * presence to ~4 %. Measured residual (32 seeds x 300 chunks): ~3 % of placements have a next-chunk crash hazard within
 * 1.2 s at the expected speed, against ~29 % without the rule.
 */
export const BIOME_BLIND_REACT_MS = 500;
export const BIOME_BLIND_SPEED_MUL = 1.2;
/** px ahead of a blind ground hazard at distM that must hold no crash hazard. @param {{durationMs?:number}} onHit @param {number} distM */
export function blindClearAheadPx(onHit, distM) {
  const ms = (onHit && Number.isFinite(onHit.durationMs) ? onHit.durationMs : 1200) + BIOME_BLIND_REACT_MS;
  return Math.round((expectedSpeedPxS(distM) * BIOME_BLIND_SPEED_MUL * ms) / 1000);
}
/**
 * B3: the HazardSpawn of a biome ground hazard. A Gear Gate (motion gate) also carries `phase` (0..1), the slot's 4th
 * pre-drawn number (h3, unused by ground slots before B3), so each gate's cycle is its own draw (spec §5) and no stream
 * moves. Other defs get exactly the pre-B3 shape.
 */
function biomeSpawn(def, x, y, rotationDeg, h3) {
  const sp = { defId: def.id, x, y, rotationDeg };
  if (def.motion && def.motion.kind === 'gate') sp.phase = Math.round((Number.isFinite(h3) ? h3 : 0) * 1e6) / 1e6;
  return sp;
}
/**
 * B3 tuning: how far inside the chunk edges a rolling hazard's TRACK must stay (its spawn keeps BIOME_EDGE_MARGIN_PX).
 * A roll now goes downhill (+x), so its track ends toward the chunk end. 120 >= the spec §4 96 px edge clearance, and a
 * neighbour chunk's hazards sit >= HAZARD_END_MARGIN_PX (240) inside its own edge, so a track end is still >= 360 px
 * from them (more than BIOME_HAZARD_CLEARANCE_PX); tests/src/biome-b3-presence.test.js checks the neighbours too.
 */
export const ROLL_TRACK_EDGE_MARGIN_PX = 120;
/** Difficulty tail: past the old caps the ramp keeps creeping up (gently) to a hard ceiling. */
export const HAZARD_DENSITY_CAP_M = 3500;
export const HAZARD_DENSITY_TAIL_END_M = 10000;
export const HAZARD_DENSITY_TAIL = 0.7; // 2.1 -> 2.8
export const SPEED_TAIL_END_M = 6000;
export const SPEED_TAIL = 80; // 620 -> 700
const GRAV = 900;
const JUMP_DEF = Object.freeze({
  id: 'gen-jump', kind: 'spline', weight: 1, minDistanceM: 0, lengthPx: 1, tags: Object.freeze(['jump', 'launch', 'jump-gen']),
});

/** Typical sled speed (px/s) at a distance: the "speed budget" that jump geometry and shard arcs are sized for. */
/**
 * B4 low-gravity fairness for biome air boxes: the gravity multiplier a flight from x0 to x1 may ride, for the arc model
 * (_arcY assumes the base g). The product of every gravityMul < 1 of the zones overlapping [x0, x1] (a conservative
 * bound: under a lowGravity zone a no-hop flight drops less, so the box must sit higher to keep AIR_CLEARANCE_PX). Zones
 * that only make the sled heavier (gravityMul > 1) or carry no gravityMul count as 1. Space Mountain's own mod is
 * lowGravity (x0.7); without this its Meteor sat on the arc of a 1.3x-expected-speed flight (measured on the real sled).
 * @param {Array<{modId:string, x0:number, x1:number}>} zones the chunk's zones
 * @param {Object<string, {physics?:{gravityMul?:number}}>} modMap mod defs by id
 * @param {number} x0 lip x
 * @param {number} x1 landing x
 * @returns {number} in (0, 1]
 */
export function flightGravityMul(zones, modMap, x0, x1) {
  let g = 1;
  for (const z of zones || []) {
    if (!z || z.x1 < x0 || z.x0 > x1) continue;
    const m = modMap && modMap[z.modId];
    const gm = m && m.physics && m.physics.gravityMul;
    if (gm > 0 && gm < 1) g *= gm;
  }
  return g;
}

export function expectedSpeedPxS(distM) {
  const d = Math.max(0, distM);
  const capM = (620 - 340) / 0.18; // ~1556 m: where the original ramp reached its 620 px/s cap
  const tail = SPEED_TAIL * clamp((d - capM) / (SPEED_TAIL_END_M - capM), 0, 1);
  return Math.min(620, 340 + 0.18 * d) + tail; // continuous at the cap, hard ceiling 620 + SPEED_TAIL
}
const RAD = Math.PI / 180;
const DEG = 180 / Math.PI;

const BUILTIN_DEF = Object.freeze({
  id: 'builtin-slope', kind: 'spline', weight: 1, minDistanceM: 0, lengthPx: 1200,
  controlPoints: [{ x: 0, y: 0 }, { x: 0.5, y: 100 }, { x: 1, y: 200 }], tags: ['intro'],
});

const toList = (x) => (Array.isArray(x) ? x.slice() : x && typeof x === 'object' ? Object.values(x) : []);
const byId = (a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
/** Defs carrying a `biome` field, grouped by biome id; input order (sorted by id) is kept inside each group. */
const groupByBiome = (sorted) => {
  const out = {};
  for (const d of sorted) if (d.biome) (out[d.biome] || (out[d.biome] = [])).push(d);
  return out;
};
const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
const smooth = (t) => t * t * (3 - 2 * t);
/**
 * Spawn chance of one biome slot: the def's `spawn.baseChance`, capped at `cap` (spec §4: BIOME_SPAWN_MAX_CHANCE; B1
 * presence amendment (c): BIOME_HAZARD_MAX_CHANCE for the hazard slot).
 */
const biomeChance = (d, cap = BIOME_SPAWN_MAX_CHANCE) => clamp(
  d.spawn && Number.isFinite(d.spawn.baseChance) ? d.spawn.baseChance : BIOME_SPAWN_DEFAULT_CHANCE, 0, cap,
);

/** 1-D smooth value noise in [-1,1]. */
function vnoise(x, seed) {
  const xi = Math.floor(x);
  const f = x - xi;
  const u = f * f * (3 - 2 * f);
  const a = hashInts(xi, seed) / 2147483648 - 1;
  const b = hashInts(xi + 1, seed) / 2147483648 - 1;
  return a + (b - a) * u;
}

/**
 * @typedef {Object} DifficultyParams
 * @property {number} slopeVariance   multiplier >= 1 on slope/height variance.
 * @property {number} hazardDensity   hazards per 1000 px.
 * @property {number} glitchFrequency multiplier >= 1 (consumed by GlitchDirector).
 * @property {number} noiseWeightMul  multiplier on noise-zone chunk weight.
 */

/**
 * @typedef {Object} TerrainGeneratorOptions
 * @property {string} seed
 * @property {import('../data/schemas.js').ChunkDef[]} chunkDefs
 * @property {Object<string, import('../data/schemas.js').HazardDef>} hazardDefs
 * @property {Object<string, import('../data/schemas.js').PowerUpDef>} powerupDefs
 * @property {Object<string, import('../data/schemas.js').TerrainModDef>} modDefs
 * @property {number} [screenWidthPx=480] defines what a "screen" is for buffering.
 * @property {number} [pxPerMeter=20]
 */

/**
 * Which biome a sector is drawn as, BEFORE arcade bridges (see biomeAtPosition). Pure and seed-deterministic: the
 * answer depends only on (seed, sector, mask), never on call order or on how much terrain has been generated,
 * so a chunk built late by streaming is identical to one built early.
 *
 * Draws from `Rng.fork('biome')`, an independent stream, so asking this question never advances the
 * terrain, hazard or shard streams. Debutmont (BASE_BIOME_ID) is the base: it answers wherever the old model
 * answered arcade (sectors before BASE_SECTORS, mask 0, no eligible defs, the base-weight draw). The home
 * biome is left out of the eligible pool, so its mask bit is a no-op and it is never double-weighted. The draw
 * count and order are the same as before, so a non-home pick for a given seed and mask is unchanged.
 *
 * @param {string|number} seed run seed.
 * @param {number} sector 0-based sector index.
 * @param {number} biomeMask bitfield of enabled biome bits.
 * @param {Array<{id:string,bit:number,weight?:number}>} [biomeDefs] content; defaults to none.
 * @returns {string} biome id (never null; the home biome is the base).
 */
export function biomeForSector(seed, sector, biomeMask, biomeDefs) {
  if (!(sector >= BASE_SECTORS)) return BASE_BIOME_ID;
  const mask = biomeMask >>> 0;
  if (!mask) return BASE_BIOME_ID;
  const defs = Array.isArray(biomeDefs) ? biomeDefs : [];
  // Eligible = the biome is in the mask AND we actually have its definition (a mask bit with no content
  // would otherwise be a sector with no palette and no chunks). The home biome is the base, not a candidate.
  const eligible = defs.filter((d) => d && d.bit && d.id !== BASE_BIOME_ID && (mask & d.bit) !== 0);
  if (!eligible.length) return BASE_BIOME_ID;
  const rng = new Rng(xxHash32(`biome:${sector}`, new Rng(seed).baseSeed));
  const pick = rng.weighted(
    eligible.concat([{ id: null, weight: BIOME_BASE_WEIGHT }]),
    (d) => d.weight || 1,
  );
  return pick && pick.id ? pick.id : BASE_BIOME_ID;
}

/**
 * Length in metres of the arcade bridge that opens a sector starting at `startM`, before chunk snapping.
 * Linear in the start distance from ARCADE_BRIDGE_MIN_FRAC to ARCADE_BRIDGE_MAX_FRAC of SECTOR_M over
 * ARCADE_BRIDGE_RAMP_M, then capped (about 83 m at the start, 125 m from 5000 m).
 * @param {number} startM distance of the sector's start, metres.
 * @returns {number} metres.
 */
export function arcadeBridgeLengthM(startM) {
  const t = clamp((Number(startM) || 0) / ARCADE_BRIDGE_RAMP_M, 0, 1);
  return SECTOR_M * (ARCADE_BRIDGE_MIN_FRAC + (ARCADE_BRIDGE_MAX_FRAC - ARCADE_BRIDGE_MIN_FRAC) * t);
}

/**
 * Whether the sector's biome differs from the previous sector's, i.e. whether the sector opens with an arcade
 * bridge. Sector 0 (the run start) never does.
 * @returns {boolean}
 */
export function sectorHasBridge(seed, sector, biomeMask, biomeDefs) {
  return sector >= 1
    && biomeForSector(seed, sector, biomeMask, biomeDefs) !== biomeForSector(seed, sector - 1, biomeMask, biomeDefs);
}

/**
 * Longest a bridge opening a sector starting at `startM` may run, in metres: ARCADE_BRIDGE_CAP_MUL x its target
 * length (about 125 m at the start, 187.5 m from 5000 m).
 * @param {number} startM distance of the sector's start, metres.
 * @returns {number} metres.
 */
export function arcadeBridgeCapM(startM) {
  return ARCADE_BRIDGE_CAP_MUL * arcadeBridgeLengthM(startM);
}

/**
 * The biome at a position: the sector's biome, except the first arcade-bridge length of a sector that changes
 * biome, which is arcade (`null`). Pure in (seed, x, mask, defs): no RNG draws beyond biomeForSector's, no
 * dependence on input, progression or BSOD, so every player sees the same course (leaderboards, Daily, ghosts).
 *
 * Chunk snapping: the generator assigns a chunk by its START x, so a bridge is a run of whole chunks. A plain
 * position query (no `chunk`) answers the unsnapped window. A chunk-level query passes the chunk's facts:
 *   - `first`: the first chunk that starts in a bridging sector is always arcade, so every biome change has at
 *     least one chunk of bridge however long the chunk straddling the boundary was;
 *   - otherwise a chunk is arcade when it starts inside the window AND ends within the cap of the bridge's own
 *     start (`runStartM` = start of the sector's first chunk, `endM` = this chunk's end), so a long chunk starting
 *     just inside the window can no longer stretch the bridge: the sector's biome takes it instead.
 *
 * @param {string|number} seed
 * @param {number} xM position, metres (>= 0).
 * @param {number} biomeMask
 * @param {Array<{id:string,bit:number,weight?:number}>} [biomeDefs]
 * @param {{first?:boolean, runStartM?:number, endM?:number}|boolean} [chunk] chunk-level facts (a bare `true`
 *   means `{ first: true }`); omit for a plain position query.
 * @returns {string|null} biome id, or null for an arcade bridge.
 */
export function biomeAtPosition(seed, xM, biomeMask, biomeDefs, chunk) {
  const sector = Math.max(0, Math.floor(xM / SECTOR_M));
  const biome = biomeForSector(seed, sector, biomeMask, biomeDefs);
  if (sector < 1 || biomeForSector(seed, sector - 1, biomeMask, biomeDefs) === biome) return biome;
  const startM = sector * SECTOR_M;
  const c = chunk === true ? { first: true } : chunk || {};
  if (c.first) return null;
  if (xM - startM >= arcadeBridgeLengthM(startM)) return biome;
  const fits = !Number.isFinite(c.endM) || c.endM <= (Number.isFinite(c.runStartM) ? c.runStartM : startM) + arcadeBridgeCapM(startM);
  return fits ? null : biome;
}

export class TerrainGenerator {
  /** @param {TerrainGeneratorOptions} options */
  constructor(options) {
    this.options = options;
    this.screenW = options.screenWidthPx || 480;
    this.ppm = options.pxPerMeter || 20;
    this.seed = String(options.seed);
    this.rng = new Rng(options.seed).fork('terrain');
    this.seedState = this.rng.baseSeed;

    const defs = toList(options.chunkDefs).filter((d) => d && d.lengthPx > 0).sort(byId);
    this.splineDefs = defs.filter((d) => d.kind === 'spline');
    this.noiseDefs = defs.filter((d) => d.kind === 'noise');
    this.bridgeDefs = defs.filter((d) => d.kind === 'bridge');
    if (this.splineDefs.length === 0) this.splineDefs = [BUILTIN_DEF];
    // ground hazards feed the original placement loop untouched; air hazards are placed per jump from their own list.
    // Biome defs (a `biome` field, B0) never enter the base lists: they are kept per biome and placed only by
    // _placeBiomeSpawns, so base placement and mask-0 output cannot see them (spec §5, E4).
    const allDefs = toList(options.hazardDefs).filter(Boolean).sort(byId);
    const allHazards = allDefs.filter((h) => !h.biome);
    this.hazardList = allHazards.filter((h) => h.placement !== 'air');
    this.airHazardList = allHazards.filter((h) => h.placement === 'air');
    const allPowerups = toList(options.powerupDefs).filter(Boolean).sort(byId);
    // `placement: 'own'` defs (Shard Magnet) never join the base pick pool or the chunk output: adding one must leave
    // every existing seed's chunks bit-identical (SPEC §9). RunScene places them from ShardMagnet.magnetSpawn.
    this.powerupList = allPowerups.filter((p) => !p.biome && p.placement !== 'own');
    /** @type {Object<string, import('../data/schemas.js').HazardDef[]>} biome id -> its hazard defs (sorted by id). */
    this.biomeHazards = groupByBiome(allDefs);
    /** @type {Object<string, import('../data/schemas.js').PowerUpDef[]>} biome id -> its power-up defs (sorted by id). */
    this.biomePowerups = groupByBiome(allPowerups);
    /** B3: biome hazard defs by id (the power-up slot keeps clear of a rolling hazard's whole track). */
    this.biomeHazardById = Object.fromEntries(allDefs.filter((h) => h.biome).map((h) => [h.id, h]));
    /** B2: ids of every crash hazard def (base and biome), for the blind fairness rule in _biomeGroundAt. */
    this.crashHazardIds = new Set(allDefs.filter((h) => !h.onHit || !h.onHit.effect || h.onHit.effect === 'crash').map((h) => h.id));
    this.modMap = {};
    for (const m of toList(options.modDefs)) this.modMap[m.id] = m;
    /** Biome defs (W3, additive): drives sector assignment, palettes and biome chunk preference. */
    this.biomeDefs = toList(options.biomeDefs).sort(byId);
    this.biomeMask = Number.isFinite(options.biomeMask) ? options.biomeMask >>> 0 : 0;

    /** @type {Map<number, import('../data/schemas.js').TerrainChunk>} */
    this.active = new Map();
    /** @type {import('../data/schemas.js').TerrainChunk[]} ascending by index. */
    this.activeList = [];
    this.pool = [];
    this._pendingRelease = [];
    this._pendingAdded = [];
    this._scratchChunk = this._newChunk();
    this._tempChunk = null;
    this._lastChunk = null;
    /** Diagnostics: created = chunk objects ever allocated, reused = chunk objects recycled from the pool. */
    this.stats = { created: 1, reused: 0, built: 0 };
    this.bounds = [{
      startX: 0, startY: 0, startAngDeg: 6, packNo: 0, pos: 0, packSize: this._packSize(0), prevKind: '',
      peakDx: 0, peakDy: 0, valDy: 0, sinceLaunch: 0, prevJump: false, noHazX: 0, speed: 90,
    }];
    this._cap = 0;
    this._raw = null;
    this._ys = null;
    this._cx = new Float64Array(16);
    this._cy = new Float64Array(16);
    this._tx = new Float64Array(15 * 24 + 2);
    this._ty = new Float64Array(15 * 24 + 2);
    this._ensureScratch(256);
  }

  // ------------------------------------------------------------------------------------------------ public API

  /**
   * Spawn point: top of chunk 0, on the surface.
   * @returns {{x:number,y:number}} world px.
   */
  getStartPosition() {
    return { x: 0, y: 0 };
  }

  /**
   * Deterministic: same index => identical chunk for a given seed regardless of call order.
   * Chunks that were recycled can be re-requested and are regenerated identically.
   * If the chunk is currently active the live object is returned, otherwise a fresh (non-pooled) object.
   * @param {number} index >= 0
   * @returns {import('../data/schemas.js').TerrainChunk}
   */
  getChunk(index) {
    index = Math.floor(index);
    if (!(index >= 0)) throw new RangeError('chunk index must be >= 0');
    const live = this.active.get(index);
    if (live) return live;
    this._boundAt(index);
    return this._build(index, this._newChunk());
  }

  /**
   * Streaming: ensure TERRAIN.bufferAheadScreens screens exist ahead of playerX and drop chunks that are
   * entirely more than TERRAIN.keepBehindScreens screens behind (recycle their arrays into a pool).
   * Call once per frame (cheap when nothing changes).
   * @param {number} playerX world px.
   * @returns {{added: import('../data/schemas.js').TerrainChunk[], removed: number[]}} newly generated chunks and indices dropped.
   */
  update(playerX) {
    // chunks dropped last update become reusable now
    while (this._pendingRelease.length) {
      if (this.pool.length < 6) this.pool.push(this._pendingRelease.pop());
      else this._pendingRelease.pop();
    }
    const removed = [];
    const list = this.activeList;
    const keepFrom = playerX - TERRAIN.keepBehindScreens * this.screenW;
    while (list.length > 1 && list[0].endX < keepFrom) {
      const c = list.shift();
      this.active.delete(c.index);
      this._pendingRelease.push(c);
      removed.push(c.index);
    }
    const added = this._pendingAdded;
    this._pendingAdded = [];
    if (list.length === 0) {
      const first = playerX <= 0 ? 0 : this._indexForX(Math.max(0, keepFrom));
      this._addChunk(first, added);
    }
    this._fillAhead(playerX + TERRAIN.bufferAheadScreens * this.screenW, added);
    // a chunk added and dropped within the same call would be misleading; filter it out
    if (removed.length && added.length) {
      for (let i = added.length - 1; i >= 0; i--) if (!this.active.has(added[i].index)) added.splice(i, 1);
    }
    return { added, removed };
  }

  /** @returns {import('../data/schemas.js').TerrainChunk[]} currently live chunks ordered by index. */
  getActiveChunks() {
    return this.activeList.slice();
  }

  /**
   * Chunk containing world x (active chunk, or a temporary rebuilt one when x is outside the live window).
   * Additive helper. Returns null for x < 0.
   * @param {number} x world px.
   * @returns {import('../data/schemas.js').TerrainChunk|null}
   */
  getChunkAt(x) {
    return x < 0 ? null : this._chunkAt(x);
  }

  /**
   * Ground surface height by linear interpolation. Also valid inside gaps (interpolated line; there is no collider).
   * @param {number} x world px.
   * @returns {number} y world px (down positive).
   */
  heightAt(x) {
    if (x < 0) return pmath.tan(this.bounds[0].startAngDeg * RAD) * x;
    const c = this._chunkAt(x);
    const p = c.points;
    const i = this._segIndex(c, x);
    const a = p[i];
    const b = p[i + 1];
    // Audit T2: a dew swell is already IN the points (see _applySwell), so heightAt is the plain polyline - the same
    // surface TerrainMesh builds the collider and the drawn edge from, and the one slopeDegAt reads.
    return a.y + ((b.y - a.y) * (x - a.x)) / (b.x - a.x);
  }

  /**
   * Swell displacement at x from the zones of the chunk containing x (diagnostic; the points already carry it).
   * @param {number} x world px
   * @returns {number} px offset, down positive
   */
  _swellAt(x) {
    return this._swellOffset(this._chunkAt(x).zones, x);
  }

  /**
   * Sum of the rolling-dew swells of `zones` at x: a sine bounded by amplitudePx, multiplied by a raised-cosine window
   * that rises from 0 to 1 over `taperPx` at each zone edge (clamped to half the zone). Offset and slope are both 0 at
   * the edges, so the swelled ground meets the raw ground with no step and no kink. taperPx absent = no taper.
   * Pure: reads only the zones and modMap, never _chunkAt, so _build can call it on a chunk under construction.
   * @param {import('../data/schemas.js').TerrainZone[]} zones
   * @param {number} x world px
   * @returns {number} px offset, down positive
   */
  _swellOffset(zones, x) {
    let sum = 0;
    for (let i = 0; i < zones.length; i++) {
      const z = zones[i];
      if (x < z.x0 || x > z.x1) continue;
      // Zones carry a modId, not the def: resolve through modMap, the same table _placeBiomeZone uses.
      const mod = this.modMap && this.modMap[z.modId];
      const sw = mod && mod.terrainSwell;
      if (!sw || !Number.isFinite(sw.amplitudePx) || !Number.isFinite(sw.periodPx) || sw.periodPx <= 0) continue;
      const taper = Math.min(Number.isFinite(sw.taperPx) && sw.taperPx > 0 ? sw.taperPx : 0, (z.x1 - z.x0) / 2);
      const t = Math.min(x - z.x0, z.x1 - x);
      const w = taper > 0 && t < taper ? 0.5 - 0.5 * pmath.cos((Math.PI * t) / taper) : 1;
      sum += pmath.sin(((x - z.x0) / sw.periodPx) * Math.PI * 2) * sw.amplitudePx * w;
    }
    return sum;
  }

  /**
   * Audit T2: move the swell of every terrainSwell zone INTO the chunk points, so the collider, the drawn edge,
   * slopeDegAt, heightAt and every spawn placed after this call describe one surface. Runs right after the zones are
   * placed and before lips, hazards, power-ups and shards. Only `points` change: zones sit >= 96 px inside the chunk
   * and the window is 0 at their edges, so the chunk end points (and with them the next chunk's bound, rise state and
   * roll speed, all built from `ys`) are untouched. 16 px spacing samples a 220 px period at ~14 points (chord error
   * < 1 px), so no extra points are needed and _segIndex keeps its uniform-spacing contract.
   * A chunk with no swell zone (every chunk outside Micro Mountain) returns before touching a point.
   * @param {import('../data/schemas.js').TerrainChunk} chunk
   */
  _applySwell(chunk) {
    const zones = chunk.zones;
    let any = false;
    for (let i = 0; i < zones.length && !any; i++) {
      const mod = this.modMap[zones[i].modId];
      if (mod && mod.terrainSwell) any = true;
    }
    if (!any) return;
    const pts = chunk.points;
    for (let i = 0; i < pts.length; i++) pts[i].y += this._swellOffset(zones, pts[i].x);
  }

  /**
   * @param {number} x world px.
   * @returns {number} slope of the ground at x in DEGREES, positive = descending to the right (clockwise rotation).
   */
  slopeDegAt(x) {
    if (x < 0) return this.bounds[0].startAngDeg;
    const c = this._chunkAt(x);
    const p = c.points;
    const i = this._segIndex(c, x);
    return pmath.atan2(p[i + 1].y - p[i].y, p[i + 1].x - p[i].x) * DEG;
  }

  /**
   * @param {number} x world px.
   * @returns {import('../data/schemas.js').TerrainZone[]} zones containing x (may be several).
   */
  getZonesAt(x) {
    if (x < 0) return [];
    const zones = this._chunkAt(x).zones;
    const out = [];
    for (let i = 0; i < zones.length; i++) if (x >= zones[i].x0 && x <= zones[i].x1) out.push(zones[i]);
    return out;
  }

  /**
   * Difficulty ramp (flat until TERRAIN.difficultyRampStartM = 1000 m, then rising).
   * @param {number} distanceM
   * @returns {DifficultyParams}
   */
  difficultyAt(distanceM) {
    // stepped per sector (SECTOR_M); the old single ramp from 1000 m is the baseline this builds toward (ramp 1 ~ 3500 m)
    const sector = Math.floor(Math.max(0, distanceM) / SECTOR_M);
    const ramp = sector / 7;
    // past the old 3500 m cap the density keeps creeping up: 2.1 -> 2.1 + HAZARD_DENSITY_TAIL by 10 km, then flat
    const tail = HAZARD_DENSITY_TAIL * clamp((sector * SECTOR_M - HAZARD_DENSITY_CAP_M) / (HAZARD_DENSITY_TAIL_END_M - HAZARD_DENSITY_CAP_M), 0, 1);
    return {
      slopeVariance: 1 + 0.5 * Math.min(ramp, 2),
      hazardDensity: 0.8 + 1.3 * Math.min(ramp, 1) + tail,
      glitchFrequency: 1 + 0.6 * Math.min(ramp, 1.5),
      noiseWeightMul: 1 + 1.5 * Math.min(ramp, 2),
      sector: sector + 1,
      speedBudget: expectedSpeedPxS(sector * SECTOR_M),
    };
  }

  // ------------------------------------------------------------------------------------------- streaming helpers

  _newChunk() {
    return {
      index: -1, defId: '', kind: 'spline', startX: 0, endX: 0, points: [],
      zones: [], gaps: [], bouncePads: [], hazards: [], powerups: [], shards: [], launches: [], sector: 1, breather: false,
    };
  }

  _addChunk(index, addedOut) {
    this._boundAt(index);
    let target;
    if (this.pool.length) {
      target = this.pool.pop();
      this.stats.reused++;
    } else {
      target = this._newChunk();
      this.stats.created++;
    }
    this._build(index, target);
    this.active.set(index, target);
    this.activeList.push(target);
    addedOut.push(target);
    return target;
  }

  _fillAhead(needX, addedOut) {
    const list = this.activeList;
    let guard = 64;
    while (list[list.length - 1].endX < needX && guard-- > 0) {
      this._addChunk(list[list.length - 1].index + 1, addedOut);
    }
  }

  /** Index of the chunk containing world x (builds bounds as needed, scratch only). */
  _indexForX(x) {
    while (this.bounds[this.bounds.length - 1].startX <= x) this._boundAt(this.bounds.length);
    let lo = 0;
    let hi = this.bounds.length - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (this.bounds[mid].startX <= x) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }

  _chunkAt(x) {
    const last = this._lastChunk;
    if (last && x >= last.startX && x <= last.endX) return last;
    const list = this.activeList;
    if (list.length === 0) {
      const added = [];
      this._addChunk(this._indexForX(x), added);
      this._pendingAdded.push(...added);
    }
    // slightly beyond the live window: extend (reported as `added` by the next update())
    if (x > list[list.length - 1].endX && x <= list[list.length - 1].endX + 4 * this.screenW) {
      this._fillAhead(x + 1, this._pendingAdded);
    }
    if (x >= list[0].startX && x <= list[list.length - 1].endX) {
      let lo = 0;
      let hi = list.length - 1;
      while (lo < hi) {
        const mid = (lo + hi + 1) >> 1;
        if (list[mid].startX <= x) lo = mid;
        else hi = mid - 1;
      }
      this._lastChunk = list[lo];
      return list[lo];
    }
    // far outside the live window (far behind after a respawn, or far ahead): temporary rebuild
    const idx = this._indexForX(x);
    if (!this._tempChunk || this._tempChunk.index !== idx) {
      this._tempChunk = this._newChunk();
      this._build(idx, this._tempChunk);
    }
    return this._tempChunk;
  }

  _segIndex(c, x) {
    const p = c.points;
    const sp = p[1].x - p[0].x;
    let i = Math.floor((x - c.startX) / sp);
    if (i < 0) i = 0;
    else if (i > p.length - 2) i = p.length - 2;
    return i;
  }

  _boundAt(index) {
    while (this.bounds.length <= index) {
      const k = this.bounds.length - 1;
      this._build(k, this._scratchChunk); // pushes bounds[k+1]
    }
    return this.bounds[index];
  }

  _packSize(packNo) {
    return Math.min(2 + Math.floor(packNo / 2), 5);
  }

  _ensureScratch(n) {
    if (this._cap >= n) return;
    this._cap = n;
    this._raw = new Float64Array(n);
    this._ys = new Float64Array(n);
  }

  // ------------------------------------------------------------------------------------------------ chunk build

  _eligible(list, distM) {
    const out = [];
    for (const d of list) {
      if ((d.minDistanceM || 0) <= distM && (d.maxDistanceM == null || distM <= d.maxDistanceM)) out.push(d);
    }
    return out;
  }

  _sectorOf(startX) {
    return Math.floor(startX / this.ppm / SECTOR_M) + 1;
  }

  /**
   * Biome of a chunk, or null for arcade (a bridge, or content-free). A chunk is assigned by its START, which
   * keeps the assignment a pure function of the chunk's own start position (and of facts about its own sector's
   * chunks, which are themselves a function of the seed): see biomeAtPosition for the bridge rule. A chunk starting
   * inside a bridge window is built as arcade first (`_arcadeEndPx`) to learn whether it would overrun the cap.
   * A biome id with no definition in `biomeDefs` is treated as arcade, so a generator built without biome
   * content is unchanged.
   * @param {{startX:number}} b
   * @param {number} index chunk index.
   * @returns {string|null}
   */
  _biomeForChunk(b, index) {
    if (!this.biomeDefs.length) return null;
    const startM = b.startX / this.ppm;
    const first = this._isBreather(index, b);
    let id = biomeAtPosition(this.seed, startM, this.biomeMask, this.biomeDefs, first);
    if (id === null && !first) {
      // inside the window of a bridging sector: arcade only if this chunk keeps the bridge under its cap
      let j = index;
      while (j > 0 && !this._isBreather(j, this.bounds[j])) j--;
      id = biomeAtPosition(this.seed, startM, this.biomeMask, this.biomeDefs, {
        runStartM: this.bounds[j].startX / this.ppm, endM: this._arcadeEndPx(b, index) / this.ppm,
      });
    }
    return id && this.biomeDefs.some((d) => d.id === id) ? id : null;
  }

  /**
   * Where chunk `index` would end if it were built as arcade (no biome preference): the def pick and the length
   * draw replayed on their own forks of the chunk's seed, exactly as `_build` makes them, so it is the real end
   * of the chunk whenever the chunk does come out arcade. Scratch only: touches no generator state.
   * @returns {number} world px.
   */
  _arcadeEndPx(b, index) {
    const distM = b.startX / this.ppm;
    const crng = new Rng(hashInts(this.seedState, index + 1));
    const def = this._pickDef(index, b, distM, this.difficultyAt(distM), crng.fork('plan'), null);
    const kind = def.kind === 'noise' || def.kind === 'bridge' ? def.kind : 'spline';
    const shape = crng.fork('shape');
    const n = this._segmentCount(def, kind, index, b, shape);
    return b.startX + (def === JUMP_DEF ? this._jumpAngles(index, b, distM, shape).length : n) * SPACING_PX;
  }

  /**
   * Segment count of a non-jump chunk of `def`: the length jitter is drawn from `shape` first (always, as it was
   * before the bridge rule needed it separately), then the length follows from the def, the pack's growth and it.
   */
  _segmentCount(def, kind, index, b, shape) {
    const scale = kind === 'spline' ? Math.min(1.6, 1 + 0.08 * b.packNo) : 1;
    const jitterLen = index === 0 ? 1 : shape.range(0.8, 1.2);
    if (kind === 'bridge') return Math.max(30, Math.round(def.lengthPx / SPACING_PX));
    return Math.max(10, Math.round((def.lengthPx * scale * jitterLen) / SPACING_PX));
  }

  /**
   * Biome at world x, as the chunk containing x is built (the same answer the terrain uses). Builds chunk
   * bounds as needed, scratch only. Every consumer that colours or announces "the biome we are in" asks this.
   * @param {number} x world px.
   * @returns {string|null} biome id, or null for an arcade bridge.
   */
  biomeAtX(x) {
    const i = this._indexForX(Math.max(0, x));
    return this._biomeForChunk(this.bounds[i], i);
  }

  /**
   * The arcade bridge that contains world x, as the generator built it (whole chunks: the same answer biomeAtX gives),
   * or null when x is not on a bridge. Read-only and scratch only (builds chunk bounds as needed), so the presentation
   * layer (#65 dissolve / reconstruct) can key a look to the sled's x without touching generation. `fromId` is the
   * biome the bridge leaves and `toId` the one it enters (null only where no biome borders it).
   * @param {number} x world px.
   * @returns {{startX:number, endX:number, fromId:string|null, toId:string|null}|null}
   */
  bridgeSpanAt(x) {
    if (!this.biomeDefs.length) return null;
    const idAt = (i) => this._biomeForChunk(this._boundAt(i), i);
    const at = this._indexForX(Math.max(0, x));
    if (idAt(at) !== null) return null;
    let a = at;
    for (let guard = 0; a > 0 && guard < BRIDGE_SCAN_MAX_CHUNKS && idAt(a - 1) === null; guard++) a--;
    let z = at;
    for (let guard = 0; guard < BRIDGE_SCAN_MAX_CHUNKS && idAt(z + 1) === null; guard++) z++;
    return {
      startX: this._boundAt(a).startX,
      endX: this._boundAt(z + 1).startX,
      fromId: a > 0 ? idAt(a - 1) : null,
      toId: idAt(z + 1),
    };
  }

  /** The first chunk that starts inside a new sector is a calm "breather". */
  _isBreather(index, b) {
    return index > 0 && this._sectorOf(b.startX) > this._sectorOf(this.bounds[index - 1].startX);
  }

  _pickDef(index, b, distM, diff, plan, biomeDef) {
    if (index === 0) return JUMP_DEF; // gentle opening: speed-building run into one easy jump
    const breather = this._isBreather(index, b);
    if (!breather && b.pos >= b.packSize) {
      const noise = this._eligible(this.noiseDefs, distM);
      const pick = plan.weighted(noise, (d) => (d.weight || 1) * diff.noiseWeightMul);
      if (pick) return pick;
    }
    let cand = this._eligible(this.splineDefs, distM);
    // Biome flavour: inside a biome sector prefer that biome's chunk templates. This is a PREFERENCE,
    // not a filter - if the templates are not eligible at this distance (or absent) the sector still
    // gets ordinary terrain, so a biome can never create a hole in the ramp.
    if (biomeDef && !breather) {
      const ids = biomeDef.chunks || [];
      const flavoured = cand.filter((d) => ids.includes(d.id));
      if (flavoured.length) cand = flavoured;
    }
    if (breather) {
      const calm = cand.filter((d) => d.tags && d.tags.some((t) => t === 'recover' || t === 'cruise' || t === 'roller' || t === 'intro'));
      if (calm.length) cand = calm;
    } else {
      const p = clamp((b.sinceLaunch - 300) / 500, 0, 1);
      if (!b.prevJump && b.prevKind !== 'bridge' && plan.chance(p)) return JUMP_DEF;
      if (index >= 2 && b.prevKind !== 'bridge') cand = cand.concat(this._eligible(this.bridgeDefs, distM));
    }
    const pick = plan.weighted(cand, (d) => d.weight || 1);
    if (pick) return pick;
    const fallback = this.splineDefs.slice().sort((a, c) => (a.minDistanceM || 0) - (c.minDistanceM || 0));
    return fallback[0];
  }

  /**
   * Fill `target` with chunk `index` and push bounds[index+1] if it does not exist yet.
   * @returns {import('../data/schemas.js').TerrainChunk}
   */
  _build(index, target) {
    this.stats.built++;
    const b = this.bounds[index];
    const distM = b.startX / this.ppm;
    const diff = this.difficultyAt(distM);
    const crng = new Rng(hashInts(this.seedState, index + 1));
    const plan = crng.fork('plan');
    const shape = crng.fork('shape');
    const biome = this._biomeForChunk(b, index);
    const biomeDef = biome ? this.biomeDefs.find((d) => d.id === biome) : null;
    const def = this._pickDef(index, b, distM, diff, plan, biomeDef);
    const kind = def.kind === 'noise' || def.kind === 'bridge' ? def.kind : 'spline';
    const isJump = def === JUMP_DEF;
    const breather = this._isBreather(index, b);
    const sharp = isJump || (def.tags && def.tags.some((t) => SHARP_TAGS.includes(t)));

    let n = this._segmentCount(def, kind, index, b, shape);
    this._ensureScratch(n + 2);
    let L = n * SPACING_PX;
    const raw = this._raw;
    let ys = this._ys;
    const limits = kind === 'noise'
      ? { down: MAX_NOISE_DOWN_DEG, up: MAX_NOISE_UP_DEG, turn: MAX_NOISE_TURN_DEG, crest: NOISE_CREST_TURN_DEG }
      : { down: MAX_DOWN_DEG, up: MAX_UP_DEG, turn: MAX_TURN_DEG, crest: sharp ? MAX_TURN_DEG : CREST_TURN_DEG };

    const variance = index === 0 ? 0.6 : diff.slopeVariance;
    let gi0 = -1;
    let gi1 = -1;
    let endAng;
    if (isJump) {
      const ja = this._jumpAngles(index, b, distM, shape);
      n = ja.length;
      L = n * SPACING_PX;
      this._ensureScratch(n + 2);
      const jy = this._ys;
      jy[0] = b.startY;
      for (let i = 0; i < n; i++) jy[i + 1] = jy[i] + pmath.tan(ja[i] * RAD) * SPACING_PX;
      endAng = ja[n - 1];
      ys = jy;
    } else if (kind === 'noise') {
      this._noiseProfile(def, shape, n, L, variance);
      this._limitRise(raw, n, b);
      endAng = this._finishSafe(raw, n, b, limits, ys);
    } else {
      this._bezierProfile(def, shape, n, L, variance, index === 0 ? 0.6 : L / def.lengthPx);
      if (kind !== 'bridge') this._limitRise(raw, n, b);
      if (kind === 'bridge') {
        const br = def.bridge || { gapPx: 176, bounceBoost: 420 };
        let gapSegs = Math.round(clamp(br.gapPx * (1 + 0.08 * Math.min(1, Math.max(0, (distM - 200) / 2000))), 64, 224) / SPACING_PX);
        gi0 = Math.max(10, Math.floor(n * 0.3));
        if (gi0 + gapSegs > n - 14) gapSegs = Math.max(4, n - 14 - gi0);
        gi1 = gi0 + gapSegs;
        const a1 = this._finish(raw, 0, gi0, b.startY, b.startAngDeg, limits, ys);
        const gapW = gapSegs * SPACING_PX;
        const drop = gapW * shape.range(0.28, 0.38);
        const yEnd = ys[gi0] + drop;
        for (let i = gi0 + 1; i < gi1; i++) ys[i] = ys[gi0] + ((yEnd - ys[gi0]) * (i - gi0)) / gapSegs;
        ys[gi1] = yEnd;
        endAng = this._finish(raw, gi1, n, yEnd, Math.min(a1, 14), limits, ys);
      } else {
        endAng = this._finishSafe(raw, n, b, limits, ys);
      }
    }

    // ---- write chunk geometry
    const startX = b.startX;
    target.index = index;
    target.defId = def.id;
    target.kind = kind;
    target.startX = startX;
    target.endX = startX + L;
    const pts = target.points;
    for (let i = 0; i <= n; i++) {
      const p = pts[i];
      if (p) { p.x = startX + i * SPACING_PX; p.y = ys[i]; } else pts.push({ x: startX + i * SPACING_PX, y: ys[i] });
    }
    pts.length = n + 1;
    target.zones.length = 0;
    target.gaps.length = 0;
    target.bouncePads.length = 0;
    target.hazards.length = 0;
    target.powerups.length = 0;
    target.shards.length = 0;
    target.launches.length = 0;
    target.sector = this._sectorOf(startX);
    target.breather = breather;
    // Present only when the chunk is inside a biome. Keeping the field absent (rather than null) for
    // base terrain is deliberate: it makes mask-0 chunks byte-identical under JSON.stringify, which is
    // what the pre-existing hazard-fill digest test compares - an additive `biome: null` would have
    // tripped a regression guard that has nothing to do with biomes. Chunk objects are pooled, so a
    // recycled chunk MUST have the field cleared or it would keep the previous sector's biome.
    if (biome) target.biome = biome;
    else if (target.biome !== undefined) delete target.biome;

    if (kind === 'bridge') {
      const br = def.bridge || { gapPx: 176, bounceBoost: 420 };
      const x0 = startX + gi0 * SPACING_PX;
      const x1 = startX + gi1 * SPACING_PX;
      target.gaps.push({ x0, x1 });
      const padC = x0 - 40;
      target.bouncePads.push({ x: padC, y: this._yAtLocal(pts, padC), width: 48, boost: br.bounceBoost });
      const mod = this.modMap.wirelessBridge;
      if (mod) {
        target.zones.push({ modId: 'wirelessBridge', x0: Math.max(startX + SPACING_PX, padC - 56), x1: Math.min(target.endX - SPACING_PX, x1 + 48) });
      }
    } else {
      // E7 (Marvin 2026-11-14, audit TERRAIN-1): a chunk that hosts a biome zone gets NO template zone, so the biome's
      // mechanic is never multiplied into its opposite (stickyPatch x highBandwidth = slippery). The biome zone is placed
      // first only to know whether it landed; both passes draw from their own forks, so the order moves no stream, and a
      // base chunk (biomeDef null, every mask-0 chunk) runs _placeZones exactly as before.
      const hosted = biomeDef ? this._placeBiomeZone(target, biomeDef, crng.fork('biomeZone'), distM) : false;
      if (!hosted) this._placeZones(target, def, crng.fork('zone'), distM, L);
    }
    this._applySwell(target);
    const vExp = expectedSpeedPxS(distM);
    const lips = kind === 'bridge' ? this._padLips(target, vExp) : this._findLips(target.points, isJump ? Math.min(vExp, JUMP_LAUNCH_SPEED_PX_S) : vExp * TEMPLATE_LIP_SPEED_MUL, target.endX);
    let landEnd = 0;
    for (const l of lips) {
      if (!l.pad) {
        target.launches.push({ x: l.x, y: l.y, angleDeg: -pmath.atan2(l.vy, l.vx) * DEG, airS: l.airS, landX: l.landX });
      }
      landEnd = Math.max(landEnd, l.zoneEnd);
    }
    this._placeHazards(target, crng.fork('haz'), distM, diff, kind, b, isJump, breather, lips);
    this._placePowerups(target, crng.fork('pu'), distM);
    this._placeShards(target, crng.fork('shard'), distM, lips);
    this._placeAirHazard(target, crng.fork('air'), distM, isJump, breather, lips);
    // B0: biome hazards / power-ups, LAST and only inside a biome chunk, from their own forks (spec §5). A fork derives
    // from crng's initial state, so creating these never moves any stream above; base chunks never reach this line.
    if (biome) this._placeBiomeSpawns(target, biome, crng.fork('biomeHaz'), crng.fork('biomePu'), distM, kind, b, isJump, breather, lips);

    if (this.bounds.length === index + 1) {
      let pos = b.pos + 1;
      let packNo = b.packNo;
      let packSize = b.packSize;
      if (pos > packSize) {
        packNo++;
        pos = 0;
        packSize = this._packSize(packNo);
      }
      const rs = this._riseState(ys, n, b);
      this.bounds.push({
        startX: target.endX, startY: ys[n], startAngDeg: endAng, packNo, pos, packSize, prevKind: kind,
        peakDx: rs.peakDx, peakDy: rs.peakDy, valDy: rs.valDy,
        sinceLaunch: lips.length ? Math.max(0, target.endX - lips[lips.length - 1].x) : b.sinceLaunch + L,
        prevJump: isJump,
        speed: Math.min(150, this._roll(ys, n, b.speed).end), // capped: slow hazards / crashes can bleed speed the roll model never saw
        noHazX: Math.max(landEnd > target.endX ? landEnd : 0, b.noHazX > target.endX ? b.noHazX : 0),
      });
    }
    return target;
  }

  _yAtLocal(pts, x) {
    const sp = pts[1].x - pts[0].x;
    let i = Math.floor((x - pts[0].x) / sp);
    i = clamp(i, 0, pts.length - 2);
    const a = pts[i];
    const c = pts[i + 1];
    return a.y + ((c.y - a.y) * (x - a.x)) / (c.x - a.x);
  }

  // ------------------------------------------------------------------------------------------ jumps and lips

  /**
   * Per-segment slope angles (deg, + = descending) of a generated launch chunk: speed-building approach, compression
   * ramp, three-segment lip, sharp fall-away onto a long down-slope landing ramp (length sized for the expected speed
   * so the trajectory lands ON it, 1.0-1.6 s of air at cruise), then a smooth runout. The whole chunk is hazard free.
   */
  _jumpAngles(index, b, distM, shape) {
    const first = index === 0;
    const vExp = expectedSpeedPxS(distM);
    const alpha = MAX_UP_DEG;
    const beta = first ? 36 : 36 + 6 * Math.min(1, distM / 1500);
    const approach = first ? 24 : JUMP_APPROACH_DEG + shape.range(-1, 1);
    const angs = [];
    let cur = b.startAngDeg;
    const move = (target, up, down) => {
      let guard = 80;
      while (Math.abs(target - cur) > 1e-6 && guard-- > 0) {
        cur += clamp(target - cur, -down, up);
        angs.push(cur);
      }
    };
    const hold = (px) => {
      const k = Math.ceil(px / SPACING_PX);
      for (let i = 0; i < k; i++) angs.push(cur);
    };
    move(approach, CREST_TURN_DEG, MAX_TURN_DEG);
    const approachPx = first ? JUMP_APPROACH_FIRST_PX : JUMP_APPROACH_PX + shape.range(0, 100);
    hold(Math.max(0, approachPx - angs.length * SPACING_PX));
    move(-alpha, 0, 10); // compression ramp
    hold(4 * SPACING_PX); // lip (the first one is long: the mesh rounds the crest, so a short lip launches flat)
    move(beta, LIP_TURN_DEG, LIP_TURN_DEG); // sharp fall-away: ground drops clear of the trajectory at once
    // landing ramp long enough for the fastest plausible launch (1.2 x expected) to touch down on it
    const vmax = first ? 470 : Math.max(JUMP_LAUNCH_SPEED_PX_S * 1.25, vExp * 1.1);
    const ca = pmath.cos(alpha * RAD);
    const k = GRAV / (2 * vmax * vmax * ca * ca);
    const xHit = (pmath.tan(beta * RAD) + pmath.tan(alpha * RAD)) / k;
    hold(Math.min(first ? 560 : 1300, xHit * 0.9 + 64));
    move(9, 0, RUNOUT_TURN_DEG); // long smooth concave runout
    hold(JUMP_RUNOUT_PX);
    return angs;
  }

  /** Ballistic flight from (x0,y0) over this chunk's polyline. @returns {{t:number, x:number}|null} null = leaves the chunk. */
  _flight(pts, x0, y0, vx, vy) {
    const xEnd = pts[pts.length - 1].x;
    for (let t = 0.03; t < 2.4; t += 0.03) {
      const x = x0 + vx * t;
      if (x >= xEnd) return null;
      const y = y0 + vy * t + 0.5 * GRAV * t * t;
      if (t > 0.09 && y >= this._yAtLocal(pts, x) - 1.5) return { t, x };
    }
    return { t: 2.4, x: x0 + vx * 2.4 };
  }

  /**
   * Launch points of a (non-bridge) chunk: convex slope breaks from which a sled at the expected speed stays airborne
   * >= LIP_MIN_AIR_S. Each lip carries its launch velocity, airtime, landing x (null = beyond the chunk) and the end of
   * its hazard-free landing zone.
   */
  _findLips(pts, vExp, endX) {
    const lips = [];
    const n = pts.length;
    const ang = (k) => pmath.atan2(pts[k + 1].y - pts[k].y, pts[k + 1].x - pts[k].x) * DEG;
    let skipTo = -Infinity;
    for (let i = 3; i < n - 2; i++) {
      if (pts[i].x <= skipTo) continue;
      const a0 = (ang(i - 3) + ang(i - 2) + ang(i - 1)) / 3;
      const a1 = (ang(i) + ang(i + 1)) / 2;
      if (a1 - a0 < 7) continue;
      const inc = ang(i - 1);
      const vx = vExp * pmath.cos(inc * RAD);
      const vy = vExp * pmath.sin(inc * RAD);
      const f = this._flight(pts, pts[i].x, pts[i].y, vx, vy);
      const air = f ? f.t : 1.6;
      if (air < LIP_MIN_AIR_S) continue;
      const landX = f ? f.x : null;
      lips.push({ x: pts[i].x, y: pts[i].y, vx, vy, airS: air, landX, zoneEnd: landX == null ? pts[i].x + Math.max(vx * 1.8 + 160, 800) : landX + 160 });
      skipTo = landX == null ? Infinity : landX;
    }
    return lips;
  }

  /** Bounce-pad launch of a bridge chunk (shard arcs only; not reported in chunk.launches). */
  _padLips(chunk, vExp) {
    const out = [];
    for (const p of chunk.bouncePads) {
      const g = chunk.gaps[0];
      out.push({ x: p.x, y: p.y, vx: vExp * 0.75, vy: -p.boost, airS: 1, landX: g ? g.x1 : null, zoneEnd: g ? g.x1 + 160 : p.x, pad: true });
    }
    return out;
  }

  // ----------------------------------------------------------------------------------------------- profiles

  /** Fill this._raw[0..n] (relative to raw[0]=0) from a bezier template with seeded control-point noise. */
  _bezierProfile(def, shape, n, L, variance, yScale) {
    let cps = def.controlPoints;
    if (!cps || cps.length < 2) cps = BUILTIN_DEF.controlPoints;
    const m = Math.min(cps.length, 15);
    if (this._cx.length < m) { this._cx = new Float64Array(m); this._cy = new Float64Array(m); }
    const cx = this._cx;
    const cy = this._cy;
    const jit = (def.jitterPx != null ? def.jitterPx : 12) * yScale * variance * variance;
    for (let i = 0; i < m; i++) {
      let x = clamp(cps[i].x, 0, 1);
      let y = cps[i].y * yScale;
      if (i > 0 && i < m - 1) {
        x += shape.range(-0.03, 0.03);
        y += shape.range(-1, 1) * jit;
      }
      cx[i] = x;
      cy[i] = y;
    }
    cx[0] = 0;
    cx[m - 1] = 1;
    for (let i = 1; i < m; i++) if (cx[i] < cx[i - 1]) cx[i] = cx[i - 1];
    // variance: stretch the template vertically (steeper) on top of the larger seeded jitter above
    const stretch = 1 + 0.35 * (variance - 1);
    for (let i = 0; i < m; i++) cy[i] *= stretch;
    // Piecewise cubic bezier through the control points (Catmull-Rom tangents converted to bezier handles), densely
    // sampled. Handle x's are clamped so x(t) stays monotone inside every piece.
    const SUB = 24;
    const tx = this._tx;
    const ty = this._ty;
    let cnt = 0;
    tx[cnt] = cx[0] * L;
    ty[cnt++] = cy[0];
    for (let i = 0; i < m - 1; i++) {
      const im = i > 0 ? i - 1 : 0;
      const ip = i + 2 < m ? i + 2 : m - 1;
      const dx = cx[i + 1] - cx[i];
      const c1x = clamp(cx[i] + (cx[i + 1] - cx[im]) / 6, cx[i], cx[i] + dx * 0.5);
      const c1y = cy[i] + (cy[i + 1] - cy[im]) / 6;
      const c2x = clamp(cx[i + 1] - (cx[ip] - cx[i]) / 6, cx[i + 1] - dx * 0.5, cx[i + 1]);
      const c2y = cy[i + 1] - (cy[ip] - cy[i]) / 6;
      for (let k = 1; k <= SUB; k++) {
        const t = k / SUB;
        const u = 1 - t;
        const b0 = u * u * u;
        const b1 = 3 * u * u * t;
        const b2 = 3 * u * t * t;
        const b3 = t * t * t;
        tx[cnt] = (b0 * cx[i] + b1 * c1x + b2 * c2x + b3 * cx[i + 1]) * L;
        ty[cnt++] = b0 * cy[i] + b1 * c1y + b2 * c2y + b3 * cy[i + 1];
      }
    }
    const raw = this._raw;
    let s = 0;
    for (let i = 0; i <= n; i++) {
      const x = i * SPACING_PX;
      while (s < cnt - 2 && tx[s + 1] < x) s++;
      const dx = tx[s + 1] - tx[s];
      const f = dx > 1e-9 ? clamp((x - tx[s]) / dx, 0, 1) : 0;
      raw[i] = ty[s] + (ty[s + 1] - ty[s]) * f;
    }
    const base = raw[0];
    for (let i = 0; i <= n; i++) raw[i] -= base;
  }

  /**
   * Flow rule (see RISE_LINE_DEG): raise (lower on screen) any raw height that would climb above the allowed line.
   * Works on heights relative to the chunk start (raw[0] = 0); peak/valley state comes from the incoming bound.
   */
  _limitRise(raw, n, b) {
    let peakX = -b.peakDx;
    let peakY = b.peakDy;
    let valY = b.valDy;
    let dir = 1;
    let prev = raw[0];
    for (let i = 1; i <= n; i++) {
      const x = i * SPACING_PX;
      let y = raw[i];
      const floor = Math.max(peakY + RISE_LINE_TAN * (x - peakX), valY - RISE_MAX_PX);
      if (y < floor) y = floor;
      raw[i] = y;
      if (y < prev) dir = -1;
      else if (y > prev) {
        if (dir < 0) { peakX = (i - 1) * SPACING_PX; peakY = prev; valY = prev; }
        dir = 1;
        if (y > valY) valY = y;
      }
      prev = y;
    }
  }

  /** Peak / valley state at the end of a built chunk (final heights), relative to its end point, for the next chunk. */
  _riseState(ys, n, b) {
    let peakX = -b.peakDx;
    let peakY = b.peakDy;
    let valY = b.valDy;
    let dir = 1;
    const y0 = ys[0];
    let prev = 0;
    for (let i = 1; i <= n; i++) {
      const y = ys[i] - y0;
      if (y < prev) dir = -1;
      else if (y > prev) {
        if (dir < 0) { peakX = (i - 1) * SPACING_PX; peakY = prev; valY = prev; }
        dir = 1;
        if (y > valY) valY = y;
      }
      prev = y;
    }
    const yEnd = ys[n] - y0;
    return { peakDx: n * SPACING_PX - peakX, peakDy: peakY - yEnd, valDy: valY - yEnd };
  }

  /** Fill this._raw[0..n] with a noise-zone profile: mean slope + fbm value noise, faded in/out at the ends. */
  _noiseProfile(def, shape, n, L, variance) {
    const nz = def.noise || { amplitudePx: 24, frequency: 0.006, octaves: 3, meanSlopeDeg: 14 };
    const seed = (shape.next() * 4294967296) >>> 0;
    const amp = nz.amplitudePx * Math.min(variance, 1.6);
    const octaves = clamp(Math.floor(nz.octaves || 2), 1, 5);
    const mean = pmath.tan(clamp(nz.meanSlopeDeg || 12, 4, 30) * RAD);
    const fade = Math.min(160, L * 0.3);
    const raw = this._raw;
    for (let i = 0; i <= n; i++) {
      const x = i * SPACING_PX;
      let v = 0;
      let a = 1;
      let f = nz.frequency;
      let norm = 0;
      for (let o = 0; o < octaves; o++) {
        v += a * vnoise(x * f, seed + o * 101);
        norm += a;
        a *= 0.35;
        f *= 2;
      }
      const env = smooth(clamp(x / fade, 0, 1)) * smooth(clamp((L - x) / fade, 0, 1));
      raw[i] = x * mean + env * amp * (v / norm);
    }
    const base = raw[0];
    for (let i = 0; i <= n; i++) raw[i] -= base;
  }

  /**
   * Anti-stall at any distance: run the 1-D roll model (65 % of g sin(slope), linear + quadratic drag, entry speed carried
   * in bounds[].speed) over the finished chunk and, while it would crawl below STALL_SPEED_PX_S, add extra uniform descent.
   */
  _finishSafe(raw, n, b, limits, ys) {
    let extra = 0;
    let endAng = 0;
    for (let iter = 0; iter < 7; iter++) {
      endAng = this._finish(raw, 0, n, b.startY, b.startAngDeg, limits, ys, extra);
      if (this._roll(ys, n, b.speed).min >= STALL_SPEED_PX_S) break;
      extra += 28 + 8 * iter;
    }
    return endAng;
  }

  /** 1-D roll along ys[0..n]. @returns {{min:number, end:number}} slowest and final speed (px/s). */
  _roll(ys, n, v0) {
    let v = v0;
    let min = v0;
    for (let i = 0; i < n; i++) {
      const dy = ys[i + 1] - ys[i];
      const len = pmath.hypot(SPACING_PX, dy);
      const sin = dy / len;
      const dt = len / Math.max(v, 25);
      v += (585 * sin - 0.3 * v - 0.0004 * v * v) * dt;
      if (v < 0) v = 0;
      if (v > 900) v = 900;
      if (v < min) min = v;
    }
    return { min, end: v };
  }

  /**
   * Shared post-processing for points i0..i1 (indices into raw/out). Writes out[i0..i1], out[i0] = startY.
   * @returns {number} slope angle (deg) of the last segment.
   */
  _finish(raw, i0, i1, startY, prevAngDeg, limits, out, extraLift = 0) {
    const segs = i1 - i0;
    const Lseg = segs * SPACING_PX;
    out[i0] = startY;
    if (segs <= 0) return prevAngDeg;
    const rawStart = (raw[i0 + 1] - raw[i0]) / SPACING_PX;
    const delta = pmath.tan(prevAngDeg * RAD) - rawStart;
    const B = Math.min(220, Lseg * 0.5);
    const net = raw[i1] - raw[i0];
    const need = Lseg * MIN_NET_TAN;
    // blended heights relative to start
    const corr = (x) => (x >= B ? 0 : delta * x * (1 - x / B) * (1 - x / B));
    const endCorr = corr(Lseg);
    let lift = (net + endCorr < need ? need - (net + endCorr) : 0) + extraLift;
    const lo = -limits.up;
    const hi = limits.down;
    const crest = limits.crest || limits.turn;
    let prev = prevAngDeg;
    // the crest limiter lags convex transitions (terrain stays higher), so re-run with more lift until the net descent holds
    for (let iter = 0; iter < 6; iter++) {
      prev = prevAngDeg;
      let y = startY;
      let lastRel = 0;
      for (let i = i0 + 1; i <= i1; i++) {
        const x = (i - i0) * SPACING_PX;
        const rel = raw[i] - raw[i0] + corr(x) + (lift * x) / Lseg;
        let ang = pmath.atan2(rel - lastRel, SPACING_PX) * DEG;
        lastRel = rel;
        if (ang > hi) ang = hi;
        else if (ang < lo) ang = lo;
        // the first segment of a chunk never turns by more than MAX_TURN_DEG (noise chunks used to allow 17 at the seam)
        const first = i === i0 + 1;
        const up = first ? Math.min(crest, MAX_TURN_DEG) : crest;
        const down = first ? Math.min(limits.turn, MAX_TURN_DEG) : limits.turn;
        if (ang > prev + up) ang = prev + up;
        else if (ang < prev - down) ang = prev - down;
        y += pmath.tan(ang * RAD) * SPACING_PX;
        out[i] = y;
        prev = ang;
      }
      const short = need - (out[i1] - startY);
      if (short <= 0.5) break;
      lift += short;
    }
    return prev;
  }

  // ------------------------------------------------------------------------------------------------- spawns

  /**
   * The biome's signature mechanic, as a zone inside a biome sector. Bounded length, never the whole
   * chunk, and never overlapping an existing zone of the same mod. Uses its own forked stream so it
   * cannot shift hazards, shards or power-ups.
   * @param {import('../data/schemas.js').TerrainChunk} chunk
   * @param {{id:string, mod:string}} biomeDef
   * @param {import('./Rng.js').Rng} rng
   * @param {number} distM
   * @returns {boolean} true when a biome zone was placed (E7: the chunk then gets no template zone).
   */
  _placeBiomeZone(chunk, biomeDef, rng, distM) {
    const m = this.modMap[biomeDef.mod];
    if (!m) return false;
    if ((m.minDistanceM || 0) > distM) return false;
    const range = m.lengthPx || [400, 800];
    const maxLen = chunk.endX - chunk.startX - 2 * 96;
    if (maxLen < 160) return false;
    if (!rng.chance(0.75)) return false;
    const len = Math.min(maxLen, Math.round(rng.range(range[0], range[1])));
    const x0 = Math.round(chunk.startX + rng.range(96, chunk.endX - chunk.startX - len - 96));
    chunk.zones.push({ modId: m.id, x0, x1: x0 + len });
    return true;
  }

  _placeZones(chunk, def, rng, distM, L) {
    const ids = def.modIds || [];
    const cand = [];
    for (const id of ids) {
      const m = this.modMap[id];
      if (m && id !== 'wirelessBridge' && (m.minDistanceM || 0) <= distM) cand.push(m);
    }
    if (!cand.length || chunk.index === 0) return;
    if (!rng.chance(chunk.kind === 'noise' ? 0.3 : 0.5)) return;
    const m = rng.weighted(cand, (d) => d.weight || 1);
    if (!m) return;
    const range = m.lengthPx || [400, 800];
    const maxLen = L - 2 * 96;
    if (maxLen < 160) return;
    const len = Math.min(maxLen, Math.round(rng.range(range[0], range[1])));
    const x0 = Math.round(chunk.startX + rng.range(96, L - len - 96));
    chunk.zones.push({ modId: m.id, x0, x1: x0 + len });
  }

  _placeHazards(chunk, rng, distM, diff, kind, b, noHazards, breather, lips) {
    if (!this.hazardList.length || kind === 'bridge' || noHazards) return;
    // smooth ramp-in: 35 % of the nominal density at 75 m, full density from 600 m
    const rampIn = clamp(0.35 + (0.65 * (distM - 75)) / 525, 0.35, 1);
    const density = diff.hazardDensity * (kind === 'noise' ? 0.5 : 1) * rampIn * HAZARD_DENSITY_MUL;
    if (!(density > 0)) return;
    const mean = 1000 / density;
    const pts = chunk.points;
    let x = chunk.startX + HAZARD_END_MARGIN_PX + rng.range(0, mean * 0.5);
    const xEnd = chunk.endX - HAZARD_END_MARGIN_PX;
    const retry = distM >= HAZARD_RETRY_FROM_M;
    while (x <= xEnd) {
      let placed = false;
      const gapX = Math.max(HAZARD_MIN_SPACING_PX, rng.range(0.6, 1.4) * mean);
      x = Math.round(x);
      let free = x >= HAZARD_MIN_X_PX && x >= HAZARD_SOFT_PX && x >= b.noHazX && !(breather && x < chunk.startX + BREATHER_CALM_PX);
      if (free) for (const l of lips) if (x >= l.x - 40 && x <= l.zoneEnd) free = false;
      if (free) {
        const dM = x / this.ppm;
        const crashOk = x >= HAZARD_SAFE_PX;
        const def = rng.weighted(this.hazardList, (h) => ((h.minDistanceM || 0) <= dM && (crashOk || !h.onHit || h.onHit.effect !== 'crash') ? h.weight || 1 : 0));
        if (def) {
          const i = clamp(Math.floor((x - chunk.startX) / SPACING_PX), 0, pts.length - 2);
          const slope = pmath.atan2(pts[i + 1].y - pts[i].y, SPACING_PX) * DEG;
          const w = (def.size && def.size.w) || 24;
          const flatEnough = slope > -12 && slope < 28 && this._flatAround(pts, i);
          const slowOk = !def.onHit || def.onHit.effect !== 'slow' || this._descentAhead(pts, i, chunk.endX);
          if (flatEnough && slowOk && x - w > chunk.startX) {
            const hx = Math.round(x);
            chunk.hazards.push({ defId: def.id, x: hx, y: this._yAtLocal(pts, hx), rotationDeg: slope });
            placed = true;
          }
        }
      }
      x += retry && !placed ? HAZARD_RETRY_STEP_PX : gapX;
    }
  }

  // ------------------------------------------------------------------------------------------------- air hazards

  /**
   * Ballistic y of the nominal flight scaled to `mul` x the launch speed, `dx` px after the lip (g = 900, y down).
   * @param {{y:number, vx:number, vy:number}} lip
   */
  _arcY(lip, mul, dx) {
    return lip.y + (lip.vy / lip.vx) * dx + (GRAV * dx * dx) / (2 * mul * mul * lip.vx * lip.vx);
  }

  /**
   * At most one air hazard per generated jump, in the flight arc. Placed LAST (after powerups and shards) from its own fork,
   * so ground terrain, ground hazards, power-ups and shards of a seed are not affected by its random draws.
   * Spawn contract for placement 'air': `y` is the CENTRE of the hazard (Hazard.js), rotationDeg 0. The hit box bottom is
   * >= AIR_CLEARANCE_PX above the highest no-hop arc (see AIR_CLEARANCE_PX), late in the flight (see AIR_MIN_DX_PX).
   */
  _placeAirHazard(chunk, rng, distM, isJump, breather, lips) {
    // fixed number of draws so the stream is independent of the early returns below
    const rChance = rng.next();
    const rU = rng.next();
    const rExtra = rng.next();
    const rDef = rng.next();
    if (!this.airHazardList.length || !isJump || breather || chunk.index === 0) return;
    const s = this._airSpan(lips);
    if (!s) return;
    const { lip, lo, hi } = s;
    const lipM = lip.x / this.ppm;
    const p = AIR_CHANCE_START + (AIR_CHANCE_END - AIR_CHANCE_START) * clamp((lipM - AIR_HAZARD_MIN_M) / (AIR_CHANCE_FULL_M - AIR_HAZARD_MIN_M), 0, 1);
    if (lipM < AIR_HAZARD_MIN_M || rChance >= p) return;
    const hiMul = this._airHiMul(lip, distM);
    // two candidate positions (the second only when the first collides with a power-up / shard)
    for (const dxPick of [lo + (hi - lo) * rU, lo + (hi - lo) * ((rU + 0.5) % 1)]) {
      const x = Math.round(lip.x + dxPick);
      const def = this._pickAirDef(rDef, x / this.ppm);
      if (!def) return;
      if (this._tryAirBox(chunk, def, lip, hiMul, x, rExtra)) return;
    }
  }

  /**
   * The jump of a chunk that can hold an air hazard: its longest non-pad lip with a known landing, and the band of x offsets
   * past the lip where the box may go. Null when there is no such lip or the span cannot hold a box >= AIR_MIN_DX_PX past it.
   */
  _airSpan(lips) {
    let lip = null;
    for (const l of lips) if (!l.pad && l.landX != null && (!lip || l.airS > lip.airS)) lip = l;
    if (!lip || !(lip.vx > 0)) return null;
    const span = lip.landX - lip.x;
    const lo = Math.max(AIR_MIN_DX_PX, AIR_U_MIN * span);
    const hi = AIR_U_MAX * span;
    if (hi < lo) return null;
    return { lip, lo, hi };
  }

  /** Launch-speed multiple whose arc bounds every no-hop flight (see AIR_SPEED_HI_MUL). */
  _airHiMul(lip, distM) {
    return Math.max(AIR_SPEED_HI_MUL, expectedSpeedPxS(distM) / pmath.hypot(lip.vx, lip.vy));
  }

  /**
   * Place `def` as an air box at x above the flight arc of `lip` (AIR_CLEARANCE_PX over the fastest no-hop arc) unless it is
   * blocked (_airBlocked). Keeps `chunk.hazards` sorted by x. @returns {boolean} true when placed.
   */
  _tryAirBox(chunk, def, lip, hiMul, x, rExtra) {
    const w = (def.size && def.size.w) || 24;
    const h = (def.size && def.size.h) || 24;
    const crashy = !def.onHit || def.onHit.effect === 'crash';
    const bw = crashy ? w * 0.72 : w;
    const bh = crashy ? h * 0.8 : h;
    const dx = x - lip.x;
    // the arc bends a little across the box width: use its highest edge sample
    const highest = Math.min(this._arcY(lip, hiMul, dx - bw / 2), this._arcY(lip, hiMul, dx), this._arcY(lip, hiMul, dx + bw / 2));
    const cy = highest - AIR_CLEARANCE_PX - 6 - 18 * rExtra - bh / 2;
    if (this._airBlocked(chunk, x, cy, bw, bh)) return false;
    chunk.hazards.push({ defId: def.id, x, y: Math.round(cy * 100) / 100, rotationDeg: 0 });
    chunk.hazards.sort((a, b) => a.x - b.x);
    return true;
  }

  // ------------------------------------------------------------------------------------------------- biome spawns (B0)

  /**
   * One biome hazard slot and one biome power-up slot (spec §4/§5). Runs only for a chunk whose `biome` is set, AFTER every
   * base pass, from forks 'biomeHaz' / 'biomePu'. Each slot draws exactly BIOME_SLOT_DRAWS numbers up front, whatever
   * happens next, so a def's chance or a blocked position never shifts the other slot or a later chunk. With no biome defs in
   * content the pass places nothing.
   * Ground hazards keep the base clearances (no bridge or jump chunk, BIOME_EDGE_MARGIN_PX from the chunk edges, the
   * breather calm stretch, lip windows, b.noHazX, gaps, HAZARD_MIN_SPACING_PX from any hazard, 90 px from any power-up,
   * readable slope, slow hazards only before a descent, no shard over the box). Air hazards use the base jump-arc box.
   * @param {import('../data/schemas.js').TerrainChunk} chunk
   * @param {string} biome
   * @param {import('./Rng.js').Rng} hRng fork 'biomeHaz'
   * @param {import('./Rng.js').Rng} pRng fork 'biomePu'
   */
  _placeBiomeSpawns(chunk, biome, hRng, pRng, distM, kind, b, isJump, breather, lips) {
    const h0 = hRng.next(); const h1 = hRng.next(); const h2 = hRng.next(); const h3 = hRng.next(); const h4 = hRng.next();
    const p0 = pRng.next(); const p1 = pRng.next(); const p2 = pRng.next(); const p3 = pRng.next(); pRng.next();
    const hDefs = this.biomeHazards[biome];
    if (hDefs && chunk.index > 0) {
      const def = this._pickBiomeDef(hDefs, h1, distM);
      if (def && h0 < biomeChance(def, BIOME_HAZARD_MAX_CHANCE)) {
        if (def.placement === 'air') {
          const s = !isJump || breather ? null : this._airSpan(lips);
          if (s) {
            // B4: under a low-gravity zone the no-hop arcs are flatter; lift the box by the zone gravity (flightGravityMul)
            const hiMul = this._airHiMul(s.lip, distM) / Math.sqrt(flightGravityMul(chunk.zones, this.modMap, s.lip.x, s.lip.landX));
            for (const u of [h2, (h2 + 0.5) % 1]) {
              if (this._tryAirBox(chunk, def, s.lip, hiMul, Math.round(s.lip.x + s.lo + (s.hi - s.lo) * u), h3)) break;
            }
          }
        } else if (kind !== 'bridge' && !isJump) {
          const span = chunk.endX - chunk.startX - 2 * BIOME_EDGE_MARGIN_PX;
          const steps = span > 0 ? Math.floor(span / HAZARD_RETRY_STEP_PX) + 1 : 0;
          let placed = false;
          for (let k = 0; k < steps && !placed; k++) placed = this._tryBiomeGround(chunk, def, (h2 + (k * HAZARD_RETRY_STEP_PX) / span) % 1, b, breather, lips, h3);
          // B1 slot rule (spec §4 amendment): no free slot -> replace one base ground hazard, picked with the 5th draw
          if (!placed) this._replaceBiomeGround(chunk, def, h4, b, breather, lips, h3);
        }
      }
    }
    const pDefs = this.biomePowerups[biome];
    if (pDefs && chunk.index > 0) {
      const def = this._pickBiomeDef(pDefs, p1, distM);
      if (def && p0 < biomeChance(def)) {
        for (const u of [p2, (p2 + 0.5) % 1]) if (this._tryBiomePowerup(chunk, def, u, p3)) break;
      }
    }
  }

  /** Weighted pick from one pre-drawn number among defs allowed at distM. `weight: 0` disables a def. */
  _pickBiomeDef(defs, r, distM) {
    let total = 0;
    for (const d of defs) if (this._biomeDefOk(d, distM)) total += Math.max(0, d.weight == null ? 1 : d.weight);
    if (!(total > 0)) return null;
    let t = r * total;
    let last = null;
    for (const d of defs) {
      if (!this._biomeDefOk(d, distM)) continue;
      const w = Math.max(0, d.weight == null ? 1 : d.weight);
      if (!(w > 0)) continue;
      last = d;
      t -= w;
      if (t < 0) return d;
    }
    return last;
  }

  _biomeDefOk(d, distM) {
    return (d.minDistanceM || 0) <= distM && (d.maxDistanceM == null || distM <= d.maxDistanceM);
  }

  /** Ground biome hazard at fraction u of the chunk's inner span, if every base clearance holds. @returns {boolean} placed */
  _tryBiomeGround(chunk, def, u, b, breather, lips, h3) {
    const lo = chunk.startX + BIOME_EDGE_MARGIN_PX;
    const hi = chunk.endX - BIOME_EDGE_MARGIN_PX;
    if (hi < lo) return false;
    const x = Math.round(lo + (hi - lo) * u);
    const at = this._biomeGroundAt(chunk, def, x, b, breather, lips, null);
    if (!at) return false;
    chunk.hazards.push(biomeSpawn(def, x, at.y, at.slope, h3));
    chunk.hazards.sort((p, q) => p.x - q.x);
    return true;
  }

  /**
   * Every biome ground rule at world x (edges, breather, lips, gaps, spacing, power-ups, slope, `slow` before a descent,
   * shards against THIS def's box). `skip` is a hazard spawn left out of the spacing check (the one a replacement swaps).
   * @returns {{y:number, slope:number}|null} the ground y and slope at x, or null when a rule fails.
   */
  _biomeGroundAt(chunk, def, x, b, breather, lips, skip) {
    if (x < chunk.startX + BIOME_EDGE_MARGIN_PX || x > chunk.endX - BIOME_EDGE_MARGIN_PX) return null;
    const crash = !def.onHit || def.onHit.effect === 'crash';
    if (x < HAZARD_MIN_X_PX || x < HAZARD_SOFT_PX || x < b.noHazX || (crash && x < HAZARD_SAFE_PX)) return null;
    if (breather && x < chunk.startX + BREATHER_CALM_PX) return null;
    for (const l of lips) if (x >= l.x - 40 && x <= l.zoneEnd) return null;
    for (const g of chunk.gaps) if (x >= g.x0 - 96 && x <= g.x1 + 96) return null;
    for (const q of chunk.hazards) if (q !== skip && Math.abs(q.x - x) < BIOME_HAZARD_CLEARANCE_PX) return null;
    for (const p of chunk.powerups) if (Math.abs(p.x - x) < 90) return null;
    if (!this._rollTrackClear(chunk, def, x, lips, skip)) return null;
    if (def.onHit && def.onHit.effect === 'blind') {
      // B2 blind fairness: nothing that crashes in the stretch the sled rides blinded (see BIOME_BLIND_REACT_MS)
      const ahead = blindClearAheadPx(def.onHit, x / this.ppm);
      for (const q of chunk.hazards) if (q !== skip && q.x > x && q.x - x <= ahead && this.crashHazardIds.has(q.defId)) return null;
    }
    const pts = chunk.points;
    const i = clamp(Math.floor((x - chunk.startX) / SPACING_PX), 0, pts.length - 2);
    const slope = pmath.atan2(pts[i + 1].y - pts[i].y, SPACING_PX) * DEG;
    if (!(slope > -12 && slope < 28) || !this._flatAround(pts, i)) return null;
    if (def.onHit && def.onHit.effect === 'slow') {
      const f = Number.isFinite(def.onHit.speedFactor) ? def.onHit.speedFactor : 0.5;
      if (f < BIOME_GENTLE_SLOW_FACTOR ? !this._descentAhead(pts, i, chunk.endX) : !this._noClimbAhead(pts, i)) return null;
    }
    const w = (def.size && def.size.w) || 24;
    const ht = (def.size && def.size.h) || 24;
    const y = this._yAtLocal(pts, x);
    for (const s of chunk.shards) if (s.x >= x - w / 2 - 22 && s.x <= x + w / 2 + 22 && s.y >= y - ht - 22) return null;
    return { y, slope };
  }

  /**
   * B3 roll track rule: a rolling hazard (motion roll) can be anywhere on [x + sweep.lo, x + sweep.hi] (HazardMotion.rollSweep),
   * so that whole track keeps the clearances its spawn point keeps: inside the chunk's edge margins, off lip windows and
   * gaps +/- 96, BIOME_HAZARD_CLEARANCE_PX from every other hazard and 90 px from every power-up. A def that does not move
   * along x (sweep 0) passes trivially. @returns {boolean}
   */
  _rollTrackClear(chunk, def, x, lips, skip) {
    const sw = rollSweep(def.motion);
    if (sw.lo === 0 && sw.hi === 0) return true;
    const lo = x + sw.lo;
    const hi = x + sw.hi;
    if (lo < chunk.startX + ROLL_TRACK_EDGE_MARGIN_PX || hi > chunk.endX - ROLL_TRACK_EDGE_MARGIN_PX) return false;
    const away = (q) => (q < lo ? lo - q : q > hi ? q - hi : 0);
    // B3 tuning: a sled landing from a lip gets the roll's whole range of ground before the track (the old uphill
    // track gave it that for free: its far end had to clear the landing zone)
    for (const l of lips) if (hi >= l.x - 40 && lo <= l.zoneEnd + (hi - lo)) return false;
    for (const g of chunk.gaps) if (hi >= g.x0 - 96 && lo <= g.x1 + 96) return false;
    for (const q of chunk.hazards) if (q !== skip && away(q.x) < BIOME_HAZARD_CLEARANCE_PX) return false;
    for (const p of chunk.powerups) if (away(p.x) < 90) return false;
    return true;
  }

  /**
   * B3: distance from x to the track a hazard spawn can occupy (a static hazard: |q.x - x|; a rolling one: its whole
   * rollSweep span). Base and B1/B2 defs have no motion, so this is exactly the old |q.x - x| for them.
   */
  _trackDist(q, x) {
    const d = this.biomeHazardById ? this.biomeHazardById[q.defId] : null;
    const sw = d ? rollSweep(d.motion) : { lo: 0, hi: 0 };
    const lo = q.x + sw.lo;
    const hi = q.x + sw.hi;
    return x < lo ? lo - x : x > hi ? x - hi : 0;
  }

  /** B1 (b): no segment climbs (angle < 0, y down) from point i over the next BIOME_EDGE_MARGIN_PX (always inside the chunk). */
  _noClimbAhead(pts, i) {
    const k1 = Math.min(pts.length - 2, i + Math.ceil(BIOME_EDGE_MARGIN_PX / SPACING_PX));
    for (let k = i; k <= k1; k++) if (pts[k + 1].y < pts[k].y) return false;
    return true;
  }

  /**
   * B1 slot rule (spec §4, amended 2026-11-14). The free scan found no slot: swap ONE base ground hazard of this chunk for
   * the biome def, in place (same x, y, rotation). A candidate must be a base (non-biome) ground def whose box, grown by
   * BIOME_REPLACE_SLACK_PX in w and h, holds the biome box, and its spot must pass every biome ground rule with the biome
   * def (spacing ignores the candidate itself). `r` is the slot's pre-drawn 5th number: the draw count never changes, so
   * base streams and the power-up slot are untouched. @returns {boolean} replaced
   */
  _replaceBiomeGround(chunk, def, r, b, breather, lips, h3) {
    const w = (def.size && def.size.w) || 24;
    const ht = (def.size && def.size.h) || 24;
    const cands = [];
    for (let k = 0; k < chunk.hazards.length; k++) {
      const q = chunk.hazards[k];
      const qd = this.hazardList.find((d) => d.id === q.defId); // base ground defs only (no biome, no air def)
      if (!qd) continue;
      const qw = (qd.size && qd.size.w) || 24;
      const qh = (qd.size && qd.size.h) || 24;
      if (w > qw + BIOME_REPLACE_SLACK_PX || ht > qh + BIOME_REPLACE_SLACK_PX) continue;
      if (!this._biomeGroundAt(chunk, def, q.x, b, breather, lips, q)) continue;
      cands.push(k);
    }
    if (!cands.length) return false;
    const k = cands[Math.min(cands.length - 1, Math.floor(r * cands.length))];
    const q = chunk.hazards[k];
    chunk.hazards[k] = biomeSpawn(def, q.x, q.y, q.rotationDeg, h3);
    return true;
  }

  /** Biome power-up at fraction u of the chunk's inner span, lifted like a base pickup. @returns {boolean} placed */
  _tryBiomePowerup(chunk, def, u, rLift) {
    const lo = chunk.startX + BIOME_EDGE_MARGIN_PX;
    const hi = chunk.endX - BIOME_EDGE_MARGIN_PX;
    if (hi < lo) return false;
    const x = Math.round(lo + (hi - lo) * u);
    if (x <= 480) return false;
    for (const q of chunk.hazards) if (this._trackDist(q, x) < 90) return false;
    for (const g of chunk.gaps) if (x > g.x0 - 80 && x < g.x1 + 40) return false;
    for (const p of chunk.powerups) if (Math.abs(p.x - x) < 90) return false;
    const r = def.radius || 10;
    const y = this._yAtLocal(chunk.points, x) - (r + 26 + 32 * rLift);
    for (const s of chunk.shards) if (Math.abs(s.x - x) < r + 24 && Math.abs(s.y - y) < r + 24) return false;
    chunk.powerups.push({ defId: def.id, x, y });
    chunk.powerups.sort((p, q) => p.x - q.x);
    return true;
  }

  /** Weighted pick (one pre-drawn random number) among air defs allowed at distance dM. */
  _pickAirDef(r, dM) {
    let total = 0;
    const ok = [];
    for (const d of this.airHazardList) {
      if (dM >= Math.max(AIR_HAZARD_MIN_M, d.minDistanceM || 0) && (d.maxDistanceM == null || dM <= d.maxDistanceM)) {
        ok.push(d);
        total += Math.max(0, d.weight == null ? 1 : d.weight);
      }
    }
    if (!ok.length || !(total > 0)) return null;
    let t = r * total;
    for (const d of ok) {
      t -= Math.max(0, d.weight == null ? 1 : d.weight);
      if (t < 0) return d;
    }
    return ok[ok.length - 1];
  }

  /** True when a hit box would sit on a power-up, shard, gap or too close to another hazard. */
  _airBlocked(chunk, x, cy, bw, bh) {
    for (const p of chunk.powerups) if (Math.abs(p.x - x) < 90) return true;
    for (const s of chunk.shards) if (Math.abs(s.x - x) < bw / 2 + 24 && Math.abs(s.y - cy) < bh / 2 + 24) return true;
    for (const g of chunk.gaps) if (x > g.x0 - 80 && x < g.x1 + 80) return true;
    for (const h of chunk.hazards) if (Math.abs(h.x - x) < HAZARD_MIN_SPACING_PX) return true;
    return false;
  }

  // ------------------------------------------------------------------------------------------------- shards

  /**
   * Collectible shard group (one per chunk at most): a ballistic arc off a launch lip / bounce pad (always when the chunk
   * has one), else a ground-hugging line on a fast smooth stretch, else a high "risk" hump over a hazard or gap. The
   * share of risky groups grows with distance. Every shard is clear of terrain and of hazard hitboxes.
   */
  _placeShards(chunk, rng, distM, lips) {
    const pts = chunk.points;
    const spacing = () => rng.range(SHARD_SPACING_PX[0], SHARD_SPACING_PX[1]);
    const hz = chunk.hazards.map((h) => {
      const d = this.options.hazardDefs && (Array.isArray(this.options.hazardDefs) ? this.options.hazardDefs.find((q) => q.id === h.defId) : this.options.hazardDefs[h.defId]);
      const w = (d && d.size && d.size.w) || 24;
      const ht = (d && d.size && d.size.h) || 24;
      return { x0: h.x - w / 2 - 22, x1: h.x + w / 2 + 22, top: h.y - ht - 22 };
    });
    const ok = (x, y) => {
      if (x < chunk.startX + 8 || x > chunk.endX - 8) return false;
      if (y > this._yAtLocal(pts, x) - 12) return false;
      for (const h of hz) if (x >= h.x0 && x <= h.x1 && y >= h.top) return false;
      return true;
    };
    const out = [];
    const arcFrom = (l) => {
      const list = [];
      let acc = 0;
      let next = 36;
      let px = l.x;
      let py = l.y;
      for (let t = 0.01; t < 2.4 && list.length < SHARD_GROUP[1]; t += 0.01) {
        const x = l.x + l.vx * t;
        const y = l.y + l.vy * t + 0.5 * GRAV * t * t;
        acc += pmath.hypot(x - px, y - py);
        px = x;
        py = y;
        if (x >= chunk.endX - 8) break;
        if (acc >= next) {
          if (!ok(x, y)) {
            if (list.length) break;
            continue;
          }
          list.push({ x: Math.round(x), y: Math.round(y) });
          next += spacing();
        }
      }
      return list;
    };
    let group = null;
    // (a) arcs off lips / pads
    for (const l of lips) {
      const g = arcFrom(l);
      if (g.length >= SHARD_GROUP[0]) { group = g; break; }
    }
    if (!group) {
      if (!rng.chance(SHARD_PLAIN_CHANCE)) return;
      const riskP = clamp(0.12 + distM / 5500, 0.12, 0.65);
      const wantRisk = rng.chance(riskP);
      const cnt = rng.int ? rng.int(SHARD_GROUP[0], SHARD_GROUP[1]) : Math.round(rng.range(SHARD_GROUP[0], SHARD_GROUP[1]));
      if ((wantRisk && chunk.hazards.length) || chunk.kind === 'bridge') {
        // (c) risk hump centred over a hazard, or over the gap of a bridge chunk
        let cx;
        let base;
        if (chunk.kind === 'bridge' && chunk.gaps.length) {
          cx = (chunk.gaps[0].x0 + chunk.gaps[0].x1) / 2;
          base = 70;
        } else {
          const h = chunk.hazards[Math.floor(rng.range(0, chunk.hazards.length)) % chunk.hazards.length];
          cx = h.x;
          base = 62;
        }
        const sp = 32;
        const g = [];
        for (let k = 0; k < cnt; k++) {
          const u = cnt === 1 ? 0 : (k / (cnt - 1)) * 2 - 1;
          const x = Math.round(cx + u * ((cnt - 1) / 2) * sp);
          g.push({ x, y: Math.round(this._yAtLocal(pts, x) - base - 26 * (1 - u * u)) });
        }
        group = g;
      } else {
        // (b) ground-hugging line on a smooth, fast section
        const sp = spacing();
        const len = (cnt - 1) * sp;
        const tries = 8;
        for (let tr = 0; tr < tries && !group; tr++) {
          const x0 = Math.round(rng.range(chunk.startX + 40, Math.max(chunk.startX + 41, chunk.endX - 40 - len)));
          const g = [];
          let good = true;
          for (let k = 0; k < cnt && good; k++) {
            const x = Math.round(x0 + k * sp);
            const i = clamp(Math.floor((x - chunk.startX) / SPACING_PX), 0, pts.length - 2);
            const a = pmath.atan2(pts[i + 1].y - pts[i].y, SPACING_PX) * DEG;
            const y = Math.round(this._yAtLocal(pts, x) - 14);
            if (a < 8 || a > 38 || chunk.gaps.some((q) => x > q.x0 - 20 && x < q.x1 + 20) || !ok(x, y)) good = false;
            g.push({ x, y });
          }
          if (good) group = g;
        }
      }
    }
    if (!group) return;
    for (const p of group) if (ok(p.x, p.y)) out.push(p);
    if (out.length < SHARD_GROUP[0]) return;
    out.sort((p, q) => p.x - q.x);
    const seen = new Set();
    let nid = 0;
    for (const p of out) {
      if (seen.has(p.x)) continue; // never two shards at the same x
      seen.add(p.x);
      chunk.shards.push({ id: `s${chunk.index}-${nid++}`, x: p.x, y: p.y });
    }
  }

  /** True if the 5 segments around i do not turn sharply (hazards sit on readable ground). */
  /** True when the next SLOW_HAZARD_CLEAR_PX of this chunk (must fit inside it) is a steady descent of >= SLOW_HAZARD_MIN_DEG. */
  _descentAhead(pts, i, endX) {
    if (pts[i].x + SLOW_HAZARD_CLEAR_PX > endX) return false;
    const k1 = Math.min(pts.length - 2, i + Math.ceil(SLOW_HAZARD_CLEAR_PX / SPACING_PX));
    for (let k = i; k <= k1; k++) {
      if (pmath.atan2(pts[k + 1].y - pts[k].y, SPACING_PX) * DEG < SLOW_HAZARD_MIN_DEG) return false;
    }
    return true;
  }

  _flatAround(pts, i) {
    const a0 = Math.max(0, i - 2);
    const a1 = Math.min(pts.length - 2, i + 2);
    let lo = Infinity;
    let hi = -Infinity;
    for (let k = a0; k <= a1; k++) {
      const a = pmath.atan2(pts[k + 1].y - pts[k].y, SPACING_PX) * DEG;
      if (a < lo) lo = a;
      if (a > hi) hi = a;
    }
    return hi - lo <= 22;
  }

  _placePowerups(chunk, rng, distM) {
    if (!this.powerupList.length) return;
    const pts = chunk.points;
    let x = chunk.startX + 320 + rng.range(0, 300);
    const xEnd = chunk.endX - 160;
    while (x <= xEnd) {
      const dM = x / this.ppm;
      const def = rng.pick(this.powerupList);
      const sp = def.spawn || { baseChance: 0.2, distanceDecayM: 1500 };
      const chance = Math.max(sp.baseChance * POWERUP_FLOOR_FRACTION, sp.baseChance / (1 + dM / sp.distanceDecayM));
      const lift = (def.radius || 10) + rng.range(26, 58);
      if (rng.chance(chance) && x > 480) {
        let clear = true;
        for (const h of chunk.hazards) if (Math.abs(h.x - x) < 90) clear = false;
        for (const g of chunk.gaps) if (x > g.x0 - 80 && x < g.x1 + 40) clear = false;
        const px = Math.round(x);
        if (clear) chunk.powerups.push({ defId: def.id, x: px, y: this._yAtLocal(pts, px) - lift });
      }
      x += rng.range(320, 640);
    }
  }
}/**
 * OWNER: input/audio/glitch engineer. DOM only (no Phaser import). Helper of VirtualPad.
 *
 * On-screen touch controls drawn with inline SVG neon shapes. Pointer events are hit-tested manually with
 * document.elementFromPoint so several fingers work at once and a thumb can slide from one button to the next
 * (e.g. tilt back -> tilt forward). Layout: steering cluster bottom-left, action cluster bottom-right, pause/reset
 * top-centre (HUD owns the top corners); the rider sits in the upper-left/middle of the screen so thumbs never cover it.
 */
import { eventTimeOnClock, perfNow } from './PadDerive.js';

/** @typedef {{name:string, label:string, icon:string, color:string, grid:string, big?:boolean}} OverlayButton */

const SVG = (body) =>
  `<svg viewBox="0 0 24 24" width="62%" height="62%" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round">${body}</svg>`;

/** @type {Object<string,string>} */
const ICONS = {
  back: SVG('<polygon points="16,5 6,12 16,19"/>'),
  fwd: SVG('<polygon points="8,5 18,12 8,19"/>'),
  tuck: SVG('<polygon points="4,8 12,17 20,8"/><line x1="6" y1="20" x2="18" y2="20"/>'),
  brake: SVG('<rect x="6" y="6" width="12" height="12"/>'),
  push: SVG('<polyline points="5,6 12,12 5,18"/><polyline points="12,6 19,12 12,18"/>'),
  hop: SVG('<polygon points="12,3 20,13 4,13"/><line x1="4" y1="19" x2="20" y2="19"/>'),
  heliL: SVG('<path d="M5 12a7 7 0 1 0 3-5.7"/><polyline points="4,3 8,7 3,8"/>'),
  heliR: SVG('<path d="M19 12a7 7 0 1 1-3-5.7"/><polyline points="20,3 16,7 21,8"/>'),
  air: SVG('<polyline points="5,15 12,7 19,15"/><line x1="5" y1="19" x2="19" y2="19"/>'),
  chute: SVG('<path d="M4 11a8 7 0 0 1 16 0z"/><line x1="4" y1="11" x2="12" y2="20"/><line x1="20" y1="11" x2="12" y2="20"/>'),
  corkscrew: SVG('<path d="M12 3 C22 3 23 19 12 20 C2 20 2 8 11 8 C17 8 16 16 12 16"/>'),
  divebomb: SVG('<path d="M12 3v16m-7-7 7 8 7-8"/>'),
  pause: SVG('<line x1="9" y1="6" x2="9" y2="18"/><line x1="15" y1="6" x2="15" y2="18"/>'),
  reset: SVG('<path d="M5 12a7 7 0 1 0 2.2-5"/><polyline points="4,4 5,9 10,8"/>'),
};

/** Button layout. grid = "gridColumn / gridRow" within the cluster. */
const LEFT = [
  { name: 'brake', label: 'BRAKE', icon: 'brake', color: 'amber', grid: '1/1' },
  { name: 'tuck', label: 'TUCK', icon: 'tuck', color: 'lime', grid: '2/1' },
  { name: 'tiltBack', label: 'TILT BACK', icon: 'back', color: 'cyan', grid: '1/2', big: true },
  { name: 'tiltForward', label: 'TILT FWD', icon: 'fwd', color: 'cyan', grid: '2/2', big: true },
];
const RIGHT = [
  { name: 'heliLeft', label: 'SPIN CCW', icon: 'heliL', color: 'lime', grid: '1/1' },
  { name: 'airBrake', label: 'AIR BRAKE', icon: 'air', color: 'amber', grid: '2/1' },
  { name: 'heliRight', label: 'SPIN CW', icon: 'heliR', color: 'lime', grid: '3/1' },
  { name: 'push', label: 'PUSH', icon: 'push', color: 'cyan', grid: '1/2' },
  { name: 'hop', label: 'HOP', icon: 'hop', color: 'magenta', grid: '2/2', big: true },
  { name: 'parachute', label: 'CHUTE', icon: 'chute', color: 'amber', grid: '3/2' },
];
const TOP = [
  { name: 'reset', label: 'RESET', icon: 'reset', color: 'amber', grid: '1/1' },
  { name: 'pause', label: 'PAUSE', icon: 'pause', color: 'cyan', grid: '2/1' },
];

/** The three on-screen clusters, exported so HOW TO PLAY can describe the real buttons. */
export const TOUCH_CLUSTERS = Object.freeze({ LEFT, RIGHT, TOP });

/**
 * What a base touch button becomes under a control layout. The overlay keeps its spatial layout but, in every
 * non-classic (Trick Deck) layout, swaps PUSH for DIVEBOMB and SPIN CCW for CORKSCREW. This is the single
 * source of truth for that swap: setControlLayout() applies it to the DOM buttons and HowToPlayLayout uses it
 * for the touch legend, so the help screen can never teach a button the player does not have.
 * @param {{name:string,label:string,icon:string}} base a LEFT/RIGHT/TOP entry
 * @param {string} layout settings.controlLayout ('classic' or a trick layout) or 'trickDeck'
 * @returns {{name:string,label:string,icon:string}}
 */
export function touchButtonFor(base, layout) {
  if (layout === 'classic') return { name: base.name, label: base.label, icon: base.icon };
  if (base.name === 'push') return { name: 'divebomb', label: 'DIVEBOMB', icon: 'divebomb' };
  if (base.name === 'heliLeft') return { name: 'corkscrew', label: 'CORKSCREW', icon: 'corkscrew' };
  return { name: base.name, label: base.label, icon: base.icon };
}

const DEFAULT_COLORS = { cyan: '#00f0ff', magenta: '#ff2bd6', lime: '#9dff3a', amber: '#ffb000' };

export class TouchOverlay {
  /**
   * @param {{setButton:(name:string, down:boolean, source:string, timeStamp?:number|null)=>void}} pad
   */
  constructor(pad) {
    this.pad = pad;
    /** Clock shared by PointerEvent.timeStamp and Phaser's rAF time (issue #115; overridable in tests). */
    this.now = perfNow;
    this.controlLayout = 'classic';
    /** @type {HTMLElement|null} */
    this.root = null;
    this.colors = { ...DEFAULT_COLORS };
    /** pointerId -> button name currently held by that finger. @type {Map<number,string>} */
    this.pointers = new Map();
    /** @type {Map<string,number>} button name -> number of fingers on it */
    this.counts = new Map();
    this.mode = 'auto';
    this.contextVisible = false;
    this.touchSeen = false;
    this._handlers = [];
  }

  /** @returns {boolean} true on devices that look touch-capable. */
  static detectTouch() {
    if (typeof window === 'undefined') return false;
    try {
      if ('ontouchstart' in window) return true;
      if (typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0) return true;
      if (window.matchMedia && window.matchMedia('(pointer: coarse)').matches) return true;
    } catch (e) { /* ignore */ }
    return false;
  }

  /** The touch UI keeps its own spatial layout but replaces obsolete push/reverse-heli
   *  buttons with the newly approved divebomb and corkscrew in Trick Deck mode. */
  setControlLayout(layout) {
    const mode = layout === 'classic' ? 'classic' : 'trickDeck';
    if (this.controlLayout === mode) return;
    this.releaseAll();
    this.controlLayout = mode;
    if (!this.root) return;
    for (const el of this.root.querySelectorAll('[data-base-btn]')) {
      const { name, label, icon } = touchButtonFor(
        { name: el.dataset.baseBtn, label: el.dataset.baseLabel, icon: el.dataset.baseIcon }, mode);
      el.dataset.btn = name;
      el.setAttribute('aria-label', label);
      el.innerHTML = ICONS[icon];
    }
  }

  /** @param {Object<string,string>} colors css colours keyed cyan/magenta/lime/amber. */
  setColors(colors) {
    this.colors = { ...DEFAULT_COLORS, ...(colors || {}) };
    if (this.root) {
      for (const k of Object.keys(DEFAULT_COLORS)) this.root.style.setProperty(`--bb-${k}`, this.colors[k]);
    }
  }

  /**
   * @param {HTMLElement} parent
   * @param {'auto'|'on'|'off'} mode
   */
  mount(parent, mode) {
    this.mode = mode || 'auto';
    if (typeof document === 'undefined') return;
    if (!this.root) this._build(parent || document.body);
    else if (parent && this.root.parentElement !== parent) parent.appendChild(this.root);
    this._listenFirstTouch();
    this._refresh();
  }

  /** @param {boolean} visible shown only while a run is in progress (set by InputRouter). */
  setContextVisible(visible) {
    this.contextVisible = !!visible;
    this._refresh();
  }

  /** @returns {boolean} */
  isVisible() {
    return !!this.root && this.root.style.display !== 'none';
  }

  _wantVisible() {
    if (this.mode === 'off') return false;
    if (!this.contextVisible) return false;
    if (this.mode === 'on') return true;
    return this.touchSeen || TouchOverlay.detectTouch();
  }

  _refresh() {
    if (!this.root) return;
    const show = this._wantVisible();
    this.root.style.display = show ? 'block' : 'none';
    if (!show) this.releaseAll();
  }

  _listenFirstTouch() {
    if (this._firstTouchBound || typeof window === 'undefined') return;
    this._firstTouchBound = true;
    const onTouch = (e) => {
      if (e.pointerType && e.pointerType !== 'touch') return;
      this.touchSeen = true;
      this._refresh();
    };
    window.addEventListener('pointerdown', onTouch, true);
    this._handlers.push([window, 'pointerdown', onTouch, true]);
  }

  /** @param {HTMLElement} parent */
  _build(parent) {
    const root = document.createElement('div');
    root.className = 'bb-touch-overlay';
    root.setAttribute('aria-hidden', 'true');
    root.style.cssText =
      'position:fixed;inset:0;z-index:20;display:none;pointer-events:none;touch-action:none;' +
      'user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;--u:clamp(40px,13vmin,76px);';
    for (const k of Object.keys(DEFAULT_COLORS)) root.style.setProperty(`--bb-${k}`, this.colors[k]);
    const style = document.createElement('style');
    style.textContent = `
      .bb-touch-overlay .bb-cl{position:absolute;display:grid;gap:calc(var(--u)*0.12);pointer-events:none}
      .bb-touch-overlay .bb-btn{pointer-events:auto;touch-action:none;box-sizing:border-box;display:flex;
        align-items:center;justify-content:center;width:calc(var(--u)*1.1);height:calc(var(--u)*1.1);
        border:2px solid currentColor;border-radius:22%;background:rgba(5,6,15,0.28);opacity:0.5;
        filter:drop-shadow(0 0 4px currentColor);font:700 9px monospace;transition:opacity 60ms,background 60ms}
      .bb-touch-overlay .bb-btn.bb-big{width:calc(var(--u)*1.45);height:calc(var(--u)*1.45)}
      .bb-touch-overlay .bb-btn.bb-on{opacity:1;background:rgba(255,255,255,0.22)}
      .bb-touch-overlay .bb-btn svg{pointer-events:none}`;
    root.appendChild(style);
    const mkCluster = (pos, cols, items) => {
      const c = document.createElement('div');
      c.className = 'bb-cl';
      c.style.cssText = `${pos};grid-template-columns:repeat(${cols},auto);align-items:end;justify-items:center`;
      for (const b of items) {
        const el = document.createElement('div');
        el.className = 'bb-btn' + (b.big ? ' bb-big' : '');
        el.dataset.btn = b.name;
        el.dataset.baseBtn = b.name;
        el.dataset.baseLabel = b.label;
        el.dataset.baseIcon = b.icon;
        el.setAttribute('role', 'button');
        el.setAttribute('aria-label', b.label);
        el.style.color = `var(--bb-${b.color})`;
        const [col, row] = b.grid.split('/');
        el.style.gridColumn = col;
        el.style.gridRow = row;
        el.innerHTML = ICONS[b.icon];
        c.appendChild(el);
      }
      root.appendChild(c);
    };
    mkCluster('left:max(2vmin,env(safe-area-inset-left));bottom:max(2vmin,env(safe-area-inset-bottom))', 2, LEFT);
    mkCluster('right:max(2vmin,env(safe-area-inset-right));bottom:max(2vmin,env(safe-area-inset-bottom))', 3, RIGHT);
    mkCluster('left:50%;transform:translateX(-50%);top:max(1.5vmin,env(safe-area-inset-top))', 2, TOP); // centre: HUD owns both top corners

    const on = (type, fn) => {
      root.addEventListener(type, fn, { passive: false });
      this._handlers.push([root, type, fn, { passive: false }]);
    };
    on('pointerdown', (e) => this._onDown(e));
    on('pointermove', (e) => this._onMove(e));
    on('pointerup', (e) => this._onUp(e));
    on('pointercancel', (e) => this._onUp(e));
    // capture lost without a pointerup (element hidden/removed, OS gesture): release that finger
    on('lostpointercapture', (e) => this._assign(e.pointerId, null, this._time(e)));
    on('contextmenu', (e) => e.preventDefault());
    this.root = root;
    parent.appendChild(root);
  }

  /** @param {PointerEvent} e @returns {string|null} */
  _hit(e) {
    const el = document.elementFromPoint(e.clientX, e.clientY);
    const b = el && el.closest ? el.closest('[data-btn]') : null;
    return b ? b.dataset.btn : null;
  }

  /** @param {Event} e @returns {number|null} event time on the rAF clock, or null (issue #115). */
  _time(e) {
    return eventTimeOnClock(e && e.timeStamp, this.now());
  }

  _press(name, t = null) {
    const n = (this.counts.get(name) || 0) + 1;
    this.counts.set(name, n);
    if (n === 1) {
      this.pad.setButton(name, true, 'touch', t);
      this._paint(name, true);
    }
  }

  _release(name, t = null) {
    const n = (this.counts.get(name) || 0) - 1;
    if (n <= 0) {
      this.counts.delete(name);
      this.pad.setButton(name, false, 'touch', t);
      this._paint(name, false);
    } else this.counts.set(name, n);
  }

  _paint(name, on) {
    if (!this.root) return;
    const el = this.root.querySelector(`[data-btn="${name}"]`);
    if (el) el.classList.toggle('bb-on', on);
  }

  _assign(id, name, t = null) {
    const prev = this.pointers.get(id);
    if (prev === name) return;
    if (prev) this._release(prev, t);
    if (name) {
      this.pointers.set(id, name);
      this._press(name, t);
    } else this.pointers.delete(id);
  }

  _onDown(e) {
    e.preventDefault();
    try { e.target.setPointerCapture && e.target.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
    if (this.onGesture) this.onGesture(e);
    this._assign(e.pointerId, this._hit(e), this._time(e));
  }

  _onMove(e) {
    if (!this.pointers.has(e.pointerId)) return;
    e.preventDefault();
    this._assign(e.pointerId, this._hit(e), this._time(e));
  }

  _onUp(e) {
    e.preventDefault();
    this._assign(e.pointerId, null, this._time(e));
  }

  /** Release every held button (hidden, blur, destroy). */
  releaseAll() {
    for (const id of [...this.pointers.keys()]) this._assign(id, null);
  }

  destroy() {
    this.releaseAll();
    for (const [t, type, fn, opt] of this._handlers) t.removeEventListener(type, fn, opt);
    this._handlers = [];
    this._firstTouchBound = false;
    if (this.root && this.root.parentElement) this.root.parentElement.removeChild(this.root);
    this.root = null;
  }
}/**
 * OWNER: core-logic engineer. NO Phaser imports. Never emits events.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Detects flips / helicopter spins / air-brake / parachute from per-frame sled state.
 * RunScene calls update() on physical touchdowns and at the fixed tick end with a SledFrameState.
 *
 * Model: an "air phase" starts on the first frame with grounded=false and ends on the first grounded frame.
 * Rotation deltas (from the unwrapped angleDeg) are accumulated into two buckets per frame: tilt (A/D driven) and
 * heli (arrow-key driven, input.heli != 0). A bucket whose net rotation reaches a full turn (minus
 * FLIP_TOLERANCE_DEG) yields one TrickEvent per completed rotation with the CUMULATIVE count so far.
 * Air phases shorter than minAirtimeMs are bumps: no landing is reported.
 */

import { SCORING } from '../constants.js';
import pmath from './pmath.js';

/** Rotation counts as a full turn at 360 - tolerance degrees. */
export const FLIP_TOLERANCE_DEG = 20;
/** Historical AirBrake held-time threshold retained for telemetry; SIM9 trick credit uses a physical one-shot. */
export const AIR_BRAKE_MIN_MS = 250;
export const PARACHUTE_MIN_MS = 300;
/** Landing alignment thresholds (|sled angle - ground slope| in degrees). */
export const PERFECT_ANGLE_DEG = 12;
export const GOOD_ANGLE_DEG = 28;
export const SLOPPY_ANGLE_DEG = 55;
/** Impact speed (px/s into the ground). Above HARD = shake worthy; above CRASH = crash regardless of angle. */
export const HARD_IMPACT_PX_S = 520;
export const PERFECT_MAX_IMPACT_PX_S = 900;
export const CRASH_IMPACT_PX_S = 1500;
/**
 * A helicopter spin phase counts as unfinished only when the air phase made at least this much spin (a quarter turn)
 * or the spin key was still held at touchdown. Less than that with the key released is coast / a nudge, not a trick.
 */
export const MID_SPIN_MIN_DEG = 90;
/** Default minimum airtime for an air phase to count as a jump. */
export const DEFAULT_MIN_AIRTIME_MS = 120;

/**
 * Per-frame state RunScene builds from the Matter body + input. UNITS: px, px/s, degrees, ms.
 * @typedef {Object} SledFrameState
 * @property {number} timeMs        run time (excludes pause), monotonically increasing.
 * @property {number} dtMs          ms since previous update (>0).
 * @property {number} x             world px.
 * @property {number} y             world px.
 * @property {number} vx            px/s.
 * @property {number} vy            px/s (down positive).
 * @property {number} [impactVx]    OPTIONAL velocity (px/s) the sled had going INTO the touchdown. Physics engines resolve the contact
 * @property {number} [impactVy]    before the frame is observed, so vx/vy on the landing frame have lost their ground-normal part and
 *                                  would grade every landing as soft; when both are finite they are used for the impact speed.
 * @property {number} angleDeg      CONTINUOUS (unwrapped, may exceed +-360) sled rotation, clockwise positive.
 *                                  Must be unwrapped by the caller so flips can be counted (e.g. accumulate shortest delta).
 * @property {number} angularVelDegS deg/s, clockwise positive.
 * @property {boolean} grounded     sled has wheel/runner contact with terrain this frame.
 * @property {number} groundAngleDeg  slope of terrain under/near sled in degrees (clockwise positive = descending right);
 *                                  used for landing alignment. Use last known value while airborne.
 * @property {{heli:-1|0|1, airBrake:boolean, airBrakeKicked?:boolean, parachute:boolean, corkscrew?:boolean}} input  heli: -1 = CCW (left arrow), +1 = CW (right arrow).
 * @property {number} [heliDeg]     OPTIONAL continuous (unwrapped) helicopter spin phase of the sled drawing, clockwise positive.
 *                                  The helicopter spin is a visual rotation about the sled's vertical axis (the physics body does
 *                                  not rotate), so when this is provided helicopter turns are counted from it, whatever the
 *                                  arrow-key state, and body rotation always counts as flips. When absent the legacy rule applies
 *                                  (body rotation while input.heli != 0 counts as helicopter).
 * @property {boolean|number} [midSpin] OPTIONAL helicopter state at touchdown, used to grade the landing (see isMidSpin).
 *                                  true = rider was mid-spin; a number = helicopter phase in degrees (any unwrapped value,
 *                                  e.g. heliDeg), mid-spin when further than SCORING.midSpinToleranceDeg (60) from a whole turn.
 *                                  A numeric phase is ignored (no penalty) when the spin key was released before touchdown and
 *                                  less than MID_SPIN_MIN_DEG of helicopter spin was made in this air phase (visual coast / a
 *                                  nudge). `true` is always honoured. Absent/false = no penalty (legacy behaviour).
 * @property {boolean} crashed      true on the frame a crash is detected (tracker discards airborne tricks).
 */

/**
 * @typedef {Object} TrickEvent
 * @property {'backflip'|'frontflip'|'helicopterCCW'|'helicopterCW'|'corkscrew'|'airBrake'|'parachute'} type
 *   backflip = counter-clockwise body rotation (A / tilt back), frontflip = clockwise; helicopter* only when
 *   rotation was driven by the arrow keys (input.heli != 0), so rotation source separates the two families.
 * @property {number} count         completed rotations so far this air phase (flips/helis; cumulative, 2 = double) or 1.
 * @property {number} rotationDeg   total rotation covered (abs).
 * @property {number} airtimeMs     airtime at the moment of completion.
 */

/**
 * @typedef {Object} LandingResult
 * @property {'perfect'|'good'|'sloppy'|'crash'} quality
 * @property {number} angleDeg        sled angle minus groundAngleDeg, wrapped to [-180,180].
 * @property {number} impactSpeedPxS  speed component into the ground at touchdown.
 * @property {number} airtimeMs
 * @property {boolean} hard           hard impact (screen shake worthy).
 * @property {number} [rotationDeg]   net rotation over the whole air phase (additive field).
 * @property {boolean} [midSpin]      additive: true when the grade was dropped one level for an incomplete helicopter.
 */

/**
 * @typedef {Object} TrickUpdate
 * @property {TrickEvent[]} tricks   tricks completed THIS frame (usually empty).
 * @property {LandingResult|null} landing  non-null on the frame the sled touches down after being airborne >= minAirtime.
 * @property {boolean} airborne
 * @property {number} airtimeMs      current airtime (0 when grounded)
 * @property {number} rotationDeg    net rotation accumulated this airtime (signed; the final value on the landing frame).
 */

/**
 * Wrap an angle to [-180, 180].
 * @param {number} a degrees
 * @returns {number}
 */
export function wrapAngle(a) {
  let r = (a + 180) % 360;
  if (r < 0) r += 360;
  return r - 180;
}

/**
 * Is the helicopter spin incomplete at touchdown? Pure helper.
 * @param {boolean|number|undefined|null} spin true/false, or a helicopter phase in degrees (unwrapped, any sign):
 *   incomplete when its distance to the nearest whole turn exceeds SCORING.midSpinToleranceDeg (60 deg).
 * @returns {boolean}
 */
export function isMidSpin(spin) {
  if (spin === true) return true;
  if (typeof spin !== 'number' || !Number.isFinite(spin)) return false;
  const r = Math.abs(spin) % 360;
  return Math.min(r, 360 - r) > SCORING.midSpinToleranceDeg;
}

/**
 * Classify a touchdown. Pure helper (exported for tests / UI).
 * @param {number} angleDiffDeg sled angle minus ground slope, wrapped.
 * @param {number} impactSpeedPxS
 * @param {boolean|number} [midSpin] numeric is actual helicopter yaw phase: grade at 40/75/120 deg
 *   and crash when backwards beyond 120. Legacy boolean true drops one grade without forcing a crash.
 * @returns {{quality:'perfect'|'good'|'sloppy'|'crash', hard:boolean}}
 */
export function classifyLanding(angleDiffDeg, impactSpeedPxS, midSpin) {
  // Backward/nose-up pitch has an extra 10 degrees of leeway; nose-down retains
  // the original +12/+28/+55 bounds. Signed angle is terrain-relative.
  const a = angleDiffDeg;
  const hard = impactSpeedPxS >= HARD_IMPACT_PX_S;
  let quality;
  if (impactSpeedPxS >= CRASH_IMPACT_PX_S || a < -65 || a > SLOPPY_ANGLE_DEG) quality = 'crash';
  else if (a >= -22 && a <= PERFECT_ANGLE_DEG && impactSpeedPxS <= PERFECT_MAX_IMPACT_PX_S) quality = 'perfect';
  else if (a >= -38 && a <= GOOD_ANGLE_DEG) quality = 'good';
  else quality = 'sloppy';
  // Numeric phases are the actual visual yaw axis: incomplete ~180-degree
  // helicopter landings crash, even if physical pitch is perfectly aligned.
  // The legacy boolean true retains old one-grade penalty for older callers.
  if (typeof midSpin === 'number' && Number.isFinite(midSpin)) {
    const folded = Math.abs(wrapAngle(midSpin));
    const yawQuality = folded > 120 ? 'crash' : folded > 75 ? 'sloppy' : folded > 40 ? 'good' : 'perfect';
    const rank = { perfect: 0, good: 1, sloppy: 2, crash: 3 };
    if (rank[yawQuality] > rank[quality]) quality = yawQuality;
  } else if (midSpin === true) {
    if (quality === 'perfect') quality = 'good';
    else if (quality === 'good') quality = 'sloppy';
  }
  return { quality, hard };
}

export class TrickTracker {
  /** @param {{minAirtimeMs?:number}} [options] airtime below this is a bump, not a jump (default 120). */
  constructor(options = {}) {
    this.options = options;
    this.minAirtimeMs = options.minAirtimeMs != null ? options.minAirtimeMs : DEFAULT_MIN_AIRTIME_MS;
    this._noTricks = [];
    this.reset();
  }

  /**
   * @param {SledFrameState} state
   * @returns {TrickUpdate}
   */
  update(state) {
    const grounded = !!state.grounded;
    const t = state.timeMs || 0;
    const dt = state.dtMs > 0 ? state.dtMs : 0;
    const angle = Number.isFinite(state.angleDeg) ? state.angleDeg : this._prevAngle || 0;
    const input = state.input || NO_INPUT;
    const heli = Number.isFinite(state.heliDeg) ? state.heliDeg : null;
    const tricks = [];

    if (state.crashed) {
      let landing = null;
      if (this._air && t - this._airStart >= this.minAirtimeMs) {
        landing = this._makeLanding(state, angle, t, true);
      }
      this.reset();
      this._prevAngle = angle;
      this._prevHeli = heli;
      this._havePrev = true;
      return { tricks, landing, airborne: false, airtimeMs: 0, rotationDeg: 0 };
    }

    if (!grounded) {
      if (!this._air) {
        this._air = true;
        this._airStart = t - dt;
        this._tiltNet = 0;
        this._heliNet = 0;
        this._tiltDone = 0;
        this._heliDone = 0;
        this._corkscrewNet = 0;
        this._corkscrewDone = 0;
        this._brakeMs = 0;
        this._chuteMs = 0;
        this._brakeDone = false;
        this._chuteDone = false;
        this._heliMax = 0;
        this._heliHeld = false;
        if (!this._havePrev) this._prevAngle = angle;
      }
      const airtime = t - this._airStart;
      this._accumulate(angle, heli, input);
      this._heliMax = Math.max(this._heliMax, Math.abs(this._heliNet), Math.abs(this._corkscrewNet));
      this._heliHeld = !!input.heli || !!input.corkscrew;

      this._emitRotations(tricks, this._tiltNet, '_tiltDone', 'backflip', 'frontflip', airtime);
      this._emitRotations(tricks, this._heliNet, '_heliDone', 'helicopterCCW', 'helicopterCW', airtime);
      this._emitRotations(tricks, this._corkscrewNet, '_corkscrewDone', 'corkscrew', 'corkscrew', airtime);

      if (input.airBrake) this._brakeMs += dt;
      if (input.parachute) this._chuteMs += dt;
      // SIM9: a tap immediately performs the entire physical AirBrake. Count
      // the actual paid-velocity kick, not 250ms of holding an already-spent
      // button; _brakeDone prevents duplicate trick credit this airtime.
      if (!this._brakeDone && input.airBrakeKicked) {
        this._brakeDone = true;
        tricks.push({ type: 'airBrake', count: 1, rotationDeg: 0, airtimeMs: airtime });
      }
      if (!this._chuteDone && this._chuteMs >= PARACHUTE_MIN_MS) {
        this._chuteDone = true;
        tricks.push({ type: 'parachute', count: 1, rotationDeg: 0, airtimeMs: airtime });
      }
      this._prevAngle = angle;
      this._prevHeli = heli;
      this._havePrev = true;
      return { tricks, landing: null, airborne: true, airtimeMs: airtime, rotationDeg: this._tiltNet + this._heliNet };
    }

    // grounded
    const trackedFlight = this._air;
    const trackedAirMs=trackedFlight?Math.max(0,t-this._airStart):Math.max(0,dt);
    // A physical one-shot kick could already have earned a trick on an earlier
    // airborne tick. If touchdown happens before the normal min-air threshold,
    // we MUST bank that pending trick even though this particular frame has
    // no new kick pulse. This is a landing settlement, not duplicate credit.
    const pendingShortBrake=this._air && this._brakeDone &&
      trackedAirMs < this.minAirtimeMs;
    let landing = null;
    let rot = 0;
    if (this._air) {
      const airtime = t - this._airStart;
      this._accumulate(angle, heli, input);
      rot = this._tiltNet + this._heliNet;
      if (airtime >= this.minAirtimeMs) {
        // a rotation completed on the touchdown frame still counts
        this._emitRotations(tricks, this._tiltNet, '_tiltDone', 'backflip', 'frontflip', airtime);
        this._emitRotations(tricks, this._heliNet, '_heliDone', 'helicopterCCW', 'helicopterCW', airtime);
        this._emitRotations(tricks, this._corkscrewNet, '_corkscrewDone', 'corkscrew', 'corkscrew', airtime);
        landing = this._makeLanding(state, angle, t, false);
        landing.rotationDeg = rot;
      } else {
        tricks.length = 0;
      }
      this._air = false;
    }
    // A genuinely paid one-shot can land before the post-physics tracker
    // observes an airborne frame, or after a flight shorter than minAirtime.
    // Credit and SETTLE the physically paid trick on this actual touchdown;
    // otherwise ScoreManager.pending would leak into an unrelated later jump.
    // Do not inherit the previous flight's _airStart, multiplier or airtime.
    const airBrakeTouchdownMs=landing ? landing.airtimeMs
      : Math.min(this.minAirtimeMs,trackedAirMs);
    if (input.airBrakeKicked) {
      // Sled re-arms on real Matter contact, not UI samples; two consecutive
      // short touchdown-only pulses can both be valid without an intervening
      // rendered airborne frame. A held key without a pulse earns nothing.
      this._brakeDone = true;
      tricks.push({ type:'airBrake',count:1,rotationDeg:0,
        airtimeMs:airBrakeTouchdownMs });
    }
    if (!landing && (input.airBrakeKicked || pendingShortBrake)) {
        if (!trackedFlight) {
          // A paid kick and real touchdown can fit between tracker samples.
          // This is a NEW flight; no prior helicopter/corkscrew attempt may
          // downgrade its landing or contaminate its rotation totals.
          this._heliHeld=false;
          this._heliMax=0;
          this._tiltNet=0;
          this._heliNet=0;
          this._corkscrewNet=0;
        }
        const measured=this._makeLanding(state,angle,t,false);
        // Very short touches can bank their earned AirBrake trick, but may not
        // invent a perfect-landing bonus or an additional trick-speed launch.
        // Ordinary sloppy/crash safety classification still applies.
        landing={...measured, airtimeMs:airBrakeTouchdownMs, rotationDeg:0,
          midSpin:measured.midSpin, shortAirBrakeTouchdown:true,
          quality:measured.quality==='perfect'?'good':measured.quality};
    }
    this._prevAngle = angle;
    this._prevHeli = heli;
    this._havePrev = true;
    return { tricks, landing, airborne: false, airtimeMs: 0, rotationDeg: rot };
  }

  /** Forget in-progress air state (after respawn / reset). @returns {void} */
  reset() {
    this._air = false;
    this._airStart = 0;
    this._tiltNet = 0;
    this._heliNet = 0;
    this._tiltDone = 0;
    this._heliDone = 0;
    this._corkscrewNet = 0;
    this._corkscrewDone = 0;
    this._brakeMs = 0;
    this._chuteMs = 0;
    this._brakeDone = false;
    this._chuteDone = false;
    this._heliMax = 0;
    this._heliHeld = false;
    this._prevAngle = 0;
    this._prevHeli = null;
    this._havePrev = false;
  }

  /** Add this frame's rotation to the flip / helicopter buckets (see SledFrameState.heliDeg). */
  _accumulate(angle, heli, input) {
    const delta = angle - this._prevAngle;
    if (heli != null) {
      let hd = this._prevHeli != null ? heli - this._prevHeli : 0;
      if (Math.abs(hd) > 720) hd = 0; // the drawing's phase was re-based
      if (input.corkscrew) {
        // A composite pitch+yaw maneuver: only the corkscrew bucket scores its
        // yaw, preventing a single hold from double-scoring helis and flips.
        this._corkscrewNet += hd;
      } else {
        this._tiltNet += delta;
        this._heliNet += hd;
      }
    } else if (input.corkscrew) this._corkscrewNet += delta;
    else if (input.heli) this._heliNet += delta;
    else this._tiltNet += delta;
  }

  _emitRotations(out, net, doneKey, ccwType, cwType, airtime) {
    const turns = Math.floor((Math.abs(net) + FLIP_TOLERANCE_DEG) / 360);
    let done = this[doneKey];
    // direction flip resets nothing: count is of the current net, so re-spinning the other way re-earns nothing
    // until net exceeds what was already credited.
    while (done < turns) {
      done++;
      out.push({ type: net < 0 ? ccwType : cwType, count: done, rotationDeg: Math.abs(net), airtimeMs: airtime });
    }
    this[doneKey] = done;
  }

  _makeLanding(state, angle, t, crashFrame) {
    const ground = Number.isFinite(state.groundAngleDeg) ? state.groundAngleDeg : 0;
    const diff = wrapAngle(angle - ground);
    const th = (ground * Math.PI) / 180;
    // a crash frame is not a touchdown (the sled may be mid-air, e.g. a hazard hit): use its live velocity
    const pre = !crashFrame && Number.isFinite(state.impactVx) && Number.isFinite(state.impactVy);
    const vx = (pre ? state.impactVx : state.vx) || 0;
    const vy = (pre ? state.impactVy : state.vy) || 0;
    const impact = Math.max(0, -vx * pmath.sin(th) + vy * pmath.cos(th));
    // residual visual coast / a key nudge is not an unfinished spin: needs a real spin attempt or the key still down
    // _heliMax is only updated in the airborne branch, so fold in the touchdown frame's own spin
    const spunDeg = Math.max(this._heliMax, Math.abs(this._heliNet), Math.abs(this._corkscrewNet));
    const coast = typeof state.midSpin === 'number' && !this._heliHeld && spunDeg < MID_SPIN_MIN_DEG;
    const yaw = !coast && typeof state.midSpin === 'number' ? state.midSpin : 0;
    const yawAttempt = !coast && (spunDeg >= MID_SPIN_MIN_DEG || this._heliHeld);
    const heliPhase = typeof state.midSpin === "boolean" ? state.midSpin : yawAttempt ? yaw : 0;
    let { quality, hard } = classifyLanding(diff, impact, heliPhase);
    // Report whether yaw actually degraded the pitch-only landing.
    const base = classifyLanding(diff, impact, false).quality;
    const penalised = quality !== base;
    if (crashFrame) {
      quality = 'crash';
      hard = true;
    }
    return {
      quality,
      angleDeg: diff,
      impactSpeedPxS: impact,
      airtimeMs: t - this._airStart,
      hard,
      rotationDeg: this._tiltNet + this._heliNet,
      midSpin: penalised && !crashFrame,
    };
  }
}

const NO_INPUT = Object.freeze({ heli: 0, corkscrew: false, airBrake: false, parachute: false });/**
 * OWNER: input/audio/glitch engineer.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * VirtualPad = the single normalized input state. Keyboard, gamepad and touch overlay all write into it
 * (via InputRouter); everything else only READS it through InputRouter.poll().
 * Pure DOM/logic: no Phaser import (Jest-testable under jsdom).
 */
import { TouchOverlay } from './TouchOverlay.js';
import { deriveHeld } from './PadDerive.js';

export { deriveHeld };

/** Analog dead-zone (stick / device tilt). */
export const ANALOG_DEADZONE = 0.15;

export const EDGE_NAMES = ['hop', 'reset', 'pause', 'airBrake', 'parachute', 'confirm'];
export const HELD_NAMES = [
  'push', 'tuck', 'brake', 'hop', 'reset', 'airBrake', 'parachute', 'divebomb', 'corkscrew', 'pause', 'confirm',
  'tiltBack', 'tiltForward', 'heliLeft', 'heliRight',
];


/**
 * Normalized control state (design doc 4.1; where 4.1 and 12 disagree 4.1 wins: S = brake, A+D together = tuck).
 * Sign convention: tilt < 0 = tilt back = counter-clockwise (A), tilt > 0 = tilt forward = clockwise (D).
 * @typedef {Object} VirtualPadState
 * @property {boolean} push        W / right trigger / touch PUSH. Held.
 * @property {number}  tilt        -1..1 analog (keyboard: A=-1, D=+1, both = 0). Gamepad left stick X.
 * @property {boolean} tuck        A and D held together / gamepad tuck button / touch TUCK. Held.
 * @property {boolean} brake       S. Held.
 * @property {boolean} hop         Space. Held (use `pressed.hop` for the edge).
 * @property {boolean} reset       Shift. Held (use `pressed.reset`).
 * @property {-1|0|1}  heli        Left arrow = -1 (CCW), right arrow = +1 (CW), both/none = 0.
 * @property {boolean} airBrake    Up arrow. Held.
 * @property {boolean} parachute   Down arrow. Held (use `pressed.parachute` to trigger the 0.8 s stall).
 * @property {boolean} divebomb    Held aerodynamic downward plunge without horizontal deceleration.
 * @property {boolean} corkscrew   Held compound pitch+yaw aerial rotation.
 * @property {boolean} pause       Esc / Start. Held.
 * @property {{hop:boolean,reset:boolean,pause:boolean,airBrake:boolean,parachute:boolean,confirm:boolean}} pressed
 *           Edge flags: true for exactly ONE poll() after a press, then cleared (consumed by poll()).
 * @property {'keyboard'|'gamepad'|'touch'} lastSource  device that produced the most recent input.
 */

/** Most timeline entries kept between two polls; older ones fold into the timeline base (no unbounded growth). */
export const TIMELINE_MAX = 256;

/** @returns {VirtualPadState} all-neutral state. */
export function emptyPadState() {
  return {
    push: false, tilt: 0, tuck: false, brake: false, hop: false, reset: false, heli: 0,
    airBrake: false, parachute: false, divebomb: false, corkscrew: false, pause: false,
    pressed: { hop: false, reset: false, pause: false, airBrake: false, parachute: false, confirm: false },
    lastSource: 'keyboard',
  };
}

export class VirtualPad {
  constructor() {
    /** @type {VirtualPadState} */
    this.state = emptyPadState();
    /** name -> set of sources currently holding it (so keyboard release never cancels a touch hold). */
    this.held = {};
    for (const n of HELD_NAMES) this.held[n] = new Set();
    /** analog source -> raw value. @type {Object<string,number>} */
    this.analog = {};
    /** @type {TouchOverlay|null} */
    this.overlay = null;
    /** Raw holds at the last poll(), and every aggregate hold change since (issue #115 timeline). */
    this._timelineBase = this._heldBits();
    /** @type {{t:number|null,name:string,down:boolean}[]} */
    this._timeline = [];
  }

  /** @private @returns {Object<string,boolean>} */
  _heldBits() {
    const o = {};
    for (const n of HELD_NAMES) o[n] = this.held[n].size > 0;
    return o;
  }

  /** @private */
  _journal(name, down, t) {
    this._timeline.push({ t: Number.isFinite(t) ? t : null, name, down });
    if (this._timeline.length > TIMELINE_MAX) {
      const old = this._timeline.shift();
      this._timelineBase[old.name] = old.down;
    }
  }

  /**
   * Set a digital button. Names are the boolean fields of VirtualPadState plus 'tiltBack'/'tiltForward'/
   * 'heliLeft'/'heliRight' raw keys (the pad derives tilt/tuck/heli from them) and 'confirm' (edge only).
   * Unknown names are ignored. Each source is tracked separately.
   * @param {string} name
   * @param {boolean} down
   * @param {'keyboard'|'gamepad'|'touch'} source
   * @param {number} [timeStamp] when it happened, on the performance.now() clock (DOM event.timeStamp). Optional:
   *        untimed changes (gamepad, touch, blur) are scheduled from the first tick of the frame that polls them.
   * @returns {void}
   */
  setButton(name, down, source, timeStamp) {
    const set = this.held[name];
    if (!set) return;
    const src = source || 'keyboard';
    const was = set.size > 0;
    if (down) set.add(src);
    else set.delete(src);
    const now = set.size > 0;
    if (down) this.state.lastSource = src;
    if (now && !was && EDGE_NAMES.includes(name)) this.state.pressed[name] = true;
    if (now !== was) this._journal(name, now, timeStamp);
    this._recompute();
  }

  /**
   * Set analog tilt (gamepad stick, device tilt). Overrides digital tilt while |value| > deadzone 0.15.
   * Several analog sources may coexist; the one with the largest magnitude wins.
   * @param {number} value -1..1
   * @param {string} [source='gamepad'] analog source key ('gamepad' | 'device').
   * @returns {void}
   */
  setTilt(value, source = 'gamepad') {
    const v = Math.max(-1, Math.min(1, Number(value) || 0));
    if (this.analog[source] === v) return;
    this.analog[source] = v;
    if (Math.abs(v) > ANALOG_DEADZONE) this.state.lastSource = source === 'device' ? 'touch' : 'gamepad';
    this._recompute();
  }

  /** @private */
  _recompute() {
    Object.assign(this.state, deriveHeld(this._heldBits(), this._analogTilt()));
  }

  /** @private @returns {number} dead-zoned analog tilt from the strongest analog source, 0 if none. */
  _analogTilt() {
    let analog = 0;
    for (const k of Object.keys(this.analog)) {
      const v = this.analog[k];
      if (Math.abs(v) > ANALOG_DEADZONE && Math.abs(v) > Math.abs(analog)) {
        // rescale so the output starts at 0 just outside the dead-zone
        analog = Math.sign(v) * Math.min(1, (Math.abs(v) - ANALOG_DEADZONE) / (1 - ANALOG_DEADZONE));
      }
    }
    return analog;
  }

  /**
   * Release everything held by one source (window blur, gamepad disconnect, overlay hidden).
   * @param {'keyboard'|'gamepad'|'touch'} source
   * @returns {void}
   */
  releaseSource(source) {
    for (const n of HELD_NAMES) {
      const set = this.held[n];
      if (set.delete(source) && set.size === 0) this._journal(n, false, null);
    }
    if (source === 'gamepad') delete this.analog.gamepad;
    if (source === 'touch') delete this.analog.device;
    this._recompute();
  }

  /**
   * Snapshot current state and CLEAR the one-shot `pressed` edges.
   * The snapshot carries a non-enumerable `timeline` (issue #115): `{ base, events, analog }` = raw holds at the
   * previous poll, every aggregate hold change since in arrival order (`t` = event.timeStamp or null), and the
   * current analog tilt. SimClock.padsFor uses it to give each tick the input that happened inside its window.
   * @returns {VirtualPadState} a copy (safe to keep).
   */
  poll() {
    const out = { ...this.state, pressed: { ...this.state.pressed } };
    for (const n of EDGE_NAMES) this.state.pressed[n] = false;
    Object.defineProperty(out, 'timeline', {
      value: { base: this._timelineBase, events: this._timeline, analog: this._analogTilt() },
      enumerable: false,
    });
    this._timelineBase = this._heldBits();
    this._timeline = [];
    return out;
  }

  /**
   * Create/show the DOM touch overlay (buttons mirroring WASD/arrows) inside `parent`. No-op on non-touch
   * devices when settings.touchOverlay === 'auto'. Safe to call again (e.g. after settings change).
   * The overlay is only visible while setOverlayContext(true) was called (InputRouter does it on RUN_START).
   * @param {HTMLElement} parent usually game.canvas.parentElement.
   * @param {Pick<import('./SaveStore.js').Settings,'touchOverlay'|'touchRotate90'>} options
   * @returns {void}
   */
  mountTouchOverlay(parent, options) {
    if (typeof document === 'undefined') return;
    if (!this.overlay) this.overlay = new TouchOverlay(this);
    this.overlay.mount(parent, (options && options.touchOverlay) || 'auto');
    this.overlay.setControlLayout((options && options.controlLayout) || 'tricksRight');
  }

  /** @param {boolean} visible show/hide the overlay for the current context. @returns {void} */
  setOverlayContext(visible) {
    if (this.overlay) this.overlay.setContextVisible(visible);
  }

  /** Remove overlay and listeners. @returns {void} */
  destroy() {
    if (this.overlay) this.overlay.destroy();
    this.overlay = null;
    for (const n of HELD_NAMES) this.held[n].clear();
    this.analog = {};
    this.state = emptyPadState();
    this._timelineBase = this._heldBits();
    this._timeline = [];
  }
}/**
 * OWNER: gameplay engineer. Phaser-free and pure (no Math.random, no Date): unit-tested in tests/src/biome-effects.test.js.
 *
 * Wards (biome full treatment, B0; spec E2). A ward is a biome power-up that switches off its own biome's hazard or
 * mechanic for a few seconds ("Slick Wax Spray: prevents sticky terrain"). One state object holds every active ward;
 * `isWarded` is the single question every consumer asks:
 *   - PhysicsTuner.getEffective skips a zone whose mod id is warded;
 *   - RunScene.onHazard ignores a hit whose hazard id or effect is warded, and RunScene stops an active slow /
 *     scramble / blind effect from acting while it is warded.
 *
 * B1 (additive): a ward may carry a small speed boost (`speedFactor`, Slick Wax Spray 1.1) that lasts exactly as long as
 * the ward; `wardSpeedMul` is the product the frame's PhysicsTuner context multiplies into `speedBoost`.
 *
 * @typedef {{id:string, msLeft:number, mods:string[], hazards:string[], effects:string[], speedFactor:number}} Ward
 * @typedef {{wards: Ward[]}} WardState
 * @typedef {{modId?:string, hazardId?:string, effect?:string}} WardQuery  exactly one key is read, in that order.
 */

/** Spec §4: ward durations are 4-6 s. A def outside the band is clamped into it. */
export const WARD_MIN_MS = 4000;
export const WARD_MAX_MS = 6000;
/** B1: a ward's optional speed boost is clamped to [1, WARD_MAX_SPEED_FACTOR]: a small bonus, never a slow. */
export const WARD_MAX_SPEED_FACTOR = 1.2;

const NONE = Object.freeze([]);
const strList = (v) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string') : []);

/** @returns {WardState} */
export function emptyWards() {
  return { wards: [] };
}

/**
 * Add (or refresh) the ward of power-up `id`. Re-collecting the same power-up restarts its timer instead of stacking.
 * Does not mutate `state`.
 * @param {WardState} state
 * @param {string} id power-up def id.
 * @param {{durationMs?:number, mods?:string[], hazards?:string[], effects?:string[], speedFactor?:number}} effect the def's `effect`.
 * @returns {WardState}
 */
export function addWard(state, id, effect) {
  const e = effect || {};
  const d = Number.isFinite(e.durationMs) ? e.durationMs : WARD_MIN_MS;
  const ward = {
    id: String(id),
    msLeft: Math.min(WARD_MAX_MS, Math.max(WARD_MIN_MS, d)),
    mods: strList(e.mods),
    hazards: strList(e.hazards),
    effects: strList(e.effects),
    speedFactor: wardSpeedFactor(e.speedFactor),
  };
  const rest = (state && state.wards ? state.wards : []).filter((w) => w.id !== ward.id);
  return { wards: rest.concat([ward]) };
}

/**
 * Count every ward down by `dtMs`. Mutates `state` in place (called every frame; no allocation unless one expires).
 * @param {WardState} state
 * @param {number} dtMs
 * @returns {{state: WardState, expired: string[]}} the ids whose ward ended on this tick.
 */
export function tickWards(state, dtMs) {
  if (!state || !state.wards.length) return { state, expired: NONE };
  let expired = NONE;
  for (const w of state.wards) {
    w.msLeft -= dtMs;
    if (w.msLeft <= 0) expired = expired === NONE ? [w.id] : expired.concat([w.id]);
  }
  if (expired.length) state.wards = state.wards.filter((w) => w.msLeft > 0);
  return { state, expired };
}

/**
 * Is this mod / hazard / effect switched off by an active ward?
 * @param {WardState|null|undefined} state
 * @param {WardQuery} query
 * @returns {boolean}
 */
export function isWarded(state, query) {
  if (!state || !state.wards || !state.wards.length || !query) return false;
  let list;
  let key;
  if (query.modId != null) { list = 'mods'; key = query.modId; } else if (query.hazardId != null) { list = 'hazards'; key = query.hazardId; } else if (query.effect != null) { list = 'effects'; key = query.effect; } else return false;
  for (const w of state.wards) if (w.msLeft > 0 && w[list].includes(key)) return true;
  return false;
}

/** ms left on power-up `id`'s ward (0 when none). @param {WardState} state @param {string} id @returns {number} */
export function wardMsLeft(state, id) {
  if (!state || !state.wards) return 0;
  const w = state.wards.find((q) => q.id === id);
  return w ? Math.max(0, w.msLeft) : 0;
}

/** A ward's speed boost from its def value: 1 when absent, else clamped to [1, WARD_MAX_SPEED_FACTOR]. @param {number} f @returns {number} */
export function wardSpeedFactor(f) {
  return Number.isFinite(f) ? Math.min(WARD_MAX_SPEED_FACTOR, Math.max(1, f)) : 1;
}

/**
 * Product of the speed boosts of every active ward (1 when none carries one). RunScene multiplies it into the tuner
 * context's `speedBoost`, kept apart from the Packet Burst / Maple Wax boost so the two never overwrite each other.
 * @param {WardState|null|undefined} state
 * @returns {number}
 */
export function wardSpeedMul(state) {
  if (!state || !state.wards || !state.wards.length) return 1;
  let m = 1;
  for (const w of state.wards) if (w.msLeft > 0 && w.speedFactor > 1) m *= w.speedFactor;
  return m;
}/**
 * Small, visual-only reactive envelope for the in-run scenery.
 *
 * The released song-specific beat grids are UNVERIFIED. This class does
 * NOT synthesize a metronome, name onsets as quarter notes, or influence
 * music, physics, Gym READY, collision, scores, or the ledger.
 * The input is short-interval samples of the *audible original music mix*.
 * Positive transient changes make scenery squash; a quick spring-like decay
 * returns the world to its ordinary geometry between musical accents.
 */
import { resolveReduceMotion } from '../ui/Motion.js';

const clamp01 = n => Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0;

export function worldDanceMotionAllowed(settings, prefersReducedMotion = false) {
  // Match the actual persisted Auto/On/Off setting used throughout the UI.
  // Explicit OFF must override OS reduced motion; explicit ON must suppress
  // movement even without OS preference. Legacy boolean true is fail-safe.
  return settings?.worldDance !== false && settings?.reduceMotion !== true &&
    !resolveReduceMotion(settings?.reduceMotion, prefersReducedMotion);
}

/**
 * Read the audio engine's world-dance sample and synthetic meter for one render frame (issue #140).
 * Audio is presentation: a missing, muted or failing engine must give "no dance", never an exception.
 * An exception here escaped RunScene.renderFrame, and Phaser's RAF step reschedules itself only AFTER the
 * frame callback returns, so one throw stopped the game loop (and the simulation) for good.
 * @param {object|null|undefined} audio REG.AUDIO engine
 * @param {boolean} allowed worldDanceMotionAllowed(...)
 * @returns {{sample: any, meter: any}} nulls when not allowed, unavailable or failing
 */
export function readWorldDanceAudio(audio, allowed) {
  if (!allowed || !audio) return { sample: null, meter: null };
  try {
    const sample = audio.getWorldDanceSample?.() ?? null;
    const meter = sample ? audio.getSyntheticMeterTiming?.() ?? null : null;
    return { sample, meter };
  } catch (e) {
    // Log once so a real audio-engine bug stays visible; every later failure is silent "no dance".
    if (!readWorldDanceAudio.warned) {
      readWorldDanceAudio.warned = true;
      try { console.warn('[WorldDance] audio read failed; scenery dance disabled for this failure', e); } catch { /* no console */ }
    }
    return { sample: null, meter: null };
  }
}

/** Each biome interprets the same musical accents in its own visual voice.
 * These are cosmetic multipliers; the intensity never leaks to physics.
 */
const DANCE_MOTIF_STYLES=Object.freeze({
    ridges:[1,0.7,0], drift:[0.8,0.55,0], terraces:[0.6,0.4,0],
    currents:[0.6,0.75,0], facets:[0.65,0.35,0],
    stars:[0.6,0.2,0.25],
    'candy-stripes':[1,0.55,1],
    jellyfish:[0.65,0.35,0.85],
    'brass-pipes':[0.55,0.15,0.42],
    'dew-drops':[0.85,0.32,1],
    vents:[0.7,0.4,0.45],
});

export function biomeDanceStyle(motif, strength) {
  const p=clamp01(strength);
  const [sun,horizon,decor]=DANCE_MOTIF_STYLES[motif]||DANCE_MOTIF_STYLES.ridges;
  return {sun:clamp01(p*sun),horizon:clamp01(p*horizon),decor:clamp01(p*decor)};
}

export function sunDanceGeometry(pulse, radius = 40) {
  const p=clamp01(pulse);
  const r=Number.isFinite(radius)&&radius>0 ? radius : 40;
  return {widthRadius:r*(1+0.12*p),heightRadius:r*(1-0.09*p)};
}

export class WorldDanceEnvelope {
  constructor(){this.reset();}

  reset(){
    this.pulse=0;
    this.meterPulse=0;
    this.mixLevel=0;
    this.lastMeterRevision=null;
    this.lastBeatIndex=null;
    this.lastMeasureIndex=null;
    this.intensity=0;
    this.baseline=0;
    this.previous=0;
    this.lastSampleMs=null;
    this.lastAccentMs=-Infinity;
    this.revision=null;
    return 0;
  }

  /** Expose the deliberately restrained cosmetic envelope: transient accent
   * supplies rhythm, smoothed actual mix intensity supplies the dynamics.
   * No unverified grid, BPM, sound transport or time-driven oscillator.
   */
  get strength(){
    // The artificial meter never becomes gameplay timing. Its visible impact
    // is gated by the actual recorded mix: silence has no rhythmic bounce.
    const audible=clamp01((this.mixLevel-0.025)/0.14);
    return clamp01(this.pulse*(0.18+0.68*this.intensity)+
      this.meterPulse*(0.07+0.19*this.intensity)*audible);
  }

  /**
   * @param {Object|null} sample bass/mid energy, audio-clock milliseconds,
   *    transport revision (from read-only AudioSynth, or null for silence)
   * @param {number} dtMs render delta, clamped so background tabs don't pop
   */
  update(sample,dtMs,meter=null){
    if(!sample||!Number.isFinite(sample.timeMs)||
      typeof sample.revision!=='string'||
      !Number.isFinite(sample.bass)||!Number.isFinite(sample.mid))return this.reset();
    if(this.revision!==sample.revision ||
      (this.lastSampleMs!==null&&sample.timeMs<this.lastSampleMs))this.reset();
    this.revision=sample.revision;
    const dt=Number.isFinite(dtMs)?Math.max(0,Math.min(100,dtMs)):16.7;
    this.pulse*=Math.exp(-dt/165); // actual recording transient envelope
    this.meterPulse*=Math.exp(-dt/140); // short, cosmetic measure/beat accent
    // The public synthetic meter is not a real musical analysis. Check the
    // transport revision and edge indices; NEVER repeatedly trigger while
    // isMeasureStartBeat remains true over multiple render frames.
    if(meter?.timingKind==='synthetic-unverified'&&meter?.use==='cosmetic-only'&&
      meter?.trusted===false&&meter?.canAuthorizeGameplay===false&&
      meter.transportRevision===sample.revision&&
      Number.isSafeInteger(meter.beatIndex)&&meter.beatIndex>=0&&
      Number.isSafeInteger(meter.measureIndex)&&meter.measureIndex>=0){
      if(this.lastMeterRevision!==meter.transportRevision){
        this.lastMeterRevision=meter.transportRevision;
        this.lastBeatIndex=meter.beatIndex;
        this.lastMeasureIndex=meter.measureIndex;
      }else if(meter.beatIndex!==this.lastBeatIndex){
        const changedMeasure=meter.measureIndex!==this.lastMeasureIndex &&
          meter.beatInMeasure===1;
        this.meterPulse=Math.max(this.meterPulse,changedMeasure?0.85:0.32);
        this.lastBeatIndex=meter.beatIndex;
        this.lastMeasureIndex=meter.measureIndex;
      }
    }else{
      this.lastMeterRevision=null;
      this.lastBeatIndex=null;
      this.lastMeasureIndex=null;
    }
    if(this.lastSampleMs===sample.timeMs)return this.strength;
    const level=clamp01(0.76*sample.bass+0.24*sample.mid);
    this.mixLevel=level;
    if(this.lastSampleMs===null){
      this.baseline=level;
      this.previous=level;
      this.lastSampleMs=sample.timeMs;
      return this.strength;
    }
    const interval=Math.max(0,Math.min(200,sample.timeMs-this.lastSampleMs));
    this.lastSampleMs=sample.timeMs;
    // Distinguish a quiet passage from a loud chorus. Use the *recorded*
    // mixture's level, with attack faster than release, never a guessed BPM.
    const target=clamp01((level-.10)/.62);
    const smoothing=1-Math.exp(-interval/(target>this.intensity?220:900));
    this.intensity+=(target-this.intensity)*smoothing;
    const rise=level-this.previous;
    const above=level-this.baseline;
    // The adaptive baseline tracks slow changes, while sudden positive
    // accents survive. This avoids endless bobbing on a sustained note.
    this.baseline+= (level-this.baseline)*(1-Math.exp(-interval/650));
    this.previous=level;
    if(rise>0.017&&above>0.034&&sample.timeMs-this.lastAccentMs>=165){
      const impulse=clamp01((rise*4+above*3.3));
      this.pulse=Math.max(this.pulse,impulse);
      this.lastAccentMs=sample.timeMs;
    }
    return this.strength;
  }
}/**
 * OWNER: UI engineer. Phaser-free, like ProfileLayout: this returns boxes and the view only draws them.
 *
 * W5 achievements grid. Its own panel rather than extra rows on PROFILE, for a measured reason: PROFILE is
 * already 240px of the 270px canvas with 11 biome toggles and a BACK button at `h - 22`, so adding 29 rows
 * would either overflow the screen or shrink the font below the readable 5x7 grid. A paged panel keeps both
 * screens honest.
 *
 * Paging is computed here, not in the view, so "does every row fit above the BACK button" is a unit test.
 */
import { measureText } from './PixelFont.js';
import { ACHIEVEMENTS, visibleAchievements, progressFor, metricsFrom, groupedAchievements, GROUP_ORDER } from '../systems/Achievements.js';

export const ACH_PANEL = Object.freeze({ w: 432, h: 244 });

const PAD = 12;
const GLYPH_H = 8;

/** Rows per page. Row pitch 13 with a header row, leaving clear space above BACK at h - 22. */
export const ROWS_PER_PAGE = 13;

const GROUP_LABELS = Object.freeze({
  skill: 'SKILL', distance: 'DISTANCE', daily: 'DAILY', collection: 'COLLECTION', biomes: 'BIOMES',
});

/**
 * Section labels, in Achievements.GROUP_ORDER (decision 9). Derived rather than listed a second time: this
 * array used to say SKILL first while the grid actually drew DISTANCE first.
 */
export const GROUPS = Object.freeze(GROUP_ORDER.map((id) => Object.freeze({ id, label: GROUP_LABELS[id] || String(id).toUpperCase() })));

/**
 * Flatten the catalogue into display rows: a group header row, then its achievements.
 * @returns {Array<{kind:'header'|'row', label?:string, id?:string}>}
 */
export function achievementRows(profile) {
  // Catalogue introspection (no profile) retains all defs for source audits.
  // Actual player views always pass a profile and hide secret rows until earned.
  const defs = profile === undefined ? ACHIEVEMENTS : visibleAchievements(profile);
  const out = [];
  for (const g of groupedAchievements(defs)) {
    const meta = GROUPS.find((x) => x.id === g.group);
    out.push({ kind: 'header', label: meta ? meta.label : String(g.group).toUpperCase() });
    for (const a of g.items) out.push({ kind: 'row', id: a.id });
  }
  return out;
}

/** How many pages the grid needs. Always at least one, so an empty catalogue still renders a page. */
export function pageCount(rows = achievementRows()) {
  return Math.max(1, Math.ceil(rows.length / ROWS_PER_PAGE));
}

/** Clamp a page index into range, so a stale page number after an unlock cannot show a blank screen. */
export function clampPage(page, rows = achievementRows()) {
  const n = pageCount(rows);
  const p = Math.floor(Number(page) || 0);
  return Math.min(n - 1, Math.max(0, p));
}

/**
 * One page of rows with their drawn text, plus progress for the player's current state.
 *
 * The bar is a RATIO, not pixels: the view multiplies by its own width, so the layout never needs to know
 * the panel's inner geometry twice.
 *
 * @param {{profile?:Object, biomeCount?:number, streak?:number, dailyRuns?:number, page?:number}} o
 * @returns {{w:number,h:number,page:number,pages:number,items:Object[],rows:Object[],footer:Object}}
 */
export function achievementsLayout(o = {}) {
  const metrics = metricsFrom(o.profile, null, {
    biomeCount: o.biomeCount, streak: o.streak, dailyRuns: o.dailyRuns,
  });
  const unlocked = (o.profile && o.profile.achievements) || {};
  const rows = achievementRows(o.profile);
  const pages = pageCount(rows);
  const page = clampPage(o.page, rows);
  const start = page * ROWS_PER_PAGE;
  const slice = rows.slice(start, start + ROWS_PER_PAGE);

  const items = [];
  const outRows = [];
  let y = 24;
  for (const r of slice) {
    if (r.kind === 'header') {
      items.push(box(`h-${y}`, r.label, PAD, y, 'amber'));
      outRows.push({ kind: 'header', label: r.label, y });
      y += 13;
      continue;
    }
    const def = ACHIEVEMENTS.find((a) => a.id === r.id);
    if (!def) continue;
    const at = unlocked[def.id];
    const done = Number.isFinite(at);
    const pr = progressFor(def, metrics);
    // Done rows read in lime and full alpha; pending rows are dimmer so a glance shows what is left.
    items.push(box(`n-${def.id}`, def.name, PAD, y, done ? 'lime' : 'text', { alpha: done ? 1 : 0.75 }));
    const pct = `${pr.value}/${pr.target}`;
    items.push(box(`p-${def.id}`, pct, ACH_PANEL.w - PAD, y, done ? 'lime' : 'cyan', { align: 'right', alpha: done ? 1 : 0.8 }));
    outRows.push({ kind: 'row', id: def.id, name: def.name, y, done, ratio: pr.ratio, progress: pct, desc: def.desc });
    y += 13;
  }

  const footer = box('page', `PAGE ${page + 1}/${pages}`, PAD, ACH_PANEL.h - 20, 'magenta', { alpha: 0.9 });
  items.push(footer);

  return { w: ACH_PANEL.w, h: ACH_PANEL.h, page, pages, items, rows: outRows, footer };
}

/**
 * Build one text box, mirroring ProfileLayout's helper so the two screens' geometry tests agree.
 * @returns {Object}
 */
function box(key, text, x, y, color, o = {}) {
  const t = String(text === undefined || text === null ? '' : text);
  const align = o.align || 'left';
  const w = measureText(t);
  return {
    key, text: t,
    x: align === 'right' ? x - w : x,
    y, w, h: GLYPH_H, align, color,
    alpha: o.alpha === undefined ? 1 : o.alpha,
  };
}

/**
 * Rows that overlap any other drawn box. Empty is the pass condition; the same shape ProfileLayout's
 * suite asserts on.
 * @param {Object[]} items
 * @returns {Array<[string,string]>}
 */
export function overlappingPairs(items) {
  const out = [];
  for (let i = 0; i < items.length; i += 1) {
    for (let j = i + 1; j < items.length; j += 1) {
      const a = items[i];
      const b = items[j];
      const sep = a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y;
      if (!sep) out.push([a.key || a.text, b.key || b.text]);
    }
  }
  return out;
}

/**
 * The unlock toast on Game Over.
 *
 * Where it goes is constrained, not chosen. The CRASHED header is centred at scale 4, so its ink spans
 * roughly x 156..324, y 8..40; the RUN REPORT panel starts at y 54; the LEDGER panel is the right half.
 * That leaves the top-LEFT corner (x 14..152) as the only band a transient line can occupy without
 * covering something the player is reading. Measured from those three boxes, so the toast can never be
 * placed over the header by a future edit.
 *
 * Up to three lines at a 10 px pitch (y 14, 24, 34; the last ends at 42, inside maxY 46). Decision 9: the
 * names are listed in the order they were unlocked (the canonical catalogue order), so a run that reaches
 * x1.75 reads COMBO STARTER, CHAIN REACTION, UNBROKEN. More than three: two names and "+N MORE", rather
 * than a truncated run-on. One: its name and its description.
 */
export const TOAST_BOX = Object.freeze({ x: 14, y: 14, w: 138, maxY: 46 });

/** Lines the toast band holds (TOAST_BOX.y .. maxY at a 10 px pitch). */
export const TOAST_LINES = 3;

/**
 * @param {Array<Object>} added achievement defs newly unlocked, in catalogue order
 * @param {{ellipsize?:function(string,number):string}} [o] injected so this file stays Phaser-free
 * @returns {{lines:Array<Object>}|null} null when there is nothing to announce
 */
export function toastLayout(added, o = {}) {
  const list = Array.isArray(added) ? added.filter((a) => a && typeof a.name === 'string' && a.name) : [];
  if (!list.length) return null;
  const cut = typeof o.ellipsize === 'function' ? o.ellipsize : (s) => s;
  const lines = [];
  lines.push(box('toast-1', cut(`UNLOCKED ${list[0].name.toUpperCase()}`, TOAST_BOX.w), TOAST_BOX.x, TOAST_BOX.y, 'amber'));
  if (list.length > 1) {
    // Every name fits: list them all. Otherwise keep the last line for the count of the rest.
    const named = list.length <= TOAST_LINES ? list.length : TOAST_LINES - 1;
    for (let i = 1; i < named; i += 1) {
      lines.push(box(`toast-${i + 1}`, cut(list[i].name.toUpperCase(), TOAST_BOX.w), TOAST_BOX.x, TOAST_BOX.y + 10 * i, 'amber'));
    }
    const rest = list.length - named;
    if (rest > 0) lines.push(box('toast-n', `+${rest} MORE`, TOAST_BOX.x, TOAST_BOX.y + 10 * named, 'magenta', { alpha: 0.9 }));
  } else if (list[0].desc) {
    // A single unlock has room for its description, which is the whole point of announcing it.
    lines.push(box('toast-d', cut(String(list[0].desc).toUpperCase(), TOAST_BOX.w), TOAST_BOX.x, TOAST_BOX.y + 10, 'text', { alpha: 0.8 }));
  }
  return { lines };
}/**
 * OWNER: UI engineer.
 * Menu backdrop, synthwave v2: gradient sky, twinkling stars with the odd shooting star, a striped retro sun
 * whose slice gaps scroll, three parallax mountain ranges, a bright perspective grid floor, and an
 * attract-mode rider carving along the foothills (with the occasional hop and flip). `warp()` accelerates
 * the grid and ranges for a launch (START RUN).
 *
 * API (unchanged from v1, so Title, Game Over and anything else keep working):
 *   new Backdrop(scene, theme, {horizon?, alpha?, depth?})   then update(timeMs) every frame, destroy() when done.
 * Added: warp(o?) -> ms, and `reduced` (read-only: reduce motion is in effect this frame).
 *
 * Art: the sun, its glow, the mountain layers and the rider are authored SVGs (ui/MenuArt.js), white or
 * greyscale and tinted from the palette inside theme.bind, so colour-blind mode and UI themes apply. Any
 * texture that did not load falls back to a procedural drawing of the same thing (the mountains from the
 * very same MenuTerrain ridge functions the art was rasterised from).
 *
 * Reduce motion (Motion.isReducedMotion, read every frame so the setting applies live): stars hold still,
 * no shooting stars, the sun slices and the ranges stop, the grid creeps at a fraction of its speed, the
 * rider stays parked on the ridge without hops, and warp() is a no-op.
 *
 * Depth: every layer sits at `depth` + a small fraction (default -10), i.e. behind all menu content.
 * `alpha` scales the accent layers (sun, ranges, grid, rider) but not the sky, as v1 did.
 */
import { GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
import { artImage, artTileSprite, bindTint, mixColor, RIDER_ORIGIN } from './MenuArt.js';
import { MENU_LAYERS, MENU_LAYER_ORDER, MENU_TERRAIN_PERIOD, ridgeY, ridgeSlope } from './MenuTerrain.js';
import { isReducedMotion, Ease, clamp01, lerp } from './Motion.js';

const STAR_COUNT = 84;
const SUN_D = 112;

/**
 * Where the sun sits for a given horizon (pure, so a host's layout tests can keep panels off it): centred on
 * the screen, high enough that the far range bites into the slices rather than hiding them.
 * @param {number} horizon
 * @returns {{cx:number, cy:number, r:number, top:number, bottom:number}}
 */
export function sunGeometry(horizon) {
  const cy = horizon - Math.round(SUN_D * 0.55);
  return { cx: GAME_WIDTH / 2, cy, r: SUN_D / 2, top: cy - SUN_D / 2, bottom: cy + SUN_D / 2 };
}
/** Phaser.BlendModes.ADD; a literal so this module does not need Phaser itself. */
const BLEND_ADD = 1;
/** Rider: which range it rides, and its hop timing. */
const RIDER_LAYER = 'near';
const HOP_MS = 950;

/** mulberry32: deterministic star field (same sky every visit). */
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export class Backdrop {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{horizon?:number, alpha?:number, depth?:number, riderX?:number, riderRange?:number}} [o]
   *   riderX / riderRange: the centre and half-width of the band the attract rider drifts across (default
   *   320 / 60, the right half). A host whose layout covers that band can move the rider somewhere visible.
   */
  constructor(scene, theme, o = {}) {
    this.scene = scene;
    this.theme = theme;
    this.horizon = o.horizon === undefined ? 196 : o.horizon;
    this.alpha = o.alpha === undefined ? 1 : o.alpha;
    this.riderCx = o.riderX === undefined ? 320 : o.riderX;
    this.riderRange = o.riderRange === undefined ? 60 : o.riderRange;
    const d = o.depth === undefined ? -10 : o.depth;
    const hy = this.horizon;
    this.lastT = null;
    this.t = 0;
    this.reduced = false;
    // scroll state accumulates (warp changes the rate, so position is not a pure function of time)
    this.gridPhase = 0;
    this.layerScroll = { far: 0, mid: 0, near: 0 };
    this.sunPhase = 0;
    this.warpFrom = 0;
    this.warpMs = 0;
    /** @type {number[]} sky colour per row 0..horizon, for the sun's slice gaps */
    this.skyRows = [];

    this.sky = scene.add.graphics().setDepth(d);
    this.starsG = scene.add.graphics().setDepth(d + 0.01);
    this._makeStars();

    // --- sun: glow + disc (art or fallback) + the slice gaps overdrawn in sky colour
    const sun = sunGeometry(hy);
    this.sunX = sun.cx;
    this.sunY = sun.cy;
    this.sunGlow = artImage(scene, 'sunGlow', this.sunX, this.sunY, {
      theme, tint: 'magenta', alpha: 0.32 * this.alpha, depth: d + 0.02, blend: BLEND_ADD,
    });
    this.sun = artImage(scene, 'sun', this.sunX, this.sunY, {
      theme, tint: (pal) => [pal.amber, pal.amber, pal.magenta, pal.magenta], alpha: this.alpha, depth: d + 0.03,
    });
    this.sunG = scene.add.graphics().setDepth(d + 0.04);

    // --- mountains, back to front. Each layer's bottom row sits on the horizon line.
    // Ranges stay opaque (a translucent range let the sun show through the rock); `alpha` dims them toward
    // the sky instead. The violet is derived from the palette so colour-blind mode moves it too.
    const a = this.alpha;
    const tints = {
      far: (pal) => mixColor(pal.bg, pal.magenta, a),
      mid: (pal) => mixColor(pal.bg, mixColor(pal.magenta, pal.cyan, 0.45), a),
      near: (pal) => mixColor(pal.bg, pal.cyan, a),
    };
    this.layers = {};
    let ld = d + 0.05;
    for (const name of MENU_LAYER_ORDER) {
      const L = MENU_LAYERS[name];
      const top = hy - L.h + 1;
      const key = name === 'far' ? 'mountainsFar' : name === 'mid' ? 'mountainsMid' : 'mountainsNear';
      const sprite = artTileSprite(scene, key, 0, top, GAME_WIDTH, L.h, { theme, tint: tints[name], depth: ld });
      // fallback: the same ridge, drawn per frame
      const fallback = sprite ? null : scene.add.graphics().setDepth(ld);
      this.layers[name] = { sprite, fallback, top, tint: tints[name] };
      ld += 0.01;
      if (name === RIDER_LAYER) {
        this._makeRider(ld);
        ld += 0.01;
      }
    }

    // --- ground + grid in front of everything
    this.ground = scene.add.graphics().setDepth(ld + 0.01);
    this.g = this.ground; // v1 exposed its single Graphics as `g`; kept for anyone holding on to it

    this._unbind = theme.bind((pal) => this._paintSky(pal));
    this.update(0);
  }

  // ------------------------------------------------------------------ construction helpers

  _makeStars() {
    const r = rng(0x5eed5);
    const maxY = Math.max(20, this.horizon - 24);
    this.stars = [];
    for (let i = 0; i < STAR_COUNT; i++) {
      const big = r() < 0.12;
      this.stars.push({
        x: Math.floor(r() * GAME_WIDTH),
        // denser toward the top, thinning into the horizon glow
        y: Math.floor(Math.pow(r(), 1.5) * maxY),
        big,
        hue: r() < 0.7 ? 'text' : r() < 0.5 ? 'cyan' : 'magenta',
        speed: 0.6 + r() * 1.6,
        phase: r() * Math.PI * 2,
      });
    }
    this.shooting = null;
    this.nextShootAt = 3000 + r() * 4000;
    this.rand = rng(0xc0ffee);
  }

  _makeRider(depth) {
    const scene = this.scene;
    const parts = [
      ['riderBase', null],
      ['riderSled', (pal) => pal.cyan],
      ['riderBody', (pal) => pal.magenta],
      ['riderHelmet', (pal) => pal.amber],
    ];
    const imgs = [];
    for (const [name, tint] of parts) {
      const img = artImage(scene, name, 0, 0, {
        theme: this.theme, tint: tint || undefined, originX: RIDER_ORIGIN.x, originY: RIDER_ORIGIN.y, depth,
      });
      if (!img) break;
      imgs.push(img);
    }
    if (imgs.length === parts.length) {
      this.riderParts = imgs;
      this.riderG = null;
    } else {
      // fallback: a tiny procedural sled + rider in local space, positioned/rotated as one Graphics
      for (const img of imgs) img.destroy();
      this.riderParts = null;
      this.riderG = scene.add.graphics().setDepth(depth);
      this._riderUnbind = this.theme.bind((pal) => {
        const g = this.riderG;
        if (!g) return;
        g.clear();
        g.fillStyle(pal.bg, 1);
        g.fillRect(-11, -4, 22, 4);
        g.fillStyle(pal.cyan, 1);
        g.fillRect(-10, -2, 19, 1);
        g.fillRect(-10, -4, 18, 1);
        g.fillRect(9, -3, 1, 1);
        g.fillStyle(pal.magenta, 1);
        g.fillRect(-5, -11, 4, 6);
        g.fillRect(-1, -7, 5, 2);
        g.fillStyle(pal.amber, 1);
        g.fillRect(-3, -15, 4, 4);
      });
    }
    this.riderX = this.riderCx + 10;
    this.hopStart = -1;
    this.nextHopAt = 5000;
    /** Current hop's height (px) and full flips; trick() raises both for one hop. */
    this.hopH = 16;
    this.hopFlips = 1;
    this.hopMs = HOP_MS;
  }

  // ------------------------------------------------------------------ painting

  /** Static sky: per-row gradient from bg at the top through a deep violet to a magenta-hot horizon. */
  _paintSky(pal) {
    const g = this.sky;
    if (!g) return;
    const hy = this.horizon;
    g.clear();
    g.fillStyle(pal.bg, 1);
    g.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
    const mid = mixColor(pal.bg, mixColor(pal.magenta, pal.cyan, 0.3), 0.16);
    const hot = mixColor(pal.bg, pal.magenta, 0.42);
    this.skyRows = [];
    for (let y = 0; y <= hy; y++) {
      const t = y / Math.max(1, hy);
      // stays dark for the top third, then warms quickly toward the horizon
      const c = t < 0.45 ? mixColor(pal.bg, mid, Ease.inQuad(t / 0.45)) : mixColor(mid, hot, Ease.inQuad((t - 0.45) / 0.55));
      this.skyRows[y] = c;
      g.fillStyle(c, 1);
      g.fillRect(0, y, GAME_WIDTH, 1);
    }
    this.groundBase = pal.bgAlt;
    this.groundHaze = mixColor(pal.bgAlt, pal.magenta, 0.2);
    // the sun's fallback disc and gaps depend on the sky colour, so repaint the dynamic layers now
    if (this.lastT !== null) this._drawDynamic(this.t, 0);
  }

  /**
   * Accelerate the grid and ranges for a launch: a quick ramp to ~9x, held until the scene moves on.
   * No-op under reduce motion.
   * @param {{duration?:number}} [o] ramp duration (default 700 ms)
   * @returns {number} the ramp duration in ms (0 when reduced), so a caller can time its scene change
   */
  warp(o = {}) {
    if (isReducedMotion(this.scene)) return 0;
    this.warpFrom = this.t;
    this.warpMs = o.duration || 700;
    return this.warpMs;
  }

  /**
   * Make the attract rider throw a big trick now: a higher hop with a double flip. No-op under reduce motion
   * or while a hop is already in the air (it never cuts a flip short).
   * @param {{height?:number, flips?:number, duration?:number}} [o]
   * @returns {boolean} whether a trick started
   */
  trick(o = {}) {
    if (isReducedMotion(this.scene) || (!this.riderParts && !this.riderG) || this.hopStart >= 0) return false;
    this.hopStart = this.t;
    this.hopH = o.height || 30;
    this.hopFlips = o.flips || 2;
    this.hopMs = o.duration || 1500;
    // the regular hop waits until this one has landed
    this.nextHopAt = Math.max(this.nextHopAt, this.t + this.hopMs + 2500);
    return true;
  }

  /** Current speed multiplier from warp(). */
  _warpFactor() {
    if (!this.warpMs || this.reduced) return 1;
    return lerp(1, 9, Ease.inCubic(clamp01((this.t - this.warpFrom) / this.warpMs)));
  }

  /** @param {number} timeMs @returns {void} */
  update(timeMs) {
    if (!this.sky) return;
    const dt = this.lastT === null ? 0 : Math.min(100, Math.max(0, timeMs - this.lastT));
    this.lastT = timeMs;
    this.t = timeMs;
    this.reduced = isReducedMotion(this.scene);
    const warp = this._warpFactor();
    const s = dt / 1000;
    if (!this.reduced) {
      for (const name of MENU_LAYER_ORDER) this.layerScroll[name] += MENU_LAYERS[name].speed * warp * s;
      this.sunPhase += 5 * s;
    }
    // the grid keeps a slow creep even when reduced: a frozen floor reads as a hung game
    this.gridPhase += (this.reduced ? 0.08 : 0.6) * warp * s;
    this._drawDynamic(timeMs, dt);
  }

  /** v1 name, kept: redraw at a time. @param {number} timeMs */
  draw(timeMs) {
    this.update(timeMs);
  }

  _drawDynamic(t, dt) {
    const pal = this.theme.pal;
    this._drawStars(pal, t, dt);
    this._drawSun(pal);
    for (const name of MENU_LAYER_ORDER) {
      const L = this.layers[name];
      const off = Math.floor(this.layerScroll[name]) % MENU_TERRAIN_PERIOD;
      if (L.sprite) L.sprite.tilePositionX = off;
      else if (L.fallback) this._drawRangeFallback(L.fallback, name, off, L.top, L.tint(pal), pal);
    }
    this._drawRider(pal, t, dt);
    this._drawGrid(pal, t);
  }

  _drawStars(pal, t, dt) {
    const g = this.starsG;
    g.clear();
    const a = this.alpha;
    for (const st of this.stars) {
      const tw = this.reduced ? 0.7 : 0.5 + 0.5 * Math.sin(t * 0.001 * st.speed + st.phase);
      const c = pal[st.hue];
      if (st.big) {
        g.fillStyle(c, (0.35 + 0.6 * tw) * a);
        g.fillRect(st.x, st.y, 1, 1);
        // a cross-shaped twinkle on the bright ones
        if (tw > 0.75) {
          g.fillStyle(c, 0.35 * (tw - 0.75) * 4 * a);
          g.fillRect(st.x - 1, st.y, 3, 1);
          g.fillRect(st.x, st.y - 1, 1, 3);
        }
      } else {
        g.fillStyle(c, (0.15 + 0.45 * tw) * a);
        g.fillRect(st.x, st.y, 1, 1);
      }
    }
    // shooting star: a short diagonal streak with a fading tail, every few seconds
    if (this.reduced) { this.shooting = null; return; }
    if (!this.shooting && t >= this.nextShootAt) {
      const r = this.rand;
      this.shooting = { x: 60 + r() * (GAME_WIDTH - 120), y: 6 + r() * (this.horizon * 0.35), born: t, vx: -(180 + r() * 120), vy: 70 + r() * 40 };
      this.nextShootAt = t + 5000 + r() * 7000;
    }
    const sh = this.shooting;
    if (sh) {
      const age = (t - sh.born) / 1000;
      if (age > 0.7) { this.shooting = null; return; }
      const life = 1 - age / 0.7;
      const hx = sh.x + sh.vx * age;
      const hy = sh.y + sh.vy * age;
      for (let i = 0; i < 14; i++) {
        const k = i / 14;
        g.fillStyle(i === 0 ? pal.text : pal.cyan, (1 - k) * life * a);
        g.fillRect(Math.round(hx - sh.vx * 0.04 * k), Math.round(hy - sh.vy * 0.04 * k), 1, 1);
      }
    }
  }

  _drawSun(pal) {
    const g = this.sunG;
    g.clear();
    const r = SUN_D / 2;
    const top = Math.round(this.sunY - r);
    const cx = this.sunX;
    const chord = (y) => {
      const dy = y + 0.5 - this.sunY;
      return dy * dy >= r * r ? 0 : Math.sqrt(r * r - dy * dy);
    };
    if (!this.sun) {
      // fallback disc: amber top to magenta bottom, row by row
      for (let y = top; y < top + SUN_D && y <= this.horizon; y++) {
        const hw = chord(y);
        if (hw <= 0) continue;
        g.fillStyle(mixColor(pal.amber, pal.magenta, (y - top) / SUN_D), this.alpha);
        g.fillRect(Math.round(cx - hw), y, Math.round(hw * 2), 1);
      }
    }
    // slice gaps over the lower 60% of the disc, thickening toward the bottom and drifting downward
    const start = top + Math.round(SUN_D * 0.4);
    const end = top + SUN_D;
    const P = 9;
    const off = this.sunPhase % P;
    for (let y0 = start - P + off; y0 < end; y0 += P) {
      const f = clamp01((y0 - start) / (end - start));
      const thick = Math.max(1, Math.round(1 + f * 5));
      for (let y = Math.round(y0); y < Math.round(y0) + thick; y++) {
        if (y < start || y >= end || y > this.horizon) continue;
        const hw = chord(y);
        if (hw <= 0) continue;
        g.fillStyle(this.skyRows[y] !== undefined ? this.skyRows[y] : pal.bg, 1);
        g.fillRect(Math.floor(cx - hw) - 1, y, Math.ceil(hw * 2) + 2, 1);
      }
    }
  }

  /** Procedural stand-in for a mountain layer whose SVG did not load: the same ridge, rim and body. */
  _drawRangeFallback(g, name, off, top, color, pal) {
    g.clear();
    const L = MENU_LAYERS[name];
    let prev = top + ridgeY(name, off - 1);
    for (let x = 0; x < GAME_WIDTH; x++) {
      const y = top + ridgeY(name, x + off);
      // opaque body (like the art), then a rim that spans to the previous column so steep slopes stay joined
      g.fillStyle(mixColor(pal.bg, color, 0.22), 1);
      g.fillRect(x, y, 1, top + L.h - y);
      g.fillStyle(color, 1);
      g.fillRect(x, Math.min(y, prev + 1), 1, Math.max(1, Math.abs(y - prev)));
      prev = y;
    }
  }

  _drawRider(pal, t, dt) {
    if (!this.riderParts && !this.riderG) return;
    const L = this.layers[RIDER_LAYER];
    // drift slowly back and forth across the right half so the carve reads as speed changes
    if (!this.reduced) this.riderX = this.riderCx + this.riderRange * Math.sin(t / 7000);
    const worldX = this.riderX + Math.floor(this.layerScroll[RIDER_LAYER]);
    let y = L.top + ridgeY(RIDER_LAYER, worldX);
    let rot = ridgeSlope(RIDER_LAYER, worldX);
    // the hop: a parabola with a full backflip, every 6-10 s
    if (!this.reduced) {
      if (this.hopStart < 0 && t >= this.nextHopAt) {
        this.hopStart = t;
        this.hopH = 16;
        this.hopFlips = 1;
        this.hopMs = HOP_MS;
        this.nextHopAt = t + 6000 + this.rand() * 4000;
      }
      if (this.hopStart >= 0) {
        const p = (t - this.hopStart) / this.hopMs;
        if (p >= 1) this.hopStart = -1;
        else {
          y -= Math.round(this.hopH * 4 * p * (1 - p));
          rot -= Math.PI * 2 * this.hopFlips * Ease.inOutCubic(p);
        }
      }
    } else this.hopStart = -1;
    const objs = this.riderParts || [this.riderG];
    for (const o of objs) {
      o.setPosition(Math.round(this.riderX), y);
      o.setRotation(rot);
      o.setAlpha(this.alpha);
    }
  }

  _drawGrid(pal, t) {
    const g = this.ground;
    g.clear();
    const hy = this.horizon;
    const a = this.alpha;
    const depthH = GAME_HEIGHT - hy;
    const warpGlow = clamp01((this._warpFactor() - 1) / 8);
    // The floor is opaque and in front of the sun and ranges: it hides the disc's lower part below the
    // horizon, which is what sets the sun "into" the grid.
    g.fillStyle(this.groundBase === undefined ? pal.bgAlt : this.groundBase, 1);
    g.fillRect(0, hy + 1, GAME_WIDTH, depthH);
    g.fillStyle(this.groundHaze === undefined ? pal.bgAlt : this.groundHaze, 1);
    g.fillRect(0, hy + 1, GAME_WIDTH, 4);
    g.fillStyle(this.groundHaze === undefined ? pal.bgAlt : this.groundHaze, 0.5);
    g.fillRect(0, hy + 5, GAME_WIDTH, 4);
    // horizontal lines: perspective spacing (quadratic), fading in from the horizon, brighter with warp
    const rows = 12;
    const ph = this.gridPhase % 1;
    for (let i = 0; i < rows; i++) {
      const f = (i + ph) / rows;
      const y = Math.round(hy + depthH * f * f);
      if (y <= hy) continue;
      g.fillStyle(pal.cyan, (0.12 + 0.55 * f + 0.25 * warpGlow) * a);
      g.fillRect(0, y, GAME_WIDTH, 1);
    }
    // vertical lines converging on the vanishing point at the sun's centre column
    const vx = this.sunX;
    for (let i = -14; i <= 14; i++) {
      const x1 = vx + i * 46;
      g.lineStyle(1, pal.cyan, (0.18 + 0.1 * (1 - Math.abs(i) / 14) + 0.2 * warpGlow) * a);
      g.lineBetween(vx + i * 6, hy + 1, x1, GAME_HEIGHT);
    }
    // the horizon: hot magenta under a crisp cyan line, with a soft glow above
    g.fillStyle(pal.magenta, 0.18 * a);
    g.fillRect(0, hy - 2, GAME_WIDTH, 2);
    g.fillStyle(pal.cyan, 0.9 * a);
    g.fillRect(0, hy, GAME_WIDTH, 1);
    g.fillStyle(pal.magenta, 0.5 * a);
    g.fillRect(0, hy + 1, GAME_WIDTH, 1);
  }

  /** @returns {void} */
  destroy() {
    if (this._unbind) this._unbind();
    this._unbind = null;
    if (this._riderUnbind) this._riderUnbind();
    this._riderUnbind = null;
    const kill = (o) => { if (o && o.scene) o.destroy(); };
    kill(this.sky); kill(this.starsG); kill(this.sunGlow); kill(this.sun); kill(this.sunG); kill(this.ground);
    for (const name of MENU_LAYER_ORDER) {
      const L = this.layers && this.layers[name];
      if (L) { kill(L.sprite); kill(L.fallback); }
    }
    for (const o of this.riderParts || []) kill(o);
    kill(this.riderG);
    this.sky = null;
    this.g = null;
    this.ground = null;
  }
}/**
 * OWNER: gameplay engineer.
 * Authored in-run backdrop art (public/assets/backdrop/*.svg, generated by tools/backdrop-art): texture keys, native
 * sizes and the loader queue. Same rules as the menu art (ui/MenuArt.js):
 *  1. Accent colour is never baked. The art is white/greyscale and is tinted from the live palette, so colour-blind mode
 *     and each biome's tint recolour it.
 *  2. Art is optional. A file that 404s or fails to decode never becomes a texture, and BiomeFx falls back to the
 *     procedural Background drawing, so a missing asset can never block a run.
 *
 * Each SVG is rasterised once, 1:1 at its native size (`load.svg(key, url, {width, height})`), and `pixelArt: true`
 * keeps it crisp; every placement is on whole pixels.
 */

/** Relative (no leading slash) so the game also works under a sub-path; Vite serves public/ at the site root. */
export const BACKDROP_ART_BASE = 'assets/backdrop/';

/** @type {Readonly<Object<string, Readonly<{key:string, file:string, w:number, h:number}>>>} */
export const BACKDROP_ART = Object.freeze({
  debutmontSky: Object.freeze({ key: 'bd-debutmont-sky', file: 'debutmont-sky.svg', w: 480, h: 160 }),
  debutmontRidgeFar: Object.freeze({ key: 'bd-debutmont-ridge-far', file: 'debutmont-ridge-far.svg', w: 960, h: 208 }),
  debutmontRidgeNear: Object.freeze({ key: 'bd-debutmont-ridge-near', file: 'debutmont-ridge-near.svg', w: 960, h: 160 }),
  arcadeSky: Object.freeze({ key: 'bd-arcade-sky', file: 'arcade-sky.svg', w: 480, h: 120 }),
  arcadeSun: Object.freeze({ key: 'bd-arcade-sun', file: 'arcade-sun.svg', w: 112, h: 60 }),
  arcadeSkyline: Object.freeze({ key: 'bd-arcade-skyline', file: 'arcade-skyline.svg', w: 480, h: 48 }),
});

/**
 * Queue every backdrop SVG on a loader (call from a scene's preload()). Tolerates loaders without svg support
 * (headless/Jest stubs) by queuing nothing.
 * @param {Phaser.Loader.LoaderPlugin|any} load
 * @returns {number} files queued
 */
export function queueBackdropArt(load) {
  if (!load || typeof load.svg !== 'function') return 0;
  let n = 0;
  for (const a of Object.values(BACKDROP_ART)) {
    if (load.textureManager && typeof load.textureManager.exists === 'function' && load.textureManager.exists(a.key)) continue;
    load.svg(a.key, BACKDROP_ART_BASE + a.file, { width: a.w, height: a.h });
    n++;
  }
  return n;
}

/**
 * Did this texture load? False for unknown names, Phaser's placeholder textures and scenes without a texture manager.
 * @param {Phaser.Scene} scene @param {string} name BACKDROP_ART name @returns {boolean}
 */
export function hasBackdropArt(scene, name) {
  const a = BACKDROP_ART[name];
  const tm = scene && scene.textures;
  if (!a || !tm || typeof tm.exists !== 'function') return false;
  try {
    return tm.exists(a.key) === true;
  } catch (e) {
    return false;
  }
}/**
 * OWNER: UI engineer.
 * Small pointer/touch button: bordered box + label (+ optional hotkey hint). Keyboard/gamepad users reach the same
 * actions through scene-level hotkeys; Button handles mouse and touch.
 *
 * Look: dark glass face with a neon border; hover lights a soft outer glow (falling-alpha strokes outside the
 * box, like Panel) and a brighter face; a press flashes the face bright and fades it out (flash(), also
 * callable by a host that triggers the button from a hotkey so keyboard users see the same feedback).
 * The hit zone is exactly the w x h box; the glow is paint only.
 */
import Phaser from 'phaser';
import { NeonText, strokeRectPx, glowRectPx } from './Neon.js';
import { uiSfx } from './Sound.js';
import { tweenProgress, Ease, isReducedMotion, REDUCED_MS } from './Motion.js';

export class Button extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,w:number,h?:number,label:string,hint?:string,color?:string,onClick:function():void,parent?:Phaser.GameObjects.Container}} o
   * x,y = top-left.
   */
  constructor(scene, theme, o) {
    super(scene, o.x, o.y);
    this.theme = theme;
    this.w = o.w;
    this.h = o.h || 16;
    this.colorKey = o.color || 'cyan';
    this.hover = false;
    this.disabled = false;
    this.flashT = 0; // 1 = press flash at full strength, decays to 0
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    this.label = new NeonText(scene, theme, this.w / 2, this.h / 2 + (o.hint ? -3 : 0), o.label, {
      color: this.colorKey, anchor: 'center', vAnchor: 0.5,
    });
    this.add(this.label);
    this.hintText = null;
    if (o.hint) {
      this.hintText = new NeonText(scene, theme, this.w / 2, this.h - 6, o.hint, {
        color: 'text', anchor: 'center', vAnchor: 0.5, outline: 'none',
      });
      this.hintText.setAlpha(0.6);
      this.add(this.hintText);
    }
    this.zone = new Phaser.GameObjects.Zone(scene, 0, 0, this.w, this.h).setOrigin(0, 0);
    this.zone.setInteractive({ useHandCursor: true });
    this.add(this.zone);
    this.zone.on('pointerover', () => this.setHover(true));
    this.zone.on('pointerout', () => this.setHover(false));
    this.zone.on('pointerdown', () => {
      if (this.disabled) return;
      uiSfx(scene, 'uiSelect');
      this.flash();
      o.onClick();
    });
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind(() => this._paint());
  }

  setHover(v) {
    this.hover = v;
    this._paint();
  }

  /** @param {string} str @returns {this} */
  setLabel(str) {
    this.label.setText(str);
    return this;
  }

  /** @param {boolean} d @returns {this} */
  setDisabled(d) {
    this.disabled = d;
    this.setAlpha(d ? 0.4 : 1);
    return this;
  }

  /** Bright press flash that fades out (shorter under reduce motion; it is feedback, not motion). */
  flash() {
    if (this._flashTween && typeof this._flashTween.remove === 'function') this._flashTween.remove();
    this.flashT = 1;
    this._paint();
    this._flashTween = tweenProgress(this.scene, {
      duration: isReducedMotion(this.scene) ? REDUCED_MS : 240,
      ease: Ease.outQuad,
      onUpdate: (p) => {
        if (!this.scene) return;
        this.flashT = 1 - p;
        this._paint();
      },
      onComplete: () => { this._flashTween = null; },
    });
    return this;
  }

  _paint() {
    const pal = this.theme.pal;
    if (!pal || !this.g) return;
    const c = pal[this.colorKey];
    const g = this.g;
    const { w, h } = this;
    g.clear();
    if (this.hover && !this.disabled) {
      // soft glow outside the box
      glowRectPx(g, 0, 0, w, h, c, 1.5);
    }
    g.fillStyle(pal.bgAlt, 0.95);
    g.fillRect(0, 0, w, h);
    // face: a hint of the accent at rest, more on hover; a top-half sheen gives it a glass bevel
    g.fillStyle(c, this.hover ? 0.24 : 0.07);
    g.fillRect(1, 1, w - 2, h - 2);
    g.fillStyle(pal.text, this.hover ? 0.1 : 0.04);
    g.fillRect(1, 1, w - 2, Math.floor((h - 2) / 2));
    if (this.flashT > 0) {
      g.fillStyle(c, 0.75 * this.flashT);
      g.fillRect(1, 1, w - 2, h - 2);
    }
    strokeRectPx(g, 0, 0, w, h, c, this.hover ? 1 : 0.7);
    // bright bottom edge on hover: the "lit" key
    if (this.hover) {
      g.fillStyle(c, 1);
      g.fillRect(1, h - 2, w - 2, 1);
    }
    this.label.setColorKey(this.flashT > 0.5 ? 'text' : this.colorKey);
  }

  destroy(fromScene) {
    if (this._flashTween && typeof this._flashTween.remove === 'function') this._flashTween.remove();
    this._flashTween = null;
    if (this._unbind) this._unbind();
    this._unbind = null;
    super.destroy(fromScene);
  }
}/**
 * OWNER: UI engineer.
 * Clipboard helper with fallbacks. Resolves true if the text reached the clipboard.
 */

/**
 * @param {string} text
 * @returns {Promise<boolean>}
 */
export async function copyText(text) {
  try {
    if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch (e) {
    /* fall through to execCommand */
  }
  let ta = null;
  try {
    ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0';
    document.body.appendChild(ta);
    ta.select();
    return !!document.execCommand('copy');
  } catch (e) {
    return false;
  } finally {
    // A throwing execCommand used to skip the remove and leave a focused, invisible textarea in the page,
    // which then swallowed the next keystrokes.
    if (ta) ta.remove();
  }
}/**
 * OWNER: UI engineer.
 * A real DOM input/textarea positioned over the canvas, for things canvas text cannot do: typing seeds on touch
 * devices (summons the virtual keyboard), pasting and selecting sharecodes. Positioned in the 480x270 virtual
 * canvas space and re-aligned every frame. Keyboard events are stopped at the element so neither Phaser nor the
 * InputRouter sees what is typed. Removed on scene shutdown.
 */
import Phaser from 'phaser';
import { GAME_WIDTH, GAME_HEIGHT } from '../constants.js';

export class DomTextBox {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,w:number,h:number,multiline?:boolean,readOnly?:boolean,value?:string,maxLength?:number,
   *          placeholder?:string,onSubmit?:function(string):void,onCancel?:function():void,color?:string}} o
   */
  constructor(scene, theme, o) {
    this.scene = scene;
    this.theme = theme;
    this.o = o;
    const el = document.createElement(o.multiline ? 'textarea' : 'input');
    if (!o.multiline) el.type = 'text';
    el.value = o.value || '';
    if (o.maxLength) el.maxLength = o.maxLength;
    if (o.placeholder) el.placeholder = o.placeholder;
    el.readOnly = !!o.readOnly;
    el.spellcheck = false;
    el.autocomplete = 'off';
    el.setAttribute('autocapitalize', 'off');
    el.setAttribute('aria-label', o.placeholder || 'text');
    el.style.cssText = 'position:fixed;z-index:50;box-sizing:border-box;margin:0;resize:none;outline:none;' +
      'font-family:ui-monospace,Menlo,Consolas,monospace;border-radius:0;overflow:hidden;';
    el.addEventListener('keydown', (e) => {
      e.stopPropagation();
      if (e.key === 'Escape') {
        e.preventDefault();
        if (o.onCancel) o.onCancel();
      } else if (e.key === 'Enter' && (!o.multiline || e.ctrlKey || e.metaKey || o.readOnly)) {
        e.preventDefault();
        if (o.onSubmit) o.onSubmit(el.value);
      }
    });
    el.addEventListener('keyup', (e) => e.stopPropagation());
    el.addEventListener('keypress', (e) => e.stopPropagation());
    el.addEventListener('focus', () => this._style(true));
    el.addEventListener('blur', () => this._style(false));
    document.body.appendChild(el);
    this.el = el;
    this.lastKey = '';
    this._style(false);
    this._reposition();
    this._onUpdate = () => this._reposition();
    scene.events.on(Phaser.Scenes.Events.UPDATE, this._onUpdate);
    this._cleanup = () => this.destroy();
    scene.events.once('shutdown', this._cleanup);
    scene.events.once('destroy', this._cleanup);
    this._unbind = theme.bind(() => this._style(document.activeElement === el));
  }

  _style(focused) {
    if (!this.el) return;
    const css = this.theme.css;
    this.el.style.background = css.bg;
    this.el.style.color = css.text;
    this.el.style.caretColor = css.lime;
    this.el.style.border = `1px solid ${focused ? css.lime : css[this.o.color || 'cyan']}`;
    // a neon halo: faint at rest in the box's own colour, brighter plus an inner glow when focused
    this.el.style.boxShadow = focused
      ? `0 0 8px ${css.lime}99, inset 0 0 6px ${css.lime}33`
      : `0 0 4px ${css[this.o.color || 'cyan']}44`;
  }

  _reposition() {
    const el = this.el;
    const canvas = this.scene.game.canvas;
    if (!el || !canvas) return;
    const r = canvas.getBoundingClientRect();
    const sx = r.width / GAME_WIDTH;
    const sy = r.height / GAME_HEIGHT;
    const key = `${r.left}|${r.top}|${sx}|${sy}`;
    if (key === this.lastKey) return;
    this.lastKey = key;
    const o = this.o;
    el.style.left = `${r.left + o.x * sx}px`;
    el.style.top = `${r.top + o.y * sy}px`;
    el.style.width = `${o.w * sx}px`;
    el.style.height = `${o.h * sy}px`;
    el.style.fontSize = `${Math.max(10, 8 * sy)}px`;
    el.style.padding = `${2 * sy}px ${3 * sx}px`;
  }

  /** @returns {string} */
  getValue() {
    return this.el ? this.el.value : '';
  }

  /** @param {string} v @returns {void} */
  setValue(v) {
    if (this.el) this.el.value = v;
  }

  /** @returns {void} */
  focus() {
    if (this.el) {
      this.el.focus({ preventScroll: true });
      if (this.o.readOnly) this.el.select();
    }
  }

  /** Select all text (for manual copy). @returns {void} */
  selectAll() {
    if (this.el) {
      this.el.focus({ preventScroll: true });
      this.el.select();
    }
  }

  /** @returns {void} */
  destroy() {
    if (!this.el) return;
    this.scene.events.off(Phaser.Scenes.Events.UPDATE, this._onUpdate);
    this.scene.events.off('shutdown', this._cleanup);
    this.scene.events.off('destroy', this._cleanup);
    if (this._unbind) this._unbind();
    const wasFocused = document.activeElement === this.el;
    this.el.remove();
    this.el = null;
    if (wasFocused && this.scene.game && this.scene.game.canvas) {
      try {
        this.scene.game.canvas.focus();
      } catch (e) {
        /* ignore */
      }
    }
  }
}/**
 * OWNER: UI engineer.
 * Pure formatting helpers.
 */

/** @param {number} n @returns {string} integer with thousands separators. */
export function fmtInt(n) {
  n = Math.round(Number(n) || 0);
  const s = String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return n < 0 ? `-${s}` : s;
}

/** @param {number} ms @returns {string} m:ss */
export function fmtClock(ms) {
  const s = Math.max(0, Math.floor((Number(ms) || 0) / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

/** @param {number} ms @returns {string} seconds with one decimal, e.g. 1.4 */
export function fmtSec(ms) {
  return (Math.max(0, Number(ms) || 0) / 1000).toFixed(1);
}

/** @param {number} m @returns {string} e.g. 1.25 -> x1.25 */
export function fmtMult(m) {
  return `x${(Number(m) || 1).toFixed(2)}`;
}

const SEED_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

/**
 * Unpredictable seed for a fresh run, from the platform CSPRNG (issue #59): a new seed is the one
 * place real entropy belongs; everything derived from it is seeded. 32 chars, so `byte & 31` is unbiased.
 * @param {{getRandomValues:(a:Uint8Array)=>Uint8Array}} [crypto]
 * @returns {string} 6 readable chars
 */
export function randomSeed(crypto = globalThis.crypto) {
  const bytes = crypto.getRandomValues(new Uint8Array(6));
  let s = '';
  for (const b of bytes) s += SEED_CHARS[b & 31];
  return s;
}

/** @param {string} id camelCase id @returns {string} 'TUCK BOOST' style label. */
export function idToLabel(id) {
  return String(id || '').replace(/([a-z0-9])([A-Z])/g, '$1 $2').toUpperCase();
}

/** Maximum length of leaderboard initials (design doc 6.2: 3 by default, configurable). */
export const INITIALS_LENGTH = 3;

/**
 * The seed a finished run should share: `seed@mask` when the run used biomes, bare seed at mask 0.
 *
 * One function because the panel display and the COPY button had drifted apart — the panel showed the
 * suffix and the clipboard did not, so copying a share seed silently changed the world. Mask 0 stays
 * suffix-free so every seed string that existed before W3 still means what it did.
 * @param {{seed:*, biomeMask:*}} rec
 * @returns {string}
 */
export function shareableSeed(rec) {
  const seed = rec && rec.seed != null ? String(rec.seed) : '';
  if (!seed) return '';
  const mask = rec && Number(rec.biomeMask) || 0;
  return mask ? `${seed}@${mask}` : seed;
}/** Read-only Game Over labels for the existing local ghost roles. */
import { FAVORITE_SLOTS, tapeCompatible } from '../systems/ghost/GhostLibrary.js';
import { SIM_REVISION } from '../systems/replay/ruleset.js';
import { fmtInt } from './Format.js';

export const GHOST_COURSE_ROWS = Object.freeze([
  Object.freeze({ role: 'best', label: 'BEST', globalKey: 'ghostBest' }),
  Object.freeze({ role: 'latest', label: 'LATEST', globalKey: 'ghostLatest' }),
  ...Array.from({ length: FAVORITE_SLOTS }, (_, slot) => Object.freeze({
    role: `fav${slot}`, label: `FAV ${'ABC'[slot]}`, slot,
  })),
]);

function savedRunLabel(tape) {
  if (!Number.isFinite(tape?.distanceM) || tape.distanceM < 0) return 'SAVED RUN';
  const distance = `${fmtInt(tape.distanceM)} M`;
  if (!Number.isFinite(tape.endedAt) || tape.endedAt <= 0) return distance;
  const d = new Date(tape.endedAt);
  return Number.isNaN(d.getTime()) ? distance : `${distance}  ${d.getMonth() + 1}/${d.getDate()}`;
}

/** Read the existing roles of this exact seed and biome mask; no writes or replay checks. */
export async function readGhostCourseRows(library, current, settings = {}) {
  const course = library.course(current.seed, current.biomeMask);
  const ids = GHOST_COURSE_ROWS.map(({ role, slot }) =>
    (slot === undefined ? course?.[role] : course?.favorites?.[slot]) || null);
  const tapes = new Map(await Promise.all([...new Set(ids.filter(Boolean))].map(async (id) =>
    [id, await library.getTape(id)])));
  return GHOST_COURSE_ROWS.map(({ role, slot, globalKey }, i) => {
    const id = ids[i], tape = tapes.get(id);
    // Match RunScene's current-terrain display gate. Direct tape access and
    // historical replay compatibility are independent of this label.
    const compatible = tapeCompatible(tape) && tape.simRevision === SIM_REVISION;
    const hasTrace = compatible && tape.trace.length > 0;
    const currentRun = id !== null && id === current.runId;
    const shared = hasTrace && ids.some((other, j) => j !== i && id === other);
    const globalOff = globalKey !== undefined && settings[globalKey] === false;
    return {
      info: !id ? 'EMPTY' : !tape ? 'TAPE MISSING' : !compatible ? 'INCOMPATIBLE' : !hasTrace ? 'NO TRACE' : currentRun ? 'THIS RUN' : savedRunLabel(tape),
      shared,
      globalOff,
      on: course?.show?.[role] !== false,
      saveLabel: slot === undefined ? null : currentRun ? 'CLEAR' : id ? 'REPLACE' : 'SAVE',
    };
  });
}/** Game Over ghost lineup (#56/#81). Switch exact-course ghosts on or off for the next
 * run, and pin or clear Favorite A/B/C. Nothing starts a run or leaves the device.
 */
import { REG } from '../constants.js';
import { View } from './View.js';
import { NeonText } from './Neon.js';
import { Button } from './Button.js';
import { uiSfx } from './Sound.js';
import { fmtInt } from './Format.js';
import { ellipsize } from './PixelFont.js';
import { GHOST_COURSE_ROWS, readGhostCourseRows } from './ghost-course-rows.js';

const ROW_Y = 49;
const ROW_H = 19;
const FAV_GAP = 6;

export class GhostFavoritesView extends View {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{library:import('../systems/ghost/GhostLibrary.js').GhostLibrary, tape:object, onClose:function():void}} o
   */
  constructor(scene, theme, o) {
    super(scene, theme, { w: 352, h: 194, title: 'COURSE GHOSTS', color: 'magenta', onClose: o.onClose,
      hints: [{ keys: ['↑', '↓'], label: 'ROW' }, { keys: ['←', '→'], label: 'SHOW' }, { keys: ['ENTER'], label: 'SELECT' }] });
    this.library = o.library;
    this.tape = o.tape;
    // Preserve the existing G, Enter shortcut for pinning Favorite A.
    this.focus = GHOST_COURSE_ROWS.findIndex(({ slot }) => slot === 0);
    this._refreshId = 0;
    this._busy = false;
    const text = (x, y, value, color = 'text') => this.panel.add(
      new NeonText(scene, theme, x, y, value, { color, outline: 'none' }));
    text(12, 22, `THIS RUN  ${fmtInt(this.tape.distanceM || 0)} M`);
    text(12, 34, 'FOR THE NEXT RUN ON THIS COURSE', 'cyan');
    text(314, 34, 'SHOW', 'cyan');
    this.rows = GHOST_COURSE_ROWS.map(({ label, slot }, i) => {
      const y = ROW_Y + i * ROW_H + (slot === undefined ? 0 : FAV_GAP);
      const mark = new NeonText(scene, theme, 6, y + 3, '>', { color: 'magenta', outline: 'none' });
      const name = new NeonText(scene, theme, 16, y + 3, label, { color: 'magenta', outline: 'none' });
      const info = new NeonText(scene, theme, 65, y + 3, 'LOADING', { color: 'text', outline: 'none' });
      const detail = new NeonText(scene, theme, 158, y + 3, '', { color: 'amber', outline: 'none' });
      const save = slot === undefined ? null : new Button(scene, theme, {
        x: 249, y, w: 56, h: 15, label: 'SAVE', color: 'lime', onClick: () => this._select(i, true),
      });
      const show = new Button(scene, theme, {
        x: 311, y, w: 29, h: 15, label: '...', color: 'cyan', onClick: () => this._select(i, false),
      });
      for (const item of [mark, name, info, detail, save, show]) if (item) this.panel.add(item);
      return { mark, info, detail, save, show };
    });
    text(12, 149, 'SHARED: DRAWS ONCE IF ANY ROLE CAN SHOW.');
    text(12, 160, 'SETTINGS CAN HIDE BEST / LATEST.');
    this.status = new NeonText(scene, theme, 12, this.h - 18, '', { color: 'lime', outline: 'none' });
    this.panel.add(this.status);
    this._markFocus();
    this._refresh();
  }

  _course() { return this.library.course(this.tape.seed, this.tape.biomeMask); }

  _markFocus() {
    this.rows.forEach(({ mark }, i) => mark.setVisible(i === this.focus));
  }

  _select(i, save) {
    this.focus = i;
    this._markFocus();
    return save ? this._save(i) : this._toggle(i);
  }

  async _refresh() {
    const id = ++this._refreshId;
    const settings = this.scene.registry.get(REG.SETTINGS) || {};
    const models = await readGhostCourseRows(this.library, this.tape, settings);
    if (!this.alive || id !== this._refreshId) return;
    for (let i = 0; i < models.length; i++) {
      const row = this.rows[i], model = models[i];
      row.info.setText(ellipsize(model.info, 88));
      row.detail.setText(model.globalOff ? (model.shared ? 'OFF IN SETTINGS / SHARED' : 'OFF IN SETTINGS') : model.shared ? 'SHARED RUN' : '');
      row.save?.setLabel(model.saveLabel);
      row.show.setLabel(model.on ? 'ON' : 'OFF');
    }
  }

  async _save(i) {
    const { slot, label } = GHOST_COURSE_ROWS[i];
    if (this._busy || slot === undefined) return;
    this._busy = true;
    try {
      const clearing = this._course()?.favorites?.[slot] === this.tape.runId;
      const done = await this.library.setFavorite(this.tape.seed, this.tape.biomeMask, slot, clearing ? null : this.tape.runId);
      if (!this.alive) return;
      uiSfx(this.scene, done ? 'uiSelect' : 'uiBack');
      this.status.setText(done ? (clearing ? `${label} CLEARED` : `SAVED AS ${label}`) : 'COULD NOT SAVE THIS GHOST');
      await this._refresh();
    } finally { this._busy = false; }
  }

  async _toggle(i) {
    const { role, label } = GHOST_COURSE_ROWS[i];
    if (this._busy) return;
    this._busy = true;
    try {
      const on = this._course()?.show?.[role] === false;
      const done = await this.library.setShow(this.tape.seed, this.tape.biomeMask, role, on);
      if (!this.alive) return;
      uiSfx(this.scene, done ? 'uiMove' : 'uiBack');
      this.status.setText(done ? `${label} ${on ? 'ON' : 'OFF'} FOR THIS COURSE` : 'NO COURSE TO UPDATE');
      await this._refresh();
    } finally { this._busy = false; }
  }

  handleAction(action) {
    if (action === 'cancel' || action === 'ghost') { this.close(); return true; }
    if (action === 'up' || action === 'down') {
      this.focus = (this.focus + (action === 'up' ? -1 : 1) + this.rows.length) % this.rows.length;
      uiSfx(this.scene, 'uiMove');
      this._markFocus();
    } else if (action === 'confirm') this._select(this.focus, GHOST_COURSE_ROWS[this.focus].slot !== undefined);
    else if (action === 'left' || action === 'right') this._toggle(this.focus);
    return true;
  }
}/**
 * OWNER: UI engineer. NO Phaser imports.
 *
 * HOW TO PLAY content and geometry. HowToPlayView only draws what this returns, so every keycap, pad glyph and
 * label is a rect a Jest test can check for overlap and containment (tests/src/title-howtoplay.test.js).
 *
 * The keyboard section follows the player's Settings > CONTROL LAYOUT, because the trick layouts really do
 * rebind W/A/S/D and the arrows in a run (systems/ControlLayouts.js, InputRouter._binding). The old Title
 * CONTROLS panel always showed the classic map, which was wrong for the default TRICKS RIGHT layout.
 * Gamepad and touch bindings do not change with the layout (InputRouter GAMEPAD, TouchOverlay).
 *
 * Coordinates are panel-local (the View's panel is HOW_TO_PLAY.w x HOW_TO_PLAY.h, title tab 0..15).
 */
import { measureText } from './PixelFont.js';
import { normalizeControlLayout } from '../systems/ControlLayouts.js';
import { TOUCH_CLUSTERS, touchButtonFor } from '../systems/TouchOverlay.js';

/** Panel size and screen y. 452 x 236 leaves 14 px either side of the 480 px screen and ends at y 253. */
export const HOW_TO_PLAY = Object.freeze({ w: 452, h: 236, y: 17 });

/** Display names of the control layouts (Settings uses the same words). */
export const LAYOUT_NAMES = Object.freeze({ tricksRight: 'TRICKS RIGHT', tricksLeft: 'TRICKS LEFT', classic: 'CLASSIC' });

/**
 * Keyboard rows for a control layout: keys (each drawn as a keycap) and what they do. `join` is drawn between
 * the caps ('+' = together, '/' = either).
 * @param {string} layout settings.controlLayout
 * @returns {{keys:string[], join?:string, label:string}[]}
 */
export function keyboardRows(layout) {
  const l = normalizeControlLayout(layout);
  const common = [
    { keys: ['SPACE'], label: 'HOP' },
  ];
  const tail = [
    { keys: ['SHIFT'], label: 'RESET' },
    { keys: ['ESC'], label: 'PAUSE' },
  ];
  if (l === 'classic') {
    return [
      { keys: ['W'], label: 'PUSH' },
      { keys: ['A', 'D'], join: '/', label: 'TILT' },
      { keys: ['A', 'D'], join: '+', label: 'TUCK' },
      { keys: ['S'], label: 'BRAKE' },
      ...common,
      { keys: ['←', '→'], join: '/', label: 'HELI SPIN' },
      { keys: ['↑'], label: 'AIR BRAKE' },
      { keys: ['↓'], label: 'CHUTE' },
      ...tail,
    ];
  }
  // TRICKS RIGHT: tricks on the arrows, aerodynamics on W/A/S/D. TRICKS LEFT swaps the two clusters.
  const right = l === 'tricksRight';
  const tricks = right ? ['↑', '↓', '→', '←'] : ['W', 'S', 'D', 'A'];
  const aero = right ? ['W', 'A', 'S', 'D'] : ['↑', '←', '↓', '→'];
  return [
    ...common,
    { keys: [tricks[0]], label: 'TILT FWD' },
    { keys: [tricks[1]], label: 'TILT BACK' },
    { keys: [tricks[2]], label: 'HELI SPIN' },
    { keys: [tricks[3]], label: 'CORKSCREW' },
    { keys: [aero[0]], label: 'CHUTE' },
    { keys: [aero[1]], label: 'AIR BRAKE' },
    { keys: [aero[2]], label: 'DIVEBOMB' },
    { keys: [aero[3]], label: 'TUCK' },
    ...tail,
  ];
}

/**
 * Gamepad rows (W3C standard mapping, InputRouter GAMEPAD). `shape`: face = round button, pill = shoulder /
 * trigger / system button, stick = analog stick, dpad = cross.
 * @type {ReadonlyArray<{glyphs:{text:string, shape:'face'|'pill'|'stick'|'dpad', color:string}[], label:string}>}
 */
export const GAMEPAD_ROWS = Object.freeze([
  { glyphs: [{ text: 'L', shape: 'stick', color: 'cyan' }, { text: '', shape: 'dpad', color: 'cyan' }], label: 'TILT' },
  { glyphs: [{ text: 'A', shape: 'face', color: 'lime' }], label: 'HOP' },
  { glyphs: [{ text: 'RT', shape: 'pill', color: 'cyan' }], label: 'PUSH' },
  { glyphs: [{ text: 'LT', shape: 'pill', color: 'cyan' }], label: 'TUCK' },
  { glyphs: [{ text: 'B', shape: 'face', color: 'magenta' }], label: 'BRAKE' },
  { glyphs: [{ text: 'X', shape: 'face', color: 'cyan' }], label: 'AIR BRAKE' },
  { glyphs: [{ text: 'Y', shape: 'face', color: 'amber' }], label: 'CHUTE' },
  { glyphs: [{ text: 'LB', shape: 'pill', color: 'lime' }, { text: 'RB', shape: 'pill', color: 'lime' }], label: 'SPIN' },
  { glyphs: [{ text: 'BACK', shape: 'pill', color: 'amber' }], label: 'RESET' },
  { glyphs: [{ text: 'START', shape: 'pill', color: 'amber' }], label: 'PAUSE' },
]);

/**
 * Touch overlay legend (TouchOverlay BUTTONS), grouped by thumb, with the colours the overlay itself uses so
 * the diagram and the real buttons match.
 */
/** Legend order inside each cluster (most-used first), by base button name. */
const TOUCH_ORDER = Object.freeze({
  LEFT: ['tiltBack', 'tiltForward', 'brake', 'tuck'],
  RIGHT: ['hop', 'push', 'parachute', 'heliLeft', 'heliRight', 'airBrake'],
  TOP: ['reset', 'pause'],
});

/** Short legend names: the two classic spin buttons collapse into one SPIN entry. */
const LEGEND_NAME = Object.freeze({ 'SPIN CCW': 'SPIN', 'SPIN CW': 'SPIN' });

/**
 * Touch overlay legend for a control layout, derived from the overlay's own buttons through
 * TouchOverlay.touchButtonFor, so Trick Deck layouts list DIVEBOMB and CORKSCREW (not PUSH) exactly as the
 * on-screen buttons do. Colours match the overlay so the diagram and the real buttons agree.
 * @param {string} layout settings.controlLayout
 * @returns {{title:string,color:string,items:string[]}[]}
 */
export function touchGroups(layout) {
  const mode = normalizeControlLayout(layout) === 'classic' ? 'classic' : 'trickDeck';
  const names = (cluster) => {
    const out = [];
    for (const base of TOUCH_ORDER[cluster]) {
      const b = TOUCH_CLUSTERS[cluster].find((x) => x.name === base);
      if (!b) continue;
      const label = touchButtonFor(b, mode).label;
      const shown = LEGEND_NAME[label] || label;
      if (!out.includes(shown)) out.push(shown);
    }
    return out;
  };
  return [
    { title: 'LEFT THUMB', color: 'cyan', items: names('LEFT') },
    { title: 'RIGHT THUMB', color: 'magenta', items: names('RIGHT') },
    { title: 'TOP BAR', color: 'amber', items: names('TOP') },
  ];
}

/** One line of advice under the sections. */
export const HOW_TO_PLAY_TIP = 'IN THE AIR, HOLD TILT TO FLIP. LAND FLAT FOR A SPEED BOOST.';

const GLYPH_H = 8;
const CAP_H = 11;
const ROW_PITCH = 15;
const KEY_COL_W = 104;
const PAD_COL_W = 102;

const r = (x, y, w, h) => ({ x, y, w, h });

/** Width of a keycap for a label: text + 3 px either side, never narrower than a square cap. */
export function keycapWidth(text) {
  return Math.max(CAP_H + 1, measureText(text) + 7);
}

/** Width of a pad glyph. */
export function padGlyphWidth(g) {
  if (g.shape === 'face') return CAP_H;
  if (g.shape === 'stick' || g.shape === 'dpad') return CAP_H;
  return measureText(g.text) + 8;
}

/**
 * Lay out a column-major list of rows into `cols` columns starting at (x, y).
 * @returns {{caps:Object[], joins:Object[], label:Object}[]}
 */
function layoutRows(rows, x, y, colW, perCol, glyphsOf, widthOf) {
  return rows.map((row, i) => {
    const col = Math.floor(i / perCol);
    const ry = y + (i % perCol) * ROW_PITCH;
    let cx = x + col * colW;
    const caps = [];
    const joins = [];
    const gl = glyphsOf(row);
    gl.forEach((g, k) => {
      if (k > 0) {
        if (row.join) {
          joins.push({ ...r(cx + 1, ry + 2, measureText(row.join), GLYPH_H), text: row.join });
          cx += measureText(row.join) + 3;
        } else cx += 2;
      }
      const w = widthOf(g);
      caps.push({ ...r(cx, ry, w, CAP_H), glyph: g });
      cx += w;
    });
    const lx = cx + 5;
    const label = { ...r(lx, ry + 2, measureText(row.label), GLYPH_H), text: row.label };
    return { caps, joins, label, col, colRight: x + (col + 1) * colW };
  });
}

/**
 * Every rect HOW TO PLAY draws, panel-local.
 * @param {string} layout settings.controlLayout
 */
export function howToPlayLayout(layout) {
  const P = HOW_TO_PLAY;
  const kRows = keyboardRows(layout);
  const kPerCol = Math.ceil(kRows.length / 2);
  const keyboard = {
    header: r(10, 22, 214, GLYPH_H),
    rows: layoutRows(kRows, 10, 36, KEY_COL_W + 4, kPerCol, (row) => row.keys.map((k) => ({ text: k, shape: 'key' })), (g) => keycapWidth(g.text)),
  };
  const pPerCol = Math.ceil(GAMEPAD_ROWS.length / 2);
  const gamepad = {
    header: r(236, 22, 206, GLYPH_H),
    rows: layoutRows(GAMEPAD_ROWS, 236, 36, PAD_COL_W + 4, pPerCol, (row) => row.glyphs, padGlyphWidth),
  };
  const bottomOfRows = (rows) => Math.max(...rows.map((x) => x.caps[0].y + CAP_H));
  const touchY = Math.max(bottomOfRows(keyboard.rows), bottomOfRows(gamepad.rows)) + 10;
  // the touch strip: a phone silhouette with the two thumb clusters, then a legend line per group
  const phone = r(10, touchY + 12, 92, 46);
  const touch = {
    header: r(10, touchY, 432, GLYPH_H),
    phone,
    groups: touchGroups(layout).map((gr, i) => {
      const y = touchY + 14 + i * 13;
      const title = { ...r(114, y, measureText(gr.title), GLYPH_H), text: gr.title };
      // ', ' rather than ' / ': the Trick Deck right thumb has six buttons (DIVEBOMB and CORKSCREW replace
      // PUSH and SPIN CCW), and the wider separator pushed that line past the panel edge.
      const text = gr.items.join(', ');
      return { ...gr, title, items: { ...r(182, y, measureText(text), GLYPH_H), text } };
    }),
  };
  const tip = { ...r(10, phone.y + phone.h + 8, measureText(HOW_TO_PLAY_TIP), GLYPH_H), text: HOW_TO_PLAY_TIP };
  // the BACK button the View base adds at (w - 76, h - 22), 68 x 16, and the key hint left of it
  const back = r(P.w - 76, P.h - 22, 68, 16);
  const backHint = { ...r(10, P.h - 18, measureText('ESC / B / ENTER: BACK'), GLYPH_H), text: 'ESC / B / ENTER: BACK' };
  const layoutChip = { ...r(0, 4, 0, GLYPH_H), text: `KEYS: ${LAYOUT_NAMES[normalizeControlLayout(layout)]}` };
  layoutChip.w = measureText(layoutChip.text);
  layoutChip.x = P.w - 10 - layoutChip.w;
  return { panel: r(0, 0, P.w, P.h), keyboard, gamepad, touch, tip, back, backHint, layoutChip };
}

/**
 * Every drawn rect, flattened, with a key, for overlap tests.
 * @param {ReturnType<typeof howToPlayLayout>} L
 * @returns {{key:string, x:number, y:number, w:number, h:number}[]}
 */
export function howToPlayRects(L) {
  const out = [];
  const push = (key, b) => out.push({ key, x: b.x, y: b.y, w: b.w, h: b.h });
  push('kb-header', L.keyboard.header);
  push('pad-header', L.gamepad.header);
  for (const [name, sec] of [['kb', L.keyboard], ['pad', L.gamepad]]) {
    sec.rows.forEach((row, i) => {
      row.caps.forEach((c, k) => push(`${name}${i}-cap${k}`, c));
      row.joins.forEach((j, k) => push(`${name}${i}-join${k}`, j));
      push(`${name}${i}-label`, row.label);
    });
  }
  push('touch-header', L.touch.header);
  push('phone', L.touch.phone);
  L.touch.groups.forEach((g, i) => { push(`touch${i}-title`, g.title); push(`touch${i}-items`, g.items); });
  push('tip', L.tip);
  push('back', L.back);
  push('back-hint', L.backHint);
  push('layout-chip', L.layoutChip);
  return out;
}/**
 * OWNER: UI engineer.
 * HOW TO PLAY: the controls reference that used to be the Title's CONTROLS panel, now a modal view reachable
 * from the Title (H key, pad X/Y or SELECT, the tappable HOW TO PLAY chip) and from Settings.
 *
 * Three sections, each drawn the way the player meets that device: KEYBOARD as keycaps (following the
 * player's CONTROL LAYOUT setting), GAMEPAD as face buttons / shoulder pills / stick and d-pad glyphs, TOUCH as
 * a phone silhouette with the two thumb clusters plus a legend. All geometry comes from HowToPlayLayout.js
 * (pure, overlap-tested); this file only paints it.
 *
 * Usage (the View contract): `new HowToPlayView(scene, theme, { onClose })`, then feed it MenuInput actions
 * through handleAction(); cancel or confirm closes it; destroy() removes everything.
 *
 * Why the subclass is built lazily: Views.js (SettingsView) imports this module, and this module extends
 * Views.js's View. A top-level `class HowToPlayView extends View` would run while Views.js is still mid-
 * evaluation whenever Views.js is imported first, and throw (View is in its temporal dead zone). Creating
 * the subclass on first construction makes the cycle harmless in either import order. `new HowToPlayView()`
 * still returns a real View subclass instance, and `instanceof HowToPlayView` still works (Symbol.hasInstance).
 */
import Phaser from 'phaser';
import { REG } from '../constants.js';
import { View } from './Views.js';
import { NeonText, strokeRectPx } from './Neon.js';
import { measureText } from './PixelFont.js';
import { mixColor } from './MenuArt.js';
import { isReducedMotion, onTick } from './Motion.js';
import { HOW_TO_PLAY, howToPlayLayout } from './HowToPlayLayout.js';

const CAP_H = 11;

/** Keycap: dark face, sheen, open-corner border in the section colour and a heavier lip. */
function paintKeycap(g, pal, b, colorKey, lit = 0) {
  const c = pal[colorKey];
  g.fillStyle(mixColor(pal.bgAlt, c, 0.12 + lit * 0.3), 1);
  g.fillRect(b.x, b.y, b.w, CAP_H - 1);
  g.fillStyle(pal.text, 0.1 + lit * 0.15);
  g.fillRect(b.x + 1, b.y + 1, b.w - 2, 3);
  g.fillStyle(c, 0.6 + lit * 0.4);
  g.fillRect(b.x + 1, b.y, b.w - 2, 1);
  g.fillRect(b.x, b.y + 1, 1, CAP_H - 3);
  g.fillRect(b.x + b.w - 1, b.y + 1, 1, CAP_H - 3);
  g.fillStyle(c, 1);
  g.fillRect(b.x + 1, b.y + CAP_H - 2, b.w - 2, 1);
  g.fillStyle(pal.bg, 0.9);
  g.fillRect(b.x + 1, b.y + CAP_H - 1, b.w - 2, 1);
}

/** Pixel disc of diameter `d` at top-left (x, y): one fillRect per row. */
function disc(g, x, y, d, color, alpha) {
  const r = d / 2;
  g.fillStyle(color, alpha);
  for (let row = 0; row < d; row++) {
    const dy = row + 0.5 - r;
    const hw = Math.sqrt(Math.max(0, r * r - dy * dy));
    const w = Math.max(1, Math.round(hw * 2));
    g.fillRect(x + Math.round(r - w / 2), y + row, w, 1);
  }
}

/** Gamepad glyph: round face button, shoulder/system pill, analog stick or d-pad cross. */
function paintPadGlyph(g, pal, b, glyph) {
  const c = pal[glyph.color];
  if (glyph.shape === 'face') {
    disc(g, b.x, b.y, CAP_H, c, 1);
    disc(g, b.x + 1, b.y + 1, CAP_H - 2, mixColor(pal.bg, c, 0.3), 1);
    g.fillStyle(pal.text, 0.25);
    g.fillRect(b.x + 3, b.y + 2, 4, 1);
  } else if (glyph.shape === 'stick') {
    disc(g, b.x, b.y, CAP_H, c, 0.55);
    disc(g, b.x + 2, b.y + 2, CAP_H - 4, mixColor(pal.bg, c, 0.35), 1);
  } else if (glyph.shape === 'dpad') {
    const m = Math.floor(CAP_H / 2) - 1;
    g.fillStyle(c, 0.9);
    g.fillRect(b.x + m, b.y, 3, CAP_H);
    g.fillRect(b.x, b.y + m, CAP_H, 3);
    g.fillStyle(pal.bg, 0.9);
    g.fillRect(b.x + m + 1, b.y + m + 1, 1, 1);
  } else {
    // pill: rounded ends (corners cut), tinted face, bright rim
    g.fillStyle(mixColor(pal.bgAlt, c, 0.25), 1);
    g.fillRect(b.x + 1, b.y, b.w - 2, CAP_H);
    g.fillRect(b.x, b.y + 1, b.w, CAP_H - 2);
    g.fillStyle(c, 0.9);
    g.fillRect(b.x + 2, b.y, b.w - 4, 1);
    g.fillRect(b.x + 2, b.y + CAP_H - 1, b.w - 4, 1);
    g.fillRect(b.x, b.y + 2, 1, CAP_H - 4);
    g.fillRect(b.x + b.w - 1, b.y + 2, 1, CAP_H - 4);
    g.fillRect(b.x + 1, b.y + 1, 1, 1);
    g.fillRect(b.x + b.w - 2, b.y + 1, 1, 1);
    g.fillRect(b.x + 1, b.y + CAP_H - 2, 1, 1);
    g.fillRect(b.x + b.w - 2, b.y + CAP_H - 2, 1, 1);
  }
}

/** Section header: label + a fading rule to the section's right edge. */
function paintHeaderRule(g, pal, b, text, colorKey) {
  const c = pal[colorKey];
  const x0 = b.x + measureText(text) + 6;
  const x1 = b.x + b.w;
  const steps = 8;
  const sw = Math.ceil((x1 - x0) / steps);
  for (let i = 0; i < steps; i++) {
    g.fillStyle(c, 0.6 * (1 - i / (steps * 1.2)));
    g.fillRect(x0 + i * sw, b.y + 4, Math.max(0, Math.min(sw, x1 - (x0 + i * sw))), 1);
  }
  g.fillStyle(c, 1);
  g.fillRect(x0, b.y + 3, 2, 3);
}

let Impl = null;

function buildImpl() {
  return class HowToPlayViewImpl extends View {
    /**
     * @param {Phaser.Scene} scene
     * @param {import('./Theme.js').Theme} theme
     * @param {{onClose:function():void}} o
     */
    constructor(scene, theme, o) {
      super(scene, theme, { w: HOW_TO_PLAY.w, h: HOW_TO_PLAY.h, y: HOW_TO_PLAY.y, title: 'HOW TO PLAY', color: 'cyan', onClose: o.onClose });
      let layout = 'tricksRight';
      try { layout = (scene.registry.get(REG.SETTINGS) || {}).controlLayout || layout; } catch (e) { /* default */ }
      const L = (this.layout = howToPlayLayout(layout));
      const add = (x, y, text, opts) => this.panel.add(new NeonText(scene, theme, x, y, text, { outline: 'none', ...opts }));
      this.g = new Phaser.GameObjects.Graphics(scene);
      this.panel.add(this.g);
      // the "pressed" key cycles through the keycaps, one at a time, like an attract-mode demo
      this.lit = -1;

      add(L.layoutChip.x, L.layoutChip.y, L.layoutChip.text, { color: 'amber', alpha: 0.85 });
      add(L.keyboard.header.x, L.keyboard.header.y, 'KEYBOARD', { color: 'amber' });
      add(L.gamepad.header.x, L.gamepad.header.y, 'GAMEPAD', { color: 'cyan' });
      add(L.touch.header.x, L.touch.header.y, 'TOUCH', { color: 'lime' });
      for (const row of L.keyboard.rows) {
        for (const c of row.caps) add(c.x + Math.floor((c.w - measureText(c.glyph.text)) / 2), c.y + 1, c.glyph.text, { color: 'text' });
        for (const j of row.joins) add(j.x, j.y, j.text, { color: 'amber', alpha: 0.8 });
        add(row.label.x, row.label.y, row.label.text, { color: 'text', alpha: 0.9 });
      }
      for (const row of L.gamepad.rows) {
        for (const c of row.caps) {
          if (!c.glyph.text) continue;
          const tx = c.x + Math.floor((c.w - measureText(c.glyph.text)) / 2);
          add(tx, c.y + 2, c.glyph.text, { color: 'text' });
        }
        add(row.label.x, row.label.y, row.label.text, { color: 'text', alpha: 0.9 });
      }
      for (const gr of L.touch.groups) {
        add(gr.title.x, gr.title.y, gr.title.text, { color: gr.color });
        add(gr.items.x, gr.items.y, gr.items.text, { color: 'text', alpha: 0.85 });
      }
      add(L.tip.x, L.tip.y, L.tip.text, { color: 'magenta', alpha: 0.95 });
      add(L.backHint.x, L.backHint.y, L.backHint.text, { color: 'text', alpha: 0.5 });

      this._unbind = theme.bind((pal) => this._paint(pal));
      this._stopTick = onTick(scene, (time) => {
        if (!this.alive || !this.g || !this.g.scene) return;
        const n = L.keyboard.rows.length;
        const lit = isReducedMotion(scene) ? -1 : Math.floor(time / 650) % (n + 3);
        if (lit !== this.lit) {
          this.lit = lit;
          this._paint(theme.pal);
        }
      });
    }

    _paint(pal) {
      const g = this.g;
      if (!g || !g.scene) return;
      const L = this.layout;
      g.clear();
      paintHeaderRule(g, pal, L.keyboard.header, 'KEYBOARD', 'amber');
      paintHeaderRule(g, pal, L.gamepad.header, 'GAMEPAD', 'cyan');
      paintHeaderRule(g, pal, L.touch.header, 'TOUCH', 'lime');
      // a faint divider between the keyboard and gamepad columns
      g.fillStyle(pal.cyan, 0.18);
      g.fillRect(L.gamepad.header.x - 6, L.gamepad.header.y + 2, 1, L.touch.header.y - L.gamepad.header.y - 8);
      L.keyboard.rows.forEach((row, i) => {
        for (const c of row.caps) paintKeycap(g, pal, c, 'amber', i === this.lit ? 1 : 0);
      });
      for (const row of L.gamepad.rows) for (const c of row.caps) paintPadGlyph(g, pal, c, c.glyph);
      this._paintPhone(g, pal, L.touch.phone);
    }

    /** A landscape phone with the overlay's two thumb clusters and the top bar, in the overlay's colours. */
    _paintPhone(g, pal, b) {
      g.fillStyle(pal.bg, 1);
      g.fillRect(b.x, b.y, b.w, b.h);
      strokeRectPx(g, b.x, b.y, b.w, b.h, pal.text, 0.7);
      strokeRectPx(g, b.x + 2, b.y + 2, b.w - 4, b.h - 4, pal.text, 0.15);
      // a hint of the run on screen: a slope line
      g.fillStyle(pal.cyan, 0.35);
      for (let x = 0; x < b.w - 20; x++) g.fillRect(b.x + 10 + x, b.y + 14 + Math.round(x * 0.22), 1, 1);
      // top: reset + pause
      g.fillStyle(pal.amber, 0.85);
      g.fillRect(b.x + 6, b.y + 5, 6, 3);
      g.fillRect(b.x + 14, b.y + 5, 6, 3);
      // left thumb: 2x2 (brake, tuck / tilt back, tilt fwd big)
      const cell = (x, y, w, h, key, a = 0.9) => {
        g.fillStyle(mixColor(pal.bg, pal[key], 0.35), 1);
        g.fillRect(x, y, w, h);
        strokeRectPx(g, x, y, w, h, pal[key], a);
      };
      cell(b.x + 5, b.y + b.h - 22, 8, 7, 'amber');
      cell(b.x + 15, b.y + b.h - 22, 8, 7, 'lime');
      cell(b.x + 5, b.y + b.h - 13, 8, 9, 'cyan');
      cell(b.x + 15, b.y + b.h - 13, 8, 9, 'cyan');
      // right thumb: 3x2 (spin ccw, air brake, spin cw / push, hop big, chute)
      const rx = b.x + b.w - 33;
      cell(rx, b.y + b.h - 22, 8, 7, 'lime');
      cell(rx + 10, b.y + b.h - 22, 8, 7, 'amber');
      cell(rx + 20, b.y + b.h - 22, 8, 7, 'lime');
      cell(rx, b.y + b.h - 13, 8, 9, 'cyan');
      cell(rx + 10, b.y + b.h - 13, 8, 9, 'magenta');
      cell(rx + 20, b.y + b.h - 13, 8, 9, 'amber');
    }

    handleAction(action) {
      if (action === 'cancel' || action === 'confirm') this.close();
      return true;
    }

    destroy() {
      if (this._stopTick) this._stopTick();
      this._stopTick = null;
      if (this._unbind) this._unbind();
      this._unbind = null;
      this.g = null;
      super.destroy();
    }
  };
}

/**
 * HOW TO PLAY modal view. See the file header for why this is a factory-backed class.
 */
export class HowToPlayView {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{onClose:function():void}} o
   */
  constructor(scene, theme, o) {
    if (!Impl) Impl = buildImpl();
    // eslint-disable-next-line no-constructor-return
    return new Impl(scene, theme, o);
  }

  static [Symbol.hasInstance](obj) {
    return !!Impl && obj instanceof Impl;
  }
}/**
 * OWNER: UI engineer.
 * Phaser-free HUD layout helpers (rectangles are {x, y, w, h} in game pixels, 480x270).
 * UIScene uses them to stack the centre banners (landing, boost, strip band, bank line, crash banner, popups) in separate slots that also dodge the fixed
 * HUD rows and the on-screen touch buttons, and to find a free spot for the bottom row (power-ups, tutorial chip).
 */

/**
 * The full-width HUD strip (sector, NEW BEST, biome banner, mission toasts): band height, the scale its text
 * is drawn at, and the clear margin kept at each screen edge. UIScene draws the strip from these numbers and
 * MissionsUi sizes the mission toast from them, so the two cannot disagree about how much text fits.
 */
export const STRIP_BAND = Object.freeze({ h: 17, textScale: 2, margin: 8 });

/**
 * Widest strip text, in UNSCALED font pixels (PixelFont.measureText units), that fits the band.
 * @param {number} [width=480] screen width in game px
 * @returns {number}
 */
export function stripTextMaxPx(width = 480) {
  return Math.floor((width - 2 * STRIP_BAND.margin) / STRIP_BAND.textScale);
}

/** True when the two rectangles overlap (pad grows `b` on every side: a minimum clear gap). */
export function rectsHit(a, b, pad = 0) {
  return a.x < b.x + b.w + pad && b.x < a.x + a.w + pad && a.y < b.y + b.h + pad && b.y < a.y + a.h + pad;
}

/**
 * Stack centred items top to bottom. Each item is {w, h, pref?, cx?, full?}: it takes `max(cursor, pref)` as its top, is pushed
 * below any keep-out rectangle it would touch, and the next item starts `gap` under it. Items that do not collide stay at `pref`
 * (their classic position). Returns the top y of every item, in order.
 *
 * `full: true` marks a full-width band (the HUD strip): it is tested across the whole `width`, not just its own `w`, because its
 * background fill crosses the row. Putting the band IN the stack, rather than placing it separately, is what keeps it off the
 * centre banners above and below it: the cursor only moves down, so no two stacked items can overlap (audit U5a/b/c).
 * @param {{w:number,h:number,pref?:number,cx?:number,full?:boolean}[]} items
 * @param {{cx:number, startY?:number, gap?:number, width?:number, keepOuts?:{x:number,y:number,w:number,h:number}[]}} opts
 * @returns {number[]}
 */
export function stackY(items, { cx, startY = 0, gap = 3, width = 480, keepOuts = [] }) {
  const out = [];
  let cursor = startY;
  for (const it of items) {
    let y = Math.max(cursor, it.pref || 0);
    const w = it.full ? width : it.w;
    const x = it.full ? 0 : (it.cx === undefined ? cx : it.cx) - it.w / 2;
    for (let guard = 0; guard < 64; guard++) {
      const hit = keepOuts.find((k) => rectsHit({ x, y, w, h: it.h }, k, gap - 1));
      if (!hit) break;
      y = hit.y + hit.h + gap;
    }
    out.push(y);
    cursor = y + it.h + gap;
  }
  return out;
}

/**
 * True when a full-width band at [y, y+h) would paint through any keep-out rectangle.
 *
 * A band is a different shape from a text box: the strip and the biome banner span the whole 480 px
 * row, so it is not enough for their own measured text to miss the fixed HUD rows - the background
 * fill crosses the row and draws over whatever sits there. That is the W2 defect (a mission toast
 * painted through "FLOW x1.25" and the trick popups) and the same bug shape the biome banner would
 * have inherited.
 * @param {{y:number,h:number}} band
 * @param {{x:number,y:number,w:number,h:number}[]} keepOuts
 * @param {number} [width=480] band width (the whole row by default).
 * @param {number} [gap=0] clear gap required.
 * @returns {boolean}
 */
export function bandHits(band, keepOuts, width = 480, gap = 0) {
  const box = { x: 0, y: band.y, w: width, h: band.h };
  return (keepOuts || []).some((k) => rectsHit(box, k, gap));
}

/**
 * Top y for a full-width band of height `h`, at or below `pref`, that clears every keep-out row.
 * Stays at `pref` when it is already clear, so the strip keeps its classic position on a quiet HUD.
 * @param {number} h band height
 * @param {number} pref preferred top y
 * @param {{x:number,y:number,w:number,h:number}[]} keepOuts
 * @param {{gap?:number, maxY?:number, width?:number}} [o]
 * @returns {number}
 */
export function placeBand(h, pref, keepOuts, o = {}) {
  const gap = o.gap === undefined ? 3 : o.gap;
  const width = o.width === undefined ? 480 : o.width;
  const maxY = o.maxY === undefined ? 270 : o.maxY;
  let y = pref;
  for (let guard = 0; guard < 64; guard++) {
    const hit = (keepOuts || []).find((k) => rectsHit({ x: 0, y, w: width, h }, k, gap - 1));
    if (!hit) break;
    y = hit.y + hit.h + gap;
  }
  return Math.min(y, Math.max(pref, maxY - h));
}

/**
 * Left edge for a w x h box at row `y` that touches none of `keepOuts`, closest to `prefLeft`, within [min, max] (right limit of
 * the box). Null when no free spot exists on that row.
 * @returns {number|null}
 */
export function placeX(w, y, h, prefLeft, keepOuts, { min = 0, max = 480, gap = 3 } = {}) {
  const cands = [prefLeft];
  for (const k of keepOuts) cands.push(k.x + k.w + gap, k.x - w - gap);
  let best = null;
  for (const left of cands) {
    if (left < min || left + w > max) continue;
    const box = { x: left, y, w, h };
    if (keepOuts.some((k) => rectsHit(box, k, gap - 1))) continue;
    if (best === null || Math.abs(left - prefLeft) < Math.abs(best - prefLeft)) best = left;
  }
  return best;
}/**
 * OWNER: UI engineer.
 * Arcade-style initials entry with an arbitrary slot count (design doc 6.2: 3 by default, configurable).
 *  - keyboard: type A-Z / 0-9 (fills the slot and advances), Backspace, arrows (left/right move, up/down cycle)
 *  - gamepad: d-pad / stick up/down cycles, left/right moves, A = advance then submit on the last slot, B = back
 *  - touch / mouse: tap a slot to select it, tap the triangles above/below it to cycle, tap SAVE
 * The widget owns no input listeners; the scene feeds it `handleAction()` (MenuInput) and `handleKey()` (raw keys).
 */
import Phaser from 'phaser';
import { NeonText, strokeRectPx, glowRectPx } from './Neon.js';
import { Button } from './Button.js';
import { uiSfx } from './Sound.js';

export const INITIALS_CHARSET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

export class InitialsEntry extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,w:number,length?:number,initial?:string,color?:string,
   *          onSubmit:function(string):void, parent?:Phaser.GameObjects.Container}} o x,y = top-left, w = available width
   */
  constructor(scene, theme, o) {
    super(scene, o.x, o.y);
    this.theme = theme;
    this.slots = Math.max(1, o.length || 3);
    this.onSubmit = o.onSubmit;
    this.colorKey = o.color || 'lime';
    const init = String(o.initial || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    /** @type {string[]} */
    this.chars = [];
    for (let i = 0; i < this.slots; i++) this.chars.push(init[i] || 'A');
    this.cursor = 0;
    this.big = this.slots <= 6;
    this.slotW = Math.min(this.big ? 30 : 17, Math.floor((o.w - 4 * (this.slots - 1)) / this.slots));
    this.slotH = this.big ? 28 : 18;
    this.gap = 4;
    this.totalW = this.slots * this.slotW + (this.slots - 1) * this.gap;
    this.x0 = Math.round((o.w - this.totalW) / 2);
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    this.slotY = 14;
    this.letters = [];
    for (let i = 0; i < this.slots; i++) {
      const sx = this.x0 + i * (this.slotW + this.gap);
      const t = new NeonText(scene, theme, sx + this.slotW / 2, this.slotY + this.slotH / 2, this.chars[i], {
        color: 'text', scale: this.big ? 3 : 2, anchor: 'center', vAnchor: 0.5, outline: 'glow',
      });
      this.add(t);
      this.letters.push(t);
      const mkZone = (zy, zh, fn) => {
        const z = new Phaser.GameObjects.Zone(scene, sx, zy, this.slotW, zh).setOrigin(0, 0);
        z.setInteractive({ useHandCursor: true });
        z.on('pointerdown', fn);
        this.add(z);
      };
      mkZone(0, 14, () => this._select(i) && this.cycle(1));
      mkZone(this.slotY, this.slotH, () => this._select(i));
      mkZone(this.slotY + this.slotH, 14, () => this._select(i) && this.cycle(-1));
    }
    this.arrowUp = new NeonText(scene, theme, 0, 0, '▲', { color: this.colorKey, anchor: 'center', vAnchor: 0.5, outline: 'none' });
    this.arrowDown = new NeonText(scene, theme, 0, 0, '▼', { color: this.colorKey, anchor: 'center', vAnchor: 0.5, outline: 'none' });
    this.add([this.arrowUp, this.arrowDown]);
    const btnW = 84;
    this.saveBtn = new Button(scene, theme, {
      x: Math.round((o.w - btnW) / 2), y: this.slotY + this.slotH + 18, w: btnW, h: 16, label: 'SAVE', color: this.colorKey,
      onClick: () => this.submit(),
    });
    this.add(this.saveBtn);
    this.contentH = this.slotY + this.slotH + 34;
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind(() => this.refresh());
  }

  _select(i) {
    if (this.cursor !== i) {
      this.cursor = i;
      uiSfx(this.scene, 'uiMove');
      this.refresh();
    }
    return true;
  }

  /** @returns {string} current initials */
  getValue() {
    return this.chars.join('');
  }

  /** @param {number} dir +1 next letter, -1 previous @returns {void} */
  cycle(dir) {
    const cs = INITIALS_CHARSET;
    const i = cs.indexOf(this.chars[this.cursor]);
    this.chars[this.cursor] = cs[(i + dir + cs.length) % cs.length];
    uiSfx(this.scene, 'uiMove', { pitch: 1 + 0.03 * i });
    this.refresh();
  }

  /** @returns {void} */
  submit() {
    uiSfx(this.scene, 'uiSelect');
    this.onSubmit(this.getValue());
  }

  /**
   * @param {string} action MenuInput action
   * @returns {boolean} consumed
   */
  handleAction(action) {
    switch (action) {
      case 'up': this.cycle(1); return true;
      case 'down': this.cycle(-1); return true;
      case 'left':
        if (this.cursor > 0) { this.cursor--; uiSfx(this.scene, 'uiMove'); this.refresh(); }
        return true;
      case 'right':
        if (this.cursor < this.slots - 1) { this.cursor++; uiSfx(this.scene, 'uiMove'); this.refresh(); }
        return true;
      case 'confirm':
        if (this.cursor < this.slots - 1) { this.cursor++; uiSfx(this.scene, 'uiSelect'); this.refresh(); } else this.submit();
        return true;
      case 'cancel':
        if (this.cursor > 0) { this.cursor--; uiSfx(this.scene, 'uiBack'); this.refresh(); return true; }
        return false;
      default: return false;
    }
  }

  /**
   * Raw keyboard text input.
   * @param {KeyboardEvent} e
   * @returns {boolean} consumed (letters, digits, Backspace)
   */
  handleKey(e) {
    if (e.ctrlKey || e.metaKey || e.altKey) return false;
    if (e.key.length === 1 && /[a-zA-Z0-9]/.test(e.key)) {
      this.chars[this.cursor] = e.key.toUpperCase();
      if (this.cursor < this.slots - 1) this.cursor++;
      uiSfx(this.scene, 'uiSelect', { pitch: 1.2 });
      this.refresh();
      return true;
    }
    if (e.key === 'Backspace') {
      if (this.cursor > 0) this.cursor--;
      this.chars[this.cursor] = 'A';
      uiSfx(this.scene, 'uiBack');
      this.refresh();
      return true;
    }
    return false;
  }

  /** Repaint. @returns {void} */
  refresh() {
    const pal = this.theme.pal;
    const g = this.g;
    g.clear();
    const c = pal[this.colorKey];
    for (let i = 0; i < this.slots; i++) {
      const sx = this.x0 + i * (this.slotW + this.gap);
      const sel = i === this.cursor;
      if (sel) glowRectPx(g, sx, this.slotY, this.slotW, this.slotH, c, 1.4);
      g.fillStyle(pal.bgAlt, 1);
      g.fillRect(sx, this.slotY, this.slotW, this.slotH);
      strokeRectPx(g, sx, this.slotY, this.slotW, this.slotH, c, sel ? 1 : 0.4);
      if (sel) {
        g.fillStyle(c, 0.18);
        g.fillRect(sx + 1, this.slotY + 1, this.slotW - 2, this.slotH - 2);
        g.fillStyle(c, 1);
        g.fillRect(sx + 3, this.slotY + this.slotH - 4, this.slotW - 6, 2);
      }
      this.letters[i].setText(this.chars[i]);
      this.letters[i].setColorKey(sel ? 'text' : this.colorKey);
    }
    const sx = this.x0 + this.cursor * (this.slotW + this.gap) + this.slotW / 2;
    this.arrowUp.setPosition(Math.round(sx), 8);
    this.arrowDown.setPosition(Math.round(sx), this.slotY + this.slotH + 8);
  }

  destroy(fromScene) {
    if (this._unbind) this._unbind();
    this._unbind = null;
    super.destroy(fromScene);
  }
}/**
 * One compact jukebox strip for Title, Pause and Game Over.
 * Read-only playlist state comes from the game's ONE StemMusicDirector.
 * Playback buttons invoke AudioSynth's canonical transport, not a second
 * audio context. Optional queue expands on click, leaving the game UI
 * unobstructed unless the user specifically asks for history/upcoming.
 */
import Phaser from 'phaser';
import {REG} from '../constants.js';
import {Panel} from './Panel.js';
import {Button} from './Button.js';
import {NeonText} from './Neon.js';
import {ellipsize} from './PixelFont.js';
import {isReducedMotion} from './Motion.js';
import { cosmeticRandom } from '../systems/CosmeticRandom.js';

/**
 * Compact cabinet variant (Title): 102x30, an animated level meter beside the song name, and four glyph
 * keys (<<, play/pause, >>, queue) instead of the word buttons. Same transport, same queue, same bounds
 * contract; Pause and Game Over keep the default 141x31 strip.
 */
export const JUKEBOX_COMPACT=Object.freeze({w:102,h:30,keyW:23,keyH:13,keyGap:2});

export class JukeboxHUD {
	/** @param {Phaser.Scene} scene @param {Theme} theme
	 * @param {{x?:number,y?:number,variant?:'default'|'compact',queueAt?:{x:number,y:number},depth?:number}} opts
	 *   queueAt: top-left of the expanded queue panel (default 245,94).
	 */
	constructor(scene,theme,{x=335,y=61,variant='default',queueAt=null,depth=320}={}){
		this.scene=scene;
		this.theme=theme;
		this.audio=scene.registry.get(REG.AUDIO);
		this.compact=variant==='compact';
		const w=this.compact?JUKEBOX_COMPACT.w:141;
		const h=this.compact?JUKEBOX_COMPACT.h:31;
		// Scene-level tap-to-retry cannot rely solely on Phaser's
		// pointerover array: overlapping UI/backdrops can briefly report
		// zero interactive objects during a real queue click.
		this.bounds={x,y,w,h};
		this.queueBounds={x:queueAt?queueAt.x:245,y:queueAt?queueAt.y:94,w:230,h:93};
		this.depth=depth;
		this.panel=new Panel(scene,theme,{
			x,y,w,h,fillAlpha:this.compact?.66:.88,color:'cyan',
		}).setDepth(depth);
		this.now=new NeonText(scene,theme,this.compact?15:4,2,'MUSIC / READY',{
			color:'cyan',outline:'none',
		});
		this.panel.add(this.now);
		this.labels=this.compact?
			{prev:'<<',play:'▶',pause:'II',next:'>>',list:'▼'}:
			{prev:'PREV',play:'PLAY',pause:'PAUSE',next:'NEXT',list:'LIST'};
		const defs=[
			{label:this.labels.prev,fn:()=>this._action('previous')},
			{label:this.labels.play,fn:()=>this._action('toggle')},
			{label:this.labels.next,fn:()=>this._action('next')},
			{label:this.labels.list,fn:()=>this._toggleQueue()},
		];
		const K=JUKEBOX_COMPACT;
		this.buttons=defs.map((item,i)=>new Button(scene,theme,this.compact?{
			x:3+i*(K.keyW+K.keyGap),y:h-K.keyH-3,w:K.keyW,h:K.keyH,label:item.label,
			color:i===1?'lime':i===3?'magenta':'cyan',onClick:item.fn,parent:this.panel,
		}:{
			x:2+i*35,y:14,w:33,h:14,label:item.label,
			color:i===1?'lime':'cyan',onClick:item.fn,parent:this.panel,
		}));
		// compact: a five-bar level meter left of the song name, bouncing while music plays
		this.meter=null;
		this.playing=false;
		if(this.compact){
			this.meter=new Phaser.GameObjects.Graphics(scene);
			this.panel.add(this.meter);
			this._meterTimer=scene.time.addEvent({
				delay:110,loop:true,callback:()=>this._paintMeter(),
			});
		}
		this.queue=null;
		this._last='';
		this._closed=false;
		this._timer=scene.time.addEvent({
			delay:300,loop:true,callback:()=>this.refresh(),
		});
		this.refresh();
	}

	_action(command){
		if(this._closed||!this.audio)return;
		try {
			const state=this.audio.jukeboxSnapshot().state;
			if(command==='toggle'){
				if(state==='playing'||state==='loading')this.audio.jukeboxPause();
				else this.audio.jukeboxPlay();
			}else this.audio.jukeboxStep(command==='previous'?-1:1);
		}catch(e){/* unavailable audio stays silent; never breaks menu */}
		this.refresh();
	}

	/** Conservative ownership of a tap on jukebox or its open queue.
	 * Coordinates are Phaser GAME coordinates, never CSS pixel offsets.
	 * Only Game Over's background-tap retry uses this explicit guard.
	 */
	ownsPointer(pointer){
		if(this._closed||!pointer)return false;
		const x=Number(pointer.x),y=Number(pointer.y);
		if(!Number.isFinite(x)||!Number.isFinite(y))return false;
		const inside=rect=>x>=rect.x&&x<=rect.x+rect.w&&
			y>=rect.y&&y<=rect.y+rect.h;
		return inside(this.bounds)||(!!this.queue&&inside(this.queueBounds));
	}

	_toggleQueue(){
		if(this.queue){
			this.queue.destroy();
			this.queue=null;
			return;
		}
		const scene=this.scene,theme=this.theme;
		const Q=this.queueBounds;
		const expanded=new Panel(scene,theme,{
			x:Q.x,y:Q.y,w:230,h:93,title:'JUKEBOX / QUEUE',
			color:'cyan',fillAlpha:.96,
		}).setDepth(this.depth+15);
		// Block Game-Over's background tap-to-retry while queue is open.
		const backdrop=new Phaser.GameObjects.Zone(scene,0,0,230,93)
			.setOrigin(0,0).setInteractive();
		expanded.add(backdrop);
		const names=[
			['last',20,'LAST:'],
			['now',34,'NOW:'],
			['next',48,'NEXT:'],
			['after',62,'THEN:'],
			['hint',77,'PLAY / PAUSE / BACK / SKIP ABOVE'],
		];
		this.queueTexts={};
		for(const [key,y,label] of names){
			const line=new NeonText(scene,theme,8,y,label,{
				color:key==='now'?'lime':key==='hint'?'text':'cyan',
				outline:'none',
			});
			if(key==='hint')line.setAlpha(.55);
			expanded.add(line);
			this.queueTexts[key]=line;
		}
		this.queue=expanded;
		this.refresh();
	}

	refresh(){
		if(this._closed)return;
		const state=this.audio?.jukeboxSnapshot?.()||{
			state:'stopped',current:null,previous:null,upcoming:[],
		};
		const name=state.current?.title||'NO MUSIC';
		const mode=state.state==='playing'?'ON ':state.state==='loading'?'... ':
			state.state==='paused'?'II ':'> ';
		this.playing=state.state==='playing';
		const label=this.compact?ellipsize(name.toUpperCase(),JUKEBOX_COMPACT.w-19):
			mode+ellipsize(name.toUpperCase(),119);
		if(label!==this._last){
			this._last=label;
			this.now.setText(label);
		}
		const available=state.current!==null;
		this.buttons[0].setDisabled(!available);
		this.buttons[1].setDisabled(!available);
		this.buttons[2].setDisabled(!available);
		this.buttons[1].setLabel(state.state==='playing'||state.state==='loading'?
			this.labels.pause:this.labels.play);
		if(!this.queue)return;
		const entries={
			last:'LAST: '+(state.previous?.title||'--'),
			now:'NOW: '+(state.current?.title||'SILENCE')+
				' ['+state.state.toUpperCase()+']',
			next:'NEXT: '+(state.upcoming?.[0]?.title||'--'),
			after:'THEN: '+(state.upcoming?.[1]?.title||'--'),
		};
		for(const [key,value] of Object.entries(entries))
			this.queueTexts[key].setText(ellipsize(value.toUpperCase(),211));
	}

	/** Compact level meter: five 2px bars, random heights while playing, a flat line otherwise. */
	_paintMeter(){
		const g=this.meter;
		if(this._closed||!g||!g.scene)return;
		const pal=this.theme.pal;
		g.clear();
		const still=!this.playing||isReducedMotion(this.scene);
		for(let i=0;i<5;i++){
			const hgt=still?(this.playing?[3,5,4,6,3][i]:1):1+Math.floor(cosmeticRandom('ui/jukebox').next()*7);
			g.fillStyle(i<2?pal.lime:i<4?pal.cyan:pal.magenta,this.playing?.95:.45);
			g.fillRect(3+i*2,10-hgt,1,hgt);
		}
	}

	destroy(){
		if(this._closed)return;
		this._closed=true;
		this._timer?.remove();
		this._meterTimer?.remove();
		this.queue?.destroy();this.queue=null;
		this.panel?.destroy();this.panel=null;
	}
}/**
 * OWNER: UI engineer.
 * Top-10 table (per device): rank, initials, score, distance, and (wide layout) seed + daily-rule flag.
 * Defensive about stub / partial records. Highlights the entry whose id === highlightId.
 */
import Phaser from 'phaser';
import { NeonText } from './Neon.js';
import { ellipsize } from './PixelFont.js';
import { fmtInt, idToLabel } from './Format.js';
import { DailyPatch } from '../systems/DailyPatch.js';
import { podiumKey, paintRule, staggerAlpha } from './ViewChrome.js';

export const ROW_H = 11;

/** @param {string} id @returns {string} display label of a daily rule id. */
export function ruleLabel(id) {
  if (!id || id === 'none') return '-';
  const r = DailyPatch.getRuleById(id);
  return (r ? r.name.toUpperCase() : idToLabel(id));
}

export class LeaderboardTable extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,w:number,entries:object[]|null,highlightId?:string,rows?:number,wide?:boolean,
   *          rowH?:number,parent?:Phaser.GameObjects.Container}} o entries === null shows a loading message
   *   `animate` (default true) fades the rows in one after another when entries arrive (skipped under
   *   reduce motion). Rows 1-3 wear the podium colours (amber / text / magenta) on a numbered chip.
   *   `rowH` lets a caller tighten the pitch to fit the same row count in less space (Game Over uses 9
   *   to keep all ten entries visible alongside the mission block). Defaults to ROW_H.
   */
  constructor(scene, theme, o) {
    super(scene, o.x, o.y);
    this.theme = theme;
    this.w = o.w;
    this.rows = o.rows || 10;
    // Per-caller pitch. The pitch is a rendering detail; the row COUNT is the contract the panel title
    // advertises, so tightening the pitch must never be used to show fewer entries than promised.
    this.rowH = o.rowH || ROW_H;
    this.wide = o.wide !== undefined ? o.wide : o.w >= 330;
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    this.animate = o.animate !== false;
    this._curRow = null;
    this.highlightId = o.highlightId;
    this.highlightRow = -1;
    this.pulse = 0;
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind(() => this._paintBars());
    this.setEntries(o.entries);
  }

  _cell(x, y, text, color, anchor = 'left') {
    const t = new NeonText(this.scene, this.theme, x, y, text, { color, anchor, outline: 'none' });
    this.add(t);
    this.cells.push(t);
    if (this._curRow) this._curRow.push(t);
    return t;
  }

  /**
   * @param {object[]|null} entries
   * @param {string} [highlightId]
   * @param {{title:string, sub?:string}} [empty] what an empty board says instead of the generic
   *   "NO ENTRIES YET" (the leaderboard view names WHICH board is empty). Omitted = the generic text.
   * @returns {void}
   */
  setEntries(entries, highlightId, empty) {
    if (highlightId !== undefined) this.highlightId = highlightId;
    for (const c of this.cells || []) c.destroy();
    this.cells = [];
    this.rowCount = 0;
    this.highlightRow = -1;
    const w = this.w;
    if (entries === null) {
      this._cell(w / 2, 50, 'READING LEDGER...', 'cyan', 'center');
      this._paintBars();
      return;
    }
    const col = this.wide
      ? { rank: 6, ini: 24, score: 108, dist: 160, seed: 172, rule: w - 6 }
      : { rank: 4, ini: 20, score: 100, dist: w - 6 };
    const hy = 0;
    this._cell(col.rank, hy, '#', 'text').setAlpha(0.5);
    this._cell(col.ini, hy, 'NAME', 'text').setAlpha(0.5);
    this._cell(col.score, hy, 'SCORE', 'text', 'right').setAlpha(0.5);
    this._cell(col.dist, hy, 'DIST', 'text', 'right').setAlpha(0.5);
    if (this.wide) {
      this._cell(col.seed, hy, 'SEED', 'text').setAlpha(0.5);
      this._cell(col.rule, hy, 'RULE', 'text', 'right').setAlpha(0.5);
    }
    const list = entries.slice(0, this.rows);
    if (list.length === 0) {
      const e = empty && empty.title ? empty : { title: 'NO ENTRIES YET', sub: 'FINISH A TOP-10 RUN TO CLAIM A SPOT' };
      this._cell(w / 2, 52, e.title, 'amber', 'center');
      if (e.sub) this._cell(w / 2, 66, e.sub, 'text', 'center').setAlpha(0.6);
    }
    this.rowCount = list.length;
    const groups = [];
    list.forEach((e, i) => {
      const y = 14 + i * this.rowH;
      const hi = this.highlightId && e.id === this.highlightId;
      if (hi) this.highlightRow = i;
      const pk = podiumKey(i);
      const color = hi ? 'lime' : i === 0 ? 'amber' : 'text';
      this._curRow = [];
      // rank: podium rows sit on a filled chip (painted in _paintBars) with the digit knocked out in bg
      this._cell(col.rank, y, String(i + 1), hi ? 'lime' : pk ? 'bg' : 'cyan');
      this._cell(col.ini, y, String(e.initials || '---').toUpperCase(), hi ? 'lime' : pk || 'text');
      this._cell(col.score, y, fmtInt(e.score), hi ? 'lime' : 'amber', 'right');
      this._cell(col.dist, y, `${fmtInt(e.distanceM)}m`, color, 'right');
      if (this.wide) {
        this._cell(col.seed, y, ellipsize(String(e.seed || '-'), 96), color);
        this._cell(col.rule, y, ellipsize(ruleLabel(e.dailyRuleId), 84), e.dailyRuleId && e.dailyRuleId !== 'none' ? 'magenta' : 'text', 'right')
          .setAlpha(e.dailyRuleId && e.dailyRuleId !== 'none' ? 1 : 0.4);
      }
      groups.push(this._curRow);
      this._curRow = null;
    });
    this._paintBars();
    if (this.animate && groups.length) staggerAlpha(this.scene, groups, { start: 60, step: 28 });
  }

  _paintBars() {
    if (!this.g) return;
    const pal = this.theme.pal;
    const g = this.g;
    g.clear();
    paintRule(g, 0, this.w, 10, pal.cyan, 0.7);
    const n = this.rowCount || 0;
    const ch = Math.min(9, this.rowH - 1);
    for (let i = 0; i < n; i++) {
      const y = 14 + i * this.rowH - 2;
      const pk = podiumKey(i);
      // zebra: every other row catches a hair more light
      if (i % 2 === 1) {
        g.fillStyle(pal.text, 0.035);
        g.fillRect(0, y, this.w, this.rowH);
      }
      if (pk && i !== this.highlightRow) {
        g.fillStyle(pal[pk], 0.08 - i * 0.015);
        g.fillRect(0, y, this.w, this.rowH);
        g.fillStyle(pal[pk], 0.9);
        g.fillRect(0, y, 2, this.rowH);
      }
      if (pk && i !== this.highlightRow) {
        // the numbered chip behind the rank digit
        const col = this.wide ? 6 : 4;
        g.fillStyle(pal[pk], 1);
        g.fillRect(col - 2, y + Math.floor((this.rowH - ch) / 2), 9, ch);
      }
    }
    if (this.highlightRow >= 0) {
      const y = 14 + this.highlightRow * this.rowH - 2;
      const k = 0.12 + 0.1 * Math.sin(this.pulse);
      g.fillStyle(pal.lime, k);
      g.fillRect(0, y, this.w, this.rowH);
      g.fillStyle(pal.lime, 0.55);
      g.fillRect(0, y, this.w, 1);
      g.fillRect(0, y + this.rowH - 1, this.w, 1);
      g.fillStyle(pal.lime, 1);
      g.fillRect(0, y, 2, this.rowH);
      g.fillRect(this.w - 2, y, 2, this.rowH);
    }
  }

  /** @param {number} delta ms @returns {void} */
  tick(delta) {
    if (this.highlightRow < 0) return;
    this.pulse += delta * 0.006;
    this._paintBars();
  }

  destroy(fromScene) {
    if (this._unbind) this._unbind();
    this._unbind = null;
    this.g = null;
    super.destroy(fromScene);
  }
}/**
 * OWNER: UI engineer.
 * Authored menu art (public/assets/menu/*.svg): texture keys, the loader queue, and tinted-image factories.
 *
 * The SVGs are generated pixel art (tools/menu-art/generate-menu-art.mjs) at their exact native size on the
 * 480x270 grid, loaded with `load.svg(key, url, {width, height})` so the browser rasterises each once at 1:1
 * and `pixelArt: true` keeps it crisp.
 *
 * Two rules every caller relies on:
 *  1. Accent colour is never baked. Art is white/greyscale and gets its colour from `tint`, resolved from
 *     the Theme inside theme.bind(), so the colour-blind palette and the equipped UI theme recolour it live.
 *  2. Art is optional. A file that 404s or fails to decode simply never becomes a texture; the factories
 *     return null and the caller draws its procedural fallback. A missing asset can never block a menu.
 */
import { MENU_LAYERS } from './MenuTerrain.js';

/**
 * Where the files are served from. Relative (no leading slash) so the game also works when deployed under a
 * sub-path; Vite copies public/ to the site root, so in dev and at the root this is /assets/menu/.
 */
export const MENU_ART_BASE = 'assets/menu/';

/**
 * Every menu texture: key (Phaser texture key), file (under MENU_ART_BASE) and native size.
 * @type {Readonly<Object<string, Readonly<{key:string, file:string, w:number, h:number}>>>}
 */
export const MENU_ART = Object.freeze({
  sun: Object.freeze({ key: 'menu-sun', file: 'sun.svg', w: 112, h: 112 }),
  sunGlow: Object.freeze({ key: 'menu-sun-glow', file: 'sun-glow.svg', w: 200, h: 200 }),
  mountainsFar: Object.freeze({ key: 'menu-mountains-far', file: 'mountains-far.svg', w: 480, h: MENU_LAYERS.far.h }),
  mountainsMid: Object.freeze({ key: 'menu-mountains-mid', file: 'mountains-mid.svg', w: 480, h: MENU_LAYERS.mid.h }),
  mountainsNear: Object.freeze({ key: 'menu-mountains-near', file: 'mountains-near.svg', w: 480, h: MENU_LAYERS.near.h }),
  logoBitstreamFill: Object.freeze({ key: 'menu-logo-bitstream-fill', file: 'logo-bitstream-fill.svg', w: 249, h: 42 }),
  logoBitstreamLine: Object.freeze({ key: 'menu-logo-bitstream-line', file: 'logo-bitstream-line.svg', w: 249, h: 42 }),
  logoBluffsFill: Object.freeze({ key: 'menu-logo-bluffs-fill', file: 'logo-bluffs-fill.svg', w: 205, h: 51 }),
  logoBluffsLine: Object.freeze({ key: 'menu-logo-bluffs-line', file: 'logo-bluffs-line.svg', w: 205, h: 51 }),
  riderBase: Object.freeze({ key: 'menu-rider-base', file: 'rider-base.svg', w: 26, h: 20 }),
  riderSled: Object.freeze({ key: 'menu-rider-sled', file: 'rider-sled.svg', w: 26, h: 20 }),
  riderBody: Object.freeze({ key: 'menu-rider-body', file: 'rider-body.svg', w: 26, h: 20 }),
  riderHelmet: Object.freeze({ key: 'menu-rider-helmet', file: 'rider-helmet.svg', w: 26, h: 20 }),
  corner: Object.freeze({ key: 'menu-corner', file: 'corner.svg', w: 9, h: 9 }),
});

/**
 * Rider sprite anchor: the runner's underside is the bottom of row 18 of the 20-row canvas, centred on x 13
 * (see RIDER_MAP in the generator). Images are placed with this origin so (x, y) is where the sled touches
 * the ridge.
 */
export const RIDER_ORIGIN = Object.freeze({ x: 13 / 26, y: 19 / 20 });

/**
 * Queue every menu SVG on a loader (call from a scene's preload()). Tolerates loaders without svg support
 * (headless/Jest stubs) by queuing nothing.
 * @param {Phaser.Loader.LoaderPlugin|any} load
 * @returns {number} files queued
 */
export function queueMenuArt(load) {
  if (!load || typeof load.svg !== 'function') return 0;
  let n = 0;
  for (const a of Object.values(MENU_ART)) {
    // already present (a scene restarted): queuing again would only log a duplicate-key warning
    if (load.textureManager && typeof load.textureManager.exists === 'function' && load.textureManager.exists(a.key)) continue;
    load.svg(a.key, MENU_ART_BASE + a.file, { width: a.w, height: a.h });
    n++;
  }
  return n;
}

/**
 * Resolve a MENU_ART name ('sun') or a raw texture key ('menu-sun') to its key.
 * @param {string} nameOrKey @returns {string}
 */
export function artKey(nameOrKey) {
  return MENU_ART[nameOrKey] ? MENU_ART[nameOrKey].key : nameOrKey;
}

/**
 * Did this texture load? False for unknown keys, Phaser's placeholder textures, and scenes without a texture
 * manager.
 * @param {Phaser.Scene} scene @param {string} nameOrKey @returns {boolean}
 */
export function hasArt(scene, nameOrKey) {
  const key = artKey(nameOrKey);
  const tm = scene && scene.textures;
  if (!tm || typeof tm.exists !== 'function') return false;
  if (key === '__MISSING' || key === '__DEFAULT') return false;
  try {
    return tm.exists(key) === true;
  } catch (e) {
    return false;
  }
}

/**
 * A tint spec: a palette key ('magenta'), a fixed colour number, or a function of the palette returning a
 * colour or four corner colours [topLeft, topRight, bottomLeft, bottomRight] (vertical gradients).
 * @typedef {string|number|function(Object<string,number>):(number|number[])} TintSpec
 */

/**
 * Apply a resolved tint to any object with setTint.
 * @param {{setTint:function(...number):any}} obj @param {number|number[]} t @returns {void}
 */
export function applyTint(obj, t) {
  if (!obj || typeof obj.setTint !== 'function') return;
  if (Array.isArray(t)) obj.setTint(t[0], t[1], t[2], t[3]);
  else obj.setTint(t);
}

/**
 * @param {TintSpec} spec @param {Object<string,number>} pal @returns {number|number[]}
 */
export function resolveTint(spec, pal) {
  if (typeof spec === 'function') return spec(pal);
  if (typeof spec === 'number') return spec;
  return pal && pal[spec] !== undefined ? pal[spec] : 0xffffff;
}

/**
 * Keep an object's tint bound to the theme: applied now and on every palette/theme change, unbound when the
 * object is destroyed.
 * @param {import('./Theme.js').Theme} theme
 * @param {Phaser.GameObjects.GameObject & {setTint:Function}} obj
 * @param {TintSpec} spec
 * @returns {function():void} unbind
 */
export function bindTint(theme, obj, spec) {
  if (!theme || typeof theme.bind !== 'function') {
    applyTint(obj, resolveTint(spec, {}));
    return () => {};
  }
  const unbind = theme.bind((pal) => applyTint(obj, resolveTint(spec, pal)));
  if (obj && typeof obj.once === 'function') obj.once('destroy', unbind);
  return unbind;
}

/**
 * @typedef {Object} ArtOpts
 * @property {import('./Theme.js').Theme} [theme] required for `tint`
 * @property {TintSpec} [tint]  omitted = the art's own (greyscale/baked) colours
 * @property {number} [originX=0.5] @property {number} [originY=0.5]
 * @property {number} [alpha] @property {number} [depth]
 * @property {number} [blend] a Phaser.BlendModes value (e.g. ADD for glows)
 * @property {Phaser.GameObjects.Container} [parent] add to this container instead of the display list
 */

function finish(scene, obj, o) {
  obj.setOrigin(o.originX === undefined ? 0.5 : o.originX, o.originY === undefined ? 0.5 : o.originY);
  if (o.alpha !== undefined) obj.setAlpha(o.alpha);
  if (o.depth !== undefined) obj.setDepth(o.depth);
  if (o.blend !== undefined && typeof obj.setBlendMode === 'function') obj.setBlendMode(o.blend);
  if (o.tint !== undefined) bindTint(o.theme, obj, o.tint);
  if (o.parent) o.parent.add(obj);
  return obj;
}

/**
 * A (tinted, theme-bound) image of a menu texture, or null when the texture is not available, so the
 * caller can draw its fallback: `artImage(...) || drawProcedural()`.
 * @param {Phaser.Scene} scene
 * @param {string} nameOrKey MENU_ART name or texture key
 * @param {number} x @param {number} y
 * @param {ArtOpts} [o]
 * @returns {Phaser.GameObjects.Image|null}
 */
export function artImage(scene, nameOrKey, x, y, o = {}) {
  if (!hasArt(scene, nameOrKey) || !scene.add || typeof scene.add.image !== 'function') return null;
  const img = scene.add.image(x, y, artKey(nameOrKey));
  return finish(scene, img, o);
}

/**
 * A (tinted, theme-bound) horizontally scrolling strip of a menu texture, or null when unavailable. Origin
 * defaults to the top-left, as strips are laid out by their top edge.
 * @param {Phaser.Scene} scene
 * @param {string} nameOrKey
 * @param {number} x @param {number} y @param {number} w @param {number} h
 * @param {ArtOpts} [o]
 * @returns {Phaser.GameObjects.TileSprite|null}
 */
export function artTileSprite(scene, nameOrKey, x, y, w, h, o = {}) {
  if (!hasArt(scene, nameOrKey) || !scene.add || typeof scene.add.tileSprite !== 'function') return null;
  const ts = scene.add.tileSprite(x, y, w, h, artKey(nameOrKey));
  return finish(scene, ts, { originX: 0, originY: 0, ...o });
}

/**
 * Mix two 0xRRGGBB colours. Used to derive in-between accents (a violet between magenta and cyan) from the
 * palette instead of baking a hex that would ignore colour-blind mode.
 * @param {number} a @param {number} b @param {number} t 0 = a, 1 = b
 * @returns {number}
 */
export function mixColor(a, b, t) {
  const k = Math.min(1, Math.max(0, t));
  const ch = (c, s) => (c >> s) & 0xff;
  const m = (s) => Math.round(ch(a, s) + (ch(b, s) - ch(a, s)) * k);
  return (m(16) << 16) | (m(8) << 8) | m(0);
}/**
 * OWNER: UI engineer.
 * Normalises every input device into a small menu vocabulary:
 *   'up' | 'down' | 'left' | 'right' | 'confirm' | 'cancel' | 'alt' | 'shop' | 'ghost' | 'retry' (opt-in)
 * Sources: EVT.INPUT_ACTION (InputRouter: keyboard / gamepad / touch), Phaser keyboard (redundant, so menus work
 * with the stub router too) and a direct navigator.getGamepads() poll. The same action arriving from two sources
 * within DEDUPE_MS is delivered once. All listeners are removed on scene shutdown.
 *
 * Raw text entry: set `rawKeyHandler` (returns true when it consumed the event). While set, keyboard-sourced
 * INPUT_ACTIONs are ignored (typing "A" must not also move a cursor) and keyboard input arrives only as raw events.
 *
 * Opt-in 'retry' (`{ retryAction: true }`, Marvin decision 7, used by GameOverScene only): keyboard Space fires
 * 'retry' FIRST and then its usual 'confirm', and pad RB (button 5) fires 'retry'. Space is told apart from
 * Enter by InputRouter's 'hop' action: on the keyboard only Space sends it (Space = 'hop' + 'confirm', Enter =
 * 'confirm'). Pad A also sends 'hop' but from source 'gamepad', so it stays a plain 'confirm'. A host that acts
 * on 'retry' (and leaves the screen) never sees the trailing 'confirm' do anything; other menus do not opt in.
 */
import Phaser from 'phaser';
import { REG } from '../constants.js';
import { EVT } from '../events.js';

const DEDUPE_MS = 60;
const REPEAT_FIRST_MS = 340;
const REPEAT_MS = 100;

const KEY_MAP = {
  ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
  w: 'up', s: 'down', a: 'left', d: 'right', W: 'up', S: 'down', A: 'left', D: 'right',
  Enter: 'confirm', ' ': 'confirm', Escape: 'cancel', n: 'alt', N: 'alt',
  // W4.1: open the Shard Shop. Added here rather than as a scene-local key listener so every menu gets
  // the same debouncing and the same gamepad equivalent (LB), and so the Game Over footer hint can
  // promise a key that actually exists.
  b: 'shop', B: 'shop',
  // Issue #56: Game Over ghost favorites. Other menus ignore the action.
  g: 'ghost', G: 'ghost',
};
const DIRS = new Set(['up', 'down', 'left', 'right']);
const ROUTER_MAP = {
  up: 'up', down: 'down', left: 'left', right: 'right', confirm: 'confirm', hop: 'confirm',
  cancel: 'cancel', pause: 'cancel',
};

export class MenuInput {
  /**
   * @param {Phaser.Scene} scene
   * @param {function(string, string):void} handler called with (action, source)
   * @param {{graceMs?:number, retryAction?:boolean}} [opts] ignore all input for graceMs after creation;
   *   retryAction: also fire 'retry' for keyboard Space and pad RB (see the file header)
   */
  constructor(scene, handler, opts = {}) {
    this.scene = scene;
    this.game = scene.game;
    this.handler = handler;
    this.enabled = true;
    /** @type {null|function(KeyboardEvent):boolean} */
    this.rawKeyHandler = null;
    this.born = performance.now();
    this.graceMs = opts.graceMs || 0;
    this.retryAction = opts.retryAction === true;
    this.last = {};
    this.padPrev = this._readPad();
    this.padHold = {};

    this._onAction = (p) => {
      if (!p || !p.pressed) return;
      if (this.rawKeyHandler && p.source === 'keyboard') return;
      // Keyboard 'hop' is Space (Enter sends 'confirm' only). 'retry' goes first so a host that leaves on it
      // never acts on the 'confirm' that follows.
      if (this.retryAction && p.action === 'hop' && (p.source || 'keyboard') === 'keyboard') this._fire('retry', 'keyboard');
      const a = ROUTER_MAP[p.action];
      if (a) this._fire(a, p.source || 'keyboard');
    };
    this.game.events.on(EVT.INPUT_ACTION, this._onAction);

    this._onKey = (ev) => {
      const e = ev.originalEvent || ev;
      this._unlock();
      if (this.rawKeyHandler && this.rawKeyHandler(e)) return;
      if (this.rawKeyHandler) return;
      const a = KEY_MAP[e.key];
      if (!a) return;
      if (e.repeat && !DIRS.has(a)) return;
      if (this.retryAction && e.key === ' ') this._fire('retry', 'keyboard');
      this._fire(a, 'keyboard', true);
    };
    // Phaser's keyboard plugin is used for plain menu keys only. In raw text-entry mode (initials) native window events
    // are used instead: InputRouter preventDefaults Space / arrows and Phaser drops default-prevented events (Space
    // would never reach the entry), and Phaser's per-frame key queue was seen re-delivering keys out of order when
    // several arrive in one frame (fast typing 'zqx' gave 'ZZX').
    // Events already consumed natively are remembered so that Phaser's (later, per-frame) copy of the same key press
    // cannot act again once raw mode has ended, e.g. the Enter that saved the initials must not also retry.
    this._native = new WeakSet();
    this._onPhaserKey = (ev) => {
      const e = ev.originalEvent || ev;
      if (this.rawKeyHandler || (e && this._native.has(e))) return;
      this._onKey(ev);
    };
    if (scene.input.keyboard) scene.input.keyboard.on('keydown', this._onPhaserKey);
    this._onWinKey = (e) => {
      if (!this.rawKeyHandler || e.ctrlKey || e.metaKey || e.altKey) return;
      const t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable === true)) return;
      this._native.add(e);
      this._onKey(e);
    };
    if (typeof window !== 'undefined') window.addEventListener('keydown', this._onWinKey);

    this._onPointer = () => this._unlock();
    scene.input.on('pointerdown', this._onPointer);

    this._onUpdate = (time, delta) => this._pollPad(delta);
    scene.events.on(Phaser.Scenes.Events.UPDATE, this._onUpdate);

    this._cleanup = () => this.destroy();
    scene.events.once('shutdown', this._cleanup);
    scene.events.once('destroy', this._cleanup);
  }

  _unlock() {
    try {
      const audio = this.game.registry.get(REG.AUDIO);
      if (audio) audio.unlock();
    } catch (e) {
      /* ignore */
    }
  }

  _fire(action, source, allowRepeat = false) {
    if (!this.enabled) return;
    const now = performance.now();
    if (now - this.born < this.graceMs) return;
    if (!allowRepeat || !DIRS.has(action)) {
      if (this.last[action] !== undefined && now - this.last[action] < DEDUPE_MS) return;
    } else if (this.last[action] !== undefined && now - this.last[action] < 12) {
      return;
    }
    this.last[action] = now;
    this.handler(action, source);
  }

  _readPad() {
    const out = { btn: [], ax: 0, ay: 0 };
    try {
      const pads = (navigator.getGamepads && navigator.getGamepads()) || [];
      for (const p of pads) {
        if (!p || !p.connected) continue;
        p.buttons.forEach((b, i) => {
          if (b.pressed) out.btn[i] = true;
        });
        if (Math.abs(p.axes[0] || 0) > Math.abs(out.ax)) out.ax = p.axes[0];
        if (Math.abs(p.axes[1] || 0) > Math.abs(out.ay)) out.ay = p.axes[1];
      }
    } catch (e) {
      /* no gamepad API */
    }
    return out;
  }

  _pollPad(delta) {
    const cur = this._readPad();
    const prev = this.padPrev;
    const edge = (i) => cur.btn[i] && !prev.btn[i];
    if (edge(0)) this._fire('confirm', 'gamepad');
    if (edge(1) || edge(9)) this._fire('cancel', 'gamepad');
    if (edge(2) || edge(3)) this._fire('alt', 'gamepad');
    // W4.1: LB / LT opens the shop, mirroring the keyboard's B so a pad player is not locked out of the
    // footer hint the keyboard player can use.
    if (edge(4) || edge(6)) this._fire('shop', 'gamepad');
    // Decision 7: RB retries on Game Over (opt-in). Free here, and InputRouter gives it no menu action.
    if (this.retryAction && edge(5)) this._fire('retry', 'gamepad');
    const dirs = {
      up: cur.btn[12] || cur.ay < -0.6,
      down: cur.btn[13] || cur.ay > 0.6,
      left: cur.btn[14] || cur.ax < -0.6,
      right: cur.btn[15] || cur.ax > 0.6,
    };
    for (const d of Object.keys(dirs)) {
      if (dirs[d]) {
        const h = this.padHold[d];
        if (h === undefined) {
          this.padHold[d] = REPEAT_FIRST_MS;
          this._fire(d, 'gamepad', true);
        } else {
          this.padHold[d] = h - delta;
          if (this.padHold[d] <= 0) {
            this.padHold[d] = REPEAT_MS;
            this._fire(d, 'gamepad', true);
          }
        }
      } else {
        delete this.padHold[d];
      }
    }
    this.padPrev = cur;
  }

  /** @returns {void} */
  destroy() {
    if (!this.game) return;
    this.game.events.off(EVT.INPUT_ACTION, this._onAction);
    const s = this.scene;
    if (s.input && s.input.keyboard) s.input.keyboard.off('keydown', this._onPhaserKey);
    if (typeof window !== 'undefined') window.removeEventListener('keydown', this._onWinKey);
    if (s.input) s.input.off('pointerdown', this._onPointer);
    s.events.off(Phaser.Scenes.Events.UPDATE, this._onUpdate);
    s.events.off('shutdown', this._cleanup);
    s.events.off('destroy', this._cleanup);
    this.rawKeyHandler = null;
    this.handler = () => {};
    this.game = null;
  }
}/**
 * OWNER: UI engineer.
 * Vertical menu list usable with keyboard, gamepad (via MenuInput actions), mouse and touch.
 * Item kinds:
 *   action : { label, onSelect }
 *   choice : { label, options:[{value,label}], get(), set(v) }   left/right cycles, click cycles forward
 *   slider : { label, get() -> 0..1, set(v), step? }              left/right adjusts, click/drag on the bar sets
 *   static : { label }                                            drawn but never focusable or clickable
 * Optional per item: sub (dim secondary text), color (palette key), disabled,
 *   badge (noninteractive in-row warning), badgeColor (palette key),
 *   subColor / subAlpha (palette key and alpha of the `sub` text; default text at 0.6),
 *   tint (palette key the label always wears when enabled; default only the selected row is coloured),
 *   heading (on a 'static' row: draw it as a bright section heading in `color` instead of a dim line).
 *
 * Selection look (synthwave pass): `g` paints the static state exactly where the selected row IS (a faint
 * wash over the selected cell, badges, sliders); it is what layout tests measure, so its first fillRect is
 * always the selected cell. On top of that, `cursorG` paints the animated cursor: a gradient bar with a
 * chevron that GLIDES from the previous row to the new one (eased, frame-rate independent), pulses gently,
 * runs a light sweep every few seconds and flashes on confirm. Reduce motion: the cursor snaps and holds
 * still. The cursor is paint only: hit zones, column layout and every input path are unchanged.
 */
import Phaser from 'phaser';
import { NeonText } from './Neon.js';
import { measureText } from './PixelFont.js';
import { uiSfx } from './Sound.js';
import { approach, isReducedMotion, onTick } from './Motion.js';

const SLIDER_W = 70;

export class MenuList extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,w:number,rowH?:number,items:object[],color?:string,align?:'left'|'center',scale?:number,
   *          parent?:Phaser.GameObjects.Container, onBack?:function():void,
   *          columns?:number, rowsPerColumn?:number}} o
   *
   * `columns` > 1 lays the SAME list out column-major: item i fills column floor(i / rowsPerColumn),
   * row i % rowsPerColumn. Column-major rather than row-major so up/down keep walking down a column and
   * only wrap into the next one at the bottom; row-major would make `down` jump sideways. Default 1
   * leaves every existing menu pixel-identical.
   */
  constructor(scene, theme, o) {
    super(scene, o.x, o.y);
    this.theme = theme;
    this.w = o.w;
    this.rowH = o.rowH || 16;
    this.items = o.items;
    this.colorKey = o.color || 'cyan';
    this.align = o.align || 'left';
    this.scale1 = o.scale || 1;
    // W6: the biome toggle list outgrew one column (11 signatures), so the list can split. Geometry is
    // computed once here and every row reads it, so a row can never disagree with its own hit zone.
    this.columns = Math.max(1, Math.floor(o.columns || 1));
    this.rowsPerColumn = Math.max(1, Math.floor(o.rowsPerColumn || this.items.length || 1));
    this.colW = this.w / this.columns;
    this.selected = this.items.findIndex((i) => !i.disabled);
    if (this.selected < 0) this.selected = 0;
    this.dragging = -1;
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    // Under the labels, over the wash: the animated cursor (see the header).
    this.cursorG = new Phaser.GameObjects.Graphics(scene);
    this.add(this.cursorG);
    /** @type {{x:number,y:number}|null} where the cursor bar is drawn now (null = snap on next paint) */
    this.glide = null;
    this.confirmFlash = 0;
    this.rows = this.items.map((item, i) => this._buildRow(scene, item, i));
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind(() => this.refresh());
    this._stopTick = onTick(scene, (time, delta) => this._tick(time, delta));
  }

  /** Column-major cell for item i: which column, and which row inside it. */
  _cell(i) {
    return { col: Math.floor(i / this.rowsPerColumn), rowInCol: i % this.rowsPerColumn };
  }

  _buildRow(scene, item, i) {
    const { col, rowInCol } = this._cell(i);
    const x0 = col * this.colW;
    const y = rowInCol * this.rowH;
    const cy = y + this.rowH / 2;
    const center = this.align === 'center';
    const label = new NeonText(scene, this.theme, x0 + (center ? this.colW / 2 : 14), cy, item.label, {
      color: item.color || 'text', scale: this.scale1, anchor: center ? 'center' : 'left', vAnchor: 0.5,
    });
    this.add(label);
    const row = { label, value: null, sub: null, zone: null, badge: null, badgeBox: null };
    if (item.badge) {
      const text = String(item.badge).toUpperCase();
      const badgeX = x0 + 14 + measureText(item.label) * this.scale1 + 7;
      const badgeW = measureText(text) * this.scale1 + 10;
      if (badgeX + badgeW > x0 + this.colW - 62) {
        throw new Error('Menu warning badge would overlap the choice value: ' + item.label);
      }
      row.badgeBox = { x: badgeX, y: y + 2, w: badgeW, h: this.rowH - 4 };
      row.badge = new NeonText(scene, this.theme, badgeX + 5, cy, text, {
        color: item.badgeColor || 'magenta', scale: this.scale1,
        anchor: 'left', vAnchor: .5,
      });
      this.add(row.badge);
    }
    if (item.kind === 'choice' || item.kind === 'slider') {
      row.value = new NeonText(scene, this.theme, x0 + this.colW - 8, cy, '', { color: this.colorKey, anchor: 'right', vAnchor: 0.5 });
      this.add(row.value);
    }
    if (item.sub) {
      row.sub = new NeonText(scene, this.theme, x0 + this.colW - 8, cy, item.sub, {
        color: 'text', anchor: 'right', vAnchor: 0.5, outline: 'none',
      });
      row.sub.setAlpha(0.6);
      this.add(row.sub);
    }
    // W6's column geometry AND W5's static rows: the zone is sized to the COLUMN, and a static row gets no
    // zone at all. Both matter — a full-width zone under a two-column list would let a click in the left
    // column select a row in the right one.
    const zone = new Phaser.GameObjects.Zone(scene, x0, y, this.colW, this.rowH).setOrigin(0, 0);
    // 'static' rows are headings and summary lines: they are drawn by the same list so they share its
    // geometry, but they must never take focus or swallow a click meant for the row beneath.
    if (item.kind === 'static') {
      row.zone = null;
      return row;
    }
    zone.setInteractive({ useHandCursor: !item.disabled });
    this.add(zone);
    zone.on('pointerover', () => {
      if (!item.disabled) this.setSelected(i, true);
    });
    zone.on('pointerdown', (p, lx) => this._onPointerDown(i, lx));
    zone.on('pointermove', (p, lx) => {
      if (this.dragging === i && p.isDown) this._setSliderFromX(i, lx);
    });
    zone.on('pointerup', () => { this.dragging = -1; });
    zone.on('pointerupoutside', () => { this.dragging = -1; });
    row.zone = zone;
    return row;
  }

  _sliderRange() {
    return { x0: this.w - 8 - SLIDER_W - 26, x1: this.w - 8 - 26 };
  }

  _onPointerDown(i, lx) {
    const item = this.items[i];
    if (item.disabled) return;
    this.setSelected(i, true);
    if (item.kind === 'slider') {
      this.dragging = i;
      this._setSliderFromX(i, lx);
    } else if (item.kind === 'choice') {
      this._adjust(i, lx < this.w * 0.6 && lx < this.w - 90 ? -1 : 1);
    } else {
      this.activate(i);
    }
  }

  _setSliderFromX(i, lx) {
    const { x0, x1 } = this._sliderRange();
    const v = Math.min(1, Math.max(0, (lx - x0) / (x1 - x0)));
    const item = this.items[i];
    const step = item.step || 0.1;
    const snapped = Math.round(v / step) * step;
    if (Math.abs(snapped - item.get()) > 1e-6) {
      item.set(Math.min(1, Math.max(0, snapped)));
      uiSfx(this.scene, 'uiMove');
      this.refresh();
    }
  }

  /** @param {number} i @param {boolean} [silent] @returns {void} */
  setSelected(i, silent) {
    if (i === this.selected) return;
    this.selected = i;
    if (!silent) uiSfx(this.scene, 'uiMove');
    else uiSfx(this.scene, 'uiMove', { volume: 0.5 });
    this.refresh();
  }

  _move(dir) {
    const n = this.items.length;
    let i = this.selected;
    for (let k = 0; k < n; k++) {
      i = (i + dir + n) % n;
      if (!this.items[i].disabled) break;
    }
    this.setSelected(i);
  }

  _adjust(i, dir) {
    const item = this.items[i];
    if (item.kind === 'choice') {
      const cur = item.options.findIndex((o) => o.value === item.get());
      const next = item.options[(cur + dir + item.options.length) % item.options.length];
      item.set(next.value);
      uiSfx(this.scene, 'uiSelect');
    } else if (item.kind === 'slider') {
      const step = item.step || 0.1;
      const v = Math.min(1, Math.max(0, Math.round((item.get() + dir * step) / step) * step));
      item.set(v);
      uiSfx(this.scene, 'uiMove', { pitch: 0.8 + v * 0.6 });
    }
    this.refresh();
  }

  /** @param {number} [i] @returns {void} */
  activate(i = this.selected) {
    const item = this.items[i];
    if (!item || item.disabled) return;
    if (item.kind === 'choice') this._adjust(i, 1);
    else if (item.kind === 'slider') this._adjust(i, 1);
    else if (item.onSelect) {
      uiSfx(this.scene, 'uiSelect');
      this.confirmFlash = 1;
      this._paintCursor();
      item.onSelect();
    }
  }

  /**
   * @param {string} action MenuInput action
   * @returns {boolean} true if consumed
   */
  handleAction(action) {
    switch (action) {
      case 'up': this._move(-1); return true;
      case 'down': this._move(1); return true;
      case 'left':
      case 'right': {
        const k = this.items[this.selected].kind;
        if (k !== 'choice' && k !== 'slider') return false;
        this._adjust(this.selected, action === 'left' ? -1 : 1);
        return true;
      }
      case 'confirm': this.activate(); return true;
      default: return false;
    }
  }

  /** Repaint highlight + values. @returns {void} */
  refresh() {
    const pal = this.theme.pal;
    const g = this.g;
    g.clear();
    this.items.forEach((item, i) => {
      const row = this.rows[i];
      const sel = i === this.selected && !item.disabled;
      const c = pal[item.color || this.colorKey];
      if (row.badgeBox) {
        const box = row.badgeBox;
        const badgeColor = pal[item.badgeColor || 'magenta'];
        g.fillStyle(badgeColor, sel ? .24 : .14);
        g.fillRoundedRect(box.x, box.y, box.w, box.h, 2);
        g.lineStyle(1, badgeColor, sel ? 1 : .7);
        g.strokeRoundedRect(box.x+.5, box.y+.5, box.w-1, box.h-1, 2);
        row.badge.setColorKey(item.badgeColor || 'magenta');
        row.badge.setAlpha(item.disabled ? .35 : 1);
      }
      // Same cell as the row's own label and zone: in a multi-column list item i is NOT at i * rowH, and
      // painting it there put the highlight below the list, in the wrong column.
      const { col, rowInCol } = this._cell(i);
      const x0 = col * this.colW;
      const y = rowInCol * this.rowH;
      if (sel) {
        // the settled highlight; the bright edge and chevron belong to the gliding cursor (cursorG)
        g.fillStyle(c, 0.1);
        g.fillRect(x0, y, this.colW, this.rowH - 1);
      }
      if (item.kind === 'static' && item.heading) {
        row.label.setColorKey(item.color || 'text');
        row.label.setAlpha(1);
      } else {
        row.label.setColorKey(item.disabled ? 'text' : sel ? (item.color || 'text') : (item.tint || 'text'));
        row.label.setAlpha(item.disabled ? 0.35 : sel ? 1 : 0.85);
      }
      if (item.kind === 'choice') {
        const opt = item.options.find((o) => o.value === item.get()) || item.options[0];
        row.value.setText(sel ? `← ${opt.label} →` : opt.label);
        row.value.setColorKey(item.color || this.colorKey);
      } else if (item.kind === 'slider') {
        const v = item.get();
        const { x0, x1 } = this._sliderRange();
        const cy = y + this.rowH / 2;
        g.fillStyle(pal.bgAlt, 1);
        g.fillRect(x0, cy - 2, x1 - x0, 5);
        g.fillStyle(c, sel ? 0.5 : 0.3);
        g.fillRect(x0, cy - 2, x1 - x0, 1);
        g.fillRect(x0, cy + 2, x1 - x0, 1);
        g.fillStyle(c, 1);
        g.fillRect(x0, cy - 1, Math.round((x1 - x0) * v), 3);
        g.fillStyle(pal.text, 1);
        g.fillRect(x0 + Math.round((x1 - x0) * v) - 1, cy - 4, 2, 9);
        row.value.setText(`${Math.round(v * 100)}%`);
        row.value.setColorKey(item.color || this.colorKey);
      }
      if (row.sub) {
        row.sub.setColorKey(item.subColor || 'text');
        if (item.subAlpha !== undefined) row.sub.setAlpha(item.subAlpha);
      }
    });
    this._paintCursor();
  }

  /** Top-left of the selected cell, or null when nothing selectable is selected. */
  _targetCell() {
    const item = this.items[this.selected];
    if (!item || item.disabled || item.kind === 'static') return null;
    const { col, rowInCol } = this._cell(this.selected);
    return { x: col * this.colW, y: rowInCol * this.rowH };
  }

  _tick(time, delta) {
    if (!this.scene || !this.visible) return;
    const target = this._targetCell();
    if (target && this.glide && !isReducedMotion(this.scene)) {
      // eased glide toward the selected cell; ~40 ms half-life feels instant to the hand but reads as motion
      const k = approach(delta, 40);
      this.glide.x += (target.x - this.glide.x) * k;
      this.glide.y += (target.y - this.glide.y) * k;
      if (Math.abs(target.x - this.glide.x) < 0.3 && Math.abs(target.y - this.glide.y) < 0.3) this.glide = { ...target };
    }
    if (this.confirmFlash > 0) this.confirmFlash = Math.max(0, this.confirmFlash - (delta || 16) / 220);
    this._paintCursor(time);
  }

  /** @param {number} [time] scene time, for the pulse and the sweep */
  _paintCursor(time) {
    const f = this.cursorG;
    if (!f || !this.scene) return;
    f.clear();
    const target = this._targetCell();
    if (!target) return;
    const reduced = isReducedMotion(this.scene);
    if (!this.glide || reduced) this.glide = { ...target };
    const t = time === undefined ? ((this.scene.time && this.scene.time.now) || 0) : time;
    const pal = this.theme.pal;
    const item = this.items[this.selected];
    const c = pal[item.color || this.colorKey];
    const x = Math.round(this.glide.x);
    const y = Math.round(this.glide.y);
    const w = this.colW;
    const h = this.rowH - 1;
    const pulse = reduced ? 0.5 : 0.5 + 0.5 * Math.sin(t / 340);
    // gradient bar: strong at the left edge, fading to nothing at the right
    const steps = 8;
    const sw = Math.ceil(w / steps);
    for (let i = 0; i < steps; i++) {
      f.fillStyle(c, (0.22 + 0.08 * pulse) * (1 - i / steps));
      f.fillRect(x + i * sw, y, Math.min(sw, w - i * sw), h);
    }
    // hairlines top and bottom over the bright half
    f.fillStyle(c, 0.3 + 0.25 * pulse);
    f.fillRect(x, y, Math.round(w * 0.55), 1);
    f.fillRect(x, y + h - 1, Math.round(w * 0.55), 1);
    // light sweep: a narrow bright band crossing the bar every 2.8 s
    if (!reduced) {
      const sx = ((t % 2800) / 1100) * (w + 24) - 24;
      if (sx < w) {
        f.fillStyle(pal.text, 0.12);
        f.fillRect(Math.max(x, x + Math.round(sx)), y + 1, Math.max(0, Math.min(8, w - Math.round(sx))), h - 2);
      }
    }
    if (this.confirmFlash > 0) {
      f.fillStyle(pal.text, 0.4 * this.confirmFlash);
      f.fillRect(x, y, w, h);
    }
    // the bright left edge, then the chevron (bobbing a pixel toward the label)
    f.fillStyle(c, 1);
    f.fillRect(x, y, 2, h);
    const row = this.rows[this.selected];
    const bob = reduced ? 0 : (Math.sin(t / 220) > 0 ? 1 : 0);
    const cx = this.align === 'center' && row && row.label
      ? Math.round(x + w / 2 - row.label.textWidth / 2 - 9) + bob
      : x + 5 + bob;
    const cy = y + Math.floor(h / 2);
    f.fillStyle(pal.text, 0.95);
    f.fillRect(cx, cy - 2, 1, 5);
    f.fillRect(cx + 1, cy - 1, 1, 3);
    f.fillRect(cx + 2, cy, 1, 1);
  }

  destroy(fromScene) {
    if (this._stopTick) this._stopTick();
    this._stopTick = null;
    if (this._unbind) this._unbind();
    this._unbind = null;
    super.destroy(fromScene);
  }
}/**
 * OWNER: UI engineer.
 * Menu backdrop mountain ridgelines as pure, periodic functions. Pure on purpose (no Phaser import):
 *
 *  - `tools/menu-art/generate-menu-art.mjs` rasterises these exact functions into the authored
 *    `public/assets/menu/mountains-*.svg` layers, and
 *  - `Backdrop` reads the SAME functions at runtime, both to draw the procedural fallback when an SVG
 *    failed to load and to put the attract-mode rider on the visible ridge.
 *
 * One source means the rider never floats above or sinks into the art, and a missing asset falls back to
 * the identical silhouette. Every profile is periodic over MENU_TERRAIN_PERIOD (the 480 px world width) so
 * the layers tile seamlessly as horizontally scrolling TileSprites.
 */

/** Horizontal period of every layer, in px. Equal to GAME_WIDTH so one texture tiles the screen exactly. */
export const MENU_TERRAIN_PERIOD = 480;

const TAU = Math.PI * 2;

/**
 * Layer geometry. `h` is the texture height; the ridge lives inside [top, h). Harmonics are integers so the
 * profile is periodic over the period. `ridged` folds a harmonic with |sin| for sharp, wire-frame peaks; the
 * near layer is left smooth so it reads as rolling foothills in front of the jagged ranges.
 * `speed` is the parallax scroll in px/s at warp 1 (far moves slowest).
 * @type {Readonly<Object<string,{h:number, top:number, amp:number, speed:number, ridged:boolean,
 *   harmonics:ReadonlyArray<[number, number, number]>}>>}
 */
export const MENU_LAYERS = Object.freeze({
  far: Object.freeze({
    h: 84, top: 4, amp: 66, speed: 3, ridged: true,
    harmonics: Object.freeze([[1, 0.5, 0.4], [2, 0.32, 2.1], [5, 0.12, 4.4], [13, 0.04, 1.3]]),
  }),
  mid: Object.freeze({
    h: 60, top: 6, amp: 46, speed: 8, ridged: true,
    harmonics: Object.freeze([[2, 0.5, 1.7], [3, 0.3, 0.2], [7, 0.12, 3.0], [17, 0.04, 5.1]]),
  }),
  near: Object.freeze({
    h: 36, top: 8, amp: 24, speed: 18, ridged: false,
    harmonics: Object.freeze([[2, 0.5, 2.6], [4, 0.3, 0.9], [7, 0.15, 4.0], [11, 0.05, 2.2]]),
  }),
});

/** Layer names, back to front (draw order). */
export const MENU_LAYER_ORDER = Object.freeze(['far', 'mid', 'near']);

/**
 * Normalised height 0..1 of a layer at x (any real x; wraps by the period).
 * @param {keyof MENU_LAYERS} name
 * @param {number} x
 * @returns {number}
 */
export function ridgeNorm(name, x) {
  const L = MENU_LAYERS[name];
  const raw = rawProfile(L, x);
  const [lo, hi] = rangeOf(name);
  // Remapped to the layer's own min..max over one period, so every layer uses its full amplitude: the sum
  // of harmonics never actually reaches 0 or 1, and unmapped it left flat, featureless valleys.
  const n = (raw - lo) / (hi - lo || 1);
  // A mild power curve deepens the valleys so peaks stand out against the horizon glow.
  return Math.pow(Math.min(1, Math.max(0, n)), L.ridged ? 1.25 : 1.1);
}

function rawProfile(L, x) {
  let sum = 0;
  let total = 0;
  for (const [k, a, ph] of L.harmonics) {
    const s = Math.sin((TAU * k * x) / MENU_TERRAIN_PERIOD + ph);
    // ridged: 1-|s| peaks sharply where s crosses zero, which is what gives the far ranges their crisp
    // crests; smooth: (s+1)/2 keeps the foothills round.
    sum += a * (L.ridged ? 1 - Math.abs(s) : (s + 1) / 2);
    total += a;
  }
  return sum / total;
}

/** @type {Map<string, [number, number]>} per-layer [min, max] of rawProfile over one period (lazy). */
const RANGES = new Map();
function rangeOf(name) {
  let r = RANGES.get(name);
  if (!r) {
    const L = MENU_LAYERS[name];
    let lo = Infinity;
    let hi = -Infinity;
    for (let x = 0; x < MENU_TERRAIN_PERIOD; x++) {
      const v = rawProfile(L, x);
      if (v < lo) lo = v;
      if (v > hi) hi = v;
    }
    r = [lo, hi];
    RANGES.set(name, r);
  }
  return r;
}

/**
 * Ridge Y of a layer at x, in texture pixels (0 = top of the layer texture). Integer, because the art is
 * rasterised per pixel column and the rider must stand on exactly the pixel the art drew.
 * @param {keyof MENU_LAYERS} name
 * @param {number} x
 * @returns {number}
 */
export function ridgeY(name, x) {
  const L = MENU_LAYERS[name];
  const xi = ((Math.floor(x) % MENU_TERRAIN_PERIOD) + MENU_TERRAIN_PERIOD) % MENU_TERRAIN_PERIOD;
  return Math.round(L.top + (1 - ridgeNorm(name, xi)) * L.amp);
}

/**
 * Ridge slope (radians, screen space: positive = descending to the right) around x, averaged over +-3 px so
 * a single stair step in the pixel ridge does not twitch the rider.
 * @param {keyof MENU_LAYERS} name
 * @param {number} x
 * @returns {number}
 */
export function ridgeSlope(name, x) {
  return Math.atan2(ridgeY(name, x + 3) - ridgeY(name, x - 3), 6);
}/**
 * OWNER: progression engineer. NO Phaser imports.
 *
 * W2 mission UI geometry, extracted so overlap is asserted in Jest rather than eyeballed in a
 * screenshot. W1's audit found three separate layout collisions that a pixel probe missed, so every
 * rectangle the mission UI draws is computed here and checked by tests/src/missionslayout.test.js.
 *
 * Virtual screen is 480x270 (see UIScene / the sim harness).
 */

// PixelFont has no Phaser import, so this stays a pure module dependency (the file's stated rule).
import { FONT_LINE_H, measureText } from './PixelFont.js';

export const SCREEN = Object.freeze({ w: 480, h: 270 });

/** One panel's fixed geometry, in virtual pixels. */
export const MISSION_PANEL = Object.freeze({
  x: 10,
  y: 96,
  w: 300,
  rows: 3,
  // 18 keeps a full three-slot panel inside the band above the Title menu: 14 + 8 + 3*18 + 6 = 82,
  // so y 96..178. At 22 the panel ran to y=190 and collided with the band below (caught by
  // tests/src/missionslayout.test.js).
  rowH: 18,
  padX: 6,
  padTop: 14,
  labelH: 8,
});

/**
 * Title-screen mission list: the last section of the right-hand "cabinet card" (TITLE_CARD below).
 *
 * The synthwave Title reorganisation moved the list out of the old y 228..254 strip and into the card, where
 * it has the card's full inner width. That changed the row shape:
 *   * the progress bar sits UNDER its label again, but at a 12 px pitch: 8 px glyph box + 1 px gap + 2 px
 *     bar + 1 px gap. The old "bar under the label" defect was a 9 px pitch, where the bar landed inside
 *     the glyph box (CC Friday's "text sliced in half"); at 12 the bar is clear of its own label and of the
 *     next row, and both are asserted in tests/src/missionslayout.test.js.
 *   * the row is 140 px wide, which fits the widest real mission title upper-cased (138 measured font px),
 *     so a title is never ellipsized at all.
 *   * still headerless as a panel: the card draws a MISSIONS rule above it (TITLE_CARD.sections.missionsHead).
 */
export const MISSION_LIST_TITLE = Object.freeze({
  x: 324,
  y: 216,
  w: 140,
  rows: 3,
  /** 8 px glyph + 1 gap + 2 px bar + 1 gap. */
  rowH: 12,
  /** Full glyph box. Must equal the font's 8 rows or descenders are cut. */
  labelH: 8,
  barH: 2,
  /** Gap between the glyph box and the bar under it. */
  barGap: 1,
  /** The bar spans the row (it sits under the label, not beside it). */
  barW: 140,
  padX: 0,
  padTop: 0,
});

/**
 * Game Over mission block. It goes in the LEDGER panel (right), because the left RUN REPORT panel has
 * no room at all: its 8 report rows reach local 128, then the ledger hash 132, seed 144, COPY button
 * to 154, against a floor at 160.
 *
 * The panel interior is local 0..160. Two earlier layouts were wrong and both were caught in audit:
 *
 *  1. Keeping the board at its 11 px pitch and trimming it to 8 rows bought the band, but it silently
 *     broke the "top 10" contract the panel title advertises (Luna, round 3).
 *  2. Packing three mission rows at an 8 px pitch put each progress bar 2 px up into its own label,
 *     because an 8 px label plus a 2 px bar needs 10 px, not 8 (Luna, round 3).
 *
 * What actually fits was solved numerically, not by eye: the board keeps ALL TEN rows at a 9 px pitch
 * (8 px glyph + 1 px gap), ending at local 125; a 1 px separator rule sits at 126; three mission rows
 * at a 10 px pitch (8 px label with its 2 px bar flush underneath) run 127..157, leaving 3 px above
 * the panel floor at 160. Ten truthful entries beat a heading that would have to lie about the count.
 */
export const GAMEOVER_BOARD_ROWS = 10;
/** Board pitch on Game Over only: 9 px fits ten rows in the space where 11 px fits eight. */
export const GAMEOVER_BOARD_ROW_H = 9;
/** Mission rows start here. Budget derived numerically, not by eye (see the solver in the tests). */
export const GAMEOVER_MISSIONS_Y = 128;
/**
 * Mission row pitch. A glyph box is 8 rows (GLYPH_H) and font row 7 is a descender, so a pitch of 10
 * leaves a 2 px nominal gap that measures 1.25 px once the descender is drawn — the rows visually
 * merge, which is half of what CC Friday read as "text sliced in half". 11 gives a real 3 px gap.
 * The block still fits: 128 + 2*11 + 8 = 158 against a panel floor at 160.
 */
export const GAMEOVER_ROW_H = 11;
/**
 * Separator rule above the mission block. This replaces the separate "MISSIONS" heading: with ten
 * truthful leaderboard rows the panel has no vertical room for a heading line, and dropping the
 * heading beats either lying about the board size or covering a mission label. The rule plus the
 * progress bars identify the group.
 */
export const GAMEOVER_MISSIONS_RULE_Y = 127;
/**
 * Rows a glyph can occupy, taken from the font rather than declared here: `buildTexture` writes font
 * rows 0..7 (a 5x7 face plus one descender row) into a cell of FONT_LINE_H = 9, so real ink spans
 * GLYPH_H = 8 rows. A text box shorter than this clips ink; a row pitch below GLYPH_H + 1 makes
 * consecutive rows touch — the descender row alone is what turned a nominal 2 px gap into 1.25 px.
 *
 * This is deliberately derived, not restated: a layout that asserts "this label is one glyph tall"
 * against its own local constant proves only that the constant equals itself, so the test could never
 * catch a wrong constant. Importing the font's own line height makes the assertion bite.
 */
export const GLYPH_H = FONT_LINE_H - 1;
/** Height of one pixel-font line at scale 1; the bar must start at or below this. */
export const LABEL_H = GLYPH_H;

/**
 * Game Over initials-entry geometry, in LEDGER-panel-local coordinates.
 *
 * This exists because moving the two hint lines to 84/96 to clear the mission separator put them
 * straight THROUGH the SAVE button (local 88..104, drawn by `InitialsEntry`), so the button box
 * covered the middle of both hint lines — a regression from the legibility fix, caught by CC Friday at
 * native resolution. The stack is fixed and order-sensitive, so it is encoded here and asserted:
 *
 *   22..30   ENTER YOUR INITIALS
 *   28..84   entry widget: up-arrow zone, 28 px letter slots, down-arrow zone
 *   88..104  SAVE button
 *  106..124  the two hint lines
 *  127      mission separator rule (the mission rows start at 128)
 *
 * The hints cannot go below ~124 because the rule is at 127 and three mission rows need 128..158.
 */
export const ENTRY_LAYOUT = Object.freeze({
  panelW: 216,
  titleY: 22,
  entryY: 28,
  /** Entry-widget internals, mirrored from InitialsEntry's constructor (slotY 14, slotH 28). */
  entrySlotY: 14,
  entrySlotH: 28,
  saveY: 88,
  saveH: 16,
  saveW: 84,
  hint1Y: 106,
  hint2Y: 116,
});

/**
 * Rects for the initials-entry stack, in panel-local coordinates. The SAVE rect and the hint rects are
 * returned separately so a test can assert they are disjoint — the assertion whose absence let the
 * button be drawn over the hints.
 * @returns {{title:Object, slots:Object, save:Object, hints:Object[], contentBottom:number}}
 */
export function entryLayout(o = {}) {
  const L = { ...ENTRY_LAYOUT, ...o };
  const slotsTop = L.entryY + L.entrySlotY;
  return {
    title: rect(8, L.titleY, L.panelW - 16, GLYPH_H),
    // The entry WIDGET spans the full panel width (it centres its slots inside that), so this rect is
    // 0-based: it is the widget's box, not a slot. Anchoring it at entryY offset it 28 px right and off
    // the panel — the panel-bounds assertion below is what caught that.
    slots: rect(0, slotsTop, L.panelW, L.entrySlotH),
    save: rect(Math.round((L.panelW - L.saveW) / 2), L.saveY, L.saveW, L.saveH),
    hints: [
      rect(0, L.hint1Y, L.panelW, GLYPH_H),
      rect(0, L.hint2Y, L.panelW, GLYPH_H),
    ],
    contentBottom: L.hint2Y + GLYPH_H,
    // The constants used, echoed so a test can re-derive the SAVE offset from the widget's own layout
    // instead of taking the resulting rect on faith.
    entryY: L.entryY,
    entrySlotY: L.entrySlotY,
    entrySlotH: L.entrySlotH,
    panelW: L.panelW,
  };
}

/**
 * Title screen geometry (synthwave arcade-cabinet layout). Virtual screen 480x270.
 *
 *   y   4..94   logo (centre, over the retro sun) + tagline; jukebox top-right; stars elsewhere
 *   y  94..150  sun + mountains, left and centre left OPEN (nothing drawn over the backdrop)
 *   y 150       horizon (TITLE_HORIZON)
 *   y 154..254  menu panel (left, over the grid floor) | open centre (rider, help chip) | cabinet card (right,
 *               y 94..254)
 *   y 258..266  control hint
 *
 * The centre column between the menu and the card (x 216..316) is kept free from the logo down to the hint so
 * the sun, the ranges, the rider and the grid's vanishing point always read. Every band is asserted
 * pairwise-disjoint in tests/src/missionslayout.test.js.
 */
export const TITLE_HORIZON = 192;

/** The right-hand "cabinet card": level badge, BEST, Daily Patch and missions. Section ys are card-local. */
export const TITLE_CARD = Object.freeze({
  x: 316,
  y: 94,
  w: 156,
  h: 160,
  pad: 8,
  /** Local y of every line, top edge of its 8 px glyph box (the rule name is 2x: 16 px). */
  sections: Object.freeze({
    level: 5,
    title: 15,
    best: 26,
    rule1: 37,
    dailyHead: 41,
    ruleName: 52,
    desc1: 71,
    desc2: 80,
    next: 91,
    chase: 101,
    missionsHead: 111,
    missions: 122,
  }),
});

/** Inner text width of the card. */
export const TITLE_CARD_INNER_W = TITLE_CARD.w - TITLE_CARD.pad * 2;

/** The Title screen's occupied bands, for overlap assertions. Screen coordinates. */
export const TITLE_BANDS = Object.freeze({
  // Both chrome words, plus 3 px either side for the wave and the glitch slices' sideways kick.
  logo: Object.freeze({ x: 110, y: 2, w: 260, h: 92 }),
  version: Object.freeze({ x: 8, y: 6, w: 96, h: 9 }),
  tagline: Object.freeze({ x: 160, y: 96, w: 150, h: 8 }),
  jukebox: Object.freeze({ x: 372, y: 6, w: 102, h: 30 }),
  menu: Object.freeze({ x: 8, y: 154, w: 208, h: 100 }),
  card: Object.freeze({ x: TITLE_CARD.x, y: TITLE_CARD.y, w: TITLE_CARD.w, h: TITLE_CARD.h }),
  // The Daily Patch section of the card: DAILY PATCH header down to the streak line.
  daily: Object.freeze({
    x: TITLE_CARD.x,
    y: TITLE_CARD.y + TITLE_CARD.sections.dailyHead,
    w: TITLE_CARD.w,
    h: TITLE_CARD.sections.chase + 8 - TITLE_CARD.sections.dailyHead,
  }),
  // BEST: one line in the card's player section, above the Daily Patch.
  best: Object.freeze({ x: TITLE_CARD.x + TITLE_CARD.pad, y: TITLE_CARD.y + TITLE_CARD.sections.best, w: TITLE_CARD_INNER_W, h: 8 }),
  // The tappable HOW TO PLAY chip, in the open centre column above the hint.
  help: Object.freeze({ x: 226, y: 240, w: 80, h: 14 }),
  // The attract-mode PRESS START prompt (2x) and its sub line, over the sun between the tagline and the horizon.
  attract: Object.freeze({ x: 170, y: 110, w: 140, h: 30 }),
  // The control hint at GAME_HEIGHT - 8 (glyphs 258..266).
  hint: Object.freeze({ x: 0, y: 258, w: 480, h: 9 }),
});

/**
 * Title menu geometry, computed from the row count so a seventh entry cannot be added silently.
 *
 * This exists because W4 added SHARD SHOP as a seventh row and the SETTINGS row ended up drawn over the
 * DAILY PATCH strip (CC Friday's W4 defect 3). The scene's panel height had multiplied the row pitch by the
 * text scale, so it reported a 228px panel for 112px of rows and nothing noticed it was lying.
 *
 * The menu sits on the grid floor under the horizon, in the band y 154..254 (the hint is at 258). MenuList
 * uses rowH as the pitch and scales only the glyphs, so six 2x rows at a 16 px pitch need 96 px plus a 2 px
 * inset top and bottom: exactly the band. Six is the ceiling: a seventh row reaches 268, through the hint.
 *
 * @param {number} count number of menu rows
 * @returns {{x:number,y:number,w:number,h:number,rowH:number,scale:number,rows:number,inset:number,lastRowBottom:number,fits:boolean}}
 */
export function titleMenuLayout(count) {
  const ROW_H = 16;
  const SCALE = 2;
  const INSET = 2;
  const band = TITLE_BANDS.menu;
  const rows = Math.max(0, Math.floor(count) || 0);
  // Panel height is rows * pitch plus the inset top and bottom. NOT multiplied by scale: MenuList treats rowH
  // as the pitch and scales only the glyphs, so scaling here double-counted it.
  const h = INSET * 2 + rows * ROW_H;
  const lastRowBottom = band.y + INSET + rows * ROW_H;
  return {
    x: band.x, y: band.y, w: band.w, h, rowH: ROW_H, scale: SCALE, rows, inset: INSET, lastRowBottom,
    fits: lastRowBottom <= band.y + band.h && h <= band.h,
  };
}

/** Left x of the Title BEST line: the card's text column. */
export const TITLE_BEST_X = TITLE_BANDS.best.x;
/** Top y of the Title BEST line. */
export const TITLE_BEST_Y = TITLE_BANDS.best.y;

/**
 * The card's BEST line: the full `BEST <m> M   <score> PTS` when it fits the card's text column, else the
 * same numbers without the PTS label and with tighter spacing. Fitting is measured in the real font.
 * @param {string} m formatted distance @param {string} sc formatted score
 * @returns {string}
 */
export function titleBestText(m, sc) {
  const full = `BEST ${m} M   ${sc} PTS`;
  return measureText(full) <= TITLE_CARD_INNER_W ? full : `BEST ${m} M  ${sc}`;
}

/**
 * The card's Daily chase line: streak and today's best (or NOT PLAYED TODAY), shortened the same way.
 * @param {number} streak 0 = no streak shown @param {string|null} todayBest formatted, null = not played today
 * @returns {string}
 */
export function titleChaseText(streak, todayBest) {
  const tail = todayBest === null ? 'NOT PLAYED TODAY' : `TODAY ${todayBest}`;
  const parts = streak > 0 ? [`STREAK ${streak}`, tail] : [tail];
  const full = parts.join('  ');
  if (measureText(full) <= TITLE_CARD_INNER_W || streak <= 0) return full;
  return `STREAK ${streak}  ${todayBest === null ? 'NOT PLAYED' : todayBest}`;
}

/**
 * Every rect the cabinet card draws text into, in SCREEN coordinates, for overlap tests (the scene reads
 * TITLE_CARD.sections for the same numbers). The rule name band is 16 px: 2x when it fits the inner width,
 * else 1x centred in the band.
 * @returns {Object<string, {x:number,y:number,w:number,h:number}>}
 */
export function titleCardLayout() {
  const C = TITLE_CARD;
  const S = C.sections;
  const x = C.x + C.pad;
  const w = TITLE_CARD_INNER_W;
  const line = (y, h = GLYPH_H) => rect(x, C.y + y, w, h);
  return {
    card: rect(C.x, C.y, C.w, C.h),
    level: line(S.level),
    title: line(S.title),
    best: line(S.best),
    rule1: line(S.rule1, 1),
    dailyHead: line(S.dailyHead),
    ruleName: line(S.ruleName, 16),
    desc1: line(S.desc1),
    desc2: line(S.desc2),
    next: line(S.next),
    chase: line(S.chase),
    missionsHead: line(S.missionsHead),
    missions: missionListLayout(3).panel,
  };
}

/**
 * A rect as {x, y, w, h} — the one shape every consumer (Jest tests, Phaser Graphics) understands.
 * @param {number} x @param {number} y @param {number} w @param {number} h
 */
export const rect = (x, y, w, h) => ({ x, y, w, h });

/** Do two rects overlap, with an optional required gap between them? */
export function overlaps(a, b, gap = 0) {
  if (!a || !b) return false;
  return !(a.x + a.w + gap <= b.x || b.x + b.w + gap <= a.x
    || a.y + a.h + gap <= b.y || b.y + b.h + gap <= a.y);
}

/** Every rect fully inside the virtual screen? */
export function insideScreen(r, screen = SCREEN) {
  if (!r) return false;
  return r.x >= 0 && r.y >= 0 && r.x + r.w <= screen.w && r.y + r.h <= screen.h;
}

/**
 * Geometry for the in-run / pause mission panel: one row per active mission.
 * @param {number} count how many missions are active (<= rows)
 * @param {{x?:number,y?:number}} [o]
 * @returns {{panel:Object, header:Object, rows:Array<Object>, bars:Array<Object>}}
 */
export function missionPanelLayout(count, o = {}) {
  const P = { ...MISSION_PANEL, ...o };
  const n = Math.max(0, Math.min(P.rows, Math.round(count || 0)));
  const panel = rect(P.x, P.y, P.w, P.padTop + P.labelH + n * P.rowH + 6);
  const header = rect(P.x + P.padX, P.y + 4, P.w - P.padX * 2, P.labelH);
  const rows = [];
  const bars = [];
  const top = P.y + P.padTop + P.labelH;
  for (let i = 0; i < n; i++) {
    const y = top + i * P.rowH;
    // Text occupies the left ~70%; the bar sits at the row's bottom edge, full width.
    rows.push(rect(P.x + P.padX, y, P.w - P.padX * 2, 9));
    bars.push(rect(P.x + P.padX, y + 10, P.w - P.padX * 2, 4));
  }
  return { panel, header, rows, bars };
}

/**
 * Geometry for the Title-screen mission list (the cabinet card's last section).
 * @param {number} count
 * @param {{x?:number,y?:number}} [o]
 */
export function missionListLayout(count, o = {}) {
  const L = { ...MISSION_LIST_TITLE, ...o };
  const n = Math.max(0, Math.min(L.rows, Math.round(count || 0)));
  const panel = rect(L.x, L.y, L.w, L.padTop + n * L.rowH);
  const rows = [];
  const bars = [];
  const top = L.y + L.padTop;
  // The bar sits under the label, separated from its full 8 px glyph box by barGap, and the pitch leaves a
  // gap under the bar too, so a bar can touch neither its own label nor the next row's glyphs.
  const textW = L.w - L.padX * 2;
  const barW = Math.min(L.barW, textW);
  for (let i = 0; i < n; i++) {
    const y = top + i * L.rowH;
    rows.push(rect(L.x + L.padX, y, textW, L.labelH));
    bars.push(rect(L.x + L.padX, y + L.labelH + L.barGap, barW, L.barH));
  }
  return { panel, header: null, rows, bars };
}

/**
 * Which HUD slots the mission toast may use. The existing MILESTONE strip owns its slot; the toast
 * must not land on top of it, nor on the hint rows.
 * @param {{hudStrips:Array<Object>}} o
 */
export function toastSlot(o = {}) {
  const strips = Array.isArray(o.hudStrips) ? o.hudStrips : [];
  const w = 240;
  const h = 12;
  // Preferred: just under the score block on the left, above the pause band.
  const candidates = [
    rect(8, 60, w, h),
    rect(8, 74, w, h),
    rect(8, 88, w, h),
  ];
  for (const c of candidates) {
    if (!strips.some((s) => overlaps(c, s, 2)) && insideScreen(c)) return c;
  }
  return null;
}

/**
 * How many characters of a mission title fit a row, given the pixel font's advance width.
 * The pixel font is monospace-ish at `advance` px per char (default 6 at scale 1).
 * @param {number} rowW @param {number} [advance]
 */
export function charsThatFit(rowW, advance = 6) {
  const a = advance > 0 ? advance : 6;
  return Math.max(1, Math.floor(rowW / a));
}

/**
 * Truncate a title to fit a row, with an ellipsis. Truncation is tested so a long template can never
 * silently overrun its bar the way W1's reward string overran a level label.
 * @param {string} text @param {number} rowW @param {number} [advance]
 */
export function ellipsize(text, rowW, advance = 6) {
  const s = typeof text === 'string' ? text : '';
  const max = charsThatFit(rowW, advance);
  if (s.length <= max) return s;
  // '..' rather than '…': the pixel font has no ellipsis glyph and would draw '?' (PixelFont.ellipsize
  // uses the same mark).
  if (max <= 2) return s.slice(0, max);
  return `${s.slice(0, max - 2)}..`;
}

/**
 * Rows for drawing the three missions inside an existing panel column (Pause, Game Over), where the
 * panel already owns its geometry. Kept here — not in the scenes — so the "does it fit?" question is
 * answered by a unit test rather than by eye.
 *
 * @param {{x:number, y:number, w:number, count:number, rowH?:number, barH?:number}} o
 * @returns {{rows:Array<{x:number,y:number,w:number}>, bars:Array<{x:number,y:number,w:number,h:number}>, h:number}}
 */
export function columnRows(o) {
  const x = o.x;
  const y = o.y;
  const w = o.w;
  const count = Math.max(0, Math.round(o.count || 0));
  const rowH = o.rowH || 10;
  const barH = o.barH || 2;
  const barW = o.barW || 30;
  const rows = [];
  const bars = [];
  // The bar is INLINE — at the right end of the row's own line — rather than underneath the label.
  // Stacking them needs labelH + barH = 10 px per row and leaves a zero-pixel gap between one row's
  // bar and the next row's glyphs, which reads as a slab of ink pasted over the text. A glyph is 8
  // rows tall (GLYPH_H), so the label box keeps that full height and the bar sits beside it.
  const textW = Math.max(24, w - barW - 4);
  for (let i = 0; i < count; i += 1) {
    const ry = y + i * rowH;
    rows.push(rect(x, ry, textW, GLYPH_H));
    bars.push(rect(x + w - barW, ry + Math.floor((GLYPH_H - barH) / 2), barW, barH));
  }
  return { rows, bars, h: count * rowH, textW };
}/**
 * W2 mission UI. One place that draws the three active missions, so Title, Pause and Game Over all
 * render from the same published view and the same tested geometry — and so a layout fix lands in
 * one file rather than three.
 *
 * All geometry comes from src/ui/MissionsLayout.js, which is unit-tested for overlap. Nothing here
 * computes a coordinate by hand.
 */
import Phaser from 'phaser';
import { NeonText } from './Neon.js';
import { mixColor } from './MenuArt.js';
import { Panel } from './Panel.js';
import { missionPanelLayout, missionListLayout, ellipsize } from './MissionsLayout.js';
// Two different ellipsize helpers exist: MissionsLayout's takes a row width at a fixed 6 px advance, PixelFont's
// takes real measured font pixels. The toast is measured text on the HUD strip, so it uses PixelFont's.
import { ellipsize as ellipsizePx, measureText } from './PixelFont.js';
import { stripTextMaxPx } from './HudLayout.js';
import { GAME_WIDTH } from '../constants.js';

const fmt = (n) => String(Math.round(n || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

/**
 * Draw the Title screen's mission list: the last section of the cabinet card. No panel of its own (the card
 * is the panel); a container at the list's top-left holding, per mission, an upper-cased title over a
 * full-width progress bar. Titles are fitted with the MEASURED font width, and the row is wide enough for
 * the longest real title (MissionsLayout.MISSION_LIST_TITLE), so nothing is cut in practice.
 * @param {Phaser.Scene} scene
 * @param {Object} theme
 * @param {Array} rows mission view rows from REG.MISSIONS
 * @returns {Phaser.GameObjects.Container|null}
 */
export function buildTitleMissionList(scene, theme, rows) {
  const list = Array.isArray(rows) ? rows.slice(0, 3) : [];
  if (!list.length) return null;
  const L = missionListLayout(list.length);
  const box = new Phaser.GameObjects.Container(scene, L.panel.x, L.panel.y);
  scene.add.existing(box);
  const g = new Phaser.GameObjects.Graphics(scene);
  box.add(g);
  const labels = [];
  list.forEach((row, i) => {
    const r = L.rows[i];
    if (!r) return;
    const title = String(row.title || '').toUpperCase();
    // a done row gets a tick when it fits; the lime colour and the full bar say "done" either way
    const ticked = `✓ ${title}`;
    const text = row.done && measureText(ticked) <= r.w ? ticked : ellipsizePx(title, r.w);
    const label = new NeonText(scene, theme, r.x - L.panel.x, r.y - L.panel.y, text, {
      color: row.done ? 'lime' : 'text', outline: 'none',
    });
    label.setAlpha(row.done ? 1 : 0.9);
    box.add(label);
    labels.push(label);
  });
  const paint = (pal) => {
    g.clear();
    list.forEach((row, i) => {
      const bar = L.bars[i];
      if (!bar) return;
      const bx = bar.x - L.panel.x;
      const by = bar.y - L.panel.y;
      const frac = Math.max(0, Math.min(1, row.fraction || 0));
      const c = row.done ? pal.lime : pal.cyan;
      // track: a dim groove with tick marks every quarter, so an empty bar still reads as a gauge
      g.fillStyle(mixColor(pal.bgAlt, c, 0.28), 1);
      g.fillRect(bx, by, bar.w, bar.h);
      g.fillStyle(c, 0.5);
      for (let q = 1; q < 4; q++) g.fillRect(bx + Math.round((bar.w * q) / 4), by, 1, bar.h);
      if (frac > 0) {
        const fw = Math.max(1, Math.round(bar.w * frac));
        g.fillStyle(c, 0.95);
        g.fillRect(bx, by, fw, bar.h);
        // a bright leading pixel: the "charging" tip
        g.fillStyle(pal.text, 0.9);
        g.fillRect(bx + fw - 1, by, 1, bar.h);
      }
    });
  };
  const unbind = theme.bind(paint);
  box.once('destroy', unbind);
  box.labels = labels;
  return box;
}

/**
 * Draw the in-run / pause mission panel with progress bars.
 * @param {Phaser.Scene} scene
 * @param {Object} theme
 * @param {Array} rows
 * @param {{x?:number,y?:number}} [o]
 */
export function buildMissionPanel(scene, theme, rows, o = {}) {
  const list = Array.isArray(rows) ? rows.slice(0, 3) : [];
  if (!list.length) return null;
  const L = missionPanelLayout(list.length, o);
  const panel = new Panel(scene, theme, {
    x: L.panel.x, y: L.panel.y, w: L.panel.w, h: L.panel.h,
    color: 'cyan', title: 'MISSIONS', fillAlpha: 0.88,
  });
  list.forEach((row, i) => {
    const r = L.rows[i];
    const bar = L.bars[i];
    if (!r) return;
    const local = { x: r.x - L.panel.x, y: r.y - L.panel.y, w: r.w };
    const text = `${ellipsize(row.title, local.w - 76)}  ${row.text || ''}`;
    const label = new NeonText(scene, theme, local.x, local.y, text, {
      color: row.done ? 'lime' : 'text', outline: 'none',
    });
    label.setAlpha(0.92);
    panel.add(label);
    const bx = bar.x - L.panel.x;
    const by = bar.y - L.panel.y;
    const g = scene.add.graphics();
    g.fillStyle(0x1a2b3a, 1);
    g.fillRect(bx, by, bar.w, bar.h);
    const frac = Math.max(0, Math.min(1, row.fraction || 0));
    if (frac > 0) {
      const color = row.done ? 0x9cff57 : (theme.color('cyan'));
      g.fillStyle(color, 1);
      g.fillRect(bx, by, Math.max(1, Math.round(bar.w * frac)), bar.h);
    }
    panel.add(g);
  });
  return panel;
}

/**
 * The lines Game Over shows for missions: what was completed and whether the set cleared.
 * @param {{completed:Array,setCleared:boolean,xp:number,shards:number}|null} m
 * @returns {string[]}
 */
export function gameOverMissionLines(m) {
  if (!m) return [];
  const done = Array.isArray(m.completed) ? m.completed : [];
  if (!done.length && !m.setCleared) return [];
  const lines = [];
  if (done.length) {
    // Names are looked up by the caller when available; ids are a safe fallback that never overruns.
    lines.push(`MISSIONS ${done.length}/3  +${fmt(m.xp)} XP  +${fmt(m.shards)} SHARDS`);
  }
  if (m.setCleared) lines.push('SET CLEARED  BONUS PAID');
  return lines;
}

/**
 * Fit "<NAME> DONE  +<XP> XP" on the HUD strip, cutting only the name (with the font's "..") so the reward
 * always shows. The limit is the strip's real text width (HudLayout.stripTextMaxPx), in measured font px.
 * @param {string} name already upper-cased
 * @param {number} xp
 * @returns {string}
 */
export function stripToastText(name, xp) {
  const suffix = ` DONE  +${fmt(xp)} XP`;
  const maxPx = stripTextMaxPx(GAME_WIDTH);
  const full = `${name}${suffix}`;
  if (measureText(full) <= maxPx) return full;
  return `${ellipsizePx(name, Math.max(0, maxPx - measureText(suffix)))}${suffix}`;
}

/**
 * Completion toast text for one finished mission, sized for the MILESTONE strip.
 *
 * It used to call MissionsLayout.ellipsize(text, 36), whose second argument is a row width in PIXELS at a
 * 6 px advance, so every toast was cut to about five letters ("LAND …", audit MT-1).
 * @param {{id:string,xp:number,shards:number}} c @param {string} [title]
 */
export function missionToastText(c, title) {
  if (!c) return '';
  const name = typeof title === 'string' && title ? title.toUpperCase() : 'MISSION';
  return stripToastText(name, c.xp);
}/**
 * OWNER: UI engineer.
 * Menu motion: the reduce-motion decision, easing, and the shared open/close/scene transitions.
 *
 * Reduce motion. Settings `reduceMotion` is 'auto' | 'on' | 'off'. 'auto' follows the OS
 * `prefers-reduced-motion: reduce` media query, read live (the MediaQueryList is cached and its `matches`
 * re-read on every call, so flipping the OS switch takes effect without a reload). When reduced, every helper
 * here collapses to a short fade (REDUCED_MS) and callers skip shake, glitch, warp and parallax. The decision
 * is a pure function (resolveReduceMotion) so it is unit-tested without a browser.
 *
 * Why no Phaser import: the pure half is tested under Jest, and the scene half only needs what a scene
 * already carries (scene.tweens, scene.add, scene.cameras). Every scene helper degrades when those are absent
 * (Jest stubs, a scene mid-shutdown): it jumps to the end state, so a transition can never strand a view
 * half-open or a scene change un-fired.
 */
import { REG, GAME_WIDTH, GAME_HEIGHT } from '../constants.js';

/** The OS media query 'auto' follows. */
export const REDUCE_MOTION_QUERY = '(prefers-reduced-motion: reduce)';
/** The settings values, in the order SettingsView cycles them. */
export const REDUCE_MOTION_VALUES = Object.freeze(['auto', 'on', 'off']);
/** Every transition collapses to a fade this long when motion is reduced. */
export const REDUCED_MS = 120;

// ------------------------------------------------------------------ reduce-motion decision (pure)

/**
 * Coerce anything to a valid setting value ('auto' for unknown), as SaveStore.sanitizeSettings does.
 * @param {any} v @returns {'auto'|'on'|'off'}
 */
export function sanitizeReduceMotion(v) {
  return REDUCE_MOTION_VALUES.includes(v) ? v : 'auto';
}

/**
 * The decision itself. 'on' and 'off' are the player's explicit choice and always win; anything else is
 * 'auto' and follows the OS.
 * @param {any} setting settings.reduceMotion
 * @param {boolean} osPrefersReduced
 * @returns {boolean} true = reduce motion
 */
export function resolveReduceMotion(setting, osPrefersReduced) {
  const s = sanitizeReduceMotion(setting);
  if (s === 'on') return true;
  if (s === 'off') return false;
  return osPrefersReduced === true;
}

/** @type {WeakMap<object, MediaQueryList|null>} per-window cached query (null = unsupported). */
const MQ = new WeakMap();

/**
 * Does the OS ask for reduced motion? Guarded for jsdom/SSR/old browsers: no window, no matchMedia, or a
 * matchMedia that throws or returns nothing all mean "no preference".
 * @param {any} [win] defaults to the global window
 * @returns {boolean}
 */
export function osPrefersReducedMotion(win = typeof window !== 'undefined' ? window : undefined) {
  if (!win || typeof win !== 'object') return false;
  let mq = MQ.get(win);
  if (mq === undefined) {
    mq = null;
    try {
      if (typeof win.matchMedia === 'function') mq = win.matchMedia(REDUCE_MOTION_QUERY) || null;
    } catch (e) {
      mq = null;
    }
    MQ.set(win, mq);
  }
  return !!(mq && mq.matches === true);
}

/**
 * Should this scene's (or game's) menus reduce motion right now? Reads the live settings in the registry.
 * @param {{registry?:any, game?:any}|null|undefined} sceneOrGame a Phaser.Scene or Phaser.Game
 * @param {any} [win] window override (tests)
 * @returns {boolean}
 */
export function isReducedMotion(sceneOrGame, win) {
  let settings = null;
  try {
    const reg = sceneOrGame && (sceneOrGame.registry || (sceneOrGame.game && sceneOrGame.game.registry));
    settings = reg && typeof reg.get === 'function' ? reg.get(REG.SETTINGS) : null;
  } catch (e) {
    settings = null;
  }
  return resolveReduceMotion(settings && settings.reduceMotion, osPrefersReducedMotion(win));
}

/**
 * A duration under the current motion preference: unchanged, or capped to REDUCED_MS.
 * @param {number} ms @param {boolean} reduced @returns {number}
 */
export function motionMs(ms, reduced) {
  return reduced ? Math.min(ms, REDUCED_MS) : ms;
}

// ------------------------------------------------------------------ easing (pure)

/** @param {number} t @returns {number} t clamped to 0..1 */
export const clamp01 = (t) => (t <= 0 ? 0 : t >= 1 ? 1 : t);
/** @param {number} a @param {number} b @param {number} t @returns {number} */
export const lerp = (a, b, t) => a + (b - a) * t;

/**
 * Easing curves over 0..1 (input clamped; every curve maps 0 -> 0 and 1 -> 1). Plain functions rather than
 * Phaser ease names so callers can ease values they compute themselves (cursor glides, warp ramps).
 */
export const Ease = Object.freeze({
  linear: (t) => clamp01(t),
  inQuad: (t) => clamp01(t) ** 2,
  outQuad: (t) => { const u = clamp01(t); return 1 - (1 - u) * (1 - u); },
  inCubic: (t) => clamp01(t) ** 3,
  outCubic: (t) => 1 - (1 - clamp01(t)) ** 3,
  inOutCubic: (t) => { const u = clamp01(t); return u < 0.5 ? 4 * u * u * u : 1 - (-2 * u + 2) ** 3 / 2; },
  inOutSine: (t) => (1 - Math.cos(Math.PI * clamp01(t))) / 2,
  /** Overshoots ~10% then settles: the "snap" of a panel landing. */
  outBack: (t) => { const u = clamp01(t); if (u === 0 || u === 1) return u; const c1 = 1.70158; const c3 = c1 + 1; return 1 + c3 * (u - 1) ** 3 + c1 * (u - 1) ** 2; },
});

/**
 * Frame-rate independent exponential approach: the fraction of the remaining distance to cover this frame
 * for a follower that closes `rate` of the gap per second at 60 fps feel. Used by the menu cursor glide.
 * @param {number} dtMs @param {number} [halfLifeMs=45] time to close half the gap
 * @returns {number} 0..1
 */
export function approach(dtMs, halfLifeMs = 45) {
  if (!(dtMs > 0)) return 0;
  return 1 - Math.pow(0.5, dtMs / Math.max(1, halfLifeMs));
}

/**
 * Progress 0..1 of the CRT open transition, split into its two phases: the zip line drawing across
 * (`line`, 0..1 during the first ZIP_SPLIT of the time) and the panel unfolding (`open`, 0..1 after it).
 * Pure so the shape of the transition is testable.
 * @param {number} p overall progress 0..1
 * @returns {{line:number, open:number}}
 */
export function crtOpenPhases(p) {
  const u = clamp01(p);
  if (u < ZIP_SPLIT) return { line: Ease.outCubic(u / ZIP_SPLIT), open: 0 };
  return { line: 1, open: Ease.outBack((u - ZIP_SPLIT) / (1 - ZIP_SPLIT)) };
}
const ZIP_SPLIT = 0.35;

// ------------------------------------------------------------------ scene helpers

/** True when the scene can run tweens (real Phaser, and the Jest harness stubs). */
function canTween(scene) {
  return !!(scene && scene.tweens && typeof scene.tweens.addCounter === 'function');
}

/**
 * Is the scene still running (not shutting down or destroyed)? Phaser sets the status to SHUTDOWN (8) before
 * it emits 'shutdown', so a view destroyed from a shutdown listener sees this as false; adding a ghost then
 * would leak it into the display list of the scene's next start. Stubs without a status count as live.
 */
function sceneLive(scene) {
  const st = scene && scene.sys && scene.sys.settings && scene.sys.settings.status;
  return typeof st !== 'number' || st < 8;
}

/** Is a game object still alive (not destroyed)? Phaser clears `scene` on destroy. */
const alive = (o) => !!(o && o.scene);

/**
 * Drive `onUpdate(easedProgress)` from 0 to 1 over `duration` ms. Without a tween manager it jumps straight
 * to the end (onUpdate(1), then onComplete), so callers can always rely on the end state.
 * @param {Phaser.Scene} scene
 * @param {{duration:number, delay?:number, ease?:function(number):number,
 *          onUpdate:function(number, number):void, onComplete?:function():void}} o
 *   onUpdate receives (eased, raw) progress.
 * @returns {Phaser.Tweens.Tween|null}
 */
export function tweenProgress(scene, o) {
  const ease = o.ease || Ease.linear;
  let done = false;
  const finish = () => {
    if (done) return;
    done = true;
    o.onUpdate(ease(1), 1);
    if (o.onComplete) o.onComplete();
  };
  if (!canTween(scene) || !(o.duration > 0)) {
    finish();
    return null;
  }
  return scene.tweens.addCounter({
    from: 0,
    to: 1,
    duration: o.duration,
    delay: o.delay || 0,
    onUpdate: (tw) => {
      if (done) return;
      const raw = clamp01(typeof tw.getValue === 'function' ? tw.getValue() : 1);
      o.onUpdate(ease(raw), raw);
    },
    onComplete: finish,
    onStop: finish,
  });
}

/**
 * Fade a game object's alpha from its current value to `to`.
 * @param {Phaser.Scene} scene
 * @param {Phaser.GameObjects.GameObject & {alpha:number, setAlpha:function(number):any}} obj
 * @param {number} to
 * @param {number} ms
 * @param {function():void} [onComplete]
 * @returns {Phaser.Tweens.Tween|null}
 */
export function fadeTo(scene, obj, to, ms, onComplete) {
  const from = obj.alpha;
  return tweenProgress(scene, {
    duration: ms,
    ease: Ease.outQuad,
    onUpdate: (p) => { if (alive(obj)) obj.setAlpha(lerp(from, to, p)); },
    onComplete,
  });
}

/**
 * Modal dim layer for a host scene (Title, Pause): reuse the previous dim when one view replaces another, so
 * navigating Profile -> Shop does not flash the dim off and on; otherwise create it and fade it in.
 * @param {Phaser.Scene} scene
 * @param {Phaser.GameObjects.Rectangle|null} prevDim the host's current dim, or null
 * @param {number} alpha target opacity
 * @returns {Phaser.GameObjects.Rectangle}
 */
export function openDim(scene, prevDim, alpha) {
  if (alive(prevDim)) return prevDim;
  const dim = scene.add.rectangle(0, 0, GAME_WIDTH, GAME_HEIGHT, 0x000000, alpha).setOrigin(0, 0).setDepth(400).setInteractive();
  dim.setAlpha(0);
  fadeTo(scene, dim, 1, motionMs(160, isReducedMotion(scene)));
  return dim;
}

/**
 * Remove a dim layer with a fade. It stops catching input at once (the view it covered is already gone,
 * so the menu beneath must be clickable immediately) and is destroyed when the fade ends.
 * @param {Phaser.Scene} scene @param {Phaser.GameObjects.Rectangle|null} dim @returns {void}
 */
export function closeDim(scene, dim) {
  if (!alive(dim)) return;
  if (!sceneLive(scene)) { dim.destroy(); return; }
  if (typeof dim.disableInteractive === 'function') dim.disableInteractive();
  fadeTo(scene, dim, 0, motionMs(140, isReducedMotion(scene)), () => { if (alive(dim)) dim.destroy(); });
}

/**
 * Open a panel container with a CRT "zip": a bright line draws across the panel's centre, then the panel
 * unfolds vertically from that line with a small overshoot. Reduced motion: a REDUCED_MS fade.
 *
 * Only alpha is set synchronously (to 0, so the frame before the first tween tick never shows the panel at
 * full size). Position and scale change only inside the tween and always end exactly at the container's
 * original x/y and scale 1, so layout read right after construction (tests, hit zones) is the real layout.
 * @param {Phaser.Scene} scene
 * @param {Phaser.GameObjects.Container} container top-left anchored panel container
 * @param {{w:number, h:number, color?:number, duration?:number}} o
 * @returns {Phaser.Tweens.Tween|null}
 */
export function transitionIn(scene, container, o) {
  if (!container) return null;
  const reduced = isReducedMotion(scene);
  const baseX = container.x;
  const baseY = container.y;
  const { w, h } = o;
  container.setAlpha(0);
  if (reduced) return fadeTo(scene, container, 1, REDUCED_MS);
  const line = scene.add && typeof scene.add.graphics === 'function' ? scene.add.graphics() : null;
  if (line) line.setDepth((container.depth || 0) + 1);
  const color = o.color === undefined ? 0xffffff : o.color;
  const end = () => {
    if (line && alive(line)) line.destroy();
    if (!alive(container)) return;
    container.setAlpha(1).setScale(1, 1).setPosition(baseX, baseY);
  };
  return tweenProgress(scene, {
    duration: o.duration || 260,
    onUpdate: (p) => {
      if (!alive(container)) { end(); return; }
      const ph = crtOpenPhases(p);
      if (line && alive(line)) {
        line.clear();
        const lw = Math.max(2, Math.round(w * ph.line));
        const cx = baseX + w / 2;
        const cy = Math.round(baseY + h / 2);
        const fade = 1 - ph.open;
        line.fillStyle(color, 0.25 * fade);
        line.fillRect(Math.round(cx - lw / 2), cy - 2, lw, 5);
        line.fillStyle(0xffffff, 0.9 * fade);
        line.fillRect(Math.round(cx - lw / 2), cy, lw, 1);
      }
      if (ph.open <= 0) {
        container.setAlpha(0);
        return;
      }
      const sy = Math.max(0.02, ph.open);
      container.setAlpha(Math.min(1, ph.open * 1.6)).setScale(1, sy).setPosition(baseX, Math.round(baseY + (h * (1 - sy)) / 2));
    },
    onComplete: end,
  });
}

/**
 * Close: the panel object is destroyed by its owner straight away (view semantics stay synchronous), and a
 * short-lived ghost plays a CRT switch-off where it was: the frame collapses to a horizontal line, the line
 * shrinks to a dot and fades. Reduced motion: the frame just fades.
 * @param {Phaser.Scene} scene
 * @param {{x:number, y:number, w:number, h:number, color?:number, depth?:number}} r
 * @returns {Phaser.GameObjects.Graphics|null} the ghost (destroys itself)
 */
export function transitionOut(scene, r) {
  if (!scene || !scene.add || typeof scene.add.graphics !== 'function' || !sceneLive(scene)) return null;
  const reduced = isReducedMotion(scene);
  const g = scene.add.graphics();
  g.setDepth(r.depth === undefined ? 501 : r.depth);
  const color = r.color === undefined ? 0xffffff : r.color;
  const cx = r.x + r.w / 2;
  const cy = r.y + r.h / 2;
  tweenProgress(scene, {
    duration: reduced ? REDUCED_MS : 220,
    onUpdate: (p) => {
      if (!alive(g)) return;
      g.clear();
      if (p >= 1) return;
      if (reduced) {
        g.lineStyle(1, color, 0.6 * (1 - p));
        g.strokeRect(r.x + 0.5, r.y + 0.5, r.w - 1, r.h - 1);
        return;
      }
      // 0..0.55: height collapses to 1px; 0.55..1: width collapses to a dot
      const a = Ease.inCubic(clamp01(p / 0.55));
      const b = Ease.inCubic(clamp01((p - 0.55) / 0.45));
      const hh = Math.max(1, Math.round(r.h * (1 - a)));
      const ww = Math.max(1, Math.round(r.w * (1 - b)));
      const x = Math.round(cx - ww / 2);
      const y = Math.round(cy - hh / 2);
      g.fillStyle(color, 0.12 * (1 - b));
      g.fillRect(x, y, ww, hh);
      g.lineStyle(1, color, 0.8 * (1 - b));
      g.strokeRect(x + 0.5, y + 0.5, Math.max(1, ww - 1), Math.max(1, hh - 1));
      g.fillStyle(0xffffff, 0.9 * (1 - b * 0.6));
      g.fillRect(x, Math.round(cy), ww, 1);
    },
    onComplete: () => { if (alive(g)) g.destroy(); },
  });
  return g;
}

/**
 * Leave a scene with a scanline wipe: horizontal bands close top-to-bottom in a stagger, the last frame
 * flashes a thin white CRT line, then `go()` runs (typically scene.start). Reduced motion: a REDUCED_MS
 * camera fade. `go` runs exactly once, even if the tween manager is missing or the scene is shutting down.
 * @param {Phaser.Scene} scene
 * @param {function():void} go
 * @param {{duration?:number, color?:number, accent?:number, depth?:number}} [o]
 * @returns {void}
 */
export function sceneTransition(scene, go, o = {}) {
  let fired = false;
  const fire = () => {
    if (fired) return;
    fired = true;
    go();
  };
  const reduced = isReducedMotion(scene);
  if (reduced) {
    const cam = scene && scene.cameras && scene.cameras.main;
    if (cam && typeof cam.fadeOut === 'function' && typeof cam.once === 'function') {
      cam.once('camerafadeoutcomplete', fire);
      cam.fadeOut(REDUCED_MS, 0, 0, 0);
      // belt and braces: a camera that never reports completion must not strand the player
      if (scene.time && typeof scene.time.delayedCall === 'function') scene.time.delayedCall(REDUCED_MS + 80, fire);
      else fire();
    } else fire();
    return;
  }
  if (!canTween(scene) || !scene.add || typeof scene.add.graphics !== 'function') { fire(); return; }
  const g = scene.add.graphics().setDepth(o.depth === undefined ? 20000 : o.depth);
  const color = o.color === undefined ? 0x000000 : o.color;
  const accent = o.accent === undefined ? 0xffffff : o.accent;
  const BAND = 6;
  const bands = Math.ceil(GAME_HEIGHT / BAND);
  tweenProgress(scene, {
    duration: o.duration || 340,
    onUpdate: (p) => {
      if (!alive(g)) return;
      g.clear();
      for (let i = 0; i < bands; i++) {
        // each band starts a little after the one above it: a wipe that reads as a raster sweep
        const local = Ease.outQuad(clamp01(p * 1.6 - (i / bands) * 0.6));
        if (local <= 0) continue;
        const hh = Math.ceil(BAND * local);
        g.fillStyle(color, 1);
        g.fillRect(0, i * BAND, GAME_WIDTH, hh);
        if (local < 1) {
          g.fillStyle(accent, 0.35 * (1 - local));
          g.fillRect(0, i * BAND + hh, GAME_WIDTH, 1);
        }
      }
      if (p > 0.85) {
        g.fillStyle(accent, (p - 0.85) / 0.15 * 0.8);
        g.fillRect(0, Math.round(GAME_HEIGHT / 2), GAME_WIDTH, 1);
      }
    },
    onComplete: fire,
  });
}

/**
 * Run `fn(timeMs, deltaMs)` every frame of a scene until the returned function is called (or the scene shuts
 * down). For the small per-frame flourishes of menu widgets (cursor glide, bracket breathing) where a tween
 * per widget would be harder to keep in sync with repaints. A no-op on scenes without an event emitter.
 * @param {Phaser.Scene} scene
 * @param {function(number, number):void} fn
 * @returns {function():void} stop
 */
export function onTick(scene, fn) {
  const ev = scene && scene.events;
  if (!ev || typeof ev.on !== 'function' || typeof ev.off !== 'function') return () => {};
  const tick = (time, delta) => fn(time, delta);
  let stopped = false;
  const stop = () => {
    if (stopped) return;
    stopped = true;
    ev.off('update', tick);
    ev.off('shutdown', stop);
  };
  ev.on('update', tick);
  ev.once('shutdown', stop);
  return stop;
}/**
 * OWNER: UI engineer.
 * Neon text + small drawing helpers. All colours are palette keys resolved through Theme.
 */
import Phaser from 'phaser';
import { FONT_KEY, FONT_OUTLINE_KEY, FONT_LINE_H, measureText } from './PixelFont.js';

/**
 * Crisp bitmap text with an outline (dark, for legibility over gameplay) or a coloured glow.
 * Origin is controlled by `anchor` ('left'|'center'|'right') and `vAnchor` (0 top, 0.5 middle, 1 bottom).
 */
export class NeonText extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {number} x
   * @param {number} y
   * @param {string} text
   * @param {{color?:string, scale?:number, anchor?:'left'|'center'|'right', vAnchor?:number,
   *          outline?:'dark'|'glow'|'none', align?:'left'|'center'|'right', alpha?:number, parent?:Phaser.GameObjects.Container}} [opts]
   */
  constructor(scene, theme, x, y, text, opts = {}) {
    super(scene, Math.round(x), Math.round(y));
    this.theme = theme;
    this.colorKey = opts.color || 'text';
    this.outlineMode = opts.outline || 'dark';
    const anchor = opts.anchor || 'left';
    const ox = anchor === 'center' ? 0.5 : anchor === 'right' ? 1 : 0;
    const oy = opts.vAnchor === undefined ? 0 : opts.vAnchor;
    this.outlineText = null;
    if (this.outlineMode !== 'none') {
      this.outlineText = new Phaser.GameObjects.BitmapText(scene, 0, 0, FONT_OUTLINE_KEY, text);
      this.outlineText.setOrigin(ox, oy);
      this.add(this.outlineText);
    }
    this.main = new Phaser.GameObjects.BitmapText(scene, 0, 0, FONT_KEY, text);
    this.main.setOrigin(ox, oy);
    this.add(this.main);
    const align = opts.align || anchor;
    for (const t of [this.main, this.outlineText]) {
      if (!t) continue;
      if (align === 'center') t.setCenterAlign();
      else if (align === 'right') t.setRightAlign();
      else t.setLeftAlign();
    }
    this.setScale(opts.scale || 1);
    if (opts.alpha !== undefined) this.setAlpha(opts.alpha);
    scene.add.existing(this);
    if (opts.parent) opts.parent.add(this);
    this._unbind = theme.bind(() => this._paint());
  }

  _paint() {
    const c = this.theme.color(this.colorKey);
    this.main.setTint(c);
    if (this.outlineText) {
      if (this.outlineMode === 'glow') {
        this.outlineText.setTint(c);
        this.outlineText.setAlpha(0.22);
      } else {
        this.outlineText.setTint(0x000000);
        this.outlineText.setAlpha(0.9);
      }
    }
  }

  /** @param {string} str @returns {this} */
  setText(str) {
    str = String(str);
    if (this.main.text === str) return this;
    this.main.setText(str);
    if (this.outlineText) this.outlineText.setText(str);
    return this;
  }

  /** @param {string} key palette key @returns {this} */
  setColorKey(key) {
    if (this.colorKey !== key) {
      this.colorKey = key;
      this._paint();
    }
    return this;
  }

  /** Text width in screen px (includes container scale). @returns {number} */
  get textWidth() {
    return measureText(this.main.text.split('\n')[0]) * this.scaleX;
  }

  /** @returns {void} */
  destroy(fromScene) {
    if (this._unbind) this._unbind();
    this._unbind = null;
    super.destroy(fromScene);
  }
}

/**
 * Add a NeonText in one call.
 * @param {Phaser.Scene} scene
 * @param {import('./Theme.js').Theme} theme
 * @param {number} x
 * @param {number} y
 * @param {string} text
 * @param {ConstructorParameters<typeof NeonText>[5]} [opts]
 * @returns {NeonText}
 */
export function neonText(scene, theme, x, y, text, opts) {
  return new NeonText(scene, theme, x, y, text, opts);
}

/**
 * Draw a 1px-bordered rectangle using filled rects (pixel exact).
 * @param {Phaser.GameObjects.Graphics} g
 * @param {number} x
 * @param {number} y
 * @param {number} w
 * @param {number} h
 * @param {number} color
 * @param {number} [alpha=1]
 */
export function strokeRectPx(g, x, y, w, h, color, alpha = 1) {
  g.fillStyle(color, alpha);
  g.fillRect(x, y, w, 1);
  g.fillRect(x, y + h - 1, w, 1);
  g.fillRect(x, y + 1, 1, h - 2);
  g.fillRect(x + w - 1, y + 1, 1, h - 2);
}

/**
 * Soft neon glow around a rectangle: 1px strokes OUTSIDE it at falling alpha (2 px reach). Pixel-exact rects
 * rather than a blur shader, so it stays crisp under pixelArt, costs nothing, and paints in tests' fakes.
 * @param {Phaser.GameObjects.Graphics} g
 * @param {number} x @param {number} y @param {number} w @param {number} h
 * @param {number} color @param {number} [strength=1] scales both passes (hover glows use ~1.5)
 */
export function glowRectPx(g, x, y, w, h, color, strength = 1) {
  strokeRectPx(g, x - 2, y - 2, w + 4, h + 4, color, Math.min(1, 0.08 * strength));
  strokeRectPx(g, x - 1, y - 1, w + 2, h + 2, color, Math.min(1, 0.2 * strength));
}

/**
 * Draw neon corner brackets (Tron-style) around a rectangle.
 * @param {Phaser.GameObjects.Graphics} g
 * @param {number} x @param {number} y @param {number} w @param {number} h
 * @param {number} color @param {number} [len=6] @param {number} [alpha=1]
 */
export function cornerTicks(g, x, y, w, h, color, len = 6, alpha = 1) {
  g.fillStyle(color, alpha);
  for (const [cx, cy, sx, sy] of [[x, y, 1, 1], [x + w - 1, y, -1, 1], [x, y + h - 1, 1, -1], [x + w - 1, y + h - 1, -1, -1]]) {
    g.fillRect(sx > 0 ? cx : cx - len + 1, cy, len, 1);
    g.fillRect(cx, sy > 0 ? cy : cy - len + 1, 1, len);
  }
}

export { FONT_LINE_H, measureText };/**
 * OWNER: UI engineer (functional helper written by foundation; UI engineer may extend, not rename).
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 */
import { REG, PALETTE_KEYS } from '../constants.js';

/**
 * Colours of the active palette (settings.palette) as Phaser-style integers (0xRRGGBB).
 * Re-read on EVT.SETTINGS_CHANGED if you cache it.
 * @param {Phaser.Game} game
 * @returns {Object<string,number>} one entry per PALETTE_KEYS key, e.g. { cyan: 0x00f0ff, ... }.
 */
export function getPalette(game, biome) {
  const content = game.registry.get(REG.CONTENT);
  const settings = game.registry.get(REG.SETTINGS);
  const name = (settings && settings.palette) || 'default';
  const base = content.palettes[name] || content.palettes.default;
  // W3: a biome may tint the world, and its overrides are PARTIAL (only the keys it wants to move).
  // They are merged over the active palette rather than replacing it, so a colour-blind player still
  // gets the colour-blind base for every key the biome does not touch - a biome must never undo an
  // accessibility setting by supplying a full palette of its own.
  const hex = withBiomePalette(base, biome, name);
  /** @type {Object<string,number>} */
  const out = {};
  for (const k of PALETTE_KEYS) out[k] = parseInt(hex[k].slice(1), 16);
  return out;
}

/**
 * Merge a biome's palette overrides over a base palette. Pure; never mutates its inputs.
 *
 * `danger` is deliberately NOT overridable: hazards and crash states must read as hazards in every
 * biome and every palette, so a biome that recoloured them would make danger look safe. That is the
 * one cosmetic mistake that changes how the game plays.
 * @param {Object<string,string>} base the active global palette (hex strings)
 * @param {{palettes?:Object<string,Object<string,string>>}|null} biome
 * @param {string} paletteName 'default' | 'colorblind'
 * @returns {Object<string,string>}
 */
export function withBiomePalette(base, biome, paletteName) {
  const out = { ...base };
  const over = biome && biome.palettes && biome.palettes[paletteName];
  if (!over) return out;
  for (const k of Object.keys(over)) {
    if (k === 'danger') continue;
    if (typeof over[k] !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(over[k])) continue;
    out[k] = over[k];
  }
  return out;
}

/**
 * Same palette as CSS strings ('#rrggbb') for Phaser Text styles.
 * @param {Phaser.Game} game
 * @returns {Object<string,string>}
 */
export function getPaletteCss(game, biome) {
  const content = game.registry.get(REG.CONTENT);
  const settings = game.registry.get(REG.SETTINGS);
  const name = (settings && settings.palette) || 'default';
  const base = content.palettes[name] || content.palettes.default;
  return withBiomePalette(base, biome, name);
}/**
 * OWNER: UI engineer.
 * Neon-bordered panel with optional title tab. Repaints on palette change.
 *
 * Look (synthwave cabinet): a dark glass fill with a faint top sheen, a double neon border whose outer
 * strokes fall off in alpha to fake a soft glow (pixel-exact rects, no blur shader, so it stays crisp under
 * pixelArt and costs nothing), an angled title tab, and corner brackets that breathe outwards by a pixel.
 *
 * Geometry contract (layout code and tests rely on it): the container's (x, y) is the panel's top-left, the
 * body is exactly w x h, the title text sits at (8, 4) and content starts below y 16. The glow strokes paint
 * up to 2 px OUTSIDE the box; nothing else does.
 */
import Phaser from 'phaser';
import { NeonText, strokeRectPx, cornerTicks, glowRectPx } from './Neon.js';
import { measureText } from './PixelFont.js';
import { isReducedMotion, onTick } from './Motion.js';

/** Height of the title tab (the old title bar's height, so title-relative content does not move). */
const TAB_H = 15;
/** Horizontal run of the tab's slanted right edge. */
const TAB_SLANT = 10;

export class Panel extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{x:number, y:number, w:number, h:number, color?:string, title?:string, fillAlpha?:number, parent?:Phaser.GameObjects.Container}} o
   */
  constructor(scene, theme, o) {
    super(scene, o.x, o.y);
    this.theme = theme;
    this.w = o.w;
    this.h = o.h;
    this.colorKey = o.color || 'cyan';
    this.fillAlpha = o.fillAlpha === undefined ? 0.92 : o.fillAlpha;
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    // Corner brackets live on their own Graphics so the per-frame breathing never repaints the frame.
    this.fx = new Phaser.GameObjects.Graphics(scene);
    this.add(this.fx);
    this.titleText = null;
    this.hasTitle = !!o.title;
    if (o.title) {
      this.titleText = new NeonText(scene, theme, 8, 4, o.title, { color: this.colorKey, outline: 'glow' });
      this.add(this.titleText);
    }
    this._breath = -1; // last painted bracket state, so idle frames skip the repaint
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind((pal) => this._paint(pal));
    // Phase offset by position so a screen full of panels does not pulse in lockstep.
    this._phase = ((o.x * 7 + o.y * 13) % 1000) / 1000;
    this._stopTick = onTick(scene, (time) => this._tick(time));
  }

  _paint(pal) {
    const g = this.g;
    const { w, h } = this;
    g.clear();
    const c = pal[this.colorKey];
    const fa = this.fillAlpha;
    // glass: dark body, then a sheen that fades down the top third (bgAlt bands at falling alpha)
    g.fillStyle(pal.bg, fa);
    g.fillRect(0, 0, w, h);
    const sheenH = Math.max(4, Math.round(h * 0.34));
    const bands = 4;
    for (let i = 0; i < bands; i++) {
      g.fillStyle(pal.bgAlt, fa * 0.75 * (1 - i / bands));
      g.fillRect(1, 1 + Math.round((i * sheenH) / bands), w - 2, Math.ceil(sheenH / bands));
    }
    // the glass edge catching light: one faint line under the top border
    g.fillStyle(pal.text, 0.06);
    g.fillRect(2, 2, w - 4, 1);
    // soft outer glow (outside the box), main neon border, inner hairline
    glowRectPx(g, 0, 0, w, h, c);
    strokeRectPx(g, 0, 0, w, h, c, 0.85);
    strokeRectPx(g, 2, 2, w - 4, h - 4, c, 0.16);
    if (this.hasTitle) this._paintTab(g, pal, c);
    if (this.titleText) this.titleText.setColorKey(this.colorKey);
    this._breath = -1;
    this._paintBrackets(0);
  }

  /** Angled title tab: slanted right edge, filled faintly, with a rule across the panel under it. */
  _paintTab(g, pal, c) {
    const tw = Math.min(this.w - TAB_SLANT - 4, (this.titleText ? measureText(this.titleText.main.text) : 0) + 16);
    for (let r = 0; r < TAB_H - 1; r++) {
      // per-row runs give a crisp pixel stair on the slant (a filled triangle would anti-alias)
      const rw = tw + Math.round(TAB_SLANT * (1 - r / (TAB_H - 2)));
      g.fillStyle(c, 0.2);
      g.fillRect(1, 1 + r, rw, 1);
      g.fillStyle(c, 0.9);
      g.fillRect(rw, 1 + r, 1, 1);
    }
    // the rule the old title bar drew, now bright under the tab and dimmer beyond it
    g.fillStyle(c, 0.9);
    g.fillRect(1, TAB_H, tw + 1, 1);
    g.fillStyle(c, 0.4);
    g.fillRect(tw + 2, TAB_H, this.w - tw - 3, 1);
    // three data ticks after the slant: a cabinet-label detail
    for (let i = 0; i < 3; i++) {
      g.fillStyle(c, 0.55 - i * 0.15);
      g.fillRect(tw + TAB_SLANT + 6 + i * 4, 6, 2, 3);
    }
  }

  /**
   * Corner brackets, `out` px outside the frame (0 or 1: the breathing), with a bright pixel at each corner.
   * @param {number} out
   */
  _paintBrackets(out) {
    const pal = this.theme.pal;
    const c = pal[this.colorKey];
    const f = this.fx;
    f.clear();
    const o = 1 + out;
    cornerTicks(f, -o, -o, this.w + o * 2, this.h + o * 2, c, 8, 0.95);
    f.fillStyle(pal.text, 0.9);
    for (const [x, y] of [[-o, -o], [this.w - 1 + o, -o], [-o, this.h - 1 + o], [this.w - 1 + o, this.h - 1 + o]]) f.fillRect(x, y, 1, 1);
  }

  _tick(time) {
    if (!this.scene || !this.visible) return;
    // Reduced motion: brackets hold still (state 0); otherwise a 2.4 s breath, out for the top ~40%.
    const out = isReducedMotion(this.scene) ? 0 : (Math.sin((time / 2400 + this._phase) * Math.PI * 2) > 0.2 ? 1 : 0);
    if (out === this._breath) return;
    this._breath = out;
    this._paintBrackets(out);
  }

  /** @param {string} key @returns {this} */
  setColorKey(key) {
    this.colorKey = key;
    this._paint(this.theme.pal);
    return this;
  }

  /** @param {string} str @returns {this} */
  setTitle(str) {
    if (this.titleText) {
      this.titleText.setText(str);
      this._paint(this.theme.pal); // the tab is sized to the title
    }
    return this;
  }

  destroy(fromScene) {
    if (this._stopTick) this._stopTick();
    this._stopTick = null;
    if (this._unbind) this._unbind();
    this._unbind = null;
    super.destroy(fromScene);
  }
}/**
 * OWNER: UI engineer.
