  '001C224100 0041221C00 2A1C7F1C2A 08083E0808 0080703000 0808080808 0000606000 2010080402 ' +
  '3E5149453E 00427F4000 7249494946 2141494D33 1814127F10 2745454539 3C4A494931 4121110907 ' +
  '3649494936 464949291E 0000240000 0040340000 0008142241 1414141414 0041221408 0201590906 ' +
  '3E415D594E 7C1211127C 7F49494936 3E41414122 7F4141413E 7F49494941 7F09090901 3E41415173 ' +
  '7F0808087F 00417F4100 2040413F01 7F08142241 7F40404040 7F021C027F 7F0408107F 3E4141413E ' +
  '7F09090906 3E4151215E 7F09192946 2649494932 03017F0103 3F4040403F 1F2040201F 3F4038403F ' +
  '6314081463 0304780403 6151494543 00007F4141 0204081020 41417F0000 0402010204 4040404040 ' +
  '0003070800 2054547840 7F28444438 3844444428 384444287F 3854545418 00087E0902 18A4A49C78 ' +
  '7F08040478 00447D4000 2040403D00 7F10284400 00417F4000 7C04780478 7C08040478 3844444438 ' +
  'FC18242418 18242418FC 7C08040408 4854545424 04043F4424 3C4040207C 1C2040201C 3C4030403C ' +
  '4428102844 4C9090907C 4464544C44 0008364100 00007F0000 0041360800 0201020402'
).split(' ');

/** Extra glyphs drawn from row strings (5 wide). Keys are the characters used in game text. */
const EXTRA_GLYPHS = {
  '←': ['00100', '01000', '11111', '01000', '00100'], // left arrow
  '→': ['00100', '00010', '11111', '00010', '00100'], // right arrow
  '↑': ['00100', '01110', '10101', '00100', '00100', '00100', '00100'], // up arrow
  '↓': ['00100', '00100', '00100', '00100', '10101', '01110', '00100'], // down arrow
  '▶': ['10000', '11000', '11100', '11110', '11100', '11000', '10000'], // cursor triangle
  '▲': ['00000', '00000', '00100', '01110', '11111', '00000', '00000'], // up triangle
  '▼': ['00000', '00000', '11111', '01110', '00100', '00000', '00000'], // down triangle
  '■': ['00000', '01110', '01110', '01110', '01110', '01110', '00000'], // square bullet
  '✓': ['00000', '00001', '00010', '10100', '01000', '00000', '00000'], // check mark
};

/** @type {Map<string, number[]>} char -> 5 column bytes */
const GLYPHS = new Map();
ASCII_COLS.forEach((hex, i) => {
  const cols = [];
  for (let c = 0; c < 5; c++) cols.push(parseInt(hex.substr(c * 2, 2), 16));
  GLYPHS.set(String.fromCharCode(32 + i), cols);
});
for (const [ch, rows] of Object.entries(EXTRA_GLYPHS)) {
  const cols = [0, 0, 0, 0, 0];
  rows.forEach((row, r) => {
    for (let c = 0; c < 5; c++) if (row[c] === '1') cols[c] |= 1 << r;
  });
  GLYPHS.set(ch, cols);
}

/** @param {string} ch @returns {{cols:number[], first:number, width:number}} trimmed glyph metrics. */
function metrics(ch) {
  const cols = GLYPHS.get(ch) || GLYPHS.get('?');
  let first = 0;
  let last = 4;
  while (first < 5 && cols[first] === 0) first++;
  while (last >= 0 && cols[last] === 0) last--;
  if (first > last) return { cols, first: 0, width: 0 };
  return { cols, first, width: last - first + 1 };
}

/**
 * Width in font pixels of a single line of text (multiply by the integer scale).
 * @param {string} str
 * @returns {number}
 */
export function measureText(str) {
  let w = 0;
  for (const ch of String(str)) {
    const m = metrics(ch);
    w += (m.width === 0 ? 2 : m.width) + 1;
  }
  return Math.max(0, w - 1);
}

/**
 * Shorten `str` with '..' so it fits `maxPx` (unscaled font px).
 * @param {string} str @param {number} maxPx @returns {string}
 */
export function ellipsize(str, maxPx) {
  str = String(str);
  if (measureText(str) <= maxPx) return str;
  while (str.length > 1 && measureText(str + '..') > maxPx) str = str.slice(0, -1);
  return str + '..';
}

/**
 * Greedy word wrap.
 * @param {string} str @param {number} maxPx unscaled font px @param {number} [maxLines=3]
 * @returns {string} lines joined by newline (last line ellipsized if text did not fit)
 */
export function wrapText(str, maxPx, maxLines = 3) {
  const words = String(str).split(' ');
  const lines = [];
  let cur = '';
  for (const w of words) {
    const next = cur ? `${cur} ${w}` : w;
    if (measureText(next) <= maxPx || !cur) cur = next;
    else {
      lines.push(cur);
      cur = w;
    }
  }
  if (cur) lines.push(cur);
  if (lines.length > maxLines) {
    lines.length = maxLines;
    lines[maxLines - 1] = ellipsize(`${lines[maxLines - 1]} ..`, maxPx);
  }
  return lines.join('\n');
}

/** @returns {string} the characters this font can draw (for upper-casing / filtering). */
export function hasGlyph(ch) {
  return GLYPHS.has(ch);
}

function buildTexture(scene, key, cellW, cellH, pad, dilate) {
  const chars = [...GLYPHS.keys()];
  const perRow = 16;
  const rows = Math.ceil(chars.length / perRow);
  const tex = scene.textures.createCanvas(key, perRow * cellW, rows * cellH);
  const ctx = tex.context;
  ctx.fillStyle = '#ffffff';
  const data = { retroFont: true, font: key, size: 8, lineHeight: FONT_LINE_H, chars: {} };
  const W = perRow * cellW;
  const H = rows * cellH;
  chars.forEach((ch, i) => {
    const cx = (i % perRow) * cellW;
    const cy = Math.floor(i / perRow) * cellH;
    const m = metrics(ch);
    for (let c = 0; c < 5; c++) {
      for (let r = 0; r < 8; r++) {
        if (!(m.cols[c] & (1 << r))) continue;
        const px = cx + pad + (c - m.first);
        const py = cy + pad + r;
        if (dilate) ctx.fillRect(px - 1, py - 1, 3, 3);
        else ctx.fillRect(px, py, 1, 1);
      }
    }
    const gw = m.width;
    const fw = gw + pad * 2 || 1;
    const fh = 8 + pad * 2;
    data.chars[ch.charCodeAt(0)] = {
      x: cx, y: cy, width: fw, height: fh,
      centerX: fw >> 1, centerY: fh >> 1,
      xOffset: -pad, yOffset: -pad,
      xAdvance: (gw === 0 ? 2 : gw) + 1,
      data: {}, kerning: {},
      u0: cx / W, v0: cy / H, u1: (cx + fw) / W, v1: (cy + fh) / H,
    };
  });
  tex.refresh();
  tex.setFilter(1); // NEAREST
  scene.cache.bitmapFont.add(key, { data, texture: key, frame: null });
}

/**
 * Generate the bitmap fonts once per game (idempotent). Call from PreloadScene.
 * @param {Phaser.Scene} scene
 * @returns {void}
 */
export function installFonts(scene) {
  if (scene.textures.exists(FONT_KEY)) return;
  buildTexture(scene, FONT_KEY, 7, 9, 0, false);
  buildTexture(scene, FONT_OUTLINE_KEY, 9, 11, 1, true);
}/**
 * OWNER: UI engineer.
 * Phaser-free layout for the profile UI: the TitleScene level badge and the whole contents of the
 * PROFILE view. `Views.js` and `TitleScene.js` only draw what this returns, so positions, text,
 * palette keys and alphas can be unit-tested (overlap + contrast) in Jest without booting Phaser.
 *
 * Every box is in panel-local / screen-local game pixels (480x270 virtual canvas, 5x7 font: 7 cap
 * rows + 1 descender row). `x`/`y` are the TOP-LEFT corner, `w`/`h` the measured extent, so a
 * renderer can draw with `anchor: 'left'` at (x, y) and a test can intersect the boxes directly.
 */
import { measureText } from './PixelFont.js';
import { loadLevelTable, levelForXp, BASE_BIOME_ID } from '../systems/Progression.js';
import { fmtInt, fmtSec, fmtClock, idToLabel } from './Format.js';
import { equippedTitle } from '../systems/Cosmetics.js';
import { sanitizeBiomeProgress, BIOME_IDS } from '../systems/BiomeDiscovery.js';
import { TITLE_CARD } from './MissionsLayout.js';

/**
 * Decision 3: the tag an UNLOCKED biome's toggle row carries. It replaces the unlock level on that row (the
 * level is already reached, so it told the player nothing). NEW = unlocked, never entered; SEEN = a run
 * entered one of its sectors; DONE = a run rode one of its sectors to the end. Locked biomes keep "LVL n".
 */
export const BIOME_STATE_TAGS = Object.freeze({ unlocked: 'NEW', encountered: 'SEEN', completed: 'DONE' });
const STATE_COLORS = Object.freeze({ unlocked: 'text', encountered: 'cyan', completed: 'lime' });

/**
 * Label and colour of one unlocked biome's toggle row. The widest (SKY JELLYFISH MOUNTAIN SEEN/DONE) is
 * 148 px, inside the ~150 px a two-column toggle band leaves before the ON/OFF value (unit-tested).
 * @param {{name:string, state:string}} row a ProfileStore.biomeToggleRows row
 * @returns {{text:string, color:string}}
 */
export function toggleLabel(row) {
  const r = row && typeof row === 'object' ? row : {};
  const state = BIOME_STATE_TAGS[r.state] ? r.state : 'unlocked';
  return { text: `${String(r.name || r.id || '').toUpperCase()} ${BIOME_STATE_TAGS[state]}`, color: STATE_COLORS[state] };
}

/**
 * PROFILE view panel size. Taller than the leaderboard because it carries 10 stats and 11 signatures.
 *
 * 240, not 224: with all five W3 signatures unlocked the toggle menu runs to local y 205, and the BACK
 * button sits at `h - 22`. At h=224 that is y 202, so the fifth ON/OFF row drew underneath the button.
 * 240 puts the button at 218 and leaves the menu clear by 13px. It still fits the 270px canvas at y=22
 * (bottom 262). The panel's own `items` were always well clear; it was the toggle band, which is
 * returned separately and so is not covered by `overlappingPairs(items)`, that overflowed.
 */
export const PROFILE_PANEL = Object.freeze({ w: 416, h: 240 });

/**
 * Screen position of the Title level badge: the top of the right-hand cabinet card (MissionsLayout.TITLE_CARD),
 * its player section, above BEST and the Daily Patch. Overlap with the logo and the card's other lines is
 * asserted in tests/src/profilelayout.test.js and tests/src/missionslayout.test.js.
 */
export const TITLE_BADGE = Object.freeze({
  x: TITLE_CARD.x + TITLE_CARD.pad,
  y: TITLE_CARD.y + TITLE_CARD.sections.level,
  lineH: TITLE_CARD.sections.title - TITLE_CARD.sections.level,
  /** The badge text column's width: the card's inner width. */
  w: TITLE_CARD.w - TITLE_CARD.pad * 2,
});

const GLYPH_H = 8; // 7 cap rows + the descender row: a conservative box for overlap tests
const PAD = 12;
const RIGHT = PROFILE_PANEL.w - PAD;

/** @returns {string} 'H:MM:SS' over an hour, else 'M:SS'. Lifetime totals get large, so plain m:ss is not enough. */
export function fmtPlaytime(ms) {
  const total = Math.max(0, Math.floor((Number(ms) || 0) / 1000));
  if (total < 3600) return fmtClock(total * 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  return `${h}:${String(m).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
}

/** 'garbage-dump-glacier' -> 'GARBAGE DUMP GLACIER'. Biome ids are kebab-case, ids elsewhere are camelCase. */
function label(id) {
  return idToLabel(String(id || '').replace(/[-_]+/g, ' '));
}

/**
 * Build one text box. Right-aligned text still records its true left edge so overlap tests are exact.
 * @param {string} key
 * @param {string} text
 * @param {number} x left edge (left/center) or right edge (right-aligned)
 * @param {number} y top edge
 * @param {string} color palette key
 * @param {{align?:'left'|'right', alpha?:number, outline?:'dark'|'glow'|'none'}} [o]
 */
function box(key, text, x, y, color, o = {}) {
  const t = String(text === undefined || text === null ? '' : text);
  const align = o.align || 'left';
  const w = measureText(t);
  return {
    key,
    text: t,
    x: align === 'right' ? x - w : x,
    y,
    w,
    h: GLYPH_H,
    align,
    color,
    alpha: o.alpha === undefined ? 1 : o.alpha,
    outline: o.outline || 'none',
  };
}

/**
 * Lifetime stat rows, in reading order. Device-best values come straight from the profile the
 * progression service publishes — this file never re-derives a best from the stored run list.
 * @param {Object} life profile.lifetime
 * @returns {[string,string][]}
 */
export function statRows(life) {
  const l = life && typeof life === 'object' ? life : {};
  const tricks = l.tricks && typeof l.tricks === 'object' ? l.tricks : {};
  const trickTotal = Object.values(tricks).reduce((a, b) => a + (Number(b) || 0), 0);
  return [
    ['RUNS', fmtInt(l.runs)],
    ['TOTAL DISTANCE', `${fmtInt(l.distanceM)} M`],
    ['PLAY TIME', fmtPlaytime(l.playMs)],
    ['BEST SCORE', fmtInt(l.bestScore)],
    ['BEST DISTANCE', `${fmtInt(l.bestDistanceM)} M`],
    ['BEST COMBO', `x${(Number(l.bestCombo) || 0).toFixed(2)}`],
    ['BEST AIR', `${fmtSec(l.maxAirtimeMs)} S`],
    // RUN SHARDS, not DATA SHARDS: lifetime.shards counts shards earned by runs only (mission shards and
    // spending never touch it), so it is neither the spendable balance nor all shards ever earned. The
    // spendable figure is the bank, drawn on the LIFETIME header row.
    ['RUN SHARDS', fmtInt(l.shards)],
    ['NEAR MISSES', fmtInt(l.nearMisses)],
    ['TRICKS', fmtInt(trickTotal)],
  ];
}

/**
 * Layout of the PROFILE view. Defensive: a missing/partial profile renders as a level 1 pilot with
 * zeroes rather than throwing, because a view can be opened before the first run ever credits.
 * @param {{profile?:Object, levels?:*}} o `levels` is the parsed levels.json (content.progression)
 * @returns {{w:number,h:number,items:Object[],bar:{x:number,y:number,w:number,h:number,ratio:number,color:string}}}
 */
export function profileLayout(o = {}) {
  const table = loadLevelTable(o.levels);
  const p = o.profile && typeof o.profile === 'object' ? o.profile : {};
  const life = p.lifetime && typeof p.lifetime === 'object' ? p.lifetime : {};
  const xp = Number(p.xp) || 0;
  // Derive the level from XP (the same rule ProfileStore applies on every load), so a stale or
  // hand-edited `level` field can never make the badge disagree with the XP figure beside it.
  const level = levelForXp(xp, table);
  const entry = table.levels.find((e) => e.level === level) || { xpMin: 0, title: '' };
  const next = table.levels.find((e) => e.level === level + 1) || null;
  const span = next ? next.xpMin - entry.xpMin : 0;
  const ratio = next && span > 0 ? Math.min(1, Math.max(0, (xp - entry.xpMin) / span)) : 1;

  const items = [];
  // Sync Level row: level + the title earned at that level.
  items.push(box('level', `SYNC LEVEL ${level}`, PAD, 24, 'lime'));
  // SHOP-2: an equipped title replaces the level title; DEFAULT shows the level title.
  items.push(box('title', equippedTitle(p) || String(entry.title || '').toUpperCase(), RIGHT, 24, 'text', { align: 'right', alpha: 0.85 }));
  // XP row: figure, Resonance bar, and what is left to the next level.
  items.push(box('xp', `XP ${fmtInt(xp)}`, PAD, 36, 'amber'));
  const bar = { x: 96, y: 36, w: 190, h: 7, ratio, color: ratio >= 1 ? 'amber' : 'lime' };
  if (next) items.push(box('tonext', `${fmtInt(Math.max(0, next.xpMin - xp))} TO L${level + 1}`, RIGHT, 36, 'text', { align: 'right', alpha: 0.85 }));
  else items.push(box('tonext', 'MAX SYNC', RIGHT, 36, 'amber', { align: 'right' }));

  // Lifetime block: two columns of five, so ten numbers fit without shrinking the font.
  items.push(box('lifetime-head', 'LIFETIME', PAD, 54, 'amber'));
  // The spendable balance is the shard figure a player acts on, so it is the primary one on this screen.
  items.push(box('bank', `BANK ${fmtInt(Math.max(0, Number(p.bank) || 0))}`, RIGHT, 54, 'amber', { align: 'right' }));
  const rows = statRows(life);
  rows.forEach(([k, v], i) => {
    const col = i < 5 ? 0 : 1;
    const labelX = col === 0 ? PAD : 208;
    const valueRight = col === 0 ? 186 : RIGHT;
    const y = 66 + (i % 5) * 12;
    items.push(box(`stat-k${i}`, k, labelX, y, 'text', { alpha: 0.7 }));
    items.push(box(`stat-v${i}`, v, valueRight, y, 'cyan', { align: 'right' }));
  });

  // Biomes: W3 ships the first five signatures, so the W1 "SIGNATURE LOCKED - COMING ONLINE" note is
  // no longer true for them. It now states how many reached biomes have a playable signature vs how
  // many are still pending W6, which stays honest as W6 adds the rest.
  // Hyphen, not an em dash: the 5x7 font has no U+2014 and would draw '?'. 
  const order = Array.isArray(table.biomeOrder) ? table.biomeOrder : [];
  // The base biome is unlocked from the first run (issue #65), whatever the profile's list says.
  const reached = new Set([BASE_BIOME_ID, ...(Array.isArray(p.pendingBiomes) ? p.pendingBiomes : [])]);
  const reachedCount = order.filter((id) => reached.has(id)).length;
  const sigIds = new Set(Array.isArray(o.playableBiomeIds) ? o.playableBiomeIds : []);
  const sigCount = order.filter((id) => reached.has(id) && sigIds.has(id)).length;
  // The base biome is online but has no ON/OFF toggle (it cannot be turned off), so it is a plain name row.
  const isToggle = (id) => id !== BASE_BIOME_ID && reached.has(id) && sigIds.has(id);
  const toggleCount = order.filter(isToggle).length;
  // SIGNATURES UNLOCKED, not BIOMES REACHED: the count is biomes unlocked by Sync Level (pendingBiomes),
  // which a player has with zero runs played, so "reached" claimed something that never happened.
  items.push(box('sig-head', `SIGNATURES UNLOCKED ${reachedCount}/${order.length}`, PAD, 132, 'magenta'));
  const note = sigIds.size === 0
    ? 'SIGNATURE LOCKED - COMING ONLINE'
    : `${sigCount} SIGNATURE${sigCount === 1 ? '' : 'S'} ONLINE`;
  items.push(box('sig-note', note, RIGHT, 132, 'text', { align: 'right', alpha: 0.7 }));
  // Signature names sit ABOVE the toggle menu, not behind it. Luna's round-2 finding: the menu was
  // drawn at y=150 in Views.js while the names ran from y=146, so the ON/OFF rows covered the names.
  // The geometry lives here now so overlap stays unit-tested instead of depending on two files agreeing.
  // Name pitch is 10, not 11: the shipped table has ELEVEN biomes (4 rows) and the toggle menu has to
  // fit under them inside a 224px panel. At pitch 11 with an 11px menu the deepest row ran to y=242.
    // NAME_TOP must clear the header row (y=132 + GLYPH_H 8) — starting at 138 overlapped it. Pitch 9 is
  // the tightest that satisfies the GLYPH_H+1 rule in MissionsLayout, and it is what lets four name rows
  // plus five toggle rows fit in a 224px panel.
  const NAME_TOP = 141;
  const NAME_PITCH = 9;
  // Every signature WITHOUT a toggle row gets a plain name row: a toggle exists only for a biome that is
  // both unlocked and playable. An unlocked biome already appears in the toggle menu below, labelled with
  // its unlock level, so listing it twice was pure duplication. This used to list only the not-playable
  // ones, and production passes every shipped id as playable, so LOCKED biomes vanished from the screen
  // (audit F11): a new player could not see what was coming.
  // Two columns (x 12 and 208, the LIFETIME columns), not three: a locked name carries a "LVL n" tag, and
  // "SKY JELLYFISH MOUNTAIN LVL 25" does not fit a 134px third of the panel.
  const NAME_COLS = 2;
  const NAME_COL_X = [PAD, 208];
  const levelOf = (id) => {
    const e = table.levels.find((l) => l.biome === id);
    return e ? e.level : null;
  };
  const prog = sanitizeBiomeProgress(p.biomeProgress);
  const namedOnly = order.filter((id) => !isToggle(id));
  namedOnly.forEach((id, i) => {
    const x = NAME_COL_X[i % NAME_COLS];
    const y = NAME_TOP + Math.floor(i / NAME_COLS) * NAME_PITCH;
    const has = reached.has(id);
    // 0.55 alpha keeps even the unreached names above the 4.5:1 contrast floor in both palettes.
    const name = box(`sig-${id}`, label(id), x, y, has ? 'amber' : 'text', { alpha: has ? 1 : 0.55 });
    items.push(name);
    // A locked signature says when it unlocks, in the shop's own "LVL n" wording.
    const lv = levelOf(id);
    let right = name;
    if (!has && lv) {
      right = box(`lock-${id}`, `LVL ${lv}`, name.x + name.w + 6, y, 'text', { alpha: 0.55 });
      items.push(right);
    }
    // Decision 3: a biome can be entered before it is unlocked (a Daily plays the date's mask), so a plain
    // name row also says SEEN / DONE when that happened. Its own box: the name and LVL texts stay exact.
    const st = prog.completed.includes(id) ? 'completed' : prog.encountered.includes(id) ? 'encountered' : null;
    if (st) items.push(box(`state-${id}`, BIOME_STATE_TAGS[st], right.x + right.w + 6, y, STATE_COLORS[st]));
  });

  // The toggle menu's band: below the last name row, sized so the deepest row still clears the panel
  // floor. Five signatures is the worst case; a sixth would push past h, which is why the height is
  // computed from `order` rather than hardcoded.
  const nameRows = Math.max(1, Math.ceil(namedOnly.length / NAME_COLS));
  const lastNameBottom = namedOnly.length
    ? NAME_TOP + (nameRows - 1) * NAME_PITCH + GLYPH_H
    : NAME_TOP - NAME_PITCH + GLYPH_H; // no plain rows: sit directly under the header
  // W6: eleven signatures cannot stack in one column. At 9px pitch, 11 rows from y 142 reach 241 while
  // BACK starts at 218, so the last three would be covered by a button the player cannot see through —
  // the exact defect W3's audit already caught once. Split into two columns instead of shrinking the pitch:
  // 6 rows per column at 9px is 54px, clearing BACK by 22px, and the font stays legible.
  // Balanced columns (ceil(n/2) rows each, at most 6) rather than always filling 6 before wrapping: now that
  // locked names are listed above the menu, 6-7 unlocked signatures under two name rows would otherwise
  // reach the ACHIEVEMENTS line at y 206. Balanced, names plus toggles never exceed six rows in total.
  const TOGGLE_MAX_ROWS = 6;
  const TOGGLE_COLS = order.length > TOGGLE_MAX_ROWS ? 2 : 1;
  const TOGGLE_ROWS_PER_COL = Math.max(1, Math.min(TOGGLE_MAX_ROWS, Math.ceil(toggleCount / TOGGLE_COLS)));
  const toggleMenu = {
    x: PAD + 2,
    y: lastNameBottom + 2,
    w: PROFILE_PANEL.w - (PAD * 2) - 4,
    // 9 not 11: the rows must clear the panel floor beneath the signature names. GLYPH_H is 8, so
    // 9 still leaves a clear row gap.
    rowH: 9,
    columns: TOGGLE_COLS,
    rowsPerColumn: TOGGLE_ROWS_PER_COL,
  };

  // Two buttons want the strip beside BACK, and both belong on this screen:
  //   * W5's ACHIEVEMENTS entry — the spec puts the grid in Profile, and Title has no seventh row;
  //   * W4's SHARD SHOP — Title's band fits six 2x rows (y92..196, daily strip at 202) and the shop was
  //     the seventh, the overflow CC Friday caught with SETTINGS.
  // BACK is right-aligned at x w-76, so both fit left of it: 96 + 8 + 96 = 200px, well inside 416.
  const achUnlocked = Object.keys(p.achievements && typeof p.achievements === 'object' ? p.achievements : {}).length;
  const achTotal = Number(o.achievementTotal) > 0 ? Number(o.achievementTotal) : 0;
  items.push(box('ach-summary',
    achTotal ? `ACHIEVEMENTS ${achUnlocked}/${achTotal}` : `ACHIEVEMENTS ${achUnlocked}`,
    PAD, PROFILE_PANEL.h - 34, 'amber', { alpha: 0.9 }));
  // Decision 3: how many biomes this pilot has actually entered and ridden through, on the same line as the
  // achievements count (right-aligned; the toggle band always ends above this line).
  const biomeTotal = order.length || BIOME_IDS.length;
  items.push(box('biome-progress', `BIOMES SEEN ${prog.encountered.length}/${biomeTotal} DONE ${prog.completed.length}/${biomeTotal}`,
    RIGHT, PROFILE_PANEL.h - 34, 'cyan', { align: 'right', alpha: 0.9 }));
  const BTN_Y = PROFILE_PANEL.h - 22;
  const achButton = { x: PAD, y: BTN_Y, w: 96, h: 16 };
  const shopButton = { x: PAD + 96 + 8, y: BTN_Y, w: 96, h: 16 };
  // SHOP-2: TITLES opens the title picker. Third in the strip (x 220..316), still clear of BACK at x 340.
  const titlesButton = { x: PAD + (96 + 8) * 2, y: BTN_Y, w: 96, h: 16 };

  // Physical rows the menu occupies: with two columns that is the taller column, not the row count, which
  // is what the overlap test has to measure.
  const togglePhysicalRows = toggleCount ? TOGGLE_ROWS_PER_COL : 0;
  return {
    w: PROFILE_PANEL.w, h: PROFILE_PANEL.h, items, bar, toggleMenu,
    toggleRowCount: toggleCount, togglePhysicalRows, achButton, achUnlocked, achTotal, shopButton, titlesButton,
  };
}

/**
 * Title-screen level badge. Two short lines in the top-left corner, left of the logo: the subtitle
 * sits at y 76-83 and the menu panel starts at y 92, so a centred badge there would collide with both.
 * `outline: 'dark'` because the badge sits on the animated backdrop, not on a flat panel.
 * @param {{profile?:Object, levels?:*}} o
 * @returns {{level:number, items:Object[]}|null} null = nothing to draw (no profile yet)
 */
export function titleBadgeLayout(o = {}) {
  const p = o.profile;
  if (!p || typeof p !== 'object') return null;
  const table = loadLevelTable(o.levels);
  const level = levelForXp(Number(p.xp) || 0, table);
  const entry = table.levels.find((e) => e.level === level) || { title: '' };
  const items = [
    box('badge-level', `SYNC LEVEL ${level}`, TITLE_BADGE.x, TITLE_BADGE.y, 'lime', { outline: 'dark' }),
    // SHOP-2: the equipped title, else the level title.
    box('badge-title', equippedTitle(p) || String(entry.title || '').toUpperCase(), TITLE_BADGE.x, TITLE_BADGE.y + TITLE_BADGE.lineH, 'text', { outline: 'dark', alpha: 0.85 }),
  ];
  return { level, items };
}

/** @param {Object[]} items @returns {Object[]} every overlapping pair, for tests and HUD probes. */
export function overlappingPairs(items) {
  const hits = [];
  for (let i = 0; i < items.length; i++) {
    for (let j = i + 1; j < items.length; j++) {
      const p = items[i];
      const q = items[j];
      const ix = Math.min(p.x + p.w, q.x + q.w) - Math.max(p.x, q.x);
      const iy = Math.min(p.y + p.h, q.y + q.h) - Math.max(p.y, q.y);
      if (ix > 1 && iy > 1) hits.push([p.key, q.key]);
    }
  }
  return hits;
}/** Read-only rider-relative terrain minimap. No gameplay state or collisions. */
import { GAME_WIDTH, GAME_HEIGHT, SCENES } from '../constants.js';
import { rectsHit } from './HudLayout.js';

export const MINIMAP_BOUNDS=Object.freeze({w:104,h:49,left:8,top:80,bottom:178,right:GAME_WIDTH-112});
/** Dwell before a voluntary corner change; a slot that hits the rider moves at once. */
export const MINIMAP_SWITCH_DWELL_MS=600;
/** Alpha while a centre banner / strip paints over the map. */
export const MINIMAP_OCCLUDED_ALPHA=0.28;

export function minimapCorner(riderScreenX,riderScreenY){
  // Owner rule: never obscure the rider when they drift into the bottom-left quadrant.
  return Number.isFinite(riderScreenX)&&Number.isFinite(riderScreenY)&&
    riderScreenX<GAME_WIDTH*0.37&&riderScreenY>GAME_HEIGHT*0.56
    ? 'top-right':'bottom-left';
}
export function minimapPlacement(corner){
  return corner==='top-right'
    ? {x:MINIMAP_BOUNDS.right,y:MINIMAP_BOUNDS.top,w:MINIMAP_BOUNDS.w,h:MINIMAP_BOUNDS.h}
    : {x:MINIMAP_BOUNDS.left,y:MINIMAP_BOUNDS.bottom,w:MINIMAP_BOUNDS.w,h:MINIMAP_BOUNDS.h};
}
/** Screen box the rider occupies (game px), padded so the map never crowds them. */
export function minimapRiderRect(riderScreenX,riderScreenY){
  if(!Number.isFinite(riderScreenX)||!Number.isFinite(riderScreenY))return null;
  return {x:riderScreenX-16,y:riderScreenY-24,w:32,h:34};
}
/**
 * Candidate slots in preference order. Bottom-left first (owner rule), then the
 * same column lifted clear of the touch buttons, then top-right. When the rider
 * is in the bottom-left quadrant the owner rule puts top-right first.
 */
export function minimapCandidates(riderScreenX,riderScreenY,keepOuts=[]){
  const {w,h,left}=MINIMAP_BOUNDS;
  const bl=minimapPlacement('bottom-left'),tr=minimapPlacement('top-right');
  const out=[{corner:'bottom-left',...bl}];
  // Lift above whatever bottom-left keep-out (the left touch cluster, the
  // power-up row) it would touch, but never into the top HUD rows.
  let top=bl.y;
  for(const k of keepOuts)if(rectsHit({x:left,y:bl.y,w,h},k,2))top=Math.min(top,k.y-h-4);
  if(top<bl.y&&top>=MINIMAP_BOUNDS.top+h/2)out.push({corner:'left-raised',x:left,y:Math.round(top),w,h});
  out.push({corner:'top-right',...tr});
  if(minimapCorner(riderScreenX,riderScreenY)==='top-right')out.sort((a,b)=>(b.corner==='top-right')-(a.corner==='top-right'));
  return out;
}
/**
 * Pick the first candidate clear of the rider and every keep-out. If none is
 * fully clear, the rider still wins: the least-covered slot that misses the rider.
 */
export function chooseMinimapSlot(riderScreenX,riderScreenY,keepOuts=[]){
  const rider=minimapRiderRect(riderScreenX,riderScreenY);
  const cands=minimapCandidates(riderScreenX,riderScreenY,keepOuts);
  let best=null,bestHits=Infinity;
  for(const c of cands){
    if(rider&&rectsHit(c,rider,2))continue;
    const hits=keepOuts.filter(k=>rectsHit(c,k,2)).length;
    if(hits===0)return c;
    if(hits<bestHits){best=c;bestHits=hits;}
  }
  return best||cands[0];
}
/** Sample the SAME deterministic terrain as the physical sled, over a small
 * local span. Never display speculative POIs, discovered hazards, or fake map
 * coordinates. Geometry is scaled into a flat 0..1 preview rectangle.
 */
export function minimapTerrainProfile(heightAt,playerX,{behind=150,ahead=550,steps=26}={}){
  if(typeof heightAt!=='function'||!Number.isFinite(playerX))return null;
  const lo=Math.max(0,playerX-behind),hi=Math.max(lo+1,playerX+ahead);
  const points=[];let min=Infinity,max=-Infinity;
  for(let i=0;i<=steps;i++){
    const x=lo+(hi-lo)*i/steps;
    let y=NaN;
    try{y=heightAt(x)}catch{return null;}
    if(!Number.isFinite(y))return null;
    min=Math.min(min,y);max=Math.max(max,y);
    points.push({u:i/steps,y});
  }
  const height=Math.max(44,max-min);
  for(const p of points)p.v=0.18+0.64*(p.y-min)/height;
  return {points,riderU:Math.max(0,Math.min(1,(playerX-lo)/(hi-lo))),minY:min,maxY:max};
}
/** World px of terrain to show ahead: always more than the screen already shows at this zoom. */
export function minimapAheadPx(riderScreenX,zoom){
  const z=Number.isFinite(zoom)&&zoom>0?zoom:1;
  const visible=(GAME_WIDTH-(Number.isFinite(riderScreenX)?riderScreenX:GAME_WIDTH*0.38))/z;
  return Math.round(Math.max(550,Math.min(1400,visible*1.6)));
}

export class RunMinimap {
  constructor(scene){
    this.scene=scene;
    this.g=scene.add.graphics();
    scene.hud.add(this.g);
    this.elapsed=Infinity;
    this.lastCorner=null;
    this.rect=null;
    this._pending=null;
    this._pendingMs=0;
  }
  /** Settle on a slot: move at once off the rider, otherwise only after the new choice holds for the dwell. */
  _settle(choice,rider,dtMs){
    const cur=this.rect;
    if(!cur||(rider&&rectsHit(cur,rider,2))){this._pending=null;return choice;}
    if(choice.corner===this.lastCorner&&choice.y===cur.y){this._pending=null;return choice;}
    if(this._pending?.corner!==choice.corner){this._pending=choice;this._pendingMs=0;return cur;}
    this._pendingMs+=dtMs;
    if(this._pendingMs<MINIMAP_SWITCH_DWELL_MS)return cur;
    this._pending=null;
    return choice;
  }
  /**
   * @param {number} dt
   * @param {{keepOuts?:object[],occluders?:object[]}} [hud] keep-outs (touch buttons,
   *   fixed HUD rows, bottom row) the map must not sit on; occluders (centre banners,
   *   the full-width strip) it dims under instead of pushing them into the playfield.
   */
  update(dt,{keepOuts=[],occluders=[]}={}){
    this.elapsed+=Number.isFinite(dt)?Math.max(0,dt):16.7;
    if(this.rect)this.g.setAlpha(occluders.some(o=>rectsHit(this.rect,o))?MINIMAP_OCCLUDED_ALPHA:1);
    if(this.elapsed<110)return;
    const stepMs=Number.isFinite(this.elapsed)?this.elapsed:110;
    this.elapsed=0;
    let run;
    try{run=this.scene.scene.get(SCENES.RUN);}catch{}
    const sled=run?.sled,terrain=run?.terrain,cam=run?.cameras?.main;
    if(!sled||!terrain||!cam||run.crashed){this.g.clear();this.rect=null;return;}
    const sx=(sled.x-cam.scrollX-GAME_WIDTH/2)*cam.zoom+GAME_WIDTH/2;
    const sy=(sled.y-cam.scrollY-GAME_HEIGHT/2)*cam.zoom+GAME_HEIGHT/2;
    const rect=this._settle(chooseMinimapSlot(sx,sy,keepOuts),minimapRiderRect(sx,sy),stepMs);
    this.lastCorner=rect.corner;
    this.rect=rect;
    // Only sample actual terrain: the current game's deterministic world.
    const profile=minimapTerrainProfile(x=>terrain.heightAt(x),sled.x,
      {ahead:minimapAheadPx(sx,cam.zoom),steps:32});
    const g=this.g;g.clear();if(!profile)return;
    const {x,y,w,h}=rect,pad=6;
    g.fillStyle(0x060f1e,.76).fillRoundedRect(x,y,w,h,3);
    g.lineStyle(1,0x2ccde5,.74).strokeRoundedRect(x+.5,y+.5,w-1,h-1,3);
    const chartX=x+pad,chartY=y+7,chartW=w-pad*2,chartH=h-15;
    g.lineStyle(1,0x81bfff,.84);
    let prev=null;
    for(const p of profile.points){
      const next={x:chartX+p.u*chartW,y:chartY+p.v*chartH};
      if(prev)g.lineBetween(prev.x,prev.y,next.x,next.y);
      prev=next;
    }
    const rp=profile.points[Math.max(0,Math.min(profile.points.length-1,
      Math.round(profile.riderU*(profile.points.length-1))))];
    const rx=chartX+profile.riderU*chartW,ry=chartY+rp.v*chartH;
    g.fillStyle(0xffd24b,1).fillCircle(rx,ry-2,2.6);
    g.lineStyle(1,0xffd24b,1).lineBetween(rx,ry-5,rx,ry-10);
    g.lineStyle(1,0x2ccde5,.4).lineBetween(x+w-11,y+h-5,x+w-5,y+h-5);
  }
  destroy(){this.g?.destroy();this.g=null;}
}/**
 * OWNER: UI engineer.
 * Subtle scanline + vignette overlay generated at runtime (no image assets), an optional rolling bright band
 * (the slow refresh "roll" of a CRT, menus only), and a one-time CRT power-on intro.
 */
import { GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
import { isReducedMotion, tweenProgress, Ease, clamp01 } from './Motion.js';

const KEY = 'bb-scanlines';
const BAND_KEY = 'bb-scanband';
const BAND_H = 28;

/** @param {Phaser.Scene} scene @returns {void} create the shared overlay textures once. */
export function installScanlineTexture(scene) {
  if (!scene.textures.exists(KEY)) {
    const tex = scene.textures.createCanvas(KEY, GAME_WIDTH, GAME_HEIGHT);
    const ctx = tex.context;
    const grad = ctx.createRadialGradient(GAME_WIDTH / 2, GAME_HEIGHT / 2, GAME_HEIGHT * 0.45, GAME_WIDTH / 2, GAME_HEIGHT / 2, GAME_WIDTH * 0.62);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.45)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
    ctx.fillStyle = 'rgba(0,0,0,0.16)';
    for (let y = 1; y < GAME_HEIGHT; y += 2) ctx.fillRect(0, y, GAME_WIDTH, 1);
    tex.refresh();
  }
  if (!scene.textures.exists(BAND_KEY)) {
    // A soft white band, brightest in the middle; drawn additively at low alpha it lifts the scanlines it
    // passes over, the way a CRT's refresh roll does.
    const tex = scene.textures.createCanvas(BAND_KEY, GAME_WIDTH, BAND_H);
    const ctx = tex.context;
    if (ctx && typeof ctx.createLinearGradient === 'function') {
      const g = ctx.createLinearGradient(0, 0, 0, BAND_H);
      g.addColorStop(0, 'rgba(255,255,255,0)');
      g.addColorStop(0.5, 'rgba(255,255,255,1)');
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, GAME_WIDTH, BAND_H);
    }
    tex.refresh();
  }
}

/**
 * Add the overlay to a scene (non-interactive, top depth).
 * @param {Phaser.Scene} scene
 * @param {number} [alpha=1]
 * @param {{roll?:boolean}} [o] roll: add the slow rolling bright band (menus; not the gameplay HUD, where a
 *   moving band would read as a visual event). Skipped while reduce motion is on.
 * @returns {Phaser.GameObjects.Image} the scanline image; the band (if any) is `image.band` and is destroyed
 *   with it.
 */
export function addScanlines(scene, alpha = 1, o = {}) {
  installScanlineTexture(scene);
  const img = scene.add.image(0, 0, KEY).setOrigin(0, 0).setDepth(10000).setAlpha(alpha);
  if (o.roll && scene.tweens && typeof scene.tweens.add === 'function') {
    const band = scene.add.image(0, -BAND_H, BAND_KEY).setOrigin(0, 0).setDepth(10000).setAlpha(0.035 * alpha);
    if (typeof band.setBlendMode === 'function') band.setBlendMode(1); // Phaser.BlendModes.ADD
    // One pass every 7 s, then a pause: a constant band would become wallpaper, an occasional one reads as
    // the tube. Read reduced motion on each update so a preference change hides a moving band immediately.
    const tw = scene.tweens.add({
      targets: band,
      y: { from: -BAND_H, to: GAME_HEIGHT },
      duration: 7000,
      repeatDelay: 2500,
      repeat: -1,
      onUpdate: () => band.setVisible(!isReducedMotion(scene)),
      onRepeat: () => band.setVisible(!isReducedMotion(scene)),
    });
    band.setVisible(!isReducedMotion(scene));
    img.band = band;
    if (typeof img.once === 'function') {
      img.once('destroy', () => {
        if (tw && typeof tw.remove === 'function') tw.remove();
        if (band.scene) band.destroy();
      });
    }
  }
  return img;
}

/** Module-level: the power-on plays once per page load, on whichever menu boots first. */
let poweredOn = false;

/**
 * One-time CRT power-on: from black, a bright dot stretches into a horizontal line, the line opens vertically
 * into the picture, with a brief white bloom. Plays only on the first call per page load (later scene starts
 * are not a power-on) and not at all under reduce motion (the scene's normal fade-in covers it).
 * @param {Phaser.Scene} scene
 * @param {{force?:boolean, duration?:number}} [o] force: play even if it already played (tests, debugging)
 * @returns {boolean} true if it plays
 */
export function playCrtPowerOn(scene, o = {}) {
  if (poweredOn && !o.force) return false;
  poweredOn = true;
  if (isReducedMotion(scene) || !scene.add || typeof scene.add.graphics !== 'function') return false;
  const g = scene.add.graphics().setDepth(20001);
  const W = GAME_WIDTH;
  const H = GAME_HEIGHT;
  const cy = Math.round(H / 2);
  const draw = (p) => {
    if (!g.scene) return;
    g.clear();
    if (p >= 1) return;
    // 0..0.3 dot -> line; 0.3..0.75 line opens to full height; 0.75..1 bloom fades
    const lineP = Ease.outCubic(clamp01(p / 0.3));
    const openP = Ease.inOutCubic(clamp01((p - 0.3) / 0.45));
    const bloom = clamp01((p - 0.3) / 0.15) * (1 - clamp01((p - 0.6) / 0.4));
    const lw = Math.max(2, Math.round(W * lineP));
    const oh = Math.round((H / 2) * openP);
    // black covers everything outside the opening picture
    g.fillStyle(0x000000, 1);
    g.fillRect(0, 0, W, Math.max(0, cy - oh));
    g.fillRect(0, cy + Math.max(1, oh), W, H);
    if (oh < 1) {
      g.fillRect(0, cy, Math.round((W - lw) / 2), 1);
      g.fillRect(Math.round((W + lw) / 2), cy, W, 1);
    }
    // the scan line itself, riding the opening edges
    g.fillStyle(0xffffff, 0.9 * (1 - openP * 0.7));
    g.fillRect(Math.round((W - lw) / 2), cy - oh, lw, 1);
    if (oh > 0) g.fillRect(0, cy + oh, W, 1);
    if (bloom > 0) {
      g.fillStyle(0xffffff, 0.25 * bloom);
      g.fillRect(0, cy - oh, W, oh * 2 + 1);
    }
  };
  draw(0);
  tweenProgress(scene, {
    duration: o.duration || 620,
    onUpdate: (_e, raw) => draw(raw),
    onComplete: () => { if (g.scene) g.destroy(); },
  });
  return true;
}/**
 * Score inspector INSIDE the game, over the actual StemMusicDirector lab.
 * Draws unverified MIDI-like SOURCE candidates with a separate
 * visible ORIGINAL OGG PCM waveform (not a post-FX output or gold notes).
 *
 * Any edit is an isolated, exported PATCH, NOT a live music correction.
 * The game's audio, saved profile, settings and base performance.json stay
 * byte-for-byte untouched. Music Lab remains the source of the real clock.
 */
import Phaser from 'phaser';
import { Panel } from './Panel.js';
import { Button } from './Button.js';
import { MenuList } from './MenuList.js';
import { NeonText } from './Neon.js';
import { ellipsize } from './PixelFont.js';
import { ScoreCorrectionDraft } from '../systems/music/ScoreCorrectionDraft.js';
import { nearbyPerformanceEvents } from '../systems/music/PerformanceScore.js';
import { originalStemWaveform } from '../systems/music/SourceStemWaveform.js';

const RATE=48000;
const HALF_WINDOW=2*RATE;
const GRAPH={x:41,y:51,w:409,h:105};
const ROLES=['melody','bass','drums','guitar','piano','other'];
const DRUMS=['kick','snare','hat','tom','cymbal'];
const noteName=n=>['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'][n%12]+
	(Math.floor(n/12)-1);
const ms=x=>Math.round(x/RATE*1000);

export class ScoreInspectorView {
	constructor(scene,theme,{lab,onClose,draft}){
		if(!lab?.score||!lab?.lab?.pack)throw new Error('No verified source score to inspect');
		this.scene=scene;
		this.theme=theme;
		this.labView=lab;
		this.score=lab.score;
		this.draft=draft||new ScoreCorrectionDraft(this.score);
		if(this.draft.scoreHash!==this.score.scoreHash)
			throw new Error('Cannot inspect patches for different source version');
		this.onClose=onClose;
		this.alive=true;
		this.role=ROLES.includes(lab.solo.toLowerCase())?
			lab.solo.toLowerCase():lab.score.featuredStem;
		this.anchorFrame=lab._clockFrame()||0;
		this.follow=true;
		this.comparison=false; // V2 is overlay ONLY, never live audio
		this.reviewIndex=-1;
		this.selectedId=null;
		this.message='TENTATIVE NOTES. NO EDITS ARE APPLIED TO MUSIC.';
		this.windowStart=0;
		this.waveformCoverage=0;
		this.waveformSource=null;
		this._hitBoxes=[];
		this.panel=new Panel(scene,theme,{
			x:6,y:7,w:468,h:253,title:'SCORE INSPECTOR  //  DRAFT ONLY',
			color:'amber',fillAlpha:1,
		}).setDepth(560);
		// Prevent hidden parent Music Lab buttons from handling pointer
		// events in the inspector's blank areas.
		const shield=new Phaser.GameObjects.Zone(scene,0,0,468,253)
			.setOrigin(0,0).setInteractive();
		this.panel.add(shield);

		this.menu=new MenuList(scene,theme,{
			x:10,y:23,w:446,rowH:18,color:'amber',parent:this.panel,
			items:[{kind:'choice',label:'INSTRUMENT ROLE',options:
				ROLES.map(role=>({value:role,label:role.toUpperCase()})),
				get:()=>this.role,set:role=>this.setRole(role)}],
		});

		this.graph=new Phaser.GameObjects.Graphics(scene);
		this.graph.setPosition(GRAPH.x,GRAPH.y);
		this.panel.add(this.graph);
		this.hitArea=new Phaser.GameObjects.Zone(scene,
			GRAPH.x,GRAPH.y,GRAPH.w,GRAPH.h).setOrigin(0,0).setInteractive(
				{useHandCursor:true});
		this.panel.add(this.hitArea);
		this.hitArea.on('pointerdown',(pointer,x,y)=>this.pick(x,y));

		this.windowLabel=new NeonText(scene,theme,10,161,'',{
			color:'cyan',outline:'none',
		});
		this.panel.add(this.windowLabel);
		this.reviewButton=new Button(scene,theme,{
			x:352,y:158,w:99,h:13,label:'NEXT SUSPECT',color:'magenta',
			onClick:()=>this.nextReview(),parent:this.panel,
		}).setDisabled(true);
		this.detailLine=new NeonText(scene,theme,10,172,'',{
			color:'amber',outline:'none',
		});
		this.panel.add(this.detailLine);
		this.helpLine=new NeonText(scene,theme,10,184,'',{
			color:'text',outline:'none',
		});
		this.panel.add(this.helpLine);
		this.messageLine=new NeonText(scene,theme,10,195,'',{
			color:'magenta',outline:'none',
		});
		this.panel.add(this.messageLine);
		const control=(x,y,w,label,fn,color='cyan')=>{
			return new Button(scene,theme,{x,y,w,h:15,label,
				onClick:fn,color,parent:this.panel});
		};
		this.controls={
			prev:control(10,210,57,'< NOTE',()=>this.shift(-1)),
			next:control(71,210,57,'NOTE >',()=>this.shift(1)),
			early:control(132,210,54,'-10MS',()=>this.modify('nudge',-480)),
			late:control(190,210,54,'+10MS',()=>this.modify('nudge',480)),
			down:control(248,210,54,'-OCT',()=>this.modify('octave',-12)),
			up:control(306,210,54,'+OCT',()=>this.modify('octave',12)),
			hear:control(364,210,87,'HEAR STEM',()=>this.hear()),
			reject:control(10,233,66,'REJECT',()=>this.modify('reject'), 'magenta'),
			accept:control(81,233,66,'ACCEPT',()=>this.modify('accept'), 'lime'),
			undo:control(152,233,62,'UNDO',()=>this.modify('undo'), 'amber'),
			export:control(219,233,63,'PATCH',()=>this.exportPatch()),
			compare:control(286,233,41,'V2',()=>this.toggleComparison(),'magenta'),
			follow:control(332,233,53,'FOLLOW',()=>this.toggleFollow()),
		};
		this.back=control(390,231,68,'BACK',()=>this.close(),'magenta');
		this._paletteUnbind=theme.bind(()=>this.refresh());
		this.refresh();
	}

	/** Jump to a machine-DISAGREEMENT passage on the SAME song's real
	 * source game clock. This is not a confirmed bad note or gold label.
	 * It seeks only the lab's sandbox engine, never the main game stream.
	 */
	nextReview(){
		const rows=this.labView?.reviewQueue?.excerpts||[];
		if(!rows.length||!this.labView?.experimentalScore)return false;
		this.reviewIndex=(this.reviewIndex+1)%rows.length;
		const row=rows[this.reviewIndex];
		this.role=row.role;
		this.anchorFrame=Math.min(this.score.frameCount-1,
			row.startFrame+2*RATE);
		this.follow=false;
		this.comparison=true;
		this.selectedId=null;
		this._selectNearest();
		this.menu.refresh();
		this.labView._solo(row.role.toUpperCase());
		this.labView.lab.seekTo(Math.max(0,row.startFrame/RATE-.2));
		this.message='UNVERIFIED RANK '+row.priorityOrder+
			' '+row.role.toUpperCase()+' BASE '+row.releaseCount+
			' / V2 '+row.candidateCount+'; MATCH '+row.samePitchWithin50ms;
		this.refresh();
		return true;
	}

	setRole(role){
		if(!ROLES.includes(role))return;
		this.role=role;
		this.selectedId=null;
		this._selectNearest();
		this.message='CHANGED ROLE. SOURCE ESTIMATES ARE NOT GOLD NOTES.';
		this.menu?.refresh(); // keep the selected instrument selector in sync
		this.refresh();
	}

	_clock(){
		return this.labView?._clockFrame()??this.anchorFrame;
	}

	_events(){
		return this.score.events[this.role]||[];
	}

	_selectNearest(){
		const events=this._events();
		if(!events.length){this.selectedId=null;return;}
		const frame=this.anchorFrame;
		let low=0,high=events.length;
		while(low<high){
			const mid=(low+high)>>1;
			if(events[mid].startFrame<frame)low=mid+1;
			else high=mid;
		}
		const idx=low===0?0:low===events.length?events.length-1:
			Math.abs(events[low].startFrame-frame)<
				Math.abs(events[low-1].startFrame-frame)?low:low-1;
		this.selectedId=events[idx].id;
	}

	_selected(){
		const events=this._events();
		return events.find(event=>event.id===this.selectedId)||null;
	}

	_preview(event){
		return this.draft.preview(event.id)||event;
	}

	/** Move to the previous/next source event (not a guessed beat). */
	shift(direction){
		const events=this._events();
		if(!events.length)return;
		const current=events.findIndex(e=>e.id===this.selectedId);
		const next=(current<0?0:Math.max(0,Math.min(events.length-1,
			current+(direction<0?-1:1))));
		this.selectedId=events[next].id;
		this.anchorFrame=events[next].startFrame;
		this.follow=false;
		this.message='SOURCE EVENT SELECTED; AUDIO NOT CHANGED.';
		this.refresh();
	}

	pick(x,y){
		if(!this._hitBoxes.length)return;
		let best=null,score=Infinity;
		for(const rect of this._hitBoxes){
			// Pointer is local to the rectangle; choose closest note.
			const dx=Math.max(0,rect.x-x,x-(rect.x+rect.w));
			const dy=Math.max(0,rect.y-y,y-(rect.y+rect.h));
			const distance=dx*dx+dy*dy;
			if(distance<score){score=distance;best=rect;}
		}
		if(!best||score>100)return;
		this.selectedId=best.id;
		this.anchorFrame=this.draft.preview(best.id).startFrame;
		this.follow=false;
		this.message='SOURCE EVENT SELECTED; USE +10MS/-10MS OR OCTAVE.';
		this.refresh();
	}

	modify(action,amount=0){
		const event=this._selected();
		if(!event)return;
		if(!this.draft.modify(event.id,action,amount)){
			this.message='INVALID EDIT: FRAME/PITCH LIMIT OR NEIGHBOR ORDER.';
			this.refresh();return;
		}
		this.follow=false;
		this.message=action.toUpperCase()+
			' DRAFT ONLY. EXPORT PATCH TO KEEP THIS CORRECTION.';
		this.refresh();
	}

	hear(){
		const event=this._selected();
		if(!event||!this.labView?.lab?.pack)return;
		const frame=this.draft.preview(event.id).startFrame;
		// A transcription guess is NOT a soloable sound. Listen to its
		// instrument ROLE via the actual game mixer, honoring the current
		// Dynamic Orchestra source/replacement setting. This is not an
		// invented single-note audition or the old standalone lab.
		this.labView._solo(this.role.toUpperCase());
		this.labView.lab.seekTo(Math.max(0,(frame/RATE)-.18));
		this.message='REAL GAME ROLE SOLOED AND SEEKED NEAR THE ATTACK.';
		this.refresh();
	}

	toggleComparison(){
		if(!this.labView?.experimentalScore){
			this.comparison=false;
			this.message=this.labView?.experimentalStatus||
				'UNVERIFIED CANDIDATE NOT AVAILABLE';
		}else{
			this.comparison=!this.comparison;
			this.message=this.comparison?
				'PINK V2 EXPERIMENTAL; CYAN RELEASE. NEITHER IS GOLD.':
				'RELEASE SCORE ONLY. MUSIC IS UNCHANGED.';
		}
		this.refresh();
	}

	toggleFollow(){
		this.follow=!this.follow;
		if(this.follow)this.anchorFrame=this._clock();
		this.message=this.follow?'FOLLOWING LIVE WEB AUDIO CLOCK':
			'VIEW FIXED TO SELECTED CANDIDATES';
		this.refresh();
	}

	exportPatch(){
		const data=this.draft.export();
		if(!data||typeof document==='undefined')return;
		const blob=new Blob([JSON.stringify(data,null,2)+'\n'],
			{type:'application/json'});
		const url=URL.createObjectURL(blob);
		try{
			const link=document.createElement('a');
			link.href=url;
			link.download='bitstream-candidate-fixes-'+this.score.songId+
				'-'+this.score.scoreHash.slice(0,10)+'.json';
			document.body.appendChild(link);
			link.click();
			link.remove();
		}finally{
			setTimeout(()=>URL.revokeObjectURL(url),10000);
		}
		this.message='PATCH EXPORTED. MUSIC AND SAVE ARE STILL UNCHANGED.';
		this.refresh();
	}

	/** Draw only a four-second viewport, even for full 3-minute songs. */
	refresh(){
		if(!this.alive)return;
		if(this.follow)this.anchorFrame=this._clock();
		if(!this._selected())this._selectNearest();
		this.windowStart=Math.max(0,Math.min(
			this.score.frameCount-2*HALF_WINDOW,
			this.anchorFrame-HALF_WINDOW));
		const g=this.graph,pal=this.theme.pal;
		g.clear();
		g.fillStyle(pal.bg,1);
		g.fillRect(0,0,GRAPH.w,GRAPH.h);
		g.lineStyle(1,pal.text,.11);
		for(let i=1;i<4;i++){
			g.lineBetween(i*GRAPH.w/4,0,i*GRAPH.w/4,GRAPH.h);
		}
		// The actual ORIGINAL OGG decode cache, not synthesized MIDI notes:
		// these source PCM peaks follow the same four-second source-frame
		// window as the provisional piano roll and its moving WebAudio playhead.
		// The original recording may be replaced/routed or FX-processed, so
		// NEVER claim this overlay represents final DSP/rendered amplitude.
		const director=this.labView?.lab;
		const sourceRole=this.role==='melody' ?
			director?._activeVoiceFor(director.pack) : this.role;
		const waveform=sourceRole ? originalStemWaveform(
			director?.pack,director?.cache,sourceRole,this.windowStart,
			this.windowStart+2*HALF_WINDOW,204) : null;
		this.waveformSource=sourceRole||null;
		this.waveformCoverage=waveform?.coverage||0;
		if(waveform?.available){
			const h=19,yBottom=GRAPH.h-2;
			g.lineStyle(1,pal.amber,.23);
			g.lineBetween(0,yBottom-h,GRAPH.w,yBottom-h);
			g.fillStyle(pal.amber,.43);
			for(let i=0;i<waveform.bins.length;i++){
				const peak=waveform.bins[i];
				if(peak<=0)continue;
				const x=i/waveform.bins.length*GRAPH.w;
				g.fillRect(x,yBottom-Math.max(1,peak*h),
					Math.ceil(GRAPH.w/waveform.bins.length),Math.max(1,peak*h));
			}
		}
		let events=nearbyPerformanceEvents(this.score,[this.role],
			this.windowStart+HALF_WINDOW,HALF_WINDOW);
		const experimental=this.comparison?this.labView?.experimentalScore:null;
		const candidateEvents=experimental?nearbyPerformanceEvents(experimental,
			[this.role],this.windowStart+HALF_WINDOW,HALF_WINDOW):[];
		// A role's events are original-source hypotheses, not rendered
		// audio transients. The viewed clock is the real game's clock.
		this._hitBoxes=[];
		const pitches=[...events,...candidateEvents]
			.filter(e=>e.event.pitch!==undefined).map(e=>e.event.pitch);
		const sorted=pitches.slice().sort((a,b)=>a-b);
		const median=sorted.length?sorted[Math.floor(sorted.length/2)]:60;
		const minPitch=Math.max(0,Math.min(103,median-11));
		const maxPitch=minPitch+23;
		const roleDrums=this.role==='drums';
		const yFor=e=>{
			if(roleDrums){
				const lane=DRUMS.indexOf(e.class);
				return Math.max(2,Math.min(GRAPH.h-11,
					2+(lane<0?4:lane)*(GRAPH.h-4)/5));
			}
			return 2+(maxPitch-e.pitch)*(GRAPH.h-4)/24;
		};
		if(roleDrums){
			g.lineStyle(1,pal.cyan,.16);
			for(let lane=1;lane<5;lane++){
				g.lineBetween(0,lane*GRAPH.h/5,GRAPH.w,lane*GRAPH.h/5);
			}
		}else{
			g.lineStyle(1,pal.cyan,.08);
			for(let p=minPitch;p<=maxPitch;p+=12){
				const y=2+(maxPitch-p)*(GRAPH.h-4)/24;
				g.lineBetween(0,y,GRAPH.w,y);
			}
		}
		// Purple/pink V2 is drawn behind CYAN release events, but cannot
		// be selected, edited or exported as an approved/gold source.
		// Its notes have NEVER been synthesized into released audio.
		for(const {event} of candidateEvents){
			const x=(event.startFrame-this.windowStart)/
				(2*HALF_WINDOW)*GRAPH.w;
			if(x<0||x>=GRAPH.w)continue;
			const y=yFor(event);
			if(y<0||y>=GRAPH.h-4)continue;
			const width=roleDrums?3:Math.max(3,Math.min(120,
				(event.endFrame-event.startFrame)/
				(2*HALF_WINDOW)*GRAPH.w));
			g.fillStyle(pal.magenta,.38);
			g.fillRect(x,y,width,roleDrums?11:4);
		}
		for(const {event} of events){
			const adjusted=this._preview(event);
			if(adjusted.status==='reject')continue;
			const x=(adjusted.startFrame-this.windowStart)/
				(2*HALF_WINDOW)*GRAPH.w;
			if(x<0||x>=GRAPH.w)continue;
			const y=yFor(adjusted);
			if(y<0||y>=GRAPH.h-4)continue;
			const width=roleDrums?3:Math.max(3,Math.min(120,
				(adjusted.endFrame-adjusted.startFrame)/
				(2*HALF_WINDOW)*GRAPH.w));
			const height=roleDrums?11:4;
			const selected=event.id===this.selectedId;
			const color=selected?pal.amber:
				this.draft.edits.has(event.id)?pal.text:pal.cyan;
			g.fillStyle(color,selected?1:.7);
			g.fillRect(x,y,width,height);
			this._hitBoxes.push({id:event.id,x,y,w:width,h:height});
		}
		const clockX=(this._clock()-this.windowStart)/
			(2*HALF_WINDOW)*GRAPH.w;
		if(clockX>=0&&clockX<=GRAPH.w){
			g.lineStyle(1,pal.lime,.9);
			g.lineBetween(clockX,0,clockX,GRAPH.h);
		}
		g.lineStyle(1,pal.cyan,.5);
		g.strokeRect(.5,.5,GRAPH.w-1,GRAPH.h-1);
		const a=Math.floor(this.windowStart/RATE*10)/10;
		const b=Math.ceil((this.windowStart+2*HALF_WINDOW)/RATE*10)/10;
		this.windowLabel.setText(ellipsize(
			this.role.toUpperCase()+' '+a.toFixed(1)+'-'+b.toFixed(1)+
			'S / '+(roleDrums?'DRUM HITS':'MIDI*')+
			' / OGG '+Math.round(this.waveformCoverage*100)+'%'+
			' / GREEN = LIVE',331));
		const event=this._selected();
		const preview=event&&this._preview(event);
		const desc=preview?(this.role.toUpperCase()+'  '+
			(roleDrums?preview.class.toUpperCase():
				noteName(preview.pitch)+' ('+preview.pitch+')')+
			' @'+(preview.startFrame/RATE).toFixed(3)+'S  '+
			event.id.slice(0,12)+'  '+preview.status.toUpperCase()):
			'NO SOURCE CANDIDATES';
		this.detailLine.setText(ellipsize(desc,446));
		this.helpLine.setText(ellipsize(
			(this.comparison&&experimental?
				'CYAN BASE / PINK V2 / WHITE DRAFT / AMBER RAW OGG':
				'CYAN NOTES / WHITE DRAFT / AMBER RAW OGG')+
			' / GREEN LIVE / NO GOLD NOTES',446));
		// The selected eight-second machine-review record already states
		// the count comparison. Do not append overlapping four-second counts.
		const counts=this.comparison&&experimental&&this.reviewIndex<0?
			'  BASE '+events.length+' / V2 '+candidateEvents.length:'';
		const corrupted=this.labView?.reviewStatus?.startsWith(
			'REVIEW SHORTLIST REJECTED:');
		this.messageLine.setText(ellipsize(
			(corrupted?this.labView.reviewStatus:this.message)+counts+
			'  ('+this.draft.count+' EDITS)',447));
		this.controls.up.setDisabled(!event||roleDrums);
		this.controls.down.setDisabled(!event||roleDrums);
		this.controls.export.setDisabled(!this.draft.count);
		this.reviewButton.setDisabled(!this.labView?.reviewQueue?.excerpts?.length||
			!this.labView?.experimentalScore);
		this.controls.compare.setDisabled(!this.labView?.experimentalScore);
		this.controls.compare.setLabel(this.comparison?'V2 ON':'V2');
		this.controls.follow.setLabel(this.follow?'FREEZE':'FOLLOW');
	}

	handleAction(action){
		if(action==='cancel'){this.close();return true;}
		if(action==='alt'){this.nextReview();return true;}
		if(action==='left'){this.shift(-1);return true;}
		if(action==='right'){this.shift(1);return true;}
		if(action==='up'||action==='down'){
			const index=ROLES.indexOf(this.role);
			this.setRole(ROLES[(index+(action==='up'?-1:1)+ROLES.length)%
				ROLES.length]);
			return true;
		}
		if(action==='confirm'){this.hear();return true;}
		return true;
	}

	close(){
		if(this.alive)this.onClose();
	}

	destroy(){
		if(!this.alive)return;
		this.alive=false;
		this._paletteUnbind?.();
		this.panel.destroy();
		this.panel=null;
	}
}/**
 * W4 shop — the SHOP view's layout, kept Phaser-free so it can be overlap-tested in Jest.
 *
 * Same contract as ProfileLayout: every box is in panel-local game pixels, `x`/`y` is the TOP-LEFT
 * corner and `w`/`h` the measured extent, so a test can intersect boxes directly and a renderer can draw
 * left-anchored without re-applying an origin.
 *
 * ONE LIST, NOT TWO. The first version of this view drew a static layer of headers and item names AND a
 * MenuList of the same rows at a different pitch, so every line was two strings on top of each other (CC
 * Friday's W4 rejection, defect 1). The fix is structural, not cosmetic: this module returns a single
 * ordered list of rows — each either a header (drawn, never selectable) or an interactive row — and the
 * view feeds exactly that list to one MenuList. A header can no longer land on a row's y, because nothing
 * is positioned independently any more.
 *
 * Defect 2 was the same root cause from the other side: the static layer could never be refreshed, so
 * after a purchase the bank line still read the old balance. Now every visible string is a row in one
 * list, so rebuilding after a purchase redraws all of it.
 */
import { measureText } from './PixelFont.js';
import { UPGRADE_CATALOG, sanitizeUpgradeRanks, nextUpgradePrice } from '../systems/PermanentUpgrades.js';
import { BSOD_GYM_PRICE, gymVisible, gymOwned, gymAdvanced, gymSetupForProfile, GYM_SETUP_OPTIONS } from '../systems/BsodGym.js';
import { SHOP_ITEMS, isOwned } from '../systems/ProfileStore.js';
import { loadLevelTable, levelForXp } from '../systems/Progression.js';

/** Shop panel: wide enough for "NAME .......... 120" with the price right-aligned. */
export const SHOP_PANEL = Object.freeze({ w: 416, h: 236 });

/**
 * The catalogue is shown one slot per page (audit F4 fit). The flat list was 247 of 248 px tall with nine
 * cosmetic rows; the eleven level rewards would have pushed it off a 270 px screen. Titles are not a page:
 * they are equipped (and Static Rider bought) from the Profile view's TITLES screen.
 */
export const SHOP_PAGES = Object.freeze(['trail', 'glow', 'rider', 'theme']);

const GLYPH_H = 8;
const PAD = 12;
// A glyph is 8 tall, so an 11 px pitch leaves 3 px of clear air between lines. The tallest page is the
// bank line, the page row, six items, a boosts header, two toggles, a loadout header and the loadout line:
// 13 rows, 143 px plus margins, inside the 236 px panel.
const ROW_H = 11;

const BOOSTS = Object.freeze([
  { id: 'errorCorrection', label: 'ERROR CORRECTION' },
  { id: 'headStart', label: 'HEAD START' },
]);

const upper = (s) => String(s === undefined || s === null ? '' : s).toUpperCase();

/**
 * The whole shop as one ordered list of rows.
 *
 * Row shapes:
 *   { kind:'page',   key, label, state, slot, page }  — the page selector ("← TRAIL →", "1/4"); selectable
 *   { kind:'header', key, label }                    — section heading, never selectable
 *   { kind:'item',   key, id, label, state, disabled, owned, equipped, locked, price }
 *   { kind:'boost',  key, id, label, on, locked, unlockLevel, state, disabled }
 *                                                    — a toggle row; locked (not in unlocked.boosts) = disabled
 *   { kind:'static', key, label, color }             — the loadout line, never selectable
 * Every row owns its measured text box in `texts`; that array is what the overlap test intersects.
 *
 * @param {Object} o
 * @param {Object|null} o.profile
 * @param {Object} [o.levels] parsed levels.json (content.progression); only used to name the level that
 *   unlocks a locked boost. Without it a locked boost reads "LOCKED".
 * @param {number} [o.page] index into SHOP_PAGES (default 0); wraps both ways
 * @returns {{w:number,h:number,rows:Array,texts:Array<{key:string,text:string,x:number,y:number,w:number,h:number,color:string}>,
 *            rowH:number, band:{x:number,y:number,w:number}, bankText:string, loadoutText:string, firstSelectable:number,
 *            page:number, pageCount:number, pageSlot:string}}
 */
export function shopLayout(o = {}) {
  const profile = o.profile || {};
  const equipped = (profile.equipped && typeof profile.equipped === 'object') ? profile.equipped : {};
  const boosts = (profile.boosts && typeof profile.boosts === 'object') ? profile.boosts : {};
  const bank = Number.isFinite(profile.bank) ? profile.bank : 0;
  const level = Number.isFinite(profile.level) ? profile.level : 1;
  const grants = (profile.unlocked && typeof profile.unlocked === 'object' && profile.unlocked.boosts
    && typeof profile.unlocked.boosts === 'object') ? profile.unlocked.boosts : {};
  const levelRows = (o.levels && Array.isArray(o.levels.levels)) ? o.levels.levels : [];

  const rows = [];
  const texts = [];

  // Title band. The panel's own Panel object draws the frame title, so this row carries the BANK only —
  // and it is a row like any other, which is what keeps it refreshable.
  const bankText = `BANK ${bank}`;
  rows.push({ kind: 'head', key: 'head', label: '', right: bankText });

  // One slot per page, cheapest first inside it, so like is compared with like.
  const n = SHOP_PAGES.length;
  const rawPage = Number.isFinite(o.page) ? Math.trunc(o.page) : 0;
  const page = ((rawPage % n) + n) % n;
  const pageSlot = SHOP_PAGES[page];
  // The page row doubles as the slot heading: "← TRAIL →" with its position, so a player always knows
  // there is more than one page and where they are in it.
  rows.push({
    kind: 'page', key: 'page', slot: pageSlot, page, label: `← ${upper(pageSlot)} →`, state: `${page + 1}/${n}`,
    disabled: false,
  });
  const sorted = [...SHOP_ITEMS]
    .filter((i) => i && i.slot === pageSlot)
    .sort((a, b) => (a.price - b.price) || ((a.unlockLevel || 1) - (b.unlockLevel || 1)));

  for (const it of sorted) {
    const owned = isOwned(profile, it.id);
    // equip() stores the catalogue's VALUE ('mint'), older profiles may hold the ID; accept both.
    const isEquipped = equipped[it.slot] === it.id || equipped[it.slot] === it.value;
    // A biome grant (the Neon Sled Drone) is locked until its biome is completed, whatever the level, and its
    // locked state names the condition ("COMPLETE MICRO MOUNTAIN") rather than a level it does not have.
    const grantLocked = it.grant === 'biome' && !owned;
    const locked = grantLocked || level < (it.unlockLevel || 1);
    const affordable = bank >= (it.price || 0);

    // State is in the TEXT, not only the colour: colourblind mode and a small screen both have to tell
    // "owned" from "buy" from "locked", and colour alone cannot do that.
    let state;
    if (isEquipped) state = 'EQUIPPED';
    else if (owned) state = 'EQUIP';
    else if (grantLocked) state = upper(it.unlockText || 'LOCKED');
    else if (locked) state = `LVL ${it.unlockLevel}`;
    else state = it.price > 0 ? String(it.price) : 'REWARD';

    // SHOP-3: the EQUIPPED row is selectable, and selecting it returns the slot to DEFAULT (the view calls
    // ProfileStore.unequip). It used to be disabled, so focus skipped it and nothing on screen could ever
    // take a cosmetic back off. A separate DEFAULT row per page would cost a row the tallest page needs.
    rows.push({
      kind: 'item', key: `item-${it.id}`, id: it.id, slot: it.slot, label: upper(it.name), state,
      owned, equipped: isEquipped, locked, affordable, price: it.price,
      disabled: !isEquipped && (locked || (!owned && !affordable)),
    });
  }

  // Boosts are part of the same list because they are part of the same panel. The old view positioned
  // them from an estimate of the catalogue's height, which is exactly how they landed on the TRAIL rows.
  rows.push({ kind: 'header', key: 'hdr-boosts', label: 'BOOSTS' });
  // F3: a boost is offered only once the profile owns it. Ownership is the grant record ProfileStore
  // writes when a level-up crosses the boost's level (`unlocked.boosts[id]`, levels 8 and 15 today); the
  // shop shows that record, it does not re-derive it from the level. A locked boost stays visible, says
  // the level that unlocks it, and cannot be selected.
  for (const b of BOOSTS) {
    const locked = !grants[b.id];
    const entry = levelRows.find((l) => l && l.boost === b.id);
    const unlockLevel = entry && Number.isFinite(entry.level) ? entry.level : null;
    const on = boosts[b.id] === true;
    const state = locked ? (unlockLevel ? `LVL ${unlockLevel}` : 'LOCKED') : (on ? 'ON' : 'OFF');
    rows.push({ kind: 'boost', key: `boost-${b.id}`, id: b.id, label: b.label, on, locked, unlockLevel, state, disabled: locked });
  }

  // Loadout: what the next run will actually look like.
  rows.push({ kind: 'header', key: 'hdr-loadout', label: 'LOADOUT' });
  const loadoutText = ['trail', 'glow', 'rider', 'theme']
    .map((slot) => {
      const v = equipped[slot];
      const shown = (v && v !== 'default') ? upper(String(v).replace(/^[a-z]+-(hue|glow)-/, '')) : 'DEFAULT';
      return `${upper(slot)} ${shown}`;
    })
    .join('  ');
  rows.push({ kind: 'static', key: 'loadout', label: loadoutText, color: 'text' });
  rows.push({ kind: 'upgradeLink', key: 'upgradeLink', label: 'PERMANENT UPGRADES', state: 'OPEN' });

  // Lay the rows out and measure every drawn string. Because y comes from this single loop, a row's text
  // and the menu's own row geometry cannot disagree.
  let y = 8;
  let firstSelectable = -1;
  rows.forEach((r, i) => {
    r.y = y;
    r.index = i;
    if (r.kind === 'head') {
      const bw = measureText(r.right);
      r.texts = [{ key: 'head-right', text: r.right, x: SHOP_PANEL.w - PAD - bw, y, w: bw, h: GLYPH_H, color: 'amber' }];
    } else if (r.kind === 'page') {
      if (firstSelectable < 0) firstSelectable = i;
      const rw = measureText(r.state);
      r.texts = [
        { key: `${r.key}-label`, text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: 'magenta' },
        { key: `${r.key}-right`, text: r.state, x: SHOP_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H, color: 'magenta' },
      ];
    } else if (r.kind === 'upgradeLink') {
      const rw = measureText(r.state);
      r.texts = [
        { key: r.key + '-label', text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: 'lime' },
        { key: r.key + '-right', text: r.state, x: SHOP_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H, color: 'lime' },
      ];
    } else if (r.kind === 'item') {
      if (firstSelectable < 0) firstSelectable = i;
      const right = r.state;
      const rw = measureText(right);
      const labelColor = r.equipped ? 'lime' : (r.locked ? 'text' : 'text');
      r.texts = [
        { key: `${r.key}-label`, text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: labelColor },
        { key: `${r.key}-right`, text: right, x: SHOP_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H,
          color: r.equipped ? 'cyan' : (r.owned ? 'lime' : (r.locked ? 'text' : 'amber')) },
      ];
    } else if (r.kind === 'boost') {
      if (firstSelectable < 0) firstSelectable = i;
      const stateText = r.state;
      const rw = measureText(stateText);
      r.texts = [
        { key: `${r.key}-label`, text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: 'text' },
        { key: `${r.key}-right`, text: stateText, x: SHOP_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H, color: (!r.locked && r.on) ? 'lime' : 'text' },
      ];
    } else {
      r.texts = [{ key: `${r.key}-label`, text: r.label, x: PAD, y, w: measureText(r.label), h: GLYPH_H, color: r.kind === 'header' ? 'magenta' : (r.color || 'text') }];
    }
    for (const t of r.texts) texts.push(t);
    y += ROW_H;
  });

  // Height: last row, plus room for the BACK button the base View pins to the panel floor.
  const contentH = y + 30;
  return {
    w: SHOP_PANEL.w,
    h: Math.max(SHOP_PANEL.h, contentH),
    rows,
    texts,
    rowH: ROW_H,
    band: { x: PAD - 6, y: 8, w: SHOP_PANEL.w - (PAD - 6) * 2 },
    bankText,
    loadoutText,
    firstSelectable,
    page,
    pageCount: n,
    pageSlot,
  };
}

/**
 * Every item row the shop shows, across all of its pages, in page order. For callers that need the whole
 * catalogue as the shop presents it (the shop prompt's "is anything buyable here" agreement, for one).
 * @param {Object} o same options as shopLayout, minus `page`
 * @returns {Array<Object>} the `kind:'item'` rows
 */
export function shopAllRows(o = {}) {
  const out = [];
  for (let page = 0; page < SHOP_PAGES.length; page++) {
    for (const r of shopLayout({ ...o, page }).rows) if (r.kind === 'item') out.push(r);
  }
  return out;
}

/**
 * MenuList items for the shop: the SAME rows in the SAME order. Headers and the loadout line become
 * non-selectable rows so the menu's geometry places them too — the single-geometry rule again.
 *
 * `onSelect` is left null here; the view attaches the buy/equip handler by id, because this module must
 * stay Phaser-free and side-effect-free.
 *
 * @param {Object} layout
 * @returns {Array<Object>}
 */
export function shopMenuItems(layout) {
  return layout.rows.map((r) => {
    if (r.kind === 'page') {
      return { kind: 'action', rowKind: 'page', label: r.label, sub: r.state, page: r.page, disabled: false, onSelect: null };
    }
    if (r.kind === 'upgradeLink') return { kind: 'action', rowKind: 'upgradeLink', label: r.label, sub: r.state, disabled: false };
    if (r.kind === 'item') {
      return { kind: 'action', id: r.id, label: r.label, sub: r.state, rowKind: 'item', disabled: r.disabled, onSelect: null };
    }
    if (r.kind === 'boost') {
      // A locked boost is a disabled row that shows its unlock level instead of an ON/OFF value.
      if (r.locked) {
        return { kind: 'action', id: r.id, label: r.label, rowKind: 'boost', boostId: r.id, sub: r.state, disabled: true, onSelect: null };
      }
      return {
        kind: 'choice', id: r.id, label: r.label, rowKind: 'boost', boostId: r.id, disabled: false,
        options: [{ value: false, label: 'OFF' }, { value: true, label: 'ON' }],
        get: () => r.on, set: null,
      };
    }
    // head / header / static: drawn, never selectable, never focusable.
    return { kind: 'static', label: r.label, rowKind: r.kind, key: r.key, disabled: true };
  });
}

/** Pure page for the permanent-upgrade catalog; shares the shop's single-row geometry. */
export function upgradeShopLayout(o = {}) {
  const profile = o.profile || {};
  const bank = Number.isSafeInteger(profile.bank) ? profile.bank : 0;
  const ranks = sanitizeUpgradeRanks(profile.upgrades);
  const rows = [
    { kind: 'head', key: 'head', label: '', right: 'BANK ' + bank },
    { kind: 'upgradeBack', key: 'upgradeBack', label: '← BACK TO SHOP', state: '' },
    { kind: 'upgradeToggle', key: 'upgradeToggle', label: 'UPGRADE MODE', state: profile.upgradesEnabled === true ? 'ON' : 'OFF' },
    { kind: 'header', key: 'header', label: 'PURCHASE PERMANENT RANKS' },
  ];
  for (const spec of UPGRADE_CATALOG) {
    const rank = ranks[spec.id];
    const price = nextUpgradePrice(spec.id, rank);
    rows.push({ kind: 'upgradeItem', key: 'upgrade-' + spec.id, id: spec.id,
      label: spec.label + ' R' + rank,
      state: price == null ? 'UNAVAILABLE' : '' + price,
      disabled: price == null,
    });
  }
  // The Gym remains entirely absent until the first legitimately scored
  // BSOD escape. Do not reveal how to earn that discovery in store copy.
  if (gymVisible(profile)) {
    const owned = gymOwned(profile);
    rows.push({ kind: 'gym', key: 'bsodGym', id: 'bsodGym',
      label: 'BSOD GYM', state: owned ? 'ENTER' : `LOCKED ${BSOD_GYM_PRICE}`,
      disabled: !owned && bank < BSOD_GYM_PRICE });
    // No disabled / mysterious hint row before the actual in-Gym 5x unlock.
    if (gymAdvanced(profile)) rows.push({ kind: 'gymSetupLink', key: 'bsodGymSetup',
      id: 'bsodGymSetup', label: 'GYM SETUP', state: 'OPEN' });
  }
  rows.push({ kind: 'static', key: 'softcap', label: 'UNLIMITED RANKS / DIMINISHING RETURNS' });
  rows.push({ kind: 'static', key: 'ranked', label: 'MODE ON = MODDED, OFFICIAL DAILY CLEAN' });
  const texts = [];
  let y = 8;
  for (const row of rows) {
    row.y = y;
    if (row.kind === 'head') {
      const w = measureText(row.right);
      row.texts = [{ key: 'head-bank', text: row.right, x: SHOP_PANEL.w - PAD - w, y, w, h: GLYPH_H, color: 'amber' }];
    } else {
      const left = row.kind === 'header' || row.kind === 'static' ? PAD : PAD + 6;
      row.texts = [{ key: row.key + '-label', text: row.label,
        x: left, y, w: measureText(row.label), h: GLYPH_H,
        color: row.kind === 'gym' ? 'cyan' : row.kind === 'upgradeItem' ? 'text' : row.kind === 'upgradeBack' ? 'cyan' : 'magenta' }];
      if (row.state) {
        const w = measureText(row.state);
        row.texts.push({ key: row.key + '-state', text: row.state,
          x: SHOP_PANEL.w - PAD - 6 - w, y, w, h: GLYPH_H, color: 'amber' });
      }
    }
    texts.push(...row.texts);
    y += ROW_H;
  }
  return { w: SHOP_PANEL.w, h: SHOP_PANEL.h, rows, texts, rowH: ROW_H,
    band: { x: PAD - 6, y: 8, w: SHOP_PANEL.w - (PAD - 6) * 2 } };
}

export { ROW_H as SHOP_ROW_H, GLYPH_H as SHOP_GLYPH_H };

// ---- SHOP-2: the TITLES screen (opened from the Profile view) -----------------------------------------

/** TITLES panel: narrower than the shop, one row per title plus the level-title DEFAULT row. */
export const TITLES_PANEL = Object.freeze({ w: 300 });

/**
 * The TITLES screen as one ordered list of rows, the same single-list rule as the shop.
 *
 * Rows: the BANK head; a DEFAULT row that names the level title ("LEVEL: PACKET JOCKEY") and puts the slot
 * back to DEFAULT; then one row per catalogue title. States are spelled out: EQUIPPED, EQUIP, a price,
 * ACHIEVEMENT (an achievement title not earned yet) or LVL n. Selecting EQUIPPED returns to DEFAULT, as
 * in the shop (SHOP-3).
 *
 * @param {{profile?:Object, levels?:Object}} o
 * @returns {{w:number,h:number,rows:Array,texts:Array,rowH:number,band:{x:number,y:number,w:number},bankText:string,firstSelectable:number}}
 */
export function titlesLayout(o = {}) {
  const profile = o.profile || {};
  const equipped = (profile.equipped && typeof profile.equipped === 'object') ? profile.equipped : {};
  const bank = Number.isFinite(profile.bank) ? profile.bank : 0;
  const table = loadLevelTable(o.levels);
  const level = levelForXp(Number(profile.xp) || 0, table);
  const entry = table.levels.find((e) => e.level === level) || { title: '' };
  const rows = [];
  const texts = [];
  const bankText = `BANK ${bank}`;
  rows.push({ kind: 'head', key: 'head', right: bankText });

  const items = SHOP_ITEMS.filter((i) => i && i.slot === 'title');
  const anyEquipped = items.some((it) => equipped.title === it.id || equipped.title === it.value);
  rows.push({
    kind: 'default', key: 'title-default', id: 'default', label: `LEVEL: ${upper(entry.title)}`,
    state: anyEquipped ? 'EQUIP' : 'EQUIPPED', equipped: !anyEquipped, disabled: false,
  });
  for (const it of items) {
    const owned = isOwned(profile, it.id);
    const isEquipped = equipped.title === it.id || equipped.title === it.value;
    const locked = !owned && it.grant !== 'achievement' && level < (it.unlockLevel || 1);
    let state;
    if (isEquipped) state = 'EQUIPPED';
    else if (owned) state = 'EQUIP';
    else if (it.grant === 'achievement') state = 'ACHIEVEMENT';
    else if (locked) state = `LVL ${it.unlockLevel}`;
    else state = String(it.price);
    const buyable = !owned && it.price > 0 && !locked && bank >= it.price;
    rows.push({
      kind: 'item', key: `title-${it.id}`, id: it.id, label: upper(it.name), state, owned, equipped: isEquipped,
      locked, price: it.price, disabled: !isEquipped && !owned && !buyable,
    });
  }

  let y = 8;
  let firstSelectable = -1;
  rows.forEach((r, i) => {
    r.y = y;
    r.index = i;
    if (r.kind === 'head') {
      const bw = measureText(r.right);
      r.texts = [{ key: 'head-right', text: r.right, x: TITLES_PANEL.w - PAD - bw, y, w: bw, h: GLYPH_H, color: 'amber' }];
    } else {
      if (firstSelectable < 0) firstSelectable = i;
      const rw = measureText(r.state);
      r.texts = [
        { key: `${r.key}-label`, text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: r.equipped ? 'lime' : 'text' },
        { key: `${r.key}-right`, text: r.state, x: TITLES_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H,
          color: r.equipped ? 'cyan' : (r.owned ? 'lime' : 'amber') },
      ];
    }
    for (const t of r.texts) texts.push(t);
    y += ROW_H;
  });
  return {
    w: TITLES_PANEL.w,
    h: y + 30,
    rows,
    texts,
    rowH: ROW_H,
    band: { x: PAD - 6, y: 8, w: TITLES_PANEL.w - (PAD - 6) * 2 },
    bankText,
    firstSelectable,
  };
}

/**
 * MenuList items for the TITLES screen: the same rows in the same order. The view attaches onSelect.
 * @param {Object} layout @returns {Array<Object>}
 */
export function titlesMenuItems(layout) {
  return layout.rows.map((r) => {
    if (r.kind === 'head') return { kind: 'static', label: '', rowKind: 'head', disabled: true };
    return { kind: 'action', rowKind: r.kind, id: r.id, label: r.label, sub: r.state, disabled: r.disabled, onSelect: null };
  });
}


/** Only referenced after real five-in-one-flight Gym mastery. No fallback
 * teaser exists in the normal Shop or permanent upgrades page. */
export function gymSetupLayout(o = {}) {
  const profile = o.profile || {};
  const bank = Number.isSafeInteger(profile.bank) ? profile.bank : 0;
  const setup = gymSetupForProfile(profile);
  const fields = [
    {id:'gapPx',label:'WALL GAP'},
    {id:'wallSpeedPxS',label:'WALL START SPEED'},
    {id:'launchHeightPx',label:'LAUNCH HEIGHT'},
    {id:'launchSpeedPxS',label:'START VELOCITY'},
    {id:'launchRisePxS',label:'UPWARD VELOCITY'},
  ];
  const rows = [
    {kind:'head',key:'head',label:'',right:'BANK '+bank},
    {kind:'gymSetupBack',key:'gymSetupBack',label:'← BACK TO UPGRADES'},
    {kind:'header',key:'gymSetupHead',label:'BSOD GYM / CUSTOM LAUNCH'},
    ...fields.map(f=>({kind:'gymSetupChoice',key:f.id,id:f.id,label:f.label,
      state:String(setup[f.id]),choices:GYM_SETUP_OPTIONS[f.id]})),
    {kind:'gymSetupStart',key:'gymSetupStart',label:'START PRACTICE'},
    {kind:'static',key:'gymSetupNote',label:'REAL PHYSICS / FORWARD-ONLY WALL'},
  ];
  return { w:SHOP_PANEL.w,h:SHOP_PANEL.h,rows,rowH:ROW_H,
    band:{x:PAD-6,y:8,w:SHOP_PANEL.w-(PAD-6)*2} };
}/**
 * OWNER: UI engineer.
 * UI sounds through the AudioSynth contract (silent with the stub; never throws).
 */
import { REG } from '../constants.js';

/**
 * @param {Phaser.Scene|Phaser.Game} sceneOrGame
 * @param {'uiMove'|'uiSelect'|'uiBack'|'powerup'|'combo'|'trick'|'landPerfect'|string} name
 * @param {{pitch?:number, volume?:number}} [opts]
 * @returns {void}
 */
export function uiSfx(sceneOrGame, name, opts) {
  try {
    const game = sceneOrGame.game || sceneOrGame;
    const audio = game.registry.get(REG.AUDIO);
    if (audio) audio.playSfx(name, opts);
  } catch (e) {
    /* audio must never break UI */
  }
}/** Isolated in-game Music Lab six-role audition mixer.
 * Pointer + keyboard/gamepad controls. All values exist only in the
 * SoundLabView's ephemeral sandbox director, never persisted to the game.
 */
import Phaser from 'phaser';
import {Panel} from './Panel.js';
import {Button} from './Button.js';
import {NeonText} from './Neon.js';
import {LAB_STEMS,LAB_MIX_PRESETS,labGainFor} from '../systems/music/LabStemMix.js';

export class StemMixerView {
  constructor(scene,theme,{lab,onClose}){
    this.scene=scene;this.theme=theme;this.labView=lab;this.onClose=onClose;
    this.alive=true;this.selected=0;
    this.panel=new Panel(scene,theme,{x:6,y:7,w:468,h:253,
      title:'STEM MIXER // LAB SANDBOX ONLY',color:'cyan',fillAlpha:1})
      .setDepth(560);
    const shield=new Phaser.GameObjects.Zone(scene,0,0,468,253)
      .setOrigin(0,0).setInteractive();
    this.panel.add(shield);
    this.panel.add(new NeonText(scene,theme,12,25,
      '5 INSTRUMENT STEMS + BIOME MELODY / NOTES = PLAYHEAD',
      {color:'cyan',outline:'none'}));
    this.panel.add(new NeonText(scene,theme,12,37,
      'SOLO IS TEMPORARY. BOOST MAY INCREASE MIX LOUDNESS.',
      {color:'text',outline:'none'}).setAlpha(.72));
    this.roleLabels=[];
    this.rows=[];
    for(let i=0;i<LAB_STEMS.length;i++){
      const role=LAB_STEMS[i],y=54+i*25;
      const name=new NeonText(scene,theme,12,y+4,role.toUpperCase(),
        {color:'lime',outline:'none'});
      this.panel.add(name);this.roleLabels.push(name);
      const create=(x,w,label,action,color='cyan')=>new Button(scene,theme,{
        x,y,w,h:18,label,color,parent:this.panel,
        onClick:()=>{this.selected=i;action();this.refresh();},
      });
      const solo=create(87,47,'SOLO',()=>this.toggleSolo(role),'magenta');
      const buttons=LAB_MIX_PRESETS.map((preset,j)=>
        create([139,197,255,320][j],[53,53,60,60][j],
          ['MUTE','DUCK','1.0x','BOOST'][j],
          ()=>this.setLevel(role,preset.gain),
          ['magenta','amber','cyan','lime'][j]));
      const level=new NeonText(scene,theme,386,y+4,'1.00x',
        {color:'amber',outline:'none'});
      this.panel.add(level);
      this.rows.push({solo,buttons,level});
    }
    this.status=new NeonText(scene,theme,12,209,'',
      {color:'cyan',outline:'none'});this.panel.add(this.status);
    this.hint=new NeonText(scene,theme,12,222,
      'UP/DOWN STEM  LEFT/RIGHT LEVEL  CONFIRM SOLO',
      {color:'text',outline:'none'});this.panel.add(this.hint);
    this.reset=new Button(scene,theme,{x:12,y:235,w:135,h:14,
      label:'RESET ALL LEVELS',color:'amber',parent:this.panel,
      onClick:()=>this.resetAll()});
    this.clearSolo=new Button(scene,theme,{x:152,y:235,w:91,h:14,
      label:'CLEAR SOLO',color:'cyan',parent:this.panel,
      onClick:()=>{this.labView._solo('ALL');this.refresh();}});
    this.back=new Button(scene,theme,{x:390,y:233,w:68,h:16,
      label:'BACK',color:'magenta',parent:this.panel,onClick:()=>this.close()});
    this.refresh();
  }

  setLevel(role,gain){
    if(!LAB_STEMS.includes(role)||!LAB_MIX_PRESETS.some(p=>p.gain===gain))return;
    this.labView._setStemLevel(role,gain);
    this.refresh();
  }
  toggleSolo(role){
    if(!LAB_STEMS.includes(role))return;
    this.labView._solo(this.labView.solo===role.toUpperCase()?
      'ALL':role.toUpperCase());
    this.refresh();
  }
  resetAll(){
    this.labView._resetStemMix();
    this.refresh();
  }
  refresh(){
    if(!this.alive)return;
    const lab=this.labView;
    const levels=lab.mixLevels||{};
    for(let i=0;i<LAB_STEMS.length;i++){
      const role=LAB_STEMS[i],row=this.rows[i];
      const own=levels[role]??1;
      const audible=labGainFor(role,levels,lab.solo);
      row.solo.setLabel(lab.solo===role.toUpperCase()?'SOLO*':'SOLO');
      row.level.setText(`${audible.toFixed(2)}x`);
      row.level.setAlpha(audible===0?.43:1);
      this.roleLabels[i].setAlpha(i===this.selected?1:.72);
      for(let j=0;j<row.buttons.length;j++)
        row.buttons[j].setLabel(own===LAB_MIX_PRESETS[j].gain?
          ['MUTE*','DUCK*','1.0x*','BOOST*'][j]:
          ['MUTE','DUCK','1.0x','BOOST'][j]);
    }
    const selected=LAB_STEMS[this.selected];
    this.status.setText(`${selected.toUpperCase()} ${(levels[selected]??1).toFixed(2)}x`+
      `  /  SOLO ${lab.solo}  /  UNSAVED LAB MIX`);
  }
  handleAction(action){
    if(action==='cancel'){this.close();return true;}
    if(action==='up'||action==='down'){
      this.selected=(this.selected+(action==='down'?1:-1)+LAB_STEMS.length)%LAB_STEMS.length;
      this.refresh();return true;
    }
    if(action==='left'||action==='right'){
      const role=LAB_STEMS[this.selected];
      const level=this.labView.mixLevels[role]??1;
      const index=LAB_MIX_PRESETS.findIndex(p=>p.gain===level);
      const next=Math.max(0,Math.min(LAB_MIX_PRESETS.length-1,
        (index<0?2:index)+(action==='left'?-1:1)));
      this.setLevel(role,LAB_MIX_PRESETS[next].gain);return true;
    }
    if(action==='confirm'||action==='alt'){
      this.toggleSolo(LAB_STEMS[this.selected]);return true;
    }
    return true;
  }
  close(){if(this.alive)this.onClose();}
  destroy(){if(!this.alive)return;this.alive=false;this.panel.destroy();this.panel=null;}
}/**
 * OWNER: UI engineer.
 * Per-scene palette binder. Every coloured UI element registers a callback with `bind()`; when the player swaps
 * the colour-blind palette (EVT.SETTINGS_CHANGED) all callbacks are re-run, so the swap is visible live.
 * The listener on game.events is removed on scene shutdown.
 *
 * Audit SHOP-5: the equipped UI theme (profile.equipped.theme) is laid over the palette here, so every
 * menu, panel and HUD painter that reads `pal`/`css`/`color()` is themed. Cosmetics.themedUiPalette owns
 * the rules: only UI accent keys move, `danger` never does, and a colourblind palette refuses the theme.
 * Call refresh() after the profile's theme changes (ShopView does).
 */
import { EVT } from '../events.js';
import { REG, PALETTE_KEYS } from '../constants.js';
import { getPaletteCss } from './Palette.js';
import { themedUiPalette } from '../systems/Cosmetics.js';

/**
 * The active UI palette, themed, as {css, pal}.
 * @param {Phaser.Game} game @returns {{css:Object<string,string>, pal:Object<string,number>}}
 */
export function themedPalette(game) {
  const base = getPaletteCss(game);
  const reg = game.registry;
  const settings = (reg && reg.get(REG.SETTINGS)) || {};
  const profile = (reg && reg.get(REG.PROFILE)) || null;
  const css = themedUiPalette(base, profile, { colorblind: settings.palette === 'colorblind' });
  /** @type {Object<string,number>} */
  const pal = {};
  for (const k of PALETTE_KEYS) pal[k] = parseInt(css[k].slice(1), 16);
  return { css, pal };
}

export class Theme {
  /** @param {Phaser.Scene} scene */
  constructor(scene) {
    this.scene = scene;
    this.game = scene.game;
    const t = themedPalette(this.game);
    /** @type {Object<string,number>} */
    this.pal = t.pal;
    /** @type {Object<string,string>} */
    this.css = t.css;
    /** @type {Set<function(Object<string,number>):void>} */
    this.subs = new Set();
    this._onChange = (p) => {
      if (!p || p.key === 'palette') this.refresh();
    };
    this.game.events.on(EVT.SETTINGS_CHANGED, this._onChange);
    this._destroy = () => this.destroy();
    scene.events.once('shutdown', this._destroy);
    scene.events.once('destroy', this._destroy);
  }

  /**
   * @param {string} key palette key, e.g. 'cyan'
   * @returns {number}
   */
  color(key) {
    return this.pal[key] !== undefined ? this.pal[key] : 0xffffff;
  }

  /**
   * Register a palette-dependent painter; it runs immediately and after each palette change.
   * @param {function(Object<string,number>, Theme):void} fn
   * @returns {function():void} unbind
   */
  bind(fn) {
    this.subs.add(fn);
    fn(this.pal, this);
    return () => this.subs.delete(fn);
  }

  /** Re-read the palette and repaint everything bound. @returns {void} */
  refresh() {
    const t = themedPalette(this.game);
    this.pal = t.pal;
    this.css = t.css;
    for (const fn of [...this.subs]) {
      try {
        fn(this.pal, this);
      } catch (e) {
        this.subs.delete(fn); // painter belongs to a destroyed object
      }
    }
  }

  /** @returns {void} */
  destroy() {
    if (!this.game) return;
    this.game.events.off(EVT.SETTINGS_CHANGED, this._onChange);
    this.scene.events.off('shutdown', this._destroy);
    this.scene.events.off('destroy', this._destroy);
    this.subs.clear();
    this.game = null;
  }
}/**
 * The base View (a centred panel with a BACK button), in its own module so views outside Views.js
 * (GhostFavoritesView) can extend it without importing the whole view catalogue. Views.js re-exports it.
 */
import { GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
import { Panel } from './Panel.js';
import { Keycaps } from './ViewChrome.js';
import { Button } from './Button.js';
import { uiSfx } from './Sound.js';
import { transitionIn, transitionOut } from './Motion.js';
import { measureText } from './PixelFont.js';

/**
 * Base: centred panel with a BACK button.
 *
 * Motion: the panel opens with Motion.transitionIn (a CRT zip: a line draws across, the panel unfolds from
 * it) and closes with Motion.transitionOut (a ghost frame collapses where the panel was). Both collapse to a
 * short fade under reduce motion. The panel's geometry is never animated away from its layout outside the
 * open tween, and destroy() stays synchronous (the ghost is a separate, self-destroying graphic), so view
 * navigation and teardown behave exactly as before for every caller and test. The host scene owns the
 * dim layer behind the panel (Motion.openDim/closeDim).
 */
export class View {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{w:number,h:number,title:string,color?:string,onClose:function():void,y?:number,backLabel?:string,
   *          hints?:Array<{keys?:string[],key?:string,label?:string}>, hintsAt?:'tab'|'foot'}} o
   *   `hints` draws a keycap row: in the title-tab line (right-aligned, the default) or at the panel foot,
   *   left of BACK. A tab-row hint that would run into the title tab is dropped, never overlapped.
   */
  constructor(scene, theme, o) {
    this.scene = scene;
    this.theme = theme;
    this.onClose = o.onClose;
    this.alive = true;
    const x = Math.round((GAME_WIDTH - o.w) / 2);
    const y = o.y !== undefined ? o.y : Math.round((GAME_HEIGHT - o.h) / 2);
    this.frameColorKey = o.color || 'cyan';
    this.panel = new Panel(scene, theme, { x, y, w: o.w, h: o.h, title: o.title, color: this.frameColorKey, fillAlpha: 1 });
    this.panel.setDepth(500);
    this.w = o.w;
    this.h = o.h;
    this.back = new Button(scene, theme, {
      x: o.w - 76, y: o.h - 22, w: 68, h: 16, label: o.backLabel || 'BACK', color: 'magenta', onClick: () => this.close(),
    });
    this.panel.add(this.back);
    this.hintRow = null;
    if (o.hints && o.hints.length) {
      const foot = o.hintsAt === 'foot';
      const caps = new Keycaps(scene, theme, {
        x: foot ? 12 : o.w - 10, y: foot ? o.h - 19 : 2, items: o.hints, align: foot ? 'left' : 'right', color: this.frameColorKey,
      });
      // the tab is the title plus 16 px padding, a 10 px slant and the three data ticks (~26 px)
      const tabEnd = measureText(String(o.title || '')) + 16 + 10 + 26;
      if (!foot && caps.x < tabEnd) caps.destroy();
      else { this.panel.add(caps); this.hintRow = caps; }
    }
    transitionIn(scene, this.panel, { w: o.w, h: o.h, color: theme.color(this.frameColorKey) });
  }

  close() {
    uiSfx(this.scene, 'uiBack');
    if (this.alive) this.onClose();
  }

  handleAction(action) {
    if (action === 'cancel') this.close();
    return true;
  }

  destroy() {
    this.alive = false;
    if (this.panel) {
      // A hidden panel (Settings while Manage Sound is open over it) leaves no ghost: it was not on screen.
      if (this.panel.visible !== false && this.panel.scene) {
        transitionOut(this.scene, {
          x: this.panel.x, y: this.panel.y, w: this.w, h: this.h,
          color: this.theme.color(this.frameColorKey), depth: 501,
        });
      }
      this.panel.destroy();
    }
    this.panel = null;
  }
}/**
 * OWNER: UI engineer.
 * Shared chrome for the modal sub-views (Views.js and friends): keycap hint rows, section dividers, glowing
 * progress bars, focus rings, state chips and the staggered row reveal. Everything paints from palette keys
 * (so the colour-blind palette and equipped UI themes apply) and nothing here changes a view's geometry:
 * helpers draw INTO space a view already owns, or on their own Graphics layered under/over the content.
 *
 * Paint helpers are plain functions over a Graphics so a view can fold them into one repaint; the two
 * widgets (Keycaps, SectionHeader) are Containers that bind to the theme themselves.
 */
import Phaser from 'phaser';
import { NeonText, strokeRectPx, glowRectPx } from './Neon.js';
import { measureText } from './PixelFont.js';
import { isReducedMotion, tweenProgress, Ease } from './Motion.js';

// ------------------------------------------------------------------ pixel patterns

/** 5x6 padlock. */
export const LOCK_GLYPH = Object.freeze(['.XXX.', 'X...X', 'X...X', 'XXXXX', 'XXXXX', 'XXXXX']);
/** 5x5 shard (the currency's diamond). */
export const SHARD_GLYPH = Object.freeze(['..X..', '.XXX.', 'XXXXX', '.XXX.', '..X..']);
/** 5x4 tick. */
export const CHECK_GLYPH = Object.freeze(['....X', 'X..X.', '.XX..', '..X..']);

/**
 * Paint a small bitmap given as rows of 'X' / '.', one fillRect per run.
 * @param {Phaser.GameObjects.Graphics} g @param {number} x @param {number} y
 * @param {readonly string[]} rows @param {number} color @param {number} [alpha=1]
 */
export function paintPattern(g, x, y, rows, color, alpha = 1) {
  g.fillStyle(color, alpha);
  rows.forEach((row, r) => {
    let c = 0;
    while (c < row.length) {
      if (row[c] !== 'X') { c += 1; continue; }
      let e = c;
      while (e < row.length && row[e] === 'X') e += 1;
      g.fillRect(x + c, y + r, e - c, 1);
      c = e;
    }
  });
}

// ------------------------------------------------------------------ podium

/**
 * Palette key for a leaderboard rank (0-based): gold ~ amber, silver ~ text, bronze ~ magenta. Shape carries
 * the rank too (the numbered chip), so the colour-blind palette never has to tell them apart by hue alone.
 * @param {number} i @returns {'amber'|'text'|'magenta'|null} null below the podium
 */
export function podiumKey(i) {
  return i === 0 ? 'amber' : i === 1 ? 'text' : i === 2 ? 'magenta' : null;
}

// ------------------------------------------------------------------ rules, bars, rings, chips

/**
 * A horizontal rule that fades out to the right, with a bright pip at its start: the section divider.
 * @param {Phaser.GameObjects.Graphics} g @param {number} x0 @param {number} x1 @param {number} y
 * @param {number} color @param {number} [alpha=0.7]
 */
export function paintRule(g, x0, x1, y, color, alpha = 0.7) {
  const w = x1 - x0;
  if (w <= 2) return;
  const steps = 8;
  const sw = Math.ceil(w / steps);
  for (let i = 0; i < steps; i++) {
    g.fillStyle(color, alpha * (1 - i / (steps * 1.25)) * 0.8);
    g.fillRect(x0 + i * sw, y, Math.min(sw, x1 - (x0 + i * sw)), 1);
  }
  g.fillStyle(color, 1);
  g.fillRect(x0, y - 1, 2, 3);
}

/**
 * A glowing progress bar: dark well, outer glow, a segmented fill with a bright top half and a hot leading
 * edge, and a crisp border. `ratio` is 0..1.
 * @param {Phaser.GameObjects.Graphics} g @param {Object<string,number>} pal
 * @param {{x:number,y:number,w:number,h:number}} r @param {number} ratio @param {string} colorKey
 * @param {{segments?:number, glow?:number}} [o]
 */
export function paintGlowBar(g, pal, r, ratio, colorKey, o = {}) {
  const c = pal[colorKey];
  const { x, y, w, h } = r;
  const k = Math.min(1, Math.max(0, Number(ratio) || 0));
  glowRectPx(g, x, y, w, h, c, o.glow === undefined ? 0.8 : o.glow);
  g.fillStyle(pal.bg, 1);
  g.fillRect(x, y, w, h);
  const iw = w - 2;
  const fw = Math.round(iw * k);
  if (fw > 0) {
    g.fillStyle(c, 0.6);
    g.fillRect(x + 1, y + 1, fw, h - 2);
    g.fillStyle(c, 1);
    g.fillRect(x + 1, y + 1, fw, Math.max(1, Math.ceil((h - 2) / 2)));
    if (fw > 2) {
      g.fillStyle(pal.text, 0.9);
      g.fillRect(x + fw, y + 1, 1, h - 2);
    }
  }
  const segs = o.segments === undefined ? 10 : o.segments;
  if (segs > 1) {
    g.fillStyle(pal.bg, 0.55);
    for (let i = 1; i < segs; i++) g.fillRect(x + 1 + Math.round((iw * i) / segs), y + 1, 1, h - 2);
  }
  strokeRectPx(g, x, y, w, h, c, 0.9);
}

/**
 * Focus ring for a button/row. The FIRST stroke is the same strokeRect the views always drew (tests and
 * layouts read it); the glow halo and bright corners are extra.
 * @param {Phaser.GameObjects.Graphics} g @param {Object<string,number>} pal
 * @param {{x:number,y:number,w:number,h:number}} r @param {string} colorKey
 */
export function paintFocusRing(g, pal, r, colorKey) {
  const c = pal[colorKey];
  g.lineStyle(1, c, 1);
  g.strokeRect(r.x - 1.5, r.y - 1.5, r.w + 3, r.h + 3);
  strokeRectPx(g, r.x - 4, r.y - 4, r.w + 8, r.h + 8, c, 0.14);
  strokeRectPx(g, r.x - 3, r.y - 3, r.w + 6, r.h + 6, c, 0.3);
  g.fillStyle(pal.text, 0.95);
  for (const [cx, cy] of [[r.x - 2, r.y - 2], [r.x + r.w + 1, r.y - 2], [r.x - 2, r.y + r.h + 1], [r.x + r.w + 1, r.y + r.h + 1]]) g.fillRect(cx, cy, 1, 1);
}

/**
 * A state chip behind a right-aligned state word: 'solid' (filled: equipped / active), 'outline' (owned),
 * 'bright' (can be bought now: outline + faint fill) or 'dim' (locked). `glyph` ('lock' | 'shard') draws a
 * small icon at its left; the chip box grows to the left to make room, and the returned box says where it
 * landed.
 * @param {Phaser.GameObjects.Graphics} g @param {Object<string,number>} pal
 * @param {{right:number, y:number, textW:number, h?:number, colorKey:string, mode:'solid'|'outline'|'bright'|'dim', glyph?:'lock'|'shard'}} o
 * @returns {{x:number,y:number,w:number,h:number}}
 */
export function paintStateChip(g, pal, o) {
  const h = o.h || 9;
  const lockW = o.glyph ? 8 : 0;
  const w = o.textW + 6 + lockW;
  const x = o.right - w;
  const c = pal[o.colorKey];
  const a = o.mode === 'solid' ? 0.9 : o.mode === 'bright' ? 0.9 : o.mode === 'outline' ? 0.55 : 0.3;
  if (o.mode === 'solid') {
    g.fillStyle(c, 0.28);
    g.fillRect(x, o.y, w, h);
  } else if (o.mode === 'bright') {
    g.fillStyle(c, 0.12);
    g.fillRect(x, o.y, w, h);
  }
  // pixel-rounded border: the four corners are left open
  g.fillStyle(c, a);
  g.fillRect(x + 1, o.y, w - 2, 1);
  g.fillRect(x + 1, o.y + h - 1, w - 2, 1);
  g.fillRect(x, o.y + 1, 1, h - 2);
  g.fillRect(x + w - 1, o.y + 1, 1, h - 2);
  if (o.glyph === 'lock') paintPattern(g, x + 3, o.y + 1, LOCK_GLYPH, pal.text, 0.55);
  else if (o.glyph === 'shard') paintPattern(g, x + 3, o.y + 2, SHARD_GLYPH, c, 1);
  return { x, y: o.y, w, h };
}

// ------------------------------------------------------------------ widgets

const CAP_H = 11;

/**
 * A row of keycap hints: `[ENTER] CONFIRM   [← →] [N] SWITCH BOARD`. Each item is {keys:[...]|key, label}.
 * `x` is the left edge, or the right edge with align:'right'. Paint only (no hit zones).
 * `summary` is the plain-text reading of the row (tests, screen readers); `totalW` its pixel width.
 */
export class Keycaps extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,items:Array<{keys?:string[], key?:string, label?:string}>,
   *          align?:'left'|'right', color?:string, parent?:Phaser.GameObjects.Container}} o
   */
  constructor(scene, theme, o) {
    super(scene, 0, o.y);
    this.theme = theme;
    this.colorKey = o.color || 'cyan';
    this.caps = []; // {x,w}
    this.summary = '';
    const GAP_KEY = 2;
    const GAP_LABEL = 4;
    const GAP_ITEM = 9;
    let cx = 0;
    const labels = [];
    const keys = [];
    const items = (o.items || []).filter(Boolean);
    items.forEach((it, n) => {
      const ks = it.keys || (it.key ? [it.key] : []);
      ks.forEach((k, ki) => {
        const w = Math.max(11, measureText(k) + 9);
        this.caps.push({ x: cx, w });
        keys.push({ x: cx + Math.floor((w - measureText(k)) / 2), text: k });
        cx += w + (ki < ks.length - 1 ? GAP_KEY : 0);
      });
      if (it.label) {
        cx += GAP_LABEL;
        labels.push({ x: cx, text: it.label });
        cx += measureText(it.label);
      }
      if (n < items.length - 1) cx += GAP_ITEM;
      this.summary += (n ? '  ' : '') + ks.join(' / ') + (it.label ? ' ' + it.label : '');
    });
    this.totalW = cx;
    this.setX(Math.round(o.align === 'right' ? o.x - cx : o.x));
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    for (const k of keys) this.add(new NeonText(scene, theme, k.x, 2, k.text, { color: 'text', outline: 'none' }));
    for (const l of labels) this.add(new NeonText(scene, theme, l.x, 2, l.text, { color: 'text', outline: 'none', alpha: 0.65 }));
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind((pal) => this._paint(pal));
  }

  _paint(pal) {
    const g = this.g;
    if (!g) return;
    g.clear();
    const c = pal[this.colorKey];
    for (const cap of this.caps) {
      const { x, w } = cap;
      g.fillStyle(pal.bgAlt, 1);
      g.fillRect(x, 0, w, CAP_H - 1);
      g.fillStyle(pal.text, 0.1);
      g.fillRect(x + 1, 1, w - 2, 3);
      // border with open corners, and a heavier bottom edge: the key's lip
      g.fillStyle(c, 0.6);
      g.fillRect(x + 1, 0, w - 2, 1);
      g.fillRect(x, 1, 1, CAP_H - 3);
      g.fillRect(x + w - 1, 1, 1, CAP_H - 3);
      g.fillStyle(c, 1);
      g.fillRect(x + 1, CAP_H - 2, w - 2, 1);
      g.fillStyle(pal.bg, 0.9);
      g.fillRect(x + 1, CAP_H - 1, w - 2, 1);
    }
  }

  destroy(fromScene) {
    if (this._unbind) this._unbind();
    this._unbind = null;
    this.g = null;
    super.destroy(fromScene);
  }
}

/**
 * Section header: label, then a fading rule to `w` (or to `ruleTo`, when something sits at the right).
 */
export class SectionHeader extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,w:number,text:string,color?:string,ruleTo?:number, parent?:Phaser.GameObjects.Container}} o
   */
  constructor(scene, theme, o) {
    super(scene, o.x, o.y);
    this.theme = theme;
    this.colorKey = o.color || 'amber';
    this.w = o.w;
    this.ruleFrom = measureText(o.text) + 6;
    this.ruleTo = o.ruleTo === undefined ? o.w : o.ruleTo;
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    this.label = new NeonText(scene, theme, 0, 0, o.text, { color: this.colorKey, outline: 'none' });
    this.add(this.label);
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind((pal) => {
      if (!this.g) return;
      this.g.clear();
      paintRule(this.g, this.ruleFrom, this.ruleTo, 4, pal[this.colorKey], 0.7);
    });
  }

  destroy(fromScene) {
    if (this._unbind) this._unbind();
    this._unbind = null;
    this.g = null;
    super.destroy(fromScene);
  }
}

// ------------------------------------------------------------------ staggered reveal

const hasTweens = (scene) => !!(scene && scene.tweens && typeof scene.tweens.addCounter === 'function');
const live = (o) => !!(o && o.scene);

/** Where a reveal starts (ms): after the panel's CRT zip has opened. */
export const REVEAL_START = 150;
/** Gap between consecutive rows (ms). */
export const REVEAL_STEP = 24;

/**
 * Fade groups of objects in one after another (alpha 0 -> its current value). Skipped under reduce motion
 * and on scenes with no tween manager, so the end state is always what a test or a reduced-motion player sees.
 * Only use it on objects nothing else re-alphas while the reveal runs.
 * @param {Phaser.Scene} scene @param {Array<Array<Phaser.GameObjects.GameObject>>} groups
 * @param {{start?:number, step?:number, duration?:number}} [o]
 * @returns {void}
 */
export function staggerAlpha(scene, groups, o = {}) {
  if (!hasTweens(scene) || isReducedMotion(scene)) return;
  const start = o.start === undefined ? REVEAL_START : o.start;
  const step = o.step === undefined ? REVEAL_STEP : o.step;
  groups.forEach((objs, i) => {
    const list = (objs || []).filter(live);
    if (!list.length) return;
    const base = list.map((ob) => ob.alpha);
    list.forEach((ob) => ob.setAlpha(0));
    tweenProgress(scene, {
      duration: o.duration || 150,
      delay: start + i * step,
      ease: Ease.outQuad,
      onUpdate: (p) => list.forEach((ob, k) => { if (live(ob)) ob.setAlpha(base[k] * p); }),
    });
  });
}

/**
 * Reveal a MenuList's rows with a short slide-in, top to bottom. Uses visibility and x (never alpha, which
 * MenuList.refresh owns), and restores both exactly at the end of each row's tween.
 * @param {Phaser.Scene} scene @param {{rows?:Array<Object>}} menu
 * @param {{start?:number, step?:number, slide?:number}} [o]
 * @returns {void}
 */
export function staggerMenuRows(scene, menu, o = {}) {
  if (!menu || !menu.rows || !hasTweens(scene) || isReducedMotion(scene)) return;
  const start = o.start === undefined ? REVEAL_START : o.start;
  const step = o.step === undefined ? REVEAL_STEP : o.step;
  const slide = o.slide === undefined ? 8 : o.slide;
  menu.rows.forEach((row, i) => {
    const parts = [row.label, row.value, row.sub, row.badge].filter(live);
    if (!parts.length) return;
    const bx = parts.map((p) => p.x);
    parts.forEach((p) => { p.setVisible(false); p.setX(p.x - slide); });
    let shown = false;
    tweenProgress(scene, {
      duration: 150,
      delay: start + Math.min(i, 14) * step,
      ease: Ease.outCubic,
      onUpdate: (p) => {
        parts.forEach((part, k) => {
          if (!live(part)) return;
          if (!shown) part.setVisible(true);
          part.setX(bx[k] - slide * (1 - p));
        });
        shown = true;
      },
    });
  });
}/**
 * OWNER: UI engineer.
 * Modal sub-screens shared by TitleScene and PauseScene: leaderboard, settings, seed entry, sharecode export/import.
 * A view is a Panel plus content; the host scene feeds it MenuInput actions via handleAction(). Each view calls
 * `onClose()` when the player backs out. destroy() removes everything it created (DOM boxes included).
 */
import Phaser from 'phaser';
import { REG, GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
import { updateSetting } from '../services.js';
import { GAME_SONGS } from '../systems/music/MusicPlaylist.js';
import { Panel } from './Panel.js';
import { NeonText, glowRectPx, strokeRectPx } from './Neon.js';
import { Keycaps, SectionHeader, paintRule, paintGlowBar, paintFocusRing, paintStateChip, paintPattern,
  staggerMenuRows, staggerAlpha, LOCK_GLYPH, SHARD_GLYPH, CHECK_GLYPH } from './ViewChrome.js';
import { Button } from './Button.js';
import { MenuList } from './MenuList.js';
import { LeaderboardTable } from './LeaderboardTable.js';
import { DomTextBox } from './DomTextBox.js';
import { copyText } from './Clipboard.js';
import { uiSfx } from './Sound.js';
import { transitionIn, transitionOut } from './Motion.js';
import { ellipsize, measureText } from './PixelFont.js';
import { profileLayout, toggleLabel } from './ProfileLayout.js';
import { achievementsLayout, clampPage } from './AchievementsLayout.js';
import { visibleAchievements } from '../systems/Achievements.js';
import { shopLayout, upgradeShopLayout, shopMenuItems, titlesLayout, titlesMenuItems, gymSetupLayout } from './ShopLayout.js';
import { toggleBiome, biomeToggleRows, purchase, equip, unequip, isOwned, shopItem } from '../systems/ProfileStore.js';
import { VOCALS_UNLOCK_SHARDS } from '../systems/ProfileStore.js';
import { StemMusicDirector } from '../systems/music/StemMusicDirector.js';
import { ScoreInspectorView } from './ScoreInspectorView.js';
import { StemMixerView } from './StemMixerView.js';
import { HowToPlayView } from './HowToPlayView.js';
import { freshLabLevels,applyLabStemLevels,LAB_STEMS } from '../systems/music/LabStemMix.js';
import {DRAFT_BUDGET,DRAFT_RULES_VERSION,DRAFT_UPGRADES,draftCost,changeDraftRank,sanitizeDraftRanks} from '../systems/DailyDraft.js';
import { BIOME_IDS, HOME_BIOME } from '../systems/music/BiomeVoices.js';
import { resolveMusicAsset } from '../systems/music/MusicPack.js';
import { validateMusicReviewQueue } from '../systems/music/MusicReviewQueue.js';
import { validatePerformanceScore, validateExperimentalPerformanceScore,
  nearbyPerformanceEvents, makeIssueMarker, PERFORMANCE_ROLES } from '../systems/music/PerformanceScore.js';

import { View } from './View.js';
export { View };

/** Top-10 leaderboard from SaveStore. */
export class LeaderboardView extends View {
  /** @param {Phaser.Scene} scene @param {import('./Theme.js').Theme} theme @param {{onClose:function():void}} o */
  constructor(scene, theme, o) {
    // 188, not 178: the board switch needs an on-screen key hint, and the only free line is between the
    // tenth table row (panel y ~146) and the button strip. At y 40 the panel still ends at 228 of 270.
    super(scene, theme, { w: 440, h: 188, title: 'LEDGER // TOP 10 ON THIS DEVICE', color: 'cyan', onClose: o.onClose, y: 40,
      hints: [{ keys: ['← →', 'N', 'PAD X'], label: 'SWITCH BOARD' }] });
    // opt-in: a host that knows the player's latest run can pass its id to light that row up
    this.highlightId = o.highlightId;
    this.table = new LeaderboardTable(scene, theme, { x: 12, y: 24, w: 416, entries: null, parent: this.panel });
    // The footer used to be one 329px line on the button row, so it ran under MODDED and BACK. It is split:
    // the short half stays on the button row (it ends at x 129, MODDED starts at 292) and the rule-flag
    // note moves to the free line above, left of the key hint.
    this.panel.add(new NeonText(scene, theme, 12, this.h - 18, 'ONE LEDGER PER DEVICE.', {
      color: 'text', outline: 'none',
    }).setAlpha(0.55));
    this.panel.add(new NeonText(scene, theme, 12, this.h - 38, 'MAGENTA RULE FLAG = DAILY PATCH ACTIVE.', {
      color: 'text', outline: 'none',
    }).setAlpha(0.55));
    // W4: two boards. The clean board is what the game has always shown; the modded board is where a
    // boosted run goes instead of vanishing. Both come from SaveStore, both decide through Ranking.js, so
    // this view never tests `modded` itself.
    this.store = scene.registry.get(REG.SAVE_STORE);
    this.showingModded = false;
    this.emptyText = null;
    this.loadToken = 0;
    this.tabBtn = new Button(scene, theme, {
      x: this.w - 148, y: this.h - 24, w: 68, h: 16, label: 'MODDED', color: 'amber',
      onClick: () => this._toggleBoard(),
    });
    this.panel.add(this.tabBtn);
    // The switch was pointer-only: no key reached it. The keycap row in the title-tab line (see the super
    // call) names every key that now does.
    // Focus ring for the two buttons (MODDED/CLEAN, BACK). Starts on the tab so confirm switches boards.
    this.focusIdx = 0;
    this.focusG = new Phaser.GameObjects.Graphics(scene);
    this.panel.add(this.focusG);
    this._paintFocus();
    this._loadBoard();
  }

  _loadBoard() {
    const store = this.store;
    this.tabBtn.setLabel(this.showingModded ? 'CLEAN' : 'MODDED');
    if (!store) { this.table.setEntries([]); return; }
    // A request token: a slow read for the board the player has already left must not paint over the
    // board they switched to.
    this.loadToken += 1;
    const token = this.loadToken;
    const modded = this.showingModded;
    const p = modded
      ? Promise.resolve(store.getModdedLeaderboard(10))
      : Promise.resolve(store.getLeaderboard(10));
    p.then((rows) => {
      if (!this.alive || token !== this.loadToken) return;
      // An empty board must say WHICH board is empty and why, or an empty modded board reads as a bug
      // rather than as "no boosted runs yet". The table draws it in place of its generic message.
      const empty = !rows || rows.length === 0;
      this.emptyText = empty ? `NO ${modded ? 'MODDED' : 'CLEAN'} RUNS RECORDED YET` : null;
      this.table.setEntries(rows || [], this.highlightId, empty ? {
        title: this.emptyText,
        sub: modded ? 'RUNS WITH A BOOST ON LAND HERE' : 'FINISH A RUN TO CLAIM A SPOT',
      } : undefined);
    }).catch(() => {
      if (this.alive && token === this.loadToken) this.table.setEntries([]);
    });
  }

  /** @param {boolean} modded which board to show; a no-op when it is already showing. */
  _showBoard(modded) {
    if (this.showingModded === Boolean(modded)) return;
    this._toggleBoard();
  }

  _toggleBoard() {
    this.showingModded = !this.showingModded;
    uiSfx(this.scene, 'uiSelect');
    this._loadBoard();
  }

  _paintFocus() {
    const g = this.focusG;
    if (!g) return;
    g.clear();
    const b = this.focusIdx === 0 ? this.tabBtn : this.back;
    paintFocusRing(g, this.theme.pal, b, this.focusIdx === 0 ? 'amber' : 'magenta');
  }

  /**
   * Left shows CLEAN and right shows MODDED (directional, so a held key cannot flicker between boards);
   * N / pad X-Y ('alt') toggles from anywhere; up/down move focus between the tab and BACK; confirm
   * activates whichever holds focus.
   */
  handleAction(action) {
    if (action === 'cancel') { this.close(); return true; }
    if (action === 'left' || action === 'right') { this._showBoard(action === 'right'); return true; }
    if (action === 'alt') { this._toggleBoard(); return true; }
    if (action === 'up' || action === 'down') {
      const next = action === 'up' ? 0 : 1;
      if (next !== this.focusIdx) {
        this.focusIdx = next;
        this._paintFocus();
        uiSfx(this.scene, 'uiMove');
      }
      return true;
    }
    if (action === 'confirm') {
      if (this.focusIdx === 0) this._toggleBoard();
      else this.close();
      return true;
    }
    return true;
  }
}

/** Rows in the Settings list; the panel height is derived from it (see SettingsView). */
const SETTINGS_ROWS = 16;
/** Row pitch: 14 px up to fourteen rows; 12 px beyond, so sixteen rows still end above the 270 px floor. */
const SETTINGS_ROW_H = SETTINGS_ROWS > 14 ? 12 : 14;

/** Settings: palette, screen shake, volumes, tilt controls (persisted via updateSetting). */
export class SettingsView extends View {
  constructor(scene, theme, o) {
    // Height follows the row count (22 + rows * pitch + 30): sixteen 12 px rows
    // yield 244 px, positioned at y=18 and ending at y=262 in a 270px view.
    const h = 22 + SETTINGS_ROWS * SETTINGS_ROW_H + 30;
    super(scene, theme, { w: 360, h, title: 'SETTINGS',
      color: 'amber', onClose: o.onClose, y: Math.max(8, Math.min(40, 262 - h)), backLabel: 'DONE',
      hints: [{ keys: ['↑', '↓'], label: 'SELECT' }, { keys: ['←', '→'], label: 'CHANGE' }] });
    this.soundView=null;
    this.howView=null;
    const game=scene.game;
    const settings=()=>game.registry.get(REG.SETTINGS)||{};
    const items=[
      { kind:'choice',label:'PALETTE',options:[
        {value:'default',label:'NEON'},{value:'colorblind',label:'COLOR-BLIND'}],
        get:()=>settings().palette,set:v=>updateSetting(game,'palette',v) },
      { kind:'choice',label:'SCREEN SHAKE',options:[
        {value:true,label:'ON'},{value:false,label:'OFF'}],
        get:()=>settings().screenShake!==false,set:v=>updateSetting(game,'screenShake',v) },
      // Next to SCREEN SHAKE: both are motion-comfort switches. AUTO follows the OS reduced-motion setting.
      { kind:'choice',label:'REDUCE MOTION',options:[
        {value:'auto',label:'AUTO'},{value:'on',label:'ON'},{value:'off',label:'OFF'}],
        get:()=>settings().reduceMotion||'auto',set:v=>updateSetting(game,'reduceMotion',v) },
      // Issue #56: the Best and Latest ghosts switch independently (favorites are per course, from Game Over).
      { kind:'choice',label:'GHOSTS',options:[
        {value:'both',label:'BEST+LATEST'},{value:'best',label:'BEST'},{value:'latest',label:'LATEST'},{value:'off',label:'OFF'}],
        get:()=>{const st=settings(),b=st.ghostBest!==false,l=st.ghostLatest!==false;return b&&l?'both':b?'best':l?'latest':'off';},
        set:v=>{updateSetting(game,'ghostBest',v==='both'||v==='best');updateSetting(game,'ghostLatest',v==='both'||v==='latest');} },
      // Issue #47 playtest: Kodiak packs of one type, or mixed types.
      { kind:'choice',label:'KODIAK PACKS',options:[
        {value:'same',label:'SAME TYPE'},{value:'mixed',label:'MIXED'}],
        get:()=>settings().kodiakPacks==='mixed'?'mixed':'same',set:v=>updateSetting(game,'kodiakPacks',v) },
      { kind:'choice',label:'WORLD DANCE',options:[
        {value:true,label:'ON'},{value:false,label:'OFF'}],
        get:()=>settings().worldDance!==false,set:v=>updateSetting(game,'worldDance',v) },
      {kind:'slider',label:'MASTER VOLUME',get:()=>settings().masterVolume,
        set:v=>updateSetting(game,'masterVolume',v)},
      {kind:'slider',label:'MUSIC VOLUME',get:()=>settings().musicVolume,
        set:v=>updateSetting(game,'musicVolume',v)},
      {kind:'slider',label:'SFX VOLUME',get:()=>settings().sfxVolume,
        set:v=>updateSetting(game,'sfxVolume',v)},
      {kind:'slider',label:'SLED WIND',get:()=>settings().windVolume??1,
        set:v=>updateSetting(game,'windVolume',v)},
      {kind:'choice',label:'WIND',options:[
        {value:true,label:'ON'},{value:false,label:'OFF'}],
        get:()=>settings().windEnabled!==false,set:v=>updateSetting(game,'windEnabled',v)},
      {kind:'choice',label:'CONTROLS',options:[
        {value:'tricksRight',label:'TRICKS RIGHT'},{value:'tricksLeft',label:'TRICKS LEFT'},
        {value:'classic',label:'CLASSIC'}],
        get:()=>settings().controlLayout||'tricksRight',set:v=>updateSetting(game,'controlLayout',v)},
      {kind:'action',label:'MANAGE SOUND',color:'cyan',sub:'SONGS / VOCALS / LAB',
        onSelect:()=>this._openSoundManager()},
      // Opens the controls reference as a sibling view over this one (same hand-off as MANAGE SOUND), so
      // neither host scene needs to know about it; closing it returns here.
      {kind:'action',label:'HOW TO PLAY',color:'cyan',sub:'CONTROLS / GAMEPAD / TOUCH',
        onSelect:()=>this._openHowToPlay()},
      {kind:'choice',label:'TILT CONTROLS (90)',options:[
        {value:false,label:'OFF'},{value:true,label:'ON'}],
        get:()=>!!settings().touchRotate90,set:v=>updateSetting(game,'touchRotate90',v)},
      {kind:'choice',label:'TOUCH BUTTONS',options:[
        {value:'auto',label:'AUTO'},{value:'on',label:'ON'},{value:'off',label:'OFF'}],
        get:()=>settings().touchOverlay||'auto',set:v=>updateSetting(game,'touchOverlay',v)},
    ];
    this.menu=new MenuList(scene,theme,{x:10,y:22,w:340,rowH:SETTINGS_ROW_H,
      items,color:'amber',parent:this.panel});
    staggerMenuRows(scene,this.menu);
    this.swatch=scene.add.graphics();
    this.panel.add(this.swatch);
    // what the live palette looks like: four glowing chips and its name, under a divider
    this.swatchLabel=new NeonText(scene,theme,10+4*22+6,this.h-17,'',{color:'text',outline:'none',alpha:0.7});
    this.panel.add(this.swatchLabel);
    this.unbindSwatch=theme.bind(pal=>{
      const g=this.swatch;
      g.clear();
      paintRule(g,10,this.w-10,this.h-27,pal.amber,0.6);
      ['cyan','magenta','lime','amber'].forEach((k,i)=>{
        glowRectPx(g,10+i*22,this.h-20,18,12,pal[k],1);
        g.fillStyle(pal[k],1);g.fillRect(10+i*22,this.h-20,18,12);
        g.fillStyle(pal.bg,1);g.fillRect(12+i*22,this.h-18,14,8);
        g.fillStyle(pal[k],1);g.fillRect(14+i*22,this.h-16,10,4);
      });
      this.swatchLabel.setText(settings().palette==='colorblind'?'COLOR-BLIND PALETTE':'NEON PALETTE');
    });
  }
  _openSoundManager(){
    if(this.soundView)return;
    this.panel.setVisible(false);
    this.soundView=new SoundManagerView(this.scene,this.theme,{
      onClose:()=>{
        this.soundView?.destroy();
        this.soundView=null;
        this.panel.setVisible(true);
      },
    });
  }
  _openHowToPlay(){
    if(this.howView||this.soundView)return;
    this.panel.setVisible(false);
    this.howView=new HowToPlayView(this.scene,this.theme,{
      onClose:()=>{
        this.howView?.destroy();
        this.howView=null;
        this.panel.setVisible(true);
      },
    });
  }
  handleAction(action){
    if(this.howView)return this.howView.handleAction(action);
    if(this.soundView)return this.soundView.handleAction(action);
    if(action==='cancel'){this.close();return true;}
    return this.menu.handleAction(action);
  }
  destroy(){
    this.soundView?.destroy();this.soundView=null;
    this.howView?.destroy();this.howView=null;
    this.unbindSwatch?.();
    super.destroy();
  }
}

/** One level deeper than ordinary Settings. The live game music engine is
 * shared by the playlist, laboratory and game - never use a separate player.
 */
export class SoundManagerView extends View {
  constructor(scene,theme,o){
    super(scene,theme,{w:448,h:238,title:'MANAGE SOUND',
      color:'cyan',onClose:o.onClose,y:15,
      hints:[{keys:['↑','↓'],label:'SELECT'},{keys:['←','→'],label:'CHANGE'}]});
    this.labView=null;
    this._build();
  }
  _profile(){return this.scene.registry.get(REG.PROGRESSION)?.store?.profile||
    this.scene.registry.get(REG.PROFILE)||{};}
  _unlocked(){return this._profile()?.unlocked?.musicVocals===true;}
  _build(){
    const game=this.scene.game;
    const settings=()=>game.registry.get(REG.SETTINGS)||{};
    const unlocked=this._unlocked();
    const bank=Number(this._profile().bank)||0;
    const menuItems=[
      ...GAME_SONGS.map((song,index)=>({
        kind:'choice',label:'TRACK '+(index+1)+'  '+ellipsize(song.label.toUpperCase(),190),
        options:[{value:true,label:'ON'},{value:false,label:'OFF'}],
        get:()=>settings().musicEnabledSongs?.[song.id]!==false,
        set:v=>updateSetting(game,'musicEnabledSongs',{
          ...(settings().musicEnabledSongs||{}),[song.id]:v,
        }),
      })),
      {kind:'choice',label:'SHUFFLE SONGS',options:[
          {value:false,label:'OFF'},{value:true,label:'ON'}],
        get:()=>settings().musicShuffle===true,
        set:v=>updateSetting(game,'musicShuffle',v)},
      {kind:'choice',label:'DYNAMIC ORCHESTRA',badge:'PRE-ALPHA',
        badgeColor:'magenta',options:[
          {value:false,label:'OFF'},{value:true,label:'ON'}],
        get:()=>settings().dynamicOrchestra===true,
        set:v=>updateSetting(game,'dynamicOrchestra',v)},
      ...(unlocked ? [
        {kind:'choice',label:'ORIGINAL VOCALS',options:[
          {value:false,label:'OFF'},{value:true,label:'ON'}],
          get:()=>settings().musicVocals===true,
          set:v=>this._changeVocals(v)},
        {kind:'slider',label:'VOCALS LEVEL',
          disabled:settings().musicVocals!==true,
          get:()=>settings().vocalGain??1,
          set:v=>updateSetting(game,'vocalGain',v)},
        {kind:'slider',label:'SYNTH MELODY WITH VOCALS',
          disabled:settings().musicVocals!==true,
          get:()=>settings().melodyWithVocalsGain??.18,
          set:v=>updateSetting(game,'melodyWithVocalsGain',v)},
      ] : [
        {kind:'action',label:'UNLOCK ORIGINAL VOCALS ('+
          VOCALS_UNLOCK_SHARDS+' SHARDS)',color:'amber',tint:'amber',
          sub:bank+' AVAILABLE',subColor:'amber',subAlpha:0.9,onSelect:()=>this._buyVocals()},
        {kind:'static',label:'VOCALS + MELODY MIX LOCKED'},
      ]),
      {kind:'action',label:'MUSIC LAB',color:'lime',
        sub:'USE REAL GAME ENGINE',onSelect:()=>this._openLab()},
    ];
    const selected=this.menu?.selected||0;
    this.menu?.destroy();
    this.menu=new MenuList(this.scene,this.theme,{x:10,y:24,w:428,
      rowH:17,items:menuItems,color:'cyan',parent:this.panel});
    this.menu.setSelected(Math.min(selected,menuItems.length-1),true);
    if(!this._revealed){this._revealed=true;staggerMenuRows(this.scene,this.menu);}
    if(!this.note){
      this.note=new NeonText(this.scene,this.theme,12,this.h-39,
        'DYNAMIC ORCHESTRA OFF = SOURCE STEMS + ALL GAME DSP',{
          color:'text',outline:'none',
        });
      this.note.setAlpha(.6);
      this.panel.add(this.note);
    }
  }
  _changeVocals(enabled){
    updateSetting(this.scene.game,'musicVocals',enabled===true);
    // The menu object is still active during click/keypress dispatch:
    // update existing row availability in place instead of destroying
    // the menu from inside one of its own pointer callbacks.
    for(const item of this.menu.items){
      if(item.label==='VOCALS LEVEL'||
        item.label==='SYNTH MELODY WITH VOCALS'){
        item.disabled=enabled!==true;
      }
    }
    this.menu.refresh();
  }
  _buyVocals(){
    const progression=this.scene.registry.get(REG.PROGRESSION);
    const store=progression?.store;
    const tx=store?.buyMusicVocals();
    if(tx?.ok){
      this.scene.registry.set(REG.PROFILE,tx.profile);
      uiSfx(this.scene,'uiSelect',{pitch:1.4});
      updateSetting(this.scene.game,'musicVocals',false);
      this._build();
    }else{
      uiSfx(this.scene,'uiBack');
      this.note.setText(tx?.reason==='not-enough-shards'
        ? 'NOT ENOUGH SHARDS TO UNLOCK VOCALS'
        : 'VOCAL PURCHASE COULD NOT BE SAVED');
    }
  }
  _openLab(){
    if(this.labView)return;
    this.panel.setVisible(false);
    this.labView=new SoundLabView(this.scene,this.theme,{
      onClose:()=>{
        this.labView?.destroy();
        this.labView=null;
        this.panel.setVisible(true);
        this._build();
      },
    });
  }
  handleAction(action){
    if(this.labView)return this.labView.handleAction(action);
    if(action==='cancel'){this.close();return true;}
    return this.menu.handleAction(action);
  }
  destroy(){
    this.labView?.destroy();this.labView=null;
    super.destroy();
  }
}


/** Actual-engine research lab. The only trusted place to check note-event
 * transcription, exact media lengths and timing, sound swap alignment,
 * repeated attacks and synchronization. Standalone :8186 is ART DESIGN ONLY.
 *
 * An isolated director instance uses the identical StemMusicDirector,
 * StemFXMixer, pack manifests and audio context as gameplay; only its
 * sandbox output is audible while this view is open. No game state writes.
 */
export class SoundLabView extends View {
  constructor(scene,theme,o){
    super(scene,theme,{w:468,h:253,title:'MUSIC LAB  //  REAL GAME AUDIO',
      color:'lime',onClose:o.onClose,y:7,
      hints:[{keys:['M'],label:'MARK'},{keys:['N'],label:'NOTES'}]});
    this.audio=scene.registry.get(REG.AUDIO);
    this.biome='crystal-cavern';
    this.songIndex=0;
    this.dynamic=false;
    this.solo='ALL';
    this.mixLevels=freshLabLevels(); // per-lab-session only
    this.mixerView=null;
    this.airborne=false;
    this.speed=0;
    this.lab=null;
    this.request=0;
    this.scoreRequest=0;
    this.score=null;
    this.scoreStatus='WAITING FOR SCORE MANIFEST';
    this.experimentalScore=null;
    this.experimentalStatus='EXPERIMENTAL COMPARISON NOT LOADED';
    this.reviewQueue=null;
    this.reviewStatus='NO MACHINE REVIEW SHORTLIST LOADED';
    this.markers=[]; // lab session only, not localStorage or profile
    this.markerStatus='NO AUDIO OR GAME SAVES ARE CHANGED';
    this.inspector=null;
    this.drafts=new Map(); // per-source-revision, session only

    this.sourceBus=null;
    this.prevBusVolume=null;
    // The four readout lines sit in an inset "display": dark well, thin frame, an amber edge. Added before
    // the texts so it paints under them.
    this.readout=scene.add.graphics();
    this.panel.add(this.readout);
    this._unbindReadout=theme.bind(pal=>{
      const g=this.readout;
      g.clear();
      g.fillStyle(pal.bg,0.85);g.fillRect(8,184,this.w-16,46);
      strokeRectPx(g,8,184,this.w-16,46,pal.cyan,0.3);
      g.fillStyle(pal.amber,0.9);g.fillRect(8,184,2,46);
    });
    this.statusText=new NeonText(scene,theme,13,188,
      'LOADING THE GAME MUSIC ENGINE...',{color:'amber',outline:'none'});
    this.panel.add(this.statusText);
    this.clockText=new NeonText(scene,theme,13,199,
      'SAMPLE-FRAME CHECK: WAITING FOR A DECODE',
      {color:'cyan',outline:'none'});
    this.panel.add(this.clockText);
    this.scoreText=new NeonText(scene,theme,13,210,
      'SOURCE SCORE: WAITING FOR CAPTURED EVENTS',
      {color:'amber',outline:'none'});
    this.panel.add(this.scoreText);
    this.infoText=new NeonText(scene,theme,13,221,
      'SCORES ARE NOT GROUND TRUTH; MARKERS DO NOT CHANGE AUDIO',
      {color:'text',outline:'none'});
    this.infoText.setAlpha(.7);
    this.panel.add(this.infoText);
    // Touch/pointer buttons leave gamepad and the ten existing lab menu
    // rows untouched. The normal View BACK button already occupies x392.
    this.markButton=new Button(scene,theme,{
      x:13,y:235,w:62,h:14,label:'MARK (M)',color:'amber',
      onClick:()=>this._markIssue(),parent:this.panel,
    });
    this.inspectButton=new Button(scene,theme,{
      x:80,y:235,w:70,h:14,label:'NOTES (N)',color:'lime',
      onClick:()=>this._openInspector(),parent:this.panel,
    }).setDisabled(true);
    this.mixerButton=new Button(scene,theme,{
      x:155,y:235,w:70,h:14,label:'MIXER',color:'lime',
      onClick:()=>this._openMixer(),parent:this.panel,
    });
    this.exportButton=new Button(scene,theme,{
      x:230,y:235,w:58,h:14,label:'EXPORT',color:'cyan',
      onClick:()=>this._exportMarks(),parent:this.panel,
    }).setDisabled(true);
    this.clearButton=new Button(scene,theme,{
      x:293,y:235,w:42,h:14,label:'CLEAR',color:'magenta',
      onClick:()=>this._clearMarks(),parent:this.panel,
    }).setDisabled(true);
    // A separate, research-only A/B/C audio page. It does not swap any
    // game stem, modify the published score, change user settings or save.
    this.pianoButton=new Button(scene,theme,{
      x:340,y:235,w:48,h:14,label:'PIANO',color:'amber',
      onClick:()=>this._openPianoReview(),parent:this.panel,
    });
    this._markKey=event=>{
      if(!this.alive||this.inspector||this.mixerView||event?.repeat)return;
      if(this.lab?.pack)this._markIssue();
    };
    scene.input?.keyboard?.on('keydown-M',this._markKey);
    this._build();
    this._openSandbox();
    this.tickTimer=scene.time.addEvent({delay:220,loop:true,callback:()=>this._tick()});
  }
  _build(){
    const titles=this.lab?.catalog?.length ?
      this.lab.catalog.map(track=>track.title) : GAME_SONGS.map(track=>track.label);
    const options=(items)=>items.map(([value,label])=>({value,label}));
    const items=[
      {kind:'choice',label:'SONG',options:titles.map((title,i)=>({
        value:i,label:ellipsize(title.toUpperCase(),215)})),
        get:()=>this.songIndex,set:i=>this._song(i)},
      {kind:'choice',label:'BIOME',options:options([
        [HOME_BIOME,'HOME'],
        ...BIOME_IDS.filter(id=>id!==HOME_BIOME).map(id=>[
          id,id.replace(/-/g,' ').toUpperCase()]),
      ]),get:()=>this.biome,set:id=>this._biome(id)},
      {kind:'choice',label:'REPLACEMENTS',options:options([
        [false,'SOURCE + DSP'],[true,'NEW ORCHESTRA']]),
        get:()=>this.dynamic,set:value=>this._dynamic(value)},
      {kind:'choice',label:'ISOLATE',options:options([
        ['ALL','ALL'],['MELODY','MELODY'],['DRUMS','DRUMS'],
        ['BASS','BASS'],['GUITAR','GUITAR'],['PIANO','PIANO'],
        ['OTHER','OTHER']]),
        get:()=>this.solo,set:value=>this._solo(value)},
      {kind:'choice',label:'DRUM PHASE',options:options([
        [false,'GROUND'],[true,'AIRBORNE']]),
        get:()=>this.airborne,set:value=>this._air(value)},
      {kind:'choice',label:'SLED SPEED',options:options([
        [0,'STOPPED'],[350,'SLOW'],[850,'FAST'],[1500,'EXTREME']]),
        get:()=>this.speed,set:value=>this._speed(value)},
      {kind:'action',label:'BACK 10 SECONDS',color:'amber',
        onSelect:()=>this._jump(-10)},
      {kind:'action',label:'FORWARD 10 SECONDS',color:'amber',
        onSelect:()=>this._jump(10)},
      {kind:'action',label:'RESTART THIS SONG',color:'cyan',
        onSelect:()=>this._jump(-10000)},
      {kind:'action',label:'STOP / PLAY',color:'magenta',
        onSelect:()=>this._toggle()},
    ];
    this.menu?.destroy();
    this.menu=new MenuList(this.scene,this.theme,{
      x:10,y:23,w:446,rowH:16,items,parent:this.panel,color:'lime'});
  }
  async _openSandbox(){
    const generation=++this.request;
    const audio=this.audio;
    try {
      if(!audio)throw new Error('Game music engine missing');
      audio.unlock(); // user gesture opens this view, respecting autoplay.
      if(!audio._ensureCtx()||!audio.nodes)throw new Error('Audio unavailable');
      const main=audio._stemMusic;
      // Opening from pause/title/end must not advance the user's actual
      // music stream or change any persistent gameplay music setting.
      this.sourceBus=main?.bus||null;
      if(this.sourceBus){
        this.prevBusVolume=this.sourceBus.gain.value;
        this.sourceBus.gain.setTargetAtTime(0,audio.ctx.currentTime,.02);
      }
      const lab=new StemMusicDirector(audio);
      this.lab=lab;
      await lab.initPromise;
      if(!this.alive||generation!==this.request){lab.destroy();return;}
      if(!lab.ready)throw new Error('No valid song packs in this build');
      if(audio.ctx.state!=='running')await audio.ctx.resume();
      if(!this.alive||generation!==this.request){lab.destroy();return;}
      lab.attach(audio.ctx,audio.nodes.musicFilter);
      lab.applySettings({
        musicEnabledSongs:Object.fromEntries(
          GAME_SONGS.map(song=>[song.id,true])),
        dynamicOrchestra:this.dynamic,
        musicVocals:false,musicCaptions:false,
      });
      lab.setBiome(this.biome);
      lab.setAirborne(this.airborne);
      lab.setSpeed(this.speed);
      lab.trackIndex=this.songIndex;
      lab.onTrackStarted=track=>{
        this.songIndex=track.index;
        this._applySolo();
        this._loadPerformanceScore(track.id);
        this.menu?.refresh();
      };
      lab.start();
      this._build();
      this._tick();
    }catch(e){
      if(this.alive)this.statusText.setText(
        'LAB UNAVAILABLE: '+ellipsize(String(e?.message||e),340));
    }
  }
  async _loadPerformanceScore(id){
    const generation=++this.scoreRequest;
    this.score=null;
    this.experimentalScore=null;
    this.experimentalStatus='EXPERIMENTAL COMPARISON NOT LOADED';
    this.reviewQueue=null;
    this.reviewStatus='REVIEW SHORTLIST NOT LOADED';
    this.inspectButton.setDisabled(true);
    const lab=this.lab;
    const scoreAsset=lab?.pack?.performance;
    if(!scoreAsset){
      this.scoreStatus='NO VERSIONED SCORE IN THIS GAME PACK';
      this._tick();
      return;
    }
    this.scoreStatus='CAPTURED SCORE LOADING';
    try{
      const url=resolveMusicAsset(lab.packBase,scoreAsset.path);
      const response=await fetch(url,{cache:'default'});
      if(!response.ok)throw new Error('Score HTTP '+response.status);
      const raw=await response.json();
      // The score must be for this pack, hash-pinned in its actual
      // shipping manifest, not merely an unrelated file with notes.
      const score=validatePerformanceScore(raw,lab.pack);
      if(!this.alive||generation!==this.scoreRequest||this.lab!==lab||
        lab.track?.id!==id)return;
      this.score=score;
      this.inspectButton.setDisabled(false);
      this.scoreStatus='SOURCE SCORE LOADED (UNCALIBRATED)';
      // Optional candidate fetch never delays, edits, or gates music.
      void this._loadExperimentalScore(lab,id,generation,score);
    }catch(err){
      if(this.alive&&generation===this.scoreRequest){
        this.score=null;
        this.scoreStatus='SCORE REJECTED: '+String(err?.message||err);
      }
    }
    this._tick();
  }
  async _loadExperimentalScore(lab,id,generation,base){
    const asset=lab.pack?.experimentalPerformance;
    if(!asset){
      this.experimentalStatus='NO EXPERIMENTAL SCORE AVAILABLE';
      return;
    }
    this.experimentalStatus='EXPERIMENTAL SCORE LOADING';
    try{
      const response=await fetch(resolveMusicAsset(lab.packBase,asset.path),
        {cache:'default'});
      if(!response.ok)throw new Error('Candidate HTTP '+response.status);
      const raw=await response.json();
      const experimental=validateExperimentalPerformanceScore(raw,
        lab.pack,base);
      if(!this.alive||generation!==this.scoreRequest||this.lab!==lab||
        lab.track?.id!==id||this.score!==base)return;
      this.experimentalScore=experimental;
      this.experimentalStatus='V2 EXPERIMENTAL SCORE LOADED (NOT GOLD)';
      // Ranked disagreements remain optional and never touch playback.
      void this._loadReviewQueue(lab,id,generation,base,experimental);
    }catch(err){
      if(this.alive&&generation===this.scoreRequest){
        this.experimentalScore=null;
        this.experimentalStatus='V2 REJECTED: '+String(err?.message||err);
      }
    }
    this.inspector?.refresh();
  }
  async _loadReviewQueue(lab,id,generation,base,experimental){
    const asset=lab.pack?.diagnosticReviewQueue;
    if(!asset){
      this.reviewStatus='NO REVIEW SHORTLIST IN THIS PACK';
      return;
    }
    this.reviewStatus='MACHINE DISAGREEMENT SHORTLIST LOADING';
    try{
      const response=await fetch(resolveMusicAsset(lab.packBase,asset.path),
        {cache:'default'});
      if(!response.ok)throw new Error('Review HTTP '+response.status);
      const raw=await response.json();
      const queue=validateMusicReviewQueue(raw,lab.pack,base,experimental);
      if(!this.alive||generation!==this.scoreRequest||this.lab!==lab||
        lab.track?.id!==id||this.score!==base||
        this.experimentalScore!==experimental)return;
      this.reviewQueue=queue;
      this.reviewStatus='MACHINE DISAGREEMENTS (NOT VERIFIED ERRORS)';
    }catch(err){
      if(this.alive&&generation===this.scoreRequest&&this.lab===lab&&
        this.experimentalScore===experimental){
        this.reviewQueue=null;
        this.reviewStatus='REVIEW SHORTLIST REJECTED: '+String(err?.message||err);
      }
    }
    this.inspector?.refresh();
  }
  _clockFrame(){
    const lab=this.lab;
    if(!lab?.pack||lab.clockStart===null||!lab.ctx)return null;
    return Math.max(0,Math.min(lab.pack.frameCount-1,Math.round(
      (lab.ctx.currentTime-lab.clockStart)*lab.pack.sampleRate)));
  }
  _markIssue(){
    const lab=this.lab;
    const frame=this._clockFrame();
    if(!lab?.track||frame===null)return;
    const role=this.solo==='ALL'?'ALL':this.solo.toLowerCase();
    this.markers.push(makeIssueMarker(this.score,{
      songId:lab.track.id,role,frame,
      biome:this.biome,airborne:this.airborne,speed:this.speed,
      replacements:this.dynamic,
    }));
    this.markerStatus='MARKED '+this.markers.length+' SUSPECT MOMENT(S), NOT GOLD NOTES';
    this.exportButton.setDisabled(false);
    this.clearButton.setDisabled(false);
    this._tick();
  }
  _clearMarks(){
    this.markers=[];
    this.markerStatus='ALL SESSION MARKS CLEARED; NO GAME SAVE CHANGED';
    this.exportButton.setDisabled(true);
    this.clearButton.setDisabled(true);
    this._tick();
  }
  _exportMarks(){
    if(!this.markers.length||typeof document==='undefined')return;
    const payload={
      format:'bitstream-music-issue-markers-v1',
      status:'human-listening-suspicions-not-gold-annotations',
      sampleRate:48000,
      count:this.markers.length,
      markers:this.markers,
    };
    const data=JSON.stringify(payload,null,2)+'\n';
    const blob=new Blob([data],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    try{
      const link=document.createElement('a');
      link.href=url;
      link.download='bitstream-music-issues-'+Date.now()+'.json';
      document.body.appendChild(link);
      link.click();
      link.remove();
    }finally{
      // A queued download owns the Blob by this point; defer revoke so
      // Firefox/Chrome can both consume the object URL.
      setTimeout(()=>URL.revokeObjectURL(url),10000);
    }
    this.markerStatus='EXPORTED '+this.markers.length+' ISSUE MARK(S), NO CHANGES SAVED';
    this._tick();
  }
  _openPianoReview(){
    if(!this.alive||this.inspector||this.mixerView)return;
    // This is deliberately a separate review tab, NOT a parallel game music
    // transport. Stop only the LAB audition so the review does not compete
    // with another song; the active gameplay song bus stays owned by the Lab.
    // A blocked popup must not change the player's persistent music settings.
    this.lab?.stop();
    this.markerStatus='OPTIONAL MAXI PIANO A/B/C OPENS IN SEPARATE TAB';
    this._tick();
    if(typeof window!=='undefined'&&typeof window.open==='function'){
      window.open('music-review/piano-friendly/index.html',
        '_blank','noopener,noreferrer');
    }
  }
  _openInspector(){
    if(this.inspector||this.mixerView||!this.score||!this.lab?.pack)return;
    const scoreHash=this.score.scoreHash;
    const draft=this.drafts.get(scoreHash);
    const inspector=new ScoreInspectorView(this.scene,this.theme,{
      lab:this,draft,
      onClose:()=>this._closeInspector(),
    });
    this.inspector=inspector;
    this.drafts.set(scoreHash,inspector.draft);
  }
  _closeInspector(){
    this.inspector?.destroy();
    this.inspector=null;
    this._tick();
  }
  _openMixer(){
    if(this.inspector||this.mixerView||!this.lab?.ready)return;
    this.mixerView=new StemMixerView(this.scene,this.theme,{
      lab:this,onClose:()=>this._closeMixer(),
    });
  }
  _closeMixer(){
    this.mixerView?.destroy();
    this.mixerView=null;
    this._tick();
  }
  _setStemLevel(role,level){
    if(!LAB_STEMS.includes(role)||![0,.35,1,1.35].includes(level))return;
    this.mixLevels[role]=level;
    this._applySolo();
  }
  _resetStemMix(){
    this.mixLevels=freshLabLevels();
    this._solo('ALL');
  }
  _song(index){
    this._closeInspector();
    this._closeMixer();
    ++this.scoreRequest;
    this.score=null;
    this.experimentalScore=null;
    this.reviewQueue=null;
    this.reviewStatus='SWITCHING REVIEW SHORTLIST';
    this.experimentalStatus='SWITCHING EXPERIMENTAL SCORE';
    this.scoreStatus='SWITCHING SOURCE SCORE';
    this.songIndex=index;
    const lab=this.lab;
    if(!lab?.ready)return;
    lab.stop();
    lab.trackIndex=index;
    lab.start();
  }
  _biome(id){
    this.biome=id;
    this.lab?.setBiome(id);
    this._applySolo();
  }
  _dynamic(value){
    this.dynamic=value===true;
    this.lab?.setDynamicOrchestra(this.dynamic);
    this._applySolo();
  }
  _air(value){
    this.airborne=value===true;
    this.lab?.setAirborne(this.airborne);
    this._applySolo();
  }
  _speed(value){
    this.speed=Number(value)||0;
    this.lab?.setSpeed(this.speed);
    this._applySolo();
  }
  _solo(value){
    this.solo=value;
    this._applySolo();
  }
  _applySolo(){
    const lab=this.lab;
    if(!lab?.mixer||!lab.pack)return;
    // Preserve motion/airborne automation on its separate WebAudio gain
    // nodes while applying 6 independent ephemeral user mix levels.
    lab.setSpeed(this.speed);
    lab.setAirborne(this.airborne);
    applyLabStemLevels(lab,this.mixLevels,this.solo);
  }
  _jump(delta){
    const lab=this.lab;
    if(!lab?.pack)return;
    const position=Math.max(0,Math.min(lab.pack.duration-1,
      (lab.ctx.currentTime-lab.clockStart)+delta));
    if(typeof lab.seekTo==='function')lab.seekTo(position);
  }
  _toggle(){
    const lab=this.lab;
    if(!lab)return;
    if(lab.started)lab.stop();
    else{
      lab.trackIndex=this.songIndex;
      lab.start();
    }
    this._tick();
  }
  _tick(){
    if(!this.alive)return;
    const lab=this.lab;
    if(!lab?.ready){
      this.statusText.setText('ENGINE: WAITING FOR THE SAME GAME CATALOG');
      return;
    }
    const name=lab.track?.title||lab.catalog[this.songIndex]?.title||'NO SONG';
    const elapsed=lab.pack&&lab.clockStart!==null ?
      Math.max(0,lab.ctx.currentTime-lab.clockStart) : 0;
    this.statusText.setText(ellipsize(
      name+'  '+(this.dynamic?'NEW INSTRUMENTS':'SOURCE + DSP'),436));
    const second=Math.floor(elapsed);
    const minutes=Math.floor(second/60);
    const stamp=minutes+':'+String(second%60).padStart(2,'0');
    let diagnostic='WAITING FOR AUDIO DECODE';
    if(lab.pack){
      const index=lab.pack.segments.findIndex(seg=>
        seg.startFrame<=elapsed*lab.pack.sampleRate &&
        seg.startFrame+seg.frames>elapsed*lab.pack.sampleRate);
      const segment=lab.pack.segments[Math.max(0,index)];
      const name=lab._activeVoiceFor(lab.pack)||'drums';
      const buffer=lab.cache.get(Math.max(0,index)+'/'+name);
      diagnostic=buffer?
        'DECODED '+buffer.length+' / EXPECTED '+segment.frames+
        ' FRAMES ['+(buffer.length-segment.frames)+']' :
        'BUFFER FETCH / DECODE PENDING';
    }
    this.clockText.setText('TIME '+stamp+'  '+diagnostic);
    const frame=this._clockFrame();
    if(this.score && frame!==null){
      const roles=this.solo==='ALL'?PERFORMANCE_ROLES:
        [this.solo.toLowerCase()];
      const near=nearbyPerformanceEvents(this.score,roles,frame,4800);
      const examples=near.slice(0,3).map(({role,event})=>
        role.toUpperCase().slice(0,2)+':'+(event.pitch??event.class)+
        '@'+Math.round((event.startFrame-frame)/48)+'MS').join(' ');
      this.scoreText.setText(ellipsize(
        'SCORE '+this.score.scoreHash.slice(0,8)+' '+
        near.length+' ATTACK(S) +-100MS  '+examples,436));
    }else{
      this.scoreText.setText(ellipsize('SCORE: '+this.scoreStatus,436));
    }
    this.infoText.setText(ellipsize(this.markerStatus,436));
    this.inspector?.refresh();
    this.mixerView?.refresh();
  }
  handleAction(action){
    if(this.mixerView)return this.mixerView.handleAction(action);
    if(this.inspector)return this.inspector.handleAction(action);
    if(action==='alt'){this._openInspector();return true;}
    if(action==='cancel'){this.close();return true;}
    return this.menu.handleAction(action);
  }
  destroy(){
    this._closeInspector();
    this._closeMixer();
    ++this.request;
    ++this.scoreRequest;
    this.scene.input?.keyboard?.off('keydown-M',this._markKey);
    this._markKey=null;
    this.score=null;
    this.experimentalScore=null;
    this.reviewQueue=null;
    this.tickTimer?.remove();
    this.lab?.destroy();
    this.lab=null;
    if(this.sourceBus&&this.audio?.ctx){
      this.sourceBus.gain.setTargetAtTime(
        this.prevBusVolume??1,this.audio.ctx.currentTime,.05);
    }
    this.sourceBus=null;
    this._unbindReadout?.();this._unbindReadout=null;
    super.destroy();
  }
}

/** Free-text seed entry (DOM input so touch keyboards work). */
export class SeedView extends View {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{onClose:function():void, onSubmit:function(string):void, initial?:string}} o
   */
  constructor(scene, theme, o) {
    super(scene, theme, { w: 340, h: 118, title: 'ENTER SEED', color: 'lime', onClose: o.onClose, y: 70 });
    this.onSubmit = o.onSubmit;
    const px = this.panel.x;
    const py = this.panel.y;
    // a lime halo around the DOM field (the field itself is an HTML element above the canvas)
    this.slot = scene.add.graphics();
    this.panel.add(this.slot);
    this._unbindSlot = theme.bind((pal) => {
      this.slot.clear();
      glowRectPx(this.slot, 12, 40, 316, 20, pal.lime, 1.4);
      paintRule(this.slot, 12, this.w - 12, this.h - 30, pal.lime, 0.5);
    });
    this.panel.add(new NeonText(scene, theme, 12, 24, 'SAME SEED = SAME TRACK. SHARE IT WITH FRIENDS.', { color: 'text', outline: 'none' }).setAlpha(0.7));
    this.box = new DomTextBox(scene, theme, {
      x: px + 12, y: py + 40, w: 316, h: 20, value: o.initial || '', maxLength: 32, placeholder: 'TYPE A SEED (EMPTY = RANDOM)',
      color: 'lime', onSubmit: () => this.submit(), onCancel: () => this.close(),
    });
    this.panel.add(new Keycaps(scene, theme, { x: 12, y: 66, color: 'lime',
      items: [{ keys: ['ENTER'], label: 'GO' }, { keys: ['ESC'], label: 'BACK' }] }));
    this.go = new Button(scene, theme, { x: 12, y: this.h - 22, w: 96, h: 16, label: 'GO!', color: 'lime', onClick: () => this.submit() });
    this.panel.add(this.go);
    scene.time.delayedCall(30, () => this.alive && this.box.focus());
  }

  submit() {
    if (this.alive) this.onSubmit(this.box.getValue().trim());
  }

  handleAction(action) {
    if (action === 'cancel') this.close();
    else if (action === 'confirm') this.submit();
    return true;
  }

  destroy() {
    if (this.box) this.box.destroy();
    this.box = null;
    if (this._unbindSlot) this._unbindSlot();
    this._unbindSlot = null;
    super.destroy();
  }
}

/** Export (copy + visible fallback) or import (paste) of the leaderboard sharecode. */
export class SharecodeView extends View {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{mode:'export'|'import', onClose:function():void}} o
   */
  constructor(scene, theme, o) {
    const exp = o.mode === 'export';
    super(scene, theme, { w: 400, h: 168, title: exp ? 'EXPORT SHARECODE' : 'IMPORT SHARECODE', color: exp ? 'cyan' : 'lime', onClose: o.onClose, y: 50,
      hints: exp ? [{ keys: ['ENTER'], label: 'COPY' }] : [{ keys: ['CTRL+V'], label: 'PASTE' }, { keys: ['ENTER'], label: 'IMPORT' }] });
    this.exp = exp;
    this.store = scene.registry.get(REG.SAVE_STORE);
    const px = this.panel.x;
    const py = this.panel.y;
    this.hint = new NeonText(scene, theme, 12, 22, exp ? 'YOUR LEDGER AS TEXT. COPY IT, SEND IT, IMPORT IT ELSEWHERE.' : 'PASTE A SHARECODE BELOW (CTRL+V), THEN PRESS IMPORT.', {
      color: 'text', outline: 'none',
    });
    this.hint.setAlpha(0.7);
    this.panel.add(this.hint);
    // halo round the DOM text box, and a divider above the status line
    this.slot = scene.add.graphics();
    this.panel.add(this.slot);
    const accent = exp ? 'cyan' : 'lime';
    this._unbindSlot = theme.bind((pal) => {
      this.slot.clear();
      glowRectPx(this.slot, 12, 36, 376, 76, pal[accent], 1.2);
      paintRule(this.slot, 12, this.w - 12, this.h - 43, pal[accent], 0.5);
    });
    this.status = new NeonText(scene, theme, 12, this.h - 38, exp ? 'PREPARING...' : 'WAITING FOR PASTE', { color: 'amber', outline: 'none' });
    this.panel.add(this.status);
    this.box = new DomTextBox(scene, theme, {
      x: px + 12, y: py + 36, w: 376, h: 76, multiline: true, readOnly: exp, value: '',
      placeholder: exp ? '' : 'PASTE SHARECODE HERE', color: exp ? 'cyan' : 'lime',
      onSubmit: () => this.act(), onCancel: () => this.close(),
    });
    this.actBtn = new Button(scene, theme, {
      x: 12, y: this.h - 22, w: 110, h: 16, label: exp ? 'COPY AGAIN' : 'IMPORT', color: exp ? 'cyan' : 'lime', onClick: () => this.act(),
    });
    this.panel.add(this.actBtn);
    scene.time.delayedCall(30, () => this.alive && this.box && this.box.focus());
    if (exp) this._load();
  }

  async _load() {
    let code = '';
    try {
      code = await this.store.exportSharecode();
    } catch (e) {
      code = '';
    }
    if (!this.alive) return;
    this.code = code || '';
    if (!this.code) {
      this.box.setValue('(LEDGER IS EMPTY - NOTHING TO EXPORT YET)');
      this.setStatus('NO ENTRIES TO EXPORT', 'amber');
      return;
    }
    this.box.setValue(this.code);
    this.box.selectAll();
    this.act();
  }

  setStatus(text, color) {
    if (!this.alive) return;
    this.status.setText(ellipsize(text, 380));
    this.status.setColorKey(color);
  }

  async act() {
    if (!this.alive) return;
    if (this.exp) {
      if (!this.code) return;
      const ok = await copyText(this.code);
      if (!this.alive) return;
      if (ok) this.setStatus('COPIED TO CLIPBOARD', 'lime');
      else {
        this.setStatus('CLIPBOARD BLOCKED - TEXT SELECTED: PRESS CTRL+C', 'amber');
        this.box.selectAll();
      }
    } else {
      const text = this.box.getValue().trim();
      if (!text) {
        this.setStatus('NOTHING TO IMPORT - PASTE A SHARECODE FIRST', 'amber');
        return;
      }
      let res = { imported: 0, skipped: 0 };
      try {
        res = (await this.store.importSharecode(text)) || res;
      } catch (e) {
        res = { imported: 0, skipped: 1 };
      }
      if (!this.alive) return;
      if (res.imported > 0) this.setStatus(`IMPORTED ${res.imported} RUN(S), SKIPPED ${res.skipped}`, 'lime');
      else this.setStatus(`NOTHING IMPORTED (SKIPPED ${res.skipped}) - NOT A VALID SHARECODE?`, 'danger');
    }
  }

  handleAction(action) {
    if (action === 'cancel') this.close();
    else if (action === 'confirm') this.act();
    return true;
  }

  destroy() {
    if (this._unbindSlot) this._unbindSlot();
    this._unbindSlot = null;
    if (this.box) this.box.destroy();
    this.box = null;
    super.destroy();
  }
}

/** Left edges of the two stat columns' zebra stripes (the layout's PAD and its second column, minus 2). */
const PAD_STAT_L = 10;
const PAD_STAT_R = 206;

/**
 * W1: PROFILE view — lifetime stats, Sync Level, Resonance progress, and the list of biome
 * signatures the player has reached (locked ones read "SIGNATURE LOCKED - COMING ONLINE" until
 * W3/W6 ship the biomes themselves). Read-only; nothing here writes the profile.
 *
 * All geometry and text come from `ProfileLayout.profileLayout()` so the layout is unit-tested for
 * overlap and contrast without Phaser; this class only draws it and repaints on palette change.
 */
export class ProfileView extends View {
  /** @param {Phaser.Scene} scene @param {import('./Theme.js').Theme} theme @param {{onClose:function():void}} o */
  constructor(scene, theme, o) {
    const content = scene.registry.get(REG.CONTENT) || {};
    const biomeDefs = Object.values(content.biomes || {});
    const layout = profileLayout({
      profile: scene.registry.get(REG.PROFILE),
      levels: content.progression,
      playableBiomeIds: biomeDefs.map((d) => d.id),
      achievementTotal: visibleAchievements(scene.registry.get(REG.PROFILE)).length,
    });
    super(scene, theme, { w: layout.w, h: layout.h, title: 'PILOT PROFILE', color: 'lime', onClose: o.onClose, y: 22, backLabel: 'BACK' });
    this._onShop = o.onShop;

    // Decoration UNDER the text: zebra stripes behind the stat rows and a fading rule after each section
    // heading (LIFETIME, SIGNATURES), drawn from the layout's own boxes so they cannot drift from the text.
    const byKey = new Map(layout.items.map((it) => [it.key, it]));
    this.deco = scene.add.graphics();
    this.panel.add(this.deco);
    this.unbindDeco = theme.bind((pal) => {
      const g = this.deco;
      g.clear();
      for (let i = 0; i < 10; i++) {
        const k = byKey.get(`stat-k${i}`);
        if (!k || i % 5 % 2 === 1) continue;
        const left = i < 5 ? PAD_STAT_L : PAD_STAT_R;
        g.fillStyle(pal.text, 0.045);
        g.fillRect(left, k.y - 2, i < 5 ? 178 : 198, 12);
      }
      for (const [head, right, ck] of [['lifetime-head', 'bank', 'amber'], ['sig-head', 'sig-note', 'magenta']]) {
        const h = byKey.get(head);
        const r = byKey.get(right);
        if (h && r) paintRule(g, h.x + h.w + 6, r.x - 6, h.y + 4, pal[ck], 0.7);
      }
    });

    const texts = [];
    for (const it of layout.items) {
      // Layout boxes are always top-left, so draw left-anchored and never let Phaser re-apply an
      // origin: passing anchor:'right' with a left edge shifted right-aligned text a second time.
      const t = new NeonText(scene, theme, it.x, it.y, it.text, {
        color: it.color, outline: it.outline, alpha: it.alpha,
      });
      this.panel.add(t);
      texts.push([it.y, t]);
    }
    // reveal row by row (objects sharing a y fade together)
    const ys = [...new Set(texts.map((e) => e[0]))].sort((a, b) => a - b);
    staggerAlpha(scene, ys.map((y) => texts.filter((e) => e[0] === y).map((e) => e[1])), { start: 110, step: 20 });

    // Resonance bar: XP progress inside the current level. Same paint as Game Over, so a player who
    // just levelled sees the same fill they saw there.
    const b = layout.bar;
    const bar = scene.add.graphics();
    this.panel.add(bar);
    this.unbindBar = theme.bind((pal) => {
      bar.clear();
      paintGlowBar(bar, pal, b, b.ratio, b.color);
    });

    // W3: signature toggles. Only unlocked biomes get a row, and toggling one persists the profile so a
    // player's choice survives a reload. Toggling is cosmetic-adjacent but real: it changes which biome
    // sectors their next run can contain, which is why mask-scoped stats exist.
    // SHARD SHOP moved here from the Title menu: Title's band physically fits six 2x rows and the shop
    // was the seventh (it overran the DAILY PATCH strip). It sits on this screen because Profile is where
    // you already look at what you own and what it looks like.
    if (layout.shopButton) {
      const sb = layout.shopButton;
      this.shopButton = new Button(scene, theme, {
        x: sb.x, y: sb.y, w: sb.w, h: sb.h, label: 'SHARD SHOP', color: 'amber',
        onClick: () => this._openShop(),
      });
      this.panel.add(this.shopButton);
      // The button is pointer-only by design (Button's own doc says keyboard users reach the action
      // through scene-level keys). That was fine while the shop also had a Title row; it is now the ONLY
      // way in, so Profile has to provide the key path itself.
      this.shopFocus = new Phaser.GameObjects.Graphics(scene);
      this.panel.add(this.shopFocus);
    }

    this.biomeDefs = biomeDefs;
    const service = scene.registry.get(REG.PROGRESSION);
    this.profileStore = (service && service.store) || null;
    this.toggleRows = this._toggleRows();
    if (this.toggleRows.length) {
      const items = this.toggleRows.map((r) => ({
        kind: 'choice',
        // Decision 3: NAME + NEW / SEEN / DONE (ProfileLayout.toggleLabel), coloured by state.
        label: toggleLabel(r).text,
        color: toggleLabel(r).color,
        options: [{ value: false, label: 'OFF' }, { value: true, label: 'ON' }],
        get: () => {
          const p = scene.registry.get(REG.PROFILE) || {};
          const row = biomeToggleRows(p, this.biomeDefs).find((x) => x.id === r.id);
          return Boolean(row && row.enabled);
        },
        set: (v) => this._setBiome(r.id, Boolean(v)),
      }));
      // Geometry from the layout, so the menu can never be drawn on top of the biome names again.
      const band = layout.toggleMenu;
      this.sigMenu = new MenuList(scene, theme, {
        x: band.x, y: band.y, w: band.w, rowH: band.rowH, items, color: 'magenta', parent: this.panel,
        // The layout balances the columns from its own count; never let a longer item list spill into a
        // third, off-panel column if the two counts ever disagree.
        columns: band.columns, rowsPerColumn: Math.max(band.rowsPerColumn, Math.ceil(items.length / band.columns)),
      });
      staggerMenuRows(scene, this.sigMenu, { start: 260, step: 14 });
    }

    // W5: the achievements grid opens from here, as the spec places it in the Profile view. The button
    // sits bottom-left because BACK owns bottom-right; the layout module owns both boxes so the two can
    // never be drawn on top of each other.
    if (layout.achButton) {
      const bb = layout.achButton;
      this.achButton = new Button(scene, theme, {
        x: bb.x, y: bb.y, w: bb.w, h: bb.h, label: 'ACHIEVEMENTS', color: 'amber',
        onClick: () => this._openAchievements(),
      });
      this.panel.add(this.achButton);
    }

    // SHOP-2: TITLES, third in the bottom strip. Opens the title picker, which replaces this view the way
    // the achievements grid does and returns here on BACK.
    if (layout.titlesButton) {
      const tb = layout.titlesButton;
      this.titlesButton = new Button(scene, theme, {
        x: tb.x, y: tb.y, w: tb.w, h: tb.h, label: 'TITLES', color: 'lime',
        onClick: () => this._openTitles(),
      });
      this.panel.add(this.titlesButton);
    }
  }

  /** Open the TITLES picker from inside the profile, replacing this view; BACK rebuilds the profile. */
  _openTitles() {
    uiSfx(this.scene, 'uiSelect');
    const scene = this.scene;
    const theme = this.theme;
    const onClose = this.onClose;
    const onShop = this._onShop;
    const next = new TitlesView(scene, theme, {
      onClose: () => {
        // Same order as the achievements grid: build the profile first, then destroy the picker, so the
        // picker's panel can never be left pinned over the Title menu.
        const back = new ProfileView(scene, theme, { onClose, onShop });
        next.destroy();
        scene.view = back;
      },
    });
    this.destroy();
    this.scene.view = next;
  }

  /** Open the achievements grid from inside the profile, replacing this view. */
  _openAchievements() {
    uiSfx(this.scene, 'uiSelect');
    const scene = this.scene;
    const theme = this.theme;
    const onClose = this.onClose;
    const onShop = this._onShop;
    const next = new AchievementsView(scene, theme, {
      onClose: () => {
        // Backing out of the grid returns to the PROFILE view the player came from, not to the Title
        // screen: ejecting them a screen further than they went in is a navigation bug the player feels.
        // The GRID is what gets destroyed here (this profile is already gone): destroying `this` instead
        // left the depth-500 grid pinned over the Title menu for good. The rebuilt profile keeps onShop,
        // or SHARD SHOP would silently just close it.
        const back = new ProfileView(scene, theme, { onClose, onShop });
        next.destroy();
        scene.view = back;
      },
      biomeDefs: this.biomeDefs,
    });
    this.destroy();
    this.scene.view = next;
  }

  /** Unlocked biomes as toggle rows (empty before any unlock). */
  _toggleRows() {
    try {
      return biomeToggleRows(this.scene.registry.get(REG.PROFILE) || {}, this.biomeDefs).filter((r) => r.unlocked);
    } catch (e) {
      return [];
    }
  }

  /**
   * Apply one toggle and persist it. `toggleBiome` flips, so it is called only when the desired state
   * differs from the current one - calling it unconditionally would invert an already-correct row.
   */
  _setBiome(id, on) {
    const prof = this.scene.registry.get(REG.PROFILE);
    if (!prof) return;
    const row = biomeToggleRows(prof, this.biomeDefs).find((x) => x.id === id);
    if (!row || row.enabled === on) return;
    const next = toggleBiome(prof, id, this.biomeDefs);
    const service = this.scene.registry.get(REG.PROGRESSION);
    const store = this.profileStore || (service && service.store) || null;
    try {
      if (store) {
        this.scene.registry.set(REG.PROFILE, store.save(next));
      } else {
        this.scene.registry.set(REG.PROFILE, next);
      }
    } catch (e) { /* a denied storage write must not break the menu */ }
  }

  /**
   * Open the shop from this screen.
   *
   * Kept as one method so the pointer button and the key path cannot diverge: the keyboard used to be
   * unable to reach the shop at all, which is only possible if the two entry points are separate code.
   */
  _openShop() {
    const go = this._onShop;
    this.close();
    if (go) go();
  }

  /**
   * Focus targets in visual order: the signature rows, then ACHIEVEMENTS, SHARD SHOP and BACK (the
   * bottom strip, left to right).
   *
   * ProfileView used to forward every action straight to `sigMenu`, which wraps inside its own five
   * rows — so keyboard and gamepad could never leave the toggles, and SHARD SHOP (the only route to the
   * shop) was unreachable without a mouse. A single ordered list is what makes it reachable: up/down walk
   * it, and confirm activates whichever entry holds focus.
   *
   * ACHIEVEMENTS was pointer-only (its button was never a target), so the grid could not be opened by
   * keyboard or pad. It sits before SHARD SHOP because it is left of it on screen; first focus still
   * lands on SHARD SHOP (`length - 2`) when there are no toggle rows.
   *
   * @returns {Array<{kind:'row'|'ach'|'buy'|'back', index?:number}>}
   */
  _focusTargets() {
    const out = [];
    const rows = this.sigMenu ? this.sigMenu.items.length : 0;
    for (let i = 0; i < rows; i += 1) out.push({ kind: 'row', index: i });
    if (this.achButton) out.push({ kind: 'ach' });
    if (this.shopButton) out.push({ kind: 'buy' });
    if (this.titlesButton) out.push({ kind: 'titles' });
    out.push({ kind: 'back' });
    return out;
  }

  /** Paint the focus ring on whichever target holds focus (rows are highlighted by MenuList itself). */
  _paintFocus() {
    if (!this.shopFocus) return;
    const g = this.shopFocus;
    const pal = this.theme.pal;
    g.clear();
    const t = this._focusTargets()[this.focusIdx];
    if (!t) return;
    let r = null;
    if (t.kind === 'ach' && this.achButton) r = { x: this.achButton.x, y: this.achButton.y, w: this.achButton.w, h: this.achButton.h };
    if (t.kind === 'buy' && this.shopButton) r = { x: this.shopButton.x, y: this.shopButton.y, w: this.shopButton.w, h: this.shopButton.h };
    if (t.kind === 'titles' && this.titlesButton) r = { x: this.titlesButton.x, y: this.titlesButton.y, w: this.titlesButton.w, h: this.titlesButton.h };
    if (t.kind === 'back' && this.back) r = { x: this.back.x, y: this.back.y, w: this.back.w, h: this.back.h };
    if (!r) return;
    paintFocusRing(g, pal, r, t.kind === 'back' ? 'magenta' : 'amber');
  }

  handleAction(action) {
    if (action === 'cancel') {
      this.close();
      return true;
    }

    const targets = this._focusTargets();
    // Focus lives here, not in MenuList: the menu's own selection wraps inside its rows, which is exactly
    // why the shop was unreachable. One ordered list means one place that decides where focus is, and the
    // menu's highlight is a mirror of it rather than a second, competing cursor.
    if (this.focusIdx === undefined || this.focusIdx === null || this.focusIdx >= targets.length) {
      // Land on the first row if there is one; otherwise on the first button. Never on BACK, so the
      // first press moves into the screen rather than leaving it.
      // With no rows, SHARD SHOP (found by kind: TITLES now sits between it and BACK).
      const buyIdx = targets.findIndex((x) => x.kind === 'buy');
      this.focusIdx = this.sigMenu ? 0 : (buyIdx >= 0 ? buyIdx : Math.max(0, targets.length - 2));
      this._syncMenu();
      this._paintFocus();
      if (action !== 'confirm') return true;
    }

    const cur = targets[this.focusIdx];
    if (!cur) return true;

    if (action === 'up' || action === 'down') {
      const next = this.focusIdx + (action === 'up' ? -1 : 1);
      if (next < 0 || next >= targets.length) return true; // clamp: no wrap onto BACK by accident
      this.focusIdx = next;
      this._syncMenu();
      this._paintFocus();
      uiSfx(this.scene, 'uiMove');
      return true;
    }

    if (action === 'left' || action === 'right') {
      // Only a toggle row is horizontally adjustable; on the buttons this is a no-op, not an exit.
      if (cur.kind !== 'row' || !this.sigMenu) return true;
      this.sigMenu._adjust(cur.index, action === 'left' ? -1 : 1);
      return true;
    }

    if (action === 'confirm') {
      if (cur.kind === 'row' && this.sigMenu) {
        this.sigMenu.activate();
      } else if (cur.kind === 'buy') {
        uiSfx(this.scene, 'uiSelect');
        this._openShop();
      } else if (cur.kind === 'ach') {
        this._openAchievements();
      } else if (cur.kind === 'titles') {
        this._openTitles();
      } else {
        this.close();
      }
      return true;
    }
    return true;
  }

  /** Mirror this view's focus onto the menu's highlight. */
  _syncMenu() {
    if (!this.sigMenu) return;
    const t = this._focusTargets()[this.focusIdx];
    if (t && t.kind === 'row') this.sigMenu.setSelected(t.index, true);
  }

  destroy() {
    if (this.unbindBar) this.unbindBar();
    this.unbindBar = null;
    if (this.unbindDeco) this.unbindDeco();
    this.unbindDeco = null;
    super.destroy();
  }
}

/**
 * W5: ACHIEVEMENTS grid. Read-only; nothing here writes the profile.
 *
 * Paged because 29 rows will not fit above a BACK button, and paging is done by swapping this view's own
 * text objects rather than rebuilding the panel: rebuilding would re-run the constructor and lose the
 * player's page when the palette changes.
 *
 * LEFT/RIGHT (or 'prev'/'next') page; cancel closes, which the base class already does.
 */
export class AchievementsView extends View {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{onClose:function():void, page?:number, biomeCount?:number, biomeDefs?:Object[]}} o
   */
  constructor(scene, theme, o) {
    const profile = scene.registry.get(REG.PROFILE);
    const biomeDefs = o.biomeDefs || Object.values((scene.registry.get(REG.CONTENT) || {}).biomes || {});
    const layout = achievementsLayout({
      profile,
      page: o.page || 0,
      // ACH-6: no catalogue-size default. The grid reads the profile's ENCOUNTERED count (decision 3); only an
      // explicit caller figure is passed through.
      biomeCount: o.biomeCount,
    });
    super(scene, theme, { w: layout.w, h: layout.h, title: 'ACHIEVEMENTS', color: 'amber', onClose: o.onClose, y: 13, backLabel: 'BACK' });
    this.profile = profile;
    this.biomeDefs = biomeDefs;
    this.biomeCount = o.biomeCount;
    this.page = layout.page;
    this.rows = [];
    // Decoration under the rows (card washes, progress rails, section rules, pager) and the header summary:
    // how much of the catalogue is unlocked, as a count and a glowing bar in the title-tab line.
    this.deco = scene.add.graphics();
    this.panel.add(this.deco);
    const got = Object.keys((profile && profile.achievements) || {}).length;
    const total = Math.max(got, visibleAchievements(profile).length);
    this.summary = { ratio: total ? got / total : 0, x: this.w - 10 - 64, y: 4, w: 64, h: 7 };
    const txt = `${got}/${total}`;
    const sumText = new NeonText(scene, theme, this.summary.x - 6 - measureText(txt), 4, txt, { color: 'amber', outline: 'none' });
    this.panel.add(sumText);
    const caps = new Keycaps(scene, theme, { x: sumText.x - 14, y: 2, align: 'right', color: 'amber',
      items: [{ keys: ['←', '→'], label: 'PAGE' }] });
    this.panel.add(caps);
    this.unbindDeco = theme.bind((pal) => this._paintDeco(pal));
    this._paint();
  }

  /** Painted under the row texts; repainted on page turns and palette swaps. */
  _paintDeco(pal) {
    const g = this.deco;
    const L = this._layout;
    if (!g || !L) return;
    g.clear();
    paintGlowBar(g, pal, this.summary, this.summary.ratio, 'amber', { segments: 0, glow: 0.6 });
    const left = 12;
    const right = this.w - 12;
    const byKey = new Map(L.items.map((it) => [it.key, it]));
    for (const r of L.rows) {
      if (r.kind === 'header') {
        paintRule(g, left + measureText(r.label) + 6, right, r.y + 4, pal.amber, 0.7);
        continue;
      }
      if (r.done) {
        // earned: lime wash, a bright edge and a tick beside the count
        g.fillStyle(pal.lime, 0.07);
        g.fillRect(8, r.y - 2, this.w - 16, 12);
        g.fillStyle(pal.lime, 0.9);
        g.fillRect(8, r.y - 2, 2, 12);
        const p = byKey.get(`p-${r.id}`);
        if (p) paintPattern(g, p.x - 9, r.y + 1, CHECK_GLYPH, pal.lime, 1);
      } else {
        // pending: a thin rail under the row with its progress filled in
        const rw = right - left;
        g.fillStyle(pal.cyan, 0.12);
        g.fillRect(left, r.y + 10, rw, 1);
        const fw = Math.round(rw * Math.min(1, Math.max(0, r.ratio || 0)));
        if (fw > 0) {
          g.fillStyle(pal.cyan, 0.75);
          g.fillRect(left, r.y + 10, fw, 1);
          g.fillStyle(pal.cyan, 0.2);
          g.fillRect(left, r.y + 11, fw, 1);
          g.fillStyle(pal.text, 0.9);
          g.fillRect(left + fw - 1, r.y + 10, 1, 1);
        }
      }
    }
    // pager: one square per page, the current one lit
    const pages = L.pages;
    const px = 12 + measureText(L.footer.text) + 10;
    for (let i = 0; i < pages; i++) {
      const on = i === L.page;
      const x = px + i * 8;
      const y = L.footer.y + 1;
      if (on) glowRectPx(g, x, y, 5, 5, pal.magenta, 1);
      g.fillStyle(pal.magenta, on ? 1 : 0.3);
      g.fillRect(x, y, 5, 5);
      if (!on) { g.fillStyle(pal.bg, 1); g.fillRect(x + 1, y + 1, 3, 3); }
    }
  }

  /** Draw the current page, replacing whatever was drawn for the previous one. */
  _paint() {
    for (const t of this.rows) t.destroy();
    this.rows = [];
    const layout = achievementsLayout({
      profile: this.scene.registry.get(REG.PROFILE) || this.profile,
      page: this.page,
      biomeCount: this.biomeCount,
    });
    this.page = layout.page;
    this.pages = layout.pages;
    this._layout = layout;
    const byY = new Map();
    for (const it of layout.items) {
      // Same rule as ProfileView: layout boxes are top-left, so never re-apply an origin.
      const t = new NeonText(this.scene, this.theme, it.x, it.y, it.text, {
        color: it.color, outline: it.outline, alpha: it.alpha,
      });
      this.panel.add(t);
      this.rows.push(t);
      if (!byY.has(it.y)) byY.set(it.y, []);
      byY.get(it.y).push(t);
    }
    if (this.deco) this._paintDeco(this.theme.pal);
    // each page deals its rows in, top to bottom
    staggerAlpha(this.scene, [...byY.keys()].sort((a, b) => a - b).map((y) => byY.get(y)), { start: this._dealt ? 0 : 120, step: 16 });
    this._dealt = true;
  }

  /** Move by `delta` pages, clamped, and repaint only when the page actually changes. */
  _turn(delta) {
    const next = Math.max(0,Math.min(this.pages - 1,this.page + delta));
    if (next === this.page) return false;
    this.page = next;
    this._paint();
    uiSfx(this.scene, 'uiMove');
    return true;
  }

  handleAction(action) {
    if (action === 'cancel') {
      this.close();
      return true;
    }
    if (action === 'left') return this._turn(-1);
    if (action === 'right') return this._turn(1);
    // Confirm is a no-op on a read-only grid rather than closing it: a player paging with confirm would
    // otherwise be ejected from the screen they were reading.
    if (action === 'confirm') return true;
    return true;
  }

  destroy() {
    if (this.unbindDeco) this.unbindDeco();
    this.unbindDeco = null;
    super.destroy();
  }
}

/**
 * Shop/Titles row state -> how it looks. Returns null for rows with no state chip. The wording of the state
 * stays in the layout (state is text, not only colour); this only chooses the dressing:
 *   EQUIPPED  solid lime chip, lime row wash          (clearly "on")
 *   EQUIP     outline lime chip, lime dot in the gutter  (owned)
 *   price     bright amber chip with a shard           (buy it now)
 *   too dear  dim amber chip                           (unlocked, cannot afford)
 *   LVL n     dim chip with a padlock                  (locked)
 */
function chipStyle(r) {
  switch (r.kind) {
    case 'item':
    case 'default':
      if (r.equipped) return { mode: 'solid', key: 'lime', text: 'lime', alpha: 1 };
      if (r.owned || r.kind === 'default') return { mode: 'outline', key: 'lime', text: 'lime', alpha: 1 };
      if (r.locked || r.state === 'ACHIEVEMENT') return { mode: 'dim', key: 'text', text: 'text', alpha: 0.55, glyph: 'lock' };
      if (r.disabled) return { mode: 'dim', key: 'amber', text: 'amber', alpha: 0.6, glyph: 'shard' };
      return { mode: 'bright', key: 'amber', text: 'amber', alpha: 1, glyph: 'shard' };
    case 'boost':
      return r.locked ? { mode: 'dim', key: 'text', text: 'text', alpha: 0.55, glyph: 'lock' } : null;
    case 'upgradeItem':
      if (!r.state) return null;
      return r.disabled ? { mode: 'dim', key: 'amber', text: 'amber', alpha: 0.6, glyph: 'shard' }
        : { mode: 'bright', key: 'amber', text: 'amber', alpha: 1, glyph: 'shard' };
    case 'gym':
      return r.disabled ? { mode: 'dim', key: 'text', text: 'text', alpha: 0.55, glyph: 'lock' }
        : String(r.state).startsWith('LOCKED') ? { mode: 'bright', key: 'amber', text: 'amber', alpha: 1, glyph: 'lock' }
          : { mode: 'outline', key: 'lime', text: 'lime', alpha: 1 };
    case 'upgradeLink':
    case 'gymSetupLink':
      return { mode: 'outline', key: 'lime', text: 'lime', alpha: 1 };
    default:
      return null;
  }
}

/**
 * Give MenuList items (aligned 1:1 with the layout rows) the colours their state chips need: the state word
 * wears the chip's colour, equipped labels wear lime, section headers become bright headings.
 * @param {object[]} items @param {object[]} rows
 * @returns {object[]} items
 */
function dressShopItems(items, rows) {
  items.forEach((it, i) => {
    const r = rows[i];
    if (!r) return;
    if (r.kind === 'header') { it.heading = true; it.color = 'magenta'; return; }
    const st = chipStyle(r);
    if (st && it.sub) { it.subColor = st.text; it.subAlpha = st.alpha; }
    if (r.equipped) it.tint = 'lime';
  });
  return items;
}

/** Number of catalogue pages the pager dots show (ShopLayout.SHOP_PAGES). */
const SHOP_PAGE_COUNT = 4;

/**
 * Paint the shop/titles decoration (under the MenuList text): state chips, equipped washes, owned dots,
 * section rules, the shard glyph by BANK and the page pips.
 * @param {Phaser.GameObjects.Graphics} g @param {Object<string,number>} pal
 * @param {{rows:object[], rowH:number, band:{x:number,y:number,w:number}}} layout
 */
function paintShopDeco(g, pal, layout) {
  const { band, rowH } = layout;
  const edge = band.x + band.w - 8; // where MenuList right-aligns sub text
  for (const r of layout.rows) {
    if (r.kind === 'head') {
      const t = r.texts && r.texts[0];
      if (t) paintPattern(g, t.x - 9, r.y + 1, SHARD_GLYPH, pal.amber, 1);
      continue;
    }
    if (r.kind === 'header') {
      paintRule(g, band.x + 14 + measureText(r.label) + 6, edge, r.y + 5, pal.magenta, 0.7);
      continue;
    }
    if (r.equipped) {
      g.fillStyle(pal.lime, 0.09);
      g.fillRect(band.x, r.y, band.w, rowH - 1);
      g.fillStyle(pal.lime, 0.85);
      g.fillRect(band.x, r.y, 2, rowH - 1);
    } else if (r.owned) {
      g.fillStyle(pal.lime, 0.8);
      g.fillRect(band.x + 10, r.y + 4, 2, 2);
    }
    if (r.kind === 'page') {
      const w = SHOP_PAGE_COUNT * 7 - 2;
      const x0 = edge - measureText(r.state) - 8 - w;
      for (let i = 0; i < SHOP_PAGE_COUNT; i++) {
        const on = i === r.page;
        g.fillStyle(pal.magenta, on ? 1 : 0.3);
        g.fillRect(x0 + i * 7, r.y + 3, 5, 4);
      }
      continue;
    }
    const st = chipStyle(r);
    if (st && r.state) paintStateChip(g, pal, { right: edge + 3, y: r.y + 1, textW: measureText(String(r.state)), colorKey: st.key, mode: st.mode, glyph: st.glyph });
  }
}

/**
 * W4: SHARD SHOP — buy cosmetics and equip them, and set the pre-run boost loadout.
 *
 * One action per row ("get me this") rather than a BUY then EQUIP dance: if the player owns it, selecting
 * equips it; if they can afford it, selecting buys and equips in one atomic save. Both paths go through
 * ProfileStore's pure functions, so the cannot-go-negative / cannot-double-buy rules are enforced in the
 * tested layer and this view only chooses which rule to invoke.
 *
 * Boosts live here too because they are the same shape of decision (a spend, then a persistent choice) and
 * because the spec makes them "chosen on a pre-run loadout" — this is that loadout screen.
 */
export class ShopView extends View {
  /** @param {Phaser.Scene} scene @param {import('./Theme.js').Theme} theme @param {{onClose:function():void}} o */
  constructor(scene, theme, o) {
    const layout = shopLayout({ profile: scene.registry.get(REG.PROFILE), levels: (scene.registry.get(REG.CONTENT) || {}).progression, page: 0 });
    super(scene, theme, {
      w: layout.w, h: layout.h, title: 'SHARD SHOP', color: 'amber', onClose: o.onClose, y: 22, backLabel: 'BACK',
    });

    this.service = scene.registry.get(REG.PROGRESSION);
    this.store = (this.service && this.service.store) || null;

    // ONE MenuList for the whole panel: headers, item rows, boosts and the loadout line are items in the
    // same list, so they all share one row pitch and cannot be drawn over each other. Nothing else is
    // drawn into this panel except the frame and BACK.
    this.menu = null;
    // F4 fit: the catalogue is paged by slot (ShopLayout.SHOP_PAGES). The page row is the first selectable
    // row, so the shop opens with focus on "← TRAIL →" and left/right is the first thing a player tries.
    this.page = 0;
    this.upgradePage = false;
    this.gymSetupPage = false;
    // state chips, washes and rules live on one Graphics UNDER the list (added before any menu exists, so
    // every rebuilt menu lands above it); repainted from the current layout on every _build
    this.deco = scene.add.graphics();
    this.panel.add(this.deco);
    this._layout = null;
    this.unbindDeco = theme.bind((pal) => this._paintDeco(pal));
    this.hintRow = new Keycaps(scene, theme, { x: 12, y: this.h - 19, color: 'amber',
      items: [{ keys: ['←', '→'], label: 'PAGE' }, { keys: ['ENTER'], label: 'BUY / EQUIP' }] });
    this.panel.add(this.hintRow);
    this._build();
  }

  _paintDeco(pal) {
    if (!this.deco || !this._layout) return;
    this.deco.clear();
    paintShopDeco(this.deco, pal, this._layout);
  }

  _profile() {
    return this.scene.registry.get(REG.PROFILE) || {};
  }

  /** The panel's single source of truth: layout rows + menu items, rebuilt together every time. */
  _menuItems(layout) {
    if (this.gymSetupPage) return layout.rows.map((r) => {
      if (r.kind === 'gymSetupBack') return {kind:'action',label:r.label,
        onSelect:()=>this._showUpgrades()};
      if (r.kind === 'gymSetupChoice') return {
        kind:'choice',id:r.id,label:r.label,
        options:r.choices.map(n=>({value:n,label:r.id==='launchRisePxS'
          ? 'UP '+Math.abs(n) : String(n)})),
        get:()=>this._gymSetup()[r.id],
        set:v=>this._setGymOption(r.id,v),
      };
      if (r.kind === 'gymSetupStart') return {kind:'action',label:r.label,
        onSelect:()=>this.scene.startRun('bsod-gym',0,{gym:true})};
      return {kind:'static',label:r.label,disabled:true};
    });
    if (this.upgradePage) return layout.rows.map((r) => {
      if (r.kind === 'upgradeBack') return { kind: 'action', label: r.label, onSelect: () => this._showShop() };
      if (r.kind === 'upgradeToggle') return {
        kind: 'choice', label: r.label,
        options: [{ value: false, label: 'OFF' }, { value: true, label: 'ON' }],
        get: () => this._profile().upgradesEnabled === true,
        set: v => this._setUpgradeMode(v === true),
      };
      if (r.kind === 'gym') return {
        kind: 'action', id: r.id, label: r.label, sub: r.state,
        disabled: r.disabled, onSelect: () => this._chooseBsodGym(),
      };
      if (r.kind === 'gymSetupLink') return {
        kind:'action',id:r.id,label:r.label,sub:r.state,
        onSelect:()=>this._showGymSetup(),
      };
      if (r.kind === 'upgradeItem') return {
        kind: 'action', id: r.id, label: r.label, sub: r.state,
        disabled: r.disabled === true, onSelect: () => this._buyUpgrade(r.id),
      };
      return { kind: 'static', label: r.label, disabled: true };
    });
    return shopMenuItems(layout).map((m) => {
      if (m.rowKind === 'upgradeLink') return {
        kind: 'action', label: m.label, sub: m.sub, onSelect: () => this._showUpgrades(),
      };
      if (m.rowKind === 'page') {
        // Confirm or a click turns the page forward; left/right are handled in handleAction. An action
        // row, not a choice row: MenuList repaints a choice row after its setter runs, and the setter here
        // rebuilds the whole menu.
        return { kind: 'action', rowKind: 'page', label: m.label, sub: m.sub, disabled: false, onSelect: () => this._turnPage(1) };
      }
      if (m.rowKind === 'item') {
        return { kind: 'action', rowKind: 'item', id: m.id, label: m.label, sub: m.sub, disabled: m.disabled, onSelect: () => this._choose(m.id) };
      }
      if (m.rowKind === 'boost' && m.disabled) {
        // F3: not unlocked yet. Drawn with its unlock level, never focusable, never toggled.
        return { kind: 'action', label: m.label, boostId: m.boostId, sub: m.sub, disabled: true };
      }
      if (m.rowKind === 'boost') {
        return {
          kind: 'choice',
          label: m.label,
          // Carried so the built-game gate can find this row by id and read it back. Without it the row
          // is identified only by its label text, which makes the stale-toggle defect ungatable.
          boostId: m.boostId,
          options: [{ value: false, label: 'OFF' }, { value: true, label: 'ON' }],
          // Read the live profile: a `boosts` snapshot captured here goes stale the moment the toggle is set.
          get: () => (this._profile().boosts || {})[m.boostId] === true,
          set: (v) => this._setBoost(m.boostId, Boolean(v)),
        };
      }
      // Headings and the BANK/loadout lines: real rows in the list for geometry, never selectable.
      return { kind: 'static', label: m.label, disabled: true };
    });
  }

  _levels() {
    return (this.scene.registry.get(REG.CONTENT) || {}).progression;
  }

  _build() {
    const layout = this.gymSetupPage ? gymSetupLayout({profile:this._profile()})
      : this.upgradePage ? upgradeShopLayout({ profile: this._profile() })
      : shopLayout({ profile: this._profile(), levels: this._levels(), page: this.page });
    // Only the ordinary Shop layout has a page index. Nested Gym setup
    // must preserve the last selected catalogue category for BACK navigation.
    if (!this.upgradePage && !this.gymSetupPage) this.page = layout.page;
    if (this.menu) { this.menu.destroy(); this.menu = null; }
    // The bank value is drawn outside the list (the list right-aligns only row state), so it has to be
    // torn down with it or every rebuild would stack another "BANK n" on the same pixel.
    for (const t of (this.bankTexts || [])) t.destroy();
    this.bankTexts = [];
    const band = layout.band;
    this._layout = layout;
    this._paintDeco(this.theme.pal);
    this.menu = new MenuList(this.scene, this.theme, {
      x: band.x, y: band.y, w: band.w, rowH: layout.rowH,
      items: dressShopItems(this._menuItems(layout), layout.rows), color: 'lime', parent: this.panel,
    });
    if (!this._revealed) { this._revealed = true; staggerMenuRows(this.scene, this.menu); }
    // The BANK line is a right-aligned value in the list, not a separate static string, so it refreshes
    // with everything else. MenuList would draw it as a label, so it is rendered beside the list at the
    // head row's own y.
    const head = layout.rows.find((r) => r.kind === 'head');
    if (head && head.texts) {
      for (const t of head.texts) {
        const txt = new NeonText(this.scene, this.theme, t.x, t.y, t.text, { color: t.color });
        this.panel.add(txt);
        this.bankTexts.push(txt);
      }
    }
  }

  /** Change only this shop panel, keeping the title/profile ownership and Back semantics. */
  _showUpgrades() {
    this.gymSetupPage = false;
    this.upgradePage = true;
    this._build();
  }

  /** Invisible until five legitimate uninterrupted Bluffs IN THE GYM. */
  _showGymSetup() {
    if (this._profile().bsodGym?.advanced !== true) return;
    this.upgradePage = false;
    this.gymSetupPage = true;
    this._build();
  }

  _gymSetup() {
    return this._profile().bsodGym?.setup || {};
  }

  _setGymOption(key, value) {
    const result = this.store?.setGymSetup({...this._gymSetup(),[key]:value});
    if (result?.ok) this.scene.registry.set(REG.PROFILE,result.profile);
  }

  _showShop() {
    this.gymSetupPage = false;
    this.upgradePage = false;
    this._build();
  }

  _setUpgradeMode(on) {
    const prof = this._profile();
    const next = { ...prof, upgradesEnabled: !!on };
    try {
      this.scene.registry.set(REG.PROFILE, this.store ? this.store.save(next) : next);
    } catch {
      this.scene.registry.set(REG.PROFILE, next);
    }
    // MenuList._adjust refreshes its own choice after the setter returns.
    // Do NOT destroy that same menu mid-setter: keyboard/gamepad controls keep
    // their focus and the display updates via the live get() callback.
  }

  _chooseBsodGym() {
    if (this._profile().bsodGym?.owned === true) {
      // The TitleScene owns this route. Gym sessions are never official or ranked.
      this.scene.startRun('bsod-gym', 0, { gym: true });
      return;
    }
    const tx = this.store?.buyBsodGym();
    if (tx?.ok) {
      this.scene.registry.set(REG.PROFILE, tx.profile);
      uiSfx(this.scene, 'uiSelect', { pitch: 1.3 });
    } else {
      uiSfx(this.scene, 'uiBack');
    }
    this._refresh();
  }

  _buyUpgrade(id) {
    const tx = this.store?.buyUpgrade(id);
    if (tx?.ok) {
      this.scene.registry.set(REG.PROFILE, tx.profile);
      uiSfx(this.scene, 'uiSelect', { pitch: 1.3 });
    } else {
      uiSfx(this.scene, 'uiBack');
    }
    this._refresh();
  }

  /**
   * Buy-or-equip, atomically. A refused purchase leaves the profile untouched: `purchase` returns the same
   * object by identity when it declines, which is how that is detected without duplicating its rules here.
   *
   * Selecting the row that is already EQUIPPED takes it off: the slot goes back to DEFAULT (SHOP-3). That
   * is the only way back to the default look, so it is the same one-action-per-row rule run in reverse.
   */
  _choose(id) {
    const prof = this._profile();
    let next = prof;
    try {
      const item = shopItem(id);
      const eq = (prof.equipped && typeof prof.equipped === 'object') ? prof.equipped : {};
      if (item && isOwned(prof, id) && (eq[item.slot] === item.value || eq[item.slot] === id)) {
        uiSfx(this.scene, 'uiBack');
        next = unequip(prof, item.slot);
        this.scene.registry.set(REG.PROFILE, this.store ? this.store.save(next) : next);
        this._refresh();
        return;
      }
      if (!isOwned(prof, id)) {
        const bought = purchase(prof, id);
        if (bought === prof) { uiSfx(this.scene, 'uiBack'); return; }
        next = bought;
        uiSfx(this.scene, 'uiSelect', { pitch: 1.4 });
      } else {
        uiSfx(this.scene, 'uiSelect');
      }
      next = equip(next, id);
      this.scene.registry.set(REG.PROFILE, this.store ? this.store.save(next) : next);
    } catch (e) {
      // A denied storage write must not break the shop; the in-memory choice still shows this session.
      this.scene.registry.set(REG.PROFILE, next);
    }
    this._refresh();
  }

  _setBoost(id, on) {
    const prof = this._profile();
    const next = { ...prof, boosts: { ...(prof.boosts || {}), [id]: on } };
    try {
      this.scene.registry.set(REG.PROFILE, this.store ? this.store.save(next) : next);
    } catch (e) {
      this.scene.registry.set(REG.PROFILE, next);
    }
  }

  /**
   * Rebuild the whole list after a purchase or a boost toggle.
   *
   * This used to patch only the menu's rows, which is why the bank line, the owned/equipped states and the
   * loadout summary went stale (CC Friday's defect 2). Rebuilding from the layout means every visible
   * string comes from the same profile read, so nothing can lag behind.
   */
  _refresh() {
    const keep = this.menu ? this.menu.selected : 0;
    // SHOP-5: an equipped (or removed) theme recolours the UI, so the scene's Theme re-reads the profile
    // and repaints every bound painter, the screen under the shop included.
    if (this.theme && typeof this.theme.refresh === 'function') this.theme.refresh();
    this._build();
    if (this.menu) this.menu.setSelected(Math.min(keep, this.menu.items.length - 1), true);
  }

  /**
   * Show the next (dir 1) or previous (dir -1) slot page, wrapping. Focus stays on the page row when it was
   * there; from an item row it stays on the same row index if the new page has an item there, else it goes
   * to the page row, so focus never lands on a heading.
   */
  _turnPage(dir) {
    const was = this.menu ? this.menu.items[this.menu.selected] : null;
    const keep = this.menu ? this.menu.selected : 0;
    this.page += dir < 0 ? -1 : 1;
    this._build();
    if (!this.menu) return;
    const pageIdx = this.menu.items.findIndex((i) => i.rowKind === 'page');
    const at = this.menu.items[keep];
    const target = (was && was.rowKind === 'item' && at && at.rowKind === 'item' && !at.disabled) ? keep : pageIdx;
    this.menu.setSelected(Math.max(0, target), true);
    uiSfx(this.scene, 'uiMove');
  }

  handleAction(action) {
    if (action === 'cancel') { this.close(); return true; }
    if (action === 'left' || action === 'right') {
      // The slot IS the page, so left/right on the page row or on any catalogue row turns it. On a boost
      // row they still toggle the boost (MenuList's own choice handling).
      const cur = this.menu && this.menu.items[this.menu.selected];
      if (cur && (cur.rowKind === 'page' || cur.rowKind === 'item')) {
        this._turnPage(action === 'left' ? -1 : 1);
        return true;
      }
    }
    return this.menu.handleAction(action);
  }

  destroy() {
    if (this.unbindDeco) this.unbindDeco();
    this.unbindDeco = null;
    for (const t of this.bankTexts || []) t.destroy();
    this.bankTexts = [];
    super.destroy();
  }
}

/**
 * SHOP-2: TITLES — buy (Static Rider) and equip titles, or go back to the level title.
 *
 * Same one-action-per-row rule as the shop: an owned title equips, an affordable one buys and equips in one
 * atomic save, EQUIPPED (or the DEFAULT row) puts the slot back to DEFAULT. Achievement titles show
 * ACHIEVEMENT until earned and cannot be selected. Opened from the Profile view; BACK returns there.
 */
export class TitlesView extends View {
  /** @param {Phaser.Scene} scene @param {import('./Theme.js').Theme} theme @param {{onClose:function():void}} o */
  constructor(scene, theme, o) {
    const layout = titlesLayout({ profile: scene.registry.get(REG.PROFILE), levels: (scene.registry.get(REG.CONTENT) || {}).progression });
    super(scene, theme, { w: layout.w, h: layout.h, title: 'TITLES', color: 'lime', onClose: o.onClose, y: 40, backLabel: 'BACK' });
    const service = scene.registry.get(REG.PROGRESSION);
    this.store = (service && service.store) || null;
    this.menu = null;
    this.bankTexts = [];
    this.deco = scene.add.graphics();
    this.panel.add(this.deco);
    this._layout = null;
    this.unbindDeco = theme.bind((pal) => this._paintDeco(pal));
    this.hintRow = new Keycaps(scene, theme, { x: 12, y: this.h - 19, color: 'lime',
      items: [{ keys: ['ENTER'], label: 'EQUIP' }] });
    this.panel.add(this.hintRow);
    this._build();
  }

  _paintDeco(pal) {
    if (!this.deco || !this._layout) return;
    this.deco.clear();
    paintShopDeco(this.deco, pal, this._layout);
  }

  _profile() {
    return this.scene.registry.get(REG.PROFILE) || {};
  }

  _build() {
    const layout = titlesLayout({ profile: this._profile(), levels: (this.scene.registry.get(REG.CONTENT) || {}).progression });
    if (this.menu) { this.menu.destroy(); this.menu = null; }
    for (const t of this.bankTexts) t.destroy();
    this.bankTexts = [];
    const items = dressShopItems(titlesMenuItems(layout).map((m) => (m.kind === 'action'
      ? { ...m, onSelect: () => this._choose(m.id) }
      : { kind: 'static', label: m.label, disabled: true })), layout.rows);
    const band = layout.band;
    this._layout = layout;
    this._paintDeco(this.theme.pal);
    this.menu = new MenuList(this.scene, this.theme, {
      x: band.x, y: band.y, w: band.w, rowH: layout.rowH, items, color: 'lime', parent: this.panel,
    });
    const head = layout.rows.find((r) => r.kind === 'head');
    for (const t of (head && head.texts) || []) {
      const txt = new NeonText(this.scene, this.theme, t.x, t.y, t.text, { color: t.color });
      this.panel.add(txt);
      this.bankTexts.push(txt);
    }
  }

  _save(next) {
    try {
      this.scene.registry.set(REG.PROFILE, this.store ? this.store.save(next) : next);
    } catch (e) {
      this.scene.registry.set(REG.PROFILE, next);
    }
  }

  /** Buy-or-equip a title, or return the slot to DEFAULT. Atomic: a refused purchase changes nothing. */
  _choose(id) {
    const prof = this._profile();
    const eq = (prof.equipped && typeof prof.equipped === 'object') ? prof.equipped : {};
    if (id === 'default') {
      this._save(unequip(prof, 'title'));
      uiSfx(this.scene, 'uiBack');
      this._refresh();
      return;
    }
    const item = shopItem(id);
    if (!item || item.slot !== 'title') return;
    if (isOwned(prof, id) && (eq.title === item.value || eq.title === id)) {
      this._save(unequip(prof, 'title'));
      uiSfx(this.scene, 'uiBack');
      this._refresh();
      return;
    }
    let next = prof;
    if (!isOwned(prof, id)) {
      next = purchase(prof, id);
      if (next === prof) { uiSfx(this.scene, 'uiBack'); return; }
      uiSfx(this.scene, 'uiSelect', { pitch: 1.4 });
    }
    this._save(equip(next, id));
    this._refresh();
  }

  _refresh() {
    const keep = this.menu ? this.menu.selected : 0;
    this._build();
    if (this.menu) this.menu.setSelected(Math.min(keep, this.menu.items.length - 1), true);
  }

  handleAction(action) {
    if (action === 'cancel') { this.close(); return true; }
    return this.menu.handleAction(action);
  }

  destroy() {
    if (this.unbindDeco) this.unbindDeco();
    this.unbindDeco = null;
    for (const t of this.bankTexts || []) t.destroy();
    this.bankTexts = [];
    super.destroy();
  }
}

/** Two official Daily lanes, deliberately separate from ordinary purchased
 * upgrade mode. No extra entry is squeezed into the full six-row Title menu.
 */
export class DailyModesView extends View {
  constructor(scene,theme,o){
    super(scene,theme,{w:432,h:242,title:'DAILY CHALLENGE // TWO LANES',color:'magenta',onClose:o.onClose,
      hints:[{keys:['↑','↓'],label:'SELECT'},{keys:['ENTER'],label:'GO'}]});
    this.panel.add(new NeonText(scene,theme,14,29,'SAME DAILY SEED + RULE. SEPARATE RANKINGS.',{
      color:'cyan',outline:'none'}));
    this.panel.add(new NeonText(scene,theme,14,43,`DRAFT: ${DRAFT_BUDGET} FREE CREDITS, REBUILD ANYTIME`,{
      color:'text',outline:'none'}));
    // Each lane is a card: a framed slot in its own colour behind the row, with a lane number tab. Painted
    // before the list so the cursor and labels sit on top.
    const LANES=[['lime','01'],['magenta','02'],['cyan','03'],['amber','04']];
    this.cards=scene.add.graphics();
    this.panel.add(this.cards);
    this.unbindCards=theme.bind(pal=>{
      const g=this.cards;
      g.clear();
      LANES.forEach(([k,n],i)=>{
        const y=62+i*31+2,w=408,h=26,x=12;
        g.fillStyle(pal[k],0.05);g.fillRect(x,y,w,h);
        strokeRectPx(g,x,y,w,h,pal[k],0.4);
        g.fillStyle(pal[k],0.8);g.fillRect(x+w-3,y+1,2,h-2);
        // corner notch: a bright pixel at each end of the top edge
        g.fillStyle(pal.text,0.8);g.fillRect(x,y,1,1);g.fillRect(x+w-1,y,1,1);
      });
    });
    this.menu=new MenuList(scene,theme,{x:12,y:62,w:408,rowH:31,parent:this.panel,items:[
      {kind:'action',label:'DAILY CLASSIC',color:'lime',sub:'NO UPGRADES',tint:'lime',onSelect:o.onClassic},
      {kind:'action',label:'DAILY DRAFT',color:'magenta',sub:'EQUAL-BUDGET BUILDS',tint:'magenta',onSelect:o.onDraft},
      {kind:'action',label:'BUILD / REBUILD DRAFT',color:'cyan',sub:'FREE - NO SHARDS',tint:'cyan',onSelect:o.onEdit},
      {kind:'action',label:'DAILY DRAFT BOARD',color:'amber',sub:'TODAY ONLY',tint:'amber',onSelect:o.onBoard},
    ]});
    this.menu.refresh();
    staggerMenuRows(scene,this.menu);
  }
  destroy(){
    this.unbindCards?.();this.unbindCards=null;
    super.destroy();
  }
  handleAction(action){
    if(action==='cancel'){this.close();return true;}
    return this.menu.handleAction(action);
  }
}

/** Every actual game upgrade (ten in rules v2), priced by the same cumulative curve but
 * purchased only in non-transferable Draft credits, never profile BANK.
 * Keyboard/gamepad: Up/Down choose, Left/Right remove/add, Enter add.
 * Pointer: independent -/+ buttons on each row.
 */
export class DailyDraftEditorView extends View {
  constructor(scene,theme,o){
    super(scene,theme,{w:440,h:248,title:'DAILY DRAFT // BUILD A SLED',color:'cyan',onClose:o.onClose,y:10});
    this.store=scene.registry.get(REG.PROGRESSION)?.store;
    this.onPlay=o.onPlay;
    this.selected=0;
    this.itemRows=[];
    // Under everything else: the budget gauge, the selected row's band and each row's rank pips.
    this.deco=scene.add.graphics();
    this.panel.add(this.deco);
    this.unbindDeco=theme.bind(()=>this._paintDeco());
    this.remaining=new NeonText(scene,theme,13,25,'',{color:'lime'});
    this.panel.add(this.remaining);
    this.errorText=new NeonText(scene,theme,13,36,'LEFT/RIGHT ADJUST RANKS - NO SHARDS SPENT',{
      color:'text',outline:'none'});
    this.panel.add(this.errorText);
    DRAFT_UPGRADES.forEach((spec,i)=>{
      const y=this._rowY(i);
      const name=new NeonText(scene,theme,14,y,spec.label,{color:'text'});
      const value=new NeonText(scene,theme,290,y,'',{anchor:'right',color:'cyan'});
      const minus=new Button(scene,theme,{x:300,y:y-4,w:26,h:15,label:'-',color:'magenta',
        onClick:()=>this._adjust(i,-1)});
      const plus=new Button(scene,theme,{x:336,y:y-4,w:26,h:15,label:'+',color:'lime',
        onClick:()=>this._adjust(i,1)});
      this.panel.add(name);this.panel.add(value);this.panel.add(minus);this.panel.add(plus);
      this.itemRows.push({name,value,minus,plus,id:spec.id});
    });
    this.resetBtn=new Button(scene,theme,{x:14,y:204,w:96,h:17,label:'RESET DRAFT',color:'amber',
      onClick:()=>this._reset()});
    this.playBtn=new Button(scene,theme,{x:134,y:204,w:108,h:17,label:'PLAY DRAFT',color:'lime',
      onClick:()=>this.onPlay()});
    this.panel.add(this.resetBtn);this.panel.add(this.playBtn);
    this._paint();
  }
  /** Row baseline: 19 px apart while seven fit; tighter (>= 15 px) so ten rows end above the buttons at 204. */
  _rowY(i){
    const gap=Math.max(15,Math.min(19,Math.floor(135/Math.max(1,DRAFT_UPGRADES.length-1))));
    return 51+i*gap;
  }
  _ranks(){return this.store?.profile?.dailyDraft?.ranks||{};}
  _adjust(i,delta){
    const id=this.itemRows[i]?.id;
    if(!id)return;
    const changed=changeDraftRank(this._ranks(),id,delta);
    if(!changed.ok){
      this.errorText.setText(changed.reason==='over-budget'?'DRAFT LIMIT REACHED - REMOVE A RANK FIRST':'MINIMUM RANK 0');
      this.errorText.setColorKey('amber');return;
    }
    const stored=this.store?.setDailyDraftRanks(changed.ranks);
    if(!stored?.ok){this.errorText.setText('COULD NOT SAVE DRAFT');this.errorText.setColorKey('magenta');return;}
    this.scene.registry.set(REG.PROFILE,stored.profile);
    this.errorText.setText('DRAFT SAVED - YOU MAY REBUILD AT ANY TIME');
    this.errorText.setColorKey('cyan');
    uiSfx(this.scene,'uiSelect');
    this._paint();
  }
  _reset(){
    const result=this.store?.setDailyDraftRanks(sanitizeDraftRanks({}));
    if(!result?.ok){this.errorText.setText('COULD NOT RESET DRAFT');return;}
    this.scene.registry.set(REG.PROFILE,result.profile);
    this.errorText.setText('DRAFT RESET - ALL CREDITS RETURNED');
    this._paint();
  }
  _paint(){
    const ranks=this._ranks();
    this.remaining.setText(`DRAFT ${DRAFT_BUDGET}  SPENT ${draftCost(ranks)}  LEFT ${DRAFT_BUDGET-draftCost(ranks)}`);
    this.itemRows.forEach((row,i)=>{
      row.name.setColorKey(i===this.selected?'lime':'text');
      row.value.setText(`R${ranks[row.id]||0}`);
    });
    // Mouse and keyboard/gamepad deserve the same visible selection cue.
    this.resetBtn.setHover(this.selected===7);
    this.playBtn.setHover(this.selected===8);
    this.back.setHover(this.selected===9);
    this._paintDeco();
  }
  _paintDeco(){
    const g=this.deco;
    if(!g||!this.itemRows.length)return;
    const pal=this.theme.pal;
    const ranks=this._ranks();
    g.clear();
    const spent=draftCost(ranks);
    paintGlowBar(g,pal,{x:230,y:26,w:196,h:7},DRAFT_BUDGET>0?spent/DRAFT_BUDGET:0,spent>=DRAFT_BUDGET?'amber':'lime',{segments:10,glow:0.6});
    this.itemRows.forEach((row,i)=>{
      const y=this._rowY(i);
      if(i===this.selected){
        g.fillStyle(pal.lime,0.1);g.fillRect(10,y-4,356,15);
        g.fillStyle(pal.lime,1);g.fillRect(10,y-4,2,15);
      }
      const r=Math.min(8,ranks[row.id]||0);
      for(let k=0;k<8;k++){
        const on=k<r;
        const x=176+k*9;
        if(on){glowRectPx(g,x,y+1,6,6,pal.cyan,0.8);}
        g.fillStyle(pal.cyan,on?1:0.16);g.fillRect(x,y+1,6,6);
        if(!on){g.fillStyle(pal.bg,1);g.fillRect(x+1,y+2,4,4);}
      }
    });
  }
  destroy(){
    this.unbindDeco?.();this.unbindDeco=null;
    super.destroy();
  }
  handleAction(action){
    if(action==='cancel'){this.close();return true;}
    if(action==='up'||action==='down'){
      this.selected=(this.selected+(action==='up'?-1:1)+10)%10;
      this._paint();uiSfx(this.scene,'uiMove');return true;
    }
    if(this.selected<7 && (action==='left'||action==='right'||action==='confirm')){
      this._adjust(this.selected,action==='left'?-1:1);return true;
    }
    if(action==='confirm'){
      if(this.selected===7)this._reset();
      else if(this.selected===8)this.onPlay();
      else this.close();
      return true;
    }
    return true;
  }
}


/** Today's separate Daily Draft top ten. Classic and normal modded entries
 * are explicitly excluded by the central Ranking.isOfficialDaily predicate.
 * Players can change their Draft allocation without touching past entries.
 */
export class DailyDraftLeaderboardView extends View {
  constructor(scene,theme,o){
    super(scene,theme,{w:440,h:202,title:"DAILY DRAFT // TODAY'S TOP 10",color:'amber',onClose:o.onClose});
    this.highlightId=o.highlightId;
    this.board=new LeaderboardTable(scene,theme,{x:12,y:25,w:416,entries:null,parent:this.panel});
    this.panel.add(new NeonText(scene,theme,12,180,`RULES V${DRAFT_RULES_VERSION}  BUDGET ${DRAFT_BUDGET}  CLASSIC EXCLUDED`,{
      color:'cyan',outline:'none'}));
    this.loadToken=0;
    this._load();
  }
  _load(){
    const token=++this.loadToken;
    const store=this.scene.registry.get(REG.SAVE_STORE);
    Promise.resolve(store?.getDailyDraftLeaderboard?.(10,new Date())||[])
      .then(rows=>{
        if(!this.alive||token!==this.loadToken)return;
        this.board.setEntries(rows||[],this.highlightId,{
          title:'NO DRAFT RUNS TODAY',sub:'PLAY DAILY DRAFT, THEN ENTER INITIALS',
        });
      }).catch(()=>{
        if(this.alive&&token===this.loadToken)this.board.setEntries([]);
      });
  }
}# Bitstream Bluffs - Architecture Contract

Source of truth for the game: `docs/DESIGN-DOC.md`. This file is the source of truth for **how the pieces connect**.
Four engineers work in parallel on disjoint files. **Public signatures (class/function names, method params, event
names and payload shapes, data shapes, registry keys) are a contract.** If you must change one, edit this file and
the stub's JSDoc in the same change and tell the others in your hand-off. Additive changes (new optional fields, new
methods) are fine. Everything is plain JS ES modules + JSDoc; Phaser 3.90, Matter, Vite.

The legacy implementation in `js/` is untouched and unrelated; do not import from it.

## 2026-11-23 owner-approved production AirBrake — SIM9 release plan

**Marvin explicitly ratified the tested 60% AirBrake horizontal speed loss** with
its existing upward kick unchanged: “I absolutely authorize that. It was a
huge improvement over the original.” This supersedes the earlier experimental
numeric-feel gate in #247 / PR #248. Unlike a parachute, the AirBrake gives
exactly one immediate deceleration kick and one upward impulse per true airtime,
rearming only after physical ground contact. There is NO continuing AirBrake
lift, gravity reduction or descent damping. The vertical kick uses the original
40% paid-speed budget at a 1.5 factor with an upward cap, even as horizontal
braking increases to 60%; extra braking is NOT exchanged for extra altitude.
Existing parachute and BSOD-driven wind remain unchanged. Variable-hop
release truncates only its own original jump; if a coyote-hop triggers in
the same substep OR in a later substep during the 90ms coyote window, it
cannot erase the separately paid AirBrake ascent. `airBrakeLiftProtected`
tracks that ownership across ticks until real terrain collision. A variable-height
Hop that fired BEFORE AirBrake is also releasable: the pre-brake upward Hop
velocity remains tracked separately from paid AirBrake ascent. A coyote Hop
that fires AFTER AirBrake is likewise releasable: `_protectedHopExtraVyPxS` records
ONLY the extra vertical velocity the Hop added atop the paid brake kick and
truncates that increment on release (including quad-drag attenuation), never
the brake. Both are SIM9 causal state fingerprinted in sled schema v3
alongside `airBrakeKickUsed`. The full physical one-shot accepts either an airborne held brake or a
first-substep `pressed.airBrake` edge that was released before the next fixed
input sample. A valid airborne press during physics hit-stop is retained by the
causal, fingerprinted Sled.airBrakePressPending latch and consumed on the next
controls step; contact and respawn clear it. The press edge cannot repeat on later substeps, and earns the
regular AirBrake trick on its one-tick `airBrakeKickPulse`, not after 250ms
holding an already-spent key. A physically paid kick on the same tick as touchdown
still receives its trick credit; two consecutive short real flights must not
lose a later kick because the UI tracker failed to observe an airborne frame.
Any touchdown-only paid kick under the ordinary minimum airtime is settled
immediately through the real RunScene / ScoreManager landing path with its
actual bounded tick airtime. This applies both to a kick on the touchdown tick
and to an airborne kick on an EARLIER tick in a short flight: the later touchdown
banks already-pending points without issuing a duplicate trick event. Within
each fixed simulation tick, `RunScene.simTick` captures genuine Matter
`Sled.endStep` touchdown frames in SUBSTEP ORDER, then applies their
TrickTracker-derived landing physics IN THE SAME Matter after-step callback,
before the next buffered Hop can relaunch. Applying spring and wobble after
all substeps would incorrectly mutate the new flight, so deferred contact
replay is expressly forbidden. Intermediate contact
frames use the real slope at their recorded contact position, NOT the slope
from the start of the fixed tick. The real BSOD Bluff tracker also receives
each physical touchdown in substep order before any final airborne update,
discarding former-flight canopy and paid AirBrake credit. Only a paid kick
AFTER the last contact can earn the next flight's near-miss bonus. The final
post-physics TrickTracker input only sees the unconsumed kick following the
most recent contact. No fake touchdown is generated by presentation state, and normal
runs without pending paid AirBrake points keep their ordinary one-frame
path. The final airborne frame uses only time AFTER the last physical contact
when starting its new flight; it cannot inherit the full fixed tick's
pre-touchdown duration. The tick-local ledger records each scaled Flow clock
step before its associated landing. At the terminal-outcome boundary, the
ledger commits real ScoreManager operations in that order on survival, including
shield-absorbed hazards. On a terminal collision the ledger advances Flow
without banking any same-tick landing or trick reward, preserving previously
banked points. Physical effects are never replayed. The actual pre-controls
BSOD gap sample determines whether the paid kick occurred in an armed approach;
a later approach cannot borrow an earlier kick.
A short physical landing cannot carry unbanked points into an unrelated
flight, receive a fake perfect-landing bonus (even under Stabilizer after
`resolveLanding`) or manufacture a new speed/spring boost on a tiny bump.
A sloppy micro-touch still applies the regular recovery speed/spin wobble
penalty; only its positive speed and spring rewards are suppressed.
The removable Hop-added ascent is damped by both quadratic drag and the SAME
per-substep Matter `frictionAir` as the actual sled velocity, AND scaled with
the same multiplicative vertical velocity penalties used by hazards or
sloppy-landing wobble, so releasing Hop cannot overcut paid AirBrake ascent. Hop release removes
at most the remaining upward
velocity, so gravity already spent on the ascent cannot turn a shortened Hop
into an instant downward impulse. If the sled is already descending, a late
Hop release leaves its positive downward velocity completely unchanged.
The AirBrake held-input state also does NOT block the normal crest snap after
its one-shot impulse has been used; only the actual kick tick gets an exemption.
This single-tick event is consumed before the replay
checkpoint but is STILL listed as causal (and fingerprinted in sled schema v3):
it can affect TrickTracker, BSOD bluff scoring and later progression. Do not
misclassify it as non-causal merely because the checkpoint normally sees zero.
During a near-wall Bitstream Bluff, the extra 40-point AirBrake bonus is earned
only by a NEW physically spent-speed kick while the approach is armed.
Attempts in vacuum or other no-payment conditions do NOT consume the one
physical kick; the first real later horizontal speed payment spends the
latch and emits exactly one trick pulse. The bonus is never earned by
holding or tapping AirBrake after its one-use latch is spent. Sled emits a
one-tick `airBrakeKickPulse` consumed and cleared in `RunScene.simTick` before
the replay checkpoint; durable bluff/score state is fingerprinted. The reduced-
order BSOD escape-envelope diagnostic uses the same one-shot `airBrakeKickStep`
and normal gravity, not obsolete continuous 800ms drag/gravity relief. The
simulation's approved default 4500px, 300px/s, 4px/s², and final 3000px / 18%
BSOD chase from SIM7 remains unchanged.

This change builds on the independent marker-prefetch SIM8 correction, so the
approved AirBrake lands as **SIM_REVISION 9**, not the historical conflicting
SIM7 number in old draft #248. The one-shot `airBrakeKickUsed` flag is causal
and belongs in sled fingerprint schema v3. Keep old SIM6/SIM7/SIM8 ruleset
archives immutable and preserve version-aware interfaces for the eventual public
release without pretending any pre-release old-player tapes exist. Source review,
real browser physics/replay tests and correct ruleset identity are required
before merging; this section records OWNER APPROVAL of behavior, not code
review approval or deployed status. Linked [[projects/truevox-bitstreambluffs/controls-tricks-and-upgrades]].

## 2026-11-23 SIM8 replay-determinism correction — BEST / DIED HERE marker reads

The #253 visual marker bug produced extra authoritative terrain chunks on repeated
runs because `BestMarker` and `LastDeathMarker` queried `TerrainGenerator.heightAt`
for positions up to 2600px ahead of the sled. That accessor may generate and
queue chunks, depending on the prior run's visible markers. The canonical
`joinedMarkerHeight(x, mesh.chunks)` read-only geometry interpolation now returns `NaN` until
that x is actually joined to the real Matter terrain mesh. Both presentation
markers defer placement, then display at the exact live terrain height. No
extra chunk generation may occur merely to render these markers; do not mask
causal terrain state or disable the markers. The old AirBrake tuning branch
(#248) is still independent and not merged by this correction.

This source change is **SIM_REVISION 8** because SIM7 had already shipped on
`main`, including the owner-approved Fast Approach / Soft Finish chase. The
SIM7 archive remains immutable; no historical SIM1–SIM7 playback support is
required before first public player release, but versioned replay interfaces
remain supported architecturally. #253 final review still requires independent
source review and real repeat-session/visual marker confirmation for this
exact main-based commit, not inherited approval from #248.

## CURRENT 2026-11-23 OWNER DECISION — production BSOD Fast Approach / Soft Finish

Owner explicitly approved **Fast Approach / Soft Finish as the normal game default**, not merely a trial. `BSOD_DEFAULTS` starts the authoritative deletion wall 4500px behind the sled collision edge, with 300px/s nominal starting speed and 4px/s² acceleration. Within the final 3000px, a smoothstep curve reduces its **actual collision-edge motion**, down to 82% of the current nominal speed at contact. This is not an animation-only delay, catch countdown, player-speed response or rubber-banding. Sync Level head start/acceleration attenuation and purchased BSOD grace continue to apply. This is an owner-approved causal change: SIM_REVISION **7**, new content-addressed ruleset, old SIM6 replay fixtures retained as historical evidence.

`BsodPursuit.wallSpeedPxS` remains the deterministic, fingerprinted **nominal** accelerating velocity; `state(sledLeftEdgeX, ...)` publishes the **actual eased** velocity to wind, warnings and time-to-impact. `RunScene` passes the real Matter left collision edge to `advance(stepMs, sledLeftEdgeX)` on every capped physics substep, so the edge that hits the rider is the edge that visually approaches. The normal production implementation is in `BsodPursuit` and MUST NOT be replaced by a QA monkeypatch. The opt-in `bsod-qa.html` retains moderate and buffered-strong comparison variants with the ending ease disabled; `soft` corresponds to the production behavior. The BSOD Gym uses the identical normal chase after its explicitly selected initial conditions.

## CURRENT 2026-11-18 OWNER CONTRACT — faithful BSOD Gym and nested 5x Gym-only Easter egg

## CURRENT 2026-11-18 OWNER CONTRACT — faithful BSOD Gym and nested 5x Gym-only Easter egg

**Marvin's direct decision (supersedes earlier assistant practice-only balancing):**
The BSOD Gym is **100% faithful to live-run gameplay once an attempt begins**.
It uses the actual player's active upgrades, earned canopy rank-12 requirement,
recharge formula, real Sync Level-dependent BSOD acceleration, ordinary
wind/atmosphere, boost/effect physics, and hazards. No practice-only fuel tank
or below-rank-12 refill, no reduced BSOD acceleration. The initial 200-shard
Gym price remains accepted for now. Only the **initial conditions**, the
lack of ranked/progression rewards, and the **consequence-free recovery** differ.

At first entry and at each retry, the Gym uses a repeatable fixed-seed
launch with selectable (post-unlock) **BSOD gap, forward-only initial wall
speed, rider launch height, forward velocity and upward velocity**.
`BsodPursuit.advance()` is NEVER overridden: within an attempt the wall
always moves strictly forward under exactly the same live acceleration.
No teleporting, reversal, wall cha-cha, or extra wind assistance is allowed
after release. The default initial setup is 460 px gap / 240 px/s wall,
260 px launch height / 280 px/s forward and -330 px/s upward rider velocity.
These are **initial conditions**, not changed movement rules. The values can
be tuned from automated tests without any owner approval of feel/balance.

**Fast repeated practice:** When caught, reconstruct deterministic initial
terrain, hazards, powerups and collected shard state at the same fixed launch,
restore the player's actually enabled initial boost loadout, clear all
attempt-local scores/combos/status, place the rider and wall, and freeze
the **whole gameplay simulation and run clock for 1000 real ms**. UIScene
shows a small `READY` cue; on expiry `GO` flashes and ordinary gameplay
resumes on the next frame. The pause menu stays functional during this
beat. This process never credits runs, shards, XP, mission completion,
achievements, or leaderboard entries.

**Matryoshka Easter egg:** Gym launch-configuration controls are completely
ABSENT from all player UI before **five successful scored BSOD Bluffs within
ONE uninterrupted airborne flight inside the GYM**. Specifically:

- Five Bluffs anywhere in the LIVE world **do NOT count** toward Gym setup.
- Five separated by landing, death or Gym reset **do NOT count**.
- A genuine 5x chain IN GYM unlocks setup exactly once via
  `ProfileStore.unlockGymSetup()`, safely persisted without XP/shards.
- Only THEN does the Shard Shop's existing Permanent Upgrades view gain a
  `GYM SETUP` row. Its nested five-choice page can change *bounded starting
  conditions* and enter practice. It is absent, not greyed out, before mastery.
- The one-time post-mastery `GYM SETUP UNLOCKED` notification is allowed;
  there are no advance tutorials, streak counters or spoilers.
- `bsodGym.advanced` and `bsodGym.setup` extend v1 profile shapes only
  after the Gym-specific milestone. Existing player profiles continue to
  deserialize unchanged; setup writes are atomically persisted and sanitized
  to physically forward-only values.

**Code ownership/verification contract:** `src/systems/BsodGym.js` owns
pure setup sanitization, preset options, forward-only placement and the
Gym-only mastery threshold. `RunScene` owns physics, the signed-relative
BSOD wind, 5x scoring gate, world reset and cooldown. `ProfileStore` owns
persistence. `ShopLayout` + `ShopView` own the hidden post-mastery menu;
`UIScene` owns READY/GO and one-time unlocked feedback. Events
`GYM_ATTEMPT_RESET {attempt,readyMs}`, `GYM_READY_GO {}` and
`GYM_SETUP_UNLOCKED {}` are additive.

The older dated passages farther down mentioning a 1500ms practice tank,
0.65px/s² Gym wall acceleration, or `0.68*full/sqrt(chain)` practice-only
refill are **historical development records, no longer active rules**.
Do not reintroduce those overrides. This is an owner decision, not
an invented Gal Friday balance change. Human audition and play-feel
testing are still pending; automated tests establish logic, not fun.

## 1. File ownership

| Owner | Files (all under `src/` unless noted) |
|---|---|
| **Foundation (frozen, change only additively)** | `main.js`, `events.js`, `constants.js`, `services.js`, `data/index.js`, `data/schemas.js`, `ARCHITECTURE.md`, root `index.html`, `tests/src/contract.test.js` |
| **Core-logic** (NO Phaser imports) | `systems/Rng.js`, `systems/TerrainGenerator.js`, `systems/ScoreManager.js`, `systems/TrickTracker.js`, `systems/SaveStore.js`, `systems/DailyPatch.js`, `data/chunks/*.json`, `data/terrainMods/*.json`, `tests/src/**` (except `contract.test.js`) |
| **Gameplay** | `scenes/RunScene.js`, `entities/*` (`Sled`, `TerrainMesh`, `Hazard`, `PowerUp`, `TrailParticles`, plus new ones), `systems/PhysicsTuner.js`, `data/hazards/*.json`, `data/powerups/*.json` |
| **Input/audio/glitch** | `systems/InputRouter.js`, `systems/VirtualPad.js`, `systems/AudioSynth.js`, `systems/GlitchDirector.js` (no Phaser imports), `shaders/glitch.frag`, `shaders/GlitchPipeline.js` |
| **UI** | `scenes/PreloadScene.js`, `TitleScene.js`, `UIScene.js`, `PauseScene.js`, `GameOverScene.js`, `data/palettes.json`, `ui/*` (`ui/Palette.js` exists and works; extend, don't rename) |

Rules: never edit a file you do not own (ask via the hand-off). New helper files are fine inside your own area
(e.g. gameplay may add `entities/Camera*.js`). New pure-logic helpers needed by two owners go in `systems/` and are
registered in the table by whoever creates them. Pure-logic modules **must not** import `phaser` (Jest cannot load
it) and must not use `import.meta`, `window`, or `Math.random`/`Date.now` for anything seed-dependent.

Terrain-mod JSON lives in `data/terrainMods/` (core-logic owns it because the generator places the zones; gameplay
reads `physics` from it at runtime).

## 2. Boot and scene flow

```
main.js (Phaser.Game, WEBGL, 480x270 FIT, matter autoUpdate:false, GlitchPipeline registered in postBoot)
  PreloadScene --createServices()--> TitleScene --start--> RunScene (+ UIScene launched in parallel)
                                                              | Esc            ^ resume
                                                              v                |
                                                         PauseScene (on top; RunScene paused)
  RunScene --crash--> RUN_END --> GameOverScene --Space/tap (instant retry, same seed)--> RunScene
  GameOverScene / PauseScene(quit) --> TitleScene
```

* `PreloadScene.create()` calls `createServices(game)` then `scene.start(TITLE)`.
* `TitleScene` writes the chosen seed to `registry REG.SEED`, calls `audio.unlock()` on first input, starts `RUN`.
* `RunScene.create()` launches `UIScene`; on crash it stores the record in `REG.LAST_RECORD`, emits `RUN_END`, waits
  <= `TIMING.crashToGameOverMs`, then `scene.start(GAME_OVER)` (this also shuts RunScene down; it must stop `UIScene`).
* Pause: RunScene reacts to `pad.pressed.pause`: emit `GAME_PAUSE`, `scene.pause()`, `scene.launch(PAUSE, {runTimeMs})`.
  PauseScene resume: `scene.stop()`, `scene.resume(RUN)`, emit `GAME_RESUME`. Quit: emit `RUN_ABORT`, stop RUN+UI+PAUSE,
  start `TITLE` (nothing is saved for an aborted run).
* Retry keeps the **same seed**. Title screen can pick a new/daily seed.

### Restart-in-under-10-seconds budget (pillar 3)
No assets are loaded, so: page load -> first interactive title <= `TIMING.maxBootToPlayMs` (3 s); crash -> GameOver
<= 1.2 s; GameOver retry key -> first RunScene frame <= 0.5 s. Therefore: `RunScene.create()` must be synchronous and
fast (generate only the first buffer of chunks), GameOverScene must accept retry input **immediately** (not wait for
IndexedDB/leaderboard queries), and nothing may `await` network. Never rebuild services on retry.
Retry is one press from every Game Over state: Space / Enter / pad A / pad RB / tap with no panel up; Space / pad RB
(MenuInput `retry`) from inside the Shard Shop, where an armed shop gives Enter / pad A to the highlighted row
(decision 7); an unrequested autoprompt shop is unarmed for `SHOP_ARM_MS` (500 ms) so an Enter already on its way
still retries. See "Addendum: Marvin decisions 7/8/9".

## 3. Data shapes

Authoritative typedefs: `src/data/schemas.js` (terrain/content), `src/events.js` (payloads),
`systems/SaveStore.js` (`Settings`, `RunRecord`), `systems/TrickTracker.js` (`SledFrameState`, `TrickEvent`,
`LandingResult`), `systems/VirtualPad.js` (`VirtualPadState`). Read them; the key points:

* **Coordinates / units**: world px, x right (downhill), **y down**; angles in **degrees, clockwise positive**;
  velocities px/s in all *interfaces* (Matter-native units only inside gameplay code, see section 7);
  distance metres = `px / PIXELS_PER_METER` (20). Time ms.
* **TerrainChunk**: `{index, defId, kind, startX, endX, points[{x,y}], zones[{modId,x0,x1}], gaps[{x0,x1}],
  bouncePads[{x,y,width,boost}], hazards[{defId,x,y,rotationDeg}], powerups[{defId,x,y}]}`. Guarantees the generator
  must keep and gameplay may rely on: `x` strictly increasing; spacing between consecutive points in
  `[TERRAIN.minPointSpacingPx, maxPointSpacingPx]`; chunk borders share the exact same point; `|slope| <
  TERRAIN.maxSlopeDeg` on spline chunks; gap spans start and end exactly on polyline points and have **no collider and
  no mesh** between them; hazards sit on the surface (`y` = ground height at `x`); power-up `y` is already lifted above
  ground. Chunk 0 starts at `x = 0` with a gentle run-in.
* **Chunk templates** (`data/chunks/*.json`, `ChunkDef`): `kind: 'spline'` (bezier control points + seeded jitter),
  `'noise'` (1-D noise params, used for difficulty spikes), `'bridge'` (wireless bridge: gap + bounce pads). Adding a
  JSON file adds content; nothing is hard-coded.
* **Hazards** (`HazardDef`): `{id, shapeKey, size{w,h}, onHit{effect: crash|slow|scramble, durationMs?, speedFactor?},
  weight, minDistanceM, placement, colorKey}` (B0 adds `biome`, `spawn` and the `blind` / `gust` effects; power-ups gain
  `biome` and the `ward` / `glide` / `stabilize` kinds: see "Addendum: biome full treatment, B0"). Ids: `glitchChasm`, `overflowFirewall`, `packetSpike`,
  `garbageDataVent`. **Power-ups** (`PowerUpDef`): ids `clockPulse` (slowmo), `packetBurst` (speedBoost), `hashedBackup`
  (shield); spawn chance per candidate slot = `baseChance / (1 + distanceM / distanceDecayM)`. **Terrain mods**
  (`TerrainModDef`): ids `highBandwidth` (frictionMul), `compression` (gravityMul), `wirelessBridge` (bounceMul).
  Colours are palette keys (`colorKey`), never raw hex.
* **TrickTracker input** `SledFrameState`: `{timeMs, dtMs, x, y, vx, vy, angleDeg (UNWRAPPED, continuous),
  angularVelDegS, grounded, groundAngleDeg, input{heli, airBrake, parachute}, crashed}`. Output `TrickUpdate`:
  `{tricks: TrickEvent[], landing: LandingResult|null, airborne, airtimeMs, rotationDeg}`. Trick types:
  `backflip` (CCW body rotation), `frontflip` (CW), `helicopterCCW/CW` (arrow-key driven spin), `airBrake`, `parachute`.
  Landing quality `perfect|good|sloppy|crash` from angle-vs-slope and impact speed (thresholds are the core engineer's;
  expose them as named constants in `TrickTracker.js`).
* **VirtualPadState** (design doc 4.1 wins over section 12: **S = brake, A+D together = tuck**):
  `push` (W) , `tilt` (-1..1; A = -1 = tilt back/CCW, D = +1 = forward/CW; both = 0), `tuck`, `brake` (S),
  `hop` (Space), `reset` (Shift), `heli` (-1 left arrow CCW / +1 right arrow CW), `airBrake` (Up), `parachute` (Down),
  `pause` (Esc/Start), `pressed{hop,reset,pause,airBrake,parachute,confirm}` one-shot edges, `lastSource`.
  Gamepad: left stick X = tilt, RT = push, face buttons = tricks; touch overlay maps to the same fields.
* **Settings**: `{version, masterVolume, musicVolume, sfxVolume (0..1), screenShake, palette: 'default'|'colorblind',
  touchOverlay: 'auto'|'on'|'off', touchRotate90, lastInitials, reduceMotion: 'auto'|'on'|'off', worldDance: boolean (default true)}`. Live copy at `registry REG.SETTINGS`.
* **RunRecord**: `{version, id, seed, dailyRuleId, startedAt, endedAt, durationMs, score, distanceM, trickPoints,
  tricks{type:count}, bestCombo, maxAirtimeMs, cause: 'crash'|'quit', ledgerHash, initials?}`.
  `ledgerHash = SaveStore.computeLedgerHash(record)` (versioned since decisions 1/2/4/6: see the addendum at the end;
  new records also carry `hashV: 2`, `dailyOfficial`, `bestFlow`, and `boosts` when modded). RunScene builds it and calls `saveRun` (no initials);
  GameOverScene later calls `setInitials(id, initials)` (3+ chars). Leaderboard = runs with initials.
* **DailyRule.modifiers** (multipliers, default 1): `tuckSpeedMul, tuckSteerMul, gravityMul, frictionMul,
  airControlMul, pushForceMul`. The daily rule (chosen from the UTC date) applies to **every** run that day and its id is
  stored in every RunRecord. RunScene reads `DailyPatch.getDailyInfo()` once at run start and feeds `rule.modifiers`
  to `PhysicsTuner`. Exception (decision 2): a run on a `daily-YYYY-MM-DD` seed plays THAT date's rule
  (`DailyPatch.infoForDateKey`).
* **Scoring** (`ScoreManager`): distance +1/m (whole metres, monotonic); trick value = `SCORING.trickBase[type] x
  rotation x airtime modifier` (core engineer defines the two factors, documents them in the file header); combo x1,
  +0.25 per *unique* trick type before landing; tricks are **provisional until landing** and are discarded on crash;
  perfect landing +20; Shift reset = drop pending combo + `resetPenaltyPoints` (doc says "-1 combo"/"-score"; we do both).

## 4. Services and registry (who creates what, and when)

| Registry key (`REG.*`) | Created by | When | Lifetime |
|---|---|---|---|
| `SAVE_STORE`, `SETTINGS`, `CONTENT`, `INPUT`, `AUDIO` | `createServices(game)` (`services.js`), called by `PreloadScene.create()` | once, at boot | whole session |
| `SEED` | `createServices` (random default); overwritten by `TitleScene` | boot / title | until changed |
| `LAST_RECORD` | `RunScene` | on run end | until next run end |
| `DAILY_OFFICIAL` | `TitleScene.startRun` (true only from DAILY RUN), `GameOverScene.retry` / `newSeed` | run start | until the next start (decision 2) |

Per-run objects (**not** in the registry; created by `RunScene.create()` and dropped on shutdown): `Rng`-seeded
`TerrainGenerator`, `ScoreManager`, `TrickTracker`, `GlitchDirector`, `PhysicsTuner`, `Sled`, `TerrainMesh`, entity
pools. Inject content as `new TerrainGenerator({seed, chunkDefs: content.chunks, hazardDefs: content.hazards,
powerupDefs: content.powerups, modDefs: content.terrainMods})`. Pure modules never read the registry.

`updateSetting(game, key, value)` (services.js) is the only way to change settings (persists + emits
`SETTINGS_CHANGED`). Palette colours: `getPalette(game)` / `getPaletteCss(game)` from `ui/Palette.js`; re-read on
`SETTINGS_CHANGED`. Nobody hard-codes colours.

Seeding: `Rng(seed)` hashes the seed string with xxHash32; use `rng.fork('terrain' | 'glitch' | 'music' | ...)` so
subsystems have independent deterministic streams. Same seed => identical terrain, spawns and glitch schedule.

## 5. Events

All on `scene.game.events` (global emitter), one payload object each. Names are in `EVT` (`events.js`), payload
typedefs are next to it. **Always remove listeners on scene shutdown.** Pure-logic modules never emit; RunScene is the
only gameplay emitter.

| Event | Emitter | Listeners |
|---|---|---|
| `RUN_START` | RunScene | AudioSynth (switch music to biome-aware run DSP without restarting the current song), UIScene (reset HUD), GlitchPipeline |
| `RUN_END` | RunScene | AudioSynth (neutral menu audio and Debutmont lead; current song continues), UIScene |
| `RUN_ABORT` | PauseScene | AudioSynth (return to menu music without restarting) |
| `CRASH`, `RESPAWN`, `LANDING`, `TRICK`, `HAZARD_HIT`, `POWERUP_COLLECTED`, `POWERUP_EXPIRED`, `EFFECT_END` | RunScene | AudioSynth (SFX), UIScene (popups/indicators) |
| `COMBO_CHANGED`, `SCORE_CHANGED`, `DISTANCE_CHANGED` | RunScene (from ScoreManager results) | UIScene |
| `ZONE_ENTER`, `ZONE_EXIT` | RunScene (compares `getZonesAt(sled.x)` each frame) | UIScene (indicator), AudioSynth |
| `GLITCH_START`, `GLITCH_END` | RunScene (from `GlitchDirector.update`) | GlitchPipeline (shader intensity), AudioSynth (glitch bus), UIScene (flicker) |
| `GAME_PAUSE` | RunScene | AudioSynth (menu-neutral music; actual playlist clock continues), UIScene |
| `GAME_RESUME` | PauseScene | AudioSynth, RunScene (re-enable input) |
| `SETTINGS_CHANGED` | `updateSetting()` | AudioSynth, InputRouter, UIScene, RunScene (screenShake), anything cached from palette |
| `INPUT_ACTION` | InputRouter | Title/Pause/GameOver scenes (menus), AudioSynth (unlock on first) |

Gameplay input is **polled**: `inputRouter.poll()` once per frame in `RunScene.update` (it consumes one-shot edges).
Since #115 the poll result also carries a non-enumerable `timeline` (timestamped hold changes since the last poll);
`SimClock.padsFor(pad, ticks, { frameTime, timeline, normalize })` uses it to give each fixed tick the keyboard input
whose `event.timeStamp` falls in that tick's window (see `docs/issue-115-fair-input.md`).
Menu scenes use `INPUT_ACTION` (or Phaser keyboard, since menus are simple) - but menus must work with gamepad + touch
too, so prefer `INPUT_ACTION`.

Glitch interval: doc section 2 says 3-6 s, section 9 says 5-15 s. Decision: start in `GLITCH.earlyGapMs` (5-15 s) and
blend to `GLITCH.lateGapMs` (3-6 s) as distance passes `TERRAIN.difficultyRampStartM`. Event duration 50-200 ms.
`GlitchDirector.update(runTimeMs, distanceM)` is pure; `runTimeMs` excludes paused time so glitches are deterministic.

## 6. Who does what in one frame (RunScene.update, gameplay owner)

1. `pad = inputRouter.poll()`; handle `pressed.pause` / `pressed.reset`.
2. `stepWorld(this.matter.world, delta, beforeStep)` - sub-steps <= 8 ms; apply controls/forces inside `beforeStep`.
3. Build `SledFrameState`, `trickTracker.update()`; for each trick `scoreManager.addTrick()` then emit `TRICK` and
   `COMBO_CHANGED`; on landing `scoreManager.onLanding()` then emit `LANDING`, `COMBO_CHANGED`, `SCORE_CHANGED`.
4. `scoreManager.setDistance(x / PIXELS_PER_METER)` -> emit `DISTANCE_CHANGED` / `SCORE_CHANGED` when it returns true.
5. `terrain.update(sled.x)` -> `TerrainMesh.addChunk` / `removeChunk`, spawn/despawn hazards and power-ups from chunk
   lists (spawn lists are already deterministic; do not re-roll).
6. `glitchDirector.update(runTimeMs, distanceM)` -> emit `GLITCH_START/END`.
7. Camera: lerp follow X with look-ahead; Y keeps the rider ~1/3 from top. Shake only if `settings.screenShake`.

## 7. Physics: design-doc units -> Phaser Matter

Doc values live in `constants.PHYSICS` in px / s / degrees. Phaser 3.90 Matter integrates in **px per step** with a step
delta in ms. Conversions (helpers in `PhysicsTuner.js`, gameplay may fix them but keep names):

| Doc quantity | Matter | Formula |
|---|---|---|
| Gravity 900 px/s^2 | `world.gravity.y` with default `gravity.scale = 0.001` | `g / 1000` => **0.9** (already set in `main.js`) |
| Velocity v px/s | `Body.setVelocity` is px **per step** | `v * stepMs / 1000` (`pxPerSecToStep`); inverse `stepToPxPerSec` |
| Tilt torque 420 deg/s^2 | change of `angularVelocity` (rad/step) per step | `deg2rad(420) * (stepMs/1000)^2` (`angAccelToStep`); air control multiplies by `0.7` |
| Drag 0.015 | `body.frictionAir` | use 0.015 directly (Matter scales it by step time; verify at 8 ms steps, tune in `PhysicsTuner`) |
| Tuck -15% gravity | one dynamic body only | multiply `world.gravity.y` by `tuckGravityMul` while tucked (set it each sub-step) |
| Parachute (gravity x0.5 for 0.8 s) | same | gravity multiplier + steer lock timer |
| Air brake (-25% horizontal speed) | velocity scaling | `vx *= 1 - 0.25 * stepMs/1000 * k` or one-shot; gameplay tunes feel |
| Slo-mo (Clock Pulse) | `world.timeScale`/engine timing | scale the delta passed to `stepWorld`, **not** the 8 ms limit |

* **Sub-stepping**: `autoUpdate` is `false` in `main.js`. `RunScene` must advance physics only via
  `stepWorld()` (<= `MAX_PHYSICS_STEP_MS` = 8 ms per `matterWorld.step`). Clamp frame delta to <= 50 ms first.
* **Rotation sign**: Matter angle is radians, clockwise positive on screen (y down). Interfaces use degrees; convert at
  the Matter boundary only. `SledFrameState.angleDeg` must be unwrapped.
* **Collision**: sled + rider = one compound body (`Matter.Body.create({parts:[...]})`; get the namespace from
  `Phaser.Physics.Matter.Matter`). Terrain colliders: static, **thick** convex quads per polyline segment (>= 24 px deep) so
  fast sleds (~800 px/s = 6.4 px per 8 ms step) never tunnel; skip `gaps`. Hazards and power-ups are **sensors**.
* **Terrain mods** are applied by multiplying effective physics from `TerrainModDef.physics` (`frictionMul`,
  `gravityMul`, `bounceMul`) - `PhysicsTuner.getEffective(ctx)` is the single place that combines base, tuck, zones, daily
  rule, and effects.
* `Hashed Backup` negates one crash: `CRASH` is emitted with `negated: true` and the run continues (respawn
  reason `'backup'`, then `POWERUP_EXPIRED` reason `'consumed'`).

## 8. Persistence

* `localStorage` key `STORAGE.settingsKey` -> `Settings` JSON (versioned; unknown keys ignored, missing keys defaulted).
* IndexedDB `STORAGE.dbName`, object store `runs` keyed by `id`. All run APIs are async. Must fall back to memory if
  IndexedDB/localStorage is unavailable (tests run in jsdom, which has no `indexedDB`).
* Sharecode = leaderboard exported as a copy/paste string; import dedupes by run id and never throws.

## 9. Tooling notes

* Vite resolves `import frag from './glitch.frag?raw'` - only `GlitchPipeline.js` uses it. `data/index.js` uses
  `import.meta.glob`. **Neither can be imported from Jest**; pure modules and tests must stay clear of them. Tests that
  need content read JSON via `fs.readFileSync` and inject it.
* Jest config: `package.json` -> `testMatch **/tests/**/*.test.js`, ESM via `--experimental-vm-modules`, jsdom env,
  `moduleNameMapper` strips `.js` extensions. New tests go in `tests/src/**/*.test.js`.
* Phaser 3.60+ API only: particles are `scene.add.particles(x, y, texture, config)` (no `createEmitter`); post-FX via
  `PostFXPipeline` + `camera.setPostPipeline`.
* A block comment cannot contain `*/` - writing `FOO_*/BAR` in JSDoc breaks the Vite build.
* Dev: `npm run dev` (vite, port 5173); headless boot check exposes `window.__bbGame`.

## Input/Audio/Glitch addenda

All additive; no existing signature or payload changed.

* **VirtualPad** (#115, additive): `setButton(name, down, source, timeStamp?)` takes an optional event time on the
  `performance.now()` clock; `poll()` snapshots carry a non-enumerable `timeline` `{ base, events, analog }`; exported
  pure `deriveHeld(held, analog)` (implemented in the pure `systems/PadDerive.js`, with `eventTimeOnClock`).
  `InputRouter.poll()` returns `timeline: null` while disabled. `TouchOverlay` passes pointer `timeStamp`s
  (down / move / up / cancel / lostpointercapture) the same way keyboard does.
* **VirtualPad**: `setTilt(value, source = 'gamepad')` has an optional 2nd arg (analog sources `'gamepad'` / `'device'`;
  largest magnitude wins; output is rescaled outside the 0.15 dead-zone). New: `releaseSource(source)`,
  `setOverlayContext(visible)`. New helper file `systems/TouchOverlay.js` (DOM only). The touch overlay is shown only
  while a run is active (InputRouter listens to `RUN_START` / `RUN_END` / `RUN_ABORT` / `GAME_PAUSE` / `GAME_RESUME`), in
  mode `touchOverlay: 'on'`, or `'auto'` on touch devices. `touchRotate90` = device roll (steering-wheel style, screen-orientation
  aware, +-30 degrees = full tilt) feeds the analog tilt; on iOS the permission prompt is requested on the first touch.
* **InputRouter INPUT_ACTION mapping**: Esc and gamepad Start emit `'pause'` only (menus treat it as back); `'cancel'` =
  Backspace / gamepad B. Space and gamepad A emit `'hop'` + `'confirm'`; Enter `'confirm'`; W/A/S/D and arrows also emit
  `'up'/'left'/'down'/'right'` (direction actions auto-repeat); Up/Down arrows additionally `'airBrake'`/`'parachute'`.
  `'anyKey'` fires on every first press of any key / gamepad button / touch pointer (touch taps do NOT emit `'confirm'`:
  scenes needing tap-to-confirm should use Phaser pointer events or `'anyKey'` with `source === 'touch'`).
  Keys typed into `input`/`textarea` are ignored; Ctrl/Meta/Alt combos are ignored.
* **Gamepad** (standard mapping, Steam Deck): left stick X analog tilt, RT push, LT tuck, A hop(+confirm), B brake(+cancel),
  X air brake, Y parachute, LB/RB (or right stick X) helicopter CCW/CW, Back reset, Start pause, d-pad = menu + digital tilt.
* **AudioSynth** additive methods: `setSpeed(pxPerSec)` (music speed/intensity only; RunScene calls it every frame; BSOD event exclusively drives environmental wind),
  `setIntensity(0..1)`, and `startMenuMusic()` (called once by Title, requests immediate One More Run, browser user gesture permitting).
  The same playback clock runs through Title, gameplay, death, pause and menus; only mix/melody/biome DSP changes.
  Menu uses unprocessed original accompaniment with Debutmont melody and no speed/jump/BSOD DSP.
  Settings `musicShuffle` persists through SaveStore; ON shuffles following enabled songs in non-repeating rounds,
  not the fresh-load One More Run opener. All songs OFF remains music silence.
  Music intensity also follows `DISTANCE_CHANGED` during runs only.
* **BSOD accompaniment corruption:** the authoritative post-physics `BSOD_STATE_CHANGED.proximity01` independently drives music-only WebAudio darkening/distortion/tremolo on the ORIGINAL guitar, piano and Other buses via `BsodThreatProcessor`. It never drives or changes global SFX, environmental wind, vocals, bass, drums, note timing or source files. The signed `relativeAirX` continues to control wind separately, so quiet relative airflow near the wall can coexist with maximal musical threat. Original accompaniment recovers smoothly on escape, and Title/Pause/GameOver force clean neutral music without resetting the active track clock. The provisional effect intensity awaits human audition before release. There is **no event for push or hop**, so RunScene
  must call `audio.playSfx('push')` / `playSfx('hop')` itself. Everything else is event driven (also `COMBO_CHANGED`
  reason `'trick'` -> `combo` SFX, `ZONE_ENTER` -> soft blip). It never throws without WebAudio.
* **GlitchDirector**: event ids are `g<n>-<4 hex>`; the hex tag is the seed-derived pattern that `GlitchPipeline` uses
  (RunScene just forwards `id/kind/durationMs/intensity`). Extra exports: `glitchRamp`, `glitchGapRange`, `preview(count)`.
  The gap blend runs from 0.5 x to 1.0 x `TERRAIN.difficultyRampStartM` (early 5-15 s below 500 m, 3-6 s from 1000 m).
* **GlitchPipeline**: also self-expires an event `durationMs + 60 ms` after start (pause-safe), runs in "safe" mode
  (weaker, no inversion flicker) when `settings.screenShake === false`, and composites transparent camera pixels over the
  game's clear colour. Extra uniforms: `uKind`, `uSeed`, `uSafe`, `uCrt`, `uBg`. The always-on CRT layer exists only on
  cameras where `install()` was called (RunScene).

## Core-logic addenda

All additive; no public signature changed.

* **Geometry conventions** (TerrainGenerator): `hazards[].x` and `bouncePads[].x` are the **centre** of the object
  (pads are `width` wide around it, always on solid ground ending before the gap). Points are evenly spaced at 16 px
  (`SPACING_PX`); a bridge chunk's polyline also has interior points inside the gap, which gameplay must skip (no
  collider/mesh between `gaps[i].x0` and `.x1`; falling into the gap is a miss, handle as a fall/crash). Hazards never
  appear on bridge chunks, inside gaps, on steep ground, within 700 px of the start, or closer than 480 px to each other
  (also across chunk borders). Power-ups are never within 90 px of a hazard.
* **Chunk lifetime**: `update()` returns `removed` indices; the chunk *objects* are recycled one `update()` later, so
  do not keep references to removed chunks past the frame you receive them (key your meshes/entities by `chunk.index`).
  Do not mutate chunk objects. `getChunk(i)` returns the live object when active, otherwise a fresh copy.
* **Extra TerrainGenerator members** (optional): `getChunkAt(x)`, `stats`, `difficultyAt()` extended values. `heightAt`,
  `slopeDegAt`, `getZonesAt` work for any x >= 0 (slightly ahead of the window they extend it and the new chunks are
  reported in the next `update().added`; far outside the window they rebuild a temporary chunk, which is slower, so
  call them with positions near the sled).
* **Difficulty**: flat until 1000 m; then `slopeVariance` 1->2, `hazardDensity` 0.8->2.1 per 1000 px, `glitchFrequency`
  1->1.9, `noiseWeightMul` 1->4 over the following ~3000-6000 m. Chunk template `jitterPx` is an optional extra field.
* **TrickTracker**: `TrickEvent.count` is the **cumulative** rotation count in the current air phase (a double flip
  emits count 1 then count 2). `ScoreManager.addTrick` pays only the increase, so call it for every event. `LandingResult`
  gains optional `rotationDeg`. On `state.crashed` while airborne the tracker returns a landing with `quality:'crash'`
  (so `scoreManager.onLanding(landing)` forfeits the combo) and resets itself; call `tracker.reset()` after Shift reset /
  respawn. Thresholds are exported constants (`PERFECT_ANGLE_DEG` 12, `GOOD_ANGLE_DEG` 28, `SLOPPY_ANGLE_DEG` 55,
  `HARD_IMPACT_PX_S` 520, `CRASH_IMPACT_PX_S` 1500, flip tolerance 20 deg, air brake 250 ms, parachute 300 ms).
  Trick value = base x (2^count - 1) x (1 + min(airtime,2500)/2500).
* **ScoreManager** also exposes allocation-free `getTotal()` / `getDistancePoints()` (what `getSnapshot()` uses) for per-frame callers.
* **ScoreManager**: snapshot gains `penaltyPoints`; reset penalty is tracked separately so `trickPoints` stays >= 0.
  A `crash` landing quality banks nothing (no separate `onCrash` call needed, though it is harmless).
* **SaveStore**: `init()` never rejects (memory fallback, `store.backend` is `'idb'` or `'memory'`). Records are
  sanitised on save/load/import (unknown keys dropped). Sharecode = `BB1:` + base64(UTF-8 JSON `{app,v,runs}`), importer
  also accepts bare base64 / raw JSON, skips runs whose `ledgerHash` does not match their contents (per hash version; an
  empty hash is rejected since decision 6), and never throws.
  `saveRun` returns committed/session-only/invalid; committed IDs deduplicate, while uncommitted IDs
  retry the original record rather than replacing it. `getRunPersistence(id)` distinguishes pending,
  committed, session-only and unknown; `whenRunSettled(id)` waits for the latest queued revision.
  Only IDB transaction completion marks a write committed. In-memory fallback remains playable and
  Game Over labels session-only results. Persistence status is local runtime metadata, not ledger
  provenance, a hash field, or ranking proof. Same-ID writes are serialized, including initials.
  `setInitials` throws `RangeError` for < 3 chars (after trim) and clamps to 12; unknown run ids are ignored,
  known rows return committed/session-only. Native fault injection uses a disposable loopback Chromium
  profile: `node tools/qa/save-persistence-browser.mjs http://127.0.0.1:43237/` against a local Vite server.
* **DailyPatch**: 8 rules; index = whole UTC days since epoch modulo `RULES.length`. Added `msUntilNextRule(date)`.
* **Rng**: `fork(label)` derives from the *initial* seed (independent of how much the parent has been consumed). New
  export `hashInts(a, b)`. Real xxHash32 (reference vectors tested).

## UI addenda (UI engineer; all additive, nothing in sections 1-9 changed)

1. **Optional HUD speed event** `'bb:hudSpeed'` (exported as `HUD_SPEED_EVENT` from `scenes/UIScene.js`, payload `{speedPxS:number}`).
   The contract has no speed event, so UIScene derives km/h from `DISTANCE_CHANGED` timing. If RunScene emits `bb:hudSpeed`
   (about 10 Hz) the HUD uses the exact value instead. Not required.
2. **Optional PauseScene launch data** `runId` (`scene.launch(PAUSE, {runTimeMs, runId})`), used for the `RUN_ABORT` payload.
   If absent PauseScene reads `UIScene.runId` (set from `RUN_START`), else sends `''`.
3. **Pause / restart / quit semantics** (PauseScene): Restart emits `RUN_ABORT`, stops RUN + UI and starts RUN again (same seed).
   Quit emits `RUN_ABORT`, stops RUN + UI, starts TITLE. Resume follows section 2 exactly, then polls `INPUT` a few times to
   consume the stale `pressed.pause` edge of the key that resumed. RunScene should additionally call `inputRouter.poll()` once on
   `GAME_RESUME` so that edge can never re-pause the run.
4. **UIScene may miss `RUN_START`** (launched in the same frame it is emitted); it initialises seed/daily rule from `REG.SEED` and
   `DailyPatch.getDailyInfo()` and resets on any later `RUN_START`. It listens to everything in the events table and removes
   every listener on shutdown.
5. **GameOverScene** shows the initials entry only when `qualifiesForTop10(score)` is true AND `score > 0` AND `cause !== 'quit'`.
   Initials length is `INITIALS_LENGTH` in `ui/Format.js` (default 3; the widget supports any length, SaveStore allows 3..12).
   Space/Enter/A/RB/tap retry immediately with `registry REG.SEED` reset to `record.seed`; a pending, unsaved entry is saved
   fire-and-forget (prefilled from `settings.lastInitials`, default `AAA`) so a retry never loses a top-10 score.
6. **Menu input**: UI scenes accept `EVT.INPUT_ACTION` (`up/down/left/right/confirm/cancel/hop/pause`) AND fall back to Phaser
   keyboard + `navigator.getGamepads()`; duplicates from different sources within 60 ms are merged (`ui/MenuInput.js`). While typing
   initials, keyboard-sourced `INPUT_ACTION`s are ignored (typing "A" must not move a cursor).
7. **DOM text boxes** (seed entry, sharecode export/import) are real `<input>`/`<textarea>` elements stopped from propagating
   key events (`ui/DomTextBox.js`), so InputRouter's window listeners never see typed keys. InputRouter must not use
   capture-phase listeners that `preventDefault` Space/arrows, or those keys cannot be typed in the box.
8. **HUD slots** (`UIScene._layout`, `ui/HudLayout.js`): the centre banners (effect warnings, BOOST, PERFECT LANDING, sector strip, bank line,
   CRASH banner, trick popups) are stacked top to bottom from their classic y (`SLOT`), so simultaneous ones take separate rows instead of
   overlapping, and are pushed under any fixed HUD row, the zone chip or touch button they would touch (rows are measured live; wide values
   such as a 7-digit score, shards in the thousands or a long combo name cannot collide). Pop animations are capped (about 25 %) so they
   stay inside the 3 px gap; the speed pop stays above the shard row (y 53); the shard chain chip follows the popping counter. The bottom
   row (power-ups, tutorial chip) is placed with `placeX`: power-ups move right of the touch buttons, the chip moves above the power-up row
   when it would touch them, the seed lines or the buttons. Touch boxes come from the overlay's `.bb-cl` clusters mapped through the canvas
   rectangle. Screenshots: `node tools/sim/shots.mjs hud <outDir>` (scenarios in `tools/sim/shots-hud.js`, with an overlap probe).

## Gameplay addenda (gameplay engineer; all additive)

* **Matter 0.20 units**: `Body.setVelocity/getVelocity/AngularVelocity` are normalised to a 1000/60 ms base step, NOT the
  sub-step (section 7's `v * stepMs / 1000` is only right for stepMs = 16.67). Gameplay uses `BASE_STEP_MS` (PhysicsTuner).
  `world.step(delta)` handles variable deltas itself (`Body._timeCorrection`).
* **Matter friction must be 0 on the sled**: any `friction >= 0.0005` jams the sled on slopes below ~15 deg (verified in node and
  in-game). Runner drag, braking and High Bandwidth zones are applied manually (`TUNING.groundResist`, `brakeResist`,
  `frictionMul`). Terrain bodies get `frictionStatic = 0` (Matter combines static friction with max()).
* **Feel tunables beyond the doc** (all in `PhysicsTuner.TUNING`, doc values in `constants.PHYSICS` untouched):
  `dragFeelMul` 0.3 (written frictionAir = 0.015 x 0.3 = 0.0045; literal 0.015 caps an 8 deg slope at ~120 px/s) and
  `airTiltFeelMul` 1.6 (air tilt = 420 x 0.7 x 1.6; literal needs ~2.1 s for 540 deg, now ~1.6 s). Set both to 1 for the literal doc.
  `EffectivePhysics` gained optional fields `steerMul`, `tiltSign`, `groundResist`, `quadDrag`, `pushForceMul`,
  `scrambleJitterDegS2`, `restitution`; `TunerContext` gained `slowFactor`, `timeMs`, `parachute`, `airBrake`, `airborne`,
  `braking`. `stepWorld()` has an optional 4th arg `afterStep`.
* **Spawn**: the sled spawns `SPAWN_RUNIN_PX` (44) px past `getStartPosition().x` so the rear runner has ground; distance is
  measured from the spawn x. Camera X is clamped to >= -30 so the world edge is never shown.
* **Crash rules**: head/torso touching terrain, `LandingResult.quality === 'crash'`, crash hazards, or falling
  `TUNING.voidDepthPx` (320) below the interpolated ground line (gaps) all crash. Hashed Backup negates any of them
  (`CRASH negated:true`); for non-hazard causes the sled is also respawned (`RESPAWN reason 'backup'`, pending combo dropped).
  Manual Shift reset: `RESPAWN reason 'manual'`, ends timed power-ups with `POWERUP_EXPIRED reason 'respawn'`.
* **Extra emissions**: `HUD_SPEED_EVENT` ~10 Hz; `audio.playSfx('hop'|'push')` and `audio.setSpeed()` from RunScene.
* **Entity files added**: `entities/Background.js` (parallax), `entities/Fx.js` (pooled shards/sparks/rings).
* **Slope-normal landing rebound** (additive): `BiomeEffects.springReboundVelocity(vx, vy, groundAngleDeg, upPxS)` keeps
  the along-slope velocity and raises the outward normal component to `max(existing outward, upPxS)`; a non-positive
  `upPxS` is a no-op. `Sled.launchNormal(upPxS, groundAngleDeg)` applies it through `Body.setVelocity` in Matter 0.20
  base-step units and resets contact/snap state like `launchUp`; a zero, negative or non-finite `upPxS` is a no-op
  before any body or state change. `RunScene.applySpringRebound` uses it once per scored (non-crash) landing with
  `fs.groundAngleDeg`, so a `bouncySpring` descent cannot turn forward speed into extra bounce; bounce pads keep
  `Sled.launchUp`. `BiomeEffects.springRebound` treats a result below `SPRING_REBOUND_MIN_PX_S` (120 px/s) as no
  rebound: at the shipped 0.2 share only impacts of 600 px/s or more are felt, while the Rails' 0.05 share stays below
  the floor even at 801 px/s. The 120 px/s floor is the measured point that keeps the bounce felt within the accepted ±15%
  mask-128 hop survival tolerance; the normal projection is checked on uniform slopes and makes no general
  irregular-terrain safety claim.

## Integration / QA addenda (QA engineer; additive, nothing in sections 1-9 changed)

* **Flow tuning (Pillar 1)**. QA found a hands-off sled stalled (< 10 px/s) in the first dip and covered ~110 m in 20 s
  (peak ~320 px/s). Doc 4.2 values in `constants.PHYSICS` are untouched; the feel multipliers in `PhysicsTuner.TUNING` changed:

  | Tunable | Before | After | Effect |
  |---|---|---|---|
  | `dragFeelMul` (x doc drag 0.015) | 0.3 | 0.15 | linear air drag 0.27/s -> 0.14/s |
  | `groundResist` (1/s) | 0.12 | 0.04 | runner resistance |
  | `quadDrag` (1/px) | 0.00009 | 0.0003 | soft terminal speed (~600 px/s on steep drops) |
  | `airTiltFeelMul` (x doc 420 x 0.7) | 1.6 | 3.6 | air tilt 470 -> 1060 deg/s^2: a held flip is ~270 deg in a 0.8 s hop, ~540 deg in ~1.0-1.1 s |
  | `maxAngularVelDegS` | 560 | 1100 | do not clip a held flip |
  | `hopPxS` | 300 | 360 | an average hop is ~0.8 s of air (was ~0.6) |
  | `pushKickPxS` | 70 | 90 | W from a standstill still useful |

  Measured with the real game (12 seeds, hazards ignored, hands-off, today's daily rule): mean speed 78 -> ~350 px/s, distance
  in 20 s ~85 m -> ~250-320 m, stalls (> 2 s below 10 px/s) in 40 s: 12 of 12 seeds -> 0 of 12 (also 0 with the heaviest,
  lightest and stickiest daily rules). Matter 0.20 loses ~35 % of `g sin(slope)` on the polyline colliders (QA measured
  accel 61 vs 91 px/s^2 at 5 deg) which is why the drag had to drop so far.
* **TerrainGenerator flow rules** (`RISE_LINE_DEG`, `RISE_MAX_PX`, `MAX_UP_DEG`): spline slopes climb at most `MAX_UP_DEG` = 12
  (was 28 - the old kicker ramps were walls that trapped sleds in bowls W cannot escape, push needs slope >= -5 deg); a hill never
  rises above the descending 7 deg line drawn from the previous peak nor more than 30 px above the valley floor it climbs out of
  (state carried in `bounds[].peakDx/peakDy/valDy`, so chunks stay pure functions of seed and index); every chunk still
  descends >= 9 deg overall (`MIN_NET_TAN`, was 7); the first segment of a chunk turns at most `MAX_TURN_DEG` (noise seams used
  to allow 17). Templates `kicker-lip`, `valley-launch`, `ski-jump` had their uphill rises cut to ~35-45 px. Terrain unit tests were
  not loosened; flow rules have their own tests (`tests/src/terrain.test.js`, "flow rules").
* **Helicopter spin scoring**: the spin is a drawing-only rotation, so `TrickTracker` (which counted body rotation while an arrow was
  held) never scored it. `SledFrameState` has an optional `heliDeg` (continuous drawing phase, `Sled.heliPhase`); when present the heli
  bucket is fed from it and body rotation always counts as flips. Without it the legacy rule applies.
* **Sled skids** are 24-gon polygons instead of Matter's 10-sided circles (polygon edge normals caused ~10 % extra seam drag).
* **Camera** keeps the rider inside a 34 px band and follows faster with vertical speed (bounce pads launched the sled off screen).
* **Menu text entry**: `ui/MenuInput` uses native window keydown events (not Phaser's keyboard plugin) while `rawKeyHandler` is set,
  because InputRouter preventDefaults Space / arrows (Phaser drops those) and Phaser's per-frame key queue re-delivered keys out of
  order when several arrived in one frame. On the Game Over initials panel: Enter saves, Space saves with the current letters and
  retries instantly, Esc skips (nothing saved). With no panel up Space / Enter / pad A / tap retry at once.
* **UIScene** hides the seed / daily-rule lines while the touch overlay is visible (they sat under the HOP / PUSH buttons).

### Fun-pass: feedback (UI / audio)
* New events (`events.js`): `LANDING_BOOST`, `NEAR_MISS`, `SHARD_COLLECTED`, `MILESTONE`, `NEW_BEST`, `TUTORIAL_HINT` (emitted by RunScene).
  UIScene listens (all removed on shutdown) and also triggers the matching sfx itself (RunScene must not).
* HUD: BOOST callout (top-centre, perfect = bigger), NEAR MISS popup, SHARDS counter + chain chip under the speed readout (chain chip
  expires 2.5 s after the last shard), pending trick points (x multiplier) pulse under the combo, SECTOR / NEW BEST strip (y 59-76, popups now start at y 80,
  < 1 s, queued), tutorial chip bottom-centre (wording by touch overlay / `pad.state.lastSource`; auto-hides after 4 s).
* AudioSynth `playSfx` opts gained `intensity` (`'boost'`, 0..1, 1 = perfect) and `step` (`'shard'`, chain index, ladder capped at 9).
  New names: `boost`, `nearMiss`, `shard`, `milestone`, `newBest`.
* GameOver: best comparison from `getRecentRuns(1000)` (excludes this run), shards / near misses rows from optional
  `rec.shards` / `rec.nearMisses` / `rec.bonusPoints`; initials panel only if the board has >= 3 entries or score >= 200;
  RETRY hint follows the panel state. Title shows the device best distance / score.

## Fun-pass: terrain (level-design engineer; additive)

* **New chunk fields** (always present, reset on recycle): `shards: {id,x,y}[]` (sorted by x, ids `s<chunkIndex>-<n>`, world px, >= 12 px above the
  surface, clear of every hazard hit box by >= 22 px), `launches: {x,y,angleDeg,airS,landX|null}[]` (ballistic lips at the expected speed),
  `sector` (1-based, `floor(startX / 20 / 500) + 1`), `breather` (bool). `ScoreManager.addBonus(points, kind)` (`'shard'|'nearMiss'|'milestone'`) adds
  immediately (separate `bonusPoints`, not combo, never multiplied, survives crash/reset); snapshot gains `bonusPoints`, `shards`, `nearMisses`,
  `milestones`, `bonusByKind`.
* **Opening**: chunk 0 is the generated `gen-jump` chunk (no template): ~720 px of 14 deg descent, then an easy lip at ~x 830 (~41 m, ~0.55 s of air at
  the expected speed) onto a 36 deg landing ramp and a hazard-free runout. No hazards before 80 m, no crash hazards before 150 m
  (`HAZARD_SOFT_PX` 1600, `HAZARD_SAFE_PX` 3000); hazard density ramps in from 35 % at 75 m to full at 600 m.
* **Launches**: `gen-jump` chunks (defId `gen-jump`, not in the JSON templates) are chosen when `sinceLaunch` grows (never twice in a row, never in
  breathers); mean launch spacing ~2700 px (~5 s at cruise). Lip up-angle 12 deg, landing slope 36 -> 42 deg by 1500 m, landing ramp sized for 1.2 x
  `expectedSpeedPxS(distM)` (340 + 0.18 m, cap 620) so airtime grows ~0.6 s -> ~1.2+ s. The whole jump chunk plus every detected lip's landing zone
  (and the next chunk's start via `bounds[].noHazX`) is hazard free.
* **Crests**: slope may increase (convex) by at most `CREST_TURN_DEG` 3.5 deg per 16 px segment on ordinary spline chunks (`NOISE_CREST_TURN_DEG` 6 in
  noise zones); templates tagged `SHARP_TAGS` (kicker, jump-lip, launch, big-air, drop, steps) and generated jumps keep the 10 / 16 deg lips.
* **Sectors**: `difficultyAt` is stepped per 500 m (ramp = sector/7, same ceilings as before, reached ~3500 m) and also returns `sector`, `speedBudget`.
  The first chunk starting in a new sector is a calm "breather" (roller/cruise/intro template, no noise/bridge/jump, first 1100 px hazard free).
* **Anti-stall**: `bounds[].speed` carries a 1-D roll model (0.65 g sin, 0.2 v + 0.0003 v^2 drag); `_finishSafe` adds descent to any non-bridge chunk
  until the model stays above 55 px/s. 0 stalls in 60 seeds x 10 000 m.
* **Shards**: one group per chunk at most, ~59 % of chunks: arcs off every launch lip / bounce pad (always), else (`SHARD_PLAIN_CHANCE` 17 % of the remaining chunks)
  a ground line 14 px above a 8-38 deg stretch or a high risk hump over a hazard / gap; risk share = 12 % + dist/5500 (max 65 %).

## Fun-pass: feel (game-feel engineer)

* **Trick -> speed loop** (`TUNING.boost*`, `sloppySpeedKeep`): good/perfect landing after >= 1 trick adds `60 x comboMult x (1 + 0.2 x (tricks-1))` px/s
  along the travel direction (perfect x1.5, cap 260) and runs drag x0.3 for 1.2 s (`Sled.boostMs`); perfect with no tricks +30; sloppy keeps 92 % speed
  and damps spin. Emits `LANDING_BOOST`. Measured: perfect single backflip +113 px/s (+~125 px/s within 150 ms).
* **Ground snap** (`TUNING.snap*`, `Sled.applyControls`, `RunScene.dropAhead`): grounded >= 100 ms, no hop/launch for 350 ms, left ground < 160 ms ago,
  normal speed < 130 px/s and ground ahead falls away < 11 deg -> normal velocity is clamped to 0. Kickers/drops/hops are untouched.
* **Forgiveness**: tracker 'crash' landings with |angle| <= 78 deg and impact < 1700 px/s become 'sloppy' (RunScene); crash hazard hit-boxes are 72 % x 80 % of the drawn box.
* **Speed feel**: camera zoom 1.0 -> 0.82 (150..600 px/s, stepped 0.005; `applyZoomCompensation` counter-scales the scroll-factor-0 background and flash
  rect), look-ahead 170 px, streaks > 420 px/s, hit-stop 45/70 ms, landing squash, impact-scaled sparks.
* **Near miss / shards / milestones / best gate / hints**: `RunScene.updateFun`; `entities/Shard.js` (ShardField), `entities/BestMarker.js`.
  `SHARD_COLLECTED.total` = shard points this run. Tutorial completion persists in localStorage `bb.tutorialDone` (SaveStore drops unknown settings keys).
  RunRecord gets `shards`, `nearMisses`, `bonusPoints` (SaveStore.sanitizeRun may strip them).

## Addendum: chase queries and daily countdown (meta/persistence engineer)

Additive, read-only helpers. No change to RunRecord, `computeLedgerHash`, the `BB1:` sharecode, the IndexedDB layout or the memory fallback.
All SaveStore helpers below are **synchronous** scans of the in-memory `this.runs` mirror (filled once by `init()`), so they never touch I/O and
are safe to call in `RunScene.create()`, `GameOverScene.create()` and `TitleScene.create()` without blocking retry. O(n) per call, fine for thousands of runs.
Every stored run counts (crash and quit); runs imported via sharecode count too (they carry initials). SUPERSEDED for the Daily
surfaces by decisions 1/2 (addendum at the end): Daily best counts only official runs, and the streak only official local runs.

* `store.getSeedStats(seed, {excludeRunId}?)` -> `{seed, attempts, bestScore, bestDistanceM} | null`. Best score and best distance are independent maxima.
* `store.getDailyStats(when = now, {excludeRunId}?)` -> same plus `dateKey`, for `DailyPatch.getDailyInfo(when).seed` (`when` is a Date or epoch ms).
  Since decisions 1/2: only official Daily runs on that date's mask (`Ranking.countsForDailyBest`).
* `store.getDailyStreak(now = new Date())` -> `{streak, playedToday, todayKey, lastPlayedKey}`. Day membership is the date inside the run's seed
  (`daily-YYYY-MM-DD`), not its timestamps (robust to clock skew and midnight-straddling runs). Streak ends today or yesterday, else 0; future-dated seeds ignored.
  Since decisions 1/2: only official, local Daily runs hold a day (`Ranking.countsForStreak`).
* `DailyPatch.dateKeyFromSeed(seed)` -> `'YYYY-MM-DD' | null`; `DailyPatch.formatCountdown(ms)` -> `'3H 12M'` / `'12M'` / `'<1M'` / `'0M'` (minutes rounded up).

**GameOver usage.** `saveRun` is async and pushes to `this.runs` synchronously before its first await, so the finished run is already in the mirror when the
scene asks. Call `const prev = store.getSeedStats(run.seed, {excludeRunId: run.id})` (and `getDailyStats(new Date(run.startedAt), {excludeRunId: run.id})` when the
seed is a daily seed) to get the PREVIOUS best; "NEW SEED BEST" when `!prev || run.score > prev.bestScore`, else "SEED BEST ${prev.bestScore}". The same call is correct
whether or not the run is saved yet, because of `excludeRunId`. For the streak, call `getDailyStreak(Date.now())` after saving: a first daily run today shows playedToday true.
**Title usage.** `store.getDailyStreak(Date.now())`, `store.getDailyStats(Date.now())`, and `DailyPatch.formatCountdown(DailyPatch.msUntilNextRule())` (refresh on a slow timer).

## Addendum: scoring fun-pass (flow, flips, combo names, milestones)

Owner: core-logic engineer. All additive except the two rule changes marked RULE. Numbers live in `SCORING` (constants.js).

* **Flow streak** (`ScoreManager`; RULE changed in the fix round): run-level multiplier `flow` x1.0..`flowMax` x3.0. A perfect (+`flowPerfectStep`
  0.25) or good (+`flowGoodStep` 0.15) landing after >= 1 COMBO-STEP trick (`SCORING.comboStepTypes`: flips and helicopters; air brake /
  parachute alone gain nothing) raises it. ANY perfect / good landing, tricks or not, refreshes the timeout (`flowTimeoutMs` 9000 of ticked
  run time). Sloppy with >= 1 trick keeps `flowSloppyKeep` (0.5) of the bonus above 1.0 (applied AFTER that landing banks, paid at the carried-in
  flow) and does NOT refresh the timeout; every halving (sloppy, timeout, `onShieldHit`) clears to 1.0 with `lost:true` when the kept bonus is
  below `flowClearBelow`, and flow reaching exactly 1.0 by any path is reported `lost`, never `changed`, with the timer zeroed. Crash landing, `onCrash()` and `penalizeReset()` clear it. The timeout does not clear: each expiry
  halves the bonus above 1.0 and restarts the timer (`FlowChange {reason:'timeout', lost:false}`); once the halved bonus would be below
  `SCORING.flowClearBelow` (0.05) it clears to 1.0 (`lost:true`). `banked = round(pending x combo x flowUsed)`, where `flowUsed` is the flow
  AFTER this landing's gain (so the first clean trick landing already pays; a landing that gains nothing pays at the carried-in flow).
  Distance and flat bonuses are never multiplied. **Shield save**: `onShieldHit(dropCombo = false)` halves the bonus (reason `'halved'`) and,
  unless `dropCombo`, leaves the pending combo, its paid baseline and the tracker counts untouched (RunScene passes `false` for a hazard hit
  absorbed by Hashed Backup, e.g. mid-air, and `true` when it respawns the sled). RunScene does NOT flag the tracker `crashed` for a hazard hit
  that a shield charge (or post-respawn grace) absorbs, so the air phase and counts continue and the landing banks the combo once. Do NOT call `onCrash()` for a shield hit: it wipes `paid`
  while TrickTracker keeps its counts, so later flips would be re-paid at full cumulative value.
* **Calls RunScene must make**: `score.tick(dtMs)` once per frame with the run-clock delta (excludes pause; never wall clock);
  `onLanding(landing)`, `onCrash()`, `penalizeReset()` as before. Each returns a `FlowChange`
  `{changed, lost, previous, flow, reason:'gain'|'halved'|'crash'|'reset'|'timeout'|'none', timeoutFrac, best}`
  (`onLanding().flowChange`, `penalizeReset().flowChange`, `onCrash()` and `tick()` directly). ScoreManager never emits: the scene emits
  `EVT.FLOW_CHANGED` (`FlowChangedPayload {flow, previous, reason:'gain'|'halved'|'timeout', timeoutFrac, best}`) when `changed && !lost`, and
  `EVT.FLOW_LOST` (`FlowLostPayload {previous, reason:'crash'|'reset'|'timeout'}`) when `lost`. FLOW_CHANGED reasons: `'gain'`, `'halved'` (sloppy /
  shield hit), `'timeout'` (timer expiry halving; flow still above 1, timer restarted, `timeoutFrac` 1); FLOW_LOST `'timeout'` = the bonus decayed away.
  HUD getters: `getFlow()`, `getFlowTimeoutFraction()` (0 when flow is 1), snapshot fields `flow`, `flowTimeoutFrac`, `bestFlow`,
  `comboCounts`. `onLanding` additionally returns `flowUsed` and `comboName`.
* **bestFlow in the record**: the scene may add an optional `bestFlow` (from `snapshot.bestFlow`) to the RunRecord. It is NOT covered by
  the v1 `computeLedgerHash` (which hashes a fixed field list), so old saved runs stay valid. SUPERSEDED by decision 6: SaveStore now
  whitelists `bestFlow` and the v2 hash covers it (absent = 0); readers default it to 1 for display.
* **RULE: combo step**: only `SCORING.comboStepTypes` (backflip, frontflip, helicopterCCW, helicopterCW) add `comboStep`. Air brake and
  parachute keep base points and still appear in `comboTricks`, but `addTrick().isNew` and `TrickPayload.isNew` are false for them.
* **Incomplete helicopter**: `classifyLanding(angleDiffDeg, impactSpeedPxS, midSpin?)`; `midSpin` is `true` or a helicopter phase in
  degrees (e.g. `heliDeg`, any sign/wrap). `isMidSpin(spin)` is true when the phase is further than `SCORING.midSpinToleranceDeg` (60, was 35:
  the drawing coasts ~40 deg after the key is released) from a whole turn. TrickTracker additionally ignores a NUMERIC phase (no penalty) when the
  helicopter key was released before touchdown and less than `MID_SPIN_MIN_DEG` (90, a quarter turn) of helicopter spin was made in the air
  phase (a nudge or pure coast); a key still held at touchdown or `midSpin: true` always counts. The grade drops one level (perfect->good, good->sloppy, sloppy stays); never creates or rescues a crash.
  `SledFrameState.midSpin` (same type, optional) is forwarded by `TrickTracker`; `LandingResult.midSpin` reports that the penalty applied.
  RunScene should pass its drawing's heli phase (or `true` while a spin is unfinished) in `midSpin` on the landing frame.
* **Combo names**: `comboName(tricks, maxChars = 28)` (ScoreManager.js) takes type strings or `{type,count}`; e.g. `DOUBLE BACKFLIP + HELI`,
  `TRIPLE FRONTFLIP`, `BACKFLIP + AIR BRAKE`; degrades to BRAKE/CHUTE, then `N-TRICK COMBO`. `getComboName()` names the pending combo;
  `onLanding().comboName` names the jump just landed (capture it for the HUD popup).
* **Milestones**: `milestoneBonus(sector) = 100 x min(sector, SCORING.milestoneMaxSector 10)` (linear, flat 1000 from 5 km on; was 100 x sector); `score.checkMilestones(distanceM)` pays (via `addBonus(..., 'milestone')`)
  every newly completed 500 m sector exactly once and returns `[{sector, points, distanceM}]`; the scene emits `EVT.MILESTONE` for each
  (payload gained optional `points`). Call it when distance advances. Reaching 500 m pays sector 1 (100), 1000 m pays sector 2 (200), 5 km sector 10 (1000).
  If RunScene keeps its own milestone trigger, drop the old `addBonus(..., 'milestone')` call to avoid double payment.
* **Event payload doc fixes**: `LandingBoostPayload.tricks` is a number (count banked). `ShardCollectedPayload.total` is cumulative shard
  POINTS; new optional `count` is the true shard count.

## Late-game freshness: air hazard, power-up floor, longer ramp (terrain engineer; additive)

* **Air hazards** (`HazardDef.placement: 'air'`, first def `roguePacket`: `data/hazards/rogue-packet.json`, 52x30 box, hit box 72 % x 80 %, crash,
  `shapeKey 'chasm'`, `colorKey 'danger'`, `minDistanceM` 1500). They are listed in `chunk.hazards` like any other hazard, so `RunScene.takeChunk`
  and `entities/Hazard.js` already spawn, draw and collide them with no scene change. **Air spawn contract**: `y` is the CENTRE of the box
  (Hazard.js already treats `placement 'air'` that way; no fix was needed), `rotationDeg` is 0, and `hazards` stays sorted by `x`. They never
  sit on the ground, so code that assumed `hazard.y == heightAt(hazard.x)` must check `defs[h.defId].placement` first.
* **Placement rules**: only in generated jump chunks (`gen-jump`), never chunk 0, never breathers, never before `AIR_HAZARD_MIN_M` (1500 m; a def's own
  `minDistanceM` can only raise it), at most one per jump. Chance per eligible jump: 25 % at 1500 m rising linearly to 55 % at 10 km (`AIR_CHANCE_*`).
  Position (fix round: LATE in the arc): `AIR_U_MIN` 0.55 .. `AIR_U_MAX` 0.8 of the lip-to-landing span AND at least `AIR_MIN_DX_PX` (400 px) past the
  lip; a jump whose span cannot fit that (0.8 x span < 400) gets no air hazard. Blocked (then retried once at another x, else skipped) by a power-up within 90 px,
  a shard, a gap or another hazard within 480 px. The def is picked by `weight` among air defs eligible at that distance (data driven).
* **Fairness guarantee (tested)**: the hit box sits ABOVE every no-hop flight with >= `AIR_CLEARANCE_PX` (70 px) of vertical clearance, for launch
  speeds from 0.75 x to max(`AIR_SPEED_HI_MUL` 1.6 x, expected speed) of the nominal launch speed (arcs rise monotonically with speed, so the fastest bounds
  the family; 1.6 x covers landing-boosted sleds). A normal flight always passes under it (nominal arc ~280-300 px below the box bottom, 1.25 x ~170 px);
  only a full hop at the lip (+360 px/s) reaches it.
  **Near miss**: flying under pays once: `RunScene.updateFun` pays an air-hazard near miss for an AIRBORNE sled crossing the box x with `0 < sled.y - box
  bottom < TUNING.airNearMissBelowPx` (= `AIR_NEAR_MISS_BELOW_PX` 360, which covers every still-airborne no-hop arc; tested). **Telegraph**:
  `TUNING.airWarnAheadPx` is 900 (box ahead of the sled): the hazard goes `alert`, `airWarn` plays, and `entities/AirTelegraph.js` draws a blinking STAY LOW
  marker with cascading chevrons and a dotted guide over the launch lip it belongs to (`Hazard.lip` = nearest `chunk.launches` entry before the box,
  set in `RunScene.takeChunk`), so the no-hop decision can be made before the lip. The hop tutorial hint still ignores air hazards. A "low" box near the
  lip-to-landing chord was rejected: a slow launch drops onto the landing ramp and no box can keep 70 px from that arc.
* **Determinism**: air placement is the last step of `_build`, draws only from `crng.fork('air')` (a fixed 4 draws per chunk) and reads, never changes,
  the shards / power-ups already placed. Air defs are kept out of the ground hazard list, so ground hazards, terrain, shards, zones and launches are
  bit-identical with and without the def (tested). Power-ups: the `rng.chance` draw is unchanged; only the threshold changed.
* **Power-up floor**: spawn chance = `max(POWERUP_FLOOR_FRACTION (0.4) x baseChance, baseChance / (1 + d / decay))`.
* **Hazard fill past 2000 m** (measured, 48 seeds `sim-01..48`): after `HAZARD_DENSITY_MUL` 3.4 the requested gap (1000 / density px) is below
  `HAZARD_MIN_SPACING_PX` 480 from ~600 m on, so slots sit exactly 480 px apart and `hazardDensity` / `HAZARD_DENSITY_TAIL` no longer change the ground
  count (only the share of eligible ground does). Only ~25-30 % of the ground is eligible (jump chunks, landing zones, breathers and margins are hazard
  free) versus ~73 % before the pacing rework, and a rejected slot (flat / slow-hazard / lip-zone rule) used to waste 480 px. From `HAZARD_RETRY_FROM_M`
  2000 a rejected slot is retried `HAZARD_RETRY_STEP_PX` 120 px further; placed hazards still advance by the full gap, so spacing and the hazard-free
  rules are unchanged and chunks starting before 2000 m are bit-identical. Result per 500 m band past 2500 m: ~3.8 ground + ~0.5 air crash hazards
  (was ~2.9 + ~0.5), ~6 hazards in total (was ~4.7); the pre-rework game had ~7 crash / ~14 total. The rest of the gap is the spacing ceiling
  (~2.08 hazards per 1000 px of eligible ground; the fill now reaches ~1.9), not a tunable constant.
* **Longer ramp**: `expectedSpeedPxS` = old curve (340 + 0.18 m, 620 at ~1556 m) + a tail of 80 px/s reached linearly at 6000 m (700 max). `hazardDensity`
  = old stepped curve (2.1 at 3500 m) + a tail of 0.7 reached at 10 km (2.8 max); other difficulty fields are unchanged. Later generated jumps may have
  a landing ramp up to 1300 px (was 1100) so a launch at 1.1 x the expected speed still lands on it. Terrain, shards and ground hazards of an existing
  seed are unchanged until the first jump / lip beyond ~1556 m; from there chunk lengths differ slightly and everything downstream is a different
  (equally valid) track. Power-ups differ from ~1800-2250 m on (floor).


## Integration: flow, spin cut, named combos, air drone, chase UI (integration engineer; additive)

* **Flow wiring** (`RunScene`): SIM9 ticks `score.tick(stepMs)` within each capped Matter physics substep, BEFORE settling its actual touchdown, so a just-expired multiplier cannot be refreshed and banked retroactively; the substep deltas sum to `simDt` = the scaled sim delta (slow-mo stretches the
  timeout, pause and hit-stop freeze it; never wall clock). `RunScene.emitFlow(fc)` turns any FlowChange (tick, `onLanding`, `onCrash`,
  `penalizeReset`) into `FLOW_LOST` (lost) or `FLOW_CHANGED` (changed). A shield-absorbed HAZARD hit calls `onShieldHit(false)` (flow halved, pending combo kept, no COMBO_CHANGED); a shield-absorbed body / landing / void crash
  respawns the sled and calls `onShieldHit(true)` (combo dropped, `COMBO_CHANGED reason 'crash'`). `HUD_SPEED_EVENT` (~10 Hz) now also carries `flow` and `flowFrac` so the HUD meter resyncs
  (covers the timeout refresh at the x3.0 cap, which is not a FLOW_CHANGED). UIScene: `FLOW xN.N` + draining bar under the pending-points line
  (top-right, visible only while flow > 1), colour steps at 1.5 / 2 / 2.5, pop per gain, `FLOW LOST` callout; pending points now include flow.
  SFX: `flowUp` (`opts.flow` raises pitch), `flowLost` (down-sweep), `airWarn`. RunRecord gets `bestFlow` (unhashed; the sanitiser drops it, so GameOver
  reads it from `REG.LAST_RECORD`). Rule change in ScoreManager: a sloppy landing that banked zero tricks no longer halves flow.
* **LandingPayload additive fields** (now in the `events.js` typedef): `comboName` (name of the jump just banked), `comboMult`, `flowUsed`, `midSpin` (grade dropped
  for an unfinished spin). `Sled.getFrameState()` passes `midSpin: heliPhase` (the drawn helicopter angle); TrickTracker applies the 60 deg tolerance and the
  coast / nudge exemption. HUD: the bank line `[SLOPPY ]NAME xMULT +POINTS` is its own big glowing line (scale 2, y 80, ~1.4 s; shortened until it fits 440 px at
  that scale) and the small popups (incl. `SPIN CUT  GRADE DOWN`) stack under it from y 100 at an 11 px pitch, so they never overlap. Top-right stack: COMBO y4,
  value y13, info y31, pending y43, FLOW y62 + bar y72 (pop peaks 2.5 / 2.3 keep them apart).
* **Milestones**: `RunScene.updateFun` uses `score.checkMilestones(metres)` only (no second `addBonus`). `MilestonePayload.sector` is now the sector
  just completed (500 m -> 1; it used to send `n + 1`), `points` is the paid bonus, shown in the SECTOR strip. **Shards**: `SHARD_COLLECTED.count` is sent
  and `SHARDS N` shows the count.
* **Tuck hint** (fix round): due after `TUNING.tuckHintMs` (800) of grounded, not tucking, slope >= `tuckHintSlopeDeg` (12) and speed > 150. It waits for any
  other hint to clear (dropped after `tuckHintWaitMs` 8000), stays up at least `tuckHintShowMs` (2500; hides when the steep stretch ends, forced at +1300)
  and is only retired (persisted `bb.tutorialDone`) when the player tucks on the ground or it has been shown `tuckHintMaxShows` (2) times (count in
  localStorage `bb.tuckShows`). At most one show per run.
* **Rogue Packet** (`Hazard.shapeKey 'drone'`): halo + rotor bars + hull + white-hot core, visual-only bob, faster pulse / tighter ring once `hazard.alert`.
  RunScene sets `alert` and plays `airWarn` once when an air hazard is within `TUNING.airWarnAheadPx` ahead. Air hazards are excluded from the "hop" tutorial hint
  (hopping is the wrong answer), and their near miss is the airborne pass-under window described in the air-hazard section above; `h.cy` is always the box centre.
* **Chase UI**: GameOver shows `NEW SEED BEST` / `SEED BEST n` (top right of RUN REPORT; on a daily seed it reads `NEW TODAY'S BEST` / `TODAY'S BEST n`
  from `getDailyStats`) and a `DAILY STREAK n DAYS` row for daily runs. The report keeps at most 8 rows by priority (DISTANCE, TRICKS, BONUSES, RESET PENALTY, BEST COMBO, BEST FLOW,
  SHARDS, NEAR MISSES, DAILY STREAK, BEST AIR, RUN TIME), dropping the lowest first. The right-column point rows add up to the score: DISTANCE + TRICKS +
  BONUSES (`rec.bonusPoints`: shards, near misses and milestones together) - RESET PENALTY (derived: parts minus score, only shown when > 0); SHARDS / NEAR MISSES
  are plain counts. The device-best lines under the chase line read `DISTANCE BEST!` / `SCORE BEST!` (+ `PREV n`) or `n M SHORT OF` / `DISTANCE BEST`, so they can never be
  confused with the seed / today's SCORE best line above them. Row pitch 9, ledger hash y 132, share seed y 144. Title daily strip: `NEXT PATCH IN 3H 12M` plus `STREAK n   TODAY'S BEST n` or
  `NOT PLAYED TODAY`, refreshed every 15 s by a scene timer.

## Addendum: landing / terrain-contact fix

Runs used to end in a `terrain` crash (head or torso on the ground) a moment after a good or perfect landing. Cause: Matter's SAT takes the minimum-overlap axis, which at the 16 px terrain quad seams is often a wall axis or one of the 24-gon runner's own 15 degree face axes ("ghost" normal, 15-60 degrees off the surface). A sled sliding at 700+ px/s then gets a spurious normal velocity and an off-centre impulse at a runner 15 px from the centre of mass: +/-400..700 deg/s of spin out of nothing, plus a hidden speed-dependent drag (grounded cruise was a flat ~480 px/s). `systems/TerrainContact.js` (installed by `RunScene.create` on `Matter.Collision.collides`) rewrites every runner/terrain contact to use the quad's top-face normal (`TUNING.terrainSnapNormals`; contacts deeper than `terrainSnapMaxDepthPx` below the top plane, i.e. gap walls, are left alone, head and deck contacts are never touched). On top of that, `TUNING.landSpinMaxDegS` caps the angular velocity for `landSettleMs` after a touchdown (a rigid sled landing on one runner first otherwise rocks onto the other), `Sled` reports the pre-solve `impactVx/impactVy` so `TrickTracker` grades the real impact speed (the solver has already removed the normal part on the landing frame), and `groundResist` went 0.04 -> 0.10 to give back part of the pace the ghost drag used to remove (jump airtimes stay at or above the old ones). A head-first landing or an over-rotated flip still crashes. `tools/sim/run.mjs` gained `--seedPrefix` (independent seed set) and `--sub N` (last N physics sub-steps before a crash).

## Addendum: first-run hint scheduler

`systems/HintScheduler.js` (pure, tests in `tests/src/hintscheduler.test.js`) owns what the first-run hints do on screen; `RunScene.updateFun` only reports triggers
(`wants`) and `UIScene` draws one slot (`HINT_TEXT` per input mode). Rules: one hint at a time; priority push > hop > boost > flip > tuck; each stays at least
`minMs` (1.5 s; tuck 2.5 s) unless the player does the action (`tutDoneId`, persisted in `bb.tutorialDone` as before), and at most `maxMs` (a timed-out hint must
see its trigger drop before it can return, so nothing sticks); 0.6 s gap after any hide; nothing before 2.5 s of run time except push; a higher-priority want
replaces the current hint once it has had its minimum; while a ground hazard is within ~3.4 s of travel and hop is not yet done, only push / hop may start. Triggers:
hop = next ground crash hazard within 1.2 s of travel (350..1300 px; the hazard itself only enters the view ~0.5-0.65 s before the sled reaches it); flip = a launch lip within 1.3 s of travel (grounded) or airborne > 250 ms with no trick
(max 3 shows per run, text says "IN AIR ..."); boost = 2.2 s after a landing boost (explains what just happened, then done); tuck = steep grounded descent, only after the
first landing and 12 s of run time, once per run, retired after `tuckHintMaxShows`. The "land" hint (dead: needed > 25 deg off the slope < 110 px above ground) is removed.
Tunables are a constants block at the top of RunScene.js (`HOP_*`, `FLIP_*`, `BOOST_HINT_MS`, `TUCK_HINT_MIN_RUN_MS`); `TUNING.tuckHintWaitMs` is now unused. `UIScene`'s
8 s `HINT_MAX_MS` is only a backstop. Measured with `tools/sim/hints.mjs` (stats from a `run.mjs --out` file) and `tools/sim/shots.mjs hints` (real screenshots).

## Addendum: camera at speed (second zoom stage)

Runs now cruise at ~650 px/s and peak at 1050-1200 px/s (up to ~1700), past the 340-700 px/s the camera was tuned for. `RunScene.updateCamera` keeps the old curve
(zoom 1 -> `TUNING.zoomMin` 0.82 between 150 and `zoomSpeedHi` 600 px/s) and adds a second stage: zoom keeps easing out to `ZOOM_FAR_MIN` 0.62 at `ZOOM_FAR_SPEED_HI`
1200 px/s, and the look-ahead grows by `LOOK_FAR_EXTRA_PX` 90 between 600 and 1000 px/s (the x follow lag eats most of the base look-ahead at speed). The rider is kept at
least `RIDER_MIN_SCREEN_X` 36 screen px from the left edge (the zoom code pins the rider's screen x to `sled.x - _camX`, so the bound is in screen px). These constants sit at
the top of RunScene.js, not in PhysicsTuner. Camera only: no physics input reads it (`run.mjs --policy hop` is identical with and without it). Nothing else needed to change for the wider
view: background and flash layers are counter-scaled by `applyZoomCompensation` (checked down to 0.62), terrain is generated `TERRAIN.bufferAheadScreens` (3) screens ahead (the view
is < 1.7 screens wide), and the cull margins use the zoomed `_view`. Measured with `tools/sim/shots.mjs zoom <dir> '{"trace":true}'` (hop-policy runs, real screenshots at scale 2;
`shots-zoom.js`): warning time = (view right edge - sled x) / speed.

## Addendum: flip release window and stall net on up-slopes

Flip timing was too strict: with the old hands-off air rules (`airIdleLevelK` 8, `airIdleSpinDamp` 3) a released flip kept spinning at 600-1000 deg/s for about a second, so every 100 ms of late (or early) release moved the landing angle by ~120 deg. `airIdleSpin()` (PhysicsTuner, used by `Sled.applyControls` when airborne with no tilt input) springs the nose toward a landing attitude by the shortest way (`airIdleLevelK` 80, error clamped to +-1.2 rad) and damps spin hard (`airIdleSpinDamp` 12); `maxAngularVelDegS` went 1100 -> 900 and `airTiltFeelMul` 3.6 -> 5 so a held flip still gives ~600 deg in 1.0 s and ~960 deg in 1.4 s (sim, held to touchdown: 627 deg at 1054 ms, 944 at 1394 ms) and a double flip stays possible on long air. That first pass fixed the early side only; a second pass fixed the late side:

* **Landing forecast.** `RunScene.airForecast` (one call after `dropAheadDeg`) sets `sled.airEtaMs` (ballistic ms to touchdown, 20 ms grid) and `sled.airSlopeDeg` (ground slope there) every frame; `Infinity` / `null` when grounded or nothing is hit within 2.5 s.
* **Aim.** With a forecast `airIdleSpin` settles at `airSlopeDeg + airIdleLandOffsetDeg` (15) instead of the velocity heading. A sled coasting on its velocity lands ~16 deg nose-down of the slope on generated jumps (median 16, p10-p90 12-19), so 15 keeps an unattended landing "good" exactly as before (hands-off 100 seeds: unchanged, median 365 m, 0 terrain crashes; aiming at the slope itself gave ~100 % perfect landings, +25 % top speed and made the hop policy fail earlier, so it is deliberately not done). Without a forecast it falls back to the heading.
* **Urgency.** The spring is multiplied by u^2 and the damping by u, u = clamp(`airIdleUrgencyRefMs` 400 / `airEtaMs`, 1, `airIdleUrgencyMax` 3): unchanged above 400 ms of air, 4x spring at 200 ms, 9x from 133 ms. The levelling that used to need ~0.45 s from the half-turn tipping point needs ~0.2 s in the model, while `maxAngularVelDegS` still stops a sled released inverted with < ~100 ms left from getting round.

Why the old window looked non-monotonic (measured on the old code): the harness's forward model matched the game (median landing-angle error 2 deg, p90 13 deg over 626 on-time attempts), but its "ideal" frame required a landing within 12 deg of the slope while a hands-off sled settles ~16 deg off it, so the ideal frame was the instant a still-swinging sled passed through the slope angle, a knife edge that has nothing to do with when the flip is done. 100 ms earlier the sled was one swing short (sloppy), 200-300 ms earlier it was at or before the half-turn tipping point and unwound to a plain clean landing, and from the tipping point (a release at ~0.42 s of hold, 140-190 deg round) the weak spring needed more air than was left, hence the crash dip at -200 ms. The policy now defaults to `--flipCleanDeg 28` (TrickTracker's "good" band = a clean landing); `--flipCleanDeg 12` gives the old definition. A single flip on a 0.7 s jump is still possible (hold ~0.50-0.65 s).

Result, `tools/sim/run.mjs --policy flip --releaseLateMs N --seeds 96` on two seed sets, clean / sloppy / crash over all attempts (see the commit message for the tables): releases from 300 ms early to 200 ms late land on the runners 89-95 % of the time with 5-11 % crashes, clean being 75-87 % (HEAD before this pass: 24-80 % clean, 8-41 % crash); 300 ms late is 49-53 % clean / 10 % crash; 400 ms late 26-28 % crash. Of the attempts whose ideal frame leaves >= 300 ms of air, 97-100 % are clean up to 200 ms late. Holding tilt into the ground (`--releaseLateMs 5000`, no emergency release) still crashes 41-47 % (38-42 % before), and a sled released inverted with < ~100 ms of air still crashes (unit-tested): holding tilt is not helped, the spring only acts with no input. The remaining crashes are attempts with little air to begin with (the flip was marginal) and releases with < ~150 ms left.

The stall safety net is `stallNudgeStep()`: it tests the signed speed along the slope (so a sled rolling backwards down a gentle up-slope counts as stalled), pushes net of gravity on up-slopes, and runs to `stallNudgeToPxS` 130 at `stallNudgeAccelPxS2` 240. On the 12 deg start ramp it now starts 0.6 s after the brake is released (was 1.4 s) and is back above 120 px/s after ~1.3 s (was 3.3 s). `tools/sim/run.mjs --policy stallProbe --probeKind first|flat|down|upGentle|upSteep` measures it; `--flipTargetDeg 700` makes the flip policy aim for a double flip.

## Addendum: pilot profile, Resonance and Sync Levels (W1)

`ProfileStore` owns the player profile under its **own** `localStorage` key `bb.profile`, with its own `v` field. It is deliberately not in the settings blob: `sanitizeSettings` drops unknown keys, so anything parked in settings is erased on the next load, and reusing settings would force a `STORAGE.saveVersion` bump and a migration for every existing device. Nothing here writes `STORAGE.saveVersion`, and no profile field enters `computeLedgerHash` — a run's ledger hash must stay reproducible from the run alone.

`Progression.js` is pure: `xpForRun(record)` returns `{total, parts[]}` (1 XP per 10 m, per 50 score, 12 per trick, 5 per shard, 2 per near miss, 1 per 2 s of airtime), `levelForXp`/`xpToNext`/`rewardsForLevel` read the table from `src/data/progression/levels.json` (30 levels, `cap`, `biomeOrder`). Thresholds and rewards are data, so tuning is a JSON edit and no code path has a magic number. `level` is always **derived** from `xp` on load and on credit; a stale or hand-edited `level` field can never disagree with XP.

`ProgressionService` is created in `createServices` under `REG.PROGRESSION`. It subscribes to `EVT.RUN_END`, credits the record **synchronously** (so Game Over can read the awards on its first frame without awaiting anything), persists, and publishes the awards under `REG.LAST_AWARDS`. **`RunScene` is not edited** — the service observes the event the scene already emits, which is why this workstream needs no change to the run loop, the record builder or `computeLedgerHash`. Crediting is idempotent on `record.ledgerHash` (falling back to `record.id`) against a bounded ring (`CREDITED_MAX` 500), so a replayed `RUN_END`, a double scene start or a retry cannot double-award. On a device that already has history the profile backfills lifetime totals and XP once from `SaveStore.getRecentRuns`; the backfill is skipped when the profile already has runs, and a missing or throwing `SaveStore` never blocks boot.

UI is additive and cosmetic. `GameOverScene._buildProgression` draws one row in the band under the buttons (`y` 250): `+XP`, the Sync Level line, a Resonance bar for progress inside the level, and on a level-up the unlock line. It is driven off `REG.LAST_AWARDS` and renders nothing when no awards were published. Retry is still frame-one: the XP is already committed before Game Over ever runs, and `retry()` cancels the pulse tween. `TitleScene` gains a `SYNC LEVEL n` badge (level + title) and a `PROFILE` item opening `ProfileView` in `src/ui/Views.js` (`View` is not exported, so the view lives in that file rather than in a new module). All new graphics register a `Theme.bind` callback and are unbound on scene shutdown, so the colour-blind palette swap repaints them live.

Biome rewards are playable from W3 for the batch-1 biomes (see the W3 addendum below); the profile now reports how many are shipped rather than a `SIGNATURE LOCKED - COMING ONLINE` note that stopped being true. The profile is not in the `BB1:` share code; that is a follow-up.

## Addendum: biomes (W3, terrain + meta; additive)

Five batch-1 biomes, each a sector of ordinary terrain with one signature mechanic:
Debutmont, Garbage Dump Glacier, Pyramid Peak, Underwater Mountain and Crystal Cavern.

**Selection is pure and cheap.** `biomeForSector(seed, sector, mask, defs)` answers from
`(seed, sector, mask)` alone - never from how much terrain has been generated or in what order -
so a chunk built late by streaming is identical to one built early. It draws from
`Rng.fork('biome')`, an independent stream, so *asking* the question never advances the terrain,
hazard or shard streams. Since #65 **Debutmont is the base biome** (`BASE_BIOME_ID`, one constant
shared by terrain and profile, defined in `data/biomeAliases.js`): sectors 0-1, mask 0, a mask with no eligible biome and
the base-weight draw (2.2:1) all answer Debutmont, never `null`. The home biome is left out of the eligible
pool, so its mask bit is a no-op and it is never double-weighted. The draw count and order are unchanged,
so every non-home pick for a seed and mask is what it was.

**Arcade is the bridge between biomes (#65).** `biomeAtPosition(seed, xM, mask, defs)` is the biome at a position:
the sector's biome, except the first `arcadeBridgeLengthM(sectorStart)` metres of a sector whose biome differs
from the previous sector's, which are arcade (`null`). Length is 1/6 of `SECTOR_M` (~83 m) at the run start,
rising linearly with the sector's start distance to 1/4 (125 m) at 5000 m, then capped
(`ARCADE_BRIDGE_MIN_FRAC`, `ARCADE_BRIDGE_MAX_FRAC`, `ARCADE_BRIDGE_RAMP_M`). It depends on distance only, never on
progression, input or BSOD, and draws nothing new, so the same seed and mask give everyone the same course
(leaderboards, Daily, ghosts). **Chunk snapping and the cap:** the generator assigns a chunk by its start x, so a
bridge is whole chunks: the first chunk of a changing sector (its breather) is always arcade, so every biome change
has at least one bridge chunk, and a later chunk is arcade when it starts inside the window **and** ends within
`ARCADE_BRIDGE_CAP_MUL` (1.5) x the target length of the bridge's own first chunk (~125 m at the start, 187.5 m
from 5000 m). A chunk that would overrun the cap is built as the sector's biome instead (the generator replays the
chunk's own def pick and length draw as arcade to ask: `_arcadeEndPx`), which ends the bridge. Measured over
13648 bridges (400 seeds, 20 km, full mask): min 46 m, median 98 m, p95 131 m, max 187 m (before the cap: median 107 m, p95 258 m, max 320 m). The sector
biome picks (`biome:${sector}`) are untouched by the cap. Bridge terrain is exactly the old
arcade (null-biome) generation: no biome preference, zone or spawns; physics is unchanged. Every consumer asks
the generator (`TerrainGenerator.biomeAtX(xPx)`, the chunk containing x) rather than computing a sector biome:
`RunScene` palette, motif, `BIOME_ENTER` (fires on entering Debutmont at the start, each bridge as
`{id:null, entering:false}`, and each biome after it) and `bsodAtmosphere`. `detectBiomeVisits` asks the same
generator answer (`biomeAt: (x) => terrain.biomeAtX(x)`), so discovery and the drawn terrain agree at bridge edges. `tools/sim/biome-layout.mjs` prints the layout.
Terrain for a given seed and mask changed, so `SIM_REVISION` is 5 (the ruleset time capsule, `src/systems/replay/ruleset.js`); `GHOST_PHYSICS_VERSION` stays 1 (Replay Contract v1 section 7.2: it is kept only for legacy tape mapping).

**Bridge presentation (#65, cosmetic only).** `TerrainGenerator.bridgeSpanAt(xPx)` is a read-only scratch query for the bridge
containing x (`{startX, endX, fromId, toId}`, or null). `systems/BiomeTransition.js` (pure: no time, state or RNG) turns the sled's x
within that span into a look: over the first 25 % of the bridge the outgoing biome dissolves into a pixel-block veil (veil
0 -> 1, an 8x8 Bayer ordered dither of 16 px blocks), the middle is pure arcade, over the last 25 % the incoming biome is revealed
(veil 1 -> 0); the look (palette / motif / glitch set) only changes while the veil is full. Reduced motion (`ui/Motion.isReducedMotion`)
is the hard cut: the veil is on for the whole bridge and the look is the generator's. `RunScene._updateLook` applies it;
`BIOME_ENTER`, discovery, music and every gameplay consumer keep asking the generator. A look change inside a bridge calls
`refreshPalette()`, which repaints the terrain graphics only (`TerrainMesh.redrawChunk`; since #140 no repaint touches a collider),
so the dissolve cannot affect the simulation whatever the effects setting.
`entities/BiomeFx.js` draws behind the play layer (one screen-space container at depth -99): Debutmont (dithered-sky and ridgeline SVGs,
blocky pixel snow, an occasional scanline shimmer; `Background` skips its own sky bands and ridges via `setSkin('pixel')`), Garbage Dump
Glacier (trash blocks and colour-channel-offset fragments), and the arcade bridge (veil blocks, dithered sky, sun, skyline, neon
perspective grid, CRT scanlines). Typed-array pools, whole-pixel positions, no per-frame allocation; reduced motion stops the
time-driven parts. Randomness is the cosmetic stream `cosmeticRandom('biomefx')`. The art is `public/assets/backdrop/*.svg`, generated by
`tools/backdrop-art/generate-backdrop-art.mjs` (greyscale, pixel-aligned, tinted from the live palette like the menu art; loaded by
`ui/BackdropArt.js`, optional). Tests: `biome-transition.test.js`, `biome-fx-cosmetic.test.js` (terrain digests and the repaint schedule
identical with the effects on, off or absent). `tools/sim/shots.mjs bridge` takes the before/after shots.

**A biome's chunk templates are a preference, not a filter.** If its templates are not eligible
at that distance the sector still gets ordinary terrain, so a biome can never leave a hole in
the ramp.

**The `biome` field is written only inside a biome, and cleared when a pooled chunk returns to
base terrain.** Absent rather than `null`, deliberately: `JSON.stringify` of a mask-0 chunk stays
byte-identical, which is what the pre-existing hazard-fill digest guard compares.

**Mechanics.** Four are physics multipliers on the existing `terrainMods` schema (powder drag,
sticky ground, thermal loft, slow-motion). Crystal Cavern's is scoring: "tricks landed inside
score a combo bonus" cannot be written as a physics multiplier, so its mod carries an additive
`scoreMul` applied to banked trick points only - never the flat perfect-landing bonus, never
distance points, clamped to `>= 1`. This is an intentional extension of `TerrainModDef`.

**Persistence.** `biomeMask` is in `sanitizeRun`'s whitelist and is *not* part of the v1
`computeLedgerHash` (which hashes a fixed field list); there is no `saveVersion` bump. Since decision 6
the v2 hash (new records, `hashV: 2`) covers `biomeMask` and `modded`; see the addendum at the end. Records
written before W3 have no field and count as mask 0. `getSeedStats` takes an opt-in `biomeMask`
scope so seed-best compares within one mask; omitting it keeps pre-W3 behaviour.

**Daily.** The Daily Run's mask is derived from the UTC date key alone - identical for every
player, independent of unlocks (a locked biome may appear as a preview, per D6). 9-day cycle:
4 clear days plus one day per batch-1 biome. SUPERSEDED by decisions 1/2 (addendum at the end):
`getDailyStats` now counts only official Daily runs and filters on the date's mask explicitly.

**UI.** Biome entry raises a banner through the same serialised strip queue as the mission
toast, so the two cannot overlap. Seed entry accepts `seed@mask`; a bare seed parses to mask 0
and is used verbatim, and a malformed suffix is treated as a seed rather than rejected.

**Gates.** Golden mask-0 terrain test pins 300 chunks x 5 seeds before any generator change.
Per-biome screenshots in both palettes come from `node tools/sim/shots.mjs biomes <dir>`, each
reporting the biome its generator claims, so a shot that fell back to base terrain fails loudly.
Per-biome simulation uses `--biomeMask`, and the mask must ride on the run *options* (the page
reads `o.biomeMask`), not only on `params` - having it only in `params` silently played every
mask as 0.

Gate harness: `node tools/sim/shots.mjs progression <dir>` (`tools/sim/shots-progression.js`) drives the **real** services and scenes — a real `RUN_END`, real `GameOverScene`/`TitleScene` — and shoots Game Over (normal and level-up), the Title badge and the Profile view in both palettes. The XP awards in those shots come from the real credit path, not from faking the registry.

## Missions

`Missions.js` implements deterministic mission selection and evaluation. It seeds draws from the profile mission counter, sorts eligible templates by ID, and filters biome- and rule-ineligible templates. Tier determines the reward multiplier AND gates offerability by Sync Level (D7): `missions.json` carries a `tierUnlock` map of tier → minimum Sync Level (tier 1 at level 1, tier 2 at 3, tier 3 at 6, tier 4 at 10), and `drawMissions` drops templates above the profile's unlocked tier before the seeded pick. Thresholds live in data so they can be tuned without a code change; tier 1 is always open. If the unlocked tiers cannot fill three slots, the draw widens only up to the highest tier at or below the profile's ceiling, never above it — D7's wording is "fall back to the highest unlocked tier, never an empty slot", so a thin pool may return fewer than three missions rather than leak a tier the player has not unlocked. Gating never re-rolls or drops a mission already in a slot: a profile that drew a tier-3 mission before this rule existed keeps it and keeps its progress, and only its refills are gated. `MissionsService` publishes active mission progress through `REG.MISSIONS` and sends live completion notifications; `ProgressionService` invokes its payout path only after a run has been credited, so replaying a credited run cannot pay a mission twice. A template with `needsBridges` (#65, "Ride 3 arcade bridges", metric `bridges`) is offered only when the profile has earned a biome besides the base one and has not switched every earned biome OFF (no bridge can exist otherwise). `MissionsService` counts it live from `BIOME_ENTER {id:null}` (RunScene's once-per-entry bridge announcement; the opening Debutmont enter has an id), resets it on `RUN_START`, and hands the total to the roll as `bridges` beside the RunRecord, which does not carry it (so no ledger hash changes). Likewise `pickups` (power-ups collected this run by id, counted from `POWERUP_COLLECTED`) feeds "Grab 3 Maple Wax in a run" (`t4-pickup-maple-wax`, metric `pickups`, `pickup: mapleWax`); it replaced the trivial "1500 m in Debutmont", and `ProfileStore` migrates an active old `t4-biome-debutmont` to it (`RETIRED_MISSIONS`). Meta only: nothing in the simulation reads either counter. Mission state and rewards persist in `bb.profile`. Title, Pause and Game Over render the published view; HUD notifications share the milestone strip.

## Addendum: shop autoprompt (W4.1, additive)

Marvin's request was that a player who can afford something be taken to the Shard Shop instead of having to
remember it lives behind PROFILE. The shop is **not** added to the Title menu (that stays as it was); Game Over
gains a popup and a hint.

**The decision is made once, at credit time, by `ProgressionService`.** It is the only place that sees the
profile both before and after the run, so it is the only place the question "did this run *newly* make
something affordable" can be answered exactly. `credit()` and `applyMissions()` both move the bank, so
re-deriving a "before" afterwards from the credit would be arithmetic guessing; instead the service snapshots
`shopState(profile)` (bank, level, owned cosmetics) before crediting, and `newlyAffordable(before, after)`
compares the two. The answer is published as `shopAutoprompt` on the awards view in `REG.LAST_AWARDS`; Game
Over renders it and never re-derives economy rules. Nothing is stored, so there is no new profile field, no
`saveVersion` bump and no ledger-hash change.

**`ShopPrompt.js` restates the shop's refusals rather than calling them.** `isOwned`/`purchase` resolve their
item from the module-level `SHOP_ITEMS`, so they cannot be pointed at another catalogue, and a helper that
quietly judged a different list than the panel it opens would be worse than useless.
`tests/src/shop-prompt.test.js` instead proves equivalence with the real `purchase()` across a grid of banks,
levels and owned-sets on the shipped catalogue, in both directions: anything the helper calls affordable is
actually buyable, and when every purchase is refused the helper says so. Repricing the catalogue therefore
breaks the tests rather than the popup.

**Frequency.** The popup fires only when this run crossed something; the footer hint `SHOP: B / LB` shows
whenever anything is affordable, popup or not, so a stockpile player is told about the shop without being
interrupted every round. `B`/`b` is a `MenuInput` action (`shop`) rather than a scene-local key listener, so it
gets the same debouncing and a gamepad equivalent, and the footer cannot advertise a key that does not exist.

**Retry always wins** (superseded in part by Marvin decision 7, 2026-11-14; see the decisions 7/8/9 addendum).
Input is live from the first frame; any action or tap before the timer fires cancels the popup; while the shop is
open, `retry` (Space / pad RB) closes it and retries, `confirm` (Enter / pad A) acts on the highlighted row once
the shop is armed (before that it closes and retries), `cancel` closes it back to Game Over, `alt` closes it and
starts a new seed. The pending timer, the arm timer and the open view are all torn down on shutdown, so nothing
fires into a scene that is gone.

**Known gap.** `notes/cc-friday-shop-popup-2.txt` mentions "boosts not yet owned" as part of purchasability.
Boosts have no price in this economy — they are level rewards toggled in the shop, not bought — so there is
nothing for that clause to match. Inventing a price would be a new economy decision, which is Marvin's, not
this workstream's.

## Addendum: W6 biome backdrops (audit T1, additive)

Every biome file's `background` id must name an entry in `Background.MOTIFS`;
`tests/src/biome-background.test.js` reads the biome files to check this, so a new biome that names a
motif which does not exist fails the suite. Before this fix, the six W6 biomes fell back to base ridges.
`MOTIFS` now has 11 ids. Each W6 id adds a silhouette shape and a decor pass:

| motif | biome | silhouette shape | decor |
|---|---|---|---|
| `stars` | Space Mountain | `crater` | starfield (twinkles) and a ringed planet |
| `candy-stripes` | Candy Cane Canyon | `gumdrop` | candy-stripe sky, canes (far ridge), lollipops (near ridge) |
| `jellyfish` | Sky Jellyfish Mountain | `cloud` | drifting, pulsing jellyfish with swaying tendrils |
| `brass-pipes` | Steampunk Slopes | `works` | turning gears behind the roofline, a brass pipe run |
| `dew-drops` | Micro Mountain | `moss` | grass blades with big dew drops that glint |
| `vents` | Vertigo Vents | `cone` | an amber glow at each vent mouth and a rising smoke plume |

New pure exports in `entities/Background.js`. Both are additive; `motifGeometry` is unchanged.
* `motifProfile(shape, wx, seed) -> number`: the layer height sample. `Background._profile` delegates to it.
  The batch-1 shapes and `peak` give the same values as before.
* `motifDecor(motif, scrollX, timeMs = 0, seed = 0) -> ReadonlyArray<primitive>`: the decor primitives
  (`poly`, `line`, `circle`, `rect`). Each primitive has a palette colour **key** and a `depth`:
  -1 = sky, k = drawn right after silhouette layer k. The decor is a pure function of its arguments.
  The layout comes from a seeded mulberry32, and the animation comes only from `timeMs` (scene time).
  `Background` uses `decorSeed = 0`, so one biome looks the same in every run.
  It returns `[]` for the base backdrop and the five batch-1 motifs, so their draw calls are unchanged.

Rules (the tests enforce them):
* Decor never uses the `danger` key, so only hazards use the hazard colour. The renderer test records
  real draw calls with a sentinel `danger` value.
* Decor stays inside 480x270, with an overhang of up to 96 px at the left and right edges only.
* Each frame is still redrawn into one Graphics. A W6 frame makes at most 2.5x the draw calls of the
  base backdrop (2.1x was measured for `candy-stripes`, the most expensive).

## Addendum: biome full treatment, B0 groundwork (engine only; additive)

B0 adds the engine for each biome's own hazard and power-up (spec `bitstream-biome-treatment-spec.md` §5-§6). It ships
**no biome content**: B1-B4 add the JSON under `data/hazards` / `data/powerups`. With no biome defs in content every
generator output is unchanged except the E7 zone rule below, and mask 0 is byte-identical (golden `shape` / `full` /
`complete` digests unchanged).

**New data fields (all optional, `data/schemas.js`).**
* `HazardDef.biome` / `PowerUpDef.biome`: a biome id. Such a def is removed from `hazardList`, `airHazardList` and
  `powerupList` in the `TerrainGenerator` constructor and kept in `biomeHazards[biome]` / `biomePowerups[biome]`
  (sorted by id). Base placement can never see it, so it cannot move a mask-0 pick (isolation test:
  `tests/src/biome-spawns.test.js`).
* `HazardDef.spawn.baseChance` (biome defs only) and the existing `PowerUpDef.spawn.baseChance`: the chance of the
  chunk's biome slot, capped at `BIOME_SPAWN_MAX_CHANCE` 0.5 (default `BIOME_SPAWN_DEFAULT_CHANCE` 0.2). Biome
  power-ups have no distance decay. `weight: 0` disables a biome def (the biome pick does not use `weight || 1`).
* `HazardDef.onHit.effect` gains `'blind'` `{durationMs?, visibility?}` and `'gust'` `{impulsePxS:[x,y]}`.
* `PowerUpDef.effect.kind` gains `'ward'` `{durationMs, mods[], hazards[], effects[]}`, `'glide'`
  `{frictionMul, durationMs}` and `'stabilize'` `{landingToleranceDeg, bounceMul?, durationMs}`.
* Not in B0: `HazardDef.motion` (`roll`, `gate`) lands with B3.

**Generator pass `_placeBiomeSpawns`.** Runs last in `_build`, after `'air'`, only when the chunk's `biome` is set, from
`crng.fork('biomeHaz')` and `crng.fork('biomePu')` (forks derive from the chunk root's initial state, so creating them
moves no other stream). One hazard slot and one power-up slot per biome chunk; each draws exactly `BIOME_SLOT_DRAWS` (5)
numbers up front whatever happens, so one def's chance or a blocked position never shifts the other slot.
* Ground hazards: never on bridge or jump chunks; `BIOME_EDGE_MARGIN_PX` (= `HAZARD_END_MARGIN_PX`, 240) from the chunk
  edges (spec asks >= 96; 240 is what keeps `HAZARD_MIN_SPACING_PX` across a chunk border); the breather calm stretch,
  lip windows `[lip.x - 40, zoneEnd]`, `noHazX`, gaps +/- 96 px, 480 px from any hazard, 90 px from any power-up,
  the base slope / flatness rules, `slow` only before a descent, and no shard over the box. The slot scans the chunk in
  `HAZARD_RETRY_STEP_PX` steps from a drawn start. `chunk.hazards` stays sorted by x.
* Air biome hazards (`placement: 'air'`): only in jump chunks, using the base jump-arc box (`_airSpan`, `_airHiMul`,
  `_tryAirBox`, shared with `_placeAirHazard` and maths-identical to it) and `_airBlocked`. `AIR_HAZARD_MIN_M` does not
  apply (biome sectors start at 1000 m); the def's own `minDistanceM` does.
* Power-ups: inside the same edge margins, > 480 px from x = 0, 90 px from any hazard and any power-up, clear of gaps and
  shards, lifted like a base pickup. `chunk.powerups` stays sorted by x.
* Measured with a fixture def at chance 0.5: base hazards fill eligible ground every ~480 px past 2 km, so the 480 px
  spacing blocks most ground slots (about 10 placements per 4 seeds x 300 chunks at mask 2|32). Power-up slots land
  in about 40 % of biome chunks.

**E7 zone rule (Marvin 2026-11-14, audit TERRAIN-1).** In a chunk where `_placeBiomeZone` placed a zone, `_placeZones`
places no template zone, so a biome mechanic is never multiplied into its opposite. `_placeBiomeZone` now runs first
and returns whether it placed a zone; both keep their own forks. This moves mask != 0 zones (and seed@mask bests) on
purpose; mask 0 is untouched. Test: `tests/src/biome-zone-stacking.test.js`.

**Effects (math in pure modules; scenes only call them).**
* `systems/Wards.js`: `emptyWards()`, `addWard(state, id, effect)` (durations clamped to `WARD_MIN_MS`..`WARD_MAX_MS`,
  4-6 s; re-collecting refreshes), `tickWards(state, dtMs)` -> `{state, expired}`, `isWarded(state, {modId|hazardId|effect})`,
  `wardMsLeft(state, id)`. `PhysicsTuner.getEffective` skips a zone whose mod id is warded. `RunScene.onHazard`
  ignores a hit whose hazard id or effect is warded (no `HAZARD_HIT`), and a warded slow / scramble / blind stops acting.
* `systems/BiomeEffects.js`: `gustImpulse` (vector norm capped at `GUST_MAX_PX_S` 180), `blindVisibility` (>=
  `BLIND_MIN_VISIBILITY` 0.35) and `blindOverlayAlpha(msLeft, totalMs, visibility)` (pure function of time, <= 0.65),
  `glideFrictionMul` ([0.2, 1], default 0.7), `stabilizeToleranceDeg` ([0, 30]), `stabilizeBounceMul`,
  `resolveLanding(landing, toleranceDeg, TUNING)` (the old forgiveness rule when the tolerance is 0; a stabilize
  re-grades with the angle reduced by the tolerance and widens the forgiveness angle by it), `hazardEffectDurationMs`,
  `timedPowerupMs`, `hazardColorKey` (a **biome** crash hazard is always `danger`; base defs keep their colorKey),
  `hazardDrawKind` / `powerupDrawKind` (an unknown shapeKey draws the generic shape).
* `TunerContext` gains `wards`, `glideFrictionMul` (multiplies `frictionMul`, so `groundResist`; Matter friction stays
  0) and `stabilizeBounceMul` (multiplies `bounceMul`).
* `RunScene`: `onHazard` branches `blind` (white flash, then a `palette.bg` overlay `blindRect` at depth 99 under the
  flash; the HUD scene stays on top) and `gust` (`_addSledVelocity` through Matter `Body.setVelocity`); `onPowerUp`
  branches `ward`, `glide`, `stabilize`. New methods: `physicsContext(pad, zoneDefs?)` (the frame's tuner context, now
  testable), `_resetBiomeEffects()`, `_endBiomeEffects(reason)`, `tickBiomeEffects(dt)`, `updateBlindOverlay()`.
  Events reuse the existing payloads: `HAZARD_HIT.effect` can be `'blind'` (with its duration) or `'gust'`
  (`durationMs` 0); `EFFECT_END {effect:'blind'}`; `POWERUP_COLLECTED {id, durationMs}` for ward / glide / stabilize;
  `POWERUP_EXPIRED {id, reason}` with reason `'timeout'`, `'respawn'` (manual reset) or `'replaced'` (a different
  glide / stabilize def took over). Biome pickups never touch `modded` or Ranking.
* `UIScene`: `EFFECT_INFO` rows `blind` ("BLINDED") and `gust` ("GUST", shown >= 700 ms); `POWERUP_KIND_INFO` gives
  ward / glide / stabilize a chip colour and its own icon in `_drawIcon` until a pickup id gets its own `POWERUP_INFO` row
  (`_powerInfo(id)`, `_powerKind(id)`). The active-effect chip is the existing power-up chip.
* `Hazard.js` / `PowerUp.js` draw through `hazardDrawKind` / `powerupDrawKind`; the generic pickup glyph is a filled
  diamond.

**Tests and gates.** `tests/src/biome-effects.test.js` (pure math), `tests/src/biome-effects-runscene.test.js` (the first
Jest test that imports RunScene, UIScene, Hazard and PowerUp: a small fake Phaser and the shipped methods on a prototype
stub), `tests/src/biome-spawns.test.js`, `tests/src/biome-zone-stacking.test.js`. The built-game gate has five B0 checks
that act on the real run (ward vs stickyPatch, glide, gust, blind, stabilize) with fixture defs injected into the registry
content. Sim baseline for B1-B4: `tools/sim/baselines/biomes-b0.json` (README there).
## Addendum: cosmetics, titles and themes (audit F4 / F4b / SHOP-2 / SHOP-5, additive)

**One catalogue.** `systems/Cosmetics.js` exports `COSMETIC_ITEMS`, a frozen array of
`{id, kind, slot, name, price, unlockLevel, value, grant?}`. `kind === slot` for every item. `ProfileStore.SHOP_ITEMS`
is the same array (identity), and the resolver's id table is derived from it. `data/cosmetics/cosmetics.json` is a
mirror only: `tests/src/cosmetics-complete.test.js` fails if any field differs. Pure modules cannot import JSON
under Jest, so the JS constant is the source.

**Ownership.** `isOwned`: listed in `unlocked.cosmetics`; or `grant === 'achievement'` and `value` is in
`unlocked.titles`; or price 0 and `unlockLevel <= level` (level rewards, including the eleven in `levels.json`).
`purchase` refuses price-0 items.

**Lookups.** `cosmeticInSlot(slot, idOrValue)` matches an id or an equipped value inside one slot. Values repeat
across slots, so `resolveCosmetics` uses it. `cosmeticFor(idOrValue)` is unchanged (first match by value).
`equippedTitle(profile)` returns the equipped title text or null.

**Themes.** `COSMETIC_HUES.theme[value].ui` is a partial palette over `UI_THEME_KEYS` = cyan, magenta, text,
bgAlt. `themedUiPalette(baseHex, profile, {colorblind})` lays it over the active palette. It returns the base
unchanged under colour-blind mode, and it can never move `danger`, `bg`, `lime` or `amber`.
`ui/Theme.js` builds `pal`/`css` through `themedPalette(game)`, which reads `REG.PROFILE` and
`REG.SETTINGS`, so every Theme consumer is themed: menus, panels and the UIScene HUD. The world palette
(`Palette.getPalette`, used by RunScene) is never themed. Call `theme.refresh()` after the equipped theme
changes; ShopView does this after every buy or equip.

**Shop pages.** `ShopLayout.SHOP_PAGES` = trail, glow, rider, theme. `shopLayout({profile, levels, page})` lays
out one page: BANK head, the page row (`kind:'page'`, first selectable), that slot's items, boosts and loadout.
It returns `page`, `pageCount` and `pageSlot`. `shopAllRows(o)` returns every page's item rows. ShopView pages
on left/right when focus is on the page row or an item row, and on confirm or click of the page row.

**Titles.** `ShopLayout.titlesLayout({profile, levels})` / `titlesMenuItems(layout)` drive `Views.TitlesView`.
Profile opens it from `titlesButton` (focus target kind `'titles'`). `ProfileLayout` shows `equippedTitle()`
in place of the level title in `profileLayout` (key `title`) and in `titleBadgeLayout`. TitleScene calls
`_refreshLevelBadge()` when Profile closes.

## Addendum: Marvin decisions 7/8/9 (Game Over shop buy, Sugar Rush steering, combo order; additive)

**Achievement order (decision 9).** `Achievements.sortAchievements(list)` is the one ordering: group
(`GROUP_ORDER`: distance, skill, daily, collection, biomes), then metric (`METRIC_ORDER`, the same set as
`METRICS`, so one ladder stays together), then `target` ascending; stable on input order; an unknown group or
metric sorts last. `ACHIEVEMENTS` is stored in this order and also sorted at load. `qualified` and
`newlyUnlocked` filter it, so `creditRun` reports the newly unlocked defs in this order, all of them in one
evaluation with one caller timestamp, and the Game Over toast shows them in this order (up to three names;
more than three: two names and `+N MORE`). `groupedAchievements` and `AchievementsLayout.GROUPS` follow
`GROUP_ORDER`. Ids never change (saves key on them); names and descriptions follow the targets.
`data/achievements/achievements.json` is kept in the same order (tested).

**Zone steering (decision 8).** A terrain mod's `physics.steerMul` multiplies `EffectivePhysics.airControl`
only. The effective `steerMul` (0 under a parachute, the daily `tuckSteerMul` when tucked) never takes a zone
factor, so ground lean (`tiltTorqueDegS2 * TUNING.groundTiltMul * steerMul * tiltSign` in `Sled`) is the same
inside and outside any zone. A zone may dull air control but must never take ground steering away from the
player. `tests/src/sugar-rush-steering.test.js` pins this against PhysicsTuner's pure output.

**Game Over shop buy (decision 7).** In the Shard Shop over Game Over, Enter / pad A (`confirm`) go to `ShopView`
once the shop is **armed**: buy + equip, equip, unequip (confirm on EQUIPPED) or turn the page, exactly the Title ->
Profile -> Shop rules. Retry stays one press: `MenuInput` opt-in `{ retryAction: true }` (GameOverScene only) fires
`retry` for keyboard Space (before Space's usual `confirm`; InputRouter's keyboard `hop` is how Space is told from
Enter) and for pad RB (button 5; free in MenuInput and in InputRouter's menu actions; Y is `alt` = new seed and
Start is `cancel`). `retry` closes the shop and retries from every state, and during initials entry it saves and
retries like Space. Esc / pad B / B / LB close the shop; N / X / Y start a new seed.
Arming: a shop opened with B / LB (`_openShop({requested: true})`) is armed at once. The autoprompt (and its resumed
form after initials entry) opens unarmed, and arms after `SHOP_ARM_MS` = 500 ms or on the first cursor move. The
popup only appears after 1.2 s with no input, so the press at risk is one started before the panel was seen; choice
reaction time is about 400-500 ms, so a confirm inside that window was aimed at Game Over and keeps the old
close-and-retry (pillar 3). The default focus is the page row, so even a later stray Enter only turns the page.
Hints: while unarmed the footer keeps `SPACE / ENTER / A / TAP = RETRY SAME SEED` (true for Enter then); once armed
it reads `ENTER / A = BUY   SPACE / RB = RETRY   ESC / B = BACK` (263 px, centred) at depth 501, above the dim (400),
on the row under the panel (panel y 22..258, footer ink y 261..269). `SHOP: B / LB` is hidden while the shop is open.
Closing restores the footer text and depth. With the shop closed nothing changed except that pad RB also retries.


## Addendum: biome full treatment, B1 "Wards" (content + slot rule; additive)

B1 ships the first biome content: one hazard and one power-up for each of Debutmont, Garbage Dump Glacier, Underwater
Mountain and Candy Cane Canyon (spec §4). Mask 0 is byte-identical (golden `shape` / `full` / `complete` unchanged): every
def below carries a `biome` field, so the B0 constructor filter keeps it out of the base lists.

| Biome (bit) | Hazard (file) | Hazard effect | Power-up (file) | Power-up effect |
|---|---|---|---|---|
| Debutmont (1) | `groomerCat` (`groomer-cat.json`), ground 24x20, shape `groomer`, amber | `slow` 0.7 x 900 ms | `mapleWax` (`maple-wax.json`), shape `maple` | `speedBoost` 1.2 x 2 s |
| Garbage Dump Glacier (2) | `seagullDive` (`seagull-dive.json`), air 40x24 in jump arcs, shape `seagull`, `danger`, >= 1000 m | `crash` | `slickWaxSpray` (`slick-wax-spray.json`), shape `waxSpray` | `ward` mods `['stickyPatch']` 4 s + `speedFactor` 1.1 |
| Underwater Mountain (8) | `seaweedTangle` (`seaweed-tangle.json`), ground 22x30, shape `seaweed`, lime | `slow` 0.6 x 1.2 s | `aquaLungBubble` (`aqua-lung-bubble.json`), shape `bubble` | `ward` mods `['slowMotion']` 4 s |
| Candy Cane Canyon (64) | `chocolateRiver` (`chocolate-river.json`), ground strip 24x8, shape `chocoRiver`, amber | `slow` 0.5 x 1.5 s | `sweetToothCoating` (`sweet-tooth-coating.json`), shape `candyCoat` | `ward` effects `['slow']` 5 s (wards off the Chocolate River) |

Hazard `spawn.baseChance`: groomerCat 0.5, seaweedTangle 0.55, seagullDive and chocolateRiver 0.75 (the amended cap);
power-ups 0.4. Groomer Cat is static; motion kinds land in B3.

**Slot rule (`TerrainGenerator._placeBiomeSpawns`, spec §4 amendment).** When the ground hazard slot fires and the free
scan finds no slot, `_replaceBiomeGround` swaps ONE base ground hazard of the chunk for the biome def, in place (same `x`,
`y`, `rotationDeg`). Candidates are base ground defs (`hazardList`; never a biome or air def) whose box grown by
`BIOME_REPLACE_SLACK_PX` (8) in w and h holds the biome box, and whose spot passes every biome ground rule with the biome
def (`_biomeGroundAt`, shared with the free scan; the spacing check skips the candidate itself, the shard check uses the
biome box, a `slow` keeps its slope rule below). The pick is `cands[floor(h4 * n)]`, where `h4` is the slot's 5th draw (B0
drew and discarded it), so `BIOME_SLOT_DRAWS` stays 5 and no other stream moves. Air biome hazards are not replaced.
With no biome defs, output at every mask is unchanged (digests pinned at 00978f6: `tests/src/biome-slot-rule.test.js`).

**Presence amendment (spec author, 2026-11-14).** The first B1 cut placed biome hazards in about 7 % of early biome chunks:
too rare to be felt. Amended rules, all in `_biomeGroundAt` / `_placeBiomeSpawns`:
* (a) a biome ground hazard keeps `BIOME_HAZARD_CLEARANCE_PX` (240) from any other hazard, not `HAZARD_MIN_SPACING_PX`
  (480). `BIOME_EDGE_MARGIN_PX` (240) stays, so hazards across a chunk border are still >= 480 apart and base pairs never
  change.
* (b) the descent-ahead rule (`_descentAhead`, anti-stall) binds a biome `slow` only when its `speedFactor` is below
  `BIOME_GENTLE_SLOW_FACTOR` (0.6): Chocolate River. A gentler slow (Groomer 0.7, Seaweed 0.6) may sit on flat or downhill
  ground but never before a climb: `_noClimbAhead` rejects any rising segment in the `BIOME_EDGE_MARGIN_PX` ahead (always
  inside the chunk).
* (c) the biome HAZARD slot's chance cap is `BIOME_HAZARD_MAX_CHANCE` (0.75); power-ups keep `BIOME_SPAWN_MAX_CHANCE` 0.5.
* (d) the replace rule stays the fallback.

Measured presence, share of the biome's chunks eligible for the placement kind (ground = not bridge / not `gen-jump`, air
= `gen-jump`), chunks 0-44 at a single biome bit: groomerCat 44.4 % (8 seeds) / 42.9 % (32 seeds), seagullDive 35.3 % /
42.9 %, seaweedTangle 35.7 % / 37.5 %, chocolateRiver 24.0 % / 20.9 %. The lead's target is 35-55 % and >= 1 per 2 km on every
seed. Open items: the river stays below the band under rule (b) (36x9 reached 15 %); the seagull (air slot, not covered by
the amendment, often 2-3 biome jump chunks per seed) misses the per-seed rule on 3 of 6 seeds with biome terrain. No-stall
check: a point mass entering any biome slow placement at 300 px/s keeps >= 128 px/s for the next 2 s. Power-ups land in
31-35 % of biome chunks.

**Effects (all existing paths except one additive field).**
* `Wards.js`: a ward may carry `speedFactor` (clamped to [1, `WARD_MAX_SPEED_FACTOR` 1.2], `wardSpeedFactor`), lasting as
  long as the ward. `wardSpeedMul(state)` is the product over active wards; `RunScene.physicsContext` multiplies it into
  `speedBoost`, separate from `boostMs` / `boostFactor`, so a Packet Burst or Maple Wax never overwrites it. On pickup
  RunScene also kicks the sled by `speedFactor` (like `speedBoost`).
* `RunScene`: the `speedBoost` branch records `boostId`; its expiry reports `POWERUP_EXPIRED {id: boostId}` (was the
  hard-coded `packetBurst`, which would have expired Maple Wax under the wrong chip). Packet Burst still reports
  `packetBurst`.
* `UIScene`: `POWERUP_INFO` rows MAPLE WAX, SLICK WAX, AQUA-LUNG, SWEET-TOOTH with their own `_drawIcon` glyphs;
  `HAZARD_LABEL` names the B1 slow hazards on the effect warning line (GROOMER CAT, SEAWEED TANGLE, CHOCOLATE RIVER); other
  hits keep their `EFFECT_INFO` label.
* `BiomeEffects.HAZARD_SHAPES` / `POWERUP_SHAPES` gain the 8 new shapeKeys; `Hazard.js` (`_groomer`, `_seaweed`,
  `_chocoRiver`, `_seagull` drawn like the drone, without corner brackets) and `PowerUp.js` draw each one.

**Tests and gates.** `tests/src/biome-b1-presence.test.js` (presence on the 8 + 32 seeds, rules (a) and (b), no-stall),
`tests/src/biome-slot-rule.test.js` (now also a spy test that the pick is `cands[floor(r * n)]`),
`tests/src/biome-b1-content.test.js` (loader / schema, spec
values, ward pairing, measured presence floors), `tests/src/biome-b1-effects.test.js` (shipped defs through the shipped
RunScene / UIScene / Hazard / PowerUp). Tests that listed ALL content now list base defs (biome defs separately):
`data.test.js`, `terrain.test.js` "all hazard types", `_biomeFixtures.withBiomeFixtures` (base content + fixtures).
`biome-spawns.test.js`'s last test states the amended contract (at most one base hazard swapped in place); after the presence
amendment its spacing test reads biome pairs >= 240 / base pairs >= 480, its cap test 0.75 (hazards) / 0.5 (power-ups), and
its fixed-draws test allows a power-up to move to its freed first position. The built-game
gate has 8 B1 checks, one hazard and one power-up per biome, each on a real `seed@bit` run with entities built by
`RunScene.takeChunk` from that run's terrain (expected counts 30 -> 38 with boosts, 19 -> 27).

## Addendum: Marvin decisions 1/2/4/6 (official Daily, mask-scoped Daily bests, Head Start, ledger hash v2)

**Official Daily (decision 2).** `REG.DAILY_OFFICIAL` (additive) is set on every Title start: true only from the DAILY RUN
item (`TitleScene._startDaily` -> `startRun(seed, mask, {official: true})`). Game Over RETRY sets it to the retried
record's `dailyOfficial`; NEW SEED sets false; PauseScene's restart keeps it (same seed, same mask). `RunScene.create`
sets `this.dailyOfficial = flag && seed is TODAY's daily seed`, writes `dailyOfficial` on the record and in the
`RUN_START` payload (additive), and passes it as Boosts' `daily` option, so only the official Daily refuses boosts. A
typed `daily-YYYY-MM-DD` with no suffix gets that date's mask in `TitleScene.startRun` (precedence: override, suffix,
typed daily date, profile mask); RunScene plays that date's rule for any daily seed.

**Ranking (decisions 1/2).** In `systems/Ranking.js`, additive:
* `isOfficialDaily(record)`: daily seed, the date's mask (absent = 0) and rule (`DailyPatch.infoForDateKey`). A v2 record
  (`hashV >= 2`) must also have `dailyOfficial === true`. A legacy record (no `hashV`) needs only the mask and rule. The v2
  rule is what keeps a typed `daily-<today>` (today's mask and rule) from passing as a legacy official run.
* `countsForDailyBest(record, o)` = `isRankable && isOfficialDaily`. `countsForStreak(record, o)` adds `imported !== true`.
* `SaveStore.getDailyStats(when, {excludeRunId})`: same signature and shape. It counts only `countsForDailyBest` runs on
  the date's seed and mask. `getDailyStreak(now)`: same signature and shape, counting only `countsForStreak` runs.
* `ProfileStore.creditRun` counts `lifetime.dailyRuns` (and so the Daily achievements) only for an official, non-imported
  record.

**DailyPatch (additive).** `infoForDateKey(dateKey)` -> `{dateKey, seed, rule, biomeMask} | null` (frozen, memoised, pure).
`dailyRunLabel(seed, official)` -> `'DAILY RUN'`, `'DAILY PRACTICE YYYY-MM-DD'` or `''`.

**Ledger hash v2 (decision 6).** SaveStore exports `LEDGER_HASH_V` (2), `computeLedgerHashV1` (the old function,
byte-identical), `computeLedgerHashV2` and `verifyLedgerHash(record)`. `SaveStore.computeLedgerHash` keeps its
signature and dispatches: `hashV === 2` -> v2, otherwise v1.
* v2 covers `'v2'`, version, id, seed, dailyRuleId, biomeMask (absent = 0), modded (strict boolean), the sorted `boosts`
  ids, dailyOfficial (strict boolean), startedAt, endedAt, durationMs, score, distanceM, trickPoints, sorted tricks,
  bestCombo, bestFlow, maxAirtimeMs, cause, shards, nearMisses and bonusPoints (absent = 0). It excludes initials,
  ledgerHash and `imported`.
* `sanitizeRun` whitelists `hashV` (exactly 2, never defaulted), `bestFlow`, `dailyOfficial` (boolean), `boosts` (id
  strings, sorted, unique, max 8) and `imported` (true only). A record without `hashV` is never re-hashed, so crediting
  (keyed on `ledgerHash`) cannot double-credit. `STORAGE.saveVersion` is unchanged.
* `importSharecode` uses `verifyLedgerHash`: per version, and an empty hash is rejected. It never throws. It forces
  `imported: true` on what it adds. `saveRun` drops `imported`. Leaderboard rows and `exportSharecode` omit it.

**Head Start (decision 4).** `BOOST_DEFS.headStart`: `speedFactor` 12 (launch multiplier on the ~50 px/s spawn,
through `Sled.scaleVelocity`), `openingSpeedMul` 1.6, `openingMs` 8000, `openingFadeMs` 2000. Pure, additive:
* `headStartOpening(loadout, o)` -> `{speedMul, ms, fadeMs}`. It is `{1, 0, 0}` unless Head Start applies (on, owned,
  not the official Daily).
* `openingSpeedMul(opening, runTimeMs)`: full strength, then a linear fade, then exactly 1.
* `RunScene.physicsContext` multiplies it into `speedBoost`, separate from `boostMs` and the ward factor.
`boostEffects` keeps its `{shieldCharges, speedFactor, modded}` shape.

**Gate.** `dailyOutcome` (typed seed vs the real DAILY RUN item, through the production crash path, plus the ledger v2
export / tamper / import round trip) and `distanceAt10s` (loop stopped, `headlessStep` at 1/60 s, hands off, seed `hs-1`).
Expected counts 38 -> 42 with boosts, 27 -> 30 without.

**Known gaps.** Imported runs saved before this change have no `imported` marker, so a legacy imported record on its
date's mask and rule can still hold a streak day. `events.js`' RUN_START typedef does not list the additive `dailyOfficial`
field (foundation file, outside this change). `UIScene._buildSeedInfo` still labels any run on today's daily seed `DAILY RUN` in the HUD. UIScene was
outside this change's files. The fix is to use `DailyPatch.dailyRunLabel(seed, payload.dailyOfficial)` from `RUN_START`.

## Addendum: Micro Mountain dew swell is in the ground (audit T2, additive)

* **One surface.** A zone whose mod has `terrainSwell` displaces the chunk **points** inside the zone
  (`TerrainGenerator._applySwell`, called in `_build` right after zone placement and before lips, hazards, power-ups,
  shards and biome spawns). The Matter collider and the drawn edge (`TerrainMesh`, which reads the points), `slopeDegAt`,
  `heightAt` and every spawn therefore describe the same ground. `heightAt` is the plain polyline again; it does not add
  the swell. `_swellAt(x)` remains as a diagnostic: the displacement already baked into the points at x.
* **Shape.** `amplitudePx * sin(2 pi (x - x0) / periodPx) * w(x)`, where `w` is a raised-cosine window that rises from 0
  to 1 over `taperPx` at each zone edge (clamped to half the zone; absent = no taper). Offset and slope are 0 at the
  edges: no step, no kink. Only `points` change: zones sit >= 96 px inside their chunk, so the end points, the next
  chunk's bound, the rise state and the roll speed (all built from the scratch `ys`) are untouched. Chunks with no swell
  zone return before touching a point, so every chunk outside Micro Mountain is byte-identical
  (`tests/src/micro-swell-isolation.test.js` pins masks 0, 1, ..., 1024 except 512 at e080803).
* **Spacing.** The 16 px point spacing is kept (`_segIndex`, `_yAtLocal`, hazard placement and `_flatAround` assume it).
  A 660 px period is ~41 points; even the old 220 px period was ~14 points with < 1 px chord error.
* **Data.** `TerrainModDef.terrainSwell` gains `taperPx` (`{amplitudePx, periodPx, taperPx}`); shipped dewSwell is
  20 / 660 / 165. The `schemas.js` typedef still lists only amplitudePx and periodPx (not on the T2 file list).
* **Tests and gate.** `tests/src/micro-swell.test.js` (heightAt == polyline, slopeDegAt == segment, continuity and
  bend at the edges, ~2A swing, taperPx read, determinism, spawns on the swelled ground, audit T2 copies).
  `biome-slot-rule.test.js` hashes its 00978f6 pin with the swell stripped (reproduces it exactly) and pins the ALL-mask
  digest of the shipped content separately. Built-game proof: a gate block (sd of sled.y - heightAt < 3 px on a
  `t2-probe@512` swell zone) is handed to the lead; it raises the expected counts by 1 in both modes.

## Addendum: Marvin decision 3 (biome unlocked / encountered / completed; additive)

Decision 3: "Biome discovery means actually encountering the biome; track unlocked, encountered, and completed separately."

- **Unlocked** is unchanged: the Sync Level unlock (`ProfileStore.unlockedBiomeIds`, from `pendingBiomes`).
- **Encountered:** the sled's x reached a stretch the generator answers with `id` (`terrain.biomeAtX`), i.e. past the arcade bridge that opens the biome's sector when the previous sector differs (#65). The sector rule is the generator's own (`floor(x / ppm / SECTOR_M)`, the same as `_sectorOf`). Debutmont is the base, so it is encountered from sector 0 at any mask (there is no mask-0 early return); arcade is never recorded.
- **Completed:** the sled rode one of that biome's sectors from its start to its end (`SECTOR_M`, 500 m), and the run's crash is not inside that sector. Only the run-ending crash counts. A crash absorbed by a Hashed Backup, or an opening-grace recovery, does not void completion, because the run went on. Completed implies encountered.

**Detection** is the pure `BiomeDiscovery.detectBiomeVisits({biomeAt, furthestX, crashX, pxPerMeter})` (`biomeAt` is the run's `terrain.biomeAtX`; each sector 0..furthest is probed once), which returns `{encountered, completed}` in canonical `BIOME_IDS` order.
- The sled moves forward through sectors and a respawn never skips one, so every sector from 0 to `sectorOfX(furthestX)` was entered. Sector `s` was crossed to its end if and only if the furthest sector is past `s`.
- `BIOME_IDS` is a static list, pinned by a test to `src/data/biomes` and to `levels.json` `biomeOrder`. The sanitizer must not depend on the level table it is handed: the fallback table's empty `biomeOrder` would erase every encounter on the next save.

**Data flow.**
1. `RunScene.doCrash` calls `detectBiomeVisits`. Furthest x is `startX + ScoreManager furthest metres * PIXELS_PER_METER`, or the crash x if that is larger.
2. It emits `RUN_END { record, biomeVisits }`. `biomeVisits` is an additive `RunEndPayload` field, typed in events.js. It is never part of the RunRecord or `computeLedgerHash`.
3. `ProgressionService.onRunEnd` forwards it as `credit(record, { streak, biomeVisits })`.
4. `creditRun` merges it as a union into `profile.biomeProgress`. A replayed run is refused before the merge, so it records nothing.

**Profile.** `bb.profile` v1 gains `biomeProgress: { encountered: string[], completed: string[] }` (`defaultProfile`).
- The change is additive. `PROFILE_VERSION` and `STORAGE.saveVersion` are unchanged, and an old profile loads with empty sets.
- `sanitizeBiomeProgress` keeps known ids only, dedupes them, sorts them canonically and adds every completed id to encountered.

**Achievements.** `metricsFrom` gives `biomesDiscovered = max(extra.biomeCount, encountered count of the profile)`.
- `creditRun` still forwards no caller `biomeCount`, so only a real encounter can unlock biomes-2/5/11.
- Their rewards go through the existing `grantAchievementReward` path in the same credit, in decision 9 order.
- `AchievementsView` no longer passes `biomeDefs.length` (ACH-6), so the grid shows encountered / target.

**Views.**
- `biomeToggleRows` rows gain `encountered`, `completed` and `state` (`'locked'|'unlocked'|'encountered'|'completed'`, strongest fact first). A Daily plays the date's mask whatever is unlocked, so a locked biome can be encountered.
- `ProfileLayout.toggleLabel(row)` labels an unlocked row `NAME NEW|SEEN|DONE`, coloured text, cyan or lime. The widest label is 148 px, which fits the two-column band before the ON/OFF value.
- Locked names keep `LVL n` and get a separate `state-<id>` box (SEEN / DONE) when they were encountered.
- A `biome-progress` line (`BIOMES SEEN n/11 DONE m/11`) is right-aligned on the ACHIEVEMENTS summary row.

**No backfill from stored runs.** It would not be exact:
- `distanceM` is floored and the spawn is 44 px in, so one integer distance per sector boundary is ambiguous.
- The first-time backfill only runs on a profile with no runs.
- Absorbed crashes are not stored.

## Addendum: biome full treatment, B2 "Sight" (content + blind fairness rule; additive)

B2 ships Crystal Cavern's and Vertigo Vents' hazard and power-up (spec §4). It adds no new effect kind: `blind` and its
overlay came in B0, `ward` in B0/B1, `shield` is the base Hashed Backup kind. Mask 0 is byte-identical (golden `shape` /
`full` / `complete` unchanged): every def below carries a `biome` field.

| Biome (bit) | Hazard (file) | Hazard effect | Power-up (file) | Power-up effect |
|---|---|---|---|---|
| Crystal Cavern (16) | `shatterWall` (`shatter-wall.json`), ground 24x34, shape `shatterWall`, lime, chance 0.6 | `blind` 1200 ms, visibility 0.4, no crash | `crystalClearGoggles` (`crystal-clear-goggles.json`), shape `goggles`, cyan, chance 0.4 | `ward` effects `['blind', 'scramble']` 6 s |
| Vertigo Vents (1024) | `ashCloud` (`ash-cloud.json`), air 56x34 in jump arcs, shape `ashCloud`, amber, chance 0.75 | `blind` 1200 ms, visibility 0.4 | `heatShield` (`heat-shield.json`), shape `heatShield`, magenta, chance 0.25 | `shield`, 1 charge |

* Both blind hazards are non-crash, so they are drawn in their own colour (never `danger`), and RunScene's air telegraph,
  near-miss and hop hint (crash hazards only) ignore the Ash Cloud. Both draw through the bracketed `Hazard.draw` switch
  (corner brackets included), like any ground hazard, so a later telegraph needs no special case.
* "Air zone" (spec table) is the existing air pass: `ashCloud` is placed by `_placeBiomeSpawns` in a generated jump of a
  Vertigo sector (`isJump`), above the no-hop arc, like Seagull Dive. Vertigo's template chunks (valley-launch, ski-jump,
  big-air-drop) are spline chunks, not `isJump`, so they hold none.
* The Shatter Wall box fits a Garbage Data Vent, Overflow Firewall or Glitch Chasm box + `BIOME_REPLACE_SLACK_PX`, so the
  slot rule can swap it in.
* The Goggles ward's `effects` list switches off every `blind` and `scramble` hit (the base Garbage Data Vent's scramble
  included) and stops one that is already acting, through the B0 consumers: `onHazard` ignores the hit,
  `updateBlindOverlay` drops the overlay to 0, and `sled.scrambled` / `physicsContext.scrambled` read false.

**Blind fairness rule (`TerrainGenerator._biomeGroundAt`).** A biome ground def whose `onHit.effect` is `blind` needs no
crash hazard of its own chunk within `blindClearAheadPx(onHit, distM)` ahead: `(durationMs + BIOME_BLIND_REACT_MS 500)` at
`BIOME_BLIND_SPEED_MUL` (1.2) x `expectedSpeedPxS(distM)`. The replacement path checks it too (the swapped hazard is
skipped). `crashHazardIds` (constructor) lists every crash def id, base and biome. The pass cannot see the next chunk;
requiring the stretch to end inside the chunk cut Shatter Wall presence to about 4 %, so only the chunk's own hazards are
checked. Measured over 32 seeds x 300 chunks: without the rule 29 % of Shatter Walls had a crash hazard within the 1.2 s
blind at the expected speed; with it 2.9 % (22 of 771), all in the next chunk. Ash Cloud: 0 of 268. The rule binds only
`blind` defs: masks 1, 2, 8 and 64 keep their e080803 digests.

**Shield sources (`BiomeEffects`, B2).** The Heat Shield feeds the one `shieldCharges` pool. RunScene also keeps
`shieldSources`, one pickup id per charge (`addShieldSource`); a spent charge reports the most recent source
(`spendShieldSource`, LIFO), so `POWERUP_EXPIRED {reason: 'consumed'}` carries `heatShield` or `hashedBackup` (was always
`hashedBackup`, which left a Heat Shield chip on screen). A charge with no tracked source (the W4 shield boost) is the
Hashed Backup's (`SHIELD_DEFAULT_SOURCE`). `POWERUP_COLLECTED.charges` is `shieldChargesFor(sources, id, pool)`: the pool
minus the charges other tracked pickups own for the Hashed Backup (so a lone Backup and the Error Correction boost charge show as before), and only its own tracked charges for a biome shield. `shieldSources` is set
with `shieldCharges` at run start; a manual reset keeps both.

**HUD (`UIScene`).** `POWERUP_INFO` rows GOGGLES (cyan) and HEAT SHIELD (magenta) with their own `_drawIcon` glyphs;
`HAZARD_LABEL` names SHATTER WALL and ASH CLOUD on the blind warning line. `BiomeEffects.HAZARD_SHAPES` gains
`shatterWall`, `ashCloud`; `POWERUP_SHAPES` gains `goggles`, `heatShield`.

**Tests and gates.** `tests/src/biome-b2-content.test.js` (loader / schema, spec values, ward pairing, slot-rule fit,
shield-source helpers), `tests/src/biome-b2-effects.test.js` (shipped defs through the shipped RunScene / UIScene / Hazard /
PowerUp), `tests/src/biome-b2-presence.test.js` (presence, the fairness rule and its measured residue, determinism).
Changed pins: `data.test.js` lists the 6 + 6 biome defs; `biome-b1-content.test.js` counts only the B1 biomes' defs (the
total is pinned in the B2 file); `micro-swell-isolation.test.js` leaves B2-tagged defs out of its digest (B2 content is
meant to change masks 16 and 1024; nothing else moved). The built-game gate has 4 B2 checks on real `b2crystal13@16` and
`b2vertigo56@1024` runs (expected counts 45 -> 49 with boosts, 33 -> 37).

## Addendum: biome full treatment, B3 "Motion" (content + moving hazards + roll track rule; additive)

B3 ships Pyramid Peak's, Steampunk Slopes' and Micro Mountain's hazard and power-up (spec §4) and the two motion kinds
(`HazardDef.motion`, spec §5). Mask 0 is byte-identical (golden `shape` / `full` / `complete` unchanged): every def below
carries a `biome` field.

| Biome (bit) | Hazard (file) | Hazard | Power-up (file) | Power-up effect |
|---|---|---|---|---|
| Pyramid Peak (4) | `rollingBoulder` (`rolling-boulder.json`), ground 22x22, shape `boulder`, `danger`, chance 0.45 | `crash`; motion `roll` 140 px/s, range 160 px, dir -1 | `sandrunnerSkis` (`sandrunner-skis.json`), shape `skis`, amber, chance 0.4 | `glide` frictionMul 0.7, 4 s |
| Steampunk Slopes (256) | `gearGate` (`gear-gate.json`), ground 20x28, shape `gearGate`, `danger`, chance 0.45 | `crash` only while closed; motion `gate` period 1400 ms, open 900 ms | `clockworkTreads` (`clockwork-treads.json`), shape `treads`, cyan, chance 0.4 | `ward` mods `['conveyorBelt']` 4 s |
| Micro Mountain (512) | `dewDrop` (`dew-drop.json`), ground 18x16, shape `dewDrop`, `danger`, chance 0.45 | `crash`; motion `roll` 110 px/s, range 140 px, dir -1 | `royalJellyWax` (`royal-jelly-wax.json`), shape `jellyWax`, amber, chance 0.4 | `glide` frictionMul 0.7, 4 s (shared kind) |

**New data fields (optional, additive).** `HazardDef.motion`: `{kind: 'roll', speedPxS, rangePx?, dir?}` or
`{kind: 'gate', periodMs, openMs}`. `HazardSpawn.phase` (0..1): only on a Gear Gate spawn. The crash JSONs set
`colorKey: 'danger'` (RunScene's palette switch reads `def.colorKey` directly).

**`systems/HazardMotion.js` (pure; no Phaser, Math.random or Date).**
* Roll: `rollParams(motion)` (speed <= `ROLL_MAX_SPEED_PX_S` 200, range <= `ROLL_MAX_RANGE_PX` 200, `dir` -1 toward the
  sled / +1 downhill away), `rollSweep(motion)` (x span relative to the spawn: `{lo, hi}`), `rollOffsetAt(motion, msActive)`
  (signed, speed x time, clamped to the range), `emptyRollState()`, `rollStep(state, motion, x0, sledX, tMs)` (starts on the
  first step with `sledX >= x0 - ROLL_ACTIVATE_PX` (340); afterwards offset = rollOffsetAt(tMs - activeAtMs), so the frame
  rate never changes the position), `rollPredictX(state, motion, x0, tMs)`.
* Gate: `gateTiming(motion)` (open >= `GATE_MIN_OPEN_MS` 400, closed in [`GATE_MIN_CLOSED_MS` 100, `GATE_MAX_CLOSED_MS` 500]),
  `gateOpenAt(motion, phase, tMs)` (each cycle starts open), `gateNextChangeMs(motion, phase, tMs)`.
* `BiomeEffects.glideFriction(frictionMul, glideMul)`: the one place a glide changes friction; `PhysicsTuner.getEffective`
  calls it (was an inline multiply). Same numbers as before.

**Entity (`Hazard.js`).** A def with a `roll` or `gate` motion keeps every usual field and draws through the normal
`Hazard.draw` switch (corner brackets included). `update(timeMs, camLeft, camRight)` (signature unchanged) first calls
`stepMotion(timeMs, sledX?)` every frame, on or off camera, BEFORE its visibility early return:
* roll: `rollStep` with `scene.sled.x`; the sensor body (`Body.setPosition` / `setAngle`), the drawing and `cx` / `cy`
  move to `x0 + offset` on `scene.heightFn` (the generator's `heightAt`, i.e. the collider polyline, dew swell included) at
  `terrain.slopeDegAt`. `rolling`, `rollDir` and `spin` drive the drawing. `cx` tracks the moving box, so the hop hint,
  near-miss and the sim's hop policy see the real position.
* gate: `open` follows `gateOpenAt(motion, spawn.phase, run time)`; a flip redraws at once.
* New methods: `stepMotion`, `isPassable(tMs)` (true only for an open gate), and for a telegraph `predictX(tMs)` and
  `gateNextChangeMs(tMs)`. A telegraph needs, for a roll, `predictX` (it waits at `x0` until the sled is 340 px behind it,
  then moves toward the sled), and for a gate, `isPassable` / `gateNextChangeMs` at the sled's arrival time.

**RunScene.** One line at the top of `onHazard`: `if (h.isPassable && h.isPassable(this.runTimeMs)) return;` before
`h.hit` is set, so an open gate is passed and stays armed; `collisionactive` re-queues the contact, so a gate that closes
on an overlapping sled crashes it.

**Generator (`TerrainGenerator`).**
* Roll track rule (`_rollTrackClear`, called from `_biomeGroundAt`, so the slot-rule replacement inherits it): the whole
  `[x + sweep.lo, x + sweep.hi]` stays inside `BIOME_EDGE_MARGIN_PX`, off lip windows `[l.x - 40, zoneEnd]` and gaps +/- 96,
  `BIOME_HAZARD_CLEARANCE_PX` from every other hazard and 90 px from every power-up. The biome power-up slot keeps 90 px
  from a rolling hazard's whole track (`_trackDist`; equals `|q.x - x|` for every def without motion, so masks without a
  roll def are unchanged). A def with no x motion passes trivially.
* Gate phase: `biomeSpawn(def, x, y, rot, h3)` adds `phase` = the slot's 4th pre-drawn number (h3, drawn and unused by
  ground slots before B3). `BIOME_SLOT_DRAWS` stays 5; no stream moves.

**Presence (tests/src/biome-b3-presence.test.js).** Chunks 0-44, share of eligible biome chunks, 8 / 32 seeds: Rolling
Boulder 41.9 % / 35.4 %, Gear Gate 55.6 % / 39.5 %, Dew Drop 44.4 % / 37.2 %. Long range (4 seeds x 300 chunks): Rolling
Boulder 32.9 %, Gear Gate 36.1 %, Dew Drop 36.1 % of eligible chunks; Sandrunner Skis 35.4 %, Clockwork Treads 39.3 %,
Royal Jelly Wax 37.4 % of biome chunks.

**Fairness numbers (tests/src/biome-b3-presence.test.js).** Roll: starts with the sled 340 px away (B2's view probe:
>= 348 px of ground on screen ahead at any speed >= 100 px/s; the gate check confirms the hazard is inside `_view` at the
start); its range (160 / 140 px) is shorter than 340 px minus its width, so a sled stopped at the start line is never
reached. Hop window (sled underside above the crash box minus the closing pass) at the expected speed: Rolling Boulder
611-626 ms, Dew Drop 641-657 ms (1000-4000 m). Gate: closed spell 500 ms vs 560-878 ms on screen before reach at 1.2x the
expected speed (500-10000 m); open 900 ms vs a 71-116 ms crossing. A closed gate is also hop-clearable (28 px box, crash
box 22 px, hop apex ~72 px), like every ground hazard.

**HUD (`UIScene`).** `POWERUP_INFO` rows SANDRUNNER SKIS (amber), JELLY WAX (amber), CLOCKWORK TREADS (cyan) with their own
`_drawIcon` glyphs. `BiomeEffects.HAZARD_SHAPES` gains `boulder`, `dewDrop`, `gearGate`; `POWERUP_SHAPES` gains `skis`,
`jellyWax`, `treads`. Crash hazards end the run, so no `HAZARD_LABEL` rows.

**Tests and gates.** `tests/src/biome-b3-motion.test.js` (pure motion and glide math), `tests/src/biome-b3-content.test.js`
(loader / schema, spec values, motion blocks, ward and glide pairing), `tests/src/biome-b3-effects.test.js` (shipped defs
through the shipped Hazard motion, RunScene dispatch, UIScene and drawing; the Dew Drop rides the real dew swell
polyline), `tests/src/biome-b3-presence.test.js` (phase from the draw, roll track rule, presence, fairness numbers,
determinism). Changed pins (none re-pinned): `data.test.js` lists the 9 + 9 biome defs; `biome-b2-content.test.js` counts
only the B1 + B2 biomes' defs; `micro-swell-isolation.test.js` leaves B3-tagged defs out. The built-game gate has 6 B3
checks on real `b3pyramid54@4`, `b3steam63@256` and `b3micro26@512` runs (expected counts 49 -> 55 with boosts, 37 -> 43).

**Sim (B0 baseline `biomes-b0.json`, +/-15 %, git archive of f9f3f91).** Hop (48 seeds): mask 4 survival 18 -> 17 (-5.6 %),
distance -2.6 %, speed -0.1 %; mask 256 14 -> 15 (+7.1 %), +3.7 %, -0.5 %; mask 512 20 -> 17 (-15.0 %, at the line),
-1.5 %, -0.4 %. Mask 512 was already 17/48 (-15.0 %) on a fresh v2.9.0 run (T2 moved it): against v2.9.0, B3 leaves Micro
hop survival unchanged (17 -> 17), distance +1.6 %, speed +0.1 %. Flip distance +1.4 % / -6.8 % / -7.5 %, speed +0.5 % /
+0.1 % / +0.3 % (flip survival exempt). Crashes on the new hazards per 48 hop runs: Rolling Boulder 2, Gear Gate 2, Dew
Drop 1. At chance 0.5 the boulder took mask 4 hop survival to 15/48 (-16.7 %), hence 0.45.

## Addendum: readable chaos (fable-10x; additive)

### Phase 1: ground-hazard telegraph

* **Why**: measured on the built game, a ground hazard was first visible ~481 px ahead (camera geometry), a median 0.85 s
  (p10 0.67 s) before the sled reached it, the hop must be pressed ~0.38 s out, and every death is a hazard death. The only
  earlier warning was the first-run `SPACE HOP` hint. The air hazard already had `entities/AirTelegraph.js`.
* **`systems/HazardTelegraph.js`** (pure; no Phaser, clock or randomness):
  * `GROUND_WARN` (frozen): `leadS` 2.0, `minPx` 700, `maxPx` 1600 (1.33 s at 1200 px/s; terrain exists 3 screens = 1440 px ahead, so faster than ~720 px/s a hazard is announced when its chunk is generated),
    `hopLeadMs` 380 / `hopWindowMs` 250 / `minVxPxS` 60 (the hop oracle's numbers, `tools/sim/browser.js`), `maxMarks` 6,
    `warnGapMs` 220, `clearMarginPx` 60. UI timing, so it lives here and not in `TUNING`.
  * `hazardResponse(def)` -> `'hop'` (crash, or no `onHit`) | `'brace'` (any other effect) | `null` (air: not ours).
  * `warnDistancePx(speedPxS)` -> `clamp(speed x leadS, minPx, maxPx)`.
  * `inHopWindow(dx, vx)`: the oracle's rule, `hopLeadMs - hopWindowMs < dx / max(vx, 60) x 1000 <= hopLeadMs`.
  * `planTelegraphMarks(hazards, sled, {isMuted}?)` -> `TelegraphMark[]`, nearest first, at most `maxMarks`:
    `{ref, kind, state: 'warn'|'go'|'clear', color: 'danger'|'amber'|'lime', clear, dx, etaS, urgency}`. Skips hit,
    passed, air and muted hazards. `go` (lime) only for a grounded sled inside the hop window. `clear` when airborne and
    the ballistic touchdown (`sled.landX`) is more than `clearMarginPx` past the box. The former explicit-right-edge
    `planTelegraph` adapter still supplies an `onScreen` hint to historical diagnostics, but live code doesn't use it.
  * `TelegraphTracker.update(nowMs, marks)` -> events `{type: 'warn'|'go', kind, ref, sound}`: `warn` once per hazard at its
    first non-clear mark (`sound` false when another warn sounded under `warnGapMs` ago), `go` once when it first turns lime.
    `firstWarnMs(ref)`. State is plain data keyed by the stable hazard id `Hazard.hid` (`${chunk.index}:${spawn ordinal}`, set in
    `RunScene.takeChunk`; a hazard without one throws), never by object identity: `snapshot()` / `restore(snap)` (JSON-safe,
    versioned) and `forgetChunk(index)` (called from `dropChunk`). `RunScene.snapshotTelegraph()` / `restoreTelegraph(snap)` wrap them and
    re-stamp `teleAtMs` on the rebuilt hazards (#119 Phase 2).
* **`entities/GroundTelegraph.js`** (drawing only; does not import Phaser): `update(timeMs, marks, view, zoom, activeChunks)`,
  `setPalette`, `destroy`. If the arrow footprint would clip in the current view, draw a badge at
  `view.right - EDGE_INSET_PX / zoom` on the terrain line (glyph by
  `BiomeEffects.hazardDrawKind`, marching chevrons, proximity bar, response cue), stacked upward, at most `EDGE_MAX_STACK` (3).
  The stem reads already-streamed polyline points or falls back to mid-view, never asking the generator to stream from a camera position.
  The nearest clipped hop-now cue gets the first (response-bearing) slot, even among earlier warnings.
  Otherwise, draw a light column on the box (shortened to stay inside the view) with the cue on top. Cue shapes repeat the
  colour: open up-chevrons = hop, filled up-arrow = hop now, two bars = brace. Every size is game px (480 x 270) / zoom.
* **`RunScene`**: `updateGroundTelegraph(now)` is called from `updateFun` (live frames only) right after the air telegraph:
  it plans the marks (muting warded hazards via `Wards.isWarded` by id and by effect; `landX` from `sled.airEtaMs`), plays
  `groundWarn` (`opts.brace` for a brace hazard) / `hopCue`, stamps `hazard.teleAtMs` (read only by the measurement harness
  and the gate) and stores `_teleMarks`; `renderFrame` draws them after `_view` is computed (nothing while crashed).
  Nothing here reads into physics, terrain, score, the RunRecord or the ledger hash.
* **`AudioSynth`**: SFX `groundWarn` (hop: rising two notes; `opts.brace`: one soft low note) and `hopCue` (bright tick).
* **Tests**: `tests/src/hazard-telegraph.test.js` (pure rules, oracle agreement on a grid), `tests/src/hazard-telegraph-runscene.test.js`
  (the shipped `RunScene` methods on a prototype stub, the entity against a recording graphics fake, the sounds).

### Phase 1 on the biome hazards (rebased onto v2.10.0; additive)

* `hazardResponse` is unchanged: B3 Rolling Boulder / Dew Drop / Gear Gate -> `hop`; B1 Groomer Cat / Seaweed Tangle /
  Chocolate River (slow) and B2 Shatter Wall (blind) -> `brace`; Ash Cloud (air) -> `null`. `tests/src/hazard-telegraph-biomes.test.js`
  pins every shipped def in an explicit table.
* `GROUND_WARN` gains `arrivalHorizonMs` 4000, `arrivalStepMs` 20, `gateMarginMs` 150.
* `predictArrival(h, sled, nowMs)` -> `{etaMs, cxAtArrival}`: with `h.predictX` (Hazard, B3) and a run time, the centre at
  now + tau is `h.cx + predictX(now + tau) - predictX(now)`; the first tau where the sled (constant `max(vx, 60)`) reaches
  it, by 20 ms steps then bisection; `Infinity` past the horizon. Static (or no `predictX` / no `nowMs`): exactly `dx / vx`.
  No roll direction is assumed. Limit: `Hazard.predictX` holds a not-yet-started roll at its spawn x.
* `inHopWindowMs(etaMs)`: the oracle's window in time. `gateVerdict(h, arrivalMs)` -> `'open'` when `isPassable` holds at
  `arrivalMs - gateMarginMs` and `gateNextChangeMs` there exceeds `2 x gateMarginMs`, else `'closed'`; `null` without the
  gate API (or when `gateNextChangeMs` returns null).
* `planTelegraphMarks(..., {isMuted, nowMs})`: marks gain `arrivalMs` (null without `nowMs`) and `gate`; `etaS` and the lime
  window come from `predictArrival`; `clear` compares `landX` with `cxAtArrival`; new state `'open'` (gate open at
  arrival: drawn dim with still chevrons, silent in `TelegraphTracker`, never lime). `RunScene.updateGroundTelegraph`
  passes `nowMs: runTimeMs` (the time base of `Hazard.stepMotion`).

### Phase 2: farther zoom-out at speed (supersedes the numbers in "Addendum: camera at speed")

* **`systems/CameraZoom.js`** (pure): `speedZoom(speedPxS, t = TUNING)` is the target zoom. Stage 1 is unchanged and still
  reads `TUNING.zoomMin` / `zoomSpeedLo` / `zoomSpeedHi` (1 -> 0.82 between 150 and 600 px/s). `ZOOM_STAGES` then eases
  (smoothstep) to 0.56 at 1000 px/s and to 0.47 at 1400 px/s (v2.6.0: one stage, 0.62 at 1200). `ZOOM_FLOOR` 0.45 is the
  hard clamp (was 0.6). `aheadPx(zoom, riderScreenX)` = `(GAME_WIDTH - riderScreenX) / zoom`. `TUNING` is not changed.
* **`RunScene.updateCamera`**: `zt = speedZoom(s.speed)`, clamp at `ZOOM_FLOOR`; easing (`TUNING.zoomLerp`), the 0.005 zoom
  step, the boost kick and the rider-keeps-its-screen-x pivot are as before. `ZOOM_FAR_MIN` / `ZOOM_FAR_SPEED_HI` are gone.
  New RunScene-local `LOOK_ULTRA_EXTRA_PX` 110 ramps in between 850 and 1300 px/s on top of `LOOK_FAR_EXTRA_PX`: the x
  follow (`cameraLerpX` 5.5 /s) lags `speed / 5.5` px, which left the rider ~130 px in at 1200 px/s. `RIDER_MIN_SCREEN_X`
  36 still bounds it.
* **Measured** (scratchpad `fable-10x/zoom-probe.cjs`, the shipped `updateCamera` at a steady speed over real terrain;
  before -> after): 650 px/s zoom 0.815 -> 0.81, 440 -> 442 px ahead, 0.68 s; 850: 0.745 -> 0.64, 512 -> 596 px, 0.60 -> 0.70 s;
  1000: 0.67 -> 0.56, 572 -> 736 px, 0.57 -> 0.74 s; 1200: 0.62 -> 0.515, 563 -> 862 px, 0.47 -> 0.72 s (rider at screen x 131 -> 36).
* **Still true at the new floor**: view width 480 / 0.45 = 1067 px, under the 3 generated screens (1440 px ahead of the
  sled); `applyZoomCompensation` counter-scales the background, flash and blind layers by exactly 1 / zoom (checked at
  0.565 on the built game); cull margins use the zoomed `_view`; sizes at 0.47: Packet Spike 9.4 game px, Glitch Chasm
  30, sled 19. The ground telegraph is drawn at a constant screen size, so it does not shrink with the view.
* **Tests**: `tests/src/camera-zoom.test.js` (curve identity below 600 px/s, anchors, monotone, floor, the shipped
  `updateCamera` settling on the curve, eased under hard acceleration, rider framing and pin).

## Addendum: readable chaos phase 3, death legibility (additive)

* **`systems/CrashReport.js`** (pure): `CRASH_BEAT` {slowMs 400, slowScale 0.25, hitStopScale 0.08, zoomIn 0.18};
  `killerName(cause, def)` (a crash def's `name`, else its id spaced and upper-cased; a non-crash def -> `'CRASH'`;
  causes `terrain` HEAD FIRST, `badLanding` BAD LANDING, `chasm` FELL INTO THE VOID); `hopTiming(lastHopMs, arrivalMs)`
  -> `{kind: 'none'|'early'|'late'|'onTime', s}` against `[arrival - hopLeadMs, + hopWindowMs]` (a hop over 1 s before
  the window is none); `verdictText`; `crashReport({runId, seed, biomeMask, cause, def, x, startX, pxPerMeter,
  lastHopMs, arrivalMs, crashMs})` -> `CrashReportData` `{runId, seed, biomeMask, x, distM, cause, hazardId, name,
  verdict, line}` (arrival falls back to crashMs); `crashBeat(msSinceCrash, hitStopMs)` -> `{fxScale, zoomMul}`;
  `deathMarkerX(lastCrash, seed, mask)`; `gameOverLine(lastCrash, rec)` (same run id and `cause: 'crash'` only).
* **`REG.LAST_CRASH`** (`constants.js`, additive): the last run-ending crash. Never in the RunRecord or the ledger hash.
* **`HazardTelegraph.TelegraphTracker.lastArrivalMs(ref)`**: latest finite planned arrival per hazard (clear / open marks too).
* **`RunScene`**: `onHazard` keeps the crashing entity in `_crashHazard` (`pendingCrash` keeps its `{cause, hazardId}`
  shape); the frame loop stamps `_lastHopMs` when a hop executes; `doCrash` calls `reportCrash(c, fs)` (an absorbed
  crash returns earlier in `resolveCrash`, so never reports); `renderFrame` scales FX by `crashBeat().fxScale` while
  crashed; `updateCamera` multiplies the zoom by `crashBeat().zoomMul` while crashed; `create` builds
  `entities/LastDeathMarker.js` (a BestMarker clone, `DIED HERE Nm`, lime `BEAT IT` once passed) when `deathMarkerX`
  matches. `CRASH_TO_GAMEOVER_MS` (950) is unchanged.
* **`UIScene.onCrash`**: the non-negated banner is `killerName(cause, content.hazards[hazardId])`.
* **`GameOverScene._buildHeader`**: `crashLine` (danger) from `gameOverLine`; y 42, or title scale 3 with rule y 33 / line y 43 when a rule line is shown.
* **Tests**: `crash-report`, `crash-legibility-runscene` (real create / onHazard / resolveCrash / doCrash), `crash-beat-runscene`, `crash-gameover`.
