 * @property {number} x
 * @property {number} y
 * @property {number} comboPenalty   unique tricks dropped from the pending combo by this respawn (>=0).
 */

/**
 * @typedef {Object} LandingPayload
 * @property {'perfect'|'good'|'sloppy'|'crash'} quality  see LANDING_QUALITY.
